INSERT INTO `t_menus_button` VALUES ('ff6ef95d-a756-4a2c-be58-f86ee36b0f97', 'e9430ee1-6f6f-4e1b-a4ec-aef531ca404d', '新增', 'add');
INSERT INTO `t_military_term_data` VALUES ('00114bdc-6e2b-42a0-ba21-f9ca01cb3d39', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地图自动显示系统', '应用电子计算机及其显示设备对军用地图进行处理、显示的人-机对话系统。通常由数字信息的获取、存储、处理、显示等硬件和软件组成。可提供多种地形资料,辅助地形分析和快速标绘要图。', 267);
INSERT INTO `t_military_term_data` VALUES ('0016bac7-6356-4011-b6b1-5ea32d3fb0c9', '06a75831-13a1-4660-870a-455bb445336a', '扩展频谱通信', '简称扩频通信。无线电发射信号的频带宽度远大于信息信号频带宽度的无线电通信。有直接序列扩频、跳频、跳时、线性凋频和混合方式等类型。抗干扰能力强，信号不易被敌方截获。', 119);
INSERT INTO `t_military_term_data` VALUES ('0021ff81-aec9-423a-a153-480a9e4e25ce', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '多选择引信', '亦称多用途引信。具有触发、近炸、定时、周炸、空炸等两种以上作用方式的引信。可根据作战需要选择装定,以取得弹药对目标的最佳毁伤效果。', 338);
INSERT INTO `t_military_term_data` VALUES ('0022db96-0424-4fc4-b72b-1240855209eb', 'd7132c58-5df3-4b97-919f-58740148b9ca', '中口径高射炮', '简称中高炮。口径为 60～100毫米的高射炮。如76毫米高射炮、85毫米高射炮、100毫米高射炮。', 41);
INSERT INTO `t_military_term_data` VALUES ('002a4727-1fc8-4683-b475-14531b40e8f4', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '战斗部队', '直接遂行作战任务的部队的统称。', 48);
INSERT INTO `t_military_term_data` VALUES ('0035351d-8914-4875-bc8a-d949e593386d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上航道管制', '沿海国对其领海和内水的航道进行的强制性管理和控制。分为平时海上航道管制和战时海上航道管制。目的是维护海上航行秩序,保证舰艇航行安全。', 289);
INSERT INTO `t_military_term_data` VALUES ('003b1956-46df-4fc6-be34-06429b9a4918', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '分布式电子干扰', '亦称散布式干扰。投放箔条和投掷式干扰机或使用其他散布式干扰器材形成的电子干扰。', 61);
INSERT INTO `t_military_term_data` VALUES ('003eb67f-6f11-486b-802f-13be03bb7933', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军队职能', '军队所担负的历史使命和根本任务。中国人民解放军的根本职能是巩固国防,抵抗侵略,保卫祖国保卫人民的和平劳动。', 92);
INSERT INTO `t_military_term_data` VALUES ('004ee3f5-b4b5-4050-b929-5206d2ab8f61', '97a19170-bfac-42c5-9906-1acb187f0654', '仪表飞行', '飞行员按机上航空仪表的指示,判断所驾驶的飞机或直升机的飞行状态及位置的飞行。通常用于复杂气象或夜间和海上的飞行。', 214);
INSERT INTO `t_military_term_data` VALUES ('00546ab0-320c-4884-9ca1-2d9217ce662d', '97a19170-bfac-42c5-9906-1acb187f0654', '领航准备', '领航人员为保证航空器按预定航线飞行并准确实施轰炸、空降、空投等任务而进行的准备。分为经常的领航准备和受领任务后的领航准备。主要内容包括选定航线和高度,进行地图作业和领航计算,研究航线、天气情况和处置特殊情况方案,检查领航设备等。', 368);
INSERT INTO `t_military_term_data` VALUES ('0058d6f1-b46b-49a9-b62c-ba5255af5109', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军人俱乐部', '军队开展群众性文化活动的场所及其机构。中国人民解放军中的军人俱乐部,包括连队俱乐部、旅或团俱乐部和师以上机关俱乐部。有的团以上俱乐部称文化活动中心。是部队官兵进行娱乐、审美、求知、健身的场所和课堂。', 118);
INSERT INTO `t_military_term_data` VALUES ('0069d5e8-d8b3-4699-8e8e-36714f8d0b08', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备抢修', '对作战或其他行动中损坏的武器装备进行的突击性修理。', 121);
INSERT INTO `t_military_term_data` VALUES ('006fbdeb-84f9-4dff-91ca-ac50a1d013e9', '06a75831-13a1-4660-870a-455bb445336a', '通信手段', '', 98);
INSERT INTO `t_military_term_data` VALUES ('00735f8c-e62b-4310-87a5-fa28999253bb', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防费', '国家用于国防事业的经费。通常包括军费、国防科研费、后备力量建设费等。', 36);
INSERT INTO `t_military_term_data` VALUES ('007bde20-1b39-46b5-876e-b162ecaeffd1', '916997ee-6728-4c61-9b79-d96960b1dc86', '隔绝式防毒衣', '由不透气材料制成的防毒衣。用以防止毒剂、生物战剂、放射性落下灰等接触皮肤而引起伤害。主要供在严重受染区内执行专业保障任务的人员使用。', 176);
INSERT INTO `t_military_term_data` VALUES ('008e9aa5-4198-40df-b9e4-be25a61eadc9', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物战剂气溶胶', '生物战剂的液体或固体微粒分散在空气中所形成的气溶胶。能进入无防护的工事、车辆、舰艇、建筑物内,而不易被人的感官和一般侦毒器材所察觉。可直接经呼吸道侵入人体,还可通过污染水源、食物或其他物品间接使人感染。是生物战的主要手段。', 231);
INSERT INTO `t_military_term_data` VALUES ('009580cb-e133-4aa1-bd62-56faac1f77a3', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '短洞', '用暗挖的施工方法构筑的只有一个出入口的较短的条形或马蹄形工事。主要供班、组人员隐蔽和储备作战物资。', 67);
INSERT INTO `t_military_term_data` VALUES ('0096559f-47c5-4dc8-a89a-9cf81dfc2851', 'd7132c58-5df3-4b97-919f-58740148b9ca', '小口径高射炮', '简称小高炮。口径小于 60毫米的高射炮。如25毫米高射炮、37毫米高射炮、57毫米高射炮。', 42);
INSERT INTO `t_military_term_data` VALUES ('009855e4-d759-4999-a2b0-f77e30b3b382', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战编成', '为达成一定的作战目的将参战的兵力临时组合成有机的整体。通常分为战役编成和战斗编成。', 94);
INSERT INTO `t_military_term_data` VALUES ('00a6dc45-ed9e-4880-8a49-6192f837feed', '98df76fb-4b65-48ff-a56c-4db587327c79', '伙食灶别', '对军人的伙食待遇划分的类别。是伙食标准的组成部分。主要内容有：灶别区分,各类灶的实物、炊事燃料的定量,相应的伙食费数额和享用人员等。中国人民解放军的全平伙食灶别统一划分为7类。', 142);
INSERT INTO `t_military_term_data` VALUES ('00b242a2-28ae-46f2-bde5-9c0607e25eff', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事摄影测量', '利用摄影机或其他传感器采集的被测对象的图像信息,经加工处理和分析以获取有军事价值信息的技术。包括航空摄影测量、地面摄影测量、双介质摄影测量、近景摄影测量、显微摄影测量、解析摄影测量。数字摄影测量和侧视雷达测量等。主要用以测制各种军用地形图,测定军事目标的形状、大小和位置,研究弹道轨迹、飞行速度,监测军事工程的变形,以及解决与像片精密量测有关的问题等。', 237);
INSERT INTO `t_military_term_data` VALUES ('00c5fe1d-7e52-454a-8064-7ee22ec1d757', '97a19170-bfac-42c5-9906-1acb187f0654', '机长', '飞机或直升机上的空勤组的负责人。通常由飞行员担任。', 189);
INSERT INTO `t_military_term_data` VALUES ('00d8a810-b2ce-4dbc-b73c-51df93fc23bb', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '电子侦察卫星', '用以侦收敌方电子设备的电磁辐射信号以获取情报的侦察卫星。由电子侦察设备、快速通信设备、遥测与姿态控制设备、电源及壳体等组成,并与地面接收站共同组成卫星电子侦察系统。侦察范围广、速度快、效率高,不受国界和天气条件限制,可进行长时间、大范围的连续侦察监视。', 207);
INSERT INTO `t_military_term_data` VALUES ('00eb6cbb-cfbc-4248-85f5-e71861a6a5c4', '878651de-adf5-4c72-9376-9c363b893ff8', '战略企图', '亦称战略意图。为达到一定战略目的的基本想法和打算。主要包括：确定主要打击方向和战略目标,实现战略目标所要采取的手段、方法和步骤等的基本设想。', 61);
INSERT INTO `t_military_term_data` VALUES ('00f841a3-2176-493d-afa6-32594a9f8e8e', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '自动气象站', '能定时或按指令自动观测、发报、记录地面气象要素的整套装置。一般由传感器、控制器、数据处理器、资料传输单元和电源等部分组成。主要测量气温、气压、湿度、风向、风速、降水量等,有的还能测量能见度、云高、雷暴、日照、总辐射等。多布设在沙漠、高山、海洋、岛屿等人烟稀少的地区,战时可空投到敌占区。', 101);
INSERT INTO `t_military_term_data` VALUES ('01018673-a104-419e-a7aa-36deb15de33e', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象资料', '各种气象观测记录、照片,以及加工后的各种气象数据、文字和图表等的统称。是国家和军队重要科技档案之一,也是实施军事气象保障的基本依据。', 70);
INSERT INTO `t_military_term_data` VALUES ('01018a62-656d-416d-9acf-4cd45a79d362', '97a19170-bfac-42c5-9906-1acb187f0654', '机场拦阻设备', '设置在机场跑道的端保险道上,用于防止飞机着陆或中断起飞时冲出端保险道的设备。分为网式、索式和网索混合式拦阻设备。', 433);
INSERT INTO `t_military_term_data` VALUES ('01105e43-d6cd-46dd-9055-fe7bd66fae8b', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹待蔽地域', '导弹部队遂行作战任务时临时集结、隐蔽、待命的地域。通常选在避开重要目标,便于机动、伪装,并与作战阵地保持适当距离的地域。', 47);
INSERT INTO `t_military_term_data` VALUES ('0113c4a7-c644-43b5-8ab6-d774edbee582', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '基本工事', '阵地中的主要工事。通常在阵地工程构筑计划的第一期作业中构筑。', 57);
INSERT INTO `t_military_term_data` VALUES ('01188c4b-0a2b-44ac-9dd5-7e84533e9363', '97a19170-bfac-42c5-9906-1acb187f0654', '侦察航空兵', '以侦察机为基本装备,遂行空中侦察任务的航空兵。主要用以查明敌方的目标和电磁信息,以及敌区的地形、天气等情况,为己方各军兵种部队的作战行动提供航空侦察情报资料。', 8);
INSERT INTO `t_military_term_data` VALUES ('0118d176-ed03-494e-a20a-cf437e5c862c', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '气象战', '通过人工影响天气和气候,造成有利于己不利于敌的气象条件,以达成军事目的的作战。是环境战的组成部分。', 152);
INSERT INTO `t_military_term_data` VALUES ('011d336a-fe4d-499f-bfd0-5815a49c3f6e', '916997ee-6728-4c61-9b79-d96960b1dc86', '糜烂性毒剂', '破坏机体细胞,以皮肤或粘膜糜烂为主要毒害特征的毒剂。如芥子气、路易氏气等。主要以液滴状态造成地面、物体表面染毒,或以气溶胶和蒸气状态使空气染毒。接触皮肤和粘膜时,引起红肿、起泡、溃烂,可造成眼睛损伤甚至失明；吸入时损伤呼吸道、肺组织及神经系统。', 215);
INSERT INTO `t_military_term_data` VALUES ('011ede19-387f-48bb-87c7-6c955bd4a49d', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '编配', '按照编制设置建制单位和配备人员、武器装备。', 66);
INSERT INTO `t_military_term_data` VALUES ('012192c6-d07c-4958-b473-5c8f25b5b0ba', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克最大爬坡度', '坦克在战斗全重状态下,在规定坡道上不用惯性冲坡所能通过的最大纵向坡度。主要由坦克单位功率、推进系统的结构、坦克的动力特性和重心位置等因素决定。坦克的最大爬坡度一般为30度。', 163);
INSERT INTO `t_military_term_data` VALUES ('012283f0-dab1-4d60-97e4-c93db36bda43', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克完好技术状况', '坦克能随时执行任务,并有持续战斗力的技术状况。表现为清洁完整,润滑周到,调整正确,紧固适当,没有故障。', 194);
INSERT INTO `t_military_term_data` VALUES ('012ca9e1-ac3a-41ce-975f-a2c719dff803', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电磁信号环境模拟器', '能在频率、时间、空间和功率等方面模拟产生各种电磁信号的电子设备。主要用以研制、检验和改进电子对抗设备,以及进行电子对抗训练等。', 144);
INSERT INTO `t_military_term_data` VALUES ('0140beec-8110-4c67-9bbd-cddb22d0654e', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤保障方式', '后勤保障的基本方法和形式。如按建制保障、按区域保障,以及交替保障、伴随保障等。', 25);
INSERT INTO `t_military_term_data` VALUES ('014196a2-4ce9-45a9-a73b-9a9eb560e41f', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '导爆管', '亦称塑料导爆管。管内壁粘附一层猛炸药,用以传递爆轰波的索类火工品。', 220);
INSERT INTO `t_military_term_data` VALUES ('014a69ec-70d4-490c-94b4-7f8a963c1925', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '营区秩序', '军队营区内的工作、生活及其他活动按照有关条令和规定保持的井然有序的状态。', 31);
INSERT INTO `t_military_term_data` VALUES ('014c225f-24a1-42b2-a11f-9945d7e60104', '06a75831-13a1-4660-870a-455bb445336a', '人防通信网', '为保障城市人民防空而建立的通信网。包括空情情报报知网、空袭警报报知网和人防指挥通信网。', 62);
INSERT INTO `t_military_term_data` VALUES ('014edbce-8bf7-4bc9-800c-eb98c46471d8', '31f4a446-5b98-4873-9d53-310d97125b07', '弹头突防装置', '安装在导弹头部用以引诱、迷惑敌人反导防御系统的装置。主要有假弹头、诱饵、干扰机等。', 147);
INSERT INTO `t_military_term_data` VALUES ('01680cb4-87a4-4f0a-bbd9-01f4eb67e53d', '878651de-adf5-4c72-9376-9c363b893ff8', '战略态势', '在军事斗争或战争中,敌对双方在总体力量对比、战略部署和战略行动等方面形成的状态与形势。', 70);
INSERT INTO `t_military_term_data` VALUES ('01700138-4425-47d0-b283-aaa43fb70c4a', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '遮障', '能妨碍敌侦察和干扰敌武器攻击的遮蔽物。分为天然遮障和人工遮障。', 342);
INSERT INTO `t_military_term_data` VALUES ('0192de2f-0bff-4f97-8cca-62bf23e7c7a8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '油船', '专门用以载运和补给油料的勤务舰船。', 149);
INSERT INTO `t_military_term_data` VALUES ('0197bde5-f0c9-49f0-9d05-58ce93ea1938', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '干扰遮障', '在地面或水面设置角反射器或在空中投放箔条等电波反射体所构成的人工遮障。主要用以干扰雷达对目标的探测。', 350);
INSERT INTO `t_military_term_data` VALUES ('019a581d-c842-466b-8827-ac6220501149', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '弹道导弹', '弹道式导弹的简称。飞行轨迹绝大部分为自由抛物体轨迹的导弹。由火箭发动机推送到一定高度和取得一定速度及弹道倾角后,发动机关闭,弹头沿着预定弹道飞向目标。为提高命中精度,有的弹道导弹在弹头再入大气层后的最后飞行段,也能实施制导。', 9);
INSERT INTO `t_military_term_data` VALUES ('01a8e915-6ef0-49a0-b6b5-35813bea7d2f', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '边防部队', '驻扎在边境地区,担负防御外敌入侵和制止人员非法越境等任务的部队。', 55);
INSERT INTO `t_military_term_data` VALUES ('01aca7dc-1f12-42a0-afeb-1700c57456f7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '人民军队', '来自人民并为人民利益而奋斗的军队。', 91);
INSERT INTO `t_military_term_data` VALUES ('01bacb68-ef0a-4096-8541-b494415c83de', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役开进', '军团由集结地域向预定作战地区的机动。', 47);
INSERT INTO `t_military_term_data` VALUES ('01c71ca3-c8fd-4dcb-ade4-e49f582c3257', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '水路输送', '使用水上运输工具实施的输送。分为海上输送和江河输送。', 77);
INSERT INTO `t_military_term_data` VALUES ('01d03f1d-21c4-43ed-a2ac-7adc447625ae', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境管理区', '中华人民共和国为保卫国界安全,维护边境秩序,便于边境管理,在国界线浅近纵深内划定的区域。一般按边境乡一级行政区划定。', 83);
INSERT INTO `t_military_term_data` VALUES ('01d597df-e360-4d0f-aef7-cd4ebad965d0', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹井内发射', '在发射井内完成一切发射准备并实施的导弹发射。包括井内热发射和井内冷发射。井内发射隐蔽性好,防护能力强,发射暴露时间短,但发射井构造复杂,造价昂贵。', 116);
INSERT INTO `t_military_term_data` VALUES ('01d5f568-5158-46d7-b92f-0d49eb0d7f9f', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹引控系统联试', '在静态情况下按模拟导弹及弹头的飞行过程,对弹头引控系统进行全面的综合性检查测试。以对其动作程序、程序延续时间以及程序工作电压幅值等作出鉴定和结论。', 93);
INSERT INTO `t_military_term_data` VALUES ('01d7f202-5212-42e4-8552-e3a347ea0407', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '有利攻击地线', '有利于反坦克导弹击毁目标的发射地线。根据反坦克导弹的战术技术性能和地形等条件，在目标可能出现的地域内预先或临时选定。目标接近此地线时发射导弹,射击效果最佳。', 266);
INSERT INTO `t_military_term_data` VALUES ('01e0623e-bd95-4d8b-aab5-3df74d75b922', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '弹药配套保管', '按有关规定,将非整装弹药配齐引信、发射药等元件进行成套保存与管理。', 103);
INSERT INTO `t_military_term_data` VALUES ('01e8826c-b341-4860-8b33-192085ac5f73', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '化学爆炸模拟核效应', '简称化爆模拟核效应。使用一定量的炸药,以其瞬时爆炸产生的能量对核爆炸的力学效应进行的模仿、模拟的主要内容包括：地面、地下核爆炸的成坑效应,地面运动效应,水面和水下核爆炸效应等。', 194);
INSERT INTO `t_military_term_data` VALUES ('01ebe993-63d6-4db3-aaa0-667cdfb7ab64', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆可靠度', '在规定条件下和规定时间内,核战斗部按规定性能指标实现核爆炸的概率。', 135);
INSERT INTO `t_military_term_data` VALUES ('020ae3bd-3724-422c-aacc-c34471fc2ad8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '攻击潜艇', '以鱼雷、巡航导弹为主要武器,用以攻击敌方潜艇和水面舰艇的潜艇。分为常规动力攻击潜艇和核动力攻击潜艇。', 138);
INSERT INTO `t_military_term_data` VALUES ('021053e3-7665-44e7-9b68-52e250c5c5e6', '97a19170-bfac-42c5-9906-1acb187f0654', '空军指挥', '空军指挥员及其指挥机关对所属部队的作战和其他行动进行的组织领导活动。', 175);
INSERT INTO `t_military_term_data` VALUES ('02227457-d31c-43fa-b3c9-1203b43af670', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '编外定编', '正式确定军队中编制外单位或人员的编制。是一种临时性编制措施。', 69);
INSERT INTO `t_military_term_data` VALUES ('022729e1-836e-4df4-aeca-742a4d7cacb0', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '戈壁', '亦称砾漠。地表面由砾碎石覆盖的荒漠。有软、硬两类。多分布在沙漠的边缘地区。软戈壁表层砾碎石不大,间有较粗沙粒,下有软沙,不便车辆通行；硬戈壁表面为砾石、碎石和卵石,下面土质较硬,便于车辆通行。', 36);
INSERT INTO `t_military_term_data` VALUES ('02321b75-e4bb-4a8f-be0a-09c2109b1b1c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克战斗全重', '载有全部乘员,加足油料和冷却液,配齐一个基数的弹药,带有全部随车工具、附件、备品时的坦克重量。', 151);
INSERT INTO `t_military_term_data` VALUES ('0232b820-d87c-4c25-a282-0f925ceb0ce0', '916997ee-6728-4c61-9b79-d96960b1dc86', '染毒', '人、畜、武器装备和地面、水源、空气等染有毒剂的现象。', 116);
INSERT INTO `t_military_term_data` VALUES ('02372e50-47eb-406d-81dc-12b921ff9b82', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵气象通报', '为防空兵编发的包括气象资料和有关天气情况的通报。高炮部队采用电报形式,通报内容包括地面和各规定炸高以下气层的弹道气温偏差量、空气密度偏差量和风等。地空导弹部队采用文字、图解或电报形式,通报内容包括天气实况、天气预报和危险天气等。', 123);
INSERT INTO `t_military_term_data` VALUES ('023b1954-c675-4db8-a8a3-ff74b2ca89c7', '98df76fb-4b65-48ff-a56c-4db587327c79', '铁路军事专用线', '与铁路联轨站相衔接,为军事单位运输物资的专用铁路线。属军事设施。其修建和维修管理,由军队和铁路有关部门分工负责。', 264);
INSERT INTO `t_military_term_data` VALUES ('023bb3a8-9d38-4ab4-9ef7-7be1b13c977f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '陆战场', '敌对双方进行陆战活动的空间。主要指一定的地域及其相关的空域,有的还包括相关的海域。', 164);
INSERT INTO `t_military_term_data` VALUES ('023db3ba-8e15-4d41-8706-9b1a46e5b36b', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战略导弹部队侦察', '战略导弹部队为获取所需情报而进行的侦察。通常由战略导弹部队各级指挥员及其司令部组织,以查明核打击目标、导弹飞行轨迹和被打击目标毁伤程度等情况。主要侦察手段有照相侦察、光测侦察、次声波探测、地震波探测、电磁脉冲探测、放射性同位素探测、红外线跟踪测量、无线电技术侦察等。', 7);
INSERT INTO `t_military_term_data` VALUES ('0253decd-2c8f-4617-b090-a0a9658f2651', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '呼唤炮兵火力', '步兵、坦克或其他部队在紧急情况下要求炮兵给予火力支援。', 79);
INSERT INTO `t_military_term_data` VALUES ('02578dab-5199-47b9-9974-8bb44c399dff', '97a19170-bfac-42c5-9906-1acb187f0654', '空中作战', '航空兵在空中攻击或抗击敌方的军事行动。包括空战、轰炸、强击等。', 39);
INSERT INTO `t_military_term_data` VALUES ('0280b8eb-bd92-4550-ae1e-bcbd068106cf', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气候', '某一地区较长时期大气的综合状态。通常用该地区气象要素的长期统计量（平均值、方差、极值概率等）描述。气候是随时间变化的。全球气候除具有温度大致按纬度分布的特征外,还具有明显的地域性特征。', 54);
INSERT INTO `t_military_term_data` VALUES ('02878141-5f7e-4662-a022-e66b7c5775e8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '登陆波次', '登陆作战中,登陆艇（直升机）波按登（着）陆的先后次序和间隔时间所排列的顺序。编波的目的是使登陆兵突击上陆的行动既迅速连续又不致拥挤阻塞。', 103);
INSERT INTO `t_military_term_data` VALUES ('028b6250-44e4-40e5-8dd1-7f55bb5197a3', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程兵', '担负工程保障任务的兵种。由工兵、舟桥、伪装、建筑、工程维护、给水工程等专业部队和分队组成。是军队中遂行工程保障任务的技术骨于力量。按隶属关系，分为预备工程兵和队属工程兵。基本任务是：实施工程侦察,构筑工事,修建道路、桥梁、渡场、港口、机场,设置和排除障碍物,实施破坏作业,构筑给水站，实施工程伪装,消除敌核、化学、生物武器袭击后果的工程作业等。', 0);
INSERT INTO `t_military_term_data` VALUES ('028c8cd5-b5bb-46d7-bc72-78f00950c314', '8a761efd-50a6-4ac8-9913-b7d745104f82', '标定射击', '在能见度不良条件下,按预先标定好的目标的方向、距离实施的射击。是夜间不用夜视器材的常用射击方法。', 95);
INSERT INTO `t_military_term_data` VALUES ('028f2714-cea8-4d3b-a2ca-018491c98c25', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役展开', '战役发起前,参加战役的各部队进入待机地域或其他指定地域的行动及其所形成的布势。', 50);
INSERT INTO `t_military_term_data` VALUES ('02914679-0ec1-4756-b3d8-ccbcedd3337a', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '哨位', '哨兵或警戒分队执行警戒任务的位置。一般设置在被警戒目标的附近地点。', 33);
INSERT INTO `t_military_term_data` VALUES ('02b4a749-2ed6-48c1-9d1d-b61520056f1c', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '靠拢', '部队或人员、作战平台相互缩小间隔距离的行动。', 349);
INSERT INTO `t_military_term_data` VALUES ('02b58c9b-668a-47e0-8d61-5e5ea85f440c', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '集训', '对受训对象进行的短期集中训练。', 143);
INSERT INTO `t_military_term_data` VALUES ('02cd8bfb-a9a2-41f6-b062-a7726f76f62f', '98df76fb-4b65-48ff-a56c-4db587327c79', '战备物资储备费', '军队用以储备战备物资的专项经费。', 81);
INSERT INTO `t_military_term_data` VALUES ('02d49980-9c0a-4d98-9771-2532bbf3b5b6', '97a19170-bfac-42c5-9906-1acb187f0654', '下令起飞线', '指挥机构确定的歼击机战斗起飞时,敌航空器所到达的位置线。用以确定歼击机起飞的时间。', 194);
INSERT INTO `t_military_term_data` VALUES ('02d8f1d4-e4ec-4573-98fc-3e118e0c9cbc', 'f0140091-c11a-48c9-8836-8aa94439dac0', '交叉火力', '从两个以上方向射击同一目标的火力。', 88);
INSERT INTO `t_military_term_data` VALUES ('02db6806-30bf-4f56-9016-6df8204c7dfc', '916997ee-6728-4c61-9b79-d96960b1dc86', '中等挥发度毒剂', '亦称双效毒剂。挥发度适中,兼有呼吸道吸入中毒和皮肤渗透中毒作用的毒剂。如梭曼的同系物等。', 210);
INSERT INTO `t_military_term_data` VALUES ('02e135aa-daf8-4036-831f-2fecfafe5e46', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '红外摄影', '亦称红外照相。利用物体反射或辐射的红外线作为光源的摄影方法。军事上用以识别和揭露伪装,监视敌人夜间活动。', 240);
INSERT INTO `t_military_term_data` VALUES ('02e396f5-7e3f-4675-aa5e-cc80394fe332', 'd7132c58-5df3-4b97-919f-58740148b9ca', '按测距机诸元射击', '由高炮测距机测定空中目标方位角、高低角和距离,计算仪计算射击诸元而进行的射击。不受电子干扰影响,测角精度高,但测距精度稍差,易受气象条件影响。', 171);
INSERT INTO `t_military_term_data` VALUES ('02f736f0-feb0-4368-9a8b-7669cfd8aac6', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵基本阵地', '炮兵遂行射击任务的主要阵地。', 56);
INSERT INTO `t_military_term_data` VALUES ('0302647b-0420-46fe-b7c8-4f18152a1000', '97a19170-bfac-42c5-9906-1acb187f0654', '航空器', '主要依靠空气浮力或气动升力而升空,仅能在大气层中航行的飞行器。分为空气浮力航空器（如气球、飞艇）和气动升为航空器（如包机、滑翔机、直升机等）。', 259);
INSERT INTO `t_military_term_data` VALUES ('0308e50a-300e-4f99-9c21-6949fc084692', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '开进', '军队由集结地域或待机地域向预定的作战地区前进的行动。', 338);
INSERT INTO `t_military_term_data` VALUES ('030d5970-7e95-4c66-9fa5-fc1f5e6e2ede', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '光电火控系统', '通过光电等设备控制武器自动地攻击目标的火控系统。通常由微光、红外、激光、电视等观测装置和火控计算机等组成。', 86);
INSERT INTO `t_military_term_data` VALUES ('0313f954-c2e7-4166-8132-cf11c7a7914a', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '缓征', '根据兵役法的规定,暂缓征集应征公民服现役。', 32);
INSERT INTO `t_military_term_data` VALUES ('0339affa-b6eb-45d1-a7a5-58f97e7bad60', '98df76fb-4b65-48ff-a56c-4db587327c79', '装具', '人员、马匹在作战、训练、执勤时佩带的制式用具。分为人装具和马装具。人装具主要包括头盔、背囊、雨衣、水壶、于粮袋、子弹袋、手榴弹袋、工事锹套等。马装具主要包括挽具、驮具、鞍具等。', 159);
INSERT INTO `t_military_term_data` VALUES ('03479d08-74f1-44e8-9c2d-aa3bb283e6f6', '98df76fb-4b65-48ff-a56c-4db587327c79', '救护直升机', '搜索、营救和后送伤病员的专用直升机。', 228);
INSERT INTO `t_military_term_data` VALUES ('03541e67-7758-4fe6-95df-64f50b6bde21', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '人工影响天气', '用人工方法使局部区域的天气按人的意愿转化的专业技术活动。包括人工降水、人工防雹、人工消雾、人工消云、人工造雾、人工控制雷电、人工削弱和引导台风等。人工影响天气在军事上具有重要的价值。', 80);
INSERT INTO `t_military_term_data` VALUES ('035f9064-68f1-426e-9385-3eac76dce3a0', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '警备部队', '担负重要城市的警卫和守备等任务的部队。', 53);
INSERT INTO `t_military_term_data` VALUES ('0361e02a-2862-4288-bb4f-5c4469209884', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '黄昏', '日落后到天黑前的一段时间。', 149);
INSERT INTO `t_military_term_data` VALUES ('0363f5c1-812d-4e2c-a707-54cbddfae4a2', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮毁歼概率', '高炮在一定条件下毁歼敌机的可能性大小的量。通常用0～1的数值表示。', 63);
INSERT INTO `t_military_term_data` VALUES ('0367a06c-2397-4f9d-83cb-253d99d4d396', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学袭击警报', '报知敌化学袭击的信号。用以使部队及时采取防护措施。', 48);
INSERT INTO `t_military_term_data` VALUES ('0374ca6a-db82-46f6-a67a-1661d4ae217e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '演习计划', '组织实施军事演习的计划。是准备和实施演习的基本依据。主要内容包括：演习课目、训练目的。训练问题,演习组织,演习地域,演习的性质和方法,演习的开始和持续的时间,演习的阶段划分和时间分配,演习的物资保障等。', 135);
INSERT INTO `t_military_term_data` VALUES ('038cc4d5-0291-47cc-9efa-a4306315050a', '878651de-adf5-4c72-9376-9c363b893ff8', '战略原则', '按照一定的战略思想确立的指导战略行动的法则或标准。是对战争指导规律的抽象概括和制定战役、战术原则的基本依据。', 59);
INSERT INTO `t_military_term_data` VALUES ('039073e2-2c60-416c-b14c-caeaaf502379', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '生活秩序', '军队的日常生活按照有关条令和规定保持的井然有序的状态。', 33);
INSERT INTO `t_military_term_data` VALUES ('0395f2a4-4401-4414-8957-f8df654dff23', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防突然袭击', '简称防突袭。对敌突然袭击的防范和抗击。主要措施包括：加强侦察预警,做好战备工作,增强边海防和空防力量,建立应急机动作战部队,对敌突袭进行抗击和反击等。', 207);
INSERT INTO `t_military_term_data` VALUES ('03aaa95d-4c85-4558-8061-d44f9a174ae3', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电磁信号密度', '位于某一区域的电子对抗侦察设备在单位时间内可能接收到的电磁信号的数量。通常分为雷达信号密度、通信信号密度等。雷达信号密度,指雷达对抗侦察设备每秒钟接收到的脉冲平均数；通信信号密度,指通信对抗侦察设备同时接收到的无线电通信信号数量。', 24);
INSERT INTO `t_military_term_data` VALUES ('03b12f30-e7a7-4ab3-ae30-8057655a7adc', '06a75831-13a1-4660-870a-455bb445336a', '野战综合通信系统', '综合运用各种通信手段组成以地域通信网为骨干、多种网络结构形式相结合的战役、战术通信系统。由地域通信网、双工无线电移动通信网、单工无线电通信网、战术卫星通信网等组成。有时还包括升空平台通信网。', 169);
INSERT INTO `t_military_term_data` VALUES ('03b1a239-9668-417c-8fa6-e91910149ab5', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机协同进攻', '武装直升机协调配合地面部队对敌进行的进攻。主要任务是突击防御之敌装甲战斗车辆及直升机等。', 60);
INSERT INTO `t_military_term_data` VALUES ('03be02e8-8673-48de-935d-c30bb975d70d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰桥', '舰艇上层建筑中操纵航行、指挥作战的部位。包括驾驶室、指挥室和露天指挥台等。', 165);
INSERT INTO `t_military_term_data` VALUES ('03be9980-127c-4a8f-86dc-6ca4d18725ca', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '地线', '为了军事上的特定需要而在地面上划定的横线。如射击出发地线、射击地线等。', 298);
INSERT INTO `t_military_term_data` VALUES ('03c08d32-e5c9-4777-8db4-6deed954289d', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵集中射击', '炮兵群、炮兵营集中两个以上炮兵连同时对同一地段内的目标实施的射击。通常用以压制或歼灭敌集群目标,如支撑点,堑壕内的有生力量和火器，集结的步兵、坦克和炮兵连等。', 181);
INSERT INTO `t_military_term_data` VALUES ('03c0b77c-a8d9-49c1-b5ba-3aef65ad6589', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克自动灭火抑爆装置', '坦克内兼有灭火和抑爆功能的自动装置。由光火焰探测器、高效灭火剂和程序控制盒等组成。可在80～120毫秒内灭火并抑制车内弹药和油气混合气的爆燃。', 141);
INSERT INTO `t_military_term_data` VALUES ('03c1f6b4-5a49-4f5f-848e-3d6cfd96996d', '8a761efd-50a6-4ac8-9913-b7d745104f82', '遮蔽物', '影响射界和视界的地物或地貌。', 66);
INSERT INTO `t_military_term_data` VALUES ('03d36cb6-967a-48d2-9c3f-170d1532d8db', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸中心', '简称爆心,亦称爆点。核弹爆炸的中心点。是进行核爆炸测量的基准点。', 140);
INSERT INTO `t_military_term_data` VALUES ('03dcb3a5-0b12-40d5-b458-3620d8c39afc', '06a75831-13a1-4660-870a-455bb445336a', '单工电台入口设备', '为单工无线电台进入地域通信网提供入口的设备。主要由无线电入口单元和无线电拨号单元等组成，并配置相应的单工无线电台。', 66);
INSERT INTO `t_military_term_data` VALUES ('03e2e99f-8f7f-4b81-a728-5b98920d3b02', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '操课', '部队或分队按规定进行的操练和上课的统称。', 27);
INSERT INTO `t_military_term_data` VALUES ('03e3c961-5c6f-464f-91f4-b994d5a37d56', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '反坦克履带地雷', '简称反履带雷。主要用以炸毁坦克等履带式车辆行动部分,使其失去机动能力的防坦克地雷。通常配用压发引信,利用履带或车轮的碾压使地雷起爆。', 139);
INSERT INTO `t_military_term_data` VALUES ('03e66747-8113-475b-ae71-38c61a87d211', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫生列车', '送伤病员并能在运行途中施行救治和保障生活的专用列车。列车编组一般包括伤病员车厢、诊疗车厢、餐车、工作人员寝车等。', 230);
INSERT INTO `t_military_term_data` VALUES ('03f579aa-263a-4800-9aad-c9c77186a01e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '快速反应', '对突然或意外出现的情况迅速采取相应的军事行动。', 249);
INSERT INTO `t_military_term_data` VALUES ('03f5fc8c-673c-4973-8466-d627610e3191', '98df76fb-4b65-48ff-a56c-4db587327c79', '战术运输', '为达成战术目的。在战术地幅内实施的军事运输。主要包括战术机动运输、物资补给运输和伤病员后送运输等。由兵团、部队的司令部、后勤部组织实施。', 247);
INSERT INTO `t_military_term_data` VALUES ('03faae1b-0092-41ab-91a4-6184d50902dc', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '比高', '地貌、地物由所在地面起算的高度。是一种相对高程。地图上对陡岸、冲沟、瀑布、路堤等常注出比高。', 174);
INSERT INTO `t_military_term_data` VALUES ('040556e6-1cee-47cc-9aab-5e16a8aa4ce6', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵声测侦察', '炮兵利用声测器材接收目标或炸点发出的声波以确定声源位置的侦察。主要测定敌方炮阵地坐标和己方射弹炸点偏差,并作为指挥和校正射击的依据。', 111);
INSERT INTO `t_military_term_data` VALUES ('0415c656-b313-4d08-b889-bbcddf78f388', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥艺术', '符合客观实际而又富有创造性的指挥才能的展现。是军队指挥员根据科学的指挥理论和实践经验充分发挥了观能动性的产物、主要表现在运筹决断、选将用兵战法运用等。', 3);
INSERT INTO `t_military_term_data` VALUES ('041d3cc4-5450-4dbb-95d4-ea8fcf8f0275', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '编队起飞', '两架以上直升机或飞机在地面摆成编队队形同时进行的起飞。', 46);
INSERT INTO `t_military_term_data` VALUES ('041e7a08-44e5-433a-907c-e09fd9ee27ef', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '宿营警戒', '保障军队宿营安全的警戒。可依情况派出营哨、连哨、排哨、班哨、组哨、步哨等担任。任务是防敌侦察、袭击,封锁消息,保障主力宿营安全。', 19);
INSERT INTO `t_military_term_data` VALUES ('042c60bc-3043-4297-a7bd-6525836e6912', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '数据分析', '从客观数据中分析提取反映事物内在规律或某种特征等有用信息的研究方法。可用以辅助军事决策。', 180);
INSERT INTO `t_military_term_data` VALUES ('0437b555-a673-42a3-80f7-3935bc203040', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反潜战', '使用反潜兵力、兵器粉碎、反击敌潜艇战的作战。分为战略反潜战、战役反潜战和战术反潜战。', 29);
INSERT INTO `t_military_term_data` VALUES ('0438542e-177c-4e43-84d7-2ccca82fd7ca', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机截击', '直升机在超低空或低空对敌空中目标进行的拦截与攻击。', 76);
INSERT INTO `t_military_term_data` VALUES ('043d651c-7e0d-42ff-9261-0830bd763c28', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹单元测试', '对导弹上单个仪器的性能参数进行的测试。一般在技术阵地上进行。', 88);
INSERT INTO `t_military_term_data` VALUES ('044b7dbe-9d96-4f07-8410-0eff4741e58d', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '计算机软件', '简称软件。计算机程序和相应的数据与文档的统称。一般分为系统软件和应用软件两大类。', 59);
INSERT INTO `t_military_term_data` VALUES ('04509db3-71bc-44b3-9640-86884e952043', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '高压脊', '天气图上水平气流呈明显的反气旋式切变、等压线伸向气压较低一侧的脊形区域。高压脊内各条等压线曲率最大处的连线称为脊线。脊线附近气流辐散下沉,天气晴好。', 46);
INSERT INTO `t_military_term_data` VALUES ('046b59a3-32bf-483b-abc9-e7790f1b45e9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '会合', '两个以上的部队或人员在预定地点相会。', 328);
INSERT INTO `t_military_term_data` VALUES ('047f319a-2d1f-40b9-9b33-81919ca76995', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '消耗', '军队人力、物力因使用或受损而造成的减少。包括平时消耗和战时消耗。', 392);
INSERT INTO `t_military_term_data` VALUES ('047f7897-aefb-4372-b3b8-ab0bb26f3ae4', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '国土防空', '为保卫国家领土安全而统一组织的全国性的防空。', 217);
INSERT INTO `t_military_term_data` VALUES ('0480579f-dc23-4528-b4c7-b9a77b9c1266', 'f0140091-c11a-48c9-8836-8aa94439dac0', '由岸到岸', '登陆兵搭乘海上输送工具,由己岸直接抵达敌岸的登陆输送方式。通常用于航程较近的登陆作战。', 144);
INSERT INTO `t_military_term_data` VALUES ('0491dfb0-fcac-40b6-9cc4-8f818c36b04a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮器材瞄准', '为使炮弹射向目标,赋予炮身轴线以一定的方向、高低角度或使观察器材瞄向目标的动作。', 275);
INSERT INTO `t_military_term_data` VALUES ('0493e4c8-0781-4dee-a8d5-98c2d140b417', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '阵地管理', '对阵地设施和进入阵地的部队、分队的战斗生活进行的管理。', 109);
INSERT INTO `t_military_term_data` VALUES ('0498ecc1-6fe1-49d7-93f1-5308b7994f6f', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '审俘', '审讯俘虏的简称。对俘获的敌军人员进行的审讯。旨在通过俘虏供词获取情报。', 47);
INSERT INTO `t_military_term_data` VALUES ('04993e4b-0a41-4435-a648-48467c035114', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '道路标志', '为保障行车安全、顺畅而在道路上设置的以示行车注意事项的标志。分为主标志和辅助标志。主标志包括警告标志、禁令标志、指示标志、指路标志等。辅助标志是附设在主标志下,起辅助说明作用的标志。军队在临战或战时,还可自定或自制道路标志。', 269);
INSERT INTO `t_military_term_data` VALUES ('049a9086-d24c-4576-bf43-5be2030551c7', '97a19170-bfac-42c5-9906-1acb187f0654', '迫降', '①飞机或直升机因特殊情况不能继续飞行时被迫进行的非正常降落。分为机场内迫降和机场外迫降。②以武力强迫航空器在指定的机场或其他着陆点降落。', 254);
INSERT INTO `t_military_term_data` VALUES ('049be96c-8c84-4f26-b903-f1c2febda0e7', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队攻击', '舰艇编队对敌实施的海上攻击。是水面战斗舰艇攻击的基本方法、有编队导弹攻击、编队鱼雷攻击、编队火炮攻击和编队深水炸弹攻击等。', 86);
INSERT INTO `t_military_term_data` VALUES ('04a10f29-346d-4d7e-bb8a-6709fdf0cc1a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '比例爆高', '简称比高。在相同大气条件下,爆炸高度与爆炸威力的立方根的比值。即：比高＝爆炸高度/根号3下威力。不同威力的核武器在空中爆炸的比高相等时,其爆心投影点的地面冲击波超压相等。', 144);
INSERT INTO `t_military_term_data` VALUES ('04ab8eee-25cb-4855-bf80-74798644b94e', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '臭氧层', '距地面 10～50千米高度之间的臭氧浓度大的大气层。能大量吸收太阳紫外辐射,影响大气的温度结构和环流,同时使地球上的生物免受过量紫外线的伤害。', 8);
INSERT INTO `t_military_term_data` VALUES ('04aed034-cd43-46be-b76d-cd18a0de0d51', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战役演习', '战役军团依据想定,结合一定战役方向和战役地幅情况进行的军事演习。分为陆军战役演习、海军战役演习、空军战役演习和第二炮兵战役演习等。目的是提高指挥员和机关的组织指挥能力以及部队的作战能力。', 127);
INSERT INTO `t_military_term_data` VALUES ('04b274ca-4e35-4631-9a80-c33b1e8a0a00', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器隐蔽性', '轻武器在使用中不易被敌方发现的性能。通常要求降低枪口噪声,减少枪口焰、烟和阵地杨尘；减小自然光和红外光的反射等。主要措施是加装消声、消焰、消烟的枪口装置增加保护性涂层等。', 221);
INSERT INTO `t_military_term_data` VALUES ('04bd6a8f-9f1c-4f57-90e9-212276181f2e', '06a75831-13a1-4660-870a-455bb445336a', '无线电信号通信', '按照预先规定的信号进行的无线电通信。一般用于紧急情况下指挥部队和报告情况。', 108);
INSERT INTO `t_military_term_data` VALUES ('04cc731f-b7fe-45dd-be60-e9697ceb8dd3', '97a19170-bfac-42c5-9906-1acb187f0654', '航空杀伤爆破炸弹', '主要以弹体爆炸时产生的弹片和冲击波杀伤人员、破坏坚固目标的航空炸弹。', 323);
INSERT INTO `t_military_term_data` VALUES ('04d01ece-eff7-406f-ae5b-35eba592d9ff', '97a19170-bfac-42c5-9906-1acb187f0654', '航空子母炸弹', '由许多小型子炸弹集装在母弹箱内构成的航空炸弹。分为杀伤子母炸弹、燃烧子母炸弹、反坦克子母炸弹等。在投掷后降至一定高度时,母弹箱解体,抛出小型子炸弹,可大面积杀伤人员、破坏目标。', 330);
INSERT INTO `t_military_term_data` VALUES ('04d4e4ad-c022-478f-ba4f-9ba7db9a2967', '97a19170-bfac-42c5-9906-1acb187f0654', '上仰轰炸', '飞机向前上方在不断增大上仰角的飞行中对目标进行的轰炸。投弹后通常向进入目标的反方向脱离。是强击机、歼击轰炸机从低空、超低空投掷核炸弹的基本方法。', 98);
INSERT INTO `t_military_term_data` VALUES ('04e4f9b9-6fc8-45ce-adfe-375884a68088', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '合同作战', '以一个军种或兵种为主,由其他军兵种直接配合进行的作战。包括各军种之间和同一军种内诸兵种之间进行的合同作战。', 180);
INSERT INTO `t_military_term_data` VALUES ('04f9dc74-19a9-47b6-a6fd-80ef550ec642', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '三角洲', '在河口由泥沙沉积而成并形似三角状的平原。一般地势低平,河网密集,多为良好的农耕地区,内外交通较便利。如中国的珠江三角洲。', 30);
INSERT INTO `t_military_term_data` VALUES ('04fa2995-7896-48be-b192-5e4772ad44d2', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备标准化管理', '为在武器装备的研制、生产、验收、使用、维修等环节中贯彻统一规定的指标要求而进行的管理。', 97);
INSERT INTO `t_military_term_data` VALUES ('04fcc451-c7fd-4c2e-ad9d-7433e79d56a6', '98df76fb-4b65-48ff-a56c-4db587327c79', '车公里限额', '在一定时间内或完成某项任务中,允许车辆消耗车公里数量的限定。分为正常车公里限额、专项任务车公里限额和价拨车公里限额。是分配车辆维修经费和供应油料的基本依据。', 322);
INSERT INTO `t_military_term_data` VALUES ('05019ca2-02bc-4a60-b136-66c820305134', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军衔', '区分和表明军人身份等级的称号和标志。通常分为军官军衔和士兵军衔。有的国家还设预备役军官军衔和预备役士兵军衔。', 127);
INSERT INTO `t_military_term_data` VALUES ('05045580-b934-4e42-9b4f-cfb4e2521774', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事突发事件', '突然发生、过程短暂、规模较小的武装冲突事件。可能是蓄谋的,也可能是偶然发生的。多指外来的武装袭击或边境武装冲突,有时也指国内敌对的武装集团之间突然发生的军事冲突。', 67);
INSERT INTO `t_military_term_data` VALUES ('0504fbd3-a30d-48b9-87e4-4d504d1441fd', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵战斗队形', '防空兵为便于遂行战斗任务,将兵力、兵器展开所形成的队形。通常由指挥所、发射阵地、对空观察哨、雷达阵地、技术阵地和弹药所等组成。', 17);
INSERT INTO `t_military_term_data` VALUES ('051a3d96-eab6-42f9-97fc-e486c4280439', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行地带', '机场中供飞机或直升机起飞、着陆的地带。通常由跑道、保险道和场内迫降场等组成。', 421);
INSERT INTO `t_military_term_data` VALUES ('05206591-ba6b-43f9-ad92-7b030f0b5941', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '优势', '战争中处于比敌方强大、有利地位的态势。通常由军事力量、作战指导及与之相关的政治、经济、科技、文化、地理环境等多种因素决定。优势是相对于劣势而言的,在一定条件下也可转化为劣势。', 265);
INSERT INTO `t_military_term_data` VALUES ('052d7f5e-e7c3-438c-81ee-815b832d6b43', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '弹药名称', '给弹药规定的称谓。常由定型年份、口径、弹种等组成。如 1956年式7． 62毫米普通弹。', 101);
INSERT INTO `t_military_term_data` VALUES ('053adfca-eb63-4b13-9805-daeede55849c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克指挥通信', '坦克指挥员为实施作战指挥而建立的通信。通常根据指挥关系,由上而下逐级组织实施。', 28);
INSERT INTO `t_military_term_data` VALUES ('0547e5bf-b7a1-4266-948a-56613c118539', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '鞍部', '山脊上相邻两山顶间形如马鞍状的低凹部分。山地的道路常从鞍部通过。', 19);
INSERT INTO `t_military_term_data` VALUES ('05510377-b44c-4ef2-8227-4b11d60e3c06', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事工程测量', '在军事工程建设的勘测设计、施工和管理阶段进行的各种测量。主要包括军用道路测量、军用坑道测量、军用机场测量、军用靶场测量、军用海港测量。', 236);
INSERT INTO `t_military_term_data` VALUES ('0557a843-6d64-4893-9630-29bd59648d5b', '8a761efd-50a6-4ac8-9913-b7d745104f82', '抵近射击', '射击武器达近目标时进行的射击。如步兵面对敌人在数十米内进行的端枪射击，火炮面对目标在数百米内进行的射击。', 94);
INSERT INTO `t_military_term_data` VALUES ('056039d7-fac8-4042-b500-4495658ebd78', '97a19170-bfac-42c5-9906-1acb187f0654', '战术轰炸', '为达成一定的战术目的而对敌战术目标进行的轰炸。', 94);
INSERT INTO `t_military_term_data` VALUES ('05742659-29e6-4198-9771-cf7559515de3', '8a761efd-50a6-4ac8-9913-b7d745104f82', '歼灭射击', '给敌生动目标或武器装备以重大毁伤，使其全部或大部丧失战斗力的射击。通常要求对暴露的集群生动目标的杀伤数量达到80％以上。', 100);
INSERT INTO `t_military_term_data` VALUES ('0576a7d0-d1d1-4232-8537-1ffb4950b024', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '击溃战', '只将敌人击退而未将之全歼或大部歼灭的作战。', 135);
INSERT INTO `t_military_term_data` VALUES ('0578efe4-0dfd-41f1-8237-00acf7609388', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核辐射生物效应', '核辐射对生物造成的损伤作用和后果。损伤程度主要取决于：核辐射的种类和强弱,照射条件、照射剂量,作用对象、作用部位、作用机制等因素。持续时间从瞬间到数年或更长时间。', 177);
INSERT INTO `t_military_term_data` VALUES ('0586194b-acc0-4517-a09e-e425b560e26f', '31f4a446-5b98-4873-9d53-310d97125b07', '战略导弹部队训练', '战略导弹部队进行的以作战理论和专业技术为主要内容的训练、主要包括军事理论教育、专业训练、操作训练、共同科目训练和合成训练、作战演习等。', 73);
INSERT INTO `t_military_term_data` VALUES ('058b6b0a-ae67-4a97-ad14-64da067836ee', '98df76fb-4b65-48ff-a56c-4db587327c79', '支援保障', '互不隶属的部队或单位之间在特殊情况下临时组织实施的后勤保障。通常由上级组织实施或由友邻之间主动协商组织实施。', 30);
INSERT INTO `t_military_term_data` VALUES ('0591b8fc-6af4-4b83-ba01-6237d8f57649', '06a75831-13a1-4660-870a-455bb445336a', '架空明线通信', '利用架空裸金属导线作为传输媒介的有线电通信。可传输电话、电报、数据和静止图像等。通信距离较远，但易遭破坏,保密性差。', 123);
INSERT INTO `t_military_term_data` VALUES ('0595bdeb-261e-4892-9dee-9c7afd530ed8', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军事军官', '军队中从事军事工作的军官。包括从事作战指挥、情报、训练、军务、动员、装备、通信等工作的军官。', 104);
INSERT INTO `t_military_term_data` VALUES ('05a81618-4403-44d3-90be-6317ae983939', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮指挥镜', '高炮部队和分队装备的对空观测的光学仪器。用以搜索、跟踪、指示目标,测定目标方位角、高低角及观察对空射击效果。', 55);
INSERT INTO `t_military_term_data` VALUES ('05c17655-2d33-4aa5-97d2-9f22e9843ee4', '916997ee-6728-4c61-9b79-d96960b1dc86', '洗消站', '对严重染有放射性物质、毒剂、生物战剂的人员、服装、武器装备等进行洗消的场所。由洗消分队开设。位置一般选择在受染部队和分队附近,靠近水源、便于隐蔽、进出方便的未受染地区。', 12);
INSERT INTO `t_military_term_data` VALUES ('05c54ce0-0e1d-4cfe-a5e0-f20b965542d3', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹连续发射', '两发以上地空导弹按照一定程序和时间间隔射向同一目标的发射。通常无须判明前一发导弹射击效果,即可发射下一发导弹。', 211);
INSERT INTO `t_military_term_data` VALUES ('05c6abb5-eff9-4e82-86bb-88cc94e45ea2', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防勤务', '边防武装力量在边境地区执行的例行性军事活动。如巡逻、观察、潜伏、搜捕等。', 113);
INSERT INTO `t_military_term_data` VALUES ('05c7ec3d-ed60-4eae-b184-b351b7fd270c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水上飞机', '能在水面起飞和降落的飞机。分为船身式水上飞机和浮筒式水上飞机。主要用于海上侦察、巡逻、反潜、轰炸、布雷、扫雷、救护和运输等。通常装备有航炮、空舰导弹或鱼雷、深水炸弹、航空炸弹、航空水雷等。', 180);
INSERT INTO `t_military_term_data` VALUES ('05c95a7c-b4c3-4c04-b59b-524b15e7d850', '97a19170-bfac-42c5-9906-1acb187f0654', '空中集合', '飞机或直升机为完成空中编队而进行的机动飞行。分为转弯集合、直线追赶集合等。', 46);
INSERT INTO `t_military_term_data` VALUES ('05d2977e-78eb-4be1-8921-8fa88f0e304c', '97a19170-bfac-42c5-9906-1acb187f0654', '永备机场', '具有较完备的飞行保障设施,供航空兵部队长期驻用的军用机场。通常修建有水泥混凝土或沥清混凝土跑道,配备有固定式的飞行保障设施。', 412);
INSERT INTO `t_military_term_data` VALUES ('05d428a0-a350-4727-9ad2-3b9e7cef86ff', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机前飞', '直升机向其机头方向前进的飞行。', 22);
INSERT INTO `t_military_term_data` VALUES ('05d69bf4-20a0-4b5b-8d14-4d9cad59725d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '断绝地', '被江河、湖泊、沼泽、断崖、绝壁、狭谷、深沟等阻隔而难以通行的地段。', 122);
INSERT INTO `t_military_term_data` VALUES ('05f6c179-2259-4b44-952e-23748c96be2e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '飞机水上起降', '水上飞机和水陆两用飞机、直升机在水上的起飞和降落。通常在飞机性能允许的风速、浪高等条件下进行。', 307);
INSERT INTO `t_military_term_data` VALUES ('05fc495f-07cf-4707-9d7e-378af690f03f', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵作战保障', '防空兵为顺利遂行作战任务而采取的各项保证性措施和进行的相应活动的统称。主要包括侦察,警戒,通信联络,电子防御,对核、化学、生物及燃烧武器的防护,以及工程、伪装、气象等方面的保障。', 95);
INSERT INTO `t_military_term_data` VALUES ('060fc2e9-8ebe-44bc-9e45-c470e3fd0e9d', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '扫频电子干扰', '干扰发射机的载频按某种方式在某一频段内周期性地连续变化所形成的电子干扰。在通信干扰中。扫频干扰可对某一频段内的各个信道或某几个固定信道逐一进行干扰。在雷达干扰中,则是对频段内的所有雷达进行干扰。', 49);
INSERT INTO `t_military_term_data` VALUES ('064a69fc-696c-4a8c-baec-f1591d56f4b2', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹飞行试验测量站', '导弹飞行试验中负责在地面或海面跟踪导弹并测量其运动状态参数、轨道参数、接收遥测信息的地面站。包括光学测量站、雷达测量站、遥测接收站和综合测量站等。', 82);
INSERT INTO `t_military_term_data` VALUES ('064bead7-ae54-42ab-9d22-1e3c9303ac63', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通保障', '根据军事目的,为进行交通准备和保持、恢复、提高交通设施能力而进行的保障。主要措施包括：规划和建设各种交通设施及交通防护、伪装、备用设施,发展、改进运输工具、筹措、储备交通物资器材,组织训练交通保障专业队伍,遂行抢修和防卫任务等。', 280);
INSERT INTO `t_military_term_data` VALUES ('066725d8-f880-4e67-8015-04df5c2aa8fb', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役规律', '战役诸因素之间的本质联系及其发展的客观必然趋势。', 15);
INSERT INTO `t_military_term_data` VALUES ('06700440-deff-4d98-acd8-966154954164', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事', '一切与战争或军队直接相关的事项的统称。主要包括国防建设与军队建设、战争准备与战争实施等。', 3);
INSERT INTO `t_military_term_data` VALUES ('06767dab-3e92-43bb-acec-908579bd8da5', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场救护打捞站', '渡场内负责救护落水人员,打捞落水物资、技术兵器和车辆的机构。通常设在渡口下游。', 319);
INSERT INTO `t_military_term_data` VALUES ('0678be03-c4c3-4bd2-b288-e11f5654b83b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇消磁', '减弱舰艇磁场强度并改善其分布特性的技术措施。用以提高舰艇的磁性防护能力,有效地防御磁探测和水中磁性武器的攻击。消磁方法有临时线圈消磁法和固定绕组消磁法。', 342);
INSERT INTO `t_military_term_data` VALUES ('067c62ee-18a9-4988-abcc-9f54114d0f8a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '遏制', '国家或政治集团之间,以军事实力或其他手段阻遏或制止对方行动的行为。', 72);
INSERT INTO `t_military_term_data` VALUES ('0680fcce-8d0f-4148-9d83-11c92c92c9ef', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '宿营地域', '部队宿营所在的地域。根据任务。敌情、地形等条件选定。宿营地域通常应有适当的地幅和良好的地形,便于疏散隐蔽地配置部队,并有良好的进出道路和充足的水源,避开明显目标和传染病区。', 95);
INSERT INTO `t_military_term_data` VALUES ('06857862-7daf-4f60-b327-5a46cbba15c8', '97a19170-bfac-42c5-9906-1acb187f0654', '公路飞机跑道', '简称公路跑道。在公路上修筑的可供飞机起飞、着陆的路段。是机场网的组成部分。', 424);
INSERT INTO `t_military_term_data` VALUES ('0693eaf7-a029-41d7-aba9-11b1038bb800', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '暂行编制', '军队暂时实行的带有试行性质的编制。通常在调整、改编部队或组建新型部队时采用。', 63);
INSERT INTO `t_military_term_data` VALUES ('06a75831-13a1-4660-870a-455bb445336a', '0', '通信兵', NULL, 19);
INSERT INTO `t_military_term_data` VALUES ('06bbcbb8-9bdd-4e68-97da-2d2885c63b15', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '大休息', '行军中间隔时间和休息时间均较长的休息。通常用以保障用餐、休息、检修装备。大休息时,应进入指定地区,加强警戒,保持战斗准备。夜行军一般不进行大休息。', 62);
INSERT INTO `t_military_term_data` VALUES ('06be0c47-e39d-43fd-9234-ddec78f231e5', '916997ee-6728-4c61-9b79-d96960b1dc86', '伤害浓度', '在一定时间内能使90 ％以上无防护人员丧失战斗力的染毒浓度。用IC90-100表示。', 126);
INSERT INTO `t_military_term_data` VALUES ('06c3112e-7786-456c-b13a-c017b0ff6194', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '照明地雷', '装填照明剂或照明弹的特种地雷。发火后能引燃照明剂原地燃烧或将照明弹抛向空中。照明半径为数十米至数百米。', 152);
INSERT INTO `t_military_term_data` VALUES ('06c5894d-e56b-46c8-af27-cb924cce97f3', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '黑火药', '亦称有烟火药。由硝酸钾、硫磺和木炭混合而成的火药。主要用作导火索芯药,也可用以装填地雷等。', 205);
INSERT INTO `t_military_term_data` VALUES ('06cc03f5-43b0-4341-97ef-95d4c859418d', '98df76fb-4b65-48ff-a56c-4db587327c79', '紧急救治', '战时团或团级单位的救护所为防止伤病员伤病情恶化和保证其后送安全而实施的应急救治。主要包括：对急救措施的补充和纠正；对有生命危险的伤病员实施气管切开,开放性气胸包扎、封闭等紧急手术；对大部分伤病员进行抗休克、抗感染等。', 195);
INSERT INTO `t_military_term_data` VALUES ('06dd61c2-612e-4d4c-b905-714ce31b7ad8', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '野战净水车', '野战条件下净化用水的专用车辆。分为普通净水车、蒸馏净水车、离子交换净水车、电渗析净水车和反渗透净水车等。具有机动性好,净水量大,便于快速开设给水站等特点。', 369);
INSERT INTO `t_military_term_data` VALUES ('06e5a1c3-d8e6-4147-b058-ccbd403f0424', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥机关', ' 军队中具有组织指挥职能的常设机关、如总参谋部及各级司令部。', 41);
INSERT INTO `t_military_term_data` VALUES ('06ea1dcc-bd4c-403a-bcd7-c693b0ff0730', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场开设', '在渡河地区内选定渡场位置。构筑渡场设施、建立渡场勤务等的行动。主要包括：江河工程侦察,排除渡场区域内的障碍物,修筑道路,准备渡河器材,设置防雷和防漂流物护栏,构筑渡口、掩蔽工事,进行渡场伪装和派出勤务分队等。', 325);
INSERT INTO `t_military_term_data` VALUES ('06f137b1-e154-4a8c-b95a-7ea55176daa8', '916997ee-6728-4c61-9b79-d96960b1dc86', '杀伤性化学袭击', '以杀伤敌有生力量为主要目的的化学袭击。通常使用致死性或失能性毒剂,突然、集中攻击预定目标,使敌方人员在极短时间内遭到杀伤或丧失战斗力。', 23);
INSERT INTO `t_military_term_data` VALUES ('0709e9af-df42-4aa3-abbb-0c70f5c8f90c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '光冲量', '核爆炸火球整个发光时间内,投射到与光线传播方向相垂直的单位面积上的能量。通常以焦／平方厘米为计量单位。', 166);
INSERT INTO `t_military_term_data` VALUES ('07240eb1-c06d-480f-88ca-5f7bbcd28edd', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队文化工作', '中国人民解放军为发展文艺、体育事业和开展群众性文化娱乐活动而进行的工作。是中国人民解放军政治工作的重要内容。', 110);
INSERT INTO `t_military_term_data` VALUES ('0728ec75-6aa9-47a4-a347-9504a12878f1', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '部队编成', '按一定要求将部队建制单位、人员、武器装备组成有机的整体。包括建制内的部队编成、建制单位加配属单位的部队编成。', 81);
INSERT INTO `t_military_term_data` VALUES ('073d7d8e-51a0-427d-b2e5-58444dca25f3', '97a19170-bfac-42c5-9906-1acb187f0654', '机载火力控制系统', '简称机载火控系统。安装在飞机或直升机上,专门用以控制航空武器实施作战的电子设备系统。通常由目标探测设备、载机参数测量设备、火控计算机、瞄准显示设备和瞄准控制设备等组成。基本功能是：搜索、识别和跟踪目标,引导或操纵载机接敌占位,控制机载武器的瞄准、射击、投掷和制导。', 338);
INSERT INTO `t_military_term_data` VALUES ('073db276-2731-4c72-8ee0-df903c4b61dc', '97a19170-bfac-42c5-9906-1acb187f0654', '航空技术装备定期检修', '由简称定检。按照规定的周期对航空技术装备进行的预防性检查和维修。目的是保持和恢复航空技术装备的可靠性。使之在下一个周期内能正常使用。', 447);
INSERT INTO `t_military_term_data` VALUES ('073f6678-2032-4850-9e90-06bb45a83a33', 'f0140091-c11a-48c9-8836-8aa94439dac0', '陆军战术', '陆军兵团、部队、分队进行战斗的方法。分为陆军合同战术和陆军兵种战术。', 24);
INSERT INTO `t_military_term_data` VALUES ('0747f5ac-c4ae-48b5-9478-46fc0301c5dd', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战绩', '作战取得的成绩。包括战役、战斗上取得的进展和收获,攻占和守住的地方,获得的战果等。', 384);
INSERT INTO `t_military_term_data` VALUES ('07511968-85b8-4fa1-a7e1-aa4bfca4d456', '878651de-adf5-4c72-9376-9c363b893ff8', '现代化战争', '大量运用现代化武器和技术装备及相应作战方法进行的战争。随着现代科学技术和武器装备的发展,战争的现代化程度愈来愈高。', 14);
INSERT INTO `t_military_term_data` VALUES ('0753d03c-d810-40c6-b685-6ccd633ec556', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '海洋权益', '主权国家在海洋中享有的各种权力和利益的统称。主要包括：在领海的主权,在毗连区、专属经济区、大陆架等的经济主权权利和管辖权,在别国领海以外的自由航行、飞越权以及在别国领海的无害通过权。', 78);
INSERT INTO `t_military_term_data` VALUES ('075a83a4-4ac4-4f39-b50c-47d75e17b230', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '岛屿防御战役', '依托岛屿进行的防御战役。可以是单独的防御战役,也可以是抗登陆战役的组成部分。', 123);
INSERT INTO `t_military_term_data` VALUES ('0763bf01-7e29-479b-9b4f-3604ca6ed2d7', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇上层建筑', '舰艇主船体上甲板以上的围蔽结构和附属结构的统称。包括船楼、甲板室、烟囱和机舱棚等。', 164);
INSERT INTO `t_military_term_data` VALUES ('076484aa-7d19-4236-a805-86305df16fc6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军飞机', '装备于海军,主要用以执行海洋上空的战斗、训练和保障任务的飞机。按起降场地,分为岸基飞机、舰载机、水上飞机等；按作战任务,分为轰炸机、歼击轰炸机、强击机（攻击机）、歼击机、反潜机、侦察机、预警机、电子对抗飞机、运输机、教练机等。', 171);
INSERT INTO `t_military_term_data` VALUES ('0778a19f-e48e-41cf-8dfe-0093b22d64cf', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学防护', '化学武器防护的简称。为避免或减轻敌化学袭击的伤害而进行的防护。主要包括：查明敌化学武器种类、数量、配置地域和储存情况,建立化学观察、警报报知配系,完善工事防化设施,组织防护训练和三防装备保障,实施化学侦察和化学监测,消除化学袭击后果等。', 47);
INSERT INTO `t_military_term_data` VALUES ('0782c16c-a13a-4e70-98a4-7c43a9544ea4', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇隆重升旗', '舰艇列队升旗,同时升起满旗、舰首旗、桅顶旗的隆重礼仪。通常在重大节日、海军成立纪念日、阅兵和授旗、命名、授予荣誉称号等典礼时进行。', 399);
INSERT INTO `t_military_term_data` VALUES ('07a6c17f-e11f-4ac6-807a-d659bff9c4ba', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '跳频', '在一定的频率范围内随机跳变无线电发射设备的载波频率。是一种反干扰技术。可用机械方法,也可用电子方法。', 103);
INSERT INTO `t_military_term_data` VALUES ('07b32e4a-e43c-40a2-a1a9-b04690dbd815', '98df76fb-4b65-48ff-a56c-4db587327c79', '伤死率', '伤死人数与战伤减员、非战斗外伤减员的人数之和的比值。通常用百分比表示。是衡量救治工作质量的重要指标。', 191);
INSERT INTO `t_military_term_data` VALUES ('07bdf6f3-0722-4e8a-91c4-64dabe4f281f', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役方针', '战役行动所要达到的总目标及其采取的基本方法。是战役行动应遵循的根本依据。通常根据战略意图、战役任务和敌我情况等确定。', 17);
INSERT INTO `t_military_term_data` VALUES ('07c6f898-4965-472c-bc42-fdc2e7cd2615', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '待机', '等待有利于军事行动的时机。', 251);
INSERT INTO `t_military_term_data` VALUES ('07ccbcf4-9862-4e15-a4d8-26e8f17306c8', 'd7132c58-5df3-4b97-919f-58740148b9ca', '便携式地空导弹迎攻射击', '亦称迎头攻击。便携式地空导弹在空中目标未过航路捷径之前对其进行的射击。', 205);
INSERT INTO `t_military_term_data` VALUES ('07d97204-34af-4a8f-841c-c89c9f3cf2ca', '98df76fb-4b65-48ff-a56c-4db587327c79', '战术储备', '为保持经常的战斗准备或根据完成一定战斗任务的需要而进行的物资储备。包括移动储备与加大储备。通常由战术指挥员掌握。储备量根据兵团或部队担负的作战任务,携运行能力,以及物资消耗规律、战中补充难易程度等因素确定。', 113);
INSERT INTO `t_military_term_data` VALUES ('081139bb-a2a4-45e4-a26f-0f9adf3459d3', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '地下核爆炸', '爆心在地面以下的核爆炸。分为浅层地下核爆炸和深层地下核爆炸。浅层地下核爆炸,能造成较大的弹坑,以极强的岩土冲击波和震动摧毁地下坚固的目标,并造成严重的放射性沾染。深层地下核爆炸,不形成弹坑,大量放射性物质被封闭于地下。', 152);
INSERT INTO `t_military_term_data` VALUES ('081468ea-81b3-4174-8252-2951dc714472', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '利用测距机试射', '利用测距机测定炸点距离偏差量进行射击修正的试射。采用测距矾测距较为精确,有利于提高试射精度。', 154);
INSERT INTO `t_military_term_data` VALUES ('081e85a3-dc02-4d21-a120-0d5e26483ec9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '杀伤弹', '以弹丸爆炸后产生的破片和冲击波毁伤目标的炮弹。主要用以毁伤敌隐蔽和暴露的有生力量和武器装备。', 305);
INSERT INTO `t_military_term_data` VALUES ('08216891-32a8-441e-8a93-42ed1014c947', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役指挥', '指挥员及其指挥机关对战役行动的组织领导活动。', 22);
INSERT INTO `t_military_term_data` VALUES ('082884f2-d9b9-46fd-9434-649c15fb19d2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '全歼', '敌军全部或90％以上被歼灭。', 379);
INSERT INTO `t_military_term_data` VALUES ('08331ab9-6266-4a75-b47f-15ecf1eae30f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事谋略', '在军事斗争中、为达成一定目的而构想并运用的计谋与策略。', 57);
INSERT INTO `t_military_term_data` VALUES ('083751a7-a68b-412a-926e-81dc1b39d845', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战斗指挥', '兵团或部队的指挥员及其指挥机构和分队指挥员对战斗行动的组织领导活动。', 43);
INSERT INTO `t_military_term_data` VALUES ('084f1144-dc60-4a1f-b5c6-45fd863c3694', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '碎甲弹', '以塑性炸药爆炸所产生的爆轰波能量使装甲内壁碎裂出破片杀伤、破坏目标的炮弹。主要用以杀伤破坏敌装甲车辆内的乘员和装备。', 310);
INSERT INTO `t_military_term_data` VALUES ('0868fe4e-a006-4d21-b9ef-536fc1bd5982', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹起坚设备', '将导弹由水平状态转为垂直状态并放置到发射装置上的设备。有的起竖设备还可用于短距离的导弹运输。', 67);
INSERT INTO `t_military_term_data` VALUES ('088f3e3c-a49d-458b-8ad0-16f01ecb58ad', '916997ee-6728-4c61-9b79-d96960b1dc86', '个人消毒急救盒', '亦称个人防护盒。装有预防药物和消毒、急救物品的个人防护器材。盒内装有对神经性毒剂的预防药品、中毒急救用的解磷针和用于对液态毒剂消毒的活性白土消毒剂等。', 174);
INSERT INTO `t_military_term_data` VALUES ('08b94f5f-2745-4434-ba80-b8ad8308e2a2', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '后方尖兵', '位于行军纵队后方的尖兵。通常由后卫派出。也可由本队直接派出。', 16);
INSERT INTO `t_military_term_data` VALUES ('08c9a8ce-c89d-4e1d-8104-3208727689f7', '97a19170-bfac-42c5-9906-1acb187f0654', '地面能见度', '人的正常视力在地面向水平方向观看,昼间能看清目标物轮廓的最远距离,或夜晚能看见灯光的最远距离。是确定飞行气象条件和机场开放或关闭的重要依据之一。', 387);
INSERT INTO `t_military_term_data` VALUES ('08dbfd07-8b9b-43ae-b9d7-61dbceabb4c0', '878651de-adf5-4c72-9376-9c363b893ff8', '太空战略', '亦称空间战略。筹划和指导航天技术的发展,对宇宙空间进行探索与利用的方略。', 51);
INSERT INTO `t_military_term_data` VALUES ('08ddaaa6-890d-4000-b419-c7788095b581', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '退却', '亦称撤退。军队放弃所占领的阵地或地区,有组织地向后转移的作战行动。分为战略退却、战役退却和战术退却。', 400);
INSERT INTO `t_military_term_data` VALUES ('08dfd304-1dc6-404e-ba03-590c24721014', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '抗辐射加固', '为使武器系统及其设施、设备在受到核辐射的情况下仍能保持其预定功能而采取的防护性加固措施。', 134);
INSERT INTO `t_military_term_data` VALUES ('08e67e4c-6719-4d8b-9f5a-e00447fefd50', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '机动', '为夺取和保持主动或形成有利态势而有组织地迅速转移兵力兵器或转移火力的行动。按内容,分为兵力优动和火力机动；按规模,分为战略机动、战役机动和战术机动；按空间,分为地面机动、海（水）上机动和空中机动。', 335);
INSERT INTO `t_military_term_data` VALUES ('08f7a0d1-de28-4685-87da-2666f9b39391', '916997ee-6728-4c61-9b79-d96960b1dc86', '喷火组', '执行喷火任务的小组。由喷火分队派出。通常由喷火手和单兵火箭手4～6人混合编成,装备有喷火器及防化单兵火箭2～3具。可单独配属给步兵分队遂行战斗任务,也可在班的编成内行动。', 13);
INSERT INTO `t_military_term_data` VALUES ('093be661-fff4-47c1-b7c5-caccea59f31b', '97a19170-bfac-42c5-9906-1acb187f0654', '二级航空维修', '亦称野战维修。由航空兵部队修理厂、飞行院校修理厂和航空中心修理厂对航空技术装备实施的较复杂的航空维修。主要包括：小修、中修,航空器损伤抢修,部、附件大修,较简单的改装等。', 445);
INSERT INTO `t_military_term_data` VALUES ('09507cf1-68ed-457b-9415-bcada6dc5e59', '98df76fb-4b65-48ff-a56c-4db587327c79', '方案', '部队根据预定的作战任务和运输方式拟制的输送方案。主要内容包括部队输送计划、梯队装载计划、装载地域要图、输送保障计划等。', 255);
INSERT INTO `t_military_term_data` VALUES ('09522bd6-f03f-47b6-aaf6-a0a106751d51', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '建军方针', '在一定时期内军队建设所要达到的总目标和应遵循的指针。是军事方针的重要组成部分,也是一定的建军思想的体现。', 95);
INSERT INTO `t_military_term_data` VALUES ('095758ea-a19e-4948-bab8-50c12d8d9cad', '97a19170-bfac-42c5-9906-1acb187f0654', '一级航空维修', '亦称外场维修。由飞行团机务大队对航空技术装备实施的较简单的航空维修。主要包括：日常维护、保养,周期检测、定期检修,排除一般性故障,调整、更换机件等。', 444);
INSERT INTO `t_military_term_data` VALUES ('0964108a-5940-4456-805c-09180cb60507', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '观察', '用目力或借助光学器材对一定区域和目标进行的察看和监视。', 40);
INSERT INTO `t_military_term_data` VALUES ('09713e04-7a80-45bb-8a74-a4d80e6dbebc', 'f0140091-c11a-48c9-8836-8aa94439dac0', '出击', '亦称阵前出击。越出防御前沿,对准备发起进攻或冲击受挫之敌实施的攻击行动。是破坏敌人进攻,稳定防御的一种积极手段。', 252);
INSERT INTO `t_military_term_data` VALUES ('098385c3-1354-4c8f-a9ae-6b686df3aa25', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电引信干扰', '发射干扰电磁波,使敌方射弹上的无线电引信提前引爆或失效的电子干扰。', 56);
INSERT INTO `t_military_term_data` VALUES ('099e254d-2dbe-4db4-a413-64c5389ad13e', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '极轨道', '亦称极地轨道。倾角为90度的人造地球卫星轨道。在极轨道上运行的卫星,每圈都经过地球两极上空,其星下点轨迹可覆盖整个地球。照相侦察卫星、气象卫星、地球资源卫星常采用这种轨道。', 239);
INSERT INTO `t_military_term_data` VALUES ('099f5744-eb51-431e-8452-50db9232bfb9', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队监控设备', '导弹部队为掌握和监视、控制作战行动及武器装备工作状况而使用的设备。主要包括导弹发射准备与发射及导弹作战指挥等的监控设备。', 128);
INSERT INTO `t_military_term_data` VALUES ('09a48a64-865f-45f9-abcb-6c9295915fd3', 'f0140091-c11a-48c9-8836-8aa94439dac0', '合同战术', '诸军兵种进行合同战斗的方法。包括军种之间和同一军种内诸兵种之间进行合同战斗的方法。', 22);
INSERT INTO `t_military_term_data` VALUES ('09f2a26a-b4fc-4751-87e0-74e6e150f037', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '建筑部队', '工程兵中担负国防工程建筑任务的专业部队。装备有建筑机械和保障机械等。主要负责构筑重要的永备工事、导弹发射阵地和特种工程等。', 5);
INSERT INTO `t_military_term_data` VALUES ('09f54ddf-cc3a-47a4-9d63-69e867ffc76f', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵作战指挥', '航空兵指挥员及指挥机构对所属部队或分队的作战和其他军事行动实施的指挥。包括防空作战指挥、空中进攻作战指挥等。', 184);
INSERT INTO `t_military_term_data` VALUES ('09ff8717-3f26-4a55-b490-e3dba8e266af', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '国防经济学', '研究国防经济活动的理论与实践及其规律的学科。主要研究内容包括：国防与经济的关系,国防经济的体制和结构,战争的经济准备和保障,以及军品的生产、采购及其与民品生产的关系等。', 29);
INSERT INTO `t_military_term_data` VALUES ('09ff9c65-35a9-4db5-b253-b2ea2fa4294d', '97a19170-bfac-42c5-9906-1acb187f0654', '空中保障队', '机群中担负各种空中保障任务的空中编队。通常由若干小编队组成。负责气象侦察、目标的侦察与指示、压制地面防空火力、实施电子对抗和佯动等。', 51);
INSERT INTO `t_military_term_data` VALUES ('0a0b5962-237d-49ae-ae23-7c5c2270547c', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军团', '①集团军（军）以上规模的兵力集团的统称。②军队中的一级组织。如中国土地革命战争时期的中国工农红军第1军团。下辖若干个军或师。', 40);
INSERT INTO `t_military_term_data` VALUES ('0a11a3a3-773e-4714-84b2-85dca9bf8f1f', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克操纵装置', '控制坦克推进系统各机构动作的装置。一般分为机械式、液压式、气压式、电力和综合式等。', 127);
INSERT INTO `t_military_term_data` VALUES ('0a135561-c26d-4c02-b3a1-b713a5f6749b', '97a19170-bfac-42c5-9906-1acb187f0654', '空军地面防空兵', '空军中以地面防空武器系统为基本装备,主要遂行地面防空作战任务的地空导弹兵和高射炮兵的统称。', 21);
INSERT INTO `t_military_term_data` VALUES ('0a174d30-da6c-4771-a591-8042619ae5f9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '内卫', '为保障国家内部安全面实施的警戒和保卫。主要包括保卫国家政权、维护社会治安以及对重要的地区、部门、设施、人物等的安全保卫。', 426);
INSERT INTO `t_military_term_data` VALUES ('0a1d0771-bb8f-4ce4-9d72-2dd1cff4bfc5', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '被覆', '对工事内壁、外表进行的加固。目的是增大其强度,防止工事内壁和外部上坡坍塌,改善内部环境。一般用草皮、编条、束柴、砖、石、竹、木、钢筋混凝土等作被覆材料。', 90);
INSERT INTO `t_military_term_data` VALUES ('0a1fb4f5-ce36-4623-80ef-2aab3bbf2d67', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '坐标变换', '将其点从一个坐标系的坐标换算为另一坐标系的坐标。', 235);
INSERT INTO `t_military_term_data` VALUES ('0a3a6de2-68df-4c26-a51f-94d8abf0e31e', '916997ee-6728-4c61-9b79-d96960b1dc86', '持久性毒剂', '施放后对人员的杀伤作用时间能持续数小时至数天或数十天的毒剂。如芥子气、维埃克斯等。主要以液滴状态,造成人员、地面和物体染毒,杀伤有生力量,阻碍人员行动。', 205);
INSERT INTO `t_military_term_data` VALUES ('0a3da75d-4d83-4baa-97d3-40175f2a287d', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹制导系统', '导引和控制导弹按选定的导引规律飞行而命中目标的全部装置和软件的统称。由测量装置、计算装置和执行装置三个部分组成。', 41);
INSERT INTO `t_military_term_data` VALUES ('0a446915-f208-48a8-b229-f30be97cdf2c', '916997ee-6728-4c61-9b79-d96960b1dc86', '洗消', '对受染对象实施消毒和消除沾染的措施。主要包括：对受染人员、武器装备实施洗消,对染毒、污染的道路、地域实施消毒,对沾染的坑道工事口部和坚硬路面实施消除等。', 59);
INSERT INTO `t_military_term_data` VALUES ('0a5137a9-f377-4d90-ab16-27256957aafc', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军地带', '军队行军所经过的地带。通常由上级给所属部队划定,以供从中选定行军路线。行军地带的宽度依任务、敌情、道路和军队的数量而定。', 54);
INSERT INTO `t_military_term_data` VALUES ('0a5813e1-7154-4e85-9d48-d58ebc7a954f', '916997ee-6728-4c61-9b79-d96960b1dc86', '防毒面具', '保护呼吸器官、眼睛和面部免受毒剂、生物战剂和放射性落下灰等伤害的个人防护器材。按防护原理,分为过滤式防毒面具和隔绝式防毒面具；按使用对象,分为军用防毒面具和民用防毒面具等。', 172);
INSERT INTO `t_military_term_data` VALUES ('0a77d15c-2fc9-4d6a-8934-e8b616159692', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地图清绘', '按照地图图式和有关规定对实测原留或编绘原图的蓝图,进行艺术加工的着墨作业。分为等大清绘和放大清绘。视地图内容繁简,可进行一版清绘或分版清绘。', 288);
INSERT INTO `t_military_term_data` VALUES ('0a880056-6d05-4cf6-b002-10753feaf627', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '平面直角坐标', '用平面上的长度值表示地面点位置的直角坐标。中华人民共和国地形图采用高斯-克吕格投影建立平面直角坐标系。地形图上坐标值均以千米数为单位,注记在内外图廓线之间。平面直角坐标,计算简便。军事上用以指示和确定目标在图上的位置,量算距离和面积。', 234);
INSERT INTO `t_military_term_data` VALUES ('0a920cd3-7f12-455b-adc5-7ecb0ec0990f', '98df76fb-4b65-48ff-a56c-4db587327c79', '医用制氧站', '军队生产、储存、供应医用氧气的卫勤专业机构。', 217);
INSERT INTO `t_military_term_data` VALUES ('0a9457a1-8051-4d8d-81f9-45966cc7bbc9', '83e065b4-6737-4645-9ea5-8276d1de13ed', '主战坦克', '具有现代技术特征,能在坦克作战中担负主要作战任务的坦克。是现代装甲兵的基本装备和地面作战的主要突击兵器。由中型和重型坦克发展演变而来。在火力和装甲防护方面,达到或超过以往重型坦克的水平,同时又具有以往中型坦克机动性好的特点。', 90);
INSERT INTO `t_military_term_data` VALUES ('0a9fe3be-1a77-4406-aa58-ffa80c8c0f31', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '崖孔', '亦称猫耳洞。构筑在掩体、堑壕、交通壕崖壁上供人员隐蔽和存放弹药、物资的浅洞。', 66);
INSERT INTO `t_military_term_data` VALUES ('0aa5b662-0364-47ac-90a6-9d35dec69e8f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战方向', '军队遂行作战任务的行动方向。按作战类型,分为进攻作战方向和防御作战方向；按在作战中的地位,分为主要作战方向和次要作战方向。', 176);
INSERT INTO `t_military_term_data` VALUES ('0ab23d53-f98b-48e6-b770-d48e6674baf1', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教学准备', '为实施教学而预先进行的各种准备活动。主要包括：依据教学大纲研究、熟悉教材,了解教学对象,制定教学实施计划,编写教案或作业指导法,进行试讲、试教等。', 34);
INSERT INTO `t_military_term_data` VALUES ('0abcfa69-87d6-48ee-b470-3a96afb1e1a5', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工事主体', '工事中用以实现其主要功能的部分。如射击室、观察室、掩蔽室等。', 81);
INSERT INTO `t_military_term_data` VALUES ('0aca3080-ed28-452f-aa42-e88a62259703', '8a761efd-50a6-4ac8-9913-b7d745104f82', '信号枪', '发射信号弹、照明弹的手枪式装置。分为单管信号枪和双管信号枪。是简易通信工具之一。人工装填,结构简单，口径20毫米以上。', 181);
INSERT INTO `t_military_term_data` VALUES ('0acb9878-7f43-4108-8b65-b72bc3c85cf9', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '云量', '云遮蔽天空视野的成数。观测时把天空分为10等份,用目力估计被云遮蔽的份数即为云量,计量单位为成。根据云量和云族,可将天空状况分为晴（无云或微量云）多云（中、低云量为4～7成或高云量为6～10成）和阴（中、低云量为8～10成）等。', 20);
INSERT INTO `t_military_term_data` VALUES ('0ae64c82-a137-4db1-9839-9cf273304db4', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机战术技术性能', '由设计、制造等因素决定的军用直升机所具备的固有特性和功能。主要包括发动机功率、飞行性能机载武器效能、生存力等。', 10);
INSERT INTO `t_military_term_data` VALUES ('0af137b6-b20a-4365-8319-5888fbfcca3d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰地导弹', '从水面舰艇上发射,用以攻击陆上目标的导弹。', 191);
INSERT INTO `t_military_term_data` VALUES ('0afac2fc-5104-4729-a51c-c9d2808e5fef', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '假文电', '为隐蔽己方真实意图、欺骗敌方而发出的文电。通常在己方的通信信道中发出,或插入敌方通信信道冒充敌台发出。', 72);
INSERT INTO `t_military_term_data` VALUES ('0afe4b8a-a61d-4883-9493-7d93eeedf2c5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵控制网', '炮兵根据国家控制点或军用控制点加密而成的或自行建立的测地控制网。建网工作通常由炮兵指挥机关组织、炮兵测地分队实施。', 119);
INSERT INTO `t_military_term_data` VALUES ('0aff8212-f07e-452f-9ded-773fb9fc9370', '97a19170-bfac-42c5-9906-1acb187f0654', '备降机场', '简称备降场。飞机或直升机不能在预定机场降落时使用的备用机场。分为固定备降机场和临时备降机场。通常选择飞行航线或计划降落机场附近的机场作为备降机场。', 416);
INSERT INTO `t_military_term_data` VALUES ('0b04ebd9-5bdc-4c27-9c04-a66ba5516e20', '06a75831-13a1-4660-870a-455bb445336a', '无线电集中台', '简称集中台。将多部无线电收发信设备分别集中配置的通信台。分为收信集中台和发信集中台。是大、中型无线电台通信的主要组织形式。', 79);
INSERT INTO `t_military_term_data` VALUES ('0b07384c-a6b6-47b7-bc11-7b3335cc865d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '方位圈', '亦称罗经圈。用以在海图上量测航向和方位的数学要素。通常用圆形刻盘图标表示,图标上方的五层指向为真北（0度）方位,图中还注有当地磁差和年变化率。', 286);
INSERT INTO `t_military_term_data` VALUES ('0b0ecdaf-8537-44f5-ac2b-62dad2a11699', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '后续任务', '进攻的军队应完成的第二步作战任务。通常由第二梯队或第三梯队遂行。主要是在完成当前任务基础上,继续向敌纵深发展进攻,或攻占某一地域（目标）,或消灭某一部分敌人。', 82);
INSERT INTO `t_military_term_data` VALUES ('0b17d54d-f416-45f0-a574-016be6aba91c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克集中射击地段', '防御战斗中给坦克分队规定的集中火力射击的地段。通常选在敌必经的地点和兵力密集的地区。', 50);
INSERT INTO `t_military_term_data` VALUES ('0b21d1f0-f611-4292-b190-bed4a2be7e76', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '调整勤务', '为保证行军纵队按规定的路线、序列和速度行进,防止拥挤、堵塞而进行的交通指挥与调理活动。由调整指挥所和调整哨实施。', 65);
INSERT INTO `t_military_term_data` VALUES ('0b244541-e24b-4dcc-8ce7-f948666eee28', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队政治工作', '中国共产党在中国人民解放军中的思想工作和组织工作。是实现中国共产党对军队的绝对领导、巩固和提高部队战斗力的根本保证,中国人民解放军的生命线。', 0);
INSERT INTO `t_military_term_data` VALUES ('0b31640d-466e-4d58-bfa5-ca4e12c29b6a', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '基础训练', '掌握军事基本知识、基本动作。基本技能的训练。是应用训练的前提。', 69);
INSERT INTO `t_military_term_data` VALUES ('0b35cb01-b5ad-41ea-938c-da039598bd62', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵敌后侦察', '炮兵侦察组在敌后方实施的侦察。用以查明敌纵深内重要目标的情况,指挥并校正射击。', 115);
INSERT INTO `t_military_term_data` VALUES ('0b3e1463-0469-4f57-a1ee-378b80b15d0b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '侦察经纬仪', '炮兵双筒潜望式侦察和测角用的光学仪器。主要用以测角、定向,侦察敌情、地形,测定目标坐标或炸点对目标的偏差量,也可用以测定炮阵地和观察所的坐标。', 280);
INSERT INTO `t_military_term_data` VALUES ('0b45f1b7-834a-4e6a-836c-9315b74bddd2', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '突破纵深', '部队在进攻正面上突贯敌人防御部署的深度。', 92);
INSERT INTO `t_military_term_data` VALUES ('0b506443-2f80-40b2-9c9a-0687319083f8', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '人防工程', '为保障人民防空指挥、通信及人员、物资掩蔽等需要而修建的工程。包括：各种人防指挥、通信设施,掩蔽工事,储存生产、生活资料的地下仓库和油库,工业企业的地下生产车间,地下交通设施,地下医院等。', 64);
INSERT INTO `t_military_term_data` VALUES ('0b5db86f-f7d6-4391-a663-6f55cf67d4ff', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮避开射击', '高炮连的炮瞄雷达和指挥仪瞄准飞机,高炮射向避开飞机,向相反方向或对称位置的假设点实施的射击。使用避开射击检查仪或双部雷达检查站观察射击结果。', 133);
INSERT INTO `t_military_term_data` VALUES ('0b5fb2af-804a-4ee8-9975-85c4085970c7', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高射炮', '简称高炮。主要用以射击空中目标的火炮。可射击中空、低空、超低空飞机及其他目标,必要时也可射击地面和水面目标。射界大（方向射界360度,高低射界可达-10度～+87度）,射速快,射击精度较高。', 40);
INSERT INTO `t_military_term_data` VALUES ('0b7f12e1-14dd-48a9-b92a-38697e0f4006', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '速浮', '亦称紧急浮起。潜艇在水下不经过半潜状态直接浮出水面的行动。主要是在水下严重丧失浮力,或产生危险纵倾、横倾,无法控制潜艇正常航行,且海面情况允许时使用。', 297);
INSERT INTO `t_military_term_data` VALUES ('0b932d15-b6c1-4fa7-ad35-e472fd0a33d8', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练经费', '专供军事训练使用的经费。通常包括标准包干计领经费和专项指标分配经费。', 188);
INSERT INTO `t_military_term_data` VALUES ('0b965971-e58e-4244-80e0-cda53ed53fc4', '97a19170-bfac-42c5-9906-1acb187f0654', '架次', '飞机或直升机出动数量的基本计算单位。以一架飞机或直升机出动一次为1架次。如四机编队出动两次即为8架次。', 55);
INSERT INTO `t_military_term_data` VALUES ('0babc783-578c-4d6a-9b29-69c13ee4a5e0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '游动炮', '在指定地域内执行游动射击任务的火炮。通常在防御时组织,由少量炮兵班或炮兵排担任。主要用以杀伤、迷惑、袭击和疲惫敌人,隐蔽己方炮兵的主要部署。', 48);
INSERT INTO `t_military_term_data` VALUES ('0bb11a4c-890d-497e-b8ce-cd1ec6402dce', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹阵地伪装', '为隐蔽导弹阵地而进行的伪装。主要措施有；保护阵地区域的自然环境,实施植被和迷彩伪装,设置遮障或假目标,构筑假阵地等。', 193);
INSERT INTO `t_military_term_data` VALUES ('0bb64a09-9254-4f13-8d62-98e88d870485', '916997ee-6728-4c61-9b79-d96960b1dc86', '沾染检查器材', '用以测量受染对象沾染程度的核辐射剂量探测器材。包括放射性沾染测量仪、辐射仪等。', 159);
INSERT INTO `t_military_term_data` VALUES ('0bc6ae67-1c11-441c-833a-beac960e56e2', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击效果指标', '衡量核毁伤效果的数量指标。通常用毁伤概率、相对毁伤面积、相对毁伤长度、可靠毁伤概率等来表示。', 149);
INSERT INTO `t_military_term_data` VALUES ('0bc90803-b6f3-4027-b569-99bea0fb779f', '97a19170-bfac-42c5-9906-1acb187f0654', '空地导弹', '从空中发射,用以攻击地面和水面目标的导弹。按用途,分为战略空地导弹和战术空地导弹；按飞行轨迹,分为弹道式空地导弹和飞航式空地导弹等。', 312);
INSERT INTO `t_military_term_data` VALUES ('0bc9f728-f8d9-44f1-9d74-a008997e6be7', '97a19170-bfac-42c5-9906-1acb187f0654', '伞降高度', '伞降时航空器至地面的垂直距离。主要根据作战需要和空降场的净空条件确定。', 167);
INSERT INTO `t_military_term_data` VALUES ('0be9b5cb-6c03-4cb6-95a9-9fd543631fe8', '916997ee-6728-4c61-9b79-d96960b1dc86', '侦毒包', '毒剂蒸气侦毒包的简称。用以发现空气染毒和查明毒剂种类的侦毒器材。可侦检沙林、梭曼、维埃克斯、芥子气、氢氰酸、氯化氰的蒸气和气溶胶。', 165);
INSERT INTO `t_military_term_data` VALUES ('0bea748a-937d-42cc-aac4-1bd07d4bb191', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '调整地区', '调整部队行进方向、顺序和速度的地区。通常选在部队行进中任务、方向转换或地形险要的地方。如重要桥梁、渡口、道路交叉口,大休息后继续行军的始点,宿营地域前的分进点等。有时把出发点也作为一个调整地区。', 66);
INSERT INTO `t_military_term_data` VALUES ('0c0972bb-b177-4c3d-b934-da50affc9d94', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力运用', '对各种火力的组织和使用。通常根据作战任务、武器性能、敌情和地形等情况确定。', 77);
INSERT INTO `t_military_term_data` VALUES ('0c1860fa-af00-480b-93fc-7a9477a7f9df', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '区域部署', '将兵力兵器分区域配置的作战部署。', 100);
INSERT INTO `t_military_term_data` VALUES ('0c1b196e-657e-457b-803a-83c1824d55f2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战役学', '研究战役及其指导规律的学科。是军事学术的重要组成部分,从属于战略学并指导战术学。主要研究内容有战役的本质、类型、特点、基本原则和组织实施方法等。', 24);
INSERT INTO `t_military_term_data` VALUES ('0c33ac50-d344-4a40-a011-ad9ae7273973', '916997ee-6728-4c61-9b79-d96960b1dc86', '战时核辐射限值', '亦称战时核辐射参考控制量。战时为合理保护战斗力而规定的辐射限值。是组织部队辐射防护的重要依据。主要包括：外照射限值；内照射限值,表面沾染限值,空气沾染限值,粮袜、水沾染限值等。', 106);
INSERT INTO `t_military_term_data` VALUES ('0c3c03f2-da5e-4591-b975-5eed1771f046', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军队建设', '组建军队和提高军队战斗力的各项工作的统称。包括军事工作、政治工作、后勤工作和技术工作等方面的内容。', 93);
INSERT INTO `t_military_term_data` VALUES ('0c4289a3-b5bd-4aeb-83e3-b2a7f0ca5f72', '916997ee-6728-4c61-9b79-d96960b1dc86', '核观测配系', '为获取核爆炸情况而配置的核观测报知系统。通常由3个以上核观测哨构成。分为野战核观测配系和要地核观测配系。主要负责：提供敌核袭击的时间、地点、威力和爆炸方式,估算核爆炸瞬时毁伤范围,预报放射性沾染情况等。', 9);
INSERT INTO `t_military_term_data` VALUES ('0c4e9ce9-d61a-495b-b31d-c94ce695a3c4', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '小威力核武器', '威力为 1千～1万吨梯恩梯当量的核武器。', 105);
INSERT INTO `t_military_term_data` VALUES ('0c61775d-373e-45bb-892c-8d8e640e0617', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '侧敌行军', '行进路线的侧方有敌情顾虑情况下的行军。须加强侧方警戒并作好可能遭敌袭击的准备。', 49);
INSERT INTO `t_military_term_data` VALUES ('0c63fd60-f2f5-4c00-a1cd-b7d9d949f756', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '悬崖', '陡壁上突出悬空的山崖。', 134);
INSERT INTO `t_military_term_data` VALUES ('0c83bc6e-b29c-43cf-8989-da4e84202550', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '了解任务', '亦称理解任务、对上级赋予的任务加以领会和理解、主要是明确上级意图,本级任务及其在作战全局中的地位、作用以及与友邻的关系等。', 64);
INSERT INTO `t_military_term_data` VALUES ('0c88fb83-b2a5-4f60-9cf0-52161444ce1b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '栈桥', '浮桥中通过桥础与河岸相连接的桥段。分为浮游栈桥和固定栈桥。', 278);
INSERT INTO `t_military_term_data` VALUES ('0c8aefda-6094-4b3b-b9f1-bcea0d97b73c', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '弹道下空中走廊', '按陆军航空兵与炮兵协同作战计划,在己方间瞄火炮弹道下面划出的供直升机飞行通过的空中通道。', 63);
INSERT INTO `t_military_term_data` VALUES ('0c9c1381-e5e0-4313-85f1-24d54e8a059f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '平洞核试验', '将核装置安装在坑道中实施核爆炸的封闭式地下核试验。通常利用地形开掘一条特殊设计的长坑道,将核装置与各种探测器放置其中,回填堵塞后实施核爆炸。', 185);
INSERT INTO `t_military_term_data` VALUES ('0c9c8555-e135-477a-8673-a76ef1306df9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '纵深作战', '在敌方或己方纵深区域内进行的作战。分为战略纵深作战、战役纵深作战和战术纵深作战。', 193);
INSERT INTO `t_military_term_data` VALUES ('0c9e0c12-01da-4bad-824a-fdba4527b489', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '氢弹', '亦称聚变弹或热核武器。利用核裂变装置爆炸的能量引发市、氖等轻元素原子核的自持聚变反应,瞬时释放出巨大能量,产生杀伤破坏效应的核武器。通常由引爆用的核裂变装置、热核装料（一般用固态氖化钾）、外壳等构成。氢弹的威力为几百到几千万吨梯恩梯当量。', 91);
INSERT INTO `t_military_term_data` VALUES ('0c9eb952-1cef-40f8-90cf-3ea90ac0dabd', '8a761efd-50a6-4ac8-9913-b7d745104f82', '头盔', '保护头部的帽式专门用具。由钢板或工程塑料制成、用以抵挡动能弹丸或破片,减少或避免对头部的损伤。', 192);
INSERT INTO `t_military_term_data` VALUES ('0ca04fc9-24a5-42fe-8cd8-360b97f5098b', 'd7132c58-5df3-4b97-919f-58740148b9ca', '远方观察哨', '高炮部队在距离阵地较远、敌机可能经常出现的方向上建立的对空观察哨。通常距高炮部队火网边沿40公里左右。任务是及时通报空中情况,使防空兵部队有较充分的直接准备时间。', 119);
INSERT INTO `t_military_term_data` VALUES ('0ca23dce-1592-4066-a83c-aa3bfb8f4318', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地图供应', '对军队遂行作战、训练和其他任务所需的地图进行调拨、分配、发放和前送的工作。', 294);
INSERT INTO `t_military_term_data` VALUES ('0cac3302-2994-4b08-9f35-a49684794574', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '编制军衔', '亦称职务军衔。对军队各级各类编制职务所规定的军衔等级。是授予和晋升军人军衔的重要依据之一。', 129);
INSERT INTO `t_military_term_data` VALUES ('0cad8e43-3850-432c-a80a-4aedc3706d68', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '合同战术训练', '合成军队的师、团为掌握合同战斗原则和方法而进行的训练。通常在完成兵种战术和专业战术训练的基础上进行。', 88);
INSERT INTO `t_military_term_data` VALUES ('0cb43440-a99f-4c19-ab6e-10dbe7b7edb5', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '梅雨', '初夏梅熟时节,出现在中国江淮流域至日本南部一带,持续时间较长的阴沉多雨天气。一般在6月上、中旬开始,称为入梅；7月上、中旬结束,称为出梅。入梅、出梅时间各年不同,梅雨期长短很不一致,长的可达1个多月,短的只有几天,少数年份不出现梅雨,称为空梅。', 53);
INSERT INTO `t_military_term_data` VALUES ('0cb83ebf-1164-499a-8277-c99d4f95db9c', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练规划', '关于军事训练工作的较为全面、长远的发展计划。', 26);
INSERT INTO `t_military_term_data` VALUES ('0cd26c75-2c30-4a57-95d5-22fd2ac35f3c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '反坦克炮兵', '以反坦克火炮和反坦克导弹为基本装备,主要用以毁伤敌坦克等装甲目标的炮兵。', 2);
INSERT INTO `t_military_term_data` VALUES ('0cd8e824-773a-4685-b064-186251ad3a3e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵作战指挥', '炮兵指挥员及其指挥机关对所属部队或分队作战行动的组织领导活动。分为集中指挥、分散指挥,逐级指挥、越级指挥、交替指挥等。', 83);
INSERT INTO `t_military_term_data` VALUES ('0cf1be50-842a-4c2b-b8e0-950534e6076d', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '微型计算机', '亦称微电脑。把中央处理器、存储器和输入、输出接口电路等集成为一片或几片大规模集成电路所构成的电子计算机。有台式、便携式,膝上型、笔记本型等。军事上有广泛用途。', 53);
INSERT INTO `t_military_term_data` VALUES ('0cfbf989-de6e-462a-8c37-1b2601126601', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航路指南', '记述海区和港口情况,用以指导舰船安全航行的航海图书。主要内容包括海区概况、海区水文气象、顺岸分段航海资料等。', 282);
INSERT INTO `t_military_term_data` VALUES ('0cfc1260-c574-4734-9987-4c6d46ce7750', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克最大侧倾行驶坡度', '坦克在战斗全重状态下,对规定坡道能安全侧倾行驶的最大横向坡度。坦克最大侧倾行驶坡度一般为30度。', 164);
INSERT INTO `t_military_term_data` VALUES ('0cfd3ac9-8fef-4022-b741-81fdf39cdd4d', '06a75831-13a1-4660-870a-455bb445336a', '载波机务站', '简称载波站。为有线电多路通信提供电路的通信站。主要设备有载波电话终端机和载波电报机。包括终端站和中间站。终端站设置在线路两端,可在一条通信线路上开通多个通信电路；中间站用于接转电路,有的还可分出部分电路。', 88);
INSERT INTO `t_military_term_data` VALUES ('0cfe74a3-029c-44a0-8d99-91613a22c7f5', '916997ee-6728-4c61-9b79-d96960b1dc86', '烟幕保障计划', '为干扰、迷盲敌人,隐蔽己方行动或重要目标而拟制的使用烟幕的计划。主要包括；烟幕保障的任务、时机、方式,施放的地区和持续时间,使用的兵力和发烟装备,以及情况变化时采取的措施等。', 18);
INSERT INTO `t_military_term_data` VALUES ('0d00b27e-d446-48c2-bc82-68db2568425d', '97a19170-bfac-42c5-9906-1acb187f0654', '空中多批多路截击', '多批歼击机同时或连续对多个航路来袭的多批空中目标进行的空中截击。', 72);
INSERT INTO `t_military_term_data` VALUES ('0d00c363-f683-41de-a978-d1458362ab67', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气压', '大气压强的简称。单位面积上承受的空气分子运动所产生的压力。某高度上的气压等于该高度单位横截面积上所承受的垂直空气柱的重量。气压随高度的增加而降低。气象上使用的气压计量单位是百（hPa）。', 13);
INSERT INTO `t_military_term_data` VALUES ('0d0af14e-2356-4315-8f1a-72c1513177cc', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役协同', '参加战役作战的各军兵种或各部队按照统一计划进行的协调配合。通常以执行主要作战任务的军兵种或部队为主,按照任务、时间、空间组织。', 44);
INSERT INTO `t_military_term_data` VALUES ('0d230e3e-01c4-4254-91c4-f6106f80505d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '攻坚爆破', '攻坚战斗中对敌障碍物、火力点和其他工程设施实施的爆破。分为强行爆破和隐蔽爆破。', 247);
INSERT INTO `t_military_term_data` VALUES ('0d299694-7457-4db6-a41e-074397ed15b6', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '牵制集团', '战役中担负牵制任务的兵力集团。主要以积极的作战行动吸引和拖住当面之敌,保障主要方向突击集团的作战。', 80);
INSERT INTO `t_military_term_data` VALUES ('0d34394b-6343-484d-95e2-5dfaf7f35b1a', '97a19170-bfac-42c5-9906-1acb187f0654', '无人驾驶飞机', '由无线电遥控设备或飞行程序控制装置操纵的不载人的飞机。主要用于侦察、预警、科研、电子干扰、探测高空核试验情况及充当靶机等。', 273);
INSERT INTO `t_military_term_data` VALUES ('0d3703d3-f742-4ef8-88a4-2abc7ae4f8c5', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '平暴', '国家依法以武装力量平息暴乱的措施与行动。', 433);
INSERT INTO `t_military_term_data` VALUES ('0d3f8be8-8c30-47c2-8259-42373de3f8b8', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '冰川', '分布在极地和高山地区,能自行运动并长期存在的巨大天然冰体。分为大陆冰盖和山岳冰川。冰川运动,可形成冰斗、冰川谷、终碛垄、冰水阶地等特殊的地貌形态。是重要的淡水资源,但山岳冰川在消融时也可造成冰川泥石流,破坏交通,淹没农田等。', 78);
INSERT INTO `t_military_term_data` VALUES ('0d525aca-d1cf-4140-b894-54b6eb692d4e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '筑城障碍物', '由改造后的地形、构筑物、结构物等构成的非爆炸性障碍物。包括铁丝障碍物、土工障碍物、桩谷类障碍物、拦障类障碍物、冰雪障碍物、水障碍物、浮游栅网类障碍物、鹿砦、刺钉、竹签桩等。', 107);
INSERT INTO `t_military_term_data` VALUES ('0d60686d-eb2c-43e5-8f91-3f3080c98742', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察工作图', '标绘有组织实施侦察情况的图。主要标记侦察部署和获取的敌情。供指挥侦察活动、研究和报告情况使用。', 107);
INSERT INTO `t_military_term_data` VALUES ('0d6d3b2b-face-4f64-a4b5-d9d8cea0f100', '97a19170-bfac-42c5-9906-1acb187f0654', '中空飞行', '航空器在真实高度为 1000～7000米（含）的飞行。', 232);
INSERT INTO `t_military_term_data` VALUES ('0d6d4e72-cad9-4692-9213-4c3c3a26ee86', '97a19170-bfac-42c5-9906-1acb187f0654', '战略轰炸', '为达成一定的战略目的而对敌方战略目标进行的轰炸。', 92);
INSERT INTO `t_military_term_data` VALUES ('0d76b895-3ac0-4f03-b574-212a728f121c', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '区域军事地理', '世界或国家的某一战略性区域的军事地理。', 1);
INSERT INTO `t_military_term_data` VALUES ('0d7c9e5d-d73b-4c20-8172-c8db183c1b4d', '878651de-adf5-4c72-9376-9c363b893ff8', '战争初期', '从战争爆发到完成第一步战略任务的一段时间。是国家由平时转入战时的一个转折时期,对战争的进程和结局有重要影响。', 45);
INSERT INTO `t_military_term_data` VALUES ('0d8635b8-f773-45fe-bc2f-3a5b9e28069d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '河漫滩', '河床和河谷坡之间,在洪水期被淹没。平水期露出的河滩。表面平坦,下部为砾石、粗砂等河床冲积物,上部为细沙、粘土等洪水泛滥的堆积物。特别宽阔的河漫滩一般称为泛滥平原或河漫滩平原。', 65);
INSERT INTO `t_military_term_data` VALUES ('0d8746c3-5a24-48b1-8bb4-50ed0487aed4', '916997ee-6728-4c61-9b79-d96960b1dc86', '累积剂量', '人体或其他生物机体在各种电离辐射的一次或多次照射下受到的总剂量。单位是库仑／千克或戈瑞。对累积剂量须建立剂量卡片,并注明时间,如人员在一年中或一生中的累积剂量等。', 105);
INSERT INTO `t_military_term_data` VALUES ('0da266ac-dc21-43bf-8ec9-cf7c7d7d0928', '878651de-adf5-4c72-9376-9c363b893ff8', '现代战争', '现代社会发生的并能反映出现代生产方式和科技水平的战争。由于受现代政治、经济、军事、科技、文化等因素的影响,它与古代战争、近代战争相比,具有许多新的特点。', 13);
INSERT INTO `t_military_term_data` VALUES ('0da99345-a9b4-40fc-b150-0b5783d18c8f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '自导水雷', '亦称自动跟踪水雷或鱼水雷。能自动搜索、跟踪、攻击目标的水雷。是自导鱼雷和锚雷的结合体。兼有水雷的长期威胁作用和鱼雷的主动攻击能力。', 216);
INSERT INTO `t_military_term_data` VALUES ('0db9bdbf-6ca5-4c2c-a2fe-4cbd1bc305a8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '活动目标侦察校射雷达', '简称活动目标侦察雷达。炮兵用以侦察测定地面、水面活动目标坐标和测定己方射弹炸点坐标的雷达。', 300);
INSERT INTO `t_military_term_data` VALUES ('0dc017a8-82b1-43f1-b12a-f09f60428186', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '轨道确定', '利用测量数据确定航天器轨道的过程。其步骤分为数据获取与预处理、初轨确定、轨道改进等。轨道确定通常由航天控制中心完成。', 234);
INSERT INTO `t_military_term_data` VALUES ('0dce2ebc-53df-418b-a2bf-20db3a849829', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '地图注记式作战命令', '以地图注记的形式下达的作战命令。', 127);
INSERT INTO `t_military_term_data` VALUES ('0dce519c-aa61-4e8f-84e8-2d0fdaa958f4', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '损坏率', '一定时间内武器装备的损坏数与实有数的比值。通常用百分比表示。', 113);
INSERT INTO `t_military_term_data` VALUES ('0dd5b3ec-1759-4449-b448-bd7960ea044d', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗态势', '在一定战场环境的某时间段内,己方配置的电子对抗兵力兵器和敌方配置的电子设备之间以及采取的电子对抗行动所形成的状态与形势。', 9);
INSERT INTO `t_military_term_data` VALUES ('0df0b27b-132c-472c-a7b3-b38a5affe5cf', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '晋级', '按照军队职务编制和需要,根据军人德才表现、工作实绩、对革命事业的贡献和服役经历、对其职务等级、专业技术等级、文职干部级别或行政等级的晋升。', 87);
INSERT INTO `t_military_term_data` VALUES ('0e270e3c-2c22-4329-8b23-00c7d5aeaee6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地球', '人类居住的星球。太阳系九大行星之一。其内部由地核、地幄和地壳构成,外部有水圈、大气圈和磁层环绕。其表面陆地面积约占29％,海洋面积约占71％。是个略扁的旋转椭球体,赤道半径6378公里,极半径6357公里,扁率为1／298.257。由西向东自转,同时绕太阳公转,自转周期为23小时56分4秒平太阳时,公转周期为365.2564平太阳日。', 196);
INSERT INTO `t_military_term_data` VALUES ('0e32313d-3771-47ed-adf9-4c4f767329b2', '97a19170-bfac-42c5-9906-1acb187f0654', '停机坪', '专门为停放和维护飞机或直升机以及进行地面飞行准备而设置的场地。按停放飞机的数量,分为集体停机坪和个体停机坪；按位置和用途,分为起飞线停机坪,停机线停机坪和警戒停机坪。', 427);
INSERT INTO `t_military_term_data` VALUES ('0e34b837-f8b9-4d75-9435-4f9e6fb69c64', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵测地勤务', '炮兵测地分队进行的对目标的坐标、方位、高程的测量和资料处理的勤务。目的是保障炮兵准确射击和实施统一射击指挥。主要任务是：测定炮阵地、观察所、声测哨、雷达站的坐标和高程,赋予火炮和观测器材的基准射向,建立和加密炮兵控制网等。', 118);
INSERT INTO `t_military_term_data` VALUES ('0e41f18e-834c-489e-8b27-e2f3e6ec9420', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹射界', '导弹不变动发射位置所能射击到的范围。主要由导弹性能和地形因素决定。', 178);
INSERT INTO `t_military_term_data` VALUES ('0e51097b-1189-46b0-b2f7-e150b56cc258', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '飞行甲板', '航空母舰上供舰载机起飞和着舰用的甲板。', 161);
INSERT INTO `t_military_term_data` VALUES ('0e51e57e-01aa-44e1-bd45-bc4378076264', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '战时编制', '军队在战争时期的编制。根据战争的需要及人力、物力、财力的可能制定和采用。一般要求齐装满员,并可在平时编制基础上扩编。', 62);
INSERT INTO `t_military_term_data` VALUES ('0e5a105f-ddde-42ec-b5bd-a06b65f31225', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物战剂施放方式', '使生物战剂发挥杀伤作用的方式。包括布洒气溶胶、散布生物战剂媒介、污染水源和食物等。', 30);
INSERT INTO `t_military_term_data` VALUES ('0e6e4483-a17a-464b-b215-81c28cf885c5', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '天文点', '用天文观测的方法测定了经度和纬度的地面点。按测量精度,分为一、二、三、四等。', 216);
INSERT INTO `t_military_term_data` VALUES ('0e7cbf8e-8f3e-4f8e-b1e2-0c674d137c2b', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机补给场', '为直升机再次出动补充、供给油料、弹药和为飞行人员供应饮食的场地。', 100);
INSERT INTO `t_military_term_data` VALUES ('0e8a94d7-0770-419f-94c4-ef90fed3f043', '8a761efd-50a6-4ac8-9913-b7d745104f82', '发射线', '亦称掷线。射弹飞离火身口瞬间的质心速度的方向线。没有起始扰动时,此方向线即为射弹飞离火身口瞬间的火身轴线的延长线。', 24);
INSERT INTO `t_military_term_data` VALUES ('0e8dd972-2c53-4075-9921-f8bc492df33c', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军长径', '行军纵队先头至后尾的长度。根据行军兵力、方式、敌情和道路等决定。', 60);
INSERT INTO `t_military_term_data` VALUES ('0e916f90-4205-4e51-81c8-f6d2a75ae0e2', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '无线电制导', '简称无线制导。利用无线电波获得导引信息进行的制导。分为无线电指令制导、无线电波束制导和无线电寻的制导。', 45);
INSERT INTO `t_military_term_data` VALUES ('0eb80131-38b6-4cb2-befe-32953ab51202', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '集团作业', '受训人员充当同一职务,按照统一的想定集体研练组织指挥的作业。', 101);
INSERT INTO `t_military_term_data` VALUES ('0ebf05c6-44ad-46da-8443-16a9b5074f37', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '纬线', '亦称纬度圈。地球表面与赤道平行的小圆。同一纬度圈上各点的纬度相同。纬线是准确的东西方向线。', 203);
INSERT INTO `t_military_term_data` VALUES ('0ecdf322-05da-4dce-b199-ab469554b7f3', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆乘员', '装甲车辆编配的操作人员。一般包括驾驶员、副驾驶员、枪炮手等。', 3);
INSERT INTO `t_military_term_data` VALUES ('0ecf7271-6bda-47d1-985d-4ceb9d1974c4', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '火药', '能在绝氧条件下进行迅速而有规律的燃烧,并释放出大量热能和气体的物质。分为均质火药（如单基火药和双基火药）和异质火药（如黑火药）。主要用作引燃药或发射药。', 204);
INSERT INTO `t_military_term_data` VALUES ('0ed603d9-5b35-4283-851c-0bcbe1a71cdf', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练法规', '军事训练方面的规章制度的统称。主要包括军事训练的各种条令、条例、大纲、教令以及有关的规定、制度等。通常由军队或军兵种最高领导机关统一制定、颁发。', 16);
INSERT INTO `t_military_term_data` VALUES ('0ed682d4-b0d6-4326-953d-4553162f382c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹多弹头', '装有两个以上子弹头的导弹弹头。分为集束式多弹头、分导式多弹头、全导式多弹头和机动式多弹头等。通常由母弹头、子弹头和释放机构等构成。', 24);
INSERT INTO `t_military_term_data` VALUES ('0ed96800-6014-48cb-b16d-7e404df1e758', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '地面电子对抗侦察站', '电子对抗部队或分队在地面遂行电子对抗侦察任务的机构。主要有雷达对抗侦察站和通信对抗侦察站。', 33);
INSERT INTO `t_military_term_data` VALUES ('0ee08f48-6655-416f-8cd6-5a9f1659a9e1', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵交替转移', '两个以上的防空兵分队以相互交错实施的方法进行的转移。', 86);
INSERT INTO `t_military_term_data` VALUES ('0ee28cc3-6798-4caf-a31d-d9011cf95bd5', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '海军情报', '海军作战所需的情报。主要来源于海军所属的专业侦察力量获取的情况,还来源于上级、作战舰艇部队、其他军兵种以及地方有关部门、海上民兵、沿海人民群众等提供的情况。', 131);
INSERT INTO `t_military_term_data` VALUES ('0ee6b961-edc5-474c-a4f9-6e18f6930644', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '水障碍物', '简称水障。利用液态水体或水的泛滥地区及泥泞地段形成的障碍物的统称。', 110);
INSERT INTO `t_military_term_data` VALUES ('0ef144c0-1b7e-496f-be65-ab649b19992d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '爆破装药', '亦称炸药包,简称药包。具有一定结构、形状,能直接用于爆破的定量炸药。分为集团装药、直列装药、聚能装药、扁平装药、环形装药和可塑型装药。', 223);
INSERT INTO `t_military_term_data` VALUES ('0ef159db-3105-497d-9cd4-2a13fe0b6e62', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '协同作战演习', '军兵种之间、部队或分队之间为提高作战中的协调配合能力而进行的军事演习。', 125);
INSERT INTO `t_military_term_data` VALUES ('0ef26e69-045a-4ecf-9cce-f03d7863c21b', '97a19170-bfac-42c5-9906-1acb187f0654', '垂直起落飞机', '能垂直于起落场坪起飞并可垂直降落的飞机。', 271);
INSERT INTO `t_military_term_data` VALUES ('0ef87612-4e47-4e26-b602-e529431ea39b', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '内务卫生', '军队日常生活中内务设置和卫生事宜的统称。主要包括：整齐有序地放置装备和个人物品,保持室内外环境卫生和个人整洁卫生等。', 42);
INSERT INTO `t_military_term_data` VALUES ('0f000ed3-766c-4f73-9890-a6f42c853947', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '法制教育', '宣传和学习法律法规为主要内容的教育。', 100);
INSERT INTO `t_military_term_data` VALUES ('0f01de40-cb9f-447b-aa66-1be0847a5958', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '兵力密度', '作战正面的单位宽度内设人兵力兵器的数量。分为战役密度和战术密度。', 155);
INSERT INTO `t_military_term_data` VALUES ('0f251f0a-5975-4d06-b074-63c1a76d8f99', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行航线', '航空器预定的或实际的飞行路线。预定的飞行航线通常标在航空地图上,标有起点、检查点、转弯点和终点。', 235);
INSERT INTO `t_military_term_data` VALUES ('0f25aa36-a3a8-4498-b491-1c5c212e3dd3', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役迂回', '战役中以一部兵力或以主力向敌战役部署翼侧和后方实施的机动作战行动。', 112);
INSERT INTO `t_military_term_data` VALUES ('0f2b0b02-af07-42e7-aa37-1061b70f243b', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '军事情报', '简称情报。对获取的军事斗争所需的情况进行分析判断的成果。是筹划和指导战争及指挥作战的重要依据。按使用范围,分为战略情报、战役情报和战术情报；按军兵种,分为陆军情报、海军情报、空军情报和战略导弹部队情报。', 125);
INSERT INTO `t_military_term_data` VALUES ('0f2de134-3589-4484-ab7d-9f9098c50112', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '原子弹', '亦称裂变弹或裂变武器。利用铀或钚等易裂变重原子核的链式裂变反应,在瞬时释放巨大能量产生杀伤破坏效应的核武器。按结构设计,分为枪法原子弹、内爆法原子弹和助爆型原子弹；按核装料,分为铀弹和钚弹。原子弹的威力通常为几百到几万吨梯恩梯当量。', 84);
INSERT INTO `t_military_term_data` VALUES ('0f3a0e40-a309-4c40-b717-4d3b5304ba9c', '97a19170-bfac-42c5-9906-1acb187f0654', '军用运输机', '专门用于空中输送人员、武器装备和物资的军用飞机。', 287);
INSERT INTO `t_military_term_data` VALUES ('0f3a3c22-7c03-4817-b27c-a9a29aac7aa5', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '水下核爆炸', '爆心在水面以下的核爆炸。通常按是否可观察到火球,分为浅水核爆炸和深水核爆炸。水下核爆炸弓愧的巨大水下涡流可导致水下控测设备在一段时间内失效,并在一定范围内的水域造成严重的放射性沾染。主要用以破坏水面和水下的舰艇、水下建筑、水下障碍物和水中设施等。', 154);
INSERT INTO `t_military_term_data` VALUES ('0f3c4c68-71e7-49d0-b7f0-4cc5e39c2ad9', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军车检查站', '军队在公路线上设置的监督、检查军用车辆和驾驶人员的临时机构。分为固定军车检查站和流动军车检查站。用以检查军用车辆的技术状态和车容、乘载、用车凭证、驾驶员的驾驶作风和军容风纪等情况。发现问题有权按规定作相应处理。', 64);
INSERT INTO `t_military_term_data` VALUES ('0f607c43-1043-494b-8138-7749efead9ef', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹运输装填车', '用以运送、装填、退卸地空导弹的专用车辆。', 38);
INSERT INTO `t_military_term_data` VALUES ('0f63e2e5-07bd-4da6-97d1-c3b12ae6d362', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵区分', '为明确任务和指挥关系而将建制内的和加强的防空兵部队、分队进行统一的分配。主要根据敌情、任务确定。', 11);
INSERT INTO `t_military_term_data` VALUES ('0f7d9a55-7a28-4e42-b368-49c43ae53159', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵气象探测器材', '炮兵用以探测地面和高空气象的器材。主要包括地面气象观测仪表和高空气象探测器材。', 289);
INSERT INTO `t_military_term_data` VALUES ('0f8998da-1a20-4e40-96e8-65be43e25f6b', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '陆军', '以步兵、装甲兵、炮兵为主体,主要在陆地遂行作战任务的军种。通常由步兵、装甲兵、炮兵、陆军航空兵、工程兵、通信兵、防化兵等兵种和各种专业勤务部队组成。可单独作战,或与其他军种协同作战。', 35);
INSERT INTO `t_military_term_data` VALUES ('0f8d45c5-1752-4ca2-9615-b5c2578ea81a', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '战场管理', '为维护战场秩序而对参战部队和分队进行的管理、主要包括执行战场纪律,组织警戒勤务和交通调整勤务构筑工事,进行伪装和疏散隐蔽以及对阵地生活的管理等。', 108);
INSERT INTO `t_military_term_data` VALUES ('0f98c807-4ee0-4d07-8c75-459ffb1cc181', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击故障', '武器在射击过程中出现的不能正常发挥射击功能的各种现象。如膛炸、炸壳、卡壳、卡弹、滑机等。', 126);
INSERT INTO `t_military_term_data` VALUES ('0fa9a899-ebaa-428b-8b36-e0b432d8e869', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国民经济动员', '国家根据战争需要,将国民经济的各个组成部分由平时状态转为战时状态的紧急措施。其目的是使工业、农业、交通运输、邮电通信、医疗卫生等国民经济部门迅速按战时要求运行,以便集中控制和调动国家的财力、物力,保障战争需求。', 52);
INSERT INTO `t_military_term_data` VALUES ('0fb1037f-cde9-47d3-8667-12d6a76150c7', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '运动保障队', '作战中以工兵分队为主编成的,随伴部队保障其沿行进路线机动的战斗编组。主要任务是：侦察和排除行进路线上的障碍物,抢修道路、桥梁,构筑急造军路,在受染地域开辟通路或构筑迂回路等。', 20);
INSERT INTO `t_military_term_data` VALUES ('0fbcb211-698c-4cea-b78d-84d13bc8f04c', '8a761efd-50a6-4ac8-9913-b7d745104f82', '密位公式', '反映角度（密位）、间隔、距离二者关系的近似公式。即：间隔＝距离X密位（除以）1000距离＝隔隔X1000(除以）密位密位＝间隔X1000（除以）距离', 83);
INSERT INTO `t_military_term_data` VALUES ('0fd27961-e17d-454d-9b1e-067019b9d66e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '水源侦察', '在作战地域为寻找水源、收集与水源有关的资料而实施的侦察。主要查明：水源位置、性质数量、出水量、水质及其受染情况,开采和利用水源所需的器材,开采工程量以及有关地形、敌情等。', 360);
INSERT INTO `t_military_term_data` VALUES ('0fd73baf-8cb8-460f-9851-4ff2802452ca', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸装置', '简称核装置。依靠核装料内原子核的裂变或聚变反应,瞬时释放巨大能量并产生核爆炸的装置、通常由核部件、炸药部件、人工品、核点火部件和相应结构件构成。是核武器的核心部分。', 123);
INSERT INTO `t_military_term_data` VALUES ('0ff0a14a-f644-497b-bce1-7e2119b7a656', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '盆地', '陆地上四周高、中间低的盆状地区。周围由山地或高原围绕,中间是平原或丘陵地、洼地。按地理位置和地形特征,分为内陆盆地、外流盆地和山间盆地等。', 28);
INSERT INTO `t_military_term_data` VALUES ('0ff14f6d-feec-4f68-bb88-abc713d0a1a5', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战阶段', '按照作战进程中的任务要求或行动性质对作战全过程所划分的段落。', 175);
INSERT INTO `t_military_term_data` VALUES ('101080da-bfdf-4d1d-bbb4-cb79cf3e9252', '97a19170-bfac-42c5-9906-1acb187f0654', '航路导航', '保障飞机或直升机沿常用航线、航路和空中走廊飞行的导航。主要利用沿航路各机场的导航设备以及专设的导航点组织实施。', 359);
INSERT INTO `t_military_term_data` VALUES ('1026a7ea-d7e9-43b0-a3b4-ed4e8bd82bda', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克行进间射击', '坦克在运动中进行的射击。射击准备、瞄准发射和射击修正均在运动中完成。', 54);
INSERT INTO `t_military_term_data` VALUES ('104122c8-8f39-4702-aeb8-0de3764f0f7d', '916997ee-6728-4c61-9b79-d96960b1dc86', '路易氏气', '学名氯乙烯二氯胂。糜烂性毒剂的一种。通常以液滴杀伤为主,也能形成蒸气、气溶胶状态使空气染毒。皮肤接触后,潜伏期较短,很快出现灼痛感等中毒症状。', 217);
INSERT INTO `t_military_term_data` VALUES ('104e62e1-f30c-414f-b787-1196e024f75e', '97a19170-bfac-42c5-9906-1acb187f0654', '侦察机', '装有航空侦察设备,专门遂行空中侦察任务的作战飞机。分为战略侦察机和战术侦察机。', 285);
INSERT INTO `t_military_term_data` VALUES ('10539687-896a-407a-b802-8b35eb03b477', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海图作业', '在航行海图上为选择舰艇航线和记录航迹而进行的量测、绘算和标注等工作。分为预先海图作业、航行海图作业、总结海图作业等。', 274);
INSERT INTO `t_military_term_data` VALUES ('1058006b-b1ae-40b8-a2a9-b856f4910e10', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '草原', '生长草本植物或间有灌木的广阔平坦地区。军事上便于大兵团和机械化部队快速机动,视界和射界开阔,但判定方位、指示目标、隐蔽伪装以及对核、化学、生物武器袭击的防护较为困难。', 88);
INSERT INTO `t_military_term_data` VALUES ('105ccf65-cb45-4b7e-a3db-d03c1a1a8f04', '916997ee-6728-4c61-9b79-d96960b1dc86', '照射量', ' X光或γ射线对单位质量空气电离程度的度量。常用以计算人员对辐射的吸收剂量。单位是库仑／千克。', 96);
INSERT INTO `t_military_term_data` VALUES ('105e848a-dd06-4a07-b996-afa55675505e', '97a19170-bfac-42c5-9906-1acb187f0654', '空中突击', '亦称航空兵突击。航空兵部队从空中对地面或水面目标进行急促而猛烈的攻击。包括轰炸、强击等。分为集中突击、连续突击、同时突击和随机突击等。', 100);
INSERT INTO `t_military_term_data` VALUES ('1066f8da-98c8-4640-bc59-647f4d6e4c0f', '06a75831-13a1-4660-870a-455bb445336a', '长途台', '接转长途电话的通信站。主要设备为长途接线台。可多台并用,以扩大容量。', 86);
INSERT INTO `t_military_term_data` VALUES ('107115f3-3e40-4a83-a6fd-ad8edd40d800', 'f0140091-c11a-48c9-8836-8aa94439dac0', '退出战斗', '亦称撤出战斗。进行战斗的部队与敌人脱离交战或脱离接触的行动。通常在达到预定目的或战场情况不利于继续战斗、需要转移兵力、调整部署等情况下,根据上级命令组织实施。退出战斗时,应组织必要的掩护。', 75);
INSERT INTO `t_military_term_data` VALUES ('1072ae83-fa4a-4878-9792-b8e16155808e', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行员', '驾驶航空器的飞行人员。', 16);
INSERT INTO `t_military_term_data` VALUES ('108319c2-a36c-4723-94aa-662b0b092c45', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵发射法', '火炮、火箭炮按规定的时间间隔、发射程序发射炮弹的各种方法的统称。主要有急促射、等速射、齐射、单发射等。应根据目标性质、射击目的和战术任务等灵活运用。', 223);
INSERT INTO `t_military_term_data` VALUES ('108422b5-cc7a-47d6-adec-fdc803789a71', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '分水线', '山脊或山背上的棱线。降水沿分水线两侧流向不同的方向。反映在地形图上则是山脊或山背各等高线凸出部分顶点的连线。在平原地区,分水线不明显,需通过测量和实地调查方能确定。', 127);
INSERT INTO `t_military_term_data` VALUES ('108bdb90-b4bb-4478-abda-374b8a0d6e66', '8a761efd-50a6-4ac8-9913-b7d745104f82', '直射距离', '轻武器和直瞄火炮在标准气象条件下,最大弹道高等于该武器所能射击的典型目标高度时,弹丸飞行的最大水平距离。距离的远近因武器种类、弹药类别、目标高度不同而异。', 57);
INSERT INTO `t_military_term_data` VALUES ('108dd0b3-1479-4a1d-91d8-da96bce6f125', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '人民防空', '简称人防。国家根据国防需要,动员和组织人民群众采取防护措施,以防范和减轻空袭危害的活动。是国防的组成部分。中华人民共和国的人民防空,实行长期准备、重点建设、平战结合的方针,贯彻与经济建设协调发展、与城市建设相结合的原则。', 61);
INSERT INTO `t_military_term_data` VALUES ('109300a1-ce6e-43f3-a241-80a90952f820', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '警报', '报知或解除紧急、危险情况的信号。按情况发生过程,分为预先警报、紧急警报和解除警报：按警报内容,分为战斗警报、空袭警报等。通常由指挥员根据上级命令或实际情况决定发出。', 35);
INSERT INTO `t_military_term_data` VALUES ('10942abb-2dcc-46a1-9a03-71b16e3a1583', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军事机关', '①国家中专门负责军事工作的各类各级领导机构。相对于地方工作机关而言。②军队中负责军事指挥与组织领导工作的机构。相对于政治机关、后勤机关等而言。如总参谋部、各级司令部。', 1);
INSERT INTO `t_military_term_data` VALUES ('109d3198-6508-4673-b245-98fc04069a26', '98df76fb-4b65-48ff-a56c-4db587327c79', '附油', '军队中除主油之外保障各种机械正常工作的油料的统称。如润滑油、润滑脂、特种液和洗涤油等。', 167);
INSERT INTO `t_military_term_data` VALUES ('10a7db29-7420-481f-8204-80620a36a0da', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇上浮', '潜艇由水下状态转为水面状态或由大深度转为小深度的行动。分为正常上浮和速浮。可在停止或行进间进行。', 295);
INSERT INTO `t_military_term_data` VALUES ('10b62448-4df8-4b22-963e-62f4754342e9', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '中等威力核武器', '威力为1万～10万吨梯恩梯当量的核武器。', 104);
INSERT INTO `t_military_term_data` VALUES ('10b8861a-4556-446e-b85c-e53b12680103', '916997ee-6728-4c61-9b79-d96960b1dc86', '核战场环境', '核袭击造成的战场情况与条件。通常指核袭击造成的人员大量伤亡,武器装备、设施、交通、通信等严重破坏以及大面积放射性沾染等状况。', 32);
INSERT INTO `t_military_term_data` VALUES ('10c16224-3598-45e3-bc34-49aa906b5cad', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥组', '亦称指挥小组。上级为加强某一单位或方向的指挥而派出的精干的指挥机构、有时也指军兵种部队派往合成军队指挥所协助指挥的指挥机构。', 53);
INSERT INTO `t_military_term_data` VALUES ('10cd470c-e0ad-4957-959c-db1fd510fb57', '916997ee-6728-4c61-9b79-d96960b1dc86', '放射性活度测量', '对核辐射发射体放射性活度的测量。主要用以确定人体、武器装备等物体的表面沾染水平,空气、水等的沾染浓度,粮食、蔬菜等的沾染比活度。', 91);
INSERT INTO `t_military_term_data` VALUES ('10d747df-3190-4c70-a5b1-3444cfe7f239', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '命令', '军队首长或领导机关对所属部队机关下达规定性任务或公布重要决定的军用文书、通常用以传达有关作战、训练等任务,颁发条令、条例,调动部队人员、装备任免干部,授予荣誉称号变更编制、体制等。', 121);
INSERT INTO `t_military_term_data` VALUES ('10dc06be-5970-4512-9ad4-c5fba807ba08', '98df76fb-4b65-48ff-a56c-4db587327c79', '转运', '在军事运输途中,人员或物资转换运输工具继续实施的运输。', 266);
INSERT INTO `t_military_term_data` VALUES ('10de8a8e-a8b6-4398-ab08-9e4bf1eb5693', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行安全', '训练飞行和任务飞行过程中没有发生航空器损坏和人员伤亡的情况。', 250);
INSERT INTO `t_military_term_data` VALUES ('10def615-1944-47a8-a1e9-51ee309e5ff7', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象通信', '收集、传输、交换和分发各种气象情报的专业通信。主要任务是收集、传输、交换和分发气象保障所需的天气实况、天气预报、危险天气警报与通报,以及其他气象情报、资料等。特殊情况下须实行保密通信。', 67);
INSERT INTO `t_military_term_data` VALUES ('10e41a04-da3a-4384-8925-581a3d1e3903', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役预备队', '战役编成中,指挥员直接掌握的用于执行机动作战任务的兵力集团。是战役部署的重要组成部分。通常由具有较强机动力、突击力和快速反应能力的团以上部队编成。', 43);
INSERT INTO `t_military_term_data` VALUES ('10f1aadf-5cd4-431e-a6f6-7fdcf29052aa', '97a19170-bfac-42c5-9906-1acb187f0654', '全天候飞行员', '亦称四种气象飞行员。在昼间的简单、复杂气象和夜间的简单、复杂气象4种气象条件下均能遂行飞行任务的飞行员。', 17);
INSERT INTO `t_military_term_data` VALUES ('1105b90d-583c-476c-bb99-b4c2da012129', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '官兵互教', '官兵之间互教互学的训练活动、是中国人民解放军的传统练兵方法之一。', 161);
INSERT INTO `t_military_term_data` VALUES ('110765a5-770a-4285-a231-04d1bc6030a1', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵配置', '防空兵部队为实施战斗而将兵力、兵器所作的配置。分为集团配置、线形配置、扇形配置、环形配置和纵深梯次配置等。', 18);
INSERT INTO `t_military_term_data` VALUES ('11108659-5821-4453-8b49-cf2e17f12402', '97a19170-bfac-42c5-9906-1acb187f0654', '长机', '①空中编队的机群中负责带队的飞机或直升机。通常由编队的空中指挥员驾驶。②基本空中编队（双机、三机）中负责指挥的飞机或直升机。', 190);
INSERT INTO `t_military_term_data` VALUES ('111a3a6a-dca3-4d7b-865f-d23f6f70b5f8', '916997ee-6728-4c61-9b79-d96960b1dc86', '吸收剂量率', '单位时间内的吸收剂量。单位为戈瑞／时或戈瑞／秒。', 99);
INSERT INTO `t_military_term_data` VALUES ('1122d01c-f350-44e0-8963-cc054fc25b01', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核鱼雷', '装有核战斗部的鱼雷。威力通常为千吨梯恩梯当量级。主要用以毁伤水下高速潜艇,也可攻击水面舰艇。', 109);
INSERT INTO `t_military_term_data` VALUES ('1126fd6e-55f7-4f35-a82e-e1cb44a4a88b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '抛掷爆破', '亦称飞散爆破。利用内部装药爆炸作用使土石破碎、抛掷,在地面形成炸坑的爆破。主要用以开挖漏斗坑、壕沟、各种工事的平底坑和土路基等。', 238);
INSERT INTO `t_military_term_data` VALUES ('1144cdf5-0184-43a2-a8d8-746b2338494c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '节点破坏', '对敌电子系统中起决定作用的关节点（要害部分）实施干扰和火力摧毁,以削弱或破坏敌电子系统的整体作战效能的行动。', 87);
INSERT INTO `t_military_term_data` VALUES ('114ae524-9628-4fb5-b52d-18029432e648', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火支援', '步兵、坦克发起冲击后,炮兵为支援其作战行动而实施的火力突击。通常在炮火准备结束时开始到炮火护送开始时结束。也泛指炮兵支援合成军队其他作战行动时的火力突击。', 68);
INSERT INTO `t_military_term_data` VALUES ('114d8cf5-0a71-4c65-9308-406fec95ffa8', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克灭火装置', '坦克内用以扑灭车内燃火的装置。分为移动式灭火装置和固定式灭火装置两类。移动式灭火装置即手提式灭火瓶；固定式灭火装置,有手动式、半自动式和自动式3种。', 140);
INSERT INTO `t_military_term_data` VALUES ('11509229-d68e-4ae7-ba0b-1ce5f645bc50', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '比武', '军事训练项目的竞赛活动。目的是激发练兵热情,深入开展群众性练兵活动,提高训练水平。', 164);
INSERT INTO `t_military_term_data` VALUES ('1166689a-aebb-42a8-9569-70ffcfd359ab', 'f0140091-c11a-48c9-8836-8aa94439dac0', '登陆点', '登陆地段内登陆兵分队突击上陆的地点。', 139);
INSERT INTO `t_military_term_data` VALUES ('1172707d-eed9-4fe3-89d4-06cebadd7e99', 'f0140091-c11a-48c9-8836-8aa94439dac0', '冲击出发阵地', '分队完成冲击准备并发起冲击所占领的阵地。通常选择在靠近冲击目标,便于隐蔽配置兵力兵器,便于观察和发扬火力的有利地形上。', 175);
INSERT INTO `t_military_term_data` VALUES ('11741b30-ba5c-4c20-b32e-351903ee9f70', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '牵引火炮', '靠牵引车或其他牵引工具牵引向运动的火炮。结构较简单,操作容易。维修方便,但机动性能差,行军与战斗转换速度慢,无装甲防护。', 18);
INSERT INTO `t_military_term_data` VALUES ('119e2468-a4a3-4fd9-9b40-4891d6e3aad8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '反坦克导弹武器系统', '反坦克导弹及其配套技术装备的统称。一般由导弹、导弹发射装置。制导系统、检测设备及其他配套设备组成。按机动方式,分为便携式、车载式和直升机载式反坦克导弹武器系统；按制导方式,分为有线手控制导、半自动制导和自动寻的制导反坦克导弹武器系统。', 33);
INSERT INTO `t_military_term_data` VALUES ('119eb3c9-1f25-4e4f-8a1f-9886e9083552', '916997ee-6728-4c61-9b79-d96960b1dc86', '过滤式防护', '使用滤毒通风器材,将外界受染空气净化后送入防护工事或车辆、舰船等的内室的防护方式。', 58);
INSERT INTO `t_military_term_data` VALUES ('11a1a4df-7930-4122-acc2-92c36d4c8ccf', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '登机地域', '空降部队登上直升机或飞机的地域。可选在机场,也可选在野外场地。地域的大小视乘载兵力而定。', 87);
INSERT INTO `t_military_term_data` VALUES ('11ac4cae-a7f8-472a-ad2f-535da91a1f22', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '人造天体', '在太空基本上按照天体力学规律运行的人造物体。包括正在太空使用的航天器和空间碎片等。', 200);
INSERT INTO `t_military_term_data` VALUES ('11e0a11d-ca2b-4055-9b64-9a947872e019', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '波束制导', '亦称驾束制导。利用光波及其他电磁波波束进行的制导。分为雷达波束制导和激光波束制导。', 48);
INSERT INTO `t_military_term_data` VALUES ('11e88e59-bbe3-4764-94ba-4d150ec92573', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射线', '射击武器发射前火身轴线的延长线。', 21);
INSERT INTO `t_military_term_data` VALUES ('12040c7b-f335-457a-b10a-5113280ca7f8', '06a75831-13a1-4660-870a-455bb445336a', '辅助通信枢纽', '为保障对远离指挥所的部队的指挥，或为增加迂回通信方向而建立的通信枢纽。配置在某一方向的适当地域、空域（机载或系留气球）或海域（舰载）。', 76);
INSERT INTO `t_military_term_data` VALUES ('120d1b7d-d9ab-467b-ad31-a52e3d98058d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇机动', '单艘舰艇或舰艇编队相对于某一目标进行的占领阵位或保持阵位的运动。分为定向定速机动、定弦角机动、曲折机动等。', 257);
INSERT INTO `t_military_term_data` VALUES ('120f895d-27c8-4f3d-8dcf-6ca1ddbf0ddd', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '预备工事', '阵地中备用的工事。在基本工事遭到破坏或有特殊需要时才启用。一般在每个基本工事附近构筑一至数个预备工事。通常在阵地工程构筑计划的第二期作业中构筑。', 58);
INSERT INTO `t_military_term_data` VALUES ('121e1c35-239f-49e9-83ab-b4a7f81d3100', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子干扰', '对敌方电子设备或系统采取的电波扰乱措施。目的是使敌方电子设备或系统的使用效能降低甚至失效。包括电子干扰技术和电子干扰战术。按干扰的性质,分为压制性电子干扰和欺骗性电子干扰；按干扰产生的方法,分为无源电子干扰和有源电子干扰。', 40);
INSERT INTO `t_military_term_data` VALUES ('12223cfd-0534-41ca-b642-dca6c5263a03', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '伪装器材', '实施伪装所用的器具和材料的统称。分为制式伪装器材和就便伪装器材。制式伪装器材有迷彩伪装器材、遮障伪装器材、单兵伪装器材、模拟伪装器材、干扰伪装器材、烟幕伪装器材和伪装检测器材等。就便伪装器材有工业制品、木材、竹材、树枝、草皮、木屑等。', 351);
INSERT INTO `t_military_term_data` VALUES ('12247015-8ca4-4a49-aec8-fe21db03fcfa', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '地雷场', '简称雷场。按照一定正面、纵深和密度布设地雷的场地。按用途,分为防坦克地雷场、防步兵地雷场和混合地雷场。地雷场的正面为数十米至数千米,纵深为数米至数百米。', 186);
INSERT INTO `t_military_term_data` VALUES ('1245004e-d960-4372-9cbb-4bcceb4f0713', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '线膛炮', '', 21);
INSERT INTO `t_military_term_data` VALUES ('1254f50c-5014-4ca0-b841-1edd9a48467c', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '实时定位', '地面部队或分队、舰艇、飞机等在运动中及时测定其所处的空间位置、可利用快速定位仪、地面导航仪、无线电定位系统、全球定位系统等手段进行。', 229);
INSERT INTO `t_military_term_data` VALUES ('1266b360-de0f-41c9-a208-fddc820ef232', 'd7132c58-5df3-4b97-919f-58740148b9ca', '空中目标运动规律假定', '对空中目标在提前时间内可能的运动规律的假设。根据目标在空中运动的状态可作四种假定：水平、匀速、直线假定,匀速、直线假定,水平、匀速、圆周假定,匀变速、曲线假定。', 140);
INSERT INTO `t_military_term_data` VALUES ('12739752-8bbe-49c2-a87f-135c5fa87b20', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '预备队', '为应付紧急、意外情况或根据作战中的实际需要,预作机动使用的兵力的统称。按规模和范围,分为战略预备队、战役预备队和战术预备队；按作战任务,分为合成预备队、炮兵预备队、坦克预备队、反坦克预备队、反空降预备队等。', 318);
INSERT INTO `t_military_term_data` VALUES ('127bcb1d-144f-4cf0-a3ce-26e19691e861', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军队内务', '军队内部的日常生活事务。主要包括：监督军人履行职责和义务,维护内部关系、军容风纪和日常工作、生活秩序,组织各项勤务等。', 29);
INSERT INTO `t_military_term_data` VALUES ('12a42245-a506-4ef1-94c2-511d48f1825b', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境挑衅', '在边境地区蓄意制造损害邻国利益和相入正常关系的行为。包括：向对方射击,越界殴打、绑架、抓捕对方人员,阻挠对方正常巡逻、通行和生产等。', 99);
INSERT INTO `t_military_term_data` VALUES ('12a84ee3-5c6b-4f01-888a-9d9f2675e02e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '架桥作业车', '由专用车辆载运、主要用就便器材架设低水桥和水面下桥的成套机械化作业工程器材。通常由数辆越野车分别安装或装载水上及陆上作业装置组成。', 288);
INSERT INTO `t_military_term_data` VALUES ('12b23e6d-eabb-4077-a47c-706c3e069dc1', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵光学测距机', '炮兵用以测量距离的以自然光为光源的光学仪器。有单目合像测距机和双目体视测距机两种。性能可靠,隐蔽性好，不受电磁波干扰,但与激光测距机相比,精度稍低,体积也大。', 281);
INSERT INTO `t_military_term_data` VALUES ('12c44ab7-df62-4ad0-b421-37b4ff705758', '98df76fb-4b65-48ff-a56c-4db587327c79', '按建制保障', '军队按建制关系组织实施的后勤保障。', 33);
INSERT INTO `t_military_term_data` VALUES ('12caf0eb-0da8-4fba-a924-17aaee03956e', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '前卫', '位于行军纵队前部,担负前方警戒和护卫任务的部队或分队。', 10);
INSERT INTO `t_military_term_data` VALUES ('12dcccc0-bad8-471d-92e8-2fd6876dd4e7', '98df76fb-4b65-48ff-a56c-4db587327c79', '伤势', '伤员受伤的轻重程度。通常按机体组织损伤范围,所需治疗时问的长短,对生命威胁程度,愈后有无残疾,对工作、生活的影响程度等综合判定。分为轻伤、中等伤、重伤3类。', 188);
INSERT INTO `t_military_term_data` VALUES ('12ec3f12-0aff-4c92-95fa-4f42e6077f9d', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '综合修理', '对武器装备及其配套设备进行的全面性修理。', 128);
INSERT INTO `t_military_term_data` VALUES ('12f172bc-1cdf-4643-a515-7c59520190b5', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵专用后勤装备', '第二炮兵为实施后勤保障而编配的各种专用装备、器材等的统称。主要包括：核监测装备,核防护装备,核伤员救治装备,推进剂废液及核废物处理装备,专用野战维修装备,核沾染区食品和饮用水补给装备等。', 206);
INSERT INTO `t_military_term_data` VALUES ('12f73185-fc2d-4943-b41d-43cb29a0db83', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火假转移', '炮兵有计划地将火力暂时转移至另一目标,诱骗敌离开隐蔽工事后再用火力突击的战术手段。通常在进攻作战时使用。', 77);
INSERT INTO `t_military_term_data` VALUES ('13108a2a-86ca-4aa8-aac0-347f7ccc75d1', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲战斗车辆', '装有武器可直接遂行作战任务的装甲车辆。包括坦克、步兵战车、装甲输送车、装甲侦察车、装甲指挥车、自行火炮等。装备于陆军、海军陆战队和空降兵等。', 84);
INSERT INTO `t_military_term_data` VALUES ('13222011-cdab-4e20-b751-ab95ac6126d6', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '实施侦察', '侦察部队和分队进行侦察活动。通常根据侦察计划进行。', 103);
INSERT INTO `t_military_term_data` VALUES ('132be762-9987-4b82-b39b-035b93de9a01', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '登陆换乘区', '亦称换乘海域。在由舰到岸的登陆作战中,登陆兵及其武器装备在登陆展开区内；从两栖运输舰船换乘小型登陆、着陆工具的海区、通常选在敌岸防兵器有效射程之外。', 101);
INSERT INTO `t_military_term_data` VALUES ('13357bb6-30a6-4bc4-b9cf-e47d6655de9b', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '荣誉室', '军队陈列单位和个人光荣历史、英雄模范事迹的展览室。是部队进行传统教育的课堂和场所。', 61);
INSERT INTO `t_military_term_data` VALUES ('133b14ca-f052-4257-b159-aa672c6ef776', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核武器投掷/发射系统', '简称核武器投射系统。将核武器投掷或发射到预定目标或提供相应初速的设备和设施的统称。通常由运载工具、投射装置及各种辅助设备等组成。', 129);
INSERT INTO `t_military_term_data` VALUES ('1340fb5a-ff13-4dc8-b189-d59a7d908445', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '部属', '军人在行政职务上有隶属关系时,行政职务低者。', 124);
INSERT INTO `t_military_term_data` VALUES ('1344ae3c-4917-403f-a686-988c8cbf32a7', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程勘察', '为组织实施工程保障任务而进行的现地勘察。一般由合成军队指挥员、工程兵指挥员和有关部队、部门参加。主要在现地明确各种工程保障设施的位置。战术技术要求和完成的时限等。', 26);
INSERT INTO `t_military_term_data` VALUES ('134bb8d8-d2cf-4e00-9541-3d10f215572b', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆分级', '汽车车辆质量分级的简称。根据汽车装备到部队的年限、总行驶里程和储备里程所划分的质量等级。通常划分为4个等级。履带车和摩托车不分级。', 301);
INSERT INTO `t_military_term_data` VALUES ('13593dab-db01-49c2-8bca-0c7d1f97adb2', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防政策', '国家在一定时期制定的关于边防建设和斗争的基本行动准则。', 109);
INSERT INTO `t_military_term_data` VALUES ('135e540d-038b-43db-a20e-0fefd2b95646', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战役集训', '为提高战役指挥员及其机关组织指挥能力而进行的短期集中训练。一般采取理论研究、战场勘察、战役想定作业和参观战役演习等形式进行。', 92);
INSERT INTO `t_military_term_data` VALUES ('13603d3e-b827-4b93-8460-f843082b37e4', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事目标', '①具有军事性质或军事价值的打击或防卫的对象。如军事设施、军事要地、军队集团等。②国家或政治集团确立的在一定时期内,军事建设或军事斗争所要达到的目的、标准和水平。', 49);
INSERT INTO `t_military_term_data` VALUES ('136c3585-8e89-4212-916c-8e85a11551f9', '98df76fb-4b65-48ff-a56c-4db587327c79', '战位急救盒', '配备在大型武器装备战位上的用于自救互救的制式药材盒。盒内装有包扎、止血、止痛、解毒、防护及抗感染等药材。通常装备在坦克、步兵战车、装甲输送车、自行火炮、雷达、飞机、舰艇等武器装备的战位上。', 223);
INSERT INTO `t_military_term_data` VALUES ('1373290b-e475-42d5-879e-67aaf60c2851', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练计划', '组织实施军事训练的预先安排。分为综合训练计划和专项训练计划。', 27);
INSERT INTO `t_military_term_data` VALUES ('13759e8b-5c42-4903-b4f7-1f09f6c6b697', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军岸上指挥所', '海军开设在岸上负责指挥海上作战的指挥机构。通常由海军领导机关、舰队或担负沿岸海区防御任务的战役编队开设。一般开设在便于指挥海上主要方向作战,便于组织与陆军、空军的协同和隐蔽、安全及交通方便的地点。', 119);
INSERT INTO `t_military_term_data` VALUES ('138e9510-ec2d-41b3-bc27-58beb0d66f9a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天测量船', '简称测量船。对航天器及运载火箭的飞行直接进行跟踪测量和控制的专用船只。是航天测控网的海上机动测量站。在航天控制中心的指挥下,可跟踪测量航天器的运行轨迹、接收遥测信息、发送遥控指令、与航天员通信,营救返回溅落在海上的航天员以及打捞数据舱等。', 270);
INSERT INTO `t_military_term_data` VALUES ('139650f1-79c2-4642-9474-36b98b9dc3be', '06a75831-13a1-4660-870a-455bb445336a', '单边带通信', '用调幅信号两个边带中的任一边带传输信息的通信方式。可传输电话、电报、数据和图像等。占用频带窄,节省功率,便于多路复用。', 107);
INSERT INTO `t_military_term_data` VALUES ('139dc4f0-9ff9-4027-bb23-5bf022dc740a', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行事故', '在训练飞行和任务飞行过程中发生的意外的航空器损坏和人员伤亡的情况、通常指航空器自滑出起飞至着陆滑行到指定位置止所发生的事故。按其损伤程度,分为一等飞行事故、二等飞行事故、三等飞行事故。一、二等飞行事故统称严重飞行事故。', 251);
INSERT INTO `t_military_term_data` VALUES ('13b5bfa6-4e16-4ab3-ba10-5b4a2e05d9f8', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机贴地飞行', '直升机在离地面或水面高度10米以下,保持等高、匀速的飞行。', 28);
INSERT INTO `t_military_term_data` VALUES ('13c717d2-6b25-495e-9e80-2ea2252a80ca', '878651de-adf5-4c72-9376-9c363b893ff8', '战略决战', '敌对双方使用主力进行的决定战争最后胜负的作战。如辽沈、淮海、平津三大战役是解放战争时期的战略决战。它们决定了中国人民解放战争的最后胜利。', 124);
INSERT INTO `t_military_term_data` VALUES ('13d62c8a-d471-4756-a1e5-a5cd91240ef7', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '障碍物', '能阻止或迟滞军队行动的地形和爆炸物、构筑物、破坏物、堵塞物及受染区等的统称。分为天然障碍物和人工障碍物。', 93);
INSERT INTO `t_military_term_data` VALUES ('13dbae01-91a7-41e0-bf13-cbd36522334a', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '雾', '大量微小水滴（或冰晶）悬浮于近地面空气中,致使水平能见度小于五千米的大气现象。雾常呈乳白色,垂直厚度一般为100～200米,有时可达数百米。', 30);
INSERT INTO `t_military_term_data` VALUES ('14013dcf-727f-46da-b3bf-56969d0db93f', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '光纤', '光导纤维的简称。由石英等材料制成直径几十微米的,用以传输光信息的玻璃细丝。与金属导线相比,具有传输信息容量大、抗电磁干扰、保密性好、体积小、重量轻和节省有色金属等优点。主要用以制造通信光缆和检测器件等。军事上有广泛用途。', 85);
INSERT INTO `t_military_term_data` VALUES ('140eff4a-315a-4202-80f9-ab4d46243a95', '97a19170-bfac-42c5-9906-1acb187f0654', '战斗活动时间', '飞机或直升机的战斗飞行时间中直接用于空战、轰炸、强击、侦察、空降和电子对抗等战斗活动的时间。计算方法是战斗飞行时间扣除起飞、出航和返航、着陆时间。', 59);
INSERT INTO `t_military_term_data` VALUES ('1417d31f-e969-4013-8ba1-951f84fd8f18', '31f4a446-5b98-4873-9d53-310d97125b07', '集群核突击', '用数枚核弹头在一定时间内对单个目标或目标群实施的突击。', 23);
INSERT INTO `t_military_term_data` VALUES ('141b7695-2c99-48ed-a0de-38097caa3dcd', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵情报保障', '第二炮兵为准确获取作战所需的情报而进行的保障。主要内容包括：敌方的战略企图、战略进攻力量、战略防御力量情况,指挥、控制与通信的手段与能力,战略目标动态和成果资料,核突袭征候、时机、规模,遭敌核袭击和实施核反击的效果等。', 156);
INSERT INTO `t_military_term_data` VALUES ('141c01a6-572c-43b2-9f07-51747b793d06', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '键控干扰', '采用电键或随机编码信号调制干扰发射机形成的电子干扰。主要用以干扰敌方的无线电报通信。', 63);
INSERT INTO `t_military_term_data` VALUES ('143166cc-7833-44bb-8f6a-136c3323ed47', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '堆积式工事', '在地面上用各种建筑材料修筑或堆积而成的工事。一般多在地下水位较高的水网稻田地、沼泽地和不易掘开的森林地、岩石地等地构筑。', 50);
INSERT INTO `t_military_term_data` VALUES ('1431dcbb-bd12-4db6-beac-f0bd66a3dfdd', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备等级转换', '军队的战备由一个等级向另一个等级的改变。通常为逐级转换,必要时也可越级转换。', 104);
INSERT INTO `t_military_term_data` VALUES ('1457a922-6bb0-43fd-b5f7-7edb1e87429e', '97a19170-bfac-42c5-9906-1acb187f0654', '近距航空火力支援', '航空兵部队在支援地面部队作战时,对敌前沿和浅近纵深内的、直接影响己方部队当前行动的目标实施的航空火力突击。包括航空火力准备、航空火力反准备和直接航空火力支援。', 122);
INSERT INTO `t_military_term_data` VALUES ('146ddfd6-64c5-463a-8d6f-a41e585cc41f', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射弹爆破效力', '射弹侵入目标或土壤一定深度爆炸后形成的摧毁目标能力。主要靠射弹爆炸形成的高温、高压、高速气浪对目标产生冲击、掀覆和摧毁作用。其大小与装药用量、射弹结构和侵入目标深度有关。', 121);
INSERT INTO `t_military_term_data` VALUES ('14885b17-4778-4ee8-87b0-d525be6b065d', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境争端', '相邻国家在边境问题上发生的争执。通常由领土归属、边界走向等涉及国家主权及重大利益的问题引起。严重的边境争端往往是引起武装冲突或战争的直接原因。', 96);
INSERT INTO `t_military_term_data` VALUES ('148ab0a9-cac1-4e39-bcf7-09f675804526', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备保管', '按有关规定对武器装备实施的保存与管理。', 99);
INSERT INTO `t_military_term_data` VALUES ('14a5b28a-80e9-4662-b6bf-469820106172', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战略侦察', '为获取与国家安全有关的和指导战争全局所需的情报而进行的侦察。通常由军队最高领导机关组织。', 1);
INSERT INTO `t_military_term_data` VALUES ('14aac7f3-8b7e-4810-960e-88661820e9dc', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '铁路输送', '使用铁路列车实施的输送。是部队实施远距离地面机动的主要方式。通常由被输送的单位和军事交通部门共同组织实施。', 74);
INSERT INTO `t_military_term_data` VALUES ('14b0c702-a9c8-4198-9591-d9c49bcbf413', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教案', '教员按课题或课时编写的教学实施方案。通常包括：课题,教学目的、要求、内容、进程、方法、时间,实施地点等。', 40);
INSERT INTO `t_military_term_data` VALUES ('14b3c1fe-e232-4676-98fd-7f7255103c1f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '导弹艇', '以舰舰导弹为主要武器的小型高速水面战斗舰艇。分为滑行型、半滑行型、排水型和水翼型等导弹艇。主要在近岸海区与其他舰艇协同对敌大中型水面舰船实施导弹攻击。', 143);
INSERT INTO `t_military_term_data` VALUES ('14c93461-a004-42db-9afa-2588451eb9cf', '8a761efd-50a6-4ac8-9913-b7d745104f82', '公算偏差', '亦称概率偏差或中间误差。在射弹散布面上，与纵、横或垂直、水平任何一条散布轴线相邻接的,并包含全部弹着点的50％的两界线间的宽度一半。以长度单位计量，是射击密集度的一种标志量。在垂直面上分为高低公算偏差和方向公算偏差，在水平面上分为距离公算偏差和方向公算偏差。', 78);
INSERT INTO `t_military_term_data` VALUES ('14c99432-81ea-47e5-ac46-653396ef4ad3', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '司令部', '军队中主管军事工作的领导机关。一般在团级以上部队或单位设立。在本部队或单位首长领导下,负责作战指挥、行政管理和军事训练等工作。', 4);
INSERT INTO `t_military_term_data` VALUES ('14d1b473-daea-4ffc-a231-ac1ff0aed450', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上飞行', '飞机、直升机在海洋上空的飞行。特点是：地标和助航设备少；海面能见度较差,天水线不易分辨；低空风力、风向极不稳定等。', 306);
INSERT INTO `t_military_term_data` VALUES ('14e44987-dde1-4642-9b5f-c06cf3c45af4', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行巡航速度', '适宜于航空器和巡航导弹长距离、长时间飞行的速度。航空器的巡航速度一般为其平飞最大速度的70％～90％。', 297);
INSERT INTO `t_military_term_data` VALUES ('14f3f90f-dc51-4b40-9773-95c52fcf7105', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '军事模型', '对军事事物进行模拟的表示形式。包括实体模型、图形模型、数学模型和混合模型等。', 167);
INSERT INTO `t_military_term_data` VALUES ('14ff273f-4458-4966-a139-340fca223bb9', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队作战准备时间', '导弹部队和分队从接到作战预先号令至占领发射阵地前（液体导弹发射井作战至加注液体推进剂前）的进行作战准备的时间。', 134);
INSERT INTO `t_military_term_data` VALUES ('15002176-a31c-465d-ab36-bafa9024d1a4', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '行政管理', '军队对内部日常事务的管理。主要包括：按照共同条令和有关规章制度,建立和保持正现的战备、训练及其他工作与生活秩序,培养严格的组织纪律性和优良的作风,维护良好的内外关系,管好军事资产,做好安全防事故了作等。', 0);
INSERT INTO `t_military_term_data` VALUES ('1500583c-b6cd-4658-91a1-d143f53b136a', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '自适应干扰', '能根据被干扰的敌电子设备的辐射参数和工作方式的变化,自动选择最佳干扰参数的电子干扰。', 65);
INSERT INTO `t_military_term_data` VALUES ('150df086-3614-4ab5-8a72-736057902c0f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核武器安全', '核武器所具有的防止发生意外的核或炸药爆炸事故及防止非授权动用的性能。', 136);
INSERT INTO `t_military_term_data` VALUES ('1512c6d2-c253-4ec7-a4db-ce77c7e431c4', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机偷袭', '直升机以隐蔽、突然的行动对敌实施出其不意的袭击。', 67);
INSERT INTO `t_military_term_data` VALUES ('151680d9-dcc1-4ffa-b185-832526dce60b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '黑障区', '导弹弹头和航天器返回舱等再入体返回大气层后无线电信号中断的飞行区段。其范围取决于再入体的外形、材料、再入速度,以及发射信号的频率和功率等。黑障区给载人飞船再入返回时的实时通信和再入测量造成困难。', 288);
INSERT INTO `t_military_term_data` VALUES ('15170bf7-faa7-444b-879d-9a66495e1f41', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场水上巡逻队', '为保障渡场安全而派遣的水上警戒分队。主要任务是；进行水上巡逻警戒,排除水雷和漂流物,防备敌人从水上袭击渡口。', 321);
INSERT INTO `t_military_term_data` VALUES ('15176cf9-1629-48c1-ac65-904a4059416d', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '个别命令', '对某一军兵种或部队单独下达的作战命令。', 125);
INSERT INTO `t_military_term_data` VALUES ('15187604-9b6c-4ce6-a585-5b12cad8af84', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫勤侦察', '军队卫勤部门为查明部队行动地域内影响有生力量健康的各种因素和进行卫勤保障的环境条件而实施的侦察。分为医疗后送侦察、卫生防疫侦察和卫生防护侦察等。', 184);
INSERT INTO `t_military_term_data` VALUES ('1519506a-0df3-414a-b76a-a1cb2d6e5518', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '内爆法原子弹', '亦称压紧型原子弹。利用炸药爆炸产生的内聚冲击波压缩处于次临界状态的裂变装料,使其密度急剧升高,达到超临界状态从而发生核爆炸的原子弹。', 86);
INSERT INTO `t_military_term_data` VALUES ('151d1af2-af96-4b7f-ae66-a12f5b1225de', '06a75831-13a1-4660-870a-455bb445336a', '电话通信', '利用电信号传输语言信息的通信。分为有线电话通信和无线电话通信。', 134);
INSERT INTO `t_military_term_data` VALUES ('151ee8e0-a5e6-4da0-b562-2cd2ae33a12b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '多普勒制导', '利用多普勒效应获得导引信息进行的制导。常与惯性制导组成惯性与多普勒复合制导。', 46);
INSERT INTO `t_military_term_data` VALUES ('1527fecf-3ed6-4a14-9c21-a96de94ec3c9', '83e065b4-6737-4645-9ea5-8276d1de13ed', '特种坦克', '装有特殊设备,担负专门任务的坦克。包括侦察坦克、扫雷坦克、水陆坦克和喷火坦克等。', 91);
INSERT INTO `t_military_term_data` VALUES ('1529210d-b17a-42bb-9e93-e5e387cd0159', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '避弹所', '容积较小且坚固程度较低,无滤毒通风装置的人员掩蔽工事。一般构筑在掩体、堑壕的附近,可容纳3～6人。', 70);
INSERT INTO `t_military_term_data` VALUES ('152e3006-7c84-4541-8a3f-f80c5e5a25ef', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵指挥', '第二炮兵指挥员及其指挥机关对所属部队作战和其他行动实施的组织领导活动。', 125);
INSERT INTO `t_military_term_data` VALUES ('153cb2d1-0ce1-46b1-a6f6-828706f8c6b7', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥方式', '实施指挥的方法与形式、按指挥权限集中程度,分为集中指挥和分散指挥；按指挥跨越的层次,分为按级指挥和越级指挥；按指挥位置是否固定,分为移动指挥和定点指挥等。', 19);
INSERT INTO `t_military_term_data` VALUES ('153dec49-6f6c-44b6-86c5-4c3796864abe', '06a75831-13a1-4660-870a-455bb445336a', '电缆通信', '利用电缆作为传输媒介的有线电通信。分为永备电缆（地下、海底电缆通信）和野战电缆通信。可传输电话、电报、数据和图像等。通信容量较大、距离远,传输质量高。可用以建立通信干线和永备筑城地域的有线电通信。', 125);
INSERT INTO `t_military_term_data` VALUES ('155aeec7-a958-4c27-aed4-143e09eacc60', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '给水工程部队', '工程兵中担负野战给水工程保障任务的专业部队。装备有给水器材。主要负责在作战地区侦察水源和构筑野战给水站。', 8);
INSERT INTO `t_military_term_data` VALUES ('155e5fbd-884b-4ed7-8b5a-65c7f809cb1e', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '攀登训练', '为使侦察兵掌握逾越悬崖、陡壁、楼房等障碍的技能而进行的训练。主要训练内容包括三点固定上下、抓绳上下和搭人梯等攀登动作要领。', 94);
INSERT INTO `t_military_term_data` VALUES ('1560df11-1c8d-418f-922c-308f125c88c4', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报评价', '对情报和情报资料的可靠程度、使用价值进行鉴定和估价。', 153);
INSERT INTO `t_military_term_data` VALUES ('15689f5f-8331-4692-874c-babe134b93dd', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗数据库', '在电子计算机中按一定格式和结构存储的敌方各种电子设备的信号特征参数、部署位置及属性等信息的数据集合。由计算机硬件、数据库管理系统软件、情报数据等组成。主要用于为电子对抗情报分析、作战决策、装备科研提供所需数据,并可生成为完成特殊使命所需的专用数据库。', 110);
INSERT INTO `t_military_term_data` VALUES ('1578c0e3-f48f-46f3-89eb-e5a03221e682', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '水体', '天然形成或人工造成的水的聚积体。包括海洋、河流、湖泊、沼泽、冰川、积雪，以及地下水和大气中的水等。', 109);
INSERT INTO `t_military_term_data` VALUES ('158cd712-ceac-45a5-bb1b-536f1e43204d', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行危险天气', '危及航空器飞行安全的天气。主要包括：恶劣能见度。大风、低云、雷暴、低空风切变,造成中度以上航空器颠簸的大气湍流,以及导致航空器在飞行中积冰的云、冻雨、湿雪等天气现象。通常由航空气象台或气象室及时发布飞行危险天气的预报或警报。', 382);
INSERT INTO `t_military_term_data` VALUES ('15923bd7-841a-4eec-a2be-b0ac18486ad4', '98df76fb-4b65-48ff-a56c-4db587327c79', '综合仓库', '储存两类以上专业物资的军用仓库。', 136);
INSERT INTO `t_military_term_data` VALUES ('15999366-0c05-443d-a660-300c9928f8cf', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天气侵蚀', '高超音速飞行体再入地球稠密大气层,与大气中的液态或固态等自然粒子群相遇,其表面材料发生质量损失的现象。再入区的云和降水是造成天气侵蚀的主要环境因素。天气侵蚀与高温烧蚀的耦合作用,可显著改变导弹弹头的气动外形和气动特性,影响导弹的命中精度与生存率。', 87);
INSERT INTO `t_military_term_data` VALUES ('15af413e-8439-4ea6-a9c6-20234f8bc9dd', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水中武器', '亦称水中兵器。能在水中毁伤目标或对抗鱼雷、水雷的各种武器的统称。包括鱼雷、水雷、深水炸弹、反潜导弹以及反鱼雷武器、反水雷武器等。', 198);
INSERT INTO `t_military_term_data` VALUES ('15c54f4f-cf82-4012-8b24-95bcce9deebd', '97a19170-bfac-42c5-9906-1acb187f0654', '拦射空空导弹', '亦称中远距空空导弹。能在空战中对中、远距离的空中目标进行拦截射击的空空导弹。按发射距离,分为中距空空导弹和远距空空导弹。中距空空导弹的发射距离为25～100公里,多采用半主动雷达寻的制导；远距空空导弹的发射距离超过100公里,多采用复合制导。', 317);
INSERT INTO `t_military_term_data` VALUES ('15cbc4e3-ed8c-404e-b7ec-d33f49ea9416', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事实力', '①现实的能够直接用于战争的军事力量。通常指现有的武装力量员额及军事设施、装备、物资等的数质量。②军队或军队的某一级组织现有的建制单位、人员、武器装备等数质量的统称。', 46);
INSERT INTO `t_military_term_data` VALUES ('15d07e42-37e3-4bbd-99d5-32775d207341', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子佯动', '利用电子设备和器材模拟己方部队行动的电磁辐射特征,以欺骗敌方的电子对抗行动。目的是隐蔽己方作战企图,使敌产生错误判断。', 74);
INSERT INTO `t_military_term_data` VALUES ('15d4fb20-67de-423f-8880-187e90674825', '916997ee-6728-4c61-9b79-d96960b1dc86', '消除液', '消除剂与水按一定比例调制成的溶液。如各种洗涤剂水溶液,洗涤剂、络合剂与水调制成的水溶液等。', 189);
INSERT INTO `t_military_term_data` VALUES ('15da8ea8-15ab-4825-a220-3cd091aa73dd', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役类型', '按照作战行动的性质对战役所作的基本分类。分为进攻战役和防御战役两大类。', 1);
INSERT INTO `t_military_term_data` VALUES ('15e5a081-a367-4c7c-a79a-626fc4dd901a', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '强行爆破', '在直瞄火力威胁下对目标强行实施的爆破。', 248);
INSERT INTO `t_military_term_data` VALUES ('15f2dd02-6b78-4556-a86e-0a2f2b502bf4', '06a75831-13a1-4660-870a-455bb445336a', '通信代密', '用于代替通信内容的数码、字母和单词的统称。通常在无线电信号表、通信密语表、部队和指挥员代号表等军用文书中使用。', 149);
INSERT INTO `t_military_term_data` VALUES ('15f9c9c2-a398-4cb0-a524-19c2e7325788', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '各个击破', '集中兵力歼敌一部,再转移兵力逐个歼灭其余各部。', 231);
INSERT INTO `t_military_term_data` VALUES ('15fbe8f9-ea31-4057-a69b-a5fef487a9e2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战任务', '武装力量在作战中所要达到的目标及承担的责任。分为战略任务、战役任务和战斗任务。', 118);
INSERT INTO `t_military_term_data` VALUES ('160d8793-44d5-42c8-9a75-2e5d6ee08b56', 'd7132c58-5df3-4b97-919f-58740148b9ca', '队属防空兵', '编入陆军集团军、师、旅、团、营建制内的防空兵。分别装备有不同射程和射高、机动性能较强的防空武器系统。', 1);
INSERT INTO `t_military_term_data` VALUES ('162f8c2b-e51d-430d-bd6c-a6290249f5a9', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '外场保障队', '负责直升机的飞行后勤保障工作的分队。由后勤指挥人员和车辆、器材、给养、油料、弹药、医务等方面的保障人员组成。', 93);
INSERT INTO `t_military_term_data` VALUES ('16351c10-1a30-402c-aaf1-5652063f6656', '06a75831-13a1-4660-870a-455bb445336a', '大气激光通信', '利用大气作为传输媒介的激光通信。可传输电报、电话、数据和图像等。抗电磁干扰,设备轻便,保密性好,但通信距离近,易受气象条件影响,并且收、发天线对准困难。一般用作河湖山谷和沙漠地区以及海岛间的视距通信。', 129);
INSERT INTO `t_military_term_data` VALUES ('163ad747-a528-4529-93ed-b69a881fc334', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国界标志', '相邻国家根据有关条约或协议确认的,表示邻国间陆地国界实际位置和走向的标志。有人工标志和天然标志两种。人工标志为界碑、界桩、界塔、浮标、浮界石等。天然标志为当事国共同确认的山脊、独立明显物体、河道（或主航道）的中心等。', 81);
INSERT INTO `t_military_term_data` VALUES ('1646075e-f322-4e50-9975-62b18bbc3892', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射弹破片效力', '射弹爆炸后形成的大量破片对目标的毁伤能力。其大小与引信种类、目标性质、命中角大小以及破片的数量、质量、初速和形状等有关。', 120);
INSERT INTO `t_military_term_data` VALUES ('1646ed51-3d8c-432c-a598-c15d4a447766', 'f0140091-c11a-48c9-8836-8aa94439dac0', '江河防御战斗', '利用江河障碍进行的防御战斗。通常在己岸组织防御,也可在对岸建立桥头阵地进行防御。', 205);
INSERT INTO `t_military_term_data` VALUES ('16481473-09f7-40d1-8c1a-8f78c8d7dad5', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战序列', '按作战需要规定的部队的组织系统和指挥关系、战术范围的作战序列,亦称战斗序列。', 119);
INSERT INTO `t_military_term_data` VALUES ('164de92c-5d2a-4c59-adbb-95bc57ff77a0', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射界', '射击武器在一个发射位置上能对目标进行射击的角度范围。其大小由武器性能、地形条件、目标类型、友邻安全等因素决定。', 85);
INSERT INTO `t_military_term_data` VALUES ('16567612-b8be-4b5e-92dc-7fd6e56e6817', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '武装力量', '国家或政治集团所拥有的各种武装组织的统称。', 14);
INSERT INTO `t_military_term_data` VALUES ('16580aa0-3307-4362-a7c6-30962f5762c8', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '预备役军官军衔', '区分和表明预备役军官身份等级的称号和标志。等级划分一般与现役军官军衔相同。', 135);
INSERT INTO `t_military_term_data` VALUES ('16733860-8522-443f-b74f-c72d53eaab2d', '97a19170-bfac-42c5-9906-1acb187f0654', '空中电击', '亦称空中雷击。飞机或直升机在飞行中,某些突出部位因被雷暴击中而产生的放电现象。一般发生在雷暴云中或其附近、电击会引起飞机结构损伤、机上电子仪表设备发生故障,并对飞行人员的心理、生理产生不良影响，严重时可导致飞行事故。', 384);
INSERT INTO `t_military_term_data` VALUES ('1681a4da-b4fd-4a31-b0b2-b7de29f023d7', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '拦阻射击提前点', '在运动目标的航向线上,接提前时间或提前距离量取射击开始诸元的点。', 233);
INSERT INTO `t_military_term_data` VALUES ('16839cba-35c6-42f6-8fda-f8919359d4e3', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵战斗出动强度', '航空兵部队遂行作战任务时战斗出动的频率。是衡量航空兵作战能力的主要标志之一。通常用平均每架飞机一昼夜出动的次数表示。取决于所受领的战斗任务,飞行人员的数量、体质、技术水平和气象条件,以及机务保障、飞行后勤保障等条件。', 62);
INSERT INTO `t_military_term_data` VALUES ('168abe33-0db3-42c1-b613-22f3c600a9e8', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '兵团', '①师、旅规模的兵力集团的统称。②中国人民解放军在解放战争时期的一级组织。下辖若干个军。', 41);
INSERT INTO `t_military_term_data` VALUES ('169f6d77-7dff-45b9-9448-032293f0e2ad', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防现代化', ' 国防事业达到现代先进水平的过程和目标。是国家现代化的重要组成部分。主要包括军事思想、武装力量、国防科技、国防工业、国防设施、国防体制与管理等方面的现代化。', 6);
INSERT INTO `t_military_term_data` VALUES ('16d3ea4d-2788-412e-b567-f42100888edd', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹紧急断电', '固体导弹发射时在发动机点火前,利用地面控制设备紧急切断其供电电路的过程。通常在热发射时固体导弹发动机尚未点火或冷发射时弹射装置尚未启动时进行。是中止发射所采取的紧急措施。', 105);
INSERT INTO `t_military_term_data` VALUES ('16e50003-8833-4d6f-9968-165e9a4ad3d5', '0', '侦察 .情报', NULL, 21);
INSERT INTO `t_military_term_data` VALUES ('16e5f160-b068-49fd-ac06-02e3a4d0ca80', '98df76fb-4b65-48ff-a56c-4db587327c79', '战时人员供给证', '中国人民解放军战时使用的为参战人员接转供应关系的凭证。作为发放薪金、津贴、补助费、负伤费和领报公务、事业费的依据。由军区、军兵种有关部门按总部规定的统一格式印制。', 78);
INSERT INTO `t_military_term_data` VALUES ('16f8fb74-828b-4365-acdd-2a702b9cbe5b', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克潜渡能力', '坦克借助潜渡装置沿水底行驶通过水障碍的能力。通常表现为潜渡水深、潜渡距离和准备时间。坦克潜水深度一般为4～5.5米。', 168);
INSERT INTO `t_military_term_data` VALUES ('16fe0089-f2fc-4d10-a943-771a7bf628b5', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术密度', '兵团或部队、分队在作战正面上每公里部署兵力兵器的平均数量。通常步兵、坦克兵以营为计算单位；坦克、步兵战车、装甲输送车、压制火炮、反坦克武器和防空武器等以辆或门、管、具为计算单位。', 41);
INSERT INTO `t_military_term_data` VALUES ('1702a48e-e187-4244-84dc-4f778066d87b', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '红外技术', '研究红外辐射的探测及其应用的技术。主要包括：红外探测器的研制技术,红外光学系统和精密机械的制造技术,信息的处理和显示技术等。军事上广泛应用于夜视、制导、侦察等方面。', 24);
INSERT INTO `t_military_term_data` VALUES ('1711a7d3-371d-4b12-8aa2-a7186cde1cc3', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '协同动作计划图', '标绘有协同计划内容的图、通常标绘有各阶段的预想情况各军兵种的行动预案指挥所的位置,协同信号和记号等。', 149);
INSERT INTO `t_military_term_data` VALUES ('1725b71d-dc95-4762-917f-0b2e8dfd9e10', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '编外文职人员', '军队中编制以外的文职干部和职员的统称。', 109);
INSERT INTO `t_military_term_data` VALUES ('172aae81-ad7b-4a19-89a9-c20e0590d099', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹泄出推进剂', '将导弹推进剂储箱里的液体推进剂泄入槽车或固定储罐的过程。通常在液体导弹紧急关机未能发射或加注训练、点火训练后进行。', 101);
INSERT INTO `t_military_term_data` VALUES ('1734088c-1299-4f06-965e-5608121a6e19', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器故障率', '轻武器在寿命期内可能出现射击故障的概率、通常以抽样射击试验中出现故障的射击次数与总射击次数的比值（百分比）表示。包括轻武器动作故障事、弹药发射故障率、弹丸作用故障率等。', 224);
INSERT INTO `t_military_term_data` VALUES ('173aa76d-d7aa-45a2-b41f-8f4ba2c4f723', '8a761efd-50a6-4ac8-9913-b7d745104f82', '平均弹道', '通过集束弹道中央的一条设想的弹道。是计算射击诸元、编制射表的基准弹道。', 38);
INSERT INTO `t_military_term_data` VALUES ('173d1e70-fba1-4bd2-8871-951cf2188278', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教练弹', '专供军事训练使用的仿真模拟弹。如模仿真弹外形但不能发射的各种练习弹和能够打响但无杀伤力的空包弹等。', 190);
INSERT INTO `t_military_term_data` VALUES ('173ee3b1-0364-4ac9-9b6b-468380ec3a66', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵跨区作战', '航空兵部队的飞机越过其作战责任区界限的作战。通常在连续攻击敌机或支援友邻区部队作战的情况下实施。跨区作战的飞机既可返回原起飞机场着陆,也可实施全程作战到友邻机场着陆。', 65);
INSERT INTO `t_military_term_data` VALUES ('173f85c1-9671-459a-a302-aaf84507c7e1', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵换班', '某一防空兵部队或分队接替另一防空兵部队或分队执行作战任务。须周密组织,加强战斗保障,充分做好对空射击准备,防敌突然袭击。', 26);
INSERT INTO `t_military_term_data` VALUES ('17478502-cde2-4b5e-8b83-8528afb17b70', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '预先号令', '为使部队预有执行任务的准备而发出的预告性的命令。通常在正式命令下达前用口头或书面方式下达。', 120);
INSERT INTO `t_military_term_data` VALUES ('174a5f27-e616-463a-8e37-9b0000c49024', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '邻带补充坐标网', '在地形图上加绘的相邻投影带的坐标网、通常在每一投影带两侧的地形图上,按规定在地形图外图廓线上加绘邻带延续过来的坐标短线,并注记相应的千米数。便于使用相邻两投影带地形图时的坐标衔接。', 274);
INSERT INTO `t_military_term_data` VALUES ('174a6a3d-e518-4cb0-b04d-665e49cc46e0', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空武器系统', '主要用以歼灭空中目标的各种武器系统的统称。包括歼击机、地空导弹、高射炮、拦阻气球、电子对抗设备等。', 27);
INSERT INTO `t_military_term_data` VALUES ('1750827d-0c67-4114-86f7-ff55b5e56f8c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '野战供水标准', '野战条件下供给军队饮水、用水的数量和水质参数的指标。分为饮用水标准洗涤用水标准、冷却和洗消用水标准。其数量通常按单人、单车、单机在单位时间内的用水量计算。', 363);
INSERT INTO `t_military_term_data` VALUES ('17530c37-31a5-451c-8a67-4774a8ef74c1', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '首曲线', '又称基本等高线。在地形图上按编图规范现定的基本等高距描绘的等高线。通常以细实线表示,用以显示地表基本形态。', 281);
INSERT INTO `t_military_term_data` VALUES ('176a22b7-c749-4f2b-871f-f384f4b1cf9f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵火力配系', '防御时将各种火炮、火箭炮、导弹按其性能作适当的配置和任务分工所构成的火力系统。目的是充分发挥各类炮兵火器的特长,使炮兵射击远近结合,平曲结合,直射、斜射和反射相结合,获取最佳射击效果。', 98);
INSERT INTO `t_military_term_data` VALUES ('176e3644-f48b-41d7-b69d-ec58c9a28b8f', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军船艇保障', '组织运用陆军船艇对部队遂行各项水上任务进行的保障、包括对人员水上交通、物资水上运输以及海上侦察、边防巡逻和工程作业的保障等。', 336);
INSERT INTO `t_military_term_data` VALUES ('17882b9b-55eb-475d-90f7-1a4891e2b3d2', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '确定站立点', '在现地使用地形图时将自己站立的实地位置确定于图上相应的位置。可依已知的明显地形点、方位物等用目测判定,或用截线法、后方交会法等确定。', 141);
INSERT INTO `t_military_term_data` VALUES ('179eba9c-6776-46c5-b3de-e9b78975c915', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战值班', '担负作战和保障指挥任务的团以上部队司令部建立的组织与制度、通常地作战部门或参谋长指定的部门担任,负责受理作战、战备等有关事宜', 60);
INSERT INTO `t_military_term_data` VALUES ('179f2347-272b-4c44-a712-93aa17776450', '98df76fb-4b65-48ff-a56c-4db587327c79', '计划内物资', '列人军队后勤物资部门计划分配的工业品生产资料。包括国家计划分配物资和纳人物资部门供应计划的军队自筹物资。', 102);
INSERT INTO `t_military_term_data` VALUES ('17aaca0b-3c8c-4e64-87da-6fe87f6dbf6e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '非线性规划', '目标函数是非线性函数或约束条件中有非线性等式或不等式的数学规划。通常在解决兵力、兵器和资源等分配问题时,用以选择最优方案。', 184);
INSERT INTO `t_military_term_data` VALUES ('17ab7929-ce81-47b3-90eb-cba95130f16c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '俘虏管理所', '收容、教育和管理敌军俘虏的处所及其机构。', 129);
INSERT INTO `t_military_term_data` VALUES ('17b27ef5-2d07-43a8-b8e0-8e2a7c50c348', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇操纵性', '舰艇所具有的借助操纵装置保持或改变航向、航速、位置和状态的性能。是舰艇战术技术性能要素之一。包括直线稳定性、航向机动性和回转性等。水下航行的潜艇,还包括水平稳定性。', 334);
INSERT INTO `t_military_term_data` VALUES ('17b82948-62c4-4d79-9aaa-5a38fd55de88', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上突击目标', '海军兵力实施海上突击的对象。分为主要突击目标和辅助突击目标。', 44);
INSERT INTO `t_military_term_data` VALUES ('17bd6237-ef57-4cfd-a454-b975a390c2f1', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '压制火炮', '主要用于对地面、水面的面状目标实施压制射击的火炮。包括各种加农炮、榴弹炮、加农榴弹炮。迫击炮等。', 16);
INSERT INTO `t_military_term_data` VALUES ('17caa7b8-dace-4964-82b7-54ecd2b3acc5', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役前方阻击区', '在第一防御地带前视情设置的临时性的阻击地区。通常在不与敌直接接触又不设掩护地带的情况下设立。阻击区一般设置若干阻击阵地、伏击阵地、障碍地带和游击区等。', 131);
INSERT INTO `t_military_term_data` VALUES ('17cafb56-409f-46eb-89e2-cb40b803666e', '98df76fb-4b65-48ff-a56c-4db587327c79', '科学研究费', '军队用于科学研究和技术革新的经费。', 83);
INSERT INTO `t_military_term_data` VALUES ('17d2eed0-2eed-4f79-95a1-4114facc5b9f', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克标定射击', '坦克利用预先测定好的射击诸元进行的射击。通常在夜间防御战斗中利用已构筑的发射阵地进行。', 57);
INSERT INTO `t_military_term_data` VALUES ('17eed43f-ae35-4c16-acba-bf5a2dd7c960', '98df76fb-4b65-48ff-a56c-4db587327c79', '运量', '在一定时间内运送人员和物资的数量。人员运量以人数表示,物资运量以吨数表示。', 275);
INSERT INTO `t_military_term_data` VALUES ('17feb8cc-4739-452d-b6f2-3fa9c802b61e', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '光纤技术', '研究光信息在光导纤维中的传输机理、光纤的制造及其应用的技术。主要包括光纤、光纤器件和光缆的研制技术,光电信息的转换传输和处理技术等。军事上可应用于通信、制导、侦察等。', 34);
INSERT INTO `t_military_term_data` VALUES ('17ff8b93-7fef-46a5-95ab-e1360bcca4aa', '8a761efd-50a6-4ac8-9913-b7d745104f82', '麻醉枪', '发射麻醉弹的手提式装置。弹药通常为注射式,命中目标后自动将麻醉剂注入生动目标体内,使之暂时失去知觉和行动能力。', 178);
INSERT INTO `t_military_term_data` VALUES ('18071c56-aa5c-4a08-a4f6-b3f8d7e2273f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '左（右）邻舰', '舰艇编队航行队形或队列中,位于某舰左（右）侧相邻的舰。', 266);
INSERT INTO `t_military_term_data` VALUES ('1808233b-a14e-4b4b-b6b5-fa0c53e156ad', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战场勘察', '以勘察预定战场实地情况为主要内容的战场准备。主要是查明自然地理和人文地理的情况并分析其对作战的影响,判断敌人在该地区可能采取的作战行动,为制定作战预案和进行战场建设提供依据。', 170);
INSERT INTO `t_military_term_data` VALUES ('181a921c-63d6-4ff6-b3b5-7fffc369a910', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '次声武器', '频率低于20赫的次声波杀伤有生力量的武器。次声波到达人体后,与人体的器官发生共振,使人产生头晕目眩、恶心呕吐、神志不清、内脏破裂等症状。通过改变次声强度和频率,可达到不同的杀伤效果。是尚在研究试验中的武器。', 50);
INSERT INTO `t_military_term_data` VALUES ('181ec996-398a-4ef0-ae9c-49ce023d45a6', '8a761efd-50a6-4ac8-9913-b7d745104f82', '微声枪弹', '专供微声枪械发射的枪弹。发射时枪口焰、烟和声响微小,夜间在50米以外难以察觉。', 202);
INSERT INTO `t_military_term_data` VALUES ('1823bbcd-4fda-4619-a1be-c319df569911', '878651de-adf5-4c72-9376-9c363b893ff8', '战略计划', '为达成一定的国防或战争目的,对战略行动所作的预先安排。主要内容包括战略判断、战略任务、战略部署、战略方向、战略步骤及战略措施等。', 62);
INSERT INTO `t_military_term_data` VALUES ('18272cb5-557c-439f-bb62-fb4ea9ec3a54', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '地地战役战术导弹', '从陆地发射,用以压制和破坏敌战役战术纵深内重要目标的导弹。有些国家称为地地战术导弹。是地地战役战术导弹武器系统的主要组成部分。按弹道特征,分为弹道式和巡航（飞航）式两种。', 32);
INSERT INTO `t_military_term_data` VALUES ('183d9f78-efd9-44b1-a2f7-d13010bf5dbc', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '核障碍区', '简称核障。核武器在地面或浅层地下爆炸造成的障碍区。以核突击或引爆核地雷的方法造成。通常由大漏斗坑、松散的土石堆和沾染区以及破坏物、堵塞物等构成。', 113);
INSERT INTO `t_military_term_data` VALUES ('183f038c-c8e0-4b52-ac51-4c949a2ab605', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水兵', '舰艇部队士兵的统称。', 11);
INSERT INTO `t_military_term_data` VALUES ('18428f40-2751-494f-b1f3-756faf2da018', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '登陆指挥控制舰艇', '登陆作战中,在登陆海域内专门负责对登陆舰艇进行指挥、控制和协调的舰艇的统称。通常在冲击出发线两端设前方控制艇,在展开线至冲击出发线之间的航道翼侧设航道控制艇,在展开（换乘）区设区域控制艇,在登陆海域中央设基本指挥舰。', 104);
INSERT INTO `t_military_term_data` VALUES ('18485ae5-fc59-4e1f-9133-7e02eb97a7d0', '97a19170-bfac-42c5-9906-1acb187f0654', '轰炸安全线', '使用飞机轰炸战场目标时,为防止误伤而划定的投弹点距己方人员的最小安全距离线。主要取决于：炸弹的杀伤破坏半径,瞄准与投弹方法、轰炸高度、轰炸瞄准设备,昼间或夜间,大气和地形,以及飞行人员的技术水平等因素。', 196);
INSERT INTO `t_military_term_data` VALUES ('18516bc1-69bd-4b13-b6eb-e944bf5e5fb8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵压制射击', '炮兵给目标以一定毁伤,使其暂时丧失战斗力或指挥能力的射击。要求毁伤程度为10％～45％。分为临时压制射击、一般压制射击和重点压制射击。', 174);
INSERT INTO `t_military_term_data` VALUES ('1851f764-a50d-4660-9227-3765fa1a617d', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '对空警戒', '军队在地面或海上组织和实施的对空中情况的警戒。主要任务是及时发现和防范来自空中之敌的突然袭击和侦察活动。', 2);
INSERT INTO `t_military_term_data` VALUES ('1852d22e-dade-4a50-b21e-7ed2b51ee5e2', 'f0140091-c11a-48c9-8836-8aa94439dac0', '奔袭', '从距离较远的地方迅速向敌人接近并对之实施的袭击。', 152);
INSERT INTO `t_military_term_data` VALUES ('1853039d-9948-473f-9e12-2a2e039ee9c0', '31f4a446-5b98-4873-9d53-310d97125b07', '核爆炸地震波探测', '对核爆炸产生的地震波进行的探测。主要用以确定核爆炸的时间、位置和当量等。', 174);
INSERT INTO `t_military_term_data` VALUES ('185e8aba-5445-41e4-833e-ebb76d49eda3', '97a19170-bfac-42c5-9906-1acb187f0654', '迫降场', '专门为飞机紧急情况下被迫着陆而设置的场地。分为场内迫降场和场外迫降场。场内迫降场亦称上跑道,通常设置在主跑道的一侧；场外迫降场通常设置在有土质跑道的旧机场或其他适宜迫降的场地。', 425);
INSERT INTO `t_military_term_data` VALUES ('1867514e-128e-4e3e-b2d8-2c166cc2a5c2', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电磁发射控制', '对己方部队各种电磁辐射源的发射活动采取的管理措施。目的是防止敌方通过对己方电磁发射信号的截获和分析来获取有价值的情报。', 95);
INSERT INTO `t_military_term_data` VALUES ('186b8f6a-5e8c-49a1-87b1-9df2476fa9d9', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '军事航天技术', '把航天技术应用于军事领域,为军事目的进入太空和开发、利用太空的综合性工程技术。是军事技术的组成部分。主要是研究、解决把航天技术中的航天器设计与制造技术、航天运输系统设计与制造技术。运载火箭与航天器试验、航天器发射、火箭制导与控制、航天器轨道控制与姿态控制、航天器返回技术、航天测控、航天器信息获取与处理、航天医学工程等工程技术应用于军事领域,并组成不同的军用航天工程系统,完成特定的军事航天任务。', 197);
INSERT INTO `t_military_term_data` VALUES ('186cbcb6-9d33-40da-b4f2-a9bccfbbceb3', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '放射性沉降预报', '对核爆炸后放射性烟云到达时间及其粒子沉降造成的地面放射性沾染的分布、强度所作的预报。是组织大气层核试验、实施核防护和核反击等勤务保障工作的重要内容。', 77);
INSERT INTO `t_military_term_data` VALUES ('18792bd1-b375-4aba-9549-1439b5a63a98', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练讲评', '在训练告一段落或结束时对训练情况所作的评估和小结。通常在现场进行。', 171);
INSERT INTO `t_military_term_data` VALUES ('187d72c9-68d0-403b-9547-ae8ae1ca37b6', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '配合', '各参战力量为保障主要方向或保障担负主要任务的部队,完成共同的作战任务而进行的快同、支援等行动。', 320);
INSERT INTO `t_military_term_data` VALUES ('18859c55-8c16-42af-b225-d1d1aed34f0e', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹技术阵地', '地空导弹部队对导弹进行检测、维护及发射前技术准备等作业的场地。', 98);
INSERT INTO `t_military_term_data` VALUES ('188cbc4c-f679-4be1-bebc-4e811e46a236', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹武器系统', '导弹及其配套的各种设备和设施按技术关系组成的整体。包括导弹及其测试、瞄准、发射和引导设备等。', 1);
INSERT INTO `t_military_term_data` VALUES ('1892cefa-740b-4b84-9fe1-498155f5eb8c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克故障', '坦克因其零、部件功能失常而影响正常使用的现象。按发生时期,分为早期故障、使用期故障和损耗期故障。', 198);
INSERT INTO `t_military_term_data` VALUES ('18965baa-6fb0-4d8b-8c67-8c9a11ee5187', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事欺骗', '在军事斗争中以隐真示假等行动迷惑对方,使之产生错觉和不意。通常与伪装结合进行。按作用范围,分为战略欺骗、战役欺骗和战术欺骗。', 59);
INSERT INTO `t_military_term_data` VALUES ('18982da0-3439-4648-bbaf-9fd10aab0d61', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役突破', '进攻的军队突入敌战役纵深,实现对敌主要防御地带的突破。', 93);
INSERT INTO `t_military_term_data` VALUES ('189f89e8-a2ba-4a19-bd2e-00b557006762', '97a19170-bfac-42c5-9906-1acb187f0654', '拂晓飞行', '从天亮到日出前的时间内实施的飞行。光线微弱,地标模糊,主要依靠机上仪表和飞行导航设备进行。', 222);
INSERT INTO `t_military_term_data` VALUES ('18ad13e5-7392-4c54-a64e-8519db213661', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '人防建设', '人民防空各项建设任务的统称。包括人防组织指挥、人防工程、人防通信、人防警报、人防专业队伍、人防知识教育等方面的建设。', 62);
INSERT INTO `t_military_term_data` VALUES ('18afc138-330b-4896-bd99-93a728ae0ab8', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '履带行军', '乘坐履带车辆的行军。通常用于机械化部队的短距离移动。', 44);
INSERT INTO `t_military_term_data` VALUES ('18afc811-da61-4477-943c-07a7f6857e1b', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '攻城集团', '在城市进攻战役中,担负夺取城市、歼灭守敌任务的兵力集团。', 78);
INSERT INTO `t_military_term_data` VALUES ('18b04b28-22dd-4d81-8768-fb35b9fc07aa', '97a19170-bfac-42c5-9906-1acb187f0654', '运输航空兵', '以运输机为基本装备,遂行空中输送任务的航空兵。主要用以空运人员、装备、物资,保障部队空中机动、空降作战等。', 9);
INSERT INTO `t_military_term_data` VALUES ('18b920e3-9104-490f-b47e-dac3fead379a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '扼守', '军队利用险要地形进行的坚守防御。', 410);
INSERT INTO `t_military_term_data` VALUES ('18c4712f-ab0f-4252-81fe-dc5131728bac', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂云团', '简称毒云。化学袭击后形成的云团状染毒空气。分为毒剂初生云团和毒剂再生云团。毒剂初生云团,简称初生云,是毒剂施放时直接形成的毒云；毒剂再生云团,简称再生云,是染毒的地面和物体上的毒剂自然美发形成的毒云。', 119);
INSERT INTO `t_military_term_data` VALUES ('18d51a98-e517-43ae-8500-9eb903319563', '98df76fb-4b65-48ff-a56c-4db587327c79', '接力运输', '从装载点到卸载点,运用一种或多种运输工具分段接替的运输。', 251);
INSERT INTO `t_military_term_data` VALUES ('18d694ff-64a7-4013-b2c4-02d5b4562031', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '团', '由若干个营编成的军队一级组织。通常隶属于师。设有领导机关,编有战斗和勤务保障分队、为基本战术部队。', 18);
INSERT INTO `t_military_term_data` VALUES ('18e090a6-6f77-4f5b-8db1-9f0b7782da2f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事理论', '关于战争和军队问题的系统化理性认识和知识体系。它产生于军事实践,又给军事实践以指导,并受军事实践的检验。', 9);
INSERT INTO `t_military_term_data` VALUES ('18e6abe3-54fa-41bd-8c38-d997f75f0a19', '8a761efd-50a6-4ac8-9913-b7d745104f82', '火身口', '射弹离开武器的身管或导轨,外始飞向空中的界面。如与火身轴线平直的枪口端面、炮口端面、火箭发射筒端面以及导轨前端面等。', 18);
INSERT INTO `t_military_term_data` VALUES ('18ef3e47-9201-4a70-8fd8-00b612dde05d', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '常行军', '按正常的日行程和时速实施的行军摩托化行军日行程一般为150～250公里·平均时速昼间为20～30公里,夜间为15～20公里；徒步行军日行程一般为25～35公里,平均时速为4～5公里。常行军应按时进行大、小休息、以恢复体力和保养车辆。', 45);
INSERT INTO `t_military_term_data` VALUES ('18f87229-26d1-4c13-bf47-55293d014ee1', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '转移兵力', '变换军队的作战方向或作战地区的行动。其基本要求是适时、迅速、隐蔽。', 334);
INSERT INTO `t_military_term_data` VALUES ('19031fd6-025e-4927-95cc-303b4e672f5e', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备交接', '按照规定履行武器装备的移交和接收手续,改变其隶属关系的活动。', 87);
INSERT INTO `t_military_term_data` VALUES ('190ee720-f946-49e8-853e-b3b0374bfddb', 'd7132c58-5df3-4b97-919f-58740148b9ca', '敌机活动规律', '在一定时限内敌机对某一防区或目标实施侦察和攻击所形成的规律。包括经常使用的机型、架数、高度、时间、进入方向和采用的战术等。', 57);
INSERT INTO `t_military_term_data` VALUES ('191ddded-188f-4ca8-9e03-94ff65297956', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队基层法律服务工作', '中国人民解放军师级以下部队开展的群众性法律咨询和经常性法制教育活动。', 138);
INSERT INTO `t_military_term_data` VALUES ('19218832-56e2-4b57-aaad-8cdaa10925b7', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防雷达伪装', '为降低敌雷达及其制导的武器对目标的探测和命中的概率而实施的伪装。主要包括；利用地形配置目标,设置防雷达遮障和假目标,施放含金属微粒的烟幕和采用隐身技术等。', 339);
INSERT INTO `t_military_term_data` VALUES ('19229912-e8dc-4704-b6c2-121338bb6a57', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '合成军队', '由诸军种或诸兵种编成的军队。也指以一个兵种为主体,同其他兵种及专业兵共同组成的部队、分队,包括营以上的建制单位和作战编组。', 32);
INSERT INTO `t_military_term_data` VALUES ('192e1af3-0e13-4d83-a458-d5579969932b', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战方案评估', '对作战方案进行的评析和估量。主要评估其符合作战目的的程度,作战的效益和风险度的人小,与战场情况变化相适应的程度等。', 192);
INSERT INTO `t_military_term_data` VALUES ('1940aff9-62bb-4be9-b40a-f73407ded099', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '避风港', '可供船舶躲避风浪的港口。一般直接利用有避风条件的天然港湾或建造防波堤而成。', 104);
INSERT INTO `t_military_term_data` VALUES ('1946f03e-1090-4f19-8967-1ee8e861551c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克超越射击', '坦克利用地形或弹道高,使射弹越过己方部队上空进行的直接瞄准射击。实施超越射击时应确保被超越部队的安全。', 52);
INSERT INTO `t_military_term_data` VALUES ('195896fc-c573-40d1-82da-f1e0bade4bed', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队运动', '舰艇编队保持或改变运动状态,组成或变换队形的行动。主要包括：编队抛锚起锚,进出港湾和锚地,编队会合,编队队形变换,编队转向,编队各种机动等。', 258);
INSERT INTO `t_military_term_data` VALUES ('196222c0-c290-429d-a712-f9028c0f3fca', 'd7132c58-5df3-4b97-919f-58740148b9ca', '按综合诸元射击', '由高炮测距机测定空中目标方位角、高低角,炮瞄雷达测定距离,计算仪计算射击诸元而进行的射击。测角、测距均较精确,但易受电子干扰,且受气象条件以及指挥仪与炮瞄雷达配置间隔的影响。', 173);
INSERT INTO `t_military_term_data` VALUES ('19713f40-15c4-41f3-b4d3-b0015c1e3752', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '军事侦察', '简称侦察。为获取军事斗争所需情报而进行的活动。按任务范围,分为战略侦察、战役侦察。战术侦察；按活动空间,分为地面侦察、海上侦察、空中侦察；还可按军兵种和活动方式等区分为各种不同的侦察。', 0);
INSERT INTO `t_military_term_data` VALUES ('1978c6b0-0e75-4b18-8265-baa0b213c57e', '98df76fb-4b65-48ff-a56c-4db587327c79', '特装', '军人执行特种勤务时着用的制式工作服装。如快艇出海服、潜水服、飞行服、跳伞服、高空代偿服、推进剂防护服等。', 149);
INSERT INTO `t_military_term_data` VALUES ('19873e27-0f81-4f6e-a599-e7d900dbf0cc', 'd7132c58-5df3-4b97-919f-58740148b9ca', '手动发射', '地空导弹操作手按规定的操作程序,手动控制实施的发射。', 208);
INSERT INTO `t_military_term_data` VALUES ('199b54a4-e4f3-4856-b436-3a5dbd3db695', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗模拟', '亦称电子对抗仿真。通过模仿电子对抗的实际情况研究电子对抗的方法和技术。有电子对抗信号环境模拟、电子对抗设备功能模拟和电子对抗作战模拟等。主要用以研制、试验电于对抗装备,研究电子对抗战术、技术和训练电子对抗部队。', 16);
INSERT INTO `t_military_term_data` VALUES ('19cbea0d-2709-44b2-8768-147673f215dd', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核武器', '利用能自持进行的原子核裂变或聚变反应瞬时释放的能量产生爆炸作用,并具有大规模杀伤破坏效应的武器的统称。一般由核战斗部及其承载壳体构成。可用导弹、火炮、飞机等发射或投掷。按结构原理,分为原子弹、氢弹和特殊性能核武器；按作战使用范围,分为战略核武器和战术核武器；按配用的武器,分为核导弹、核炸弹、核炮弹、核地雷、核鱼雷和核深水炸弹等。', 83);
INSERT INTO `t_military_term_data` VALUES ('19d4c3e5-109b-4906-8fcb-069a93cd8763', '8a761efd-50a6-4ac8-9913-b7d745104f82', '微声冲锋枪', '射击时只有微弱的声响、火焰和烟雾的冲锋枪。枪管的前段装有消声、消烟、消焰装置。与一般冲锋枪相比，其体积和重量较大，有效射程较近。', 160);
INSERT INTO `t_military_term_data` VALUES ('19d6bc4c-9c3f-4ab3-b3ff-be04203738f7', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹场坪发射', '在预先设置好的地面场坪上进行的导弹发射。场坪发射便于组织实施,但容易暴露、防护能力差。', 115);
INSERT INTO `t_military_term_data` VALUES ('19de7484-8652-45a7-8789-e885373cb789', '98df76fb-4b65-48ff-a56c-4db587327c79', '联勤', '在统一领导下,按统一的制度和标准,诸军种间联合组织部分或全部的后勤保障。是军队后勤保障体制的一种类型。', 7);
INSERT INTO `t_military_term_data` VALUES ('19f0f493-2082-4d5f-816f-0d571fd84ef6', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '野战装备', '能伴随部队或分队运动和作战的装备。相对于固定装备而言。一般分为自行式、牵引式、车载式、马驮式、携带式等野战装备。', 83);
INSERT INTO `t_military_term_data` VALUES ('1a0bc230-89b5-4a2d-9c5c-8eb8c43cbb7b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '物资准备', '为实施战争和保障武装力量作战而在物资方面进行的准备。包括物资的生产、筹集、补充和储备等。', 160);
INSERT INTO `t_military_term_data` VALUES ('1a0cf7ae-7e90-4927-a8ae-98156edc5b96', 'f0140091-c11a-48c9-8836-8aa94439dac0', '第二阵地', ' 师防御地区内由第一梯队团的第二梯队步兵营或坦克营防御地域,或团预备队占领的地域所组成的阵地。用以阻止敌人向纵深扩张或作为反冲击的依托,有时也可作为防御的主要阵地。', 220);
INSERT INTO `t_military_term_data` VALUES ('1a0fcf49-4ae3-41d3-9091-c00bc9220708', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事哲学', '关于军事方面的世界观和方法论的学说。主要是用哲学的基本原理认识与考察军事问题,并揭示军事领域内各种运动形式的主客观因素相互联系及其转化的一般规律。', 21);
INSERT INTO `t_military_term_data` VALUES ('1a10b582-ce15-4f54-bd71-f4a0fb1b3337', '97a19170-bfac-42c5-9906-1acb187f0654', '超高空飞行', '航空器在真实高度为15000米以上的飞行。', 234);
INSERT INTO `t_military_term_data` VALUES ('1a20fa48-b0c7-4569-8c70-f72e4797281d', '97a19170-bfac-42c5-9906-1acb187f0654', '空降兵', '以降落伞和陆战兵器为基本装备、航空器为输送工具,主要遂行伞降和机降作战任务的空军兵种。有的国家将其列入陆军兵种。通常用以空降到重要目标或地域,突袭敌方的部队、指挥机构、重要军事设施和后方供应系统,以及支援己方在敌后作战的部队和游击队等。', 26);
INSERT INTO `t_military_term_data` VALUES ('1a36f40d-4ae2-4240-b869-fa69561d7812', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '步测', '用步幅量测距离。通常以复步为单位进行实地量测,一般1复步长为1.5米。', 152);
INSERT INTO `t_military_term_data` VALUES ('1a385e8f-f317-4b94-8708-140c2e404fe4', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '单兵伪装器材', '用于单个人员伪装的器材。分为制式单兵伪装器材和就便单兵伪装器材。包括伪装服、单兵伪装网、涂肤油膏及其他就便材料。', 356);
INSERT INTO `t_military_term_data` VALUES ('1a4a8776-7249-49aa-b4ff-ab9dd09fa9d9', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击诸元', '高炮射击时使用的目标提前位置的方位角、射角和引信分划等数值的统称。', 160);
INSERT INTO `t_military_term_data` VALUES ('1a4de0dd-cb57-4095-8960-0b23d5f1d972', '8a761efd-50a6-4ac8-9913-b7d745104f82', '迟发火', '射击武器在射击过程中,击针正常击中底火后发火时间延迟的射击故障。', 139);
INSERT INTO `t_military_term_data` VALUES ('1a5045f1-ea4b-482a-9ed9-c7411ff038e7', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '登陆作战舰艇', '亦称两栖作战舰艇。专门用以输送登陆兵、登陆工具、战斗车辆、武器装备和物资,实施由岸到岸或由舰到岸的登陆作战的舰艇。包括登陆舰艇、船坞登陆舰、两栖船坞运输舰、两栖攻击舰、两栖火力支援舰、通用两栖攻击舰和两栖指挥舰等。', 129);
INSERT INTO `t_military_term_data` VALUES ('1a59d55a-8129-42ce-a5b2-817de6834350', '878651de-adf5-4c72-9376-9c363b893ff8', '战争根源', '战争现象产生的根本社会缘由。存在于阶级、民族、政治集团、国家之间政治、经济利益的对抗性矛盾之中。帝国主义、霸权主义是现代战争的主要根源。', 3);
INSERT INTO `t_military_term_data` VALUES ('1a5f0dae-ca98-4640-9615-c0e649954fad', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵火力控制点', '简称火控点。预先计算出射击诸元,以备对运动目标或临时出现的目标迅速实施转移射的明显地物、特殊地形点或虚设点。分为实有火控点和虚设火控点。', 217);
INSERT INTO `t_military_term_data` VALUES ('1a621aae-dc7b-4924-a02a-56bbe8242a64', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '屋顶起降', '直升机或垂直起落飞机在大型建筑物的顶部平台进行的起飞和降落。', 42);
INSERT INTO `t_military_term_data` VALUES ('1a66e4d9-9c6e-4b6f-99e9-45060cb83448', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '军事工程', '用于军事目的的各种工程建筑和为保障军队作战行动而采取的其他工程技术措施的统称。工程建筑包括：军事工程建筑物和构筑物,建筑过程中的工程侦察、勘测、设计、施工、维护等技术活动。其他工程技术措施包括：布雷,排雷,破坏作业,克服障碍物,漕渡,工程伪装以及野战给水中的非建筑性工程技术措施等。', 25);
INSERT INTO `t_military_term_data` VALUES ('1a6fc719-717f-4123-98da-3175ab9e4c2d', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥文书', '用以组织指挥部队作战或其他行动的军用文书包括命令通令指示、计划、通知通报批复等。', 112);
INSERT INTO `t_military_term_data` VALUES ('1a79fb15-0c5c-468a-bf50-8a507253f48f', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克发射点', '坦克在掩体内或利用地形进行原地射击构成的火力点。', 37);
INSERT INTO `t_military_term_data` VALUES ('1a7b0ff8-9a9b-4b45-bcc1-1231e8811fb3', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机装载', '将物资装进直升机舱内的行动。要求严格按舱内划定的标线安放物资。', 13);
INSERT INTO `t_military_term_data` VALUES ('1a8b9abc-5d0d-44ca-b598-627c2caa5c71', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程保障建议', '合成军队司令部的工程兵部门,为合成军队首长定下决心而提供的组织与实施工程保障的建议。主要包括：需要采取的工程措施,工程作业任务区分及开始和完成的时限,工程兵运用,工程器材保障等。', 13);
INSERT INTO `t_military_term_data` VALUES ('1a9c055b-b013-4397-b023-89ff3e5ba259', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上搜索', '海军兵力对指定海区进行的搜索。分为对空搜索、对水面搜索和对水下搜索。目的是查明可疑目标,监视敌情,寻找失事和迷航舰船,营救落水人员等。', 56);
INSERT INTO `t_military_term_data` VALUES ('1a9c6b2c-953e-41d5-b2a8-15566de3b142', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '野战军', '①中国人民解放军曾用的对遂行全国机动作战任务的陆军部队的称谓。相对于地方军而言。有时亦指陆军的军。②中国人民解放战争时期,人民解放军中担负机动作战任务的战略战役军团。为作战部队最高一级建制单位。由若于个兵团或军组成。隶属于中央军委。如第一、二、三、四野战军,华北野战军等。', 16);
INSERT INTO `t_military_term_data` VALUES ('1a9cbb4a-e182-4fe5-844c-643b5f9bfa5e', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '双拥工作', '中国人民解放军开展的拥政爱民工作和地方政府、人民群众开展的拥军优属工作的统称。', 121);
INSERT INTO `t_military_term_data` VALUES ('1aa70319-cb79-4e7a-9491-1dd587ab001a', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹道要素', '构成外弹道质心运动轨迹的各种因素。主要有起点、火身口水平面、射线、射角、射面、发射线、发射角、发射差角、弹道最高点、最大弹道高、弹道高、落角、升弧、降弧、射程等。', 17);
INSERT INTO `t_military_term_data` VALUES ('1aa96914-f97e-47ff-8500-1f21e4334e9f', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '通信技术', '研制、使用通信设施的技术。主要包括无线电通信、有线电通信、光通信和卫星通信等技术。现代通信技术向数字化、高速度、大容量和综合化的方向发展。对保障军队作战指挥具有重要作用。', 20);
INSERT INTO `t_military_term_data` VALUES ('1aae99a9-ebe4-4af7-b842-ad01fe89bb56', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹技术准备', '为发射阵地提供合格导弹而进行的装配、检查和测试等各项技术准备工作的统称。分为导弹弹头技术准备和导弹弹体技术准备。有的导弹在完成弹头和弹体技术准备后,还需进行弹头与弹体结合和综合测试。', 130);
INSERT INTO `t_military_term_data` VALUES ('1abf1a58-6ba5-486b-bd1a-b4b5b718239f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜水装具', '潜水员潜水作业时使用的服装和器具的统称。包括非抗压潜水装具又分为重潜水装具和轻潜水装具。', 249);
INSERT INTO `t_military_term_data` VALUES ('1ad3fc0d-e994-4bdd-bf9e-9dd0dd7678f6', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '卫星制导', '利用接收卫星发出的信号进行的制导。分为有源和无源两种。其中无源的较为隐蔽,抗干扰性能强。', 44);
INSERT INTO `t_military_term_data` VALUES ('1aec0572-ab26-413f-8346-8647529ca39c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克射击地境', '防御战斗中给单辆坦克规定的扇形射击地域。分为基本射击地境和补加射击地境。通常以坦克所在位置为起点,利用前方2～4个方位物确定；夜间以炮塔分划的数值确定。', 47);
INSERT INTO `t_military_term_data` VALUES ('1b125a88-9a58-435d-b517-abbb776ba1cf', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '制海权', '作战中,在一定时间内对一定海域的。控制权。现代战争中,制海权依赖于相应的制空权来保障。', 355);
INSERT INTO `t_military_term_data` VALUES ('1b1fee97-2179-40d0-91cb-1645615cf5ef', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克机动性能', '坦克在战斗全重和一定环境条件下运动时所具有的特性与功能。包括直线行驶快速性、转向灵活性、越野通过性和最大行程,有时也包括可运输性。水陆坦克除陆地机动性能外,还具有水上机动性能。', 156);
INSERT INTO `t_military_term_data` VALUES ('1b23d173-f7d3-4344-ae5b-97a396815973', '97a19170-bfac-42c5-9906-1acb187f0654', '空中接敌', '空战的准备阶段。自飞机发现目标起至飞机占据有利的攻击起始位置止。主要进行空中占位活动。', 76);
INSERT INTO `t_military_term_data` VALUES ('1b24264e-ad72-4ae0-a03e-b040dc2dccf4', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军备竞赛', '国家或政治集团之间竟相扩充军备的活动。', 87);
INSERT INTO `t_military_term_data` VALUES ('1b2860c1-154d-4d71-9f4c-133be124c1dc', 'f0140091-c11a-48c9-8836-8aa94439dac0', '斜射火力', '射击方向与目标正面成锐角的火力。', 86);
INSERT INTO `t_military_term_data` VALUES ('1b2928d3-304c-444b-a9f3-67ca40e98f5c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '通信网台识别', '对敌方通信网台的性质、级别和隶属关系的分析鉴别。主要根据敌方无线电通信信号的特征参数、通联规律和工作特点等判明,以确定干扰优先等级,合理分配现有通信干扰资源。', 32);
INSERT INTO `t_military_term_data` VALUES ('1b3c71a0-f8b8-42df-b6b2-c75243b0ff28', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵战斗转场', '航空兵部队为执行作战任务向预定机场实施机动。通常在调整作战部署时进行。战斗转场时一般编有先遣队、飞行梯队、地面梯队及空运梯队等。', 67);
INSERT INTO `t_military_term_data` VALUES ('1b3e9d67-daa0-474d-9c76-e2d17bee8595', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击技术准备', '炮兵射击前消除火炮、器材因技术条件和阵地设置不同而产生的偏差量的工作。主要包括：检查并规正火炮瞄准装置、观测器材和射击指挥作业器材,确定火炮瞄准线偏移和表尺射角对象限仪射角不一致的偏差,决定火炮单独修正量等。', 135);
INSERT INTO `t_military_term_data` VALUES ('1b488028-5e83-4592-88e5-d38e5c61f50c', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备配套', '武器装备按照作战使用和技术标准的要求编配完整成套。包括技术配套和战术配套。技术配套是指武器装备按照技术标准的要求编配完整齐全。如单件和成套装备中,装备部件完整,附件、器材、装具、牵引车辆等配备齐全、战术配套是指武器装备按照作战要求能互相配合,成套编配。如反坦克武器中,有对远、中、近距离装甲目标射击的各种反坦克武器等。', 85);
INSERT INTO `t_military_term_data` VALUES ('1b4f86c9-637e-4eba-95bd-d529a43a1902', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役容量', '战役作战地区所能容纳的展开兵力的最大数量。其大小主要取决于战役作战地区的幅员、地形、经济、交通等情况。', 27);
INSERT INTO `t_military_term_data` VALUES ('1b56df91-0594-4458-865c-d5778d7f99ba', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '交通工事', '供人员、装备在阵地间和工事间隐蔽机动及运送物资、伤员的工事。包括交通壕和暗道。', 47);
INSERT INTO `t_military_term_data` VALUES ('1b576478-9ece-4cd4-b45d-b9dffb566f57', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵拦阻射击', '炮兵在选定的阻击点或阻击线上拦击运动目标实施的射击。主要用以打乱敌运动队形,迟滞其行动,妨碍其射击。毁歼其一部,为直瞄火器歼敌创造有利条件。', 182);
INSERT INTO `t_military_term_data` VALUES ('1b5c5c34-a7b8-492e-99cf-4fd6b3c81e73', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '有源电子干扰', '简称有源干扰,亦称积极干扰。通过发射或转发电磁信号对敌方电子设备进行压制或欺骗的电子干扰。可广泛用于对雷达、无线电通信、制导、导航、光电等电子设备的干扰。', 43);
INSERT INTO `t_military_term_data` VALUES ('1b6e0442-0282-415e-9ac3-e2c399a6246f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事援助', '国家或政治集团之间根据受援方的要求而提供的军事上的支援活动。分为有偿援助和无偿援助。包括提供军事贷款、修建军事工程、供应武器装备、训练军事人员、派出部队或人员参战等。', 82);
INSERT INTO `t_military_term_data` VALUES ('1b7faef4-c2f9-4e2b-ab3f-bc3eed3014d0', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '假定高程', '亦称相对高程。由任一水准面起算的地面点高程。当测区内无国家水准点时,可以某一点的高程为起算值,以测定其他各点的高程。', 171);
INSERT INTO `t_military_term_data` VALUES ('1b85dfa1-d017-48c3-94f6-79dbb5207680', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '冲击波弹', '亦称减少剩余放射性弹。简称RRR弹（按英文缩写）。以冲击波效应为主要杀伤破坏因素的特殊性能核武器。主要用以摧毁坚固的军事目标。其爆炸时产生的放射性沉降较少。', 96);
INSERT INTO `t_military_term_data` VALUES ('1b91aa99-8abb-49d5-ab2c-dc8a44abeeff', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '飞行器', '可在大气层内或太空飞行的人造物体。主要包括：航空器（如气球、飞艇、飞机、滑翔机、直升机等）,航天器（如人造地球卫星、载人飞船、航天飞机等）,火箭和导弹。', 202);
INSERT INTO `t_military_term_data` VALUES ('1b929731-2b55-4acb-a361-6dac2ccc7ff1', '8a761efd-50a6-4ac8-9913-b7d745104f82', '班用机枪', '通常编配在步兵班内的轻机枪。如1981年式7.62毫米班用机枪,全重5.1千克，初速735米/秒,容弹量75发,战斗射速80一150发／分，有效射程600米。', 168);
INSERT INTO `t_military_term_data` VALUES ('1b9884a1-f1ed-4a2d-865d-a749aaa84700', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战区战役', '①由战区的全部或大部武装力量进行的战役。②两个以上战区的武装力量在某一战区的统一指挥下共同进行的战役。', 10);
INSERT INTO `t_military_term_data` VALUES ('1ba44089-427a-4025-9210-6e7818859417', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '联络参谋', '担任联络工作的参谋人员、主要负责上下级单位之间、友邻部队之间、支援单位与被支援单位之间、友军之间等的联络文作', 44);
INSERT INTO `t_military_term_data` VALUES ('1ba85417-dd7f-4c9f-a9d1-ac65fc3b9dc7', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '测绘数据库', '储存有测量成果和地图诸要素的数据库。主要包括：大地测量数据库,重力数据库,摄影测量数据库,地形测量数据库,地图数据库和地名数据库等。用于测绘成果的集中管理和保存,数据的快速查询和提供,以及计算机地图制图等。', 291);
INSERT INTO `t_military_term_data` VALUES ('1bb1f05b-c4c0-4ef7-8518-3dff2cdfab1a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '试射成果射角', '试射结束时所获得的射角。是使射弹散布中心通过目标或试射点的射角。其值等于高角、炮目高低角与高角修正量之和。', 159);
INSERT INTO `t_military_term_data` VALUES ('1bb43486-9652-4e0a-a608-6c9e45800f35', 'f0140091-c11a-48c9-8836-8aa94439dac0', '街垒战斗', '攻占或扼守街垒的战斗行动。', 16);
INSERT INTO `t_military_term_data` VALUES ('1bb879c6-a300-4779-a53e-50baea20063f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '隧道', '建造在山岭、河道、海峡及城市地面以下的孔道。供车辆、行人、水流、管线等通过,或供采矿等工程作业使用。有铁路隧道、公路隧道、海底隧道等。', 109);
INSERT INTO `t_military_term_data` VALUES ('1bb94406-07e6-4113-bbbe-e33cf3d91f82', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '抵抗', '抵御抗击外来的武装侵略或抵御抗击敌军进攻的作战行动。', 404);
INSERT INTO `t_military_term_data` VALUES ('1bc01889-6be8-43cb-9c7f-f39d49083ef7', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '固体火箭', '用固体火箭发动机作动力装置的火箭。结构简单,维护使用方便,发射准备的时间短,但推力调节和多次启动困难。', 69);
INSERT INTO `t_military_term_data` VALUES ('1bc1bc70-5da7-4893-bfa2-0a25842bdcff', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '反卫星导弹', '用以攻击人造地球卫星或其他航天器的导弹。可从陆地或空中和外层空间的飞行器上发射。', 13);
INSERT INTO `t_military_term_data` VALUES ('1bc931e6-3357-48a5-b78b-6f9272bfe896', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '电化教学', '使用电的教学设备进行的教学。主要通过幻灯、录音、广播、电视、录像设备和电子计算机等手段进行。', 156);
INSERT INTO `t_military_term_data` VALUES ('1bc94453-7686-410f-8364-994389837e55', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程装备', '军队专门用于工程保障的装备。主要包括：工程侦察器材,军用工程机械,渡河桥梁器材,路面器材,地雷战和反地雷战器材,陆军水雷和空飘雷,爆破器材,工程伪装器材,野战给水器材,成套野战工事构件,移动式非爆炸性障碍器材,电工器材和工具等。', 34);
INSERT INTO `t_military_term_data` VALUES ('1bce3451-6db9-443e-a81c-01d6369f192c', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射动力', '使导弹飞离发射装置的原动力。常用的导弹发射动力有自力、外力和导弹自重力。自力是指由导弹发动机或火箭助推器在发射装置上直接点火产生的推力；外力是指由发射装置的弹射系统提供的导弹发射动力；自重力是指导弹脱离运载体（如飞机）的挂弹装置的重力。', 112);
INSERT INTO `t_military_term_data` VALUES ('1bd80237-acb0-4297-be8e-9fd557362836', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '连续爆破', '依照一定顺序对单个或多个目标实施的不间断或轮番的爆破。', 246);
INSERT INTO `t_military_term_data` VALUES ('1bf125be-48d5-48fd-881f-0aa6a60ba728', 'f0140091-c11a-48c9-8836-8aa94439dac0', '荒漠草原地战斗', '在沙漠、戈壁、草原地区进行的战斗。便于部队机动、观察和发扬火力,但不便于隐蔽、伪装和防护,武器装备易磨损,保障困难。', 8);
INSERT INTO `t_military_term_data` VALUES ('1bf6c54b-f955-40f6-9230-9a3003c7cb2d', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '专职人民武装干部', '简称专职人武干部。在乡镇、大中型企业和事业单位的人民武装部内,专门从事民兵、兵役等工作的地方干部。', 130);
INSERT INTO `t_military_term_data` VALUES ('1bf8a3e9-0151-47f7-86ad-fa65dcf63bcb', '8a761efd-50a6-4ac8-9913-b7d745104f82', '膛炸', '射击武器击发后,弹丸在膛内爆炸或弹丸在膛内受阻使身管损坏的射击故障。', 127);
INSERT INTO `t_military_term_data` VALUES ('1bfd552f-a60c-455d-86a3-f89fa3c5358a', '98df76fb-4b65-48ff-a56c-4db587327c79', '物资委托加工', '军队委托地方企业生产军用产品。通常由军队提出产品的生产技术要求和验收标准,提供必要的原材料,经济合同方式与企业建立供需关系,获得所需产品。', 104);
INSERT INTO `t_military_term_data` VALUES ('1c072e5e-866b-4d54-a5ba-c4e1e543252d', '916997ee-6728-4c61-9b79-d96960b1dc86', '个人防护器材', '亦称个人三防器材。用于个人免受毒剂、生物战剂和放射性落下灰等伤害的防护器材。主要包括：防毒面具、防毒衣（服）、防毒斗篷、防毒手套、防毒靴套,以及个人使用的剂量仪、侦毒纸、消毒急救盒等。', 171);
INSERT INTO `t_military_term_data` VALUES ('1c082e42-30f7-4cc2-b0e7-0523fe6ee620', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '舟桥部队', '工程兵中担负渡河工程保障任务的专业部队。装备有舟桥和机械化桥等。主要负责构筑和维护门桥、浮桥渡场,有时也负责架设低水桥和水面下桥等。', 4);
INSERT INTO `t_military_term_data` VALUES ('1c085da8-a777-4fd9-8030-abbd9d3f7788', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机中队编队', '直升机中队建制内的3～4架直升机按规定组成的空中编队。', 34);
INSERT INTO `t_military_term_data` VALUES ('1c11c704-38ba-4b28-b359-332ebc932fc5', '06a75831-13a1-4660-870a-455bb445336a', '电报等级', '电报急缓程度的区分。通常分为特急、加急、急3个等级。由签发的首长确定。电台、电报站根据电报等级安排电报拍发次序。', 137);
INSERT INTO `t_military_term_data` VALUES ('1c187ac5-e6c9-4563-a09b-7da82ddb775e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵侦察地带', '炮兵侦察分队负责侦察的地带。通常包括基本侦察地带和补加侦察地带。一般大于本级炮兵的射击地带和战斗纵深。相邻的炮兵侦察地带应有一定的重叠。', 107);
INSERT INTO `t_military_term_data` VALUES ('1c28d1bb-0c43-47e5-b776-8cf74d218100', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '计算机地图制图', '利用电子计算机制图系统进行地图制图的技术与方法。具有提高地图信息的采集、存储、处理、管理、显示、绘图和制版的作业速度与精度,缩短成图周期、扩大地图使用范围等功能。', 290);
INSERT INTO `t_military_term_data` VALUES ('1c2b663a-f900-4f80-93f0-9230d2302663', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核战斗部', '核武器中起杀伤破坏作用的组成部分。由核装置和引爆控制系统等组成。在不同类型的核武器中,核战斗部的组装形式、安装部位有所不同。', 124);
INSERT INTO `t_military_term_data` VALUES ('1c34faf5-aaca-45a2-8402-f05768d13a73', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵战术', '炮兵进行战斗的方法。主要包括炮兵战斗基本原则、兵力部署、战斗指挥、人力运用、协同动作及各种保障措施等。分为炮兵部队战术和炮兵分队战术。', 38);
INSERT INTO `t_military_term_data` VALUES ('1c43bed0-886c-4f68-bf23-8de0da36454d', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆保养', '对军用车辆进行的清洁、检查、调整、紧定和润滑等技术工作的统称。通常分为日常保养。定期保养、停驶车保养、初驶保养、换季保养等。', 311);
INSERT INTO `t_military_term_data` VALUES ('1c497cca-4d89-4fb4-af93-03df865ec1e1', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '医院船', '专门用以在海上收容、医治并运送伤病员和遇难人员的非武装勤务舰船。按国际法规定：船体水线以上涂成白色,标有红十字（红新月或红狮与日）；悬挂本国国旗,并在桅杆上悬挂白底红十字旗。', 151);
INSERT INTO `t_military_term_data` VALUES ('1c4dc288-4c5a-46c8-8633-6eba7ea13058', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队政法工作', '中国人民解放军内部运用法律手段,防范与打击军内违法犯罪活动和境内外敌对势力、敌对分子对军队的渗透破坏活动,以及保障军人合法权益的工作。主要包括军队保卫工作、军事审判工作、军事检察工作和军队司法行政工作等。', 130);
INSERT INTO `t_military_term_data` VALUES ('1c653752-ba53-4df2-b7f9-9718ed5e2852', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气候预测', '亦称气候趋势预测。对一定地区未来1个月以上可能出现的大气过程和气候状况所作的预测。其中,预测时效为1～12个月的称短期气候预测；12个月以上的称气候预测。军队气象部门通常根据军事任务的需要发布专项气候预测。', 73);
INSERT INTO `t_military_term_data` VALUES ('1c6cf23e-cb84-45a6-a33e-7a9fa14435e6', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射角', '射线与火身口水平面的夹角。是瞄准角与高低角的代数和。', 22);
INSERT INTO `t_military_term_data` VALUES ('1c6ea3fc-1a2f-4e5b-92f8-07254d505d7c', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '警卫哨', '担负警戒保卫任务的哨兵。任务是保障重要的机构、设施和人员等警卫目标的安全。', 27);
INSERT INTO `t_military_term_data` VALUES ('1c726941-87df-4dd7-9e98-54ab6f519bde', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '学生军训', '地方高等院校和高级中学的在校学生,依照国家兵役法的有关规定,接受军事基础理论教育和基本军事技能训练的活动。', 140);
INSERT INTO `t_military_term_data` VALUES ('1c78f72d-e5cd-4c7a-a9bc-8c256e033353', '916997ee-6728-4c61-9b79-d96960b1dc86', '喷火器', '亦称火焰喷射器。喷射火焰射流的燃烧武器。有便携式和车载式两种类型。用以攻击火力点,消灭工事、建筑物和洞穴内的有生力量,抗击冲击的集群步兵等。', 235);
INSERT INTO `t_military_term_data` VALUES ('1c79aa02-27ed-48cf-9a8c-3cdf4c630c68', '97a19170-bfac-42c5-9906-1acb187f0654', '导航台站', '设置在地面,装备有飞行导航设施的各种飞行导航机构的统称。主要包括；中波导航站、超短波定向台。导航台,精密进场雷达站,航向信标台,下滑信标台等。', 362);
INSERT INTO `t_military_term_data` VALUES ('1c9a8605-2976-4035-a945-23e95423da10', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '小比高空爆', '比高在120米/根号3下的千吨TNT当量以下的空中核爆炸。能破坏地面和浅地下的较坚固目标。', 150);
INSERT INTO `t_military_term_data` VALUES ('1c9b768b-243e-4a1f-bc38-2037c9f1678d', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境封锁', '亦称边界封锁。以军事或行政手段断绝边境地区同境外或内地的各种联系的行动。是边界控制的一种措施。包括关闭边境口岸、港口等。', 117);
INSERT INTO `t_military_term_data` VALUES ('1c9f4555-079f-4534-bb90-1b95514ad98a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察训练', '为使指挥员、参谋人员和部队掌握组织、实施侦察所需的知识与技能而进行的训练。主要训练内容包括：组织实施侦察的基本原则,侦察方式与手段的运用,对情况的分析判断,外军知识等。', 85);
INSERT INTO `t_military_term_data` VALUES ('1cb82132-a130-42ff-9e06-88ab1bb76fc5', '98df76fb-4b65-48ff-a56c-4db587327c79', '军队财务保障', '军队后勤机构在经费方面实施的保障。主要内容包括：制订财务保障方案或计划,请领、分配、划拨和支付经费,实施财务核算和财务监督,清理和结算经费等。', 72);
INSERT INTO `t_military_term_data` VALUES ('1cb9544d-b045-47e6-b857-1323c107d429', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军通信保障', '海军为遂行作战和其他任务在通信联络方面进行的保障。由海军各级司令部组织实施。内容包括组织直接或越级指挥通信、协同通信、报知通信、海上遇险通信和日常通信。', 357);
INSERT INTO `t_military_term_data` VALUES ('1cc303aa-1d56-49e5-94ca-0b588d719053', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '岸舰导弹', '亦称岸防导弹或海岸导弹。从岸上发射,用以攻击水面舰船的导弹。按发射装置,分为固定式岸舰导弹和机动式岸舰导弹；按射程,分为近程岸舰导弹、中程岸舰导弹和远程岸舰导弹。', 188);
INSERT INTO `t_military_term_data` VALUES ('1ccedfd0-33a5-472b-958d-231f14b6c036', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '登陆队形', '登陆兵搭乘登陆工具向敌岸接近和抢滩上陆时的队形。', 67);
INSERT INTO `t_military_term_data` VALUES ('1cd2cb19-0111-4cc1-a8f1-6bc7f7ebdac8', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '装（卸）载', '被输送单位的人员登上（离开）输送工具和将装备、物资装上（卸下）输送工具的行动。', 88);
INSERT INTO `t_military_term_data` VALUES ('1cd758ec-07ac-4479-8ba7-39415eb7d213', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇航迹', '舰艇航行时投影在海底的运动轨迹。在海图上为若干实测的精确舰位的连线。', 271);
INSERT INTO `t_military_term_data` VALUES ('1ce1806a-01a5-4b27-a309-7f0f49af3610', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹药自毁装置', '为了安全或其他原因,能使射弹在落地后或在一定时间内自行炸毁或销毁的弹内装置。', 124);
INSERT INTO `t_military_term_data` VALUES ('1ce883f4-0134-4e8d-ae64-7121da8e154d', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '空运梯队', '空中输送时按行动顺序编组的梯队。', 83);
INSERT INTO `t_military_term_data` VALUES ('1ce936c4-6a99-4d70-8e68-55d5317bb3d5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇水下逗留时间', '潜艇满载潜入水中后,在与大气隔绝的条件下保证艇员正常呼吸所能持续的最长时间。', 300);
INSERT INTO `t_military_term_data` VALUES ('1cea10ab-48fb-4496-9235-fceccc023f0c', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备维修', '为保持和恢复武器装备的良好技术性能而进行的维护和修理。一般分为大修、中修和小修。', 120);
INSERT INTO `t_military_term_data` VALUES ('1cef4ad1-d2ed-41a7-9563-5d610436a7c6', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵核反击战役', '第二炮兵战役军团为达成特定的战略目的或战略性战役目的,按照统一的计划和高度集中的指挥实施的若干次核突击的作战行动。', 29);
INSERT INTO `t_military_term_data` VALUES ('1d0201f5-b509-4ae0-abb3-2d3cab431f13', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '无线电侦收', '使用无线电收信器材接收敌方无线电通信信号,从中获取情报的方法。', 57);
INSERT INTO `t_military_term_data` VALUES ('1d024a10-11f3-4090-bb73-b85069ce98e3', 'f0140091-c11a-48c9-8836-8aa94439dac0', '冲击', '步兵或伞兵、坦克等快速冲向攻击目标的战斗行动。通常以火力、格斗和装甲战斗车辆碾压与冲撞等手段消灭敌人。', 181);
INSERT INTO `t_military_term_data` VALUES ('1d02c222-4b85-4fda-ac7d-ebf56f220a2d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空雷达部署', '根据上级赋予的雷达保障任务,对雷达部队或分队的兵力、兵器进行的部署。包括任务区分和确定配置位置。基本形式有集团部署和线状部署。', 116);
INSERT INTO `t_military_term_data` VALUES ('1d053d9d-701c-4b06-bae2-a6ef36f54105', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '示范', '以规范的动作和正确的组织实施方法,供观摩、仿效的教学活动。', 149);
INSERT INTO `t_military_term_data` VALUES ('1d09e3df-248c-4046-90cd-e73f1ee4ad49', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上佯动', '海军兵力在海上制造假象以欺骗和迷惑敌人的作战行动。分为海上兵力佯动、海上火力佯动和海上无线电佯动等。', 40);
INSERT INTO `t_military_term_data` VALUES ('1d115d81-b972-4d0c-8680-29d39bbe5758', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇雷达', '亦称舰载雷达。装备在舰艇上用以探测、跟踪海面和空中目标的各种雷达的统称。包括警戒雷达、火控雷达、多功能雷达、航海雷达、舰载机引导雷达,以及舰艇雷达敌我识别器等。', 227);
INSERT INTO `t_military_term_data` VALUES ('1d16ee15-0dbc-4e70-8a1a-e4862fa06b50', 'f0140091-c11a-48c9-8836-8aa94439dac0', '登陆冲击', '登陆兵抢滩上陆时为夺占滩头阵地实施的冲击。包括登陆分队乘登陆工具通过登陆冲击出发线,抵达敌岸和向陆上预定目标的冲击。', 186);
INSERT INTO `t_military_term_data` VALUES ('1d253407-b030-445c-94ea-961823702c0f', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '岛屿进攻战役', '对据守岛屿之敌实施的进攻战役。', 58);
INSERT INTO `t_military_term_data` VALUES ('1d2a2910-e451-4b7d-899d-f0dfe6680545', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '信息战', '敌对双方在信息领域的对抗活动。主要是通过争夺信息资源,掌握信息的生产、传递、处理等的主动权,破坏敌方信息传输,为遏制或打赢战争创造有利的条件。', 145);
INSERT INTO `t_military_term_data` VALUES ('1d34accb-ccff-464a-bb4a-dd8945ffcf5e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '受领任务', '亦称接受任务、下级接受上级赋予江务、须准确领会任务的性质、内容与要求。', 63);
INSERT INTO `t_military_term_data` VALUES ('1d5c8993-135f-4c12-846a-5d850f8d0307', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '参训率', '实际参加训练的单位数或人数与编制的单位数或单位的实力数的比值。通常用百分比表示。', 44);
INSERT INTO `t_military_term_data` VALUES ('1d5e1357-8de1-42e8-b531-6832e031c1db', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练验收', '上级或主管部门按训练标准对下属单位或人员的训练进行的检验和认可。', 174);
INSERT INTO `t_military_term_data` VALUES ('1d627165-6df7-4d86-aaa4-7631116475c3', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克测距仪', '坦克上测定目标距离的光电仪器。有光学测距仪和激光测距仪两类。', 121);
INSERT INTO `t_military_term_data` VALUES ('1d685d93-2fdf-4fd8-8d53-fe4c208d87e2', '8a761efd-50a6-4ac8-9913-b7d745104f82', '指幅', '手指的宽度。用于测角。当手臂伸出到距眼50厘米时,相应的密位数约为；拇指00－40,食指00-35,中指00－35,无名指 00－30,小指 00－25。', 84);
INSERT INTO `t_military_term_data` VALUES ('1d824bf3-c93c-4118-a101-867bddb869ba', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵通信保障', '第二炮兵为遂行作战、训练等任务而在通信联络方面进行的保障。包括在指挥、协同、预警以及后勤和装备技术等方面的通信联络保障。', 189);
INSERT INTO `t_military_term_data` VALUES ('1d8846c3-3f28-4abe-9b92-1028d499e13c', '98df76fb-4b65-48ff-a56c-4db587327c79', '军运备品', '国家交通运输部门为保障军事运输需要而专门制造和储备的各种器材和用品的统称。主要包括活动装卸设备、捆绑加固器材、装卸用具用料和军用代客车备品等。', 270);
INSERT INTO `t_military_term_data` VALUES ('1d8870e9-32b5-49e4-9fd6-86a7da7929de', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击时间', '空中目标一次飞越高炮有效射击范围,高炮能够对其射击的全部时间。', 148);
INSERT INTO `t_military_term_data` VALUES ('1da08c63-878e-4642-be8b-da2b61ee4d9b', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '侧卫', '位于行军纵队侧方,担负侧方警戒和护卫任务的部队或分队。', 12);
INSERT INTO `t_military_term_data` VALUES ('1dbd18de-c2b3-462f-be34-d830f014b9f4', '97a19170-bfac-42c5-9906-1acb187f0654', '空降出发地区', '空降部队集结、乘载航空器和起飞的地区的统称。包括集结地区、待运地区、航空器的起降场等。', 161);
INSERT INTO `t_military_term_data` VALUES ('1dca9e3f-a306-4674-a289-281265710a1d', 'f0140091-c11a-48c9-8836-8aa94439dac0', '远战火力', '远战火器发射的火力。通常包括各种压制火炮、战役战术导弹等所发射的火力。', 92);
INSERT INTO `t_military_term_data` VALUES ('1dcfa918-df94-4f78-b1af-9d268029ba9d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军合同训练', '海军两个以上兵种进行的以合同作战的组织指挥和协同动作为主要内容的训练。包括海军合同战术训练和海军合同战役训练。', 313);
INSERT INTO `t_military_term_data` VALUES ('1ddea861-6308-474e-ab7b-b6e84fed3a63', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '警戒信号', '警戒分队或人员报知紧急或危险情况的信号。通常使用无线电信号和密语通信,有时也使用有线电话和旗语、音响、信号弹等简易信号。', 34);
INSERT INTO `t_military_term_data` VALUES ('1df92096-57e9-4d55-93a8-a47fde0de940', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '将官', '亦称将军。①军官军衔中高于校官低于元帅的一等。通常分为上将、中将、少将3级、有的国家还在上将之上设大将,少将之下设准将。②泛指被授予将官军衔的军官。', 131);
INSERT INTO `t_military_term_data` VALUES ('1e0442b6-6bd3-4893-a29d-10d926998157', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军命令', '下达行军任务的命令。内容一般包括敌情,行军目的、路线及行军纵队的编成，友邻部队的情况,所属各部队、分队的行军路线或在行军序列中的位置,出发点或出发线及通过的时间,宿营地区或集结地区及到达时间,指挥员的位置和各种保障措施等。', 51);
INSERT INTO `t_military_term_data` VALUES ('1e095525-5339-4149-ae83-5681b9cf215d', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫生飞机', '运送伤病员并能在飞行中进行医疗护理的专用飞机。通常配备有必要的工作电源、照明设备、医疗器械和药品等。', 226);
INSERT INTO `t_military_term_data` VALUES ('1e10d557-b9cb-414e-a3bb-f01a6f51dfcc', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '军教影片', '用于军事训练和教学的影片。通常包括各种教学片以及可用于训练和教学的纪录片、战例片和外军资料片等。', 194);
INSERT INTO `t_military_term_data` VALUES ('1e11ec95-740c-4395-864b-987634fcdaa2', 'f0140091-c11a-48c9-8836-8aa94439dac0', '从进攻出发阵地发起进攻', '在占领的进攻出发阵地完成进攻准备后向敌人发起进攻的方式。', 158);
INSERT INTO `t_military_term_data` VALUES ('1e1cc4e6-e13f-4f6f-921e-f9eab43b8c2d', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军队业务部门', '军队各级领导机关内分管某项业务工作的办事机构。如各级司令部、政治部（处）、后勤部（处）、装备技术部（处）等机关内设置的业务部、局、处、科、股等。', 8);
INSERT INTO `t_military_term_data` VALUES ('1e26f6d8-1619-461d-90c6-0ab7afc319a3', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气温', '表示空气冷热程度的物理量。气象台观测的地面气温,通常是指观测场百叶箱内离地1,5米高处的温度。计量单位主要有摄氏温度（。C）、华氏温度（。F）和热力学温度（K）。其值分别用t。C、fF和TK表示,三者间的换算关系是：t。C＝9/5（f-32）；t。C＝T-273.16。', 12);
INSERT INTO `t_military_term_data` VALUES ('1e34f9b5-0eb7-45bd-8bd1-5da7cbaf5dc2', '878651de-adf5-4c72-9376-9c363b893ff8', '游击战争', '以游击战为主要作战形式的战争。相对于正规战争而言。通常是力量比较弱小的一方为了战胜强敌而进行的战争。', 19);
INSERT INTO `t_military_term_data` VALUES ('1e43f194-d4f2-46b2-a7c8-7f2e42dc6326', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮武器系统', '高射炮及其配套技术装备的统称。分为牵引高射炮武器系统和自行高射炮武器系统。能连续测定空中目标坐标,计算射击诸元,使火炮自动跟踪目标射击。大多能全天候作战。', 43);
INSERT INTO `t_military_term_data` VALUES ('1e4cd7f6-6cde-4ad3-958e-5c37fe194cf3', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器存储性', '轻武器在封存仓储期间保持设计功能的能力。主要包括金属件不锈蚀,塑料件不老化弹簧件不失效发射药及火工品的化学安定性和相容性好等。', 219);
INSERT INTO `t_military_term_data` VALUES ('1e542d27-904e-4019-b7be-af2fe7bc7ae6', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克会战', '作战双方以坦克部队为主力，在主要战场上进行的大规模交战。', 8);
INSERT INTO `t_military_term_data` VALUES ('1e5e9c9d-4ea1-40fb-848a-11147f411e04', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻型纵火弹', '能引燃易燃目标的轻型弹药的统称。包括燃烧手榴弹、燃烧枪榴弹以及用榴弹发射器、火箭发射器无坐力发射器等发射的燃烧弹。', 213);
INSERT INTO `t_military_term_data` VALUES ('1e666e70-bdda-41ea-9090-22cc83a0cecd', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '标准时', '以某一子午圈的时间作为其邻近地区或某一行政区域的通用时间标准。区时是应用较广的标准时。', 211);
INSERT INTO `t_military_term_data` VALUES ('1e70fe01-d6dd-4dbb-a119-6ac48205013b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵编组', '将建制和加强的炮兵兵力进行临时性的组合。通常编成各种炮兵群、反坦克预备队、炮兵预备队。防御时还可编成机动炮队或纵深打击机动炮队。', 41);
INSERT INTO `t_military_term_data` VALUES ('1e880d32-f9a2-47ea-9ce2-4ce17e06d901', '98df76fb-4b65-48ff-a56c-4db587327c79', '军费预算', '按法定程序编制、审核、批准的一定时间内的军队经费收支计划。一般按年度进行。主要包括军队经费总预算、单位经费预算、分项经费预算和专项经费预算等。', 74);
INSERT INTO `t_military_term_data` VALUES ('1e9a2d12-13ac-4d13-b57f-fb8adcdb4dd4', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '桥梁渡河', '借助桥梁通过江河的行动。是军队大规模渡河的主要方式。', 302);
INSERT INTO `t_military_term_data` VALUES ('1e9b18eb-7cf3-4dcf-93e7-564d6040e88d', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军船艇在航率', '①一定时期内能正常航行的船日与总船日的比值。②某一时间能正常航行的船数与实有船数的比值。均用百分比表示。用以表明陆军船艇的完好程度和船员数质量的达标程度。是反映陆军船艇部队保障能力的综合指标。', 333);
INSERT INTO `t_military_term_data` VALUES ('1ec451aa-979a-46ee-9eeb-668bb37e84aa', '97a19170-bfac-42c5-9906-1acb187f0654', '亚音速飞机', '最大飞行速度小于音速的飞机。', 267);
INSERT INTO `t_military_term_data` VALUES ('1ec78e13-c7df-400c-99e1-83d548deb1ec', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '部队番号', '军队中各建制单位的正式名号。通常按照编制序列和单位性质授予。一般属于军队机密,限于内部掌握使用。', 142);
INSERT INTO `t_military_term_data` VALUES ('1ee1e4c0-67be-4cdc-b708-d6b2e1f76ff1', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军礼仪', '舰艇及其舰员的礼节和仪式。通常有敬礼、悬挂满旗或满灯、分区列队、鸣放礼炮、鸣笛和舰艇下半旗、默哀等形式。分别表示尊敬、庆祝、欢迎、答谢和哀悼。用于日常工作和生活、节日庆典、迎送首长、外事活动及丧礼等。', 397);
INSERT INTO `t_military_term_data` VALUES ('1ee70746-c279-40c4-befb-2f5b119b6189', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军水文气象保障', '海军为遂行作战和其他任务而在海洋水文气象方面进行的保障。', 369);
INSERT INTO `t_military_term_data` VALUES ('1eeaeda9-5f7e-4450-be8d-bf3ff7fdf1ff', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮队镜', '炮兵用以观察和测角的潜望式双目光学仪器。主要用以侦察敌情、地形,观察射击效果和测定炸点对目标的偏差量,也可用以测定炮阵地和观察所坐标。适于在堑壕、掩体内隐蔽作业时使用。', 279);
INSERT INTO `t_military_term_data` VALUES ('1ef701bf-9891-4b1f-9d48-1a9798ae67d6', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军衔制', '规定军人军衔的制度。主要包括：军衔等级设置,编制军衔,军衔的授予、晋级及降级、取消和剥夺,军衔的标志和佩带等规定。', 128);
INSERT INTO `t_military_term_data` VALUES ('1eff58a2-e329-46ef-81fb-5d5a84c1b79e', '8a761efd-50a6-4ac8-9913-b7d745104f82', '间隙射击', '直射武器弹道通过己方战斗队形间隙的射击。在目标的两个翼侧与己方分队对应边沿之间应留出规定的安全角。', 91);
INSERT INTO `t_military_term_data` VALUES ('1f136461-f836-428a-9365-f4ab0328f0a0', '31f4a446-5b98-4873-9d53-310d97125b07', '核反击作战命令', '实施核反击作战任务的命令。主要内容包括；简要敌情,打击目标,任务区分,发射弹数,以及完成各种准备的时限等。', 12);
INSERT INTO `t_military_term_data` VALUES ('1f1a1e60-cc11-4b05-836f-c3c71b0db994', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境纠纷', '相邻国家在边境地区因某些问题而发生的纠缠和纷争。如因非法移动国界标志以及人员或牲畜越界等引起的纠纷。', 100);
INSERT INTO `t_military_term_data` VALUES ('1f1c184e-8024-4be3-b531-2775cfaff49f', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '领海', '濒海国陆地领土及其内水以外相邻接的一定宽度的海域。其范围为领海基线至领海线之间的海域。国家主权及于领海的海床、底土及其上空。', 74);
INSERT INTO `t_military_term_data` VALUES ('1f204636-6d53-43c5-95bc-49f6b14f14cc', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '单人掩体爆破器', '用以在土壤地上快速构筑单人掩体的炸坑器。', 229);
INSERT INTO `t_military_term_data` VALUES ('1f2f068e-8b0a-4ea6-b162-8675336f1650', '97a19170-bfac-42c5-9906-1acb187f0654', '空中射击', '即飞机或直升机从空中以导弹、航炮、火箭等武器对空中或地面、水上目标进行的射击。', 78);
INSERT INTO `t_military_term_data` VALUES ('1f31110b-18ca-484f-beaa-9555b327a531', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇引导截击法', '潜艇在指挥所或侦察兵力引导下,对敌舰船实施截击的作战方法。通常用以对敌方重要舰船或舰船编队实施集中突击。', 88);
INSERT INTO `t_military_term_data` VALUES ('1f38dbb0-cb42-456f-b754-7dd969901eff', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射阵地配置', '将导弹发射阵地各要素及其设施、设备分布在发射阵地的适当位置。通常分为以发射场坪为主体组成的发射场坪配置和以发射井为主体组成的发射井配置。', 49);
INSERT INTO `t_military_term_data` VALUES ('1f3af6f7-e36c-408f-a595-1808a4b728aa', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇校阅', '舰艇编队以上首长视察舰艇、舰员的隆重仪式。校阅内容通常包括舰艇战备、军政训练、武器装备管理,以及舰员的军政素质、军容风纪等。', 405);
INSERT INTO `t_military_term_data` VALUES ('1f556c04-15aa-4a38-a6cc-414d6abb79b6', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹技术阵地', '导弹技术分队对导弹进行技术准备的阵地。分为地下技术阵地和地面技术阵地。陆基固定发射的战略导弹,多采用地下技术阵地；战术导弹和机动发射的导弹多采用地面技术阵地。', 44);
INSERT INTO `t_military_term_data` VALUES ('1f5b0e1f-88ba-4a0a-b274-18a84c69fed5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮阵地', '炮兵为准备战斗、进行射击而占领的火炮阵地。按用途,分为基本阵地、预备阵地、待机阵地、临时阵地；按遮蔽程度,分为遮蔽阵地、半遮蔽阵地和暴露阵地。通常选择在射界开阔、便于充分发扬火力,有适当的地幅、便于疏散隐蔽配置,有良好的进出道路、便于机动的位置。', 55);
INSERT INTO `t_military_term_data` VALUES ('1f5bd13a-17f7-44b7-9586-ce1d6261fc0b', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '空军侦察', '空军为获取所需情报而进行的侦察。通常由空军各级指挥员及其司令部组织。包括空军各级直属侦察部队和分队,以及航空兵、空降兵、空军雷达兵等的侦察。', 6);
INSERT INTO `t_military_term_data` VALUES ('1f7762a6-a01d-42c6-98a3-395e1f2bf0f6', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射实施计划', '导弹部队根据上级命令制定的实施导弹发射的计划。主要内容包括；打击的目标,发射阵地,发射单位,弹头的领取、总装和测试的时间,弹体的领取和测试的时间,占领发射阵地,预定加注推进剂和完成发射准备的时间,以及对各种保障任务的要求等。', 11);
INSERT INTO `t_military_term_data` VALUES ('1f80c9df-d792-4a67-96f3-64613c9d12c2', '97a19170-bfac-42c5-9906-1acb187f0654', '空降兵师', '由若干个空降兵团及炮兵和专业兵部队或分队编成的空降兵一级组织。通常隶属于空降兵军。', 28);
INSERT INTO `t_military_term_data` VALUES ('1f8d1586-2a1c-4b25-8f1d-8b005d29f628', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮极限发射速度', '加在一定的射击持续时间内,火炮的技术性能所允许的最多发射弹数。用发／分表示。', 207);
INSERT INTO `t_military_term_data` VALUES ('1f921fba-1d68-4e85-a2cb-03267a17083f', 'f0140091-c11a-48c9-8836-8aa94439dac0', '遭遇战斗', '敌对双方部队在运动中相遇发生的战斗。分为预期遭遇战斗和不预期遭遇战斗。', 130);
INSERT INTO `t_military_term_data` VALUES ('1f98f7c0-66fc-4be9-a733-46a499b296ef', '8a761efd-50a6-4ac8-9913-b7d745104f82', '瞄准要素', '实施瞄准的主要因素。包括瞄准基线、瞄准线、瞄准点、瞄准角、高低角、表尺距离、实际射击距离、瞄准线上的弹道高等。瞄准角与高低角之和称射角。', 7);
INSERT INTO `t_military_term_data` VALUES ('1fa1f012-0049-4900-8fdf-2ceaa432a597', '97a19170-bfac-42c5-9906-1acb187f0654', '三角翼飞机', '机翼前缘的后掠角大,机翼俯视平面形状呈三角形的飞机。', 275);
INSERT INTO `t_military_term_data` VALUES ('1fa30030-7e34-4907-bc9d-8e8f48485c6a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击练习', '为巩固和提高炮兵指挥员的射击指挥能力和阵地勤务技能而进行的练习。包括单项射击练习、阵地勤务练习和综合射击练习。', 128);
INSERT INTO `t_military_term_data` VALUES ('1fb1148e-3adf-4f17-ab08-64d5dcbbf895', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击效能', '炮兵所能担负的最大射击能力。分为单炮射出效能和单位射击效能。单炮射击效能由目标性质、炮弹威力、火炮性能等决定；单位射击效能还与火炮数量、每公顷弹药消耗量和射击持续时间有关。', 219);
INSERT INTO `t_military_term_data` VALUES ('1fb506cb-bd48-4b68-8fb8-c36032889cb2', '06a75831-13a1-4660-870a-455bb445336a', '无线电频率管理', '对无线电频率的统一划分、分配和指配等业务进行的管理。', 36);
INSERT INTO `t_military_term_data` VALUES ('1fbebad9-c210-4503-9273-d18c4f3edc53', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '按方位角行进', '在地形图上选定行进路线,利用指北针等工具测定行进方向上各转折点的磁方位角和距离而实施的行进方法。通常在缺少方位物的地区或在夜间视度不良的条件下行进时采用。', 144);
INSERT INTO `t_military_term_data` VALUES ('1fc30c22-d5d1-48cf-893c-3e24bc3e72b1', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克最大速度', '坦克处于战斗全重状态时,在规定的道路及其他环境条件下行驶所能达到的最大速度。一般为 50～70公里／时。', 157);
INSERT INTO `t_military_term_data` VALUES ('1fcc18f2-c7aa-491c-bbc5-f8e633654416', '98df76fb-4b65-48ff-a56c-4db587327c79', '铁路轮渡', '载运机车车辆渡过江河、湖泊、港湾或海峡的渡运设施。包括渡船、轮渡站、引线、栈桥和靠船设备等。通常在铁路线通过水域障碍而修建桥梁又有困难时采用。战时在特大桥梁被破坏时,也可作为应急通车措施。', 263);
INSERT INTO `t_military_term_data` VALUES ('1fd658d7-2e68-4f63-98d6-9a06f45af575', '97a19170-bfac-42c5-9906-1acb187f0654', '空中待战', '飞行员驾驶飞机在指定空域内作机动飞行,待命出击的状态。', 44);
INSERT INTO `t_military_term_data` VALUES ('1fdfa154-1146-4142-9866-296a5b575dea', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '隘路', '狭窄而险要的道路。有山地隘路、河川隘路、森林隘路等。其两侧通常是陡壁或河流等地形障碍,不易绕过,军事上利于扼守和伏击。', 137);
INSERT INTO `t_military_term_data` VALUES ('1ff0b99b-75a6-4b32-bdfd-2ef6f53b9bcd', '97a19170-bfac-42c5-9906-1acb187f0654', '航空维修', '为保持、恢复和提高航空技术装备的性能而进行的维护、修理与改装工作的统称。按维修性质,分为预防性航空维修、修复性航空维修和改进性航空维修；按维修内容,分为一级航空维修、二级航空维修和三级航空维修。', 443);
INSERT INTO `t_military_term_data` VALUES ('1ff854fe-67d2-436c-85fd-1361637e59d6', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射阵地设施', '导弹发射阵地上各种设施的统称。主要包括：发射场坪或发射井,推进剂库和固定加注设施,发射控制室或发射控制中心等。', 51);
INSERT INTO `t_military_term_data` VALUES ('1ffcae31-bf14-4cd4-b576-972d0acae3e7', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化兵', '亦称防化学兵。①担负防化保障喷火、发烟任务的兵种。由防化（观测、侦察、洗消）、喷火、发烟等部队和分队组成。基本任务是：实施核观测、化学观察、化学和辐射侦察,沾染检查、剂量监督、消毒和消除沾染,实施喷火和纵火,组织烟幕施放,组织指导部队、战地党政机关和人民群众对核、化学、生物武器及燃烧武器的防护等。②从事防化专业的士兵。', 0);
INSERT INTO `t_military_term_data` VALUES ('200b337a-a450-43ad-b307-38bb2b285f6d', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '计算机仿真', '以计算机为工具对真实系统或设想系统建立数学模型，进行实验研究的技术。基本要素为系统、模型和计算机。军事上有广泛用途。', 64);
INSERT INTO `t_military_term_data` VALUES ('200c9792-40e6-47e2-869f-7f707b86cacd', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方供应', '依靠国家的经济体系,通过后勤系统组织实施的物资供应。', 97);
INSERT INTO `t_military_term_data` VALUES ('200f6ca8-b615-4e75-9fb7-e5965ce02d60', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反蚕食', '针对敌之蚕食活动所进行的军事斗争。', 359);
INSERT INTO `t_military_term_data` VALUES ('201ce179-dd39-4df2-9b96-0510c7fd03ef', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上战术群', '海军遂行海上战斗任务的各种基本兵力编组的统称。包括海上突击群、海上保障群和战术预备队等。', 63);
INSERT INTO `t_military_term_data` VALUES ('204241f9-8f89-4830-a5fb-26eb1fc72d5c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹飞行试验', '为获取导弹的飞行弹道和工作状态等有关数据,在专门的试验场区进行的导弹发射试验。分为研制性飞行试验、定型飞行试验、生产检验性飞行试验和战斗使用性飞行试验。', 71);
INSERT INTO `t_military_term_data` VALUES ('20576834-8075-4b71-ac5d-3869ab28e253', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵雷达侦察', '炮兵利用雷达发现并测定目标位置的侦察。主要用以侦察活动目标测定敌方地位，还可测定己方炸点坐标。雷达侦察不受能见度影响,可在远距离上发现目标,但易受电子干扰和地形限制,容易暴露。', 112);
INSERT INTO `t_military_term_data` VALUES ('2065f583-1ad1-4175-bd89-5b0a13739aa7', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方命令', '军队指挥员组织实施后勤工作的军用文书。通常由后勤指挥机关拟制,经军政首长签署下达。', 67);
INSERT INTO `t_military_term_data` VALUES ('206d0425-f8d7-4c2d-ba49-fd4cc3ac2692', '06a75831-13a1-4660-870a-455bb445336a', '电话交换机', '亦称电话总机。汇集电话线路并完成用户间通话的接续设备。有人工和自动两类。', 205);
INSERT INTO `t_military_term_data` VALUES ('20708253-c032-4729-9d63-12321dea642d', '916997ee-6728-4c61-9b79-d96960b1dc86', '核防护', '核武器防护的简称。军队为避免或减轻敌核袭击造成的毁伤而进行的防护。主要包括：查明敌核武器的部署和使用企图,建立核观测、警报报知配系,组织疏散配置,构筑防护工事,组织防护训练和三防装备保障,实施辐射侦察、沾染检查和剂量监督,消除核袭击后果等。', 39);
INSERT INTO `t_military_term_data` VALUES ('2070ab9d-75c5-4f40-b0c1-8c4101ee9f60', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事占领', '使用武装力量占据对方领土或地区的行为。', 69);
INSERT INTO `t_military_term_data` VALUES ('207acfe0-d4bf-4636-ac91-5732bdb7e738', '97a19170-bfac-42c5-9906-1acb187f0654', '雷达盲区', '雷达在其最大探测距离以内和最大探测高度以下探测不到目标的区域。分为低空盲区、波瓣间盲区、顶空盲区和地物遮蔽盲区。', 395);
INSERT INTO `t_military_term_data` VALUES ('207d1d20-669a-4e67-9b36-6092c519e5dd', '97a19170-bfac-42c5-9906-1acb187f0654', '空中能见度', '从空中向地面和向水平方向目视,或从地面向空中目视,能看清目标物轮廓的最远距离。', 388);
INSERT INTO `t_military_term_data` VALUES ('20860921-9aa4-4ae5-975d-8e1d26cefa55', '98df76fb-4b65-48ff-a56c-4db587327c79', '基数', '弹药、油料、战救药材等物资的配备、储备、消耗和补充所使用的一种计算单位。以基数作为供应计算单位,便于计算,利于保密。', 131);
INSERT INTO `t_military_term_data` VALUES ('208d1f13-f069-4cf4-a191-375676bf37d3', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水上机场', '供水上飞机起飞、降落、停放和检修的场所。分为永久性水上机场和临时性水上机场。由陆域和水域两部分组成。一般建在水面开阔、远离航道、常年风浪较小、无水中障碍物和有良好净空条件的海湾或湖泊上。', 393);
INSERT INTO `t_military_term_data` VALUES ('2098e84d-1e87-44a7-8f2f-c3acfe69eb56', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '登陆艇（直升机）波', '登陆作战中,分批次输送登陆兵上陆的小型登陆艇组或直升机组。', 102);
INSERT INTO `t_military_term_data` VALUES ('209ceba6-3f05-48ef-834f-d846e8653cac', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '点火管', '由导火索连接火雷管构成的起爆装置。分为应用点火管和制式点火管。', 221);
INSERT INTO `t_military_term_data` VALUES ('20a03454-0400-4a07-8f52-14f54af29763', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反鱼雷武器', '用以干扰、诱骗声自导鱼雷的水中武器的统称。包括潜艇模拟器、鱼雷诱饵、水声干扰器等。', 209);
INSERT INTO `t_military_term_data` VALUES ('20a2f2b5-b780-4233-83de-bc0c580caa20', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '雷区', '布设有地雷的区域。', 184);
INSERT INTO `t_military_term_data` VALUES ('20be177d-486a-4014-a307-b197aae81554', '97a19170-bfac-42c5-9906-1acb187f0654', '空军部队战斗准备等级', '对空军各兵种部队战斗准备程度所划分的级别。如一等战备、二等战备等。各等级的具体内容由空军有关的条令、条例和战备制度规定。', 183);
INSERT INTO `t_military_term_data` VALUES ('20c24003-69e8-4cea-a721-242697f5a846', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '绊发地雷', '通过牵动引信控制机构的绊线（拉线）而发火的触发地雷。配用绊发（拉发）引信。多为破片型防步兵地雷。其绊线为一至数根,每根长度不超过该地雷的密集杀伤半径。', 137);
INSERT INTO `t_military_term_data` VALUES ('20c8f122-8bf5-429c-bb40-244902cc11cf', 'f0140091-c11a-48c9-8836-8aa94439dac0', '对运动之敌的进攻战斗', '对在地面、水面、空中处于行军或航行等运动状态之敌实施的进攻战斗。包括伏击战斗、遭遇战斗、追击战等。', 123);
INSERT INTO `t_military_term_data` VALUES ('20cf26d0-b3eb-45b7-b131-e570398aa27a', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤通信', '为保障后勤指挥而建立的通信联络。主要包括：上下级后勤指挥所之间·后勤指挥所与后勤各业务部门之间,后勤部队或分队及有关单位之间,后勤机关部门与被保障单位之间等的通信联络。', 65);
INSERT INTO `t_military_term_data` VALUES ('20d8becb-68db-45ee-abe0-93946b479c41', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '分队训练', '营以下分队为掌握军事理论知识和战斗技能而进行的训练。一般包括技术训练、专业协同训练和战术训练。', 59);
INSERT INTO `t_military_term_data` VALUES ('20dfcd4d-a051-4aba-a493-cbcccb993d34', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子侦察船', '装有电子侦察设备,专门执行电子侦察任务的舰船。用于对敌方沿海地区、岛屿和舰船进行电子侦察。', 120);
INSERT INTO `t_military_term_data` VALUES ('20e2ac61-4b88-4093-8b45-e6c9d75498ab', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '士官训练', '对军士长、专业军士进行的训练。主要内容包括军事专业理论知识、作战技能和管理能力等。', 56);
INSERT INTO `t_military_term_data` VALUES ('20e53a5e-06a5-4e20-941e-46b5ceb38f18', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役目的', '战役所要达到的预期结果。', 19);
INSERT INTO `t_military_term_data` VALUES ('20e8f0a2-f25b-49fb-bdc3-5d23274666cd', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '革命人生观教育', '正确看待人生价值、选择人生目标和道路为主要内容的教育。', 95);
INSERT INTO `t_military_term_data` VALUES ('20ea262a-30fa-4a70-bb82-4c53174c38c7', '878651de-adf5-4c72-9376-9c363b893ff8', '反侵略战争', '为反对外来侵犯、掠夺和奴役而进行的正义战争。', 27);
INSERT INTO `t_military_term_data` VALUES ('21124a15-a81e-43ea-bc4e-fedb8633dc14', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射分队', '导弹部队中担负导弹发射准备并实施发射的分队。通常编有起竖、瞄准、控制、发动机等专业技术人员。其中液体型号导弹发射分队还编有加注专业技术人员,井式阵地的导弹发射分队还编有吊装专业技术人员。', 3);
INSERT INTO `t_military_term_data` VALUES ('212a730e-1bed-482f-89c8-5943be5e1b06', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '宿营报告', '关于行军、输送与宿营情况的报告。内容通常包括：出发时间、地点和途中概况,到达宿营地的时间,驻地情况,当面敌情,宿营部署,各种保障,发生的问题,请示事项等。', 97);
INSERT INTO `t_military_term_data` VALUES ('21384227-64c5-444b-b91b-0d99894ff98f', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '编组作业', '受训人员充当不同职务,按照统一的想定和各自扮演的角色研练组织指挥和业务工作的作业。', 102);
INSERT INTO `t_military_term_data` VALUES ('213bbbd4-f285-42ba-a8ee-d0f5faef80da', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '授勋', '国家为军队的有功人员授予各种勋章、奖章的表彰活动。授予勋章、奖章的同时发给证书。', 62);
INSERT INTO `t_military_term_data` VALUES ('21413a5d-7a0a-4a2f-8791-ecef1abe77dc', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹测试设备', '用以检查测试导弹弹体上的仪器、元件性能及其系统工作状况的设备。是导弹地面设备的组成部分。分为单元测试设备和综合测试设备。单元测试设备用以测试导弹单个仪器和元件的性能；综合测试设备用于分系统及其协调测试,检查导弹发射功能和飞行程序是否正常。', 60);
INSERT INTO `t_military_term_data` VALUES ('214220f8-ec45-4e21-ab55-a549f672b0b5', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工事配置', '对筑城工事布局和位置进行的安排。主要根据战斗部署、阵地编成、工事的战术技术要求和地形等情况决定。', 79);
INSERT INTO `t_military_term_data` VALUES ('2142c810-c183-47af-b3cc-6b004914fdb8', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵工作三落实', '中华人民共和国民兵工作的组织落实、政治落实和军事落实。毛泽东于1962年6月19日对民兵工作提出的要求。是衡量民兵工作的基本标准。', 127);
INSERT INTO `t_military_term_data` VALUES ('21433829-209f-4645-9800-0831317bc5e0', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹装填设备', '将导弹装入发射井、发射筒或导轨的设备。主要有垂直装填设备、倾斜装填设备和水平装填设备。', 68);
INSERT INTO `t_military_term_data` VALUES ('217c56c3-2f3d-42a6-ab3b-1c0c70fbf264', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮测距机', '亦称测距仪。测定高炮阵地与空中目标之间距离的光学仪器。有光学测距机和激光测距机。', 53);
INSERT INTO `t_military_term_data` VALUES ('2196f797-b065-49a1-8f96-6b6a09a5479c', '97a19170-bfac-42c5-9906-1acb187f0654', '强击机', '以炸弹、航空火箭、空地导弹等为基本武器,具有低空和超低空突击能力的作战飞机。主要用于对敌地面、水面目标实施突击。是航空兵对陆军、海军部队实施直接空中支援的主要机种。', 284);
INSERT INTO `t_military_term_data` VALUES ('219834c3-21f9-428a-b94a-8287f2a01074', '97a19170-bfac-42c5-9906-1acb187f0654', '空降运输协同', '空降部队与运输航空兵部队之间在空降行动上的协调配合。由合成军队或空军的指挥机构组织。主要内容包括：空降兵力编成,航空器乘载场,起飞时间,空降场,空降时间,飞行航线、队形,伞降时飞行的高度、速度,空降最低气象条件,有信号规定,特殊情况的处置等。', 159);
INSERT INTO `t_military_term_data` VALUES ('2199c320-9a86-46fe-8b77-00e9225f43f4', '97a19170-bfac-42c5-9906-1acb187f0654', '水上跳伞', '人员使用降落伞从在水面上空飞行的航空器上跳下,降落在水面的行动。水上跳伞人员须穿救生背心并携带必要的水上救生器材。', 256);
INSERT INTO `t_military_term_data` VALUES ('21a0627c-ee86-43bf-b346-7c22ed5f3266', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '爆破安全规则', '为防止发生爆破事故而制定的规章制度、主要包括：爆破作业的基本规定,爆破器材的运输、储存、保管、检验和销毁的规定以及爆破安全距离等方面的规定等。', 254);
INSERT INTO `t_military_term_data` VALUES ('21bbabf0-9481-44d6-ac90-b0e56fa73138', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '遮蔽度', '通过遮蔽顶的敌视线至炮阵地的铅垂高度。可用以确定炮阵地对敌地面观察的隐蔽程度。', 235);
INSERT INTO `t_military_term_data` VALUES ('21be5532-34e6-46be-8c37-fb94f0dc64b5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '漂雷', '布设在水面或水中一定深度呈自由漂移状态的水雷。分为水面漂雷、固定定深漂雷和自动定深漂雷。锚雷因雷索中断而呈自由漂移状态时也称漂雷。', 213);
INSERT INTO `t_military_term_data` VALUES ('21cadcc6-9731-4b39-a187-193425446b8c', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防力量', '国家用于边境防卫的力量。主要包括边防部队、武装警察边防部队和民兵等武装力量。', 111);
INSERT INTO `t_military_term_data` VALUES ('21e2e43f-1f68-4d53-bd46-3cb053eeeb6a', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵转隶', '将原配属给某一合成军队单位的防空兵部队或分队转而配属给另一合成军队单位。通常根据战场情况的发展变化,按照预先计划和战役指挥员的命令组织实施。', 25);
INSERT INTO `t_military_term_data` VALUES ('21e3d685-c457-4776-9bbe-500bc57585f6', '06a75831-13a1-4660-870a-455bb445336a', '收信机', '亦称通信接收机。接收无线电通信射频信号,并转换为原信息的无线电技术设备。按调制方式,分为调幅收信机、调频收信机和单边带收信机等。由放大器、变频器和解调器等部件组成。可接收电话、电报、数据和图像等。', 188);
INSERT INTO `t_military_term_data` VALUES ('21ef3ca5-71b1-49e3-8597-46b52dfb614f', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵混合编组', '将不同性能的地空导弹分队,或不同口径的高炮分队,或地空导弹分队与高炮分队进行临时性的组合。目的是发挥不同防空武器的性能,在被掩护目标或被掩护地域上空,构成不同高度和不同距离的防空火网。', 16);
INSERT INTO `t_military_term_data` VALUES ('21f112b0-729e-42b0-9787-7f7a4efbc4c9', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '基层建设', '中国人民解放军的连队或相当于连级的基层单位为不断提高战斗力而进行的全面建设。主要内容包括：组织建设,军事训练,思想政治教育,行政管理,后勤保障,文化工作,纪律和作风培养等。', 53);
INSERT INTO `t_military_term_data` VALUES ('21faa59d-9aa1-4a2b-b976-4bfcd56cfc23', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵传统战法', '中国革命战争时期创造的适合民兵特点并行之有效的作战方法。如地雷战、地道战、麻雀战、破袭战、围困战、伏击战等。', 136);
INSERT INTO `t_military_term_data` VALUES ('21ff3110-647b-4413-80c1-ad701cf4f3ef', '97a19170-bfac-42c5-9906-1acb187f0654', '预警机', '亦称预警指挥机。装有机载预警雷达等电子设备,具有指挥引导能力的作战飞机。主要用以探测敌方空中或水面目标,并指挥己方兵力兵器实施攻击。', 286);
INSERT INTO `t_military_term_data` VALUES ('21ffb343-6af8-4f2a-953e-16efe78b09b1', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '拦阻布雷', '在敌人的行进方向上或战斗队形前实施的机动布雷。用以迟滞敌前进或迫使其改变前进方向。', 183);
INSERT INTO `t_military_term_data` VALUES ('2206d227-e56f-4c26-8e4f-133f780c1da9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮射角', '火炮射线与炮口水平面的夹角。火炮初速固定不变,射角由0度增大到45度时,射程随之增大。射角等于45度时,射程最大。射角由45度继续增大时,射程随之减小。', 248);
INSERT INTO `t_military_term_data` VALUES ('220ba379-db26-40a2-89df-b79cfcda82ef', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '接近路', '连接军用道路干线与进出路的辅助军用道路。', 260);
INSERT INTO `t_military_term_data` VALUES ('221a6aa5-90c1-4500-bc1c-69b1f5888a29', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '激光模拟训练器材', '利用激光技术研制的供部队训练用的模拟器材。军事上用于枪、炮、导弹等武器的射击训练和部队的对抗演习。', 84);
INSERT INTO `t_military_term_data` VALUES ('221ae11d-0b48-4da1-8a57-7faa709e35b3', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆二次效应防护性能', '装甲被弹丸穿透后,装甲车辆对弹丸引起的车内弹药爆炸或油料燃烧的杀伤和破坏效应的防护特性与功能。', 177);
INSERT INTO `t_military_term_data` VALUES ('22255c32-b366-4362-826c-2419b062a44f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事制度', '简称军制。国家或政治集团组织。管理、维持、储备和发展军事力量的制度。一般以法律、法规。规章等规范性文件予以规定和颁行。', 17);
INSERT INTO `t_military_term_data` VALUES ('2233ccd1-1afe-4fbd-8744-571bb6bcaa4e', 'f0140091-c11a-48c9-8836-8aa94439dac0', '防御阵地', '为进行防御作战,兵力兵器所占领的阵地。根据工事坚固和完善程度,分为野战防御阵地和坚固防御阵地。', 214);
INSERT INTO `t_military_term_data` VALUES ('223b814a-64ec-4424-8702-784075de388f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '大陆坡', '大陆架边缘向深海海盆过渡的斜坡。常呈阶梯状,宽度一般为20～100公里。坡度多为3度～6度,最大可达40度。', 57);
INSERT INTO `t_military_term_data` VALUES ('223d033e-f716-4fe9-a7d5-3163ebe8ee7f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹射程控制系统', '使导弹质心在达到与预定射程相对应的速度、倾角等参数时,自动关闭发动机的装置。', 60);
INSERT INTO `t_military_term_data` VALUES ('223fdcd8-cd32-4e40-8350-b7c39a87aedb', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '高程', '亦称海拔、真高、绝对高程。由高程基准面起算的地面点高度。', 170);
INSERT INTO `t_military_term_data` VALUES ('2240c1dd-4815-4e6e-8bee-32a36ce1165e', '98df76fb-4b65-48ff-a56c-4db587327c79', '战役储备', '为保障战役作战需要而进行的物资储备。通常由军团根据上级的规定筹建和掌握。', 112);
INSERT INTO `t_military_term_data` VALUES ('224472ef-bad4-433a-8a43-49de4403612f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵敌后观察射击', '炮兵敌后侦察组深入敌区对射击目标实施观察和协助指挥的射击。通常用以摧毁敌纵深内或反斜面上的重要目标。', 172);
INSERT INTO `t_military_term_data` VALUES ('22464267-2d2c-4c90-90a3-c99b0c1faac5', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察文书', '组织实施侦察所使用的军用文书。如侦察计划、侦察指示、侦察工作图、敌情报告、敌情通报等。', 102);
INSERT INTO `t_military_term_data` VALUES ('224edcef-9ab6-4a2a-b7e6-b2177cd7a827', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反扑', '敌人为夺回已失阵地或挽回败局而采取的反击性作战行动。', 351);
INSERT INTO `t_military_term_data` VALUES ('2259bdcc-6163-470a-9b9f-cce2fd7004c9', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '保密', '保守秘密的简称。保证秘密事项在一定时问内只限一定范围的人员知悉的工作。一般包括：建立保密组织机构,完善保密设施,区分秘密载体的秘密等级并对秘密载体妥善保管,制定和落实保密制度与措施,开展保密教育与保密检查等。', 73);
INSERT INTO `t_military_term_data` VALUES ('2262dc11-17eb-4cbc-b27a-fe6f6d79bad3', '98df76fb-4b65-48ff-a56c-4db587327c79', '后转', '由下级救治机构组织运力,将伤病员送到上级救治机构的活动。是伤病员后送的辅助方式。分为逐级后转和越级后转。', 204);
INSERT INTO `t_military_term_data` VALUES ('2265b3d4-a12c-4137-9f34-39804655fa0f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '机动炮队', '防御作战时实施机动作战的炮兵临时战斗编组。由机动性能较好的炮兵分队组成。', 47);
INSERT INTO `t_military_term_data` VALUES ('22686a47-329c-44f0-8913-f98355044a81', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '本队', '行军纵队的主体部分、通常由一至数个行军梯队编成。', 13);
INSERT INTO `t_military_term_data` VALUES ('226f5777-a6dc-4c9c-969a-91f0e8f00d1d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备等级', '对军队战备程度划分的级别。如一级战备、二级战备。', 103);
INSERT INTO `t_military_term_data` VALUES ('22736692-e20b-4e08-ac1b-a81d7e329ecf', 'f0140091-c11a-48c9-8836-8aa94439dac0', '直接火力准备', '冲击发起直前对敌实施的火力突击。用以摧毁当面之敌的防御设施,压制其火力,为步兵、坦克冲击创造条件。', 95);
INSERT INTO `t_military_term_data` VALUES ('227a8ae2-ee8c-4d10-b2e4-12b9384daa4e', '97a19170-bfac-42c5-9906-1acb187f0654', '伞降散布面积', '一批次伞降时所有人员和物资散落到地面的面积。散布面积的大小,主要取决于伞降时航空器编队大小,飞行速度和高度,人员、物资全部离航空器时间的长短,以及风速、风向等因素。', 168);
INSERT INTO `t_military_term_data` VALUES ('227aeaee-ed6f-484b-ae90-109de7fbb7b5', 'f0140091-c11a-48c9-8836-8aa94439dac0', '对运动防御之敌的进攻战斗', '对在一定地区内逐次转移兵力兵器和转换阵地节节进行抗击之敌实施的进攻战斗。', 125);
INSERT INTO `t_military_term_data` VALUES ('227bfafd-929d-4687-997b-981596651571', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '模拟演习', '运用计算机及仿真装置,模仿武器装备性能、战场环境和作战行动等所进行的军事演习。', 115);
INSERT INTO `t_military_term_data` VALUES ('22882692-13bd-48ce-a9bb-9013efc0e22d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '反地雷战器材', '用以克服地雷障碍物的工程器材。包括探雷器材、扫雷器材及其有关配套器材等。', 168);
INSERT INTO `t_military_term_data` VALUES ('228976eb-cf19-4973-b8c6-91eb0a6a0701', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '扫雷车', '装有扫雷器的专用车辆。常用的有火箭扫雷车和混合扫雷车。主要用以伴随部队行动,在地雷场中开辟通路。火箭扫雷车装有火箭爆破器1～4套或扫雷火箭弹10～30发。混合扫雷车多以坦克或其他装甲履带车辆为基础车,车上装有扫雷犁（扫雷磙）、火箭爆破器和通路标示装置,有的还装有磁扫雷器。', 174);
INSERT INTO `t_military_term_data` VALUES ('2289bf35-2814-4d49-992a-abc480576c61', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲扫雷车', '装有扫雷装置,用以在地雷场中为部队开辟通路的装甲保障车辆。', 100);
INSERT INTO `t_military_term_data` VALUES ('22aa5f1f-bc6b-40cf-831c-3b21b286e9e4', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '窃听', '借助技术器材秘密听、录敌方谈话和声响的侦察活动。包括有线电窃听、无线电窃听、红外线窃听、微波窃听和激光窃听等。', 44);
INSERT INTO `t_military_term_data` VALUES ('22af58ba-ab16-4ce7-b2fa-69017bb41730', '97a19170-bfac-42c5-9906-1acb187f0654', '航空技术装备寿命', '航空技术装备在正常的使用和维修条件下允许使用的最大时限。', 449);
INSERT INTO `t_military_term_data` VALUES ('22b55ce5-a0f5-49bc-b162-2900c4b25268', '878651de-adf5-4c72-9376-9c363b893ff8', '战略', '①亦称军事战略。筹划和指导战争全局的方略。按作战类型和性质,分为进攻战略和防御战略。在军事战略下一层次,还可分为军种战略和战区战略等。②泛指对全局性、高层次的重大问题的筹划与指导。如国家战略、国防战略、经济发展战略等。', 47);
INSERT INTO `t_military_term_data` VALUES ('22ba197a-febc-4be5-8443-be8e168658c7', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '陆军侦察', '陆军为获取所需情报而进行的侦察。通常由陆军各级指挥员及其司令部组织。包括陆军各级直属侦察部队和分队,以及步兵、炮兵、防空兵、装甲兵、工程兵、防化兵、陆军航空兵、电子对抗兵等的侦察。', 4);
INSERT INTO `t_military_term_data` VALUES ('22c43ad1-bedd-4782-9e24-d7d492decd40', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '特种作战', '由特种部队或临时赋予特殊任务的部队担负的,为达成特定目的的作战。包括袭击敌首脑机关、重要军事设施和其他要害目标以及为解救人质等进行的特种作战。', 138);
INSERT INTO `t_military_term_data` VALUES ('22c57075-925d-4b1c-94a3-0cb30e922777', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵间接瞄准射击', '对用瞄准镜向瞄准点瞄准以赋予火炮射向,用瞄准具赋予火炮射角实施的射击。主要供占领遮蔽阵地的炮兵采用。特点是阵地隐蔽,火力突然,但射击指挥和协同比较复杂。', 167);
INSERT INTO `t_military_term_data` VALUES ('22c7df25-a7c4-46ca-ac5c-fcf141acfcda', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵技术保障', '防空兵为使战斗装备处于良好技术状态而进行的保障。主要包括：火炮。仪器、器材、车辆的维修、抢修与管理,弹药的保管、保养,导弹技术阵地的选择、配置,导弹的装配、加注、测试、保管等。', 97);
INSERT INTO `t_military_term_data` VALUES ('22cdb7a1-0323-4d24-9752-eccb156e17e9', '98df76fb-4b65-48ff-a56c-4db587327c79', '装备购置费', '军队用以采购武器装备、军事技术设备,以及与采购有关的业务活动的经费。主要包括：各种装备的购置、改装和延寿费,随装备件、用品资料费,新装备技术培训费和业务杂支费等。', 84);
INSERT INTO `t_military_term_data` VALUES ('22dda446-fc3c-43c3-afb7-5296c585b3c0', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军后勤保障', '海军为满足部队建设、作战和生活等需要而在后勤方面采取的各项保证性措施与进行的相应活动的统称。主要包括：经费、物资供应,军械维修,军港和机场勤务,运输补给,医疗卫生,工程建设等方面的保障。', 346);
INSERT INTO `t_military_term_data` VALUES ('22de7601-03cc-49ef-9d7c-302e3bc0abc9', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '军事数据库', '以一定方式储存在计算机中的相互关联并可供共享的军事数据的集合。通常由军事数据、数据库管理系统和数据库应用程序等构成。', 176);
INSERT INTO `t_military_term_data` VALUES ('22e5f598-2ae1-41ff-a3ad-44903a120075', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '遥测弹', '弹上装有遥测设备供飞行试验用的导弹。通过遥测设备可获得导弹在飞行中的有关参数,作为导弹性能分析和改进设计的依据。', 16);
INSERT INTO `t_military_term_data` VALUES ('22ea3349-33d7-459a-a6ef-58281ee988b0', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '红树林海岸', '生长着耐盐、繁茂的红树林植物群落的海岸。分布于热带、亚热带的沿海地区。不便于登陆作战。', 46);
INSERT INTO `t_military_term_data` VALUES ('22f40e47-1d9c-4212-8fb0-169b6beb2e0c', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战报告', '向上级反映作战情况的报告。包括作战要报和作战详报。', 134);
INSERT INTO `t_military_term_data` VALUES ('22f5c94c-ba38-4f40-b1e4-6a45c0e4df14', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练四落实', '军事训练中的人员落实、时间落实、内容落实、质量落实。是军事训练的基本要求和衡量标准。', 42);
INSERT INTO `t_military_term_data` VALUES ('22ffa79a-1b75-476a-a641-97f9136c1e56', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '环境战', '亦称地球物理战。利用人为地改变环境状态所产生的效应达成军事目的的作战。如人为地影响局部地区天气、气候,破坏地貌、地物,改变大气层电磁性质以及破坏臭氧层等,以造成有利于己不利于敌的作战环境,或直接杀伤敌有生力量。', 151);
INSERT INTO `t_military_term_data` VALUES ('2303478d-3b4b-447f-85a1-c4bba8fd8415', '98df76fb-4b65-48ff-a56c-4db587327c79', '军需勤务', '军需物资的供应与管理的专业勤务。', 137);
INSERT INTO `t_military_term_data` VALUES ('230ec0bc-84c2-4d19-a153-d972f813d846', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '支援', '以兵力或火力对所属单位或友邻进行的援助。', 322);
INSERT INTO `t_military_term_data` VALUES ('231569c1-84d5-4a40-95f5-47594cf30f60', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '野战给水', '野战条件下对军队的饮水、用水的供应。包括水源侦察、汲水、水质处理、储水、输运水和配水等。', 357);
INSERT INTO `t_military_term_data` VALUES ('23251204-e4ed-4913-96d4-067abee93509', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '伪装部队', '工程兵中担负工程伪装任务的专业部队。装备有各种制式伪装器材。主要负责对重要的战略、战役目标的伪装,制作和设置技术复杂的假目标等。', 7);
INSERT INTO `t_military_term_data` VALUES ('233a5b38-11b7-4926-87ec-64ebefc9ea1c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军战役', '由海军战役军团单独或在其他军兵种协同下,在海洋战区实施的合同战役。按作战类型,分为海军进攻战役和海军防御战役；按作战任务,分为攻击海上战斗舰艇编队战役、袭击敌港岸重要目标战役、海上保交战役、海上破交战役、海上封锁战役、海上反封锁战役、海军基地防御战役等。', 33);
INSERT INTO `t_military_term_data` VALUES ('2350c0a5-9ba0-4512-a22b-03caab0b6d48', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '野外场地起降', '直升机或垂直起落飞机在机场以外的场地上进行的起飞和降落。', 43);
INSERT INTO `t_military_term_data` VALUES ('235bd192-8440-4d79-af78-48aa290363fd', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '评教评学', '教学双方共同总结训练经验的活动。主要是评议教学双方的态度、方法、效果等。', 165);
INSERT INTO `t_military_term_data` VALUES ('2360269d-17bd-4db3-b7de-1dd6a2c17c0e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战场', ' 敌对双方作战活动的空间。一般分为陆战场、海战场、空战场和太空战场。大规模战争常有若干个按地区划分的相对独立的战场,如第二次世界大战中有欧洲战场、北非战场、太平洋战场等；中国人民解放战争中有东北、华北、西北、华中、华东等战场。', 163);
INSERT INTO `t_military_term_data` VALUES ('2374dc68-50b8-4861-954c-b5d772052375', 'f0140091-c11a-48c9-8836-8aa94439dac0', '对立足未稳之敌的进攻战斗', '对刚由运动状态转为驻止状态且作战准备尚不完善之敌实施的进攻战斗。包括对临时驻止之敌的进攻战斗、对空降着陆之敌的进攻战斗和对登陆上岸尚不巩固之敌的进攻战斗等。', 122);
INSERT INTO `t_military_term_data` VALUES ('237697a7-9f41-4b33-937c-d2d5de07f50e', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射场坪', '为发射导弹而在地面构筑的具有一定幅员的场地。主要由导弹发射基座、发射点及瞄准点、地面设备展开用的场地及进出道路等组成。通常预先构筑,并进行伪装。', 52);
INSERT INTO `t_military_term_data` VALUES ('23789138-7a95-4c3c-9261-3498edff74a0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵光测侦察', '炮兵使用光学观测器材和光电转换侦察器材进行的侦察。通常由炮兵侦察分队在指挥所和观察所内进行。', 110);
INSERT INTO `t_military_term_data` VALUES ('237fd348-082a-48bf-9328-fb2e87eb6b00', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国界', '国家领土的地理空间范围的界限。包括陆地国界（有时亦称边界）线、领海线及其上下垂直面所及的大气空间和底土的界限。国界决定一个国家的存在空间,限定其行使领土主权的范围。具有相对稳定性、确定性和不可侵犯性。', 80);
INSERT INTO `t_military_term_data` VALUES ('239692e5-6adb-4c00-a391-52cdd2e7bda6', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '试射成果距离', '试射结束时所获得的与成果高角相应的炮目距离或炮试距离。', 156);
INSERT INTO `t_military_term_data` VALUES ('23b04ca7-b82e-4316-b396-4f4899c5ebd2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '保障', '军队为遂行各种任务而采取的各项保证性措施与进行的相应活动的统称。按任务,分为作战保障、后勤保障、技术保障、政治工作保障；按层次,分为战略保障、战役保障、战斗保障等。', 157);
INSERT INTO `t_military_term_data` VALUES ('23b3eb03-77af-4f49-8d8e-2a8a62f2380e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战局', '①战争进程中的一定时间和阶段内,敌对双方在战争全局上或一定战区内通过一系列交战所形成的战场态势和军事形势。②外军也有指战争与战役之间的作战层次。', 291);
INSERT INTO `t_military_term_data` VALUES ('23cfda27-5ee6-4f42-add1-88dec9831516', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '早检查', '连队在早晨进行的以检查着装、仪容和个人卫生为内容的例行性行政管理活动。通常于整理内务和洗漱后,以排为单位列队进行,时间不超过10分钟。', 36);
INSERT INTO `t_military_term_data` VALUES ('23e9c3c7-51c2-44b5-b097-f1052d83a881', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '战斗舰艇', '装有专用武器,担负直接作战任务的舰艇的统称。包括水面战斗舰艇和潜艇。水面战斗舰艇主要有航空母舰、战列舰、巡洋舰、驱逐舰、护卫舰（艇）、导弹艇、鱼雷艇、猎潜舰（艇）、布雷舰（艇）、反水雷舰（艇）、猎雷舰（艇）等。潜艇主要有战略导弹潜艇和攻击潜艇等。', 128);
INSERT INTO `t_military_term_data` VALUES ('23f6b1e2-12c8-465a-8b8c-99dc2cc36254', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵战略', '筹划和指导第二炮兵运用与建设的方略。从属于军事战略,并受国家核政策的指导与制约。', 8);
INSERT INTO `t_military_term_data` VALUES ('24094e83-b4f2-4dce-8ecf-c79ce6f5af93', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队防御', '水面舰艇编队为防备和抗击敌方袭击而进行的防御。主要包括：对空防御,对潜防御,对水面舰艇防御,对水雷防御,以及对核、化学、生物武器袭击的防护等。', 95);
INSERT INTO `t_military_term_data` VALUES ('2422e954-0893-43d3-a188-5e08bca4294b', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹延期发射', '根据上级命令或因故推迟导弹的发射。延期发射的时间,不得超过导弹性能所允许的待发时间。', 138);
INSERT INTO `t_military_term_data` VALUES ('243f5b8d-cd92-4f1e-853e-0e25d8093d6d', '878651de-adf5-4c72-9376-9c363b893ff8', '战略转移', '战略防御中,军队在统帅部的领导下,由原作战地区转移到新地区的战略行动。目的是暂时摆脱进攻之敌,争取有利的战略态势。', 121);
INSERT INTO `t_military_term_data` VALUES ('2475d024-c1d4-4165-8803-0a1bf92aec76', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '立体部署', '能从陆地、海洋和空中实施进攻或防御的作战部署、是现代作战部署的基本形式。', 99);
INSERT INTO `t_military_term_data` VALUES ('2479f08f-cb27-44ff-ab59-5fb6ae311965', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队训练', '两艘以上同种舰艇编队进行的技术战术科目和协同动作的训练。在单舰艇训练的基础上进行。目的是提高编队指挥员及其指挥机构的组织指挥能力,密切舰艇之间的协同动作,提高编队的海上作战能力。', 318);
INSERT INTO `t_military_term_data` VALUES ('247fc7b9-bd23-45a6-b1cf-89f24bf7ff6d', '98df76fb-4b65-48ff-a56c-4db587327c79', '机动装具', '军需部门直接掌握的备用装具。主要用于对部队装具丢失、损坏的补充。', 160);
INSERT INTO `t_military_term_data` VALUES ('24816b5e-3443-41d2-9d74-c3d78a3bc90f', '8a761efd-50a6-4ac8-9913-b7d745104f82', '最大开火距离', '高炮弹丸在有效射击范用的边界上迎击目标时,火炮至目标的斜距离。其大小与火控系统的工作范围和目标的高度、航路捷径、飞行速度有关。', 56);
INSERT INTO `t_military_term_data` VALUES ('2486cd47-40d6-4bf4-ba2d-8f8c5ac18d88', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '链', '①航海中计量较短距离的长度单位。1链等于 0．1海里。②舰炮对海射击时射程的计量单位。l炮链等于182．87米。', 278);
INSERT INTO `t_military_term_data` VALUES ('24910bdd-906f-49ad-89a1-197f52878422', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '脉冲干扰', '利用各种宽度和重复频率的脉冲、脉冲串调制干扰发射机的载波形成的电子干扰。主要用以干扰脉冲工作方式的雷达、导航设备、数字通信设备以及其他电子设备。', 59);
INSERT INTO `t_military_term_data` VALUES ('24a453c8-67c5-4b53-a4a7-ab1f889f23d3', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '水面下桥', '桥面没入水面以下的军用桥梁、没入水下深度通常为50厘米,必要时可达70～100厘米。', 276);
INSERT INTO `t_military_term_data` VALUES ('24af6144-84df-4720-a66d-00f001263597', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '湿热指数', '高温条件下,人体对热的感觉程度与湿度、气温关系的指数。用给定的高温和湿度下人体的热感程度与干燥空气条件下相当的气温值来表示。气温在25摄氏度～54摄氏度之间时,空气相对湿度越大,人体感觉越热。', 93);
INSERT INTO `t_military_term_data` VALUES ('24b17194-7f91-48bc-9272-a30d47889cb1', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '教练地雷', '供教学、训练使用的地雷。其外形、尺寸、重量和结构与实物相同,配有教练引信,但不装填炸药。', 156);
INSERT INTO `t_military_term_data` VALUES ('24b98b99-c7a0-4ac7-9f14-7cfdf01888e8', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察协同', '各种侦察力量为遂行共同的侦察任务,按照统一的计划而采取的协调一致的行动。主要包括：各侦察机构之间的协同,侦察部队与其他作战部队之间的协同,军队侦察机构与民兵、地方有关部门之间的协同等。', 100);
INSERT INTO `t_military_term_data` VALUES ('24c7c1b4-1b8c-4c51-a5cb-ceef5e0e1f68', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '分散指挥', '给下级明确意图和任务由下级独立自卞实施的指挥通常在分散行动或没有较可靠的通信联络手段时采用。', 21);
INSERT INTO `t_military_term_data` VALUES ('24c98adc-6300-422a-9fea-ad4268ad4456', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机掩体', '亦称机窝。用土或其他建筑材料围筑的无顶盖的飞机防护工事。每个飞机掩体可停放一架或数架飞机。', 438);
INSERT INTO `t_military_term_data` VALUES ('24d40a01-cb2d-403d-902a-8fc15f6a0968', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '协同作战训练', '军兵种之间、部队或分队之间为提高作战中的协调配合能力而进行的训练。', 86);
INSERT INTO `t_military_term_data` VALUES ('24de43e3-8e0d-474d-86f2-bb93f4394a01', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军事检察院', '国家在军队中设立的法律监督机关。属于专门检察院。中国人民解放军的军事检察院分三级设置,即：中国人民解放军军事检察院,军区、海军、空军、解放军总直属队、武警部队军事检察院,海军舰队、军区空军、陆军军级单位军事检察院。', 137);
INSERT INTO `t_military_term_data` VALUES ('24e969fd-d3f0-46bb-814f-8b56e3b0f54e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '受挫', '军队在作战中行动不顺利,遭受损失与挫折。', 374);
INSERT INTO `t_military_term_data` VALUES ('24ec04ee-ebdf-4db8-a98e-b6750e6e89db', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵政列观察射击', '由设在炮阵地附近的炮兵观察所实施指挥的射击。通常要求观炮距离不超过炮目距离的5％。特点是射击准备快,指挥简便,火力反应迅速。通常为随伴步兵行动并实施间接瞄准射击的炮兵分队所采用。', 173);
INSERT INTO `t_military_term_data` VALUES ('24f0dc8b-e7e3-4506-b194-f414c1c6517f', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力封锁', '以火力严密控制和封闭某一区域或目标。主要用以限制敌人的行动,断绝其补给或外援,为歼敌创造条件。', 100);
INSERT INTO `t_military_term_data` VALUES ('24f1bca4-bc33-4cbe-8d14-17ead84484db', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '技术兵', '使用专业技术装备,以专门技能遂行任务的士兵。', 116);
INSERT INTO `t_military_term_data` VALUES ('24fef076-a32a-4350-ac27-204b0a4dba45', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '侧后', '翼侧的后面。通常为部署的薄弱部位。', 284);
INSERT INTO `t_military_term_data` VALUES ('250c6241-1b20-4774-a616-99ccff82d5ef', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹戒备率', '处于戒备状态、能在反应时间内实施作战的导弹数与部署的导弹数的比值。通常用百分比表示。主要取决于导弹的类型及其战术技术性能。', 16);
INSERT INTO `t_military_term_data` VALUES ('251b8414-d1cd-4002-9592-1b20e645eb56', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '大潮', '当月球、太阳和地球的相对位置大致在同一直线上,月球与太阳的引潮力方向几乎相同时,产生的潮差最大的潮汐。大潮一般出现在农历朔（初一）和望（十五）之后约1～2天。', 141);
INSERT INTO `t_military_term_data` VALUES ('252c52f0-11b5-4ea1-ab61-3deab3988873', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海洋内波', '密度层结稳定的海水受外部扰动作用,在其内部产生的波动。影响因素主要有天体引潮力,海面风浪向深处传播,海面气压突然变化,风引起的增水和分层海水中物体运动等。海洋内波会给舰船航行造成困难,使潜艇有被抛出海面或压向海底的危险,影响声纳的探测功能等。', 134);
INSERT INTO `t_military_term_data` VALUES ('253a77da-2708-476c-b616-ff19873b1a69', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜空导弹', '从潜艇上发射,用以攻击空中目标的导弹。主要用以攻击近程、低空的反潜直升机。', 197);
INSERT INTO `t_military_term_data` VALUES ('25424491-c2c2-4013-b9b5-c170bfb0e0d7', '97a19170-bfac-42c5-9906-1acb187f0654', '雷达值班', '雷达部队为遂行对空警戒侦察和其他保障任务而使雷达处于开机或待命开机的状态。分为轮流开机值班、定时开机值班和待命开机值班。', 398);
INSERT INTO `t_military_term_data` VALUES ('254f73d6-afd3-413f-8470-52e262b62737', '878651de-adf5-4c72-9376-9c363b893ff8', '帝国主义战争', '帝国主义国家间为瓜分势力范围、争夺霸权而进行的非正义战争。如日俄战争、第一次世界大战。', 28);
INSERT INTO `t_military_term_data` VALUES ('2552138b-2967-4efe-8b08-ec57acecfc26', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反围困', '对抗和打破敌人围困的作战行动。', 418);
INSERT INTO `t_military_term_data` VALUES ('2559a417-01b3-4c50-a4a6-fb78c4bab5be', '97a19170-bfac-42c5-9906-1acb187f0654', '跳伞', '人员使用降落伞从飞行中的航空器上跳下,降落到地面或水面的行动。按任务性质,分为战斗跳伞、训练跳伞、救生跳伞、试验跳伞和专项任务跳伞；按降落点的自然地理条件分为陆地跳伞和水上跳伞等。', 255);
INSERT INTO `t_military_term_data` VALUES ('255c6182-87a9-4986-a22d-b55f61f63dc4', '878651de-adf5-4c72-9376-9c363b893ff8', '战略集团', '战略区或重要战略方向的重兵集团。通常由若干个战役军团组成。', 93);
INSERT INTO `t_military_term_data` VALUES ('255c6d73-70f7-4893-9d41-7b0a95ebaae8', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力转移', '火器不变换发射阵地,将火力由一目标向另一目标的转换。', 103);
INSERT INTO `t_military_term_data` VALUES ('256817ad-7d8d-435d-a633-17320796384e', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物武器', '以生物战剂杀伤有生力量和毁坏植物的武器。包括装有生物战剂的炮弹、航空炸弹、火箭弹、导弹弹头和航空布洒器等。主要通过气溶胶和带菌昆虫等方式施放,由呼吸道、消化道、皮肤和粘膜侵入人、畜体内,经一定潜伏期后发病以至死亡。也可大规模毁伤农作物。', 229);
INSERT INTO `t_military_term_data` VALUES ('2569e96f-cc54-40d3-b05d-abf981f183ef', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '尖兵', '担任行军警戒任务的连以下分队。有前方尖兵、后方尖兵和侧方尖兵。通常兵力为1个班至1个连,分别称为尖兵班、尖兵排、尖兵连。', 14);
INSERT INTO `t_military_term_data` VALUES ('256b8dfe-e689-4341-ae50-1449492b420c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电磁辐射源', '能以电磁波形式向空间发射能量的设备。主要有雷达、无线电台、导弹制导系统和导航发射台等。有些电磁辐射源亦称威胁辐射源,如直接控制武器系统的炮瞄雷达、导弹制导雷达、激光制导装置等。', 26);
INSERT INTO `t_military_term_data` VALUES ('257900a1-b63b-4f39-b589-35cffa5e0388', '06a75831-13a1-4660-870a-455bb445336a', '步坦协同通信', '为保障步兵与坦克的协同作战而建立的通信联络。主要方法有；组织协同无线电网；通过坦克兵向步兵派出的作战小组（代表）的电台建立无线电通信；通过上级指挥网转信；由步兵向坦克兵建立野战有线电通信；使用简易信号通信器材等。', 15);
INSERT INTO `t_military_term_data` VALUES ('25793a93-6202-488e-91fe-6f756657c9f4', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '技术测试区', '简称测试区,亦称综合技术准备区。航天器发射场内用于对运载火箭和航天器进行装配、检测、试验等工作的专门区域。主要设施有；运载火箭装配测试厂房,航天器装配测试厂房,危险品储存、装配和检测设施,以及充电站、供气站、电力站、通信设施、各种实验室等。', 247);
INSERT INTO `t_military_term_data` VALUES ('2591870e-9b95-404c-acb0-74457a35e026', '97a19170-bfac-42c5-9906-1acb187f0654', '航空穿破炸弹', '装有火箭加速器,用以破坏混凝土结构目标的航空炸弹、在超低空投下时有较强的侵彻力,主要用以破坏机场跑道和钢筋混凝土工事等。', 332);
INSERT INTO `t_military_term_data` VALUES ('2595a41c-1673-4ed7-a43f-dc53aa020143', 'f0140091-c11a-48c9-8836-8aa94439dac0', '攻击', '主动进击敌人的战斗行动。', 147);
INSERT INTO `t_military_term_data` VALUES ('259cf456-8989-4dda-b4ca-dd57e2f785a2', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '电子计算机', '按程序自动进行数学运算和信息处理的电子设备。分为数字电子计算机、模拟电子汁算机和混合电子计算机。数字电子计算机的通用性最强、应用面最广。军事上有广泛用途。', 52);
INSERT INTO `t_military_term_data` VALUES ('25a4e92f-2bc4-41da-ba06-8cd7daa7a046', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '红外一激光雷达', '利用目标的红外辐射时其进行跟踪测角,并用激光进行测距的雷达。跟踪测量精度高,隐蔽性和抗干扰性能好,但作用距离较近。军事上主要用于导弹主动段和再入段的跟踪测量、侦察和火力控制等。', 100);
INSERT INTO `t_military_term_data` VALUES ('25b0d7ca-c20e-48ee-a00d-f8f95c3b52a9', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '军队指挥', '简称指挥。军队指挥员及其指挥机关对所属部队的作战和其他行动的组织领导活动。中队作战指作包括战略、战役、战斗范围内的各种类型形式、样式作战的指挥、对军队其他行动的指挥主要包括对战备行动、军事训练、防暴、抢险救灾等的指挥', 0);
INSERT INTO `t_military_term_data` VALUES ('25b91bc0-949b-42a3-9b03-b0e08033778a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '火力准备', '进攻前或冲击前对敌实施的火力突击。主要由炮兵、航空兵、舰艇部队、导弹部队等实施。分为预先火力准备和直接火力准备。预先火力准备指进攻前一至数天进行的火力突击；直接火力准备指冲击发起直前进行的火力突击。', 259);
INSERT INTO `t_military_term_data` VALUES ('25cf1dd7-7463-411e-af72-ca36db444121', '06a75831-13a1-4660-870a-455bb445336a', '无线电通信检查', '为保证无线电台能够及时沟通联络而采取的措施。通常在无线电静默期间实施。由主台采用单方发信的方式,拍发通信检查信号,属台将收到检查信号的情况,按规定的方法告知主台。', 40);
INSERT INTO `t_military_term_data` VALUES ('25cfda6b-4296-42d9-8ffd-3d629a107125', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '政治机关制', '中国人民解放军在团或相当于团级以上的部队和单位设立政治工作领导机关的制度。团或相当于团级的部队和单位设立政治处,旅以上的部队和单位设立政治部,全军设立总政治部。政治机关是所属部队和单位政治工作的领导机关,在上级政治机关、同级部队或单位的党委和政治委员领导下,负责管理所属部队和单位党的工作,组织实施政治工作。', 22);
INSERT INTO `t_military_term_data` VALUES ('25d0b944-0534-42a8-91ab-846ab9d2d690', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '辐射源威胁识别', '对敌方电磁辐射源威胁程度的分析鉴别。方法是：将侦获的敌方电磁辐射源的特征参数与数据库中存储的已知各类威胁辐射源特征参数作比较,以确定辐射源的种类和威胁等级。是电子对抗支援侦察系统所具有的重要功能。', 31);
INSERT INTO `t_military_term_data` VALUES ('25e00694-6c2e-4d6f-bdc6-679139d5a5db', 'f0140091-c11a-48c9-8836-8aa94439dac0', '阵地防御战斗', '依托阵地抗击敌人进攻的防御战斗。分为野战阵地防御战斗和坚固阵地防御战斗。', 200);
INSERT INTO `t_military_term_data` VALUES ('25e2fdc2-7b03-4fa2-9cfa-64abd23ddd1f', '916997ee-6728-4c61-9b79-d96960b1dc86', '最低刺激浓度', ' 亦称阈刺激浓度。受染空气中的刺激剂使无防护人员眼、鼻、喉等产生刺激症状的最低浓度。单位为毫克／升或毫克／立方米。', 140);
INSERT INTO `t_military_term_data` VALUES ('25e7aa58-967f-41e3-84e9-1e43641503f5', '916997ee-6728-4c61-9b79-d96960b1dc86', '二元化学武器', '弹体内分隔装填两种或两种以上毒剂前体,在投射过程中经化学反应生成毒剂的化学武器。包括能生成沙林、维埃克斯和中等挥发度毒剂的二元化学炮弹、二元化学航空炸弹、二元化学火箭弹、二元化学导弹弹头等。', 200);
INSERT INTO `t_military_term_data` VALUES ('25f02845-cce5-4d64-803a-f980182710a2', '06a75831-13a1-4660-870a-455bb445336a', '应急通信', '为应付紧急情况或突发事件而建立的通信联络。通常采取以无线电通信为主,与有线电通信等多种手段相结合的方式建立。要求具有快速应变和超越多级的全程通信保障能力。', 22);
INSERT INTO `t_military_term_data` VALUES ('2609973c-4039-4953-8463-0d30f516a158', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹热发射', '亦称自力发射。靠导弹发动机直接点火产生推力使导弹飞离发射装置的发射。热发射消耗推进剂多,增加导弹重量,但地面设备比较简单。', 118);
INSERT INTO `t_military_term_data` VALUES ('2618651d-5f2a-4d70-95b8-21a9df1d5f64', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '闪电探测设备', '获取闪电信息的设备。通过对闪电产生的电磁波和场强的测量,判定闪电的方位。距离、强度、次数等。由传感器和检测放大、数据传输与处理显示等系统组成。能为跟踪、预报与防护雷电提供直观有效的手段。', 103);
INSERT INTO `t_military_term_data` VALUES ('261f5f66-6856-49b6-9454-e02f4d917017', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克疏开队形', '亦称坦克临战队形。坦克部队和分队由一路行军纵队转换成多路行军纵队,并保持一定的间隔和距离的队形。通常在接敌运动、通过障碍区、向纵深发展进攻和追击时采用。可提高机动速度,减少敌火伤害,并便于迅速变换成战斗队形。', 21);
INSERT INTO `t_military_term_data` VALUES ('26268fce-822c-416b-997a-c1305ba94076', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '观察要图', '观察所和观察哨使用的工作图、主要标绘有：本观察所或观察哨的基本位置和预备位置,观察地境和死角,重要观察地段,阵地编号,方位物,敌我前沿位置,当面敌人基本部署和新发现的情况等。', 110);
INSERT INTO `t_military_term_data` VALUES ('262dfa38-0989-4487-a465-5fc08e382559', '06a75831-13a1-4660-870a-455bb445336a', '预先通信指示', '在通信指示下达前为使直属通信部队、分队和下级通信部门预有执行任务的准备而发出的指示。主要包括：简要敌情,通信部队、分队将要执行的概略任务,主要准备工作及完成的时限、要求和注意事项等。', 34);
INSERT INTO `t_military_term_data` VALUES ('26383586-2007-4121-ae66-33409cc619e6', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '榴弹', '以弹丸爆炸产生的破片和爆炸装药的爆轰能量杀伤、破坏目标的炮弹。', 304);
INSERT INTO `t_military_term_data` VALUES ('263cbe98-6c8a-4293-9915-0b7aa3705019', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '重点部署', '有重点地配置兵力兵器的作战部署。', 101);
INSERT INTO `t_military_term_data` VALUES ('265147f2-e59a-4864-a7cf-092056624713', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行最低气象条件', '保证航空器安全起飞、着陆所要求的气象要素的最低限度。主要包括对云底高、能见度以及地面风速、风向等气象要素的最低要求。通常根据不同的机场、机型和飞行员技术水平等具体情况分别规定。', 386);
INSERT INTO `t_military_term_data` VALUES ('265d442f-c6e1-4df6-8d43-d9da63324042', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '智能武器', '人工智能武器的简称。应用人工智能技术,能自动寻找、识别和摧毁敌方目标的武器。如具有人工智能的导弹、炸弹、鱼雷等。', 51);
INSERT INTO `t_military_term_data` VALUES ('265f76c8-62f5-40cb-839a-5307cf492d93', '97a19170-bfac-42c5-9906-1acb187f0654', '下滑轰炸', '飞机向前下方在较小下降角的直线等速飞行中对目标进行的轰炸。通常用以轰炸狭长目标。', 97);
INSERT INTO `t_military_term_data` VALUES ('2663adaf-763e-4828-b7b8-32e52f2eccdc', '878651de-adf5-4c72-9376-9c363b893ff8', '战略环境', '影响国家安全或战争全局的客观情况和条件。主要包括国际和国内的政治、经济、军事、外交、科技、地理等方面综合形成的客观情况和条件。', 64);
INSERT INTO `t_military_term_data` VALUES ('2675e237-6326-46fa-a760-f900eb08a309', '97a19170-bfac-42c5-9906-1acb187f0654', '螺旋桨式飞机', '利用螺旋桨把发动机的动力转化为拉力或推力的飞机。分为活塞式螺旋桨飞机和涡轮螺旋桨飞机。', 268);
INSERT INTO `t_military_term_data` VALUES ('267da5ac-6245-41aa-a765-0bbcd2228195', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '低水桥', '上部结构缘略高于江河常年高水位的固定桥脚的军用桥梁。可用就便器材或制式器材架设。使用期限较短,一般不考虑洪水、流冰和船只从桥下通过。', 274);
INSERT INTO `t_military_term_data` VALUES ('2681ee1a-e1df-4b0a-8af1-5364bb1eb862', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '扫雷直升机', '主要用以扫除水雷的海军直升机。', 179);
INSERT INTO `t_military_term_data` VALUES ('26858c70-d1c2-4f9c-bd3d-762d76deb5c0', '06a75831-13a1-4660-870a-455bb445336a', '数字通信', '用数字信号传输信息的通信。可传输电话、电报、数据和图像等。抗干扰能力强,易于加密,便于综合各种业务在一个网内传输。是军事通信的发展方向。', 95);
INSERT INTO `t_military_term_data` VALUES ('2694b2d1-577e-44f3-91c1-3ffcc2ea0c7d', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战备训练', '根据战备要求和担负的作战任务而进行的训练。', 46);
INSERT INTO `t_military_term_data` VALUES ('26969ce2-af94-40f6-af7a-370b91788878', '97a19170-bfac-42c5-9906-1acb187f0654', '炮兵校射机', '亦称侦察校射机。专门为地面炮兵指示目标和校正射击误差的军用飞机。机内装有照相机、观测仪、无线电台等设备。', 291);
INSERT INTO `t_military_term_data` VALUES ('269f8759-aab8-443b-86f3-b580fd02c374', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '重点攻击', '以主要兵力对敌之一部或敌某个（某些）目标实施的攻击。', 235);
INSERT INTO `t_military_term_data` VALUES ('26a6d8e5-0f65-4603-8c1d-c43281b51e50', '06a75831-13a1-4660-870a-455bb445336a', '波长', '电磁波在一个振荡周期内传播的距离。基本计量单位为米。波长与频率成反比。', 90);
INSERT INTO `t_military_term_data` VALUES ('26a7deee-8404-47f9-a71a-85e43504430d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '建军思想', '关于军队建设问题的理性认识。通常表现为建军的指导理论和基本原则。', 94);
INSERT INTO `t_military_term_data` VALUES ('26a9de4b-49ef-4072-bbfe-d97a0e3f7954', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '传真电报', '采用传真通信方式传送的军用文书。', 116);
INSERT INTO `t_military_term_data` VALUES ('26ae98b0-f466-42f7-a3c2-cb2bc2365bfc', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '军用建筑机械', '用于国防工程施工作业的军用工程机械。有推土机、挖掘机、装载机、平路机、铲运机、压路机、空压机、凿岩机、木材加工机械和混凝土拌合机等。', 374);
INSERT INTO `t_military_term_data` VALUES ('26bc7963-479f-47d9-be45-e3c7ad442632', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事禁区', '根据军事需要所划定的禁止无关人员进入或限制其活动的特定区域。其边界通常设有醒目的标志。', 80);
INSERT INTO `t_military_term_data` VALUES ('26cb85c0-127d-48be-8282-9cace53fa958', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻机枪', '用两脚架支撑、重量较轻的机枪。主要用以射击800米内的生动目标。重量、射击精度和火力都介于步枪与重机枪之间。口径5.45～8毫米，枪重5～10千克,战斗射速80～150发／分。', 167);
INSERT INTO `t_military_term_data` VALUES ('26df5b7f-37b1-4272-8f6b-1fa74b2005d7', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '鱼雷艇', '以鱼雷为主要武器的小型高速水面战斗舰艇。分为滑行型、半滑行型和水翼型等鱼雷艇。主要在近岸海区与其他舰艇协同对敌大中型水面舰船实施鱼雷攻击。', 144);
INSERT INTO `t_military_term_data` VALUES ('26f0b33a-07d1-42d3-b967-0b360ebdb8b5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '支援炮兵', '由上级掌握并根据被支援部队指挥员的火力请求而实施射击的炮兵。', 8);
INSERT INTO `t_military_term_data` VALUES ('26fb7555-db4b-4323-bec6-f0942e263752', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '主力', '军队中担负主要任务或起主要作用的作战力量。通常指担负主要作战任务的部队或分队,战斗力强的部队或分队,以及建制部队、分队或兵力集团中的大部兵力。', 256);
INSERT INTO `t_military_term_data` VALUES ('270aa0f9-40a1-43c7-8a01-403cdf2aefe4', '06a75831-13a1-4660-870a-455bb445336a', '甚长波电台', '亦称甚低频电台。工作波长为100～10千米（频率为3～30千赫）的无线电发信台。主要用于对潜艇和远洋舰船发信,有的也用于导航及标准时间、标准频率的发送。', 180);
INSERT INTO `t_military_term_data` VALUES ('270bc3ce-6177-4d6d-a958-160b162a4e48', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '遥感侦察', '使用遥感技术器材探测和识别远距离目标的侦察。分为地面遥感侦察、航空遥感侦察和航天遥感侦察。', 62);
INSERT INTO `t_military_term_data` VALUES ('2712ab40-cbb2-4258-a030-a60843ea2dcc', '97a19170-bfac-42c5-9906-1acb187f0654', '机场净空区', '为保证飞机或直升机起飞、着陆和复飞的安全,在机场周围划定的限制地貌地物高度的空间区域。包括端净空区和侧净空区。净空区范围大小和规格根据机场的等级确定。', 420);
INSERT INTO `t_military_term_data` VALUES ('271b39a7-719c-4291-b28c-11b4f2a379c4', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军旗帜', '海军部队用于识别、通信和礼仪等的旗帜的统称。包括识别标志旗和通信旗。识别标志旗,代表国籍、军种、兵种、职务、军衔、级别和舰艇状况等；通信旗,主要用于舰船间、舰船与陆地间的通信联络。', 396);
INSERT INTO `t_military_term_data` VALUES ('272765b2-58e0-4e91-b306-7671ce1dbd79', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克集中使用', '作战中将坦克部队的全部或大部集中使用在主要作战方向。目的是构成较大的坦克密度,形成局部优势,充分发挥坦克部队的突击作用以及便于实施指挥、协同和各项保障。', 9);
INSERT INTO `t_military_term_data` VALUES ('2738edfa-6c07-4f01-90b6-af828d4a4ed9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮射弹落点', '射弹飞出炮口后形成的弹道与炮口水平面的交点。', 251);
INSERT INTO `t_military_term_data` VALUES ('273d3d53-bfcf-4562-84c4-31b4721a2026', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '纪律条令', '军队行政纪律的条令。是军队维护纪律和实施奖惩的依据。', 4);
INSERT INTO `t_military_term_data` VALUES ('273f39d3-29ec-4c1c-bff9-03d4faa5ee15', '8a761efd-50a6-4ac8-9913-b7d745104f82', '法线角', '亦称着角。弹着点处的弹道切线与法线之间小于90度的夹角。法线角与命中角之和为90度。对同样厚度的装甲,法线角越大,需穿透的法线角厚度越大。', 41);
INSERT INTO `t_military_term_data` VALUES ('2746298a-3278-4be9-866e-257ea1f5b3ee', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '爆炸性障碍物', '爆炸产生的能量毁坏装备、杀伤有生力量的人工障碍物。如地雷场、水雷区、空飘雷区、炸药管道系统等。', 100);
INSERT INTO `t_military_term_data` VALUES ('27497705-5742-40a8-b85a-27e48944c71c', '98df76fb-4b65-48ff-a56c-4db587327c79', '营区', '建有营房及相应附属设施井有明确地界的区域。是军队日常工作、生活和训练的场所。通常包括：机关办公区、宿舍区,科研、医疗及其他业务活动区,训练场区,仓库、车场区,干部眷属住宅区,生活服务区等。', 234);
INSERT INTO `t_military_term_data` VALUES ('274bf858-59ae-4413-8b14-a418de2b0eaa', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲指挥车', '设有指挥室并配备指挥、通信和观察设备的装甲战斗车辆。用于作战指挥。分为履带式和轮式两种。', 97);
INSERT INTO `t_military_term_data` VALUES ('275458c6-6c01-471c-84de-6a3c91c57ac2', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报指导', '对情报资料的搜集工作提出要求和进行评价。目的是使情报资料的搜集工作更具有针对性和计划性。', 134);
INSERT INTO `t_military_term_data` VALUES ('2761ca0f-d079-478c-b042-6d939c076a2d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '布雷文件', '有关布雷的文书和资料的统称。包括地雷场要图、登记表、报告表等。由布雷分队指挥员负责绘制与登记。是移交、维护和撤除地雷场（群）和其他爆炸性障碍物的依据。', 193);
INSERT INTO `t_military_term_data` VALUES ('276e4679-d468-4ecf-a6e0-f4e09eb13db2', '0', '导弹 .核武器 .航天', NULL, 15);
INSERT INTO `t_military_term_data` VALUES ('278c78fc-9b7d-4aa4-86fa-aa1f33a336e5', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '掩护', '保障主力或其他部队、人员遂行任务或安全的作战行动。包括以兵力或火力进行的牵制、阻击、压制、迷盲等。', 332);
INSERT INTO `t_military_term_data` VALUES ('2793c491-9bb0-4131-88f1-88403b09926b', '97a19170-bfac-42c5-9906-1acb187f0654', '空军雷达兵', '空军中以对空情报雷达为基本装备,主要遂行对空中目标探测和报知空中情报任务的兵种。通常用于对空警戒侦察,并保障有关部门对航空器飞行的指挥引导和实施航空管制等。', 29);
INSERT INTO `t_military_term_data` VALUES ('279440eb-b0d6-4841-8c43-ab23bc1061ca', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击效果判定', '根据核打击效果侦察获取的资料,对被打击目标毁伤程度进行的综合分析和判断。是确定是否实施补充打击的主要依据。', 171);
INSERT INTO `t_military_term_data` VALUES ('279de0d4-10ba-4c2c-9105-caaab8f95d63', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '通信对抗侦察设备', '专门用以搜索、截获、分析、识别敌无线电设备发射的信号,并获取其技术参数及其方向、位置的电子设备。分为通信对抗情报侦察设备、通信干扰引导侦察设备和无线电测向设备。', 115);
INSERT INTO `t_military_term_data` VALUES ('27a182cb-6f1c-4cf5-89e8-e32812c0b830', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '垂直起飞', '直升机或垂直起落飞机不经地面滑跑而进行的垂直离地的起飞。是直升机、垂直起落飞机的主要起飞方式。对起飞场地条件要求较低。', 40);
INSERT INTO `t_military_term_data` VALUES ('27aaa914-431b-432c-a551-e5513dfeca1e', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '预有准备防御', '预先做好各项准备的防御作战。通常准备时间比较充裕,防御体系和设施比较完善。包括野战阵地防御、坚固阵地防御、要塞防御等。', 118);
INSERT INTO `t_military_term_data` VALUES ('27ae9ac5-4651-4ad7-a803-784aac3d4233', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇光电探测设备', '舰艇上利用光电技术对目标搜索、定位和跟踪的各种探测设备的统称。主要包括：激光测距仪、激光雷达,微光夜视仪,红外热像仪、红外探测与跟踪器,光电跟踪系统,潜艇光电桅杆,以及各类电视跟踪、摄像系统和水下电视等。', 242);
INSERT INTO `t_military_term_data` VALUES ('27b9ec88-90bc-4db9-8be0-b8c6767cae0a', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境涉外事务', '在边境地区发生的涉及相邻国家利益并须与之交涉的事情。如对人、畜非法越境等事情的交涉。', 93);
INSERT INTO `t_military_term_data` VALUES ('27baecba-7077-4ff1-b272-0b8bcd9ee877', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤配置地域', '后勤机关、部队和分队配置并展开工作的地域。', 49);
INSERT INTO `t_military_term_data` VALUES ('27c47599-f6d7-4c36-bfa8-986a7fa71576', '8a761efd-50a6-4ac8-9913-b7d745104f82', '半数弹着圆半径', '亦称圆公算偏差。在散布面上以平均弹着点为心,包含一半弹着点时所画出的圆的半径。常用R50表示。是衡量导弹和轻武器射弹密集度的主要指标。', 77);
INSERT INTO `t_military_term_data` VALUES ('27c4ce06-f426-492c-8c93-a9b76a150e9c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲防护力', '亦称装甲防护性能。装甲对各种武器的毁伤作用所具有的护能力。其评价指标是被击穿概率。有时也以正面主要部位不被某种规定武器的弹药击穿的最小距离表示。', 176);
INSERT INTO `t_military_term_data` VALUES ('27c9b266-6ee4-45a1-a44a-8dae5d5e56c8', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通枢纽', '数条相同或不相同的交通线交汇的中枢。包括：铁路枢纽、公路枢纽,水路枢纽,航空枢纽,陆水、陆空混合枢纽等。', 284);
INSERT INTO `t_military_term_data` VALUES ('27ce207b-c28b-43d0-b5d4-35346a77fd40', '97a19170-bfac-42c5-9906-1acb187f0654', '弹射跳伞', '飞行人员使用飞机上的弹射装置将自身弹离飞机的跳伞。', 257);
INSERT INTO `t_military_term_data` VALUES ('27d09610-8170-4140-833b-8ebc28c99ffe', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇部署', '对舰艇人员在舰艇上的战斗位置和职责的确定。分为舰艇战斗部署和舰艇日常部署,全舰性部署和舰艇部门部署。通常以表格形式表示,称舰艇部署表。', 60);
INSERT INTO `t_military_term_data` VALUES ('27d1ac58-9d4c-411f-bd37-e0025e406576', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机机降掩护', '武装直升机和作战勤务直升机保障运输直升机机降安全的作战行动。包括空中警戒、佯动、护航、火力压制等。', 90);
INSERT INTO `t_military_term_data` VALUES ('27d1ebfe-2b00-4a36-a377-0cf8845cd45d', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹头留膛', '射击武器击发后弹丸仍滞留在膛内的射击故障。', 145);
INSERT INTO `t_military_term_data` VALUES ('27d69391-5f05-44b6-b8b2-3c1538d4ee28', '97a19170-bfac-42c5-9906-1acb187f0654', '编队飞行', '两架以上的飞机或直升机组成一定队形并有指挥协同关系的飞行。', 212);
INSERT INTO `t_military_term_data` VALUES ('27e25d82-b8a0-486b-a42a-ca4eacbe3a38', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役后方', '战役军团作战的后方地域和机构的统称。', 31);
INSERT INTO `t_military_term_data` VALUES ('27ed241e-d59c-4a94-94de-81bb543c25c7', '916997ee-6728-4c61-9b79-d96960b1dc86', '战场三防建设', '为防核、化学。生物武器袭击而在预定战场进行的建设。主要包括：建立核监测报知体系,完善国防工程三防设施,储备一定的三防装备和物资器材,组织防化资料调查等。', 35);
INSERT INTO `t_military_term_data` VALUES ('280ca6c1-1cf2-4e14-afa3-6eb57e1de6f1', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术渗透', '利用有利地形或夜暗、不良天候等条件,从敌部署间隙秘密地渗入敌方战术纵深的作战行动。', 34);
INSERT INTO `t_military_term_data` VALUES ('2810b3d4-4166-4064-bb93-927f8e4d6a2d', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '院校协作中心', '以同一地区的军队院校为主,吸收该地区的部队和科研单位参加的教学与科研的协作组织。', 65);
INSERT INTO `t_military_term_data` VALUES ('282c168a-b292-409e-ae5e-b6f2214306a5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇潜望深度', '潜艇在水下能够使用潜望镜进行观察的深度。中型潜艇潜望深度约为8～1O米,大型潜艇潜望深度约为10～15米。', 299);
INSERT INTO `t_military_term_data` VALUES ('2835a0e3-9e6b-48cf-a38c-591b894a31f7', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击指挥', '炮兵指挥员及其指挥机关组织和运用炮兵火力遂行射击任务的活动。主要包括：组织射击准备,定下射击决心,选择射击手段,下达射击任务,观察射击效果，修正射击偏差和组织火力转移等。', 132);
INSERT INTO `t_military_term_data` VALUES ('283fa623-d319-4702-80f5-ef91c1785a5d', '97a19170-bfac-42c5-9906-1acb187f0654', '空中攻击', '①飞机、直升机从空中对空中目标的射击或对地面、水面、水下目标的射击与轰炸。②空战的实施阶段。自飞机占据有利的攻击位置起至飞机停止对敌射击止。主要进行攻击活动。', 79);
INSERT INTO `t_military_term_data` VALUES ('28445883-e500-4a93-9b14-87e78cad2d52', '98df76fb-4b65-48ff-a56c-4db587327c79', '军运号码', '由军事交通运输部门对每批军事运输所批予的代号。是核准运输计划、区分运输种类和等级的标志。', 268);
INSERT INTO `t_military_term_data` VALUES ('284c2991-d12e-4fda-9dee-a1c85f8043f1', '916997ee-6728-4c61-9b79-d96960b1dc86', '维埃克斯', ' 学名二异丙胺基乙基硫赶甲膦酸乙酯。神经性毒剂的一种。可装填在炮弹、航空炸弹、航空布洒器中使用。主要以液滴通过皮肤吸收中毒,也能以气溶胶通过呼吸道吸入和皮肤吸收中毒。', 214);
INSERT INTO `t_military_term_data` VALUES ('286d998e-d115-4faa-8d1d-3040d412be5c', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象火箭', '亦称探空火箭。用于中、高层大气探测的火箭。头部装有气象仪器,可探测20～100千米高度内的气压、气温、空气密度、风向、风速,以及大气成分,太阳紫外辐射和大气结构等。', 100);
INSERT INTO `t_military_term_data` VALUES ('28761c48-915c-4cfd-b23a-517fddd0af0b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸地震波', '地面或地下核爆炸所产生的在地面和地层中引起类似地震作用的冲击波。传播距离远,作用时间较长,能造成地面建筑、地下工事等较严重损坏。可据以测定核爆炸参数。', 163);
INSERT INTO `t_military_term_data` VALUES ('2891a813-7e88-4a10-bed4-3dad9db67e87', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '战略导弹', '射程为1000公里以上,用于打击敌方战略目标的导弹。按射程分为中程导弹、远程导弹和洲际导弹。', 3);
INSERT INTO `t_military_term_data` VALUES ('28b1abfc-3b04-4d06-8692-de447e0324c9', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹诸元计算保障', '为保证导弹准确命中目标并成功地爆炸,对有关数据进行的一系列计算措施。内容包括大地基础诸元计算、射击诸元计算、弹头诸元计算和导弹发射特殊情况处置的有关计算等。', 180);
INSERT INTO `t_military_term_data` VALUES ('28c4bb7f-5133-40ee-bcca-7f7c025bce7c', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军运输船', '陆军编配的专门用于物资运输的船。分为液货船、于货船、边防综合补给船、冷藏船和驳船等。主要担负向船艇基地、岛屿、边防执勤点等地运送油料、淡水、武器装备和其他军用物资的任务。', 327);
INSERT INTO `t_military_term_data` VALUES ('28caffdf-9187-42c8-8fab-edf177fedd14', '8a761efd-50a6-4ac8-9913-b7d745104f82', '隐形枪', '外形象一般生活用品的枪。多由短枪改装。有手杖式、手套式、钢笔式、照相机式等单发枪和手提箱式等连发枪。', 179);
INSERT INTO `t_military_term_data` VALUES ('28dc5cf1-dc48-46cb-9e16-b2fca94e63b4', '916997ee-6728-4c61-9b79-d96960b1dc86', '地域消毒', '对染毒地域实施的消毒。通常是对染毒地域中的主要地段、工事和进出路实施消毒,以保障部队在该地域内行动。', 64);
INSERT INTO `t_military_term_data` VALUES ('28dcb2fc-6295-421f-977d-4abbba1ba634', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战术学', '研究战斗及其指导规律的学科。是军事学术的重要组成部分,从属于战略学和战役学。主要研究内容有战斗的本质、类型、特点、基本原则和组织实施方法等。', 25);
INSERT INTO `t_military_term_data` VALUES ('28e8bfec-619e-4c7e-810d-75e36ed5861e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '胶着', '敌对双方在交战中胜负难分而又难以脱离接触的状态。', 407);
INSERT INTO `t_military_term_data` VALUES ('290334a0-a9da-4c62-9b32-ecfa217a9f00', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '首长机关演习', '团以上指挥员及其机关进行的军事演习。有首长、司令部、政治部（处）、后勤部（处）、装备技术部（处）等参加、通常使用通信工具在现地或室内实施。', 124);
INSERT INTO `t_military_term_data` VALUES ('2906051f-32a0-4db4-9f49-93b7c100c8b8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事计划', '为实现一定的政治、军事目的,对军事工作或行动预先拟制的计划。', 52);
INSERT INTO `t_military_term_data` VALUES ('290ed11d-22d3-4913-998f-26fce1909267', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵火力控制网', '简称火控网。在射击区域内按一定密度确定的火控点系统。', 218);
INSERT INTO `t_military_term_data` VALUES ('290f8f85-984c-4d19-8801-32b7374291c5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队队形', '舰艇编队航行时根据战术要求,各舰艇按照一定的关系位置形成的配置。有单列队形、复列队形和复杂队形。', 267);
INSERT INTO `t_military_term_data` VALUES ('29133208-1408-4c1e-8175-0c274e777d38', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军事秘密', '军事方面的在一定时间内只限一定范围的人员知悉的事项。如军队的部署、实力、作战行动,军事计划,军事设施等。', 70);
INSERT INTO `t_military_term_data` VALUES ('29214f81-83a4-4b82-8fbc-11302c5e21eb', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上战术展开', '舰艇编队从展开阵位汗始,由航行队形变为战斗队形并占领攻击出发（预备齐射）阵位的机动、分为预先展环和集中展开要求小确掌握展开时机,行动迅速力争缩短展开时间。', 81);
INSERT INTO `t_military_term_data` VALUES ('2927571c-478f-41ac-9c07-fb7462cc2369', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克炮稳定器', '坦克行驶时将炮身轴线保持在赋予的空间角位置的自动控制装置。用以提高坦克行进间捕捉目标和射击的能力。有单向稳定器和双向稳定器。单向稳定器,亦称高低向稳定器,只稳定火炮的射角；双向稳定器同时稳定射角和射向。', 122);
INSERT INTO `t_military_term_data` VALUES ('292ec28c-01d2-4b8a-97fc-e1f85b0c7412', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '礁', '隐现于海洋水面的岩石或珊瑚礁。有明礁、干出礁、适淹礁、暗礁等。露出大潮高潮面的为明礁；在大潮高潮面和深度基准面之间,时淹时露的为干出礁；在深度基准面时正好被海水淹没的为适淹礁；在深度基准面以下的为暗礁。', 55);
INSERT INTO `t_military_term_data` VALUES ('29493a42-89af-4192-976d-26b1e75bb121', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火箭炮', '可发射较大口径火箭弹的多发联装的炮兵武器。有牵引式和自行式两种。发射速度快、火力猛、威力大,机动性能好,但发射时火光大,阵地易暴露。主要用于对面状目标射击。', 30);
INSERT INTO `t_military_term_data` VALUES ('2954c7ac-4f06-49e1-8125-7b7921875735', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '兵力', '军队人员及其武器装备的数量。通常以建制单位或人数表述、如5个营的兵力，3万人的兵力。', 257);
INSERT INTO `t_military_term_data` VALUES ('295fca38-c1c5-4411-831b-2ec4804f2281', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '退役装备', '经一定的报批手续退出服役状态的武器装备。通常指由于战术技术性能落后,材料、结构老化,或其他原因不宜继续服役的武器装备。', 109);
INSERT INTO `t_military_term_data` VALUES ('29773a68-f4de-404d-9d33-c4f7aa4205ef', '06a75831-13a1-4660-870a-455bb445336a', '有线电通信', '利用金属导线传输电信号的通信。可传输电话、电报、数据和图像等。通信稳定,保密性较好,但机动性差。采用多路复用和增音（再生中继）设备,可实施多路远距离通信。', 121);
INSERT INTO `t_military_term_data` VALUES ('29863afe-55c1-4e76-8bea-092c827b511a', 'f0140091-c11a-48c9-8836-8aa94439dac0', '一字队形', '沿进攻正面展开成一线的战斗队形。通常在己方强大火力掩护下,通过开阔地和冲击时采用。', 57);
INSERT INTO `t_military_term_data` VALUES ('29897923-9afb-4485-ad54-1185792ee248', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事政策', '国家、政党为贯彻落实一定时期的军事路线和方针而制定的军事工作须遵循的基本行动准则。', 15);
INSERT INTO `t_military_term_data` VALUES ('29a2ce1c-4015-4b6b-b8e3-2d2864c43efd', '916997ee-6728-4c61-9b79-d96960b1dc86', '非致死性毒剂', '基本毒害作用能使中毒人员丧失战斗力的毒剂。一般不会造成死亡。如毕兹等。', 207);
INSERT INTO `t_military_term_data` VALUES ('29c62d33-6fe8-4d47-87c7-747be1e230c3', '8a761efd-50a6-4ac8-9913-b7d745104f82', '掉弹', '射击武器在射击过程中,弹药从弹链上或输押线上自行脱落的射击故障。', 131);
INSERT INTO `t_military_term_data` VALUES ('29d773fa-52d7-4f9a-a3ea-5d7abe682538', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸瞬时杀伤破坏因素', '核爆炸时产生的在较短时间内对目标起杀伤破坏作用的因素的统称。包括冲击波、光（热）辐射、电磁脉冲、早期核辐射和X射线等。', 156);
INSERT INTO `t_military_term_data` VALUES ('29dc3827-5587-4add-bc48-996c9c1d083a', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹计算发控车', '装有计算、发射控制地空导弹和通信等设备的专用车辆。主要用以测定空中目标运动参数、计算地空导弹射击诸元及控制导弹发射。', 37);
INSERT INTO `t_military_term_data` VALUES ('29dce917-527e-42fd-abb9-05fbc8a8e500', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机攻击', '武装直升机以机载火力对空中或地面、水面目标实施的进攻行动。按攻击方式,分为水平攻击、悬停攻击、下滑攻击、俯冲攻击、跃升攻击等。', 65);
INSERT INTO `t_military_term_data` VALUES ('29e9934a-03b3-4045-8a5e-044cf6dfb4d4', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '攻击声纳', '为水中武器系统提供目标的方位、距离、径向速度等要素,以保证实施攻击的声纳。一般具有自动跟踪目标能力,但作用距离较近。', 234);
INSERT INTO `t_military_term_data` VALUES ('29f7919d-775a-4424-83a1-0cb5b2615199', '98df76fb-4b65-48ff-a56c-4db587327c79', '日常储备', '为衔接进货间隔,保证日常供应不间断而进行的物资储备。储备品种主要是经常使用、消耗量较大的物资,如油料、给养、药材、零配件等。储备量根据部队消耗情况、调运周期和物资来源等因素确定。', 109);
INSERT INTO `t_military_term_data` VALUES ('29f9a73e-59b0-4614-8e91-bbb3aa2b8c95', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆储备里程', '车辆到大修或中修之前尚可行驶的里程。是车辆战备程度指标之一。', 307);
INSERT INTO `t_military_term_data` VALUES ('2a0542bb-487e-49ff-a7f3-a03bbf8ee8e3', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克单位功率', '坦克发动机功率与坦克战斗全重之比。是评价坦克机动性能的一项重要指。一般为12～20千瓦／吨。', 152);
INSERT INTO `t_military_term_data` VALUES ('2a289d78-9a99-4473-961c-177276112b2a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军队', '国家或政治集团为准备和实施战争而建立的正规武装组织。是执行政治任务的武装集团。', 90);
INSERT INTO `t_military_term_data` VALUES ('2a3168ed-dc49-454e-bea3-2fcbb552e2a5', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '进攻方向', '亦称突击方向。军队向防御之敌实施攻击并向纵深发展进攻的行动方向。分为主攻（主要突击）方向和助攻（辅助突击）方向。', 87);
INSERT INTO `t_military_term_data` VALUES ('2a41ebae-bc9e-4ebb-9a72-7ec32eaae6b4', '8a761efd-50a6-4ac8-9913-b7d745104f82', '最大射程', '某种武器在标准条件下射击时，其射弹飞行所能达到的最大水平距离。', 54);
INSERT INTO `t_military_term_data` VALUES ('2a4caee0-d165-4d69-ae80-86b1b70c5678', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上护航', '海军兵力对己方舰船或舰船编队进行护送和掩护的行动。分为全程护航和区域护航护航方式有伴随护航、待机护航和综合护航。护航兵力通常为水面舰艇和海军航空兵,必要时可用潜艇,在近岸海区还可使用海军岸防兵。', 41);
INSERT INTO `t_military_term_data` VALUES ('2a569a69-a60d-4441-8f7f-b693643d46f0', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程作业能力', '部队在一定条件下遂行工程作业任务的能力。包括可遂行工程任务的种类,完成工程任务的速度和质量。主要取决于部队的素质、编制、装备、物资保障和战场环境等因素。', 29);
INSERT INTO `t_military_term_data` VALUES ('2a5b1285-f59c-429b-9bc2-8fd1b58f28d6', '8a761efd-50a6-4ac8-9913-b7d745104f82', '拦阻射击', '在目标运动方向的前方选定拦阻点或拦阻线,若干射击武器对运动之敌同时进行的概略射击。分为固定拦阻射击和移动拦阻射击。', 101);
INSERT INTO `t_military_term_data` VALUES ('2a5fe5dc-ea13-4bfb-b92c-354d5f67d7cd', '916997ee-6728-4c61-9b79-d96960b1dc86', '亚当氏气', '学名氯化二苯胺胂。主要作用于鼻、咽的喷嚏型刺激剂。鼻、咽受刺激后,引起连续喷嚏、咳嗽,严重时产生胸闷、头痛、恶心、呕吐以及流泪等症状。', 225);
INSERT INTO `t_military_term_data` VALUES ('2a75dfc5-1e60-4e0c-8039-181e95119b16', '98df76fb-4b65-48ff-a56c-4db587327c79', '车日', '军用车辆动态的计算单位。每车每天为 1个车日。分为实有车日、完好车日、出勤车日、停驶车日、非完好车日等。', 303);
INSERT INTO `t_military_term_data` VALUES ('2a7b355e-07c6-4379-8a40-c5eb97ca3c39', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '微波技术', '研究微波的产生、传输、测量、控制及其应用的技术。微波是频率为300～300000兆赫或波长为1米～l毫米的电磁波,能象光波一样直线传播和会聚。军事上广泛应用于侦察、制导、导航、火控、通信以及研制微波武器等方面。', 21);
INSERT INTO `t_military_term_data` VALUES ('2a7c0d11-3380-431f-90eb-8109308759f7', '878651de-adf5-4c72-9376-9c363b893ff8', '战略外线', '军队处于战略进攻或对敌战略包围的态势。相对于战略内线而言。', 88);
INSERT INTO `t_military_term_data` VALUES ('2a7c7a5a-cf5d-4fd8-a36a-f340a11b7dfb', '916997ee-6728-4c61-9b79-d96960b1dc86', '半数伤害浓度', '在一定时间内能使50％无防护人员丧失战斗力的染毒浓度。用IC50表示。', 127);
INSERT INTO `t_military_term_data` VALUES ('2a818ff4-f682-497e-b82e-32a885838098', '8a761efd-50a6-4ac8-9913-b7d745104f82', '初速', '射弹脱离火身口瞬间的飞行速度。通常以米\\秒表示。是决定射程远近的主要因素。', 45);
INSERT INTO `t_military_term_data` VALUES ('2a854a9d-61e7-4fc6-9504-022f6f2bbe70', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '山腰', '亦称山腹。山顶到山脚的中间部分。', 17);
INSERT INTO `t_military_term_data` VALUES ('2a8d8823-b330-4f18-b86d-480a1fd49e80', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '北京时间', '中华人民共和国统一采用的标准时。是北京所在的东八时区的区时,即以东经120度子午线为准的地方平太阳时。比格林尼治时间早8个小时。', 213);
INSERT INTO `t_military_term_data` VALUES ('2a96bbef-f894-437a-beb9-86412e99f52f', '31f4a446-5b98-4873-9d53-310d97125b07', '战略导弹部队配套建设', '战略导弹部队为形成整体作战能力而进行的全面建设。包括人员、体制编制、武器装备、阵地、作战指挥系统及各种保障等方面的建设。', 7);
INSERT INTO `t_military_term_data` VALUES ('2a9adc43-47ec-44ff-94cc-0d2295edba4c', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '全训', '全年中以大多数的兵力、大部分或全部的时间进行军事训练。中国人民解放军中担任全训任务的部队,年度训练时间通常规定为：陆军部队、海军舰艇部队在10个月内安排,空军航空兵部队在12个月内安排；要求参训单位数与编制单位数之比、单位的参训人数与实力数之比均达80％以上。', 9);
INSERT INTO `t_military_term_data` VALUES ('2ab0274d-9b77-4bfd-8971-ce9dc624bb50', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力支援', '以火力对部队作战行动进行支援。通常由炮兵、航空兵、舰艇部队和战役战术导弹部队等实施。包括军兵种之间、友邻之间以及上级对下属部队或分队的火力支援。', 97);
INSERT INTO `t_military_term_data` VALUES ('2ab80117-e015-486b-8e89-aca34221f866', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮行军中射击', '小口径高炮或高射机枪分队,在运动过程中对空中目标或地面、水面目标进行的射击。分为短促停顿间（短停）射击、行进间射击和临时放列射击。在掩护部队行军、开进、展开、转移和独立行军时采用。', 177);
INSERT INTO `t_military_term_data` VALUES ('2ac7bab3-0365-427d-b8ac-322afa017f26', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '掩蔽所', '供隐蔽装备、物资用的掩蔽工事。', 69);
INSERT INTO `t_military_term_data` VALUES ('2ac99147-c799-44fd-9255-f28dd7f8e3e9', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '后勤部（处）', '军队中主管后勤工作的领导机关。一般在团级以上部队或单位设立。在本部队或单位首长领导下,负责领导和管理各项后勤业务,组织实施后勤保障工作等。', 6);
INSERT INTO `t_military_term_data` VALUES ('2ad0a13d-3695-4032-9d44-dce6d8eee0ba', 'f0140091-c11a-48c9-8836-8aa94439dac0', '乘车战斗', '机械化步兵或伞兵乘坐步兵战车、装甲输送车或伞兵战车进行的战斗。通常在地形有利,受敌反坦克火力和障碍物威胁不大时,为提高进攻速度而采用。', 177);
INSERT INTO `t_military_term_data` VALUES ('2ad32564-267a-485f-a706-eb7e94db7203', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事模拟', '按照已知的或设定的条件和数据、借助于电子计算机等手段对军事工作或军事活动所进行的模仿。通过数据计算、图形显示和演练动作等,形象地揭示军事工作或军事活动的演变过程及其结果,为军事决策提供一定依据。', 60);
INSERT INTO `t_military_term_data` VALUES ('2ad9b0d6-39db-4332-a7e6-e29410957d40', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '帽堡工事', '以装甲帽堡或钢筋混凝土帽堡作为顶部构件的工事。多用于观察和射击。', 74);
INSERT INTO `t_military_term_data` VALUES ('2adfb65f-2f4a-49f0-92ef-436b67fd754b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '机动作战', '①任务、地点、战法不事先固定,根据实际情况进行的作战。②由一地机动到另一地及其过程中所进行的作战。', 189);
INSERT INTO `t_military_term_data` VALUES ('2ae26941-0b45-4bda-8089-c09df623d47f', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '征兵', '按照义务兵役制的规定,征集公民服现役的工作。', 31);
INSERT INTO `t_military_term_data` VALUES ('2ae5dc3b-44b9-483d-b954-47b7e9c5a731', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学反击', '遭敌化学武器袭击后,以化学武器进行的反击。', 26);
INSERT INTO `t_military_term_data` VALUES ('2ae6738a-7f5e-45ea-8a51-987c75616a55', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰位', '舰艇所在的地理位置。用地理坐标（包括经度和纬度）或相对于某一固定物标的方位与距离表示。', 273);
INSERT INTO `t_military_term_data` VALUES ('2aecc4df-19cf-4284-a5ea-f58a1c64a97b', '8a761efd-50a6-4ac8-9913-b7d745104f82', '滑机', '射击武器的发射机构控制失灵引起的意外击发的射击故障。', 134);
INSERT INTO `t_military_term_data` VALUES ('2af33e22-cb31-4513-bf78-faa1615c2f82', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军队学员', '军队院校和其他训练机构学习的军人。', 121);
INSERT INTO `t_military_term_data` VALUES ('2af55e33-1d5a-4e1f-be5d-1f06b633a0e9', 'f0140091-c11a-48c9-8836-8aa94439dac0', '三角队形', '展开成三角形的战斗队形。分为前三角队形和后三角队形。', 58);
INSERT INTO `t_military_term_data` VALUES ('2b03b80e-1343-4f23-bfc2-4ac985624228', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥体制', '军队指挥公机构设置、职能划分和相互关系等方向所确定的组织制度、分为平时指挥体制和战时指挥体制。', 5);
INSERT INTO `t_military_term_data` VALUES ('2b08f1b0-63c8-4f10-a49b-ed36b7ba400e', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵指挥所', '防空兵指挥员及其指挥机关实施作战指挥的临时性机构。防空兵旅、团通常建立基本指挥所、预备指挥所和后勤指挥所；防空兵营、连只建立基本指挥所。', 93);
INSERT INTO `t_military_term_data` VALUES ('2b15ea91-17e8-458f-bdbb-fbafd7abbbb9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '会战', '战争双方军队主力或战区主力之间进行的大规模作战。通常指战略性战役。如中国人民解放战争时期的辽沈战役亦称辽沈会战。', 201);
INSERT INTO `t_military_term_data` VALUES ('2b1d19b2-007c-47bf-b23f-da15ff292a50', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '噪声干扰', '幅度、频率、相位随机变化的电子干扰。其性质与电子设备的接收机内部噪声相似。可遮盖和压制敌电子设备接收的有用信号,使其电子设备获取的信息大大减少。', 57);
INSERT INTO `t_military_term_data` VALUES ('2b2a117a-3e37-4aab-ba08-7a2e68ebc51b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '长弹', '炮弹长度比发射该弹的迫击炮身管长的一种迫击炮弹。威力比普通迫击炮弹大。', 324);
INSERT INTO `t_military_term_data` VALUES ('2b2d17c5-8563-4993-96dc-4675fd86c9ef', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军队礼仪', '军队在日常活动、节日、庆典及其他场合,为表示庄严、隆重和敬意而行使的礼节和举行的仪式的统称。一般包括敬礼、升旗、鸣礼炮和阅兵等。通常由有关条令、条例及其他法规性文件统一规定。', 51);
INSERT INTO `t_military_term_data` VALUES ('2b2daa54-22f5-4820-b03c-a07cc3e179d1', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵决定诸无误差', '由于决定射击诸元不精确而产生的射弹散布中心对目标的误差。本要包括测地准备误差、弹道准备误差、技术准备误差、气象准备误差、决定目标位置误差和射表误差等。', 244);
INSERT INTO `t_military_term_data` VALUES ('2b54382f-179e-464a-9296-9326540dca35', '98df76fb-4b65-48ff-a56c-4db587327c79', '医疗后送', '对伤病员实施救护治疗和后送的卫勤保障活动。包括从伤病员负伤、患病开始到治疗终结、离开救治机构的全过程。是战时卫勤保障的中心任务。', 192);
INSERT INTO `t_military_term_data` VALUES ('2b54dc28-9e9c-4bbd-a9a8-55eb2448121d', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '战斗警报', '出现紧急或危险情况并要求部队立即进入战斗状态时发出的警报。', 38);
INSERT INTO `t_military_term_data` VALUES ('2b575664-36a2-4925-b92d-ea0a959bbaca', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上突击群', '海战中担负突击任务的海上战术群、分为预先突击群、主要突击群和辅助突击群。可由性能相同的兵力编成,如导弹艇突击群、潜艇突击群和海军航空兵突击群等。也可由性能不同的兵力编成,如航空母舰突击群等。', 64);
INSERT INTO `t_military_term_data` VALUES ('2b581757-c710-4ddc-8c23-2e419dd422e8', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '北斗星', '简称北斗。大熊星座中排列成斗形的7颗亮星。星名分别为a、R、Y、S、。、和0。从p向a的连线延长5倍,可找到北极星。', 193);
INSERT INTO `t_military_term_data` VALUES ('2b5982ba-7b8f-472f-aba6-d2869aeb7d2c', '878651de-adf5-4c72-9376-9c363b893ff8', '战争', '敌对双方为了一定的政治、经济目的,有组织有计划地使用武力进行的激烈的军事对抗活动。是解决阶级、民族、政治集团、国家之间矛盾冲突的最高斗争形式。是政治通过暴力手段的继续。', 0);
INSERT INTO `t_military_term_data` VALUES ('2b5cc827-6fb3-4cba-aec3-4df0d8ebddc9', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队战斗序列', '海战中舰艇编队内各战术群的编成和配置。', 75);
INSERT INTO `t_military_term_data` VALUES ('2b778e72-745a-4d25-ab59-7c8d01ddfb12', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '岸勤部', '亦称舰艇基地。主要担负舰艇部队后勤保障和技术保障任务的海军团一级组织。隶属于海军基地或舰艇支队。编有技术队、勤务船中队、通信站、装备修理所、医疗所、码头管理所、仓库等。', 12);
INSERT INTO `t_military_term_data` VALUES ('2b78f548-0e5a-4f05-9b9c-c0453f52869d', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天气现象', '发生在空中和地面上的各种大气物理现象。主要包括；降水、水汽凝结（云除外）和冻结,大气的声、光、电现象,以及一些与风有关的特征等。', 24);
INSERT INTO `t_military_term_data` VALUES ('2b7c288d-7744-44e5-9729-8e95a423bae0', '878651de-adf5-4c72-9376-9c363b893ff8', '防战略突袭', '防范和抗击敌人的战略突袭。用以保存己方的有生力量和战争潜力,稳定战略防御体系,为尔后的作战创造条件。', 115);
INSERT INTO `t_military_term_data` VALUES ('2b9404f3-24f9-4618-815d-db2263c40eae', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '空间站', '亦称航天站、太空站或轨道站。在太空具备一定试验或生产条件、可供航天员生活和工作的长期运行的航天器。分为单一式空间站和组合式空间站。在太空运行期间,靠载人飞船和航天飞机等接送航天员、运送货物和设备。主要用于；航天医学、生物学和生命科学的研究,地球资源勘测和国土普查,军事侦察和大地测量,微重力环境下新材料、高纯药物生产的试验,天文学观测等。', 222);
INSERT INTO `t_military_term_data` VALUES ('2b9560ce-9bdd-48e9-a044-464e3556ce15', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥自动化网文电', '通过指挥自动化网传送的军用文书。', 117);
INSERT INTO `t_military_term_data` VALUES ('2b9af6a3-4f08-404e-8cf0-fa8204e397b7', '98df76fb-4b65-48ff-a56c-4db587327c79', '铁路舟桥', '用制式舟或民船作为浮动基础,能通行列车的铁路浮桥。具有一定的机动性和快速展开与撤收的能力。是战时和抢险救灾时通过较大江河障碍的桥渡形式之', 262);
INSERT INTO `t_military_term_data` VALUES ('2ba061da-942b-4a5f-bc85-61cf268f2e82', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤保障', '为满足军队建设、作战和生活需要,各种后勤专业采取的各项保证性措施进行的相应活动的统称。主要包括经费保障、物资保障、卫生保障、交通运输保障、工程建筑与营房保障等。', 22);
INSERT INTO `t_military_term_data` VALUES ('2ba9d3b9-3938-4f1a-be62-98ec0ce73041', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '关照全局', '指挥员及其指挥机关照顾到各个方面的情况,使每一个局部行动都符合总的意图。', 31);
INSERT INTO `t_military_term_data` VALUES ('2bbfad58-ac42-44c9-9fb5-89fe6ce620df', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '超越换班', '在交班部队或分队占领地域的前方实施的换班通常在进攻战斗准备时进行。', 102);
INSERT INTO `t_military_term_data` VALUES ('2bc08f0b-b466-412c-a779-ac8778158111', '98df76fb-4b65-48ff-a56c-4db587327c79', '散装油料', '用油罐、油罐车、油船等大型容器储运或用管线输送的油料。', 177);
INSERT INTO `t_military_term_data` VALUES ('2bc4b7eb-a629-44de-8dc3-2c17c5b85efb', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战役侦察', '为获取战役行动所需情报而进行的侦察。通常由战役指挥员及其司令部组织。', 2);
INSERT INTO `t_military_term_data` VALUES ('2bd6701e-fa58-4757-ac24-e2d8cc2c63f4', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核弹头', '装有核战斗部的弹头。一般由核战斗部及承载壳体组成,有的还包括制导、突防等装置。', 125);
INSERT INTO `t_military_term_data` VALUES ('2bdaa618-114c-4eb5-ae7d-be3cb05faf05', '98df76fb-4b65-48ff-a56c-4db587327c79', '综合运输', '运用多种运输方式组织实施的运输。主要指对铁路、公路、水路、航空、管道等运输方式的综合运用。', 249);
INSERT INTO `t_military_term_data` VALUES ('2bdb2940-70bb-4d04-b3a0-a2778bd1de5d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇下潜', '潜艇由水面状态转为水下状态或由小深度转为大深度的行动。分为正常下潜和速潜。可在停止或行进间进行。', 294);
INSERT INTO `t_military_term_data` VALUES ('2be29d16-9188-4c8d-b81f-9ee7e086c72b', '878651de-adf5-4c72-9376-9c363b893ff8', '战略空袭', '从空中对敌政治、经济、军事等战略目标实施的大规模袭击。目的是削弱对方的战争力量,保证己方战略行动的顺利实施。', 111);
INSERT INTO `t_military_term_data` VALUES ('2be49201-1e1f-45ba-be15-f9dde0b1628a', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防会谈', '相邻两国边防部门就重大边境涉外事务进行交涉、处理的商谈活动。通常由双方边防代表在预定的边境地点进行。', 120);
INSERT INTO `t_military_term_data` VALUES ('2be51b7e-2150-4959-8733-1411186adfcb', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '警戒配系', '担任警戒的部队、分队按照战斗要求进行配置所形成的系统。通常有环形的和立体的警戒配系。', 5);
INSERT INTO `t_military_term_data` VALUES ('2bf557e4-7e25-41f5-b325-861c8557ebd6', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '建制', '按编制编成的军队各种组织及其隶属关系。如编制规定第1师下辖第1、第2、第3团,这3个团即属第1师建制,都是第1师的建制单位；由这3个团编成的第1师称建制师。', 79);
INSERT INTO `t_military_term_data` VALUES ('2bf852c7-b0ec-4910-a4bf-9cd2b57f135e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克集中火力', '坦克连、排将全部或大部火力集中射向一个目标。', 44);
INSERT INTO `t_military_term_data` VALUES ('2c02c003-a84c-452a-a24e-6dd8409495ba', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事交流', '国家、政治集团或军队之间按照彼此需要在军事方面的相互交往或给予。包括军事人员、军事物资、军事技术、军事信息等方面的交流。', 76);
INSERT INTO `t_military_term_data` VALUES ('2c03d1d5-7147-4922-a7d0-c60da9676aca', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵导航保障', '为引导飞机或直升机起飞、着陆和按预定的航线飞行而在导航方面进行的保障、包括机场导航、航路导航和野战导航等方面的保障。', 357);
INSERT INTO `t_military_term_data` VALUES ('2c0ae8f2-c3bd-488b-849d-5f2c85116740', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹道气象修正诸元', '影响地弹飞行的气象要素与其标准值（在定值）间的偏差量的统称。主要包括气压偏差量、温度偏差量、空气密度偏差量和风的偏差量等。', 63);
INSERT INTO `t_military_term_data` VALUES ('2c0c5cc6-b983-4dfb-919f-5f2cc923a15e', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '齐头并进', '进攻的军队分数路向同一方向、基本等齐地平行前进。', 106);
INSERT INTO `t_military_term_data` VALUES ('2c104b89-aafd-4373-ab79-a49fd7b88f36', '8a761efd-50a6-4ac8-9913-b7d745104f82', '步枪', '单兵使用的长管肩射枪。可以火力杀伤生动目标,还可进行格斗,有的能发射枪榴弹。按自动化程度,分为非自动装填步枪和自动装填步枪；自动装填步枪又分为半自动步枪和自动步枪。', 161);
INSERT INTO `t_military_term_data` VALUES ('2c176aed-0e18-4d2f-9bb6-905dfc575c77', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '野战防空', '部队在野战条件下为保障其空中安全而组织实施的防空。', 219);
INSERT INTO `t_military_term_data` VALUES ('2c1ad934-8887-4c14-9c66-a08cec222fbf', '97a19170-bfac-42c5-9906-1acb187f0654', '作战值班飞机', '担负作战值班任务,处于待命出动状态的飞机。作战值班飞机的数量和状态,由航空兵部队依据战备制度或上级命令确定。', 42);
INSERT INTO `t_military_term_data` VALUES ('2c1c180c-8032-4cfe-b3b3-c306b965e868', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹杀伤区', '地空导弹发射后能以不低于某一概率毁伤空中目标的空间区域。通常以杀伤区的远界、近界、高界、低界、侧界等特征参数表示。', 139);
INSERT INTO `t_military_term_data` VALUES ('2c1f94a9-e14b-484b-a006-311032195b5a', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹打击目标能力', '导弹对被打击目标的毁伤能力。分为打击软目标能力和打击硬目标能力。打击软目标能力用核弹头的等效百万吨当量EMT表示,打击硬目标能力用硬目标摧毁力表示。', 20);
INSERT INTO `t_military_term_data` VALUES ('2c22c045-7d4f-4ce7-97ab-cc983976e0b8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '跟进', '在前面部队、人员的后方或侧后方,按要求保持一定距离跟随前进的行动。', 339);
INSERT INTO `t_military_term_data` VALUES ('2c2e079d-a68e-4dae-b9e6-9af092c89483', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军队管理', '按照有关军事法规对军队各项活动所进行的计划、调控、组织、领导等工作的统称。', 98);
INSERT INTO `t_military_term_data` VALUES ('2c370684-3336-4a32-8cb7-6b7f3e498458', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '要图', '标绘有军事情况的地形图、地形略图和像片图的统称。主要用以标绘作战情况,或作为作战文书的附件等。', 269);
INSERT INTO `t_military_term_data` VALUES ('2c3862ac-94df-4864-b9f4-93de9067604a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '激光侦察', '使用激光器材进行的侦察。主要器材有激光测距机、激光测速仪、激光雷达、激光扫描相机、激光电视和激光目标指示器等。', 53);
INSERT INTO `t_military_term_data` VALUES ('2c41bda8-88b2-4721-8b6f-180b0bb4315f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸次声波', '核爆炸冲击波在传播中蜕变形成的频率低于20赫的声波。沿地面至50千米高空的大气层中传播。可依据探测到的次声波信号,计算出核爆炸参数。', 162);
INSERT INTO `t_military_term_data` VALUES ('2c55aece-5a0f-4c2d-bcc4-b54812745aee', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹技术保障部队', '担负导弹的各项技术保障任务的部队。主要任务是对导弹武器系统的储存、保管、运输、检查测试、维护保养、修理检验、零备件供应等。', 5);
INSERT INTO `t_military_term_data` VALUES ('2c662bc4-b713-464a-a7b1-6a7019238c22', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '自然电子干扰', '简称自然干扰。由自然界中的物体和各种自然现象辐射或反射的电磁波而造成的电子干扰。可使电子设备的效能降低甚至短时期失效。主要有天电干扰、宇宙干扰、电离层扰动干扰、极光干扰以及地形地物和气象现象反射电磁波造成的干扰等。', 45);
INSERT INTO `t_military_term_data` VALUES ('2c91184e-f091-482c-96f9-4c59aeea63ff', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '战评', '对作战情况进行的群众性的评议和检查总结的活动。是中国人民解放军战时开展军事民主和政治民主的一种方式。一般在战斗间隙和战后进行。主要内容是发动官兵评斗志、评指挥、评战术、评技术、评纪律以及评功评奖等。', 36);
INSERT INTO `t_military_term_data` VALUES ('2ca3ffae-88f4-4daa-8e4c-50795a84c1f7', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地形判读', '根据航空、航天像片上的影像判明相应实地的地貌和地物性质、状况的作业。用以测制地形图和研究地形等。', 247);
INSERT INTO `t_military_term_data` VALUES ('2caef01f-1b9f-4676-bc0f-779e271d4c2c', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '间曲线', '亦称十距等高线。在地形图上按1／2等高距描绘的等高线。以长虚线表示,用以显示基本等高线不能显示的局部地貌。', 283);
INSERT INTO `t_military_term_data` VALUES ('2cb50053-13f0-4105-a0dc-3bfed54d3230', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '编制员额', '军队编制规定的建制单位人员数量的限额。', 60);
INSERT INTO `t_military_term_data` VALUES ('2ccff5ff-429f-41f2-b8f9-f9628bd91178', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '生存力', '有生力量、武器装备、技术器材等在险恶环境或作战中所具有的保存生命或保持战术技术性能的能力。', 272);
INSERT INTO `t_military_term_data` VALUES ('2cd1c794-d868-4ab4-9ca2-0096282cd4ca', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军队史', '关于军队的产生及其发展的历史。是军事历史学的重要研究内容。', 36);
INSERT INTO `t_military_term_data` VALUES ('2cd4835d-d366-4640-bae2-9f944c2df5b2', 'f0140091-c11a-48c9-8836-8aa94439dac0', '追击战斗', '追歼退却、溃逃之敌的战斗。', 131);
INSERT INTO `t_military_term_data` VALUES ('2cd871f0-a3ee-4706-ad54-1cf87e629f5d', '98df76fb-4b65-48ff-a56c-4db587327c79', '装备维修管理费', '军队用以维修、保养、管理武器装备和器材,以及与管理、维修活动有关的经费。', 85);
INSERT INTO `t_military_term_data` VALUES ('2cdb2edd-0c24-4cd0-bf94-1d6813caed3d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '无害通过权', '亦称无害通行权。在领海和群岛国的群岛水域,各国船舶享有的在不损害沿海国的和平、良好秩序或安全的情况下继续不停和迅速通过的权利。行使无害通过权应遵守有关的国际规章、制度和惯例。沿海国有权制定有关无害通过的法律和规章,并可在领海内采取必要的措施防止非无害的通过。', 373);
INSERT INTO `t_military_term_data` VALUES ('2cdb94e3-70c0-4594-a1ea-574d2c051694', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火准备', '在步兵、坦克进攻发起前或冲击直前,炮兵集中火力对敌进行的有组织、有计划的火力突击。主要在对阵地防御之敌进攻时实施。用以破坏敌防御体系,削弱其抵抗能力,为顺利突破创造条件。通常采取急袭射击与破坏射击相结合的方法进行。', 65);
INSERT INTO `t_military_term_data` VALUES ('2ce4c28d-7229-4781-8604-d4b64742bf0a', '06a75831-13a1-4660-870a-455bb445336a', '无线电管理', '对无线电频谱的使用和无线电台的设置、使用进行的管理。主要任务是：统管无线电频率的划分和指配,统筹安排无线电台、站的建设布局,审定台、站技术指标和具体位置,监督管理台、站的设置和使用,指导无线电通信保密,对消除工业电气干扰提出建议,维护空中电波秩序,防止相互干扰和敌人的无线电窃密等。', 35);
INSERT INTO `t_military_term_data` VALUES ('2cee4ee4-7d26-489d-9ddf-6f2b56084ab4', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇区域游猎法', '亦称潜艇区域巡逻法。潜艇在指定的较宽阔的海区内,采取游动与待机相结合的方式,主动搜索并袭击敌舰船的作战方法。', 90);
INSERT INTO `t_military_term_data` VALUES ('2cf852c9-7538-49c6-8c45-b8cc041f12e2', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '反辐射导弹', '利用敌方电磁辐射源发射的信号进行自导引、跟踪并摧毁该辐射源的导弹。如反雷达寻弹。', 145);
INSERT INTO `t_military_term_data` VALUES ('2d0c6e05-88e3-40fe-b2f5-50f6dc99665a', '98df76fb-4b65-48ff-a56c-4db587327c79', '军事交通勤务', '组织实施军事运输和交通保障的专业勤务。', 242);
INSERT INTO `t_military_term_data` VALUES ('2d1d84d2-e9e2-45eb-b49d-b05abd0d0f4c', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '非战斗损失', '由于事故或其他非战斗原因造成的人员、武器装备和物资等的损失。', 94);
INSERT INTO `t_military_term_data` VALUES ('2d27c34b-3c76-43aa-9329-9bac6a373825', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '观察所', '观察当面情况的场所。分为合成军队观察所、各兵种观察所和边海防观察所等。通常由各级侦察部门开设。', 75);
INSERT INTO `t_military_term_data` VALUES ('2d41613a-3f16-4185-8cac-56d5efe0fba4', 'f0140091-c11a-48c9-8836-8aa94439dac0', '侧方阵地', '在防御部署翼侧构筑的阵地。通常在防御部署暴露翼侧的有利地形上构设,以保障翼侧安全。', 229);
INSERT INTO `t_military_term_data` VALUES ('2d69b939-119e-48cc-9b2c-468d0f4de425', '97a19170-bfac-42c5-9906-1acb187f0654', '空军雷达情报', '空军雷达部队利用雷达获取的空中目标的情报。通常分为目标坐标情报、目标性质情报和干扰情报等。', 390);
INSERT INTO `t_military_term_data` VALUES ('2d727e10-f10a-416e-b73c-a6c79e8ad6e2', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹航区', '导弹飞经的空间及其弹道投影的区域。', 124);
INSERT INTO `t_military_term_data` VALUES ('2d788a65-d1cd-47ad-85ba-cf5f27f0a854', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '弹射式发射装置', '在导弹的发动机点火前以燃气或蒸汽为动力将导弹快速推离发射器的发射装置。由弹射动力系统、发射筒和减震装置等部分构成。潜地导弹和陆基机动发射导弹多采用弹射式发射装置。', 64);
INSERT INTO `t_military_term_data` VALUES ('2d7a5e3f-ffff-4208-b427-5c3f061f2e49', '878651de-adf5-4c72-9376-9c363b893ff8', '战略动向', '战略企图或战略行动所显露出来的迹象及发展趋向。准确而适时地掌握对方的战略动向,是进行战略预测、作出战略判断和决策的前提。', 66);
INSERT INTO `t_military_term_data` VALUES ('2d7cdfa6-bf84-4069-90ea-dd75481dff77', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核电磁脉冲弹', '简称EMP弹（按英文缩写）。以增强电磁脉冲效应为主要杀伤破坏因素的特殊性能核武器。可利用其在大气层外爆炸时产生的强电磁脉冲,毁坏敌方的通信系统及电子设备。', 97);
INSERT INTO `t_military_term_data` VALUES ('2d7e681b-ab69-4370-a61b-92f94ca3dd54', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '高技术', '亦称高新技术。科学技术领域中处于前沿或尖端地位,对促进经济和社会发展、增强国防力量有巨大推动作用的技术群。是动态的、发展的概念。当代高技术主要指信息技术、新材料技术、新能源技术、生物技术、航天技术和海洋开发技术等。高技术在军事上的应用,导致了精确制导、隐身、定向能、电子对抗、侦察卫星以及指挥自动化等武器装备的出现,对军事活动产生了重大影响。', 2);
INSERT INTO `t_military_term_data` VALUES ('2d7ebb1a-2d76-4253-9bcf-d6c37a5d05b4', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '常规武器', '以化学能及其转化的动能毁伤目标,牵连损伤较小的武器。相对于核、化学、生物等大规模杀伤破坏性武器而言。其弹药的装填物通常是火炸药或燃烧剂。', 40);
INSERT INTO `t_military_term_data` VALUES ('2d87b058-e05b-4179-b607-ad43a82a1a63', '97a19170-bfac-42c5-9906-1acb187f0654', '复飞', '飞机在着陆的下滑阶段因某种原因而中止下滑,重新转入正常上升的飞行。分为指挥复飞和主动复飞。', 242);
INSERT INTO `t_military_term_data` VALUES ('2d89470c-95ca-42d1-bfc2-32b7d065ecd0', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲补给车', '装有专用方舱和装卸设备的装甲保障车辆。用于野战条件下为装甲车辆补给弹药、油料、器材等物资。', 106);
INSERT INTO `t_military_term_data` VALUES ('2d8d56a5-41d4-461b-a605-0b13f401b527', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防公路', '在国家公路干道网中选定的或专门修建的用于国防的公路。是国防交通网的组成部分。对平时、战时军事运输和国民经济建设具有重要作用。', 60);
INSERT INTO `t_military_term_data` VALUES ('2d95da10-605c-4451-9939-51db4db752c1', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '计划', '对作战和其他工作预先做出安排的军用文书、如作战计划,各种保障计划,行军输送、换班计划,军事训练计划等。', 86);
INSERT INTO `t_military_term_data` VALUES ('2d9752b2-c0bf-44c8-9d12-f2a13ebd14a6', '06a75831-13a1-4660-870a-455bb445336a', '电传打字机', '简称电传机。用打字方式直接拍发和自动收录并打印成报文的用户设备。有机械式和电子式两种。用以进行人工发报、自动发报和自动转报。', 203);
INSERT INTO `t_military_term_data` VALUES ('2d9ee03f-4c3a-4566-9f53-3c2813b1f34b', '31f4a446-5b98-4873-9d53-310d97125b07', '装填导弹', '用装填设备将导弹从发射井口吊放在井内发射台上或将导弹水平装填在发射简内的过程。分为整体装填和分级装填。是井式发射或发射筒发射的导弹技术准备的一项重要工作。', 81);
INSERT INTO `t_military_term_data` VALUES ('2da98992-07a7-4bfa-bd2a-f1af591d058a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '阵地战', '正规部队依托阵地进行防御或对据守阵地之敌实施进攻的作战形式。', 141);
INSERT INTO `t_military_term_data` VALUES ('2dc6a23d-336e-4087-bfcc-5bdabfe5219f', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教学装备', '供教学用的各种武器、技术装备和器材的统称。', 183);
INSERT INTO `t_military_term_data` VALUES ('2dccd508-bc39-4ba1-b6b9-ffaa9b940467', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥员', '①军队中的各级军事主官、②军队中负责作战指挥或军事行政工作的各级领导干部、③军队干部的泛称、相对于战斗员而言。如指战员中的指挥员即指所有军队干部', 42);
INSERT INTO `t_military_term_data` VALUES ('2dce483e-7b46-43de-a8a2-ce57bb699a75', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '观通站', '观察通信站的简称。设在海岸和岛屿的制高点,担负对海观察和通信任务的专业勤务分队。隶属于观通营。主要担负对海面的观察,兼顾对低空的观察,负责对近岸活动的舰船实施导航、引导,以及舰艇与岸上指挥机关之间的通信联络。', 17);
INSERT INTO `t_military_term_data` VALUES ('2de96653-9361-4e9e-9657-df26896a321d', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军梯队', '行军纵队中本队按任务和行动顺序编成的梯队。前后梯队的区分通常与战斗展开顺序一致,无特殊需要,不打乱部队建制。', 58);
INSERT INTO `t_military_term_data` VALUES ('2df81878-1a34-415e-8fa3-f58d1e5d137f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '航空摄影测量', '简称航测。利用航空像片确定所摄目标的形态、大小、空间位置及其性质的技术。是测绘地形图的主要方法。', 242);
INSERT INTO `t_military_term_data` VALUES ('2df95687-86e4-49e6-948b-ec7544efda5e', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学事故应急救援', '对有毒、有害化学物质失控外泄造成的意外事故实施的紧急救援。主要包括；对化学事故危害地区实施化学监测,查明事故原因并排除事故危害,抢救伤员,组织群众撤离等。', 82);
INSERT INTO `t_military_term_data` VALUES ('2e06092b-12a5-4cf9-8af1-b47e75c0df7d', '878651de-adf5-4c72-9376-9c363b893ff8', '战争目的', '以通过战争手段想要达到的最终结果。包括战争的政治目的、经济目的和军事目的等。', 36);
INSERT INTO `t_military_term_data` VALUES ('2e107485-54f6-4a30-8731-c3f5f6e43230', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '摩托化步兵', '能以建制内的轮式载重车辆实施机动,下车进行战斗的步兵。', 38);
INSERT INTO `t_military_term_data` VALUES ('2e3881ef-5ce9-4cff-bacf-a65c1791c3db', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫生监督', '军队卫勤部门对所管辖单位执行有关卫生法规情况进行的监察与督导。如营养、食品、给水卫生监督,个人、环境卫生监督等。', 207);
INSERT INTO `t_military_term_data` VALUES ('2e3b22d6-8bf1-496c-bac8-f68da8e6816f', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵运用原则', '作战中使用装甲兵应遵循的基本准则。主要包括：通常用于机动作战,并主要用于进攻；集中使用于主要方向和重要时机；力求使用在便于坦克行动的地形上；周密组织与其他军兵种的协同动作；加强对空防御、电子对抗和后勤、技术、工程保障等。', 5);
INSERT INTO `t_military_term_data` VALUES ('2e3f416a-3bb3-4c95-924f-070ab6681930', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克小修', '坦克小修间隔期使用终了时进行的修理。由坦克旅、团或营修理分队承担。', 211);
INSERT INTO `t_military_term_data` VALUES ('2e416d31-dd22-46a0-9462-16aef45afa57', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役穿插', '战役中以一部兵力插入敌战役纵深的机动作战行动。', 113);
INSERT INTO `t_military_term_data` VALUES ('2e4d4f44-c55d-4890-9789-36f5a5a1c03b', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '行政看管', '军队中对犯有某些严重违纪行为或可能发生某种严重问题的人员实施的强制性、临时性的看守和管理。是一种维护秩序、制止严重违纪行为和预防事故的行政措施。必须严格按照有关规定和一定批准权限执行。', 62);
INSERT INTO `t_military_term_data` VALUES ('2e4de8a0-f6f6-401d-b8b0-23d71f4e2071', 'f0140091-c11a-48c9-8836-8aa94439dac0', '进攻出发阵地', '完成进攻最后准备和发起进攻所占领的阵地。兵团或部队的进攻出发阵地包括各梯队、预备队的配置地域,炮兵、防空兵以及其他火器的射击阵地和各种保障部队或分队的配置地域等。通常选择在靠近敌人,便于隐蔽疏散配置兵力、兵器和突然发起进攻的有利地形上。', 174);
INSERT INTO `t_military_term_data` VALUES ('2e563d3c-f399-4718-9a24-1896556c99fb', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '分练', '不同军兵种的部队、分队或不同岗位的人员分别进行的训练。', 169);
INSERT INTO `t_military_term_data` VALUES ('2e5a8593-560b-4d9b-8291-64468b0039c9', '916997ee-6728-4c61-9b79-d96960b1dc86', '核破坏等级', '依核爆炸对物体造成的破坏程度划分的级别。按破坏的程度、对作战使用的影响和修复的难易,通常分为轻微破坏、中等破坏和严重破坏。轻微破坏,一般不影响装备使用；中等以上破坏,武器装备和工程设施基本不能使用。', 113);
INSERT INTO `t_military_term_data` VALUES ('2e5d2b36-e112-422c-8959-3d4b53e6162b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '高斯柨寺栏裢队?/A>', '简称高斯投影,亦称等角横切圆柱投影。德国数学家高斯首创,经克吕格研究改进而成的一种投影方法。中华人民共和国大于1:50万比例尺的基本比例尺地形图,统一采用这种投影。', 271);
INSERT INTO `t_military_term_data` VALUES ('2e5ee4d7-5db4-4672-9941-b98afc176e13', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '干扰弹', '装填有各种干扰器材的弹药的统称。主要有箔条干扰弹、红外诱饵弹、箔条与红外混合干扰弹、通信干扰弹、烟幕弹、气幕弹等。可使用专用发射装置、火箭发射架、火炮等发射,或由飞机投掷。', 136);
INSERT INTO `t_military_term_data` VALUES ('2e775662-16d2-4b55-b155-227b339db2b9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事管制', '在战争或其他非常情况下,军队对指定的地区、行业系统或单位所实施的强制性管理和控制。', 73);
INSERT INTO `t_military_term_data` VALUES ('2e78750f-73d1-4a2f-adf5-dafd18815355', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事合作', '国家、政治集团或军队之间在军事上共同进行某项事情或完成某项任务。包括作战、训练、军事技术等方面的合作。', 75);
INSERT INTO `t_military_term_data` VALUES ('2e887075-aeac-4581-9974-311aa856302c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达迷盲', '雷达因遭受干扰而处于完全丧失探测和跟踪目标能力的状态。', 106);
INSERT INTO `t_military_term_data` VALUES ('2ea10ab7-fe75-4861-8804-e722b650f9ae', 'f0140091-c11a-48c9-8836-8aa94439dac0', '强击支队', '遂行强攻任务的战斗编组。用以攻击敌坚固支撑点等。兵力通常为1个加强营,由2～3个强击群和火力队、爆破队等编成。', 169);
INSERT INTO `t_military_term_data` VALUES ('2eaa6a0c-9791-4add-b683-1785c70d7756', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电通信反干扰', '为降低或消除敌方通信干扰对己方无线电通信的影响而采取的战术技术措施。', 101);
INSERT INTO `t_military_term_data` VALUES ('2eba4919-db1d-4df2-bf4b-bd1f2c485c2a', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器维修性', '轻武器便于维修和日常维护的程度。通常要求结构简单分解结合不用工具,分解后错装不能结合零部件能互换使用磨损后能调整或修复；维修技术容易掌握故障易于排除；表面污垢易于清除,日常擦拭方便等。', 227);
INSERT INTO `t_military_term_data` VALUES ('2ebaeec2-e75a-4b74-9ba7-d64cec0b8faa', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '警戒声纳', '亦称搜索声纳。主要用于警戒和监视的声纳。作用距离较远,观察范围较大,能长期连续工作,但定位精度较低。', 233);
INSERT INTO `t_military_term_data` VALUES ('2ec1b9bf-f6b9-49c0-8912-8e32b840c1ef', '916997ee-6728-4c61-9b79-d96960b1dc86', '空气再生装置', '亦称氧气再生装置。利用化学药剂吸收二氧化碳、放出氧气供人员正常呼吸的装置。通常使用于密闭的工事、车辆、舰艇舱室等环境中。', 182);
INSERT INTO `t_military_term_data` VALUES ('2edf7857-87d7-4824-bd75-9f281aefb719', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '火障碍物', '简称火障。由燃烧器材或纵火造成的非爆炸性障碍物。通常以燃烧地雷、燃烧瓶、燃烧液滴、燃油以及柴草等燃烧器材构成,也可纵火燃烧森林、草原造成。', 111);
INSERT INTO `t_military_term_data` VALUES ('2eee409b-c858-4cdf-9e17-04938dfaeb73', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '最低气象条件', '为保证某项军事活动安全进行所现定的最低限度气象条件。', 82);
INSERT INTO `t_military_term_data` VALUES ('2ef8ef8f-729f-4df3-9aba-aad6cb887657', '97a19170-bfac-42c5-9906-1acb187f0654', '螺旋', '亦称尾旋。飞机失速后出现的自动沿一条半径很小的螺旋线急剧旋转下降的失控运动状态。', 246);
INSERT INTO `t_military_term_data` VALUES ('2f0f0f8e-0709-4b34-9baf-bcd1b3d6cfa5', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '撤离', '军队撤出、离开战场或所占领的地区的行动。', 353);
INSERT INTO `t_military_term_data` VALUES ('2f212b43-1322-47b3-9e83-4f2f2df2fd8c', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练手段', '组织实施训练所采用的具体方法和措施。', 166);
INSERT INTO `t_military_term_data` VALUES ('2f275f2b-ecc3-4442-84c0-a96f93faa210', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '调整部署', '对原部署作部分改变的行动。通常在作战过程中仟务或情况发生变化时进行。', 102);
INSERT INTO `t_military_term_data` VALUES ('2f30a642-0514-47a5-9042-c0bed380ab7c', 'f0140091-c11a-48c9-8836-8aa94439dac0', '通过通路', '通过在障碍地带开辟的通路的行动。', 189);
INSERT INTO `t_military_term_data` VALUES ('2f3ba457-7d3b-44b1-afa3-c03dbc5ad816', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '航空图', '简称航图。在普通地图上加绘航空资料而编制成的地图。包括领航图、航路图和机场区域图等。着重表示与航空有关的地理要素和航空要素（飞机场、导航台、垂直障碍物、磁差线、磁力异常区、空中特区等）。供航空兵计划航线,确定航空器的位置和飞行距离、方向、高度以及寻找地面目标时使用。', 263);
INSERT INTO `t_military_term_data` VALUES ('2f3f01dc-54f0-4284-b6be-ff23adc046b7', '878651de-adf5-4c72-9376-9c363b893ff8', '战略伪装', '为隐蔽战略企图和行动而采取的欺骗、迷惑敌人的措施。如外交上的欺骗手段、军事上的欺骗行动等。', 102);
INSERT INTO `t_military_term_data` VALUES ('2f47def5-c92e-40a5-9a48-52516fc9c5ef', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵大间隔射击', '观炮夹角大于或等于400密位时的射击。', 196);
INSERT INTO `t_military_term_data` VALUES ('2f583a65-7397-45da-a07c-eeb6454215ae', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '修定决心', '对已定下的决心进行调整或改正。通常在发现决心不符合客观实际或客观情况发生重大变化时进行', 79);
INSERT INTO `t_military_term_data` VALUES ('2f617653-fe06-4f89-8443-7610ac17132b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵照相侦察', '炮兵利用照相器材摄取目标景象、地形及有关射击资料的侦察。包括空中照相侦察和地面（水面）照相侦察、可在较短时间内摄取准确可靠的目标资料,保证炮兵射击的需要。', 116);
INSERT INTO `t_military_term_data` VALUES ('2f7317e7-3936-4ac4-a478-cd9c799ae276', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练物资', '供军事训练使用的各种物质资料的统称。通常包括油料、弹药和钢材、木材、水泥等。', 180);
INSERT INTO `t_military_term_data` VALUES ('2f76163d-6651-4a5a-91bf-53d38a65198a', '98df76fb-4b65-48ff-a56c-4db587327c79', '军用仓库', '储存军用物资的设施及其管理机构的统称、分为基地仓库、野战仓库,综合仓库、专业仓库等。', 134);
INSERT INTO `t_military_term_data` VALUES ('2f77ab7c-e7fa-4eb8-91b3-cfb4e11ebc0c', 'd7132c58-5df3-4b97-919f-58740148b9ca', '广泛游击', '高炮分队在一定地域内广泛机动,出其不意地歼灭敌机的战术手段。通常在防空兵力较少、掩护目标较多的情况下采用。', 75);
INSERT INTO `t_military_term_data` VALUES ('2f90a32f-067e-4b37-9cad-6a116d58db6e', 'f0140091-c11a-48c9-8836-8aa94439dac0', '抗击', '抵抗敌人攻击的战斗行动。', 246);
INSERT INTO `t_military_term_data` VALUES ('2f94b03c-7936-4ccb-9060-6afa2598197a', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物战剂标本采集', '发现敌使用生物武器后,为查明其使用的生物战剂种类而对受染物进行的标本采集。采集的对象包括；受袭区的空气、水、粮食、药品,异常昆虫、动物或其尸体,植物叶片上可疑的粉末或液滴,武器装备交通运输工具受染表面,以及其他可疑物品等。', 69);
INSERT INTO `t_military_term_data` VALUES ('2f967704-0414-4d42-a645-1c0bc16904e9', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化单兵火箭', '防化兵用以发射燃烧弹、发烟弹的单兵火箭。燃烧弹用于摧毁敌火力点,发烟弹用于迷盲和干扰敌方的观察和射击。', 237);
INSERT INTO `t_military_term_data` VALUES ('2f999ab1-8cbd-4f91-903b-96b9f74b84ec', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '臂长尺', '以臂长的百分数为单位而刻制的尺。通常将手臂前伸,以自己的眼睛至拇指距离的百分之一为1个分划,刻在铅笔或直长物件上,并注以数宇。常用以测定距离和高度。', 154);
INSERT INTO `t_military_term_data` VALUES ('2fb65356-74e3-4686-83e7-05132a0f9019', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备', '①武器装备的简称。②向部队或分队配发武器及其他制式军用物件的话动。如以武装直升机装备陆军集团军。', 96);
INSERT INTO `t_military_term_data` VALUES ('2fb87cf4-532a-466d-a3b1-960b9fee0c41', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '佯攻', '为隐蔽企图和欺骗、迷惑敌人而采取的攻击行动。', 255);
INSERT INTO `t_military_term_data` VALUES ('2fd17970-db64-4509-a3c9-06832c97757d', '97a19170-bfac-42c5-9906-1acb187f0654', '机场助航灯光设备', '场中为保障飞机或直升机在夜间或昼间低能见度条件下起飞、着陆、滑行而设置的灯光信号设备。通常包括跑道灯、跑道端灯、滑行道灯、场界灯、下滑灯、“T”字灯、风向指示灯、机场位置标志灯等。', 432);
INSERT INTO `t_military_term_data` VALUES ('2fe3df95-3c00-4c01-8873-efeb4ac54c6f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '瞬发引信', '瞬发触发引信的简称。在撞击目标的瞬间引爆弹丸的引信。分机械瞬发引信、电瞬发引信和惯性瞬发引信。其作用时间为几十微秒到几毫秒。主要配用于杀伤弹、杀伤爆破弹和破甲弹。', 332);
INSERT INTO `t_military_term_data` VALUES ('2fe59d7a-1b87-42dc-abd7-20da8813eb62', 'd7132c58-5df3-4b97-919f-58740148b9ca', '战术防空', '兵团、部队、分队制止敌航空侦察，抗击敌空袭的战斗行动。', 68);
INSERT INTO `t_military_term_data` VALUES ('2ff08c15-36bb-4611-b9fe-27c31a6f87c4', '06a75831-13a1-4660-870a-455bb445336a', '海空协同通信', '为保障海军舰艇部队与海军航空兵、空军航空兵的协同作战而建立的通信联络。主要方法有：组织协同无线电网；通过航空兵向舰艇部队派出的作战小组、目标引导小组的电台建立无线电通信；舰艇部队的电台加入航空兵对空指挥网；使用简易信号通信器材等。', 13);
INSERT INTO `t_military_term_data` VALUES ('3007bc2b-f835-4ede-8871-3fd0f34f7f96', '97a19170-bfac-42c5-9906-1acb187f0654', '迷航', '飞行人员在飞行中处于不能判明自身航空器的所在位置和无法确定正确航向的状态。', 370);
INSERT INTO `t_military_term_data` VALUES ('300d968f-d345-4bb6-9c1f-e6dc649fd126', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '批复', '答复下级请示事项的军用文书。', 141);
INSERT INTO `t_military_term_data` VALUES ('300ff460-3220-4f98-927b-829ea4a8e866', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '首长决心图', '标绘指挥员作战决心的图。通常作为作战命令或作战报告的附图，其内容和形式,依作战类型及需要而定，以能准确反映首长决心和作战部署为原则。', 146);
INSERT INTO `t_military_term_data` VALUES ('30218256-250b-40ac-b8f5-05b036f24b5f', 'f0140091-c11a-48c9-8836-8aa94439dac0', '反坦克单位', '反坦克武器数量的计算单位。通常以某种单件反坦克武器作为基准单位,其他反坦克武器以其效能与之对比进行指数换算。有时也可不分反坦克武器的种类,均以件数为计算单位。', 42);
INSERT INTO `t_military_term_data` VALUES ('3036cb10-75a2-4b3a-a049-c90e01d6dc81', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射训练', '以导弹发射技术和战术为主要内容并按发射程序进行的训练。分为模拟发射训练和实弹发射训练。', 77);
INSERT INTO `t_military_term_data` VALUES ('304bf5c0-955f-4671-bd53-70a78214d12a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '卫星', '环绕行星运行的天体。其本身不发可见光,反射恒星光而发亮。分为天然卫星和人造卫星。月球是地球的天然卫星。', 188);
INSERT INTO `t_military_term_data` VALUES ('304f71a8-19a8-468b-80da-6e16da050914', '97a19170-bfac-42c5-9906-1acb187f0654', '空军战术', '空军部队、分队进行战斗的方法。分为空军合同战术和空军兵种战术。主要包括战斗基本原则以及兵力部署、战斗指挥、协同动作、战斗行动方法和战斗保障措施等。', 35);
INSERT INTO `t_military_term_data` VALUES ('30543812-95a7-402f-836d-42bc16ca03c0', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '加强', '以兵力兵器增强执行任务的单位的战斗力。其方式有支援和配属等。', 321);
INSERT INTO `t_military_term_data` VALUES ('30559048-1d3d-4278-ab1a-031b4a41ee83', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '激光制导', '利用激光技术获得导引信息,并按选定的导引规律进行的制导。分为激光波束制导和激光寻的制导。', 50);
INSERT INTO `t_military_term_data` VALUES ('3065c325-573d-4d6f-897c-5bf62a81f89f', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '士兵训练', '对军士和兵进行的训练。通常采取专设机构培训或部队自训等形式组织实施。', 54);
INSERT INTO `t_military_term_data` VALUES ('306cb8b8-036f-47f8-b4d2-d11afce90548', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克架桥车', '亦称架桥坦克。装有制式车辙桥及其架设、撤收装置的装甲保障车辆。多为履带式。通常用以快速架设车辙桥,保障坦克和其他车辆通过防坦克壕、沟渠等障碍。', 101);
INSERT INTO `t_military_term_data` VALUES ('30841da4-fe33-4fcd-9283-ce8f04e7c7ef', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战兵力区分', '简称兵力区分。根据作战任务,对所属兵力进行的分配和部署,以及明确其相互间的从属支援关系。', 85);
INSERT INTO `t_military_term_data` VALUES ('3085c969-2722-41b3-a1fe-e4614cfcb416', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克修理工程车', '装有修理设备、仪器和工具的技术保障车辆。通常由轮式越野车辆改装。用于野战条件下对损伤和有故障的坦克及其他装甲车辆进行检测、修理等。', 104);
INSERT INTO `t_military_term_data` VALUES ('308cea8e-f0ca-41a4-b617-45bdcccc9886', '98df76fb-4b65-48ff-a56c-4db587327c79', '代供', '后勤机构对本级部队建制外的单位或人员临时代理实施的经费、物资供应。分为全部代供和部分代供。', 93);
INSERT INTO `t_military_term_data` VALUES ('30a9fe83-2bed-46e2-97b3-60de48038e9c', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军区', '亦称大军区。在本国领土按战略区域设立的军队一级组织。中国人民解放军的军区,由中央军事委员会直接领导。设有领导机关,下辖一定数量的战斗部队和勤务保障部队、省军区、院校,有的还辖卫戍区或警备区等。统一领导辖区内的军事工作,包括民兵、兵役、动员工作和战场建设等。', 13);
INSERT INTO `t_military_term_data` VALUES ('30af2e05-f7f9-427e-96fd-75a684aa3d0a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '严寒地区', '最冷月平均气温低于-15摄氏度的地区。包括终年严寒地区和季节性严寒地区。季节性严寒地区冬季风雪多,能见度低,冻土层厚,有的地方积雪深,江河湖泊冻结期长,夏季冰雪冻土消融时地面泥泞,对军队行动有很大影响。', 118);
INSERT INTO `t_military_term_data` VALUES ('30b8e0ca-783f-4e79-8cb6-c6b9d622f725', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '海防建设', '为提高沿海地区和海疆的防卫与管理能力而进行的军事及相关的政治、经济、科技、文化的方面的建设。', 106);
INSERT INTO `t_military_term_data` VALUES ('30bf9065-c285-4c83-9a09-9bd6f29e0678', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '进攻战役', '以主动进击敌人为主的战役。是战役的基本类型之一。根据不同情况可具体分为不同样式的进攻战役。', 54);
INSERT INTO `t_military_term_data` VALUES ('30c5871c-374c-4d17-b5a8-13676c622578', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆驾驶等级', '对装甲兵指挥员和装甲车辆乘员掌握的驾驶理论和技能程度划分的等级。分为驾驶技师、一级驾驶员和二级驾驶员3个等级。', 79);
INSERT INTO `t_military_term_data` VALUES ('30d48330-2849-40c0-98b3-69c786105ea6', '97a19170-bfac-42c5-9906-1acb187f0654', '载机', '用以携带飞机或运载特种武器和特定装置的飞机。如运载航天飞机、无人驾驶飞机、核武器和巡航导弹的飞机。', 294);
INSERT INTO `t_military_term_data` VALUES ('30d9a3d6-6848-4b4a-ac29-8537079f3664', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机跃升攻击', '直升机飞行中使用机载武器以突然增加飞行高度的方式对敌方目标进行的攻击。对空中目标，通常先以低于目标的高度跟踪迫击,时机适宜时突然跃升实施攻击；对地面目标，通常待敌接近时,突然从隐蔽物后面跃升实施攻击。', 81);
INSERT INTO `t_military_term_data` VALUES ('30e90757-b705-49b2-8a62-2f87d5b3019a', 'f0140091-c11a-48c9-8836-8aa94439dac0', '屈身前进', '单兵俯身大步或快步前进的动作。通常在受敌火力威胁的情况下采用。', 113);
INSERT INTO `t_military_term_data` VALUES ('30f08981-ecbe-411e-9840-8a6deae2e30a', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵战术', '航空兵进行战斗的方法。包括航空兵合同战术和航空兵单一机种战术。主要内容有战斗基本原则、兵力部署、战斗指挥、协同动作、战斗活动方法与各种保障措施等。', 38);
INSERT INTO `t_military_term_data` VALUES ('30f2c0a2-663f-4592-8912-7cb3588dba38', '8a761efd-50a6-4ac8-9913-b7d745104f82', '自动步枪', '能实现首发后的自动再次装填,并能连发射击的步枪。口径通常小于8毫米,枪长1米左右，枪重4千克左右,容弹量10～30发,初速700～1000米／秒,有效射程400米左右,战斗射速90～100发/分。', 163);
INSERT INTO `t_military_term_data` VALUES ('30ff824e-8be3-436f-bb71-d1b0df559330', '878651de-adf5-4c72-9376-9c363b893ff8', '战略要点', '对战略行动具有重大意义的地点。如战争中双方必争的重要城镇、港口、机场、要冲等。', 90);
INSERT INTO `t_military_term_data` VALUES ('31123e3d-c79c-40aa-b475-c132e15744cc', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战部署', '据作战需要而确定的任务区分兵力编组和配置接作战规模和范围分为战略部署战役部署和战斗部署；按作战类型,分为进攻作战部署和防御作战部署等。', 95);
INSERT INTO `t_military_term_data` VALUES ('311257d2-e49c-45ec-bf34-1cd5533ea5f7', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战术想定作业', '依据设想的战术情况研练战斗组织指挥的作业。是想定作业之一。', 99);
INSERT INTO `t_military_term_data` VALUES ('31145e36-627d-4595-b538-f9f7b9668afb', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '立功创模', '中国人民解放军在全体军人中开展的以为祖国为人民建立功勋、争创模范、争取荣誉为内容的群众性革命竞赛活动。', 56);
INSERT INTO `t_military_term_data` VALUES ('31268be7-5102-46be-a80b-d2aabe99e10f', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '大气气溶胶', '固态、液态微粒在大气中的悬浮体系。是大气的重要组成部分,对天气和气候有重要影响由作战行动造成的大气气溶胶,如化学毒剂和生物战剂云团、核爆炸烟云和放射性尘埃等,其微粒影响微波通信、电子光学武器的使用,对人员具有杀伤力。', 10);
INSERT INTO `t_military_term_data` VALUES ('31592cc7-80a3-48e8-9e9d-2febbb701667', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '部队代号', '为密化部队番号而授予建制单位的代称。通常以数字或字母加语词组成,如 58324部队、 97621部队14分队。主要用于单位或个人的对外联系。对外公开的军事机关、院校、科研机构、医院、工厂、仓库等,一般不授予代号。', 143);
INSERT INTO `t_military_term_data` VALUES ('3163359a-c88e-4883-83c7-83e5c218e20c', '97a19170-bfac-42c5-9906-1acb187f0654', '战役空降', '由战役军团组织的为达成一定战役目的而在敌战役纵深和后方实施的空降。主要任务是：夺取并扼守敌方战役纵深内的重要目标和地区,配合正面部队加速战役进程等。', 151);
INSERT INTO `t_military_term_data` VALUES ('3166b31b-8bad-426c-8f12-35c5b07271a1', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '专业部（分）队', '各兵种和专业兵所属的担负某种专门任务的部队或分队。如工程兵的舟桥部队或分队,电子对抗兵的电子对抗部队或分队等。', 57);
INSERT INTO `t_military_term_data` VALUES ('3168302d-65c1-4bdd-9ea4-70223c5964ae', '98df76fb-4b65-48ff-a56c-4db587327c79', '伤部', '伤员负伤的部位、通常按照解剖、生理关系划分。中回人民解放军现行划分方法,将全身分为颅脑、面颈、胸背、腰腹、骨盆、脊柱、上肢、下肢等8个部位。', 189);
INSERT INTO `t_military_term_data` VALUES ('316abab3-1f21-455e-8a62-f243c174a89b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮弹', '供火炮发射的弹药。由弹丸和发射装药两部分组成。按用途，分为主用弹、特种弹和辅助弹；按装填方式,分为定装式炮弹和分装式炮弹；按弹丸装填物,分为常规炮弹,原子炮弹、化学炮弹、生物炮弹等。', 303);
INSERT INTO `t_military_term_data` VALUES ('316f43c8-8c78-444b-b804-579ffa162d5d', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通保障计划', '为保障战时交通而制定的计划。主要内容包括：交通网路的建设和使用,重点线路和目标的确定及其保障等级和保障任务的区分,物资器材的筹措与储备,运输工具的动员和征用,交通保障的组织指挥等。', 281);
INSERT INTO `t_military_term_data` VALUES ('316fbdc4-447c-476f-9f17-9e05a63529ec', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '紧急疏散', '在发现敌明显突袭征候或敌突袭时,迅速进行的疏散。', 223);
INSERT INTO `t_military_term_data` VALUES ('318932ff-ffb9-4eb1-a51f-dd8355b106ce', '8a761efd-50a6-4ac8-9913-b7d745104f82', '榴弹发射器', '抛射小型榴弹的发射装置。口经一般为20－60毫米,外形、结构和使用方式大多与步枪或机枪相似，也有的象迫击炮。用于填补手榴弹与迫击炮之间的火力空白,杀伤2500米内暴露的或遮蔽物后面的生动目标。也可对付薄壁装甲目标。重量轻,体积小，适合单兵或小组携行使用。', 182);
INSERT INTO `t_military_term_data` VALUES ('31961a9d-004b-47d1-b2c2-e07356c69bef', '97a19170-bfac-42c5-9906-1acb187f0654', '地勤特种服装', '航空工程机务人员维修飞机或直升机时着用的制式工作服装。包括皮制或棉制的工作服、帽、手套、皮靴等。', 405);
INSERT INTO `t_military_term_data` VALUES ('319d8aea-6e57-49db-9efe-8fed52ba2e6f', '06a75831-13a1-4660-870a-455bb445336a', '通报速率', '单位时间传送电报信号的码元数。计量单位为波特、每分钟字符数或字数。手键报的通报速率为每分钟100字左右。电传报的通报速率为50、75、100波特,甚至200波特以上。', 138);
INSERT INTO `t_military_term_data` VALUES ('31acc940-e91f-422d-bcdf-2a496015ffb1', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '航天技术', '亦称空间技术。探索、开发和利用太空以及地球以外天体的技术。主要包括航天器和航天运输系统的研制、试验、发射、运行、返回、控制、生命保障及应用技术等。在军事上的应用十分广泛,对军事战略和武器的发展有着深远的影响。', 7);
INSERT INTO `t_military_term_data` VALUES ('31b438fd-c18b-46e5-b3af-03f8b0f4d343', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '火箭推进剂', '简称推进剂。为化学火箭发动机提供能源和工质的物质。包括燃烧剂和氧化剂等。分为固体推进剂、液体推进剂、固液组合使用的混合推进剂。', 40);
INSERT INTO `t_military_term_data` VALUES ('31b45dc3-fb6e-443e-8d45-b167d2f15324', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地图复制', '将地图出版原图复制成多份地图的生产技术。可利用平版照相印刷工艺复制或复印机复制。', 289);
INSERT INTO `t_military_term_data` VALUES ('31b562db-a033-45c2-a4e3-7ae3ca411922', '97a19170-bfac-42c5-9906-1acb187f0654', '航空技术装备', '简称航空装备。航空器及其各种装备、设备、附件的统称。主要包括飞机、直升机、航空发动机、航空军械、航空电子设备、航空仪表、航空电器设备和航空救生设备等。', 258);
INSERT INTO `t_military_term_data` VALUES ('31bfca33-7c85-4f72-aac9-234517cd1258', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '整置', '亦称架设。炮兵将器材由行军状态转换为战斗状态的过程。', 271);
INSERT INTO `t_military_term_data` VALUES ('31c1e30e-b0c8-4ee6-84cd-2692c987f8a9', '06a75831-13a1-4660-870a-455bb445336a', '野战通信部（分）队', '在野战条件下担负通信联络任务的专业部队和分队。集团军以上各级均编有团一级野战通信部队。师、旅、团编有野战通信分队。', 1);
INSERT INTO `t_military_term_data` VALUES ('31c90e10-db63-4840-85a6-fd48cc90605e', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '河宽', '亦称河幅。江河两岸间的宽度。', 69);
INSERT INTO `t_military_term_data` VALUES ('31c94efe-f6fc-47a6-a6b2-e2a6ccbec6bc', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反潜巡逻机', '师主要用于海上巡逻和反潜作战的海军飞机。分为岸基反潜巡逻机和水上反潜巡逻机。通常装备有水声器材和自导鱼雷、水雷和深水炸弹等反潜武器。', 182);
INSERT INTO `t_military_term_data` VALUES ('31e9e59e-9ce7-4849-bece-f7d6f186b008', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹射击诸元', '与导弹发射、飞行有关的瞄准、加注乃各项装定的数据的统称。包括瞄准方位角、射程装定量、推进剂加注量等。是决定导弹射程和射击精度的基本数据。', 183);
INSERT INTO `t_military_term_data` VALUES ('31ec681c-03cc-454a-b431-ca5688c4572b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '待渡地区', '部队在渡场内等候前出渡河的区域。设在渡口附近便于疏散的隐蔽处,并构筑有人员和车辆掩体。', 315);
INSERT INTO `t_military_term_data` VALUES ('31ef5b17-4366-4f23-afbc-b979de09757e', '06a75831-13a1-4660-870a-455bb445336a', '通信枢纽', '汇接、调度通信线路（电路）和传递、交换信息的中心。由通信台、站和相应的管理机构组成。按保障任务,分为指挥所通信枢纽、干线通信枢纽（干线节点）和辅助通信枢纽；按设备安装与设置,分为固定通信枢纽和野战（移动）通信枢纽等。', 72);
INSERT INTO `t_military_term_data` VALUES ('31f4a446-5b98-4873-9d53-310d97125b07', '0', '第二炮兵', NULL, 16);
INSERT INTO `t_military_term_data` VALUES ('31f677f4-8e13-47c7-b29a-17dccdf1d977', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '混合地雷场', '用两种以上用途的地雷混合设置的地雷场。可提高地雷场的障碍能力,增加敌侦察和排除的困难。', 187);
INSERT INTO `t_military_term_data` VALUES ('31f77857-b7c8-4783-a731-0b18f0abca4d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇航向', '舰艇航行时舰首所指的方向。从基准北沿顺时针方向计量到舰首线在水平面投影的夹角。用度表示。按起算的基准北不同,分为真航向（以真北为基准计量）、磁航向（以磁北为基准计量）、罗航向（以罗经北为基准计量）、陀罗航向（以陀螺罗经北为基准计量）等。', 269);
INSERT INTO `t_military_term_data` VALUES ('31f9b86d-3106-4b48-bb7b-3224f3b6143e', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '双休日管理', '军队在双休日期间对人员的生活、休息及其他活动实施的管理。部队和分队双休日管理的重点是坚持各项制度,组织好各项活动和士兵的休息。控制人员外出。', 40);
INSERT INTO `t_military_term_data` VALUES ('3206532d-bd71-4206-a00e-6aedbc5776f0', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反包围', '被包围的部队打破敌之包围或以外线部队对包围之敌实施的包围。是战场上敌对双方犬牙交错形态的一种表现。', 415);
INSERT INTO `t_military_term_data` VALUES ('320c6ce8-8255-41a7-88f8-be9b5fe2944f', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵训练', '装甲兵为掌握遂行作战任务所需的军事知识和专业技能而进行的训练。主要包括专业技术训练、战术训练和共同科目训练。', 66);
INSERT INTO `t_military_term_data` VALUES ('321500f8-52e2-4889-a3fe-5b33714330b3', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵标准射击条件', '亦称表定射击条件。编制火炮射表和进行炮兵射击条件修正时所依据的标准弹道、气象、地形等条件的统称。射表规定了各项射击条件的标准值,炮兵射击时,实际值与标准值有偏差的要以标准值为准进行修正。', 136);
INSERT INTO `t_military_term_data` VALUES ('322094d8-f44b-4985-acdf-38ab795b5a68', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备制度', '军队为进行战争准备而颁发的各种制度和规定的统称。如情报报知、警报发放、战备等级、战备值班等制度或规定。', 105);
INSERT INTO `t_military_term_data` VALUES ('3224700c-be68-4c2b-905e-22275e1a286b', '97a19170-bfac-42c5-9906-1acb187f0654', '变后掠翼机', '飞行中机翼的后掠角可以改变的飞机。机翼后掠角的变化范围约为20度～70度。', 277);
INSERT INTO `t_military_term_data` VALUES ('32342e80-6596-4d19-894a-d924b93d031e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反舰导弹', '用以攻击水面舰船的导弹的统称。包括舰舰导弹、潜舰导弹、岸舰导弹和空舰导弹。', 186);
INSERT INTO `t_military_term_data` VALUES ('32369362-c368-415a-9c14-f8edf65f55c1', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '车（炮）场日', '部队或分队在车辆（火炮）停放场所,对汽车、坦克、火炮及其他军用车辆和机械进行维护保养的固定工作日。通常每周一次。', 105);
INSERT INTO `t_military_term_data` VALUES ('323861b1-511f-483b-b287-20cc5b52acd6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '民族', '人们在历史上由于长期共同相处所形成的,具有共同语言、共同地域、共同经济生活和表现在共同民族文化特点上的共同心理素质等特征的稳定共同体。有时也用作多民族国家内所有民族的统称。民族问题常常是影响国家安全与稳定和国家之间关系的重要因素。', 100);
INSERT INTO `t_military_term_data` VALUES ('323d692f-8ef9-4525-8890-cd36b82d488d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '山谷', '亦称山沟。相邻的山背或山脊之间的低凹部分。包括谷源、谷口、谷底、谷壁（谷坡）常成为通过山地的交通孔道。', 18);
INSERT INTO `t_military_term_data` VALUES ('323e7631-d4fb-4b42-a6ff-38dd6c3296fd', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '调整指挥所', '师以上部队行军时设立的专门担负调整勤务的指挥所。', 69);
INSERT INTO `t_military_term_data` VALUES ('32413d89-cf2f-49c1-baf6-cd8737481f25', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '运动战', '正规部队在长的战线和大的战区进行战役、战斗的外线速决的进攻的作战形式。其中包括起辅助作用的运动防御战和阵地攻防作战。', 139);
INSERT INTO `t_military_term_data` VALUES ('324e8845-b62a-493c-9493-a66a2233e4bc', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '入轨误差', '航天器入轨参数的实际值与设计值之差。入轨误差的大小,直接影响着航天器完成使命的好坏。', 260);
INSERT INTO `t_military_term_data` VALUES ('324fe948-7992-4d50-8c29-0d52561f74f3', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '越级指挥', '越过直属下级实施的指挥、通常在执行特殊任务或情况紧急时采用越级指挥者应及时将其命令、指示告知被越过的下级；受越级指挥的下级亦须及时向其直属上级报告受领任务的情况。', 25);
INSERT INTO `t_military_term_data` VALUES ('3250d716-c11e-4aea-a1e3-56c34c27c229', '8a761efd-50a6-4ac8-9913-b7d745104f82', '三无弹射器', '利用膨胀的火药燃气,通过活塞的瞬时冲量推动弹丸的发射装置发射过程中无焰无烟、微声,隐蔽性好但射程较近一般不超过400米。可使用杀伤弹燃烧弹、烟幕弹等弹种。主要用以压制遮掩物后面的集群生动目标。', 186);
INSERT INTO `t_military_term_data` VALUES ('325b7e2e-7365-46f3-8cf8-a20a94c8bb2b', '8a761efd-50a6-4ac8-9913-b7d745104f82', '瞄准', '为使射弹射向目标，在水平面和垂直面上赋予火身轴线以一定方向角和射角的动作。构成方向角的动作称方向瞄准,构成射角的动作称高低瞄准。利用瞄准装置直接瞄向目标，称直接瞄准；根据目标位置换算出方向角和射角,利用瞄准装置瞄向参照物，称间接瞄准。', 6);
INSERT INTO `t_military_term_data` VALUES ('326dbabb-5417-49b7-ba39-4829c320cd45', 'f0140091-c11a-48c9-8836-8aa94439dac0', '交替转移', '部队、分队在统一指挥下,按规定的次序轮番进行的转移。', 117);
INSERT INTO `t_military_term_data` VALUES ('326fdcb3-5774-4bef-a770-954a6e9e90b9', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '桥梁维护', '为保证军用桥梁正常使用而采取的技术检查、维修保养和各种防护措施的统称。', 289);
INSERT INTO `t_military_term_data` VALUES ('3274a7a7-6513-42b3-a466-664a55ba3ee1', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战效能分析', '定量分析应用武器系统遂行给定作战任务的有效程度的方法。主要是为武器系统的规划、设计、使用、管理的研究和决策提供理论指导与数据依据、包括单一武器系统的作战效能分析和多种武器系统合同作战的作战效能分析。', 190);
INSERT INTO `t_military_term_data` VALUES ('3277f554-3e12-4343-ae5e-168b195accb1', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵要点掩护', '防空兵对军队运动道路上的重要地点实施的对空掩护。通常预先展开,作好射击准备。', 78);
INSERT INTO `t_military_term_data` VALUES ('32865d07-e8d7-4adc-afbd-176d388b412e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克自救', '坦克成员利用本车牵引力和自救器材使坦克脱险的行动。', 221);
INSERT INTO `t_military_term_data` VALUES ('328835c1-551f-4a3b-9fbe-ab8f729da989', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '气翼艇', '亦称冲翼艇。现称地效翼艇。利用船体两侧机翼产生的气动升力。使之离开水向而作超低空高速航行的船艇。分为冲翼式气翼艇、槽流不气翼艇和动力增升式气翼艇。', 158);
INSERT INTO `t_military_term_data` VALUES ('328848f4-3f65-4a38-829c-14ef40b113a5', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹战场准备', '为使导弹部队能在预定阵地作战而进行的以战场建设为基本内容的准备。主要包括地形勘察、阵地建设、隐蔽伪装、武器装备与物资的储备、阵地管理、群众工作等。', 195);
INSERT INTO `t_military_term_data` VALUES ('329fb324-c788-4a3e-9b5f-d16e23d85131', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '新兵训练', '对刚入伍的兵进行的训练。主要内容包括政治、军事基础知识和战斗基本技能。', 51);
INSERT INTO `t_military_term_data` VALUES ('32b27397-6dd9-4cc6-84e2-edceb1357e2e', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队机关直属党委', '军队机关中党的直属委员会的简称。中国共产党在中国人民解放军团级以上单位的司令部、政治部（处）、后勤部（处）、装备技术部（处）等机关设立的统一领导其直属单位的委员会。旅级以上单位的机关直属党委在机关党委领导下,对直属单位实行统一领导,负责机关党的工作。团级单位的机关直属党委在同级部队党委领导下,对直属单位实行统一领导,负责机关党的工作。', 40);
INSERT INTO `t_military_term_data` VALUES ('32b6bdd7-8618-4390-a166-2b8c712a7cfe', 'd7132c58-5df3-4b97-919f-58740148b9ca', '自行高炮武器系统', '靠自身动力驱动行进的高射炮武器系统。通常包括高射炮、搜索或跟踪雷达、光电跟踪和测距装置、火控计算机等。均装于同一车体上。', 44);
INSERT INTO `t_military_term_data` VALUES ('32d663ec-2896-4156-806e-751a68f69056', '8a761efd-50a6-4ac8-9913-b7d745104f82', '校枪', '亦称射效校正。以标准（近似）条件下试射的射击准度，校正轻武器瞄准基线的过程。目的是使瞄准其处于准确状态。通常在新枪初次使用前、更换或修理过对射击精度有影响的零件、使用中发现射击精度异常等情况下进行。', 231);
INSERT INTO `t_military_term_data` VALUES ('32eb4635-6cb3-4646-9e9a-7738bb44fc8d', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役', '军团为达成战争的局部目的或全局性目的,在统一指挥下进行的由一系列战斗组成的作战行动。它介于战争与战斗之间。按作战基本类型,分为进攻战役和防御战役；按战役力量构成及其相互关系,分为合同战役和联合战役；按规模,分为集团军战役、方面军（集团军群）战役、战区战役等。还可按军兵种,分为陆军战役、海军战役、空军战役、第二炮兵战役等。', 1);
INSERT INTO `t_military_term_data` VALUES ('32f1e836-be00-4e11-a2ed-b8ac0c88df85', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役要点', '对战役作战有重大价值的地点。如具有重要战役价值的山地、城镇、港口、交通枢纽、海空军基地等。', 32);
INSERT INTO `t_military_term_data` VALUES ('32fb31c6-7d0d-42a7-987f-8071027d3d61', 'd7132c58-5df3-4b97-919f-58740148b9ca', '对空侦察雷达', '亦称目标指示雷达。防空兵部队用于掌握空情和指示目标的雷达。探测距离较远，具有良好的搜索和发现目标的能力。', 51);
INSERT INTO `t_military_term_data` VALUES ('330138d5-bc62-45f2-b464-158323be28e2', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵小间隔射击', '观炮夹角小于400密位时的射击。', 197);
INSERT INTO `t_military_term_data` VALUES ('3317cdd7-49ca-44e7-b5d3-c4c19d562b6c', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防教育', '国家为巩固和加强国防而对公民进行的普及性教育。主要包括国防思想、军事知识等方面的教育。目的是使公民增强国防观念,掌握国防知识和必要的军事技能,发扬爱国主义精神,自觉履行国防义务。', 54);
INSERT INTO `t_military_term_data` VALUES ('331a589c-a124-4e01-b1cf-4014ea2a1c5f', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '延期地雷', '亦称定时地雷或定时爆破装置。装有时间引信；可在预定时间发火的特种地雷。多设置在需要定时炸毁的目标内或其附近。', 151);
INSERT INTO `t_military_term_data` VALUES ('331f2be9-db47-4517-8b20-a4c2af84e131', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵训练', '炮兵为掌握遂行作战任务所需的军事知识和专业技能而进行的训练。主要包括炮兵专业技术训练、炮兵战术训练和共同科目训练。', 125);
INSERT INTO `t_military_term_data` VALUES ('333a5f9b-a699-4c0f-b6c9-519f206c3602', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸烟云', '亦称放射性烟云。大气层核爆炸火球熄灭后形成的放射性云团。爆后初期该云团迅速上升并向四周扩展,与随之从地面升起的尘柱形成蘑菇状烟云。', 172);
INSERT INTO `t_military_term_data` VALUES ('333bb5e4-16d3-40c0-ae7f-2b5d3507ef22', '06a75831-13a1-4660-870a-455bb445336a', '散射通信站', '进行散射通信的通信站。主要设备有发信机、收信机、天线、终端和电源等。', 82);
INSERT INTO `t_military_term_data` VALUES ('334813e3-891e-4bcd-8f49-e0374a5416b6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '滩头', '海（河）滩的最高处。常作为海岸和江河攻防作战的阵地,并称之为滩头阵地。', 48);
INSERT INTO `t_military_term_data` VALUES ('334b09d7-c9c5-447f-b908-398ee7644569', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '岩石海岸', '由岩石构成的海岸。多背靠陆地山丘,岸高且陡,岸线曲折,近岸水深,岛礁较多。登陆作战比较困难,但便于组织防御。', 42);
INSERT INTO `t_military_term_data` VALUES ('335906c2-1953-4dce-a079-dcbdecd91155', '97a19170-bfac-42c5-9906-1acb187f0654', '空中走廊', '飞行管制部门为使航空器有序进出某地区上空而划定的具有一定宽度的空中通道。目的是限制飞行范围,便于飞行管制,维护飞行秩序,保证飞行安全。空中走廊的宽度不得小于8公里。', 379);
INSERT INTO `t_military_term_data` VALUES ('335d0afd-a8c7-47ad-8ae1-dbebc51ff832', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵测地诸元', '由测地计算所得或从图上量取的未经修正射击条件影响的射击开始诸元。包括炮目距离、炮目方向和炮目高低角。只作为试射开始诸元。', 142);
INSERT INTO `t_military_term_data` VALUES ('337c24cc-5fa8-4821-a308-f82c5db6b680', '8a761efd-50a6-4ac8-9913-b7d745104f82', '燃烧枪弹', '弹头内装有燃烧剂的枪弹。弹丸命中目标后燃烧剂发火,可点燃各种易燃物。', 200);
INSERT INTO `t_military_term_data` VALUES ('3384a293-6ec8-4ef2-bb91-b0713555b1ce', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击效果侦察', '对核打击的准确程度及其对被打击目标的毁伤程度进行的侦察。', 170);
INSERT INTO `t_military_term_data` VALUES ('338dc714-9835-4249-ab57-37d6d050b7df', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '财务管理', '军队有关部门和各单位首长对各种经费的管理。主要包括对经费的领报、记帐、分发、审批、使用、结算等方面的管理工作。', 25);
INSERT INTO `t_military_term_data` VALUES ('33907453-9ce8-4f2a-ab8e-55a579c07433', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击结果自动评价系统', '用以检测高炮射击结果的自动化系统。由靶载的脱靶距离显示器和地面站组成。能在高炮射击时自动测定、评价和显示射击结果。', 136);
INSERT INTO `t_military_term_data` VALUES ('33ad82ae-bfbc-4b53-b2ac-4911d2a58a1b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '破甲弹', '以聚能效应产生的金属射流贯穿装甲的炮弹。主要用以摧毁敌坦克、步兵战车等装甲目标。', 309);
INSERT INTO `t_military_term_data` VALUES ('33aeb217-1123-4b23-8998-4ebdec5be2e9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '无后方作战', '在没有后方保障或无根据地作依托的条件下进行的作战。', 195);
INSERT INTO `t_military_term_data` VALUES ('33bc2edf-7b40-4be4-917b-d6aa2f5ed760', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队保卫工作', '中国人民解放军依法对内部危害国家安全和军事利益的敌对分子和其他刑事犯罪分子的犯罪行为所进行的防范与侦查工作。', 131);
INSERT INTO `t_military_term_data` VALUES ('33c35d55-69aa-43e8-9b32-b6e2e7e05bb9', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰载机升降机', '航空母舰上设在机库甲板与飞行甲板之间。用以升降舰载机的机械装置。分为船内式升降机和舷侧式升降机。', 170);
INSERT INTO `t_military_term_data` VALUES ('33e67023-1d61-4064-be18-4bd9d74f6825', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '试验性演习', '亦称研究性演习。以探讨和实验方式进行的军事演习、通常用以研究和论证新的作战方法和训练方法,试验新的条令、教令、作战预案,以及新的编制或新装备等。', 113);
INSERT INTO `t_military_term_data` VALUES ('33e8382d-bba5-41be-b5a9-d93474d5459d', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行机务准备', '为使飞机或直升机经常保持或及时恢复良好状态,并使之符合飞行任务要求而进行的技术准备。分为预先机务准备、直接机务准备和再次出动机务准备。主要包括；进行飞行前和飞行后的检查,加添燃料、滑油和充气、充液,按任务要求进行航空弹药的准备、补充和装挂,装卸执行任务所必须的附加设备等。', 442);
INSERT INTO `t_military_term_data` VALUES ('33ee7747-b892-4747-bc79-66c39129ceb5', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军船艇基地', '为陆军船艇的驻泊和机动提供各项保障的基地。是陆军船艇部队领导机关所在地。由陆军船艇部队管理使用。包括一定范围的水域、陆域和码头、港池、仓库,并配置有通信导航、船艇维修以及船员生活、训练等设施。', 337);
INSERT INTO `t_military_term_data` VALUES ('33f5b498-c28c-4389-a9e8-f43df8a19a94', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军电子防御保障', '海军为顺利遂行作战任务而在电子防御方面进行的保障。由海军各级司令部组织实施。', 364);
INSERT INTO `t_military_term_data` VALUES ('33f962de-dfb2-4fcd-ba4d-583069807f95', '31f4a446-5b98-4873-9d53-310d97125b07', '反导作战空域', '根据防御雷达性能划定的进行拦截来袭导弹的空间范围。取决于防御雷达空间扫描的范围及其作用的距离。', 34);
INSERT INTO `t_military_term_data` VALUES ('340987c1-9c20-47dc-bed8-0dd75f4b4181', '06a75831-13a1-4660-870a-455bb445336a', '无线电遥控', '利用无线电技术对远距离的军事装备进行的控制。按多路复用方式,分为时分遥控和频分遥控；按控制信号形式,分为模拟遥控和数字遥控。', 80);
INSERT INTO `t_military_term_data` VALUES ('341360d4-47ff-4edd-ab90-15302eb79f18', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海啸', '由海底地震或火山爆发、塌陷、滑坡等激起的海洋巨浪、海啸可使堤岸决口,舰船沉没,造成严重灾害。此外,水下核爆炸或风暴等气象原因也能引起海啸。', 132);
INSERT INTO `t_military_term_data` VALUES ('3414eb9f-485d-4fd1-b2d8-ed55ef2cdf62', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '地带', '作战中对两端都作明确标示的陆上呈长条形的带状区域。通常每端各用两个点表述,如XX、XX、XX、XX地带,即指上述四点之间的地带。', 299);
INSERT INTO `t_military_term_data` VALUES ('34160cac-ce27-43b4-97b7-3d0ea3e59c42', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '军民联防', '中国人民解放军、中国人民武装警察部队在民兵、地方有关部门和人民群众配合下,联合执行边防、海防勤务的活动。', 104);
INSERT INTO `t_military_term_data` VALUES ('343404c0-64ec-49f4-abfe-17fe582a2df8', '97a19170-bfac-42c5-9906-1acb187f0654', '领航', '使用有关设备测定航空器飞行时相对于地球表面的位置,确定应飞航向、速度和高度,引领航空器在预定时刻飞达指定地点或空域的活动。', 366);
INSERT INTO `t_military_term_data` VALUES ('343621e8-f857-4645-baef-8af76c304cdb', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '激光代炮射击训练', '将激光发射器固定在火炮身管上,以发射激光束代替发射炮弹的炮兵射击训练。在炮兵指挥员进行射击指挥练习和分队进行直接瞄准射击训练时采用。', 130);
INSERT INTO `t_military_term_data` VALUES ('3436ce3b-66f1-45db-be23-f233c4f4c876', '878651de-adf5-4c72-9376-9c363b893ff8', '核战争', '使用核武器进行的战争。相对于常规战争而言。分为全面核战争和有限核战争。', 12);
INSERT INTO `t_military_term_data` VALUES ('344d94bf-bf01-40c2-acbd-6ef6fc1b6e7f', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军船艇完好率', '①一定时期内完好船日与实有船日的比值。②某一时间完好船数与实有船数的比值。均用百分比表示。用以表明陆军船艇技术状况完好的程度。', 335);
INSERT INTO `t_military_term_data` VALUES ('344df2a9-e647-48f8-ae53-3bac7a46cf26', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '大陆性气候', '中纬度大陆腹地受大陆影响显著的气候。主要特征是：冬季与夏季、昼间与夜间温差大,春季气温高于秋季,云、雾和降水少,空气湿度小,降水主要集中在夏季。', 56);
INSERT INTO `t_military_term_data` VALUES ('345ca5bd-7778-44fd-a69e-f08f1861e9c7', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇战位救护', '在舰艇战位上对伤员进行的应急救治。通常以自救和互救为主。包括止血、包扎、骨折固定、伤员搬运、溺水急救及止痛等。', 353);
INSERT INTO `t_military_term_data` VALUES ('3462ce2e-18b9-45a7-aecd-dc926b348444', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '先进连队', '中国人民解放军在全军开展的争创先进连队活动中,达到基层建设标准、成绩优异的连队。', 54);
INSERT INTO `t_military_term_data` VALUES ('3462d78f-4cf1-4dbb-aca1-01985f1aab06', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵分段射击', '将各炮兵营或连的火力，分别指向同一目标中不同地段的射击。各营或连根据自己分担的射击地段或阻击线的中心点决定诸元并根据射击地段的幅员或阻击线的宽度分配火力。', 184);
INSERT INTO `t_military_term_data` VALUES ('346574b6-033b-40e0-98c9-8327d83a2897', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战役想定作业', '依据设想的战役情况研练战役组织指挥的作业。是想定作业之一。', 100);
INSERT INTO `t_military_term_data` VALUES ('34715f3f-e6f7-4569-ad9e-e0441cb255c0', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '速潜', '亦称紧急下潜。潜艇以最短时间不经过半潜状态直接下潜到预定深度的行动。分为水上速潜和水下速潜。通常在发现敌情或遭受险情的紧急情况下采用。', 296);
INSERT INTO `t_military_term_data` VALUES ('3476c95c-02fa-4468-9db0-c4fa6965ffc1', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战场勤务', '为保障作战而在战场组织的各种勤务的统称。主要包括战斗、后勤、技术方面的勤务以及战场管理等。', 60);
INSERT INTO `t_military_term_data` VALUES ('347ddfe2-5328-49d1-838d-2ed7a72fc777', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报收集', '对情报资料进行汇集的工作。通常根据上级意图、作战需要和对情况掌握的程度,确定情报资料收集的内容、范围。', 135);
INSERT INTO `t_military_term_data` VALUES ('34842afc-2f4b-4ffe-af86-99a6b3987c8d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '假地雷场', '模拟真地雷场的场地。可用作障碍物配系的组成部分,以弥补己方布雷时间、兵力、器材的不足,增加敌克服地雷场的困难。为增强欺骗性,可在假地雷场中布设少量真地雷。', 188);
INSERT INTO `t_military_term_data` VALUES ('3490ac2a-a2a1-43c7-b108-a9f35f044148', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '钢管混凝土工事', '用灌注混凝土的钢管材料作支撑结构的工事。分为密接配置钢管混凝土工事和相间配置钢管混凝土工事。抗压强度和抗变形能力均高于型钢和钢筋混凝土构件工事。', 75);
INSERT INTO `t_military_term_data` VALUES ('3495db7e-3c3c-4ae1-bdfc-5256e077b69b', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '隐形技术', '亦称隐身技术。减弱目标辐射和反射的特征信息,使之难以被探测系统发现的技术。包括反雷达探测、反红外探测、反电子探测、反可见光探测和反声波探测等技术。', 28);
INSERT INTO `t_military_term_data` VALUES ('3496c146-bd3f-436a-bfb0-76d9d0c2a159', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克底盘', '用以承载坦克炮塔、武器系统和其他有关设备的自行平台。包括坦克车体、坦克推进系统和有关电气设备等。', 109);
INSERT INTO `t_military_term_data` VALUES ('34a5d822-f2e8-46d1-ad1e-6834aad7a984', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防建设', '国家为提高国防能力而进行的各方面的建设。主要包括：武装力量建设,边防、海防、空防。人防及战场建设,国防科技与国防工业建设,国防法规与动员体制建设,国防教育,以及与国防相关的交通运输、邮电、能源、水利、气象、航天等方面的建设等。', 4);
INSERT INTO `t_military_term_data` VALUES ('34be9531-47ae-42dc-b5b9-62a858eb415b', 'f0140091-c11a-48c9-8836-8aa94439dac0', '进入战斗', '亦称加入战斗或投入战斗。战斗中后续梯队或预备队前进至实施战斗位置的行动。通常是从前一梯队战斗队形的间隙或翼侧进入战斗。', 74);
INSERT INTO `t_military_term_data` VALUES ('34c63f98-3f05-448e-8c48-04c0b0a7d538', '97a19170-bfac-42c5-9906-1acb187f0654', '跃升', '飞机急跃升的简称。飞机向前上方以大于稳定上升的最大上升角进行直线减速的飞行。有些飞机跃升时的最大上升角可达90度。', 238);
INSERT INTO `t_military_term_data` VALUES ('34cc6d5a-d409-403c-a0bf-60fa40f11a67', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克徒涉场', '坦克徒涉浅水江河障碍的场地。应选在河水较浅、河底坚硬、水流平缓、两岸地形便于坦克隐蔽机动的地段上。', 64);
INSERT INTO `t_military_term_data` VALUES ('34cee2de-0efa-4101-9769-a77c8ea4c2f8', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击能力', '高炮部队或分队遂行射击任务所具有的能力。主要包括；有效射击范围,发射速度,发射弹数,反应时间,射击时间和毁歼概率,以及能同时射击的目标数等。', 142);
INSERT INTO `t_military_term_data` VALUES ('34d2fba6-cfed-4763-a105-f8003505e4de', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教范', '规范军事技术训练的基本教材。如射击教范、汽车驾驶教范等。', 39);
INSERT INTO `t_military_term_data` VALUES ('34e2e1df-7492-4838-ad9b-a7944a1da106', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达告警设备', '用以实时截获、识别敌方雷达信号并能立即发出警报信息的电子设备。通常安装在飞机、舰船、坦克等兵器上,可与雷达干扰系统和武器控制系统交联,以便对敌方雷达或雷达载体采取有效的对抗措施。', 116);
INSERT INTO `t_military_term_data` VALUES ('34e87a08-f1f5-4232-8826-321f63cf53d7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防空体系', '由各种防空组织、武器、设施等要素构成的有机整体。主要包括各类防空组织系统及其指挥控制、情报预警、防空武器、勤务保障等系统。', 214);
INSERT INTO `t_military_term_data` VALUES ('34ebed94-176d-434d-9a5e-03cfa2601356', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队群众工作', '中国人民解放军开展的以密切军队与政府、军队与人民群众之间关系,实现军政、军民一致的工作。是中国人民解放军政治工作的重要内容。', 120);
INSERT INTO `t_military_term_data` VALUES ('34ed19b5-e554-4156-9a49-683a983e37e6', '916997ee-6728-4c61-9b79-d96960b1dc86', '简易防护器材', '对毒剂、放射性落下灰和生物战剂有一定防护作用的器材。制作简单、取材容易,通常指非制式的、群众自制的防护器材。如用锯末、土颗粒、石灰等制成的滤毒罐,浸以苏打水的毛巾、手帕和口罩等。', 197);
INSERT INTO `t_military_term_data` VALUES ('34f08152-517e-480d-8191-72a7efa14e46', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '俘获', '作战中俘虏敌方人员和缴获敌方武器装备、物资、文件等的统称。', 372);
INSERT INTO `t_military_term_data` VALUES ('34f2ed02-e2f4-460d-b652-5e614ee35c59', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '逼降', '利用强大的军事压力或其他有利态势逼迫敌人投降。', 371);
INSERT INTO `t_military_term_data` VALUES ('34f8e184-4745-4fd4-98f8-fad26b4ec186', '916997ee-6728-4c61-9b79-d96960b1dc86', '侦毒纸', '毒剂液滴侦毒纸的简称。用以发现地面、物体表面毒剂液滴的侦毒器材。有一色侦毒纸和三色侦毒纸。可侦检沙林、梭曼、维埃克斯、芥子气、路易氏气等。供合成军队使用。', 166);
INSERT INTO `t_military_term_data` VALUES ('3507c803-0d24-474e-9e46-3df34b5b6371', '83e065b4-6737-4645-9ea5-8276d1de13ed', '设伏坦克', '担负伏击任务的坦克。通常预先配置在敌必经路线的附近,以突然的火力和冲击消灭敌人。', 39);
INSERT INTO `t_military_term_data` VALUES ('35081da5-8a44-4f82-b0ef-95f4b2137147', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '士气', '军队的战斗意志和斗争精神的统称。是军队精神力量的外在表现和战斗力的重要因素。', 109);
INSERT INTO `t_military_term_data` VALUES ('350f261f-5eb5-41d6-8f34-49bb92ea170a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '起伏地', '地面高低起伏的地域。一般指起伏平缓的岗地和低矮的丘陵地。', 123);
INSERT INTO `t_military_term_data` VALUES ('3510adc6-59a3-44a6-be6d-509420ef4fde', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战略学', '亦称军事战略学。研究战争及其指导规律的学科。是军事学术的最高领域和起主导作用的骨干学科。主要研究内容有：战争与战略基础理论,战争准备与实施理论,军事力量建设与运用理论等。', 23);
INSERT INTO `t_military_term_data` VALUES ('352e85ce-b577-4589-bda1-595a1681536b', '98df76fb-4b65-48ff-a56c-4db587327c79', '伤病员分类', '战时救治机构将伤病员区分为不同处置类型的活动。分为收容分类、救治分类和后送分类等。是战时组织实施大批伤病员医疗后送不可缺少的环节。通常由战伤救治经验丰富的卫生人员实施。', 201);
INSERT INTO `t_military_term_data` VALUES ('3532df4b-1a7e-4d93-a7e9-60f558f59ca0', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮火力转移', '亦称高炮火力机动。高炮部队或分队的火器不变换发射阵地而改变射击目标的行动。分为交替转移火力、逐批转移火力和越批转移火力。', 88);
INSERT INTO `t_military_term_data` VALUES ('3534e331-2eff-4ec7-910a-cfe1107d4aff', '878651de-adf5-4c72-9376-9c363b893ff8', '战略保障', '军队为顺利遂行战略任务而采取的各项保证性措施与进行的相应活动的统称。包括作战、后勤、技术、政治工作等方面的战略保障。', 96);
INSERT INTO `t_military_term_data` VALUES ('353ddd5c-9ee2-402b-90e8-3c223267294c', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '多光谱摄影', '将被拍摄物体的光谱,按波长分割成若干段,分别拍摄该物体几个不同波段的影像的摄影方法。根据多光谱航空像片的影像,可判明海岸线、浅滩、暗礁、水深、地下水以及隐蔽在密林深处的人员、装备等。', 241);
INSERT INTO `t_military_term_data` VALUES ('353fa33c-e91e-40b8-8a24-9993907ff1cd', '916997ee-6728-4c61-9b79-d96960b1dc86', '半数失能剂量', '能使染毒人员 50％丧失正常活动能力的毒剂量。用ID50或ICt50表示。', 136);
INSERT INTO `t_military_term_data` VALUES ('354721d7-40da-44f5-9f3a-e61a58648309', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '当日任务', '进攻的军队当日日终前应完成的作战任务。', 83);
INSERT INTO `t_military_term_data` VALUES ('354b03ce-c6d8-454a-831b-0f5ae21949ac', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '新材料技术', '研制、生产新型材料的技术。主要包括新型金属材料、半导体材料、光学晶体玻璃材料、陶瓷材料、高分子材料和复合材料等技术。是提高社会生产力的技术基础和先导,对提高武器装备的战术技术性能有重大影响。', 11);
INSERT INTO `t_military_term_data` VALUES ('35574f75-d18c-466b-a055-3c701c2b7311', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事建设', '①国家或政治集团为增强军事力量而进行的建设。主要包括武装力量、军事科技、军事设施等方面的建设。②军队为提高其成员军事素质而进行的各项工作的统称。通常指司令部系统所组织的工作,主要包括战备、军事训练、行政管理、武器装备建设、动员准备与国防后备力量建设、军事科学研究等。', 43);
INSERT INTO `t_military_term_data` VALUES ('356208e6-cc32-424f-a81f-c4470742f1f0', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战准备', '军队为遂行作战任务而进行的各项准备。主要包括：侦察和研究敌情,勘察地形,进行战斗动员,组织临战训练,补充调整人员、物资,检查、保养、维修武器装备等。', 156);
INSERT INTO `t_military_term_data` VALUES ('356adf96-9d35-444e-8dab-7eac9687d791', '8a761efd-50a6-4ac8-9913-b7d745104f82', '行进间射击', '地面武器在前进中实施的短停顿或不停顿的射击。', 93);
INSERT INTO `t_military_term_data` VALUES ('356c1ee6-ff12-4610-9b52-d5a24a9b0380', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '耐爆地雷', '配用耐爆引信,在爆炸冲击波作用下不易发火,但在目标作用下能正常发火的地雷。', 146);
INSERT INTO `t_military_term_data` VALUES ('356d2ce8-60e6-4097-b449-3e5d6e5f80df', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '光电对抗装备', '用于光电对抗侦察和光电干扰的电子对抗装备。包括光电对抗侦察设备和光电干扰设备（器材）。', 113);
INSERT INTO `t_military_term_data` VALUES ('356df7bd-cc7b-429e-8b89-838d5644ea19', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '沙盘作业', '按照想定在沙盘上研练组织指挥的作业。', 106);
INSERT INTO `t_military_term_data` VALUES ('3581b4fa-8ece-4f49-a361-d4be27cedd2e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '机动布雷', '作战过程中针对敌人行动临时实施的布雷。分为拦阻布雷和覆盖布雷。', 181);
INSERT INTO `t_military_term_data` VALUES ('3584cb16-0486-4a01-99b4-4a8bcf19960d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '劣势', '战争中处于比敌方弱小、不利地位的态势。通常由军事力量、作战指导及与之相关的政治、经济、科技、文化、地理环境等多种因素决定。劣势是相对于优势而言的,在一定条件下也可转化为优势。', 266);
INSERT INTO `t_military_term_data` VALUES ('35903f3d-c01d-404a-9166-eb44337ae50a', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥所保障', '指挥所正常工作而采取的保障。主要包括通信保障、安全保障设备与技术保障生活保障等。', 57);
INSERT INTO `t_military_term_data` VALUES ('3598078e-785a-4fae-b440-05007c7aa1db', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '卫星大地测量', '利用人造地球卫星进行地面点定位及测定地球形状、大小和地球重力场的技术。在军事上可为远程武器和各种航天器的轨道计算提供精确的地球形状和地球重力场数据,为发射点和测控站提供精确的地心坐标,为飞机、舰船和地面部队提供导航定位等。', 224);
INSERT INTO `t_military_term_data` VALUES ('35a6863a-b4ad-45c7-ba67-08d25b6d1999', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '临时驻止之敌', '行动途中短时间停留或驻扎的敌军。如休息、宿营之敌,在集结地域、待机地域停留之敌等。', 238);
INSERT INTO `t_military_term_data` VALUES ('35b32644-9b07-4fdc-a925-6cc5805e39e1', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹稳定方式', '使地空导弹稳定地飞抵目标的方式。有尾翼稳定、尾翼与旋转稳定、弹翼与尾翼稳定等方式。', 199);
INSERT INTO `t_military_term_data` VALUES ('35ce3d15-1f6a-4aa1-a2ec-a36f7da559e0', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备教育', '以树立常备不懈思想和保持良好战备状态为目的的教育。是军队战备工作和经常性思想政治教育的重要内容之一。', 100);
INSERT INTO `t_military_term_data` VALUES ('35d6443f-f97c-49b2-9b5f-dd2e79294985', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '截击卫星', '亦称反卫星卫星。用以攻击、破坏敌方太空目标的人造地球卫星。是天基反卫星武器的一种。可利用卫星上的雷达或红外寻的器,探测与跟踪目标,自动变轨接近目标,利用自身爆炸或发射火箭、炮弹、激光、粒子束等杀伤手段摧毁目标。', 226);
INSERT INTO `t_military_term_data` VALUES ('35d77ee2-be1c-491b-92de-5e4020bddafd', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸电磁脉冲效应', '简称核电磁脉冲效应。核爆炸释放的Y、X射线与其作用范围内的介质相互作用,产生的瞬时脉冲电磁场对电磁系统所造成的破坏效果。其电场强度高（10伏／米）,频域宽（从零至数百兆赫）,传播距离远,能干扰或损伤无线电电子系统、供电系统等。', 175);
INSERT INTO `t_military_term_data` VALUES ('35e6db6c-52a0-4e14-872f-ed7fb01fd085', '98df76fb-4b65-48ff-a56c-4db587327c79', '白袍衣', '亦称烈士布、殉葬布。用于包裹烈士遗体的白布。以人份为计算单位。每人份为白布8米。', 158);
INSERT INTO `t_military_term_data` VALUES ('35f47ca0-ecb4-4e70-8670-0877cc03cfc9', '8a761efd-50a6-4ac8-9913-b7d745104f82', '实际射击距离', '从外弹道起点到弹着点之间的距离。', 44);
INSERT INTO `t_military_term_data` VALUES ('36000215-06ba-4c26-acc9-3ebd9eb7e1db', '878651de-adf5-4c72-9376-9c363b893ff8', '战争形势', '战争的发展变化在一定时期内所形成的格局和态势。是敌对双方以作战活动为中心的军事及政治、经济、科技和外交诸方面矛盾斗争的综合反映。', 40);
INSERT INTO `t_military_term_data` VALUES ('3601019d-759b-47e6-88ab-610fc643853d', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '分队战术训练', '分队为掌握战斗原则和方法而进行的训练。目的是提高分队指挥员的组织指挥和分队快同作战的能力。', 84);
INSERT INTO `t_military_term_data` VALUES ('36015029-7644-4eb8-87cb-afc996983acd', '97a19170-bfac-42c5-9906-1acb187f0654', '歼击轰炸航空兵', '以歼击轰炸机为基本装备,主要遂行攻击、轰炸地面、水面目标以及空战任务的航空兵。通常用以攻击、轰炸敌方战役和战术纵深内的目标,参加争夺制空权的斗争等。', 6);
INSERT INTO `t_military_term_data` VALUES ('360c68a1-c728-45e4-939b-4dec0378226c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮初速', '火炮射弹在起点时运动的速度。', 241);
INSERT INTO `t_military_term_data` VALUES ('36119c81-06a5-45b8-98ee-7e06def63cb4', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹紧急关机', '液体导弹发动机点火后利用地面紧急关机电路关闭发动机的过程。分为自动紧急关机和人工紧急关机。通常在发现发动机工作不正常或因其他原因不能发射时进行。', 104);
INSERT INTO `t_military_term_data` VALUES ('3612cdfc-8dce-4708-b86f-889890675b4d', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '班哨', '担负宿营警戒任务并进入预定位置的建制班。通常由宿营的营、连或排哨派出。', 23);
INSERT INTO `t_military_term_data` VALUES ('36208bd5-1c96-4ff4-806d-1f643358149b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '非触发地雷', '受目标物理场的作用而发火的地雷。配用磁引信、震发引信、声引信、光引信及能感知两种物理场的复合引信等。多为反坦克地雷。', 135);
INSERT INTO `t_military_term_data` VALUES ('3620b232-0798-4bfc-bc60-b1b096c291a1', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '毛泽东军事思想', '以毛泽东为代表的中国共产党人关于中国革命战争和军队问题的科学理论体系。是毛泽东思想的重要组成部分,中国共产党集体智慧的结晶。基本内容包括：辩证唯物主义的战争观和方法论,人民军队的建军学说,人民战争的指导路线和战略战术,以及国防建设的理论、方针和原则等。', 11);
INSERT INTO `t_military_term_data` VALUES ('3621b94a-fb51-4063-9d3a-a343f27a258e', '97a19170-bfac-42c5-9906-1acb187f0654', '负速度差截击', '歼击机对大于本机速度的空中目标进行的空中截击。通常是从目标前半球发射空空导弹或使用航炮和航空火箭弹实施拦截射击。', 71);
INSERT INTO `t_military_term_data` VALUES ('3634b07f-14f4-4524-a227-53efad4a1f71', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '竹签桩', '用长30～50厘米的竹片或小圆竹,削尖两端插入土中构成的防步兵障碍物。通常设置在草丛中,也可设置在防步兵陷阱内。一般间距为30～40厘米,纵深不小于4米。', 128);
INSERT INTO `t_military_term_data` VALUES ('364a8815-f6e3-4a70-8158-b32aea3d90d5', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '军事气象勤务', '为实施军事气象保障而开展的各项专业技术工作的统称。主要包括；气象观测,气象情报的传输与加工,天气预报和气候预测,气象装备保障和气象勤务管理等。', 95);
INSERT INTO `t_military_term_data` VALUES ('366ced56-a57f-46b9-925e-8c0142067f31', '06a75831-13a1-4660-870a-455bb445336a', '通信容量', '通信系统在单位时间内能够传输的最大信息量。是通信系统通信能力的重要标志。', 93);
INSERT INTO `t_military_term_data` VALUES ('3674669a-e019-4162-8580-2e3e7054b594', '97a19170-bfac-42c5-9906-1acb187f0654', '伞降', '用降落伞将人员、装备、物资从航空器上降落于地面的空降行动。', 147);
INSERT INTO `t_military_term_data` VALUES ('367f72ec-67c4-4ff9-b079-16140bc4c259', '06a75831-13a1-4660-870a-455bb445336a', '信号表', '以简短信号表达一定通信内容的一种隐蔽指挥文书。通常在无线电台通信和简易信号通信中用以传递紧急战斗号令和战斗报告等。', 152);
INSERT INTO `t_military_term_data` VALUES ('3684c27e-62bc-4739-ae32-4a35e6096399', '98df76fb-4b65-48ff-a56c-4db587327c79', '军办企业', '由军队投资和经营管理的,从事生产、流通、服务等活动的独立经济核算单位。', 163);
INSERT INTO `t_military_term_data` VALUES ('3685185c-3a88-4745-ba93-a60bd664cba3', '06a75831-13a1-4660-870a-455bb445336a', '指挥通信', '为保障军队指挥,按指挥关系建立的通信联络。包括作战编成内上下级之间,军队同配属作战的民兵之间建立的通信联络。对主要方向或执行重要任务的部队、分队,必要时可建立越级指挥通信。', 8);
INSERT INTO `t_military_term_data` VALUES ('36986875-9cb5-49d9-b19d-43cc3796486d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海底电缆', '简称海缆。敷设在海底的电缆。包括电力电缆和通信电缆。电力电缆用以输送电力。通信电缆用于沿岸通信、岸岛通信、岛间通信和越洋通信。', 363);
INSERT INTO `t_military_term_data` VALUES ('369afc2c-1f79-4b93-989d-d44da610dc67', '97a19170-bfac-42c5-9906-1acb187f0654', '机场区域', '机场和为其划定的各种飞行空域的空间范围。由地面和空中两部分组成。地面部分包括飞行场地、飞机疏散区、技术勤务区、营区和仓库区等；空中部分包括机场起落航线空间和其他飞行空域。', 418);
INSERT INTO `t_military_term_data` VALUES ('36a7f03e-688c-451d-8f75-54cbbec2d063', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '甲板', '船体结构中位于内底板以上、用以封盖部内空间或将其水平分隔成层的平面板架。主船体最上一层贯通全部的连续甲板称上甲板,以下各层甲板统称下层甲板；局部设置的甲板称平台甲板或平台。上甲板以上的各层甲板和平台统称上层建筑甲板。', 160);
INSERT INTO `t_military_term_data` VALUES ('36bada09-ddd4-4e6d-a66d-234e393afeb2', '97a19170-bfac-42c5-9906-1acb187f0654', '空中指挥所', '设置在飞机上的指挥所。通常作为地面或海上指挥所的预备指挥所或辅助指挥所,可在地面、海上指挥所不能实施指挥时用以接替其指挥。', 177);
INSERT INTO `t_military_term_data` VALUES ('36bb685d-9fe4-4b6a-8129-b063c55da270', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '气垫船', '利用船底与水面或地面之间形成的气垫,使船体全部或大部离开水面或地面而高速航行的船只。分为冲气式气垫船和侧壁式气垫船。', 157);
INSERT INTO `t_military_term_data` VALUES ('36c82294-3caa-4516-b183-51e07d8a10db', '916997ee-6728-4c61-9b79-d96960b1dc86', '吸收剂量', '简称剂量。单位质量物质受电离辐射作用后吸收射线的能量。常用以表示射线对人员的伤害程度。单位为戈瑞。', 98);
INSERT INTO `t_military_term_data` VALUES ('36d411bf-5f4f-45ea-90de-981abcc20cc4', '31f4a446-5b98-4873-9d53-310d97125b07', '核反击指挥程序', '导弹部队指挥员根据上级作战命令制定的核反击作战中的指挥工作顺序。通常采用文字叙述、表格和网络图等形式表达。', 129);
INSERT INTO `t_military_term_data` VALUES ('36eb1e97-7b3f-48d9-9175-9adfa6ca9a38', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆修理', '为恢复车辆完好的技术状况而进行的作业。通常分为小修、中修和大修。必要时可进行总成大修。', 312);
INSERT INTO `t_military_term_data` VALUES ('3708d07f-c903-4846-aee6-ba2948d3c40d', '31f4a446-5b98-4873-9d53-310d97125b07', '起坚导弹', '利用起竖设备将水平状态的导弹安全可靠地竖立在发射台上的过程。分为场坪起坚和井内起坚。是导弹发射准备中的一项重要工作。', 82);
INSERT INTO `t_military_term_data` VALUES ('3709318a-84f8-4aad-bba5-3260b0991516', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军事审判工作', '中国人民解放军和中国人民武装警察部队的审判机关依法审理内部的刑事、经济纠纷等案件的专门工作。', 132);
INSERT INTO `t_military_term_data` VALUES ('3712b188-d3b9-456e-83ce-221bcb3119f3', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军作战保障', '海军为顺利遂行作战任务而采取的各项保证性措施与进行的相应活动的统称。主要包括：侦察,警戒,技术观察,通信,电子防御,对核、化学、生物武器的防护,工程、伪装,航海,水文、气象,对航空兵引导,导航以及防险救生等保障。', 356);
INSERT INTO `t_military_term_data` VALUES ('371df9e1-0726-42e8-9607-b750c975e27a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海战', '敌对双方海军或以海军为主体的兵力在海战场上进行的战役、战斗的统称。分为海上进攻战和海上防御战两种基本类型。目的是消灭敌海上兵力集团,夺取制海权,保证己方海上目标安全及海上行动自由等。', 21);
INSERT INTO `t_military_term_data` VALUES ('371ef992-6c6c-425f-ac03-2295e1dddcc1', '8a761efd-50a6-4ac8-9913-b7d745104f82', '方向射界', '射击武器由于结构限制，火身轴线在水平面上能转动的角度范围。', 87);
INSERT INTO `t_military_term_data` VALUES ('3724c76f-2f02-49aa-a668-1d6393af93b7', '8a761efd-50a6-4ac8-9913-b7d745104f82', '瞎火', '射击武器在射击时击针正常打击,射弹不发火的射击故障。', 140);
INSERT INTO `t_military_term_data` VALUES ('373f8c7e-1705-4940-b908-2f8f6caf3727', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '全副武装', '军人按规定携带所配备的全部武器装备。', 53);
INSERT INTO `t_military_term_data` VALUES ('375643cf-ac07-41c8-9752-1e80f7f6a977', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '扩张战果', '在已取得的战果的基础上继续发展胜利的作战行动。', 386);
INSERT INTO `t_military_term_data` VALUES ('375779d1-2957-46c6-84a8-09db7b5853d7', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机着陆', '飞机从一定高度（通常为25米或15米）下滑并落于地面直至停止滑跑的运动过程。通常由下滑、平飞、平飘、接地和滑跑等阶段组成。', 207);
INSERT INTO `t_military_term_data` VALUES ('3759a0c0-7f9a-42b1-89b9-a81c6f349c50', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '枯水', '无雨或少雨时期,江河、湖泊等水体流量减少、水位下降的现象。在枯水期,有些河流、湖泊出现于枯、断流现象。', 118);
INSERT INTO `t_military_term_data` VALUES ('3785b57a-5409-4e71-842e-1673f743238e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇仪仗队', '舰艇上执行礼仪任务的小分队。通常由一名军官和若干名水兵组成。主要用于迎送国家、政府和军队领导人。', 403);
INSERT INTO `t_military_term_data` VALUES ('378a7b3a-ac2d-4349-9a20-c2e2de9a78c8', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学威胁', '敌可能在战争中使用化学武器而构成的威胁。构成化学威胁的主要条件是：敌拥有化学武器的种类和数量,使用化学武器的能力、可能性和准备状况。', 20);
INSERT INTO `t_military_term_data` VALUES ('379265af-a3ec-4f05-9c63-9a381522c4ee', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮单独修正量', '炮兵连用于使用统一的射击诸元时,各炮自行修正的补偿修正量。用以修正因各炮技术条件及炮位不同,所用炮弹的重量差异而产生的射方偏差。通常包括瞄准线偏移修正量,射向修正量,射角不一致修正量,火炮初速偏差修正量,弹重偏差修正量,以及对基准炮或炮阵地中心的高差、纵深差的修正量等。', 245);
INSERT INTO `t_military_term_data` VALUES ('379f88f2-6795-46da-8f8c-59a898259447', '83e065b4-6737-4645-9ea5-8276d1de13ed', '中型坦克', '战斗全重20～40吨、火炮口径为75～105毫米的坦克。用以遂行装甲兵的主要作战任务。', 88);
INSERT INTO `t_military_term_data` VALUES ('37ac650f-59e9-40a2-beb7-b75c5384d849', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '遮蔽地', '地面起伏显著或地物较多,妨碍观察的地域。如山地、丘陵地、山谷、森林和居民地等。', 121);
INSERT INTO `t_military_term_data` VALUES ('37b0716f-7013-4394-a6e5-00831ebab77b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '规正水平', '火炮放列或器材整置后,用水准仪（水准器）或象限仪将其调整为水平状态的过程。', 273);
INSERT INTO `t_military_term_data` VALUES ('37bd6f82-663d-4f28-b438-ee19ed85b37b', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '雷达', '利用发射和接收反射的无线电波探测目标的设备。由天线、发射机、接收机、显示器和电源等部分组成。军事上广泛用于警戒、引导、侦察、导航、火控、制导、靶场测量、敌我识别等。', 88);
INSERT INTO `t_military_term_data` VALUES ('37c7aa95-a07e-47d7-bc7a-236708ec47a5', '98df76fb-4b65-48ff-a56c-4db587327c79', '复合伤', '两种以上杀伤因素作用于人体所引起的损伤。如核武器可同时使人员遭受冲击伤、烧伤和放射线伤等。', 186);
INSERT INTO `t_military_term_data` VALUES ('37d0bd32-8eb1-472f-bdb7-50423b00eef0', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '合同战役训练', '合成军队为掌握合同战役理论和合同战役行动的原则与方法而进行的训练。按规模,分为集团军合同战役训练、方面军合同战役训练和战区合同战役训练。', 93);
INSERT INTO `t_military_term_data` VALUES ('37d483b8-bad3-4729-80ec-d80f22de2429', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '步兵', '以枪械、小口径火炮、导弹、装甲车辆为基本装备,主要在地面遂行作战任务的陆军兵种。按机动和战斗方式,分为徒步步兵、摩托化步兵和机械化步兵。能单独或在其他军种、兵种协同下作战。主要担负近战中歼灭敌人,夺取或把守地区和阵地的任务。', 36);
INSERT INTO `t_military_term_data` VALUES ('37d69d70-20ad-463a-9399-239df941cb63', '97a19170-bfac-42c5-9906-1acb187f0654', '空中攻击波', '航空兵部队在一定时间内,对地面或水上某一目标或目标群进行大规模空中突击的若干梯队的统称。', 99);
INSERT INTO `t_military_term_data` VALUES ('37df7356-6bb5-4bb9-8ccf-0ce76c36f180', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击点目标', '一枚核弹头直接命中即可将其全部摧毁的单个目标。其最大长度的一半不大于核弹威力半径的五分之一。', 162);
INSERT INTO `t_military_term_data` VALUES ('37f46dbe-b104-4aa5-8e1b-90a8334dd1c8', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克生存力', '坦克在战场上保持战斗力的能力。主要表现为坦克在战场上不被发现的概率,被发现后不被击中的概率,被击中后不被击毁的概率。', 174);
INSERT INTO `t_military_term_data` VALUES ('37f7f4cf-81ef-4b89-8fab-3c4ada534d46', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上猎雷', '猎雷舰艇使用探雷器和灭雷具直接摧毁沉底水雷的战斗行动。能逐个排除各种引信的水雷,但作业速度较慢。', 113);
INSERT INTO `t_military_term_data` VALUES ('3803b7ce-c200-46e3-b269-bebf0be0cd56', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮集火近战', '高炮部队或分队集中火力,对进入有效射击范围内的同一目标,选定有利时机突然开火的战法。运用这种战法,可使火力密度增大,命中概率提高。', 167);
INSERT INTO `t_military_term_data` VALUES ('380523cf-2f28-4abf-bd0d-599c610746e3', '97a19170-bfac-42c5-9906-1acb187f0654', '集中突击', '航空兵部队使用较多的兵力,在短时间内对地面或水面单个目标或目标群进行密集的空中突击。用以彻底摧毁或严重破坏目标,并给敌以精神上的震撼。', 101);
INSERT INTO `t_military_term_data` VALUES ('380b3d8e-fa8d-40da-b869-05798fc514e5', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '室内作业', '按照想定在室内研练组织指挥的作业。', 103);
INSERT INTO `t_military_term_data` VALUES ('38176b04-4c49-4b37-9528-65e7337302f3', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '情况显示', '在军事训练或演习中以实兵、装备和器材等,对敌对双方情况进行的显现和表示。', 139);
INSERT INTO `t_military_term_data` VALUES ('3818425f-b9db-4aa2-8f96-2bca50685655', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '削壁', '将己方海岸、江岸的斜坡削成陡壁而构成的防登陆土工障碍物。其高度应能使敌登陆工具和登陆兵在高潮水位时难以上陆。', 118);
INSERT INTO `t_military_term_data` VALUES ('3818db02-df1d-4003-b3ca-12d706cb6e60', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射成功率', '发射导弹成功数与发射导弹数的比值。通常用百分比表示。是反映导弹部队战斗力强弱的一项重要数据。', 140);
INSERT INTO `t_military_term_data` VALUES ('382119f7-b45c-42f9-a0ce-7afc6d57ef49', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '载人飞船', '能保障航天员在太空执行航天任务,航天员座舱能返回地面垂直着陆的航天器。分为卫星式载人飞船、登月载人飞船和行星际载人飞船等。主要用于：试验各种载人航天技术,开展航天医学和生理学研究,通过改变轨道高度进行侦察,在轨道上成为空间站乘员的救生艇,为空间站接送航天员和运送物资,实施载人绕月、登月飞行和行星际飞行等。', 223);
INSERT INTO `t_military_term_data` VALUES ('382c3d46-7610-4d6c-bb28-a823748c2af1', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '岗位练兵', '在工作岗位上进行本职专业训练的活动。', 160);
INSERT INTO `t_military_term_data` VALUES ('383289b2-395f-413e-a456-71e840e3e1a6', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核武器储存期', '核武器在正常的储存条件下,为保持其使用的可靠度而规定的存放期限。', 138);
INSERT INTO `t_military_term_data` VALUES ('38365845-f0d2-469d-96c8-096076dbe7a3', '878651de-adf5-4c72-9376-9c363b893ff8', '战略转变', '根据客观形势变化的要求而对军事战略所作的重大改变。通常包括战略任务、战略方针、战略重点、战略方向的改变及主要作战形式的转换等。', 83);
INSERT INTO `t_military_term_data` VALUES ('383ef85f-e889-4297-922f-656851c8e85c', '916997ee-6728-4c61-9b79-d96960b1dc86', '通过剂量', '人员通过沾染区时受到的照射量或吸收剂量。单位是库仑／千克或戈瑞。', 104);
INSERT INTO `t_military_term_data` VALUES ('38419b63-4158-4e5c-b79d-b8efd9c3237f', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '培训', '院校对学员进行系统的培养训练。是培养军官、文职干部和士官的主要形式。', 145);
INSERT INTO `t_military_term_data` VALUES ('38447b9c-9b12-4833-94c7-eca172b48349', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子侦察飞机', '装有电子侦察设备,专门用以截获、分析、记录敌方电磁辐射信号并测向、定位的飞机。包括有人驾驶电子侦察飞机、无人驾驶电子侦察飞机和电子侦察遥控飞行器等。多用于对敌方浅近纵深地区实施不定期的电子侦察。', 121);
INSERT INTO `t_military_term_data` VALUES ('384e8358-bb84-47eb-b5c5-4b2f99e7de4c', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '扩编', '对军队原编制进行扩充。包括增加建制单位、扩充编制员额和武器装备等。', 75);
INSERT INTO `t_military_term_data` VALUES ('384ea64b-b6f7-437e-a989-890f14b48e1f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地理坐标', '用经度、纬度表示地面点位置的球面坐标。军事上通常用地理坐标指示和确定舰艇、飞机与其他目标的位置。在小于1:25万比例尺的地形图上,都绘有地理坐标网,并注有相应的经纬度数值。在大于1:10万比例尺地形图上,图廓间绘有分度带,图廓四角注有经纬度数值。', 231);
INSERT INTO `t_military_term_data` VALUES ('3870abd8-2edb-4e73-a79e-48f942218519', '878651de-adf5-4c72-9376-9c363b893ff8', '战争实施', '战争活动的实际进行。通常指从战争开始至结束所进行的以作战为中心的全部活动。', 43);
INSERT INTO `t_military_term_data` VALUES ('388106ef-4657-4b85-8d8b-67b95c4e0256', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '先遣侦察', '在作战部队战斗行动之前,派出侦察分队到预定作战地区进行的侦察。主要查明敌主力位置、行动企图和己方部队开进的地形、道路等情况,为指挥员定下决心、制订作战计划提供依据,并为尔后全面展开侦察打下基础。', 17);
INSERT INTO `t_military_term_data` VALUES ('38885e61-ce20-4ce1-98c2-486e7622b002', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '三大任务', '中国人民解放军担负的打仗、做群众工作和生产二项基本任务。在中国历次革命战争中,人民解放军既是一支战斗队,同时又是工作队、生产队。体现了人民军队的性质和宗旨。', 4);
INSERT INTO `t_military_term_data` VALUES ('38919600-cab4-411d-bdd3-5c5565b66e2f', '97a19170-bfac-42c5-9906-1acb187f0654', '航空弹药', '能供航空器使用的各种弹药的统称。主要包括；机载导弹,航空炮弹、枪弹、炸弹、火箭弹、鱼雷、水雷,座椅弹射弹、座舱盖抛射弹,航空信号弹等。', 311);
INSERT INTO `t_military_term_data` VALUES ('3893159b-ff76-4837-9474-c7f0b3c4e055', '878651de-adf5-4c72-9376-9c363b893ff8', '战略协同', '各战略集团为达成全局性的任务而进行的协调配合。是作战协同的最高层次。通常由统帅部或战区组织实施。', 105);
INSERT INTO `t_military_term_data` VALUES ('389fe37f-80a6-4777-bf00-8dbfd1c3bc54', '06a75831-13a1-4660-870a-455bb445336a', '密码电报通信', '密化报文内容的通信。发端将报文内容编码、加密后,用通信设备发送出去,收端进行逆变换,恢复成原报文。加密方式有电子自动加密、机械加密和手工加密等。', 153);
INSERT INTO `t_military_term_data` VALUES ('38c5c7a2-d1e7-4cea-9eb3-01e68007d1ca', 'f0140091-c11a-48c9-8836-8aa94439dac0', '仓促防御战斗', '临时转入防御,预先没有充分的准备或准备时间短促的防御战斗。通常在受敌威胁的紧急情况下进行。应就地占领阵地或抢占有利地形,迅速组织并逐步完善防御体系。', 203);
INSERT INTO `t_military_term_data` VALUES ('38cd5653-c3e0-4dcf-9ba1-caafa7d5bfe6', '06a75831-13a1-4660-870a-455bb445336a', '密钥', '用以控制密码变换的可变参数。改变了密钥,即改变了密码算法。是保密设备中最机要的部分。对密钥必须加强管理,确保其在制作、分配、传递、存储以及注入使用过程中的安全。', 157);
INSERT INTO `t_military_term_data` VALUES ('38d38e7e-8016-4706-9e69-777abb73c86e', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '沙（砾）质海岸', '由泥沙或砾石构成的海岸。岸线较平直,海湾较少,岸坡较平缓,便于登陆作战。', 43);
INSERT INTO `t_military_term_data` VALUES ('38e51a5e-3abc-4b2b-b7c3-2c6fdf9c2315', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防登陆水雷', '用以阻滞登陆工具上陆的陆军水雷。布设时多与其他防登陆障碍物相结合,构成防登陆障碍物配系。', 161);
INSERT INTO `t_military_term_data` VALUES ('38e9ce50-5449-4a8a-ab7a-1ab4c3be6edd', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '应用训练', '军事基本知识和技能的实际运用的训练。通常于基础训练完成之后,在近似实战的条件下组织实施。分为单项科目的应用训练和多项科目的应用训练。', 70);
INSERT INTO `t_military_term_data` VALUES ('38f7af5f-7799-4dae-ab93-304c440f7dfd', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天遥感', '利用装在航天器上的遥感器收集地物目标辐射或反射的电磁波,以获取并判认大气、陆地或海洋环境的信息。军事上广泛用于侦察、导弹预警、海洋监砚、测绘、气象观测等。', 289);
INSERT INTO `t_military_term_data` VALUES ('38f7e039-8d66-4886-8189-030e4d7d0263', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '专业战术训练', '专业部队、分队及人员为掌握专业战斗原则和方法而进行的训练。', 85);
INSERT INTO `t_military_term_data` VALUES ('39042610-86a7-4b57-b8c0-10bd58ad6ccc', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '成果法', '根据精密测地决定的测地诸元、利用对试射点的试射成果或对目标的射击成果,求取并修入射击条件修正量以决定射点开始诸元的方法。成果法精度较好,通常用以决定目标射击开始诸元。是决定射击开始诸元的基本方法。', 146);
INSERT INTO `t_military_term_data` VALUES ('3905c342-d5e1-4b5b-a061-7a34602c769c', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防体制', '国家为进行边防建设和斗争而确定的组织体系及相应制度。', 110);
INSERT INTO `t_military_term_data` VALUES ('390cfdc6-aeaf-422c-aa9a-326fdc2ff955', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事目的', '在军事方面所要达到的预期结果。', 48);
INSERT INTO `t_military_term_data` VALUES ('391b662b-bc67-47cc-b30b-7624626310dc', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵分散指挥', '在上级统一意图下炮兵部队或分队指挥员独立实施的指挥。通常在任务需要、情况变化急剧或部队分散行动不便集中指挥时采用。', 85);
INSERT INTO `t_military_term_data` VALUES ('393642cb-f9c9-408d-8992-f38f8a8ccd95', '97a19170-bfac-42c5-9906-1acb187f0654', '空军高射炮兵', '空军中以高射炮武器系统为基本装备,主要遂行地面防空作战任务的兵种。通常用于要地防空和争夺制空权的斗争。必要时也可遂行歼灭地面或水面目标的任务。', 23);
INSERT INTO `t_military_term_data` VALUES ('393b1e61-0b4b-45f3-b71d-9c84f8c624d7', '916997ee-6728-4c61-9b79-d96960b1dc86', '核袭击警报', '报知敌核袭击的信号。包括预先警报、紧急警报和解除警报。目的是使部队及时采取防护措施,避免或减轻核武器的毁伤。', 40);
INSERT INTO `t_military_term_data` VALUES ('3940143d-fad8-4949-a8ae-a76e8aa17210', '31f4a446-5b98-4873-9d53-310d97125b07', '提升导弹', '利用升降设备将竖立在发射井内的导弹连同发射台一起提到井口的过程。是采用井口发射方式的导弹发射准备的一项重要工作。', 83);
INSERT INTO `t_military_term_data` VALUES ('3943b45c-076a-4f05-9328-8e1b425d91c4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '混凝土破坏弹', '以弹丸的强度撞击目标或侵入一定深度爆炸,破坏混凝土和砖石结构的坚固工事与建筑物的炮弹。配用于大口径火炮。', 311);
INSERT INTO `t_military_term_data` VALUES ('394756be-1540-436f-9214-17f0226f5c79', '916997ee-6728-4c61-9b79-d96960b1dc86', '燃烧武器防护', '为避免或减轻敌燃烧武器袭击的毁伤效应而进行的防护。主要包括：查明敌人可能使用燃烧武器的种类、数量和企图,预报可能遭敌燃烧武器袭击的地域、规模及火势蔓延的方向,制定防火措施；遭敌燃烧武器袭击后,迅速查明火情区域情况,及时扑灭火源,组织抢救、抢修等。', 71);
INSERT INTO `t_military_term_data` VALUES ('394a5b0d-48dd-474a-8ff9-123b5db5b33f', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役间隙', '两个战役之间或一个战役的实施过程中两个阶段之间的时间。可用以调整控制战役节奏,进行战役休整,以保证尔后行动的顺利实施。', 38);
INSERT INTO `t_military_term_data` VALUES ('394aab0d-7326-4e50-a776-275461c125c6', '97a19170-bfac-42c5-9906-1acb187f0654', '空军指挥自动化系统', '保障空军各级指挥机构对部队和武器系统实施指挥与控制的指挥自动化系统。是军队指挥自动化系统的组成部分。分为空军、军区空军、军、基地、师、团等指挥自动化系统。', 178);
INSERT INTO `t_military_term_data` VALUES ('394b09bf-c565-4a5b-9f78-529484f2e6d0', '878651de-adf5-4c72-9376-9c363b893ff8', '战争理论', '关于战争问题的系统化理性认识和知识体系。科学的战争理论是战争规律的正确反映和战争实践的指南。', 34);
INSERT INTO `t_military_term_data` VALUES ('39656a01-8478-4b96-af37-4a04e97902b5', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机生存力', '直升机具有的不易被敌方发现、击毁和被击伤后仍可安全着陆的能力。主要取决于直升机的隐蔽性、机动能力、抗弹伤能力、抗坠毁能力等。', 15);
INSERT INTO `t_military_term_data` VALUES ('396878b8-bb80-42dc-8043-84945711238b', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '民兵侦察', '根据军事需要由民兵进行的侦察。通常由人民武装部门或民兵指挥员组织。主要组织形式有民兵侦察分队、民兵观察所、民兵观察哨、渔业民兵侦察船（轮）和民兵情报网等。', 16);
INSERT INTO `t_military_term_data` VALUES ('397116e8-e452-4562-8181-8bf902666a68', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇火控雷达', '用以跟踪空中和海面目标,为舰艇武器系统提供目标精确数据,保证武器的控制和射击的舰艇雷达。包括舰艇炮瞄雷达、导弹制导雷达、鱼雷攻击雷达和综合火控雷达等。', 229);
INSERT INTO `t_military_term_data` VALUES ('397eb29f-997f-4b38-8288-2c93dde56b10', 'f0140091-c11a-48c9-8836-8aa94439dac0', '直射火力', '弹道高不超过目标高度的火力。', 90);
INSERT INTO `t_military_term_data` VALUES ('3987ad17-d646-412c-b347-f8f2b1fb3d50', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '改编', '军队或军队某一建制单位原来的性质、任务或编制所作的改变。如对起义部队进行改编,将步兵师改编为坦克师等。', 76);
INSERT INTO `t_military_term_data` VALUES ('398e7d2e-5eb4-4b73-8e98-cdbd822d29ef', '98df76fb-4b65-48ff-a56c-4db587327c79', '救生食品', '专供飞行和舰艇人员等在待救时维持生存的专用食品。具有体积小、重量轻、能量高、食用方便等特点。', 145);
INSERT INTO `t_military_term_data` VALUES ('3991b4c4-322f-42ac-9e9d-cce300d04dab', '06a75831-13a1-4660-870a-455bb445336a', '野战通信枢纽', '将通信设备安装在野战工事内或车辆、飞机、舰船等运载工具上的通信枢纽。开设迅速,机动性强。', 74);
INSERT INTO `t_military_term_data` VALUES ('39922c0e-3585-4cd8-94fa-e03dc4c6110f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反击', '①防御的军队对进攻之敌实施的主动攻击。目的是击破当面敌人的进攻。是积极防御的一种手段。②防御战斗中,对攻占己方阵地暂取守势之敌的攻击。', 402);
INSERT INTO `t_military_term_data` VALUES ('3992cf96-0fce-4764-b474-582d0b6759f8', '98df76fb-4b65-48ff-a56c-4db587327c79', '战备储备', '为保障战备需要而进行的物资储备。分为战略储备、战役储备和战术储备。主要用于战争初期衔接后续补给和应付突发事件的需要,平时不得随意动用。', 110);
INSERT INTO `t_military_term_data` VALUES ('399d2501-9848-47eb-9b2f-caf74751179e', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹气密性检查', '对导弹或地面设备有关部分的密闭情况进行的充气检查。使用的气体一般为高压氮气。', 91);
INSERT INTO `t_military_term_data` VALUES ('39a410d1-d478-4b4f-bd76-5d185cdc5e81', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克技术保养', '为保持坦克经常处于规定的技术状态而进行的预防性维护活动。通常分为出车前准备,行军间隙检查,一、二、三级保养以及车场日、换季与普查工作等。', 197);
INSERT INTO `t_military_term_data` VALUES ('39a413fb-04c3-4c10-b64e-65060b022c79', '06a75831-13a1-4660-870a-455bb445336a', '传真机', '利用光电变换和扫描技术把书面信息转换成电信号,并以记录形式复制出原信息的用户设备。有文件传真机、气象图传真机、像片传真机和报纸传真机等。由发送机和接收机两部分组成。用以传送军用文书、报文、像片和图表等。', 197);
INSERT INTO `t_military_term_data` VALUES ('39a58d84-70af-4ceb-a092-e7131d725ed7', '916997ee-6728-4c61-9b79-d96960b1dc86', 'γ射线报警器', '监测γ辐射水平的核辐射剂量探测仪器。通常安装在具有防化设施的工事内,在预定的γ辐射阈值下报警并能测量工事外探头附近的γ照射量率。', 156);
INSERT INTO `t_military_term_data` VALUES ('39b93197-269e-4246-aa32-c9d18d2ca289', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '端末调理员', '军事演习中,充任演习部队或分队的下级或友邻,负责向其上级和导演报告情况、诱导演习的调理员。', 131);
INSERT INTO `t_military_term_data` VALUES ('39bc3026-cca0-4e32-8b68-8d6c0772f607', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '战场宣传鼓动', '中国人民解放军在作战中为鼓舞士气、坚定胜利信心而进行的短小精悍、形式多样的思想宣传活动。', 35);
INSERT INTO `t_military_term_data` VALUES ('39d4d7db-c58f-4b8b-9bdc-f0f237b2bd70', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '港口', '位于江、河、湖、海岸边,建有码头等设施,供船舶出入和停泊、人员上下、货物装卸等的地域。按地理位置,分为河港和海港；按用途,分为商港、渔港、军港、避风港等。', 103);
INSERT INTO `t_military_term_data` VALUES ('39ebe3e9-34c2-46a0-9245-9ce413223462', '97a19170-bfac-42c5-9906-1acb187f0654', '空中编队', '①两架以上飞机或直升机,在空中按规定的间隔、距离和高度差组成的编队。最基本的编队是双机或三机编队。②两架以上飞机在空中进行编队的行动。通常是同型机进行编队,必要时不同的机种、机型也可混合进行编队。', 47);
INSERT INTO `t_military_term_data` VALUES ('39ecd945-f63d-4e7e-b63c-704a301e3849', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹壳破裂', '射击武器击发后弹壳体部破裂的射击故障。', 146);
INSERT INTO `t_military_term_data` VALUES ('39f01011-22bd-442d-ac18-0e1c7b335348', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '空间碎片', '在太空运行的废弃的人造天体。主要包括：已经停止工作的航天器和末级运载火箭,航天器抛弃的整流罩及保护盖,航天器与陨星碰撞所产生的碎片,人造天体爆炸的碎片,航天员扔掉的垃圾等。空间碎片与正常使用的航天器可能会发生碰撞,对航天器构成一定的威胁。', 201);
INSERT INTO `t_military_term_data` VALUES ('39f1e95f-4814-4640-8573-ba7b772b54d5', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克支援步兵', '坦克在步兵战斗队形之后以火力支援步兵战斗的一种步坦协同形式。通常在地形不利于坦克通行,敌反坦克火器和防坦克障碍较多的情况下采用。', 24);
INSERT INTO `t_military_term_data` VALUES ('39f7a967-14ac-4af5-be2e-7b7bb21ae4ce', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮曳光穿甲爆破弹', '弹丸在侵彻目标装甲防护层后爆炸的曳光高射炮弹。主要用以射击空中和地面有装甲防护的目标。', 217);
INSERT INTO `t_military_term_data` VALUES ('3a0b8f4d-2e01-45c2-804d-117cd31d6043', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电磁遮断', '在一定时间内对某一地区的敌方电子设备实施大规模压制性电子干扰,以切断敌与外界的无线电通信联络的行动。', 86);
INSERT INTO `t_military_term_data` VALUES ('3a0ffb07-88d4-4b46-949d-fad24a855802', '878651de-adf5-4c72-9376-9c363b893ff8', '战争类型', '按性质或某一特征对战争所作的基本分类。按性质,分为正义战争和非正义战争；按规模,分为世界大战和局部战争；按是否使用核武器,分为核战争和常规战争等。', 5);
INSERT INTO `t_military_term_data` VALUES ('3a1fe313-213f-467d-b307-d45905ba68ef', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '火力突击', '以火力对敌实施的集中、急速、猛烈的打击。包括进攻中的火力掩护、火力准备、火力支援、火力护送,防御中的火力反准备、火力反击等。通常由炮兵、航空兵、舰艇部队、导弹部队等实施。', 262);
INSERT INTO `t_military_term_data` VALUES ('3a20da38-7ad8-4a1e-a6ec-b25f309beee6', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '攻城阻援', '以主力攻城,以部分兵力阻敌援军。目的是歼灭守敌,夺取城市。', 233);
INSERT INTO `t_military_term_data` VALUES ('3a21a2d3-8f58-4beb-97ce-ca811b496235', '97a19170-bfac-42c5-9906-1acb187f0654', '降落伞', '利用空气阻力使人员或装备、物资从空中缓慢降落到地面的伞状或翼状器具。分为人用降落伞和物用降落伞。通常由引导伞、伞衣套、伞衣、伞绳、背带系统、开伞部件和提伞袋组成。', 341);
INSERT INTO `t_military_term_data` VALUES ('3a2b0b4e-a5b6-48f8-893c-1b4317fc84b4', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '义务兵役制', '亦称征兵制。国家关于公民在一定年龄段内必须履行一定期限兵役义务的制度。包括公民在军队中服现役和在军队外服预备役的制度。', 23);
INSERT INTO `t_military_term_data` VALUES ('3a3617ae-3174-4b68-96f3-06e067c176e9', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方指挥所', '为统一指挥后勤保障、装备技术保障和后方防卫而建立的指挥所。通常由部队副职首长或后勤指挥员负责,以后勤机关为主,司令部、政治部（处）。装备技术部（处）等机关和地方支前机构有关人员和必要的勤务保障力量组成,在后方地域开设。', 45);
INSERT INTO `t_military_term_data` VALUES ('3a3deb00-3bf4-4045-b98e-f9976cb52d33', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '机动力', '兵力或兵器所具有的进行空间位移的能力。', 274);
INSERT INTO `t_military_term_data` VALUES ('3a42cc86-62e0-4e10-849c-91b11b1952d2', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '无控段弹道', '亦称起飞弹道。反坦克导弹在起飞发动机推力作用下,从开始运动到导弹起控前的一段自由飞行弹道。', 267);
INSERT INTO `t_military_term_data` VALUES ('3a4920c0-27ad-437e-911d-8635b4e861f9', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边界勘察', '由边防主管部门或边防部队、武装警察边防部队组织实施的勘测、检查、巡视国界的活动。目的是及时掌握国界线及界标的情况。', 115);
INSERT INTO `t_military_term_data` VALUES ('3a4c775d-454c-43a3-8559-319c9915abbd', '878651de-adf5-4c72-9376-9c363b893ff8', '战略防空', '国家以及战略区、战略方向对来自空中和外层空间威胁的防范与斗争。', 113);
INSERT INTO `t_military_term_data` VALUES ('3a60930e-6922-450f-8671-c4850e16afe7', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '操纵地雷', '按照操纵者的指令进入战斗状态、转入安全状态或直接起爆的地雷。操纵方式有绳索操纵、有线电操纵和无线操纵3种。多布设在敌可能行进的路线或方向上。', 150);
INSERT INTO `t_military_term_data` VALUES ('3a82eee9-e110-48bb-944a-08fa913f031a', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工事抗力等级', '亦称工事防护等级。工事抵抗常规武器、核武器破坏的能力的等级区分。', 78);
INSERT INTO `t_military_term_data` VALUES ('3a8cc143-5b04-47dd-9d6a-8b7bb7fe6d1d', '916997ee-6728-4c61-9b79-d96960b1dc86', '致死剂量', '能使染毒人员90％以上死亡的毒剂量。用LD90-100或LCt90-100表示。', 131);
INSERT INTO `t_military_term_data` VALUES ('3a8f3fca-3d76-4ba5-80a4-f8ac154bc2ce', '97a19170-bfac-42c5-9906-1acb187f0654', '空军后勤保障', '空军为满足部队建设、作战和生活等需要而在后勤方面采取的各项保证性措施与进行的相应活动的统称。包括物资、经费、医疗卫生、交通运输、工程修建、机场和营产管理等方面的保障。', 399);
INSERT INTO `t_military_term_data` VALUES ('3a9fc0a9-0175-4d31-b92a-56d5c9097222', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '屯兵工事', '供屯集部队的各种掩蔽工事的统称。', 42);
INSERT INTO `t_military_term_data` VALUES ('3aa20099-70b8-4413-b18b-675bb27bccb7', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '等深线', '地形图和海图上将海洋或湖泊、河流等水域中水深相等的各点连成的曲线。用以显示水底地貌的起伏形态和水的深度。', 285);
INSERT INTO `t_military_term_data` VALUES ('3aa5dd7c-5ed4-44e2-8bdc-6b3b7f76e0ad', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '军用桥梁', '为保障军队通过江河、沟谷等障碍而架设的临时性桥梁。按使用器材,分为制式桥和就便桥；按承载能力,分为重型桥、轻型桥,驮载桥、徒步桥、铁路桥等；按有无中间桥脚,分为多跨桥和单跨桥；按作战运用,分为冲击桥、伴随桥和后方桥。', 270);
INSERT INTO `t_military_term_data` VALUES ('3aa69e5f-99da-495a-826e-ba7a313e2462', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '部队训练', '部队为掌握军事理论、军事技术和战术、战役法而进行的训练。分为军兵种部队和专业兵部队训练。', 60);
INSERT INTO `t_military_term_data` VALUES ('3aa9841b-3595-410c-8f3b-2e11a2998f8c', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒害剂量', '亦称毒剂剂量或中毒量。引起机体病理变化所需的毒剂量。表示染毒空气的毒害剂量单位是毫克·分／立方米或微克·分／立方米。表示毒剂液滴的毒害剂量单位是毫克／千克。常用的毒害剂量级有致死剂量、半数致死剂量、伤害剂量、半数伤害剂量、失能剂量、半数失能剂量等。', 130);
INSERT INTO `t_military_term_data` VALUES ('3aac6695-994c-4885-bd0f-f0ff61bf3978', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '开辟通路', '排除或克服障碍物以形成通路的行动。基本方法有：爆破,用机械或人工清除、填塞、铺垫等,也可用炮兵、航空兵和舰艇的火力开辟。', 199);
INSERT INTO `t_military_term_data` VALUES ('3ab3a4f5-8e49-49d4-89ee-ee013b4a654f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇日常升旗', '舰艇停泊时每日昼间升降军旗的制度。通常每日按规定时间在舰尾旗杆升旗,日没降旗。每周星期一举行列队升旗。', 398);
INSERT INTO `t_military_term_data` VALUES ('3ab63214-90ac-468d-aca4-3c54b1f95f80', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克支撑点', '防御时由坦克连阵地或坦克排阵地组成的支撑点。是坦克连用防御阵地的基本形式。坦克连支撑点由各坦克排支撑点和配属分队的阵地组成；坦克排支撑点由各辆坦克和加强火器的发射阵地组成。', 36);
INSERT INTO `t_military_term_data` VALUES ('3aba9025-9f23-4fd5-8305-805b944e1166', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '高浓铀', '铀同位素混合物经过同位素分离后,其中铀-235的丰度达90％以上的铀。是核武器的重要装料。', 120);
INSERT INTO `t_military_term_data` VALUES ('3ac4cb8d-569d-4083-a07b-60e7d1e7ecbd', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机技术训练', '为掌握直升机的基本理论知识和操纵、维修、管理技能而进行的训练。主要包括驾驶技术训练、维修技术训练和其他专业技术训练等。', 53);
INSERT INTO `t_military_term_data` VALUES ('3ac9dd15-7697-41b7-8275-44608c51027f', '06a75831-13a1-4660-870a-455bb445336a', '传输媒介', '信息传输时经由的空间或实体。有线电通信的传输媒介有被覆线、架空明线和电缆等；无线电通信的传输媒介有大气、外层空间、水和岩土等；光通信的传输媒介有光纤、大气、水和外层空间等。', 92);
INSERT INTO `t_military_term_data` VALUES ('3acc6ae4-9a1a-48cd-a5fe-5819a5316371', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '战役工程保障', '对战役行动实施的工程保障。由战役指挥机关组织实施。主要任务是：组织实施战役工程侦察或勘察,构筑与维护战役防护工程和后方基地工程,构筑与维护战役作战地区的道路、桥梁、渡场,修建野战机场和直升机起降场,抢修、抢建铁路、码头,在障碍区开辟战役通道,实施战役工程伪装,侦察战区水源和构筑、维护给水站等。', 11);
INSERT INTO `t_military_term_data` VALUES ('3adffc49-2404-4e5c-9aac-8baac5ee6a5f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炸点偏差', '射弹炸点距目标（试射点、观察基准）的方向、距离（高低）偏羌量的统称。', 228);
INSERT INTO `t_military_term_data` VALUES ('3ae31ea6-1e82-4384-b65e-b3fd0ebf0feb', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教学法', '向受训对象传授理论知识和技能的方法。', 141);
INSERT INTO `t_military_term_data` VALUES ('3aec104a-3803-48b6-b4fa-c1c8508cb205', '916997ee-6728-4c61-9b79-d96960b1dc86', '核威胁', '敌可能在战争中使用核武器而构成的威胁。构成核威胁的主要条件是：敌拥有核武器的数量和质量,使用核武器的能力、可能性和准备状况。', 19);
INSERT INTO `t_military_term_data` VALUES ('3aed067b-d93c-4289-8fe5-de5740fbfe70', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '土工作业', '土石方工程作业的简称。在土质或石质地段进行的挖掘、填充和运送土石的作业。', 87);
INSERT INTO `t_military_term_data` VALUES ('3aed26fa-8f4c-4364-9e07-4ce7479081ca', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹弹头检测', '对导弹弹头各部分的外观、几何尺寸及技术性能、装配精度等进行的检查测试和调整装定。', 96);
INSERT INTO `t_military_term_data` VALUES ('3aee7308-9ea8-467d-a361-9c95ef8233ef', 'f0140091-c11a-48c9-8836-8aa94439dac0', '强击群', '在强击支队编成内或单独遂行强攻任务的战斗编组。兵力通常为1个加强连,由突击队、火力队、爆破队等编成。', 170);
INSERT INTO `t_military_term_data` VALUES ('3b0229af-9a8e-485f-9ea4-8a5c2311ded3', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮射弹散布误差', '由于射弹散布产生的火炮射弹对散布中心的偏差。', 262);
INSERT INTO `t_military_term_data` VALUES ('3b06be3e-1fb8-4b1e-b192-63aa07cbd9cd', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练准备', '为实施军事训练而预先进行的各种准备活动。包括思想、组织、计划、场地、器材、教材、教具等方面的准备。', 33);
INSERT INTO `t_military_term_data` VALUES ('3b0799e4-f89a-4854-a2a8-5e4e58d78f34', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海水淡化', '亦称海水脱盐。将海水进行脱盐处理变为生活用水的过程。脱盐方法有蒸馏法、电渗析法、离子交换法、反渗透法等。', 355);
INSERT INTO `t_military_term_data` VALUES ('3b25e79e-afa8-43e0-8c2d-9d4e1a8f30be', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '征集', '国家按照兵役法的规定和军队的需要,通过严格的工作程序,将履行兵役义务并符合服现役条件的应征公民征集到军队服现役的工作。', 53);
INSERT INTO `t_military_term_data` VALUES ('3b391f74-2500-4a93-b833-4c0d4cb51952', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察计划', '为组织实施侦察而制定的计划。主要内容包括：侦察任务的区分,侦察力量和手段的使用,报告情况的方法,侦察协同,保障措施,完成侦察任务的时限等。', 99);
INSERT INTO `t_military_term_data` VALUES ('3b3cb559-51ca-4f71-a5b0-1a0ed09d89f7', '97a19170-bfac-42c5-9906-1acb187f0654', '空中等待', '飞机或直升机为等待着陆而在指定空域进行的机动飞行。', 240);
INSERT INTO `t_military_term_data` VALUES ('3b498bd1-3c4f-483b-bcb4-cf3a6305db28', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '迫榴炮', '兼有迫击炮和榴弹炮两种火炮战斗性能的火炮。有自行式迫榴炮和牵引式迫榴炮。', 25);
INSERT INTO `t_military_term_data` VALUES ('3b5c0a60-5f1a-4756-bd2f-455baa520d04', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上炸雷', '使用快速小型水面舰艇或直升机投放深水炸弹炸毁水雷的战斗行动。通常用以紧急开辟航道。排除不便进行扫雷的水雷障碍或降低温布水雷障碍的密度等。', 114);
INSERT INTO `t_military_term_data` VALUES ('3b60948d-083d-40dd-966d-76f25c9eba06', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '收缩', '根据作战需要缩小兵力兵器的原部署范围的行动。', 350);
INSERT INTO `t_military_term_data` VALUES ('3b671085-9a6b-48e2-a21f-fdbd15b772cd', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '珊瑚礁', '在热带、亚热带浅海区,由造礁珊瑚骨架和生物碎屑组成的海底隆起。按形态及其与岸线关系,分为岸礁、堡礁和环礁。岸礁是紧靠大陆或岛屿所形成的珊瑚礁；堡礁是长条形的,与陆地以泻湖或浅海相隔的珊瑚礁；环礁是包围泻湖的环状或马蹄状珊瑚礁。', 45);
INSERT INTO `t_military_term_data` VALUES ('3b6810a0-c045-4f71-901b-e5d9d8774995', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '障碍物密度', '战役、战术地幅内障碍物的疏密程度。通常用障碍物的总长度与防御正面宽度的比值表示。分为爆炸性障碍物密度和非爆炸性障碍物密度,防坦克障碍物密度和防步兵障碍物密度。', 95);
INSERT INTO `t_military_term_data` VALUES ('3b899920-99b6-4cf6-9d6d-f214ab860137', '97a19170-bfac-42c5-9906-1acb187f0654', '空降阶段', '空降作战中部队从乘载航空器开始至完成空降着陆止的阶段。主要包括：空降部队乘载航空器,航空兵部队实施空中输送,空降部队进行伞降着陆或机降着陆等。', 157);
INSERT INTO `t_military_term_data` VALUES ('3b929c87-5224-45e0-bef3-4c116d37457f', '916997ee-6728-4c61-9b79-d96960b1dc86', '受染区', '染有放射性物质或毒剂、生物战剂的区域。包括沾染区、染毒区和污染区。', 147);
INSERT INTO `t_military_term_data` VALUES ('3b9342e4-c397-4b72-9624-7ba58d542275', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上攻击', '舰艇在海上主动对敌实施的进攻行动、按攻击兵力分为单舰（艇）攻击、编队攻击和合同攻击按使用武器分为导弹攻击、鱼雷攻击、舰炮攻击和深水炸弹攻击；按攻击目标,分为对水面舰艇攻击、对潜艇攻击和对岸上目标攻击。通常包括接敌展凡攻击和撤离1个阶段。', 79);
INSERT INTO `t_military_term_data` VALUES ('3bab5526-53eb-4be8-8a12-e9e8fe05d975', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '加农炮', '身管长、初速大、弹道低伸的火炮。通常身管长为口径的40倍以上,初速大于700米／秒,射角在45度以下。主要用以射击垂直目标、装甲目标和远距离目标。', 22);
INSERT INTO `t_military_term_data` VALUES ('3bb5ec43-fabb-4a64-8731-6491f68876ba', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军国主义', '主张把国家完全置于军事控制之下,对内实行军事独裁统治、对外实行军事扩张的思想体系、社会制度及其政策。如第二次世界大战时期的德国和日本,都是实行军国主义的国家。', 85);
INSERT INTO `t_military_term_data` VALUES ('3bc28c21-9308-4e4e-9a1f-3a6574185e15', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '政审', '政治审查的简称。军队有关部门依据规定的程序和内容,对有关人员的政治情况进行的审查。', 107);
INSERT INTO `t_military_term_data` VALUES ('3bce1ede-d261-4c2e-8120-8e4ae47da6b8', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核试验测试技术', '核试验中对核爆炸过程、爆炸结果和毁伤效应等进行全面观测和定量测量的技术。包括核物理诊断、放射化学诊断和效应参数测试等技术。', 190);
INSERT INTO `t_military_term_data` VALUES ('3bd1130a-96b6-4946-8cba-327fb1cb16c6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇航程', '舰艇由起航点至到达点的航行距离。海上航程以海里为计量单位。', 270);
INSERT INTO `t_military_term_data` VALUES ('3bd68659-10c2-42cf-b5c7-7154242c5b6e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '补充想定', '围绕总的训练课题对某一具体训练问题提供情况和条件的想定。是基本想定的补充和继续。', 110);
INSERT INTO `t_military_term_data` VALUES ('3bdaf1b7-d40d-48b9-a36f-029cf25119ae', '916997ee-6728-4c61-9b79-d96960b1dc86', '发烟剂', '用以构成烟幕的化学物质。分为固体发烟剂和液体发烟剂。', 238);
INSERT INTO `t_military_term_data` VALUES ('3bed8db8-61be-4c21-a6ec-d17921371ec9', '8a761efd-50a6-4ac8-9913-b7d745104f82', '信号弹', '装有发光剂或发烟剂发射后在空中能产生强光或有色烟雾的弹药。分为发光信号弹和发烟信号弹。发光信号弹无壳枪弹可发出红、绿、白、黄等颜色的光亮供夜间使用；发烟信号弹可发出蓝红、黄等颜色的烟雾,供昼间使用。通常使用信号枪发射、新式信号弹采用火箭发射方式,包装筒即发射器,一次性使用无需用枪发射。', 207);
INSERT INTO `t_military_term_data` VALUES ('3bee4df7-1c01-45cd-827c-60d73689bb3f', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '航空工业', '研制、生产和维修航空器及其配套设备的工业。主要产品有军用民用飞机、滑翔机、地面效应飞行器、飞艇、气球、飞机发动机、机载武器、机载设备、地面设备等。', 42);
INSERT INTO `t_military_term_data` VALUES ('3bf3261e-6c61-4fb6-883d-6954ebd07d8b', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '联合演习', '两个以上军种或两支以上军队联合进行的军事演习。', 126);
INSERT INTO `t_military_term_data` VALUES ('3bf36720-5578-41b9-b029-e786f6c77d29', '8a761efd-50a6-4ac8-9913-b7d745104f82', '大口径机枪', '口径12毫米以上的机枪。主要用以毁伤2000米以内的地面轻型装甲目标和压制火力点,以及对付空中目标。射击距离远,火力强度大,但火力持续性能较差。可携行、牵引或安装在车辆、舰艇、直升机等载体上。', 171);
INSERT INTO `t_military_term_data` VALUES ('3bf4fe6c-a2bd-4dac-8f8d-e075e8bdd3b6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇作战半径', '舰艇按规定装足燃料、弹药、食品、淡水及其他消耗品,从基地出发,中途不补给,进行作战活动时所能达到的最大平均直线距离。是舰艇战术技术性能要素之一。主要取决于舰艇续航力的大小。常规动力水面舰船的作战半径为续航力值的1／3,潜艇的作战半径为通气管航速续航力值的30％。', 327);
INSERT INTO `t_military_term_data` VALUES ('3bf5a506-9e71-4aed-848a-a43e960791a7', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '共同条令', '军队各级组织和全体人员都必须执行的条令。中国人民解放军的共同条令包括《内务条令》、《纪律条令》、《队列条令》等。', 2);
INSERT INTO `t_military_term_data` VALUES ('3bfcf011-f143-4396-a2be-b94792311d64', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡河', '军队通过江河障碍的行动。分为桥梁渡河、冰上渡河、徒涉渡河、漕渡和潜渡等。', 297);
INSERT INTO `t_military_term_data` VALUES ('3bfd21a9-6b9b-4458-8332-e0327655b6a9', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克火力机动性', '坦克武器所具有的发现、捕捉、跟踪和瞄准目标并及时实施射击的性能。主要取决于火控系统精度和反应时间,炮塔回转速度,瞄准速度等。', 155);
INSERT INTO `t_military_term_data` VALUES ('3c178cf0-6eaf-46ab-b73d-a5938b9f7ab3', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '近海', '靠近陆地的海区。中华人民共和国的近海包括渤海、黄海、东海、南海和台湾岛以东的部分海域。', 377);
INSERT INTO `t_military_term_data` VALUES ('3c1a8ef9-a092-4d76-85a3-40d42c3db296', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '森林', '以乔木为主的大面积树林。军事上可作为防卫的天然屏障,能隐蔽重要军事设施,掩护军队和武器装备的集结与机动,减弱核、化学、生物武器的杀伤力,但对军队的机动和技术兵器的使用限制很大,观察和判定方位困难,容易滞留毒剂和引起火灾等。', 89);
INSERT INTO `t_military_term_data` VALUES ('3c1cf0c8-a31b-4049-9c8d-3d2f8fdf2dc7', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '军事运筹分析', '根据运筹学的原理和方法,建立有关军事决策问题的数学模型,并利用电子计算机技术进行定量分析和决策优化的研究活动。如作战运筹分析、后勤保障运筹分析、武器发展运筹分析等。', 164);
INSERT INTO `t_military_term_data` VALUES ('3c27803a-7fd3-473a-b83f-fdbbfc1bf8d9', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '反坦克弹雷', '发射后能直接攻击坦克顶甲,弹药落地后又能转换成为反车底雷的反坦克武器。分为寻的型反坦克弹雷和普通型反坦克弹雷。用火炮、飞机、直升机、火箭布雷车等发射,以对付装甲集团目标。通常在一发炮弹或火箭弹里装填若干枚反坦克弹雷,构成子母弹。', 143);
INSERT INTO `t_military_term_data` VALUES ('3c367901-c72d-4ae4-aebb-dc374592609a', '97a19170-bfac-42c5-9906-1acb187f0654', '强行起飞', '飞机在非正常的起飞条件下的强制性起飞。通常在机场遭敌空中封锁的情况下进行。', 205);
INSERT INTO `t_military_term_data` VALUES ('3c3dd04e-1acf-4ea7-a869-bba7d2ac2c8c', 'f0140091-c11a-48c9-8836-8aa94439dac0', '游动火力', '以少量火炮、坦克、导弹等不断地变换发射阵地所构成的火力。主要用以隐蔽己方炮兵、坦克、导弹的基本部署,杀伤和迷惑敌人。', 93);
INSERT INTO `t_military_term_data` VALUES ('3c4507ec-3063-4b10-a03a-1c15f8e7eb8f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '定下决心', '指挥员对作战目的及行动作出基本决定的思维活动和工作过程、通常包括了解任务,断情况听取决心建议、作出决断,形成决心', 78);
INSERT INTO `t_military_term_data` VALUES ('3c62072b-ff42-4510-af9c-1e16ff6e03c0', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '制空权', '作战中,在一定时间内对一定空域的控制权。', 354);
INSERT INTO `t_military_term_data` VALUES ('3c69465c-153f-4db5-b872-33c89a485592', '4d839792-0c29-4fae-bafd-63350606b2a7', '1', '1', 0);
INSERT INTO `t_military_term_data` VALUES ('3c6982d4-b84e-46f9-9271-d700c63a7703', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '野外场地引导', '对在野外场地降落的直升机进行的指引。', 105);
INSERT INTO `t_military_term_data` VALUES ('3c8fad51-ab7a-4257-8186-184cc8c0f803', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '政治纪律', '中国人民解放军军人在政治生活中必须遵循的行为准则。主要内容包括：坚决贯彻党的基本路线,执行党的方针和政策,坚持党对军队的绝对领导,在政治上同党中央、中央军委保持一致等。', 27);
INSERT INTO `t_military_term_data` VALUES ('3c9233e4-4af8-43ee-b7f0-6fcb84c01bc7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '诱敌深入', '有计划地将进攻之敌诱至己方一定纵深的预定区域,以便包围歼灭。', 230);
INSERT INTO `t_military_term_data` VALUES ('3c9486b6-fe89-4a2d-929c-ab4c36ab8f50', 'd7132c58-5df3-4b97-919f-58740148b9ca', '对空多层火网', '防空兵器在被掩护目标或被掩护地域上空构成的多层次网状密集火力。在高度上通常要求高、中、低空相结合,在距离上通常要求远、中、近程相结合。', 157);
INSERT INTO `t_military_term_data` VALUES ('3ca2e0a1-6b8f-4bbc-ac49-42144d8509e0', '06a75831-13a1-4660-870a-455bb445336a', '光纤通信', '利用光导纤维作为传输媒介的激光通信。可传输电话、电报、数据和图像等。通信容量大、距离远、质量高,抗电磁干扰，保密性强。可用于大容量国防干线通信和野战通信等。', 128);
INSERT INTO `t_military_term_data` VALUES ('3caeb02d-7198-47bc-9cc2-28792fb8b313', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹自动驾驶仪', '安装在导弹上用以稳定导弹的飞行姿态并按控制指令控制导弹飞行的装置。', 61);
INSERT INTO `t_military_term_data` VALUES ('3cb010ad-c858-4387-979d-63331c1785a8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵齐射', '在指挥员的统一口令下,各炮同时射击的发射方法。对火箭炮还要求将装填的火箭弹一次发射完毕。', 226);
INSERT INTO `t_military_term_data` VALUES ('3cbbd925-122b-41b6-b16c-d1882f2f20f5', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹总检查', '通过模拟导弹发射、飞行和关机程序对导弹各系统工作情况、协调性能及关机线路进行的综合测试。包括技术阵地总检查和发射阵地总检查。', 98);
INSERT INTO `t_military_term_data` VALUES ('3cbca045-6684-44ac-9450-2c81b706f736', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹技术分队', '导弹部队中担负导弹技术准备的分队。通常编有转运、对接、控制、发动机等专业技术人员。主要任务是向导弹发射分队提供技术性能符合发射要求的导弹。', 4);
INSERT INTO `t_military_term_data` VALUES ('3cc42081-2628-44b7-9f10-00278d20a029', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '证件管理', '军队有关部门和人员对各种证件的管理。主要包括证件的制发、请领、登记、保管、使用、收缴、注销和销毁等工作。', 21);
INSERT INTO `t_military_term_data` VALUES ('3ccafc28-b964-43e5-9869-193cf1246dc5', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '核心工事', '位置适中并对整个防御的稳定起关键作用的骨干工事。', 56);
INSERT INTO `t_military_term_data` VALUES ('3ccd053e-434e-450f-a0ca-475cad6952d0', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '地道', '在平坦地面下构筑的暗挖式工事。', 53);
INSERT INTO `t_military_term_data` VALUES ('3cce04a2-3429-41c9-949c-c2fb3b0d0363', 'f0140091-c11a-48c9-8836-8aa94439dac0', '斜切阵地', '各防御阵地或防御地带之间斜方向的阵地。用以割裂敌人的战斗队形,阻止其向两翼扩张,并作为反冲击、反突击等攻势行动的依托。', 223);
INSERT INTO `t_military_term_data` VALUES ('3cdb4773-4bf2-4902-aaf8-7951914195ea', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '应急机动作战', '为应付各种紧急或意外情况而进行的作战。应急机动作战任务通常由专门指定的部队担负。', 190);
INSERT INTO `t_military_term_data` VALUES ('3ce87a09-9a9a-4153-9184-0d884c297854', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '内务条令', '现定军人基本职责、军队内部关系和日常生活制度的条令。是军队实施行政管理的主要依据。', 3);
INSERT INTO `t_military_term_data` VALUES ('3cf1d6e0-25d7-4524-bd27-e3bb70a6ce1e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '中国人民解放军', '中国共产党缔造和领导的,用马克思列宁主义、毛泽东思想、邓小平理论武装起来的人民军队。是中华人民共和国的武装力量,人民民主专政的坚强柱石。中国人民解放军的唯一宗旨是紧紧地和人民站在一起,全心全意地为人民服务。在社会主义现代化建设时期,担负着巩固国防,抵抗侵略,保卫祖国,保卫人民的和平劳动,参加国家建设事业的任务。', 0);
INSERT INTO `t_military_term_data` VALUES ('3cf8849d-87a6-44d4-8d37-daf8d632f2b9', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '大地天文测量', '利用仪器观测恒星测定地面点的天文经度、天文纬度和该点至相邻一点天文方位角的技术。主要用以推算天文大地垂线偏差,进行地球椭球定位和研究地球形状、大小,控制三角测量和导线测量的横向误差积累,为导弹定向等。', 183);
INSERT INTO `t_military_term_data` VALUES ('3cfc7387-cfcf-4459-bed7-f34550bb80bd', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核武器战术技术性能', '核武器在服役和作战使用中所具有的特性与功能。主要包括：威力、射程、爆高可调范围,突防能力,安全性能,机动性,可靠性,战备反应时间,寿命和维修性等。', 132);
INSERT INTO `t_military_term_data` VALUES ('3d03659a-5292-451b-aac1-c3b28acc1422', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射命令', '导弹部队指挥员根据上级命令向所属发射部队或分队下达发射导弹的命令。主要内容包括：执行发射任务的部队或分队,任务区分,发射时间,核反（突）击效果侦察要求,发射后的行动及有关注意事项等。', 13);
INSERT INTO `t_military_term_data` VALUES ('3d0d03ea-eeed-4b08-bb86-098ea88a5b87', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察保障', '为获取作战所需情报而采取的各项保证性措施与进行的相应活动的统称。分为战略侦察保障、战役侦察保障、战术侦察保障。', 106);
INSERT INTO `t_military_term_data` VALUES ('3d1a5e51-46e5-4de0-8959-5c979e5a422d', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '复合干扰', '对敌方某一电子设备同时使用多种干扰手段形成的电子干扰。可增强干扰效果。', 60);
INSERT INTO `t_military_term_data` VALUES ('3d36ddae-560d-436b-a6d4-05a0003c89af', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵与航空兵合练', '防空兵与航空兵联合实施的训练。分为炮空合练和弹空合练。通常由航空兵模拟敌机的各种战术行动和动作,高炮部队与地空导弹部队演练抗击敌机袭击时的各种战斗行动。', 132);
INSERT INTO `t_military_term_data` VALUES ('3d6e55b9-f8d2-4f63-9c8e-570fee768832', '97a19170-bfac-42c5-9906-1acb187f0654', '机载反雷达导弹', '亦称机载反辐射导弹。从飞行的飞机或直升机上发射,利用敌方雷达的电磁辐射进行制导,专门用以攻击敌方雷达的导弹。', 313);
INSERT INTO `t_military_term_data` VALUES ('3d754319-da60-478d-acd4-a82e67d8e3cc', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '山脉', '沿一定方向有规律分布的若干相邻山岭的统称。包括主脉和支脉。构成山脉主体的山岭为主脉,由主脉延伸出去的为支脉。', 21);
INSERT INTO `t_military_term_data` VALUES ('3d8c8cf3-00df-4132-a08b-5d3cd57aefca', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '捕俘', '捕捉俘虏的简称。为了解敌方情况而捕捉敌军人员的侦察活动。分为伏击捕俘和袭击捕俘。', 46);
INSERT INTO `t_military_term_data` VALUES ('3da6873e-7e39-4b38-b5c3-3d3726e05373', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队党委', '军队中党的委员会的简称。中国共产党在中国人民解放军团或相当于团级以上的部队和单位设立的委员会、由同级党代表大会选举产生,并经上级党委批准。', 18);
INSERT INTO `t_military_term_data` VALUES ('3da9a31f-bcf0-4595-9477-8926cf59c73c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克特种装置', '为保障坦克在野战条件下遂行特殊任务而配备的制式专用辅助装置。包括潜渡装置、浮渡设备、扫雷装置、推土装置、导航装置和空气调节设备等。', 145);
INSERT INTO `t_military_term_data` VALUES ('3df77971-ac75-457e-a8f6-0dcd6443beef', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队律师', '具有国家律师资格,享有国家律师权利并承担相应义务,在军队法律顾问处从事军队法律服务的专业人员。', 140);
INSERT INTO `t_military_term_data` VALUES ('3df8a673-e64c-4111-9a3e-893dd7cef701', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反潜', '搜索和攻击敌潜艇的战斗行动。有水面舰艇反潜、攻击潜艇反潜、海军航空兵反潜和舰机协同反潜等。', 92);
INSERT INTO `t_military_term_data` VALUES ('3e11112a-0dff-4b7f-98a2-3148f55ac399', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '安全制度', '军队中关于安全、防事故工作的制度。主要包括进行安全教育、建立安全组织、实行安全工作责任制和预防各种事故等方面的规定。', 14);
INSERT INTO `t_military_term_data` VALUES ('3e12d500-059c-4390-af2a-80a4880c5cd0', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '减员', '军队或军队某一组织因各种情况造成的人员减少。包括战斗减员和非战斗减员。', 88);
INSERT INTO `t_military_term_data` VALUES ('3e16cca7-1f38-4d2f-8044-92bb45517c27', 'f0140091-c11a-48c9-8836-8aa94439dac0', '桥头阵地', '亦称桥头堡。设置在桥头、渡口或其附近的阵地。根据情况可在己岸、对岸或两岸构设。', 231);
INSERT INTO `t_military_term_data` VALUES ('3e1817eb-e9b1-4118-a268-189b394e448a', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击准备', '高炮部队或分队为实施射击而做的各项准备工作的统称。通常包括：开设指挥所,准备和检查火炮、仪器、器材、弹药,组织对空侦察,确定禁射界,制定射击预案,计算和修正射击条件偏差等。', 141);
INSERT INTO `t_military_term_data` VALUES ('3e2a132c-ea43-4859-9b5f-803a11201574', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '师', '由若干个团编成的军队一级组织。通常隶属于集团军或军。设有领导机关,编有战斗和勤务保障部队与分队。为基本战术兵团。', 16);
INSERT INTO `t_military_term_data` VALUES ('3e2f3616-2068-41ae-b901-15149093aaa3', '8a761efd-50a6-4ac8-9913-b7d745104f82', '膛内弹道', '简称内弹道。射弹在火身内运动的轨迹。', 15);
INSERT INTO `t_military_term_data` VALUES ('3e2ff3f4-7e90-4e83-b062-65f9d7aec2f7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防御正面', '防御地区或防御部署朝向敌方的一面。分为战役防御正面和战术防御正面。其宽度通常由防御作战任务、地形条件、兵力兵器数质量等因素决定。', 281);
INSERT INTO `t_military_term_data` VALUES ('3e3d653b-fe99-4999-9965-4e472ac48d9c', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击周转时间', '高炮分队从对一批目标射击转移到对另一批目标射击所需的时间。主要包括：下达转移火力命令的时间,重新指示目标的时间,搜捕新目标的时间,捕住新目标后的操作时间,以及对新目标的射击时间。', 149);
INSERT INTO `t_military_term_data` VALUES ('3e4391d4-29a5-4bcd-b527-f3b7ee0c6648', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '脉冲压缩雷达', '发射宽脉冲编码信号,将回波信号压缩处理成为窄脉冲的雷达。探测距离较远,距离分辨力较强,并具有良好的抗干扰性能。广泛用于导航、测量、预警等方面。', 92);
INSERT INTO `t_military_term_data` VALUES ('3e5477d7-516a-4d22-a222-c82c4b350f74', 'd7132c58-5df3-4b97-919f-58740148b9ca', '对空观察哨网', '由配置在防区不同方向、不同距离的对空观察哨组成的对空观察网。是弥补雷达侦察不足,获取低空情报的重要手段。', 118);
INSERT INTO `t_military_term_data` VALUES ('3e67a3e5-d6c2-4d6b-b5de-b0cb61976e2d', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '上级', '军人之间或军队组织之间不论有无隶属关系,行政职务或级别高者。军人在相互不知道行政职务时、军衔高者亦为上级。', 125);
INSERT INTO `t_military_term_data` VALUES ('3e6bbd33-ba87-4365-855d-5a0fb8b915e6', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '徒步桥', '供一路纵队全副武装人员徒步通过的军用桥梁。分为徒步浮桥、徒步固定桥、徒步吊桥、藤索桥等。', 284);
INSERT INTO `t_military_term_data` VALUES ('3e7858df-ee91-4a1a-bf72-ec51b45b8127', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方勤务', '简称后勤。运用人力、物力和财力对军事建设和作战需要进行的各种保障工作的统称。分为战略后勤、战役后勤和战术后勤。主要包括后勤保障、后勤防卫、后勤指挥、后勤建设、后勤训练和后勤科研等。', 0);
INSERT INTO `t_military_term_data` VALUES ('3e7b5f86-0fcc-4fbd-b1e4-1e7fa97e225c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克跃进距离', '战斗中坦克两次短停间快速行进的距离。取决于乘员射击准备程度、地形状况、敌人火力威胁情况和观察条件,通常为50～150米。', 34);
INSERT INTO `t_military_term_data` VALUES ('3e9b1f2f-977b-4979-a73c-ea0f87a27917', '06a75831-13a1-4660-870a-455bb445336a', '单工通信', '通信双方轮流收信、发信的工作方式。一方发信时,另一方只能处于收信的工作状态。', 53);
INSERT INTO `t_military_term_data` VALUES ('3ea25e77-cbc2-4bf0-a34a-bced64288c7b', '8a761efd-50a6-4ac8-9913-b7d745104f82', '自动机卡滞', '射击武器在射击过程中自动机后坐不到最后（下）方或复进不到最前（上）方的射击故障。', 137);
INSERT INTO `t_military_term_data` VALUES ('3ea7c43c-8a7a-4aaf-a5ab-80214b5e4a12', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '地球站', '设置在地球表面或稠密大气层内与航天器保持无线电通信联络,或通过航天器及其他空间物体进行无线电中继的台站。分为通信地球站、测控地球站、数据注入地球站等。', 271);
INSERT INTO `t_military_term_data` VALUES ('3eac7d4e-1cd0-4eb4-8441-16a2d53f7e64', '916997ee-6728-4c61-9b79-d96960b1dc86', '群众性防护', '为使集体避免或减轻敌核、化学、生物武器袭击的伤害而进行的防护。如利用有防化设施的工事、装甲车辆和帐篷等进行的防护。', 56);
INSERT INTO `t_military_term_data` VALUES ('3eb2483f-5492-41c6-bd67-0e566b991f59', '98df76fb-4b65-48ff-a56c-4db587327c79', '基数标准', '一个基数物资的数量或重量标准。通常根据武器装备的战术技术性能、部队携运行能力和一般消耗规律规定。如规定7．62半自动步枪的一个弹药基数标准为200发,一辆解放CA10运输车一个油料基数标准为167千克。', 132);
INSERT INTO `t_military_term_data` VALUES ('3eb515df-8735-4d4a-9982-6ef436f7ee2f', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力掩护', '以火力保障部队或重要目标的安全。主要由炮兵、航空兵、舰艇部队和战役战术导弹部队担负。', 98);
INSERT INTO `t_military_term_data` VALUES ('3eb6b8a1-1a9c-48e8-9f65-ca3baf0a24d5', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '动能武器', '以每秒数千米以上高速运动的弹头的动能直接摧毁目标的武器。包括以化学推进剂为能源的动能拦截弹和以电磁力加速的电磁炮。主要用于反卫星、反导弹和防空、反坦克等。是尚在研究试验中的武器。', 49);
INSERT INTO `t_military_term_data` VALUES ('3eb7ee6f-ebb6-4fb3-bb15-7ba47b305b63', '98df76fb-4b65-48ff-a56c-4db587327c79', '实物供应', '后勤机构按标准以实物形式对受供单位和人员进行的物资供应。如武器装备、弹药、战备训练用油、军人制式被装等物资的供应。', 90);
INSERT INTO `t_military_term_data` VALUES ('3ebe1b3c-6e9c-42a6-b561-6f87426b8858', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行', '航空器、航天器以及导弹、火箭等在空中以一定的高度和速度进行的运动。航空器的飞行,按速度,分为亚音速飞行、超音速飞行；按高度,分为超低空飞行、低空飞行、中空飞行、高空飞行和超高空飞行。', 203);
INSERT INTO `t_military_term_data` VALUES ('3ebe42d6-2b04-4a2e-843e-dcd0f32fb1c5', '97a19170-bfac-42c5-9906-1acb187f0654', '超音速飞机', '最大飞行速度大于音速的飞机。', 266);
INSERT INTO `t_military_term_data` VALUES ('3ecb6368-94fb-47f4-82d0-f7277abf7878', '8a761efd-50a6-4ac8-9913-b7d745104f82', '横风修正量', '为克服横风对射弹的影响而修正的瞄准偏移量。轻武器修正时,以横向和风的修业量为基准,按强风加一倍,弱风、斜风各减半的方法实施。', 60);
INSERT INTO `t_military_term_data` VALUES ('3ee13acb-85d7-4e5a-a42a-f371aa09e031', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防设施', '用于国防目的的工程建筑和设备及其相应的管理机构的统称。主要包括各种军事设施以及可以用于军事目的的交通、运输、通信等设施。', 58);
INSERT INTO `t_military_term_data` VALUES ('3ee92ed2-4914-4879-acf9-0822edbc255c', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '悬停攻击', '直升机或垂直起落飞机悬停下空中以机载武器对敌方目标进行的攻击。', 77);
INSERT INTO `t_military_term_data` VALUES ('3ef29212-d1ce-42b3-baa0-9ac985af38de', '06a75831-13a1-4660-870a-455bb445336a', '密码', '按特定法则编成的、用以对通信双方的信息进行明密变换的符号。将明信息变换为密信息称为加密；将密信息变换为明信息称为解密。密码编制的方法有手工、机械和自动3种。', 156);
INSERT INTO `t_military_term_data` VALUES ('3efcb55d-25f0-42e4-9e9f-4369645bf59e', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '沙暴', '亦称沙尘暴。强风将大量尘沙吹卷到空中,致使水平能见度降至1千米以下的天气现象。沙暴多发生在沙漠地区和长期缺雨、土质干松又无植被覆盖的地区。', 31);
INSERT INTO `t_military_term_data` VALUES ('3efec0b3-6e3f-4fcd-b469-33ad7114554e', '06a75831-13a1-4660-870a-455bb445336a', '无线电接力站', '进行无线电接力通信的通信站。主要设备有无线电接力机、天线、电源等。分为终端站和中间站。终端站设置于接力线路的始端与末端,负责向使用单位提供电路；中间站负责接转邻站的信息,有的也可向附近用户提供电路。', 81);
INSERT INTO `t_military_term_data` VALUES ('3f035e9d-7e2c-4c67-b263-de33d9c9bc1d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '策应', '与友邻或友军相呼应的作战行动。可起间接援助的作用。', 330);
INSERT INTO `t_military_term_data` VALUES ('3f0f430c-176b-4631-9eff-b6740cc4cbe9', '97a19170-bfac-42c5-9906-1acb187f0654', '航空救生训练', '飞行人员为掌握被迫跳伞和特殊环境中的生存、营救技能而进行的训练。', 202);
INSERT INTO `t_military_term_data` VALUES ('3f133376-9455-459b-b08b-aa8441c1597f', '97a19170-bfac-42c5-9906-1acb187f0654', '空中轮番攻击', '多架飞机或直升机对同一空中目标相互轮流反复进行的攻击。以保持空中攻击的连续性和便于相互掩护。', 82);
INSERT INTO `t_military_term_data` VALUES ('3f1c0025-82d6-4259-9d89-22ca6fa72fb6', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '信息技术', '生产、获取、传输、处理和利用信息的技术。其主体是传感器技术、通信技术和计算机技术,以及支持主体技术的微电子技术、激光技术、自动控制技术、空间技术等。是当今世界新技术革命的核心与先导。军事上广泛应用于侦察、预警、通信、指挥、控制、电子对抗和后勤保障等方面。', 9);
INSERT INTO `t_military_term_data` VALUES ('3f32109e-9f7e-4962-b4c1-cd804b97da9c', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射准备', '将已完成技术准备的导弹转入临射状态所进行的各项准备工作的统称。', 133);
INSERT INTO `t_military_term_data` VALUES ('3f348bc7-d843-4e22-ae4d-41603c5dec53', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '中间层', '亦称中层。平流层顶至距地面约85千米高度之间的大气层。气温随高度的增加迅速降低,空气垂直运动相当强烈。', 4);
INSERT INTO `t_military_term_data` VALUES ('3f366c64-f5be-4fec-aa01-a46372143ec8', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练预备期', '年度训练开始前预作准备的日期。通常安排1～2个月。主要用以制定训练计划,准备训练场地、器材、培训教学骨干等。', 35);
INSERT INTO `t_military_term_data` VALUES ('3f41248b-7150-40fd-81da-12e7e4aac65f', '97a19170-bfac-42c5-9906-1acb187f0654', '飞艇', '有推进和操纵装置,主要靠空气浮力升空的航空器。分为软式飞艇、半硬式飞艇和硬式飞艇。主要用于空中运输、预警、巡逻等。飞艇。', 261);
INSERT INTO `t_military_term_data` VALUES ('3f4bd530-94af-434d-8e23-eed1b9af9a11', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '预备指挥所', ' 简称预指、备用的指挥所、一般与基本指挥所同时开设。在基本指挥所不能工作时接替指挥以保障不间断指挥', 48);
INSERT INTO `t_military_term_data` VALUES ('3f4f8e24-3f0c-4ad2-96ef-3bf7bdf0b90c', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '输送梯队', '输送时依任务、运输工具情况和行动顺序编组的梯队。通常根据任务和输送工具的情况进行编组,尽量保持部队建制的完整,使每个梯队都具有独立作战的能力。', 81);
INSERT INTO `t_military_term_data` VALUES ('3f530a66-10a0-43f8-a5fd-561a4e1098aa', '06a75831-13a1-4660-870a-455bb445336a', '通信自动化', '采用电子、机械设备代替人工操作,实现信息传输、交换和处理的自动化。主要包括；电话、电报、数据和图像等信息的自动交换,自动分配信道,自动加密、解密、纠错、抑制干扰和自动扫描显示、跟踪,设备的自动调谐、检测和维护管理,自动切换故障设备,整个通信网工作状态的自动显示、监控和调测等。', 160);
INSERT INTO `t_military_term_data` VALUES ('3f88bdf7-b431-4686-b42d-9debe70ba6d6', '8a761efd-50a6-4ac8-9913-b7d745104f82', '表尺距离', '在瞄准线上从外弹道起点到落点之间的距离。常指最大表尺分划所对应的射距。', 43);
INSERT INTO `t_military_term_data` VALUES ('3f8c7dc2-6523-47f9-bbcc-30c66481e43a', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵训练', '防空兵部队或分队进行的以作战所需的专业知识和技能为主要内容的训练。包括单兵训练、班组训练、连营训练、团或群训练等。', 131);
INSERT INTO `t_military_term_data` VALUES ('3f8df8be-e53b-41e1-9130-8ac61a47e89a', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '内务制度', '军队中关于内部日常生活事务的制度。一般由内务条令和其他规范性文件规定。主要内容包括：军人宣誓,军人职责,内部关系,礼节,军容风纪,作息,值班,警卫,装备管理,财务和伙食、农副业生产管理,卫生,营区、营产管理和连队内务设置,日常战备和紧急集合,野营管理,安全工作,国旗、军旗、军徽使用和国歌、军歌奏唱等。', 9);
INSERT INTO `t_military_term_data` VALUES ('3f92da36-5a27-43e5-a297-855e012168ee', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵群', '由数个执行同一任务的防空兵部队或分队临时组成的战斗编组。用以统一组织指挥防空兵的作战行动,提高对空掩护效能。', 13);
INSERT INTO `t_military_term_data` VALUES ('3f9d903c-67ab-4a19-9b2c-f51ac04054e7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '佯动', '为隐蔽企图和欺骗、迷惑敌人而采取的军事行动。按规模,分为战略佯动、战役佯动、战术佯动；按空间,分为地面佯动、海上佯动、空中佯动；按手段,分为兵力作动、火力佯动、电子佯动等。', 254);
INSERT INTO `t_military_term_data` VALUES ('3fa3847a-b4df-44e6-838b-8f126816008b', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行人员', '亦称空勤人员。在航空器上执行飞行任务和空中勤务的各种人员的统称。包括飞行员和空中领航员、通信员、射击员、机务员、乘务员以及预警机、电子对抗飞机、侦察机、空中加油机等飞机上的指挥人员和特种设备操纵人员等。', 15);
INSERT INTO `t_military_term_data` VALUES ('3fa757d9-8cd1-4587-b559-e212ec45ebca', '916997ee-6728-4c61-9b79-d96960b1dc86', '消毒剂', '用以清除毒剂及生物战剂的洗消剂、常用的有次氯酸盐类消毒剂、氯胺类消毒剂、碱性消毒剂、配方消毒剂和吸附性消毒剂等。能使毒剂失去毒性或利用吸附作用将毒剂从受染物表面除去,也可杀灭与清除生物战剂。', 186);
INSERT INTO `t_military_term_data` VALUES ('3fa7fe58-88e4-45b0-9581-4423c5b2e638', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵参战支前', '民兵配合军队或单独执行作战任务以及参加支援前线的各项勤务保障的活动；如运输物资、后送伤员以及担负侦察、封锁消息、打扫战场等作战保障任务。', 141);
INSERT INTO `t_military_term_data` VALUES ('3fadcdfc-3fd6-4c6a-b11c-04b9bb9320ac', '97a19170-bfac-42c5-9906-1acb187f0654', '轰炸', '飞机投掷炸弹、鱼雷和发射空地导弹对地面或水面、水下目标进行的空中突击。按飞行状态,分为水平轰炸、俯冲轰炸、下滑轰炸和上仰轰炸；按目的和规模,分为战略轰炸、战役轰炸和战术轰炸。', 90);
INSERT INTO `t_military_term_data` VALUES ('3fb1b3f2-3e71-444d-b9a8-db898ce38189', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事手段', '为达到一定的政治、军事目的而在军事上采取的方法或措施。', 50);
INSERT INTO `t_military_term_data` VALUES ('3fb82650-292f-4aa4-bd6c-d9f34b61b9f4', '97a19170-bfac-42c5-9906-1acb187f0654', '航空穿甲炸弹', '以高强度的弹体和下落时的动能穿透装甲或坚固工事而毁坏目标的航空炸弹。主要用以摧毁大型军舰、地下建筑和用钢板或钢筋混凝土构筑的工事等。', 327);
INSERT INTO `t_military_term_data` VALUES ('3fbc7596-3059-485e-87cc-c0ea0c25a039', '4d839792-0c29-4fae-bafd-63350606b2a7', '4444', '4', 0);
INSERT INTO `t_military_term_data` VALUES ('3fc76410-0daa-4875-92ed-d6b0b6085771', '916997ee-6728-4c61-9b79-d96960b1dc86', '野战化验箱', '野战条件下分析常见毒剂的化验器材。可随身携带,也可配备在野战化验车上使用。', 169);
INSERT INTO `t_military_term_data` VALUES ('3fc9588e-518e-4f8a-8ebb-9d9c7b955493', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '防反辐射摧毁', '为削弱或破坏敌方反辐射武器的攻击效能,保护己方电子设备安全而采取的战术技术措施。', 105);
INSERT INTO `t_military_term_data` VALUES ('3fcdb6a5-02ba-4df4-b98d-5512d4263255', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练制度', '军事训练工作必须遵守的各种制度、规定的统称。主要包括计划制度、请示制度、报告制度、会议制度、教学制度、考核制度等。', 21);
INSERT INTO `t_military_term_data` VALUES ('3fe366a1-5fb4-4ac1-882b-e4fc7d37af62', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '断崖', '背向敌方的陡壁式防坦克土工障碍物。通常在15度～45度的反斜面上切坡构成。壁高3.5米左右,底宽5.5～6米,并向内倾斜,以使坦克坠落时翻车。', 117);
INSERT INTO `t_military_term_data` VALUES ('3fe41f13-fe40-489d-a3a4-13931e2a9b6d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '点火站', '爆破作业时实施点火的位置。通常选在安全、隐蔽、能观察到爆破目标的地点。', 232);
INSERT INTO `t_military_term_data` VALUES ('3fe86c3d-3d98-4235-bee8-7dd1d205ff05', '878651de-adf5-4c72-9376-9c363b893ff8', '战略枢纽', '在战略指导上需要着重关注的,对战争全局具有决定意义的关节点。通常指战争中关键性的时间、地点、方向和行动等。须抓住战略枢纽部署战役。', 79);
INSERT INTO `t_military_term_data` VALUES ('40076b07-8e40-4431-970b-57c4f35f220c', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '缺编', '实有建制单位、人员或武器装备的数量少于编制规定的数额。', 73);
INSERT INTO `t_military_term_data` VALUES ('4015f305-902d-4165-abb1-2c68f3636d6f', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机潜伏场', '供少量直升机隐蔽,以执行侦察、攻击等作战任务的场地。', 99);
INSERT INTO `t_military_term_data` VALUES ('401d1137-ad51-4475-b108-e3889cfe4ab8', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵混合配置', '将执行同一任务的不同口径的高炮分队,或不同性能的地空导弹分队,或高炮分队与地空导弹分队结合,在同一地域所作的配置。可在被掩护目标或被掩护地域上空构成不同高度和不同距离的防空火网。', 23);
INSERT INTO `t_military_term_data` VALUES ('401ec8ba-7321-41a0-9dfe-2ce6d21f687d', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战略情报', '有关国家安全和战争全局所需的情报。主要包括：敌方和有关各方的军事思想、战略方针、战争计划、作战原则,战备措施,武装力量体制、军事实力、战争潜力,战略目标、军事部署,以及政治、外交、经济、科技、地理等情况。', 126);
INSERT INTO `t_military_term_data` VALUES ('4030ea2e-8499-4629-9f3f-c54a6441ba78', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学战场环境', '化学袭击造成的战场情况与条件。通常指化学袭击造成的人员中毒、伤亡大面积染毒地区和毒剂云团传播地带等状况。', 33);
INSERT INTO `t_military_term_data` VALUES ('40342686-35ea-42fc-8e1c-48fc8cc00d58', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克扫雷装置', '安装在坦克上的用以清除防坦克地雷的装置、分为机械式扫雷器和火箭爆破扫雷器两种。可根据需要在战斗前临时安装。', 146);
INSERT INTO `t_military_term_data` VALUES ('403edcbd-6966-42cb-b7e2-b58d60069ec1', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '贻误战机', '因主观指导失误或行动不力而丧失有利的问敌采取作战行动的时机。', 36);
INSERT INTO `t_military_term_data` VALUES ('404ee68f-f7d7-46c7-9960-d3ee65deccb7', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机悬停', '直升机利用本身动力在空中保持位置、高度、方向相对于地面或水面不变的飞行状态。', 21);
INSERT INTO `t_military_term_data` VALUES ('406b8272-85e2-47d3-83f3-4c19eb616940', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '战斗警戒', '掩护军队战斗行动的警戒。任务是防止敌之侦察、渗透和袭击,保障执行战斗任务部队的安全等。', 4);
INSERT INTO `t_military_term_data` VALUES ('406eec7f-0734-4bbe-b711-6daaabc17e3b', '06a75831-13a1-4660-870a-455bb445336a', '电话等级', '电话急缓程度的区分。分为警报信号传递、特急电话、加急电话、普通电话4个等级。', 135);
INSERT INTO `t_military_term_data` VALUES ('4072a876-7f30-4b2b-9831-3ab13cbe5aaa', '878651de-adf5-4c72-9376-9c363b893ff8', '战略方向', '对战争全局具有重要意义的作战方向。是指向战略目标的具有一定宽度和纵深的地区。分为主要战略方向和次要战略方向。', 84);
INSERT INTO `t_military_term_data` VALUES ('4073531c-0a0d-4d6a-b56e-384a2d590797', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天气预报', '对一定地区或空域未来一定时段内可能出现的天气状况所作的预测报告。按预报时效,分为临近预报（2小时以内）、甚短期预报（0～12小时）、短期预报（1～3天）和中期预报（4～10天）；按军事专业和保障对象,分为战区天气预报、海洋水文气象预报、航空天气预报、大气污染潜势预报、放射性沉降预报,以及保障各军兵种行动和国防科研试验的某些专项预报等。', 72);
INSERT INTO `t_military_term_data` VALUES ('40836d0e-e835-468d-a758-e961be9dc5d2', '98df76fb-4b65-48ff-a56c-4db587327c79', '战救药材', '卫勤分队和卫勤机动力量用于战伤救治的药材。主要包括上血、镇痛、麻醉、抗休克、抗感染等药品和包扎固定用卫生材料。战时观情况采用基数或单品种供应。', 219);
INSERT INTO `t_military_term_data` VALUES ('40940658-2c0b-4391-b4d9-654aa2ea48da', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报整理', '将情报资料分析提炼成情报的工作。主要包括消化资料、核实情况、研究原委、作出结论、编写成文字材料等步骤。', 142);
INSERT INTO `t_military_term_data` VALUES ('4094ca05-5259-45cd-8254-d6b98732ee61', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '野战火炮弹药支援车', '能直接给自行火炮供弹的专用车辆。机动性能好,载弹量大,供弹速度快。', 294);
INSERT INTO `t_military_term_data` VALUES ('409ae9d5-db7a-44ce-9bc0-6e6c26696e24', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵迷盲射击', '炮兵发射发烟弹造成一定的迷育地域,以妨碍敌之观察、机动或掩护己方行动的射击。', 178);
INSERT INTO `t_military_term_data` VALUES ('40a23d9d-162b-4ee2-b65c-11c65dd6bc54', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '班', '由若干名士兵编成的军队最基层一级组织。通常隶属于排。为最基本的战术小分队。', 22);
INSERT INTO `t_military_term_data` VALUES ('40aacf51-5b20-45ed-b8d6-f9ce3d51b016', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '对内正面', '担负围歼敌军任务的部队面向被围之敌的一面。', 51);
INSERT INTO `t_military_term_data` VALUES ('40c44eea-22a6-4094-a832-5e62373e489c', '97a19170-bfac-42c5-9906-1acb187f0654', '机型', '飞机的机种型号。通常由机种代字后加数字或再在数字后加其他代号编成,如歼击7型飞机（简称歼7）、强击5A型飞机（简称强5A）。', 265);
INSERT INTO `t_military_term_data` VALUES ('40cfbf74-901e-4ea4-9f1d-3b34556b4e0b', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物武器袭击迹象', '在适于使用生物武器的条件下,可据以判断敌进行生物武器袭击的现象。主要包括：敌飞行器投掷的不明材料或布洒的异常气溶胶；发现敌使用异常类型的炮弹或航空炸弹；蚊蝇等昆虫出现的季节和场所反常；人、畜突然发生原因不明的疫病；发现本国从未有过的传染病,并在短期内蔓延等。', 31);
INSERT INTO `t_military_term_data` VALUES ('40e9c9b6-dc74-4142-85e0-47fcdb09168a', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '单兵训练', '对单个士兵进行的训练。主要内容包括共同科目、专业技术和单兵战斗技能等。是分队训练的基础。', 53);
INSERT INTO `t_military_term_data` VALUES ('40ebeb43-19bd-4d0f-8302-25a3e595c0dd', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反机动', '破坏或制止敌军机动的作战行动。主要方法有：进行火力突击、兵力伏击,封锁、控制或破坏交通设施,干扰和破坏C3I系统等。', 336);
INSERT INTO `t_military_term_data` VALUES ('40ec13de-f87b-4596-8626-efa300db12fc', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '要点', '具有重大军事价值的地点。按重要程度,分为战略要点、战役要点和战术要点。', 305);
INSERT INTO `t_military_term_data` VALUES ('40f29e1f-7563-4422-83f6-9406a82f0ba4', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆战术技术性能', '车辆由设计、制造等因素所具备的固定特性和功能。主要包括技术性能参数和军事使用特性。如质量参数、尺寸参数、动力性能和适用的地区等。', 306);
INSERT INTO `t_military_term_data` VALUES ('40fe063e-3365-4211-b76a-7be6631c7348', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '防暴训练', '特种警备部队为掌握遂行防暴任务所需的制止暴乱知识和技能而进行的训练。', 82);
INSERT INTO `t_military_term_data` VALUES ('4100dc57-1c3f-4809-8e4c-d572a1dfb5c2', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '海岸线', '陆地与海平面的交界线。其位置随海水的涨落而变动。一般指多年平均海水高潮面所能达到的岸线。', 41);
INSERT INTO `t_military_term_data` VALUES ('4109b4e2-9142-48fd-b447-8a96aab354d0', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '队列条令', '规定军队的队列动作、队列队形和队列指挥的条令。是军队队列训练和队列生活的依据。', 5);
INSERT INTO `t_military_term_data` VALUES ('4111c0c4-bc9b-4527-acbb-05458d50ed88', '98df76fb-4b65-48ff-a56c-4db587327c79', '军队自筹物资', '军队通过非国家计划分配渠道自行筹集的物资。主要包括通过市场调节、军工自产、合资经营、补偿贸易、协作串换、自有外汇进口等办法筹集的物资。用以弥补计划供应不足,兼顾计划外任务的需要。', 101);
INSERT INTO `t_military_term_data` VALUES ('4111d416-82ea-4286-8a12-3c56fca95062', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵集中指挥', '炮兵指挥员及其指挥机关对所属部队或分队作战行动实施的集中统一的指挥。通常在炮火准备和部队统一行动时采用。', 84);
INSERT INTO `t_military_term_data` VALUES ('4113dddb-9b92-4908-a0c8-f327faa44a74', '8a761efd-50a6-4ac8-9913-b7d745104f82', '抛绳弹', '能利用弹丸将绳索抛到远处的弹药。抛射方式有榴弹发射、火箭发射和弹射发射等。抛射距离可达100米以上。主要供侦察兵和特种兵使用。', 208);
INSERT INTO `t_military_term_data` VALUES ('412a04c8-21f8-4b14-bfa9-210667bcebf3', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事测绘装备', '配备给测绘部队和分队使用的测绘仪器、设备和器材的统称。', 149);
INSERT INTO `t_military_term_data` VALUES ('4144d44a-9ff9-4ab7-a111-baa50922f83d', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天', '亦称宇宙航行。人类为探索、开发和利用宇宙空间以及地球以外的天体,借助航天器在太空进行的飞行活动。主要包括：环绕地球的运行,飞往月球或各大行星的航行,行星际空间的航行以及飞出太阳系的航行等。', 195);
INSERT INTO `t_military_term_data` VALUES ('4158ee19-917f-4fe7-a377-7d40141db28a', '31f4a446-5b98-4873-9d53-310d97125b07', '转运导弹', '对导弹实施的转载和运输。如将导弹从铁路运输车上起吊到公路运输车上或由公路运输车上起吊到发射车上,并运输到目的地。', 80);
INSERT INTO `t_military_term_data` VALUES ('415fbccf-2d36-4435-a033-18332bb79841', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '雷炮阵地', '由水雷障碍与岸炮火力和岸舰导弹火力构成的海上封锁区域。通常设置在海峡或海岸防御的重要海区,以充分发挥水雷和岸防火力联合打击的威力,消灭进入雷炮阵地的敌舰船或限制其行动。', 110);
INSERT INTO `t_military_term_data` VALUES ('4160c8e8-862f-4660-9631-98866dd4d103', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '多级火箭', '由两枚以上单级火箭连接而成的火箭。分为二级火箭、三级火箭、四级火箭等。多用于弹道导弹和航天器的发射。', 66);
INSERT INTO `t_military_term_data` VALUES ('41620ccc-fef8-4883-a663-a4db2603196e', '98df76fb-4b65-48ff-a56c-4db587327c79', '越野汽车', '能在各类地面行驶的全轮驱动汽车。分为轻型、中型、重型和超重型越野汽车。主要用以牵引或运载武器装备,输送人员物资等。', 293);
INSERT INTO `t_military_term_data` VALUES ('416b532b-b1d2-491a-bdcf-5151ab0edd48', '916997ee-6728-4c61-9b79-d96960b1dc86', '固定烟幕', '发烟正面停留在一个区域而基本不移动的烟幕。施放烟幕时,发烟地域固定不变。', 77);
INSERT INTO `t_military_term_data` VALUES ('4186df7e-0eee-4d27-a9b9-4332686ef476', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察车', '装备有侦察器材,用以进行侦察的专用车辆。包括侦听车、测向车、照相侦察车、雷达侦察车、电视侦察车、炮兵侦察车、防化侦察车等。', 118);
INSERT INTO `t_military_term_data` VALUES ('418d4cf3-cf83-47d4-9c68-a31dc5016b7b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核弹头总装时间', '核弹头由分袋储存状态组装成可交付与弹体对接的状态所需要的时间。也就是核弹头的战备反应时间。', 127);
INSERT INTO `t_military_term_data` VALUES ('4191b3e5-e6b1-4e0f-a0d6-f38d170f0869', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '勤务舰船', '亦称辅助舰船。用于海上作战保障、技术保障和后勤保障的舰船的统称。包括侦察、测量、调查、救生、运输、补给、修理、工程、医疗、训练和试验等舰船。', 130);
INSERT INTO `t_military_term_data` VALUES ('41925bcc-03eb-4c7d-8d92-4cdec8ba45e7', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '水下核试验', '爆心在水面以下一定深度的核爆炸试验。通常分为浅层水下核试验和深层水下核试验。主要用以研究水下核爆炸对舰艇、海港、大型水利设施和建筑物的破坏效应以及放射性沾染等。', 182);
INSERT INTO `t_military_term_data` VALUES ('41b35652-6f7a-4f3b-9f08-e33662fe8bf8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航空兵海上救生', '航空兵对海上遇险人员进行救援的行动。通常由水上飞机或直升机担任。水上飞机采用着水或投放救生器材的方法实施救援；直升机采用悬停救援。', 339);
INSERT INTO `t_military_term_data` VALUES ('41bd6106-ee56-4167-b037-2548b0f85ab5', '8a761efd-50a6-4ac8-9913-b7d745104f82', '狙击步枪', '供狙击用的高精度步枪。配有专门瞄准镜，射击精度明显优于普通步枪,能射击1000米内单个生动目标。有非自动狙击步枪和半自动狙击步枪。枪重4.5～6千克,容弹量10～20发。', 165);
INSERT INTO `t_military_term_data` VALUES ('41c1bf19-3d49-46db-9371-67a8208f1184', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '图廓', '地图上表示地理内容要素的范围线。有内图廓和外图廓。内图廓是图幅的实际范围线,由一条细线和经纬线加密划分的分度带组成；外图廓仅起装饰作用,地形图上只绘一条粗线。小比例尺挂图的外图廓常用各种图案的花边装饰。', 278);
INSERT INTO `t_military_term_data` VALUES ('41c9f98d-80f3-4824-a107-f914caa578b6', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '人民武装部', '简称人武部。在县、旗、县级市、市辖区设立的军队一级组织。隶属于军分区或卫戍区、警备区。中国人民解放军在地方所设立的人民武装部为本地区的军事领导机关,是县、旗、县级市、市辖区党委的军事部,兼同级政府的兵役机关,受上级军事机关和同级地方党委、政府的双重领导。主要负责辖区内的民兵、兵役和动员工作。在乡镇、大中型企业和事业单位负责民兵、兵役等工作的部门,亦称人民武装部,但不列入军队编制。', 25);
INSERT INTO `t_military_term_data` VALUES ('41cabfbb-781d-4216-8aee-e722730921cc', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '团日', '中国共产主义青年团的基层组织进行团内活动的专门时间。活动内容主要包括：召开团的会议,进行团的教育,发展团员等。', 52);
INSERT INTO `t_military_term_data` VALUES ('41d49461-e387-4418-851b-92a1d791a5d3', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战术情报', '组织实施战斗行动所需的情报。主要包括：当面之敌的番号、战斗企图、战斗编成、兵力部署、行动方向、阵地编成、火力配系、工事构筑、障碍设置、通信联络、后勤保障,战术特点,以及地形、气象、水文、社会情况等。', 128);
INSERT INTO `t_military_term_data` VALUES ('41df3f70-f981-4d90-9391-3726d02fe572', '916997ee-6728-4c61-9b79-d96960b1dc86', '消除沾染', '简称消除。对受染对象实施消除放射性沾染的洗消。根据不同的受染对象,可采用拍打、扫除、吸尘、冲洗、高速气流冲除、过滤、铲除等方法,清除沾染或降低沾染程度。', 65);
INSERT INTO `t_military_term_data` VALUES ('41df98be-a1d6-42af-a120-cd423e6d2edf', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡河检查站', '负责检查、调整和监督人员、车辆及技术兵器按规定前出渡河的机构。通常设在由待渡地区（渡河出发线）通往渡口的道路近旁,设有卡门、路标和掩蔽工事等。', 317);
INSERT INTO `t_military_term_data` VALUES ('41e537e6-5e00-4996-98b3-29297772de98', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '脉冲多普勒雷达', '利用多普勒效应和频谱分离技术测定目标的位置和速度的脉冲雷达。具有对目标进行速度分辨和较好的抑制地物杂波的能力。主要用作具有下视能力的机载雷达也可用于导弹制导、战场侦察、气象观测等。', 91);
INSERT INTO `t_military_term_data` VALUES ('41f2dcee-e223-4ad1-ac8b-2ab2f1bab43d', '97a19170-bfac-42c5-9906-1acb187f0654', '空域', '根据飞行任务需要而划定、以地标或导航台为标志的一定范围的航空空间。通常分为训练空域和作战空域。', 226);
INSERT INTO `t_military_term_data` VALUES ('41fb83e8-6e28-4098-b78b-71cf1b53bc0e', '31f4a446-5b98-4873-9d53-310d97125b07', '水平测试', '导弹呈水平状态时,对其各系统的功能和协调性进行的测试。一般在技术阵地上进行。', 87);
INSERT INTO `t_military_term_data` VALUES ('42088e7b-666d-4f9c-9383-c5c061c6a6e4', '8a761efd-50a6-4ac8-9913-b7d745104f82', '集束弹道', '一件武器在同一发射条件下,众多射弹自然散布所形成的一束弹道。它随着距起点的距离增大而逐渐向外扩散,其中互有交错。', 37);
INSERT INTO `t_military_term_data` VALUES ('4222b020-e7d8-4d87-b966-c3d3080616fc', '98df76fb-4b65-48ff-a56c-4db587327c79', '单兵装备', '单个士兵配带的武器、弹药、被服和装具等的统称。', 20);
INSERT INTO `t_military_term_data` VALUES ('4222e706-fe1d-46a9-96ac-f5147f4e45c6', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物战剂媒介', '能感染、储存或携带并传播生物战剂的媒介昆虫或媒介动物。生物媒介能通过叮咬等途径,将生物战剂传入人、畜机体而使其致病。', 145);
INSERT INTO `t_military_term_data` VALUES ('422e51cf-e9fa-438e-920f-a4034268e925', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备状况', '战争准备的状态和情况。通常指战备制度的落实以及战备工作与活动的开展的状况。', 102);
INSERT INTO `t_military_term_data` VALUES ('424572b7-fc1d-4222-a76b-fbb5b4f88b5a', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边界联合检查', '相邻两国的边防人员或专家共同对国界标志进行的检查。包括定期的和不定期的边界联合检查。目的是检查因自然或人为原因所引起的国界变化情况。', 116);
INSERT INTO `t_military_term_data` VALUES ('42490234-9839-40ea-a565-af1a5693c59c', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹射击方法', '地空导弹火力单位对空中目标射击时,为探测、跟踪目标、制导导弹,连续实施射击和提高射击效率而采用的方法的统称。包括选择武器系统的工作体制、导引方法、跟踪方法、发射种类和转移火力等。', 196);
INSERT INTO `t_military_term_data` VALUES ('42618449-fc84-4784-8654-d5a411294393', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军队院校', '军队中培养各级各类人才的大学、学院和学校的统称。', 10);
INSERT INTO `t_military_term_data` VALUES ('4261c04d-ef40-48ef-be93-27950184e215', '98df76fb-4b65-48ff-a56c-4db587327c79', '营房', '专供军队住用的房屋。通常包括工作用房、文体活动用房、专业用房、生活用房、招待用房、库房和附属用房等。', 233);
INSERT INTO `t_military_term_data` VALUES ('4269ff60-afb4-4288-8c27-ee0ffdc9d8db', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '粉碎', '彻底打败敌人,使其企图不能得逞。', 376);
INSERT INTO `t_military_term_data` VALUES ('427ac589-108c-4ebf-8566-943c594c9766', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '养成教育', '日常生活中对军人进行的以自觉贯彻执行条令、条例和各种规章制度为内容的经常性教育。目的是培养军人严格的纪律观念和良好的作风。', 75);
INSERT INTO `t_military_term_data` VALUES ('427e3bc9-2042-4fc8-a8a4-fb4dc540dff7', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹发射区', '地空导弹发射时空中目标必须处在的空间区域。通常以发射区的远界、近界。高界、低界、侧界等特征参数表示。其形状和大小与杀伤区及目标运动特性有关。', 140);
INSERT INTO `t_military_term_data` VALUES ('427ef6a7-0bce-42e2-b612-088973f2f08c', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军队领导机关', '军队中负有组织领导责任的各级工作机构的统称。中国人民解放军的最高领导机关是中央军事委员会（简称军委）及其工作机构总参谋部、总政治部、总后勤部（简称三总部）；部队的领导机关包括各级司令部、政治部（处）、后勤部（处）等。', 2);
INSERT INTO `t_military_term_data` VALUES ('4292d21c-08bf-421f-be07-4fe3ae676dae', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '军港管理勤务', '对军港港区实施管理和对停泊舰船提供后勤保障的专业勤务。主要包括：港区的规划与建设,港产管理,设施维修,港池、港内航道的疏浚,港区安全警卫,港容卫生,码头管理,防污监督与治理以及对停泊舰船水、电、气、暖的供应等。', 347);
INSERT INTO `t_military_term_data` VALUES ('4298a554-3552-48be-b9a4-f94d23785a5a', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '制式桥', '用制式桥梁器材架设的军用桥梁。如轻便桥、机械化桥、装配式公路钢桥等。架设作业机械化程度较高,速度快,架设撤收方便。', 272);
INSERT INTO `t_military_term_data` VALUES ('429e1045-c86a-40e1-9a01-498cf65ec514', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克大修', '坦克大修间隔期使用终了时进行的全面修理。由坦克大修厂承担。', 209);
INSERT INTO `t_military_term_data` VALUES ('42b5b60a-54ce-4d98-a17d-9021abc6c106', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵跟随转移', '防空兵部队或分队跟随被掩护部队一起进行的转移。', 85);
INSERT INTO `t_military_term_data` VALUES ('42b97d53-a400-4eed-ba79-66f0a81d26ac', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '飑线', '由雷暴单体或雷暴群体组成的狭窄的强对流天气带。是一种发生突然、持续时间较短的中尺度天气系统。飑线过境时,风向突变,风速急增,气压涌升,气温骤降,常伴有雷暴、阵雨,有时还伴有冰雹或龙卷。', 48);
INSERT INTO `t_military_term_data` VALUES ('42bb6f6a-3cc4-4453-a994-33b7c97529d3', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '作业指导法', '用以统一、规范部队、分队及单兵作业训练的组织与实施的指导性文件。是部队、分队组织实施作业训练的基本依据。', 18);
INSERT INTO `t_military_term_data` VALUES ('42c49c4e-110e-45eb-84c4-12676036c8ab', '97a19170-bfac-42c5-9906-1acb187f0654', '训练飞行', '为遂行军事训练任务而实施的飞行。', 209);
INSERT INTO `t_military_term_data` VALUES ('42c9cea5-84cf-4002-b91c-5690d98f2ed1', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '塑性炸药', '以猛炸药为主要成份与高聚物粘结剂、增塑剂混合制成腻状的混合炸药。如C－4炸药系列,爆胶和胶质炸药,粘性炸药及糊状炸药等。主要用以装填碎甲弹和作特种爆破装药使用。', 212);
INSERT INTO `t_military_term_data` VALUES ('42e02412-a7c2-401e-a0dd-0ecc9abe8840', '878651de-adf5-4c72-9376-9c363b893ff8', '战争起源', '战争现象在人类历史上的最初产生。一般认为,最初的战争现象产生于原始社会的后期。私有制和阶级出现后,产生了阶级社会的战争。', 2);
INSERT INTO `t_military_term_data` VALUES ('42e23380-0560-44bc-aac8-68dd5ac3dbcb', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '海疆', '国家所属和领海管辖的海域的统称。包括领海及毗连区、专属经济区及大陆架等。', 75);
INSERT INTO `t_military_term_data` VALUES ('42e804f3-9278-484f-a348-9b9344c3466f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事测绘', '为满足国防建设、军队作战和训练的需要而进行的测绘。主要包括：军事大地测量,军事摄影测量,军事地图制图,军事海洋测绘和军事工程测量等。', 146);
INSERT INTO `t_military_term_data` VALUES ('42f41901-f7e3-42b9-a278-548e960ff71b', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '四会教练员', '军事训练中会讲、会做、会教、会做思想工作的基层军官和班长。是部队军事训练中对教练员的基本要求和衡量标准。', 146);
INSERT INTO `t_military_term_data` VALUES ('42f68f69-e72e-4226-987b-7178c3b94c09', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '灌木', '无明显主干的木本植物。植株一般矮小,大片聚生的称灌木林,小片丛生的称灌木丛。灌木林妨碍军队运动。', 94);
INSERT INTO `t_military_term_data` VALUES ('43006f3a-da85-4d1a-a0df-adf7b2c74f4a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '边防侦察', '边防部队、民兵在边境地区组织实施的侦察。', 25);
INSERT INTO `t_military_term_data` VALUES ('43075a78-cc2d-46b0-8738-b24ab99fc41f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '反坦克导弹发射车', '发射反坦克导弹的专用车辆。车上装载导弹发射控制装置、瞄准装置和制导装置等。有轮式和履带式两类。', 35);
INSERT INTO `t_military_term_data` VALUES ('4309de16-61d4-421a-ba1a-b678041a89b6', '98df76fb-4b65-48ff-a56c-4db587327c79', '支前', '地方政府和人民群众以人力、物力、财力支援前线的活动。如动员参军,参加战勤工作,慰问伤病员,优待烈军属等。', 39);
INSERT INTO `t_military_term_data` VALUES ('431c3f2a-0169-4be3-ad35-df6064dbba8f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '预设战场', '在敌人可能入侵的方向上,预先设防的作战地区。如要塞、设防岛屿等。', 171);
INSERT INTO `t_military_term_data` VALUES ('432b1a58-e62f-4855-9641-63a9df8005ac', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '摩托化行军', '亦称乘车行军。乘坐建制内或配属的轮式车辆的行军。', 43);
INSERT INTO `t_military_term_data` VALUES ('433a8964-206e-43ed-a332-f5093ac729eb', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '像片判读', '通过对航空、航天像片上目标影像的分析。判明目标的性质和状况的作业。是获取地形信息和敌情资料的重要途径。主要通过影像的形状、大小、色调、阴影、纹形图案、相关位置和活动痕迹等,识别和判读目标。', 246);
INSERT INTO `t_military_term_data` VALUES ('435266d7-3f6e-4ee6-989e-d15cf2c63a0d', '06a75831-13a1-4660-870a-455bb445336a', '通信装备', '军队列编的各类通信设备和器材的统称。主要包括：无线电、有线电、光通信装备,运动通信、简易信号通信工具,以及通信设备的各种附属工具、仪器、表、材料等。', 173);
INSERT INTO `t_military_term_data` VALUES ('436cd506-82a9-460a-9887-12b5338ef1a3', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '导弹战', '以导弹武器为主要攻防手段的作战。', 148);
INSERT INTO `t_military_term_data` VALUES ('436d9752-9034-45af-b0ea-099385af8153', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '可撤布地雷', '用于空投、发射、抛撒等方式布设的地雷。分为可撒布防坦克地雷和可撒布防步兵地雷。通常装填于炮弹、炸弹、火箭弹和布雷器内,用火炮、飞机、布雷车和单兵布雷器等撒布,着地后自行解除保险,进入战斗状态。', 144);
INSERT INTO `t_military_term_data` VALUES ('437126b7-fa41-4d41-8a0c-5e20df6835f5', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方地域', '后方机关、部队配置和展开工作的地域。', 47);
INSERT INTO `t_military_term_data` VALUES ('4389bc33-3042-4b7a-9852-2b7c21064b55', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵交替掩护', '防空兵分批交替转移,对运动中的部队实施的对空掩护。通常在进攻部队向敌纵深推进时采用。', 81);
INSERT INTO `t_military_term_data` VALUES ('43a3554a-5833-4548-92c9-44fa5fddd921', '878651de-adf5-4c72-9376-9c363b893ff8', '战略迂回', '为达成一定战略目的而向敌战略部署的翼侧或后方实施的迂回。通常与战略包围相结合。用以断敌退路,阻敌增援,协同正面进攻,合围和消灭敌人。', 118);
INSERT INTO `t_military_term_data` VALUES ('43a98895-1eee-43e7-8a8f-e21cfaf16e9f', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤演习', '后勤机关、部队或分队在想定情况诱导下进行的军事演习。通常在合成军队演习中进行,也可单独组织实施。', 38);
INSERT INTO `t_military_term_data` VALUES ('43af9bdb-207c-4156-bc43-102ab63e24df', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '进攻发起方式', '部队对敌发起进攻所采取的方式。通常分为从进攻出发阵地发起进攻和从行进间发起进攻两种方式。', 96);
INSERT INTO `t_military_term_data` VALUES ('43de0801-084e-451f-81e6-95d4c3f40ae2', '97a19170-bfac-42c5-9906-1acb187f0654', '机场防御', '为保卫机场及其所驻兵力的安全,抗击来自空中和地面的袭击而进行的防御。通常构有环形而有重点的对空和对地面的防御体系,并采取疏散、隐蔽、伪装等措施。', 119);
INSERT INTO `t_military_term_data` VALUES ('43e22a76-05dc-4e9a-8798-41883b556b9a', '97a19170-bfac-42c5-9906-1acb187f0654', '空军指挥体系', '由空军各级指挥系统按指挥关系构成的统一整体。包括空军、军区空军和空军军、师、团等指挥系统。各指挥系统主要由基本指挥所、预备指挥所等指挥机构组成,必要时还可建立前进指挥所、辅助指挥所、指挥小组和目标引导组等。', 176);
INSERT INTO `t_military_term_data` VALUES ('43e3e1d2-e8f9-4516-85c5-26823f9257a3', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '等高距', '地形图上相邻两等高线水平截面间的高程差。', 280);
INSERT INTO `t_military_term_data` VALUES ('43e892bd-7b3b-49c5-a9e7-2a5e5906a313', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '要地防空', '为保卫国家重要地区或目标安全而组织的区域性的防空。包括政治经济中心、首脑机关、军事要地、重要工程、工业基地和交通枢纽的防空等。是国土防空的主体部分。', 218);
INSERT INTO `t_military_term_data` VALUES ('43e9ba1d-7ce7-4a68-8d79-07f72f9c5dd1', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军龄', '军人服现役的年数。', 152);
INSERT INTO `t_military_term_data` VALUES ('440c773b-a013-4097-9419-ebe43de17757', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '逼近', '军队强行接近敌人的行动。通常在火力掩护下实施。', 342);
INSERT INTO `t_military_term_data` VALUES ('441be1d9-8e2b-41a0-88b2-2301ad36550c', '06a75831-13a1-4660-870a-455bb445336a', '数字电话终端机', '利用时间分割原理进行多路复用的电话通信设备。主要是将电话信号进行模数和数模变换,以实现数字传输。可进行多路电话通信。', 193);
INSERT INTO `t_military_term_data` VALUES ('441dcf19-db7d-4daf-aaf5-4e85df3653b7', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达对抗侦察设备', '专门用于雷达对抗侦察的电子设备。包括情报侦察设备、支援侦察设备和雷达告警设备。', 114);
INSERT INTO `t_military_term_data` VALUES ('441f3bef-d426-4740-bb9c-f816be212e97', '97a19170-bfac-42c5-9906-1acb187f0654', '空中搜索', '①在飞机或直升机上用目力或机载雷达等设备,对空中、地面、水面、水下目标进行的搜寻活动。②空战的起始阶段。自飞机进入作战空域起至飞机发现空中目标止。主要进行搜寻敌空中目标活动。', 75);
INSERT INTO `t_military_term_data` VALUES ('443667de-3d70-47f8-9219-5c38a92f1d42', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教学法集训', '对教员、教练员进行的以教学方法为内容的短期集中训练。通常用以统一教学思想和训练内容,改进教学方法,提高教学能力。', 142);
INSERT INTO `t_military_term_data` VALUES ('4447cdfd-00ee-42d7-898c-fdb552eac3bd', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军人通行证', '军人离开驻地出差或探亲时使用的允许其通行的证件。证内填写有军人身份,出发、经过和到达地点,是否携带武器以及有效期限等情况。', 41);
INSERT INTO `t_military_term_data` VALUES ('444b7092-e9ae-4005-8c00-bd4bea9a15d2', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤管理', '为实现后勤工作目标而实施的计划、组织、协调、控制活动的统称。是军队管理的组成部分。主要包括财务管理、物资管理、卫生管理、装备管理、营房管理等。', 4);
INSERT INTO `t_military_term_data` VALUES ('44512749-d8f4-47c6-a433-8a2f726dbdfd', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '行政责任事故', '军队中由于管理不严,工作失职,违反条令、条例、规章制度和操作规程等原因造成的事故。如军事训练事故、工程作业事故、交通运输事故以及日常工作和生活中的武器走火、失火、淹亡、触电、中毒。中暑、冻伤等事故。', 58);
INSERT INTO `t_military_term_data` VALUES ('4452c0f3-76cc-4937-8616-0c618f0a4d1d', '31f4a446-5b98-4873-9d53-310d97125b07', '核突击', '使用核武器对敌方目标实施的突击。分为单个核突击、集群核突击和密集核突击。通常用于有决定意义的时机和方向。实施核突击,必须实行高度集中统一指挥,按照核火力计划进行,并与各军兵种的行动协调一致,密切配合。', 21);
INSERT INTO `t_military_term_data` VALUES ('445aee4e-044a-4186-bbfa-f02c89b75401', '916997ee-6728-4c61-9b79-d96960b1dc86', '内照射', '进入人体内的放射性核素对人体产生的照射。主要是a射线和β射线的照射。', 101);
INSERT INTO `t_military_term_data` VALUES ('4463c06b-375d-4b34-8927-63a9650ee840', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤力量', '军事后勤的人力、物力、财力的统称。包括军队后勤力量和地方支前后勤力量。', 56);
INSERT INTO `t_military_term_data` VALUES ('4474fbed-7117-4b1a-a6e1-84855edbe146', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '防御地区', '担负防御作战任务的部队负责守卫或抗击敌人进攻的地区。', 127);
INSERT INTO `t_military_term_data` VALUES ('4475aa63-7ecc-4774-9b62-745d58a42b27', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海区', '海洋的一定区域。有按自然地理称谓的,如渤海海区、太平洋海区等；有根据军事需要划定的,如作战海区、训练海区等；还有根据科研、生产需要划定的,如试验海区、捕捞海区等。', 379);
INSERT INTO `t_military_term_data` VALUES ('447a0b42-8b22-4b03-8a61-ec2438599541', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮弹装药', '炮弹的发射装药和爆炸装药的统称。发射装药为用于发射弹丸的发射药、药筒、底火和辅助元件的组合件；爆炸装药为装在弹丸内用于起爆、杀伤或抛射的炸药。', 328);
INSERT INTO `t_military_term_data` VALUES ('4481af9a-2958-4a70-89f9-00ddbd3c1ca7', '06a75831-13a1-4660-870a-455bb445336a', '超短波通信', '亦称甚高频通信。波长为10～1米（频率为30～300兆赫）的无线电通信。一般不受昼夜和季节变化的影响,但通信距离受地形影响较大。通常用于战术电台的近距离通信。采用无线电接力、散射、卫星和流星余迹通信等方式可进行远距离通信。', 104);
INSERT INTO `t_military_term_data` VALUES ('44823d12-0ce0-4214-b20d-67a023b34a77', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '拥军优属', '中华人民共和国地方各级党政机关、群众团体和人民群众开展的拥护人民解放军,支持国防建设和军队建设,优待烈属、军属、伤残军人、复员退伍军人的工作。', 123);
INSERT INTO `t_military_term_data` VALUES ('448b971c-6462-414f-b42d-300f60c4cf9f', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '省军区', '在省、自治区一级行政区域设立的军队一级组织。隶属于军区。中国人民解放军的省军区同时是中国共产党省或自治区委员会的军事工作部门和省或自治区政府的兵役工作机构,受军区和省或自治区党委、政府的双重领导。设有领导机关。一般辖若干个军分区或师级要塞区、警备区,有的还辖一定数量的部队和分队。主要负责辖区内的民兵、预备役、兵役、动员工作和省会或自治区首府的警备勤务,有的还担负边防、海防守备任务等。', 23);
INSERT INTO `t_military_term_data` VALUES ('448db25e-befa-4029-bca9-b301b1e8df1c', '06a75831-13a1-4660-870a-455bb445336a', '通信电缆', '具有密封护套的绝缘导线束构成的电信号传输线。可传输电话、电报、数据和图像等。通常采用架空、直埋、管道和水底等方式敷设。通信容量较大,受外界干扰小,但不易检修。适用于建立战略、战役干线和永备筑城地域的通信线路。', 208);
INSERT INTO `t_military_term_data` VALUES ('44930158-8354-41e8-a54b-b1d881a17b64', '916997ee-6728-4c61-9b79-d96960b1dc86', '速效性毒剂', '能使中毒人员在数分钟内出现毒害效应的毒剂。如沙林、梭曼、氢氰酸等。', 208);
INSERT INTO `t_military_term_data` VALUES ('44a4d4ba-d054-44de-a4d0-1e22c9393dc9', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '下级', '军人之间或军队组织之间不论有无隶属关系,行政职务或级别低者。军人在相互不知道行政职务时,军衔低者亦为下级。', 126);
INSERT INTO `t_military_term_data` VALUES ('44bc7ae0-bbd4-4844-ab9b-1efe7aa42e53', '31f4a446-5b98-4873-9d53-310d97125b07', '核武器自相摧毁效应', '用两件以上核武器对目标实施袭击时；后续的核武器因前面的核武器爆炸而被摧毁、失效或偏离预定目标,以及杀伤因素被削弱的现象。通常在爆炸时间间隔过短,或相互间爆炸的距离小于核袭击安全距离的情况下出现。', 154);
INSERT INTO `t_military_term_data` VALUES ('44c0be51-8ec1-494a-beec-6f62e791f411', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '大熊星座', '北极区内最明亮、最重要的星座。座内的7颗亮星称北斗七星,排列似长尾巴大熊状。是判定方位和认识其他星座的重要标志。', 192);
INSERT INTO `t_military_term_data` VALUES ('44c1d948-8245-4aa4-8fed-7caf81fd6b25', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达对抗侦察', '为获取雷达对抗所需的情报而进行的电子对抗侦察。主要是通过搜索、截获、分析和识别敌方雷达发射的信号,查明敌雷达的工作频率、脉冲宽度、脉冲重复频率、天线方向图、天线扫描方式和扫描速率以及雷达的位置、类型、工作体制等。', 18);
INSERT INTO `t_military_term_data` VALUES ('44c5c5f3-c94a-47e0-8db3-a7ad1f242d70', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军指挥自动化系统', '保障海军各级指挥机构对所属部队和武器系统实施快速、高效的指挥与控制的指挥自动化系统。是军队指挥自动化系统的组成部分。按指挥层次,分为海军、舰队（基地）、编队和舰艇等指挥自动化系统；按工作环境,分为岸基和舰载指挥自动化系统。', 120);
INSERT INTO `t_military_term_data` VALUES ('44d371aa-4254-4a52-b80a-0ca28db59f89', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练摩托小时', '车辆、机械的发动机用于军事训练的工作时间的计算单位。发动机工作1小时称为1个训练摩托小时。', 193);
INSERT INTO `t_military_term_data` VALUES ('44d4de3d-e4fd-4412-bc99-ab40138ec578', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核武器残片', '亦称核武器碎片或核武器剩留物。核武器爆炸后残存的碎片。包括核裂变产物、尚未裂变的核装料和弹壳等。核爆炸时,这些碎片因高温急剧汽化,随后凝成细小微粒沉降。是主要的放射性沾染源。', 170);
INSERT INTO `t_military_term_data` VALUES ('44db90dc-03b3-415f-a140-824635d839a9', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '战略导弹潜艇', '亦称弹道导弹潜艇。以弹道导弹为主要武器。用于对敌方陆上战略目标实施核突击的潜艇。战略导弹潜艇均为核动力。核动力战略导弹潜艇的隐蔽性好,生命力强,突正威力大,是核打击力量的重要组成部分。', 137);
INSERT INTO `t_military_term_data` VALUES ('44eacee8-ec41-4379-9a83-f94c6d309fe9', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '软着陆', '航天器经专门减速装置减速后,以很低的速度在地球或其他星球表面实施的安全着陆。', 285);
INSERT INTO `t_military_term_data` VALUES ('44f5530f-d7d3-4631-92bf-a6a134221933', 'f0140091-c11a-48c9-8836-8aa94439dac0', '兵种战术', '单一兵种进行战斗的方法。如陆军中的步兵战术、工程兵战术,海军中的水面舰艇战术,空军中的航空兵战术等。', 25);
INSERT INTO `t_military_term_data` VALUES ('44fecccf-307b-419d-ad07-401a96080f68', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '集中兵力', '在一定的时间内,把兵力集中使用于同一方向、区域或目标。', 242);
INSERT INTO `t_military_term_data` VALUES ('4504e303-3b65-4ce9-857a-00569b213dd3', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '转业军人', '退出现役转到地方,由国家统一安排工作的中国人民解放军的干部和志愿兵。', 157);
INSERT INTO `t_military_term_data` VALUES ('4509c3af-5e88-46ab-8609-5e293870df4e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '基准车', '冲击时为保持冲击方向而指定的、起导向作用的坦克、步兵战车和装甲输送车的统称。', 32);
INSERT INTO `t_military_term_data` VALUES ('4522fd6d-24a3-40ac-890d-e7e8b57dabe2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备', ' 为应付可能发生的战争或军事突发事件而在平时进行的准备和戒备。', 99);
INSERT INTO `t_military_term_data` VALUES ('452bdb7d-1e19-48fa-b374-4c66ff3f3c06', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '节', '①航海通用的速度计量单位。也可用以计量水流、风速和水中武器航行的速度。每1海里／小时为1节。②舰船锚链分段制造和使用标志的长度单位。国际上通常规定锚链以27.5米长为1节。中华人民共和国舰艇锚链则以20米长为1节。', 279);
INSERT INTO `t_military_term_data` VALUES ('452ee36a-b44f-4819-9680-d243e900e9df', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '战炮分队', '操作火炮执行射击任务的分队。', 13);
INSERT INTO `t_military_term_data` VALUES ('4531d504-09ee-4600-8641-12eef7d70b26', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '泄密', '泄漏秘密的简称。违反保密规定,泄漏秘密信息。', 77);
INSERT INTO `t_military_term_data` VALUES ('453fd418-efcf-4465-bb47-8c1fd0cfce27', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击安全界', '步炮、坦炮协同作战时规定的步兵、坦克距炮兵射击目标边缘的最小距离。根据射击诸元的精度、射击距离、射弹散布、炮弹效力和是否进行空炸射击、跳弹射击,以及步兵、坦克隐蔽程度等确定。', 216);
INSERT INTO `t_military_term_data` VALUES ('4553a981-7514-4714-87c2-eae56265906e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队航行序列', '舰艇编队在航行中,各舰艇群的配置和航行次序的排列。', 73);
INSERT INTO `t_military_term_data` VALUES ('45699c48-0c26-43a5-a69e-7c504cb8fae8', '98df76fb-4b65-48ff-a56c-4db587327c79', '支前委员会', '战时由地方政府组建的支的领导机构。通常由地方政府领导人负责,政府和军队有关部门的负责人参加组成。', 41);
INSERT INTO `t_military_term_data` VALUES ('456ae8ca-8aa7-4b6d-a265-cff1ab63c6d5', '916997ee-6728-4c61-9b79-d96960b1dc86', '消除化学袭击后果', '遭敌化学武器袭击后,为减少损失而采取的防护措施。主要包括：迅速查明染毒情况,对中毒人员进行抢救和后送治疗、对染毒人员。武器装备及重要地域、道路进行消毒,对染毒粮袜、饮水进行检验和卫生处理等。', 66);
INSERT INTO `t_military_term_data` VALUES ('456f3f79-309f-4790-bcf0-20d930f44b2c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '发射区', '航天器发射场内用于航天器、运载火箭发射前准备和实施发射的专门区域。发射场内可设一至数个发射区。主要设施有：发射装置（包括发射台、发射塔、勤务塔）发射控制中心。加注、供气、供电、供水、消防、瞄准、摄影。电视等系统,以及废液处理设施和避雷装置等。', 246);
INSERT INTO `t_military_term_data` VALUES ('45771a82-d050-46cb-8d10-6738c15ae17d', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天医学工程', '研究载人航天活动对人体影响的规律,结合航天工程寻找可靠的防护措施,设计合理的人工环境,研究先进的辅助机器,以解决载人航天中的生命安全、生活条件和工作效率的综合性技术科学。是航天医学和航天工程相结合的产物,载人航天工程的重要组成部分。', 290);
INSERT INTO `t_military_term_data` VALUES ('458593ca-2274-47a0-a804-823c4dfe8170', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '航天摄影测量', '利用航天摄影获取的图像信息进行分析、判释和量测,确定所摄物体的形状、大小、空间位置及其性质的技术。不受地域、国界限制,用于无控制地区的目标定位和地形测绘。', 243);
INSERT INTO `t_military_term_data` VALUES ('458d03da-4485-485b-8815-89cad35aa0d2', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通战备', '为保障战时交通畅通而进行的准备。是国防建设的组成部分。主要包括：规划、建设交通网路和设施,拟制交通保障计划、方案,组建、培训交通保障队伍,筹措、储备交通保障物资,建立、健全响关法规、开展交通战备训练和科研活动等。', 279);
INSERT INTO `t_military_term_data` VALUES ('459e7557-8d8b-48f9-8d99-f29b3b77b064', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术地幅', '战斗部署及战斗活动所涉及的空间范围。其大小取决于进行战斗的兵力、任务、地形等情况。', 36);
INSERT INTO `t_military_term_data` VALUES ('45a65aa1-6e43-4274-b5da-b82cc4908700', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火护送', '炮兵为掩护步兵、坦克向敌纵深发展进攻在其冲击的正面或翼侧的预定地段上对敌实施的火力突击。通常在炮火支援结束时开始到进攻部队完成后续任务时结束。', 69);
INSERT INTO `t_military_term_data` VALUES ('45abfd6c-dc7c-41ab-96bb-f805d6fa0955', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '后方', '①亦称大后方。战时前线和敌占区以外的全部国土。②军队的后方地域和所设的机构。', 295);
INSERT INTO `t_military_term_data` VALUES ('45b7063a-bf6c-4ccc-a11d-6d2f296e1770', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵气象车', '遂行防空兵气象保障任务的专用车辆。装有地面和高空气象观测和探测仪器、播发气象通报的设备以及附属器材等。与测风雷达结合,组成全天候的防空兵气象探测系统。', 124);
INSERT INTO `t_military_term_data` VALUES ('45b934f8-5048-4c4e-8065-843033f93793', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '粒子束武器', '利用接近光速的电子、质子、原子、离子等高能粒子流毁伤目标的武器。由能源、粒子加速器、聚焦控制器、瞄准跟踪系统等组成。是尚在研究试验中的武器。', 47);
INSERT INTO `t_military_term_data` VALUES ('45bb873c-91da-427d-8fef-59eac32b3265', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '仿真技术', '利用相似原理,以电子计算机为工具,对相关对象建立系统模型,并对其进行实验研究的技术。系统模型有物理模型、数学模型和物理-数学模型。与之相对应的有物理仿真（实物仿真）、数学仿真（计算机仿真）和半物理仿真（半实物仿真）。是作战模拟和武器系统研制的重要技术方法和手段。', 32);
INSERT INTO `t_military_term_data` VALUES ('45c8733e-4c94-4f4b-9b55-50396e10658d', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象侦察', '亦称大气侦察。为获取作战或其他军事活动所需气象情报而进行的侦察。主要使用气象卫星、飞机、舰船、自动气象站、空飘气球、气象雷达等或派出地面气象分队进行。', 65);
INSERT INTO `t_military_term_data` VALUES ('45d56aee-6438-433b-af6d-c691843814e4', '06a75831-13a1-4660-870a-455bb445336a', '无线电集群通信系统', '简称集群系统。多个用户（部门）共用一组无线电信道的移动通信系统。由交换（控制）中心、基地台、调度台和移动台等组成。能自动选择、动态分配信道，信道利用率高,接续时间短。', 171);
INSERT INTO `t_military_term_data` VALUES ('45d86e85-01dc-42b5-8b2d-ac7b1773e614', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵火力密度', '在一定时间内落达单体面积内的炮弹数。通常用发／公顷表示。', 100);
INSERT INTO `t_military_term_data` VALUES ('45d99aad-9841-4288-bde3-a085be088f73', '06a75831-13a1-4660-870a-455bb445336a', '卫星通信', '利用人造地球卫星作为中间站转发信号的无线电通信。卫星通信系统主要由通信卫星、跟踪遥测指令站和卫星通信地球站等组成。可传输电话、电报、数据和图像。通信覆盖面积广,传输质量高,可以传输几千路甚至上万路电话。', 113);
INSERT INTO `t_military_term_data` VALUES ('45de707d-adc5-41ba-9ec4-6947d3d0f1ae', '878651de-adf5-4c72-9376-9c363b893ff8', '军种战略', '筹划和指导军种的建设与运用的方略。', 49);
INSERT INTO `t_military_term_data` VALUES ('45e7f8db-807d-4e58-a3ff-721b0cce80cf', '06a75831-13a1-4660-870a-455bb445336a', '地下通信', '收、发信设备及其天线全部设置在地下的无线电通信。传递信息隐蔽,抗毁性强。常用于地下指挥所之间、导弹发射井与地下指挥控制中心之间的通信。', 117);
INSERT INTO `t_military_term_data` VALUES ('45ec475c-6ef6-4f59-8fc0-43acd3b41f0d', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦听员', '担负无线电侦听任务的专业人员。', 83);
INSERT INTO `t_military_term_data` VALUES ('45f62c9b-befe-4f90-8250-2da009c69cb9', '97a19170-bfac-42c5-9906-1acb187f0654', '空军专用后勤装备', '空军为实施后勤保障而编配的专用机械、车辆、设备、器材等的统称。主要包括航空兵飞行用的供电和供气设备,机场勤务设备,油料设备,卫生设备,航空装备，地空导弹武器系统和雷达的仓储、修理设备,空降、空投物资专用设备等。', 400);
INSERT INTO `t_military_term_data` VALUES ('45fb5ef5-619c-4649-a939-9b01d51ebbc6', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹跟踪照射雷达', '无线电半主动寻的地空导弹武器系统的制导雷达。可发射脉冲波和连续波两种无线电信号。在捕获、跟踪、测定目标坐标时发射脉冲波；在为导弹寻的头提供跟踪源时发射连续波。', 34);
INSERT INTO `t_military_term_data` VALUES ('45fb79d7-04da-4a27-9485-7ddbe1aa5c4d', '98df76fb-4b65-48ff-a56c-4db587327c79', '汽车驾驶员训练', '对汽车驾驶员进行的以专业知识和技能为主要内容的训练。分为新训和复训。', 318);
INSERT INTO `t_military_term_data` VALUES ('4602bc3c-08e8-4b11-897a-4662717c70fc', '98df76fb-4b65-48ff-a56c-4db587327c79', '分级救治', '亦称阶梯治疗。军队各级救治机构分工救治伤病员的基本组织形式和工作制度。目的是将伤病员的救治全过程从时间、空间、救治任务和范围上加以合理区分,以实施连续不间断的继承性治疗。', 193);
INSERT INTO `t_military_term_data` VALUES ('460f5ac9-b202-4a12-a09b-9096e0472b2d', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机起飞距离', '飞机从开始滑跑到离地升空至一定高度（通常为15米或25米）所经过的水平距离。起飞距离与飞机的起飞重量、发动机推力与工作状态、机场标高、跑道状况、气象条件等有关。', 304);
INSERT INTO `t_military_term_data` VALUES ('461031f7-a52c-4494-879f-9f3fdba28e4d', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹推进剂加注设备', '转注、储存、加注和泄出液体导弹推进剂所用的地面设备。分为机动加注设备和固定加注设备。', 64);
INSERT INTO `t_military_term_data` VALUES ('461223b4-2991-478c-b004-10f7eb914184', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化保障指示', '为组织实施防化保障向所属部队和分队下达的指示。是指导部队和分队对核、化学、生物武器防护的战斗文书。主要包括：敌可能使用核、化学、生物武器的情况,部队和分队的防护任务和要求,防化专业分队的保障任务和器材保障等。', 17);
INSERT INTO `t_military_term_data` VALUES ('46134b28-7ad0-4074-bab3-1a8b61fe16b1', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '党委统一的集体领导下的首长分工负责制', '中国人民解放军中党的各级委员会对部队实行的统一领导和集体领导与军政主官分工负责相结合的领导制度。是中国共产党对中国人民解放军实施领导的根本制度。', 17);
INSERT INTO `t_military_term_data` VALUES ('4625c3fc-427e-4e32-823f-92e759e3c83b', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '原件修理', '对武器装备进行不更换其零部件的修理。相对于换件修理而言。', 122);
INSERT INTO `t_military_term_data` VALUES ('4627ec5f-f1a6-4b99-a106-a119e040e89d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '转属', '亦称转隶。将原配属给某单位的兵力兵器转而配属给其他单位。', 325);
INSERT INTO `t_military_term_data` VALUES ('46390446-ccae-4698-93ca-9df2ae787122', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克输送', '利用各种输送工具运送坦克的行动。有铁路输送、水路输送、空中输送和公路输送等方式。坦克公路输送亦称坦克运输车输送,是坦克实施较远距离机动时采取的主要输送方式。', 65);
INSERT INTO `t_military_term_data` VALUES ('463c5b8d-e768-4925-9f8f-f193bcfc0e68', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡口', '由两岸进出路和渡河设备构成,供渡河用的工程设施。是渡场的主要组成部分。', 312);
INSERT INTO `t_military_term_data` VALUES ('463d1dc2-48f8-4f20-8ad6-553ffe71f686', '916997ee-6728-4c61-9b79-d96960b1dc86', '三防', '对核、化学、生物武器防护的简称。军队为避免或减轻核、化学、生物武器的毁伤而进行的防护。目的是最大限度地减少损伤,保持部队的战斗力和重要目标的生存能力。', 14);
INSERT INTO `t_military_term_data` VALUES ('4641002e-638f-4923-adf9-d49697981761', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '远程导弹', '射程为 3000～8000公里的导弹。', 6);
INSERT INTO `t_military_term_data` VALUES ('465e2154-3a85-4316-9685-bc51990f0d3e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防步兵障碍物', '能阻止或迟滞敌人徒步行动的人工障碍物。如防步兵地雷场、铁丝网、染毒区、沾染区、电网、竹签桩、陷阱、拒马、刺钉、鹿砦等。', 102);
INSERT INTO `t_military_term_data` VALUES ('46698b87-70aa-44c0-9c78-1ad9b44871e5', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克徒涉', '坦克不用任何辅助设备和器材,以涉水方式通过江河障碍的行动。可在河底坚实和水浅的河段上实施。', 63);
INSERT INTO `t_military_term_data` VALUES ('46719ad1-5b56-4b64-9292-48844c737c4f', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军事训练中政治工作', '中国人民解放军在军事训练中进行的思想工作和组织工作。主要内容包括：结合训练任务进行的马克思主义战争观、军队职能和形势战备教育,宣传贯彻毛泽东军事思想、邓小平新时期军队建设思想和中央军委的战略方针,搞好思想动员和宣传鼓动,发扬军事民主,激发练兵热情等。', 32);
INSERT INTO `t_military_term_data` VALUES ('4674dcac-4311-4a77-bb44-ca582f607a54', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '拒马', '用木、竹、型钢或钢筋混凝土杆件等交叉连接制成马和防登陆工具拒马；按形状,分为矩形拒马、菱形拒马和三角形拒马。', 127);
INSERT INTO `t_military_term_data` VALUES ('467f83f0-7631-47d5-8e7c-367d4d163339', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军民一致', '中国人民解放军和人民群众在根本利益与奋斗目标上一致的原则。是中国人民解放军正确处理军民关系的准则。主要内容包括：履行全心全意为人民服务的宗旨,拥护地方党委和政府,热爱人民群众,遵守国家的法律法规和军队的群众纪律,密切军政军民关系,巩固和发展军政军民团结。', 13);
INSERT INTO `t_military_term_data` VALUES ('4683681b-53b1-4639-be55-016028ac9a33', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '伤残等级', '对革命伤残军人依据其伤残程度和丧失劳动能力及影响生活能力的程度划分的伤残级别。主要有：特等；一等：二等甲级,二等乙级；三等甲级,三等乙级。其中因病评残仅限于在服役期间患病致残的义务兵,其等级有一等,二等甲级,二等乙级。', 76);
INSERT INTO `t_military_term_data` VALUES ('468b5bb5-224f-4464-9b35-48e1f6c776c9', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '定点捕获', '使进入准同步轨道的卫星漂移到预定的地理经度的赤道上空定点的过程。主要是利用卫星上携带的小发动机逐步修正其运行轨道,使其逼近静止轨道,最后使卫星停止漂移。', 264);
INSERT INTO `t_military_term_data` VALUES ('469b1218-987a-4937-a644-1d378f365d90', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射弹冲击波效力', '射弹爆炸瞬间,从爆心向四周传播的高温、高压、高速气浪对建筑物、装备、人员等目标造成的毁伤能力。其大小与爆炸装药、目标特性、目标与爆心距离等有关。', 119);
INSERT INTO `t_military_term_data` VALUES ('46b2c4c7-4799-43e0-8150-73a38169ff02', 'f0140091-c11a-48c9-8836-8aa94439dac0', '阻滞', '亦称迟滞。以阻击、袭击、设障等手段迫使敌人停滞不前或行动迟缓的战斗行动。', 249);
INSERT INTO `t_military_term_data` VALUES ('46c023b1-c919-46b1-bb68-e0d1ae62cfa3', '97a19170-bfac-42c5-9906-1acb187f0654', '空降场', '用于空降部队或空降人员伞降或机降着陆的场地。空降场一般应具备的条件是：靠近预定夺取的目标；附近无敌集结的部队,特别是无装甲兵部队；敌地面防御和防空火力薄弱；场内无妨碍着陆的障碍物；有足够的面积,便于空中识别等。', 163);
INSERT INTO `t_military_term_data` VALUES ('46c0f2a9-c06f-47b0-9bc2-43ef5e2fe80f', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', 'C3I系统工程', '运用系统工程的理论和方法对军队的指挥、控制、通信、情报系统进行建设和应用的工程技术。', 37);
INSERT INTO `t_military_term_data` VALUES ('46c6206b-2b5a-46b3-94de-ba985ba22859', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程作业', '部队完成工程任务的活动。如构筑工事、修筑道路、架设桥梁、开设渡场和设置及排除障碍物等。', 28);
INSERT INTO `t_military_term_data` VALUES ('46c80291-7400-4b98-abcc-e7cd8d2552ee', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '勋章', '国家授予有功勋人员的荣誉证章。中华人民共和国勋章出全国人民代表大会常务委员会颁发,国家卞席授予。1955年2月12日,中华人民共和国全国人民代表大会常务委员会作出决议并颁发条例,决定对中国人民解放军在土地革命战争时期、抗日战争时期和解放战争时期参加革命战争的有功人员,分别授予八一勋章、独立自由勋章、解放勋章。每种勋章分一、二、三级。', 64);
INSERT INTO `t_military_term_data` VALUES ('46cbc6b3-0c57-43bb-a5f3-1670d96f2600', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核武器杀伤破坏效应', '亦称毁伤效应。核武器爆炸产生的各种杀伤破坏因素对人员和物体造成的毁伤作用及效果。造成杀伤破坏的主要因素有：冲击波、光（热）辐射、早期核辐射、放射性沾染和电磁脉冲等。前三种因素的作用时间都在几十秒之内；电磁脉冲的作用时间不超过几百微秒；放射性沾染的作用时间可持续几天,甚至更长的时间。', 155);
INSERT INTO `t_military_term_data` VALUES ('46cc9978-2c5c-4363-9d54-9d005a8718a2', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '审时度势', '指挥员及其指挥机关认真观察思考和研究当时的情况,正确分析判断所处的形势', 30);
INSERT INTO `t_military_term_data` VALUES ('46d980b5-0918-4fba-ac3c-df92bc0fd7ac', '06a75831-13a1-4660-870a-455bb445336a', '电报通信', '利用电信号传输书面信息的通信。分为编码电报通信、汉字电报通信和传真电报通信。', 136);
INSERT INTO `t_military_term_data` VALUES ('46e88277-c2e6-4796-aa84-02165d000e3a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '溶洞', '地下水对可溶岩的溶蚀所形成的地下空洞。分为水平溶洞和垂直溶洞。大的溶洞军事上可加以利用。', 32);
INSERT INTO `t_military_term_data` VALUES ('46e89183-aafd-4c23-b744-24fb1ed7d4a1', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹药安全跌落高度', '弹药自由坠落水泥地上,不会导致发火的最大高度。以保证运输装卸和使用的安全。', 125);
INSERT INTO `t_military_term_data` VALUES ('46e9d319-8f77-4403-a435-cb70afee06bc', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥活动', '指挥员及其指挥机关对所属部队实施指挥的思维及其行动、指挥活动的核心是定下决心和实现决心。', 15);
INSERT INTO `t_military_term_data` VALUES ('46f46cfb-5de3-417b-be00-f73efe2a0c04', '06a75831-13a1-4660-870a-455bb445336a', '双工通信', '通信双方同时收信和发信的工作方式。双方通常使用两个不同的频率工作；采用同频双工技术的,也可使用同一频率工作。', 54);
INSERT INTO `t_military_term_data` VALUES ('472dceb1-90eb-4052-b9b4-c0b2bdaf3365', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役保障', '战役军团为顺利遂行战役任务而采取的各项保证性措施与进行的相应活动的统称。主要包括：战役范围内的侦察情报、通信、电子防御、工程、伪装、气象、水文、交通和对核、化学、生物、燃烧武器袭击的防护等作战保障,以及后勤、技术、政治工作等保障。海军、空军、第二炮兵还有其特有的战役保障。', 45);
INSERT INTO `t_military_term_data` VALUES ('4764b879-dd1f-41ca-b44c-4af2fda99cb1', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '四有军人', '有理想、有道德、有文化、有纪律的革命军人。是中国人民解放军培育军人的目标和要求。', 105);
INSERT INTO `t_military_term_data` VALUES ('47707cfa-b75d-45b3-995b-01d8fb4fbe6c', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '现地勘察', '指挥员及有关人员在实地观察与研究敌情、地形和其他情况的活动。', 61);
INSERT INTO `t_military_term_data` VALUES ('479a0428-3874-412b-a429-321714a69629', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '攻潜', '海军反潜兵力对敌潜艇实施攻击的战斗行动。有水面舰艇攻潜、潜艇攻潜、海军航空兵攻潜和舰机协同攻潜等。', 94);
INSERT INTO `t_military_term_data` VALUES ('479b3741-b5d3-43bb-a9cd-82055f8c17b4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击条件修正量', '炮兵用以修正射击条件偏差对射弹飞行影响的各种修正量的统称。包括弹道、气象、地形等条件修正量。', 139);
INSERT INTO `t_military_term_data` VALUES ('479d823e-027c-469f-97f6-15b18a1f0ff4', 'f0140091-c11a-48c9-8836-8aa94439dac0', '反斜面阵地', '设置在高地背向敌方斜面上的阵地。用以隐蔽配置兵力兵器,乘敌翻越棱线、不便观察射击时,突然打击之。', 225);
INSERT INTO `t_military_term_data` VALUES ('47c2fa30-a261-45b0-970e-cc139b7a9f86', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹射程装定量', '装定在导弹射程控制仪器上的与瞄准射程相适应的有关数值。是导弹实现既定射程的控制数据。', 185);
INSERT INTO `t_military_term_data` VALUES ('47ca8115-1019-4995-adf8-4e1623fc013a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '竖井核试验', '将核装置和各种探测器吊置于大口径竖井底部,回填后实施核爆炸的封闭式地下核试验。竖井核试验不受地形限制,但难度较平洞核试验大。', 186);
INSERT INTO `t_military_term_data` VALUES ('47d649ba-ac73-4290-9637-d94ffb55971f', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克修复率', '在规定时间内修复坦克的台数与待修复坦克台数的比值。通常用百分比表示。是直接影响参战坦克数量的重要因素。', 200);
INSERT INTO `t_military_term_data` VALUES ('47d96f0d-28ba-4ab3-8a46-8a2cf687fb46', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地貌', '地表面自然起伏的形态。包括山地、丘陵、高原、平原、盆地等。对军事行动有一定影响。', 9);
INSERT INTO `t_military_term_data` VALUES ('47daff8c-2266-467f-adee-f535079e22a5', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事运筹学', '研究军事问题的定量分析及决策优化的理论和方法的学科。是军事学术的组成部分,属于综合性的新兴边缘学科。主要是通过运用数学模型、电子计算机技术和定量分析等方法,揭示各种军事系统的结构、功能及其运行规律,为科学地进行军事实践活动,合理利用资源,提高军事效益提供一定的理论依据。', 30);
INSERT INTO `t_military_term_data` VALUES ('47dbd800-d635-438c-b7dd-67a73748e60a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '敌情侦察', '对作战所需的敌军情况进行的侦察。主要查明敌人的作战企图、行动方向、作战编成、兵力部署、番号、装备等情况。', 21);
INSERT INTO `t_military_term_data` VALUES ('47e8afc0-d5fe-4fb3-9c06-c6ed87e6d40e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵夜视器材', '炮兵夜间进行战场观察、车辆驾驶和武器瞄准所用的器材。包括主动红外夜视仪、微光夜视仪和热像仪等。', 286);
INSERT INTO `t_military_term_data` VALUES ('47eb6f86-8674-482d-965e-251a81848b60', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '坑道工事', '构筑在山体内的暗挖式工事。由口部（包括头部和颈部）和主体两部分组成。一般都有两个以上口部。分为指挥所坑道、战斗坑道、屯兵坑道、交通坑道、救护所坑道、弹药物资坑道和特殊用途坑道等工事。', 52);
INSERT INTO `t_military_term_data` VALUES ('47ebe4df-3f71-4f73-b784-9cbcf5efc7bd', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '失利', '军队在作战中遭受严重损失,未能达成预期目的或打了败仗。', 375);
INSERT INTO `t_military_term_data` VALUES ('47f1336e-3638-4de3-8998-49aa12818053', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '支队', '①相当于师的军队一级组织。如中国人民解放军海军的舰艇支队。②作战时军队的一种临时编组。如先遣支队、侦察支队等。', 29);
INSERT INTO `t_military_term_data` VALUES ('47f7c4e5-9030-4b4f-9b9c-41bed6838d40', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防坦克障碍物', '能阻止或迟滞坦克和各种车辆行动的人工障碍物。如防坦克地雷场、防坦克壕、桩砦、拦障、陷阱、水障碍物、冰雪障碍物等。', 103);
INSERT INTO `t_military_term_data` VALUES ('480ba174-8a8a-4bb7-aabe-b99edd167ad0', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战模型', '模拟作战活动和作战环境等的军事模型。包括各种规模、样式的作战模型以及武器的作战运用模型等。', 168);
INSERT INTO `t_military_term_data` VALUES ('4810fce2-f1df-4437-98b5-280184b127f3', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '遥测系统', '能对相隔一定距离的被测对象进行测量、分析处理和显示记录的系统。通常由输入设备、数据传输设备和终端设备组成。广泛用于常规武器试验、飞机试验、核弹头试验、战略导弹与航天器飞行试验等。', 276);
INSERT INTO `t_military_term_data` VALUES ('4812a65e-6674-4ffd-b69c-ec52735a8b8c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮射导弹', '用火炮发射的导弹。导弹由炮弹发射药推出炮口后,弹内发动机点火工作并推动导弹飞行。', 36);
INSERT INTO `t_military_term_data` VALUES ('481415fc-5b2d-4158-a33f-dae55e812593', '8a761efd-50a6-4ac8-9913-b7d745104f82', '高射机枪', '战术技术性能主要满足对空中目标射击的机枪。亦可用以对付地面薄壁装甲目标和压制火力点。口径在12毫米以上,有效射程2000米,单管战斗射速60～150发／分。便携式为单管高射机枪,牵引式为多管联装高射机枪。', 172);
INSERT INTO `t_military_term_data` VALUES ('4818a5a1-05ec-430e-87b3-061347af1da7', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克潜渡装置', '安装在坦克上的用以潜渡的器材、设备和装置的统称。包括密封器材、进排气装置、救生设备和排水设备等。', 147);
INSERT INTO `t_military_term_data` VALUES ('481d3452-a078-435e-8910-3780f0d9d0a9', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '抚恤', '国家和社会对因战、因公负伤或因病致残的现役军人和牺牲、病故军人及其家属进行的物质上的优待帮助和精神上的褒扬抚慰。', 77);
INSERT INTO `t_military_term_data` VALUES ('481d7b20-2d49-4fb0-8489-8ec1e0c38c5e', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化部队', '主要担负防化保障任务的专业部队。包括核观测分队、防化侦察分队和洗消分队等。是军队对核、化学武器防护的主要技术力量。', 1);
INSERT INTO `t_military_term_data` VALUES ('4827049c-80a8-4282-ad3b-a145b78924b4', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天黑', '太阳中心点落至当地地平线下7度的时刻（约在日没后半小时）。天黑时刻随日期和地理位置的不同而异,其求算方法与天亮时刻相同。', 150);
INSERT INTO `t_military_term_data` VALUES ('4839b516-8fbc-404b-88f2-ecdb9c4eb5ab', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击死角', '亦称射击死界。在射击武器射程内,因地貌地物、弹道性能和武器性能限制而导致射击不到的区域。', 69);
INSERT INTO `t_military_term_data` VALUES ('484b93ad-ff57-4c1f-b77d-3cf60afe84a0', '98df76fb-4b65-48ff-a56c-4db587327c79', '倒运', '运输过程中因交通线路中断而改换运输工具进行中转,将被运的人员和物资越过受阻地段继续实施运输的一种应急措施。', 267);
INSERT INTO `t_military_term_data` VALUES ('484f57bb-dce6-4d4a-b0a6-3dd16359b438', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报传递', '亦称情报传输。情报和情报资料的传送工作。要求及时、准确、安全、保密。', 151);
INSERT INTO `t_military_term_data` VALUES ('48849143-c7e6-4d3d-8596-774236023275', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航海计划', '舰艇出航前对航线和航行时间进行的预先设计和绘算。主要包括：航线拟定,航区气象、海况预报,潮时、潮高和日月出没时间的计算,保证航行安全和实施航海的措施等。', 252);
INSERT INTO `t_military_term_data` VALUES ('4897df46-b44a-4ec7-addc-b96b07bb8f1e', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击目标选择', '挑选主要核打击目标及对其排序的工作。通常是按照作战意图、武器性能及所掌握的目标资料,对敌方众多目标进行全面分析、计算,对比多种打击方案,从中选取最佳打击目标并进行排序。', 166);
INSERT INTO `t_military_term_data` VALUES ('48a5eda1-5b6c-4d04-acdd-74ae54f244e9', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '潜听', '隐藏在敌人附近听其动静。通常在夜间或能见度不良情况下隐蔽地进行。', 45);
INSERT INTO `t_military_term_data` VALUES ('48a6210c-68c5-449b-9387-7ba657f1b91a', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气旋', '亦称低气压或低压。北半球水平气流呈逆时针（南半球呈顺时针）旋转的大气涡旋。在天气图上表现为闭合等值线包围的低气压区,其中心附近的气压低于四周。受气旋控制的地区,易产生云和降水,或大风、沙暴等天气。', 39);
INSERT INTO `t_military_term_data` VALUES ('48a9e0a0-bf5c-4f9a-86d6-76526aa21ed5', '97a19170-bfac-42c5-9906-1acb187f0654', '战术空降', '由战术兵团组织的为达成一定战术目的而在敌战术纵深实施的空降。主要任务是：夺取并扼守敌方战术纵深内的要点,阻止敌预备队的机动,割裂敌战斗部署,配合正面部队加速战斗进程等。', 152);
INSERT INTO `t_military_term_data` VALUES ('48aff964-d809-4a85-8780-cd654f98f45a', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '方面军战役', '亦称集团军群战役。由临时编成的方面军（集团军群）或相当于方面军（集团军群）的战役军团进行的战役。可在上级编成内实施,也可单独实施。', 11);
INSERT INTO `t_military_term_data` VALUES ('48b38479-9bc7-4c88-9baa-311df1e9c365', 'd7132c58-5df3-4b97-919f-58740148b9ca', '空情标图', '在远方情报图板和近方情报图板上标示空中情况的作业。包括标绘目标的性质、位置、批次、机型、架数、高度、航向、测定时间和干扰情况等。', 108);
INSERT INTO `t_military_term_data` VALUES ('48b51592-069c-41ca-8846-2c44ba419598', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '陆军战役', '由陆军战役军团单独组织实施的合同战役。', 9);
INSERT INTO `t_military_term_data` VALUES ('48c971dc-5938-4733-8ea1-afbd709a18eb', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '叛乱', '以分裂国家、推翻政权、制造社会混乱为目的的有组织的武装叛变行为。', 434);
INSERT INTO `t_military_term_data` VALUES ('48cd14a7-3607-4585-8202-35b68971290d', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机空中应急投放', '直升机在发生特殊情况和危及飞行安全时，将载运或吊挂的装备、物资等从空中紧急投掉的行动。', 27);
INSERT INTO `t_military_term_data` VALUES ('48e2e954-4407-4293-b1f0-999caa5f0e22', '97a19170-bfac-42c5-9906-1acb187f0654', '超低空飞行', '航空器在真实高度为100米（含）以下的飞行。', 230);
INSERT INTO `t_military_term_data` VALUES ('48f1ff2f-0677-43c8-9e89-c839079f015e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教导队', '轮训基层军官、培训班长或预提班长的专设训练机构。通常在集团军（军）、师、旅、独立团及相当级别单位的建制内设立。', 12);
INSERT INTO `t_military_term_data` VALUES ('48f393ca-4e8f-4098-9f2e-eeeeb4dc931f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击口令', '炮兵指挥员指挥射击的口述命令。包括开始口令、修正口令、更正口令、记录诸元口令和更新诸元口令等。', 165);
INSERT INTO `t_military_term_data` VALUES ('48fc61d7-8257-4812-b34a-dc4dc1e6f472', 'f0140091-c11a-48c9-8836-8aa94439dac0', '对预有准备防御之敌的进攻战斗', '对预先作好各项防御准备之敌实施的进攻战斗。包括对野战阵地防御之敌的进攻战斗、对坚固阵地防御之敌的进攻战斗和对要塞防御之敌的进攻战斗等。', 121);
INSERT INTO `t_military_term_data` VALUES ('48fe3a12-54c4-4dc2-815e-3a15b0d20875', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '轻便器材渡河', '部队借助舟、筏和徒步桥等实施的渡河。', 307);
INSERT INTO `t_military_term_data` VALUES ('491f0d69-efd6-40fd-8451-1c411514d1c3', '8a761efd-50a6-4ac8-9913-b7d745104f82', '攻坚弹', '专门用以近距离轰击水泥构件、砖石墙壁和土木工事等坚固目标的爆炸弹药。发射方式有枪械掷射和火箭发射等。', 212);
INSERT INTO `t_military_term_data` VALUES ('4945beaa-c1c9-40a0-8178-eeed1fa42e91', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡河地段', '部队在渡河地区内选定的用以开设渡场的河段。', 310);
INSERT INTO `t_military_term_data` VALUES ('494ec520-8880-4137-a731-788535b33abd', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击提前量', '对运动目标射击时瞄准点提前于目标运动前方的距离。提前量的大小,依据目标距离、运动速度、弹丸飞行时间和目标运动的角度等条件而定。', 61);
INSERT INTO `t_military_term_data` VALUES ('4955274f-7a90-4336-83d0-a54b5eb58359', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '卫星云图', '由气象卫星观测、接收系统获取的显示云层覆盖和地表特征的图片。分为可见光云图和红外云图。利用卫星云图可以及时、直观地掌握天气系统的演变过程,连续监视有关地区的天气变化。是一种重要的气象资料。', 79);
INSERT INTO `t_military_term_data` VALUES ('4956118b-acdb-4f3d-a483-3ada3fe85596', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '先训后补', '新兵入伍后先在专设训练机构集中训练,再补充到各建制单位。', 52);
INSERT INTO `t_military_term_data` VALUES ('4960a1e1-eed6-4403-9f35-b088d0247399', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '警报传递演习', '由上而下传递警报信号的演习。目的是检验警报系统战备状况及其设备的完好性和灵敏性。', 120);
INSERT INTO `t_military_term_data` VALUES ('49610810-f647-4777-8769-eebf6a25e20a', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵射击训练', '坦克及其他装甲车辆的乘员和载员为熟练使用武器,掌握射击理论和射击技能而进行的训练。', 70);
INSERT INTO `t_military_term_data` VALUES ('49610ffb-2ff8-442d-a92b-d317bbc7d089', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '拦障', '以木、竹、钢材和砖石构成的栏栅式或墙壁式筑城障碍物。主要用于防坦克。通常构筑在隘路、林中界道、城市街道等坦克难以迂回的地段。', 123);
INSERT INTO `t_military_term_data` VALUES ('49674e54-72ad-4839-b7ca-052a324bdc6a', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '计算机安全', '计算机系统的硬件、软件和数据未遭破坏、更改与被窃，整体系统得以正常运行的状况。是实施军队指挥自动化和武器系统控制自动化的重要保障。在管理和技术上的安全措施,包括防窃密、防破坏、防计算机病毒等。', 66);
INSERT INTO `t_military_term_data` VALUES ('496f9d87-6464-4297-99f9-6feaf9d2e08c', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战场侦察雷达', '探测地面活动目标的雷达。用以搜索、监视处于运动状态的人员、车辆、坦克等目标,并测定其方位、距离和运动路线等参数。现代的战场侦察雷达还可探测低空、低速飞行目标。', 122);
INSERT INTO `t_military_term_data` VALUES ('497e1330-b3e9-4864-99f1-65376234107b', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵战备等级', '对防空兵战斗准备程度划分的级别。包括防空兵指挥所战斗准备等级和防空兵部队战斗准备等级。如一等战备、二等战备。', 94);
INSERT INTO `t_military_term_data` VALUES ('49826da1-7d85-48b9-83a3-3ec273643491', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇停泊场', '供舰艇安全停泊的水域。分为遮蔽停泊场和敞开停泊场。用于舰艇等待靠泊码头或出海,进行补给、装卸作业、维修等；有的还兼作锚地。通常建有系泊、导航、防护等设施。', 387);
INSERT INTO `t_military_term_data` VALUES ('499714cb-618a-4f20-9513-83eb289d1cf9', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '红外扫描仪', '亦称红外扫描相机。采用一维扫描并由载体飞行完成另一维扫描的红外成像装置。由行扫描器、光学系统、红外探测器、信息处理和记录等部分组成。一般装在卫星和飞机上用于航天和航空侦察。', 81);
INSERT INTO `t_military_term_data` VALUES ('499f5929-7468-473b-905b-9681d579179b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军用地图', '为军事需要而制作的各种地图。包括军用地形图、海图、航空图和各种专门用图。可供指挥员和指挥机关分析利用地形、组织指挥作战,以及为火炮、导弹发射和舰艇、飞机导航等提供地形资料和数据。', 259);
INSERT INTO `t_military_term_data` VALUES ('49a6eee4-75ba-47a6-b619-978180303be4', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火器机动', '战斗中火器由某一发射阵地向另一发射阵地的转移。', 107);
INSERT INTO `t_military_term_data` VALUES ('49a99997-a3d0-4a5f-bd22-1f5219390718', 'd7132c58-5df3-4b97-919f-58740148b9ca', '正常炸点群', '齐射炸点对称地出现在目标周围,半数以上在以目标为中心、一定的密位为半径的园内,且远近弹数概略相等,平均炸点的距离偏差不超过某规定数值的炸点群。', 187);
INSERT INTO `t_military_term_data` VALUES ('49be9968-c9a2-4f90-a321-1aae72eed6a5', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方工程', '为保障军队后方机构能够开展工作和实施有效防护而构筑的各种军事工程建筑、设施的统称。主要包括：洞库、桥梁、道路、隧道、码头、机场,以及准备用于配置医院、修理所、修理厂、指挥所和其他机构的各种地下工程和坑道工事等。', 36);
INSERT INTO `t_military_term_data` VALUES ('49c58be2-f7e0-437a-b9cb-035bc1c04681', '98df76fb-4b65-48ff-a56c-4db587327c79', '战略储备', '为保障战略行动和重点支援的需要而进行的物资储备。通常由国家有关部门和军队最高领导机关负责筹建和掌握。', 111);
INSERT INTO `t_military_term_data` VALUES ('49ca0e6d-46fc-4123-8b0c-42d3f71243f6', '83e065b4-6737-4645-9ea5-8276d1de13ed', '基准排', '坦克连冲击或装甲步兵连乘车冲击时,为保持冲击方向而指定的、起导向作用的坦克排或装甲步兵排。', 33);
INSERT INTO `t_military_term_data` VALUES ('49d4ec4c-70f0-411d-b2df-98329365a515', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '掩盖遮障', '周边与地面相连,能全部遮盖目标的人工遮障。根据目标所处的地形，可设置成凸面、平面、凹面等形式。', 347);
INSERT INTO `t_military_term_data` VALUES ('49ebee39-8177-4fbb-b34f-ff8be3aaf89b', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '模拟训练', '运用计算机及仿真设备、器材,模仿武器装备性能、战场景况、作战行动等进行的训练。', 157);
INSERT INTO `t_military_term_data` VALUES ('49ee74a7-4122-4080-bc1f-b1bb91bcf98c', '916997ee-6728-4c61-9b79-d96960b1dc86', '野战化验车', '野战条件下分析化验毒剂和测定放射性活度的专用车辆。主要用以化验染毒样品,确定毒剂种类、染毒程度,测定空气、粮秣、水样品的放射性活度。还可用以测定消毒效果及消毒剂质量。', 168);
INSERT INTO `t_military_term_data` VALUES ('49f6cfd2-e123-4cf9-9174-74b80dad151f', '06a75831-13a1-4660-870a-455bb445336a', '可视电话机', '在通话的同时能看到对方图像的电话机。有窄带和宽带两种。窄带占用一个话路,只显示静态图像。宽带占用数十至数百个话路,可显示动态图像。由摄像机、显像机、控制器和电话机等组成。', 199);
INSERT INTO `t_military_term_data` VALUES ('4a03b4a3-8ff1-416e-bc17-d536a96ccb05', '06a75831-13a1-4660-870a-455bb445336a', '抢通', '通信设备发生故障时为及时沟通联络而采取的应急措施。方法有倒通、代通和跳通等。倒通是以备用设备进行开通；代通是以代用设备替换故障设备；跳通是跳过设备中有故障的部分临时连通。', 57);
INSERT INTO `t_military_term_data` VALUES ('4a05f655-8487-4680-857d-bddc3e0d09bb', '06a75831-13a1-4660-870a-455bb445336a', '短波自适应通信系统', '采用实时信道估值技术,并具有实时选频、自动建立线路等功能的短波通信系统。能把信道的实时探测、评估、选频、换频与通信线路的建立等功能结合起来,实现通信过程的全自动化,改善短波通信的质量。', 103);
INSERT INTO `t_military_term_data` VALUES ('4a17f9a4-76c3-44f4-8607-ce292987dda8', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '航空天气预报', '对有关航站、航线和空域未来一定时段内的天气状况所作的预报。预报内容包括：云量、云状、云高和云厚,地面和空中的风向、风速、气温、能见度,降水、雷暴等天气现象,以及飞机积冰和飞机颠簸的强度等。预报时效以2～6小时和12～24小时为主。对危及飞行安全的危险天气需及时发布警报和通报。', 76);
INSERT INTO `t_military_term_data` VALUES ('4a3d23c6-fb1d-4987-aab2-85441c351639', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹扇形配置', '以敌机主要来袭方向为对称轴,将地空导弹分队、兵器呈扇状展开所作的配置。', 24);
INSERT INTO `t_military_term_data` VALUES ('4a438839-7192-4e1c-9a49-f51d519eaf14', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '排水量', '舰艇在静水中船体入水部分所排开的水的重量。是舰艇战术技术性能要素之一。水面舰艇排水量,分为空载排水量、标准排水量、正常排水量、满载排水量、最大排水量；潜艇排水量,分为水上排水量和水下排水量。通常以吨为计量单位。', 323);
INSERT INTO `t_military_term_data` VALUES ('4a4b0bcf-18f0-4233-a24a-76fb4003ba6a', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '伪装网', '空网上面缀有伪装饰片的伪装器材。按用途和性能,分为防光学伪装网、防雷达伪装网、防热红外伪装网、多谱伪装网以及其他专用伪装网等；按适用的背景,分为林地型、草原型、荒漠型、雪地型等伪装网。', 352);
INSERT INTO `t_military_term_data` VALUES ('4a51d710-c3d7-45e9-bee1-84ff2c657809', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '地雷场准备等级', '对地雷场战斗状态划分的等级。分为一级准备和二级准备。一级准备是地雷场中的通路已封闭,护栏已撤收,地雷全部处于战斗状态。二级准备是地雷场已设置完毕,但通路未封闭,护栏未撤收,操纵地雷处于安全状态。', 191);
INSERT INTO `t_military_term_data` VALUES ('4a555a19-3acd-49f3-b144-94e91bfe11d9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防护力', '有生力量、武器装备、技术器材等所具有的抵御敌杀伤、破坏和恶劣自然条件侵害的能力。', 273);
INSERT INTO `t_military_term_data` VALUES ('4a6aa45d-446a-4dfa-83cb-d66a3390c690', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役方向', '战役军团遂行作战任务的行动方向。分为主要战役方向和次要战役方向。', 29);
INSERT INTO `t_military_term_data` VALUES ('4a6e6516-fc29-4cc1-8e06-fc69c75d5d48', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克原地射击', '坦克在预先占领的发射阵地上或在运动中停顿较长时间进行的射击。', 56);
INSERT INTO `t_military_term_data` VALUES ('4a718ba3-0b73-4258-af20-db4284fe8a29', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机团编队', ' 2～3个直升机大队编队按规定组成的空中编队。', 36);
INSERT INTO `t_military_term_data` VALUES ('4a7cde22-36ec-4bbf-aea8-29b5f300147e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥效能评估', '对指挥系统在实施指挥活动中发挥作用的有效程度的评析和估量。', 191);
INSERT INTO `t_military_term_data` VALUES ('4a878e64-a852-4eb3-b9ce-b20d624640a3', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '空中侦察', '使用有侦察设备的航空器和航天器,在大气层和外层空间进行的侦察。分为航空侦察和航天侦察。', 30);
INSERT INTO `t_military_term_data` VALUES ('4a8b4c77-3e9c-4de2-b096-9bbdc83a77f0', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '行星', '在椭园轨道上环绕恒星运行的近似球形的大体。其本身不发射可见光,而以表面反射恒星光而发亮。太阳系有九大行星,按距离太阳由近到远的次序,为水星、金星、地球、火星、木星、土星、天王星、海王星和冥王星。', 187);
INSERT INTO `t_military_term_data` VALUES ('4a8d6812-bbd8-426f-a0d0-4ec42ed8776e', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军事检察工作', '中国人民解放军和中国人民武装警察部队的检察机关依法开展的法律监督工作。通过行使检察权,保障国家宪法、法律和军事法规的正确实施,维护统一的社会主义法制。', 133);
INSERT INTO `t_military_term_data` VALUES ('4a995272-3bb7-436f-ac5a-862406b86293', '98df76fb-4b65-48ff-a56c-4db587327c79', '急救包', '包扎伤口用的制式无菌卫生材料包。用防潮材料密封包装,经压缩灭菌而成。主要有三角巾急救包、绷带急救包等。', 221);
INSERT INTO `t_military_term_data` VALUES ('4aa932e0-2cb3-426d-b49f-2fa1c48aeb46', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '缩微地图', '利用缩微技术将地图高倍率缩摄于感光片上的微型化地图。体积小,便于携带,可进行快速检索、屏幕显示与放大复印。战时可用野战制印设备放大复印。', 257);
INSERT INTO `t_military_term_data` VALUES ('4ab87f13-dd03-49f7-9b1c-d918780dff75', '06a75831-13a1-4660-870a-455bb445336a', '海底电缆通信', '利用海底电缆作为传输媒介的有线电通信。通常用于岛屿间、大陆与岛屿间以及跨越海洋的有线电通信。通信容量较大,传输性能稳定,但施工与维修较困难。', 126);
INSERT INTO `t_military_term_data` VALUES ('4ac24920-b289-49ef-b880-ae229ac45ffd', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队', '由两艘以上舰艇或两个以上海上战术群组成的兵力编组。分为建制舰艇编队和临时舰艇编队。建制舰艇编队通常由同类型的舰艇组成；临时舰艇编队根据任务由不同建制和不同类型的舰艇组成。', 61);
INSERT INTO `t_military_term_data` VALUES ('4ace0877-8816-457f-9afb-4909177f6b9d', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物战剂检验', '对可疑为生物战剂的病原微生物或细菌毒素进行的鉴别和检出的技术措施。包括标本收集和处理、初步检验、纯种鉴定等。主要为组织消除生物武器袭击后果提供依据。', 144);
INSERT INTO `t_military_term_data` VALUES ('4ade5dcd-4cd6-402d-972f-403651dcdaad', '916997ee-6728-4c61-9b79-d96960b1dc86', '光辐射烧伤', '光辐射作用于机体造成的损伤。核爆炸光辐射的直接作用会使人的眼睛、皮肤烧伤,还会引燃服装、建筑物等,对人造成间接烧伤；人员吸入辐照的空气或尘土,会造成呼吸道烧伤。', 108);
INSERT INTO `t_military_term_data` VALUES ('4ae9514b-12a4-4640-86c6-df65e5dec04c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '制式桥梁器材', '用以架设军用桥梁的工程装备。包括舟桥器材、机械化桥、拆装式金属桥、坦克架桥车等。', 271);
INSERT INTO `t_military_term_data` VALUES ('4af03287-a1df-466c-9271-6918f99acf50', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物战剂检验车', '用以检验生物战剂的专用车辆。可在野战条件下利用车上装备的器材和试剂,从生物战剂样品中检出和鉴别生物战剂的病原微生物或细菌毒素等。', 195);
INSERT INTO `t_military_term_data` VALUES ('4b15dce0-c40b-4f8b-9ab4-7a5f55059649', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '有控段弹道', '亦称续航弹道。反坦克导弹按控制指令飞行的一段弹道。导弹进入此段弹道,续航发动机启动,开始接受导引,转入有控飞行。', 268);
INSERT INTO `t_military_term_data` VALUES ('4b1b52f7-c2a2-46a7-9245-3338b897c866', '916997ee-6728-4c61-9b79-d96960b1dc86', '染毒浓度', '亦称毒剂浓度。染毒空气或染毒液体的单位体积内的毒剂重量。常用单位为毫克／升或微克／升。分为战斗浓度和安全浓度。战斗浓度又分为致死浓民半数致死浓度、伤害浓度、半数伤害浓度等。', 123);
INSERT INTO `t_military_term_data` VALUES ('4b4e6122-af84-4d8e-a79e-39866d2e8132', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '三一战术', '由三批直升机周而复始地轮番进行补给、航行、攻击的方法。即：一批直升机在基地进行油料、弹药补给,一批直升机在飞往战场的途中，一批直升机在战场对目标进行攻击。', 72);
INSERT INTO `t_military_term_data` VALUES ('4b4f975d-d3b3-408a-ad65-cf6e36930a9c', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '假设敌', '军事演习中由部队或分队、人员装扮的敌军。通常由适量人员利用模型、音响和发光器材等,模仿敌军,设置和显示敌情。有时还按照敌军编制装备组成假设的敌军部队或分队。', 138);
INSERT INTO `t_military_term_data` VALUES ('4b604b21-c8ba-4d0b-a1e0-a077ab1eaa0b', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '仪仗队', '军队中执行礼仪任务的分队。由陆、海、空三军人员共同组成,或由某一军种人员单独组成。执行任务时配有军乐队。通常用以迎送外国的国家元首、政府首脑或高级将领等,也用于隆重典礼或特别重要人物的殡葬仪式。', 69);
INSERT INTO `t_military_term_data` VALUES ('4b66f2a7-e3eb-4b67-a4b0-dce5fbad693d', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '穿云着陆', '直升机或飞机按规定的航线、数据穿越云层下降而进行的着陆。难度较大,通常要有地面指挥和导航设备引导。', 48);
INSERT INTO `t_military_term_data` VALUES ('4b6a5a6d-fece-47c6-ad74-01579efe91ff', '06a75831-13a1-4660-870a-455bb445336a', '通信兵', '①担负军事通信任务的兵种。由固定通信、野战通信、通信工程、指挥自动化、观通、导航、军邮等专业部队和分队组成。基本任务是：组织运用各种通信手段,保障军队的通信联络；建立和管理军队指挥自动化系统；组织实施观通、导航、军邮勤务等。②从事通信专业的士兵。', 0);
INSERT INTO `t_military_term_data` VALUES ('4b71a0c5-75b8-4852-aaf6-204908867b20', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '适宽射向', '将目标正面等分成与连内炮数相等的若干段,各炮射向分别对准每段目标中央所构成的射击方向。通常用于对幅员较大的目标射击。', 211);
INSERT INTO `t_military_term_data` VALUES ('4b77cc0b-f77b-4ef1-b1f8-0b446b39854c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '一次性使用电子干扰设备', '投放或预置到指定地域而不回收的电子干扰设备。有投掷式干扰机和摆放式干扰机等。通常用以干扰敌地面火控雷达、对空情报雷达和战术无线电通信等。', 125);
INSERT INTO `t_military_term_data` VALUES ('4b94150e-03de-4d59-980b-c947bd6a94d6', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天员', '亦称宇航员。在航天飞行中驾驶、管理、维修航天器,或从事科学实验、生产加工和军事活动的人员。', 291);
INSERT INTO `t_military_term_data` VALUES ('4b99065b-9cf5-4292-bfe0-9b816b9e5469', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '警备', '军队对驻防地区的警卫和守备。包括实行警卫、协助地方维持社会治安、维护军容风纪、保卫驻守地区的安全等。', 424);
INSERT INTO `t_military_term_data` VALUES ('4baddc70-98b3-4ea4-8fab-bef81c301f2e', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '兵役', '公民依照国家兵役制度履行的军事义务。分为现役和预备役。', 21);
INSERT INTO `t_military_term_data` VALUES ('4bb3469a-1daf-40a4-a3df-5b193f141250', '97a19170-bfac-42c5-9906-1acb187f0654', '空中袭扰', '航空兵部队以小编队或单机飞临敌方空域进行的空中袭击和扰乱活动。通常用以牵制、麻痹、消耗敌人。', 111);
INSERT INTO `t_military_term_data` VALUES ('4bb34983-5382-48d0-b1e6-330e4a386f00', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '宵禁', '在规定的夜间时间、区域内,禁止未经许可的人员、车辆通行和外出活动。通常是军事管制或戒严期间采取的一种措施。', 430);
INSERT INTO `t_military_term_data` VALUES ('4bb77abd-6e9e-4c81-b558-72a158fdb9c0', '31f4a446-5b98-4873-9d53-310d97125b07', '反导作战', '使用反弹道导弹武器将来袭弹道导弹摧毁在飞行中或使其失效的作战行动。', 35);
INSERT INTO `t_military_term_data` VALUES ('4bb98f3f-5170-4b25-9068-785fcd88b164', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵急促射', '火炮、火箭炮以规定的最大发射速度发射完规定数量的炮弹的发射方法。', 224);
INSERT INTO `t_military_term_data` VALUES ('4bbdad99-9bbb-4c82-afdf-625f010406e9', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物战剂污染区处理', '为防止敌生物武器袭击区传染病的发生和蔓延而采取的措施。主要包括：封锁污染区,对人员进行医学观察、隔离、治疗、免疫接种和药物预防,对污染区消毒、杀虫和灭鼠等。', 70);
INSERT INTO `t_military_term_data` VALUES ('4bc25a43-7025-4d0a-9574-d143bdc79c91', '916997ee-6728-4c61-9b79-d96960b1dc86', '三防技术', '核、化学、生物武器防护技术的简称。用于避免或减轻核、化学、生物武器毁伤效应的军事技术。主要包括；对核、化学、生物武器袭击的报警技术,侦察技术,防护技术,洗消技术和救治技术。', 83);
INSERT INTO `t_military_term_data` VALUES ('4bcaffd5-4ae5-469f-99f4-b086d4bcc57d', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '反击战役', '在防御态势下对进攻之敌进行主动攻击的战役。目的是挫败敌人的进攻,改善或恢复原防御态势。', 62);
INSERT INTO `t_military_term_data` VALUES ('4bcc86d1-fdcc-4c4d-90d1-ee151aed7f3e', 'd7132c58-5df3-4b97-919f-58740148b9ca', '便携式地空导弹尾追射击', '亦称尾追攻击。便携式地空导弹在空中目标飞过航路捷径后对其进行的射击。', 204);
INSERT INTO `t_military_term_data` VALUES ('4be140fa-0f3e-4701-90bc-7fa48855fadf', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '运行序列', '任部队在输送时各梯队的运行顺序和位置。', 85);
INSERT INTO `t_military_term_data` VALUES ('4be6cc35-7b00-4819-b7e1-2725720040a3', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '尔后行动方向', '进攻的军队完成后续任务后的行动方向。通常在赋予作战任务时或作战过程中加以明确,以便在完成任务后不停顿地行动。', 89);
INSERT INTO `t_military_term_data` VALUES ('4bf92970-22e2-47fe-83a6-27bc1d9c3fc7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '接合部', '作战中两支部队作战部署相连接的地方。通常为部署的薄弱部位。', 285);
INSERT INTO `t_military_term_data` VALUES ('4c0f1090-e971-460e-9ff2-fb620cde03a0', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '航天工业', '研制和生产外层空间的飞行器、空间设备、武器系统以及地面保障设备的工业。主要产品有战略导弹、运载火箭、空间飞行器及其地面和水面保障设备等。', 41);
INSERT INTO `t_military_term_data` VALUES ('4c1a00ac-1aff-41cd-9061-1c4237260e4f', '916997ee-6728-4c61-9b79-d96960b1dc86', '云迹区', '放射性烟云径迹地带沾染区的简称。在放射性烟云扩散飘移的路径上,从烟云中降落的放射性落下灰形成的沾染区。云迹区的大小取决于爆炸方式、爆炸威力、风向风速等因素。', 88);
INSERT INTO `t_military_term_data` VALUES ('4c1f1896-767f-4edf-98b2-6d6643ea4a34', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '航天侦察', '使用有侦察设备的航天器在外层空间进行的侦察。包括卫星侦察、空间站侦察、宇宙飞船侦察、航天飞机侦察等。', 31);
INSERT INTO `t_military_term_data` VALUES ('4c219b5d-c586-470a-8b30-e01c1248fc17', '97a19170-bfac-42c5-9906-1acb187f0654', '航空军械', '航空器上装备使用的各种武器、弹药及其瞄准、投射、控制设备的统称。包括航空机关炮。机枪和航空炸弹、火箭弹、导弹以及航空瞄准具、导弹发射架。火箭发射器等。', 308);
INSERT INTO `t_military_term_data` VALUES ('4c27c217-458e-4f8b-8103-72cc124e6730', '98df76fb-4b65-48ff-a56c-4db587327c79', '计价供应', '军队后勤机构按规定价格计价收费的物资供应。如国防施工、营建、生产用油,供应标准以外的制式被装,编外车辆及其维修器材等。通常采取计价收费（价拨）形式进行供应。', 91);
INSERT INTO `t_military_term_data` VALUES ('4c2b8545-c050-4d8c-959d-08b0bfc63745', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '电视技术', '使用电和光电转换的方法传送活动图像的技术。在军事上主要应用于侦察、制导和飞行导航等方面。', 22);
INSERT INTO `t_military_term_data` VALUES ('4c2d6a4b-800a-48f6-a60b-768709f72a76', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '冰雪障碍物', '利用冰雪构成的筑城障碍物。如雪垒、结冰斜面、冰窟、人工诱发的雪崩等。', 109);
INSERT INTO `t_military_term_data` VALUES ('4c47fdbf-fb21-4c92-bab5-009ed6bbe087', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹飞行主动段', '亦称动力飞行段。弹道导弹发射后在发动机工作期间飞行的一段弹道。导弹飞行主动段终点的弹道参数（速度、弹道倾角和关机点的坐标）,决定被动段弹道的特性（落点、射程、飞行时间等）。', 75);
INSERT INTO `t_military_term_data` VALUES ('4c5483fb-917e-4f64-b74c-44bc4401d1d0', 'f0140091-c11a-48c9-8836-8aa94439dac0', '敌火下运动', '在敌火力威胁下向敌前进或实施机动的行动。通常采用疏开队形或战斗队形。', 180);
INSERT INTO `t_military_term_data` VALUES ('4c5960c0-713c-4a12-aeba-977a064d9d3a', '916997ee-6728-4c61-9b79-d96960b1dc86', '失能性毒剂', '简称失能剂。能造成人员暂时失去正常的精神、躯体功能,以致丧失战斗力的毒剂。如毕兹等。施放后呈气溶胶状态,经呼吸道吸入机体引起中毒,产生口干、瞳孔散大、眩晕、丧失定向力和产生幻觉等症状。其作用可持续数小时至数天。', 222);
INSERT INTO `t_military_term_data` VALUES ('4c5ba91a-dd87-46ce-9124-610c36b78cae', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '路面器材', '用以在泥泞、松软地段快速构筑路面的工程器材。分为制式路面器材和就便路面器材。', 262);
INSERT INTO `t_military_term_data` VALUES ('4c5df9e7-8511-41f5-8368-7d09906dbac3', '97a19170-bfac-42c5-9906-1acb187f0654', '空中截击', '歼击机或歼击直升机对空中目标进行的拦截与攻击。', 69);
INSERT INTO `t_military_term_data` VALUES ('4c699352-81a5-4dfe-8c73-0a6e65bc156a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵暴露阵地', '无遮蔽物掩蔽,敌从地面观察能通视的炮阵地。', 62);
INSERT INTO `t_military_term_data` VALUES ('4c69e367-4a21-4753-afb4-da94e0d50dca', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '预警卫星', '亦称导弹预警卫星。用以监视、发现和跟踪敌方战略弹道导弹的发射及其主动段的飞行,并提供早期预警信息的侦察卫星。通常由多颗卫星组成预警网。一般可在敌弹道导弹袭击时,为己方争取到15～30分钟的预警时间。', 210);
INSERT INTO `t_military_term_data` VALUES ('4c6ee3a3-9b3a-4742-9d60-8267dace6f24', '97a19170-bfac-42c5-9906-1acb187f0654', '航空火力反准备', '航空兵部队为破坏敌地面部队的进攻,对发起进攻直前之敌实施的航空火力突击。通常与炮兵等火力反准备结合进行,也可单独进行。', 124);
INSERT INTO `t_military_term_data` VALUES ('4c709270-98ad-4041-b229-6f375e2de7da', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '山地气候', '地面起伏大、地形复杂的山区所形成的一种地方性气候。主要特征是：随着山脉的走向和坡向,以及山顶、山谷、盆地、隘口等局部地形的不同，气温、风、云、雾、降水等要素的差异较大。例如,在山脉的上部以昼雨为主,山谷、盆地底部则以夜雨为主。', 62);
INSERT INTO `t_military_term_data` VALUES ('4c7934b9-83c5-4f38-923b-fc43d4fc1bd0', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '推演', '在军事演习的实施中,按照训练问题的顺序和进程逐个地进行演练。', 137);
INSERT INTO `t_military_term_data` VALUES ('4c7d20e8-372e-4f41-b610-edd52618cbd9', '916997ee-6728-4c61-9b79-d96960b1dc86', '信号烟幕', '用于指示、识别目标和通信联络的烟幕。通常使用红、绿、黄、蓝等彩色烟幕。', 76);
INSERT INTO `t_military_term_data` VALUES ('4c7f2aeb-c68d-466d-86a1-f10ab6d98916', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '地段', '某一线状区域中的一段。其范围通常用两点表述。', 300);
INSERT INTO `t_military_term_data` VALUES ('4c8f04fa-464d-4014-9d41-135ecc638b11', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子进攻', '为破坏或阻止敌方有效使用其电子设备或系统而采取的行动。电子进攻任务通常由电子对抗兵承担。', 39);
INSERT INTO `t_military_term_data` VALUES ('4ca698c6-adb4-4376-8a31-d2f528172e39', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '混合潮', '不正规半日潮和不正规全日潮的统称。不正规半日潮是指在一个太阴日内有两次高潮和两次低潮,但两次高潮或低潮的潮高不等,涨潮时和落潮时也不等的潮汐。不正规全日潮是指在半个月内大多数时间出现不正规半日潮,少数几天在一个太阴日内出现一次高潮和一次低潮的潮汐。', 140);
INSERT INTO `t_military_term_data` VALUES ('4ccf4bd2-7c19-45bb-887b-49e1db59536f', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '回答式电子干扰', '简称回答式干扰。接收敌方电子设备发射的电磁信号，经过各种处理后再发射出去所形成的电子干扰。按干扰产生的方法,分为转发式干扰和应答式干扰。', 50);
INSERT INTO `t_military_term_data` VALUES ('4cd2283d-13f3-4d4d-8bf6-e6377ad10a63', '98df76fb-4b65-48ff-a56c-4db587327c79', '装（卸）载站', '供军队人员乘车、下车和物资装卸的铁路车站。分为基本装（卸）载站和预备装（卸）载站。要求有适于部队集结、疏散、隐蔽、防空、警戒的场地和进出站道路,有适于装卸的固定或移动站台及装卸设备等。', 272);
INSERT INTO `t_military_term_data` VALUES ('4cdada8c-c8c1-4e93-b3ad-5d189a1a45aa', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '奖状', '颁发给获奖单位和个人的奖励证书。', 69);
INSERT INTO `t_military_term_data` VALUES ('4cf00ef6-070f-47a9-ba50-8e7879509048', '06a75831-13a1-4660-870a-455bb445336a', '移动通信中心站（台）', '为双工移动用户进入地域通信网提供入口并能在移动用户间接转信息的通信站（台）。主要由无线电收发信机、接力机、交换机。保密机等组成。工作半径一般为15公里左右。', 65);
INSERT INTO `t_military_term_data` VALUES ('4cf1ac71-11c2-4e26-942d-859772facd65', '97a19170-bfac-42c5-9906-1acb187f0654', '航空宣传炸弹', '专门用以散发宣传品的航空炸弹。弹体内装有宣传品。被投掷后降至一定高度时,能在空爆引信作用下使弹体解体,宣传品散落。', 333);
INSERT INTO `t_military_term_data` VALUES ('4cfd8ccd-73ed-41d7-8af1-ab0850282551', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '寻的制导', '依靠弹上导引装置接收目标辐射或反射的能量（如红外、激光、无线电波）形成导引信号而自动导向目标的制导。分为主动寻的制导、半主动寻的制导和被动寻的制导。', 49);
INSERT INTO `t_military_term_data` VALUES ('4cfed1df-b82e-4c8d-835a-85023674f1a9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵区分火力', '炮兵指挥员及其指挥机关给所属的各单位分配火力任务。通常根据目标的性质、幅员、重要程度,对其毁伤要求,炮兵的数量,火炮性能,分队的射击能力,阵地位置和尔后的任务等因素进行分配。', 97);
INSERT INTO `t_military_term_data` VALUES ('4d006999-84c3-4ecf-97a0-66a39b70cb35', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役规模', '实施战役作战的兵力兵器数量和作战行动的空间范围。', 3);
INSERT INTO `t_military_term_data` VALUES ('4d0c10a1-b219-4093-ba17-81f45190629d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击指挥作业器材', '高炮部队或分队的指挥员及指挥分队实施射击指挥时使用的手工作业器材。包括标图器材和诸元测量器材。用以标绘空中目标活动情况和在空情标图板上测量目标诸元。', 103);
INSERT INTO `t_military_term_data` VALUES ('4d42703c-e80c-4b53-aed3-2875089d9c28', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器适应性', '轻武器对使用环境和使用者的适应性能。包括环境适应性、人类工效性和敌火下生存性。环境适应性指武器在各种气候下和各种地形上能正常操作使用。人类工效性指武器的人机接口尺寸得当、操作方式符合常人习惯、操作省力、射手感觉舒适等。敌火下生存性指武器的便于防护和隐蔽。', 225);
INSERT INTO `t_military_term_data` VALUES ('4d4dce09-13a1-4cbd-a53e-3d5f7dd2f593', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '观察地境', '观察所或观察哨负责观察的扇形区域。各观察所或观察哨观察地境的两侧要互相重叠,以消除视界死角。', 112);
INSERT INTO `t_military_term_data` VALUES ('4d501009-11d9-4ca1-b72c-6e3999b7a9b5', 'f0140091-c11a-48c9-8836-8aa94439dac0', '从行进间发起进攻', '在集结地域完成进攻准备后,于开进过程中逐级逐次展开战斗队形,不停顿或作短暂停顿即向敌人发起进攻的方式。是机械化部队采用的主要进攻方式。', 157);
INSERT INTO `t_military_term_data` VALUES ('4d748818-29c1-44c3-afb9-b528515e7c7f', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报处理自动化', '使用电子计算机及其配套技术设备进行情报处理。', 152);
INSERT INTO `t_military_term_data` VALUES ('4d75a384-4354-4f53-8a7e-1455e14507ed', '97a19170-bfac-42c5-9906-1acb187f0654', '指挥引导交接', '航空兵跨区遂行任务或原指挥所不宜对其继续指挥引导时,原指挥所与后继指挥所之间指挥引导任务的移交和接替。通常由上级指挥所组织,也可由双方指挥所直接协调完成。', 181);
INSERT INTO `t_military_term_data` VALUES ('4d80411f-a750-4c82-a2fe-ccc9718eeaa8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击地境', '防御战斗中直接瞄准射击的火炮、反坦克导弹等负责射击的扇形区域。通常分为基本射击地境和补加射击地境。', 215);
INSERT INTO `t_military_term_data` VALUES ('4d8128d6-ddc3-494a-bad7-0cbb3a9b1bd6', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '前出', '军队根据作战需要,离开原来位置向前方指定位置移动的行动。', 341);
INSERT INTO `t_military_term_data` VALUES ('4d813c20-bbe6-42fc-a919-a1b73d398fad', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '组织指挥能力', '指挥员及其指挥机关实施指挥活动所具有的实际能力、主要包括情报获取与处理能力筹划决断能力、计划组织能力以及控制协调能力等。', 11);
INSERT INTO `t_military_term_data` VALUES ('4d839792-0c29-4fae-bafd-63350606b2a7', '0', '111', '', 33);
INSERT INTO `t_military_term_data` VALUES ('4d86a076-b6b1-44a3-8287-9816a720abe7', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '列属', '革命烈士的家属。包括烈士的父母、配偶、子女以及依靠烈士生活的18周岁以下的弟妹和曾连续抚养烈士逾7年以上（从烈士出生至18周岁期间）者。', 74);
INSERT INTO `t_military_term_data` VALUES ('4d871667-bb08-4dfd-8688-24141241d96c', '98df76fb-4b65-48ff-a56c-4db587327c79', '作战费', '部队遂行作战任务时,在正常经费之外增加的专项经费。主要用于构筑战场设施,补充装备、物资、器材,抢修作战装备,组织人员、物资运输,新组建、扩编部队,以及因作战需要增加生活、公务事业等方面的开支。', 80);
INSERT INTO `t_military_term_data` VALUES ('4d90e235-137d-42d9-ba72-abee902f5f6a', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天气过程', '天气及其相应的天气系统的发生、发展、移动、消失的全部演变过程。寒潮、梅雨、台风、暴雨等天气过程的典型模式,对分析、预报天气具有重要参考价值。', 37);
INSERT INTO `t_military_term_data` VALUES ('4d9ccf96-f5d6-4982-b14f-e2a134ebdd44', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '秘密载体', '载有秘密信息的物体、包括记载有秘密内容的各种纸张、胶片、磁带、磁盘、光盘等。', 72);
INSERT INTO `t_military_term_data` VALUES ('4da5a18f-9611-4055-8983-40739464b332', '98df76fb-4b65-48ff-a56c-4db587327c79', '储备标准', '根据部队的作战任务、装备技术性能、物资消耗规律和作战补充难易程度等因素而制定的各类物资的储备定额。', 120);
INSERT INTO `t_military_term_data` VALUES ('4dead292-9ce7-4e61-b6ea-0f6d86f5b606', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '搜潜', '海军反潜兵力使用搜潜设备搜索敌潜艇的战斗行动。任务是发现敌潜艇,测定其位置和运动要素,并进行跟踪监视,为攻潜提供基本数据。', 93);
INSERT INTO `t_military_term_data` VALUES ('4def7fef-5140-4be6-ba1d-b4decf06234f', '8a761efd-50a6-4ac8-9913-b7d745104f82', '投掷距离', '手榴弹或其他手投式弹药在规定的条件下投掷时,自投掷点全落弹点间的距离。', 228);
INSERT INTO `t_military_term_data` VALUES ('4df0f8fe-40e8-462b-b273-08e8b4ebc752', 'f0140091-c11a-48c9-8836-8aa94439dac0', '警戒阵地', '设置在防御阵地的前沿前或侧方,由警戒分队占领的阵地。用以防止敌之侦察、渗透和突然袭击,迫敌过早展开,迟滞敌向主阵地接近。', 228);
INSERT INTO `t_military_term_data` VALUES ('4df2724c-e3e4-420c-9375-8dbe7aa92e23', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '命中弹', '直接命中目标或落达面积目标幅员内的射弹。', 231);
INSERT INTO `t_military_term_data` VALUES ('4e041195-96ba-4045-ac3e-b47ed0a628ab', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '功勋荣誉章', '中国人民解放军功勋荣誉章的简称。中华人民共和国中央军事委员会授予军队离休干部的荣誉证章。根据1988年7月1日第七届全国人民代表大会常务委员会第二次会议批准的中央军委《关于授予军队离休干部中同人民解放军功勋荣誉章的规定》,军委决定对中国人民解放军在土地革命战争时期、抗日战争时期和解放战争时期入伍或参加革命工作的军队离休干部,分别授予红星功勋荣誉章（分一、二级）、独立功勋荣誉章、胜利功勋荣誉章。', 65);
INSERT INTO `t_military_term_data` VALUES ('4e153284-080a-4d53-9f51-388b86d1f107', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '内水', '国家内陆水和领海基线向陆一侧的水域的统称。包括领陆内的河流、湖泊和领海基线内的海湾、海峡、海港、内海、河口等。', 73);
INSERT INTO `t_military_term_data` VALUES ('4e1abd46-1c7d-45da-aaf3-22d97dc29cb0', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '攻势', '军队实施的进攻行动及其态势。', 345);
INSERT INTO `t_military_term_data` VALUES ('4e1edce0-91d0-4879-8dce-5f455e572261', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '发射药', '用以发射弹丸的火药。通常分为单基发射药、双基发射药和三基发射药。', 206);
INSERT INTO `t_military_term_data` VALUES ('4e1fc52f-4d99-48cb-aa28-fd4928a75af6', '06a75831-13a1-4660-870a-455bb445336a', '既设通信设施', '已建立的军用与民用通信台、站、线路等设施。分为固定通信设施与野战通信设施。', 30);
INSERT INTO `t_military_term_data` VALUES ('4e27e76f-9233-4acb-b969-5b82cacf1896', '98df76fb-4b65-48ff-a56c-4db587327c79', '责任支付', '战时紧急情况下由部队首长负责批准作战费开支的一项制度。中国人民解放军的集团军、师或旅首长,有权在作战费预拨款的数额内作责任支付。', 76);
INSERT INTO `t_military_term_data` VALUES ('4e35cda0-59f1-47f5-8eb4-f1bc8e38b962', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '编配比例', '军队编制中人员之间、装备之间、人员与装备之间的配备比例。如军官与士兵、战斗人员与保障人员、战斗舰艇与勤务舰船、飞行员与飞机等的比例。', 64);
INSERT INTO `t_military_term_data` VALUES ('4e394334-050d-4501-a34c-1f497286c410', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克集结地域', '坦克部队为遂行任务而临时集中的地域。通常选择在敌远程火炮射程以外,便于坦克隐蔽配置,便于组织三防,有良好的进出道路和充足水源的地区。', 17);
INSERT INTO `t_military_term_data` VALUES ('4e4b5ef1-286d-4c7f-b011-9db8a0974e63', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗训练基地', '主要用于电子对抗部队、分队的战术训练及有关部队进行电子对抗训练的基地。', 12);
INSERT INTO `t_military_term_data` VALUES ('4e4e3e2c-4a72-441b-b00a-e59906a70856', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '棱线', '平地或高地上成线形的凸棱部分。如堤坝、田埂和山脊线。军事上用以保护自己,发扬火力。', 22);
INSERT INTO `t_military_term_data` VALUES ('4e4fc8bf-4722-4db1-aa2f-d6ea7b194c34', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防潜力', ' 国家经动员转化可用于防卫目的的潜在力量。一般指可动员起来用于国防的人力、物力和财力。其大小取决于国家的政治、经济、科技、文化以及领土、人口和资源等条件。', 9);
INSERT INTO `t_military_term_data` VALUES ('4e5749e8-1538-41cb-98a6-5e636ba33177', '06a75831-13a1-4660-870a-455bb445336a', '宇宙通信', '亦称空间通信。利用电磁波在星球之间、航天器之间、星球与航天器之间进行的通信。地球站与地球卫星轨道上的航天器之间的通信,称近空通信；地球站与地球卫星轨道之外的航天器之间的通信,称深空通信。', 116);
INSERT INTO `t_military_term_data` VALUES ('4e6d71a7-24c5-4c19-89f2-7b73a829d73d', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '空降战役', '以空降作战为主要形式的进攻战役。由空降兵、航空兵以及其他军兵种共同进行。现代条件下的空降战役通常为联合战役的组成部分。有时亦可单独进行。', 60);
INSERT INTO `t_military_term_data` VALUES ('4e89961a-5f7e-44cc-b147-7aed997c7fe4', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队党委制', '中国共产党在中国人民解放军团或相当于团级以上的部队和单位设立委员会、实行党委领导的制度、是党对军队实施领导的根本制度。党的各级委员会是各单位统一领导和团结的核心,实行民主集中制原则, 贯彻执行党委统一的集体领导下的首长分工负责制。党委书记和委员享有平等的权利,个人不能决定重大问题或改变党委的决定。', 16);
INSERT INTO `t_military_term_data` VALUES ('4e8a0dd3-aacc-4776-b8ec-eeb7371f3f46', 'f0140091-c11a-48c9-8836-8aa94439dac0', '城市战斗', '在城镇地区进行的战斗。受建筑物制约大,观察、射击、指挥、协同不便,机动困难,兵力兵器不易展开。', 4);
INSERT INTO `t_military_term_data` VALUES ('4e8b31c6-d579-4d46-a79c-162142fab5a6', '06a75831-13a1-4660-870a-455bb445336a', '电磁兼容性', '电子设备在电磁环境中仍能进行正常工作的性能。多个电子设备集中工作时,要求每个电子设备能抑制来自其他设备的电磁干扰,同时本身又不对其他设备产生过强的干扰。', 94);
INSERT INTO `t_military_term_data` VALUES ('4e8f26d5-bb44-4e0e-bbb5-73d9f5c4dbe3', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核深水炸弹', '装有核战斗部的深水炸弹。威力通常为千吨梯恩梯当量级。可由航空器投掷,也可由舰载反潜火箭发射。主要用以攻击敌方潜艇及其他水下目标。', 111);
INSERT INTO `t_military_term_data` VALUES ('4e91d28c-6de3-4255-858b-0c9873e38441', 'f0140091-c11a-48c9-8836-8aa94439dac0', '阵地设施', '阵地上的各种工事、工程障碍物和指挥、生活设备的统称。', 61);
INSERT INTO `t_military_term_data` VALUES ('4e95000b-ad4c-4cf1-bffd-e828c1e2a125', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵作战指挥', '防空兵指挥员及其指挥机关对所属部队或分队作战行动的指挥。包括战役行动和战斗行动中的作战指挥。', 92);
INSERT INTO `t_military_term_data` VALUES ('4e9e0ddd-a7e9-48ef-b207-fb5027e0fb36', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '非触发水雷', '非触发（近炸）引信,能主动发射信号或利用舰船物理场起爆的水雷。多为沉底雷。分为主动式非触发引信水雷和被动式非触发引信水雷。', 217);
INSERT INTO `t_military_term_data` VALUES ('4ea285c3-969f-459e-b0d0-d76e3d45a015', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮雷达火控系统', '主要使用雷达探测跟踪空中目标的高射炮火控系统。由跟踪雷达或搜索雷达、人控计算机和高炮随动装置等组成。', 48);
INSERT INTO `t_military_term_data` VALUES ('4ea6e4cc-376b-466e-8100-cc4befad7d1d', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防战略', '国家筹划和指导国防建设与斗争全局的方略。是国家战略的组成部分,由国家依据国际国内形势和客观条件及国防的需要制定。', 3);
INSERT INTO `t_military_term_data` VALUES ('4eaa2048-bd40-4c7a-9eb8-36bc50932ef7', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵监视射击', '炮兵为维持急袭射击效果或对须以火力监视的目标而实施的不定时的射击。通常使用1～2个炮兵连,必要时也可使用l～2门火炮,用少量的弹药进行。', 186);
INSERT INTO `t_military_term_data` VALUES ('4eb44113-3605-4f05-8a1e-60734d6070d3', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '水文', '水在地球表面、大气层中和地壳内各种变化与运动的现象。分为陆地水文、海洋水文等。对军事行动有很大的影响。', 107);
INSERT INTO `t_military_term_data` VALUES ('4eb80adf-7743-46ab-9c82-3f5a90a3764b', '06a75831-13a1-4660-870a-455bb445336a', '通信兵技术训练', '为提高各类通信人员的技术理论水平与专业技能而进行的训练。主要包括：通信专业技能和勤务知识,通信技术和指挥自动化技术基础理论,通信装备和指挥自动化系统的工作原理、战术技术性能和使用维修技能等。', 216);
INSERT INTO `t_military_term_data` VALUES ('4ec5f348-43e6-4f5b-b4b8-2a5ed86aa4ef', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '轨条砦', '以钢轨或工字钢为桩柱的桩砦。一般设置在水深2～2.5米的水际滩头。主要用以阻滞中小型登陆工具登陆。', 121);
INSERT INTO `t_military_term_data` VALUES ('4f0eae10-97e9-4c95-aa34-51f6f97c582a', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '换班顺序', '交班与接班的部队或分队进行交接班的光后顺序、需根据任务、敌我态势、地形状况、换班的时间确定、通常按先上级后下级先加强后所属、先保障后作战先纵深后前沿等顺序进行。', 103);
INSERT INTO `t_military_term_data` VALUES ('4f0f572a-7208-45a8-ad36-90e4998f944e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防飞机障碍物', '用以阻滞或毁伤低空、超低空飞行的直升机和飞机的人工障碍物。如防空雷区、防空缆索等。通常设置在重要目标的外围空域和地面,反空降地域的上空和地面,以及敌机接近目标的机场上空。', 106);
INSERT INTO `t_military_term_data` VALUES ('4f287a16-1702-406f-b2f0-a453d4442569', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '轨道倾角', '简称倾角。航天器绕地球运行的轨道平面与地球赤道平面之间的夹角。它用地心至北极的方向和轨道平面正法向（与航天器绕地球运动的角速度方向一致）之间的夹角度量。倾角小于90度的轨道称为顺行轨道；倾角大于90度的轨道称为逆行轨道。', 230);
INSERT INTO `t_military_term_data` VALUES ('4f2d0581-e16f-4862-88ca-c813e8b83390', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇战斗出航准备等级', '对舰艇战斗出航准备程度和时限的区分。分为水面舰艇战斗出航准备等级和潜艇战斗出航准备等级。水面舰艇战斗出航准备等级一般分7级,最高为一级；潜艇战斗出航准备等级分3级,最高为一级。', 284);
INSERT INTO `t_military_term_data` VALUES ('4f2dab6d-d113-47f6-8754-35be80e0349b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '后续舰', '舰艇编队成单纵队航行时,前后相邻的两艘舰中后面的一艘舰。', 264);
INSERT INTO `t_military_term_data` VALUES ('4f3a69cf-5ff0-43ab-90a2-59dbe97bb221', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '通信卫星', '用作无线电通信中继站的人造地球卫星。由专用系统（有效载荷）和保障系统组成。通常分为军用通信卫星、海事通信卫星、电视广播卫星、跟踪和数据中继卫星等。军用通信卫星又分为战略通信卫星和战术通信卫星。利用卫星通信,具有通信距离远、传输容量大、覆盖区域广、通信质量好、经济效益高等优点。', 212);
INSERT INTO `t_military_term_data` VALUES ('4f4cb210-9e2b-4dba-9712-abb5c18d3b47', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力控制', '以火力对某一区域或目标实施的控制。', 245);
INSERT INTO `t_military_term_data` VALUES ('4f5550d0-4b8a-4fbd-bd32-3d6358b9fae6', '06a75831-13a1-4660-870a-455bb445336a', '自动化信息处理系统', '在指挥自动化系统中利用电子计算机进行信息处理的分系统。包括自动化文电处理系统和态势图处理系统。具有对信息进行自动综合、分类、存储、检索、复制、统计和数据库管理等功能。', 163);
INSERT INTO `t_military_term_data` VALUES ('4f5ef1dc-0f85-4948-b17d-0bcc9afcf188', 'f0140091-c11a-48c9-8836-8aa94439dac0', '阻击', '以兵力、火力阻止或迟滞敌人前进的战斗行动。', 247);
INSERT INTO `t_military_term_data` VALUES ('4f68e02a-b5c9-4833-a4b6-7c7fe5a47c6a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '特殊性能核武器', '通过设计调整核战斗部性能以增强或削弱某些杀伤破坏因素的核武器。包括中子弹、增强X射线弹、冲击波弹、核电磁脉冲弹、感生放射性弹等。', 93);
INSERT INTO `t_military_term_data` VALUES ('4f7c9b31-664b-4730-9994-cf7f5e3f7260', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战空间', '作战活动所涉及的空间范围随着现代战争的立体化程度增强,远战增多,军队的作战空间也日益增大。', 121);
INSERT INTO `t_military_term_data` VALUES ('4f82983d-8e54-43b6-bbe8-4273cae0d79e', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '坡度', '斜面对水平面的倾斜程度。通常用起止点的高差与水平距离的比值或角度数表示。地面坡度的大小对军队行动有很大影响。', 24);
INSERT INTO `t_military_term_data` VALUES ('4f846e8d-68f1-41cf-9a9a-e6893232efcd', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹氮气供气设备', '为测试发射导弹提供和分配氮气的地面设备。包括空压机、氮气瓶车、气瓶组和配气设备等。', 62);
INSERT INTO `t_military_term_data` VALUES ('4f85694a-d741-4cc1-8d93-e7d10f2f3528', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '修械所', '部队中负责维修军械的机构。主要负责分工范围内的维修任务,并指导部队或分队正确使用和维护武器装备,有时还以部分力量到部队或分队进行定点修理、伴随修理或巡回修理服务。', 107);
INSERT INTO `t_military_term_data` VALUES ('4f87badd-d7c0-4dbb-b084-af2745ca732b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击指挥作业器材', '炮兵用以求取射击诸元的手工作业器材。主要包括：射击指挥器,射击计算盘,射击条件修正量计算器,阵地计算盘和射击修正器等。结构简单,坚固耐用,但作业速度较慢,精度不够高。', 297);
INSERT INTO `t_military_term_data` VALUES ('4f9dd819-8d1f-4cc6-a609-c33ca42af85f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事革命', '在社会变革前提下,军事领域内发生的一系列带根本性的、具有重大影响的变革。主要反映在军事技术、武器装备、军队结构、作战方法、军事思想及理论等方面的质的变化上。', 41);
INSERT INTO `t_military_term_data` VALUES ('4f9e4f24-6e87-4169-95f2-538fab9c8f93', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '经差', '地面两点的经度值之差。', 206);
INSERT INTO `t_military_term_data` VALUES ('4f9f7fce-ecc0-4bd9-bb66-d743fed31a13', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天控制中心', '航天测控网中对航天器飞行实施监视,并进行数据的收集、交换、分析和指挥控制的中枢机构。通常配有数据处理系统、通信系统、指挥监控系统、时间统一系统等。', 268);
INSERT INTO `t_military_term_data` VALUES ('4fac3fcc-421a-4a16-b168-a594f9ba0be5', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学武器', '以毒剂的毒害作用杀伤有生力量的武器。包括装有毒剂或毒剂前体的化学弹药和航空布洒器等施放器材。', 198);
INSERT INTO `t_military_term_data` VALUES ('4fc2010e-61f3-4fd6-960d-3271ae2aeb6d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '丘陵地', '地面起伏较缓,岗丘错综连绵,高差在200米以下的地区。以较小的高度和起伏区别于山地,以明显的相对高度区别于平原。一般谷宽岭低、岗丘形状圆浑、斜面较缓,人烟较多,物产较丰富。便于军队通行、观察和射击。', 25);
INSERT INTO `t_military_term_data` VALUES ('4fc5f1b4-e438-424f-8b1c-786e2369382d', '97a19170-bfac-42c5-9906-1acb187f0654', '空勤组', '在同一架飞机上执行飞行任务和空中勤务的飞行人员的编组。包括飞行员和空中领航员、通信员、射击员、机械师等。', 14);
INSERT INTO `t_military_term_data` VALUES ('4fcb0296-8fcb-4d44-84ce-7d6905ae5314', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克炮', '安装在坦克上并按坦克的特殊要求制成的火炮。分为线膛炮和滑膛炮两种。现代坦克炮口径一般为85～125毫米。是坦克的主要武器。具有初速大、弹道低伸、射击精度高、后坐距离短等特点。主要以直接瞄准射击击毁敌装甲目标,也可压制、消灭反坦克武器,摧毁野战工事,歼灭有生力量。', 112);
INSERT INTO `t_military_term_data` VALUES ('4fe9404f-dde1-458b-aa5e-006a6a7d14e1', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '洲', '地球表面各大陆及其附属岛屿分别组成的地理区。通常将地球表面的六块大陆及其周围岛屿分为七大洲,按其面积大小,依次为亚洲、非洲、北美洲、南美洲、南极洲、欧洲和大洋洲。', 4);
INSERT INTO `t_military_term_data` VALUES ('4fee0f3c-9072-4554-9116-fc9ef9563669', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥效能', '军队指挥系统在实施指挥活动中发挥作用的有效程度。', 17);
INSERT INTO `t_military_term_data` VALUES ('50018ed6-7016-4683-9f5b-d1a09f617246', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '通报', '对所属单位或其他有关单位介绍情况、交流经验教训和公布成绩等的军用文书。', 139);
INSERT INTO `t_military_term_data` VALUES ('50080d37-f7da-4453-9fb1-05eb08b06b34', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军事法院', '国家在军队中设立的审判机关。属于专门法院。中国人民解放军的军事法院分三级设置,即：中国人民解放军军事法院,军区、海军、空军、解放军总直属队、武警部队军事法院,海军舰队、军区空军、陆军军级单位军事法院。', 136);
INSERT INTO `t_military_term_data` VALUES ('500c9fa5-73e4-48c2-9d1b-8091940e146d', '98df76fb-4b65-48ff-a56c-4db587327c79', '加大储备', '在移动储备之外增加的物资储备。通常根据作战任务的需要和交通条件确定。是战术储备的组成部分。', 118);
INSERT INTO `t_military_term_data` VALUES ('5018a9f8-f8a0-44ea-a389-5973b8ef36bb', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲倾角', '装甲表面法线与水平面之间的夹角。装甲倾角大,装甲的抗弹能力就强。主战坦克首上装甲倾角一般为65度～82度。', 179);
INSERT INTO `t_military_term_data` VALUES ('50207986-9cd6-4be0-8c68-60f145431454', '06a75831-13a1-4660-870a-455bb445336a', '再生中继器', '将传输过程中变形的脉冲信号恢复原状的设备。主要由均衡放大器、定时电路、识别再生电路组成。设置在数字通信线路上,以延长通信距离。', 194);
INSERT INTO `t_military_term_data` VALUES ('5034c14c-4e90-4afb-8ff6-e31743d6eaa6', '97a19170-bfac-42c5-9906-1acb187f0654', '机场导航', '保障飞机或直升机起飞、着陆和出航、返航以及在机场区域上空飞行的导航。', 358);
INSERT INTO `t_military_term_data` VALUES ('50438491-c8a5-4d3a-a779-93c51df8a313', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事预测', '对与战争或军队直接相关的事项的发展趋势及其前景预先进行的科学推测。', 44);
INSERT INTO `t_military_term_data` VALUES ('5049252b-0b8b-461e-b1db-601a05b3a458', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆战斗射击', '装甲车辆单车射击练习中,乘员使用火炮、机枪在近似实战条件下进行的实弹射击。是装甲兵单车射击的最高训练课题。', 72);
INSERT INTO `t_military_term_data` VALUES ('50506cf3-9963-4f37-8e10-a9434c6b4969', '97a19170-bfac-42c5-9906-1acb187f0654', '空中巡逻', '歼击航空兵部队以少数兵力在指定空域和规定时间内进行的巡查警戒飞行。', 112);
INSERT INTO `t_military_term_data` VALUES ('505446f1-096c-492b-8b74-07a114648a90', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '飞机水上迫降', '飞机因故不能继续飞行而被迫在水面进行的紧急降落。通常在飞机发生故障、燃料耗尽、战伤和气象恶化等危及安全而又无法在陆上迫降的情况下进行。', 310);
INSERT INTO `t_military_term_data` VALUES ('5059297a-815a-460f-818f-b96eace9e75e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '爆破药块', '按一定规格制作,用于爆破的制式块状炸药。常用的有75克圆药柱,200克、400克、2.5千克和5千克等规格的药块。', 222);
INSERT INTO `t_military_term_data` VALUES ('50754119-1c1c-4b39-9623-176dbcbf7ec7', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核点火', '亦称中子点火。由少量中子按预定时刻引发核装置中裂变材料产生链式裂变反应,形成核爆炸的动作。中子发生器和热核激发器都可作核点火之用。', 128);
INSERT INTO `t_military_term_data` VALUES ('5078a4e6-d2bc-4513-bc6c-a1d26bb1a88d', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教学实施计划', '组织实施教学的计划。内容包括教学课目、目的、时间、方法、要求等。', 31);
INSERT INTO `t_military_term_data` VALUES ('50a288a3-8074-4683-829c-e4d2be52ffef', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '空潜导弹', '从航空器上发射,用以攻击潜艇的导弹。', 194);
INSERT INTO `t_military_term_data` VALUES ('50b453ee-56fc-4299-a67d-c4dfeee5a3a3', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '军事决策支持系统', '用以支持军事决策的交互式计算机信息系统。主要是通过人机对话等方式,协助决策者发现和分析问题,探索决策方案,对有关方案进行评价、预测。通常用于军事规划、作战训练和武器装备研制等。', 171);
INSERT INTO `t_military_term_data` VALUES ('50cbfec2-b8ac-469b-a22d-979d3253d369', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机颠簸', '飞机飞行中遇到扰动气流使飞机  升力改变而引起的忽上忽下和机身震荡的现象。按颠簸程度,分为弱、中、强3级。中级以上的颠簸会影响飞机操纵和空中射击、投弹的准确性,使编队飞行、空中加油等难以顺利进行。严重时会损坏飞机,造成事故。', 245);
INSERT INTO `t_military_term_data` VALUES ('50d043c3-92cc-4a35-8f9b-7d7f98408662', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '台地', '顶部广阔平坦，四周为陡坡、陡坎的高地。', 27);
INSERT INTO `t_military_term_data` VALUES ('50db16d7-e25b-4ee6-ba30-147a52c89a36', 'f0140091-c11a-48c9-8836-8aa94439dac0', '跃进', '①徒步人员在敌火下运动时,突然跃起,屈身快跑,迅速到达预定地点的动作。②机械化、摩托化部队逐次分段快速前进的方法。通常在与徒步运动的部队编为一个行军纵队时采用,以协调行军速度。', 111);
INSERT INTO `t_military_term_data` VALUES ('50e13c49-8e5e-4c53-8e6f-4993706bf3be', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇战', '使用潜艇兵力以隐蔽袭击手段在海洋进行的进攻作战。', 30);
INSERT INTO `t_military_term_data` VALUES ('50f177ba-3327-4ed0-9a34-cdaecff9948d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防御方向', '防御部署朝向敌人的作战方向。分为主要防御方向和次要防御方向。。', 397);
INSERT INTO `t_military_term_data` VALUES ('50facbc2-e44e-403a-8d51-41f1ade709c6', '98df76fb-4b65-48ff-a56c-4db587327c79', '牵引车', '专门用以牵引火炮和其他武器装备的车辆。分为轮式牵引车和履带式牵引车。', 295);
INSERT INTO `t_military_term_data` VALUES ('50fc8809-1975-4bd0-946a-f51c048d6198', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '探雷车', '实施探雷作业的专用车辆。由车载式探雷器和基础车组成。探头置于车的前方,车内装有信号处理装置和音响、发光或屏幕显示等报警设备。主要用以在道路和平坦地形上探测地雷。作业车速每小时5～15公里,发现地雷后能自动停车。', 172);
INSERT INTO `t_military_term_data` VALUES ('50feb99b-85cc-4a57-b48d-41d6e5e3c89f', '98df76fb-4b65-48ff-a56c-4db587327c79', '单兵野战食品', '亦称单兵口粮。由单兵携带,以日份或餐份包装的野战食品。主要供地面部队在作战中因饮食保障不及时的情况下食用。', 144);
INSERT INTO `t_military_term_data` VALUES ('510d813e-2ee8-4b64-84df-e0325e45d1c3', 'f0140091-c11a-48c9-8836-8aa94439dac0', '袭击支队', '遂行攻击或破坏敌纵深重要目标任务的战斗编组。通常由师以上单位派出和指挥。', 168);
INSERT INTO `t_military_term_data` VALUES ('5121de6f-b672-4ed0-a0b2-fef38befc90e', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹运输设备', '用以运输导弹弹头。弹体、推进剂、发射台和其他设备、装置等各种设备的统称。包括专用的、通用的和经过改装的铁路运输车、公路运输车、轮船、飞机等。', 56);
INSERT INTO `t_military_term_data` VALUES ('5125110e-cef5-4da7-8972-e52852c826f0', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '斜撑桥', '以两个斜交的框架作为上部结构的中间支点架成的单跨桥梁。用以克服山地的小河、沟谷,也可用以抢修被破坏的小跨径桥梁。', 281);
INSERT INTO `t_military_term_data` VALUES ('512de11f-41e2-48bb-a577-9b32cf7be8af', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队联络工作', '中国人民解放军开展的以团结友军、瓦解敌军为主要内容的工作、是中国人民解放军政治工作的重要内容。', 126);
INSERT INTO `t_military_term_data` VALUES ('51351c5b-fc31-4e6b-a333-94b0a6a97f77', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '望远镜', '观察远方景物的光学仪器。在军事上用以观察战场情况。有分划刻度的望远镜还可用于方位角、高低角和距离的概略测量。', 69);
INSERT INTO `t_military_term_data` VALUES ('513842c4-20f1-487f-9c31-d015da09f912', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军队政治工作学', '研究军队思想政治工作的理论与实践及其规律的学科。中国人民解放军的政治工作学,主要研究中国共产党在中国人民解放军中的思想工作和组织工作的理论原则和实施方法等。', 28);
INSERT INTO `t_military_term_data` VALUES ('514383f4-8021-46fb-910d-1a9ee5d3f782', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '南十字星座', '距南天极约30度,似十字状的星座。座内4颗亮星,名为a、e、Y、8。从Y星向a星连线,并延长至两星距离的4.5倍处,就是南天极。是南半球判定方位和认识其他星座的重要标志。亦是北纬23度以南地区、上半年判定方位的主要星座。', 195);
INSERT INTO `t_military_term_data` VALUES ('51447b1f-8465-4806-9b9c-879510e20e56', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '大地水准面', '假想的与平均海水面相重合并延伸到大陆内部包围整个地球的水准面。通常用大地水准面表示地球形状。是高程测量中正高系统的起算面。', 221);
INSERT INTO `t_military_term_data` VALUES ('5145e781-3cc4-4405-a3ea-c36a82b44090', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军歼击轰炸机', '用以攻击水面和库上目标,并具有空战能力的海军飞机。通常装备有航炮、空上导弹、空规或空地导弹、鱼雷、炸弹等。', 173);
INSERT INTO `t_military_term_data` VALUES ('5151a52f-20d2-4b3a-bf89-2f5b346c956d', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行场地', '以机场中供飞机或直升机起飞、着陆、滑行和维护、停放的场地。包括跑道、滑行道、联络道、保险道、土跑道、停机坪等。', 422);
INSERT INTO `t_military_term_data` VALUES ('516d2b69-38fb-47ff-8e1a-5996f4f30f63', 'f0140091-c11a-48c9-8836-8aa94439dac0', '前沿战斗', '前沿阵地及其附近地区的战斗行动。', 12);
INSERT INTO `t_military_term_data` VALUES ('516d6b8f-6d8d-46db-b2db-4363c4ac0a76', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '总攻击', '亦称总攻。担负进攻任务的各部队,在统一号令下同时发起的攻击。', 95);
INSERT INTO `t_military_term_data` VALUES ('517124c3-efaf-448e-8cec-ccf02b6e65f8', '916997ee-6728-4c61-9b79-d96960b1dc86', '冲击伤', '冲击波作用于机体造成的损伤。核爆炸冲击伤由冲击波超压的挤压和动压的冲击造成。超压可使心、肺、胃肠、膀眈和耳鼓膜等损伤；动压可使肝脾破裂,软组织损伤,骨折,脱臼,体表撕裂,肢体离散等。受冲击波破坏的物体在倒塌和散裂过程中,还可对人员造成间接伤害。', 107);
INSERT INTO `t_military_term_data` VALUES ('5175bed7-fb6a-4d74-a5bc-dbc03acc18a0', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '寻的地雷', '能自动探测、识别和攻击目标的地雷。由目标传感器、数据处理系统、发射装置和寻的战斗部等组成。可用飞机撒布,也可用人工布设。', 145);
INSERT INTO `t_military_term_data` VALUES ('5184d20f-95ce-4cd0-94d9-c6c0f237dce6', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军人道德教育', '依据社会主义道德和军人职业特点,以培养官兵道德品质和规范官兵道德行为为主要内容的教育。', 101);
INSERT INTO `t_military_term_data` VALUES ('518b2a63-c999-41ea-aecd-7565cfce276e', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备管理', '为使武器装备得到适时补充、合理使用并保持良好状态而进行的管理。通常是指武器装备从军队接收到退役、报废的一系列管理工作过程。主要包括武器装备的申请、补充、调整、动用、封存、保管、维修、转级、退役、报废和技术革新等。', 78);
INSERT INTO `t_military_term_data` VALUES ('5192ad66-17c9-422d-b551-048211e23509', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程作业编组', '将参加工程作业的单位或人员根据需要进行临时性的组合。如担负坑道掘进任务的分队,可编成风钻组、爆破组、除渣组等。', 31);
INSERT INTO `t_military_term_data` VALUES ('519a08db-ac49-4bb3-a1df-ac85e26520ad', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '界河航行例会', '以同一江河湖泊为共同疆界的相邻国家的航运、外事、边防等部门代表参加的,就有关航行、航运等问题进行磋商的例行会议。', 122);
INSERT INTO `t_military_term_data` VALUES ('519adff9-6fa9-4426-a775-06c67060c199', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事对抗', '敌对双方以军事力量进行的直接抗衡活动。其最高形式是战争。', 5);
INSERT INTO `t_military_term_data` VALUES ('51ab0bb5-5db1-4a90-89f9-6d73697516d5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击修正', '亦称炮兵射击校正在炮兵射击过程中对射弹偏差进行的修正。', 161);
INSERT INTO `t_military_term_data` VALUES ('51bc0900-2b08-4445-98fa-fc7dfa61ab1a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '制高点', '对周围地域具有瞰制作用的高地或建筑物的顶部。可居高临下,便于观察和发扬火力。', 129);
INSERT INTO `t_military_term_data` VALUES ('51c13aa6-28ba-4646-9996-78eee296bfd6', 'f0140091-c11a-48c9-8836-8aa94439dac0', '反坦克火力配系', '用以摧毁敌坦克、步兵战车等装甲目标的火力配系。由火箭筒、反坦克导弹、反坦克火炮以及坦克、攻击直升机等反坦克火力组成,并与防坦克障碍物相结合。', 79);
INSERT INTO `t_military_term_data` VALUES ('51c69304-9bcf-4d03-8495-293c2b95731c', '06a75831-13a1-4660-870a-455bb445336a', '无线电专向', '简称专向。两部无线电台之间使用相同的联络规定直接建立通信联络的方法。通常用于指挥所同主要作战方向或执行重要任务的部队或分队建立通信联络。', 49);
INSERT INTO `t_military_term_data` VALUES ('51d54bd1-31b8-4e02-b85b-b4b6eba95de0', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行航迹', '飞机或直升机飞行时相对于地面或水面运动的轨迹。', 372);
INSERT INTO `t_military_term_data` VALUES ('51e0107e-ae07-445c-9479-6c1347198df2', '06a75831-13a1-4660-870a-455bb445336a', '通信保障', '为顺利遂行作战和其他任务而在通信联络方面采取的各项保证性措施与进行的相应活动的统称。按保障范围,分为战略通信保障、战役通信保障和战术通信保障；按保障对象,分为合成军队通信保障和军兵种通信保障。', 26);
INSERT INTO `t_military_term_data` VALUES ('51e502fa-4f7c-4013-ac81-3c02ed8bd22b', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '登直升机', '搭乘直升机的部队或分队在直升机部队人员的指引下登上直升机的行动。分为地面登直升机。悬停登直升机、绳梯登直升机等。', 88);
INSERT INTO `t_military_term_data` VALUES ('51ead039-13e3-440d-bf2d-4b64ffcac23c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队党的纪律检查工作', '中国共产党在中国人民解放军中进行的维护党的纪律的工作。是中国人民解放军政治工作的重要内容。', 47);
INSERT INTO `t_military_term_data` VALUES ('51ed4dbe-f920-4652-a09e-2b7920949286', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '合同命令', '对所属各军兵种部队统一下达的作战命令。', 124);
INSERT INTO `t_military_term_data` VALUES ('51f01f63-0a8a-4df4-a685-142142c30b19', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮平均弹道', '通过火炮射弹散布中心的弹道。是编制射表、制定射击规则、计算射击诸元、进行射击观察和修正的基准弹道。', 254);
INSERT INTO `t_military_term_data` VALUES ('51f43761-b213-443c-988d-1c19788c21b8', '06a75831-13a1-4660-870a-455bb445336a', '保密机', '可对信息进行加密和对已加密的信息进行解密的通信设备。分为电话保密机、电报保密机、传真保密机。图像保密机和数据保密机等。', 148);
INSERT INTO `t_military_term_data` VALUES ('51f93f57-f8cf-442a-ac2f-8b17d127e2cf', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '防御地带', '战术兵团防守的横向带状地区。通常每道防御地带由2～3道防御阵地构成。', 129);
INSERT INTO `t_military_term_data` VALUES ('52183fe1-f71d-4997-ab23-74a9cb1b9597', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '时令路', '在一定季节可通行的道路。', 136);
INSERT INTO `t_military_term_data` VALUES ('521b8552-957f-416e-a35e-d90124f7613b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '军用卫星', '用于军事目的的人造地球卫星。包括侦察卫星、军用通信卫星、军用气象卫星、军用导航卫星、军用测地卫星、截击卫星和军事技术试验卫星等。', 205);
INSERT INTO `t_military_term_data` VALUES ('52377f23-2d48-47ee-9f54-df0a3071ee40', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥对象', '构成指挥关系中的被指挥的单位和个人的统称。', 6);
INSERT INTO `t_military_term_data` VALUES ('5245ad5f-21a4-43f2-aed7-8e6ff20125e3', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵简便射击', '口径迫击炮、无坐力炮和火箭炮炮手,仅用炮身或火箭弹以概略瞄准的方法实施的射击。通常在时间短促或无炮架、无定向管时采用。', 201);
INSERT INTO `t_military_term_data` VALUES ('524801f4-b21c-45c8-8090-ca210294937f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战类型', '按照作战行动的性质对各种作战所作的基本分类。分为进攻和防御两大类。', 128);
INSERT INTO `t_military_term_data` VALUES ('524adfde-9cb6-4420-bfac-331dd2ebd77d', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵破坏射击', '炮兵摧毁敌装甲目标、防御工事、障碍物和建筑物等目标,削弱其战斗能力的射击。', 176);
INSERT INTO `t_military_term_data` VALUES ('524beaad-b538-4c66-b278-170eab88115a', '98df76fb-4b65-48ff-a56c-4db587327c79', '军队农场', '军队投资和经营管理的具有一定规模的农副业生产单位。', 161);
INSERT INTO `t_military_term_data` VALUES ('52525759-a345-4244-a5b9-97e9b899a637', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹射击准备', '地空导弹发射前进行的各项准备的统称。主要包括：兵器展开，对设备进行功能检查，构通作战通信网,导弹加电准备,确定禁射范围,测量和装定环境参数,搜索、发现和跟踪目标,计算目标诸元和射击诸元,导弹部件准备和发射条件检查等。', 195);
INSERT INTO `t_military_term_data` VALUES ('5256250c-f5bb-4402-8d29-31b7fe81e4c3', 'f0140091-c11a-48c9-8836-8aa94439dac0', '假阵地', '由假工事、假目标等组成的阵地。用以欺骗、迷惑敌人。', 232);
INSERT INTO `t_military_term_data` VALUES ('5260d16e-05ac-47ca-9a9e-e4830f22da9d', '06a75831-13a1-4660-870a-455bb445336a', '通信装备维护', '为使通信装备保持完好状态而采取的技术措施。包括日常维护、周维护、月维护、季度检查和年度普查等。主要是对通信装备进行擦拭、除潮、紧固、除锈、涂漆、注油、测试、检修和鉴定以及清点数量、补充消耗等。', 213);
INSERT INTO `t_military_term_data` VALUES ('5268f51d-7d28-41b9-ad4f-daa7b592d375', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥理论', '关于军队指挥问题的系统化理性认识和知识体系、它产生于军队指挥实践又给牛队指挥实践以指导,并受其检验。', 1);
INSERT INTO `t_military_term_data` VALUES ('52836e3e-13a9-4ad1-968a-b1b771a1e025', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战斗', '兵团或部队、分队在较短时间和较小空间内进行的有组织的作战行动。分为进攻战斗和防御战斗两大类。可在战役内进行,也可单独进行。', 0);
INSERT INTO `t_military_term_data` VALUES ('52838cf0-ed67-4572-9381-0ea5af142563', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵作战保障', '第二炮兵为安全、顺利遂行作战任务而采取的各项保证性措施与进行的相应活动的统称。主要包括：情报、侦察,目标、测地、计算,气象,通信,电子防御,伪装,工程,地面防卫、防空袭、反空降以及对核、化学、生物武器的防护等保障。', 155);
INSERT INTO `t_military_term_data` VALUES ('5289e145-d600-4393-abea-aa05c807ab4d', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸光（热）辐射效应', '核爆炸的光和热辐射对人员和物体造成的毁伤作用与效果。毁伤程度主要取决于核爆炸火球的光冲量。其作用时间可持续零点几秒至几十秒,能灼伤人、畜,烧毁物体。', 164);
INSERT INTO `t_military_term_data` VALUES ('529ab41c-fa01-4d98-9476-cc1716dcc80f', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '隐形武器', '亦称隐身武器。采用隐形技术，不易被敌方发现的武器。如隐形飞机、隐形导弹、隐形舰艇、隐形坦克等。', 44);
INSERT INTO `t_military_term_data` VALUES ('52a28db9-d964-46a9-8d71-e604b4232301', '06a75831-13a1-4660-870a-455bb445336a', '呼号', '通信台（站）之间互相联络时使用的称呼。分为通报呼号和通话呼号。通报呼号通常以字母或字母与数码混合编成；通话呼号通常以三位数码或山河、城镇等名称编成。', 45);
INSERT INTO `t_military_term_data` VALUES ('52ab4189-1e09-42dd-bdee-b6d948b002e9', '97a19170-bfac-42c5-9906-1acb187f0654', '航空爆破炸弹', '主要以弹体爆炸时产生的冲击波破坏目标的航空炸弹。通常用以摧毁地面或水面的坚固目标。如防御工事、掩蔽部、工厂、桥梁、机场、港口、大型舰船、铁路枢纽等。', 321);
INSERT INTO `t_military_term_data` VALUES ('52bd7240-6024-4d0e-9674-94519864dcd1', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥所转移', '指挥所由原配置位置向新配置位置的移动。通常在指挥所的位置不适合指挥要求或受到严重威胁时实施、基本指挥所转移进攻时应报告上级,通报部队和友邻；防御时必须经上级批准。', 56);
INSERT INTO `t_military_term_data` VALUES ('52bf8277-03b2-435f-8e91-1fee9304a78e', '916997ee-6728-4c61-9b79-d96960b1dc86', '西埃斯', '学名邻-氯苯亚甲基丙二腈。主要作用于眼睛和上呼吸道的复合型刺激剂。眼和上呼吸道受刺激后,出现灼痛、大量流泪、流涕,皮肤接触产生刺痛和红斑等症状。其作用可持续数小时。', 226);
INSERT INTO `t_military_term_data` VALUES ('52d44c04-29b3-4a7e-a7b1-ba57407bbe5c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队法律顾问处', '军队的专门法律服务组织。是军队律师执行职务的工作机构。', 139);
INSERT INTO `t_military_term_data` VALUES ('52ea4cc9-46e6-490a-b5c1-2f34a6742e49', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '调整点', '行军纵队的各部分按规定时限通过的地点。根据情况,在一日行程内可现定一至数个调整点。第一调整点通常也是行军出发点。', 67);
INSERT INTO `t_military_term_data` VALUES ('52efb95e-d5da-4b80-9c6d-338cbc5dc1ec', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '首长机关训练', '团以上部队的首长、机关进行的组织指挥和业务的训练。通常采取自修、集训、函授、想定作业、演习等形式组织实施。', 61);
INSERT INTO `t_military_term_data` VALUES ('52efcc5b-9b6e-4493-8acb-70733d5d6552', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵配置地域', '炮兵具体配置兵力兵器的地域。通常由上级指定配置的范围,炮兵部队根据其任务、兵力数量、火炮性能和地形条件等具体确定。', 54);
INSERT INTO `t_military_term_data` VALUES ('52f07e75-504c-4e85-9bb2-35b46f844428', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射程', '射弹从弹道起点到终点间的水平距离。各类武器射程概念的表述不尽相同。如枪械常用直射距离、有效射程,地面火炮、导弹常用有效射程、最大射程,鱼雷常用行程等。', 53);
INSERT INTO `t_military_term_data` VALUES ('52f99a89-5f34-4176-8bab-298a55ac20ad', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '正面', '部队部署或作战行动朝向敌方的一面。分为进攻正面和防御正面。用一定的横向宽度表示。', 279);
INSERT INTO `t_military_term_data` VALUES ('52fa7e90-c3a6-447d-b031-d4db70e91b30', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '识别技术', '根据目标对光波及其他电磁波和声波有不同的反射和辐射特性,采用光学和光电仪器以及雷达、声纳与计算机等设备,对目标进行探测、识别的技术。军事上主要应用于判明目标的类型和敌我属性，以便采取相应的措施。', 27);
INSERT INTO `t_military_term_data` VALUES ('52fb05f2-4cb8-4fa2-9504-f95d0652b572', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空雷达站', '在战斗队形中执行雷达保障任务的各种防空雷达分队的统称。按雷达种类和性能,分为对空侦察雷达站、炮瞄雷达站、气象雷达站和制导雷达站等。', 117);
INSERT INTO `t_military_term_data` VALUES ('5304cfc1-422e-4743-88c7-2d749debccaa', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵观测器材', '炮兵用以观察、测量和指挥射击的光学仪器、器材的统称。包括望远镜、方向盘、炮队镜、经纬仪、测距机、夜视器材等。', 278);
INSERT INTO `t_military_term_data` VALUES ('531ea482-34a9-4a8b-9719-b02d3bf31fee', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '队属炮兵', '编入陆军的集团军、师、旅、团、营建制内的炮兵。', 3);
INSERT INTO `t_military_term_data` VALUES ('53202e0a-3d98-4584-9974-940cb3d956b6', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '定向地雷', '爆炸后雷体内的钢珠（破片）向预定控制方向和范围内飞散的地雷。杀伤距离一般为50～200米。可用以杀伤人员,在铁丝障碍物中开辟通路,也可用以攻击轻型装甲车辆和直升机。', 147);
INSERT INTO `t_military_term_data` VALUES ('5324dde1-7292-4aa4-8989-9c8b16423862', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹火力计划', '根据上级意图制定的科学分配和使用导弹火力的计划。主要内容包括：目标编号、名称、幅员,瞄准点坐标,毁伤要求,执行任务的单位,发射阵地,导弹的型号、数量,弹头当量,爆炸方式等。', 10);
INSERT INTO `t_military_term_data` VALUES ('53266327-a28f-4594-99bc-f1e79de51f2e', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '惯性制导', '利用装在弹上的陀螺装置、加速度表等惯性仪表进行的制导。不受外界干扰,隐蔽性好,但制导误差会随着时间的增长而加大。', 43);
INSERT INTO `t_military_term_data` VALUES ('532a9562-35db-46f1-99e3-553281e371e7', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战方案', '亦称作战预案、关于作战行动实施办法的设想、是作战计划的雏形、一个作战行动,可有一个或数个作战方案。', 89);
INSERT INTO `t_military_term_data` VALUES ('53376cf9-3ed1-4492-b389-ba9d132b2666', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '临战准备', '①国家或其局部地区在战争迫近时所进行的直接战争准备。主要包括；加强战略侦察,进行战争动员,扩编武装力量,加速疏散城市人口,国家或局部地区由平时体制转入战时体制等。②武装力量从受领作战任务到作战开始前所进行的各项准备。', 155);
INSERT INTO `t_military_term_data` VALUES ('533ccf56-fa89-48e2-86ab-a3be43c218b5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵效力射', '炮兵为获得预期的目标毁伤效果或完成其他战斗任务而进行的射击。按射击效果,分为压制射击、歼灭射击、破坏射击、妨害射击和特种射击等；按战术任务和使用兵力,分为集中射击、拦阻射击、延伸射击和徐进弹幕射击等。', 162);
INSERT INTO `t_military_term_data` VALUES ('53555b76-2909-4378-bbc3-b3f8390a371e', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核载机', '运载核武器并可将之投向或射向目标的飞机。运载的核武器一般为核炸弹或空对地核导弹。机上除瞄准设施外,还设有监控核武器的装置。', 130);
INSERT INTO `t_military_term_data` VALUES ('536d14d3-ba7c-4952-8dd2-675066737d16', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '偏流距离', '泅渡或漕渡时目标实际航迹终点至起航点与流线的垂线间的距离。其大小取决于航速（泅渡速度）、水流速度和初始航向线（泅渡方向钱）与流线的夹角大小。从起航点垂直于流线向对岸航行或泅渡时,其航迹终点至起航点与流线垂线间的距离,称为最大偏流距离。', 331);
INSERT INTO `t_military_term_data` VALUES ('536d2fef-7da0-4ce7-baf3-dfaa92e78184', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击效果', '单个或建制单位射击武器以规定的弹药数量和射击时间对某种目标射击后的杀伤或破坏程度。取决于武器的精度、弹道性能、弹药威力、目标种类及射击条件等。通常用毁伤概率、毁伤目标数量等表示。', 116);
INSERT INTO `t_military_term_data` VALUES ('5371d980-ad6f-4a66-baff-eabc8b123a21', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '人防训练', '对人民防空的干部、专业队伍和城镇居民进行的训练。主要内容包括防空知识和防空技能。', 68);
INSERT INTO `t_military_term_data` VALUES ('537f439e-91f1-4da5-b3d9-e0542b13d6fe', '06a75831-13a1-4660-870a-455bb445336a', '简易信号通信工具', '利用烟火、灯光、旗语、形体物和音响等传递简短信息的各种器材的统称。主要包括：信号枪（弹）、信号灯、发烟罐、旗帜和布板等视觉信号工具,军号、哨子、小喇叭和警报器等音响信号工具等。结构简单,操作、携带方便。', 211);
INSERT INTO `t_military_term_data` VALUES ('5397604f-057a-46ca-b661-f21da70b57c4', '98df76fb-4b65-48ff-a56c-4db587327c79', '航医包', '航空军医巡诊和参加飞行卫勤保障时使用的制式卫生装备。包内装有血压计、听诊器、五官检查器和常用急救药材等。', 225);
INSERT INTO `t_military_term_data` VALUES ('539a91ae-64d9-496c-bf77-6bf02da96b7e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '人工障碍物', '亦称工程障碍物。为阻止、迟滞敌行动而构筑和设置的各种障碍物。按作用性质,分为爆炸性障碍物和非爆炸性障碍物；按用途,分为防坦克障碍物、防步兵障碍物、防登陆障碍物、防飞机障碍物和防空降障碍物等。', 99);
INSERT INTO `t_military_term_data` VALUES ('53b5981f-4890-4b57-9698-799c58b1d0c9', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤文书', '用以组织实施后勤工作的各种文电、图表的统称。包括命令、通令、决定、计划、指示、通知、通报、请示、报告、批复、函、合同等。分为日常后勤文书和作战后勤文书。', 66);
INSERT INTO `t_military_term_data` VALUES ('53bad7da-9042-4c01-9aa0-3630b71d6d98', '8a761efd-50a6-4ac8-9913-b7d745104f82', '手枪', '以单手发射为主要使用方式的短枪。口径多为5.45～11.43毫米，枪重1千克左右，枪长200毫米左右，容弹量5～2O发,在5O米内有良好杀伤效能。', 156);
INSERT INTO `t_military_term_data` VALUES ('53f2ec8d-3fa2-4857-808b-66e024a1182b', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '人民群众侦察', '根据军事需要由人民群众进行的侦察、通常在地方政府领导下,由人民武装部门组织,战时也可由部队直接组织。', 15);
INSERT INTO `t_military_term_data` VALUES ('540a2099-6513-4f00-b40f-07bb8df27a0e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵转移射', '炮兵利用已射击过的目标或已决定射击诸元的火控点,修正新发现目标与原目标（火控点）对阵地的方向差、距离差,以决定目标射击开始诸元的射击。', 163);
INSERT INTO `t_military_term_data` VALUES ('540ebbdc-8517-430f-853a-e0709e1be179', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹发射阵地', '地空导弹部队配置并发射对空导弹的场地。', 99);
INSERT INTO `t_military_term_data` VALUES ('5410cae9-3eb5-471d-b145-1717751cd0c0', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '待运地域', '被输送的部队等待搭乘和装载时的配鲁地域。由被输送单位的指挥员与军事交通部门负责人共同选定。要求有良好的进出道路,便于部队隐蔽和伪装,并组织对空警戒和对空火力。', 86);
INSERT INTO `t_military_term_data` VALUES ('541d6042-d162-4aca-8055-631b6cb5c122', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备值班', '军队为防备敌人突然袭击和应付意外情况而建立的值班。通常由专门指定的部队、机关和首长担任。', 107);
INSERT INTO `t_military_term_data` VALUES ('542bc839-5fed-460d-b636-5fc2dafe17a3', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防空', '防备、抵御敌之空中入侵的措施与行动。主要内容包括：建立各种防空体系,进行反空中侦察、反空袭作战,实施对空隐蔽、伪装、防护和消除空袭后果等。', 212);
INSERT INTO `t_military_term_data` VALUES ('543b142a-bf4c-450c-a329-0448b45ae453', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮瞄准具射击法', '利用高炮上的瞄准具求取和装定射击诸元的射击方法。具有操作简便灵活、反应速度快、便于对付突然出现的目标等特点，但精度较差。通常在不能使用指挥仪射击法时采用。', 175);
INSERT INTO `t_military_term_data` VALUES ('5448b05d-4140-4367-9bce-2e3b6d8fccf1', 'f0140091-c11a-48c9-8836-8aa94439dac0', '巩固突破口', '对打开的突破口以火力或兵力加以控制,防敌封闭的战斗行动。', 195);
INSERT INTO `t_military_term_data` VALUES ('545b431d-f6db-483b-a593-f463e668341a', '97a19170-bfac-42c5-9906-1acb187f0654', '空中警戒', '为防敌突袭而使用飞机或直升机在空中进行的警戒。', 107);
INSERT INTO `t_military_term_data` VALUES ('545de39a-5a87-4b95-bc56-49a385ec5cfe', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '无人驾驶侦察飞机', '简称无人侦察机。由无线电遥控设备或自备程序控制系统操纵的不载人的侦察飞机。通常装有航空照相机、电视摄像机、无线电接收机以及雷达、红外线侦察设备等,有的还装有信息传递装置。', 121);
INSERT INTO `t_military_term_data` VALUES ('546bab53-f84e-43f7-9ed9-01fda2625aa1', '83e065b4-6737-4645-9ea5-8276d1de13ed', '车载机关炮', '安装在装甲车辆上的小口径自动火炮。通常是轻型装甲车辆的主要武器。具有自动变换弹种、射速,高射平射两用等特点。平射时,用以毁伤敌轻型装甲目标,压制火力点,消灭有生力量；高射时,用以打击敌低空飞行的飞机和直升机等。', 113);
INSERT INTO `t_military_term_data` VALUES ('5479e313-f1c5-4a8b-9261-f5df697ba3c5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '电动力鱼雷', '利用电能转换成机械能作为推进动力的鱼雷。通常以蓄电池组作能源,以电动机作为发动机。', 201);
INSERT INTO `t_military_term_data` VALUES ('54aa261e-f00c-46fd-bd58-6377a1e8e773', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防目标', '国家确定的在一定时期内国防所要达到的目的、标准和水平。', 5);
INSERT INTO `t_military_term_data` VALUES ('54b5cb80-7ad3-422d-911e-d2d1f2e2786f', '8a761efd-50a6-4ac8-9913-b7d745104f82', '瞄准角', '火身轴线与瞄准线之间的夹角。其大小是决定射击距离远近的主要因素之一。', 11);
INSERT INTO `t_military_term_data` VALUES ('54be7b39-ab1d-4815-a4ae-45baed1d03eb', '97a19170-bfac-42c5-9906-1acb187f0654', '机降', '用飞机或直升机、滑翔机装载人员、装备、物资直接降落于地面的空降行动。', 148);
INSERT INTO `t_military_term_data` VALUES ('54d13be1-5bfb-4147-a0ab-bc62e5258fdd', '06a75831-13a1-4660-870a-455bb445336a', '入口节点', '为各级指挥所及其附近的固定用户进入地域通信网提供入口的节点。由多路传输设备、交换设备、群路保密机、复接器等组成。通常配置在指挥所地域。', 64);
INSERT INTO `t_military_term_data` VALUES ('54db041d-3b95-408c-9429-cee08c8cbffd', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '天文方位角', '亦称真方位角。从某点的真子午线北向起,顺时针方向至目标方向线间的水平夹角。', 217);
INSERT INTO `t_military_term_data` VALUES ('54e79864-9ecd-451b-9488-ac7b939ad0cf', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '控守台', '对已选定的无线电通信网台,实施固定侦听、侦收的基本业务单位。', 78);
INSERT INTO `t_military_term_data` VALUES ('54e9544b-f009-4bde-b4fb-d32e5963ae56', '06a75831-13a1-4660-870a-455bb445336a', '通信纪律', '通信人员在值勤中应遵守的纪律。主要包括：通信条令,通信台站工作制度,通报（话）规则,通信保密规则,通信联络规定,隐蔽指挥规定,保密设备的使用规定和各种通信设备的操作规程等。', 41);
INSERT INTO `t_military_term_data` VALUES ('54ea3b6a-1ddb-4cf2-8e50-f6d7de2050bf', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '预备役人员', '正在服预备役的公民。分为预备役军官和预备役士兵。中华人民共和国的预备役军官包括：退出现役转入预备役的军官,确定服军官预备役的退出现役的士兵、高等院校毕业生,专职人民武装干部和民兵干部,符合服预备役条件的非军事部门的干部和专业技术人员；预备役士兵包括；基干民兵、普通民兵,以及其他登记服士兵预备役的人员。', 27);
INSERT INTO `t_military_term_data` VALUES ('54fd132c-0271-46b5-a45a-5f86a30a6049', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '遥感图像', ' 由航空航天遥感器获取的经加工成为目视能够判认的载有目标影像信息的像片。能揭示被测目标的性质、形状、大小、位置及其变化情况,用于军事侦察。军事地理、军事测绘、军事气象以及空间科学技术研究等领域。', 244);
INSERT INTO `t_military_term_data` VALUES ('54fd1dba-8323-402d-8488-afba6bb324c1', 'd7132c58-5df3-4b97-919f-58740148b9ca', '弹炮情报指挥系统', '地空导弹与高炮情报指挥系统的简称。防空旅、团实施对空侦察和作战的指挥自动化系统。由计算机、通信器材、雷达接口装置和运载车辆等组成。包括旅站、团站、营站、连站和雷达站。能自动为地空导弹和高炮提供射击方案,传送目标诸元。', 106);
INSERT INTO `t_military_term_data` VALUES ('54fd48ca-cd88-47bc-9622-3023736c935a', '97a19170-bfac-42c5-9906-1acb187f0654', '航空器材', '简称航材。用于装配和维修航空器的器材。主要包括：航空器的构件,发动机及各系统的部件、附件、零件,仪表,电子设备,航空军械,救生装置,充冷、充氧、充电设备,以及维护航空器用的试验仪器、设备、材料等。', 401);
INSERT INTO `t_military_term_data` VALUES ('5510945b-e31e-4c6b-86aa-b65299e09fd7', '916997ee-6728-4c61-9b79-d96960b1dc86', '隔绝式防护', '依靠气密设施,将防护工事或车辆、舰船等的内室与外界受染空气隔绝的防护方式。通常是在遭敌核、化学、生物武器袭击后,外界受染空气浓度高或工事附近有大火时采用。', 57);
INSERT INTO `t_military_term_data` VALUES ('551828c4-9f7f-446a-957a-4b70ea8af561', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '长驱直入', '在敌缺乏防御或防御不力的情况下,进攻的军队长距离、不停顿地快速向敌纵深推进的作战行动。', 362);
INSERT INTO `t_military_term_data` VALUES ('552913ed-33eb-434a-b2c8-58f2c79ca369', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '入轨参数', '航天器进入运行轨道时诸运动状态的参数。包括轨道运动参数和姿态运动参数等。入轨参数决定着航天器运行的轨道要素。', 259);
INSERT INTO `t_military_term_data` VALUES ('5538eec4-d6c0-4bb3-bd21-70db777b8748', 'd7132c58-5df3-4b97-919f-58740148b9ca', '无线电遥控靶机', '用无线电信号控制的空中飞行靶标。分为低空低速型和高空高速型两类。能模拟军用飞机的战术动作。用于防空部队训练和鉴定防空兵器性能。', 137);
INSERT INTO `t_military_term_data` VALUES ('553b53dc-8fb7-42f4-b666-fdae65756d13', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察力量', '可用以执行侦察任务的人力、物力的统称。包括侦察人员、侦察装备与器材的数量和质量。', 66);
INSERT INTO `t_military_term_data` VALUES ('553cb843-21df-4150-b11f-4506566f8c2c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '爆破穿孔器', '以聚能装药爆炸后形成的聚能射流对目标穿孔的爆破器材。主要用以在冻土地、坚硬土地和混凝土结构上进行爆破穿孔以及毁伤装甲目标等。由外壳、装药、药型罩、支架和起爆装置组成。', 230);
INSERT INTO `t_military_term_data` VALUES ('5543231e-c80d-468b-8441-7ad831a1f581', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '光电干扰', '利用辐射、散射、吸收光波能量或改变目标的光学特征,以削弱或破坏敌方光电设备使用效能的电子干扰。按干扰产生的方法,分为无源光电干扰和有源光电干扰。', 55);
INSERT INTO `t_military_term_data` VALUES ('554e480d-6d71-4466-8db1-95a8d3e23246', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '行军侦察', '在行军纵队的前方或翼侧进行的侦察、主要查明部队行军所需的敌情、地形等情况。', 19);
INSERT INTO `t_military_term_data` VALUES ('554ec435-e728-4f88-a046-7061abc82e8a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事原则', '军事活动所依据的法则或标准。通常包括作战原则和建军原则。', 16);
INSERT INTO `t_military_term_data` VALUES ('55515919-7386-456d-9679-8e03a72a8eda', '97a19170-bfac-42c5-9906-1acb187f0654', '机群', '由遂行同一任务,受统一指挥并保持目视联系或战术联系的一至数个飞机或直升机编队在空中组成的战斗集体。不同机种编队组成的机群,称混合机群。', 41);
INSERT INTO `t_military_term_data` VALUES ('5551985c-8ce8-4929-acb0-7772ea87c7f5', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '军事构模', '亦称军事建模。构建军事模型的过程。是军事运筹分析的重要步骤。', 169);
INSERT INTO `t_military_term_data` VALUES ('55521b84-7519-44a0-86a0-f0fc3efa553a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '星座', '按恒星排列的形状,对星空所划分的若于区域。每个星座以其中亮星的特殊分布辨认。星座的名称通常用动物名或器具名、神话人物名命名。国际上通用的星座共88座。', 189);
INSERT INTO `t_military_term_data` VALUES ('555236ab-a3b7-466d-b991-51326e870248', '98df76fb-4b65-48ff-a56c-4db587327c79', '伤死', '伤员在团救护所以上救治机构发生的死亡。', 190);
INSERT INTO `t_military_term_data` VALUES ('5556466e-e645-4fe3-ab47-0dc70630bd7c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '桩砦', '将桩柱植入土中或固定于钢筋混凝土墩中而构成的筑城障碍物。桩柱可使用钢轨、槽钢、工字钢、钢筋混凝土桩、大圆木、条石等。通常成数列交错配置,并向敌方倾斜60～70C。用以防坦克、防机降和防登陆工具等。', 120);
INSERT INTO `t_military_term_data` VALUES ('5558f7a1-b876-4650-9fe1-637e5c987f83', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇就位', '舰艇按规定时间到达指定位置的行动要求准时抵达、位置准确、行动隐蔽。', 77);
INSERT INTO `t_military_term_data` VALUES ('555992b0-7d83-4371-b7cb-03e584cbcd94', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '登陆编队', '登陆作战中参加夺占登陆场的各种舰船组成的海上编队。通常编为登陆输送队、海上掩护队、舰艇火力支援队、排雷舰艇队、海上保障队等。1个登陆编队可输送、掩护、支援1个师的登陆兵。', 67);
INSERT INTO `t_military_term_data` VALUES ('555e6df6-3c99-41fa-b791-e891ecb7da7c', '98df76fb-4b65-48ff-a56c-4db587327c79', '军事交通', '用于军事目的的陆地、水域、空中交通的统称。包括交通设施、机构和组织管理。', 243);
INSERT INTO `t_military_term_data` VALUES ('555f9ba7-dc49-4e06-911a-9ee8b9af6c6b', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克引导步兵', '坦克在步兵战斗队形之前引导步兵冲击的一种步坦协同形式。通常在地形利于坦克通行,敌反坦克火器和防坦克障碍较少的情况下采用。', 23);
INSERT INTO `t_military_term_data` VALUES ('5565c441-70ff-44af-ba27-8b4be4e49666', '8a761efd-50a6-4ac8-9913-b7d745104f82', '交叉射', '从两个以上方向对同一目标的射击。通常由正射、侧射、斜射、倒射等互相结合出现。', 111);
INSERT INTO `t_military_term_data` VALUES ('5586152b-eff4-4af7-9da3-8abbbeefae47', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '分进合击', '即进攻的军队分数路由不同方向对同一目标实施的攻击。', 105);
INSERT INTO `t_military_term_data` VALUES ('55880e95-cea4-4c21-bd9c-75c532505089', '98df76fb-4b65-48ff-a56c-4db587327c79', '野战手术车', '能在野战条件下对伤病员实施外科手术治疗的卫生专用车辆。车上通常配有手术台以及其他必需的设备和药品、器材等。', 227);
INSERT INTO `t_military_term_data` VALUES ('559509f9-2bce-4f39-a2ba-575b307df432', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防御', '抗击敌人进攻的作战行动。是作战基本类型之一。包括战略、战役和战术范围的防御。', 394);
INSERT INTO `t_military_term_data` VALUES ('55991702-2e9e-42ae-9b32-037d6e9332b6', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '沙漠气候', '沙漠地区的大陆性气候。主要特征是：空气干燥,终年少雨或几乎无雨；气温日变化剧烈,地面最高气温可达60～80摄氏度,而夜间又很快降温,日较差可达50摄氏度以上。', 57);
INSERT INTO `t_military_term_data` VALUES ('55acbf29-2770-40d9-a8b7-74599bf381d6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '遥控水雷', '由遥控信号控制水雷引信起爆的非触发水雷。分为有线遥控水雷和无线遥控水雷。', 219);
INSERT INTO `t_military_term_data` VALUES ('55b8182c-3041-4694-8e86-970fc6c6fb5a', 'f0140091-c11a-48c9-8836-8aa94439dac0', '巷战', '在城镇、村落的街巷内进行的作战。通常是对建筑物、街垒、制高点进行争夺,形成许多独立的短兵相接的战斗。', 17);
INSERT INTO `t_military_term_data` VALUES ('55e0f0f9-a442-4ff9-9aa1-a58ed9471721', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '延期引信', '撞击目标后,经引信内的延期装置延迟一段时间后再引爆弹丸的引信。其延迟时间有的是固定的,有的在射击前可调整。主要配用于穿甲弹、爆破弹、杀伤爆破弹和混凝土破坏弹。', 333);
INSERT INTO `t_military_term_data` VALUES ('55ff10a4-7978-4108-83cd-7a5ec2fe7e9b', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击目标', '使用核武器打击的具有重要价值的目标。如重要的军事目标、工业目标、城市目标、交通目标等。打击上述目标可对敌方的军事、政治、经济及社会心理等产生重大影响。', 157);
INSERT INTO `t_military_term_data` VALUES ('560ab9c8-2168-4a99-aa82-ff04c67f3c4b', '83e065b4-6737-4645-9ea5-8276d1de13ed', '战伤坦克', '被击伤而失去规定功能,但尚可修复的坦克。', 202);
INSERT INTO `t_military_term_data` VALUES ('5614bfd1-e58d-4124-ba88-f2060d2fe1b0', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '旅', '由若干个营编成的、一般相当于副师级的军队一级组织。通常隶属于集团军（军）。设有领导机关,编有战斗和勤务保障分队。为战术兵团。', 17);
INSERT INTO `t_military_term_data` VALUES ('5623cb8b-27d2-42e8-afeb-82b42cfd7351', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '机动战', '军队在战场上借助现代快速运载工具,以广泛实施机动、灵活变换战法为基本特征的作战形式。是运动战在现代条件下的新发展。', 140);
INSERT INTO `t_military_term_data` VALUES ('562502c5-3601-4d5d-9179-9962faef2c7d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇修理', '为恢复舰艇性能而采取的维修活动。分为计划修理和临时修理。计划修理分为坞（排）修、小修、中修和大修；临时修理包括日常临时修理、事故修理和战损修理。', 341);
INSERT INTO `t_military_term_data` VALUES ('56269209-ac23-4478-96d0-db0986eeca08', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵护送射击', '步兵、坦克冲击或反冲击时,炮兵为支援其行动、护送其前进而逐次转移火力的射击。', 180);
INSERT INTO `t_military_term_data` VALUES ('563ccbea-b168-4e46-ab2b-e33f97fd24e4', '06a75831-13a1-4660-870a-455bb445336a', '通信枢纽转移', '通信枢纽从原所在地域转移至新的地域的行动过程。包括通信枢纽的撤收、转移,在新地域的展开以及在转移过程中的通信联络等。通常采取随同指挥所转移的方式分批逐次转移或一次转移。', 78);
INSERT INTO `t_military_term_data` VALUES ('56415c28-b85f-493a-b278-e76c96f934e6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海道测量船', '亦称水道测量船。专门用于海区和航道勘测的勤务舰船。分为海洋测量船、近海测量船和沿岸测量船。', 155);
INSERT INTO `t_military_term_data` VALUES ('564313ba-48a2-4fd4-8263-95b8714e4156', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '协同', '各种作战力量按照统一的协同计划在行动上的协调配合。按范围,分为战略协同、战役协同和战术协同；按军兵种,分为军种之间的协同、兵种之间的协同等。', 308);
INSERT INTO `t_military_term_data` VALUES ('5650d1da-3024-4fe3-8160-4bd06ba428c7', '97a19170-bfac-42c5-9906-1acb187f0654', '空中格斗', '敌对双方歼击机或歼击直升机使用格斗空空导弹或航炮,在目视距离内以大动作量的机动飞行相互进行攻击。', 74);
INSERT INTO `t_military_term_data` VALUES ('5687bdf1-179e-4c90-afb8-3b2dbae37ebf', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '解除戒严', '结束戒严状态,恢复戒严地区的正常秩序。', 429);
INSERT INTO `t_military_term_data` VALUES ('56911a23-e80c-41ac-af76-1898b7ce7ad3', '06a75831-13a1-4660-870a-455bb445336a', '传真通信', '利用光电转换和扫描等技术设备传送文字、图表和照片等真迹的通信方式。主要用于传输战斗文书、电报、地形图、统计表报和照片等。', 139);
INSERT INTO `t_military_term_data` VALUES ('56948456-cc2c-4896-8d8c-dd4e1aa91f30', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵标定射击', '火炮装定预先测定的射击诸元,按间接瞄准操作要领进行的射击。通常在夜间对白天发现的固定目标进行射击时采用。', 168);
INSERT INTO `t_military_term_data` VALUES ('56a62dd3-c11a-45c7-9eeb-8b642e6f6fb9', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '探雷器材', '用以探测地雷等爆炸性障碍物位置的工程器材。主要包括探雷针、单兵探雷器、探雷车、机载式探雷器等。', 169);
INSERT INTO `t_military_term_data` VALUES ('56ac5b18-990c-4d92-ba4a-3e0c8905bac0', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '自我工程保障能力', '工程兵以外的各部队或分队以自身力量完成工程保障任务的能力。主要取决于部队的工程训练和工程装备的水平。', 17);
INSERT INTO `t_military_term_data` VALUES ('56b4ae22-0c4d-4f9c-a767-bf938154f54b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '港口吞吐量', '一定时期内船舶进出港口装卸货物的总量。是衡量港口生产能力的主要指标。通常以吨数表示。', 108);
INSERT INTO `t_military_term_data` VALUES ('56b78b46-d316-43ca-898c-92757def153c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '冲击波聚焦效应', '核爆炸远区的弱冲击波受某些气象条件影响,使空中冲击波折向地面,产生会聚加强的现象。聚焦区内的冲击波超压大大超过该距离处正常情况下的冲击波超压,对建筑物可造成破坏,甚至影响飞行中飞机的安全。', 160);
INSERT INTO `t_military_term_data` VALUES ('56daa87d-409b-477c-8799-301db0360dee', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '备考文书', '供指挥员及其指挥机关定下决心、拟制计划和指挥部队行动时查考的各种资料性军用文书。如实力统计、敌我兵力对比,作战物资统计,作战计算、战役或战斗数学模拟数据,阵中日记等。', 114);
INSERT INTO `t_military_term_data` VALUES ('56daf735-210d-4df2-98e7-d719ed1600a4', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '开阔地', '地面平坦、视界开阔的地区。军事上便于观察和射击,但不便于隐蔽。', 120);
INSERT INTO `t_military_term_data` VALUES ('56e0fc89-11bb-4dc6-b221-29159185d4f5', '98df76fb-4b65-48ff-a56c-4db587327c79', '伤类', '伤员致伤原因的类别。通常接致伤武器和致伤因素来划分。中国人民解放军现行伤类区分为炸伤、枪伤。刃器伤、挤压伤、冻伤、烧伤、冲击伤、毒剂伤、复合伤、核武器伤等10类。', 187);
INSERT INTO `t_military_term_data` VALUES ('56e80fc4-ae2d-4208-844b-13fa2c2c1b3b', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '超编', '实有建制单位、人员或武器装备的数量多于编制规定的数额。', 71);
INSERT INTO `t_military_term_data` VALUES ('56eea3b2-6048-48bd-82d7-c4a08b89d5e7', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '压发地雷', '直接受到目标一定的压力作用而发火的触发地雷。配用压发引信。爆破型防步兵地雷和反坦克履带地雷多为压发地雷。', 136);
INSERT INTO `t_military_term_data` VALUES ('56fa2d53-52c8-4685-9d7a-67c10a8c3973', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反封锁', '以军事手段及相关措施打破敌之封锁的作战行动。', 421);
INSERT INTO `t_military_term_data` VALUES ('57007662-84c3-4cee-958a-5dacb3ea0ae7', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '党日', '中国共产党的基层组织进行党内活动的专门时间。活动内容主要包括：召计党的会议,进行党的教育,开展组织生活,发展党员等。', 45);
INSERT INTO `t_military_term_data` VALUES ('57061a8f-0432-475e-9d26-02748deb27a7', '878651de-adf5-4c72-9376-9c363b893ff8', '战略部署', '为达成战略目的而对力量、行动或工作所作的总体布置和安排。', 77);
INSERT INTO `t_military_term_data` VALUES ('57180a9f-a831-4990-b1f8-ba537bbfa04e', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '化学火箭发动机', '利用火箭推进剂的化学反应（燃烧）而产生推力的火箭发动机。包括固体火箭发动机、液体火箭发动机和固液混合火箭发动机。是现代火箭技术中最重要的动力装置,广泛用于各种导弹、运载火箭和航天器。', 35);
INSERT INTO `t_military_term_data` VALUES ('57204a0b-cb0b-4cc9-b98b-443e08d4b212', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '漕渡航次', '门桥等浮游结构物从己岸装载,漕行至对岸卸载,再返回己岸的漕渡作业周期。', 330);
INSERT INTO `t_military_term_data` VALUES ('57301ce9-a88a-420e-b83f-6d10f213ec8a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '电子侦察', '使用电子技术器材截收有关电磁辐射信号的侦察。包括无线电技术侦察、雷达侦察等。', 54);
INSERT INTO `t_military_term_data` VALUES ('5735a89d-cead-4a26-98e6-c08f7d2aaf61', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '职务等级', '军队中对编制规定的各种职位等级的划分。如正军级、副军级、正连级、副连级等。', 100);
INSERT INTO `t_military_term_data` VALUES ('57465709-db01-456a-b703-aa5d9a109fb0', '878651de-adf5-4c72-9376-9c363b893ff8', '世界大战', '敌对国家集团之间,在世界范围进行的大规模战争。通常指第一次世界大战和第二次世界大战,以及未来可能发生或可能避免的世界性大规模战争。', 8);
INSERT INTO `t_military_term_data` VALUES ('574e1949-dfb6-4dab-81cb-095a600c4198', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克火力运用', '①坦克连、排指挥员对所属坦克火力的组织和使用。②泛指合成军队指挥员对坦克火力的运用。', 43);
INSERT INTO `t_military_term_data` VALUES ('574fc347-94bb-41d0-9fd5-4bb93a7aeaf9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '地幅', '军队陆上作战部署及行动所涉及的一定空间范围。通常在标示作战地区时使用。', 302);
INSERT INTO `t_military_term_data` VALUES ('5782cedc-df5c-4587-888d-65c7920a7850', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器安全性', '轻武器不出现危及操作者安全的性能包括机件的动作不伤及射手近邻；弹药不出现膛外发火；爆炸弹丸不出现膛炸和飞出后早炸；手榴弹不伤及安全半径外的投掷者等。', 226);
INSERT INTO `t_military_term_data` VALUES ('5792f0c4-f6a5-4bb2-8785-4f0bb7f20e9d', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '再入测量', '对导弹弹头和航天器返回舱等再入体返回大气层时的弹道参数和特征现象的观测。包括再入弹道测量、再入遥测、目标特性测量、多目标测量、落点测量等。主要用以检验再入体的弹道性能、结构性能和烧蚀防护性能,鉴定运载火箭的制导精度和再入散布（理论落点与实际落点之差）,以及研究再入的特殊现象。', 287);
INSERT INTO `t_military_term_data` VALUES ('57a33bb5-472e-40ce-8c29-05029dc4c6d9', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '掩盖工事', '采用支撑结构并在顶部设有防护层的工事。', 55);
INSERT INTO `t_military_term_data` VALUES ('57ad4253-16dd-467a-9a20-1edadb8ed605', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '红外诱饵', '投射到空中能产生类似被保护目标特征的红外辐射,以欺骗红外寻的导弹的光电干扰器材。主要有红外干扰弹、热气球诱饵、燃油类诱饵等。广泛应用于飞机、舰艇和坦克的自卫。', 131);
INSERT INTO `t_military_term_data` VALUES ('57b99ddb-1533-44b3-97d8-154288e0e76b', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '换班计划', '组织实施换班的计划通常由交接班部队或分队指挥员根据换班命令的内容与规定并经过现地勘察后共同制定。', 105);
INSERT INTO `t_military_term_data` VALUES ('57be9de9-af53-42e1-8d35-ed5bae65f10c', '878651de-adf5-4c72-9376-9c363b893ff8', '战争法', '国际社会以条约和惯例的形式调整、约束战争行为的法律准则。主要包括：处理交战国之间关系的规则,协调交战国与中立国之间关系的规则,规范作战行为的规则,制裁发动侵略战争的国家和惩办战争罪犯的规则等。', 35);
INSERT INTO `t_military_term_data` VALUES ('57c08e8d-7541-4d1c-bdd1-fb305deec56c', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事测绘保障', '为满足部队作战、训练、科研等对军事测绘方面的需要而采取的各种保证性措施和进行的相应活动的统称。主要包括；测定大地控制网和重力场的精确数值,测定海洋控制点、水深、地磁差值等,测绘陆地和海底地形图,对军用道路、机场、基地、坑道、海港进行工程测量,编绘、印制和供应地形图、海图、航空图、大地控制点和军用控制点等成果资料,调查和编制战区兵要地志等。', 147);
INSERT INTO `t_military_term_data` VALUES ('57c828ab-4785-448e-b261-6a22a565fec1', '98df76fb-4b65-48ff-a56c-4db587327c79', '供血站', '军队供应血液和生产血液制品的卫勤专业机构。负责血液采集、血液制品生产,血液和血液制品的检验、储存、分配、运送等。', 216);
INSERT INTO `t_military_term_data` VALUES ('57ca0d74-9d2e-4ff2-ba0e-9bce0aaae989', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上会合', '两艘以上舰艇或两个以上舰艇编队在预定海区聚集的行动。有集中会合和分别会合。通常用以编组海上编队、接护舰艇或进行海上补给等。', 37);
INSERT INTO `t_military_term_data` VALUES ('57cfcab2-739d-4ae8-a75e-f92026386148', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军战略', '筹划和指导海军运用与建设的方略。从属于军事战略。', 19);
INSERT INTO `t_military_term_data` VALUES ('57d3b9b3-ea45-4179-b8c6-4accb6839f82', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '太空监视', '亦称空间监视。通过卫星、雷达和光学跟踪仪器等专用技术设备,对太空目标进行的跟踪和探测。以识别和判明外层空间各种飞行器的国别、用途、形状、尺寸、轨道参数和核试验情况等。', 33);
INSERT INTO `t_military_term_data` VALUES ('57d91572-768d-4eef-b2ca-d9abc8595991', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '捕捉战机', '寻找并抓住有利于对敌采取作战行动的时机。', 33);
INSERT INTO `t_military_term_data` VALUES ('57dde5c8-23ed-411c-a17d-fd00479dab62', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '诡雷', '设有诡计装置或利用诱惑物及其他欺诈手段制作和设置的地雷。分为制式诡雷和应用诡雷。通常设置在有计划撤离的地区内和敌可能接近的地点,也可设置在地雷场内。', 149);
INSERT INTO `t_military_term_data` VALUES ('57e740ea-5da1-4bf7-a3c1-067afdad1b96', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '实际控制线', '相邻国家在边境地区的实际控制范围所能达到的界线。它与条约线或传统习惯线有时并不一致。', 87);
INSERT INTO `t_military_term_data` VALUES ('57f2e9a6-3faa-4dc2-bfe5-81acd488531a', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹阵地管理', '按照作战要求和有关的规章制度对导弹阵地进行的管理。主要包括；对阵地设施、设备,技术资料,物资经费,战斗、维护人员的活动等方面的管理。', 204);
INSERT INTO `t_military_term_data` VALUES ('58169bb4-8168-4f15-8f4a-dcd4eabdd4e8', '98df76fb-4b65-48ff-a56c-4db587327c79', '佯动运输', '为隐蔽真实意图给敌人以假象而组织的运输。', 253);
INSERT INTO `t_military_term_data` VALUES ('582264fb-6900-4447-8fea-c7127110d6a4', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹飞行再入段', '弹道导弹的弹头从再入大气层开始至命中目标的一段弹道。是导弹飞行被动段的最后一段。', 77);
INSERT INTO `t_military_term_data` VALUES ('5825fa1e-2d24-4a8a-baa4-4a30576b17ca', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '调理员', '军事演习中、导演部派往演习部队或分队的具体负责诱导、检查、裁决和评定等工作的人员。有地段调理员、端末调理员等。', 129);
INSERT INTO `t_military_term_data` VALUES ('582cc710-98d9-4c30-bdaf-b48df7258ed0', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '岗位责任制', '军队中关于各级各类人员按其工作岗位各司其职、各负其责的制度。', 11);
INSERT INTO `t_military_term_data` VALUES ('583171e6-7ff1-4206-9332-2d1c28b1c458', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学观察', '为发现敌化学袭击征候、判明袭击情况而组织的观察。主要任务是：发现敌化学袭击情况,判明毒袭区位置和毒云传播方向,并迅速上报和报警。', 50);
INSERT INTO `t_military_term_data` VALUES ('583376d2-0fc2-4ab6-9755-cf6c2fe2f938', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '令行禁止', '有令即行,有禁则止,一切行动听指挥。', 43);
INSERT INTO `t_military_term_data` VALUES ('585c3701-ac3d-45fc-be1e-1e94df83b011', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹核武器', '亦称核导弹。装有核弹头或核战斗部的导弹。', 2);
INSERT INTO `t_military_term_data` VALUES ('585d5f4b-a697-47f6-9c43-dd23ae2914b9', 'f0140091-c11a-48c9-8836-8aa94439dac0', '阻援', '阻击增援之敌的战斗行动。', 250);
INSERT INTO `t_military_term_data` VALUES ('586f6c34-79a1-4d22-aced-bf65c543f400', '97a19170-bfac-42c5-9906-1acb187f0654', '空军战役', '由空军战役军团单独或在其他军兵种协同下实施的合同战役。通常包括空中进攻战役、防空战役和空降战役。', 31);
INSERT INTO `t_military_term_data` VALUES ('58746d3f-3773-4f77-8d6f-cf2547a8c3e2', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '专业技术训练', '专业部队、分队及人员进行的以专业技术理论知识和技能为主要内容的训练。', 78);
INSERT INTO `t_military_term_data` VALUES ('58764435-88a5-4278-b49e-0e3d36b7fe26', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤基地', '在战略、战役后方建有相对固定的后勤机构和设施,并集中储备一定物资的基地。分为战略后勤基地、战役后勤基地以及海、空军后勤基地等。', 14);
INSERT INTO `t_military_term_data` VALUES ('58928a05-5e32-424e-ac8f-0bf35adc5679', 'f0140091-c11a-48c9-8836-8aa94439dac0', '水网稻田地战斗', '在沟渠纵横、水塘密布、稻田遍地的区域进行的战斗。部队机动受限,构筑工事困难,对部署兵力兵器和协同动作影响较大。', 7);
INSERT INTO `t_military_term_data` VALUES ('58997ce1-de9e-47be-960f-5641e50f5911', '916997ee-6728-4c61-9b79-d96960b1dc86', '地面照射量率衰变规律', '沾染区内照射量率随时间的推移而衰减的规律。爆炸方式不同,地面照射量率衰变规律也不同。依此规律可以计算出沾染区某处任意时刻的地面照射量率。', 102);
INSERT INTO `t_military_term_data` VALUES ('58a0b235-ee0d-495b-82da-1115b31f4ffc', '878651de-adf5-4c72-9376-9c363b893ff8', '正义战争', '符合人民的根本利益,推动社会进步的战争。包括抵抗反动阶级压迫、争取民族解放、抵御外来侵略、维护国家统一和世界和平等而进行的战争。', 22);
INSERT INTO `t_military_term_data` VALUES ('58b68696-5652-4d21-8851-53c98236d375', '98df76fb-4b65-48ff-a56c-4db587327c79', '铁路保障', '为战时铁路运输的顺利实施而进行的保障。主要措施包括：预防敌人和自然灾害时铁路的破坏,修复被破坏的铁路,抢建新铁路线,实施铁路运输军事管理等。', 259);
INSERT INTO `t_military_term_data` VALUES ('58bbd274-8004-4df3-b72e-3f336f2d9982', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克潜渡', '坦克按规定的技术条件密封后,借助潜渡装置从水底通过江河障碍的行动。分为入水前准备、水下行驶和出水后启封三个阶段。', 61);
INSERT INTO `t_military_term_data` VALUES ('58bc205d-5a9f-46d2-b49d-b5092ddbd792', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防会晤', '相邻两国边防部门就一般边境涉外事务进行交涉、处理的会见活动。通常由双方边防代表在预定的边境地点进行。', 121);
INSERT INTO `t_military_term_data` VALUES ('58bd3252-4663-4cdc-8aa9-e2a34edf5809', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '经纬仪', '测量水平角和高低角的测角仪器。用于大地测量、工程测量、战场侦察和其他测量工作。常用的有测地经纬仪、天文经纬仪,以及电影经纬仪、工具经纬仪等。', 73);
INSERT INTO `t_military_term_data` VALUES ('58c1cd94-21ce-4029-8349-4e52f5f67d18', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队组织工作', '中国共产党在中国人民解放军中进行的党的组织建设及共青团建设和连队军人委员会建设的工作。是中国人民解放军政治工作的重要内容。', 38);
INSERT INTO `t_military_term_data` VALUES ('58ce00eb-a290-4134-b740-fd8bf9a5a02b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '山口', '亦称垭口。高大山岭或山脊的鞍状坳口。通常是通过高山大岭的交通孔道。如唐古拉山口等。', 14);
INSERT INTO `t_military_term_data` VALUES ('58d00a64-812e-4cef-9ccb-951cc6e4f0cb', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '二次雷达', '通过向目标发射询问信号,并接收其应答信号进行工作的雷达。由地面雷达与飞行器上的应答机配合工作。具有作用距离远、不易受干扰等特点。军事上通常用于敌我识别、空中交通管制和火箭、导弹、卫星的跟踪测量等。', 101);
INSERT INTO `t_military_term_data` VALUES ('58d1bd7a-0f0e-40f7-bc22-199a4cb4d74d', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '逆温层', '大气中气温随高度的增加而升高的气层。逆温层中,空气十分稳定,不易发生垂直扰动,并能阻挡了层空气的上升运动。对流层中出现的逆温层,其底部常易聚集水汽、杂质,能见度较差。对航空器飞行和核、化学、生物武器的使用与防护等影响较大。', 9);
INSERT INTO `t_military_term_data` VALUES ('58df16ec-7c5a-4527-ba7a-709f9e650511', '878651de-adf5-4c72-9376-9c363b893ff8', '战略核力量', '装备有战略核武器的作战力量。通常包括陆基战略导弹部队、战略导弹潜艇部队和战略航空兵部队。', 92);
INSERT INTO `t_military_term_data` VALUES ('58e76144-963e-4307-b670-01142c9ebaca', '97a19170-bfac-42c5-9906-1acb187f0654', '目视飞行', '飞行员用目力观察天地线及地标,判断所驾驶的飞机或直升机的飞行状态及位置的飞行。通常用于气象良好的昼间飞行。', 213);
INSERT INTO `t_military_term_data` VALUES ('58ed587a-11cb-49af-8585-30d1ce6ee36a', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '武装力量动员', '国家根据战争需要,将军队和其他武装组织由平时状态转为战时状态的紧急措施。通常包括对现役军人、预备役人员和其他武装组织人员以及相应的武器装备和物资等的动员。', 50);
INSERT INTO `t_military_term_data` VALUES ('58f7613f-0eff-44f0-98b7-35b21133247b', '878651de-adf5-4c72-9376-9c363b893ff8', '战略要地', '亦称战略重地。对战争全局具有重大影响的地区。如政治、军事中心,重要工业区,交通枢纽,要塞等。', 89);
INSERT INTO `t_military_term_data` VALUES ('58ff6ae6-688e-4fab-b950-1d63239afb6f', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物战剂采样箱', '采集和保藏生物战剂标本的器材。用以采集空气中、水中、土壤及物体表面污染的生物战剂及昆虫和小动物尸体内脏标本。', 194);
INSERT INTO `t_military_term_data` VALUES ('5904b4da-6aa1-4d04-b17e-59edf9d4f1ae', '8a761efd-50a6-4ac8-9913-b7d745104f82', '橡皮弹', '弹丸由橡胶制成的枪弹、霰弹、榴弹的统称。主要用于防暴。使用中对弹丸作用于人体的动能常有限制要求、橡皮枪弹用枪械发射,一般使用距离为20～150米。橡皮榴弹和橡皮展弹由榴弹发射器贸弹枪发射一般使用距离为20～300米。', 194);
INSERT INTO `t_military_term_data` VALUES ('590559b9-5396-4359-bcf9-629866defcea', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地心坐标', '以地球质心为原点的坐标。包括地心空间大地直角坐标和地心大地坐标这两种坐标。之间存在着严密的数学关系,可互相换算。主要用以描述人造地球卫星和远程导弹在空间的位置。', 233);
INSERT INTO `t_military_term_data` VALUES ('5909009a-dad3-4c31-b675-1a176114152e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '地段调理员', '军事演习中负责调理某一地段演习活动的调理员。', 130);
INSERT INTO `t_military_term_data` VALUES ('590c15a1-a3f8-409a-9a4e-a2d2a6be90d1', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地球磁极', '地球磁场方向与地球表面垂直相交的点。有南磁极和北磁极。其位置受多种因素的影响随时间缓慢地移动。', 158);
INSERT INTO `t_military_term_data` VALUES ('59184218-b80e-4104-9986-60baefb416f6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上接敌', '舰艇由驻泊点或法机点驶向展外阵位所进行的机动、分为引导接敌和搜索接敌、要求行动迅速隐蔽、安全,准确占领展开阵位。', 80);
INSERT INTO `t_military_term_data` VALUES ('5923ca8a-85eb-449f-9116-9b2eae36c313', '916997ee-6728-4c61-9b79-d96960b1dc86', '沾染区', '放射性沾染区的简称。沾染有放射性物质并对军队和居民构成危害的区域。核爆炸沾染区通常分为爆炸地域沾染区（爆区）和放射性烟云径迹地带沾染区（云迹区）。也可按其危害程度,分为轻微沾染区、中等沾染区、严重沾染区和极严重沾染区。', 87);
INSERT INTO `t_military_term_data` VALUES ('592595ce-fce6-410b-9401-fe53766af528', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '单兵布雷器', '由单兵携带和操作的机动布雷器材。分为布撒防步兵地雷和布撒防坦克地雷的单兵布雷器。布雷距离为数十米至数百米,一次布雷数量可达数十枚,面积可达数百平方米至数千平方米。', 167);
INSERT INTO `t_military_term_data` VALUES ('592c272c-2d01-4fda-a9aa-d9c79eb2bdc0', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '空军情报', '空军作战所需的情报。主要来源于空军所属的专业侦察力量获取的情况,还来源于上级、参战飞行员、其他军兵种以及地方有关部门、民兵、人民群众等提供的情况。', 132);
INSERT INTO `t_military_term_data` VALUES ('593476d0-d1eb-468d-bc69-0f3ac5ab3b1c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克涉水深', '坦克在无任何辅助设备和器材的情况下,能安全通过规定水障碍的最大深度。一般为1～1.4米。', 167);
INSERT INTO `t_military_term_data` VALUES ('593a880d-d29e-420c-ac72-c9c20bf96778', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力延伸', '火力按计划逐次地向敌纵深伸展。可采取增大火器射程或变换发射阵地的方法实施。主要用以压制敌方,掩护己方,加快步兵、坦克的进攻速度。', 102);
INSERT INTO `t_military_term_data` VALUES ('5957b04d-4012-4824-badb-af966b3b11ee', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '三大纪律八项注意', '中国人民解放军军人必须遵循的基本行为准则和规范。是人民军队本质和宗旨的体现。三大纪律是：一切行动听指挥；不拿群众一针一线；一切缴获要归公。八项注意是：说话和气；买卖公平；借东西要还；损坏东西要赔；不打人骂人；不损坏庄稼；不调戏妇女；不虐待俘虏。', 26);
INSERT INTO `t_military_term_data` VALUES ('59618067-2b21-4dc1-889b-d3f466e6977d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '军用索道桥', '在锚固于河、谷两岸的一排缆索上铺设桥面结构而成的军用桥梁。通常架设于山地的江河、峡谷或其他不宜架设浮桥和固定桥的地方。', 280);
INSERT INTO `t_military_term_data` VALUES ('5963365d-022c-4bb8-8419-1470101afaf1', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '歼击直升机', '专门设计制造的以航炮、航空火箭、空空导弹为基本武器,主要用以歼灭敌空中目标的武装直升机。必要时也可用以突击地面或水面目标。', 7);
INSERT INTO `t_military_term_data` VALUES ('5965c57b-2eb0-4994-afa0-7b4a1056cd1a', '97a19170-bfac-42c5-9906-1acb187f0654', '轰炸兵力计算', '对预定轰炸目标进行的空中突击兵力和预期空中突击效果的计算。可根据预定出动的空中突击兵力,计算预期空中突击效果；也可根据预期空中突击效果,计算需出动的空中突击兵力。', 195);
INSERT INTO `t_military_term_data` VALUES ('59748e9d-d0dd-4039-b4b8-37dc66ec760e', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '超视距雷达', '亦称超地平线雷达。利用电磁波的电离层折射或地球表面统射效应,探测地平线以下远距离目标的雷达。分为天波超视距雷达和地波超视距雷达。探测距离远,但分辨力较低。军事上通常用于对远程导弹、战略轰炸机的早期预警，以及对低空飞机、巡航导弹、海面舰艇的警戒等。', 97);
INSERT INTO `t_military_term_data` VALUES ('59899527-31f4-41d6-888f-88541d33b5e8', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '空包弹', '没有弹头,弹壳内装有发射药的枪弹、炮弹。发射时产生声响。用于战术演习和鸣放礼炮。', 191);
INSERT INTO `t_military_term_data` VALUES ('599cd972-15c9-4673-a896-ea647819608d', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '现地勘察计划', '组织实施现地勘察的计划。', 93);
INSERT INTO `t_military_term_data` VALUES ('59a5679a-f0c3-4bb5-99f1-50cdb858a9d6', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '地球同步轨道', '轨道周期与地球自转周期（23时56分4秒）相同的人造地球卫星轨道。也有人把轨道周期的整数倍等于地球自转周期的人造卫星轨道称为地球同步轨道。', 236);
INSERT INTO `t_military_term_data` VALUES ('59bc995b-939d-4cc1-a35a-a2167c218c6c', '97a19170-bfac-42c5-9906-1acb187f0654', '航空烟幕炸弹', '爆炸后产生烟幕以迷盲敌人或标示目标的航空炸弹。', 329);
INSERT INTO `t_military_term_data` VALUES ('59c11929-f9cb-47af-8844-590b045593f8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '裁军', '国家或政治集团削减军备的活动。', 89);
INSERT INTO `t_military_term_data` VALUES ('59d65ad6-656c-4abc-b50f-a0918086a5cb', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术机动', '为达成一定的战斗目的而组织实施的兵团以下的兵力兵器移动。基本样式包括战术包围、战术迂回、战术穿插、战术渗透和战术开进等。', 30);
INSERT INTO `t_military_term_data` VALUES ('59eb8e7d-0271-4de3-952a-9f52968b3f41', '06a75831-13a1-4660-870a-455bb445336a', '简易信号通信', '使用简易信号通信工具、就便器材和简便方法,按照规定的信号或记号传递信息的通信。通常用以传递简短命令、报告情况,以及识别敌我、指示目标、协同动作等。', 132);
INSERT INTO `t_military_term_data` VALUES ('59f147e9-f630-4f12-b41c-8cec55dcb47e', '98df76fb-4b65-48ff-a56c-4db587327c79', '输油管线', '由输油管、泵站及其他设备组成的用于长距离输送油料的整套技术装备。分为固定输油管线和野战输油管线。', 179);
INSERT INTO `t_military_term_data` VALUES ('59f345a1-eb61-49ea-a5f1-d404d9c1a58d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海岸雷达', '亦称岸防雷达。设置在海岸用于对海防御的各种雷达的统称。包括对海警戒（监视）雷达、岸炮炮瞄雷达、岸舰导弹制导雷达等。通常装备于观通站,岸炮、岸导阵地以及沿海的观察哨和观察所。', 231);
INSERT INTO `t_military_term_data` VALUES ('59f951b1-059b-4efe-8e51-46c3924aa24a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮器材瞄准点', '供火炮、器材瞄准或标定用的目标或物体上的某一点。夜间瞄准点通常设在火炮左后方或右后方200米以外,两瞄准点对火炮的夹角不小于10－00。当炮兵连内各炮不便于使用同一瞄准点时,也可分别设置。', 277);
INSERT INTO `t_military_term_data` VALUES ('5a0bfd4c-eda1-4ff1-ab45-3fddea43e21f', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '现役', '公民在军队中服兵役。包括军官的现役和士兵的现役等。', 145);
INSERT INTO `t_military_term_data` VALUES ('5a1ac3fe-b865-4034-8ca9-c36b6d1d809e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火佯动', '炮兵以火力突击非主要目标，以隐蔽己方真实作战意图的作战行动。', 81);
INSERT INTO `t_military_term_data` VALUES ('5a1d2896-7b0c-4eb2-bee8-ac1b4d06ee22', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察要图', '亦称情况要图。标绘有已查明的与作战有关的敌情、地形、社情等重要情况的图。供指挥员判断情况、定下决心作参考。', 108);
INSERT INTO `t_military_term_data` VALUES ('5a1f5e93-ca32-440e-9107-267fd6eea9e9', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆浮力储备', '具备浮渡能力的装甲车辆在战斗全重状态下停于静水中,其吃水线以上部分的水密容积所能提供的浮力。一般以浮力储备系数（储备浮力与车辆战斗全重的百分比）表示。其值主要取决于车体的外廓尺寸、密封情况和战斗全重等,一般为20％～30％。', 169);
INSERT INTO `t_military_term_data` VALUES ('5a22b198-c7cf-4f9e-9502-3c7b18f780e6', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '聚变反应', '简称聚变,亦称热核聚变反应或热核反应。在极高温度下两个较轻原子核合成一个较重原子核同时释放巨大能量的核反应。', 114);
INSERT INTO `t_military_term_data` VALUES ('5a260ea2-b513-42e3-99d7-d60903de33ab', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '照相侦察卫星', '用光电遥感器提取地面目标图像的侦察卫星。主要侦察设备有可见光与红外照相机、扫描仪、电视摄像机、多谱段照相机、侧视雷达等。具有图像分辨率高、侦察范围大、不受国界限制等特点。有的还具有全天候侦察能力。', 208);
INSERT INTO `t_military_term_data` VALUES ('5a2eed05-d112-4a4e-8cad-47ae2f5df239', '06a75831-13a1-4660-870a-455bb445336a', '载波电报机', '利用频率分割原理进行多路复用的电报通信设备。有音频载波电报机和插报机。音频载波电报机利用一个载波话路的频段,可开通16～24个报路,是军用电报通信的主要终端设备。插报机利用载波话路未占用的超音频段或载波话路的高音频段,可开通1～6个报路、多用于野战通信。', 191);
INSERT INTO `t_military_term_data` VALUES ('5a5523b1-1e61-4e46-b520-d55ab799cc9c', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂战斗状态', '毒剂在战斗使用中发挥杀伤作用的状态。通常有蒸气、气溶胶和液滴三种状态。毒剂蒸气可通过呼吸道侵入机体造成中毒,毒剂气溶胶可通过呼吸道、眼睛和皮肤引起中毒,毒剂液滴可通过皮肤侵入机体造成中毒。', 28);
INSERT INTO `t_military_term_data` VALUES ('5a7c7f40-2bf5-438a-b92e-86e82999767d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地图图式', '简称图式。测绘地图所用地图符号的技术规定。包括地图符号的图形、尺寸、颜色、注记以及图廓整饰和说明等。是测制和识别地图的依据。', 275);
INSERT INTO `t_military_term_data` VALUES ('5a922483-3073-4929-817e-4356721202ef', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机机动作战', '直升机部队或分队根据战场的实际情况,积极移动兵力,随机、灵活地进行作战。', 70);
INSERT INTO `t_military_term_data` VALUES ('5a980fd9-c01d-419b-b3a0-b2777d98ef26', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '政治委员制', '中国人民解放军在团或相当于团级以上的部队和单位设立政治主官的制度。政治委员与同级军事主官同为所在部队和单位的首长,在同级党的委员会领导下,对所属部队和单位的各项工作共同负责。政治委员是党的委员会日常工作的主持者。', 21);
INSERT INTO `t_military_term_data` VALUES ('5a9ab6a5-e281-4baf-9c3a-6e968eabfcac', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '抵近干扰', '将干扰设备尽量靠近敌方配置,以对敌电子设备实施近距离电子干扰的战术。', 66);
INSERT INTO `t_military_term_data` VALUES ('5aa3b240-5bbb-4248-bfaf-f4adeb6e1e5d', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '战术核武器', '弹道式导弹的简称。飞行轨迹绝大部分为自由抛物体轨迹的导弹。由火箭发动机推送到一定高度和取得一定速度及弹道倾角后,发动机关闭,弹头沿着预定弹道飞向目标。为提高命中精度,有的弹道导弹在弹头再入大气层后的最后飞行段,也能实施制导。', 101);
INSERT INTO `t_military_term_data` VALUES ('5aa57280-4949-4001-b486-3e4ecc92fa58', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队性质', '军队根本的政治属性。中国人民解放军的性质,是中国共产党缔造和领导的,用马克思列宁主义、毛泽东思想、邓小平理论武装起来的人民军队,中华人民共和国的武装力量,人民民主专政的坚强柱石。中国人民解放军永远忠于党,忠于人民,忠于国家,忠于社会主义。', 1);
INSERT INTO `t_military_term_data` VALUES ('5aa69e99-8c81-4b45-b2dd-4d589c337147', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '武装侦察', '以战斗行动进行的侦察。主要包括战斗侦察、火力侦察、搜索、捕俘等。', 12);
INSERT INTO `t_military_term_data` VALUES ('5aca62c4-5ba5-40c2-a723-166a195cf5a7', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹特种战斗部', '装有特殊装填物,具有特种破坏力的导弹战斗部。主要有化学战斗部、生物战斗部、燃烧战斗部、干扰战斗部等。', 23);
INSERT INTO `t_military_term_data` VALUES ('5ad46c75-b832-4b00-a13c-39f416d125ed', '98df76fb-4b65-48ff-a56c-4db587327c79', '礼服', '军人在重大节日和参加庆典、检阅及重要外事活动时穿着的军服。', 155);
INSERT INTO `t_military_term_data` VALUES ('5ad84660-06b6-4448-a9ef-e5c4307c7f56', '98df76fb-4b65-48ff-a56c-4db587327c79', '定点保障', '在固定地点开设保障机构实施的后勤保障。通常在部队驻止时采用。亦可用以为过往部队提供后勤保障。', 27);
INSERT INTO `t_military_term_data` VALUES ('5af078f9-9d6e-4b1a-8d66-0d84b6a33b49', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '大陆架', '陆地向海面下自然延伸和缓倾的浅水平台。其范围从低潮线起到海底坡度突然变陡处止。国际法上是指邻接一国海岸,但在领海以外的一定区域的海床和底上。沿岸国有对其行使勘探和开发自然资源为目的的主权权利。', 56);
INSERT INTO `t_military_term_data` VALUES ('5af25275-0ccf-4c7d-9dbf-d0b0ce75e93b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '集团装药', '外形长度不大于最小横向尺寸5倍的爆破装药。广泛用于土石爆破、水下爆破和对军事设施、技术装备的破坏。', 224);
INSERT INTO `t_military_term_data` VALUES ('5af74bb7-35fe-4bee-868a-44c9621e11c7', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '普通地图', '综合反映地表自然要素和社会经济现象的地图。分为地形图和地理图。使用范围广,也是编制各种专用地图的基础。', 251);
INSERT INTO `t_military_term_data` VALUES ('5b020b89-046f-4708-a15d-52d8874d6ac9', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '时差定位', '亦称反罗兰定位。根据电磁辐射源的同一脉冲信号到达三个以上观测点的时间差确定辐射源的位置。时差定位可获得很高的定位精度。', 38);
INSERT INTO `t_military_term_data` VALUES ('5b09f008-e041-4fd3-ad88-577bf6b3d560', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹作战基地', '使用地地导弹遂行作战、训练等任务的基地。编有指挥机构、导弹部队、工程等各种保障部队和分队,建有指挥所、导弹发射阵地和各种保障设施。', 2);
INSERT INTO `t_military_term_data` VALUES ('5b0a16d1-defe-4fbe-af12-59f64779dfcd', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵侦察', '炮兵为获取作战行动所需的情报和资料而进行的侦察。包括炮兵地面侦察、航空侦察以及炮兵测地、气象、照相勤务等。', 103);
INSERT INTO `t_military_term_data` VALUES ('5b0b2bee-25fe-40e6-93b6-472ff85f004e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '激光近炸引信', '用引信发出的激光控制引爆的近炸引信。一般配用于导弹和火箭弹。', 336);
INSERT INTO `t_military_term_data` VALUES ('5b148a9b-3d41-470b-bd8c-89f687f31114', '31f4a446-5b98-4873-9d53-310d97125b07', '核毁伤程度', '核爆炸对目标毁伤的轻重状况。按毁伤程度,分为完全毁伤、严重毁伤、中等毁伤和轻微毁伤等。', 152);
INSERT INTO `t_military_term_data` VALUES ('5b18841c-9e31-4b38-8bfa-9170229f4682', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行调配', '飞行管制部门协调、安排航空器飞行次序的工作。分为预先调配、飞行前调配和临时调配。通常包括飞行高度调配、飞行次序或飞行时间调配、飞行航线或飞行空域调配等。', 376);
INSERT INTO `t_military_term_data` VALUES ('5b1fdf99-d126-408e-be5f-aa7a722da189', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆封存', '对技术状况良好、较长时间不使用的车辆采取的综合保护和控制使用的措施。包括清洁各部机件、解除负荷、除锈、涂油、补漆、密封包扎等。由旅或独立团以上的车辆勤务部门归口呈报,经部队首长批准后实施。', 313);
INSERT INTO `t_military_term_data` VALUES ('5b28c81f-8e54-4577-abd0-cec6579bf7bd', '97a19170-bfac-42c5-9906-1acb187f0654', '空中指挥', '①空中编队指挥员对所率编队或机群实施的指挥。②指挥员在空中指挥所或在担负空中指挥引导任务的飞机上,对所属部队作战或其他行动实施的指挥。', 186);
INSERT INTO `t_military_term_data` VALUES ('5b2fc6c0-f844-440f-8a53-05907f605b0c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '支援干扰', '掩护攻击机群遂行作战任务时,电子干扰飞机在距攻击目标一定距离上对敌方电子设备实施电子干扰的战术。按干扰飞机距离目标的远近,分为远距支援干扰和近距支援干扰。', 69);
INSERT INTO `t_military_term_data` VALUES ('5b3157ee-fa7f-43e1-95d8-ec5969d67304', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹近快战法', '地空导弹部队待空中目标接近或进入发射区时才打开制导雷达天线,迅速跟踪目标并快速发射地空导弹的战斗方法。有利于反敌空中目标机动和反电子干扰,出其不意地消灭空中目标。', 135);
INSERT INTO `t_military_term_data` VALUES ('5b37f2ae-c1b7-42c4-80d4-876cbf7a609d', 'f0140091-c11a-48c9-8836-8aa94439dac0', '急袭', '对敌实施急促而猛烈的袭击。', 151);
INSERT INTO `t_military_term_data` VALUES ('5b3ca036-f21c-4749-945c-91a2b74b15d4', '06a75831-13a1-4660-870a-455bb445336a', '光通信', '利用光信号传输信息的通信。按光源特性,分为激光通信和非激光通信。激光通信又分为光纤通信和大气激光通信。', 127);
INSERT INTO `t_military_term_data` VALUES ('5b3db3ae-03a2-4e93-a839-afbda9c365fe', '97a19170-bfac-42c5-9906-1acb187f0654', '空中强击', '简称强击。飞机或直升机从低空、超低空对地面或水面目标强行实施的空中突击。通常由强击机或攻击直升机实施。必要时也可由歼击机或歼击轰炸机实施。', 89);
INSERT INTO `t_military_term_data` VALUES ('5b44955f-928b-445d-aeab-6df0bcc64d7a', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '雷达敌我识别系统', '用于识别敌我飞机、舰艇、坦克等目标的雷达系统。由询问机和应答机组成。是现代战争中陆、海、空三军通用的敌我识别系统。分为地面雷达敌我识别系统、舰载雷达敌我识别系统和机载雷达敌我识别系统等。', 102);
INSERT INTO `t_military_term_data` VALUES ('5b4c1e79-8488-4c22-9d50-666a0fb30211', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇阵位', '海战中舰艇或舰艇编队为有利于实施战斗和充分发挥武器效能而占领的相对于攻击目标的位置、有战术展开阵位、攻击出发（预备齐射）阵位和攻击（齐射）阵位等、通常以目标方位或敌舰舷角、敌我距离和己舰舷角等要素表示。', 76);
INSERT INTO `t_military_term_data` VALUES ('5b4e7a21-a04f-402c-bf49-bc4d4c44ea63', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '速决战', '在较短时间内决出胜负的作战。相对于持久战而言。分为战略速决战、战役速决战和战斗速决战。通常是拥有优势兵力兵器或进攻的一方采取的作战方针。', 132);
INSERT INTO `t_military_term_data` VALUES ('5b59c726-d4bd-4fef-8936-3de62b8c9d3c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击条件偏差量', '炮兵射击时的实际射击条件对标准射击条件的偏差量。包括弹道、气象、地形等条件的偏差量。', 138);
INSERT INTO `t_military_term_data` VALUES ('5b5ce6c8-886e-459c-9607-88424ace0b21', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤指挥', '后勤指挥员及其指挥机构对后勤保障、后勤防卫和其他后勤工作进行的组织领导活动。包括对所属后勤机关、部队或分队的组织指挥和对下级部队后勤的业务指导。', 44);
INSERT INTO `t_military_term_data` VALUES ('5b63bf83-f93a-4611-b465-d9b840507f8c', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事辩证法', '关于军事问题的辩证唯物主义的认识论与方法论的学说。主要揭示构成战争运动的敌对双方各种因素的相互对立、依存、渗透和转化的一般规律。可为认识战争和实践战争提供认识论与方法论的指导。', 22);
INSERT INTO `t_military_term_data` VALUES ('5b6b910a-6068-4942-ab1e-9836911c3c1a', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮有效射击距离', '亦称有效斜距离。高炮位置至有效射击范围边沿的距离。100毫米高炮的有效射击距离为12800米,57毫米高炮有效射击距离为6000米,37毫米高炮有效射击距离为3500米,25毫米高炮有效射击距离为2500米。', 151);
INSERT INTO `t_military_term_data` VALUES ('5b775959-072c-42b2-b391-20fd7b97f1ed', '06a75831-13a1-4660-870a-455bb445336a', '光端机', '将电信号转换成发送的光信号和将接收到的光信号转换成电信号的通信设备。是光纤通信终端设备的重要组成部分。由光发送和光接收两部分组成。', 195);
INSERT INTO `t_military_term_data` VALUES ('5b84a44f-3e72-4ce8-aadb-11af2ef4126f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '主动', '军队在作战中能够按照己方意图自由行动的状态。', 268);
INSERT INTO `t_military_term_data` VALUES ('5b861393-6fc6-4239-93a1-068c5207976e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '陆军水雷', '供陆军在近海浅水域和江河湖泊中使用的水雷。按用途,分为防登陆水雷、江河水雷和特种水雷；按在水中的状态,分为锚雷、沉底雷、漂雷、高桩水雷和吸附水雷等。可用人工、船艇、飞机、火箭等布设。', 160);
INSERT INTO `t_military_term_data` VALUES ('5b8bd07d-a733-4595-837f-1bc46d4fc8bc', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击计算器', '炮兵用以计算射击诸元的电子计算器。重量轻，用简便,有利于快速确定射击诸元。是未装备射击指挥系统的炮兵营、连的主要射击指挥器材。', 296);
INSERT INTO `t_military_term_data` VALUES ('5b8db911-e967-4e2e-a5b1-d8072beb72ec', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '防险救生船', '用以救援和打捞失事的舰艇、飞机和落水人员及进行其他潜水作业的各种专用勤务舰船的统称。包括打捞救生船、救生船、潜水工作船、救助工作船、救助拖船、快速救生艇和消防船等。', 154);
INSERT INTO `t_military_term_data` VALUES ('5b977b2e-3137-42fa-9329-433788ac5c18', '98df76fb-4b65-48ff-a56c-4db587327c79', '军用集装箱', '配备给军队装运物资的有特殊标记代号的标准化容器。具有1立方米以上容积,备有快速装卸和转运装置,是配合各种运输工具反复使用的重要运输设备。分为通用集装箱和专用集装箱。', 271);
INSERT INTO `t_military_term_data` VALUES ('5bbe1c83-9253-428c-9f4e-026faa92973f', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '政治部（处）', '军队中主管政治工作的领导机关。中国人民解放军中的政治部（处）一般在团级以上部队或单位设立。在上级政治机关、本部队或单位党的委员会和政治委员的领导下,负责管理所属部队或单位党的工作,组织实施政治工作。', 5);
INSERT INTO `t_military_term_data` VALUES ('5bd0e3a8-551b-4b36-bb44-13026970013a', '916997ee-6728-4c61-9b79-d96960b1dc86', '轻便洗消器材', '对武器装备、车辆。工事口部等实施局部洗消的小型洗消器材。主要有坦克消毒器、手动洗消器和车炮消毒盒等。', 193);
INSERT INTO `t_military_term_data` VALUES ('5bd42555-5e71-4718-9cc8-e2cf286fcea6', '8a761efd-50a6-4ac8-9913-b7d745104f82', '发射', '由发射药或推进剂燃气能量等产生的膨胀力,将射弹从导轨或身管装置推送出去的过程。如火箭、导弹靠自身动力装置所产生的反作用力飞离发射装置，枪炮弹丸靠发射药燃烧产生的推力飞出身管等。', 0);
INSERT INTO `t_military_term_data` VALUES ('5c027b53-fa6f-4db6-addd-503c582c69c4', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击危险界', '在遮做界内弹道高不超过目标高的一段距离。', 68);
INSERT INTO `t_military_term_data` VALUES ('5c113c07-654f-44ce-a8d0-2a3b53baf746', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '放射性沾染效应', '核爆炸后产生的裂变产物、剩余核装料和感生放射性物质等对生态环境造成的污染和对生物体造成的伤害作用。放射性沾染的作用时间较长（几小时、几星期甚至更长）,作用范围较大。', 173);
INSERT INTO `t_military_term_data` VALUES ('5c201df4-3864-475e-a191-8546e9f8d103', '916997ee-6728-4c61-9b79-d96960b1dc86', '照射量率', 'X光或 γ射线辐射场中单位时间内的照射量。常用以衡量辐射场的辐射水平。单位是库仑／千克·秒。', 97);
INSERT INTO `t_military_term_data` VALUES ('5c2af1e4-f87e-44f4-b7fa-c2ebc1aaa628', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '分列式', '受阅部队或分队列队依次从检阅台前通过,接受阅兵营长检阅的仪式。', 68);
INSERT INTO `t_military_term_data` VALUES ('5c57ac98-089c-4791-ac4c-97f0da69f671', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '文化素质', '军人在科学文化知识、艺术审美和学识水平等方面所具有的素养。提高军人文化素质,适应现代条件下高技术战争的要求,是军队政治工作的重要内容。', 31);
INSERT INTO `t_military_term_data` VALUES ('5c57f276-0936-4b57-a44f-d5f3e9d0ee12', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力压制', '以火力毁伤敌部分兵力兵器,使之暂时不能还击并限制其机动。', 101);
INSERT INTO `t_military_term_data` VALUES ('5c64afef-43bc-4b33-a910-c44f9f0bd480', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '轮训', '对受训对象分期分批进行的短期集中训练。', 144);
INSERT INTO `t_military_term_data` VALUES ('5c6cb9b1-058e-496e-886e-f7792f56cafb', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '掩蔽部', '安装有防化设施,容积较大、较坚固的人员掩蔽工事。供人员工作和休息。有分队掩蔽部、指挥所掩蔽部和救护所掩蔽部等。', 68);
INSERT INTO `t_military_term_data` VALUES ('5c70d6c2-8879-4c88-8e14-a8dd12c5458a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天测控网', '简称测控网。对航天器飞行状态进行跟踪测量,并控制其运动和工作状态的系统。通常由航天控制中心和若干航天测控站（包括测量船和测量飞 机）组成。用以测定和控制航天器的运动,检测和控制航天器上各种装置和系统的工作,接收来自航天器的专用信息,与载入航天器的乘员进行通信联络等。', 267);
INSERT INTO `t_military_term_data` VALUES ('5c7db7a4-4cd9-4f9b-9376-5e8564cd14ff', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '电磁炮', '利用电磁力发射炮弹的武器。是动能武器的一种。分为电磁轨道炮、电磁线圈炮和电磁重接地等。可用于反坦克、反飞机,也可用以发射战术导弹等。', 29);
INSERT INTO `t_military_term_data` VALUES ('5c7dbeb1-d413-44ec-a7e1-4e2e249d186f', 'd7132c58-5df3-4b97-919f-58740148b9ca', '近方观察哨', '高炮部队在阵地附近不便观察和敌机可能进行主要攻击的方向上建立的对空观察哨。通常距高炮部队火网边沿15公里左右。任务是及时掌握敌机主攻方向上的空中情况,防敌低空偷袭。', 120);
INSERT INTO `t_military_term_data` VALUES ('5c806f49-19ae-4980-941b-0da566052155', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '敌后作战', '在敌军后方区域进行的作战。如敌后游击战和敌后空降作战等。', 196);
INSERT INTO `t_military_term_data` VALUES ('5c8b42b5-029f-45c4-a9ed-922326589665', 'f0140091-c11a-48c9-8836-8aa94439dac0', '下车战斗', '机械化步兵或伞兵离开乘坐的步兵战车、装甲输送车或伞兵战车徒步进行的战斗。通常在地形不利,受敌反坦克火力和障碍物威胁大时采用。步兵战车、装甲输送车或个兵战车在步兵或伞兵之后跟进或跃进,以火力支援其战斗。', 178);
INSERT INTO `t_military_term_data` VALUES ('5c9415ba-9bd1-44ff-a201-be68db816404', '98df76fb-4b65-48ff-a56c-4db587327c79', '替换被装', '战时用以替换伤员、受沾染人员的被装和殓葬烈士的被装的统称。', 151);
INSERT INTO `t_military_term_data` VALUES ('5ca449fb-a202-46cd-94a0-b207c1d505d1', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '寒潮', '自极地或副极地大规模地向中、低纬度侵袭,致使地面气温在24小时内下降10摄氏度以上,且最低气温在5摄氏度以下的强冷空气活动。寒潮带来的强烈降温、大风、雨雪、霜冻和沙暴等天气,对军队的人员、装备以及运输、通信等影响很大。', 52);
INSERT INTO `t_military_term_data` VALUES ('5ca4652e-defb-4ce1-838b-a4b2355a0924', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '切变线', '呈气旋式转变的两股方向不同的水平气流的分界线。在天气图上表现为风场中的一条不连续线。切交线附近存在气流的辐合上升运动,是造成降水的重要天气系统。', 43);
INSERT INTO `t_military_term_data` VALUES ('5ca5742c-ecde-4b57-8e85-273671e4d552', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '特种地雷', '具有特殊性能和用途的地雷。如信号地雷、照明地雷、燃烧地雷、化学地雷、核地雷、延期地雷等。', 133);
INSERT INTO `t_military_term_data` VALUES ('5ca99abe-0f8c-41c9-bd9c-e3ad02e04173', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '随军家属', '符合规定条件,经批准办理手续的随军队干部一起生活的军人的配偶和子女。', 90);
INSERT INTO `t_military_term_data` VALUES ('5cc79688-a135-4698-b0e5-705e933e4c32', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '志愿兵', '①依照志愿兵役制或募兵制征召的军人。②中国人民解放军中服现役满一定年限、已成为技术骨干的,根据军队需要,由本人申请,经批准继续留在军队服役的士兵。包括专业军上和军士长。', 148);
INSERT INTO `t_military_term_data` VALUES ('5cd1e38e-6b04-4711-a526-db92228af538', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '值勤', '军队中单位和人员轮流担任日常勤务。包括执行警卫勤务、观察勤务、纠察勤务等。', 56);
INSERT INTO `t_military_term_data` VALUES ('5cd40763-5672-4f4e-ab31-094c2e067f12', '8a761efd-50a6-4ac8-9913-b7d745104f82', '末速', '射弹在弹着点或落点时的速度。', 47);
INSERT INTO `t_military_term_data` VALUES ('5cd4e0bc-3325-4453-ba07-3603a14fd43c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '群众纪律', '中国人民解放军军人为维护人民群众利益、正确处理军政军民关系必须遵守的纪律。主要内容包括：关心和维护人民群众的利益,尊重群众的风俗习惯,正确处理同人民群众的关系等。', 28);
INSERT INTO `t_military_term_data` VALUES ('5cd814f3-13ac-4b66-b865-f7e74ff63c30', '916997ee-6728-4c61-9b79-d96960b1dc86', '免疫预防', '利用生物制品将抗原或抗体注入人体,使之获得对某些疾病的特异性免疫力的防疫措施。目的是保护易感人群,控制疾病的流行。主要方法有皮上划痕法。注射法、口服法、喷雾法和气溶胶吸入法。', 68);
INSERT INTO `t_military_term_data` VALUES ('5cef6bd7-c749-470a-b172-9071a4b3c107', '06a75831-13a1-4660-870a-455bb445336a', '密语通信', '用数码、字母、词组等密化通话内容的通信。依据事先编好的密语表进行。是团以下部队和分队在无保密设备条件下,实施无线电通话的主要方法。', 154);
INSERT INTO `t_military_term_data` VALUES ('5cf7337b-ff0f-4a70-9ef6-1c0bb2e44320', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '红树林', '热带、亚热带海滨泥滩上生长的常绿乔灌木植物群落。以红树科为主。涨潮时茎干下部没入水中,上部带叶树冠露出水面。是防风、防浪的天然护岸林。是登陆作战的严重障碍。', 93);
INSERT INTO `t_military_term_data` VALUES ('5cf8d17f-c873-44ef-960e-8f5d638b57b2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '劝降', '利用有利的军事、政治形势,通过晓以利害关系,规劝敌投降。', 387);
INSERT INTO `t_military_term_data` VALUES ('5d11aa20-9339-4925-9d6e-df8f7abc97d0', '83e065b4-6737-4645-9ea5-8276d1de13ed', '扫雷坦克', '装有机械式和火箭爆破式扫雷装置的坦克。用以在防坦克地雷场中开辟通路。', 93);
INSERT INTO `t_military_term_data` VALUES ('5d149e38-b877-48c6-a3d9-8a32008530ed', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机战斗出动率', '航空兵部队战斗出动的飞机架数与实有的飞机架数的比值。通常用百分比表示。', 61);
INSERT INTO `t_military_term_data` VALUES ('5d1b7e30-81a3-4401-99f5-a786c1895205', 'f0140091-c11a-48c9-8836-8aa94439dac0', '攻占', '亦称攻克。攻击并占领敌方控制的地区或目标。', 165);
INSERT INTO `t_military_term_data` VALUES ('5d2fe637-f910-4921-a6ca-74d5aee6adf2', '98df76fb-4b65-48ff-a56c-4db587327c79', '军用列车', '专为输送部队和军用物资以及为其他军事目的而开行的列车。', 265);
INSERT INTO `t_military_term_data` VALUES ('5d44ed6a-a965-42a9-bf24-21485e0e5e3f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '突防', '导弹或飞机突破敌方对空防御系统的拦截,进入预定的攻击目标区。', 210);
INSERT INTO `t_military_term_data` VALUES ('5d4785d5-0a4f-4d5c-8c27-e34318334628', '916997ee-6728-4c61-9b79-d96960b1dc86', '侦毒器材', '侦检毒剂的化学侦察器材。包括侦毒器、侦毒包和侦毒纸等。用以发现毒剂并初步查明毒剂种类,并概略测定空气的染毒浓度。', 163);
INSERT INTO `t_military_term_data` VALUES ('5d4f1c89-3172-48aa-bc29-ca6b56806e56', '06a75831-13a1-4660-870a-455bb445336a', '传递保密', '亦称信道保密。采用敌方和无关人员不易截获信息的通信保密措施。通常有扩频通信、专用通信线路、地下通信、瞬间通信、定向发信及按规定经常更换无线电台工作频率、呼号等方法。', 147);
INSERT INTO `t_military_term_data` VALUES ('5d576657-e088-427b-acc3-a04ae2932999', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '特种部队', '专门担负破袭敌纵深内重要的军事、政治、经济等目标和其他特殊作战任务的部队。', 51);
INSERT INTO `t_military_term_data` VALUES ('5d626705-38d2-440e-a177-629f312621ea', '916997ee-6728-4c61-9b79-d96960b1dc86', '暂时性毒剂', '施放后对人员的杀伤作用时间能持续几分钟至几十分钟的毒剂。如沙林、氢氰酸等。主要以蒸气、气溶胶状态造成染毒,杀伤有生力量。', 204);
INSERT INTO `t_military_term_data` VALUES ('5d6936fb-a4c2-439b-9f48-342f469b4db5', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '归建', '配属其他单位或派出独立执行任务的部队归回原建制单位。', 326);
INSERT INTO `t_military_term_data` VALUES ('5d7d5814-c76c-4100-beba-4da799f858df', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥所开设', '指挥所在选定的位置和预定的时间设立并展开工作。', 54);
INSERT INTO `t_military_term_data` VALUES ('5d8765df-497e-4eee-bc34-3b3aa8ec1c8a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '隐蔽', '①把目标隐藏或遮蔽起来以防止敌方侦察的行动。②地形或物体具有的可供隐藏或遮蔽的价值。如讲某处地形隐蔽,即指该处可供隐蔽军队等。', 224);
INSERT INTO `t_military_term_data` VALUES ('5d8ed4e8-b490-4d57-b8c0-4d50498939d0', 'd7132c58-5df3-4b97-919f-58740148b9ca', '筒装导弹', '置于筒式容器中进行储存、运输和发射的导弹。', 32);
INSERT INTO `t_military_term_data` VALUES ('5d90a3a1-1883-4eb4-9fd5-4843d1a7ae48', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '分队', '①营及营以下建制单位的统称。②相当于连或排的军队组织。通常隶属于中队。③用于军事机关各部门和营以下单位的通信代号。', 43);
INSERT INTO `t_military_term_data` VALUES ('5d94dd9f-cc54-4f32-852c-c96c09633d11', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '沉底雷', '布设后沉于水底的水雷。多为非触发式,通常装有磁、声、水压的单一引信、联合引信或组合引信等。', 212);
INSERT INTO `t_military_term_data` VALUES ('5d9b46a9-da97-4aee-8216-3f7375074ff3', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '制电磁权', '作战中,在一定时空范围内对电磁频谱使用的控制权。', 356);
INSERT INTO `t_military_term_data` VALUES ('5d9f52d1-94d3-4829-853d-a3dd0f3a3dc0', '97a19170-bfac-42c5-9906-1acb187f0654', '航空油气炸弹', '装有可气化的液态燃料的航空炸弹。燃料以液态储存在炸弹内,着地放出后与空气中的氧混合形成气化云雾,再起爆产生超压和冲击波,可大面积地起杀伤破坏作用。', 331);
INSERT INTO `t_military_term_data` VALUES ('5da0eb68-b53c-40af-a496-e011b5c99697', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水雷障碍', '用水雷构成的水中障碍。分为攻势水雷障碍、防御水雷障碍和机动水雷障碍。布设样式有零散水雷、雷线、雷群和雷幕等。', 109);
INSERT INTO `t_military_term_data` VALUES ('5da1bed8-b703-450b-a913-6d887b0c0c0f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇续航力', '舰艇一次装足燃料、机械用水和滑油,以规定的航速航行所能达到的最大距离。是舰艇战术技术性能要素之一。通常以海里为计量单位。续航力的大小决定舰艇作战半径的大小。', 326);
INSERT INTO `t_military_term_data` VALUES ('5dafc454-af9c-4c8a-add8-2ab628d84ac8', '97a19170-bfac-42c5-9906-1acb187f0654', '反航空侦察', '打击或阻挠敌实施航空侦察的作战行动。包括：使用歼击航空兵、高射炮兵和地空导弹兵打击敌侦察航空器的战斗行动,采取干扰、欺骗、隐蔽、伪装等措施。以阻挠敌侦察活动或降低其侦察效果。', 116);
INSERT INTO `t_military_term_data` VALUES ('5db61c09-9c6b-4cd8-80e6-ab8b0b04358a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮射弹散布中心', '火炮射弹散布区域的中心点。是射弹散布区域内全部炸点的平均位置。', 261);
INSERT INTO `t_military_term_data` VALUES ('5db68dc0-9e23-4543-969f-42f05d9255f5', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战效能', '武器或武器系统在作战中发挥作用的有效程度。', 126);
INSERT INTO `t_military_term_data` VALUES ('5db9f580-1c4e-47fc-8ce2-e2a075ee3de0', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '司令部演习', '团以上司令机关进行的军事演习。分为单级司令部演习和多级司令部演习。通常使用通信工具在现地或室内实施。', 122);
INSERT INTO `t_military_term_data` VALUES ('5dba1fef-07bf-4882-a1db-9bf770703e88', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡河器材集结场', '渡河器材在渡场内隐蔽、集结、待机的场地。同时用以停放卸载的运载车辆和备用器材。通常设在靠近渡口、便于前出和横向机动的区域,并构筑有进出路和掩蔽工事。', 314);
INSERT INTO `t_military_term_data` VALUES ('5dc101fd-ec08-42d4-96f1-942e81c314e7', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防执勤点', '边防小分队或民兵在边境地区执行观察、警戒等勤务的地点。', 92);
INSERT INTO `t_military_term_data` VALUES ('5dc86a63-bb6d-4a36-be04-9960ed51a578', '878651de-adf5-4c72-9376-9c363b893ff8', '战略追击', '对战略退却或溃逃之敌实施的追击。是战略进攻的继续。', 125);
INSERT INTO `t_military_term_data` VALUES ('5dc9fa6e-03fb-4bb2-bea3-ed721a41105b', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '斜坡起降', '直升机或垂直起落飞机在具有一定坡度的野外场地上进行的起飞和降落。', 44);
INSERT INTO `t_military_term_data` VALUES ('5dca25d7-1fd3-4ba2-84bd-7b87476d83bf', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克保养工程车', '亦称坦克技术保养车。装有坦克保养设备、仪器和工具的技术保障车辆。用于野战条件下为坦克充电、充气,协助坦克乘员实施车辆技术状况的检测和保养。是坦克部队野战车场的活动保养站。', 105);
INSERT INTO `t_military_term_data` VALUES ('5dd229ad-56e7-4fdd-a3c5-63fe366dac97', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '查铺查哨', '军官在夜间检查士兵睡眠和哨兵执勤情况的例行性行政管理活动。', 38);
INSERT INTO `t_military_term_data` VALUES ('5dd32d8f-85d1-4987-a578-08ad0a74657b', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '兵力对比', '敌对双方兵力兵器数量的比较。包括双方兵力的人数、主要武器装备数和建制单位数的对比。可进行双方参战总兵力的对比,也可进行某一作战方向、区域或地段双方兵力的对比。', 157);
INSERT INTO `t_military_term_data` VALUES ('5ddedcf2-e30b-45e1-a70a-6ad1d6ceaf78', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵编组', '将数个执行同一作战任务的防空兵部队或分队进行临时性的组合。', 12);
INSERT INTO `t_military_term_data` VALUES ('5dedf144-292d-4949-97e5-7148f1c08839', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电磁辐射', '亦称电磁波。以交变的电磁场的形式并以光速向空间传输电磁能量的过程。包括无线电波、红外线、可见光、紫外线、X射线、Y射线等。', 25);
INSERT INTO `t_military_term_data` VALUES ('5dff6550-9007-49c6-bd73-1c273ca8f948', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '登临权', '一国军舰、军用飞机或经正式授权并有清楚标志可以识别的为政府服务的任何船舶或飞机,在公海上对他国军舰和政府公务船舶以外的船舶进行登船和检查的权利。登船和检查的对象,仅限于有合理根据被认为有从事海盗行为、从事奴隶贩卖、从事非法广播、没有国籍、虽悬挂外国旗帜或拒不展示国旗而事实上与行使登临权的舰船或飞机为同一国籍的船舶。', 374);
INSERT INTO `t_military_term_data` VALUES ('5e079463-3a7e-4841-acdb-1888d8d609fb', '97a19170-bfac-42c5-9906-1acb187f0654', '空情报知', '雷达部队将侦察到的空中情况上报和通报的行动。通常分为集中空情报知和分散空情报知。', 392);
INSERT INTO `t_military_term_data` VALUES ('5e083a42-8dd2-4ebd-87b7-bd97dcd4303e', '878651de-adf5-4c72-9376-9c363b893ff8', '战略纵深', '战略部署的纵向深度或战略任务要求达到的纵向深度。也指远离边沿地带的战略腹地。', 85);
INSERT INTO `t_military_term_data` VALUES ('5e0d363c-12f5-4362-935b-ea59aa42a7ea', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹弹头技术准备', '对导弹弹头进行的各项技术准备工作的统称。主要包括：突防、姿态控制、引爆控制和安全控制等系统的检查、测试,弹头的总装与测试,以及技术分析、处理工作等。', 131);
INSERT INTO `t_military_term_data` VALUES ('5e150084-fe62-4108-ab88-9b023b408dff', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '文件管理', '军队有关部门和人员对各种文书资料的管理。主要包括按保密工作和文书档案工作的有关规定,对文件进行的收发、登记、传阅、使用、保存、清退、归档和销毁等工作。', 20);
INSERT INTO `t_military_term_data` VALUES ('5e24efbb-6081-427d-baab-5d71ac272568', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克保管', '对不动用的坦克及其组件的保存和管理。要求是：对短期不动用的坦克及其组件应妥善保管,达到无丢失、无损坏、无锈蚀、无霉烂变质；对长期不动用的坦克及其组件按规定和要求进行封存,并进行定期检查和保养。', 225);
INSERT INTO `t_military_term_data` VALUES ('5e272960-b50a-46c6-8710-532e8713c4b6', 'd7132c58-5df3-4b97-919f-58740148b9ca', '正常弹迹群', '弹迹对称地出现在目标周围，且半数以上在以目标为中心、一定的密位为半径的圆内的弹迹群。', 186);
INSERT INTO `t_military_term_data` VALUES ('5e42c0e3-cda3-4b4f-a94c-aa95028f2fea', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '群岛', '海洋中彼此相距很近的岛屿群。其中呈线状排列的群岛称列岛,呈弧形排列的群岛称岛弧。', 53);
INSERT INTO `t_military_term_data` VALUES ('5e4f3f51-0d90-4161-9d99-1d2df0dade5b', '31f4a446-5b98-4873-9d53-310d97125b07', '垂直测试', '导弹呈垂直状态时,对其各系统工作的性能和协调性进行的测试。包括系统单元测试、总检查和临时检查。一般在发射阵地进行。', 90);
INSERT INTO `t_military_term_data` VALUES ('5e66c9a8-6983-4495-a1f9-6c7500090954', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机抢救', '对迫降、冲出跑道或在地面发生其他事故的飞机采取的紧急救援措施。抢救时通常先救出机上人员,切断飞机电源和油路,采取灭火措施,卸下弹药,消除燃烧和爆炸的危险,然后将飞机拖往指定地点。', 450);
INSERT INTO `t_military_term_data` VALUES ('5e6b8eae-403d-4ce1-9f63-1a1f2dcd01ba', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '基准舰', '舰艇编队航行时为保持航向和队形,其中起导向和定位作用的舰艇。通常为指挥舰艇。其余各舰艇以其为基准,确定自己在编队队形或队列中的位置。', 260);
INSERT INTO `t_military_term_data` VALUES ('5e805ce4-61c2-4a2f-9b82-e1bda252d9c2', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水雷战', '敌对双方使用水雷作战和进行反水雷作战的统称。分为战役、战术性水雷战和战略性水雷战。', 31);
INSERT INTO `t_military_term_data` VALUES ('5e9c5eef-db14-42ac-80a3-a331b8d7e730', '98df76fb-4b65-48ff-a56c-4db587327c79', '单向运输', '在一定时间和路段内所有列车或汽车都向一个方向运行的运输。通常在大量人员、物资急待前运或后送。需连续通过封锁地段或大量空车回送时采用。', 252);
INSERT INTO `t_military_term_data` VALUES ('5ea6be89-7f73-4f02-b433-4a2fe3e82381', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '水下爆破', '装药设置在水面下、水下目标表面或水下岩土内部的爆破。分为水下非接触爆破、水下接触爆破和水下内部爆破。用以加深河床、清除暗礁和破坏水中目标。', 243);
INSERT INTO `t_military_term_data` VALUES ('5eadb32f-847f-4bfa-b2f7-58c3eedee4b1', '97a19170-bfac-42c5-9906-1acb187f0654', '空军合同战术', '空军两个以上兵种进行合同战斗的方法。', 36);
INSERT INTO `t_military_term_data` VALUES ('5eb4c59c-5da6-45ae-af96-4bb94bce356a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰船豁免权', '在公海上,一国军舰和一国所有或经营并专用于政府非商业性服务船舶享有的,不受船旗国以外的任何其他国家管辖的完全豁免的权利。', 375);
INSERT INTO `t_military_term_data` VALUES ('5eb6773f-70cc-4583-bcd4-948439243db5', 'f0140091-c11a-48c9-8836-8aa94439dac0', '袭扰', '以扰乱敌作战行动、军心士气等为目的的袭击。用以消耗、疲惫、牵制、迷惑敌人。', 155);
INSERT INTO `t_military_term_data` VALUES ('5ecaa77b-10a5-4030-937b-b0e3632a7e56', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '反坦克导弹瞄准线', '反坦克导弹射手操纵点与目标中心的连线。射手依据瞄准线,修正飞行偏差，导引反坦克导弹飞向目标。', 264);
INSERT INTO `t_military_term_data` VALUES ('5ecbefd3-4f8a-4d93-9f1a-f89cbc2bd746', '06a75831-13a1-4660-870a-455bb445336a', '电台', '敌对双方在信息领域的对抗活动。主要是通过争夺信息资源,掌握信息的生产、传递、处理等的主动权,破坏敌方信息传输,为遏制或打赢战争创造有利的条件。', 174);
INSERT INTO `t_military_term_data` VALUES ('5ed4a25c-1aed-483c-98c2-41d745744ce7', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '道路抢修队', '在防御作战中担负道路抢修任务的临时编组。一般在道路成为敌人破坏的重点目标或路况不良时建立。通常以工程兵道路分队为骨干,配属步兵或民兵组成。主要任务是：维护道路,抢修遭破坏的道路、桥梁,构筑迂回路,保障道路畅通等。', 21);
INSERT INTO `t_military_term_data` VALUES ('5ed77ee2-281d-451c-a64d-fa99244d60dc', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备疏散', '将密集的人员、物资分散转移,疏开配置的战备行动。分为早期疏散、临战疏散和紧急疏散。', 220);
INSERT INTO `t_military_term_data` VALUES ('5edb0b17-ee30-4393-8dab-c26c72897bfa', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军籍', '公民在服现役期间，所取得的军人身份。军人退出现役,其军籍自然解除。', 151);
INSERT INTO `t_military_term_data` VALUES ('5ee597c5-ac4b-466b-9881-1db752cc6287', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆出勤率', '出勤车数与实有车数的比值。通常用百分比表示。', 305);
INSERT INTO `t_military_term_data` VALUES ('5eeabef2-ab3e-4cd6-9c89-90cd6a9463e6', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战计划', '军队为完成作战任务而制定的指导作战准备和作战行动的计划。是指挥员决心的具体体现,部队作战准备和行动的依据、包括作战行动计划和作战保障计划。', 87);
INSERT INTO `t_military_term_data` VALUES ('5eec8c0d-90c0-49ee-8d74-46a1c326a317', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '过水路面', '允许横向水流漫过的路面。多用块石和混凝士等材料砌筑。通常修筑在季节性河流或浅水河。溪的通过地段。', 264);
INSERT INTO `t_military_term_data` VALUES ('5eecee3e-0579-40b7-9836-7c926bf8bca1', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '固液混合火箭发动机', '混合使用固体和液体推进剂的化学火箭发动机。包括固液、液固、准固液和三组元固液的混合火箭发动机。', 38);
INSERT INTO `t_military_term_data` VALUES ('5ef5ea7d-40e3-47d0-aeed-a604f2447285', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战原则', '作战行动所依据的法则或标准。正确的作战原则是作战指导规律的反映。', 114);
INSERT INTO `t_military_term_data` VALUES ('5f0fd200-fb58-4c5a-ad2a-0f5dcd96d917', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队操作训练', '导弹部队、分队及人员进行的以操作技能、协同动作和组织指挥为主要内容的训练。包括模拟操作训练以及在导弹、装备上进行的单装操作、单项操作和综合操作训练等。', 75);
INSERT INTO `t_military_term_data` VALUES ('5f10d53d-11e2-4425-9f39-c1e2dccf738b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '基准射向', '火炮、器材按照共同的方向转动基准的坐标方位角所指向的方向、通常由炮兵群指挥员或炮兵指挥机关决定，其数值为炮阵地区域中央至目标区域中央连线坐标方位角的整百密位数。', 209);
INSERT INTO `t_military_term_data` VALUES ('5f165491-526c-4fe1-aaa8-eeb366689762', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲通信车', '装有多种通信设备,用以保障部队通信联络的装甲战斗车辆。分为履带式和轮式两种。', 99);
INSERT INTO `t_military_term_data` VALUES ('5f167f81-d093-4a65-868d-b4a39f95e089', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹引信', '导弹上决定引爆的时间并引爆战斗部装药的装置。分为触发引信、非触发引信和定时引信。', 29);
INSERT INTO `t_military_term_data` VALUES ('5f194554-5c05-474f-bd30-c6f27ddad070', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练大纲', '关于部队军事训练的总体设计的法规性文件。主要内容包括训练的内容、时间、目的、要求等。是部队军事训练的基本依据。', 22);
INSERT INTO `t_military_term_data` VALUES ('5f1993a0-aa69-4ca4-b140-f8c60e806b17', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '阅兵式', '阅兵首长从受阅部队或分队队列前通过,进行检阅的仪式。', 67);
INSERT INTO `t_military_term_data` VALUES ('5f1c5a27-210a-4cc4-9ca9-6360730c179d', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '知彼知己', '亦称知己知彼、对敌方和乙方的情况都有全面透彻的了解。', 29);
INSERT INTO `t_military_term_data` VALUES ('5f2076ee-1739-417a-b596-a3157b1420a7', '97a19170-bfac-42c5-9906-1acb187f0654', '空军雷达保障', '空军雷达部队为使航空兵顺利遂行作战、训练等任务而在雷达情报方面进行的保障。包括对空搜索、探测、测定并报知空中目标情况等。', 389);
INSERT INTO `t_military_term_data` VALUES ('5f2c4884-188e-4342-abb3-8ca82ff3b853', 'f0140091-c11a-48c9-8836-8aa94439dac0', '疏散地域', '部队人员、装备、物资的分散转移与分开配置的地域。通常选择在便于隐蔽、机动、指挥、通信和防护的地域。', 65);
INSERT INTO `t_military_term_data` VALUES ('5f31cd80-08c4-4eb8-8c3e-a3e37b4c6a38', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '补兵', '军队给缺编单位补充兵员或将新兵分配给各单位的工作。', 149);
INSERT INTO `t_military_term_data` VALUES ('5f3eea85-d41f-406f-8e5b-3a070a4c879e', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '技术器材', '构造复杂,需要较高技能操作的器材。如观测器材、侦毒器材等。', 94);
INSERT INTO `t_military_term_data` VALUES ('5f480f91-86cd-49f2-82c6-10b4f4bb496b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军语', '军事术语的简称。表述军事概念的语词。是规范化的军事用语。军队在作战、训练及其他工作中必须使用统一的军语。', 2);
INSERT INTO `t_military_term_data` VALUES ('5f53c9ca-6dd5-477a-9c0e-cb2c14270ea2', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '全导式多弹头', '导弹的母弹头和子弹头都装有推进和制导装置的导弹多弹头、子弹头与母弹头分离后,能各自按预先给定的程序攻击不同的目标。突防能力强,命中精度高。', 27);
INSERT INTO `t_military_term_data` VALUES ('5f60fa55-d13b-4763-9531-3e332b252a9a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '雷达侦察', '使用雷达设备进行的侦察。包括使用战场侦察达、对空情报雷达、对海警戒雷达、地炮雷达和预警雷达等进行的侦察。', 58);
INSERT INTO `t_military_term_data` VALUES ('5f61c5d4-e7f7-4e3b-b388-54fd9cb9d0dd', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '两栖侦察', '两栖侦察分队或蛙人进行的侦察。通常由水上运输工具把两栖侦察分队或蛙人送至侦察目标附近实施。', 34);
INSERT INTO `t_military_term_data` VALUES ('5f65cc65-3190-4e2a-bc12-2873eaaeb555', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '布雷器材', '专门用以布设地雷的工程器材。包括布雷车、布雷弹、布雷器、布雷绳等。', 163);
INSERT INTO `t_military_term_data` VALUES ('5f66aa90-abf5-4104-8a6f-463aea22d2ee', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '分割', '亦称割裂。把敌人的作战部署切割成若干部分的作战行动。', 347);
INSERT INTO `t_military_term_data` VALUES ('5f6cbd35-bee3-43cc-b752-9130290c39de', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队合成训练', '以导弹部队或分队为主体,各保障部队或分队参加,按实战要求进行的以组织指挥和协同动作为主要内容的整体演练。分为战役合成训练和战术合成训练。', 76);
INSERT INTO `t_military_term_data` VALUES ('5f784f51-4539-4aa7-8603-4b5a1715f4eb', '8a761efd-50a6-4ac8-9913-b7d745104f82', '输弹不到位', '射击武器射击过程中,输弹机构不能将弹药输送到正确的进膛位置或取弹位置的射击故障。', 132);
INSERT INTO `t_military_term_data` VALUES ('5f831b94-f756-4eba-94bb-c3d36dbd8e47', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行引导', '指挥人员利用地面或航空器上的雷达、通信等设备指引航空器飞向目标的活动。', 371);
INSERT INTO `t_military_term_data` VALUES ('5f86e8cd-be54-4f09-886a-ab968a6f08d7', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '集中指挥', '亦称统一指挥。对所属部队实施集中控制、统一协调的指挥。是军队指挥的基本方式。', 20);
INSERT INTO `t_military_term_data` VALUES ('5f8ab844-32b0-4a2c-bce0-858df85c0821', 'f0140091-c11a-48c9-8836-8aa94439dac0', '防空火力配系', '用以抗击敌空中袭击的火力配系。通常以地面或舰船防空火力为主,结合航空兵火力组成,构成高、中、低空和远、中、近程相衔接的防空火网。', 80);
INSERT INTO `t_military_term_data` VALUES ('5f9354e8-7c74-49e2-8d0d-83ea01747b32', 'f0140091-c11a-48c9-8836-8aa94439dac0', '一（二）路队形', '成一路或二路纵队运动的队形。通常在敌直瞄武器射程以外运动或通过较隐蔽的区域、狭窄的地段、通路时采用。', 56);
INSERT INTO `t_military_term_data` VALUES ('5fa29ac9-4c48-4971-8bfc-7927662ac006', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥所管理', '为维护指挥所正常的工作和生活秩序而进行的管理。主要包括工作秩序管理、安全保密管理、设施与设备管理、生活的保障与管理等', 58);
INSERT INTO `t_military_term_data` VALUES ('5fb332e2-7f9a-478e-ac98-9b4e49146a2b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵高射界射击', '炮兵用大于49度的射角实施的射击。主要用于对高大遮蔽物后和位于深沟、峡谷以及反斜面的目标的射击。有时用以增大命中角。', 192);
INSERT INTO `t_military_term_data` VALUES ('5fdc8cf2-7f3a-436f-bda8-68dd3f6918a6', '916997ee-6728-4c61-9b79-d96960b1dc86', '防毒衣', '亦称防毒服。防止毒剂、生物战剂、放射性落下灰等接触皮肤引起伤害的个人防护器材。分为隔绝式防毒衣、透气式防毒服等。通常与防毒面具、防毒手套、防毒靴套配套使用。', 175);
INSERT INTO `t_military_term_data` VALUES ('6000db2c-a5c2-4dc5-85d6-2cdedee9c2f9', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '锋', '亦称锋面。温度和密度差异很大的两个气团之间倾斜而狭窄的过渡带。按气团移动的方向,分为冷锋、暖锋、准静止锋、锢囚锋等。锋两侧的气象要素和天气表现有明显差异。锋经过的地区，常出现深厚的云系、宽广的降水带、恶劣的能见度以及风向突变、风力剧增等。', 47);
INSERT INTO `t_military_term_data` VALUES ('60013970-6487-4aba-b428-b1f33a2e9c36', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '近战', '敌对双方在近距离内进行的作战。各军兵种所使用的武器和手段不同,近战的距离也不同。通常是短兵相接,紧张激烈。', 204);
INSERT INTO `t_military_term_data` VALUES ('601c08bd-d9e4-40c5-99a2-fb5286c1c305', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '敬礼', '军人或分队、部队表示尊重和敬意时行使的礼节。按敬礼动作,分为举手礼、注目礼、举枪礼等；按敬礼主体,分为单个军人的敬礼和分队、部队的敬礼等。', 50);
INSERT INTO `t_military_term_data` VALUES ('6021a9a4-25e1-4ce6-83f8-e837854a27f7', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮预制破片弹', '内装预制杀伤体和高能炸药的高射炮弹。主要用以射击飞机和直升机。', 219);
INSERT INTO `t_military_term_data` VALUES ('603130b3-43cb-474b-bb57-59a86f4d84c8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '滑膛炮', '身管内壁无膛线的火炮。炮弹发射后靠尾翼保持飞行状态的稳定。迫击炮、无坐力炮和大口径反坦克炮多为滑膛炮。', 20);
INSERT INTO `t_military_term_data` VALUES ('6047c213-59ca-4003-a961-2b657ab84f79', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '技术勤务', '组织实施武器装备技术方面的供应、管理和保障的专业勤务。主要内容包括：组织实施武器装备技术方面的物资筹措、储备、补充、管理和技术保障,制定技术勤务规章制度,拟定技术工作规划、计划和保障方案,管理技术专业部队或分队的业务工作,开展技术革新和技术勤务工作的科学研究等。', 115);
INSERT INTO `t_military_term_data` VALUES ('604c3a74-64c4-453c-aefd-0b11ab7283b8', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射弹', '射击武器以发射药燃气能量发射的弹丸。如枪弹、枪榴弹、炮弹的弹丸。广义上还包括导弹、鱼雷、火箭等具有自身动力，使用专门装置发射的弹药。', 3);
INSERT INTO `t_military_term_data` VALUES ('6069bf6a-2d36-4a0b-8353-18ef04b6b1f0', 'f0140091-c11a-48c9-8836-8aa94439dac0', '突入', '攻入敌之部署或阵地的战斗行动。', 164);
INSERT INTO `t_military_term_data` VALUES ('606b573d-6ac1-4a42-8850-457e755e5cf7', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵', '以坦克为基本装备,主要遂行地面突击任务的兵种。具有较强的火力、快速的机动力和较好的装甲防护力,是陆军的重要突击力量。可协同其他军兵种作战,也可在其他军兵种协同下或单独遂行作战任务。', 0);
INSERT INTO `t_military_term_data` VALUES ('60958aaf-4e84-463f-aeab-b5d9e6e37525', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '热带气旋', '发生在热带海洋上的气旋。是热带低压、热带风暴、强热带风暴、台风（飓风）的统称。其中心附近的平均最大风力小于8级的称为热带低压,8～9级的称为热带风暴,10～11级的称为强热带风暴,12级及其以上的称为台风（飓风）。', 40);
INSERT INTO `t_military_term_data` VALUES ('60b0e733-7221-4781-ac8c-a86975e221bb', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '艰苦奋斗教育', '以不怕艰苦,英勇奋斗,保持人民军队政治本色,抵制腐朽思想、文化和生活方式的侵蚀为主要内容的教育。', 97);
INSERT INTO `t_military_term_data` VALUES ('60bf2964-6bc3-4bd0-850e-32da65848e67', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵战斗队形', '炮兵为遂行战斗任务将兵力兵器展开所形成的队形。通常由指挥所、观察所、炮阵地和雷达站等组成。', 43);
INSERT INTO `t_military_term_data` VALUES ('60c00c35-8c66-44cd-adcf-6abed157a28a', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '要塞区', '在军事要地设立的军队一级组织。中国人民解放军的要塞区隶属于省军区或集团军。设有领导机关,辖有若干海防部队和分队,担负本要塞的设防和坚守任务。', 28);
INSERT INTO `t_military_term_data` VALUES ('60c0e119-e4e0-49f4-8557-c874a844cf86', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '溃退', '战场上被击溃的军队无组织无秩序地退却。', 401);
INSERT INTO `t_military_term_data` VALUES ('60c16bef-fbd7-4bcd-be1b-fdf093149999', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '集训队', '对教学骨干和专业技术人员等进行短期集中训练的临时性机构。', 13);
INSERT INTO `t_military_term_data` VALUES ('60e616a8-014f-416d-99e5-f7328facf208', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮瞄准速度', '高炮及其配套的仪器瞄准目标时,在单位时间内方向或高低的角度改变量。有电动瞄准速度和人工瞄准速度。通常以度／秒或度／转计算。', 153);
INSERT INTO `t_military_term_data` VALUES ('60f04fe8-7d26-4d2d-94b9-cb60af3d60e3', '98df76fb-4b65-48ff-a56c-4db587327c79', '通用物资', '诸军兵种均可使用的物资。如通用武器弹药、油料、给养、被装、药材、建筑材料等。', 98);
INSERT INTO `t_military_term_data` VALUES ('6105f873-3d8e-48f8-80ba-2eae6c41591b', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤专业', '按照军队后勤工作性质分工而形成的专门业务。中国人民解放军的后勤专业有财务、军需、油料、物资、营房、卫生、军事交通、车船、生产管理等。各设有相应的业务部门,有的还编有专业部队或分队。', 3);
INSERT INTO `t_military_term_data` VALUES ('6108f75c-c78c-4a7f-9467-8bd01c396342', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮拦阻射击', '高炮在敌机航线上构成不动弹幕的射击。通常在能见度很差,又不能使用其他射击方法时采用。', 176);
INSERT INTO `t_military_term_data` VALUES ('610f05d7-6365-4aa6-aeb4-1bd70e34d850', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上机动布雷', '海战中海军兵力根据作战需要临时布设水雷的战斗行动。', 108);
INSERT INTO `t_military_term_data` VALUES ('6119ee13-f9b2-4e62-b378-16e978b0f3c0', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗协同', '电子对抗部队或分队内部以及与有关部队或分队之间在合同作战中的协调与配合。', 10);
INSERT INTO `t_military_term_data` VALUES ('611ceb3e-de68-42c9-8252-9a137da1c705', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电测向设备', '用以测定正在工作的无线电发射台所在方位的电子设备。按工作波段,分为超长波、长波、中波、短波、超短波和微波测向设备。', 119);
INSERT INTO `t_military_term_data` VALUES ('613f9f01-cefd-412a-9110-c8a7865db327', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练器材', '供军事训练用的各种设备、器械和器具的统称。有技术训练器材和战术训练器材等。', 186);
INSERT INTO `t_military_term_data` VALUES ('6140c85d-16b8-4372-9777-a05d198d6734', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报来源', '获取情报资料的渠道。按获取途径,分为公开来源和秘密来源；按获取方式,分为直接来源和间接来源。', 138);
INSERT INTO `t_military_term_data` VALUES ('615327ce-59c5-4865-837b-193616c1be11', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '阵地进攻战役', '对依托阵地进行防御之敌实施的进攻战役。分为对野战阵地防御之敌进攻战役和对坚固阵地防御之敌进攻战役。', 56);
INSERT INTO `t_military_term_data` VALUES ('615b200c-0099-417b-a7a1-5592634a37da', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天气图', '在特制的地图上填有各地同一时刻的气象观测记录,经分析、绘制而成的反映广大区域大气运动状况和气象要素分布的图。包括地面天气图、高空天气图、雨量图等。是分析预报未来天气变化的主要工具之一。', 78);
INSERT INTO `t_military_term_data` VALUES ('6164f30d-2ef0-4a29-84e3-0a3bcbe6d8b1', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战命令', '赋予部队和分队作战任务的命令、有合同命令和个别命令。', 123);
INSERT INTO `t_military_term_data` VALUES ('61722f37-dc50-4276-a00d-90ff6f3a0861', '06a75831-13a1-4660-870a-455bb445336a', '保密通信', '采用加密技术隐蔽信息内容的通信。发端将信息内容加密后进行传输,收端进行解密恢复成原信息。主要有保密机通信、密码电报通信和密语通信等。', 145);
INSERT INTO `t_military_term_data` VALUES ('61734ee0-9c6c-44bf-8ea1-fafc8aa221d3', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹变换射向', '导弹发射前交换导弹的发射方位角,赋予导弹新的射向的过程。', 141);
INSERT INTO `t_military_term_data` VALUES ('6178815d-896e-4f6f-b3f7-f3fc83183684', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通线抢修', '将被破坏的交通线迅速恢复到使用状态的行动。包括对铁路、公路、管线、港口、码头、机场和通信线路的抢修。', 287);
INSERT INTO `t_military_term_data` VALUES ('618d488d-0bbb-4734-9ef9-2c6478691b2a', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海洋性气候', '海洋及其邻近地区受海洋影响显著的气候。主要特征是；冬季与夏季、昼间与夜间温差大,年极端气温出现时间较陆地迟,春季气温低于秋季,云、雾、降水较多,空气湿度大,降水量季节分配比较均匀。', 58);
INSERT INTO `t_military_term_data` VALUES ('619cfc56-d245-4341-816c-f7e1ca01b4a5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '底凹弹', '弹丸尾部有一个向内凹陷的空腔的榴弹。受空气涡流阻力小,射程远,弹壁薄,射击精度较高。', 314);
INSERT INTO `t_military_term_data` VALUES ('61ae7733-6e62-4b34-ab03-d4b52d5a64e0', '97a19170-bfac-42c5-9906-1acb187f0654', '空军战术训练', '空军部队、分队为掌握遂行战斗任务的方法而进行的训练。包括空军各兵种的战术训练和空军合同战术训练。', 198);
INSERT INTO `t_military_term_data` VALUES ('61b00768-c539-4913-9fd4-9ea6ba6b1028', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '队属工程兵', '编入集团军、师、旅、团建制内的工程兵。主要用以保障本部队的战斗行动。', 1);
INSERT INTO `t_military_term_data` VALUES ('61bc3808-fc4e-433a-98cf-aac9396f573a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事测绘部队', '担负军事测绘任务的专业部队；由测绘大队以及各种测绘专业分队等组成。', 148);
INSERT INTO `t_military_term_data` VALUES ('61bf6c6f-06a8-411e-8eb4-c220010d67e3', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '观察日记', '观察所或观察哨每日对观察情况所作的记录。主要记载观察的时间、地点,发现的情况,情况判断,处理结果和上级指示等。', 113);
INSERT INTO `t_military_term_data` VALUES ('61d6ae6b-fc53-415c-92c5-4d9ca883bb6a', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲侦察车', '装有侦察仪器和设备,用于战术侦察的装甲战斗车辆。分为履带式和轮式两种。', 98);
INSERT INTO `t_military_term_data` VALUES ('61f727c5-2141-4d18-b4af-71d4636e16b1', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇在航率', '能正常出航的舰艇数与实有舰艇数的比值。通常用百分比表示。是衡量舰艇技术保障水平的重要标志。', 345);
INSERT INTO `t_military_term_data` VALUES ('61fafa70-f8d0-408f-b035-9268f88904dc', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射弹散布范围', '射弹在平面上或空间里的散布区域。对地面射击时呈椭圆形散布，对空射击时呈椭圆体散布。', 74);
INSERT INTO `t_military_term_data` VALUES ('6215e2f0-5771-4e68-b92c-a47a2a1f224c', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器', '亦称轻兵器。枪械和可由单兵、小组携行使用的武器的统称。枪械之外通常包括手榴弹、榴弹发射器、火箭发射器等。', 147);
INSERT INTO `t_military_term_data` VALUES ('6217f6a4-95e4-4190-91e1-db0439691d7e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上保障群', '海战中担负作战保障任务的各种海上战术群的统称。通常包括侦察引导群、电子对抗群、掩护群、佯动群等。', 65);
INSERT INTO `t_military_term_data` VALUES ('6223ddc9-94b0-4333-9ea3-938a82897328', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军船艇', '陆军编配的用以遂行水上交通、运输、侦察、巡逻和工程作业等任务的船和艇的统称。主要包括交通艇、登陆艇、侦察艇、巡逻艇、运输船、工程作业船等。', 325);
INSERT INTO `t_military_term_data` VALUES ('62491f7a-fb15-49a7-959b-c424c8cdd71b', 'f0140091-c11a-48c9-8836-8aa94439dac0', '对机动防御之敌的进攻战斗', '对以迟滞作战与机动反击相结合的方法进行防御之敌实施的进攻战斗。', 126);
INSERT INTO `t_military_term_data` VALUES ('624ed1ce-723d-461b-8ed7-d0a38c40200a', '97a19170-bfac-42c5-9906-1acb187f0654', '机场场站', '在机场担负飞行后勤保障任务的组织机构。由机关和通信、导航、航空管制、气象、汽车、场务、卫生、警卫等勤务分队组成。通常受所驻的航空兵师或飞行院校领导,主要负责物资供应,机场维护、防护、抢修,医疗救护,以及通信、航空管制、气象、生活等保障工作。', 20);
INSERT INTO `t_military_term_data` VALUES ('62705bf1-e303-4bd7-99b7-3fb21a9a0d9c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵标准气象条件', '亦称炮兵表定气象条件。为编制火炮射表和炮兵射击时进行气象条件修正而规定的气象条件的标准值。', 137);
INSERT INTO `t_military_term_data` VALUES ('627c8a17-cb85-4b09-bc09-3bd6e55f8a15', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火制区', '以密集火力控制的区域。', 243);
INSERT INTO `t_military_term_data` VALUES ('628fee09-b23e-49cd-9398-f5575253e396', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '反坦克火炮', '主要用以毁伤坦克和其他装甲目标的火炮。包括各种滑膛反坦克炮,中小口径加农炮和无坐力炮等。', 17);
INSERT INTO `t_military_term_data` VALUES ('629279f3-0725-4421-8ffc-d4d4112bdceb', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮口水平面', '通过火炮射弹起点的水平面。', 247);
INSERT INTO `t_military_term_data` VALUES ('629effa8-3b3d-450d-a984-55d4f37afa9b', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '组织作战', '作战行动进行计划和组织的活动、主要包括了解任务,判断情况定下决心拟制计划,下达命令、指示,纠织协同和保障进行政治动员检查作战准备以及作战过程中的组织协调活动等。', 80);
INSERT INTO `t_military_term_data` VALUES ('62a1655f-a180-4f12-9211-e9a200da607f', '98df76fb-4b65-48ff-a56c-4db587327c79', '船日', '陆军船艇动态的计算单位。每船每天为 1个船日。分为实有船日、完好船日、执勤船日、在航船日、停航船日、非完好船日等。', 334);
INSERT INTO `t_military_term_data` VALUES ('62aab3fa-8c06-4f8e-9953-230aa554a05d', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '强行军', '加快行进速度和延长行进时间的行军。通常在奔袭、追击、迂回、摆脱敌人或执行其他紧急任务时采用。一般要求徒步日行程50公里以上,乘车日行程300公里以上。', 46);
INSERT INTO `t_military_term_data` VALUES ('62b27c0a-4cee-42a1-9aca-a949fb06d973', '98df76fb-4b65-48ff-a56c-4db587327c79', '军需物资', '①军队后勤军需部门负责供应的吃、穿、用物资的统称。主要包括给养、被服、装具、饮食装备器材和日用品等。②泛指军队所需的物资。', 138);
INSERT INTO `t_military_term_data` VALUES ('62c7e5e1-5210-4cab-8c47-ce16e9c297f7', '97a19170-bfac-42c5-9906-1acb187f0654', '空投场', '空投的装备和物资着陆的场地。通常选在不易受敌地面炮火威胁,有适当的面积和净空条件,便于空中发现、地面收集、搬运空投物品的地域。', 171);
INSERT INTO `t_military_term_data` VALUES ('62cfbb87-bfd1-4fa1-a774-4b7ddef8108f', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '敌情报告', '向指挥员或上级陈述敌情的报告。分为一事一报、专题报告和综合报告。', 149);
INSERT INTO `t_military_term_data` VALUES ('62d3d68c-822a-47c6-b653-2356c86d8e28', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '复员军人', '退出现役的中国人民解放军的志愿兵和干部。复员军人一般回参军地区或在服役所在地安置,国家不包分配工作。', 155);
INSERT INTO `t_military_term_data` VALUES ('62ddf205-8660-45cb-8f80-48721b6b090b', '8a761efd-50a6-4ac8-9913-b7d745104f82', '低伴损轻武器', '除毁伤射击目标外,对位于目标后面和两侧的人员、装备损伤最小或不出现伴随损伤的轻武器。如反劫机用的手枪、使用橡皮子弹的步枪等。', 152);
INSERT INTO `t_military_term_data` VALUES ('62f24ec3-dce5-4a19-9c8e-62f122e9dfa9', '97a19170-bfac-42c5-9906-1acb187f0654', '测高雷达', '主要用以测定空中目标飞行高度的雷达。通常与不能测高的雷达配合使用。', 346);
INSERT INTO `t_military_term_data` VALUES ('6322c10e-55fb-4958-8e0a-e95611014bdf', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '兵役制度', '国家关于公民参加武装组织或在武装组织之外承担军事义务、接受军事训练的制度。主要包括；公民依照法律在军队中服现役,在军队外服预备役,以及在校学生接受军事训练等规定。', 22);
INSERT INTO `t_military_term_data` VALUES ('63342e39-e2e2-40f2-8520-650a65ee5f20', '98df76fb-4b65-48ff-a56c-4db587327c79', '作训服', '亦称野战服。军人作战、训练、劳动和执行军事勤务时穿着的军服。中国人民解放军的作训服分为夏作训服和冬作训服,单色普通作训服和多色组合迷彩作训服等类。', 156);
INSERT INTO `t_military_term_data` VALUES ('6342b61a-b3b0-46dc-a6e5-5d7cb91791ee', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '激光测距仪', '用激光器作为光源测量目标距离的仪器。有脉冲式测距和连续波相性式测距两类。作用距离为数百米至数万米,测量精度为5～10米。军事上广泛用于侦察、测量和武器的光电灯控系统。', 72);
INSERT INTO `t_military_term_data` VALUES ('634c42e0-fdfe-444b-bdbd-a8fef09b6eac', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机滑跑着陆', '直升机降落于地面经滑跑而进行的着陆。多在直升机超载时采用。对着陆场地条件要求较高。', 39);
INSERT INTO `t_military_term_data` VALUES ('6351db10-1a49-48f4-9ad8-8fb3da9237a4', '98df76fb-4b65-48ff-a56c-4db587327c79', '应急保障', '在紧急和意外的情况下根据预案组织实施的后勤保障。通常在应付局部战争、突发事件或抢险救灾时采用。', 29);
INSERT INTO `t_military_term_data` VALUES ('635231bb-380e-402d-a722-4e8d360203a0', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '战斗损失', '因战斗造成的人员、武器装备和物资等的损失。', 93);
INSERT INTO `t_military_term_data` VALUES ('6361c570-aea4-402e-a4f3-4de695f2f27b', '06a75831-13a1-4660-870a-455bb445336a', '通信兵演习', '通信兵在想定情况诱导下进行的演练。目的是提高通信兵在近似实战条件下的通信保障能力。', 219);
INSERT INTO `t_military_term_data` VALUES ('6367597c-2356-4d01-904e-f52264c525bc', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '把握战机', '抓住有利的作战时机适时对敌采取行动。', 35);
INSERT INTO `t_military_term_data` VALUES ('63699f81-108d-4ba4-ab52-59c5681f6e65', '31f4a446-5b98-4873-9d53-310d97125b07', '化验推进剂', '对液体推进剂的物理和化学性能进行的检查测量、分析鉴定。一般分为全分析化验和野战化验。液体推进剂的性能对火箭发动机的工作有重大影响,在储存和直接向导弹储箱加注之前,必须对其性能进行检查、化验。', 99);
INSERT INTO `t_military_term_data` VALUES ('6394502c-1092-4881-a81b-d2a57360d6a4', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '植物伪装', '用种植、采集植物和改变植物颜色实施的伪装。方法有植物覆盖、植物遮障和植物变色等。可用以对付光学、热红外和雷达侦察。', 335);
INSERT INTO `t_military_term_data` VALUES ('63972c70-94bd-4b2a-a9ac-d8154067c7e4', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '编制实力', '编制规定的建制单位、人员、武器装备等的数量。', 83);
INSERT INTO `t_military_term_data` VALUES ('63a11bf0-4a83-4f49-ad0c-6efd155abf9e', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '装（卸）载计划', '部队输送或物资运输时组织实施装（卸）载的计划。根据输送计划拟制。', 89);
INSERT INTO `t_military_term_data` VALUES ('63a3586a-be9c-49f9-8e3b-0de4c4d44ac2', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '径流', '由降水形成的、沿着流域的不同途径流人河流、湖泊或海洋的水流。分为地面径流、表层（壤中）径流和地下径流、径流是水文循环的重要环节,是河流水文情势变化的根本因素。', 111);
INSERT INTO `t_military_term_data` VALUES ('63bb4753-ac67-42ce-a60d-49ea7c7fba9c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军帆缆勤务', '海军对帆缆器材的筹措、储备、供应与管理等勤务。帆缆器材包括帆布制品、绳索、救护器材、水手工具、清洁用品、涂料、除涂机具等。', 348);
INSERT INTO `t_military_term_data` VALUES ('63c53be8-b658-49f3-b6c7-372113b80ad3', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军导航台', '海军中为舰艇、飞机导航的专业勤务分队。按导航距离,分为近程、中程和远程导航台。隶属于海军基地、水警区或海军航空兵场站。装备有供导航定位用的无线电发射台。', 16);
INSERT INTO `t_military_term_data` VALUES ('63e55ecb-b959-4515-bb91-5b8a97c90358', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮位侦察校射雷达', '简称炮位侦察雷达。炮兵用以侦察测定正在发射的敌方火炮炮位和测定己方射弹弹着点坐标以校正射击的雷达。如迫击炮炮位侦察校射雷达等。', 299);
INSERT INTO `t_military_term_data` VALUES ('63f08380-5987-4fc0-8e8a-f40a5af56049', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '军队标号', '军队标图中使用的特定的队标和队号、由图形、代字、数字和颜色组成、队标用以表示个兵种部（分）队、指挥机构武器装备、军事设施及军队行动队号,用以注明队标所表示的军队的番号、数量和军队行动的时间序号的代字及数字。', 118);
INSERT INTO `t_military_term_data` VALUES ('64038efb-2a17-4f2e-b61b-4145cb4f010a', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机作战保障', '为使直升机部队顺利遂行作战任务而采取的各项保证性措施和进行的相应活动的统称。主要包括情报、通信、技术、领航方面的保障等。', 69);
INSERT INTO `t_military_term_data` VALUES ('640b56ee-3916-4081-9b3f-f2f25a98ba43', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '黄土地貌', '发育在黄土地层中的地貌。沟壑多,地面破碎,地势起伏大,坡度陡。分为黄土沟谷地貌、黄土沟间地貌、黄土潜蚀地貌。黄土沟间地貌包括黄土源、黄土梁和黄土峁。中国黄土地貌主要分布于黄土高原。军事上便于部队隐蔽、集结,但不便于观察、射击和机械化部队运动。', 39);
INSERT INTO `t_military_term_data` VALUES ('6418e3be-2886-492c-9b5b-eceecb3062e5', 'f0140091-c11a-48c9-8836-8aa94439dac0', '核心阵地', '阵地编成内对整个防御战斗起枢纽和支撑作用的阵地。通常指纵深内便于控制主要防御方向的阵地。', 222);
INSERT INTO `t_military_term_data` VALUES ('641f2154-8a82-4869-aa10-ac8f3b36c267', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '夜战', '在夜暗条件下进行的作战。一般利于隐蔽行动企图,达成突然性,便于近战歼敌。现代夜视器材的发展和使用,使夜战条件发生了新的变化。', 205);
INSERT INTO `t_military_term_data` VALUES ('64289cb8-834a-488b-8bff-2d2713c6c9ef', '97a19170-bfac-42c5-9906-1acb187f0654', '机场标高', '机场主跑道中心线中点的海拔高度。', 419);
INSERT INTO `t_military_term_data` VALUES ('6429e6fe-b7b4-454a-9879-35c1c01d1d60', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '远战', '在远距离上使用远战武器和手段进行的作战。各军兵种武器装备的作用距离和使用的手段不同,远战的距离也不同。', 203);
INSERT INTO `t_military_term_data` VALUES ('642abf6a-3407-4976-9d69-107d9c2511d0', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹制导雷达', '如用以引导和控制地空导弹飞行的雷达。能准确跟踪空中目标,同时向导弹发射控制信号,使其按预定弹道准确飞向目标。', 343);
INSERT INTO `t_military_term_data` VALUES ('64318214-2919-42bd-9853-74563a5a8c75', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核地雷', '亦称原子爆破装置。装有核战斗部的地雷。威力为几百至几万吨梯恩梯当量级。主要用以构成地形障碍和放射性沾染带,阻滞敌军坦克群的行动及直接杀伤敌军。', 110);
INSERT INTO `t_military_term_data` VALUES ('6444aca5-6aa7-491e-addd-ca2f1a5f84c6', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '巨型计算机', '亦称超级计算机。具有高速计算功能,并采用快速大容量存储器和广泛使用并行结构技术的规模巨大的计算机。军事上主要用于国防尖端技术研究和天气预报等。', 54);
INSERT INTO `t_military_term_data` VALUES ('644aff12-77a5-42e9-91bf-bfff6e7b97a8', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '跟班作业', '军官跟随士兵一同操课或工作。是对基层干部领导、管理好部队的一项基本要求。', 28);
INSERT INTO `t_military_term_data` VALUES ('645da4e7-e5f1-4947-b47d-847627d37d49', '8a761efd-50a6-4ac8-9913-b7d745104f82', '齐射', '两件以上武器按统一口令或信号同时进行的射击。', 112);
INSERT INTO `t_military_term_data` VALUES ('646162f3-84f6-49cb-9b92-27108d9f07dc', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '带式舟桥', '桥脚舟与上部结构合为一体,所架浮桥形似带状的重型舟桥器材。结构整体性好,架设速度快,作业强度小。', 301);
INSERT INTO `t_military_term_data` VALUES ('64651f8e-8cc2-4a6c-88c2-5cc4f593ab13', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮机动作战', '高炮部队在作战地域内以适时机动兵力的方式,积极寻求战机进行的作战。通常采用预设埋伏、短距出击和广泛游击等手段进行。', 72);
INSERT INTO `t_military_term_data` VALUES ('646b3cf3-889a-4636-acca-e9d0d719bbef', '97a19170-bfac-42c5-9906-1acb187f0654', '按计划出动', '航空兵部队在支援陆军、海军部队作战中,按照协同计划规定的任务和时间自行组织的战斗出动。有利于适时做好战斗准备和恰当地使用兵力。', 127);
INSERT INTO `t_military_term_data` VALUES ('6479f80f-3988-4019-b0be-6a83baf2b9d0', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '自然地理环境', '亦称自然环境。人类赖以生存和发展的自然界。由地质、地貌、气候、水文、土壤和生物等自然地理要素构成。', 8);
INSERT INTO `t_military_term_data` VALUES ('64979f94-34d2-4be4-8d6f-44dbc695827e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '观摩教学', '施教人员切磋教学方法或交流教学经验的教学研究活动。通常有示范观摩教学、专题研究观摩教学、汇报观摩教学等。', 151);
INSERT INTO `t_military_term_data` VALUES ('64a5d5e9-9066-49c5-922e-677063e950a2', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '破坏物', '破坏建筑物、构筑物而造成的障碍物。包括对隘路、桥梁、隧道、铁路、港口、机场、楼房等破坏造成的障碍物。', 114);
INSERT INTO `t_military_term_data` VALUES ('64af1715-26fb-4e74-a7c1-c9bfcc2b16a5', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '非战斗减员', '由于疾病或事故等非战斗原因造成的人员减少。', 90);
INSERT INTO `t_military_term_data` VALUES ('64b1924a-2e60-49fb-af1d-b63c9f242c0c', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '武装直升机', '装有机载武器,用于空战或对地面、水面、水下目标实施空中攻击的直升机的统称。包括专门设计制造的各种歼击、攻击直升机以及加装有机载武器。', 5);
INSERT INTO `t_military_term_data` VALUES ('64b966e8-e2e2-4a55-9f25-f5b6f35d2da5', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '岬角', '亦称地角。陆地伸向海、河、湖上的角状突出部。通常位于半岛前端。军事上利于控制水上交通。', 51);
INSERT INTO `t_military_term_data` VALUES ('64cd4ba9-6ba1-4c97-9631-5b7fa559ddf3', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '军用筑路机械', '在不与敌直接接触情况下构筑和维护军用道路所使用的军用工程机械。有推土机、铲运机、装载机、平路机、压路机等。', 376);
INSERT INTO `t_military_term_data` VALUES ('64cd9dd9-91e2-4236-aa06-7a18a522ecba', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '领空', '主权国家领陆和领水上空的大气层空间。是国家领土的组成部分。', 71);
INSERT INTO `t_military_term_data` VALUES ('64d0fd86-124c-4544-9eea-86b5cba79b6c', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反攻', '防御中对进攻之敌采取的攻势行动。通常用于战略范围。', 403);
INSERT INTO `t_military_term_data` VALUES ('64dbfeb3-4eaf-4390-a37a-93bc80652aad', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '暗堡', '利用有利地形构筑并经过严密伪装的地堡。用以封锁接近地和交通要道等。', 60);
INSERT INTO `t_military_term_data` VALUES ('64dcd350-55fc-4573-bd84-f329f7dd7aa1', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '对峙', '敌对双方相持对阵的态势。', 405);
INSERT INTO `t_military_term_data` VALUES ('64dd444e-35a3-4016-aa9c-8e1437a53e92', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克后送', '利用输送工具将损坏的坦克运往修理点或后方转运地的行动。通常在行动装置严重损坏,无法牵引域距离过远不适于牵引时进行。', 219);
INSERT INTO `t_military_term_data` VALUES ('64ecaefc-9583-476f-8c8c-213e0ff72999', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆动态', '车辆在运用过程中每台车每天所处的状态。分为完好车和非完好车。完好车包括执勤、待命、封存等状态；非完好车包括待料、待修或在修、待报废等状态。', 302);
INSERT INTO `t_military_term_data` VALUES ('64f77e59-d997-483d-aa41-7938f3f8b567', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工兵部队', '工程兵中担负野战工程保障任务的专业部队。装备有野战工程机械、地雷战和反地雷战器材。爆破器材、桥梁渡河器材、筑城器材等。主要负责：构筑和维护指挥所,构筑野战工事,构筑和抢修主要道路、急造军路和桥梁,开设渡场，设置和排除障碍物，以及实施破坏作业等。', 3);
INSERT INTO `t_military_term_data` VALUES ('6520897e-652e-48c3-8ea0-cbc64ddc8884', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战略导弹部队情报', '战略导弹部队作战所需的情报。主要来源于战略导弹部队所属的专业侦察力量获取的情况,还来源于上级、友邻部队、其他军兵种以及地方有关部门、民兵、人民群众等提供的情况。', 133);
INSERT INTO `t_military_term_data` VALUES ('652182f0-692d-460f-880c-e254a0011f96', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇火力支援队', '登陆作战中以火力支援登陆兵登陆的舰艇编队。由水面战斗舰艇编成。包括远程火力支援群、近程火力支援群和直接火力支援群。', 69);
INSERT INTO `t_military_term_data` VALUES ('6523bf36-3a59-438d-ad9a-3c363a5f23d5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇阵地伏击法', '潜艇预先隐蔽配置在敌舰船必经海区的伏击阵地,待敌舰船通过时对其实施突然袭击的作战方法、是潜艇袭击敌舰船的传统战法。通常1个伏击阵地配置1艘潜艇。', 89);
INSERT INTO `t_military_term_data` VALUES ('652e01e1-671e-4502-b4ba-d45e6d66a2ea', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程维护部队', '工程兵中担负战略和战区指挥所工程维护任务的专业部队。装备有用于工程维护的各种工程机械、设备和成套工具等。主要负责维护统帅部、战区（军区）的指挥防护工程。', 6);
INSERT INTO `t_military_term_data` VALUES ('653335d4-08a5-4e40-9cdc-da8c419e6442', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '回收', '航天器回收舱返回地球稠密大气层后,经减速直至安全降落地面或水面并被取回的过程。分为陆地回收。海上回收和空中回收。', 280);
INSERT INTO `t_military_term_data` VALUES ('65375177-32e6-4c11-988e-2904716e1fd2', '97a19170-bfac-42c5-9906-1acb187f0654', '航空工程保障', '为使航空装备的技术状况经常处于良好状态而进行的保障。主要是组织实施飞行机务准备和飞机或直升机的维修,以保证航空兵顺利遂行作战和训练等任务。', 441);
INSERT INTO `t_military_term_data` VALUES ('6551a704-ca78-4912-9b41-b92ee8a5c553', '97a19170-bfac-42c5-9906-1acb187f0654', '三级航空维修', '亦称后方维修。由空军航空修理工厂对航空技术装备实施的复杂的航空维修。包括大修、翻修、复杂的改装等。', 446);
INSERT INTO `t_military_term_data` VALUES ('6554b3cc-9309-4126-831c-c5daef90983a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察部署', '对侦察兵力所作的任务区分和编组、配置。', 101);
INSERT INTO `t_military_term_data` VALUES ('65612d5f-67b1-4766-b91a-25e8da09422c', '878651de-adf5-4c72-9376-9c363b893ff8', '战争力量', '可直接和间接用于战争的各种力量的统称。包括战争实力和战争潜力。', 37);
INSERT INTO `t_military_term_data` VALUES ('656ea0e9-c655-4178-a438-a22954e93c49', '916997ee-6728-4c61-9b79-d96960b1dc86', '喷火油料', '喷火器喷射用的油基燃烧剂。有液状油和凝固汽油两种。凝固汽油是由汽油和稠化剂调制而成的。有较强的粘性,燃烧时温度高达700～800摄氏度。', 236);
INSERT INTO `t_military_term_data` VALUES ('6571a959-7688-43a1-9a30-b755084efec2', '98df76fb-4b65-48ff-a56c-4db587327c79', '饮食保障', '对部队膳食和饮水的保障。主要包括热食保障、军用食品保障和饮水保障等。', 140);
INSERT INTO `t_military_term_data` VALUES ('657ceac7-8b20-470d-b593-d510bb600c5a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '火箭助飞鱼雷', '简称助飞鱼雷。从舰艇上发射,由火箭空中助飞到达预定点入水,自动搜索、跟踪和攻击目标的鱼雷。由火箭飞行器和自导鱼雷组成。兼有火箭射程远、速度快和自导鱼雷自动搜索攻击能力强的优点。', 207);
INSERT INTO `t_military_term_data` VALUES ('658f8619-1408-402f-95b0-b2696cf1d0b6', '98df76fb-4b65-48ff-a56c-4db587327c79', '给养', '军队人员的主食、副食、饮料和牲畜饲料等的统称。是军需物资的组成部分。', 139);
INSERT INTO `t_military_term_data` VALUES ('6596e601-8edc-49b1-9db1-6d50fd789c63', '97a19170-bfac-42c5-9906-1acb187f0654', '空降时机', '空降部队实施空降的有利时间。主要由作战企图、战区情况、空降任务和天气条件等因素确定。', 165);
INSERT INTO `t_military_term_data` VALUES ('659b8aea-50d5-4d68-8d49-5fc36ebe5f00', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '点验', '对部队或分队的编制、实力、战备和安全状况进行的全面清点和检验。主要检查：执行编制情况,装备和物资的数量、质量、保管、维修和保养情况,人员的健康和卫生状况,装备和物资的携行能力,个人物品等。用以促进行政管理和战备工作的落实。', 55);
INSERT INTO `t_military_term_data` VALUES ('659cd6c5-6b32-4420-922f-1122a32143c9', '878651de-adf5-4c72-9376-9c363b893ff8', '全面战争', '全面动员、全力实施的战争。', 9);
INSERT INTO `t_military_term_data` VALUES ('65a0e7d7-dc5d-474f-9f54-197810b3d828', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '器材', '技术器材、工具、零部件、原材料等的统称。', 93);
INSERT INTO `t_military_term_data` VALUES ('65a2392f-ccd1-4ab9-bb4d-7020465c31f3', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵武器装备', '编制在民兵组织内或储存的专供民兵使用的武器及其配套的弹药、仪器、器材和附件等的统称。', 135);
INSERT INTO `t_military_term_data` VALUES ('65a3c385-3d5f-4d37-b716-789f6af3464b', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '专业技术军官', '军队中从事专业技术工作的军官包括从事专业技术教学、专业技术科学研究、工程技术、卫生技术、会计。审计、经济、新闻、出版、图书、翻译、体育、文艺、档案等工作的军官。一般评定有专业技术职称。', 107);
INSERT INTO `t_military_term_data` VALUES ('65a7e35b-c0fa-4af6-af98-4787af26a9b6', '97a19170-bfac-42c5-9906-1acb187f0654', '烟火信号', '使用浓烟或火光进行对空联络、标示位置和供飞机或直升机识别致我的视觉信号。通常使用发烟器材、信号弹、燃烧剂等显示。', 364);
INSERT INTO `t_military_term_data` VALUES ('65b10f52-c7fd-4a96-bc23-52cb05112c6b', '916997ee-6728-4c61-9b79-d96960b1dc86', '发烟点', '施放烟幕时最小发烟单元的所在地点。可以是每辆发烟车或每部发烟器、每个发烟罐的发烟地点,也可以是几个发烟罐集中在一处的发烟地点。', 79);
INSERT INTO `t_military_term_data` VALUES ('65ba2013-2f74-4554-a14e-630ff942e15e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰炮', '装备在舰艇上用以射击水面、空中和岸上目标的海军炮。现代舰炮多为中、小口径炮。主要用于对空防御。', 184);
INSERT INTO `t_military_term_data` VALUES ('65cc225d-3836-48cb-9bd1-ad1223c47611', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤协同', '为完成后勤保障任务而进行的协调配合行动。主要包括：后勤各部门之间,各军兵种后勤之间,后勤各部队或分队之间,后勤机关与其他机关之间,以及后勤与地方支前机构之间的协同等。', 62);
INSERT INTO `t_military_term_data` VALUES ('65d6575e-bc4e-465b-830c-68ea124e73f4', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '攻防转换', '作战中由进攻转为防御或由防御转为进攻的作战类型的变换。', 198);
INSERT INTO `t_military_term_data` VALUES ('65e89aae-3532-4df0-8f56-f0d5f047df76', '97a19170-bfac-42c5-9906-1acb187f0654', '空军指挥所战斗准备等级', '对空军各级指挥所战斗准备程度划分的级别。如一等战备、二等战备等。各等级的具体内容由空军有关的条令、条例和战备制度规定。', 182);
INSERT INTO `t_military_term_data` VALUES ('65e9da4d-00ae-4246-b80e-cda28998e296', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥所', '①军队中由指挥员及其指挥机关组成的民有组织指挥职能的临时性指挥机机军队遂行作战、防暴、抢险救灾、演习等任务时,通常应对设指挥所。作战指挥所分为基本指挥所、预备指挥所、前进（方向）指挥所后方指挥所等、②担负作战值班仟务的常设指挥机构。', 46);
INSERT INTO `t_military_term_data` VALUES ('65ec6500-e686-4a2d-ad7d-56ba5f207bf8', '878651de-adf5-4c72-9376-9c363b893ff8', '战略指导', '亦称战争指导。对有关战争或其他全局性的重大问题实施的宏观控制与协调活动。包括对战争形势的判断,对战略行动的决策,对各种战略手段的协调、运用,对战略各阶段、各方面问题的运筹与照应等。', 69);
INSERT INTO `t_military_term_data` VALUES ('65ed1d22-be72-47d4-8389-b6a23add561f', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '离直升机', '搭乘直升机的部队或分队在直升机部队人员的指引下离开直升机的行动。分为着陆离直升机、悬停离直升机、绳梯离直升机、小速度贴地飞行离直升机等。', 89);
INSERT INTO `t_military_term_data` VALUES ('65ef3934-928e-4dbb-aaa0-4c74dee1aac3', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '尊干爱兵教育', '以士兵尊重干部、干部爱护士兵为主要内容的教育。', 96);
INSERT INTO `t_military_term_data` VALUES ('65fb56c4-59fe-48da-98fc-529562014ad8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '消极防御', '单纯以防御手段阻挡敌之进攻,放弃任何积极主动攻势行动的消极保守的防御。', 396);
INSERT INTO `t_military_term_data` VALUES ('65ff561e-6f3c-4441-81ec-ac619da1f2e2', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '波纹钢工事', '用波纹钢构件组成的装配式工事。如波纹钢圆形机枪工事、波纹钢直墙半圆拱形掩蔽工事等。特点是重量轻、抗力强、结构简单、连接可靠、拆装方便。', 71);
INSERT INTO `t_military_term_data` VALUES ('66019b8a-97cd-4b9e-b1f0-37fc9a778d7f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '组织协同动作', '为使参战力量形成有机整体而计划与协调各部（分）队相互配合行动的活动。通常于战前在现地图上、沙盘或利用计算机系统组织。作战中应根据情况变化及时调整或恢复协同。', 82);
INSERT INTO `t_military_term_data` VALUES ('66162195-4771-42a1-8c48-fb98146d7452', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '助攻', '亦称辅助突击。使用部分兵力、火力在次要方向上实施的进攻。', 85);
INSERT INTO `t_military_term_data` VALUES ('661f935b-fd9b-4f83-b877-a034b84781d7', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇码头', '供舰艇靠泊、维修保养,人员上下舰艇以及物资补给装卸的水工建筑。按用途,分为停泊码头、装卸码头、登陆码头、油码头、舾装码头和洞库码头；按平面轮廓,分为顺岸式码头、突堤式码头、扩岸式码头；按结构形式,分为岸壁式码头、栈桥式码头和浮动式码头。', 392);
INSERT INTO `t_military_term_data` VALUES ('662904ba-de64-43ce-956f-8b15f481d8b5', '916997ee-6728-4c61-9b79-d96960b1dc86', '染毒区', '简称毒区。染有毒剂并对军队和居民构成危害的区域。包括化学袭击区、毒剂传播区以及毒剂滞留区。', 118);
INSERT INTO `t_military_term_data` VALUES ('662eb251-05f8-4a0f-ac26-8354c8dc0142', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹', '亦称防空导弹。从地面发射、攻击空中目标的导弹。由弹体、动力装置、制导设备、战斗部和电源设备等组成。', 29);
INSERT INTO `t_military_term_data` VALUES ('6648d074-2a19-47f2-a80c-9c6ef64a91fc', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵交会观察通信', '实施交会作业的各炮兵观察所之间建立的通信联络。通常由在遮蔽阵地上执行射击任务的炮兵营、连组织。一般只建立直达有线电通信，必要时也可建立无线电通信。', 124);
INSERT INTO `t_military_term_data` VALUES ('665645ed-8404-47ae-b00a-7340e25c47d2', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机靶场', '直升机机载武器进行实弹射击训练和对直升机机载武器进行实弹校验所用的场地。', 102);
INSERT INTO `t_military_term_data` VALUES ('66588db0-3442-4cfe-8425-4e7d0fce2840', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '隐形造势', '采用各种干扰和欺骗的方法,隐真示假,以求形成对己方有利作战态势的行动。', 89);
INSERT INTO `t_military_term_data` VALUES ('665a8055-2675-476b-88f2-596dbac2f5e2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '非正规战', '采取游击战等形式进行的作战。', 137);
INSERT INTO `t_military_term_data` VALUES ('666c97ab-32bd-424a-94cf-efc779e4c62a', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '反气旋', '亦称高气压或高压。北半球水平气流呈顺时针（南半球呈逆时针）旋转的大气涡旋。在天气图上表现为闭合等值线包围的高气压区,其中心附近的气压高于四周。反气旋中心附近,气流辐散下沉,天气晴好。大型反气旋常常左右周围其他天气系统的活动。', 44);
INSERT INTO `t_military_term_data` VALUES ('66753744-7d3c-4727-bd31-a6d32cd5385e', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹综合测试', '为综合考察导弹各系统的工作情况和协调性而进行的测试。', 89);
INSERT INTO `t_military_term_data` VALUES ('667d4b83-d12f-4ebb-aa27-7bec894e1b20', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '标定地图', '利用指北针、直长地物或明显地形点相对照等办法,使地图的方位和现地方位取得一致。是现地使用地图的前提条件。', 140);
INSERT INTO `t_military_term_data` VALUES ('6680fa9e-996d-44ff-bb6e-20a4f39b1d1b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队航行队形', '舰艇编队在航行中,各舰艇按照航行需要排列成的队形。基本航行队形有单纵队、双纵队、人字队（楔形队）、方位队和环形队形等。', 72);
INSERT INTO `t_military_term_data` VALUES ('6682e00d-cd42-4604-ab6f-8d23570fdc49', '916997ee-6728-4c61-9b79-d96960b1dc86', '沾染检查哨', '为检查人员、装备等放射性沾染程度而开设的哨所。通常由防化侦察分队开设。其位置应选择在沾染区以外。', 7);
INSERT INTO `t_military_term_data` VALUES ('669a68ba-0138-4dca-bf42-2f0787a23d30', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '着装', '军人按规定穿着服装、佩戴徽章符号和携带武器装具。要求整齐一致,便于工作,适应环境。', 48);
INSERT INTO `t_military_term_data` VALUES ('66a57a7a-0cdc-43be-84ad-3633dc4848f8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '锚地', '用于舰船安全锚泊的一定水域。按用途,分为待机锚地、候潮锚地、避风锚地、集结锚地、装卸锚地、消磁锚地等；按位置,分为港内锚地和港外锚地。', 391);
INSERT INTO `t_military_term_data` VALUES ('66ca4cb6-9a40-4567-ab62-9f05b15b6a1c', '06a75831-13a1-4660-870a-455bb445336a', '通信报告', '通信部门和通信部队、分队向首长和上级司令部反映通信工作情况的报告。主要包括：通信联络保障情况,通信人员伤亡、器材损耗和缴获情况,主要经验教训,有关通信工作的建议和请示等。', 32);
INSERT INTO `t_military_term_data` VALUES ('66cd608e-5a5d-4d85-b03e-849cacd64d83', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮火力范围', '高射炮兵对空中目标实施有效射击的范围。包括1个火力单位的火力范围和数个火力单位的火力范围。可根据火力单位的有效射击半径、配置间隔、配置样式和目标高度等条件求出。', 156);
INSERT INTO `t_military_term_data` VALUES ('66d02f78-b72d-40b8-87ad-ba3bcc0bbcb6', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '第二梯队', '作战部署或战斗队形中配置在第一梯队后面的梯队。进攻时,主要用以接替第一梯队。增强突击力量,扩张战果；防御时,主要用以接替第一梯队的防守,或用以反击突入之敌,扼守纵深阵地。', 316);
INSERT INTO `t_military_term_data` VALUES ('66e288b1-bf91-4334-bf5b-f4974ff08d21', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤分队', '军队内担负后勤保障任务的营和营级以下的后勤建制单位、如汽车营、管线队、修理所、勤务连、炊事班等。', 12);
INSERT INTO `t_military_term_data` VALUES ('66e381e2-0ab2-4f3d-9ee8-a094296ab4a1', '31f4a446-5b98-4873-9d53-310d97125b07', '核反击', '遭敌核袭击后用核武器对敌实施的反击作战。', 26);
INSERT INTO `t_military_term_data` VALUES ('66e75fd5-499c-4a43-9057-0ce2dec84a8a', '98df76fb-4b65-48ff-a56c-4db587327c79', '输送进度', '实施部队输送时,单位时间内发出的列车数。车辆数、船舶数、飞机数。进度大小根据上级意图、输送量、输送时限和运输能力等因素决定。', 256);
INSERT INTO `t_military_term_data` VALUES ('66edbee6-04fe-4c07-8e23-b25ea3b3834f', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹射向', '导弹的射击方向。通常根据基准方向（或检查方向）与瞄准方位角的关系确定。', 177);
INSERT INTO `t_military_term_data` VALUES ('66f0e56c-1bea-43a1-8cff-44ffd282f297', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '敌情判断', '对敌人情况进行分析研究并得出结论的思维活动。主要判明敌人的兵力、企图、部署、特点主要行动力向可能使用的作战方法和手段等', 68);
INSERT INTO `t_military_term_data` VALUES ('66f4552c-31a6-4c27-9b8c-0769c24fff8e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '障碍地带', '由各种障碍物有机结合而形成一定纵深和宽度的地带。通常设在防御阵地前沿前和翼侧,并与火力紧密结合。', 96);
INSERT INTO `t_military_term_data` VALUES ('66fed853-c18a-4d8e-9983-6b1a40808a38', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵应急分队', '为应付紧急或意外情况而专门设立的民兵分队。', 133);
INSERT INTO `t_military_term_data` VALUES ('67239593-eca4-4ab5-9141-1f52799fec95', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备普查', '对现有的武器装备的数量、质量、配套和管理情况进行的全面检查。', 117);
INSERT INTO `t_military_term_data` VALUES ('6726c58f-b603-40bd-8b1c-c6f77270376e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡河器材', '军队渡越江河障碍使用的工程器材。分为制式渡河器材和就便渡河器材。制式渡河器材包括制式桥梁器材、门桥器材、两栖渡河车辆、轻型渡河器材等。就便渡河器材包括现地征集的民舟、筏及用竹、木等材料制作的各种浮游结构物和桥梁构件。', 298);
INSERT INTO `t_military_term_data` VALUES ('67294d7d-550c-4621-a1db-ac0056d5fdb2', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂滞留时间', '毒剂云团在某一地点处于相对静止状态的时间。其长短受地形、地物、植被和气象等因素影响。', 120);
INSERT INTO `t_military_term_data` VALUES ('672b119d-a95f-42f9-8455-0ee53221025b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '加农榴弹炮', '简称加榴炮。兼有加农炮和榴弹炮两种火炮弹道特性的火炮。用多量装药射击时,初速大，弹道低仰；用少量装药射击时,初速小，弹道弯曲。主要用以射击远距离目标和破坏较坚固的工程设施。', 24);
INSERT INTO `t_military_term_data` VALUES ('6736aca3-d9c1-42a9-9fae-dfdd968ab591', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水上飞机锚泊', '水上飞机在水面上抛锚停泊。通常选择在风浪、水流较小,水深适宜,没有礁石和其他障碍物的水区锚泊。', 311);
INSERT INTO `t_military_term_data` VALUES ('673ea396-e039-407d-b136-a7dc6f06097d', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学袭击', '使用化学武器实施的袭击。通常分为杀伤性化学袭击、迟滞性化学袭击和扰乱性化学袭击。可用炮兵、航空兵、导弹等火力系统实施。', 22);
INSERT INTO `t_military_term_data` VALUES ('6747be08-73b1-4e76-807e-d6d8e0631b85', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮目线', '火炮射弹起点与目标的连线。', 257);
INSERT INTO `t_military_term_data` VALUES ('674b9bcb-0a66-4c15-b9f3-72a055888f82', '97a19170-bfac-42c5-9906-1acb187f0654', '任务飞行', '为执行抢险救灾、校验、试飞以及其他特定任务而实施的飞行。', 210);
INSERT INTO `t_military_term_data` VALUES ('675ab85a-854e-4c07-b913-d84e68c9fff1', '06a75831-13a1-4660-870a-455bb445336a', '运动通信', '由通信人员徒步或乘坐交通工具传递书面或口头信息的通信。', 130);
INSERT INTO `t_military_term_data` VALUES ('676062ed-cc5b-4fb8-9547-65055cf52dcd', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '基本歼灭', '敌军80％～90％被歼灭,基本上丧失了作战能力。', 380);
INSERT INTO `t_military_term_data` VALUES ('6770ca9f-3e04-49f2-925c-36b45ecca5f5', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵训练', '民兵组织进行的军事理论教育和作战技能训练。通常分为普通民兵训练和基干民兵训练。目的是提高民兵作战能力和为战时储备具有军事素质的后备兵员。', 137);
INSERT INTO `t_military_term_data` VALUES ('6774f711-62c8-4575-83a4-02ee273dc687', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥自动化系统', '建立在计算机技术、信息技术和系统工程方法基础之上的,对指挥所需信息的收集、储存、传递和处理具有自动化功能的系统。能把指挥、控制、通信、情报等有机地结合在一起,提高指挥效能。', 173);
INSERT INTO `t_military_term_data` VALUES ('677b3690-40e0-48da-a5a7-e20998760596', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '日出', '太阳升起时其上边缘与地平线相切的瞬间。日出时刻随日期和地理位置的不同而异,可根据所在地理位置和日期在专门编制的“日出时刻表”中查算。', 147);
INSERT INTO `t_military_term_data` VALUES ('6786e36e-b348-4e94-90ec-1b559d483262', '97a19170-bfac-42c5-9906-1acb187f0654', '空中进攻战役', '空军战役军团单独或在其他军兵种协同下实施的以空中进攻作战为主的战役。分为夺取制空权的空中进攻战役、削弱敌战争潜力的空中进攻战役、孤立战场的空中进攻战役和消灭敌重兵集团的空中进攻战役。', 32);
INSERT INTO `t_military_term_data` VALUES ('67b0b4d4-bc28-4b5b-829a-b6e84c558765', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '登陆输送队', '登陆作战中输送登陆兵及其武器装备到预定登陆地段登陆的舰艇编队。由登陆作战舰艇、运输舰船和警戒舰艇编成。通常1个登陆输送队可输送1个团的登陆兵。', 68);
INSERT INTO `t_military_term_data` VALUES ('67b2870a-aec8-4579-b581-39fae7bfec26', '8a761efd-50a6-4ac8-9913-b7d745104f82', '口径', '枪、炮身管的内直径。线膛身管的口径指两条相对阳膛线之间的距离，滑膛身管的口径指内径。通常以毫米为计算单位。', 5);
INSERT INTO `t_military_term_data` VALUES ('67c010a9-9a98-45d0-8d5b-b3cfb3ec27ba', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹道高', '弹道上任何一点到火身口水平面的垂直距离。', 26);
INSERT INTO `t_military_term_data` VALUES ('67c841ef-4b03-472a-8469-9bf592ecf545', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '参谋技能', '参谋人员从事业务工作的基本技巧和基础能力。主要包括组织作战所需要的写、画、传、读。记、算以及操作指挥设备、驾驶交通工具等技能。', 161);
INSERT INTO `t_military_term_data` VALUES ('67d45b0b-1f1a-4c64-b7a5-5f5a0857c87f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '地球静止卫星', '简称静止卫星。采用地球静止轨道的人造地球卫星。在地球赤道上空、距地面高约35786千米、倾角为0度的圆形轨道上,以3.07干米／秒的速度运行。轨道周期与地球自转周期相等。', 219);
INSERT INTO `t_military_term_data` VALUES ('67d771b3-55e4-4f98-949b-430e68c43649', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物战场环境', '生物武器袭击造成的战场情况与条件。通常指生物武器袭击造成的人、畜感染、发病以至死亡,以及大面积疫区等状况。', 34);
INSERT INTO `t_military_term_data` VALUES ('67e378fe-8d86-4c18-8e99-c96ebb61cf2e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '三类坦克', '需经过修理,恢复其功能才能执行任务的坦克。', 192);
INSERT INTO `t_military_term_data` VALUES ('67e6b729-ebc4-422f-b16b-3e018f1065fa', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '桥梁车轮式荷载', '轮式车辆和以轮胎为行走装置的技术兵器对桥梁的垂直压力。是验算桥板强度的主要数据。', 295);
INSERT INTO `t_military_term_data` VALUES ('67eabaa1-fa6d-42da-be33-792b3870d741', '98df76fb-4b65-48ff-a56c-4db587327c79', '输送时限', '实施部队输送时对输送持续时间的限定。指自第一输送梯队由装载点发出,至最后一个输送梯队到达卸载点时的总时间。通常由军事交通运输部门根据上级意图,会同国家交通运输部门商定。', 257);
INSERT INTO `t_military_term_data` VALUES ('67ecebf7-9b41-40f4-b4b7-7b5fbef92dc0', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '水平控制测量', '为建立水平控制网而进行的测量。通常采用三角测量、导线测量、三边测量、边角测量等方法。配以天文测量、重力测量和高程测量,经数据处理可获得网中各点的大地坐标或平面直角坐标。', 164);
INSERT INTO `t_military_term_data` VALUES ('67f50e98-a158-4c7d-8faf-0187110d763c', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '半日潮', '在一个太阴日内出现两次高潮和两次低潮,相邻的高潮或低潮的潮高大体相等的潮汐。', 138);
INSERT INTO `t_military_term_data` VALUES ('67f7cd22-10bd-4904-b6c2-2ca6659eb9fa', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹待发状态', '导弹在发射装置上完成测试、加注、瞄准、装定射程等工作后处于待命发射的状态。', 136);
INSERT INTO `t_military_term_data` VALUES ('68013b32-0d52-44ec-8494-6eb4ff45834e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '战备坦克', '坦克部队为保障作战使用而储备的坦克。通常储备摩托小时不得少于发动机使用寿命的70％,车体储备使用时间不得少于大修间隔期的45％,并定期换季、普查,动用时须经批准。', 188);
INSERT INTO `t_military_term_data` VALUES ('68084a5f-c78e-4a61-a529-47d549d99bb8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵声测器材', '炮兵用以测定火炮发射与弹丸爆炸所形成的脉冲声源位置的器材。一般用以确定敌方炮位和校正己方火炮射击。不受能见度和通视程度的限制，但受气象条件影响较大。', 283);
INSERT INTO `t_military_term_data` VALUES ('680b24cb-cefc-4a76-add5-4d9db04025da', '06a75831-13a1-4660-870a-455bb445336a', '调幅电台', '采用载波振幅随调制信号变化的调制方式,发送、接收调幅信号的无线电台。设备较简单,通信容量小,耗费功率较大。主要用于无线电话、电报通信及导航、广播等。', 183);
INSERT INTO `t_military_term_data` VALUES ('680eef03-9234-4721-9c1b-8a2d8651db1d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹齐射', '在统一指挥下,两发以上的地空导弹同时或在极短的间隔时间内射向同一目标的发射。通常用以射击重要目标。', 210);
INSERT INTO `t_military_term_data` VALUES ('68236eb1-a85a-4da7-8da9-726662f23ac4', '98df76fb-4b65-48ff-a56c-4db587327c79', '军用士地', '军队拥有使用权和管理权的国有土地。主要包括：由政府无偿划拨给军队使用的土地,军队通过法律手续征用的土地,军队与地方单位调换或地方有偿转让的土地,军队开垦荒山荒地以及填（围）海（湖）造出的土地等。分为直接军事用地、间接军事用地和准军事用地等。', 239);
INSERT INTO `t_military_term_data` VALUES ('6850bff0-a108-4b70-968f-3457ad2ca4e4', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '装配式工事', '用预制构件作支撑结构组装成的可多次装拆使用的工事。按结构材料,分为波纹钢工事、玻璃钢工事、型钢工事、钢丝网水泥工事、钢筋混凝土构件工事、竹木构件工事、充气工事、集装箱工事等。', 51);
INSERT INTO `t_military_term_data` VALUES ('68534c9a-a206-4473-bcef-4c95d4a45c88', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物防护', '生物武器防护的简称。为避免或减轻敌生物武器袭击的危害而进行的防护。主要包括：对生物战剂侦察和检验,免疫接种和药物预防,消毒、杀虫和灭鼠,使用个人和集体防护器材进行防护,隔离和治疗传染病人,对污染区进行处理等。', 67);
INSERT INTO `t_military_term_data` VALUES ('6856fcec-59d5-472e-a4a7-8474baa906f3', '8a761efd-50a6-4ac8-9913-b7d745104f82', '命中概率', '亦称命中公算。射击武器在一定射击条件下射弹命中目标可能性大小的量。通常用0～1的数值或百分比表示。如同一条件下多次射击，每射弹100发,平均命中80发,命中概率即为0.8或 80％。', 81);
INSERT INTO `t_military_term_data` VALUES ('68589681-ad39-4397-9bad-19066a716687', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '排雷舰艇队', '登陆作战中负责排除水雷障碍的舰艇编队。由扫雷舰艇、猎雷舰艇、破雷舰和炸雷艇等编成。', 70);
INSERT INTO `t_military_term_data` VALUES ('6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '0', '国防科技', NULL, 24);
INSERT INTO `t_military_term_data` VALUES ('6867e6f3-84ae-4a24-93a9-e9a7e527265b', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '国防科学技术', '简称国防科技。直接为国防服务的自然科学及应用技术的统称。是构成国防力量的重要因素和衡量国防现代化水平的重要标志。其发展状况,直接关系到国防建设的现代化程度。', 0);
INSERT INTO `t_military_term_data` VALUES ('686f9bdf-b674-4d16-a7e1-edf2919223a8', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程措施', '为完成工程保障任务而采取的手段和办法。', 33);
INSERT INTO `t_military_term_data` VALUES ('68800d65-ab07-4d3f-ae1c-16424b9e5394', '98df76fb-4b65-48ff-a56c-4db587327c79', '按区域保障', '亦称划区保障。后勤机构按划分的区域组织实施的保障。通常为每个划定的区域编配一定的后勤力量,并派出一个指挥机构,负责对区域内所有部队或分队的保障。', 34);
INSERT INTO `t_military_term_data` VALUES ('688b30fa-511d-4c67-ac74-b7ee280c25cb', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '红外制导', '利用目标辐射的红外线获得制导信息进行的制导。常用于空空导弹和地空导弹。', 54);
INSERT INTO `t_military_term_data` VALUES ('68a977c4-c2c3-4f56-9b52-47022484ce10', '8a761efd-50a6-4ac8-9913-b7d745104f82', '落角', '落点的弹道切线与火身口水平面的夹角。', 32);
INSERT INTO `t_military_term_data` VALUES ('68ac0b6b-c32e-44dc-ac31-d6e89d0dd664', 'f0140091-c11a-48c9-8836-8aa94439dac0', '既设阵地', '由预先构筑的阵地。', 213);
INSERT INTO `t_military_term_data` VALUES ('68b3bd9e-4c14-4c3e-85cf-f0c85c6dc36d', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '转业', '中国人民解放军的干部和志愿兵退出现役转到地方,由国家统一安排工作。', 156);
INSERT INTO `t_military_term_data` VALUES ('68be87ac-337e-45c3-bd34-f1969ead189a', '97a19170-bfac-42c5-9906-1acb187f0654', '空中转信', '利用中介飞机上的无线电通信设备在空中收转信息的通信。分为转信飞机自动空中转信和指派飞机人工空中转信。主要用以增大地面通信点之间和地空通信点之间的无线电通信距离。', 356);
INSERT INTO `t_military_term_data` VALUES ('68caceeb-613e-4926-a643-0af3111f945d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '恒星', '由炽热气体组成的,能自己发光的球状或类球状天体。太阳是距地球最近的恒星。太阳以外的其他恒星,都在不停地运动,因距离地球非常遥远,在短期内人们感觉不到它们相互位置的改变,故称为恒星。人眼能看到的恒星约6500颗,主要的明亮恒星约50颗。', 186);
INSERT INTO `t_military_term_data` VALUES ('68dbd703-e8aa-43d9-a386-1970792ea982', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '自然资源', '存在于自然界可供人类利用的各种资源的统称。包括矿产资源、水资源、气候资源、土地资源、生物资源等。是人类赖以生存和发展的物质基础,是构成国力的重要因素。', 96);
INSERT INTO `t_military_term_data` VALUES ('68df78a0-4560-4cee-b0be-61cb1f41db64', 'f0140091-c11a-48c9-8836-8aa94439dac0', '先遣支队', '先于主力部队行动,遂行特定任务的战斗编组。通常由师以上单位派出和指挥。主要用以查明情况,驱逐或歼灭敌警戒分队,抢占要点等。', 167);
INSERT INTO `t_military_term_data` VALUES ('68e276e6-8657-4a34-bb09-f7013a0e54af', '97a19170-bfac-42c5-9906-1acb187f0654', '空降集合', '空降部队着陆后按照预定的战斗部署和队形集结在一起的行动。通常是边前进、边集合、边组织战斗。', 169);
INSERT INTO `t_military_term_data` VALUES ('68e5b344-3b78-46f1-aff9-977c08287a22', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '迂回', '绕向敌翼侧和后方的作战行动。通常用以断敌退路,阻敌增援,协同正面进攻,合围和消灭敌人。分为战略迂回、战役迂回和战术迂回。', 366);
INSERT INTO `t_military_term_data` VALUES ('68eb99a3-5c78-4541-ad43-0e15172fdbf0', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '沙盘', '军队使用的用沙土或其他材料做成的地形模型。根据地形图、航空照片或实地的地形,按一定的比例尺制作。通常布以兵棋,以显示地形和地面目标。主要用以研究地形、敌情、作战方案、组织协同和军事训练等。', 162);
INSERT INTO `t_military_term_data` VALUES ('68f6d029-8b67-4210-8349-7cc63caaf09c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '目测法', '以目视和器材概略测定求取炮目距离和炮目方向,决定射击开始诸元的方法。目测法精度较差,一般只用以决定试射开始诸元。', 143);
INSERT INTO `t_military_term_data` VALUES ('6900d219-3f65-4f94-b5a3-c2172e5e46ee', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通调整勤务', '维护交通秩序,调整车辆运行,指挥人员、车辆疏散隐蔽的勤务。一般由派出的交通调整哨负责执行；大部队通过的重要地区,通常由开设的调整指挥机构负责组织实施。', 290);
INSERT INTO `t_military_term_data` VALUES ('690c90ee-18b4-4e6f-b631-d4722ca8d6f3', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '要害', '关系全局安危的目标或部位。如作战部署中足以影响全局的要点、指挥机关及C3I系统、导弹发射场和炮兵阵地等。', 303);
INSERT INTO `t_military_term_data` VALUES ('690ee0d8-363f-4a25-b65e-ad211346720d', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '位置保持', '为把地球静止卫星的轨道保持在规定的偏差范围内而作的轨道控制。主要是通过卫星上的小发动机达成。分为南北位置保持和东西位置保持。', 265);
INSERT INTO `t_military_term_data` VALUES ('6931f2a4-794c-48ce-8a6c-ce517b6187ff', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反潜机', '主要用以搜索和攻击潜艇的海军飞机和直升机。通常装备有航空声纳、磁力探潜仪等搜潜设备和反潜导弹、反潜鱼雷、深水炸弹等反潜武器。', 181);
INSERT INTO `t_military_term_data` VALUES ('6943ffaf-7fe1-436a-bdc6-030309ae4668', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆三防性能', '装甲车辆对核、化学、生物武器的防护特性与功能。一般体现为车内超压值、反应时间和滤清效率等。装有三防装置的主战坦克通常可在乘员室内建立起大于295帕的超压,滤清效率可达90％以上,滤毒效率可达99％以上。', 178);
INSERT INTO `t_military_term_data` VALUES ('694ff4e6-b7f7-4bb6-8ece-2c81b143165f', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '风浪', '由风力直接作用产生的波浪。风浪的波面较陡,波长短,波峰处常有浪花或泡沫,传播方向与风向一致。海上风浪的强弱受制于海区风场的变化。按浪高,可划分为无浪、微浪、小浪、轻浪、中浪、大浪、巨浪、狂浪、狂涛和怒涛等10级。', 129);
INSERT INTO `t_military_term_data` VALUES ('695ac390-4163-4444-8235-0feb9ef8b4de', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '反射器', '能将从各个方向入射的电磁波再反射回去的装置。分为光波反射器和雷达反射器。光波反射器主要用以欺骗敌光电探测和制导设备。雷达反射器主要用以干扰雷达,还可用于各种测量和气象观测。', 134);
INSERT INTO `t_military_term_data` VALUES ('6979f2a8-7d65-4789-b71a-83d25f0f7ed2', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹自毁时间', '从地空导弹发射到地空导弹自毁所用的时间。', 201);
INSERT INTO `t_military_term_data` VALUES ('6983f5df-a30d-4944-b5c5-56882634d909', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器威力', '轻武器对目标的杀伤和破坏的能力。通常以毁伤概率表示。其大小主要取决于射程、终点效应、射击精度、战斗射速、目标类型等因素。', 215);
INSERT INTO `t_military_term_data` VALUES ('698a9c57-04f6-41b9-8c6c-aff69afae3c6', '916997ee-6728-4c61-9b79-d96960b1dc86', '苯氯乙酮', '主要作用于眼睛的催泪型刺激剂。眼睛受刺激后,引起怕光和大量流泪；高浓度时也刺激上呼吸道,引起咳嗽、恶心等症状。', 224);
INSERT INTO `t_military_term_data` VALUES ('699877b9-18a9-4bb1-b580-1501a3669d1c', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '中央处理机', '简称处理机。计算机的中央处理器与主存储器的统称。包括运算器、控制器和主存储器。', 56);
INSERT INTO `t_military_term_data` VALUES ('699a079e-a7f2-4fad-bb79-4ce17f8022e5', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦收员', '使用技术器材截获侦察对象的电话、电报、数据、图像等的人员。', 82);
INSERT INTO `t_military_term_data` VALUES ('69a41b51-2f47-41bd-b776-446c5c1ad36c', '97a19170-bfac-42c5-9906-1acb187f0654', '高空飞行', '航空器在真实高度为 7000～15000米（含）的飞行。', 233);
INSERT INTO `t_military_term_data` VALUES ('69ac15a9-1dfb-4652-9863-32cdaabcc7ae', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '情况处置', '指挥员及其指挥机关对作战中出现的各种情况采取相应处理措施的行动。', 107);
INSERT INTO `t_military_term_data` VALUES ('69ce3a67-b086-4bab-9c22-0e8f432262ec', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '交通壕', '供人员隐蔽机动、前送后送和连接工事用的掘开式交通工事。按深度,分为匍匐行进交通壕、屈姿行进交通壕和立姿行进交通壕。视需要在壕内可构筑和设置掩蔽、射击、待避、进出、排水等设施和路标。', 64);
INSERT INTO `t_military_term_data` VALUES ('69d79c45-26f1-40a9-a5fb-55dba852fff5', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克兵', ' ①坦克乘员的筒称。②同装甲兵。', 1);
INSERT INTO `t_military_term_data` VALUES ('69dfaab8-a002-4f0c-b3bc-91d5b3b11ff2', '97a19170-bfac-42c5-9906-1acb187f0654', '上升率', '亦称爬升率。飞机或直升机在单位时间内上升的垂直距离。通常以米／秒或米／分为计算单位。', 300);
INSERT INTO `t_military_term_data` VALUES ('69e30470-c02b-43bc-84d6-57865b7afac0', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '堑壕', '供人员射击、观察、隐蔽和机动用的壕沟式工事。多为曲线形或折线形。按深度,分为跪射堑壕、立射堑壕和加深堑壕。壕内通常有射击、观察、掩蔽、排水、路标和进出口等设施。', 65);
INSERT INTO `t_military_term_data` VALUES ('6a036ed9-b362-44f6-b2d4-c3318897c141', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火反准备', '炮兵对完成进攻准备、即将发起进攻之敌实施的火力突击。用以破坏敌进攻准备或削弱其首次突击力量。最有利的开始时机是在敌实施火力准备直前。', 71);
INSERT INTO `t_military_term_data` VALUES ('6a0551f8-8876-4f53-8826-e065a1e955df', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地理图', '比例只小于 1:100万的普通地图。没有统一的地图投影和地图分幅。内容概括,反映广大地区地理现象的主要特征。多用以研究、了解一般的自然地理和社会经济等情况。', 252);
INSERT INTO `t_military_term_data` VALUES ('6a10fb7d-e429-4d65-8dcd-0c77def4b9de', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹着点', '弹道与目标或地表面的交点。', 30);
INSERT INTO `t_military_term_data` VALUES ('6a1de363-985a-4f2d-8533-89fa1486b903', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '值班日记', '由值班人员记载的在值班时间内发生的情况及处置结果的备考文书。', 144);
INSERT INTO `t_military_term_data` VALUES ('6a281b3b-82f8-4eed-9d0f-6312d54d648a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇防疫', '在舰艇上采取的预防、控制和消灭传染病流行的措施。包括对舰员防疫接种、卫生消毒以及灭鼠等。', 352);
INSERT INTO `t_military_term_data` VALUES ('6a2ce313-fce4-4a3c-8f94-f39f82c411dc', '97a19170-bfac-42c5-9906-1acb187f0654', '机场等级', '根据主跑道长度和道面承载能力以及机场保障能力等条件,对军用永备机场划分的级别。按跑道的基本长度,分为特级、一级、二级、三级4个等级；按道面承载能力,分为A级、B级、C级、D级、E级5个等级。', 410);
INSERT INTO `t_military_term_data` VALUES ('6a337f11-d7d2-4f6b-bbc8-e6dbdbd971bc', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '硝铵炸药', '以硝酸铵为主要成分的混合炸药。主要有铵梯炸药、铵油炸药等。多为浅黄色或灰白色,使用安全、经济,但易受潮。主要用于内部装药爆破土石方等。', 211);
INSERT INTO `t_military_term_data` VALUES ('6a39ce1f-9d97-4c3e-a8f4-f8efa1bd581d', '31f4a446-5b98-4873-9d53-310d97125b07', '发射导弹', '按照发射程序使导弹由临射状态到点火飞离发射装置的过程。须在导弹完成发射准备并合格的基础上进行。', 106);
INSERT INTO `t_military_term_data` VALUES ('6a4266c1-819c-45e2-8b6f-7e3c16ca6114', '98df76fb-4b65-48ff-a56c-4db587327c79', '军马场', '繁殖和培育军用骡马的生产单位。', 164);
INSERT INTO `t_military_term_data` VALUES ('6a4361fa-bba2-46d7-808f-8607a71539d6', 'f0140091-c11a-48c9-8836-8aa94439dac0', '直身前进', '单兵直身大步或快步前进的动作。通常在隐蔽条件较好、敌火力威胁不大的情况下采用。', 114);
INSERT INTO `t_military_term_data` VALUES ('6a47698b-7e84-4516-9f63-65780832c5e5', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '城市防御工程', '亦称城市防卫工程。用于城市防御作战的各项工程设施的统称。包括地面工程和地下工程。', 66);
INSERT INTO `t_military_term_data` VALUES ('6a590d75-8328-44e1-af62-77001b681674', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克淤陷', '坦克陷于沼泽地、稻田地、沙滩、冰雪地、江河、沟谷等处不能正常行动的状况。根据淤陷程度和拖救所需牵引力的大小,分为轻陷、中陷、重陷和超重陷。', 220);
INSERT INTO `t_military_term_data` VALUES ('6a655356-dbd8-48dc-a165-a90d14a63be7', '98df76fb-4b65-48ff-a56c-4db587327c79', '统供', '由合成军队后勤机构统一组织实施的物资供应。主要适用于诸军兵种通用物资的供应。', 94);
INSERT INTO `t_military_term_data` VALUES ('6a7657e3-b761-4b51-8572-e1cb3bca4fb4', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水雷', '布设在水中,当舰船与其碰撞或进入其非触发引信作用范围,或由人工控制而起爆的水中武器。按在水中状态,分为锚雷、沉底雷和漂雷；按引信类型,分为触发水雷、非触发水雷和控制水雷；按布雷平台,分为舰布水雷、潜布水雷、空投水雷和通用水雷；此外,还有火箭上浮水雷、自导水雷、自航水雷等特殊性能的水雷。', 210);
INSERT INTO `t_military_term_data` VALUES ('6a775b7a-cbaa-4e67-be3f-ce1205dc1aee', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵通信保障', '为使炮兵顺利遂行任务而在通信联络方面进行的保障。按通信设施分为有线电、无线电通信保障；按保障任务,分为指挥、协同、警报和情报报知等通信保障。通常以无线电通信为主。与有线电通信和其他通信手段并用。', 122);
INSERT INTO `t_military_term_data` VALUES ('6a871c4e-eff5-4a9d-b395-e0df14412fe4', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '火箭爆破器', '以火箭发动机为动力拖带直列装药在地雷场中开辟通路的爆破扫雷器。由火箭发动机、爆炸带、控制标示绳、发射架等组成。射程为数十米至四百多米。', 176);
INSERT INTO `t_military_term_data` VALUES ('6a8beca3-25b6-4bd8-ba78-9702f9af1659', '83e065b4-6737-4645-9ea5-8276d1de13ed', '步兵战车', '简称步战车。用于步兵机动和战斗,能与主战坦克直接协同冲击,也可独立遂行突击任务的装甲战斗车辆。分为履带式和轮式两种。', 95);
INSERT INTO `t_military_term_data` VALUES ('6a8f7bb2-9c9c-4df2-870f-8ab0510dd169', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事地图制图', '军用地图的设计、制作和复制的理论与技术。包括地图设计、地图的投影选取、地图编绘、地图复制等工艺过程。', 249);
INSERT INTO `t_military_term_data` VALUES ('6a920e76-2304-4cf5-8f6a-21c9189dff1e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '临时轻便炮兵群', '由团营属炮兵和加强的轻便炮兵临时组成的战斗编组。通常在步兵团未编炮兵群时建立。', 45);
INSERT INTO `t_military_term_data` VALUES ('6a94d0ef-9c8b-4b35-a991-ef2646ba9dc0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮火线高', '火炮纵横向水平时身管轴线到地面的垂直距离。', 250);
INSERT INTO `t_military_term_data` VALUES ('6a989cd1-1807-4e29-bda8-e1e525b55cc0', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '决心建议', '参谋长和指挥机关为指挥员定下决心提出的建议、可口头或书面提出、要求抓住重点、简明扼要符合上级意图', 77);
INSERT INTO `t_military_term_data` VALUES ('6aa0ae59-ce91-42a3-aa2c-f559f3421c47', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '对流层', '位于大气最下部，垂直对流运动显著的大气层。下边界为地表面,厚度随纬度和季节而异,中纬度平均距地面10～12千米。气温随高度的增加而降低,平均递减率为 6.5度／千米。对流层集中了整个大气的 3／4的质量和几乎全部的水汽,常产生云、雨、雪、雾、雷电等天气现象,是天气变化最复杂、对人类生活和军事活动影响最大的大气层。', 2);
INSERT INTO `t_military_term_data` VALUES ('6aa69425-f2bb-489a-8846-a957b52d0f78', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '声纳浮标', '探测水下潜艇的浮标或水声遥感器材。按用途,分为航空声纳浮标和锚系固定监视声纳浮标；按工作方式,分为主动声纳浮标和被动声纳浮标,定向声纳浮标和非定向声纳浮标,有线电声纳浮标和无线电声纳浮标。', 241);
INSERT INTO `t_military_term_data` VALUES ('6aab03fa-72a3-4ff9-9412-bad2cbefe98b', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '换乘地域', '输送途中转换输送工具的地域。', 87);
INSERT INTO `t_military_term_data` VALUES ('6aab71b6-6274-4882-84c9-3d34b18829d9', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '濒陆海区', '邻接陆地的海区。在海军与陆军协同作战中,通常指岸炮火力与岸舰导弹火力能够控制的海区。', 380);
INSERT INTO `t_military_term_data` VALUES ('6ac08a36-8260-41d9-b733-5c67c3468b61', '98df76fb-4b65-48ff-a56c-4db587327c79', '油料勤务', '军用油料和油料装备的供应、管理及其技术保障的专业勤务。主要内容包括：组织实施油料和油料装备的筹措、储备、供应、管理和技术保障,制定油料勤务规章制度,拟定油料工作规划、计划和保障方案,管理油料专业部队或分队的业务工作,开展油料勤务和油料技术的科学研究等。', 165);
INSERT INTO `t_military_term_data` VALUES ('6ac74dde-98f4-4ff3-8e55-59daf57adafe', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '夜间侦察训练', '为使侦察部队和分队掌握夜间实施侦察的技能和方法而进行的训练。主要训练内容包括：夜间活动的动作要领,夜间观察与潜听,夜视器材的种类、性能、特点及其操作使用等。', 92);
INSERT INTO `t_military_term_data` VALUES ('6acfe40b-f61f-4ca3-8316-8b3dbe412c5c', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机待命区域', '直升机部队进行作战准备、等待投入战斗的区域。', 85);
INSERT INTO `t_military_term_data` VALUES ('6ad54244-c120-439f-805d-756b186933ab', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '军用工程机械', '军队装备的用以遂行工程保障任务的机械。通常分为野战工程机械、建筑机械和保障机械。', 372);
INSERT INTO `t_military_term_data` VALUES ('6aede7ed-1f36-451d-8369-b82dff24bb8d', '83e065b4-6737-4645-9ea5-8276d1de13ed', '轮式装甲车辆', '靠轮胎行驶的装甲车辆。按驱动型式分,主要有4X4、6X6、8X8三种。与履带式装甲车辆相比,具有噪声低、公路行驶速度高和使用维修简便等特点,但越野机动性能较差。', 83);
INSERT INTO `t_military_term_data` VALUES ('6af09f27-f20e-4dd0-8c2e-a3962917d00f', '97a19170-bfac-42c5-9906-1acb187f0654', '空军地空导弹兵战术', '空军地空导弹兵进行战斗的方法。主要包括战斗基本原则、兵力部署、战斗指挥、抗击敌空袭与侦察的行动、协同动作与各种保障措施等。', 131);
INSERT INTO `t_military_term_data` VALUES ('6b18d281-c28b-4a46-a216-1239b44b9f89', '98df76fb-4b65-48ff-a56c-4db587327c79', '野战食品', '中国人民解放军总后勤部或军区后勤部派出的划区保障机构。设有司令部、政治部和若干业务处,并根据保障任务编有若干医院、仓库以及运输、工程、修理等勤务部队或分队。分为一线分部、二线分部和总后勤部直属分部。', 143);
INSERT INTO `t_military_term_data` VALUES ('6b210433-b568-42f2-8b73-82015577f221', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮', '以火药为能源发射弹丸,口径在20毫米以上的身管射击武器。按炮膛构造,分为线膛炮和滑膛炮；按弹道特性,分为加农炮、榴弹炮、加农榴弹炮和迫击炮等。', 15);
INSERT INTO `t_military_term_data` VALUES ('6b269bf7-5e0b-448b-a37d-78540bacdb66', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '军官训练', '对现任和拟任军官进行的训练。通常采取院校培训、在职训练等形式组织实施。', 57);
INSERT INTO `t_military_term_data` VALUES ('6b26f5c0-25d1-45c0-80d5-3f8b4a909ef2', '916997ee-6728-4c61-9b79-d96960b1dc86', 'β射线皮肤烧伤', '人员皮肤沾染放射性物质,由射线照射造成的损伤。按皮肤损伤程度通常分为3度：一度,出现红斑,脱毛及于性脱屑,有烧灼感；二度,出现水肿、水泡、表残溃疡,湿性脱屑；三度,患部剧痛,出现深层溃疡、坏死等症状。', 111);
INSERT INTO `t_military_term_data` VALUES ('6b2cb7a7-f2a7-487e-a9eb-cd00e2519a59', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机伏击', '直升机预先埋伏在敌必经通路附近,待敌通过时突然升空进行攻击。', 68);
INSERT INTO `t_military_term_data` VALUES ('6b34f43f-7803-4827-8f46-633e8343c327', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '游动哨', '在一定的区域内执行巡逻警戒任务的哨兵。通常配置在警戒线附近或宿营地域内,按规定的范围或路线进行警戒活动。', 31);
INSERT INTO `t_military_term_data` VALUES ('6b3b7f1c-7dda-4647-87be-85bff53ad0b1', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '传统教育', '以继承和发扬党和军队优良传统为主要内容的教育。', 99);
INSERT INTO `t_military_term_data` VALUES ('6b4917c6-0db0-4175-bd26-efda85c8a539', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '消光材料', '对光波能量具有强烈的吸收、衰减或散射作用的材料。主要用以干扰敌方光电设备。', 140);
INSERT INTO `t_military_term_data` VALUES ('6b4c51c6-30e0-4178-aecd-a643d6813864', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵防化保障', '第二炮兵为使部队免受或减轻核、化学、生物武器伤害而进行的保障。主要包括；实施核观测、化学观测和化学、辐射侦察,组织沾染检查和剂量监督,进行消毒和消除沾染,组织防化器材的保障工作等。', 188);
INSERT INTO `t_military_term_data` VALUES ('6b5304ca-85a0-4a03-8412-ec9374aceedb', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射弹侵彻力', '亦称贯穿力。射弹击中水泥、砖石、土木结构等非装甲物体后的穿入能力。其大小主要取决于弹丸质量、断向比能、目标性质和命中角大小。通常以射弹钻入深度衡量。', 118);
INSERT INTO `t_military_term_data` VALUES ('6b759b89-3b87-40c3-ac71-cf5cc0f68019', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸冲击波效应', '核爆炸瞬间,从爆心向四周传播的高速、高温、高压气浪对人员及物体造成的毁伤作用和效果。毁伤的严重程度主要取决于冲击波所形成的超压和动压的大小。', 157);
INSERT INTO `t_military_term_data` VALUES ('6b7a1c20-2e2e-429b-9669-75a23b4ed46b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '仙后星座', '在北天极附近,似“W”状的星座。与大熊星座遥遥相对、北纬40度以北、以南地区分别在全年和下半年可以看到。在仙后座“W”的缺口方向约为缺口宽度的两倍处,可找到北极星。', 194);
INSERT INTO `t_military_term_data` VALUES ('6b7fae1f-fbe9-41a4-b25c-e44a9ca25168', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '对舰载机指挥', '对舰载机部队飞行、作战行动实施的指挥。包括起降指挥、对空指挥和空中指挥。', 117);
INSERT INTO `t_military_term_data` VALUES ('6b866054-216a-4ccc-9f72-0663b4d5657d', 'f0140091-c11a-48c9-8836-8aa94439dac0', '登陆冲击出发线', '登陆分队在近岸水域发起冲击的起始线。通常以两侧的锚泊小型船艇标示。用以控制发起冲击的时间和调整冲击队形。', 140);
INSERT INTO `t_military_term_data` VALUES ('6b91003b-f188-4b8a-9bf4-0b29e1d41d01', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇部队', '以潜艇为基本装备,主要在水下遂行作战任务的海军兵种。包括战略导弹潜艇部队和攻击潜艇部队。可攻击敌方大、中型舰船和潜艇,突袭陆上战略目标,袭击和封锁港口、基地,破坏海上交通线以及进行侦察、反潜、布雷、巡逻和运送人员、物资等。', 1);
INSERT INTO `t_military_term_data` VALUES ('6b9a769e-d596-4a54-801c-e3570797b54b', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '组织保障', '计划与组织各种保障的活动。包括组织作战保障、技术保障、后勤保障等。', 83);
INSERT INTO `t_military_term_data` VALUES ('6b9e2702-be93-4a92-bead-6bb61a20fda3', '98df76fb-4b65-48ff-a56c-4db587327c79', '军队后勤', '军队所属后勤系统从事的各项后勤活动的统称。是军事后勤的主体部分。', 2);
INSERT INTO `t_military_term_data` VALUES ('6ba1b4c6-4ee6-49a5-8f95-2a4f44cc3eea', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '泊位', '港内可供船舶停泊的位置。包括供船舶停泊的码头泊位、浮筒泊位、锚地泊位等。停泊1艘船舶所需的位置称1个泊位。其数量和等级是港口规模和吞吐能力的主要标志。', 107);
INSERT INTO `t_military_term_data` VALUES ('6ba496ea-182a-4f66-9e62-e3fc7efc3f17', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '扫雷舰艇', '装有多种扫雷具,具有搜索和排除水雷能力的水面战斗舰艇。包括舰队扫雷舰、基地扫雷舰和遥控扫雷艇等。', 140);
INSERT INTO `t_military_term_data` VALUES ('6ba4f1d4-987f-4be6-8bcb-8d34067eee0c', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备机动', '根据战备需要而进行的兵力兵器机动。', 109);
INSERT INTO `t_military_term_data` VALUES ('6bb55d08-2c07-40db-98af-c1488ddc34f9', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '机械化部队', '陆军中能以建制内的装甲战斗车辆实施机动和作战的部队。是以装甲步兵或坦克兵为主体的诸兵种合成部队。', 47);
INSERT INTO `t_military_term_data` VALUES ('6bc9d40d-23a1-4288-bea8-c1626d353997', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天气形势', '天气系统的空间分布及其所显示的大气运动状况、分为气压形势、环流形势、地面形势、高空形势等。天气形势分析是制作天气预报的前提。', 36);
INSERT INTO `t_military_term_data` VALUES ('6bd9d5aa-c288-4747-add5-38ae647d81a0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火反击', '防御作战中炮兵集中一定的火力,对进攻之敌实施的火力突击。通常预先计划,有时临时组织。用以杀伤敌有生力量,摧毁其兵器,破坏其指挥系统,削弱或阻滞其进攻。', 72);
INSERT INTO `t_military_term_data` VALUES ('6bdc93e4-a96a-4f2a-aba2-a0afdbb979f2', '916997ee-6728-4c61-9b79-d96960b1dc86', '燃烧弹药', '装有燃烧剂的弹药。包括燃烧航空炸弹、燃烧炮弹、燃烧火箭弹、燃烧枪榴弹、燃烧手榴弹等。', 234);
INSERT INTO `t_military_term_data` VALUES ('6bdeca15-a477-478b-8729-20394c1ee1b8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事力量', '简称军力。国家或政治集团在军事领域内所拥有的各种力量的统称。包括军事实力与军事潜力。', 45);
INSERT INTO `t_military_term_data` VALUES ('6be570b5-6755-4da8-907f-fd8e4438ae31', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵利用侦察校射雷达射击', '炮兵利用侦察校射雷达侦察目标位置、测定炸点位置或偏差量实施的射击。利用雷达校射,能在较远的距离上捕捉目标和炸点,作业简便,精度较好,但在大雪、大雨天气,雷达效能降低,且易受电子干扰。', 198);
INSERT INTO `t_military_term_data` VALUES ('6be926c3-5142-4114-8ea3-4a84049224ea', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '军兵种运用', '合成军队指挥员对所属各军兵种部队和分队的指挥控制与使用。', 104);
INSERT INTO `t_military_term_data` VALUES ('6beb384d-0304-44b5-9f79-eed30d76cc2c', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机掩蔽库', '在机场内用钢筋混凝土构筑的有顶盖的飞机防护工事。', 437);
INSERT INTO `t_military_term_data` VALUES ('6bedd280-40ae-4f9a-a2d8-885273cbfb52', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '警戒水位', '危及水体堤坝安全的水位。通常根据各地水体及其防洪能力等具体情况确定。', 113);
INSERT INTO `t_military_term_data` VALUES ('6bedefca-8bbc-4ddb-a188-9eba0dd73fe0', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '氢铀弹', '亦称三相弹。核能量释放过程包含山裂变反应到聚变反应再到裂变反应三个阶段的氢弹。通常在热核装料外包上一层铀-238外壳,聚变反应所产生的高能中子使壳体铀-238发生裂变,从而释放更多能量。绝大多数战略核武器均属此类型。氢铀弹的威力和比威力皆成倍提高,放射性沾染较严重。', 92);
INSERT INTO `t_military_term_data` VALUES ('6c05aec6-c1eb-4d76-a42b-920100d76235', 'f0140091-c11a-48c9-8836-8aa94439dac0', '对仓促防御之敌的进攻战斗', '对临时转入或应急进行防御之敌实施的进攻战斗。', 128);
INSERT INTO `t_military_term_data` VALUES ('6c071756-2541-43dd-a78b-8ff03beb2ef3', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '警备条令', '规定军队警备工作的组织与实施的条令。是军队组织实施警备工作的依据。', 6);
INSERT INTO `t_military_term_data` VALUES ('6c129481-b721-4989-9952-6f551dcfeddb', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '我情判断', '对乙方情况进行分析研究并得出结论的思维活动、主要判明投入兵力的数量质量及其与敌军的对比,部队特点及其行动准备的状况后勤、技术保障状况友邻情况等。', 69);
INSERT INTO `t_military_term_data` VALUES ('6c18b614-8afd-4f0b-8a9f-0fa31c32b676', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '专业训练', '专业部队、分队及人员进行的以专业理论、技能为主要内容的训练。包括专业技术训练和专业战术训练。', 77);
INSERT INTO `t_military_term_data` VALUES ('6c1b25e4-9c24-44b8-9b7e-1887dda761eb', '878651de-adf5-4c72-9376-9c363b893ff8', '防御战略', '筹划和指导防御性战争全局的方略。相对于进攻战略而言。分为积极防御战略和消极防御战略。', 54);
INSERT INTO `t_military_term_data` VALUES ('6c22efc4-1523-456d-a635-47be21afe393', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮短点射', '小口径高炮每次射击时每管发射2～3发炮弹的发射方式。通常用于对空中低速目标射击。', 183);
INSERT INTO `t_military_term_data` VALUES ('6c37155c-082c-4f72-8ec7-d6e4f0a04866', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无源定位', '利用无线电接收设备所接收的电子设备发射的电磁信号测定辐射源的位置。主要方法有单站定位法、交会定位法和时差定位法等。', 35);
INSERT INTO `t_military_term_data` VALUES ('6c5c56c4-54bd-4487-b41e-103bb05493fa', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥系统', '由指挥主体、指挥对象、指挥手段等要素以一定组织形式构成的具有组织指挥功能的有机整体。', 39);
INSERT INTO `t_military_term_data` VALUES ('6c6ae308-f7a7-4ff2-b704-7808c6db8c9e', '916997ee-6728-4c61-9b79-d96960b1dc86', '喷火兵战术', '喷火兵进行战斗的方法。主要包括喷火兵战斗基本原则、兵力部署、战斗指挥、协同动作、战斗行动的方法及喷火油料的保障等。', 37);
INSERT INTO `t_military_term_data` VALUES ('6c6d677c-1d08-410d-8803-8e127e886d92', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上出击', '海上出航攻击的简称。海军舰艇出航、接敌并对敌实施攻击的行动要求隐蔽、迅速、果断。', 78);
INSERT INTO `t_military_term_data` VALUES ('6c71f9b1-a112-405c-9b33-b45b58214997', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '爆破作业', '按照工程设计说明或破坏计划实施爆破任务的作业。包括准备、装药、填塞、连接点火网路、点火、检查爆破效果等。', 245);
INSERT INTO `t_military_term_data` VALUES ('6c74e4cc-2722-49be-9c0e-47efa6e773e8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵触发射击', '炮兵应用触发引信使射弹触及目标或地面、水面后爆炸的射击。通常用以歼灭或压制掩体内的目标,破坏水中障碍物。', 188);
INSERT INTO `t_military_term_data` VALUES ('6c7994a5-92ed-4e0b-b10f-6960117596ce', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '梯队', '按执行任务及行动的先后顺序,对作战、行军的部队所划分的若干部分。通常每一部分为一个梯队。如第一梯队、第二梯队,先头梯队、后续梯队等。', 314);
INSERT INTO `t_military_term_data` VALUES ('6c87bf24-d81a-4d1f-85f5-97b48378a72e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '速战速决', '以快速作战行动歼敌,尽快结束战争或战役、战斗。', 248);
INSERT INTO `t_military_term_data` VALUES ('6c9f4eeb-7f5b-4aa6-91f5-512e1a3465a8', '916997ee-6728-4c61-9b79-d96960b1dc86', '干扰烟幕', '用以干扰敌红外、激光、微波等武器装备使用效能的烟幕。有干扰红外烟幕、干扰激光烟幕和干扰微波烟幕等。', 75);
INSERT INTO `t_military_term_data` VALUES ('6ca60736-b404-403c-9208-3c5272517c75', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '对抗训练', '两个以上的单位或人员互为对手进行的训练。如射击训练中,3个步兵班在相同条件下同时时规定的目标进行实弹射击比赛。战术训练中,两个排分别克当攻、防一方进行训练等。', 89);
INSERT INTO `t_military_term_data` VALUES ('6ca79c2e-4a6e-4932-80b9-2439e979c9f5', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '激光致盲式干扰', '通过发射强激光能量,使敌方光电设备的传感器、光学系统或战斗人员的眼睛受到损坏而不能正常工作的干扰。', 76);
INSERT INTO `t_military_term_data` VALUES ('6caa25e0-8509-4218-981b-07a9d2804e57', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军卫生勤务', '海军为其成员组织实施的卫生保健和伤病防治的专业勤务。', 351);
INSERT INTO `t_military_term_data` VALUES ('6cb0bcb3-891b-4de2-a120-81d88991ca92', '916997ee-6728-4c61-9b79-d96960b1dc86', '燃烧剂', '燃烧时能产生高温或炽热火焰,用于毁伤和纵火目的的化学物质。分为油基燃烧剂、金属燃烧剂、铝热燃烧剂、油基-金属燃烧剂及自燃燃烧剂等。', 233);
INSERT INTO `t_military_term_data` VALUES ('6cb1bf32-1fe7-4d4d-8654-c5b70956c04c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇系泊操纵', '操纵舰艇按照一定的程序和要求靠离指定泊位的技艺。包括靠离码头、系离浮筒（水鼓）、起抛锚等的操作。', 304);
INSERT INTO `t_military_term_data` VALUES ('6cb4e963-5941-4b49-898a-2381bac838a6', 'f0140091-c11a-48c9-8836-8aa94439dac0', '反坦克预备队展开地区', '反坦克预备队展开成战斗队形的地区。通常选择在受敌坦克严重威胁方向上便于发扬火力的位置。', 234);
INSERT INTO `t_military_term_data` VALUES ('6cbf6dd5-a7c3-4824-b132-2050a35a2e38', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '解冻', '水域固定冰盖融化、消失的现象。解冻时可产生冰层滑动和断裂,出现流冰。', 73);
INSERT INTO `t_military_term_data` VALUES ('6ccf553e-d1a9-4067-bf34-d1e48ddb90ee', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军船艇勤务', '陆军船艇的筹划、运用、管理、使用、维修和基地保障的专业勤务。基本任务是：不断提高陆军船艇保障能力,并运用船艇保障陆军水上交通、运输、侦察、巡逻和工程作业等任务的完成。', 324);
INSERT INTO `t_military_term_data` VALUES ('6cd1d3a7-529c-4d2c-be76-6e4362cd21ac', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电通信干扰站', '电子对抗部队中装备专用的无线电通信干扰设备,担负无线电通信干扰任务的机构。', 75);
INSERT INTO `t_military_term_data` VALUES ('6cd7fc1a-a06f-4049-8097-c52053fae789', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '主峰', '若干相邻的山顶中最高的山顶。', 13);
INSERT INTO `t_military_term_data` VALUES ('6cf0d222-62a1-48b9-b9e7-dfaace5ba94a', '98df76fb-4b65-48ff-a56c-4db587327c79', '立体保障', '利用陆地、空中、海上、水下、航天等多种保障手段,对处于各个作战空间的部队组织实施的后勤保障。是现代战争后勤保障的重要形式。', 32);
INSERT INTO `t_military_term_data` VALUES ('6cf64700-4bba-4c69-b5b9-1c02e0a68e7c', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战保障', '军队为顺利遂行作战任务而采取的各项保证性措施与进行的相应活动的统称。主要包括情报侦察、通信、三防、工程、电子防御、气象水文、测绘等保障。', 158);
INSERT INTO `t_military_term_data` VALUES ('6d0002f4-2aab-4fb3-aeba-c5a3c595f096', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '制式装备', '按照规定的标准和规格生产并列人军队装备体制的装备。', 80);
INSERT INTO `t_military_term_data` VALUES ('6d071e2c-372a-42ff-9822-a5a5c68edf6e', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军分区', '在地区、盟、自治州或地级市一级行政区域设立的军队一级组织。隶属于省军区。中国人民解放军的军分区同时是中国共产党地区、盟、自治州或地级市委员会的军事工作部门,并兼地区行政公署和盟、自治州、地级市政府的兵役工作机构,受省军区和地区、盟、自治州或地级市党委、政府的双重领导。设有领导机关。辖若干个人民武装部,有的还辖有一定数量的部队和分队。主要负责辖区内的民兵、预备役、兵役和动员工作,有的还担负边防、海防守备任务和所驻城市的警备勤务等。', 24);
INSERT INTO `t_military_term_data` VALUES ('6d0759cf-dd09-455a-8ffd-7ffa4db84c76', '8a761efd-50a6-4ac8-9913-b7d745104f82', '遮蔽界', '从射弹不能射穿的遮蔽物顶端到弹着点的一段距离。遮蔽物愈高、弹道愈低伸,遮蔽界愈大,反之则小。', 67);
INSERT INTO `t_military_term_data` VALUES ('6d114f11-5ff9-4f06-bf96-76c819701689', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '珊瑚礁海岸', '由珊瑚等生物残骸构成的海岸。是热带特有的海岸。不便于登陆作战。', 44);
INSERT INTO `t_military_term_data` VALUES ('6d1d5b78-8894-44dc-8cd2-27a2be3914af', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克火控计算机', '用以计算坦克炮射弹的弹道,并对坦克武器进行实时控制的计算机。是现代坦克火控系统的核心部分。', 120);
INSERT INTO `t_military_term_data` VALUES ('6d2f59f4-c5d2-481c-8ac6-6728bb0f5f2a', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军人职称', '军队中根据编制职务对各级各类人员的称谓。以军队编制规定的和任职命令所用的名称为准。', 99);
INSERT INTO `t_military_term_data` VALUES ('6d33570f-87b3-4762-807c-1731b2c817cc', '878651de-adf5-4c72-9376-9c363b893ff8', '战略作战', '为达成一定战略目的或对战争全局具有重大影响的作战。由统帅部或战区、战略集团按照一定的战略意图组织实施。', 106);
INSERT INTO `t_military_term_data` VALUES ('6d368310-6fcc-48ed-aee3-e126ac1c54b2', '8a761efd-50a6-4ac8-9913-b7d745104f82', '匕首', '狭长的锋刃短刀。', 154);
INSERT INTO `t_military_term_data` VALUES ('6d3e39fc-1910-4241-9906-e6beda8b5c60', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '海控点', '在国家大地点基础上布设和加密的供海道测量用的控制点。按精度,分为一、二、三级点和补充点。', 169);
INSERT INTO `t_military_term_data` VALUES ('6d4ec862-dff7-4124-93a9-379e5af74319', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗试验场', '专门用以在近似实战条件下进行电子对抗战术训练和对电子对抗设备进行试验、鉴定的场地。', 14);
INSERT INTO `t_military_term_data` VALUES ('6d563208-8ade-4f14-9c94-17f0a010b32f', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '探雷器', '以非接触方式发现地雷和地雷场的探雷器材。由探头、信号处理装置和报警装置组成。分为便携式探雷器（又称单兵探雷器）、车载式探雷器和机载式探雷器。', 170);
INSERT INTO `t_military_term_data` VALUES ('6d613b0c-9bca-4093-90a6-92b4963b40d9', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军队干部', '军队中担负排级或相当于排级职务以上的军人。通常指军官。中国人民解放军的干部中还包括文职下部。', 101);
INSERT INTO `t_military_term_data` VALUES ('6d795c4d-9c23-4741-bc1b-a58551f68104', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '会操', '集中部属并按指定的单位或人员对已训课目进行操演、通常适用于队列科目和某些技术科目。用以检验训练效果和互相观摩学习。', 172);
INSERT INTO `t_military_term_data` VALUES ('6d79fc46-2d99-4cde-93c7-436f0bc40c87', '06a75831-13a1-4660-870a-455bb445336a', '战役通信训练', '为提高组织实施战役通信的能力而进行的训练。主要内容包括：战役通信理论,战役通信系统及装备的组织运用,指挥自动化系统的建立与管理,通信部队的组织指挥,通信对抗,外军战役通信研究等。', 218);
INSERT INTO `t_military_term_data` VALUES ('6d8e8060-b321-4597-ac64-b40c1b284e9f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵连测战斗队形', '测定炮阵地和炮兵侦察分队各所、哨、站的位置,将其置于统一的坐标系统内,赋予并检查火炮与观测器材基准射向的作业。分为精密连测和简易连测。', 120);
INSERT INTO `t_military_term_data` VALUES ('6d9727af-b686-430e-b8b6-f941992623c2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '有生力量', '有生命的从事作战的力量。一般指军队中参加作战的人员。', 263);
INSERT INTO `t_military_term_data` VALUES ('6da49d10-865b-4973-97bf-899f7ab42a68', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵纵火射击', '炮兵发射纵火弹或燃烧火箭弹纵火,以焚毁敌军事设施、武器装备和其他易燃物体的射击。', 179);
INSERT INTO `t_military_term_data` VALUES ('6da89ddc-b895-4237-9278-98effa0eabea', 'd7132c58-5df3-4b97-919f-58740148b9ca', '空中目标运动参数', '能够确定空中目标速度向量的方向和大小的数值。通常包括航路捷径、航路角、航路方位角、升降角、目标速度、方位角改变速度、目标加速度等。是求解对空中目标射击诸元必须具备的基础数据。', 139);
INSERT INTO `t_military_term_data` VALUES ('6daaef03-c90a-4145-9d74-18b7a4fa6715', '8a761efd-50a6-4ac8-9913-b7d745104f82', '普通枪弹', '某种枪械根据其主要用途配备的数量最多的基本枪弹。步枪、轻机枪、重机枪的普通弹是钢铅结构弹丸的枪弹；大口径机枪的普通弹是装有硬钢心和燃烧剂弹丸的穿甲燃烧弹。', 198);
INSERT INTO `t_military_term_data` VALUES ('6dab3fff-b919-4b64-bd4a-815f7ca7d750', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '角反射器', '由三个或两个垂直相交的金属或其他导电材料平面构成的电波反射装置。按立体角数量,分为单角反射器、四角反射器和八角反射器；按形状,分为三角形、方形、圆弧形和混合形的角反射器；按结构形式,分为固定式、折叠式、装配式、充气式的角反射器等。通常能将入射电磁波按原入射方向反射回去。', 354);
INSERT INTO `t_military_term_data` VALUES ('6dbb1fa7-4041-4dfb-ab4b-419b76964d7d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '目测', '用眼睛估测距离、高度和角度的方法、通常在没有任何辅助仪器情况下采用。', 153);
INSERT INTO `t_military_term_data` VALUES ('6dbeb973-3f0a-45d5-83af-ec2733f353c4', '98df76fb-4b65-48ff-a56c-4db587327c79', '铁路运输军事管理', '战时由军队负责组织指挥的铁路运输管理。主要是采取适合于战时情况的管理体制、制度和办法组织铁路运输。通常由军队派出军事代表组织指挥,具体工作由铁路员工承担；对接近前沿或新占领地区的铁路,有时由受过专业训练的负责。', 258);
INSERT INTO `t_military_term_data` VALUES ('6dcfa6d9-14b8-4107-9925-314a8c5d6de5', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '保交支前', '民兵及人民群众保卫交通运输线以支援前线作战的活动。', 142);
INSERT INTO `t_military_term_data` VALUES ('6dcfd649-7417-4c7a-921b-47d5687499ef', 'f0140091-c11a-48c9-8836-8aa94439dac0', '突击队', '在强击群编成内或单独遂行强攻任务的战斗编组。兵力通常为互个加强排。', 171);
INSERT INTO `t_military_term_data` VALUES ('6ddc1fdb-8226-464c-886b-43917d0343a6', '8a761efd-50a6-4ac8-9913-b7d745104f82', '非致命轻武器', '发射、投掷非金属弹丸式喷洒液剂、汽雾,可使人畜伤痛,感官暂时障碍,肌体暂时失能的轻武器。主要用于防暴和维护社会治安。', 189);
INSERT INTO `t_military_term_data` VALUES ('6de9e55c-5006-4b9f-80a3-2c45a316cfca', '8a761efd-50a6-4ac8-9913-b7d745104f82', '高低角', '瞄准线与火身口水平面的夹角。目标高于火身口水平面时, 高低角为正；目标低于火身口水平面时,高低角为负。', 12);
INSERT INTO `t_military_term_data` VALUES ('6dea6eb0-2ed6-4a44-85a6-7c61997fc2ec', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵试射', '为获得对目标的效力射开始诸元或对试射点的试射成果诸元而用少量的炮弹进行的射击。按试射对象,分为对目标试射和对试射点试射；按试射方法,分为交叉法试射、偏差法试射、方向比法试射等。', 149);
INSERT INTO `t_military_term_data` VALUES ('6df8c3e0-f380-466f-abbc-ad0845098cc8', 'f0140091-c11a-48c9-8836-8aa94439dac0', '进攻发起', '亦称战斗发起。进攻战斗实施的开始。通常以火力准备或火力急袭的开始为起点。进攻发起的方式,主要有从行进间发起进攻和从进攻出发阵地发起进攻。', 156);
INSERT INTO `t_military_term_data` VALUES ('6e0241ba-1061-4236-a0db-a3ae8ab7b361', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵利用声测手段射击', '炮兵利用声测手段决定目标位置、测定炸点偏差量实施的射击、使用声测手段实施射击不易被敌发现,但受风速、气温和炮兵射击猛烈程度等因素的影响。', 200);
INSERT INTO `t_military_term_data` VALUES ('6e0e67d8-4c68-422b-8443-0d0a40ec3d6f', '8a761efd-50a6-4ac8-9913-b7d745104f82', '激光枪', '发射激光束毁伤目标的手提式装置。可使生动目标致盲或致伤。射击时不需提前量，射程可达千米。', 177);
INSERT INTO `t_military_term_data` VALUES ('6e0f913f-c005-4b49-b2fa-d98dddaf43da', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '感生放射性弹', '利用核爆炸释放的中子照射某些添加的核素,感生大量半衰期较长的放射性同位素,从而增强放射性沾染的特殊性能核武器。添加钻-59的称钻弹,添加锌-64的称锌弹。', 98);
INSERT INTO `t_military_term_data` VALUES ('6e1d29ae-8b74-421e-b837-4189e5e0290e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克大修间隔期', '亦称坦克大修期。坦克从新车启用到大修或两次大修之间的实际使用时间或行驶里程。', 208);
INSERT INTO `t_military_term_data` VALUES ('6e23b6f3-9232-4ca0-a4db-27bafeb6be85', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆水上推进装置', '将传动装置传来的动力通过与水的相互作用转变为推力,保障装甲车辆水上行驶的装置。分为划水式、喷水式和螺旋桨式。', 129);
INSERT INTO `t_military_term_data` VALUES ('6e33df85-52aa-4705-ab00-874be53de969', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮射弹起点', '发射药气体对射弹作用结束时，射弹底部脱离炮口瞬间其重心所在的位置。通常把火炮瞄准以后的炮口十字线交点的位置作为起点。', 246);
INSERT INTO `t_military_term_data` VALUES ('6e459f1e-0ac3-4ffa-a3c6-fc6c9a3286cd', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舷号', '标示在舰艇两舷的序号。通常用数字或代字加数字表示。小型舰艇和勤务舰船通常没有舰名,只使用舷号。', 127);
INSERT INTO `t_military_term_data` VALUES ('6e4cc212-66c8-431b-acd8-7533cf1f6ae1', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '用炮', '将火炮由行军状态转换为战斗状态的过程。', 269);
INSERT INTO `t_military_term_data` VALUES ('6e69fe0b-fbd4-4d7c-be43-2fa6fd1bd3fe', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '漕渡', '用门桥、两栖车辆、舟和筏等浮游结构物渡送军队人员和物资过江河的行动。', 303);
INSERT INTO `t_military_term_data` VALUES ('6e7a3ebf-2318-40c9-88b0-87b072fef9ca', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵专业技术兵', '从事专业技术工作,并能使用相应专业技术装备的民兵。其分类一般与军队的专业技术兵分类保持一致,以满足平时训练和战时对口动员的需要。', 131);
INSERT INTO `t_military_term_data` VALUES ('6e7bcbe3-e0f7-4980-b8fb-4bd596a17006', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '装甲工程车', '亦称战斗工程车。装有防护装甲的多用途野战工程机械。主要用于：伴随坦克等装甲车辆行动,担负敌火下开辟通路,抢修军用道路,构筑坦克、火炮掩体等。', 377);
INSERT INTO `t_military_term_data` VALUES ('6e87537f-415e-4baa-a41f-08cc2bf6a8e2', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '示范性演习', '演示正确的组织指挥方法和战斗行动,供见学人员观摩的军事演习。多用于战术范围。', 112);
INSERT INTO `t_military_term_data` VALUES ('6e913e1f-259e-44ae-a0d1-d973cf4058be', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '掩护地带', '未与敌直接接触情况下组织防御时,在第一防御地带前设置的由掩护部队占领的地带。通常用以进一步查明敌情,制止和破坏敌人侦察,迫敌过早展开,杀伤、消耗、迟滞敌人,为主力部队防守创造有利条件。', 130);
INSERT INTO `t_military_term_data` VALUES ('6e916b2a-9e8b-4589-8938-de567a707c25', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '游击战战役', '以游击战为主要作战形式的战役。通常在敌人的翼侧或后方实施,以配合主要战场或主要方向的作战。', 64);
INSERT INTO `t_military_term_data` VALUES ('6e9309fb-65d9-4af2-ae25-73db3e916ed4', '98df76fb-4b65-48ff-a56c-4db587327c79', '伙食标准', '对军人膳食消费水平所作的统一规定、包括对不同类区、不同灶别的食物、炊事燃料定量和相应的经费数量以及享用人员的规定。是部队组织实施饮食保障的主要依据。', 141);
INSERT INTO `t_military_term_data` VALUES ('6e981f49-87cb-4276-bb98-7ec33d820fae', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战斗原则', '亦称战术原则。战斗行动所依据的法则或标准。', 29);
INSERT INTO `t_military_term_data` VALUES ('6eae108e-5aab-4161-8fbf-29e8e6859a17', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战术分段作业', '亦称战术队列作业。逐段地讲解、示范和演练某个战术课题。一般用于分队战术训练。', 94);
INSERT INTO `t_military_term_data` VALUES ('6eae2ede-b58d-4f9c-8691-1b3afa16f765', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '整编', '对军队的体制、编制进行调整。包括改变组织结构、编配数量和比例等。', 74);
INSERT INTO `t_military_term_data` VALUES ('6eb02391-9a36-428d-a23e-8a96e374e60f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '地地战役战术导弹部队', '以地地战役战术导弹为基本装备,在战役、战术范围内压制和破坏地面和水面目标的炮兵部队。一般配置在战役纵深内,由战役军团指挥员直接掌握使用。', 1);
INSERT INTO `t_military_term_data` VALUES ('6eb14f7c-458a-4e59-8002-06cd73fab3cd', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹检测', '为保证导弹经常处于良好状态,对导弹的技术状态和性能进行的检查测试。分为经常性检测、定期检测和特种检测。', 201);
INSERT INTO `t_military_term_data` VALUES ('6eb924b5-e3f9-40e4-a061-d6ba338d16dd', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '蛙跳战术', '直升机以分段前进、分段起降的方式超越障碍对敌进行战斗的方法。可用以避开敌方火力,发挥自身火力。', 71);
INSERT INTO `t_military_term_data` VALUES ('6ec95ae7-7630-439e-b1d3-78ab83a9f06d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '火力', '弹药经发射、投掷或引爆后所产生的杀伤力和破坏力。通常分为常规火力和核火力。', 258);
INSERT INTO `t_military_term_data` VALUES ('6eca1b6c-abbc-41e6-9f07-63743221efd9', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高射炮兵', '以高射炮为主要装备,遂行地面防空作战任务的防空兵。主要担负保障国家要地、军队和重要物体对空安全的任务,必要时也可逆行对地面和水面目标射击任务。', 3);
INSERT INTO `t_military_term_data` VALUES ('6ede15e5-04ae-4519-bd01-46129d79c145', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '平行射向', '炮兵连内各门火炮的射向互相平行所构成的射击方向。在目标正面概略等于或稍大了阵地放列正面,且各炮间隔概略相等时使用。炮兵连占领炮阵地时一般构成平行射向。', 212);
INSERT INTO `t_military_term_data` VALUES ('6ef5e5a9-4364-41f2-9e67-596eb66ea5e8', '8a761efd-50a6-4ac8-9913-b7d745104f82', '底缘拉脱', '已射击武器在发射过程中弹壳底缘局部被拉壳钩拉掉的射击故障。', 144);
INSERT INTO `t_military_term_data` VALUES ('6efe124f-f87c-4b30-8f16-3f51d545f313', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮弹引信', '弹丸上的引爆装置。分触发引信、时间引信、感应引信和多选择引信等。射击时根据弹种和完成任务的要求,选择使用不同的引信。', 330);
INSERT INTO `t_military_term_data` VALUES ('6f03141d-8ff7-4e36-b0eb-fae2440cc333', '916997ee-6728-4c61-9b79-d96960b1dc86', '神经性毒剂', '亦称含磷毒剂。以损害神经系统为主要毒害特征的毒剂。如沙林、梭曼、维埃克斯等。施放后呈蒸气、气溶胶和液滴状。经呼吸道、皮肤、消化道等途径使人员中毒,出现缩瞳、流涎、呕吐、痉挛、呼吸困难、中枢神经麻痹等症状,严重者死亡。', 211);
INSERT INTO `t_military_term_data` VALUES ('6f271663-b9e9-4b43-8798-f3ee0bd6ddf4', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '固体火箭发动机', '使用固体推进剂的化学火箭发动机。', 36);
INSERT INTO `t_military_term_data` VALUES ('6f4673e8-5057-495b-94ff-3949d553cc46', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '部队', '①团及团以上建制单位的统称。②军队的一部分。如北京部队、炮兵部队、空军部队等。③泛指军队。', 42);
INSERT INTO `t_military_term_data` VALUES ('6f65c74c-6b83-4392-9882-d6ba0cb15ad0', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '合成孔径雷达', '利用雷达与目标的相对运动,通过信号处理的方法将真实的小孔径天线合成为较大等效孔径天线的成像雷达。具有分辨力高、数据量大,能全天候工作、识别伪装和穿透掩盖物能力强等特点。通常装载在飞机或航天器上。主要用于侦察、测绘和图像匹配制导等方面。', 95);
INSERT INTO `t_military_term_data` VALUES ('6f7b0fc2-139e-4fe0-b239-075ff0767728', '916997ee-6728-4c61-9b79-d96960b1dc86', '植物杀伤剂', '军事上用以引起植物枝叶凋落、不育甚至枯死的化学药剂。包括除草剂、落叶剂、干枯剂和土壤不孕剂等。可毁坏农作物、林带和灌木丛等绿色植被。', 228);
INSERT INTO `t_military_term_data` VALUES ('6f91806d-ce0e-4d29-88c4-3cd48ecda759', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '重建', '按原番号重新组建已撤销的或在作战中失去战斗力的部队。', 78);
INSERT INTO `t_military_term_data` VALUES ('6f996def-39f6-4095-89ef-0e911923d4a5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '低阻力炮弹', '弹体外形细长如枣核,弹体无圆柱部,飞行阻力比普通炮弹小的炮弹。', 319);
INSERT INTO `t_military_term_data` VALUES ('6f9e8312-a3d7-4fd7-9ef4-0ea9ad1e2f7a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '翼侧', '军队的作战部署、行军队形、战斗队形或阵地的左右两侧。', 282);
INSERT INTO `t_military_term_data` VALUES ('6fa2621b-a1b4-4b86-9cef-ce0fa96b41e1', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方医院', '配置在战役、战略后方的固定性医院。主要负责对伤病员实施专科治疗和康复治疗。', 215);
INSERT INTO `t_military_term_data` VALUES ('6fb70b02-7bc3-48b7-af30-24ede0267e33', 'f0140091-c11a-48c9-8836-8aa94439dac0', '侧击', '向敌部署的翼侧实施的攻击。可从敌之一侧或两侧进行。', 159);
INSERT INTO `t_military_term_data` VALUES ('6fc51add-b1a5-4a96-9fb8-d403f669178c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵仪器侦察', '炮兵使用各种侦察测量仪器和器材进行的侦察。主要包括使用光学器材、声测器材、雷达、无线电技术器材、照相器材、电视等进行的侦察。', 109);
INSERT INTO `t_military_term_data` VALUES ('6fce736c-991f-4617-b962-fd0bbcf96a98', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克烟幕装置', '坦克上的烟幕器材以及相应装置的统称。分为抛射式烟幕装置、热烟幕装置和烟幕筒3种。', 139);
INSERT INTO `t_military_term_data` VALUES ('6fd0c9fa-e122-4a5a-ab45-249696a56b4b', '98df76fb-4b65-48ff-a56c-4db587327c79', '摩托小时', '车辆发动机工作时间的计算单位。车辆发动机工作1小时,为1个摩托小时。用以计算车辆的使用、保养、修理、驾驶员训练等的期限和燃料、润滑油料的消耗数量。', 308);
INSERT INTO `t_military_term_data` VALUES ('6fdc74ce-33bd-4485-9bd5-d2ef433437d2', '98df76fb-4b65-48ff-a56c-4db587327c79', '就地筹措', '军队在作战地区或驻地内向地方筹集、获取所需物资的后勤保障行动。就地筹措的物资主要是军民通用的给养、燃料、建筑材料和日用品等。', 96);
INSERT INTO `t_military_term_data` VALUES ('6fe0d865-dba9-4926-8e28-4b5b20652f15', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '近程导弹', '射程为 1000公里以下的导弹。', 8);
INSERT INTO `t_military_term_data` VALUES ('6fe37266-a4f3-4e01-b72a-3c1648897dd0', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲输送车', '主要用以输送步兵,并可以火力支援下车步兵战斗的装甲战斗车辆。分为履带式和轮式两种。', 96);
INSERT INTO `t_military_term_data` VALUES ('700788e6-880a-41d5-90cd-5fe095cdbf50', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲抢修车', '装有抢修机具和器材的装甲保障车辆。主要用于野战条件下对装甲车辆实施现地快速修理。', 102);
INSERT INTO `t_military_term_data` VALUES ('700c1991-cf1c-4ce4-bdad-062edf99cbef', '916997ee-6728-4c61-9b79-d96960b1dc86', '防毒通道', '工事中两道相邻密闭门或防护密闭门与密闭门之间的通道。其作用是利用通道的通风设施,排出人员进出工事时带入通道的受染空气。', 183);
INSERT INTO `t_military_term_data` VALUES ('701946c9-3865-42db-a0b1-8161988d6a1f', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '补训', '对漏训人员、漏训课目或考核不及格者进行的补课性训练。', 177);
INSERT INTO `t_military_term_data` VALUES ('701fafc7-cf1d-4664-9634-9e5d3bd8d7e7', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '试射成果高角', '试射结束时所获得的炮目高角或炮试高角。是当时射击条件不能使射弹散布中心通过目标或试射点在炮口水平面上的投影点的高角。其值等于成果射角与高低修正量之差。', 158);
INSERT INTO `t_military_term_data` VALUES ('702662e6-6903-4d67-b254-3e3c2e2212b4', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '梯恩梯当量', '用释放相同能量的梯恩梯（TNT）炸药的质量表示核爆炸能量的一种习惯计量。通常用吨梯恩梯当量作为计量单位。', 90);
INSERT INTO `t_military_term_data` VALUES ('702fcb13-2704-41f4-bd70-efca46593440', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '风暴潮', '亦称气象海啸。由台风（飓风或热带风暴）、温带气旋、冷锋等天气系统产生的强风或气压骤变,引起海面异常升降的现象。通常分为温带风暴潮和热带风暴潮两类。', 133);
INSERT INTO `t_military_term_data` VALUES ('7031232d-ce04-4fcf-878b-a22caca8ba2d', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹装定射程', '将经过各种修正的与射程相对应的物理量或程序装定在导弹射程控制系统的过程。主要是赋予导弹的射程。', 103);
INSERT INTO `t_military_term_data` VALUES ('703ac2b1-b5d3-4b0e-b28f-3280d70b381b', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '搜索组', '担任复杂和可疑地域搜查任务的小组。兵力一般不大于1个班。', 18);
INSERT INTO `t_military_term_data` VALUES ('703f49ab-b5b7-45c6-8c01-678e9cbc11a5', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克机动抢救修理组', '坦克部队战时组织的临时性机动技术保障机构。隶属于坦克抢修所。由修理分队部分人员组成。用以执行临时赋予的抢救、抢修任务和接替失去保障能力的坦克技术保障组的工作。', 230);
INSERT INTO `t_military_term_data` VALUES ('7046c902-3037-49af-a6a4-5dd0899a205f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵对水面目标射击', '炮兵对敌舰船、登陆工具和水中障碍物等实施的射击、水面视界广阔、便于侦察、发现目标,但方位物少,气象、水义多变,目标经常在运动,射击指挥较为复杂。', 195);
INSERT INTO `t_military_term_data` VALUES ('704d9f72-004a-481d-b8cb-93e39917a57c', 'd7132c58-5df3-4b97-919f-58740148b9ca', '对空中目标侦察', '简称对空侦察。防空兵为获取空中情报而进行的侦察。主要包括：组织收听空情报知,雷达侦察,对空观察哨侦察,防空兵指挥所观察和阵地观察。', 111);
INSERT INTO `t_military_term_data` VALUES ('70519881-36d9-43dd-b0d3-33fab08d58d3', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵航空侦察', '炮兵利用飞行器从空中对地面实施的侦察。一般由集团军、师炮兵指挥机关组织实施。航空侦察能在较短时间内。获得较大纵深内的敌情、地形等资料，但易受天气、能见度的影响和敌方防空火力的威胁。', 113);
INSERT INTO `t_military_term_data` VALUES ('70565608-dedd-4d78-bc8a-489edcca1842', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程伪装', '用伪装器材和工程技术手段实施的人工伪装。分为植物伪装、迷彩伪装、遮障伪装、假目标伪装、灯火伪装和音响伪装等。', 334);
INSERT INTO `t_military_term_data` VALUES ('7068a5dc-c8c3-4280-8de6-7a7c6df361dc', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '人造地球卫星', '简称人造卫星。在空间轨道上环绕地球运行（不少于一圈）的无人航天器。分为科学卫星、技术试验卫星和应用卫星。', 204);
INSERT INTO `t_military_term_data` VALUES ('706cf052-851c-4ab0-abf9-8a92f07275db', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军人职责', '按其职务应担负的责任。包括士兵职责、军官职责,首长职责、主管人员职责等。一般由内务条令和其他规范性文件规定。', 8);
INSERT INTO `t_military_term_data` VALUES ('706d66b3-da08-4450-a8f1-0b12308026f3', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '夜间', '天黑后到天亮前的一段时间。可见月亮时称为明夜,不见月亮时称为暗夜。', 151);
INSERT INTO `t_military_term_data` VALUES ('708b6798-3121-4f83-805d-018e6d9aca91', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队体工队', '中国人民解放军培养训练运动员的专业组织。', 116);
INSERT INTO `t_military_term_data` VALUES ('709cf790-cc87-41ed-8df0-73e785e69372', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军礼炮', '舰艇或军港炮台鸣放空包弹或专用礼炮弹的海军礼仪。分为国家礼炮（21响）和个人礼炮（通常为11～21响单数）。主要用于外事活动,以表示敬意、欢迎或答谢。', 404);
INSERT INTO `t_military_term_data` VALUES ('70ac4906-fdd6-4258-b14a-907fc723e2b7', '916997ee-6728-4c61-9b79-d96960b1dc86', '消除剂', '用以清除放射性物质的洗消剂。有洗涤剂、络合剂等。', 188);
INSERT INTO `t_military_term_data` VALUES ('70b1e53e-f04d-450d-b6c2-861d084e2b38', '916997ee-6728-4c61-9b79-d96960b1dc86', '放射性沾染测量仪', '测定核辐射发射体放射性活度的核辐射剂量探测仪器。主要用以测量各种受染对象样品的放射性活度,确定人体和各种物体表面的沾染水平以及空气、水等受沾染的浓度与粮食、蔬菜的沾染比活度。', 160);
INSERT INTO `t_military_term_data` VALUES ('70d546dd-9db8-4ef3-b71a-50a154b8b204', '97a19170-bfac-42c5-9906-1acb187f0654', '对空指挥', '地面指挥人员对空中飞机或直升机的各种飞行活动实施的指挥。', 185);
INSERT INTO `t_military_term_data` VALUES ('70d7b678-2636-4579-9f2c-82ec971eac33', '97a19170-bfac-42c5-9906-1acb187f0654', '空中突击队', '机群中担负空中攻击作战主要任务的空中编队。通常在空中掩护队与空中保障队的配合下行动。', 49);
INSERT INTO `t_military_term_data` VALUES ('70d85808-668c-4ee1-96b1-f93f667c7bb1', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克', '具有较强的火力、机动力和装甲防护力，主要用于地面突击的履带式装甲战斗车辆。由武器系统、推进系统。防护系统、通信设备、电气设备以及其他特种设备和装置组成。乘员一般为3～4人。按用途,分为主战坦克和特种坦克。20世纪60年代以前,还按战斗全重和火炮口径,分为轻型坦克、中型坦克和重型坦克。', 86);
INSERT INTO `t_military_term_data` VALUES ('70d8c556-96a7-48d7-bb4b-030bc0c32c2e', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电通信干扰', '削弱或破坏敌方无线电通信效能的电子干扰。按干扰性质,分为压制性通信干扰和欺骗性通信干扰。欺骗性通信干扰亦称通信欺骗。', 54);
INSERT INTO `t_military_term_data` VALUES ('70d9f959-27ed-4b9b-a23d-e594cd5ff264', '916997ee-6728-4c61-9b79-d96960b1dc86', '梭曼', '学名甲氟磷酸特己酯。神经性毒剂的一种。可装填在炮弹、航空炸弹、地雷、航空布洒器中使用。主要通过呼吸道和皮肤侵入机体,使人畜中毒。', 213);
INSERT INTO `t_military_term_data` VALUES ('70faedb4-7172-4b9a-9faa-b2540fa57d43', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰机协同', '水面舰艇与飞机或直升机为遂行共同的作战任务而进行的协调配合。', 59);
INSERT INTO `t_military_term_data` VALUES ('70fc4b0d-7034-474c-b614-eab4127d3d0d', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '管理教育', '按照军队建设的宗旨、要求和规章制度,结合战备、训练和其他工作以及日常生活与各种勤务活动所进行的行政管理与思想教育工作。严格管理教育,是巩固和提高部队战斗力的重要方面。', 1);
INSERT INTO `t_military_term_data` VALUES ('710021ae-ddfd-45d9-832d-212252272024', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程机械技术保障', '为保持军用工程机械的战术技术性能而在技术方面进行的保障。包括对军用工程机械的保养、修理、检查、鉴定等。', 380);
INSERT INTO `t_military_term_data` VALUES ('7102f15e-55a7-4fe3-9d4d-0c2ec6c76ba5', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射阵地', '导弹发射分队对导弹进行发射准备和实施发射的阵地。分为地面发射阵地、地下发射阵地和半地下发射阵地。通常由发射场坪或发射井及有关设施等组成。', 45);
INSERT INTO `t_military_term_data` VALUES ('7117cdd5-01c6-40fe-81f6-5e48aa11e552', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射向', '同一炮阵地上的数门火炮对同一目标射击时,各炮身轴线铅垂面构成的具有一定相互关系的射击方向。主要有集火射向、适宽射向和平行射向。炮兵射向通常以炮兵连为单位构成。单个火炮射击时指炮身轴线沿垂面所指的射。射击方向。', 203);
INSERT INTO `t_military_term_data` VALUES ('71185f97-a8ca-4a4a-9366-50f2fa23f1e7', '83e065b4-6737-4645-9ea5-8276d1de13ed', '车辆导航装置', '用以在运动中随时确定车辆的方向和位置，并引导车辆行驶到指定地点的装置。由陀螺罗盘及指示器、纬度校正仪、里程表、计算器等组成。', 148);
INSERT INTO `t_military_term_data` VALUES ('713380fe-08eb-49e3-a6d4-730ab13ab23e', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电通信对抗', '简称通信对抗。为削弱、破坏敌方无线电通信设备的使用效能,保护己方无线电通信设备正常发挥效能而采取的各种措施和行动的统称。基本内容包括通信对抗侦察、通信干扰和通信电子防御等。', 2);
INSERT INTO `t_military_term_data` VALUES ('7133eb5b-ab9f-4d35-be09-5664adea153e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '起爆', '亦称点火。在外界能量作用下引起炸药爆炸的过程。', 234);
INSERT INTO `t_military_term_data` VALUES ('71373b56-ec18-4583-9727-ef7e7f58ffc8', '97a19170-bfac-42c5-9906-1acb187f0654', '战斗返航', '飞机或直升机退出战斗后返回着陆机场的飞行。', 53);
INSERT INTO `t_military_term_data` VALUES ('713a39ad-0f08-4350-947d-2c6b5763497c', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战斗间隙', '两次战斗之间或一次战斗过程中的间歇时间。可用以调整部署,整顿组织,补充弹药、给养,恢复和增强战斗力。', 20);
INSERT INTO `t_military_term_data` VALUES ('7144021d-ba83-4c8f-8e23-d28898ceab5f', '8a761efd-50a6-4ac8-9913-b7d745104f82', '法线', '通过目标上某点并垂直于目标表面的直线。', 40);
INSERT INTO `t_military_term_data` VALUES ('71466c9e-e278-4cc1-aeb6-69530025ff8f', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '高水桥', '上部结构下缘高出江河常年洪水位的军用桥梁。洪水、流冰和小型船只可从桥下通过。多用作后方桥。', 275);
INSERT INTO `t_military_term_data` VALUES ('714c8558-141c-40f6-b18e-a76fdbb168e2', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗兵群', '电子对抗部队战时遂行电子对抗作战任务的战斗编组。通常编为基本群和前方群,有时还编有后方群。', 6);
INSERT INTO `t_military_term_data` VALUES ('715106cd-8ca1-4763-98e0-7ba929a4c524', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '军队院校教育', '军队院校有目的。有计划地培训各级各类军官和专业技术人才的活动。通常包括指挥院校教育和专业技术院校教育。', 64);
INSERT INTO `t_military_term_data` VALUES ('7156c9e6-5861-4508-ab07-5952f95a88ef', '916997ee-6728-4c61-9b79-d96960b1dc86', '污染区', '染有生物战剂并对军队和居民构成危害的区域。其范围取决于生物战剂施放方式、生物战剂的种类和数量,以及风向和风速等因素。', 146);
INSERT INTO `t_military_term_data` VALUES ('71604c9c-4e9d-404f-bcfd-ed115abb3d86', '8a761efd-50a6-4ac8-9913-b7d745104f82', '禁射界', '为保证自身和友邻安全面规定的武器不能超越的高低射界或方向射界。', 88);
INSERT INTO `t_military_term_data` VALUES ('71630ad6-7fe3-472a-a09b-4561d96a53f8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '假炮阵地', '为欺骗、迷惑敌人而模拟设置的炮阵地。', 63);
INSERT INTO `t_military_term_data` VALUES ('7171a109-9bf7-4688-b532-09d3364b8523', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防体制', '国家为进行国防建设和斗争而确定的组织体系及相应制度。主要包括国防领导体制、武装力量体制、国防动员体制、国防经济体制、国防科技与武器装备发展体制等。', 10);
INSERT INTO `t_military_term_data` VALUES ('717ac8ec-38b4-49f4-8022-358b860f95b3', '97a19170-bfac-42c5-9906-1acb187f0654', '外场飞行保障指挥室', '机场场站向机场飞行现场派出的保障航空兵飞行的指挥机构。通常由场站首长、参谋人员和其他有关人员组成,在机场飞行指挥员的统一指挥下,具体组织飞行的后勤保障和通信、气象等保障工作。', 434);
INSERT INTO `t_military_term_data` VALUES ('717ccdad-d020-4696-b60a-cfb59d53e333', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵基本观察所', '炮兵观察配系中起主导作用的观察所。通常由作训、侦察部门的人员和指挥分队组成。', 90);
INSERT INTO `t_military_term_data` VALUES ('7182bc6a-f92d-4766-b74a-6756dd02df82', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化侦察分队', '担负化学观察、化学和辐射侦察、沾染检查任务的防化分队。主要负责查明部队行进路线、配置地域及重要目标的受染情况。', 3);
INSERT INTO `t_military_term_data` VALUES ('719b27a3-1140-4b0f-aeef-e0042b0e6e11', 'd7132c58-5df3-4b97-919f-58740148b9ca', '据筒', '将便携式地空导弹武器系统由行军状态转为战斗状态的行动过程。', 213);
INSERT INTO `t_military_term_data` VALUES ('71a20aae-4ed9-4d88-88a7-eb7954fb9b31', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气候带', '根据气候要素的分布特征而划分的大致呈纬向的地带。按照一定的标准,通常将全球气候按南、北半球分别从高纬度到低纬度划分为6个气候带：极地带（90～65度）、寒带（65～55度）、温带（55～35度）、副热带（35～25度）、热带（25～10度）和赤道带（10～0度）。', 55);
INSERT INTO `t_military_term_data` VALUES ('71a40781-0b1f-4c53-8e4a-f15d91ace895', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵前进观察射击', '由炮兵前进观察所实施观察和指挥的射击。通常在为改善观察条件和密切步炮、坦炮协同时采用。', 171);
INSERT INTO `t_military_term_data` VALUES ('71acf2e1-0533-481f-bf9e-6f407014887c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '机械化桥', '由专用基础车载运、并用该车上的机械装置架设和撤收的成套多跨式制式桥梁器材。分为重型机械化桥和轻型机械化桥。机动性能好,架设作业机械化程度高。', 282);
INSERT INTO `t_military_term_data` VALUES ('71b0d493-ee63-414e-bc96-7288cb0c1221', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '浮桥长', '在渡场长领导下负责一座浮桥架设。维护和分解作业的指挥员。通常由架设浮桥的舟桥部队或分队指挥员担任。', 323);
INSERT INTO `t_military_term_data` VALUES ('71c5d605-f77b-46d5-b7d1-828a9ef616a6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '前导舰', '舰艇编队航行时位于编队队形或队列最前面的舰。', 261);
INSERT INTO `t_military_term_data` VALUES ('71c72ac7-35a7-44ae-ba98-14f5221fe75a', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹待机阵地', '导弹部队实施机动作战时,在进入作战阵地前进行隐蔽待命的阵地。有时也指撤出作战阵地后临时占领的阵地。通常构筑有防护工程,可对导弹在水平状态下进行补充测试、检查。', 46);
INSERT INTO `t_military_term_data` VALUES ('71ce071b-a866-4726-b98c-c49629f1be7c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '左（右）翼舰', '舰艇编队航行队形或队列中,位于某舰左（右）侧的所有舰。', 265);
INSERT INTO `t_military_term_data` VALUES ('71d0c159-902c-426e-a141-2b0b046d35ae', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '高原气候', '高海拔高原地区的气候。主要特征是：太阳直接辐射（尤其紫外辐射）强、光照多、昼夜温差大,风力强且日变化大,多雷暴、冰雹,地形对气候影响明显。', 59);
INSERT INTO `t_military_term_data` VALUES ('71d19c26-8fe1-49e7-ac77-b5a120d298d7', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '军事体育训练', '具有军事实用价值的身体素质训练。共同科目训练内容之一,是技术战术训练的基础。主要内容包括：徒手体操、军体拳、器械体操,通过障碍、越野、爬山、攀登,游泳,田径等。', 73);
INSERT INTO `t_military_term_data` VALUES ('71eb34b1-5175-4705-a6ee-9491753ddd4e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵气象勤务', '炮兵气象分队进行的气象探测和资料处理的勤务。目的是获取火炮射击和不测侦察所需的气象资料。', 121);
INSERT INTO `t_military_term_data` VALUES ('71ed1555-c132-4231-9e1c-a08a79fa65ec', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '热带雨林', '热带或亚热带暖热湿润地区,由高大常绿阔叶树构成的有繁密林冠,多层结构,并有木质藤本和附生植物的森林。其内部各种植物生长茂密,通行十分困难。', 90);
INSERT INTO `t_military_term_data` VALUES ('71f4b6a1-9bb7-43d9-9f22-92a1aad69c59', 'f0140091-c11a-48c9-8836-8aa94439dac0', '登陆地域', '登陆地区内师一级登陆部队登陆和发展岸上进攻的地域。包括敌岸上部分及其临近水域。在登陆地域内,通常含有数个登陆地段。', 137);
INSERT INTO `t_military_term_data` VALUES ('72020a3c-6fc8-4558-8695-4c72ec99730d', '916997ee-6728-4c61-9b79-d96960b1dc86', '剂量监督', '对人员受核辐射伤害情况的检查和控制。用以及时掌握部队受核辐射照射情况,控制人员的吸收剂量。', 45);
INSERT INTO `t_military_term_data` VALUES ('7206c6f9-79bb-4dfd-8d13-c2c87c32abc6', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '军事水文', '①影响军事活动的海洋和陆地的水文环境状况。②研究海洋和陆地水文环境对战争和其他军事活动影响的规律,以及实施军事水文保障的理论与方法的学科。', 108);
INSERT INTO `t_military_term_data` VALUES ('7207e1ad-b71b-4927-925f-bd9586127c7f', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '抗击反突击', '进攻战役中击退或歼灭反突击之敌的作战行动。用以继续发展进攻。', 115);
INSERT INTO `t_military_term_data` VALUES ('720b7d03-63df-44cf-9aff-48f4493a577a', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军船艇管理', '对陆军船艇实施的业务管理、技术管理和行政管理的统称。是陆军船艇勤务的组成部分。目的是达到并保持船艇组织的整体性、人员行动的一致性和装备的可靠性。', 332);
INSERT INTO `t_military_term_data` VALUES ('721363ff-ef8e-4f3e-b23c-75fdbaaba62d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵跟进掩护', '防空兵分队编在被掩护部队行军纵队中实施的对空掩护。可采用行进间射击、短停射击或临时放列射击等方法实施。', 79);
INSERT INTO `t_military_term_data` VALUES ('721f8ca9-f088-4a72-b8c5-1ef29039c661', '878651de-adf5-4c72-9376-9c363b893ff8', '战略武器', '由统帅部直接掌握的专门用以打击敌战略目标并具有强大威慑作用的武器。如战略导弹、战略轰炸机、导弹核潜艇等。', 95);
INSERT INTO `t_military_term_data` VALUES ('72251de5-58c1-49df-9eb7-ab5bdaf24182', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '直升机平台起降', '直升机在高于水面或地面的有限场地上进行的起飞和降落。分为固定平台起降和活动平台起降。平台上设有明显的识别标志,并有助航、照明、系留和助降等设备。', 309);
INSERT INTO `t_military_term_data` VALUES ('7225c8db-f446-4e93-9dec-73b8e52e9ae9', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克渡河', '坦克以各种手段和方法通过江河障碍的行动。包括潜渡、徒涉、浮渡和门桥渡河、冰上渡河等。', 60);
INSERT INTO `t_military_term_data` VALUES ('72285890-dbfa-4d7c-8354-a7df4953bb34', '97a19170-bfac-42c5-9906-1acb187f0654', '战伤飞机（直升机）抢修', '对遭受战斗损伤的飞机或直升机在战场范围内进行的快速修理。主要是修复其结构损伤,使其在短时间内恢复到可以执行任务的技术状态。', 451);
INSERT INTO `t_military_term_data` VALUES ('722cd3fd-23aa-4d1c-b563-dee0f9b5cfdc', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练指示', '部署和指导军事训工作的文件。通常有年度训练指示、阶段训练指示、补充训练指示和专题训练指示等。', 41);
INSERT INTO `t_military_term_data` VALUES ('722e6377-9449-4a7f-91a6-2e31dce66aff', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆监理', '军队有关业务部门对军用车辆和驾驶人员的监督与管理。主要内容包括；核发车辆驾驶证,考核、审验军车驾驶员；换发车辆号牌和行车执照,审验军用车辆；对行驶中的军用车辆实施检查；参与军用车辆事故现场的勘验和处理。', 314);
INSERT INTO `t_military_term_data` VALUES ('7261698a-0413-4cd4-a5d8-376156ca4964', '97a19170-bfac-42c5-9906-1acb187f0654', '歼击航空兵', '以歼击机为基本装备,主要遂行空战任务的航空兵。通常用以反敌航空侦察,抗击敌空袭,争夺制空权,实施空中掩护。必要时也可用以突击地面、水面目标。', 4);
INSERT INTO `t_military_term_data` VALUES ('72647ce7-7cff-4e43-95b5-66f3e442730d', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵单车训练', '为提高坦克及其他装甲车辆乘员的整体作战能力,以单车为单位进行的训练。', 77);
INSERT INTO `t_military_term_data` VALUES ('7266627d-40fd-4c4d-8ec5-2da1a7b885d3', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '同步卫星定位', '利用地球同步卫星转发地面中心站与测站间的双向测距信号实施定位的方法。定位精度一般为几十米。主要用于车辆、舰船和飞机的全天候快速定位。', 227);
INSERT INTO `t_military_term_data` VALUES ('72673083-8916-49a8-aff7-c6b65986f873', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '液体火箭', '用液体火箭发动机作动力装置的火箭。能量水平高于固体火箭,但结构较复杂,地面设备多,发射准备时间长。', 70);
INSERT INTO `t_military_term_data` VALUES ('72682c76-05a0-4ffd-952d-8e22f7c38b84', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹阵地防御', '为抗击敌人的袭击,保障导弹阵地的安全而在导弹阵地区域进行的防御。包括对空防御和地面防御。', 40);
INSERT INTO `t_military_term_data` VALUES ('726b0bae-57c2-4ae5-b7aa-01d74eac4b65', '878651de-adf5-4c72-9376-9c363b893ff8', '战略退却', '劣势军队处在优势军队的进攻面前,有计划地向后撤退的战略行动。是战略防御的继续。目的是保存军力,待机破敌。', 122);
INSERT INTO `t_military_term_data` VALUES ('726fa6ef-0778-4154-84a7-23be37aac756', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '退伍军人', '①退出现役的中国人民解放军的义务兵。②泛指退出现役的军人。', 159);
INSERT INTO `t_military_term_data` VALUES ('7276d1d5-857e-4097-b6db-1a32055ad407', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防理论', '关于国防问题的系统化理性认识和知识体系。它产生于国防实践,又给国防实践以指导,并受国防实践的检验。', 2);
INSERT INTO `t_military_term_data` VALUES ('72781cb1-6fcd-4779-aeaa-13ca388dfbc3', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战果', '作战获得的成果。包括毙、伤、俘敌之人员,毁坏、缴获敌之武器装备与物资等。', 385);
INSERT INTO `t_military_term_data` VALUES ('72856ce7-6366-4143-8d30-5949a9d59616', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '内部装药爆破', '装药设置在目标内部进行的爆破。如钻孔爆破、药洞爆破和硐室爆破等。', 235);
INSERT INTO `t_military_term_data` VALUES ('72a69b2d-1b31-4c46-97ca-54afb742bfaf', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '配系', '兵力、兵器、技术器材等按一定的任务、性能和要求,有计划有组织地配置后形成的体系。如火力配系、障碍物配系等。', 310);
INSERT INTO `t_military_term_data` VALUES ('72a6eb47-4e2f-46c1-9295-69d5d701911e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '夜间训练', '部队为提高夜暗条件下的机动和作战能力而进行的训练。内容通常包括夜间的基础课目、技术、战术以及夜视器材的操作使用技能等。', 81);
INSERT INTO `t_military_term_data` VALUES ('72a80279-d6fb-470d-8458-ec50928b20ea', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '反干扰技术', '反电子干扰技术的简称。为提高电子设备本身在干扰条件下工作能力而采取的技术措施。通常体现在电子设备的发射机、天线、接收机和信号处理系统中。包括防止接收机过载、提高信号强度和抑制（鉴别）干扰等技术。', 98);
INSERT INTO `t_military_term_data` VALUES ('72ab46c3-b88c-49d7-9b6b-1818474d99a3', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练试点', '部队普遍展开训练之前选定个别单位进行的训练试验。目的是取得经验,指导部队训练。', 11);
INSERT INTO `t_military_term_data` VALUES ('72adad28-f97c-4c33-ab01-70e1ef2e4fed', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '利用地图行进', '利用地形图选定行进路线,并在行进中不断与现地对照,以保持沿选定的路线到达预定地点的行进方法。', 142);
INSERT INTO `t_military_term_data` VALUES ('72af8f81-bfdd-4c4b-9486-e7a6a58b2719', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队反侦察伪装', '导弹部队为欺骗、迷惑敌方的侦察而进行的伪装。', 191);
INSERT INTO `t_military_term_data` VALUES ('72b3571b-108b-4a0d-9b93-4a8366b6085e', '97a19170-bfac-42c5-9906-1acb187f0654', '空中封锁', '航空兵部队以轰炸、强击、布雷等手段对敌方地面、水面的某一区域或目标进行的封锁。通常以若干飞行编队或小分队轮流或连续实施。', 108);
INSERT INTO `t_military_term_data` VALUES ('72b41f43-7735-4672-843d-a7ea2925a249', '97a19170-bfac-42c5-9906-1acb187f0654', '军用教练机', '专门用以训练军队飞行人员的军用飞机。按训练对象,分为飞行教练机和专业教练机；按飞机性能,分为初级教练机、中级教练机和高级教练机。', 288);
INSERT INTO `t_military_term_data` VALUES ('72b97361-39d0-4357-b66a-fa13af0e3918', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行高度', '航空器飞行时与地球表面一定基准水平面的垂直距离。根据所选取的基准水平面不同,分为绝对高度（海拔高度）、相对高度（距机场平面的高度）和真实高度（距地面的高度）。', 229);
INSERT INTO `t_military_term_data` VALUES ('72bea76b-c90b-4c84-9f0c-de74f645af3a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '空间武器', '亦称太空武器。设置在太空或部署在陆地、海洋与空中,用以打击、破坏与干扰太空目标的武器,以及从太空攻击陆地、海洋与空中目标的武器的统称、主要包括反卫星武器、轨道轰炸武器、部分轨道轰炸武器、天基反导武器等。', 224);
INSERT INTO `t_military_term_data` VALUES ('72bede8a-6c0a-45fe-ab66-1a634147a7d8', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆完好率', '①一定时期内完好车日与实有车日的比值。②某一时间完好车数与实有车数的比值。均用百分比表示。用以表明车辆技术状况完好的程度。', 304);
INSERT INTO `t_military_term_data` VALUES ('72d02bad-6611-4843-89df-8d8a77d978f9', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹地面供电设备', '在导弹阵地上为测试、发射导弹提供电能的地面设备。包括电站、交流设备、配电设备和充电、放电设备等。', 63);
INSERT INTO `t_military_term_data` VALUES ('72e231fb-7d46-4cd3-b469-13832ddd9f7f', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮急促射', '高炮按规定的最大速度发射先指定的炮弹数量的发射方式。', 182);
INSERT INTO `t_military_term_data` VALUES ('72e6d1a4-be23-4036-aef5-f9e39eadeb61', '06a75831-13a1-4660-870a-455bb445336a', '自动化信息收集系统', '在指挥自动化系统中利用侦察设备收集情报的分系统。由侦察卫星、侦察飞机、雷达、声纳、光学摄像机和遥感器等组成。能及时收集敌我双方的兵力部署、作战行动以及战场地形、气象等情况。', 161);
INSERT INTO `t_military_term_data` VALUES ('72e7328a-4add-4243-9aa7-2a634445c74f', 'd7132c58-5df3-4b97-919f-58740148b9ca', '敌机投弹距离', '敌机投弹时的投掷点到目标的水平距离。其数值因投弹方式不同而异。分为水平投弹距离和俯冲投弹距离。', 58);
INSERT INTO `t_military_term_data` VALUES ('72ede393-14a5-43b8-b890-aa707e3d2f13', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察情报装备', '侦察情报机关和侦察部队、分队列装的技术装备、器材及其附属设备的统称。分为情报获取装备、情报处理装备、情报传递装备和侦察保障装备。', 115);
INSERT INTO `t_military_term_data` VALUES ('72f0b4c4-2df7-413a-a3d8-b337cce7a06f', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机安定性', '亦称飞机稳定性。飞机在飞行中所具有的保持初始运动姿态,抵抗外界扰动和在扰动消失后自动恢复初始运动姿态的特性。分为俯仰安定性、横侧安定性和方向安定性。', 307);
INSERT INTO `t_military_term_data` VALUES ('72f70adc-1ee4-4e79-81f8-0be9d33b4d1b', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '武器装备', '用以实施和保障作战行动的武器、武器系统和军事技术器材的统称。主要指武装力量编制内的武器、弹药、车辆、机械、器材、装具等。', 95);
INSERT INTO `t_military_term_data` VALUES ('72ff993c-58b7-4ac9-947f-5bbc1e22e444', '916997ee-6728-4c61-9b79-d96960b1dc86', '透气式防毒服', '由透气材料制成的防毒衣。具有防毒、透气、散热功能,用以防止雾滴状和蒸气状毒剂接触皮肤引起的伤害。是适宜合成军队使用的一种防毒服。', 177);
INSERT INTO `t_military_term_data` VALUES ('73014769-6d94-43a5-b4de-093409ce6000', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '运动之敌', '处于移动状态的敌军。通常指行军、开进、增援、退却之敌。这种敌人往往兵力未完全展开,没有阵地依托,作战准备不足,战斗力难以充分发挥。', 236);
INSERT INTO `t_military_term_data` VALUES ('73271ca9-85fa-4694-b8a3-b112fc422c96', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防御纵深', '防御地区或防御部署的纵向深度。分为战役防御纵深和战术防御纵深。', 290);
INSERT INTO `t_military_term_data` VALUES ('732e9c5a-99ce-4611-b496-396017a37386', 'd7132c58-5df3-4b97-919f-58740148b9ca', '对空掩护方法', '防空兵保障目标对空安全的作战方法。有固定掩护、游动伏击、跟进掩护、要点掩护、交替掩护、伴随掩护以及建立对空掩护走廊等。', 76);
INSERT INTO `t_military_term_data` VALUES ('733e3945-c7dc-488e-a2b3-08337cdba488', 'f0140091-c11a-48c9-8836-8aa94439dac0', '抗击反冲击', '进攻中击退或歼灭反冲击之敌的战斗行动。', 196);
INSERT INTO `t_military_term_data` VALUES ('7344c927-3bf7-4e0b-a947-a78acd013f3e', '916997ee-6728-4c61-9b79-d96960b1dc86', '迟滞性化学袭击', '以迫使敌行动迟缓为主要目的的化学袭击。通常使用持久性毒剂在预定地区造成染毒。', 24);
INSERT INTO `t_military_term_data` VALUES ('73558b5e-adc9-4dea-8c35-2f2436024674', '06a75831-13a1-4660-870a-455bb445336a', '转信', '通信双方通过其他台（站）收转信息的通信方法。按组织方法,分为专台（站）转信和相互转信；按技术设施,分为自动转信和人工转信。主要在天候和地形对通信影响较大、通信距离过远、部队机动频繁、遭受敌人干扰及核爆炸等原因造成联络困难的情况下采用。', 47);
INSERT INTO `t_military_term_data` VALUES ('735685c1-c748-400a-b0ce-c56d32be8a17', '98df76fb-4b65-48ff-a56c-4db587327c79', '计划外物资', '未列人后勤物资部门供应计划,由部队后勤自筹的工业品生产资料。', 103);
INSERT INTO `t_military_term_data` VALUES ('7373b9e1-5e60-469e-8f5e-c5c0a521b470', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵等速射', '火炮、火箭炮按相同的时间间隔发射两发战斗状态的过程。', 225);
INSERT INTO `t_military_term_data` VALUES ('7379d4a2-2993-49da-b211-d9bb7529de3b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '放射性武器', '弹道式导弹的简称。飞行轨迹绝大部分为自由抛物体轨迹的导弹。由火箭发动机推送到一定高度和取得一定速度及弹道倾角后,发动机关闭,弹头沿着预定弹道飞向目标。为提高命中精度,有的弹道导弹在弹头再入大气层后的最后飞行段,也能实施制导。', 99);
INSERT INTO `t_military_term_data` VALUES ('73aade8d-57bc-4c56-8aa4-72a730db8b42', 'f0140091-c11a-48c9-8836-8aa94439dac0', '配置地域', '配置兵力、兵器的地域。通常选择在便于遂行任务、便于机动和便于指挥、协同、保障的地域。', 64);
INSERT INTO `t_military_term_data` VALUES ('73c3a1af-def5-4716-9aa8-e05979fb558b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '投诚', '①在中国人民革命战争和国防斗争中,敌方军队或其人员叛离其所从属的集团,归附中国人民武装力量的行为。②泛指战争中非正义一方的军队或其人员叛离其所从属的集团,归附正义一方的行为。', 389);
INSERT INTO `t_military_term_data` VALUES ('73c881f7-9160-4481-bc9f-14cecdb0dd49', '97a19170-bfac-42c5-9906-1acb187f0654', '纵深空中突击', '航空兵部队在支援陆、海军部队作战时,对敌战役战术纵深的目标实施的航空火力突击。分为进攻战役纵深空中突击和防御战役纵深空中突击。', 121);
INSERT INTO `t_military_term_data` VALUES ('73cbaceb-ddab-410a-9abf-179b48fd07fe', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰载预警机', '以航空母舰或其他舰船为基地、主要用于舰队防空预警,并能指挥引导己方飞机遂行作战和其他任务的舰载机。分为固定翼舰载预警机和舰载预警直升机。', 177);
INSERT INTO `t_military_term_data` VALUES ('73daa813-7b46-4d34-b481-ae75c2453c7a', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克航向机枪', '安装在车首驾驶员位置一侧,射击方向与坦克行进方向一致的机枪。用以歼灭和压制近距离的敌有生力量。通常由驾驶员操作。', 115);
INSERT INTO `t_military_term_data` VALUES ('73e6f091-8f13-4fc8-ba39-a042c1451ed4', '8a761efd-50a6-4ac8-9913-b7d745104f82', '有效射程', '亦称有效射击距离。某种射击武器对某类目标射击时，能取得可靠射击效果的距离。各种武器的有效射程依其技术性能和目标种类而定。', 55);
INSERT INTO `t_military_term_data` VALUES ('73e6fa3e-39ed-41d7-b372-51758f58ee52', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '大气', '亦称大气层、大气圈。包围地球的空气层。其密度随高度的增加而减小,2000千米以上大气极其稀薄,一般将磁层顶定为大气的上边界。大气由氮、氧为主的多种气体混合组成。根据大气温度自下而上的垂直分布特征,依次分为对流层、平流层、中间层、热层和外层；根据大气的电离特性,分为中性层、电离层和磁层；根据大气的成分是否保持定常,分为均质层和非均质层。', 0);
INSERT INTO `t_military_term_data` VALUES ('73f1801f-e400-4885-a37e-bafe4605c7eb', 'd7132c58-5df3-4b97-919f-58740148b9ca', '空中目标现在位置', '高炮发射瞬间被射击的空中目标所在的位置。由防空武器系统的炮瞄雷达、光学仪器或光电装置测定。', 163);
INSERT INTO `t_military_term_data` VALUES ('73f4ec95-18ae-4337-ad2b-3925c735065e', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '临时编组', '在一定的部队编成内,根据任务的区分或需要,对部队或分队进行的临时组合。', 82);
INSERT INTO `t_military_term_data` VALUES ('7409c805-cd36-4ea2-a913-4e87a5d4bbfe', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '后备力量', '国家经过动员后所有可以直接参加和支援战争的人力。主要包括预备役部队、民兵和其他服预备役的人员,以及经过军事训练的大、中学校学生。', 19);
INSERT INTO `t_military_term_data` VALUES ('74129531-cdda-499d-932a-bc9ffaafca91', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '覆盖布雷', '直接将地雷布设到敌人的阵地、战斗队形或配置地域内的机动布雷。用以毁伤敌技术兵器,杀伤其人员，割裂其战斗队形,扰乱和迟滞其战斗行动等。', 182);
INSERT INTO `t_military_term_data` VALUES ('741823f2-8ef9-4b82-bda6-291dec796107', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力护送', '以火力支援步兵、坦克向敌防御纵深发展进攻。通常在冲击的火力支援结束时开始,持续到完成战斗任务止。', 99);
INSERT INTO `t_military_term_data` VALUES ('7418e23f-53b2-41ea-824b-ae3e49bd31f7', '8a761efd-50a6-4ac8-9913-b7d745104f82', '刺刀', '亦称枪刺、装于步枪冲锋枪前端用于刺杀的锋刃器具。现代刺刀均为多用，除具有刺杀功能外,还具有砍、割、剪、锯等功能。', 153);
INSERT INTO `t_military_term_data` VALUES ('741e901c-b5e6-4371-870f-b0e8c860130f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '包围', '在正面部队配合下向敌翼侧或后方突击,形成围攻态势的作战行动。按规模,分为战略包围、战役包围和战术包围；按样式,分为一翼包围、两翼包围、四面包围等。', 363);
INSERT INTO `t_military_term_data` VALUES ('742db021-9c20-4cec-9125-774d86c384d8', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '炸点模拟', '亦称炮火显示。在演习场或作业场上，用炸药包、发烟剂等对炮弹、航弹、地雷、手榴弹等爆炸景象的模仿。', 251);
INSERT INTO `t_military_term_data` VALUES ('74315604-52db-49ad-bffe-354637e327db', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '陆军情报', '陆军作战所需的情报。主要来源于陆军所属的专业侦察力量获取的情况,还来源于上级、作战部队、其他军兵种以及地方有关部门、民兵、人民群众等提供的情况。', 130);
INSERT INTO `t_military_term_data` VALUES ('7434b2f3-3473-4d95-b7d7-284fa100706b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '小熊星座', '最靠近北天极的星座。座内有7颗亮星。排列似长尾巴小熊,又形似北斗,亦称小北斗。可用以判定方位。', 191);
INSERT INTO `t_military_term_data` VALUES ('744701be-5e6f-4fe5-b85e-959b825e980f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥自动化', '利用现代科学技术,对指挥所需信息的收集、储存、传递和处理实现自动化。', 172);
INSERT INTO `t_military_term_data` VALUES ('745e525b-aaed-4477-b287-b3850f39744c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '大威力核武器', '威力为 10万～100万吨梯恩梯当量的核武器。', 103);
INSERT INTO `t_military_term_data` VALUES ('74660d1c-6649-461c-9a41-e5eac873e490', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '前进（方向）指挥所', '简称前指,有时亦称方向指挥所为加强对第一战队或某一方向的指挥的出到一定什置建在的辅助基本指挥所指挥的指挥所。通常由副职首长、副参谋长和必要的参谋人员组成,配备有一定的勤务保障力量。', 49);
INSERT INTO `t_military_term_data` VALUES ('74761f10-c4d2-41e5-b208-6c7e419dc620', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '现役军人', '正在军队中服现役的军人。', 146);
INSERT INTO `t_military_term_data` VALUES ('748c97f2-49f1-4c60-8120-9cbff6b89ef6', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防斗争', '为维护国家主权、领土完整以及安全利益而在边境地区开展的斗争。包括反袭扰、反挑衅、反蚕食、反敌特、反走私、缉毒、打击非法越境等。', 107);
INSERT INTO `t_military_term_data` VALUES ('749aa055-55bc-4759-8a69-a7d2a231c5b3', 'f0140091-c11a-48c9-8836-8aa94439dac0', '上船地域', '登陆兵集结上船的地域。包括登陆兵待机地域、上船点和登陆输送工具待机海域。通常选择在有良好的港湾、较好的疏散隐蔽条件、受敌威胁小、便于组织对空对海防御、距离登陆地段近、航渡时间短的地方。', 141);
INSERT INTO `t_military_term_data` VALUES ('74a894b9-2b07-4d45-be83-6d093d0add3e', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '伙食管理', '对连队及其他基层单位的集体伙食工作的管理。主要包括炊事人员的挑选和教育训练、饮食质量和卫生条件的改善、经费计支的掌管等工作。', 24);
INSERT INTO `t_military_term_data` VALUES ('74af0c32-669f-4939-b65e-f250775d9532', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '过渡轨道', '亦称转移轨道。航天器从初始轨道或停泊轨道转移到目标轨道时经过的中间轨道。行星探测器、月球探测器、离地球较远的人造地球卫星,一般都要经过过渡轨道才能到达目标轨道。', 242);
INSERT INTO `t_military_term_data` VALUES ('74b36170-b1d0-4644-9649-71922cf28591', '06a75831-13a1-4660-870a-455bb445336a', '图像通信', '传输图像信息的通信。包括传真通信和电视。传输信息直观,效率高。电视可用于观察、监视作战和演习现场,武器的发射与制导过程,水下和空间的目标运行情况。', 141);
INSERT INTO `t_military_term_data` VALUES ('74be5b8e-30c2-42b9-a10f-349b0c535e50', 'd7132c58-5df3-4b97-919f-58740148b9ca', '对地（水）面目标侦察', '防空兵部队为了解地面或水面敌人活动情况而进行的侦察。通常由阵地对空观察员和对空观察哨进行,必要时也可组织专人实施。', 112);
INSERT INTO `t_military_term_data` VALUES ('74c082a4-386e-4d02-abaa-f479920c86f7', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '敌后侦察', '侦察分队在敌人后方进行的侦察。主要查明敌纵深和后方的重要情况。派出方法有空降和陆地、海上渗透以及预先留置等。', 18);
INSERT INTO `t_military_term_data` VALUES ('74cbc1c9-4981-4100-b2df-003506ab6954', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '定量分析', '运用统计和数学计算的方式研究客观事物的方法、是军事领域内揭示可用一定数量指标表示的事物的质的规定性的重要方法。通常与定性分析结合使用。', 179);
INSERT INTO `t_military_term_data` VALUES ('74d45b5b-c49c-4ce2-abda-76b4e1c4e383', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '电子海图', '利用电子计算机在屏幕上显示海图及舰船航迹、雷达影像等信息,并自动记录航海日志的系统。由舰载计算机、高分辨率彩色图像显示器和航海定位设备等组成。主要用于舰船航行、海上实时定位、港口管理等。', 266);
INSERT INTO `t_military_term_data` VALUES ('74d4c1d5-1390-46ee-bccd-a4a7ea66150e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '标图', '使用军队标号和文宁将军事情况标绘在地图上的作业、包括手工标图和计算机标图。', 119);
INSERT INTO `t_military_term_data` VALUES ('74dd6c59-04ec-4aec-8e5c-f5705c08319a', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '战场修理', '战斗中对损坏的武器装备就地或就近进行的修理。', 124);
INSERT INTO `t_military_term_data` VALUES ('74df9e0a-3c4d-43fc-97f1-4f3721ce5f35', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '复合制导', '采用两种以上制导方式相结合的制导。如自主制导和寻的制导相结合的制导。可综合利用几种制导的优点,增大制导距离,提高制导精度。常用于中、远程导弹。', 55);
INSERT INTO `t_military_term_data` VALUES ('74eb2d50-d48b-4a6f-9a40-c6c1ef93d625', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '降水', '液态或固态水从云、雾中降落并到达地面的天气现象。包括雨、毛毛雨、雪、级、冰雹、冰粒、米雪、冰针等。按一定时段内的降水量或能见度,可将降水分为不同的等级。', 25);
INSERT INTO `t_military_term_data` VALUES ('74ebbf87-45e0-43e6-ae91-458b225220f8', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '潜伏哨', '潜藏埋伏在固定哨警戒范围之外的哨兵。通常配置在便于观察、较为隐蔽的地点。', 30);
INSERT INTO `t_military_term_data` VALUES ('74f1dfc8-a381-4121-9c06-05d9d12a1f4e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防护门', '为阻止冲击波、光辐射及弹片进入工事内部,而在工事出入口设置的门。', 91);
INSERT INTO `t_military_term_data` VALUES ('74f62d53-6d96-408c-bf22-d016dee245b2', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '舍营', '部队在房舍内的宿营。是军队宿营的主要方式。', 93);
INSERT INTO `t_military_term_data` VALUES ('74fa288d-19dd-4e28-9d11-fb25d6cfb033', '98df76fb-4b65-48ff-a56c-4db587327c79', '战时常备药材', '简称战常村。战时卫勤分队和医疗机构用于门诊和救治伤病员的经常消耗的药材。一般以月量为供应计算单位。', 220);
INSERT INTO `t_military_term_data` VALUES ('74fb4fef-18a7-4223-a555-17bf6837e173', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥关系', '指挥员及其指挥机关与所属部队之间构成的指挥与被指挥的关系通常依据编制序列确定还可由下级根据其作战编成确定。', 13);
INSERT INTO `t_military_term_data` VALUES ('74fcd8b8-f72f-436a-9ee8-72f1a1d02f6f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军战役军团', '海军中具有独立实施海上战役作战能力的兵力集团。通常指由水面舰艇、潜艇、海军航空兵、海军陆战队、海军岸防兵和专业勤务等部队临时组成的战役机动编队。', 34);
INSERT INTO `t_military_term_data` VALUES ('7508a174-5d69-4147-86ab-0bae929d09e2', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮表尺', '火炮上用作装定高角（射角）的分划尺。以距离分划为单位的称为距离表尺,以密位分划为单位的称为密位表尺,射击开始时使用的表尺称为开始表尺。', 237);
INSERT INTO `t_military_term_data` VALUES ('751682ee-b936-4415-81a9-14e1c1693a78', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程兵战术', '工程兵遂行工程保障任务的方法。主要包括工程兵行动基本原则、兵力部署、工程技术与工程器材的运用、战斗指挥、协同动作、工程作业的程序与方法、各种保障措施等。', 18);
INSERT INTO `t_military_term_data` VALUES ('752eadd9-04c6-4c5e-904d-8047c4648ac0', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射弹散布中心区', '亦称中央半数必中界。高低散布密集界和方向散布密集纪相交形成的包合全部弹着点50％的矩形区域。', 80);
INSERT INTO `t_military_term_data` VALUES ('752f643c-ea00-4c22-b86b-834e5d398e03', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机超越障碍物飞行', '直升机贴地飞行或超低空飞行时,为防止与地面障碍物相撞而进行的越过或绕过障碍物的飞行。', 30);
INSERT INTO `t_military_term_data` VALUES ('75368e85-0563-4127-8b11-c9d3c813fe78', '8a761efd-50a6-4ac8-9913-b7d745104f82', '基本射击', '为掌握射击的基本要领和技能而进行的不带战术背景的实弹射击。是射击训练的重要内容和阶段。步枪、机枪的基本射击有对固定目标、隐显目标、夜间目标和运动目标的射击。', 98);
INSERT INTO `t_military_term_data` VALUES ('7546fd6a-2865-47b2-bf34-683e97be4cc1', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机机动飞行', '直升机改变运动高度、速度、方向和姿态的飞行。', 29);
INSERT INTO `t_military_term_data` VALUES ('75516fc4-20c1-4e5b-9daa-fb3383b1aad9', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队基层文化工作', '中国人民解放军在连队和舰艇、飞行大队以及与其相当的基层单位开展的群众性文化工作。', 117);
INSERT INTO `t_military_term_data` VALUES ('75544378-7db7-4c54-a0d1-56cb0987f3d0', '31f4a446-5b98-4873-9d53-310d97125b07', '激光反导', '使用激光武器拦截、摧毁来袭的弹道导弹。是反导的重要方法。', 33);
INSERT INTO `t_military_term_data` VALUES ('75555892-9043-4c7a-8aa0-7ef75c358acd', '8a761efd-50a6-4ac8-9913-b7d745104f82', '重机枪', '以稳固枪架为支撑,能持续射击的机枪。重量较大,但射击精度较好，火力持续性长。主要用以歼灭或压制1000米内的生动目标,射击薄壁装甲目标。口径6.5～13毫米,枪身重15～25千克，枪架重15～40千克,战斗射速150－300发／分。', 169);
INSERT INTO `t_military_term_data` VALUES ('75558dbb-f055-4e57-b685-a11414fce67f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '峡谷', '山区河段狭而深的河谷。谷坡陡峭,横剖面常呈“V”字形。谷底上方常见急流和瀑布。如中国金沙江虎跳峡,下切深度达2500～3000米。峡谷可选作水库的坝址。军事上峡谷利于扼守。', 64);
INSERT INTO `t_military_term_data` VALUES ('755a1036-ed15-405d-a472-28b3fd646264', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵激光测距机', '炮兵用以测量距离的以激光为光源的光学仪器。有脉冲式激光测距机和相位式激光测距机两种。测距精度高,体积小,重量轻,便于操作,是炮兵测距的主要器材。', 282);
INSERT INTO `t_military_term_data` VALUES ('75635a62-5698-44b7-938e-bd57930e9a98', '06a75831-13a1-4660-870a-455bb445336a', '战术通信', '为保障战斗指挥而建立的通信联络。基本任务是保障兵团、部队和分队的指挥、协同、后勤、报知和技术保障等通信的顺畅。', 25);
INSERT INTO `t_military_term_data` VALUES ('7564a9f9-0537-4d96-85d2-55186012e0f9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击提前量', '炮兵对运动目标射击时所提前的,相应射弹飞行时间内目标移动的距离或方向的数值。准确决定提前量能保证取得最佳射击效果。', 140);
INSERT INTO `t_military_term_data` VALUES ('75826a76-9ccb-49ee-9b98-c4438ea2d759', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '游击区', '游击队经常进行活动,但未能完全控制或占领的地区。通常位于敌对双方之间的地区或敌占区内控制薄弱的地区。', 292);
INSERT INTO `t_military_term_data` VALUES ('7589c83c-dfc0-4b24-882f-5627f938b767', '97a19170-bfac-42c5-9906-1acb187f0654', '空军作战保障', '空军为顺利遂行作战任务而采取的各项保证性措施与进行的相应活动的统称。主要包括情报侦察、通信、领航、气象、航空管制、雷达、电子防御、机场（阵地）防御等保障。', 348);
INSERT INTO `t_military_term_data` VALUES ('758bc9f0-3a4d-4122-940e-3b2dd425c6b9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '触发引信', '亦称着发引信或碰炸引信。靠撞击目标引爆弹丸的引信。按作用时间长短,分为瞬发引信、短延期引信和延期引信。主要配用于杀伤弹、爆破弹、杀伤爆破弹和破甲弹。', 331);
INSERT INTO `t_military_term_data` VALUES ('758fa4c2-50cd-4521-8fc9-d52c2079dc3f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事形势', '军事斗争的发展变化在一定时期内所形成的格局和态势。', 40);
INSERT INTO `t_military_term_data` VALUES ('7595236b-3ec7-4dcf-9fcd-962e5efd8023', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '像片平面图', '简称像片图。用纠正投影和倾斜误差后的像片拼接而成的影像图。具有图上地物地貌直观、详细等特点。用以制作平坦地区的军用地形图的底图,也可加工成影像地图。', 245);
INSERT INTO `t_military_term_data` VALUES ('75a028f0-f93f-4302-b5e0-45c495cfd5eb', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤防卫', '为保证后勤的人员、物资、装备、设施的安全而进行的防卫。主要包括：对敌情的侦察、观察、报知,对后勤目标的警戒,对敌空袭和核、化学、生物武器的防护,以及与敌特分子的袭击破坏作斗争等。', 64);
INSERT INTO `t_military_term_data` VALUES ('75a74f76-75cd-4722-9280-5e63e65f2db0', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '企图', '军队行动所要达到的基本目的及打算采取的本要手段。', 66);
INSERT INTO `t_military_term_data` VALUES ('75a8ca3d-13cb-4425-8ea4-ccdb534fd606', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克乘员训练基地', '培训坦克乘员和修理工的基地、用以培训坦克车长、一炮手、驾驶员和坦克修理工等。', 67);
INSERT INTO `t_military_term_data` VALUES ('75ab417d-257e-4e05-affa-e87d98192e2d', '916997ee-6728-4c61-9b79-d96960b1dc86', '氯化氰', '全身中毒性毒剂的一种。可装填在炮弹、航空炸弹、火箭弹中使用,造成空气染毒,通过呼吸道引起中毒。有强烈窒息作用,能引起肺水肿等中毒症状。', 220);
INSERT INTO `t_military_term_data` VALUES ('75adf304-22a4-402a-ad55-520d3741ab10', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '军用浮桥', '用浮体作桥脚或以一系列浮体紧密排列起来形成的、浮在水面上的军用桥梁。可用舟桥器材、民舟或其他有一定浮力的就便器材架设。', 277);
INSERT INTO `t_military_term_data` VALUES ('75bced94-1fc2-4eb9-9d24-728a53575316', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '武器', '亦称兵器。能直接杀伤敌有生力量和破坏敌设施的器械与装置的统称、如匕首、枪械、火炮、坦克、导弹、作战飞机、战斗舰艇、核武器、化学武器、生物武器等。', 92);
INSERT INTO `t_military_term_data` VALUES ('75bf185b-2db5-4c8f-90ab-ec1c884d21ba', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克开始射击地区', '战斗中为保证坦克能以突然、猛烈、准确的火力杀伤敌人而规定的射击地区。应以明显地物为标志,通常选在坦克火炮有效射程内。', 49);
INSERT INTO `t_military_term_data` VALUES ('75dcbf92-37a7-43af-97eb-e5b84dccb8e0', '878651de-adf5-4c72-9376-9c363b893ff8', '战略掩护', '掩护国家转入战时体制和军队实施战略展开或战略退却的行动。通常在战略防御的态势下实施。有时也指攻防作战行动中不同战略集团间的相互掩护。', 104);
INSERT INTO `t_military_term_data` VALUES ('75e9ce40-c6f0-405e-8755-079d82231562', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '陆军水雷区', '布设陆军水雷的区域。由数个雷列、雷组或雷群组成。可沿海岸、江岸设置,也可横断江河设置。', 189);
INSERT INTO `t_military_term_data` VALUES ('75f04831-266f-4338-9581-d0aa07d633ba', '98df76fb-4b65-48ff-a56c-4db587327c79', '随军银行', '战时由国家银行派驻军队并随部队行动的金融机构。主要业务是：负责部队经费的划拨、结算和现金管理,办理个人储蓄、汇兑,代管金银、外币、有价证券和贵重物品等。', 77);
INSERT INTO `t_military_term_data` VALUES ('75f5629b-2d10-4a79-b728-1263448d23a8', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '三结合武装力量体制', '由中国人民解放军、中国人民武装警察部队和民兵三种武装组织构成的中华人民共和国的武装力量体制。', 13);
INSERT INTO `t_military_term_data` VALUES ('75fd421b-3a4d-4cd4-bd63-aaf18bb39006', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练基地', '有固定的训练机构和较完善的训练、生活设施,专门用以培训专业技术骨干或供部队、分队进行技术、战术训练的基地。', 15);
INSERT INTO `t_military_term_data` VALUES ('760337f9-c474-4db7-b303-d2bce9c69590', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '参谋业务训练', '为提高参谋人员的业务技能和组织、协调、谋划能力而进行的训练。', 80);
INSERT INTO `t_military_term_data` VALUES ('7606bdc5-8291-4123-8507-dab0a4e24b45', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '杀伤爆破弹', '兼有毁伤有生力量、技术兵器和破坏坚固目标等作用的炮弹。', 307);
INSERT INTO `t_military_term_data` VALUES ('7610a014-c0b4-485d-8d2f-a8dc4e3bc6db', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防坦克壕', '壕沟式防坦克障碍物。通常构筑在平坦地形上或小于15度的缓坡上。包括梯形、三角形和齿轮形防坦克壕。一般口宽4.5～5米,深2～2.5米。积土堆积于壕的两侧或己方一侧。', 115);
INSERT INTO `t_military_term_data` VALUES ('7615450b-c8b8-4855-b4c2-f7e1164f2f6e', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '高苗地', '以生长着高杆农作物的田地。如高粱地、玉米地、甘蔗地等。对部队战斗行动能起遮蔽作用,利于隐蔽和伏击。', 124);
INSERT INTO `t_military_term_data` VALUES ('76168bc1-55ee-493a-890b-f0f7ea87215f', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防建设', '为提高边境地区的防卫和管理能力而进行的军事及相关的政治、经济、科技、文化等方面的建设。', 105);
INSERT INTO `t_military_term_data` VALUES ('761f4300-0c07-4005-ba95-f76320cb5acd', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '射击工事', '保障射手安全和发挥火器射击效能的工事。如机枪工事、火炮工事等。', 43);
INSERT INTO `t_military_term_data` VALUES ('762ac7ab-33a1-4409-a327-0971ef454871', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '空战场', '敌对双方进行空战活动的空间。主要指一定的空域,有的也包括相关的地域或海域。', 165);
INSERT INTO `t_military_term_data` VALUES ('763ba69b-0eb1-4766-a5d8-6bb140474994', '8a761efd-50a6-4ac8-9913-b7d745104f82', '联装机枪', '若干挺枪身安装在一起，共用一套高低机、方向机、瞄准具和发射机的机枪。有双联装机枪三联装机枪、四联装机枪。通常安装在牵引车架或舰艇上。战斗射速高、火力猛。', 173);
INSERT INTO `t_military_term_data` VALUES ('763ecdb5-a3df-4618-a482-43ed161be567', '98df76fb-4b65-48ff-a56c-4db587327c79', '战略后勤', '保障战争的准备与实施的后勤。包括军队最高层次的后勤和国家直接为武装力量建设与战争服务的后勤。', 8);
INSERT INTO `t_military_term_data` VALUES ('7640aab7-b563-48c8-8df0-122d50b53d70', '97a19170-bfac-42c5-9906-1acb187f0654', '机种', '按用途划分的飞机种类。如歼击机、歼击轰炸机、强击机、轰炸机、预警机、侦察机、运输机、空中加油机等。每一机种又可分为不同的机型。', 264);
INSERT INTO `t_military_term_data` VALUES ('7641cbf4-0b99-474b-839e-0ab529d3d945', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达对抗部队', '担负雷达对抗侦察和雷达干扰任务的专业部队。', 7);
INSERT INTO `t_military_term_data` VALUES ('76455e28-d7b9-49e6-83c9-5d8fb151d301', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术防区', '兵团或部队负责防守的区域。通常指师或旅、团防守的阵地,是实施防御战斗的基本依托。一般选择在地形有利,便于构成纵深、环形防御阵地,便于独立坚守,便于指挥、协同和相互支援的地区。', 208);
INSERT INTO `t_military_term_data` VALUES ('7655d768-fc1c-4931-aaa1-0c0b3eaa688d', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '战斗减员', '因战斗伤亡、失踪、被俘等造成的人员减少。', 89);
INSERT INTO `t_military_term_data` VALUES ('76581bc7-33b9-432f-9f4a-e06a885a058d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '内线作战', '军队处于防御地位或被包围态势下的作战。战略上处于内线时,战役、战斗上应力求以外线作战打击和歼灭敌人。', 182);
INSERT INTO `t_military_term_data` VALUES ('765de47e-df1f-426f-bb95-af383f5a3055', '916997ee-6728-4c61-9b79-d96960b1dc86', '核观测分队', '担负对核袭击观测任务的防化分队。主要负责开设核观测哨,及时观测核袭击情况。', 2);
INSERT INTO `t_military_term_data` VALUES ('76755a87-8b57-428f-ae6b-1bc226bb7772', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵临时阵地', '炮兵临时占领的阵地。', 58);
INSERT INTO `t_military_term_data` VALUES ('767591e0-ab17-441f-8af0-178db8d1c16b', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克分割使用', '作战中将坦克部队的全部、大部或一部,分别配属给不同作战方向上的部队使用。目的是增强各个作战方向上部队的突击能力或防御能力。', 10);
INSERT INTO `t_military_term_data` VALUES ('769dd2ab-3d69-4aed-9fe0-ea885a972018', '06a75831-13a1-4660-870a-455bb445336a', '数据通信', '按一定规约（协议）传输数字、字母和符号等数据信息的通信。通常为数据终端与计算机或计算机之间的通信。主要用于作战指挥、地面防空、战略预警、航天测控等方面的数据传输。', 140);
INSERT INTO `t_military_term_data` VALUES ('76b0cad2-2a19-4584-b7c8-45391c0e2978', '98df76fb-4b65-48ff-a56c-4db587327c79', '分供', '亦称专供。由各军兵种后勤机构按建制系统分别组织实施的物资供应。主要适用于专用物资的供应。', 95);
INSERT INTO `t_military_term_data` VALUES ('76c41d50-7b34-4d9c-84ce-482864a72390', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机起飞', '飞机从开始沿跑到离开地面、工升到一定高度（通常为15米或25米）达到一定速度的运动过程。分为正常起飞、紧急起飞、强行起飞等。', 204);
INSERT INTO `t_military_term_data` VALUES ('76c66983-a146-4b21-8286-53a3a3fef46a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '云爆火箭弹', '亦称燃料空气弹。战斗部内装有燃料空气炸药的火箭弹。弹体爆炸后周围呈云雾状,并与空气中的氧混合产生二次爆炸,形成大面积超压,可扩大杀伤效果。', 315);
INSERT INTO `t_military_term_data` VALUES ('76e7bea4-493d-4872-89c7-6547df061b02', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '距离测量', '确定在地面上两点间连线长度的测量。主要包括步测、目测、视距测量、量尺量距、视差法测距、电磁波测距等。', 163);
INSERT INTO `t_military_term_data` VALUES ('76efa9f7-75bb-4390-8ce2-dcbecbc81541', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '掩壕', '能防枪弹、弹片的窄而短的深壕式人员掩蔽工事。通常构筑在掩体的近旁或堑壕、交通壕的一侧。分为露天掩壕和掩盖掩壕。', 63);
INSERT INTO `t_military_term_data` VALUES ('76f712f2-4d96-457a-9d14-df92fd5b4c28', '97a19170-bfac-42c5-9906-1acb187f0654', '失速', '飞机在飞行中因飞行迎角接近或大于临界迎角而引起的失控运动状态。飞机失速后会突然改变正常飞行状态,发生非周期性的俯仰。滚转或偏转直至螺旋等现象。', 247);
INSERT INTO `t_military_term_data` VALUES ('76fc1b24-80c9-452a-8ee5-b79bfb89db4f', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫勤保障', '军队后勤机构在卫生勤务方面实施的保障。主要由卫生部门采用组织管理措施和医学技术措施,直接对部队人员进行伤病防治,以保障其健康。包括医疗后送、卫生防疫、卫生防护、医疗保健、药材供应等。', 182);
INSERT INTO `t_military_term_data` VALUES ('77077df9-b947-45d5-b623-dd17c4f68099', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边疆', '国家陆地领土的边缘地区。', 79);
INSERT INTO `t_military_term_data` VALUES ('770d589a-bb17-419c-9522-0006f92983f5', '97a19170-bfac-42c5-9906-1acb187f0654', '战斗出航', '遂行战斗任务的飞机或直升机起飞后,通过航线起点向战区或目标区的飞行。有时也指直接向战区或目标区的飞行。', 52);
INSERT INTO `t_military_term_data` VALUES ('77200ef1-bbd5-4588-bd87-d4e135574974', '8a761efd-50a6-4ac8-9913-b7d745104f82', '正射', '亦称正面射。射向与目标正面概略垂直的射击。', 107);
INSERT INTO `t_military_term_data` VALUES ('772c5b57-88fd-4ecb-9121-ac9607bb6bd1', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '授衔', '授予军衔的简称。按照军官军衔条例和士兵服役条例,首次授予现役军人相应等级军衔的活动。', 86);
INSERT INTO `t_military_term_data` VALUES ('7737192c-f83a-4505-a363-c64a395c9014', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '磁偏角', '磁子午线与真子午线间的夹角。磁子午线北向在真子午线以东的称东偏,以西的称西偏；东偏为正,西偏为负。磁偏角是经实地测得的,大小因地而异。同一地点的磁偏角随时间变化发生微小变化。地形图上的磁偏角是该图幅范围内的平均值。', 161);
INSERT INTO `t_military_term_data` VALUES ('7738b33f-9b0e-4aef-a462-32785ebbcdfc', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射准备时间', '导弹部队和分队进行发射准备的时间。通常指从占领发射阵地（液体导弹发射井作战从加注液体推进剂起）至导弹处于待发状态时的时间。', 135);
INSERT INTO `t_military_term_data` VALUES ('77411d80-750d-4ec4-94db-d550bec05719', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '鹿砦', '用伐倒树木设置的形似鹿角的筑城障碍物、分为树枝鹿砦和树干鹿砦。树枝鹿砦用直径不小于15厘米的树交叉并列设置,主要用以防步兵。树干鹿砦是将直径20厘米以上的树,在距地面0.6～1.5米处交叉伐倒,使树冠朝向敌方,主要用以防坦克。', 125);
INSERT INTO `t_military_term_data` VALUES ('774e0e0c-36ec-4659-ba2b-f7c90a615c17', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学侦察', '为查明敌化学袭击造成的染毒情况而进行的侦察。包括方向侦察、地域侦察和定点监测。主要用以查明染毒的种类、范围,概略判定染毒的密度和浓度,收集染毒样品,监测毒剂云团的传播和滞留情况。', 51);
INSERT INTO `t_military_term_data` VALUES ('7751f61c-523d-4d4a-9725-94c808697de7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '撤出', '军队退出作战的行动。通常在战场情况发生重大变化,无需或无法继续作战时,根据上级命令实施。', 352);
INSERT INTO `t_military_term_data` VALUES ('77544cc9-bdc0-4b0c-ae3a-9a0cae70f746', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防观念', '保卫国家安全、履行国防义务的思想意识。', 55);
INSERT INTO `t_military_term_data` VALUES ('77565dd6-7003-47a1-9902-dba89b6d2d73', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事技术学', '研究军事工程和武器装备的技术理论及其应用的各学科的统称。是军事科学的重要组成部分。按武器装备的种类,分为枪械、火炮、坦克、弹药、军用飞机、舰艇、导弹等技术学；按军兵种,分为海军、空军、战略导弹部队、炮兵、装甲兵、工程兵、防化兵等技术学。', 31);
INSERT INTO `t_military_term_data` VALUES ('778235ac-38f9-4521-a6d9-1db152b47e70', '97a19170-bfac-42c5-9906-1acb187f0654', '对空警戒侦察', '运用雷达或其他手段对空中情况进行的侦察。包括搜索、发现、监视空中目标和综合、报知空中情况等。', 117);
INSERT INTO `t_military_term_data` VALUES ('7788f892-8546-41b9-bf30-86f89358f508', '06a75831-13a1-4660-870a-455bb445336a', '无线电监测', '对无线电设备和信号进行的技术测量和鉴定。监测项目包括频率稳定度、频带宽度、谐波辐射、电场强度、干扰来源等。', 38);
INSERT INTO `t_military_term_data` VALUES ('7789ddae-187a-4b8e-9160-a267e93fbfd5', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '野战气象仪', '野战条件下使用的便携式综合地面气象观测仪器。包括大气温度、湿度、压力和风的测量仪器以及其他辅助器材等。通常装在一个轻便手提箱内,由单兵携带使用。', 102);
INSERT INTO `t_military_term_data` VALUES ('7790c9cd-3654-4407-9847-7733c3d393e0', 'f0140091-c11a-48c9-8836-8aa94439dac0', '由舰到岸', '登陆兵由登陆输送舰船输送到预定海域,再换乘小型登陆工具上陆的登陆输送方式。通常用于航程较远的登陆作战。', 145);
INSERT INTO `t_military_term_data` VALUES ('779c5202-b2c3-4d77-9638-f03537536cfe', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '舟桥器材', '简称舟桥。用以架设浮桥和结构门桥的成套制式渡河器材。按是否具有水陆自行能力,分为自行舟桥和非自行舟桥；按所架浮桥载重量,分为轻型舟桥、重型舟桥和特种舟桥；按所架浮桥的桥脚配置形式,分为桥脚分置式舟桥和带式舟桥。', 299);
INSERT INTO `t_military_term_data` VALUES ('77a7bb4c-0964-4087-9255-07ebb55a5a0e', '97a19170-bfac-42c5-9906-1acb187f0654', '航空布雷', '使用飞机或直升机对预定区域布设地雷或水雷的战斗行动。', 105);
INSERT INTO `t_military_term_data` VALUES ('77a8a3fc-de2d-4314-9062-dc5d3656461c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵待机地域', '炮兵为组织准备进攻或待机进入交战而占领的地域。通常由上级指定。一般选择在便于隐蔽伪装、机动和有利于及时展开作战的地方。', 53);
INSERT INTO `t_military_term_data` VALUES ('77aee677-da1a-462e-a138-e8b118d8461f', 'f0140091-c11a-48c9-8836-8aa94439dac0', '轮番战斗', '数个作战单位轮流交替进行的战斗行动。通常在战斗持续时间较长、己方兵力占优势或敌设防较坚固等情况下采用。', 19);
INSERT INTO `t_military_term_data` VALUES ('77c422c0-bc33-42f1-b9b7-2f010eb0d1d9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战目标', '作战所要打击的对象或要夺占的地方。', 117);
INSERT INTO `t_military_term_data` VALUES ('77c5065f-3d9a-4661-a7ed-da1f00c8945b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战线', '敌对双方作战时的接触地带。战线是否固定,依作战形式而定。阵地战的战线比较固定,运动战、游击战没有固定的战线。', 278);
INSERT INTO `t_military_term_data` VALUES ('77d6a71c-b9a3-4585-bc1d-368969cb4306', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战特点', '各种作战因具体条件不同而反映出的各自的矛盾特殊性。', 123);
INSERT INTO `t_military_term_data` VALUES ('77d887b4-f71e-4fe2-a462-928ece0cb842', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天气实况', '气象台站实时观测、记录和报告的天气状况。主要内容包括气温、气压、湿度、风、云、能见度、降水、雷暴以及其他天气现象等。', 64);
INSERT INTO `t_military_term_data` VALUES ('77da6de2-399f-4fc9-a6f2-4e1520d2b4f2', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '铁丝障碍物', '用有刺铁丝或刺钢带等构成的筑城障碍物。主要用以迟滞步兵行动,有的也可用以迟滞车辆行动。分为固定式和移动式两类。固定式铁丝障碍物有低桩铁丝网、屋顶形铁丝网、两列桩铁丝网、同形铁丝网、系蹄、乱线等。移动式铁丝障碍物有蛇腹形铁丝网、蛇腹形钢带网、防步兵拒马等。', 108);
INSERT INTO `t_military_term_data` VALUES ('77ed9d28-2b44-48f3-8794-c5a6916bead5', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电通信对抗部队', '简称通信对抗部队。担负无线电通信对抗侦察和通信干扰任务的专业部队。', 8);
INSERT INTO `t_military_term_data` VALUES ('77fefe4c-a14a-4d27-acbd-58a8f3bd4a68', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇下潜深度', '潜艇潜入水中后从水面至其中央舱深度计之间的垂直距离。以米为计算单位。分为潜望深度、危险深度、安全深度、工作深度、最大工作深度、极限深度和设计深度等。', 298);
INSERT INTO `t_military_term_data` VALUES ('7801f251-47d2-401f-bf67-b2b2df5d9f99', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战斗队形', '部队或分队为进行战斗而展开兵力兵器所形成的队形。分为合成军队战斗队形和兵种战斗队形。', 55);
INSERT INTO `t_military_term_data` VALUES ('7803a5de-b616-47e0-b66c-4227623baac4', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海陆风', '滨海地区因海洋和陆地受热不均匀而形成的有明显日变化的风。通常在晴朗而稳定的天气条件下出现。白天,陆地增热较快,气压相对较低,风从海面吹向陆地,称为海风；夜间,陆地冷却较快,气压相对较高,风从陆地吹向海面,称为陆风。由于海陆的温差白天大于夜晚,海风一般比陆风强。', 50);
INSERT INTO `t_military_term_data` VALUES ('7805354d-52ed-469c-8b3d-07cc21bb1491', '31f4a446-5b98-4873-9d53-310d97125b07', '战略导弹战术技术性能', '由设计、制造等因素决定的战略导弹在服役期和作战使用中所具备的特性与功能。主要包括射程、威力、命中精度,反应时间,可靠性,外形尺寸、质量参数,发动机推力,以及突防能力、机动能力、防护能力和投掷质量等。', 18);
INSERT INTO `t_military_term_data` VALUES ('781c3f4c-e3df-4b4a-ab3f-77f748edde5e', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机水平攻击', '直升机在水中飞行状态中以机载武器对敌方目标进行的攻击。', 79);
INSERT INTO `t_military_term_data` VALUES ('781ce7a1-5183-41fb-8a59-6eba933ae0a6', '06a75831-13a1-4660-870a-455bb445336a', '信号观察哨', '负责发放和接收简易信号的哨所。战时在团以上部队设置,并配备一定数量的通信工具；营以下分队通常指定战斗员兼任信号观察员。信号观察哨的位置,应选择在便于发放、接收信号而又隐蔽的地点。', 133);
INSERT INTO `t_military_term_data` VALUES ('78425381-462f-4b89-a1bd-62802ae30a90', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '灵活机动', '战争中,根据客观实际情况随机应变地运用战略战术。', 247);
INSERT INTO `t_military_term_data` VALUES ('78447894-254d-4ade-84cf-64e20d545bca', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵通信等级', '对装甲兵指挥员和装甲车辆乘员掌握的通信理论与技能程度划分的等级。分为特级无线电手、一级无线电手和二级无线电手3个等级。', 80);
INSERT INTO `t_military_term_data` VALUES ('784c5a6a-4190-4ad8-a03d-f9ec75ef1a6b', '06a75831-13a1-4660-870a-455bb445336a', '通信光缆', '由光导纤维构成的光信号传输线。由光导纤维、加强件、填充物和外护套等组成。可传输电话、电报、数据、图像等。通信容量大,通信距离远,重量轻,不受电磁干扰和核爆炸产生的电磁脉冲的影响。', 209);
INSERT INTO `t_military_term_data` VALUES ('784ca248-80b0-41fc-a237-bfeac4536974', '97a19170-bfac-42c5-9906-1acb187f0654', '机场待战', '飞行员和飞机做好战斗准备,在机场待命出击的状态。', 43);
INSERT INTO `t_military_term_data` VALUES ('784d624f-1207-424d-936e-0c76691d2cf5', 'd7132c58-5df3-4b97-919f-58740148b9ca', '对空射击训练模拟器', '用以模拟地空导弹、高射炮对空射击的训练器材。包括室内训练模拟器和室外训练模拟器。', 135);
INSERT INTO `t_military_term_data` VALUES ('784ffcdf-6119-47b5-960c-94ee5796fba4', 'f0140091-c11a-48c9-8836-8aa94439dac0', '对阵地防御之敌的进攻战斗', '对依托阵地进行防御之敌实施的进攻战斗。包括对野战阵地防御之敌的进攻战斗和对坚固阵地防御之敌的进攻战斗。', 124);
INSERT INTO `t_military_term_data` VALUES ('78591d1e-802f-48ec-8d6b-06941fd742eb', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行中队', '航空兵最基层的一级组织。为航空兵的基本战术分队。通常隶属于飞行大队。', 13);
INSERT INTO `t_military_term_data` VALUES ('785de53a-e824-4922-8abc-73352fd78f94', '97a19170-bfac-42c5-9906-1acb187f0654', '空降作战准备阶段', '空降作战中部队从受领作战任务起至完成乘载航空器准备止的阶段。主要包括：进行战斗动员,完成组织指挥和各种保障准备,进行临战训练,选择空降出发地域和空降场,开进到乘载航空器的地域等。', 156);
INSERT INTO `t_military_term_data` VALUES ('786ad6f2-64fa-4fb4-a167-337e093d652e', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备配套率', '武器装备的实际配套数与编制配套数的比值。通常用百分比表示。', 86);
INSERT INTO `t_military_term_data` VALUES ('786f5710-80d1-43af-86a6-9bbfee3a10f6', '97a19170-bfac-42c5-9906-1acb187f0654', '巡航高度', '适宜于航空器或巡航导弹长距离、长时间飞行的高度。', 299);
INSERT INTO `t_military_term_data` VALUES ('78774507-086c-436e-94e8-d29807d29989', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵指挥所', '第二炮兵指挥员及其指挥机关指挥作战和其他行动的机构和场所。按指挥职能,分为基本指挥所、预备指挥所、前进指挥所和后方指挥所；按指挥所位置,分为地下指挥所、地面指挥所和空中指挥所；按载体,分为机载指挥所和车载指挥所等。', 126);
INSERT INTO `t_military_term_data` VALUES ('787d8c8a-2e66-4ba7-b7c5-61715ed2b2b9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火袭击', '在步兵、坦克发起冲击前,炮兵集中火力对敌实施的短促火力突击。主要用于对仓促防御、临时驻止、空降着陆和运动之敌的进攻。通常以急袭射击的方法进行。', 66);
INSERT INTO `t_military_term_data` VALUES ('788273ee-8920-4cc7-92e9-9fd22327a9f6', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆管理', '车辆从订购到退役、报废的一系列管理工作过程。主要包括：车辆的订购、配发、动用、保管、维修、退役报废,以及车辆科研和专业训练等。', 299);
INSERT INTO `t_military_term_data` VALUES ('788a5e7d-3d71-4a11-87c5-15743c2036b9', '97a19170-bfac-42c5-9906-1acb187f0654', '特种空降', '为执行特殊任务而组织实施的空降。如在敌后遂行侦察、袭扰、破坏、营救任务等。', 153);
INSERT INTO `t_military_term_data` VALUES ('789c6a3f-9177-4abe-a25b-2e550ac765ad', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '回归轨道', '星下点轨迹周期性重复的人造地球卫星轨道。重复的时间间隔,称为回归周期。在回归轨道上运行的卫星,可对覆盖区域进行动态监视,借以发现间隔时间内目标所发生的变化。', 240);
INSERT INTO `t_military_term_data` VALUES ('789d275a-31ab-4f1e-84d2-ced5c18f64ef', '98df76fb-4b65-48ff-a56c-4db587327c79', '支前组织', '地方为支援军队前线作战而组建的领导机构和各种勤务组织的统称。支前领导机构,如支前委员会；支前勤务组织,如医疗队、防疫队、担架队、运输队、工程队、物资供应站等。', 40);
INSERT INTO `t_military_term_data` VALUES ('789eb7b3-cea4-4798-b1a9-3a896dc89e4f', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '临战训练', '在临近战争爆发或受领作战任务后进行的有针对性的训练。通常结合作战任务和战区特点,选择急需内容,以突击的方式进行。', 47);
INSERT INTO `t_military_term_data` VALUES ('78a531e2-6c88-4790-a0ca-ac0e1cb06e0d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '爆破器材', '实施爆破作业使用的器具和材料的统称。包括炸药、火具（火工品）、爆破器、核爆破装置和爆破工具等。', 203);
INSERT INTO `t_military_term_data` VALUES ('78a8334f-dc0e-407e-abde-8ebde2ae2857', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军航空兵', '以飞机为基本装备,主要在海洋和濒海上空遂行作战任务的海军兵种。包括海军岸基航空兵和舰载航空兵。可攻击敌方海上、空中目标,袭击敌方和保护己方的海军基地、港口、沿海机场和海上交通线,争夺海洋战区和濒海战区的制宝权与制海权,从空中掩护、支援己方舰艇的战斗行动等。', 3);
INSERT INTO `t_military_term_data` VALUES ('78ace189-3b0e-4c14-a799-fe1729de7a8d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '道路警备调整勤务', '为保证军用道路正常使用而组织的护路警戒、对空观察、交通调整等勤务的统称。由合成军队司令部指派专门的或临时指定的勤务分队实施。', 267);
INSERT INTO `t_military_term_data` VALUES ('78bce128-1aad-4cff-9180-4819513cd7e0', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '锚位', '舰船锚泊时锚的位置。用地理坐标（包括经度和纬度）或相对于某一固定物标的方位与距离表示。', 280);
INSERT INTO `t_military_term_data` VALUES ('78c08872-dac7-4613-9a57-a2835427904f', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫生船舶', '水上救护、医疗和后送伤病员的专用船、艇。包括医院船、卫生运输船、救护艇和特种医学船（艇）等。', 229);
INSERT INTO `t_military_term_data` VALUES ('78c7113f-ca75-47af-b935-4cf9264ad4c0', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '党小组', '党支部的组成部分。根据党支部党员数量和分布情况划分。每个党小组选举1名正式党员担任组长。中国人民解放军的连队党支部通常每排编1个党小组。', 44);
INSERT INTO `t_military_term_data` VALUES ('78d636ef-0f88-4aae-93e8-047f84665cdf', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹瞄准射程', '在导弹发射点至目标瞄准点的大地距离的基础上经过各种修正后的射程、分为基本瞄准射程、近似瞄准射程和最终瞄准射程。对大地距离进行地球物理因素偏差修正后的瞄准射程,称为基本瞄准射程；在基本瞄准射程基础上,对起飞重量偏差修正后的瞄准射程,称为近似瞄准射程；对地球物理因素和其他有关因素作进一步修正后的瞄准射程,称为最终瞄准射程。', 184);
INSERT INTO `t_military_term_data` VALUES ('78e8ce1f-b673-4063-b40c-02b4905cb307', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹单发射', '一次只用一发地空导弹射击一个目标的发射。当判明前一发导弹未命中目标时、可再补射一发。', 209);
INSERT INTO `t_military_term_data` VALUES ('78ec9327-95d4-4033-b430-8969a36c2e1a', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '山谷风', '山区因山坡和谷地受热不均匀而形成的有明显日变化的风。通常在晴朗而稳定的天气条件下出现。白天,山坡增热较快,气压相对较低,风从谷地吹向山坡,称为谷风；夜间,山坡冷却较快,气压相对较高,风从山坡吹向谷地,称为山风。由于山坡与谷地的温差白天大于夜晚,谷风一般比山风强。', 51);
INSERT INTO `t_military_term_data` VALUES ('78efe752-1f27-4f2e-b432-1c3bf1c099ed', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机再次出动准备', '飞机着陆后为在短时间内再次执行飞行任务而进行的地面准备。包括飞机准备和飞行人员准备。', 63);
INSERT INTO `t_military_term_data` VALUES ('7902e707-cc70-4740-bb9a-a424649ed0b7', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '作战统计', '亦称战斗统计。对战绩和己方战斗减员、装备物资损耗等情况的数量统计。', 87);
INSERT INTO `t_military_term_data` VALUES ('7919f617-aa3a-4ebd-a76f-ea3d3514de1c', 'd7132c58-5df3-4b97-919f-58740148b9ca', '制止空中侦察', '防空兵部队或分队打击敌航空器,阻止其实施空中侦察的作战行动。', 61);
INSERT INTO `t_military_term_data` VALUES ('791dad84-be13-4f92-bfd9-60ec572088d7', '97a19170-bfac-42c5-9906-1acb187f0654', '空降兵战术', '空降兵进行战斗的方法。主要包括空降战斗的基本原则、兵力部署、战斗指挥、战斗行动的方法、协同动作与各种保障措施等。', 145);
INSERT INTO `t_military_term_data` VALUES ('79304200-f370-4c82-a144-140668bf89a5', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '专业技术符号', '表明军人从事专业技术工作的标志。中国人民解放军的专业技术符号以“八一军徽”为主体,衬以原于符号图案、规定佩戴在军衣领上。', 141);
INSERT INTO `t_military_term_data` VALUES ('794205f9-445f-4f0d-a3f4-61f887a41b1d', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '追击战役', '追歼退却的敌重兵集团的战役。', 63);
INSERT INTO `t_military_term_data` VALUES ('79476eee-7f3e-4219-81ed-ce0c732ccf59', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '时节', '战役、战斗某阶段中的某一作战行动从开始到结束的一段时间。如火力准备时节、火力支援时节等。', 36);
INSERT INTO `t_military_term_data` VALUES ('794ab238-39aa-46c7-8bab-cdd524e74c1b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队战斗队形', '海战中舰艇编队或战术群内各舰艇按照战术要求展开后形成的队形、基本战斗队形有单纵队、单横队方位队、梯队和人字队（楔形队）等。', 74);
INSERT INTO `t_military_term_data` VALUES ('7955a8a2-9177-41da-9677-968e50c22339', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克通信性能', '坦克所具有的可供车内外通信联络的特性与功能。主要表现为通信距离、抗干扰能力和通信保密能力。', 181);
INSERT INTO `t_military_term_data` VALUES ('79562192-770a-4a9f-8cfc-8912fc1859ce', '878651de-adf5-4c72-9376-9c363b893ff8', '战争状态', '国家或政治集团之间终止正常关系,公开宣战或实际进入武装对抗行动所形成的敌对关系状况。', 30);
INSERT INTO `t_military_term_data` VALUES ('7965bab6-8496-4cc5-b50d-d9f58de1ce0e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '试射成果方向', '试射结束时所获得的炮目方向或炮试方向。是在当时射击条件下能使射弹散布中心通过目标或试射点的方向。其值等于开始方向与试射过程中的方向修正量之和。', 157);
INSERT INTO `t_military_term_data` VALUES ('7969870c-4183-43e5-9de4-f7c4b38b5192', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '沙漠', '地表为大片沙层覆盖的荒漠。日照强烈,昼夜温差大,降水少,植被稀疏矮小,风沙活动频繁,人烟稀少,农产品缺乏。军队在沙漠地行动,不易掌握方向,不便隐蔽,体力消耗大,后勤补给和给水困难。', 37);
INSERT INTO `t_military_term_data` VALUES ('796f24cc-0b2f-4b44-81eb-e774fcec693e', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备体制', '军队在一定时期内的各种武器装备系列的总体结构。按时限,分为现行装备体制和发展规划装备体制；按用途,分为主战装备体制和保障装备体制等。', 79);
INSERT INTO `t_military_term_data` VALUES ('79759696-b5c0-4bb2-9714-d7a4c328e9db', '878651de-adf5-4c72-9376-9c363b893ff8', '常规战争', '使用常规武器进行的战争。相对于核战争而言。', 11);
INSERT INTO `t_military_term_data` VALUES ('7979e76e-332e-4eeb-9976-c5cf3933a46c', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '远战武器', '用以遂行远距离火力打击任务的武器。如大口径火炮、作战飞机、弹道导弹、巡航导弹等。', 41);
INSERT INTO `t_military_term_data` VALUES ('79800c78-124f-421a-adbc-428277393d86', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤先遣组', '根据部队的行动任务事先派出的后勤工作小组。主要负责与沿途的兵站和地方支前机构联系,安排途中后勤保障工作。', 59);
INSERT INTO `t_military_term_data` VALUES ('7986628d-d177-4f47-ae8d-852e6a156d15', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航空母舰', '简称航母。以舰载机为主要武器并作为其海上活动基地的大型水面战斗舰艇。按作战任务,分为攻击航空母舰。反潜航空母舰和多用途航空母舰：按动力分,为常规动力航空母舰和核动力航空母舰。主要用以攻击敌舰船袭击海岸设施和陆上目标,中取作战海区的制宝权和制海权,支援登陆和抗登陆作战。', 132);
INSERT INTO `t_military_term_data` VALUES ('7986c642-4b57-4030-ab2b-2a639cac5864', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '激光器', '利用受激发射原理使光波放大而产生激光的装置。一般由激光工作物质、光学谐振腔和激励源组成。军事上有广泛用途', 83);
INSERT INTO `t_military_term_data` VALUES ('798786fc-45b9-4d47-ba81-d2a288cf6c85', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化方向侦察', '沿指定方向或道路实施的化学、辐射侦察。主要用以查明军队行进路线上的受染情况,寻找绕行路和选择通路,并标志受染地域前后界。', 52);
INSERT INTO `t_military_term_data` VALUES ('799bce35-ff92-4ad4-92bd-f0bc4ec81c1b', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫生防疫', '在军队中预防疾病,控制和消除传染病流行的卫勤保障活动。主要内容包括：调查研究战区或部队驻地的致病因素,采取各种预防和扑灭传染病的措施,改善部队卫生状况,指导部队防疫工作等。', 205);
INSERT INTO `t_military_term_data` VALUES ('799dd53c-081a-4cdf-86dc-eb976f62de71', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹部队', '地空导弹旅、团的统称。独立地空导弹营一般亦被称作地空导弹部队。', 4);
INSERT INTO `t_military_term_data` VALUES ('79a60a96-ed8f-4678-ba90-da20d6a04c5a', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '报告', '向上级反映情况的军用文书。', 133);
INSERT INTO `t_military_term_data` VALUES ('79a87038-ec8f-412d-bae9-b75bbc8a57b0', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '组织侦察', '对侦察行动进行计划和组织的活动。由各级司令部实施。主要内容包括：拟制侦察计划,下达侦察指示,派遣侦察机构和人员,组织侦察协同和通信联络等。', 96);
INSERT INTO `t_military_term_data` VALUES ('79ae865c-83ec-4724-a551-2ae022cc9e67', '83e065b4-6737-4645-9ea5-8276d1de13ed', '车间距离', '装甲车辆两车之间的距离。运动中通常保持50～100米；在尘土较大、地形复杂或通过沾染区时,可适当加大。', 35);
INSERT INTO `t_military_term_data` VALUES ('79b1a5c9-4334-48ea-99c8-aeb4254cf7f4', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '投掷式电子侦察设备', '可被各种运载工具投放并能自动实施电子侦察的电子设备。通常被投放到敌方重要军事目标附近,搜集、存储敌方电子设备发射的电磁信号,并可在己方遥控下适时将所获情报发回。', 122);
INSERT INTO `t_military_term_data` VALUES ('79b82385-51be-482f-9003-b7b84fda8a53', 'f0140091-c11a-48c9-8836-8aa94439dac0', '堵击', '对退却或前进之敌进行的阻击。', 161);
INSERT INTO `t_military_term_data` VALUES ('79be76bf-5d41-4814-bf54-a68a7badb8bb', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电通信冒充', '利用无线电台模拟敌方电台工作并插入其通信网络进行欺骗的行动。', 73);
INSERT INTO `t_military_term_data` VALUES ('79c02a67-b32d-431c-8d75-faea3f199258', '06a75831-13a1-4660-870a-455bb445336a', '口令', '①识别敌我的口头问答暗语。通常在夜暗及其他能见度不良的情况下使用。②使用简短的军事术语下达的口头命令。如立正、稍息等各种队列口令。', 158);
INSERT INTO `t_military_term_data` VALUES ('79d03c21-c03b-4ba6-87fd-82179400637d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮齐射', '在指挥员统一口令下数门高炮同时射击的发射方式。', 181);
INSERT INTO `t_military_term_data` VALUES ('79d298f3-c773-46b5-ac62-588dee7c5d27', '97a19170-bfac-42c5-9906-1acb187f0654', '机场疏散区', '在机场附近划定的疏散隐蔽飞机或直升机的区域。通常有飞机掩体、停机坪以及通往主跑道、应急起飞跑道的拖机道等。飞机可在疏散区进行机务、后勤准备。', 439);
INSERT INTO `t_military_term_data` VALUES ('79d58121-d77e-4c98-a940-4697189e371e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '定向爆破', '将定量的土石按预定方向抛掷并堆积到预定区域的爆破。主要用以堵塞隘路、筑坝、筑路、构筑土工障碍物等，也可用以杀伤有生力量。', 240);
INSERT INTO `t_military_term_data` VALUES ('79d8f1d8-1971-4e33-bc02-1bb011043122', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '电视侦察', '使用电视摄像器材摄取目标图像的侦察。主要器材有可见光摄像机、红外线摄像机、多光谱摄像机等。', 59);
INSERT INTO `t_military_term_data` VALUES ('79db1fa9-7ea5-4efa-afdd-76fb725e6696', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '军事海洋测绘', '为保证国防建设和军队作战、训练的需要,对海洋和江河湖泊水域及其沿岸地带进行测量和制图的统称。包括海洋大地测量、海道测量、海底地形测量、海图编制、海区资料编汇等。', 370);
INSERT INTO `t_military_term_data` VALUES ('79e1cc00-2543-4c0c-ade1-2a95f149d173', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '政治动员', '中国人民解放军在作战、训练和其他工作中从政治思想上对军人进行的教育和宣传。目的是使军人认清形势,明确执行任务的目的和意义,了解完成任务的有利条件和克服困难的办法,提高完成任务的自觉性和积极性。', 34);
INSERT INTO `t_military_term_data` VALUES ('79ed6c29-e8ee-4507-a343-bfba33651803', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '时区', '将地球表面按经线划分的24个时间区域。以本初子午线（经度0度）为基准,以西经7.5度至东经7.5度的范围作为0时区,然后每隔15度为1个时区。每时区以其中央子午线上的时间为该时区统一使用的标准时,即该时区的区时。相邻两时区的时差为工小时。', 210);
INSERT INTO `t_military_term_data` VALUES ('79f5d99d-f475-41b3-b944-2971bf718ef7', '31f4a446-5b98-4873-9d53-310d97125b07', '危险区', '以导弹飞行轨迹为中心划出的对己方人员、物体具有危险性的一定区域。', 122);
INSERT INTO `t_military_term_data` VALUES ('7a042fd9-0bd7-48a7-9626-5c4afb836c5c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '战役战术导弹', '射程在 1000公里以下,用于打击敌战役、战术纵深内重要目标和支援部队战斗行动的导弹。', 4);
INSERT INTO `t_military_term_data` VALUES ('7a0e5ada-325a-4444-b2de-90c4142ce3ab', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练弹药', '供军事训练用的各种弹药的统称。包括各种实弹和教练弹等。', 187);
INSERT INTO `t_military_term_data` VALUES ('7a1569d8-c4f5-423a-9e9b-392963650a48', '98df76fb-4b65-48ff-a56c-4db587327c79', '救治范围', '按照统一的分级救治体制和救治规则,对各级救治机构救治伤病员的项目和幅度的规定。目的是使各级救治机构的救治任务具体化、规范化,保证伤病员救治过程的连续性、继承性和完整性。', 198);
INSERT INTO `t_military_term_data` VALUES ('7a16e5cc-ffbe-4bac-b713-9e5e619002d9', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂报警器', '监测空气染毒情况,自动发现并发出警报信号的化学侦察器材。按监测距离和范围,分为点测、遥测毒剂报警器；按使用方式,分为便携式、固定式、车载式毒剂报警器等。', 162);
INSERT INTO `t_military_term_data` VALUES ('7a19a344-849c-4e52-87db-4c1cd6506bd1', '97a19170-bfac-42c5-9906-1acb187f0654', '反轰炸', '对敌方的轰炸采取的抗击行动和防护措施的统称。包括使用歼击航空兵、地空导弹兵、高射炮兵打击敌机的作战行动,以及采取隐蔽、伪装、电子防御等措施。', 91);
INSERT INTO `t_military_term_data` VALUES ('7a21e755-b7a6-45dc-a210-b2813af54bf8', '06a75831-13a1-4660-870a-455bb445336a', '单边带电台', '发送、接收调幅信号两个边带中一个边带信号的无线电台。每个边带可传输一路话、多路报或低速数据。节省频谱,便于多路复用。', 182);
INSERT INTO `t_military_term_data` VALUES ('7a2ae29b-a8b7-4c32-aae9-d13b8d1aca08', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役力量', '用于完成战役任务的各种力量的统称。主要指参战的诸军兵种部队以及配合战役行动的武警部队、民兵等。', 20);
INSERT INTO `t_military_term_data` VALUES ('7a330b36-7838-4fda-bbd2-1d5df0a07925', '916997ee-6728-4c61-9b79-d96960b1dc86', '人防三防', '人民防空中对核、化学、生物武器的防护。是人民防空的组成部分。主要包括：普及三防知识,开展三防训练,建立核、化学、生物武器袭击警报报知系统,完善人防工事的三防设施,建立人防三防专业队伍等。', 149);
INSERT INTO `t_military_term_data` VALUES ('7a38aaa0-2146-499e-b833-f6e7aa299e2a', 'f0140091-c11a-48c9-8836-8aa94439dac0', '滚进', '单兵卧于地面滚动身体移动位置的动作。通常在敌火下通过棱线或横向变换射击位置时采用。', 110);
INSERT INTO `t_military_term_data` VALUES ('7a45f670-cdec-4e03-ad0e-2ec3f3796f3e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战地区', '军队作战行动所及的范围。包括陆地、空中和海洋。', 177);
INSERT INTO `t_military_term_data` VALUES ('7a643d70-76d4-4973-9d65-1dd027791318', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事思想史', '关于军事思想的产生及其发展的历史。是军事历史学的重要研究内容。', 37);
INSERT INTO `t_military_term_data` VALUES ('7a6ff66e-518c-46b8-9df1-38331dbb5116', '97a19170-bfac-42c5-9906-1acb187f0654', '空中截击线', '指挥机构确定的歼击机战斗起飞后开始拦截和攻击敌航空器的位置线。主要根据敌情、作战任务、兵力部署、飞机性能和引导保障等条件确定。', 193);
INSERT INTO `t_military_term_data` VALUES ('7a7383c0-1a85-4fd1-b609-b6db3ba3789a', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达干扰设备', '用以发射或转发干扰电磁波,破坏和扰乱敌雷达工作的雷达对抗设备。按干扰作用，分为压制式干扰设备、欺骗式干扰设备和具有压制、欺骗两种功能的双模干扰设备；按工作原理,分为引导式干扰设备和回答式干扰设备。', 126);
INSERT INTO `t_military_term_data` VALUES ('7a7906d3-36db-4f7a-b0e0-8c0cdd3732da', '8a761efd-50a6-4ac8-9913-b7d745104f82', '掉弹头', '射击武器在供弹过程中弹丸从弹壳内脱出的射击故障。', 143);
INSERT INTO `t_military_term_data` VALUES ('7a7f778a-fe1d-4b7d-a2bb-4656f2a96386', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '系船浮筒', '亦称水鼓。浮于水面并用锚链系在水底重锚上的鼓形系船设备。通常布设在港内外锚地。有的具有通水、通电、通油、通话的功能。', 394);
INSERT INTO `t_military_term_data` VALUES ('7a82294b-8d33-46f8-b0f6-1259aa550cca', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '敌后', ' 战时敌人的后方地区。', 293);
INSERT INTO `t_military_term_data` VALUES ('7a8f1ffd-e82e-4274-993b-ad0c5999e7ad', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵技术装备', '防空兵编制内构造复杂、技术性较强的装备。如火炮、导弹、雷达、指挥仪、机动车辆及情报指挥系统等。', 101);
INSERT INTO `t_military_term_data` VALUES ('7a92499f-57a5-4d41-8756-4af5bc258fb4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火箭弹', '以火箭发动机推进的非制导弹药。由战斗部（弹头）、推进装置和稳定装置组成。有火箭炮发射的火箭弹、单兵发射的反坦克火箭弹、航空器发射的火箭弹和舰艇发射的火箭弹等。主要用以攻击面状目标。', 312);
INSERT INTO `t_military_term_data` VALUES ('7a957011-12e2-4316-8bd9-5b2c182dfcac', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '洪水', '由流域内的暴雨、冰雪速融或河口区风暴潮等引起的江河流量激增、水位暴涨的现象。洪水过程通常以洪峰、洪峰流量和洪水过程线等要素来描述。山区发生的洪水可造成破坏力极强的泥石流。', 116);
INSERT INTO `t_military_term_data` VALUES ('7a9c0dc6-2204-4bcb-9b15-abce07bfd865', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '反电子干扰', '简称反干扰,亦称抗干扰。为降低或消除敌方电子干扰对己方电子设备（系统）使用效能的影响而采取的措施。包括反电子干扰技术和反电子干扰战术。', 97);
INSERT INTO `t_military_term_data` VALUES ('7a9dff31-2605-4182-8222-8a3d770b5125', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '汛期', '一年中江河水位有规律地显著上涨的时期。一般由降雨、积雪融化、河冰解冻引起。分为春汛（凌汛）、夏汛（伏汛）和秋汛。不同地区的河流,汛期出现的时间、次数、历时、水位和流量等各不相同。', 115);
INSERT INTO `t_military_term_data` VALUES ('7aa45c36-91e2-4e40-9dd9-6e8ad68a2780', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '船舶气象仪', '设置在舰船上的自动气象观测设备。以微型计算机为核心,由传感器、模／数转换器。控制器、显示与输出接口等部分组成。主要测量风向、风速、气温、气压和湿度等。', 106);
INSERT INTO `t_military_term_data` VALUES ('7aaa4db8-a7d9-41f6-ac34-04ca45ea020f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇抗风力', '舰艇在保证安全航行的条件下可承受的最大风力的能力。是舰艇战术技术性能要素之一。通常以蒲氏风级或极限风速表示。', 329);
INSERT INTO `t_military_term_data` VALUES ('7aac73ac-885f-412a-a85c-c671fd93d74e', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '山顶', '山的最高部位。有平顶、圆顶、尖顶等形态。在地形图上,有的以数字表示山顶的高程。', 12);
INSERT INTO `t_military_term_data` VALUES ('7ab42a6d-6c7b-40c3-b359-8132bea58584', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军衔肩章', '佩戴于军衣肩上、表明军人军衔的标志。', 139);
INSERT INTO `t_military_term_data` VALUES ('7ad20fea-e60f-46b1-8bb1-5dcbbce5ce88', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战', '武装力量打击或抗击敌方的军事行动。泛指战争、战役、战斗范围的各种类型、形式、样式的作战。', 110);
INSERT INTO `t_military_term_data` VALUES ('7afa4c14-97a1-47b8-929d-ccee4f016dde', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机超载', '直升机实际装载的人员、武器装备、物资的总重量超过直升机最大载重量的状况。', 14);
INSERT INTO `t_military_term_data` VALUES ('7b1085ef-01a0-4409-b3b4-be6efc93e66a', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹导引方法', '地空导弹制导系统按运动学的原理将导弹导向目标的方法。有追踪法、平行接近法、比例导引法、三点法和前置法等。', 198);
INSERT INTO `t_military_term_data` VALUES ('7b12f17b-1e39-4f74-b67c-7bd46c52df65', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵低射界射击', '炮兵用等于或小于45度的射角实施的射击。是炮兵射击的基本方法。', 191);
INSERT INTO `t_military_term_data` VALUES ('7b17f2ff-2fc4-49d0-93ea-695e3675d3de', '98df76fb-4b65-48ff-a56c-4db587327c79', '火线抢救', '亦称阵地抢救。在战斗现场对负伤人员实施的急救活动。通常要求迅速寻找和隐蔽伤员,及时正确地进行急救,尽快地送下火线。', 199);
INSERT INTO `t_military_term_data` VALUES ('7b1d52c1-db21-4fd5-aaf8-093d8b23ddd8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海洋法规', '有关各种海域的法律地位和各国在各种海域从事航行、资源开发利用、海洋科学研究等活动,以及海洋环境保护方面的法律规范的统称。主要包括有关内海、领海、毗连区、专属经济区、大陆架、公海、国际海底、用于国际航行的海峡等海域的一系列法律、法规、规章等。', 371);
INSERT INTO `t_military_term_data` VALUES ('7b37a71d-b0dc-418f-824a-3b35ceefd0af', '97a19170-bfac-42c5-9906-1acb187f0654', '盘旋', '飞机在空中某一水平面上所作的等速圆周飞行。按飞行坡度,分为小坡度盘旋、大坡度盘旋和最大允许坡度盘旋。', 239);
INSERT INTO `t_military_term_data` VALUES ('7b3abdac-438d-4463-8ad4-c3087c0e1346', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆三防装置', '装甲车辆上用于防护核、化学和生物武器的杀伤和破坏的装置。分为超压式三防装置、个人式三防装置和混合式三防装置3种。超压式三防装置由辐射、毒剂报警器,增压风扇。门商关闭机,滤毒通风装置及其控制机构和密封部件等组成；个人式三防装置由个人防护面具和辛用的滤毒通风装置组成；混合式三防装置是超压式和个人式三防装置的有机组合。', 137);
INSERT INTO `t_military_term_data` VALUES ('7b3b6774-c174-40ae-9ca8-f66f53880264', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '相控阵雷达', '控制阵列天线各辐射单元的馈电相位,使天线波束在空间快速扫描的雷达。具有多功能、高数据率、多目标处理、覆盖空域大、作用距离远等特点。主要用于战略预警、武器火控、飞行管制、靶场测量、炮位侦察等方面。', 94);
INSERT INTO `t_military_term_data` VALUES ('7b56caa4-7e5f-42c9-9e67-3b9f2e490978', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击目标要素', '反映核打击目标情况的主要因素。主要包括：目标的价值、性质、分布、幅员、结构特点,目标区域的地理状况与气候特点,目标的防御设施和坐标等。', 159);
INSERT INTO `t_military_term_data` VALUES ('7b6b7d0d-6160-4e2f-ac26-2a0ddaaa14ea', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '精简整编', '军队以提高战斗力和工作效能为目标,以减少机构和人员为主要内容的体制编制调整。', 77);
INSERT INTO `t_military_term_data` VALUES ('7b71a1c9-89a6-4232-bf31-a3c76d07ebae', '878651de-adf5-4c72-9376-9c363b893ff8', '国家战略', '筹划和指导国家安全与发展的总体方略。是国家根本利益的集中体现和制定军事战略的基本依据。', 52);
INSERT INTO `t_military_term_data` VALUES ('7b72c36c-e9ca-4604-936e-f3bc78843d93', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '返回轨道', '航天器从离开运行轨道开始至降落在地球表面过程中的质心运动轨迹。', 243);
INSERT INTO `t_military_term_data` VALUES ('7b83d726-7a1c-479b-986a-b5fba1cdcf6c', '06a75831-13a1-4660-870a-455bb445336a', '协同通信', '为保障协同作战，按协同关系建立的通信联络。包括执行共同任务并有直接协同关系的各部队之间、军兵种之间以及部队与民兵之间等建立的通信联络。通常由组织协同动作的司令部统一组织,有时也可由上级指定的协同某一方负责组织。', 10);
INSERT INTO `t_military_term_data` VALUES ('7b85806d-438d-42bb-b215-4a74d5d3432a', 'f0140091-c11a-48c9-8836-8aa94439dac0', '接敌运动', '部队接近敌人,由进攻出发阵地向冲击出发阵地前进的行动。要求队形疏散,行动迅速、隐蔽,并组织火力掩护。', 179);
INSERT INTO `t_military_term_data` VALUES ('7b8a5c09-fa2e-4e48-b5b0-5ec0f00606aa', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '奖章', '国家和军队授予有功人员的荣誉证章。中华人民共和国奖章,1955年由国务院颁发,国防部长授予。有八一奖章、独立自由奖章、解放奖章3种,分别授予中国人民解放军在土地革命战争时期、抗日战争时期、解放战争时期没有获得八一勋章、独立自由勋章、解放勋章的作战有功人员。中国人民解放军奖章,始于土地革命战争时期,种类繁多。中华人民共和国成立后,颁发的奖章有：英雄模范奖章（分二级、一级）,分别授予二级英雄模范、一级英雄模范；立功奖章（分三等功、二等功、一等功）,分别奖给三等功、二等功、一等功获得者。', 66);
INSERT INTO `t_military_term_data` VALUES ('7b8f9eb4-1ef3-4691-a425-689493b7126c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '次口径炮弹', '弹丸直径小于发射该种炮弹的火炮口径的炮弹。分为在飞行中脱壳次口径炮弹和不脱壳次口径炮弹。穿甲弹多为次口径炮弹。', 322);
INSERT INTO `t_military_term_data` VALUES ('7ba6f81b-d735-4c1e-bf5f-aac13fe509bb', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '生物战', '亦称细菌战。使用生物武器伤害人畜、毁坏农作物等的作战。', 150);
INSERT INTO `t_military_term_data` VALUES ('7bb87f0b-47a5-4c70-9d09-64b98bc521b9', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '中程导弹', '射程为 1000～ 3000公里的导弹。', 7);
INSERT INTO `t_military_term_data` VALUES ('7bb90945-db68-401a-9f03-b7c61721a514', '8a761efd-50a6-4ac8-9913-b7d745104f82', '瞄准点', '瞄准线指向目标或参照物上的一点。射击的武器和条件不同,瞄准点也不同。', 10);
INSERT INTO `t_military_term_data` VALUES ('7bbbef61-dece-497f-aca8-2e2d6e4b2b5f', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '水声对抗', '亦称声纳对抗。为削弱、破坏敌方水声设备和声制导武器的使用效能,保护己方水声设备和声制导武器正常发挥效能而采取的各种措施与行动的统称。', 4);
INSERT INTO `t_military_term_data` VALUES ('7bca3936-7c14-43af-adc8-fb15872751ad', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '积极防御', '积极主动的攻势行动对付进攻之敌的防御。通常体现为在战略防御中采取积极的战役、战斗进攻行动，或在战役、战术防御中采取阵前出击、火力反击、反冲击、反突击、反空降、纵深打击等各种攻势行动,以消耗和歼灭敌人，为转入反攻和进攻创造条件。', 395);
INSERT INTO `t_military_term_data` VALUES ('7bd6a2bf-7da6-4512-8ce7-6072e106c2c5', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '筑城', '①筑城工事、筑城障碍物及其组成的阵地工程体系的统称、分为永备筑城和野战筑城。②构筑筑城工事、筑城障碍物等阵地工程的行动。', 37);
INSERT INTO `t_military_term_data` VALUES ('7bdbbc01-30c8-4309-a24c-76ac273b706c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '预备工程兵', '在建制上直接隶属于军区以上单位的工程兵。通常集中使用，多用以遂行战略、战役工程保障任务或作为战略、战役工程兵预备队，必要时可加强给主要方向上的合成军队。', 2);
INSERT INTO `t_military_term_data` VALUES ('7bdd0c19-54cb-4c34-89ff-275c3a2f4dce', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥自动化网', '实施指挥自动化的专用计算机网络。能传输文电、报表、数据、图像等,并具有信息处理、网内资源共享和加密等功能。', 174);
INSERT INTO `t_military_term_data` VALUES ('7bdfab0e-7d9b-4299-905e-a0e85a6d57ef', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军务', '①军队的编制、兵员、行政、装备方面的管理事务。②泛指军队的各种事务。', 7);
INSERT INTO `t_military_term_data` VALUES ('7bebe309-c473-4e79-92a9-8fc6ff56bb7a', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军人仪表', '军人的仪容外表。要求整洁、端庄、振作、威武。', 45);
INSERT INTO `t_military_term_data` VALUES ('7bf56f44-3903-492c-9b47-7f3d9509a5b5', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程保障', '军队为顺利遂行作战任务在工程方面采取的各项保证性措施和进行的相应活动的统称。分为战略工程保障、战役工程保障和战斗工程保障。', 9);
INSERT INTO `t_military_term_data` VALUES ('7bffd45f-49a3-4b0e-baa4-cfbf135cab8e', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '危险天气', '危及军事活动和军队人员、武器装备、军事设施安全的大气。主要指达到规定标准的恶劣能见度、低云、大风、积雨云、雷暴、冰雹、龙卷、沙暴、雪暴、雨淤、强降水、强寒潮等。危险天气标准通常由各军兵种具体制定。', 66);
INSERT INTO `t_military_term_data` VALUES ('7c08539a-d66e-4be1-aae4-ef8e5e33612a', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '干扰样式', '有源电子干扰的信号形式。通常指干扰的调制样式。如连续波干扰、脉冲干扰、调幅干扰、调频于找、调相干扰等。对某种电子设备能产生最佳干扰效果的干扰信号形式称为最佳干扰样式。', 77);
INSERT INTO `t_military_term_data` VALUES ('7c0a071a-3947-4e2c-83c4-7e5d35a31bd6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '水准测量', '根据水平视线原理,利用水准仪和水准标尺测定地面两点间高差的测量方法。主要用以建立国家和地区的高程控制网。', 178);
INSERT INTO `t_military_term_data` VALUES ('7c11cd28-f80b-4e7b-823e-eef0258ad932', '97a19170-bfac-42c5-9906-1acb187f0654', '航空炸弹', '能从航空器上投掷,无航行动力装置的爆炸性弹药。分为非制导航空炸弹和制导航空炸弹。主要包括：爆破炸弹、杀伤炸弹、杀伤爆破炸弹,燃烧炸弹、爆破燃烧炸弹、油气炸弹,穿甲炸弹、穿破炸弹,照明炸弹、照相炸弹、标志炸弹、烟幕炸弹以及宣传炸弹、训练炸弹等。通常由弹体、弹耳、装药、安定器等组成。', 319);
INSERT INTO `t_military_term_data` VALUES ('7c19aa85-c07d-4f9b-87b5-ac53bf569337', '06a75831-13a1-4660-870a-455bb445336a', '通信车', '装有通信设备用以保障通信联络的专用车辆。包括无线电台车、接力通信车、散射通信车、卫星通信车、载波车、电话车、电报车、传真车和线缆收放车等。', 189);
INSERT INTO `t_military_term_data` VALUES ('7c19ec9a-3a13-4d6c-9629-3f20c716861d', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '离休', '中国人民解放军中的在中华人民共和国成立以前参加革命工作的干部，离开工作岗位休养。', 160);
INSERT INTO `t_military_term_data` VALUES ('7c21eb13-1e54-4ad8-a07b-8dcaabe57b95', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '扫雷器', '主要用于地雷场中开辟通路的扫雷器材。分为机械扫雷器、爆破扫雷器和磁扫雷器。', 175);
INSERT INTO `t_military_term_data` VALUES ('7c259b77-f024-481e-b28e-c0994f7b1ebb', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '短延期引信', '撞击目标后延迟较短的一段时间引爆弹丸的引信。延迟时间一般为2～300毫秒。主要配用于穿甲弹和杀伤爆破弹。', 334);
INSERT INTO `t_military_term_data` VALUES ('7c2e08fb-0e35-4cbf-8e51-2dbc30989e4b', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役伪装', '为隐蔽战役企图和行动而采取的欺骗敌人的措施。主要方法有：利用天然条件伪装和实施人工技术伪装,以及采取虚假行动等。', 46);
INSERT INTO `t_military_term_data` VALUES ('7c39d3b5-b653-4a73-acf5-6d9360762cfe', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '远距离照相机', '拍摄远距离目标的摄影仪器。拍摄距离为千米以上,镜头焦距大于500毫米,可用大尺寸胶卷拍摄大画幅照片。通常分为地面远程照相机、航空照相机和航天照相机。军事上用于侦察和测绘地图等。', 76);
INSERT INTO `t_military_term_data` VALUES ('7c3b4861-ff8f-4782-b8b3-fe8d1c8fb3b3', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '猎雷武器', '对水雷进行探测、定位并逐个予以识别和消灭的反水雷武器。由猎雷声纳、高精度导航定位设备。猎雷综合显控系统和灭雷具等组成。通常装备在猎雷舰艇上。', 224);
INSERT INTO `t_military_term_data` VALUES ('7c3d0d2c-c72c-4ef8-9241-f24da8b967a0', '97a19170-bfac-42c5-9906-1acb187f0654', '复杂气象飞行', '飞行员在看不清或看不见地标或发光点的气象条件下的飞行。分为昼间复杂气象飞行和夜间复杂气象飞行。包括云中的飞行、云量8成以上的云上飞行以及能见度小于规定的云下飞行。', 225);
INSERT INTO `t_military_term_data` VALUES ('7c4086bd-2cc1-4181-81d4-9a6deba23b1d', '97a19170-bfac-42c5-9906-1acb187f0654', '航空技术装备翻修', '对使用到规定时限或超过规定损耗标准的航空技术装备进行的较为全面、彻底的修理。目的是恢复航空技术装备的性能和可靠性。通常在航空修理工厂或其他指定的维修机构内进行。', 448);
INSERT INTO `t_military_term_data` VALUES ('7c46afdc-cb3b-4eb8-9dcd-9b826fd12b8a', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '意图', '希望达到某种目的的基本设想和打算、上级意图是下级工作或行动的基本依据。', 65);
INSERT INTO `t_military_term_data` VALUES ('7c4af34e-042e-421e-8c6a-2973193fef06', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '桥梁抢修', '快速修复或加固桥梁的工程作业。方法有应急处理、局部修补、上部结构整体抢修、下部结构整体抢修等。', 291);
INSERT INTO `t_military_term_data` VALUES ('7c4b4075-f5d9-4a32-a839-776c43d97a4e', '97a19170-bfac-42c5-9906-1acb187f0654', '空中加油机', '专门用于空中给飞行中的飞机及直升机补给燃油的军用飞机。通常由运输机或轰炸机改装而成。', 293);
INSERT INTO `t_military_term_data` VALUES ('7c522bc1-7693-42d7-8af8-5dc1a969bed6', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵指挥所', '炮兵指挥员及其指挥机关实施作战指挥的临时性机构。分为基本指挥所、预备指挥所、前进指挥所等。', 87);
INSERT INTO `t_military_term_data` VALUES ('7c57cc40-896b-40e9-8844-8e4c481feb6f', '06a75831-13a1-4660-870a-455bb445336a', '共电式电话机', '由共电交换机集中供给通话和呼叫信号电源的电话机。结构简单,使用方便,但对线路要求较高。适用于部队和军事机关内部电话通信。', 201);
INSERT INTO `t_military_term_data` VALUES ('7c5b6da5-9986-4e11-9101-3ff10a85f5ed', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '水文预报', '陆地水文预报的简称。对某一水体在未来一定时段内的水文状况作出的预测报告。内容包括对洪水、枯水、冰情、台风暴潮和沙量的预报等。按水体和范围,分为河道、流域、区域、河口、水库等的水文预报；按时效,分为短期（数小时至数天）、中长期（数天至一年）和超长期（一年以上）的水文预报。', 122);
INSERT INTO `t_military_term_data` VALUES ('7c637aca-4dbf-4b77-8219-86e1e2baa0fb', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上防御战', '海军或以海军为主体的兵力在海上抗击敌进攻的作战。是海战的基本类型之一。目的是阻止或迟滞敌海上进攻行动,打破其海上封锁,保护海上交通线,掩护己方行动等。', 23);
INSERT INTO `t_military_term_data` VALUES ('7c64681a-6641-4229-9edd-72585816fee2', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '拂晓', '天亮前东方地平线上天空由黑转白的一段时间。', 145);
INSERT INTO `t_military_term_data` VALUES ('7c808cb8-8535-430d-883b-e97f42090456', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '人为电子干扰', '简称人为干扰。由人工制造的各种设备和装置发射、转发、反射或吸收电磁波而造成的电子干扰。分为有意干扰和无意干扰。敌对双方施放的电子干扰都是有意干扰。工业设备、运输工具和家用电器产生的电磁辐射所造成的干扰,以及各种电子设备工作时相互之间造成的干扰属于无意干扰。', 46);
INSERT INTO `t_military_term_data` VALUES ('7c83c3fc-3a36-44dc-b6a5-29dd29f6d561', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察时限', '完成侦察任务的规定期限。通常以将侦察结果传送到下达任务机关的时间为准。', 114);
INSERT INTO `t_military_term_data` VALUES ('7c84d524-92d9-4baa-b287-f1487f42cec7', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸长期效应', '核爆炸瞬时杀伤破坏效应所导致的潜在伤害因素和放射性沾染对自然环境及人员生理和心理产生的长期破坏效果。包括核爆炸放射性沉降中的长半衰期放射性核素造成的潜在威胁以及核爆炸对环境、气候产生的长期破坏性后果所引起的社会效应等。', 176);
INSERT INTO `t_military_term_data` VALUES ('7c89b103-e098-45e0-a365-cd0aaeb714a5', '97a19170-bfac-42c5-9906-1acb187f0654', '空中运输', '简称空运,亦称航空运输。组织和使用运输机、运输直升机或其他航空器输送人员、武器装备、物资的活动。常用以保障空降作战、快速机动兵力和紧急后勤补给等。', 130);
INSERT INTO `t_military_term_data` VALUES ('7ca07dd3-64a5-46ff-abd9-d60733016f5c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '连续波干扰', '发射不间断的连续振荡波形的射频信号所形成的电子干扰。为提高干扰效果,通常对连续波进行各种调制,如调幅、调频、调相或复合调制等。', 58);
INSERT INTO `t_military_term_data` VALUES ('7ca6b163-40ae-47fd-8504-89079c6513cf', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军计划', '组织实施行军的计划。通常依据行军命令的内容及有关规定拟制。', 52);
INSERT INTO `t_military_term_data` VALUES ('7cb3a143-606c-40f1-8388-e40b15bcc266', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸高度', '简称爆高。核武器在地面或水面以上爆炸时,从爆心到地面或水面的垂直距离。', 143);
INSERT INTO `t_military_term_data` VALUES ('7cb89612-4ede-4a5c-a5c4-e6215261d6a8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战对象', '军队与之作战或准备与之作战的敌军。', 115);
INSERT INTO `t_military_term_data` VALUES ('7cd2b456-5c8d-43a5-a94f-b8afa9f79306', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '日没', '太阳落下时其上边缘与地平线相切的瞬间。日没时刻随日期和地理位置的不同而异,可根据所在地理位置和日期在专门编制的“日没时刻表”中查算。', 148);
INSERT INTO `t_military_term_data` VALUES ('7cd65dfc-ba49-4c25-b97a-f07f314de123', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海洋水文气象预报', '亦称海洋环境预报。对一定海域未来一定时段内的海洋水文和天气状况所作的预报。预报内容包括：海浪、海洋潮汐、潮流、风暴潮,水温、盐度、跃层,海冰、海流及气温、气压、风、云、能见度,台风,海雾和其他天气现象等。', 75);
INSERT INTO `t_military_term_data` VALUES ('7cf81820-9916-4873-a6a1-191661fc145b', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军民共建', '中国人民解放军各部队同驻地人民群众共同开展的以社会主义精神文明建设为内容的活动。', 125);
INSERT INTO `t_military_term_data` VALUES ('7d00a9f0-4325-4e7b-a039-855b793b2d20', '8a761efd-50a6-4ac8-9913-b7d745104f82', '存速', '射弹在外弹道上某一点的速度。', 46);
INSERT INTO `t_military_term_data` VALUES ('7d020893-05da-46f5-af60-aad75307f5cb', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队青年工作', '中国共产党在中国人民解放军中以中国共产主义青年团组织为主体开展的适应青年特点的工作。是中国共产党青年工作的组成部分,中国人民解放军政治工作的重要内容。', 48);
INSERT INTO `t_military_term_data` VALUES ('7d2f7a68-13de-4c54-ad92-a1f4d4da90fe', '98df76fb-4b65-48ff-a56c-4db587327c79', '军用饮食供应站', '地方政府在交通沿线为过往部队设立的饮食服务机构。分为常设站和临时站。', 147);
INSERT INTO `t_military_term_data` VALUES ('7d2fd084-5ea0-4f98-a595-71f644b91fb7', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '进攻地带', '陆上进攻作战时,左右两条作战分界线之间从展开地区起至任务全纵深止的作战行动地带。', 86);
INSERT INTO `t_military_term_data` VALUES ('7d468977-be8f-4f01-a980-57f903ef3d0e', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机大队编队', '2～3个直升机中队编队按规定组成的空中编队。', 35);
INSERT INTO `t_military_term_data` VALUES ('7d4aebd4-c7a0-4a3c-960d-7f47e66cc550', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '点火法', '亦称起爆法。使爆破装药起爆的方法。常用的有导火索点火法、导爆索传爆法、导爆管传爆法和电点火法等。', 231);
INSERT INTO `t_military_term_data` VALUES ('7d4b6d01-9b25-4de7-82fb-6e409f3a60b7', '8a761efd-50a6-4ac8-9913-b7d745104f82', '点射', '连发的自动武器每次发射两发以上的断续射击。分短点射和长点射。', 113);
INSERT INTO `t_military_term_data` VALUES ('7d4fc941-02bf-46d4-b546-1e7d3c018e9e', '98df76fb-4b65-48ff-a56c-4db587327c79', '消耗标准', '军队领导机关制定和颁发的单个或集团使用单位在一定时间内或为完成某项任务的物资消耗定额。按执行对象,分为单个消耗标准和集团消耗标准；按执行时机,分为平时消耗标准和战时消耗标准。是组织物资供应的基本依据。', 127);
INSERT INTO `t_military_term_data` VALUES ('7d561374-7d6b-41f6-9691-47df86a013e2', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹战斗弹', '简称战斗弹。供作战使用的导弹。', 17);
INSERT INTO `t_military_term_data` VALUES ('7d5aa721-2595-48cd-9be7-8d1de8f49ce7', '31f4a446-5b98-4873-9d53-310d97125b07', '弹道导弹预警', '对来袭的弹道导弹进行探测并预先发出警报。是战略预警的重要内容。', 31);
INSERT INTO `t_military_term_data` VALUES ('7d69326e-3e73-453a-b49c-95f739708cb5', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮分火射击', '高炮部队或分队在有效火力范围内区分火力同时对数个目标进行的射击。', 169);
INSERT INTO `t_military_term_data` VALUES ('7d72127c-07f4-4b09-90f3-e5c5c688920f', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '声学侦察', '使用声学探测设备进行的侦察。包括声纳侦察、声测侦察和声振传感器侦察。', 61);
INSERT INTO `t_military_term_data` VALUES ('7d78de7e-98f5-446e-b8ea-46b1ea38731d', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军交通艇', '陆军编配的专门为人员提供水上交通的艇。具有较好的稳定性和适航性。艇上配置有供乘员乘坐和救生的设备。', 328);
INSERT INTO `t_military_term_data` VALUES ('7d8221ef-8aa6-42e4-b39a-bbabe6ece947', '8a761efd-50a6-4ac8-9913-b7d745104f82', '突击步枪', '发射小威力的普通口径枪弹或小口径枪弹的自动步枪。口径通常为8毫米以下。比一般的步枪火力猛烈,比冲锋枪威力大。有效射程300～400米。', 164);
INSERT INTO `t_military_term_data` VALUES ('7d8bea17-3c95-4bbc-9f04-aea71ba3bdfa', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上机动编队', '海军遂行海上机动作战任务的兵力编组。可辖若干战术群。通常由战斗力较强、机动性能较好的水面舰艇、潜艇和海军航空兵编成。', 62);
INSERT INTO `t_military_term_data` VALUES ('7d8ca48a-6ead-44f5-8cb6-7901a53265ba', '8a761efd-50a6-4ac8-9913-b7d745104f82', '卡弹', '射击武器的弹药推不进弹膛的射击故障。', 130);
INSERT INTO `t_military_term_data` VALUES ('7d8dd96a-3996-4375-aea5-07fb5c2dc490', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵', '以火炮、火箭炮、地地战役战术导弹和反坦克导弹为基本装备,主要遂行地面火力突击任务的兵种。由加农炮、榴弹炮、加农榴弹炮、迫击炮、无坐力炮、反坦克炮、火箭炮、地地战役战术导弹、反坦克导弹等部队和分队组成。是陆军的主要火力突击力量。用以歼灭敌有生力量,击毁敌坦克等装甲目标和水面舰艇,摧毁、压制敌炮兵和指挥系统,破坏敌工程设施和交通枢纽。通常协同步兵、装甲兵和其他兵种作战,也可单独进行火力战斗。', 0);
INSERT INTO `t_military_term_data` VALUES ('7d9c874f-74bf-4c1c-bd93-a5b1e7640f63', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '测控通信网', '为导弹、航天器的发射、运行、返回传递测控信息及其他信息的通信网。由终端设备、传输信道、交换设备、网路控制管理和软件系统等组成。', 273);
INSERT INTO `t_military_term_data` VALUES ('7db064ae-42c5-4eeb-8039-7f2ff25762f5', '916997ee-6728-4c61-9b79-d96960b1dc86', '集体防护器材', '用于军队和居民集体免受毒剂、生物战剂和放射性落下灰等伤害的防护器材。包括设置在掩蔽部、地下建筑、帐篷、战斗车辆、飞机、舰艇舱室内的气密设施和供给清洁空气的设施等。', 179);
INSERT INTO `t_military_term_data` VALUES ('7db1265c-1413-4ece-81c6-4ff25585c6ca', '8a761efd-50a6-4ac8-9913-b7d745104f82', '落点', '射弹落回地面时弹道与火身口水平面的交点。', 29);
INSERT INTO `t_military_term_data` VALUES ('7dc16184-08e3-4373-8a60-1e25d2c33b7d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮火控系统', '控制高射炮自动瞄准、计算与传输射击诸元,并控制高射炮射击的自动化系统。分为高炮光学人控系统、高炮雷达火控系统和高炮光电火控系统等。', 46);
INSERT INTO `t_military_term_data` VALUES ('7dc28908-9f4e-4353-846e-6c606defe3e2', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵全程作战', '航空兵部队的飞机进行的超过其作战半径的作战。完成作战任务的飞机需在友邻机场着陆加油或空中加油后,才能飞回原起飞机场。', 64);
INSERT INTO `t_military_term_data` VALUES ('7dc7067a-8369-43b8-bae4-e9f2e070e4ab', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '特种侦察', '亦称特殊侦察。特种侦察部队进行的侦察。通常由战区以上指挥机关组织实施。', 10);
INSERT INTO `t_military_term_data` VALUES ('7ddd5f12-6e43-4dc3-b05e-255ec787453e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战文书', '用于军队作战的军用文书。包括命令、通令、指下、计划通知通报、批复、决心图情况图、态势图、工作图注记、密语文书等。', 111);
INSERT INTO `t_military_term_data` VALUES ('7dddd30d-4495-4fad-b592-e81f8be6a12e', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '人-机-环境系统工程', '运用系统工程的理论方法,根据人员、武器装备、作战环境之间相互关系的规律,寻求人-机-环境系统最优组合的工程技术。在军事航天、作战武器系统研制等方面具有广泛的应用价值。', 38);
INSERT INTO `t_military_term_data` VALUES ('7debf230-2770-4790-a732-f56d6216129b', '8a761efd-50a6-4ac8-9913-b7d745104f82', '底火脱落', '射击武器的自动机开锁后坐时,发射后的底火壳从弹壳底火室中掉出的射击故障。', 142);
INSERT INTO `t_military_term_data` VALUES ('7e06995d-3a47-40a3-8074-8da4a31bec2e', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '募兵制', '亦称雇佣兵制。以雇佣方式招募人员参加军队的制度。应募者以当兵为职业,较长期地在军队服役。', 25);
INSERT INTO `t_military_term_data` VALUES ('7e1b20ce-d126-43f9-8e04-2512cee335fe', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹多功能发射车', '安装有导弹起竖设备和发射装置的专用车辆。主要用于导弹的机动发射。分为公路导弹发射车和铁路导弹发射车。是固体导弹武器系统中的基本设备和火力计算单位。', 59);
INSERT INTO `t_military_term_data` VALUES ('7e26c8e5-be69-4ee0-8893-cbc91f49b66c', '916997ee-6728-4c61-9b79-d96960b1dc86', '沾染比活度', '受染物的单位重量中的放射性活度。常用以表示粮食、蔬菜等受放射性沾染的情况。单位是贝可／千克。', 94);
INSERT INTO `t_military_term_data` VALUES ('7e2b22a9-be74-440e-9e0f-3d535174038e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '江河水雷', '布设于江河、湖泊中的陆军水雷。用以封锁江河、湖泊的航道和渡口,切断水上运输线。', 162);
INSERT INTO `t_military_term_data` VALUES ('7e388b98-3e23-4a31-b576-ee422e5ce3e3', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战斗力', '亦称作战能力。武装力量遂行作战任务的能力。由人员和武器装备的数质量,编制体制的科学化程度,组织指挥和管理的水平,各种保障勤务的能力等因素综合决定。也与地形、气象及其他客观条件有关。', 124);
INSERT INTO `t_military_term_data` VALUES ('7e48d329-3bde-4da2-acaa-1408a070a85c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '水陆坦克', '亦称两栖坦克。能自身浮渡,有水上排进装置,可在水上和陆上使用的坦克。重量较轻,装甲较薄。主要用于水网稻田地、强渡江河和登陆作战。', 92);
INSERT INTO `t_military_term_data` VALUES ('7e4b47fd-fbdf-405e-9c7f-ba80f824627a', '97a19170-bfac-42c5-9906-1acb187f0654', '纵深机场', '亦称二、三线机场。远离国境线或战线。位于战役、战略纵深的军用机场。通常进驻轰炸、运输航空兵部队,以及部署战役军团航空兵的第二梯队和预备队。', 415);
INSERT INTO `t_military_term_data` VALUES ('7e503e8a-cbc0-41c8-8500-d2858460b21a', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '夜视器材', '运用红外、激光、热成像等技术，将夜间不可见的景物图像转变成可见图像的器材。包括主动红外夜视器材、微光夜视器材和热成像器材等。军事上用于夜间侦察、瞄准、导航和武器火控系统等。', 78);
INSERT INTO `t_military_term_data` VALUES ('7e74b99e-2674-4db1-867e-342c513c80bc', '06a75831-13a1-4660-870a-455bb445336a', '地域通信网', '由多路传输信道连接若干个干线节点、入口节点、移动通信中心站（台）、单工电台入口设备所形成的覆盖一定作战地域的栅格状通信网。作战地域的固定和移动用户都能进入网内沟通联络。抗毁性能好,机动性强。', 63);
INSERT INTO `t_military_term_data` VALUES ('7e7cbca0-187f-4c2f-923c-b814263d98ac', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机静升限', '直升机在发动机以最大功率工作的状况下能维持悬停状态的最大高度。分为有地面效应静升限和无地面效应静升限。', 19);
INSERT INTO `t_military_term_data` VALUES ('7e7e99fa-e809-4081-ba4d-fc22647178ae', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克乘员避弹所', '坦克乘员的掩蔽工事。由掩蔽室和出入口组成。构筑在坦克掩体的侧面,也可单独构筑在坦克掩体附近的有利地形上。', 42);
INSERT INTO `t_military_term_data` VALUES ('7e8166b9-d362-44c2-98de-e47610a46211', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '毫米波雷达', '工作波长为1～10毫米,相应频率为300～30吉赫的雷达。具有体积小、重量轻、测量精度高等优点，但在雨、雾中的传播损失大,作用距离较近。军事上主要用于炮弹和战术导弹的末制导、对低空目标的跟踪测量和火力控制等。', 98);
INSERT INTO `t_military_term_data` VALUES ('7e8d4151-4440-42b2-8821-3142480ca086', '8a761efd-50a6-4ac8-9913-b7d745104f82', '平均弹着点', '亦称散布中心。平均弹道与目标表面相交的一点。在平均弹着点位置上可能没有实际的弹着点。', 76);
INSERT INTO `t_military_term_data` VALUES ('7e9601b8-7c63-41c7-a4aa-78c66bcd3335', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮火力密度', '高炮部队对进入火力范围内的空袭兵器,在其每千米航程上所发射的平均弹数。以发／千米表示。计算高炮火力密度,可检验战斗部署的正确性和命中目标的可能性。', 155);
INSERT INTO `t_military_term_data` VALUES ('7eb23c73-2e26-47e0-8817-16e1c37a5c35', '98df76fb-4b65-48ff-a56c-4db587327c79', '阵地储备', '作战部队在既设阵地上的物资储备。', 114);
INSERT INTO `t_military_term_data` VALUES ('7eb58478-a8c3-4373-8cd8-b50e8e3edb7b', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵师', '由若干个航空兵团以及机场场站编成的航空兵一级组织。为航空兵的基本战术兵团。通常隶属于军区空军或空军军、空军基地（军级）。', 10);
INSERT INTO `t_military_term_data` VALUES ('7eb64ae2-6f5e-4816-8b20-42e95ae69595', '06a75831-13a1-4660-870a-455bb445336a', '载波增音机', '用以补偿线路传输衰减和均衡频率特性的通信设备。分为有人增音机和无人增音机。设置在有线电长途线路上,用以放大电信号,延长通信距离。', 192);
INSERT INTO `t_military_term_data` VALUES ('7eb95d15-3849-4267-80fc-207a0a9f16c9', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '周表', '亦称周训练计划。一周的军事训练安排表。通常根据本月训练计划表制定。内容包括；训练科目、课题、内容,目的、要求、时间,施训地点·授课教员等。', 32);
INSERT INTO `t_military_term_data` VALUES ('7ebeb7b0-0801-48ce-ba4f-a1466f8fb1b0', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事法规', '①由国家制定或认可的,并以国家强制力保证实施的,用以规范军事领域社会关系与活动的法律、法规、规章的统称。②中华人民共和国的军事立法层次中,专指中央军委独立制定的军事法规和与国务院联合制定的军事行政法规。', 18);
INSERT INTO `t_military_term_data` VALUES ('7ee043db-dac8-4a22-bf43-e79802b4363a', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '卫兵守则', '卫兵值勤时必须遵守的警卫现则。分为卫兵一般守则和卫兵特别守则。卫兵一般守则是各种卫兵值勤时都必须遵守的警卫规则；卫兵特别守则是根据卫兵所警卫的目标的特殊情况而专门制定的特别警卫规则。', 60);
INSERT INTO `t_military_term_data` VALUES ('7ee15941-cfe7-4719-b7ba-fdabdd1ef8c8', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '遥测技术', '对相隔一定距离的被测对象的参量进行检测,并把结果传送到接收地点的技术。通过遥测,可实时监视飞行器和武器装备的工作状态与性能,为指挥控制提供信息,并为改进武器装备的设计提供依据。', 18);
INSERT INTO `t_military_term_data` VALUES ('7eec981f-b7e1-4353-8da6-527bdfb5e657', '878651de-adf5-4c72-9376-9c363b893ff8', '反革命战争', '为维护反动的阶级统治、实行民族压迫或对外侵略扩张而进行的非正义战争。', 25);
INSERT INTO `t_military_term_data` VALUES ('7eedd214-fd57-4e69-b6b2-7f745ed58121', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '轻便炮兵', '装备的火炮重量较轻,便于机动的炮兵。如步兵团、营建制中装备轻型迫击炮、无坐力炮、轻型火箭炮的炮兵。射击准备简单,展开方便,射击快,转移快。', 10);
INSERT INTO `t_military_term_data` VALUES ('7ef7c93f-5bb6-45ce-bc0c-59b6142614df', '97a19170-bfac-42c5-9906-1acb187f0654', '航空机关炮', '简称航炮。专门设计的安装于飞机或直升机上,口径等于或大于20毫米的连发炮。有单管式、转膛式和多管旋式等航空机关炮。', 310);
INSERT INTO `t_military_term_data` VALUES ('7f0fd876-bd83-45c9-a053-5aaddf48f7f3', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '先期作战', '在某种作战全面展开之前,对敌实施一定打击的作战行动。目的是破坏敌人的作战准备,削弱其作战能力,为己方作战创造有利条件。', 178);
INSERT INTO `t_military_term_data` VALUES ('7f17f6ed-9919-432d-9cb1-482c69f18a9b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炸高', '射弹炸点到目标或地面、水面的铅垂距离。', 229);
INSERT INTO `t_military_term_data` VALUES ('7f19c3fa-a980-4553-ac16-70c6e9654eb5', '98df76fb-4b65-48ff-a56c-4db587327c79', '军队房地产权', '后勤机构与保障对象之间在后勤保障活动中所构成的工作关系。', 241);
INSERT INTO `t_military_term_data` VALUES ('7f1a535b-06c6-43f6-8862-a5db37ce9cf9', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '话音干扰', '用音乐声、说笑声、尖叫声等各种声音混合凋制干扰发射机形成的电子干扰。用以扰乱敌方无线电通信人员对通信信号的收听。', 62);
INSERT INTO `t_military_term_data` VALUES ('7f4a05b0-4a08-4e5b-beca-4def1e8dac19', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '岸舰协同', '海军岸防兵与水面舰艇部队为遂行共同的作战任务而进行的协调配合。', 58);
INSERT INTO `t_military_term_data` VALUES ('7f4caa1b-47b7-4fa0-9e9f-d64cd099fbf4', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '救生钟', '援救失事潜艇艇员水下脱险的钟形救生设备。装备在防险救生船上。救生钟内分上室和下室。上室为救生室,内有供排气、注排水系统和通信、照明装置等；下室为救生通道,有裙口可与潜艇救生平台对接进行干救,也可不对接进行湿救。', 247);
INSERT INTO `t_military_term_data` VALUES ('7f67832b-5dd3-465b-a85b-7c5d864a7591', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '天然遮障', '自然界中存在的能对目标起隐蔽作用的遮障。如地貌、地物、雨、雪、雾、风沙等。', 343);
INSERT INTO `t_military_term_data` VALUES ('7f6a39ff-d64e-4d73-a050-51d4f8f511dc', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '激光武器', '利用激光束毁伤目标的武器。由激光器及其能源系统、精密瞄准跟踪系统以及激光束控制与发射系统组成。主要恃点是；以光速射向目标，不必计算提前量；射击精确,不受电磁干扰；威力随距离增加而降低；不能全天候作战。', 46);
INSERT INTO `t_military_term_data` VALUES ('7f7794f8-885b-43d2-86a7-b9c84199a5a4', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击学', '研究合理运用射击武器系统，将射弹射向目标并获得最佳射击效果的学科。内容包括射击理论和射击方法。射击理论主要以概率论和外弹道学为基础,探求如们获得最佳射击效果；射出方法主要措射击的程序、规则和要领。', 4);
INSERT INTO `t_military_term_data` VALUES ('7f7ff64b-dd86-431e-b4c6-9c4ddf3fa1fc', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '空中核爆炸', '简称空爆。爆心在海平面以上不足30千米,且火球不接触地面或水面的核爆炸。按比高不同,分为大比高、中比高和小比高空爆。空爆的毁伤因素主要是光辐射、冲击波和早期核辐射等。毁伤作用与效果视爆炸威力和爆炸高度而定。', 147);
INSERT INTO `t_military_term_data` VALUES ('7f913adf-cc30-474a-9bc7-5dcce06d1a25', '878651de-adf5-4c72-9376-9c363b893ff8', '战略思想', '关于战争全局问题的理性认识。通常表现为国防与战争的指导理论和基本原则。', 56);
INSERT INTO `t_military_term_data` VALUES ('7f965bd2-2b55-441e-8702-1e7710271634', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '士兵军衔', '区分和表明士兵身份等级的称号和标志、通常分为士官、军士、兵3等。中国人民解放军的士兵军衔中,士官分军士长、专业军士,军士分上士、中士、下士,兵分上等兵、列兵。军士长和专业军士军衔,由高至低又各分为四级、三级、二级、一级。有的国家规定士官军衔不属士兵军衔,单独设立。', 134);
INSERT INTO `t_military_term_data` VALUES ('7f9794cc-6ca8-4ab9-bd20-defdbdbfe6f8', 'f0140091-c11a-48c9-8836-8aa94439dac0', '反冲击展开地区', '反冲击的部队或分队展开成战斗队形的地区。通常选择在便于隐蔽占领和向敌侧后攻击的位置。', 233);
INSERT INTO `t_military_term_data` VALUES ('7fcd41b9-4dfa-4be2-b080-28670558b112', '97a19170-bfac-42c5-9906-1acb187f0654', '空情', '空中情况的简称。各种航空器在空中活动的情况。', 391);
INSERT INTO `t_military_term_data` VALUES ('7fceaf7a-6826-4211-81ce-2423dc774545', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '桥梁跨径', '桥梁两相邻下部结构（桥脚、桥础）轴线之间的距离。', 294);
INSERT INTO `t_military_term_data` VALUES ('7fcfb517-f088-4ef4-9e46-1ef26ec92287', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '侵略', '一国或多国对他国领土、主权的侵犯或对他国人民实施掠夺、奴役的行为。', 68);
INSERT INTO `t_military_term_data` VALUES ('7fd63229-fff0-4d02-ba19-92bb7d1e6e68', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克观察瞄准仪器', '坦克上供乘员观察、瞄准用的仪器。包括车长瞄准镜和观察镜,炮长瞄准镜,驾驶员观察镜,装填手观察镜和高射机枪瞄准镜等。分为昼间、夜间和昼夜合一的坦克观瞄仪器。', 123);
INSERT INTO `t_military_term_data` VALUES ('7fd90f3a-137d-4662-afdd-ea27ccb7dc41', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '课外活动', '军人在操课或工作时间以外进行的活动。包括参加集体活动和个人自由活动。', 35);
INSERT INTO `t_military_term_data` VALUES ('7fed77bc-052b-414b-a539-cc86bcf12e4f', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器系统重量', '单件（套）轻武器的全部携行重量。包括发射装置、架座、瞄准装置、规定的携弹量、武器装具、附品工具和备份件等的总重量。是影响机动性能的重要因素。', 214);
INSERT INTO `t_military_term_data` VALUES ('7fedcf2f-62da-4a7d-8825-072e1e9838ef', '06a75831-13a1-4660-870a-455bb445336a', '干线通信枢纽', '设置在通信干线交汇点的通信枢纽。在地域通信网中称为干线节点。作用是汇接和调度各方向的通信线路（电路）,并为附近的指挥所和用户进入通信网提供入口。', 77);
INSERT INTO `t_military_term_data` VALUES ('7fedd4f5-1117-499b-bd65-5a9bbb829b72', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天救生', '载人航天器在飞行中出现危急情况时,使航天员迅速脱离航天器或转移到另一性能良好的航天器中,从而安全返回地面并组织营救的活动。主要包括：发射台和主动上升段低空阶段救生,主动上升段高空阶段救生,轨道运行阶段救生,返回阶段救生和着陆阶段救生等。', 293);
INSERT INTO `t_military_term_data` VALUES ('7ff20816-cf58-49af-993f-a26172acfd21', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击目标群', '在一定的范围内由两个以上核打击目标组成的目标群体。按目标群内各单个目标相互距离,分为疏散目标群和密集目标群；按目标性质,分为城市目标群、工业目标群、军事目标群和混合目标群等。', 160);
INSERT INTO `t_military_term_data` VALUES ('8000533d-f14d-4ba1-b7f7-c72476f1822e', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '高空核爆炸', '亦称超高空核爆炸。爆心高于海平面30千米的核爆炸。高空核爆炸的主要毁伤因素是光辐射、早期核辐射和核电磁脉冲等、可用以摧毁航天器、来袭的核导弹,干扰和破坏电子设备与通信系统等。', 146);
INSERT INTO `t_military_term_data` VALUES ('80087ae0-55e9-4993-a5b3-9b356edc89c0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮射弹散布', '用同一门火炮、相同的弹药,装定同一射击诸元,由同一炮手用相同的操作手法连续发射多发,其弹着点或炸点有规律地散布在一定范围内的现象。', 259);
INSERT INTO `t_military_term_data` VALUES ('800c9cce-f4ee-4ac9-9d6a-5c1fae8c49a1', 'f0140091-c11a-48c9-8836-8aa94439dac0', '防御战斗', '抗击敌人进攻的战斗。是战斗的基本类型之一。按防御的目的和防御准备程度,分为阵地防御战斗、运动防御战斗、机动防御战斗、仓促防御战斗等。还可按地形、气候等条件,分为山地、荒漠草原地、水网稻田地、热带山岳丛林地、高寒地、城市、海岸、岛屿、江河等防御战斗。', 199);
INSERT INTO `t_military_term_data` VALUES ('8010a2a5-b28b-484a-bef0-b5bfb358d786', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹毁伤概率', '表示导弹毁伤目标的可能性大小的量。通常用0～1之间的数值表示。主要取决于：目标的幅员、坚固程度、状态和目标区的地形、气象情况,导弹的精度、威力、可靠性、突防能力,发射时有无干扰,发射区的地形、气象条件等因素。', 150);
INSERT INTO `t_military_term_data` VALUES ('80136425-b453-4868-86b4-2bb4ec473c3f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥自动化系统管理', '为保证指挥自动化系统正常运转而进行的管理。主要包括；指挥控制、通信、情报和电子对抗各分系统的值勤与运作的管理,装备与软件的管理,安全与保密的管理等。', 175);
INSERT INTO `t_military_term_data` VALUES ('802865d7-a6ce-47ad-8fdb-2a909fb3a8dd', '98df76fb-4b65-48ff-a56c-4db587327c79', '部队平均油料基数里程', '部队一个基数的油料按基本耗油标准计算,能供车辆行驶的平均里程。', 173);
INSERT INTO `t_military_term_data` VALUES ('8028ad98-84da-47a0-b086-fa81ef1e2b03', '8a761efd-50a6-4ac8-9913-b7d745104f82', '通用机枪', '亦称轻重两用机枪。装在枪架上能作重机枪使用,离开枪架又能作轻机枪使用的机枪。口径6～8毫米，枪身重7～15千克,枪架重4～20千克,战斗射速100～300发/分。', 170);
INSERT INTO `t_military_term_data` VALUES ('8028dda4-abe0-4aa1-a04f-15e69b7498ca', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机空中编队', '①两架以上的直升机在空中按规定的间隔、距离和高度差组成的编队。②两架以上的直升机在空中进行编队。', 32);
INSERT INTO `t_military_term_data` VALUES ('8037d4b6-3ecb-405a-bd7d-7ac5155dd2bd', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '尽头阶', '连接道路干线,另一端通往军事设施而不再继续延伸的军用道路。对所连接的军事设施进行伪装时,应同时对尽头路实施伪装。', 261);
INSERT INTO `t_military_term_data` VALUES ('8047cc4b-3ee8-4d13-b627-6ef71c6dbc3b', '8a761efd-50a6-4ac8-9913-b7d745104f82', '理论射速', '亦称射击频率。仅依武器自动机运动周期循环时间计算的每分钟内所能发射的平均弹数。半自动武器可由运动周期计算得之,自动武器可由直接连发测得。', 50);
INSERT INTO `t_military_term_data` VALUES ('804d0d28-6817-44c2-bb84-ad5e321e6fc9', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '给水站', '野战条件下供给军队饮水、用水的场所。分为饮用水给水站和机械、车辆、洗消用水给水站等。由水源和取水、水处理、储水、配水的设施及附属设备组成。', 364);
INSERT INTO `t_military_term_data` VALUES ('804fb475-ddfd-433f-bcac-1d2c8ffe2141', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇避碰操纵', '海上航行中控制舰艇以避免相互碰撞的技艺。', 305);
INSERT INTO `t_military_term_data` VALUES ('805b4481-0652-4831-9e6c-bcf11ae0236d', '916997ee-6728-4c61-9b79-d96960b1dc86', '防毒斗篷', '防止毒剂液滴、生物战剂、放射性落下灰降落或飞溅到人体、装具和单兵武器上的个人防护器材。有斗篷式和雨衣式两种。是一次性使用的器材。通常与防毒面具、防毒手套、防毒靴套配套使用。适用于步兵、炮兵等部队。', 178);
INSERT INTO `t_military_term_data` VALUES ('806d3229-5ae4-485a-8381-8f4365869694', '916997ee-6728-4c61-9b79-d96960b1dc86', '辐射侦察', '为查明地面、水域或空中的核辐射分布情况而进行的侦察。包括方向侦察、地域侦察和定点监测。主要用以发现放射性沾染,查明部队行动地域、行军路线以及重要目标的辐射水平,确定沾染区的范围并标志沾染边界。', 43);
INSERT INTO `t_military_term_data` VALUES ('80985fff-de7c-4709-88e9-684874da5ff6', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆运用计划', '部队对车辆的使用、保养、修理、初驶、封存等工作预先做出的安排。分为年度计划和月度计划。', 317);
INSERT INTO `t_military_term_data` VALUES ('80ca12a7-7da6-49d4-91b9-51ae0482d7a8', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行指挥', '飞行指挥员和飞行管制部门对航空器飞行实施的指挥。内容包括：掌握空、地动态和有关情况,适时向航空器发出指令,对飞行进行统一调配控制等。', 187);
INSERT INTO `t_military_term_data` VALUES ('80d1eea2-e6e0-42af-81dc-9a7beccbfd73', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '梯次部署', '将兵力区分为若丁个梯队由前向后依次成阶梯形的作战部署。', 97);
INSERT INTO `t_military_term_data` VALUES ('80e2ee04-42ce-432c-a721-e48604897f37', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵火力侦察', '炮兵用火力诱敌或迫敌暴露目标、以判明目标性质和位置的侦察。通常在其他手段不能达到侦察目的时,报上级批准后实施。', 114);
INSERT INTO `t_military_term_data` VALUES ('80e43e34-b059-42b7-936c-9b4e553788ab', 'd7132c58-5df3-4b97-919f-58740148b9ca', '交替转移火力', '两个以上的防空兵火力单位,对两批或两架以上连续进袭的敌机以相互交错的方式进行射击。通常在敌机批与批或架与架的间隔时间小于各火力单位射击周转时间时采用。', 89);
INSERT INTO `t_military_term_data` VALUES ('80f2a510-dc46-4ddb-8983-d4c0e2d663fc', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '反空降战役', '在己方战略或战役纵深内歼灭较大规模空降之敌的战役。', 61);
INSERT INTO `t_military_term_data` VALUES ('80f667c8-b2c3-49ba-ad66-6fcb5a1b6142', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤指示', '级后勤机关向下级后勤机关厂达的组织实施后勤工作的军用文书。通常由后勤有关业务部门拟制,经后勤首长审查批准后,以后勤机关的名义下发。', 68);
INSERT INTO `t_military_term_data` VALUES ('810cd250-d1eb-489e-ba7f-aaf884acf494', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '箔条投放装置', '装载在飞机、舰艇、车辆上,用以向空中投放或发射箔条等干扰器材的装置。有机电式投放装置、引爆式投放装置和火箭、火炮发射装置等。', 138);
INSERT INTO `t_military_term_data` VALUES ('8110cbda-10b2-49e6-a2b3-dd68c1b1a279', 'f0140091-c11a-48c9-8836-8aa94439dac0', '高寒地战斗', '在海拔高、气候寒冷的地区进行的战斗。易发生冻伤、雪盲和高山反应症,人员体能下降,武器装备使用效能降低,机动和保障困难。', 5);
INSERT INTO `t_military_term_data` VALUES ('811979e7-01d6-427c-b685-41ea88dc62da', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '吊挂飞行', '直升机在机舱下悬挂有装备、物资等情况下的飞行。', 25);
INSERT INTO `t_military_term_data` VALUES ('812e0bf8-16c6-41e2-87eb-e19fa1677166', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '坐标网', '地图上用于确定点位、方向和距离的网格。有地理坐标网和平面直角坐标网。', 273);
INSERT INTO `t_military_term_data` VALUES ('8135f89d-4509-46c3-a146-cc187d46b578', '06a75831-13a1-4660-870a-455bb445336a', '中文电传机', '亦称汉字终端。拍发和收录中文电报的用户设备。由硬件和软件两部分组成。可不用人工编译码,直接输入输出汉字,并具有存储、显示和编辑电文等功能。广泛用于军队指挥自动化和办公自动化等系统。', 207);
INSERT INTO `t_military_term_data` VALUES ('8142c28d-043c-4001-9e2a-3e0c7fd26418', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反空降', '攻歼空降之敌的作战。包括反机降和反伞降。分为战略反空降、战役反空降和战术反空降。', 420);
INSERT INTO `t_military_term_data` VALUES ('81453fae-8f5d-4558-8583-642f8ce894bb', '97a19170-bfac-42c5-9906-1acb187f0654', '前半球攻击', '飞机从空中目标的前方任意角度对其进行的攻击。', 87);
INSERT INTO `t_military_term_data` VALUES ('814b25ad-4aa0-4975-8caa-f06f84ec22ee', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射速', '轻武器、火炮在单位时间内发射弹药的数量。分为理论射速和战斗射速。通常以每分钟内平均发射的弹数表示。', 49);
INSERT INTO `t_military_term_data` VALUES ('81531514-bfd9-4691-a692-bd340c5719b8', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '两栖侦察队', '可在陆地和水上进行侦察活动的专业部队或分队。', 70);
INSERT INTO `t_military_term_data` VALUES ('8153de2f-c886-47ea-914c-acd6bc84f4cc', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '比威力', '核武器威力与其质量的比值。同等威力的核武器（如核弹头、核炸弹）,质量小的比威力高。故常用比威力的量值衡量核武器的小型化水平。', 89);
INSERT INTO `t_military_term_data` VALUES ('815e5246-96c6-4011-b169-6d515d883820', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军徽', '象征军队的标志。中国人民解放军军徽的图案为镶金黄色边的红色五角星,中嵌金黄色“八一”两字。简称“八一军徽。', 137);
INSERT INTO `t_military_term_data` VALUES ('81690f9f-eff9-4cce-8348-3d19500c2d22', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '登陆顺序', '亦称上陆顺序。登陆兵按照预定部署实施登陆的先后次序。', 68);
INSERT INTO `t_military_term_data` VALUES ('816bb735-4ab7-4feb-b49a-a81297f27d0c', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹大地诸元', '与导弹发射阵地和打击目标有关的各项大地测量的数据的统称。主要有发射点和目标瞄准点的坐标与高程,发射点的重力加速度,发射点到目标瞄准点的大地距离和方位角等。', 182);
INSERT INTO `t_military_term_data` VALUES ('816bdb56-88de-4099-b71c-67a4b1feed6d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '水处理', '亦称净水。按用水水质要求对天然水或废水进行的净化过程。分为给水处理和废水处理。', 366);
INSERT INTO `t_military_term_data` VALUES ('817fd8a2-4e93-4367-8129-26cba091b89e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '破坏作业', '用炸药、火、水、机械等破坏军事目标或其他目标的作业。按时机,分为预有准备破坏作业和仓促破坏作业；按行动方式,分为隐蔽破坏作业和强击破坏作业；按破坏程度,分为完全破坏作业和局部破坏作业。', 244);
INSERT INTO `t_military_term_data` VALUES ('8189a252-0fef-409f-854e-b220a11c05f0', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通网', '运输网、邮电网的统称。运输网包括铁路网、公路网、水路网、航空网和管道网等；邮电网包括电信网和邮政网。', 283);
INSERT INTO `t_military_term_data` VALUES ('819ff7b0-4d22-4f66-a61a-3aba93e427ca', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海洋战区', '为制定战略计划和执行战略任务而在海洋上划分的作战区域。通常根据战略意图、海上军事斗争需要和海区状况等划定。', 383);
INSERT INTO `t_military_term_data` VALUES ('81a1e75b-8c48-4bf5-bc64-bcac9726dfcd', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战术侦察', '为获取战斗行动所需情报而进行的侦察。通常由战术指挥员及其司令部组织。', 3);
INSERT INTO `t_military_term_data` VALUES ('81a33eee-0190-48f2-acc4-38a3abaecebb', '06a75831-13a1-4660-870a-455bb445336a', '通信时效', '平均每小时传输的信息量。通常用作机上通报和无线电密语通话、密语通报技能的考核标准之一。机上通报以平均每小时通报的组数计；密语通话、密语通报以平均每小时通话、通报的字数计。', 155);
INSERT INTO `t_military_term_data` VALUES ('81bfc761-bdb0-4736-84bd-806134a93bd6', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克交火距离', '作战双方的坦克能相互直接瞄准射击的距离。距离的远近主要取决于坦克武器系统性能和战场通视程度。', 46);
INSERT INTO `t_military_term_data` VALUES ('81d2cb09-5875-4993-811c-0fba7327c473', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '岸滩侦察', '对岸际和滩头情况进行的侦察。重点查明当面敌情以及岸滩坡度、底质、水位变化、障碍物等情况及其对军队行动的影响。', 23);
INSERT INTO `t_military_term_data` VALUES ('81d48642-4201-4747-972c-7226909ae375', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '透水路堤', '亦称透水路基。允许水流从路面下透过的填石路。适用于路线通过水质较清、流速和流量较小的小河、溪的地段。', 265);
INSERT INTO `t_military_term_data` VALUES ('81dfb70f-5d95-4d21-93d6-abea77db43ac', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '战役炮兵作战', '战役军团编成内的炮兵和加强的炮兵,在合同战役指挥员的统一计划和指挥下,为支援和掩护战役军团作战行动而进行的作战。', 37);
INSERT INTO `t_military_term_data` VALUES ('81f367a7-208c-417e-8095-69028fa76732', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '松散爆破', '利用内部装药爆炸作用使土石破碎、松动而不飞散的爆破。主要用以采集石料、松散岩石和硬土等作业。', 239);
INSERT INTO `t_military_term_data` VALUES ('8208c8b5-22f3-40f7-bb3c-e26bd374459f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '定性分析', '运用经验、逻辑推理和辩证思维等方式研究客观事物的方法。是军事领域内揭示不易用数量指标表示的事物的质的规定性的根本方法。', 178);
INSERT INTO `t_military_term_data` VALUES ('8214215b-65d5-4329-8d78-d5f11901f9a9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '勤务', '担负保障任务的部队或分队所进行的各项专业工作的统称。', 159);
INSERT INTO `t_military_term_data` VALUES ('8215a01f-199b-4f37-80de-6797746f08c8', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '变形地', '地表面因受地壳变动、流水和风化作用或其他影响而改变原来形状的部分。如冲沟、陡崖、陡石山、崩崖、滑坡等。在地形图上用专门符号表示。', 132);
INSERT INTO `t_military_term_data` VALUES ('821695c4-d453-4c2b-a193-e3acb62f4a2a', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军队体制', '军队的组织体系及相应制度。包括机构的设置及其职能划分、相互关系等方面的规定。', 0);
INSERT INTO `t_military_term_data` VALUES ('823559f0-6836-4458-b922-73131f9a7753', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上破交战', '海军兵力破击敌方海上交通线的进攻作战。是海上进攻战的重要样式。攻击的主要目标：在海上交通线航行的敌运输舰船或护航运输队,敌方的海军基地、港口等。', 27);
INSERT INTO `t_military_term_data` VALUES ('8236bd80-411c-4e2a-b765-fbf98f49e483', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇大队', '由若干艘舰艇或若干个舰艇中队编成的海军团一级组织。通常隶属于舰艇支队或水警区,也有的直属于海军基地。一般按其所辖舰种或主要舰种称谓,如护卫舰大队等。', 9);
INSERT INTO `t_military_term_data` VALUES ('8242c381-acdf-4c83-aaea-5089e4ed6b1b', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役实施', '军团从战役发起至结束所进行的全部作战行动。', 33);
INSERT INTO `t_military_term_data` VALUES ('8249eead-0dcf-44bc-a1b9-c5f6424d9554', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹训练基地', '供导弹部队发射训练和作战演习使用的基地。通常建有指挥所、导弹技术准备区、导弹发射场坪或发射井等设施,编有训练机构,配有警戒、观察。控制、通信、指挥等设备。', 79);
INSERT INTO `t_military_term_data` VALUES ('824f7d16-a74d-48fc-b794-6bd542e4fc30', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航海通告', '国家或海军的有关部门定期或不定期地发布有关舰船航行安全事项和航海图书改正资料的出版物。分为长久通告、临时通告和预先通告。', 281);
INSERT INTO `t_military_term_data` VALUES ('825322b4-d5d7-4221-81d2-74b5323c4561', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象雷达', '用于大气探测的雷达。按用途,分为天气雷达和高空探测雷达。天气雷达主要探测降水和云以及雷暴、冰雹等；高空探测雷达可与无线电探空仪配合,测定空中各层的风向、风速、气温、气压和湿度等。', 98);
INSERT INTO `t_military_term_data` VALUES ('82563333-7a57-4c87-9b8c-bb0babd77728', 'd7132c58-5df3-4b97-919f-58740148b9ca', '零位检查', '在对高炮、仪器、器材规正水平、诸元归零后,检查和调整各部划与零位或与起始分划之间差值的行动过程。目的是使各部分划处于标准的起始位置。', 190);
INSERT INTO `t_military_term_data` VALUES ('826926ba-75c1-4503-9031-3d5e4d107dee', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '威慑', '国家或政治集团之间,通过显示武力或表示准备使用武力的决心,以期迫使对方不敢采取敌对行动或使行动升级的军事行为。是军事斗争的一种方式。', 71);
INSERT INTO `t_military_term_data` VALUES ('8278344e-4953-479c-bd24-dabff550f9dc', 'f0140091-c11a-48c9-8836-8aa94439dac0', '坚固防御阵地', '以永备工事为骨干的防御阵地。通常是以预先构筑的坑道（地道）和地面永备工事为骨干,与临时构筑的野战工事相结合,并设置有障碍物配系的阵地。工事较坚固,有完善的战斗、生活和防护设施,便于长期坚守。', 216);
INSERT INTO `t_military_term_data` VALUES ('8296c98c-3ef4-4c52-b642-159746e5de27', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵指挥分队', '保障炮兵作战指挥的专业分队。包括侦察、计算、测地、气象、通信、雷达等分队。', 12);
INSERT INTO `t_military_term_data` VALUES ('829af5de-7729-4f06-9236-2f07fdd1986c', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '谍报站', '由情报机关派出的,开展谍报工作的机构。主要任务是物色、训练和派遣谍报人员,并接收谍报人员所获取的情报。', 74);
INSERT INTO `t_military_term_data` VALUES ('829f7602-6f35-4c25-b9d1-78a8d5234ef0', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹试验基地', '亦称导弹试验靶场。用于导弹的发射、飞行试验,并对试验导弹实施测量控制的基地。包括综合性导弹试验基地、弹道导弹试验基地、反弹道导弹试验基地、战术导弹试验基地等。通常由发射场区、航区和弹着区组成、配有测试发射、测量控制和指挥通信系统的设备和设施,并能对试验结果进行分析评定。', 78);
INSERT INTO `t_military_term_data` VALUES ('82a11817-2fcc-4afb-af9c-afd9baacc0f7', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '军事技术', '直接运用于军事领域的技术科学和应用技术的统称。是构成军队战斗力的重要因素。主要指武器装备研制和生产所涉及的科学技术,发挥武器装备效能的操作使用和维修保养技术,以及军事工程和指挥控制技术等。有时也专指操纵使用武器装备的技能,如射击技术、驾驶技术、飞行技术、电子设备操作技术等。', 1);
INSERT INTO `t_military_term_data` VALUES ('82acaf70-3e58-476f-811a-4f30083b0947', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '转移', '部队、人员、装备或物资等从一地移到另一地的行动。', 333);
INSERT INTO `t_military_term_data` VALUES ('82b38160-dcde-4779-b7d2-0e54e1cea9b8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '退守', '军队放弃原来防守的地方或防御阵地,撤退到指定的阵地继续进行防御作战。', 411);
INSERT INTO `t_military_term_data` VALUES ('82b7a1cb-2a44-431a-b37e-da7d903c0a40', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克野战修理', '在野战条件下为恢复坦克规定的技术状态而进行的修理。主要是对战伤和损坏坦克的抢修。', 214);
INSERT INTO `t_military_term_data` VALUES ('82bfece0-bfba-45c3-9e33-46b1f17270cf', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '野战炮兵', '主要遂行野战任务的炮兵。如预备炮兵、集团军和师建制内的炮兵。', 6);
INSERT INTO `t_military_term_data` VALUES ('82cbc188-3784-41d7-b33c-2b9a0ff60c55', '878651de-adf5-4c72-9376-9c363b893ff8', '战区战略', '筹划和指导战略区的战争准备与实施的方略。', 48);
INSERT INTO `t_military_term_data` VALUES ('82ce6156-5b79-4c02-a3e7-6455036561b0', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵专业技术训练', '装甲兵部队进行的以装甲车辆的射击、驾驶和通信等专业技术为主要内容的训练。根据各专业技术的特点,规定有通过训练达到的专业技术等级。', 69);
INSERT INTO `t_military_term_data` VALUES ('82cefa26-3120-475b-8215-a5f207292198', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸物理模拟', '简称核爆物理模拟。在实验室内创造与核爆炸局部类似的条件对核武器物理问题进行的模仿。模拟手段有流体动力学爆轰实验、脉冲功率技术和激光驱动惯性约束聚变等。', 193);
INSERT INTO `t_military_term_data` VALUES ('82cf3408-c77e-4b0a-b475-97fe80325ca5', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '轨道武器', '亦称轰炸武器。弹头能进入卫星轨道运行一圈以上,在预定点制动,再入大气层攻击目标的导弹武器。运行不到一圈的,称部分轨道武器。轨道武器实防能力强,反导系统对其拦截比较困难。', 15);
INSERT INTO `t_military_term_data` VALUES ('82da59bc-4063-40a6-9540-fc809668bb44', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '组织建设', '中国人民解放军为加强党对军队的领导而在组织方面进行的建设。主要内容包括：建立健全党的各级组织,坚持民主集中制原则,严肃党纪,加强党的组织生活,做好发展党员工作；贯彻党的干部路线；选拔、培养和管理干部,调整配备领导班子；加强共青团组织和连队军人委员会建设。', 24);
INSERT INTO `t_military_term_data` VALUES ('82df8186-f859-4103-a243-1a12a6b784f3', '98df76fb-4b65-48ff-a56c-4db587327c79', '油料基数', '军队油料供应的一种计算单位。分为单项装备油料基数和部队油料基数。根据装备的油箱容量和按标准配发的附属油量规定。', 170);
INSERT INTO `t_military_term_data` VALUES ('82e1ce24-c179-4607-9791-83b86340f124', 'd7132c58-5df3-4b97-919f-58740148b9ca', '放列', '将高炮和仪器由行军状态转为战斗状态的行动过程。', 188);
INSERT INTO `t_military_term_data` VALUES ('82ee8a30-8027-4dfd-9c65-bb8661c531f9', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '绿洲', '亦称沃洲。荒漠中水源丰富可供灌溉,土壤肥沃、植被生长良好,宜于人类生活的地方。多见于河流两岸,泉、井附近及高山冰雪融水灌注的山麓地带,呈带状或点状分布。大的绿洲,农业发达,人口稠密,便于军队宿营和补给。', 38);
INSERT INTO `t_military_term_data` VALUES ('82f19b85-4d62-439b-9856-715a04e98257', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵疏散地域', '炮兵分散隐蔽的地域。', 51);
INSERT INTO `t_military_term_data` VALUES ('82f9b47e-209d-41ae-a0a7-9bb7f22c45c2', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '空防', '国家为保卫主权、领土完整和安全,防备外敌入侵,对领空进行的防卫和管理活动的统称。', 103);
INSERT INTO `t_military_term_data` VALUES ('82fa164c-9fa6-4848-8a0d-e1bbc7bbb661', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方部署', '对后方机关、部队的任务区分、编组和配置。', 50);
INSERT INTO `t_military_term_data` VALUES ('82feae84-7ed4-451f-b19a-90d5c9337261', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军械物资', '军械及使用、保管和维修军械所需的各种机械、仪器、零配件和材料的统称。一般分为通用军械物资和专用军械物资。', 91);
INSERT INTO `t_military_term_data` VALUES ('8306383f-37b4-40da-95c7-8404cab03bfb', '97a19170-bfac-42c5-9906-1acb187f0654', '地勤机组', '在地面相对固定维护一架飞机的航空工程机务人员的编组。歼击机、歼击轰炸机、强击机等小型飞机的地勤机组,一般由机械师和机械员组成；轰炸机、运输机等大型飞机的地勤机组,一般由机械师、机械员和其他专业人员组成。', 19);
INSERT INTO `t_military_term_data` VALUES ('830fa6eb-11be-4e8c-87b3-e8f1b7edd564', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '政治攻势', '中国人民解放军在战时为配合军事打击而对敌方开展的政治宣传活动。主要包括：战场喊话,广播。散发传单、书刊和其他物品等。', 127);
INSERT INTO `t_military_term_data` VALUES ('830fb444-17da-44df-8fec-635264255454', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '军事水文情报', '保障军事活动所需的水文方面的情报。主要包括；水文测验报告、水文预报、各种水文通报,以及说明水文状况的其他报告和资料等。', 121);
INSERT INTO `t_military_term_data` VALUES ('83102a1e-1bca-453e-9973-fc6943710842', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵最大射距离', '炮兵群或炮兵营内距敌最远的炮兵连阵地至射击区域远沿的距离。', 204);
INSERT INTO `t_military_term_data` VALUES ('83164ea7-074c-4544-b802-546fe414b466', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达静默', '在规定的时间和地区内禁止雷达在某些频率或所有频率上发射电磁信号的强制性措施。', 96);
INSERT INTO `t_military_term_data` VALUES ('832c6534-46c5-4732-acce-85242655bf31', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '先机制敌', '抓住有利战机先敌采取作战行动。以克敌制胜。', 228);
INSERT INTO `t_military_term_data` VALUES ('834b2165-04fc-4a7b-8b96-59bd83526b49', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战分界线', '划分相邻部队作战任务区域的界线。通常用数个明显地点之间的连线表示,并明确线上各点的归属和接合部的保障。战术范围内的作战分界线,亦称战斗分界线。', 120);
INSERT INTO `t_military_term_data` VALUES ('836f7ea9-0857-4270-a3de-378853c3375a', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '处分', '对违反纪律的人员按其情节轻重作出的行政处罚决定。中国人民解放军纪律条令规定,对军官、文职干部的处分项目有：警告、严重警告、记过、记大过、降职或降衔、降级（工资档次）、撤职、开除军籍。对士兵的处分项目有：警告、严重警告、记过、记大过、降职或降衔（级）、撤职或取消志愿兵资格、除名、开除军籍。', 72);
INSERT INTO `t_military_term_data` VALUES ('83827bc5-f93a-4829-bcec-4012f1e2a6d2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事同盟', '亦称军事联盟。两个以上国家或政治集团为对付共同的敌人,通过缔结盟约而建立的军事合作关系。如第二次世界大战期间的中、苏、美、英、法等国结成的反法西斯同盟。', 83);
INSERT INTO `t_military_term_data` VALUES ('83859fd5-dca7-4317-a10c-95bbcd389288', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '对进突击', '亦称相向突击。从两个相对的方向向敌之同一目标实施的突击。', 100);
INSERT INTO `t_military_term_data` VALUES ('838ebfde-fd1b-4442-8394-51f7659e3f7a', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '技术保障', '为保持和恢复武器装备的良好技术状态而采取的各项保证性措施与进行的相应活动的统称。主要包括对武器装备及其零部件的供应、保养、检查、维修、改装等。', 116);
INSERT INTO `t_military_term_data` VALUES ('83929d07-31c6-4314-bf07-fcfe986e9850', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '进攻纵深', '军队进攻作战任务的纵向深度。分为战役进攻纵深和战术进攻纵深。', 289);
INSERT INTO `t_military_term_data` VALUES ('83b2dbfe-23db-46b9-af07-4fb3a4318721', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化保障', '为使军队免受或减轻敌核、化学、生物武器袭击的损害而采取的各种保证性措施与进行的相应活动的统称。主要包括：组织实施核观测、化学观察和化学、辐射侦察,组织沾染检查、剂量监督和洗消,及时消除袭击后果,组织指导部队和人民群众的防护,组织防化技术和器材保障,兼顾对生物武器的防护等。通常由各级司令部组织实施。', 15);
INSERT INTO `t_military_term_data` VALUES ('83b53e3b-3051-477e-b6c4-e522254b8b7c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '聚能装药', '亦称空心装药。炸药一端带有空穴或团糟的爆破装药。有些聚能装药的空穴（凹槽）内还带有药型罩。主要用以在目标上穿孔和实施破坏作业。', 226);
INSERT INTO `t_military_term_data` VALUES ('83bb9875-79a5-4c0d-a094-1cf2077d9ea7', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军船艺', '简称船艺。舰艇操纵、舱面作业、舰体保养等技艺的统称。船艺水平是衡量船员军事素质的重要标志。', 301);
INSERT INTO `t_military_term_data` VALUES ('83cd19df-51d2-4061-9ed5-3cb209986047', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战争史', '关于战争的产生和发展的历史。是军事历史学的重要研究内容。', 35);
INSERT INTO `t_military_term_data` VALUES ('83d27054-e4d2-4d47-ae05-c0529f5c48ba', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天器发射', '利用航天运输工具把航天器送入太空预定轨道的过程。分为地面发射、太空发射和空中发射。地面发射,是在航天器发射场使用运载火箭载运航天器起飞并使之进入预定的轨道。太空发射,是利用在太空的航天飞机将卫星等航大器施放到预定的近地轨道。空中发射,是使用大型运输机把悬挂在机翼下的载有人造卫星的空射型火箭带入空中,在适当高度实施投放,再由空射型火箭点火将人造卫星送入预定轨道。', 250);
INSERT INTO `t_military_term_data` VALUES ('83e065b4-6737-4645-9ea5-8276d1de13ed', '0', '装甲兵', NULL, 9);
INSERT INTO `t_military_term_data` VALUES ('83e7a75e-d55c-47ce-b046-59c3deff4356', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报人员', '从事组织侦察和情报处理的人员。', 81);
INSERT INTO `t_military_term_data` VALUES ('83f5d2b8-35cd-48ca-825b-de69f7dc5e80', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '微光侦察', '使用微光夜视器材进行的侦察。主要器材有微光夜视仪、微光电视和微光照相机等。', 51);
INSERT INTO `t_military_term_data` VALUES ('83f62407-2289-4c2e-92de-6fbda5d6d117', '06a75831-13a1-4660-870a-455bb445336a', '通信差错', '值勤人员失职和操作不当等造成的延误通信、损坏通信设备等过失。按情节轻重、时间长短及后果,分为差错和严重差错。', 59);
INSERT INTO `t_military_term_data` VALUES ('84043c72-66e0-47c6-8425-1040d43ceedb', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '光电对抗', '为削弱、破坏敌方光电设备的使用效能,保护己方光电设备正常发挥效能而采取的各种措施和行动的统称。通常有可见光对抗、红外对抗和激光对抗等。基本内容包括光电对抗侦察、光电干扰和光电电子防御等。', 3);
INSERT INTO `t_military_term_data` VALUES ('84070dd9-84eb-4fee-96eb-6178406f3bf1', 'f0140091-c11a-48c9-8836-8aa94439dac0', '袭击', '乘敌不备突然实施的攻击。包括伏击、急袭、奔袭和破袭、偷袭以及袭扰等。', 149);
INSERT INTO `t_military_term_data` VALUES ('8409bbd8-8ecb-4815-af77-97aef6fd17c4', '97a19170-bfac-42c5-9906-1acb187f0654', '起飞线', '机场上飞机起飞时开始滑跑的地方。通常位于跑道一端。', 428);
INSERT INTO `t_military_term_data` VALUES ('840d3a79-38c8-4dc8-aaba-6439901422c8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战方法', '简称战法。遂行作战任务的各种方法的统称。作战方法随着军事技术和武器装备的发展而发展。', 127);
INSERT INTO `t_military_term_data` VALUES ('841a5c4a-b3dd-47f8-ba8a-c07a57bbb0cf', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '三分四定', '部队的战备物资按要求分为携行、运行和后留三类,并在存放、保管和运输中做到定人、定物、定车、定位。', 98);
INSERT INTO `t_military_term_data` VALUES ('8421cd0e-0736-404a-88d1-29cd2033f0f2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事干预', '以军事手段介入国际或国内非军事领域事务的行为。', 61);
INSERT INTO `t_military_term_data` VALUES ('8425d31a-2688-4d18-a9db-1f0c97b000db', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '传统习惯线', '相邻国家在历史上逐渐形成并沿袭下来,但未经正式条约确认的边界线。', 85);
INSERT INTO `t_military_term_data` VALUES ('842daadb-65da-44bd-ae53-144fd0e040ca', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练课题', '对训练科目的具体划分。如对步兵分队战术科目划分为对立足未稳之敌进攻战斗、遭遇战斗、伏击战斗、登陆战斗等训练课题。', 25);
INSERT INTO `t_military_term_data` VALUES ('8434cf18-46fa-4c05-a4bb-69aed3ef0434', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵无线电遥控靶船', '供炮兵训练用的由无线电遥控的水上运动靶标。可直接作为实弹射击目标,也可用以拖曳艇靶。', 301);
INSERT INTO `t_military_term_data` VALUES ('843a82a5-4d64-41fc-8fc2-a86a073df8dd', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '导火索', '以黑火药或烟火药为芯药,用以传递火焰的索类火工品。', 218);
INSERT INTO `t_military_term_data` VALUES ('843ed66a-e4da-4f0b-aaa4-edad9a19937f', '98df76fb-4b65-48ff-a56c-4db587327c79', '军队传染病管理', '军队卫勤部门依法采取的预防、控制和消除传染病发生和流行的工作。是军队卫生防疫工作的重要内容。中国人民解放军按国家现定,将传染病分为甲、乙、丙3类加以管理。', 206);
INSERT INTO `t_military_term_data` VALUES ('8440548c-0924-484b-8d65-fe0e7144c2a8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '反坦克导弹', '用以击毁坦克和其他装甲目标的导弹。是反坦克导弹武器系统的主要组成部分。可从地面、车上和直升机上发射。', 34);
INSERT INTO `t_military_term_data` VALUES ('84427ded-64e5-4141-91ca-2ad14d62c8be', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战斗编组', '将战斗编成内的兵力兵器进行临时性的组合。如担任进攻任务的分队可组成突击队、火力队、爆破队等。', 48);
INSERT INTO `t_military_term_data` VALUES ('84449338-6714-439d-8372-8f5fb9ccd282', '97a19170-bfac-42c5-9906-1acb187f0654', '航空救生设备', '保障飞行人员在紧急情况下安全脱离正在飞行的航空器,并在特殊环境下维护生命的设备。包括弹射跳伞设备、伞上供氧设备、救生船、救生背心以及通信联络用具、急救医疗用品和救生食品等。', 407);
INSERT INTO `t_military_term_data` VALUES ('844ebf55-3fb5-4277-bbea-2d2dd3b7c8b5', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '海岸', '海水面与陆地接触的地带、分为岩石海岸、沙质或砾质海岸、珊瑚礁海岸和红树林海岸等。', 40);
INSERT INTO `t_military_term_data` VALUES ('845895d7-3995-4b1d-809e-481d8dd9e492', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹试验弹着区', '导弹发射试验时弹头落点所在的区域。通常配有搜索、捕获、跟踪、测量导弹弹头飞行及其落点的光学、声学、雷达设备和遥测设备等。试验弹着区可设置在陆上或海上。', 80);
INSERT INTO `t_military_term_data` VALUES ('845e5d4a-7ec8-45d3-b795-070430ae0c76', '98df76fb-4b65-48ff-a56c-4db587327c79', '营房勤务', '组织营房建筑、营产管理、营区环境保护和野营装备供应的专业勤务。主要内容包括：营房建筑的计划、设计、施工与分配,营房、营具及附属设施的管理和修缮,管理军用土地,保护和改善营区的环境,组织战时营房保障,筹措、储备、补给、管理野营装备,组织营房专业的技术和学术研究,培训营房专业人员等。', 232);
INSERT INTO `t_military_term_data` VALUES ('84659e9d-6a1b-4538-b538-088967926e18', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克预备队', '以坦克部队或分队为主编成的预备队。是合成预备队的重要编组形式。', 11);
INSERT INTO `t_military_term_data` VALUES ('84693ddf-783a-4253-ade3-59db67ba99c8', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队机动作战', '导弹部队从某一阵地转移到另一阵地实施的作战。主要目的是提高导弹部队的生存能力和争取作战的主动权。', 15);
INSERT INTO `t_military_term_data` VALUES ('846f7a2d-1beb-4c46-9168-695a2304433b', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '领土', '国家主权所及的全部疆域。包括国家的领陆、领空、领水以及领陆与领水的底土。领土是构成国家的基本要素之一,国家行使主权的地理空间及其人民赖以生存和发展的客观环境。', 69);
INSERT INTO `t_military_term_data` VALUES ('8483664c-6294-4dcb-83cc-0d427eeb1c08', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国界线', '亦称边界线。表示或标明国界的实际位置及其走向的线。', 84);
INSERT INTO `t_military_term_data` VALUES ('8486d366-314b-4ca7-8064-ceee9a525264', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克冲击', '坦克向近距离内的目标迅猛前进,以火力杀伤、车体撞击和履带碾压敌人的战斗行动。冲击中坦克与坦克、坦克与步兵、坦克与炮兵等应协调一致。', 30);
INSERT INTO `t_military_term_data` VALUES ('848a7e16-82d4-4787-ba1b-6863222ae144', '8a761efd-50a6-4ac8-9913-b7d745104f82', '断壳', '射击武器在射击过程中弹壳横断,其前段留在膛内的射击故障。', 135);
INSERT INTO `t_military_term_data` VALUES ('8495c183-3c78-4678-8ad3-b4fe85ee1b4f', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '天然障碍物', '天然形成的和平时为生产、生活而构筑的,战时能够阻止和迟滞军队行动的障碍物。如江河、湖泊、沼泽、陡坡、峭壁、密林、深雪、堤坝、路堑、沟渠、梯、水网稻田等。', 98);
INSERT INTO `t_military_term_data` VALUES ('849bf186-09a9-46e4-929c-259b2bd219b4', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '深度基准', '亦称深度基准面或海图基准面。海图及各种水深资料的深度的起算面。确定深度基准面的原则是,保证舰船航行安全和航道的利用率。', 177);
INSERT INTO `t_military_term_data` VALUES ('84a52e98-fdf8-4752-9ece-b98b4698099f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '要塞', '坚固设防并准备长期坚守的军事要地。一般配置强有力的守备部队,储备充足的物资,形成独立的防御体系。', 304);
INSERT INTO `t_military_term_data` VALUES ('84a78900-0e7a-4219-ba54-ffdf8aed871b', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '无线电侦听', '使用无线电收信器材收听敌方无线电通话,从中获取倩报的方法。', 56);
INSERT INTO `t_military_term_data` VALUES ('84a9f20f-76a0-4f08-974b-f15ef23acf46', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机外挂能力', '飞机所具有的能够在其机身、机翼外部挂载武器装备、弹药的能力。包括能够挂载导弹、航空炸弹、火箭和副油箱等外挂物的种类、数量和重量。歼击机、歼击轰炸机和强击机的机载武器（除航炮外）大多采用外挂方式。', 309);
INSERT INTO `t_military_term_data` VALUES ('84ce8039-01c0-42db-9d5b-2e5089eabed4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '遮蔽顶', '炮兵射击地带内影响射击或观察的遮蔽物的顶端。', 234);
INSERT INTO `t_military_term_data` VALUES ('84d7723d-dad3-4496-81bf-09ab6d268888', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '垂直着陆', '直升机或垂直起落飞机进行的不经地面滑跑的着陆。是直升机、垂直起落飞机的主要着陆方式。对着陆场地条件要求较低。', 41);
INSERT INTO `t_military_term_data` VALUES ('84f6cc29-b538-48ac-bbc4-7edb397aab74', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇', '潜水艇的简称。能游入水下活动和作战的舰艇。按作战任务,分为战略导弹潜艇和攻击潜艇；按动力,分为核动力潜艇和常规动力潜艇；按排水量,分为大型潜艇、中型潜艇。小型潜艇和袖珍潜艇。主要用于对敌陆上重要目标实施核突击,破坏敌海上交通线,攻上敌大中型水向舰船,进行反潜以及侦察、布雷、救援和遣送特种人员登陆等。', 136);
INSERT INTO `t_military_term_data` VALUES ('84fc96f4-6d3c-4376-8c4d-d63dbe13c147', '98df76fb-4b65-48ff-a56c-4db587327c79', '直达运输', '装载点到卸载点,途中无改编和中转作业的运输。', 250);
INSERT INTO `t_military_term_data` VALUES ('850647b3-d867-433f-a566-85ba6e4f7b00', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹突防措施', '为使导弹突破敌方反导防御系统而采取的战术和技术措施的统称、如采取饱和突防和低空突防的战术；运用反识别技术（隐形、诱饵、电子干扰等）,进行抗核加固和抗激光加固等。', 146);
INSERT INTO `t_military_term_data` VALUES ('850f1bc1-43ac-4d7f-b9d0-36616e4e1bd6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '半岛', '伸入海洋或湖泊中的三面临水的陆地。', 54);
INSERT INTO `t_military_term_data` VALUES ('85169c16-d8a0-433a-a982-ce4eabd75164', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克发射阵地', '坦克射击时占领的阵地。通常预先构筑坦克掩体。防御战斗中,除基本发射阵地外,还有预备和临时发射阵地。', 40);
INSERT INTO `t_military_term_data` VALUES ('8527e73a-6f0c-4f11-838d-9ab616363397', '8a761efd-50a6-4ac8-9913-b7d745104f82', '外弹道起点', '火身口的中心点。', 20);
INSERT INTO `t_military_term_data` VALUES ('8533bdca-d6f4-4f99-a479-0a067c51b735', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程兵预备队', '合成军队指挥员掌握的工程兵机动兵力。主要用以执行临时性工程保障任务,替换遭受损失的工程兵部队或分队,加强主要方向上的工程兵力量。', 24);
INSERT INTO `t_military_term_data` VALUES ('85364e96-d296-4b4e-82de-4c514eb202cc', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '兵力部署图', '标绘有兵力编成、配置、任务区分、行动次序等情况的图。', 148);
INSERT INTO `t_military_term_data` VALUES ('8542ddd8-ddd3-42f9-b4d0-484b2ac51199', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '生物技术', '亦称生物工程。运用基因操作和生物反应等技术达到生产生物材料、创造新的生物物种或其他特定目的的技术。主要包括基因工程、细胞工程、酶工程、发酵工程和蛋白质工程等。军事上可应用于制造生物武器或对生物武器的防护等。', 13);
INSERT INTO `t_military_term_data` VALUES ('8549a212-eda6-417f-b33a-a2a030f97d7b', '97a19170-bfac-42c5-9906-1acb187f0654', '伞勤特装', '亦称跳伞装具。空降兵跳伞时专用的服装和随身携带的特种装具的统称。包括跳伞服、头盔。跳伞鞋、护踝、背包、伞兵刀、三用水壶、裆带、背囊等。', 406);
INSERT INTO `t_military_term_data` VALUES ('8552363d-d953-4d82-96b4-94bfd81b2c53', '8a761efd-50a6-4ac8-9913-b7d745104f82', '霰弹枪', '能将许多弹丸、小箭等成柬射向目标的枪。按装填方式,分为非自动式霰弹枪和半自动式霰弹枪。枪管多为无膛线的光膛，口径较大，近距离火力猛,命中率高。弹种有霰弹、榴弹、橡皮弹、催泪弹、烟幕弹、染色弹等。', 180);
INSERT INTO `t_military_term_data` VALUES ('855c5c67-daaf-4be7-963b-7a3f83deae85', '97a19170-bfac-42c5-9906-1acb187f0654', '航空工程机务人员', '亦称地勤人员。军队中从事航空技术装备维修管理和维修作业的人员的统称。通常包括：各级航空装备技术部门负责机务工作的军官,航空兵部队和飞行院校中负责维修飞机的机械师、机械员和维修航空军械、电子设备、仪电设备等的专业师、专业员以及修理机构的修理师、修理工等。', 18);
INSERT INTO `t_military_term_data` VALUES ('856cb859-5e3c-481d-81eb-708e5300e671', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '爱国奉献教育', '以热爱祖国、保卫祖国、关心祖国命运与前途、积极献身军队与国防建设为主要内容的教育。', 94);
INSERT INTO `t_military_term_data` VALUES ('856f14c1-0d69-4b18-a80e-8182139f975d', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮器材标定', '在保持炮身轴线和观测器材定向线不动的情况下,测出并装定某一指定点的方向分划的动作。', 276);
INSERT INTO `t_military_term_data` VALUES ('857cb085-4183-4399-be85-2d23975a87ab', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇规避', '舰艇或舰艇编队在航行或战斗中有目的地避开某一目标的机动、航行中主要是避丹障碍物和危险物,以保障航行安全；战斗中主要是避开敌人的搜索和攻击,以争取主动。', 87);
INSERT INTO `t_military_term_data` VALUES ('8580bcb2-5235-4b71-bd11-e47cbb311d26', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '开放桥门', '将已架设好的浮桥引出一至数个门桥构成桥门的作业。用以保证通航或下泄漂流物。桥门通常设在浮桥位于江河主流线的部位。', 329);
INSERT INTO `t_military_term_data` VALUES ('858c2e44-d005-4985-a575-4273998e64a9', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '合同作战训练', '军兵种部队或分队为提高合同作战能力而进行的训练。包括合同战术训练和合同战役训练。', 87);
INSERT INTO `t_military_term_data` VALUES ('859976fd-3b6d-47df-9b1a-ad10644cdf58', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克严重损坏', '坦克较多的主要机件损坏,不能完成规定功能的严重故障状态。需要消耗大量器材和较长维修时间,方可恢复规定功能。通常须经后方修理基地修复。', 206);
INSERT INTO `t_military_term_data` VALUES ('859a37eb-40a8-40f2-b0e0-3f40c79f2b52', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸效应模拟', '简称核爆效应模拟、利用各种非核爆手段对核爆炸所能产生的效应进行的模仿。模拟手段有化学爆炸模拟、试验室模拟和计算机模拟等。主要用于对防护技术的研究。', 192);
INSERT INTO `t_military_term_data` VALUES ('859cbc42-2c96-4ee3-bf65-cf2698b6d1bd', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '火箭布雷车', '发射布雷火箭弹实施布雷的专用车辆。射程多在10公里以内。每车一次可撒布数百个防坦克地雷,构成正面和纵深各达数百米的地雷场。有的还可布撒防步兵地雷。', 165);
INSERT INTO `t_military_term_data` VALUES ('85c2f5ff-1b01-417e-8930-c66aaef7fa0a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '诱降', '以某种利益作诱饵或设置某种圈套使敌人投降。', 370);
INSERT INTO `t_military_term_data` VALUES ('85c5ec1b-98ba-417c-8f76-ef88709246aa', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '冷战', '第二次世界大战以后,美国和苏联双方之间所进行的除直接武装对抗以外的一切敌对活动的统称。其主要特征是：相互进行核威慑,操纵代理人战争或局部武装冲突,两大政治军事集团长期对抗,激烈的意识形态斗争,国家关系长期紧张,军备竞赛逐步升级等。苏联解体后,美苏冷战关系告逐结束。', 65);
INSERT INTO `t_military_term_data` VALUES ('85c7449c-cd0e-4a1f-8e69-42f8947c8627', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '创造战机', '以积极的行动造成有利于对敌采取作战行动的时机。', 34);
INSERT INTO `t_military_term_data` VALUES ('85cd64f2-332d-45c9-b7bb-b903c4d845e9', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '形象化教学', '采用演示、实验、示范等直观的方法进行的教学。通常利用实物、模型、标本、图表、幻灯、录音、电视、电影、电子计算机等进行。', 155);
INSERT INTO `t_military_term_data` VALUES ('85d7f3ed-03d7-4d05-b4e1-f9b66cc8a85a', '97a19170-bfac-42c5-9906-1acb187f0654', '轰炸航空兵', '以轰炸机为基本装备,主要遂行轰炸地面或水面、水下目标任务的航空兵。通常用以摧毁与破坏敌方战略和战役纵深的目标,参加争夺制空权的斗争等。', 5);
INSERT INTO `t_military_term_data` VALUES ('85db389f-38fd-462f-bfbd-252212cdd44a', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '阵中日记', '中作战时记载每日作战情况的备考文书。内容通常包括,当日气象,敌情变化,本部行动,上级指示和执行情况,本级下达的命令、指示,下级的请示报告和处理情况及其他重要情况等。', 143);
INSERT INTO `t_military_term_data` VALUES ('85df2267-7f90-45ce-bd5f-5d1267c29386', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '轻度', '地面某点的子午面与本初子午面间的夹角。本初子午面以东的称东经,以西的称西经,各由0度至180度。通常用度、分、秒表示。', 204);
INSERT INTO `t_military_term_data` VALUES ('85e3bf94-f704-4cef-906f-67f840b9115c', 'f0140091-c11a-48c9-8836-8aa94439dac0', '冲击开始时间', '从冲击出发阵地或展开地区向敌实施冲击的起始时间、也是冲击信号的发出时间。根据冲击基准时间、冲击距离、冲击速度确定。计算公式为：冲击开始时间＝冲击基准时间一冲击距离（除以）冲击速度', 183);
INSERT INTO `t_military_term_data` VALUES ('85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '0', '军事地理 . 测绘', NULL, 8);
INSERT INTO `t_military_term_data` VALUES ('86291935-d5fe-4f09-ab9e-64d1b9b59c33', '98df76fb-4b65-48ff-a56c-4db587327c79', '供应实力', '被供应的单位及其人员、马匹。武器装备、卫生床位等的实有数。是实施经费、物资供应的基本依据之一。', 107);
INSERT INTO `t_military_term_data` VALUES ('863f4ebc-5edc-459b-a917-c8df21a33e3c', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '海防部队', '驻扎在沿海地区及岛屿,担负防御外敌入侵和制止人员非法越境等任务的部队。', 56);
INSERT INTO `t_military_term_data` VALUES ('8642e9c4-e819-4fb0-bd16-3d00df1f4371', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击地带', '炮兵群或炮兵营如负有射击任务的带状区域。通常分为基本射击地带和补加射击地带。', 214);
INSERT INTO `t_military_term_data` VALUES ('864865ca-efc4-4130-8877-3a768a1381e4', '8a761efd-50a6-4ac8-9913-b7d745104f82', '翼侧射击', '直射武器弹道通过己方战斗队形一侧的射击。', 92);
INSERT INTO `t_military_term_data` VALUES ('864dd9b7-c817-4fc1-a5ca-003a9b68cae7', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '障碍物配系', '将各种障碍物有机配置形成的障碍物系统。通常与火力配系紧密结合,用以阻止、迟滞和消灭敌人,保障防御的稳定。', 94);
INSERT INTO `t_military_term_data` VALUES ('865619a2-7009-4aeb-9daf-ed5bc338507f', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮发射速度', '简称高炮射速。高炮在单位时间内发射的炮弹数。有理论射速（技术射速）、战斗射速（实际射速）和极限射速（安全射速）,均用发／分表示。', 154);
INSERT INTO `t_military_term_data` VALUES ('865cba27-2bfe-4376-9d08-242c91d37f0c', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机下滑攻击', '直升机在下滑飞行状态中以机载武器对敌方目标进行的攻击。通常适用于在狭长地带和山谷里的作战。', 78);
INSERT INTO `t_military_term_data` VALUES ('8660a497-08b5-4787-8f83-74f2e519604b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '探雷', '用探雷器等探测地雷、水雷及其他爆炸物的行动。任务是查明其类型、范围、配置样式和单个地雷、水雷及未爆炸弹等位置,为排雷（弹）提供情报资料。', 195);
INSERT INTO `t_military_term_data` VALUES ('86825af1-7b43-4b18-a0ae-a8413ba6a8e0', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '坑道施工', '坑道工事的定位、掘进、被覆、装修、伪装等作业的统称。', 83);
INSERT INTO `t_military_term_data` VALUES ('86837586-8237-4db6-8406-e44206abe9d5', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '谍报侦察', '亦称秘密侦察。向侦察对象内部秘密派遣或就地发展人员获取重要情报的侦察。通常由战区以上指挥机关组织。', 13);
INSERT INTO `t_military_term_data` VALUES ('8687078f-2443-4ce8-8db5-ebab966062ff', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '正规战', '正规部队采取运动战或阵地战形式进行的作战。', 136);
INSERT INTO `t_military_term_data` VALUES ('868957fc-72ba-4a4a-aa84-a8d6cb090454', '97a19170-bfac-42c5-9906-1acb187f0654', '对空情报雷达', '亦称对空搜索雷达。搜索、监视空中目标并确定其坐标和运动参数的各种雷达的统称。包括对空警戒雷达、引导雷达、测高雷达和目标指示雷达等。', 344);
INSERT INTO `t_military_term_data` VALUES ('868a70fe-05db-460c-922d-4aadb38d3ccc', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '主攻', '亦称主要突击。集中主要兵力、火力在主要方向上实施的进攻。', 84);
INSERT INTO `t_military_term_data` VALUES ('868d9cc2-66ab-44d4-ac9d-a5f79d7a3cb0', '97a19170-bfac-42c5-9906-1acb187f0654', '空中优势', '作战中航空兵的数量、质量和作战指挥等方面的综合对比优于敌方的态势。占有空中优势,便于夺取较大范围和保持较长时间的制空权。', 40);
INSERT INTO `t_military_term_data` VALUES ('86908ed8-46cd-49d4-b992-7923fd0ba65f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军岸防兵', '以岸炮和岸舰导弹为基本装备,部署在沿海重要地段,主要遂行海岸防御作战任务的海军兵种。包括海岸导弹部队和海岸炮兵部队。可突击敌方舰船,保卫基地、港口和沿海重要地段,扼守海峡、水道,掩护近岸海上交通线和己方舰船,支援岛岸和要塞守备部队作战等。', 4);
INSERT INTO `t_military_term_data` VALUES ('86a2a780-524e-4ebd-b743-6cab5ea11071', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '缴械', '①收缴敌方人员的武器装备的行动。②被迫向敌方交出武器装备的行为。', 382);
INSERT INTO `t_military_term_data` VALUES ('86b42892-bcc8-4de6-8ee2-30a1420c3b9b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '立体战', '在陆地、海洋、空中、外层空间同时或交互进行的作战。', 144);
INSERT INTO `t_military_term_data` VALUES ('86bc039d-0b32-43a2-b91b-450ac63806f3', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军地两用人才', '中国人民解放军在官兵中培养的既适用于军队建设又适用于地方建设的人才。', 104);
INSERT INTO `t_military_term_data` VALUES ('86d06c53-7933-4d44-918f-2066973c9d2a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '化装侦察', '侦察人员装扮成群众或敌方人员接近或潜入敌区进行的侦察。', 36);
INSERT INTO `t_military_term_data` VALUES ('86e18516-af54-4b54-a410-6d58fcf59c46', '8a761efd-50a6-4ac8-9913-b7d745104f82', '便携式武器', '便于携行使用的，不依赖车辆牵引或载运的武器。如各种轻武器及轻型迫出炮、轻型导弹等。', 149);
INSERT INTO `t_military_term_data` VALUES ('86e94cc4-e0c9-46d2-90bc-5ff8c3e98aec', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗情报侦察', '对侦察区域内的敌方电子设备进行长期监视或定期核查的电子对抗侦察。目的是全面获取敌电子设备和系统的战术技术参数,查明其部署位置,掌握其活动规律和发展动态,并为电子对抗支援侦察预先提供基础情报。', 20);
INSERT INTO `t_military_term_data` VALUES ('86e95644-aaad-4170-a60b-cd5fa678a55e', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵机动作战', '航空兵部队根据战场的实际情况积极移动兵力,随机灵活地进行作战。通常派出空中机动分队转移到既便于隐蔽,又便于出击的空域或机场,伺机歼敌。', 66);
INSERT INTO `t_military_term_data` VALUES ('86f7c9ae-96a6-406c-8228-794d171350d2', '31f4a446-5b98-4873-9d53-310d97125b07', '核毁伤半径', '亦称核杀伤破坏半径。从核武器爆心或爆心投影点到毁伤区域边缘的距离。毁伤半径与规定的毁伤程度有关。当毁伤程度一定时,毁伤半径主要由核弹头威力、爆炸方式、目标性质、地形和气象条件等因素决定。', 151);
INSERT INTO `t_military_term_data` VALUES ('86fc426b-99bb-467b-95d1-9519635e1423', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '三手活动', '在军事训练中开展的神枪手、神炮手、技术能手活动。是中国人民解放军传统的群众性练兵活动之一。', 163);
INSERT INTO `t_military_term_data` VALUES ('86fcc919-62a3-4c4c-826a-fa049d99661f', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '风向', '风的来向。一般用16个方位或0～360度表示。飞机航行中用的风向,是指风的去向,与气象观测的风向相差180度。', 16);
INSERT INTO `t_military_term_data` VALUES ('87014192-2832-43c7-b1fd-e349199ad244', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '进出路', '连接渡场、工事、仓库等军事目标与接近路的辅助军用道路。', 259);
INSERT INTO `t_military_term_data` VALUES ('870e64e8-b079-4b19-90e9-8ecac98d667e', '8a761efd-50a6-4ac8-9913-b7d745104f82', '早发火', '射击武器在射全过程中,推弹未能入膛到位即被占发的射击故障。', 138);
INSERT INTO `t_military_term_data` VALUES ('872bcd29-7999-48ff-9137-4c4301994f86', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役追击', '对战役退却或溃逃之敌的追击。是战役进攻的继续。', 116);
INSERT INTO `t_military_term_data` VALUES ('872c0004-1cf8-4576-9a62-e1ec380cdd9e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反围攻', '抗击敌人围攻的作战行动。', 417);
INSERT INTO `t_military_term_data` VALUES ('8733a324-428c-4eea-8043-d2c0880414a3', '97a19170-bfac-42c5-9906-1acb187f0654', '空中连续攻击', '多架飞机或直升机对同一空中目标逐批接连进行的攻击。以对目标实施不间断的打击并便于己方的机动飞行。', 83);
INSERT INTO `t_military_term_data` VALUES ('873e6f0c-d8f0-4af7-a517-7c3f90c895ea', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '地球同步卫星', '采用地球同步轨道的人造地球卫星。轨道周期与地球自转周期相同。', 218);
INSERT INTO `t_military_term_data` VALUES ('874e4f5d-e308-40f2-ac3d-07ba5fd466f5', '916997ee-6728-4c61-9b79-d96960b1dc86', '核爆炸闪光盲', '在核爆炸的闪光突然作用下造成视觉功能暂时紊乱的症状。包括视力下降、眼前发黑、眼花、视物模糊、眼睛胀痛,严重的还有头痛、恶心呕吐、植物神经功能紊乱等现象。持续时间为几秒到几小时,一般不经治疗即可恢复正常。', 109);
INSERT INTO `t_military_term_data` VALUES ('874f125f-8d1d-43cd-b794-fec0cc807a70', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克抢救修理所', '简称坦克抢修所。坦克部队战时组织的负责抢救修理的临时性技术保障机构。由修理分队和上级加强的技术力量组成。主要负责对坦克的抢救、抢修和组织修复的坦克归队,并对不能修复的坦克组织上缴后送。', 228);
INSERT INTO `t_military_term_data` VALUES ('87594108-b18a-4610-a182-7eda5875f7df', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '计算机终端设备', '在计算机网络中,经由通信线路向主计算机输入信息或接收其输出信息的装置。通常包括显示设备和输入输出设备。是人与计算机交换信息的重要设备。军事上广泛用于指挥自动化系统等。', 58);
INSERT INTO `t_military_term_data` VALUES ('875b148f-af35-4f1a-aaf5-f2ab468e56f8', '878651de-adf5-4c72-9376-9c363b893ff8', '局部战争', '在局部地区进行的,目的、手段、规模均较有限的战争。相对于世界大战而言。有的国家亦称有限战争。', 10);
INSERT INTO `t_military_term_data` VALUES ('877235a1-a8ea-4be6-b4f2-75b4c83c1c1e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事外交', '国家在军事方面的对外交往活动。是国家外交活动的重要组成部分。如军事人员互访,军事谈判,缔结军事条约,以及处理国际上的军事事务等。', 74);
INSERT INTO `t_military_term_data` VALUES ('8774702f-87d7-48b0-b82f-f7047056cce1', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '报告文书', '向上级反映情况或请示问题的军用文书、包括报告、汇报总结请示等。', 113);
INSERT INTO `t_military_term_data` VALUES ('8774e6d8-46fd-4bdc-a04f-72424a005b48', '97a19170-bfac-42c5-9906-1acb187f0654', '军区空军', '根据作战需要,在军区设置的空军一级组织。隶属于空军,受空军和所在军区的双重领导和指挥。设有领导机关,下辖若干个空军军、空军基地（军级）和一定数量的战斗部队、专业勤务部队。通常作为空军战役军团,主要担负本战区的防空作战、空中进攻作战和协同陆军、海军作战等任务,', 1);
INSERT INTO `t_military_term_data` VALUES ('8775d63f-cdff-4b99-8ee1-8595ebd394b9', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '航空技术', '航空器的研究、制造和应用的技术。主要包括航空器结构、航空发动机、飞行控制、通信与导航、机载武器、安全救生、电子对抗及使用维修技术等。', 6);
INSERT INTO `t_military_term_data` VALUES ('87794017-ce34-428e-bdf7-9c1e5a050fdf', '06a75831-13a1-4660-870a-455bb445336a', '电话站', '接转电话的通信站。按通信距离,分为市内电话站和长途电话站；按交换机的性能,分为人工电话站和自动电话站。主要设备为电话交换机。', 84);
INSERT INTO `t_military_term_data` VALUES ('877cd9f9-5ccb-4d31-9593-969be58ceab4', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '障碍排除队', '进攻战斗中以工兵分队为主编成,随伴部队在障碍物中开辟通路的战斗编组。主要任务是：在敌障碍物中开辟或扩大通路,以保障坦克和步兵的行动。', 23);
INSERT INTO `t_military_term_data` VALUES ('878651de-adf5-4c72-9376-9c363b893ff8', '0', '战争.战略', NULL, 30);
INSERT INTO `t_military_term_data` VALUES ('87873fc0-b733-4fae-8206-db1db17fe358', '97a19170-bfac-42c5-9906-1acb187f0654', '机场防护工事', '构筑在机场及其周围,用于飞机、直升机和人员、设备、物资的防护的各种工事的统称。主要包括飞机防护工事、指挥通信防护工事和其他掩蔽工事等。', 435);
INSERT INTO `t_military_term_data` VALUES ('8789d5d1-760a-4082-b502-4b295db517de', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队团总支', '军队中共青团总支部委员会的简称。中国共产主义青年团在中国人民解放军营或相当于营级的单位设立的基层组织。由共青团员大会或共青团员代表大会差额选举产生,经本级党委同意,报上级团委批准。在共青团委员会、本级党的委员会的领导下和同级首长的指导下进行工作。', 50);
INSERT INTO `t_military_term_data` VALUES ('878a942b-5a05-4081-acf5-f1c7e143741f', 'f0140091-c11a-48c9-8836-8aa94439dac0', '合同战斗', '以某一兵种为主体,诸军兵种、专业兵协同进行的战斗。包括军种之间和同一军种内诸兵种之间进行的合同战斗。', 2);
INSERT INTO `t_military_term_data` VALUES ('87984017-1de5-492d-a280-a2a006adfb2b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '前沿', '阵地或兵力部署最前面的边沿。防御阵地前沿通常指第一道堑壕或最前面诸火力点。', 287);
INSERT INTO `t_military_term_data` VALUES ('879ffafd-6aca-4d85-a4a2-c25583a54c5e', '916997ee-6728-4c61-9b79-d96960b1dc86', '防毒时间', '在规定条件下防护设施或防护器材可对毒剂起防护作用的持续时间。通常是在规定的毒剂种类、浓度、空气流量、温度等条件下测定的,是评价防护设施与器材性能的依据。', 143);
INSERT INTO `t_military_term_data` VALUES ('87cd637a-e7aa-45b5-b22a-cbef1bb36649', '916997ee-6728-4c61-9b79-d96960b1dc86', '外照射', '射线从外部对人体的照射。分全身照射和局部照射。主要是γ射线和中子流的照射。', 100);
INSERT INTO `t_military_term_data` VALUES ('87ce9ac7-1f38-4dc7-a4cf-b29c81564430', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队机关党委', '军队机关或部门中党的委员会的简称。中国共产党在中国人民解放军旅级以上单位的司令部、政治部、后勤部、装备技术部等机关设立的委员会。机关党委在同级部队党委领导下,讨论决定本机关工作中的重大问题和自身建设问题,对直属单位实行统一领导。各级机关党委行使低于同级部队党委一个等级的权限。', 39);
INSERT INTO `t_military_term_data` VALUES ('87cf69eb-0813-44d2-aae9-f38776b65046', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克机动系数', '坦克在作战中实际行驶里程与作战任务纵深（公里）之比。用以计算坦克油料的可能消耗量和技术保养的工作量。', 59);
INSERT INTO `t_military_term_data` VALUES ('87d627c7-7d73-4a88-8aa3-2d44c3e41e8d', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵哨所', '民兵执行观察、警戒勤务的处所。如边防民兵哨所、海防民兵哨所。', 134);
INSERT INTO `t_military_term_data` VALUES ('87d95a84-bca4-46aa-b58c-ae586d70bbe4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵侦察电视系统', '炮兵用以摄取并传送目标图像,以侦察目标、观察战场、校正射击的电视系统。按使用方式,分为地面和航空侦察电视系统；按负载方式,分为单兵背负式、车载式和机载式侦察电视系统等。', 287);
INSERT INTO `t_military_term_data` VALUES ('87ff8b04-dcde-4296-a686-fa908f661072', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '被动测距声纳', '亦称噪声测距声纳。使用大孔径水听器线列基阵测定目标辐射噪声的距离和方位的不纳。主要装备于潜艇。能在不发射声信号情况下测定目标坐标等数据,保障潜艇隐蔽实施鱼雷攻击。', 237);
INSERT INTO `t_military_term_data` VALUES ('8807a76a-2382-47a6-b7b4-50c2ada037a7', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '警戒线', '①警戒范围的边缘线。②各固定哨位之间的连线。', 28);
INSERT INTO `t_military_term_data` VALUES ('88135060-8e4c-483c-90a4-6aa9c4c2c48e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '迫击炮弹', '靠炮弹在炮膛内滑落而迫击发火的炮弹。有尾翼式和旋转式两种。主要用以杀伤敌有生力量和技术兵器,破坏其防御工事及其他建筑物。空心装药的迫击炮破甲弹可用以射击装甲目标。', 325);
INSERT INTO `t_military_term_data` VALUES ('8813b99e-f0b7-4f54-a1eb-4b1331688b75', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '人防专业队伍', '按专业组成的担负人民防空勤务的群众性队伍。主要包括抢险抢修、医疗救护、消防、防化、通信、运输、治安等专业队伍。', 65);
INSERT INTO `t_military_term_data` VALUES ('8820c09a-d6d8-4ddd-912a-3c7e1fb172d8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上补给', '对在海上航行或锚泊的舰艇实施的物资补给。补给方式有航行补给、锚泊补给和漂泊补给。补给的物资包括油料、淡水、食品、弹药、医药用品等。', 350);
INSERT INTO `t_military_term_data` VALUES ('88420746-4202-46d0-89e8-0890c5dfee40', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火掩护', '亦称炮火保障。炮兵为掩护合成军队行动,牵制或压制敌人而实施的火力突击。用以保障合成军队的集结、开进、展开,顺利地进行作战准备。', 73);
INSERT INTO `t_military_term_data` VALUES ('884c0488-5193-49e3-961f-76460d116b9b', '8a761efd-50a6-4ac8-9913-b7d745104f82', '火箭筒', '发射火箭弹的无坐力的便携式反坦克武器。一般由筒身、击发机握把、瞄准装置等组成、本经用以摧毁近距离的装甲目标和坚固工事、有效射程约300米。', 185);
INSERT INTO `t_military_term_data` VALUES ('884ccc63-2875-418c-bfd6-6791da9460e6', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '型钢工事', '用型钢作支撑结构的工事。分为密接配框型钢工事和相间配框型钢工事。相间配框型钢工事使用的被覆材料有柔性和刚性两种。柔性被覆材料有纤维织物等；刚性被覆材料主要有波纹钢、钢板、玻璃钢板、木材、竹材等。', 72);
INSERT INTO `t_military_term_data` VALUES ('884e6733-038d-4c13-8781-9427ef147d7e', '8a761efd-50a6-4ac8-9913-b7d745104f82', '冷兵器', '发射药或炸药,依靠人的体能效应发挥杀伤作用的武器。如戈、矛、戟、剑、刀、锤、钢、棍、刺刀、匕首和弓、箭、弩等。', 150);
INSERT INTO `t_military_term_data` VALUES ('884fcdd4-1be4-4b72-8c83-38c7bc195fe1', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克封存', '对长期存放的坦克采取的一种密封保管方法。分为全车封存和局部封存两类。封存方法有油膜密封、堵塞密封、气相缓蚀剂密封和封套密封等。', 224);
INSERT INTO `t_military_term_data` VALUES ('8850ed98-8bb7-426f-a7aa-0f37e5977f99', '06a75831-13a1-4660-870a-455bb445336a', '代号', '为密化部队番号、指挥员职称及作战计划、军事行动等的真实名称而规定的代称。通常用数码、字母、单词单独编成,也可混合编成。严禁代号与真实名称混用或同时使用。', 150);
INSERT INTO `t_military_term_data` VALUES ('8851c561-94be-448a-b88c-cfbe3a146416', '06a75831-13a1-4660-870a-455bb445336a', '天线', '辐射或接收无线电波的装置。分为发射天线和接收天线。长波至超短波波段通信,一般采用金属导线构成的线状天线；微波波段通信,主要使用金属面构成的面状天线。', 210);
INSERT INTO `t_military_term_data` VALUES ('8855a63f-abce-4eb8-b14a-2d3005f88b95', '0', '体制编制', NULL, 27);
INSERT INTO `t_military_term_data` VALUES ('885efb48-ea8e-456b-b8ca-e3d2d122cf8b', '916997ee-6728-4c61-9b79-d96960b1dc86', '西阿尔', '学名二苯并[b,f][l,4]氧杂吖庚因。主要作用于眼、鼻、咽、皮肤的复合型刺激剂。眼、鼻、咽和皮肤受刺激后,出现流泪、喷嚏和皮肤红斑等多种症状。', 227);
INSERT INTO `t_military_term_data` VALUES ('8862b4f9-f900-4fa8-8671-79fbcd740625', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '暗河', '亦称地下河。在喀斯特地貌区,地表水通过溶洞、裂隙、漏斗渗入地下形成的河流。', 62);
INSERT INTO `t_military_term_data` VALUES ('8868ebe5-4c6d-4b36-81bd-a08fce7cc0a9', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克电气设备', '坦克上供电、用电的装置、器件、仪表的统称。由电源装置、用电装置、辅助器件、检测仪大和车内电路等组成。', 144);
INSERT INTO `t_military_term_data` VALUES ('887343c6-f08c-401c-ae56-0b05ca40c382', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '条令', '用简明条文规定并以命令形式颁布的关于军队战斗、工作或生活方面的法规性文件。如战斗条令、内务条令、纪律条令、队列条令等。', 19);
INSERT INTO `t_military_term_data` VALUES ('8894b7da-3c78-41ff-91e3-265fae673bbf', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵歼灭射击', '炮兵给目标以严重毁伤,使其全部或大部丧失战斗力或指挥能力的射击。要求毁伤程度为50％～6O％。', 175);
INSERT INTO `t_military_term_data` VALUES ('88979fcb-2e52-4d10-98ea-3d00a179ef03', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '晋衔', '按照军官军衔条例和士兵服役条例规定的条件,对现役军人军衔等级的晋升。', 88);
INSERT INTO `t_military_term_data` VALUES ('88ad8e9c-2fc6-44bd-aacb-de71c1936f4b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '占领', '军队进入或夺取某一地方（目标）的行动。', 367);
INSERT INTO `t_military_term_data` VALUES ('88b83b90-f504-4560-9b95-3a7bf3b91575', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克推进系统', '能将燃料燃烧产生的热能转变为机械能,经过传输、控制,使坦克获得机动性能的联合装置。由动力、传动、行动和操纵等装置组成。', 124);
INSERT INTO `t_military_term_data` VALUES ('88d08eba-9842-4249-b843-a63f0a1c2cbc', 'd7132c58-5df3-4b97-919f-58740148b9ca', '检查联动', '高炮连检查并调整指挥仪与炮瞄雷达、火炮的同步联动的行动过程。目的是使指挥仪与炮瞄雷达之间、指挥仪与火炮之间传送和接受诸元准确一致。', 193);
INSERT INTO `t_military_term_data` VALUES ('88d60b3a-e960-43af-b442-5aec2d13d047', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境口岸', '为对出入国界及特定地区的人员、货物和交通工具实行检查与管理而设立的对外开放口岸和指定的口岸及边境通道的统称。', 90);
INSERT INTO `t_military_term_data` VALUES ('88d778da-ceca-49db-8de6-297ad8153209', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '基本想定', '按照总的训练课题对敌对双方作战基本情况和条件的想定。主要内容包括：敌对双方态势和行动的性质,上级意图,本级任务,要求执行事项和相关参考资料等。是进行战役、战术想定作业和演习的基本依据。', 109);
INSERT INTO `t_military_term_data` VALUES ('88e05977-ed3c-42b0-9eeb-e24b505733fb', '06a75831-13a1-4660-870a-455bb445336a', '单方发信', '亦称单向通信。一方发信,对方只收信的一种无线电台通信方式。通常用于对潜艇通信、无线电通播和报知通信等。', 48);
INSERT INTO `t_military_term_data` VALUES ('88eb6ea3-8fc6-4323-bccd-0cf9e9ecf7b7', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '纠察', '①军队值勤人员或分队在公共场所或营区内对过往军人军容风纪的检查、督促和对公共秩序的维持。②担任纠察任务的人员。', 61);
INSERT INTO `t_military_term_data` VALUES ('89012d99-f848-4950-a315-6dd6691f0513', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克特种驾驶', '坦克乘员在特定的条件下对坦克行驶的操纵。主要包括水网稻田地、冰雪地、沙漠地、海滩地、森林地、沼泽地、上下门桥及上下登陆舰的驾驶。', 76);
INSERT INTO `t_military_term_data` VALUES ('8912dee1-defe-4566-8b25-ddb0af7ba4c9', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地形图', '比例尺大于 1:100万,采用正射投影的普通地图。地物用图式符号加注记表示,地貌用等高线显示,能反映地表面的高低起伏状态和高程。', 253);
INSERT INTO `t_military_term_data` VALUES ('8915a737-59ea-4dc2-9e29-8ca9055a7f0b', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '换班', '一个部队或分队替换另一个部队或分队执行作战任务的行动主要用于休整补充以及变换部署、分为原地换班和超越换班。也指值勤人员或执行其他任务的单位之间的替换。', 100);
INSERT INTO `t_military_term_data` VALUES ('891ee761-f24a-4270-a5f1-3233a357dcbe', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '急造军路', '为保障技术兵器和车辆应急通行,而用简易的方法迅速构筑或标示的军用道路。分为供轮胎式车辆通行和供履带式车辆通行的急造军路。通常在原有道路数量不足或不能使用时开辟。', 256);
INSERT INTO `t_military_term_data` VALUES ('893b0064-f3b0-49cc-acc7-e2c84ec8dc75', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化地域侦察', '对指定地域实施的化学、辐射侦察。主要用以查明部队行动地域的受染情况并标受染边界。', 53);
INSERT INTO `t_military_term_data` VALUES ('8943dc7a-682e-4b23-8d4c-7c43c1de6c41', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事改革', '对军事领域中过时的或不合理、不协调的部分进行的改进和革新。', 42);
INSERT INTO `t_military_term_data` VALUES ('894c471f-21e8-41a3-8470-d0815d85ae2d', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防政策', '国家在一定时期所制定的关于国防建设和斗争的基本行动准则。是国家政策的组成部分。由国家依据其军事和政治、经济、科技、文化、地理以及国际环境等条件制定。', 1);
INSERT INTO `t_military_term_data` VALUES ('8953fe04-5386-4b65-91a5-a9496a4397b8', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '自卫干扰', '作战飞机或军舰为保护自身安全,利用携带的电子干扰设备和器材实施的电子干扰。常与支援干扰、随行干扰配合使用。', 71);
INSERT INTO `t_military_term_data` VALUES ('8958677a-346e-4c55-af5a-e3ebb50b18d0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击', '炮兵使用火炮、火箭炮和地地战役战术导弹武器系统、反坦克导弹武器系统,将弹丸、火箭、导弹射向目标或预定位置的行动的统称。包括射击准备和射击实施两个阶段。', 131);
INSERT INTO `t_military_term_data` VALUES ('896efd69-a6ec-4e65-b9c3-70347284faa1', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '卫星在轨测试', '由地球站对运行轨道上己方通信卫星的有效载荷的工作性能进行的检测和试验。是监测通信卫星工作状态和通信质量的主要手段。', 261);
INSERT INTO `t_military_term_data` VALUES ('89751a7d-f52f-488b-96f8-8da9a636954e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '偏训', '军事训练偏离了训练大纲规定的内容。', 176);
INSERT INTO `t_military_term_data` VALUES ('8987ea3b-cc2f-43c9-be23-56f112b3e199', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '数据注入地球站', '简称数据注入站。向人造卫星发送轨道预报参数、指令、时钟校正参数及其他数据的地球站。', 272);
INSERT INTO `t_military_term_data` VALUES ('899478a4-2bee-4c2a-8a73-35690b90f0a0', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '大气层核试验', '爆炸高度在海平面以上、30千米以下的空中、地面或水面的核爆炸试验、爆炸能量几乎都分配给冲击波和光辐射,并在空中及附近地面产生较多的放射性沾染。', 181);
INSERT INTO `t_military_term_data` VALUES ('89ad93e4-8e38-42f3-8ffe-0ab2f585ab76', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '消耗战', '以消耗敌方兵力兵器及其他战争物质力量为目的的作战。', 134);
INSERT INTO `t_military_term_data` VALUES ('89ae3696-1bae-4291-ad14-c0372ed79c0d', '916997ee-6728-4c61-9b79-d96960b1dc86', '喷火分队', '担负喷火任务的防化兵分队。主要以喷火器和防化单兵火箭杀伤敌有生力量或迷盲敌火力点。', 5);
INSERT INTO `t_military_term_data` VALUES ('89b5c5a8-539d-4f28-9097-ea35e6b67933', '31f4a446-5b98-4873-9d53-310d97125b07', '战略导弹使用工程', '亦称战略导弹使用系统工程。战略导弹武器系统全寿命过程中的技术管理和使用方法的统称。主要内容包括：对战略导弹武器系统的规划、论证、定型、采购、验收,运输、储存、维修,军事训练、作战使用、技术保障以及导弹退役等的技术管理和使用方法。', 6);
INSERT INTO `t_military_term_data` VALUES ('89bb89f1-39f8-47bc-8e0b-a503d15a33f4', 'f0140091-c11a-48c9-8836-8aa94439dac0', '伏击', '预先将兵力兵器隐蔽配置在敌必经之路附近,待敌或诱敌进入伏击区域突然予以攻击。', 150);
INSERT INTO `t_military_term_data` VALUES ('89cc02f3-3a41-4458-920a-b75cf1293053', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军用地形图', '为军事目的测绘或编制的地形图。图上绘有等角投影构成的经纬网和平面直角坐标网。内容要素详细,定位精确,有规定的比例尺、统一的地图分幅和图式符号。分为大、中、小比例尺的军用地形图。大比例尺军用地形图,通常指1:1万、1:2.5万、1:5万、1:10万比例尺地图。可以在图上量取角度、距离、坡度、坐标、高程、面积,是军队作战、训练的基本用图；中比例尺军用地形图,指1:25万和1:50万比例尺地图,表示较大区域的地形概貌,是战略、战役指挥的主要用图；小比例尺军用地形图,指1:100万比例尺地形图,一般作为战略指挥用图。', 260);
INSERT INTO `t_military_term_data` VALUES ('89d4cf33-ce2b-408c-ab20-f9e6f996b3e4', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '申请侦察', '当急需获知某种情况而本级无力进行侦察时,请求上级进行侦察。如申请航空侦察、舰艇侦察等。申请侦察时应说明侦察内容、范围和完成时间。', 95);
INSERT INTO `t_military_term_data` VALUES ('89da87c7-2813-4f3c-b2ae-c6c78f6dd58a', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海洋潮汐', '海水受月球和太阳等天体引潮力作用产生的周期性涨落现象。通常将海面上升过程称涨潮,下降过程称落潮。潮位上升至最高点时称高潮,下降至最低点时称低潮。高、低潮位之间的高度差称潮差。潮汐完成一次升降运动所需的时间称潮汐周期,一般为12小时25分,有的海区是24小时50分。潮汐按涨落周期分为半日潮、全日潮和混合潮。', 135);
INSERT INTO `t_military_term_data` VALUES ('89df9e47-19ff-40f4-aaca-8b4fa72e923a', 'd7132c58-5df3-4b97-919f-58740148b9ca', '越批转移火力', '防空兵人力单位对两批或两架以上连续进袭的敌机,越过某批或某架进行射击。通常在敌机批与批或架与架的间隔时间小于该火力单位射击周转时间、区不能交替转移火力时采用。', 91);
INSERT INTO `t_military_term_data` VALUES ('89e84472-a1bb-43f6-87a3-e3fd7641818f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事路线', '国家、政党在一定时期内,为实现一定的政治目标而规定的军事工作必须遵循的总方向和根本途径。', 13);
INSERT INTO `t_military_term_data` VALUES ('89f21104-8872-4367-be12-f553fb9c38ed', 'f0140091-c11a-48c9-8836-8aa94439dac0', '直瞄火力', '以目视或使用仪器直接瞄准目标进行射击的火力。', 89);
INSERT INTO `t_military_term_data` VALUES ('89fdbadf-55d6-4e26-895d-fb5d32d65b6a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战斗侦察', '以进攻或佯攻行动进行的侦察。主要用以迫使敌人暴露其兵力部署、阵地位置、工事构筑。火力配系、前沿位置和障碍物设置等。', 41);
INSERT INTO `t_military_term_data` VALUES ('89fe98d5-618f-450c-a441-65f57c5b16fb', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '海', '海洋靠近大陆边缘的水域。由半岛、岛屿或海底隆起与洋相隔,水深一般浅于2～3千米,水文和气候因受大陆与洋的影响有明显的季节变化,沉积物多为陆生物质。约占海洋总面积的11％。按其与陆地的关系,分为边缘海、陆间海（亦称地中海）和内陆海（深入大陆内部的海,简称内海）。', 7);
INSERT INTO `t_military_term_data` VALUES ('8a0a10d4-35d8-48ed-a54f-3d5a3dedad7c', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '定点修理', '在相对固定的地点开设修理机构,对损坏的武器装备进行的修理。主要负责接收、修理当地部队或分队自身难以修复的武器装备和过往部队或分队待修的武器装备。', 126);
INSERT INTO `t_military_term_data` VALUES ('8a11bc11-6c1c-4640-ad27-0e101580c4f5', '98df76fb-4b65-48ff-a56c-4db587327c79', '敷料包', '盛装卫生员急救伤员用的包扎固定材料的制式卫生装备。内装三角巾急救包、绷带卷、木夹板等。', 222);
INSERT INTO `t_military_term_data` VALUES ('8a36d3cc-93f5-4b98-afaf-3d1d2200a84a', '98df76fb-4b65-48ff-a56c-4db587327c79', '战勤组', '作战中营、连临时组织的后勤工作小组。主要负责前送、分发弹药、救护伤员以及饮食保障等。', 60);
INSERT INTO `t_military_term_data` VALUES ('8a4042b6-b35d-4307-b0e7-f153cae179ee', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '聚变燃料', '亦称热核燃料。能产生聚变反应并释放出巨大能量的物质。如氘、氮以及锂-6和氘化锂-6等。一般氢弹都用固态氘化锂-6作热核装料。', 118);
INSERT INTO `t_military_term_data` VALUES ('8a761efd-50a6-4ac8-9913-b7d745104f82', '0', '射击 .轻武器', NULL, 23);
INSERT INTO `t_military_term_data` VALUES ('8a8cabbe-6aaf-4150-bd6c-af1d040326d6', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程侦察', '为获取有关工程保障的情报而进行的侦察。主要查明：敌人的工程设施,作战地区内的地形、水文、地质和交通状况,以及可供利用的就便器材和民用加工设备能力等。', 19);
INSERT INTO `t_military_term_data` VALUES ('8a98247e-e314-4282-b4ef-8d051f4067fe', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教练车', '专供训练和教学用的各种车辆的统称。通常包括坦克、步兵战车、装甲输送车、自行火炮、汽车等。', 192);
INSERT INTO `t_military_term_data` VALUES ('8a9baddf-1d71-4e23-ab82-e9a0dc3f9196', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '瞄准式电子干扰', '简称瞄准式干扰。针对敌方电子设备的信号频谱而进行的窄频带有源压制性电子干扰、干扰功率集中,效率高,但需要精确的频率引导。', 47);
INSERT INTO `t_military_term_data` VALUES ('8aa1f3fa-a4fe-4296-8ac8-9a15be507053', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇洞库', '亦称舰艇隐蔽基地。构筑在港湾岸侧、岛屿,用以保障舰艇的隐蔽、安全停泊,并可进行维修、补给活动的濒水坑道。分为航道式舰艇洞库和滑道式舰艇洞库。', 388);
INSERT INTO `t_military_term_data` VALUES ('8aa8d475-114a-4f1a-a745-0a4d12c52157', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役密度', '战役军团作战正面上单位宽度内兵力、兵器的平均数量。大规模战役的兵力密度通常以师为计算单位；各种战役的兵器密度通常以对战役作战有较大影响的单个主要兵器为计算单位。', 28);
INSERT INTO `t_military_term_data` VALUES ('8ab39048-13ae-40a7-a14b-3d17f8a2fb4d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '道路设备', '为保障路基稳定和车辆行驶安全而构筑和设置的结构物。包括排水设备、防护设备和道路标志等。', 268);
INSERT INTO `t_military_term_data` VALUES ('8ac85287-5fb5-4f12-93a1-5dadf12e43c5', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '集装箱工事', '外形、尺寸、结构、运输方式等类似集装箱的掩蔽工事。通常由一个或几个集装箱构成。兼有集装箱和工事的功能。便于机动,能提供良好的内部环境,有较好的三防性能。多用于指挥工事,并可用作给水站、医疗站、加油站、修理所和人员掩蔽部等。按尺寸分为国际标准型和非国际标准型两类。', 76);
INSERT INTO `t_military_term_data` VALUES ('8ad7c01b-c702-426c-97ab-89561f9fde69', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '专家系统', '能在一定程度上模拟专家的思维、判断,起到某领域专家作用的计算机应用系统。军事上可用于辅助决策等。', 62);
INSERT INTO `t_military_term_data` VALUES ('8adbfd4d-9f65-4764-a878-bc94f0373ba0', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '计划导演', '按计划规定的进程和设置的情况对军事演习进行的导演。', 132);
INSERT INTO `t_military_term_data` VALUES ('8aed2b98-900d-4007-9726-2abf40faf13f', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力配系', '对参战的各种火器作适当配置和分工所构成的火力系统。通常根据作战任务、敌情、地形和火器性能确定。包括反坦克火力配系、防空火力配系、防步兵火力配系等。', 78);
INSERT INTO `t_military_term_data` VALUES ('8b008956-71d0-45df-bd1c-682a0fb2b390', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵雷达侦察网', '由在同一区域遂行同一作战任务的防空兵对空侦察雷达或炮瞄雷达组成的对空侦察网。', 114);
INSERT INTO `t_military_term_data` VALUES ('8b02e948-87f1-4879-a8c2-2579fc88b661', 'f0140091-c11a-48c9-8836-8aa94439dac0', '反坦克预备队', '担负反坦克任务的预备队。通常以反坦克炮兵、反坦克导弹分队等编成。', 52);
INSERT INTO `t_military_term_data` VALUES ('8b1f52a0-d206-4d26-bc9d-29628c2fd888', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '等高线', '亦称水平曲线。在地图上将地面上高程相等的各点连成的闭合曲线。分为首曲线、计曲线、间曲线和助曲线。用以显示地貌高低起伏、倾斜陡缓形态,量取某一地段的坡度或任一点的绝对高程与相对高程等。', 279);
INSERT INTO `t_military_term_data` VALUES ('8b2e352b-2101-416a-9df9-c8ff0271d12e', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '陆上发展进攻', '登陆部队以登陆场为依托,继续向敌纵深发展进攻的作战行动。', 76);
INSERT INTO `t_military_term_data` VALUES ('8b396899-f29b-4011-9bc8-4e770f95929d', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机机降场', '空降作战中运输直升机实施机降的着陆场地。通常要求具备直升机野外起降条件,并适应机降作战的需要。', 96);
INSERT INTO `t_military_term_data` VALUES ('8b3d6945-f4b5-4d5b-80fc-43d9827ca969', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵作战保障', '炮兵为顺利遂行作战任务而采取的各项保证性措施和进行的相应活动的统称。主要包括；侦察，通信、电子防御,警戒与自卫,对核、化学、生物武器和燃烧武器袭击的防护,工程、伪装、气象、战场管理等。', 102);
INSERT INTO `t_military_term_data` VALUES ('8b482145-3590-4661-943d-2e76c162a76d', '916997ee-6728-4c61-9b79-d96960b1dc86', '发烟车', '装有发烟气的专用车辆。有喷洒式发烟车和雾油发烟车等。主要用以施放大面积烟幕。', 240);
INSERT INTO `t_military_term_data` VALUES ('8b51d8f4-1102-40a6-84ad-15342b37d47f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆区', '简称爆区。核爆炸爆心投影点周围一定范围的区域。通常指能对无防护的暴露人员、物体造成轻度以上杀伤破坏作用的区域。', 142);
INSERT INTO `t_military_term_data` VALUES ('8b6003ce-dedd-4586-a997-124e724b61eb', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化兵战术', '防化兵进行战斗的方法。主要包括防化兵战斗基本原则、战斗指挥、兵力部署、协同动作、战斗行动的方法和各种保障措施等。有防化部队战术,核观测分队战术,防化侦察分队战术,洗消分队战术,发烟分队战术以及喷火兵战术等。', 36);
INSERT INTO `t_military_term_data` VALUES ('8b6352c6-0bfc-4f6c-8533-f0c8d4d3b577', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '居民地', '人们按生产和生活需要而集聚定居的地方。按其性质、人口和工商业发展状况,分为城市、集镇、乡村等。', 119);
INSERT INTO `t_military_term_data` VALUES ('8b67fe41-186f-4aea-be2c-0a2fb1c07ae8', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '步兵侦察分队训练', '为使步兵侦察分队掌握侦察知识和技能而进行的训练。主要训练内容包括侦察专业知识、侦察专业技术和侦察专业战术以及共同课目等。', 86);
INSERT INTO `t_military_term_data` VALUES ('8b732094-e2ce-413c-8715-c6a09c7cd02a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹核战斗部', '亦称导弹核弹头。装有核装料及引爆系统的导弹战斗部。如原子弹头、氢弹头、中子弹头等。', 21);
INSERT INTO `t_military_term_data` VALUES ('8b91da61-0aad-475b-91f5-571218406aa8', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '协同动作指示', '对有关部队或分队所作的关于协同动作的指示。通常明确协同关系、时间、地点、任务和方法等。', 131);
INSERT INTO `t_military_term_data` VALUES ('8b9b7269-881a-4403-bc7f-fa4ddb65c072', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行申请', '准备实施飞行的单位或机组将飞行计划预先上报飞行管制部门的工作。一切飞行都应预先申请,经批准后才能进行。紧急情况下也可临时申请。战斗飞行按战斗命令执行,但在起飞前后亦要及时通报飞行管制部门。', 375);
INSERT INTO `t_military_term_data` VALUES ('8bad0e1e-3f84-4260-9de1-24762428049c', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '紧急集合场', '为应付紧急情况而在驻地或在宿营地域预先选定的部队或分队紧急集台的场所。须符合战斗要求、必要时还可规定预备紧急集合场。', 99);
INSERT INTO `t_military_term_data` VALUES ('8bb698e0-3c83-475d-9dfb-f2626db76a29', '98df76fb-4b65-48ff-a56c-4db587327c79', '单兵负荷量', '单个士兵徒步行军、作战时,按规定穿着和随身携带的武器装备与物品的总重量。分为战斗负荷量和行军负荷量。', 122);
INSERT INTO `t_military_term_data` VALUES ('8be12f2d-755b-4b9b-b5fe-18d89b6903ae', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学观察哨', '为观测敌化学武器袭击情况而开设的哨所。通常由防化侦察分队开设。主要负责：及时发现和报知敌化学袭击情况,概略判断袭击规模及毒剂云团', 10);
INSERT INTO `t_military_term_data` VALUES ('8bfb03fb-b681-4a89-902b-d6d7ecdf433d', '878651de-adf5-4c72-9376-9c363b893ff8', '非正义战争', '违背人民的根本利益。阻碍社会进步的战争。包括为实行阶级与民族压迫、镇压人民革命、侵略他国、制造国家分裂和争夺世界与地区霸权等而进行的战争。', 23);
INSERT INTO `t_military_term_data` VALUES ('8bfe036f-0a9c-4fed-974a-7a455c18485d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '集团军雷达营', '集团军建制内担负对空预警任务的雷达专业分队。由指挥分队和数个雷达分队组成。主要是为集团军指挥所及其所属的防空部队提供空情保障。', 8);
INSERT INTO `t_military_term_data` VALUES ('8c007388-5723-4c9e-97a6-da3680577707', '878651de-adf5-4c72-9376-9c363b893ff8', '革命战争', '亦称解放战争。被压迫的阶级或民族为争取自身解放而进行的正义战争。', 24);
INSERT INTO `t_military_term_data` VALUES ('8c033507-6b17-400d-ad5d-6d4d57d8008b', '97a19170-bfac-42c5-9906-1acb187f0654', '机场加油线', '简称加油线。机场中专门用于加油车或加油设备给飞机或直升机加油的位置。通常设于主滑行道中段、便于安放加油设备的地方。', 430);
INSERT INTO `t_military_term_data` VALUES ('8c06befd-2fb6-40e5-a620-78528f52bd7f', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '迷彩伪装', '用涂料、染料或其他材料,按一定要求改变目标或改变目标背景的颜色而实施的伪装。', 336);
INSERT INTO `t_military_term_data` VALUES ('8c0a6adf-5b38-4027-97b8-fcde324b2892', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '连哨', '担负宿营警戒任务并进入预定位置的建制连。通常由宿营的师、团或营哨派出。', 21);
INSERT INTO `t_military_term_data` VALUES ('8c142d7f-7831-4163-917c-522b7ff7f555', '98df76fb-4b65-48ff-a56c-4db587327c79', '轻装物资', '部队因执行紧急任务的需要而减下来的个人携带物资。其品种、数量和管理措施由合成军队首长确定。', 121);
INSERT INTO `t_military_term_data` VALUES ('8c189f0e-9579-467d-be21-29168290d3ae', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '风力', '用风级表示的风的强度。气象上常用的蒲福风力等级是根据风对地面物体或海面的影响程度而划分的风力等级，共分18级，级数越大,风力越强。', 18);
INSERT INTO `t_military_term_data` VALUES ('8c1c161a-131a-4fc0-b5c7-d0b1b500b963', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '轨道保持', '使人造卫星的实际运行轨道与标准轨道的偏离量限制在给定范围内所做的轨道控制。通常是利用人造卫星携带的动力装置,调整卫星的运行速度,修正其轨道参数达成。对不同高度的卫星,轨道保持的方法也不相同。', 266);
INSERT INTO `t_military_term_data` VALUES ('8c2e17f4-1821-444d-8f3d-9084dc1fd412', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力协同', '各种火力之间的协调配合。通常根据作战任务,按目的、时间和空间进行计划和组织。', 76);
INSERT INTO `t_military_term_data` VALUES ('8c3113ef-ec54-44e5-8909-70b5b6933950', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导航卫星', '从太空发射无线电导航信号,能为地面、海洋、空中和太空用户导航定位的人造地球卫星。利用卫星导航或定位,具有高精度、全天候、能覆盖全球和用户设备简便等优点。', 214);
INSERT INTO `t_military_term_data` VALUES ('8c38b773-552e-4dd4-8464-31136fb2c60b', '878651de-adf5-4c72-9376-9c363b893ff8', '战争指导规律', '符合战争规律的指导战争的原理、原则。是战争客观规律在主观指导上的正确反映和自觉运用,也是主观指导与客观实际相统一的产物。通常表现为正确的战略、战役法和战术。', 33);
INSERT INTO `t_military_term_data` VALUES ('8c3d682e-0704-4817-bd1a-8ef2219b57bb', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '请销假制度', '军队中关于人员外出请假和归队销假的制度。主要包括外出人员请假的批准权限、时限、比例和归队销假等方面的规定。', 16);
INSERT INTO `t_military_term_data` VALUES ('8c43e2c6-f1a1-4a37-9274-e21e07d2b298', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察兵野战生存训练', '为培养和锻炼侦察兵在恶劣环境下求生技能和保持战斗力而进行的训练。', 91);
INSERT INTO `t_military_term_data` VALUES ('8c4e4c71-4ca2-40d4-8c97-f46c703be92b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地形', '①地貌和地物的统称。地貌是指地表面高低起伏的状态,如平原、丘陵地、山地等；地物是指分布在地面上人工或自然形成的固定物体,如居民地、道路、江河、森林以及各种管线等。②同地貌。即泛指地面起伏的形状。', 116);
INSERT INTO `t_military_term_data` VALUES ('8c51e31e-4d59-4f96-b6d0-bb1cad45c8c6', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程保障计划', '为组织实施工程保障而制定的计划。主要包括；各种工程作业的项目、位置、数量、种类、方法和要求,各部队及民兵参加工程作业的兵力、任务区分及完成任务的顺序、时限,工程兵兵力使用,工程器材保障和工程装备技术保障等。', 16);
INSERT INTO `t_military_term_data` VALUES ('8c748fe4-170d-4fe1-b89c-758914fe9175', '97a19170-bfac-42c5-9906-1acb187f0654', '航空炸弹圆径', '用名义重量表示的航空炸弹的量级。通常以千克为单位表示。分为1、2、5、10、25、50、100、250、500、1000、3000千克等炸弹圆径。每种圆径都规定应量级炸弹的最大重量及其最大几何尺寸（弹体的长度、直径,尾翼的弦长、翼展）。', 335);
INSERT INTO `t_military_term_data` VALUES ('8c76def7-6930-43b8-8e97-b14e6cac6185', '916997ee-6728-4c61-9b79-d96960b1dc86', '沙林', '学名甲氟磷酸异丙酯。神经性毒剂的一种。可装填在炮弹、火箭弹、航空炸弹等弹药内,以爆炸方式形成蒸气和气溶胶,主要经呼吸道和眼睛侵入机体,使人畜中毒。', 212);
INSERT INTO `t_military_term_data` VALUES ('8c7bf0cc-d89f-449b-857a-5890b5b83c21', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '司令部训练', '司令机关进行的组织指挥和参谋业务的训练。是首长机关训练的组成部分。通常采取讲授、专题研究、图上作业、司令部合练或参加实兵演习等形式组织实施。', 62);
INSERT INTO `t_military_term_data` VALUES ('8c7d8be9-638b-49d9-81a4-d454fde4924e', '06a75831-13a1-4660-870a-455bb445336a', '自动化信息显示系统', '在指挥自动化系统中应用光电技术实现信息直观显示的分系统。通常由信息源、接口转换、选切控制和显示设备等组成。可以显示以文字、数字和符号表示的情报参数,以地图、图表和标号表示的敌我态势,以及由摄像机拍摄的静态和动态的现场实况等。', 164);
INSERT INTO `t_military_term_data` VALUES ('8c7f4dc4-a623-40f2-a4da-372a36016847', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上预警', '海军预警兵力在舰载雷达和岸基雷达探测范围以外发现来袭的敌方兵力兵器,并及时告警。通常使用海军预警机和装有远程警戒雷达的水面舰艇结合预警卫星实施。', 38);
INSERT INTO `t_military_term_data` VALUES ('8c8038b8-e2b3-4a63-9226-d038dbfab261', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹井口发射', '导弹在发射井内完成发射准备后,用井内的专门提升装置将其提升至井口进行的发射。发射井可多次使用。井口发射防护能力强,发射暴露时间较场坪发射短,但较井内发射长。', 117);
INSERT INTO `t_military_term_data` VALUES ('8c8e5cf4-d43f-447b-82ba-a7913c07b7e7', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '当前任务', '进攻的军队应完成的第一步作战任务。由第一梯队遂行,通常为突破敌人防御的一定纵深,或攻占某一地域（目标）,或消灭某一部分敌人。', 81);
INSERT INTO `t_military_term_data` VALUES ('8c90b303-5dc8-47fa-bc0b-ccc8d8c05b99', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '口述作战命令', '以口头形式下达的作战命令、通常在现地或借助沙盘地图、显示屏幕等下达。', 126);
INSERT INTO `t_military_term_data` VALUES ('8c929c4b-bcbd-47b7-a23a-df0b539129b3', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '发射条件', '亦称航天器发射限制条件。为保证航天器发射成功而必须满足的各种技术条件。分为最佳发射条件和允许发射条件。影响发射成功的限制条件主要包括地面发射控制系统限制条件、测控系统限制条件、通信系统限制条件、气象限制条件、发射窗口等。', 252);
INSERT INTO `t_military_term_data` VALUES ('8cada529-fa8c-4093-a953-dffebc0221cb', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '空舰导弹', '从飞行器上发射,用以攻击水面舰船和水面航行状态的潜艇的导弹。也可用以攻击地面目标。装备于海军轰炸机、攻击机、反潜巡逻机和反潜直升机等。', 190);
INSERT INTO `t_military_term_data` VALUES ('8cbf4e9a-99ec-4468-9837-c2d1a29e3cd3', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军序列', '行军纵队中各个部分行进时所在的位置和顺序。', 59);
INSERT INTO `t_military_term_data` VALUES ('8cd446a9-4316-4915-a289-8f916b41bdbb', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事潜力', '在一定时间内或经过动员后,可转化为军事实力的军事力量。通常包括人力、物力、财力等各种潜在力量。', 47);
INSERT INTO `t_military_term_data` VALUES ('8cd609eb-b1a8-45a7-88bc-86e0e5339538', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '利用法', '火箭炮兵在缺乏完整而适时的气象通报。但有完整的弹道资料、完善的技术准备和较精确的测地诸元时,利用线膛炮的射击成果,求取火箭炮射击条件修正量以决定射击开始诸元的方法。利用法精度较好,通常用以决定目标射击开始诸元。', 148);
INSERT INTO `t_military_term_data` VALUES ('8cd7d63f-326d-440e-a30a-0a029c81ff90', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '海防斗争', '为维护国家安全和海洋权益而在沿海地区和海疆开展的斗争。包括：保卫领海及其上空安全,制止外国在专属经济区、大陆架的未经许可的活动,以及反敌特、反偷渡、反走私等。', 108);
INSERT INTO `t_military_term_data` VALUES ('8cdf8d5f-fd27-46b3-89ef-53ea59a02a8d', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报要素', '构成情报的主要因素。包括情况的来源、发生时间、地点和情报的内容等。', 140);
INSERT INTO `t_military_term_data` VALUES ('8ce73b8a-cd9f-41ba-a672-9cd1318a17e4', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸地球物理效应', '爆炸引起的地球物理现象及其异常变化。主要有人工极光、人工辐射带、电离层效应、地震、地磁扰动和次声波扰动等。', 167);
INSERT INTO `t_military_term_data` VALUES ('8cf2ca25-248c-4228-88e3-060649b6e246', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象仪器', ' 用以测量气象要素的仪器。包括温度表、气压表、湿度表、风向风速表、云幕灯、能见度表、雨量器、辐射表、日照计、气象气球、无线电经纬仪、测风经纬仪、无线电探空仪等。', 97);
INSERT INTO `t_military_term_data` VALUES ('8cf61947-d123-45be-9130-5d3a622b925b', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电磁脉冲防护', '为使电子（电气）设备及其系统免受或减轻核爆炸产生的高能电磁脉冲的破坏而采取的保护措施。主要有：采取完善的电磁屏蔽,采用保护电路和良好的接地,选用抗电磁脉冲能力强的电子元器件等。', 107);
INSERT INTO `t_military_term_data` VALUES ('8cf62ce4-2245-4285-9d71-61c5052b89fa', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '通信干扰附加器', '附加在无线电通信设备上,使之能作为干扰机使用的专用装置。主要功能是：使干扰频率对准敌电台信号频率,产生各种样式的干扰,控制发射机施放干扰等。', 129);
INSERT INTO `t_military_term_data` VALUES ('8d074e67-21fb-4d3c-83ae-943d61150c87', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '阻援集团', '战役中担负阻击增援之敌任务的兵力集团。', 79);
INSERT INTO `t_military_term_data` VALUES ('8d118ad5-b909-4803-a896-d0e5346efbb6', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵装备技术保障', '第二炮兵为使导弹武器装备保持和恢复完好状态及实施成功发射而在技术方面进行的保障。主要包括：武器装备的储存与供应,武器装备及阵地设备的技术保障,导弹发射异常情况的技术处置等。', 197);
INSERT INTO `t_military_term_data` VALUES ('8d11b500-ebdf-435d-912e-9eb29149fb7c', '8a761efd-50a6-4ac8-9913-b7d745104f82', '超越射击', '使用直射武器时，利用地形及弹道高使弹丸飞越己方战斗队形上方的射击。瞄准线与指向己方分队位置的标定线之间应留出规定的安全角。', 90);
INSERT INTO `t_military_term_data` VALUES ('8d1fbb54-3359-4bd1-ad69-dd22df85f43d', '8a761efd-50a6-4ac8-9913-b7d745104f82', '激光束照准器', '可发射激光束并能在目标上形成一个瞄准光斑的装置。主要用以指示和瞄准目标,分为可见光的和不可见光的两种。不可见光的激光束照准器需要配合夜视瞄准镜使用。', 196);
INSERT INTO `t_military_term_data` VALUES ('8d41cc12-b027-4a7e-90ee-a8ee78e44622', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗情报', '实施电子对抗所需的情报。主要内容包括：敌方的电子装备战术技术性能、用途、配置、作战运用及相关联的武器系统,雷达、通信、电子对抗等专业部队的编制序列、作战原则、作战能力、战术训练情况,军用电子技术发展动态等。', 22);
INSERT INTO `t_military_term_data` VALUES ('8d4591ff-c3de-4c71-ac0a-d5dc1a1d61bb', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '技术准备', '为使武器装备、技术器材的战术技术性能保持良好状态而进行的准备。主要包括：武器装备、技术器材的保养和维修,各种器材、零配件、原材料的补充和储备维修机构、设备的健全和完善,保养和维修人员的培训等。', 161);
INSERT INTO `t_military_term_data` VALUES ('8d528f7c-1506-494c-a0ce-5cc6c6fb74bc', '98df76fb-4b65-48ff-a56c-4db587327c79', '急救', '①对发生急病或突然遭受外伤的人员,就地、就近进行的紧急抢救。主要包括包扎、止血、临时骨折固定、通气、简单的抗休克、预防感染和解毒等。②战时由连、营卫生人员对伤病员实施的紧急抢救措施。', 194);
INSERT INTO `t_military_term_data` VALUES ('8d57c503-7d4e-4acc-b04e-54fb5f9d8f9e', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '高原', '地面比较平缓宽广,海拔一般在 500米以上,起伏较小、外围较陡的地区。以较大高度区别于平原,以平缓的地面区别于山地。海拔高的高原,空气稀薄,气候寒冷,人烟稀少。军队行动时人员体力消耗大,运动速度低,射击误差大,影响机械和车辆使用,人员易发生疾病。', 26);
INSERT INTO `t_military_term_data` VALUES ('8d5ff82f-f095-4bb4-9966-2aaef4111860', '06a75831-13a1-4660-870a-455bb445336a', '国防通信网', '用以保卫国家安全、防御外来武装侵略和颠覆而建立的各种通信网的统称。包括军事通信网和具有国防功能的民用通信网。', 60);
INSERT INTO `t_military_term_data` VALUES ('8d7f16b6-8143-42f0-8af9-4096af518940', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战场环境', '战场及其周围对作战活动有影响的各种情况和条件的统称。包括地形、水文、气象等自然条件,人口、民族、交通、建筑物、工农业生产、社会情况等人文条件,以及国防工程构筑、作战物资储备等战场建设的情况。', 168);
INSERT INTO `t_military_term_data` VALUES ('8d9a2efd-d9d0-4873-a3bf-7241d9ae9d7f', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹阵地设施', '导弹阵地上的土建工程及有关设备的统称。主要包括坑道、场坪、掩体、道路、桥梁、伪装设施以及供水、通风、供电等设备。', 50);
INSERT INTO `t_military_term_data` VALUES ('8dad33d0-3b26-414c-ba98-3776c62a3557', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸通信效应', '核爆炸释放的能量对光、电、声信号传输和对通信设施造成的破坏作用及影响。核爆炸产生的核辐射、光辐射、冲击波和电磁脉冲等可使一定范围内的无线电信号减弱以至中断,并毁坏通信设施。', 174);
INSERT INTO `t_military_term_data` VALUES ('8dc5e625-f79b-4c3b-b5ab-26891869a9a3', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '平流层', '对流层顶至距地面 50～55千米高度之间,空气对流运动微弱，气流平稳的大气层。由于臭氧对紫外辐射的吸收作用,除底部外,气温随高度的增加而升高。', 3);
INSERT INTO `t_military_term_data` VALUES ('8dd02f4c-2491-4658-afe2-ccb13b38ea1d', '916997ee-6728-4c61-9b79-d96960b1dc86', '半数致死剂量', '能使染毒人员 50％死亡的毒剂量。用LD50或LCt50表示。', 132);
INSERT INTO `t_military_term_data` VALUES ('8dd153ff-419a-4598-b3a6-8d3f4d5f50f1', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上拖曳飞行', '海军直升机拖带小型船艇、声纳基阵或扫雷具等在海洋上空的飞行。拖曳过程中,当拖索（缆）张力超过限度时,索钩即与直升机自动脱离,以保证飞行安全。', 338);
INSERT INTO `t_military_term_data` VALUES ('8dd453e7-33dd-4958-b9b0-c12c5e342fc8', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗侦察', '运用电子对抗侦察装备搜索、截获敌方电子设备的电磁辐射信号,通过分析识别,从中获取其战术、技术特征参数及位置数据等情报的侦察。目的是为组织实施电子干扰、电子防御以及部队的其他战斗行动提供情报。包括雷达对抗侦察、通信对抗侦察和光电对抗侦察等。按侦察任务范围,分为电子对抗情报侦察和电子对抗支援侦察。', 17);
INSERT INTO `t_military_term_data` VALUES ('8de091c8-3534-4dd2-80af-1d72261ce790', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防', '国家为防备和抵抗侵略,制止武装颠覆,保卫国家的主权、统一、领土完整和安全,而进行的军事及与军事有关的政治、经济、外交、科技、教育等方面的活动。是国家生存与发展的安全保障。国家的社会制度和国家政策决定国防的性质。', 0);
INSERT INTO `t_military_term_data` VALUES ('8de9fc80-db04-4d40-875f-02957c907b26', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达诱饵', '能够模拟被掩护目标的雷达信号特征,以引诱和欺骗敌方雷达跟踪系统的假目标装置。分为飞航式、拖曳式和投放式雷达诱饵。通常由作战飞机、导弹或舰艇携带,在受到敌雷达跟踪时发射或投放。', 132);
INSERT INTO `t_military_term_data` VALUES ('8df101f3-ee3d-41e6-a779-d90a3df77de4', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '应急训练', '受领紧急作战任务或其他应急任务后进行的有针对性的训练。', 48);
INSERT INTO `t_military_term_data` VALUES ('8df7ec1a-4a2d-4c13-93a9-f8e600e5199d', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '干扰暴露区', '干扰压制区以外的空间范围。', 81);
INSERT INTO `t_military_term_data` VALUES ('8e0a5679-faee-4ac9-97f7-4ec326375e81', 'f0140091-c11a-48c9-8836-8aa94439dac0', '卷击', '突破后向突破口翼侧实施的攻击。用以扩大突破口,协同正面部队攻歼敌人。分为一翼卷击和两翼卷击。', 163);
INSERT INTO `t_military_term_data` VALUES ('8e0a5a78-43d9-4132-8907-36d8b72336a7', '8a761efd-50a6-4ac8-9913-b7d745104f82', '集火射击', '亦称集中射击。多人或多个分队用同种或多种武器同时对同一目标或地段进行的射击。火力密度大,可达到迅速歼灭或压制敌人的目的。', 106);
INSERT INTO `t_military_term_data` VALUES ('8e0dfdd0-b8c3-4592-bcd0-d23043ff9af2', 'f0140091-c11a-48c9-8836-8aa94439dac0', '展开地区', '部队展开成战斗队形的地区。', 66);
INSERT INTO `t_military_term_data` VALUES ('8e11c8a9-f3c9-4710-8410-6dd170380d9d', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行安全高度', '飞行管制制度规定的保证航空器不致与地面障碍物相撞的最低飞行高度。如在平原地带飞行时,规定应高出航线两侧各25公里以内最高标高400米；在山岳地带飞行时、规定应高出航线两侧各25公里以内最高标高600米。', 248);
INSERT INTO `t_military_term_data` VALUES ('8e13092f-a57f-4d0d-be31-75e68cb272d6', '06a75831-13a1-4660-870a-455bb445336a', '无线电通信', '利用无线电波传输信息的通信。包括无线电台通信、无线电接力通信、散射通信、卫星通信、流星余迹通信等。可传送电话、电报、数据和图像。无线电通信建立迅速、便于机动,但保密性较差,易受电磁干扰和自然条件的影响。是战时的主要通信手段。', 99);
INSERT INTO `t_military_term_data` VALUES ('8e153059-40aa-4bfe-b704-33f8b1d59fea', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '临战疏散', '在国家转入临战状态时进行的疏散。', 222);
INSERT INTO `t_military_term_data` VALUES ('8e205488-63fb-4af5-bddd-3e745b034341', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '原地换班', '在交班部队或分队占领的地域内实施的换班。用于防御战斗中或进攻战斗准备时、通常按先纵深后前沿的顺序进行也可纵深和前沿同时实施。', 101);
INSERT INTO `t_military_term_data` VALUES ('8e25e397-5198-4c30-b9cb-713f0826cb1a', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹诸元准备', '确定导弹射向。射程等数据的计算工作。包括大地基础诸元计算和射击诸元计算。', 181);
INSERT INTO `t_military_term_data` VALUES ('8e366f29-e690-491a-951c-d49268c9ba38', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '空气湿度', '表示空气干湿程度（水汽含量）的物理量。常用相对湿度和绝对湿度等参量表示。相对湿度是空气中实际水汽压与同温度下饱和水汽压的比值（用百分比表示）；绝对湿度是单位体积空气中所含水汽的质量,用克／立方米表示、水汽是大气中最富变化的成分,云、雾、雨、雪等都是水汽相变的产物。', 14);
INSERT INTO `t_military_term_data` VALUES ('8e37cf6e-e843-4343-8d36-80779b6c1760', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹飞行试验安控站', '导弹飞行试验中负责导弹安全控制的地面站。站内通常安装有大功率的遥控设备,在导弹出现故障后能及时发送炸毁导弹的指令。', 81);
INSERT INTO `t_military_term_data` VALUES ('8e3cb2fe-2b75-44ce-a7da-3ceb35712770', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '轨道备份卫星', '正在太空轨道上运行,还未投入使用,可根据指令接替其他卫星工作的人造地球卫星。用以保证卫星工作的不间断。', 220);
INSERT INTO `t_military_term_data` VALUES ('8e3cebb3-8fa3-45f4-ba9d-670d1a114a91', 'f0140091-c11a-48c9-8836-8aa94439dac0', '预先火力准备', '部队发起进攻之前一至数天,对防御之敌实施的火力突击。用以破坏敌防御设施,削弱敌防御力量,为进攻创造条件。', 94);
INSERT INTO `t_military_term_data` VALUES ('8e4e9ab4-e786-475a-9021-7bea797f1709', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '爆破筒', '由简体、装药、引信组成的管状爆破器材。分为刚性爆破筒、柔性爆破筒和刚柔组合爆破筒。主要用以爆破敌工事和杀伤敌人员,以及在铁丝障碍物、地雷场中开辟通路等。', 227);
INSERT INTO `t_military_term_data` VALUES ('8e50e6bf-61bf-4c87-a96f-c91e4206146e', 'd7132c58-5df3-4b97-919f-58740148b9ca', '瞄准线检查', '为保证射击精度,对高炮和指挥仪瞄准镜的光轴线与瞄准线进行的检查。检查和调整高炮瞄准镜的光轴线,目的是使其与炮身轴线相一致。检查和调整指挥仪瞄准镜的瞄准线,目的是使其与测距机的中央立标相一致。', 191);
INSERT INTO `t_military_term_data` VALUES ('8e564874-d42b-4a0e-9d10-66986677eb18', 'f0140091-c11a-48c9-8836-8aa94439dac0', '散开', '单兵之间扩大间隔和距离的动作。通常在敌火力威胁的情况下采用,以减少敌方火力对己方的损害。', 109);
INSERT INTO `t_military_term_data` VALUES ('8e56c78e-3606-4bb3-8b10-dbe97a3c6276', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地轴', '地球自转的轴线。从南至北并通过地心。', 197);
INSERT INTO `t_military_term_data` VALUES ('8e5746b5-ff3a-406f-a8c1-95bf56f62d35', '97a19170-bfac-42c5-9906-1acb187f0654', '航行情况通信', '航行管制和通信部门组织的传递飞行管制情况的通信。通常根据飞行管制区的划分和航路飞行的需要组织。使用有线电通信和无线电通信。无线电通信一般在指挥、协同、机要和气象情报无线电网内实施。', 355);
INSERT INTO `t_military_term_data` VALUES ('8e5bac74-9677-4309-bacc-9154c7a89cca', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵部署', '对防空兵兵力进行的区分、编组和配置。通常根据敌我航空兵情况,防空兵的任务、数量和武器装备性能,以及地形和道路等因素确定。', 10);
INSERT INTO `t_military_term_data` VALUES ('8e6fb548-cbea-45c6-ad21-070fdb984157', 'f0140091-c11a-48c9-8836-8aa94439dac0', '冲击路线', '分队由冲击出发阵地或展开地区冲向目标的运动路线。', 185);
INSERT INTO `t_military_term_data` VALUES ('8e73fc08-e83c-431a-873f-f036b682bff6', '06a75831-13a1-4660-870a-455bb445336a', '自动式电话机', '由用户拨号或按键发出的呼叫信号,控制交换设备自动完成通话接续的电话机。有转盘式和按键式两种。使用方便,转接速度快,线路利用率高。多用于军队指挥机关和驻地相对稳定的部队。', 202);
INSERT INTO `t_military_term_data` VALUES ('8e783dda-1676-48c0-b739-b801af90b0b8', '06a75831-13a1-4660-870a-455bb445336a', '无线电管理技术站', '担负军队无线电管理技术保障工作的通信机构。主要任务是：对无线电频率使用和台站选址进行电磁兼容分析；监视无线电台、站频率使用情况；测定干扰源；查找擅自使用军用频率的无线电台站；拟定无线电管理技术标准等。', 6);
INSERT INTO `t_military_term_data` VALUES ('8e7f3752-f013-4f4d-9046-a70de7861cb0', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '训练舰', '亦称练习舰。专供海军院校学员或舰艇人员海上实习使用的勤务舰船。分为综合训练舰和专业训练舰。', 153);
INSERT INTO `t_military_term_data` VALUES ('8e80d5a3-94b4-4656-8d39-cf26ec655e77', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜水钟', '运载潜水员实施深潜作业的潜水装备。通常用于饱和潜水和帮司潜水。外壳为钢制钟形或球形体,底部开口供潜水员出入。舱内有给排气、照明、加热、通信、观察等装置,一般可容纳2～3名潜水员。由母船下放或起吊。', 248);
INSERT INTO `t_military_term_data` VALUES ('8e88d537-aea4-4797-b3cb-05f313c3eb76', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹火力范围', '地空导弹武器系统在其圆周射击区域内能有效杀伤空中目标的范围。在作战地图上通常标示为以发射阵地为圆心、杀伤区最大远界的水平距离为半径的圆。', 141);
INSERT INTO `t_military_term_data` VALUES ('8e8f89ed-836d-4b0f-86a4-b7eeafb007c9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮弹装药号数', '简称装药号数。使用变装药炮弹时区分装药的序号。一般称装药量最大的为全装药或全号装药,以下随装药量的减少,依次称为一号装药、二号装药等。', 329);
INSERT INTO `t_military_term_data` VALUES ('8ea43d3c-8473-4374-b670-41dfa86a36fa', '06a75831-13a1-4660-870a-455bb445336a', '无线电佯动', '利用无线电通信进行迷惑敌人的活动。通常和部队佯动配合实施。', 43);
INSERT INTO `t_military_term_data` VALUES ('8eab2303-a5fe-4f30-b2cb-6dccff91d8f8', '98df76fb-4b65-48ff-a56c-4db587327c79', '行车编组', '汽车部队或分队执行运输任务时,对人员十辆进行的编配组合。主要分为连排行车编组、班组行车编组和混合行车编组等。一般根据任务、敌情、道路、人员和车辆状况等条件,确定采取何种行车编组。', 320);
INSERT INTO `t_military_term_data` VALUES ('8eaf11fd-d583-499c-8b74-6801875f5c93', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '纬度', '地面某点的沿垂线方向与赤道面间的夹角。在赤道以北的称北纬,以南的称南纬,各由0度至90度。通常用度、分、秒表示。', 205);
INSERT INTO `t_military_term_data` VALUES ('8eb4589f-e584-49c1-a59e-8db95e76cf71', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航空鱼雷', '亦称空投鱼雷。由飞机或直升机携带并投射的鱼雷。分为空舰鱼雷和空潜鱼雷。主要用以攻击水面舰船和潜艇,也可用以攻击船坞、水坝等。', 204);
INSERT INTO `t_military_term_data` VALUES ('8ecb36fd-368d-4b66-af4b-832288ab5eb9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '纵深', '作战部署的纵向深度或作战任务要求达到的全纵向深度。也指除前沿以外的纵深地域。分为进攻纵深和防御纵深等。', 288);
INSERT INTO `t_military_term_data` VALUES ('8ecff7ac-fa1e-4620-a61b-0d20fea1daf4', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '参谋业务', '参谋人员的专业工作。主要包括准备资料运筹谋划并提出建议,传达首长的决心计划组织、控制协调部队的行动等。', 109);
INSERT INTO `t_military_term_data` VALUES ('8ed4d6d8-48cd-4092-abfb-c6e02358befd', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克发动机', '适应坦克性能要求的内燃机。与其他辅助系统构成坦克动力装置。主要有往复活塞式发动机和燃气轮机两种。', 125);
INSERT INTO `t_military_term_data` VALUES ('8ed8ed6e-2116-4daf-b990-9da8d3113ee2', '06a75831-13a1-4660-870a-455bb445336a', '战役通信', '为保障战役指挥而建立的通信联络、基本任务是保障战役军团的指挥、协同、后方、报知和技术保障等通信的顺畅。', 24);
INSERT INTO `t_military_term_data` VALUES ('8ee00fad-3ff1-4fd3-a07a-ad7c4a0f27ec', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射弹散布密集界', '在射弹散布面上沿任何一条散布轴线对称排列,并包含全部弹着点的70％的两条散布界线间的宽度。在垂直散布面上分为高低散布密集界和方向散布密集界，在水平散布面上分为距离散布密集界和方向散布密集界。', 79);
INSERT INTO `t_military_term_data` VALUES ('8eeba563-7a96-4b94-a47c-e1f8e93c71a8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '锚雷', '由雷锚和雷索将雷体系留在水中一定深度的水雷。', 211);
INSERT INTO `t_military_term_data` VALUES ('8ef9b37f-5f35-44bb-a039-b5b87ebc438f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核能', '亦称原子能。原子核中的核子（质子和中子）束缚在原子核内的一种内能。当核子重新分配时,其能量可部分地释放出来。如核反应和核衰变都能释放能量,其中核反应能分为裂变能和聚变能。', 122);
INSERT INTO `t_military_term_data` VALUES ('8efe33df-02e5-4f1a-b6a9-7b2716a308eb', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '野战工程机械', '伴随部队执行野战工程保障任务的军用工程机械。有装甲工程车、开路机、多用工程车、挖壕机、挖坑机等。主要用于：敌火下克服障碍物,抢修军用道路,构筑急造军路、野战工事和防坦克壕等。', 373);
INSERT INTO `t_military_term_data` VALUES ('8f038ac9-086a-4913-be91-3e74c60f0745', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸方式', '核武器在不同介质、不同高度或深度实施爆炸的方法和形式。分为高空爆炸、空中爆炸、地面或水面爆炸、地下或水下爆炸等。威力相同的核武器爆炸方式不同时,爆炸的外观景象和杀伤破坏作用也不同。', 139);
INSERT INTO `t_military_term_data` VALUES ('8f051008-5363-44f7-9716-58a1e191fe83', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆保障', '组织运用车用车辆对部队遂行各项任务所进行的保障。包括武器装备牵载、人员输送和物资运输等。', 319);
INSERT INTO `t_military_term_data` VALUES ('8f169a36-1f3e-4b90-b49f-ca0617021124', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '时间引信', '亦称定时引信。按照预先装定的时间引爆弹丸的引信。依定时装置的原理,分为机械时间引信、火药时间引信、电子时间引信、化学时间引信等。一般配用于炮弹和航空炸弹。', 335);
INSERT INTO `t_military_term_data` VALUES ('8f19b93e-cb4a-40b5-ade7-52afecf632ba', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵特种射击', '炮兵根据任务需要和敌情、地形、天候、气象等特定情况,采取特种手段进行的射击。主要包括：跳弹射击、空炸射击、高射界射击,利用侦察校射雷达射击、刊用侦察校射飞机射击、利用声测手段射击,夜间射击、山地射击和对水面目标射击,以及发射发烟弹、照明弹、宣传弹、燃烧弹、干扰弹、曳光弹、电视侦察弹等的射击。', 187);
INSERT INTO `t_military_term_data` VALUES ('8f224ce7-3bfa-4c63-b1fc-036973945473', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防登陆障碍物', '设置在近岸水中、水际滩头和岸上,用于阻止或迟滞登陆工具和登陆兵登陆行动的人工障碍物。如水雷区、地雷场、桩砦、三角锥、浮游拦障、削壁、拒马、铁丝网、火障碍物等。', 104);
INSERT INTO `t_military_term_data` VALUES ('8f285d87-5114-4e2e-a4ef-aa0c12b822d1', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '新能源技术', '开发利用新型能源的技术。主要包括对核聚变能、太阳能、风能、生物质能、地热能、海洋能及氢能等开发与利用的技术。', 12);
INSERT INTO `t_military_term_data` VALUES ('8f28f70b-903b-4521-b414-35e59d7bdba3', '98df76fb-4b65-48ff-a56c-4db587327c79', '工作服', '军队专业人员为方便操作和防护需要而着用的军服。一般分为普通工作服和特种工作服两类。', 157);
INSERT INTO `t_military_term_data` VALUES ('8f3021c0-e59c-45eb-b4c2-b0d6a89179dd', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '伪装服', '亦称迷彩服。用于人员伪装的特种军服。属单兵伪装器材。按适用的地区,分为林地型伪装服、荒漠草原型伪装服、沙漠型伪装服、雪地型伪装服等。', 353);
INSERT INTO `t_military_term_data` VALUES ('8f32e927-f3b9-4766-bd71-704e86fe15a5', '06a75831-13a1-4660-870a-455bb445336a', '越级通信', '为保障越级指挥而建立的通信联络。通常只超越一级，必要时可超越数级。', 9);
INSERT INTO `t_military_term_data` VALUES ('8f336832-0806-4029-aacd-75d361a69e7a', '97a19170-bfac-42c5-9906-1acb187f0654', '空中阻击', '歼击航空兵部队在一定的时限和空域内使用较多的飞机升空形成空中屏障,阻拦和抗击敌空袭的作战行动。主要用以夺取局部制空权和掩护陆军、海军部队及其他航空兵部队。', 110);
INSERT INTO `t_military_term_data` VALUES ('8f4cbde5-6a72-4233-87b3-07657f00b607', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '守势', '军队实施的防御作战行动及其态势。', 408);
INSERT INTO `t_military_term_data` VALUES ('8f55dfa1-44b8-4382-9a25-a5467d507635', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场勤务', '为保障顺利构筑和正常使用渡场而进行的各项勤务工作的统称。包括交通调整、水位测量、水上巡逻、救护打捞和维修、警戒等。', 320);
INSERT INTO `t_military_term_data` VALUES ('8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '0', '警戒 .行军 .宿营', NULL, 5);
INSERT INTO `t_military_term_data` VALUES ('8f7164ea-8dad-40a1-9f46-ae10b3e13c0a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '编成', '按照一定的要求把部队或阵地组成有机的整体、如部队编成、阵地编成。', 312);
INSERT INTO `t_military_term_data` VALUES ('8f724642-035a-4da7-b377-31ceef93d73a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '破坏性', '战争或武器所具有的对社会及人员、物体造成毁损的性质。', 277);
INSERT INTO `t_military_term_data` VALUES ('8f8873d7-9d29-4921-bb2b-b40cac6bc8f0', '8a761efd-50a6-4ac8-9913-b7d745104f82', '染色弹', '装填有染色剂,着落后溅落在人员的皮肤、服装或物体上能形成彩色斑点的弹药。主要用于防暴,以便于对凶手追踪、区分和取证。', 195);
INSERT INTO `t_military_term_data` VALUES ('8f96965b-549c-4969-b828-f4f219641263', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场维护', '为保障渡场不间断使用而采取的检查、抢修和各种保养措施的统称。主要包括：维护渡场内的道路与渡口,修复受损的器材,排除漂雷和漂流物,必要时分解桥梁等。', 326);
INSERT INTO `t_military_term_data` VALUES ('8f9833bf-8600-436c-8ac0-4068e08e6abd', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '海峡', '两块陆地之间连接两个海或洋的狭窄水道。分天然海峡和人工海峡。多为海上交通咽喉,可缩短航程和扼控舰船航行,在经济和军事上具有重要地位。', 50);
INSERT INTO `t_military_term_data` VALUES ('8f986cb9-bfef-4883-924f-220145fd4535', '31f4a446-5b98-4873-9d53-310d97125b07', '地地战略导弹', '从陆地发射,主要打击陆地战略目标,射程在1000公里以上的导弹。按飞行轨迹,分为地地弹道战略导弹和地地巡航战略导弹；按战斗部装药,分为地地核战略导弹和地地常规战略导弹；按射程,分为地地洲际战略导弹、地地远程战略导弹和地地中程战略导弹。', 1);
INSERT INTO `t_military_term_data` VALUES ('8f9a0f55-b2dd-45d3-a7bb-962e9f3faa84', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '后方警戒', '位于行军纵队后方,由后卫或后方尖兵实施的警戒。背敌行军时,后方警戒是行军警戒的主要部分。', 8);
INSERT INTO `t_military_term_data` VALUES ('8f9bfd05-8f8b-4c38-a0b5-a61408db75e0', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达告警', '实时截获和识别敌方雷达的照射信号,迅速判明其威胁程度并立即报警的过程。广泛用于飞机、舰艇、坦克等武器对敌方雷达的警戒。', 28);
INSERT INTO `t_military_term_data` VALUES ('8fa13a03-c2f6-46c1-95b6-1c1adac38e9c', '97a19170-bfac-42c5-9906-1acb187f0654', '航空火箭弹', '亦称航空火箭。从飞行的飞机或直升机上发射,以火箭发动机为动力的非制导的爆炸性弹药。由引信、战斗部、发动机、稳定装置等组成。可用以攻击空中、地面或水面目标。', 318);
INSERT INTO `t_military_term_data` VALUES ('8faf2c56-b6ea-480d-a9e7-7567bbaf74aa', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇分区列队', '俗称站坡。舰员按规定的区划和次序沿舰艇左、右舷或一舷面向舷外列队的海军礼仪。通常用于迎送首长、阅兵和外事活动等。', 402);
INSERT INTO `t_military_term_data` VALUES ('8faf828e-3111-4c8a-8ec8-6449d7c9e034', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '门桥长', '在渡场长或浮桥长领导下负责单个门桥的结构、漕渡等作业的指挥员。通常由负责结构门桥的舟桥排长或班长担任。', 324);
INSERT INTO `t_military_term_data` VALUES ('8fb2f542-6a16-49fa-9754-561fc40801e1', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军队指挥学', '研究军队组织指挥的理论及其实施方法的学科。是军事学术的组成部分,与战略学、战役学和战术学有密切联系。主要研究内容有军队组织指挥的基本理论、原则、形式、方法等。', 26);
INSERT INTO `t_military_term_data` VALUES ('8fba7b0a-aa86-4ebb-9420-bc3b4439a9b7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事条约', '国家或政治集团之间缔结的有关军事方面相互权利和义务的各种书面协议的统称。主要形式包括条约、公约、协定、议定书等。有时专指以条约为名的协议,如军事同盟条约、互不侵犯条约等。', 78);
INSERT INTO `t_military_term_data` VALUES ('8fbc3146-d3a3-4c7e-a0f9-be30021780b0', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军械', '以枪械和队属火炮、导弹为主的各种武器、弹药及其配套的仪器、器材和备附件的统称。', 90);
INSERT INTO `t_military_term_data` VALUES ('8fbc6ab6-0eca-48b8-9eeb-3aa3cb4b90ea', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役枢纽', '在战役指挥上需要着重关注的、对战役全局具有决定意义的关键问题。包括战役作战的关键性方向、时机、地点或行动等要害问题。通常要求抓住战役枢纽部署战斗。', 25);
INSERT INTO `t_military_term_data` VALUES ('8fc366f8-f62b-4ed6-8d42-92f0bf9966a7', 'f0140091-c11a-48c9-8836-8aa94439dac0', '中间阵地', '各防御阵地或防御地带之间起辅助作用的阵地。用以制止敌向纵深扩张,并作为预备队实施反冲击、反突击的依托。', 224);
INSERT INTO `t_military_term_data` VALUES ('8fca8e04-dedf-447e-abf5-8a5eedc32f28', '916997ee-6728-4c61-9b79-d96960b1dc86', '核辐射', '在核反应过程中从原子核中发射出来的电离辐射。核爆炸的核辐射,通常分为早期核辐射和剩余核辐射。早期核辐射主要有γ辐射和中子辐射；剩余核辐射主要有γ辐射和β辐射。', 89);
INSERT INTO `t_military_term_data` VALUES ('8fcc3b02-d494-401c-971f-ef5c42df0800', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役样式', '对战役基本类型所作的具体划分。如进攻战役,分为运动战战役、阵地进攻战役、城市进攻战役、登陆战役、空降战役、空中进攻战役、海上进攻战役等；防御战役,分为阵地防御战役、城市防御战役、抗登陆战役、防空战役、海上防御战役等。', 2);
INSERT INTO `t_military_term_data` VALUES ('8fcefc93-1029-4883-a1ef-c729b10a270d', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '步哨', '担负宿营警戒任务并进入预定位置的士兵。分为单哨（1人）和复哨（2人）。由宿营分队或宿营警戒分队派出。', 26);
INSERT INTO `t_military_term_data` VALUES ('8fdbf608-95f8-4f60-99d3-bcbf28f079c8', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '前委', '前敌委员会或前线委员会的简称。中国共产党中央委员会为统一领导某一地区的武装斗争或组织指挥重大战役而在前线设立的党的领导机关、其成员一般由中共中央或中央军委决定,主要由党、政、军有关方面的领导人组成。', 20);
INSERT INTO `t_military_term_data` VALUES ('8fe28f1f-1915-47ff-906b-f790388f4c5e', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '洼地', '近似封闭的比周围地面低洼的地形。通常指陆地表面局部低洼部分,排水不良,中部常积水成湖泊或沼泽,影响人员和车辆通行。也指底部低于海平面的内陆盆地。如中国新疆吐鲁番盆地是世界上面积最大的内陆洼地之一。', 76);
INSERT INTO `t_military_term_data` VALUES ('8feeb0db-52e7-404d-9e4f-f40e727cc894', '98df76fb-4b65-48ff-a56c-4db587327c79', '联合保障', '两支以上军队或两个以上军兵种部队,在统一的计划下,共同组织实施的后勤保障。通常在联合作战或合同作战时采用。', 31);
INSERT INTO `t_military_term_data` VALUES ('8ff8dfd4-c627-433d-830c-fbcb2ad3c923', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '轻装', '部队或分队为提高机动能力而临时减少其携行量和减轻人员的负荷量。通常在执行紧急任务时采用。', 54);
INSERT INTO `t_military_term_data` VALUES ('90094dbd-8883-4900-b4b2-67f12ea3a6c7', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '重力测量', '对地球表面或近地空间某点重力加速度的测量。分为绝对重力测量和相对重力测量。绝对重力测量是直接测定一点的重力值。相对重力测量是测定两点间的重力差,由已知重力点求待定重力点的重力,是重力测量的主要方法。', 220);
INSERT INTO `t_military_term_data` VALUES ('902b3b15-15f2-438d-9a21-04b7ba619d7d', '8a761efd-50a6-4ac8-9913-b7d745104f82', '小型榴弹', '利用专门发射器发射的近距离使用的小型爆炸弹药。有杀伤、破甲、破甲杀伤、燃烧、照明烟幕等弹种。特点是重量小（0.2～0.7千克）,初速低（40～400米/秒）,射程近（2500米以内）弹道弯曲。', 211);
INSERT INTO `t_military_term_data` VALUES ('905c6fc9-17f6-4cfd-8135-d9c85b08c3ee', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高射炮兵群', '简称高炮群。由数个高炮部队或分队临时组成的战斗编组。用以统一组织指挥高射炮兵的作战行动,提高对空掩护效能。', 14);
INSERT INTO `t_military_term_data` VALUES ('90677bcb-138d-42a9-8fc0-f7e34f245435', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '探雷声纳', '用以探测单个水雷或雷阵的声纳。具有识别沉底雷的功能。其中可直接引导灭雷具消灭水雷的探雷声纳,又称猎雷声纳。', 235);
INSERT INTO `t_military_term_data` VALUES ('90687283-77a8-4102-9d99-b02beb32fb0e', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役原则', '战役行动所依据的法则或标准。正确的战役原则,是战役规律的反映。', 18);
INSERT INTO `t_military_term_data` VALUES ('906b7a90-1c72-48a2-9018-cf10eeca4a98', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '通路', '障碍物中的通道。包括设置障碍物时预先留出的通路和在障碍物中临时开辟的通路。分为坦克通路、步兵通路和水中障碍物通路等。', 198);
INSERT INTO `t_military_term_data` VALUES ('906d1317-9b0c-4598-a1e6-b09d9adcf559', '878651de-adf5-4c72-9376-9c363b893ff8', '军事冲突', '亦称武装冲突。敌对双方武装力量之间发生的低强度的军事对抗。就国家之间关系来说,军事冲突尚未构成战争状态。在一定条件下,军事冲突也可能发展成为战争。', 1);
INSERT INTO `t_military_term_data` VALUES ('9075a690-239d-4dc5-b5ba-1d59c3b7ace1', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军战术', '海军部队、分队进行战斗的方法。分为海军合同战术和海军兵种战术。主要包括战斗基本原则、兵力部署、战斗指挥、协同动作、战斗行动方法和各种保障措施等。', 48);
INSERT INTO `t_military_term_data` VALUES ('9079c2bc-1370-4e35-b262-c7f65a0b2828', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '登陆地区', '战役军团登陆和发展岸上进攻的地区。通常包含数个登陆地域。', 72);
INSERT INTO `t_military_term_data` VALUES ('907ee50f-6c5b-47b3-918f-7ac7e857b011', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '现地作业', '亦称实地作业。按照想定在实地研练组织指挥的作业。', 105);
INSERT INTO `t_military_term_data` VALUES ('908bca9e-911b-4f21-984c-84813f48544c', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆初驶', '新车和大修及中修后的车在正常使用前按规定的里程、时速、载重标准和不准拖挂等要求的行驶。用以使车辆各部机件磨合,延长其使用寿命。', 310);
INSERT INTO `t_military_term_data` VALUES ('9090d7f4-cd14-4593-82eb-9306f3f9be16', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵观察所', '炮兵指挥员和指挥分队观察战场、指挥射击的机构和场所。分为基本观察所、预备观察所、前进观察所、侧方观察所、交会观察所和临时观察所等。', 89);
INSERT INTO `t_military_term_data` VALUES ('9098e729-9319-4200-aedd-f7d075de202a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰载机', '以航空母舰或其他水面舰船为活动基地的海军飞机、直升机的统称。分为常规起落舰载机、垂直心距边落舰载机和舰载直升机。', 174);
INSERT INTO `t_military_term_data` VALUES ('90a80548-e11f-4826-8b1c-74b0c4470154', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵战术', '防空兵进行战斗的方法。主要包括防空兵战斗基本原则、兵力部署、掩护方法、战斗指挥、火力运用、协同动作和各种保障措施等。', 9);
INSERT INTO `t_military_term_data` VALUES ('90adb14d-7ce8-42da-81a5-f296448ab8e5', '06a75831-13a1-4660-870a-455bb445336a', '识别信号', '为识别敌我而规定的信号。是协同作战计划中信号规定的内容之一。通常以电信号及灯光、旗语、音响、标志物和口令等表示。主要用于空中飞机、地面部队。海上舰艇的相互识别和指示目标。', 151);
INSERT INTO `t_military_term_data` VALUES ('90af1225-9388-4143-84d5-faba7d890c70', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军信号通信', '海军使用简易信号工具进行的通信。包括灯光、旗语、形体、烟火等视觉通信和音响通信。主要用于岸舰间、舰艇间、舰艇与飞机间传递简短信息。', 361);
INSERT INTO `t_military_term_data` VALUES ('90b14460-4700-4801-accf-24ddd78f5439', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '气象卫星', '能够从大空对地球及其大气层进行气象观测的人造地球卫星。分为太阳同步轨道气象卫星（亦称极轨气象卫星）和地球静止轨道气象卫星（简称静止气象卫星）。气象卫星观测的地域宽广,观测时间长,观测数据汇集迅速,能提高气象预报的质量。', 216);
INSERT INTO `t_military_term_data` VALUES ('90b1a4fc-1629-4b22-b514-4051591daba3', 'f0140091-c11a-48c9-8836-8aa94439dac0', '强攻', '集中优势兵力、火力对防御之敌实施强行攻击的战斗行动。主要用于对坚固阵地防御之敌、野战阵地防御之敌、城市防御之敌的进攻战斗。', 148);
INSERT INTO `t_military_term_data` VALUES ('90b1f775-b2d7-4480-9439-c660f9e56ecf', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '战斗损耗', '因战斗造成的武器、弹药、车辆、油料、器材及其他物资的损失、损坏和消耗的统称。', 91);
INSERT INTO `t_military_term_data` VALUES ('90c19512-1fcf-4900-8338-0fe473e4d88e', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '风速', '空气水平运动的速度。单位为米；秒、千米／时、海里／时等。瞬时风速达到17米／秒（风力8级）以上的地面风称为大风。', 17);
INSERT INTO `t_military_term_data` VALUES ('90c96582-8533-4138-8b9f-5618ece5a201', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '溅落', '航天器回收舱在水面的降落。靠漂浮装置漂浮在水面。', 284);
INSERT INTO `t_military_term_data` VALUES ('90de6e60-1497-4868-952e-17d2c4897d3d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '车辙桥', '桥跨采用车辙式结构（中间有一定间隙）的军用桥梁。如车辙式机械化桥。', 283);
INSERT INTO `t_military_term_data` VALUES ('90ee0d01-8c45-434e-9af2-50f87d42db45', '06a75831-13a1-4660-870a-455bb445336a', '自动化信息传递系统', '在指挥自动化系统中利用通信设备传递信息的分系统。主要由终端、交换、线路,用户和保密设备等组成。具有自动进行信息交换,信息加密与解密,选择路由,控制信息流量等功能。', 162);
INSERT INTO `t_military_term_data` VALUES ('90f0bf6b-d649-4ce7-8daf-f2773a1ff7d6', '98df76fb-4b65-48ff-a56c-4db587327c79', '车公里利用率', '亦称里程利用率。车辆重载行驶里程与总行驶里程的比值。通常用百分比表示。是衡量车辆使用效率的指标之一。', 323);
INSERT INTO `t_military_term_data` VALUES ('90f9874a-3558-4e6e-99aa-a62726bd678b', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '阻塞式电子干扰', '简称阻塞式干扰。干扰频带宽度远大于受干扰电子设备信号频谱的有源压制性电子干扰。可同时干扰多部不同频率的电子设备,不需要精确的频率引导,但干扰功率分散,效率较低。', 48);
INSERT INTO `t_military_term_data` VALUES ('9101d5aa-a71f-44e1-a600-090de9276421', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '猎潜艇', '装有反潜武器,以近海反潜为主要任务的小型水面战斗舰艇。本要用以搜索和攻击潜艇,以及巡逻。警戒、护航和布雷等。', 145);
INSERT INTO `t_military_term_data` VALUES ('9108089e-cab2-487f-88fe-0e3ec950b5a1', '06a75831-13a1-4660-870a-455bb445336a', '固定通信系统', '通信设备固定设置的通信系统。其设备安装在地面建筑物或地下工事内。是战略通信系统的主要组成部分,也可作为战役、战术通信系统的依托。', 168);
INSERT INTO `t_military_term_data` VALUES ('9109d92f-8c8a-449a-bb05-50c1f7227313', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '停战', '交战双方达成协议,停止战争行动的状态。分为有限期停战和无限期停战,局部停战和全面停战。有时把有限期停战和局部停战,称为休战。', 70);
INSERT INTO `t_military_term_data` VALUES ('910a4b02-c126-426e-b484-ec9008c9ffb6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '运河', '人工开挖的沟通不同水系的河流。主要用于水上运输、农田灌溉和城市供水等。', 60);
INSERT INTO `t_military_term_data` VALUES ('912eff25-80dd-4c17-8c30-47b0c159e031', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天飞机', '亦称轨道器。带有机翼的靠运载火箭发射进入太空轨道,返回地面时能在机场跑道水平着陆,并可重复使用的兼有载人、运货功能的航天器。', 221);
INSERT INTO `t_military_term_data` VALUES ('9131075f-aab3-4c69-bb61-7909cb37b183', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核辐射遗传效应', '核辐射对生物体生殖细胞的遗传物质造成的破坏作用。可诱发染色体畸变和基因突变,导致后代的形态或功能异常。', 178);
INSERT INTO `t_military_term_data` VALUES ('9137f6bd-b026-41c7-863d-e1e1c6aec5fc', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '灯火伪装', '通过消除、减弱灯光或模拟目标灯火暴露征候而实施的伪装。', 337);
INSERT INTO `t_military_term_data` VALUES ('9160ee53-4115-46f3-8b19-9266c5009bae', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克修理', '为使坦克或其机件恢复规定的技术状态而进行的维修活动。分为预防性修理和修复性修理。预防性修理有小修、中修和大修,要求按规定间隔时间（里程）定期实施；修复性修理有检修和特修,要求在出现故障后及时进行。', 207);
INSERT INTO `t_military_term_data` VALUES ('916997ee-6728-4c61-9b79-d96960b1dc86', '0', '防化兵 . 三防', NULL, 28);
INSERT INTO `t_military_term_data` VALUES ('917bb8a7-0744-4217-bc14-e7322b1da20e', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮光学火控系统', '主要使用光学仪器探测跟踪空中目标的高射炮火控系统。由光学瞄准镜、光学测距机、火控计算机和高炮随动装置等组成。', 47);
INSERT INTO `t_military_term_data` VALUES ('9181b953-e165-4c35-878c-926c93ec0ce1', '98df76fb-4b65-48ff-a56c-4db587327c79', '军人津贴', '军人定期获得的工资以外的各种补助和补贴的统称。主要包括：军人职业津贴、士兵津贴、地区津贴,专业补助、福利补助、伙食补贴和其他津贴等。', 87);
INSERT INTO `t_military_term_data` VALUES ('919a6fc0-1a25-47ea-9597-7e5ad38881e1', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机战术技术性能', '由设计制造等因素决定的军用飞机所具备的固有特性和功能。主要包括：飞机发动机的数量和功率,飞机的飞行速度、上升率、升限、航程、续航时间、起落滑跑距离,机动性、操纵性、抗干扰性以及机载武器性能、载弹量等。', 295);
INSERT INTO `t_military_term_data` VALUES ('919dfc7f-918b-41d1-98bb-4b0b54d3c20d', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '登陆工具', '输送登陆兵抢滩上陆用的各类舰艇（船）、两栖车辆、直升机等的统称。', 69);
INSERT INTO `t_military_term_data` VALUES ('919fa413-fd5f-4acd-be7d-799ba3ea5696', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵试射点', '炮兵为求出射击条件修正量而设定的进行试验射击的点。分为实有试射点和虚设试射点。', 150);
INSERT INTO `t_military_term_data` VALUES ('91b85142-d53c-43b5-bc91-3c42e04deeea', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核燃料', '亦称核材料。能发生核反应并释放出巨大能量的物质。分为裂变核燃料与聚变核燃料。可作为核武器的装料和核电站、核潜艇等核动力装置的燃料。', 116);
INSERT INTO `t_military_term_data` VALUES ('91b8f395-0f82-4582-b730-06bda34b68b0', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹飞行被动段', '亦称无动力飞行段。弹道导弹在其发动机关闭后飞行的一段弹道。包括自由飞行段和再入段。', 76);
INSERT INTO `t_military_term_data` VALUES ('91c09e96-c89f-4cdc-b848-b331d8a77ed4', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '军事气象条件', '符合作战、训练或其他军事活动要求的大气环境状态。通常根据军事活动的性质、规模、样式,武器装备的类型、性能,军事训练水平以及自然地理条件等具体确定。', 81);
INSERT INTO `t_military_term_data` VALUES ('91ce11e5-3b1a-4bc3-abb8-2957e891aa0f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '枪法原子弹', '亦称压拢型原子弹。利用炸药爆炸产生的强驱动力,把两块以上处于次临界状态的裂变装料迅速推拢在一起,达到超临界状态从而发生核爆炸的原子弹。', 85);
INSERT INTO `t_military_term_data` VALUES ('91cffaf0-f0bc-4834-93b7-be1e88c32e1e', 'f0140091-c11a-48c9-8836-8aa94439dac0', '障碍设置队展开地区', '障碍设置队展开成战斗队形的地区。通常选择在受敌坦克严重威胁方向上便于机动设置障碍物的位置。', 235);
INSERT INTO `t_military_term_data` VALUES ('91d8cd7d-ac9c-4dfc-ae6b-ece43aeea075', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '声纳', '利用声波对水中目标进行探测、定位和识别的水声设备。分为警戒声纳、攻击声纳、探雷声纳、导航声纳、通信声纳和识别声纳等。装备于舰艇、反潜机、海岸声纳站和反潜预警系统。主要用于对潜艇、水面舰船、水雷、鱼雷的搜索、警戒、跟踪和监视,也可用于水下导航定位、沉船探测和水下近距离通信等。', 232);
INSERT INTO `t_military_term_data` VALUES ('91df3ca3-21fb-4d25-93ea-3492b192b124', '97a19170-bfac-42c5-9906-1acb187f0654', '黄昏飞行', '从日没到天黑前的时间内实施的飞行。光线微弱,地标模糊,主要依靠机上仪表和飞行导航设备进行。', 221);
INSERT INTO `t_military_term_data` VALUES ('91eacf28-afaa-4e4b-bc00-34a0637dcd20', '97a19170-bfac-42c5-9906-1acb187f0654', '空战', '①敌对双方航空兵在空中进行的战役、战斗的统称。②专指空对空战斗。即歼击机或歼击直升机对空中之敌实施的空中截击或空中格斗。空战过程由空中搜索、接敌、攻击和退出战斗等阶段组成。按攻击距离,分为远距空战、中距空战和近距空战。', 68);
INSERT INTO `t_military_term_data` VALUES ('91ffb9a5-89b9-47e2-aa81-25eed14333a9', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '星箭分离点', '载有人造卫星的运载火箭达到预定的高度和速度,卫星与运载火箭分离时所在的位置。也是低轨道卫星进入运行轨道的初始位置。', 256);
INSERT INTO `t_military_term_data` VALUES ('92016300-5c44-4ac2-9c12-6687d15732c5', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '兵员动员', '国家根据战争需要所采取的征募兵员、扩充军队的紧急措施。主要是使全部或部分预备役人员转服现役。', 51);
INSERT INTO `t_military_term_data` VALUES ('9201a992-3a85-422d-9206-35657fe19b82', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '行政例会制度', '军队中关于部队或分队定期召开行政工作会议的制度。主要包括在一定时间内召开例会的次数、参加人、主持人、内容等的规定。连队的行政例会通常有班务会、排务会、连务会和连军人大会。', 12);
INSERT INTO `t_military_term_data` VALUES ('92038277-2603-4b45-9d36-fcd1de3994df', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水面舰艇', '在水面遂行作战和战斗保障任务的舰艇的统称。包括水面战斗舰艇、登陆作战舰艇和勤务舰船。水面战斗舰艇和登陆舰艇中通常把正常排水量500吨及其以上的称为舰,500吨以下的称为艇。', 131);
INSERT INTO `t_military_term_data` VALUES ('92490042-c4e3-40be-8f1e-42e41f13b8d8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '超口径炮弹', '弹丸直径大于发射该种炮弹的火炮口径的炮弹。如迫击炮使用的长弹和火箭筒使用的破甲弹等。威力比普通炮弹大。', 323);
INSERT INTO `t_military_term_data` VALUES ('924fb466-ec28-4aa7-9499-f6d7f8d6122c', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '电子地图', '储存于磁盘、光盘等介质上,利用电子计算机图形显示系统进行阅读的平面或立体地图。', 256);
INSERT INTO `t_military_term_data` VALUES ('925de3f8-b524-4dfc-aec7-95440273f944', '97a19170-bfac-42c5-9906-1acb187f0654', '引导雷达', '主要用以保障有关人员指引飞机截击空中目标的雷达。能较准确测定目标的方位、距离和高度。', 345);
INSERT INTO `t_military_term_data` VALUES ('9261910f-395b-489f-af0f-fa578edbb400', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '驱逐舰', '以导弹、鱼雷、舰炮为主要武器,具有多种作战能力的中型水面战斗舰艇。包括对海型、防空型、反潜型和多用途卫等驱逐舰。主要用以攻击敌水面舰船和潜艇,担负己方舰艇编队的防空、反潜,以及护航、侦察、巡逻、警戒,支援登陆和抗登陆作战等。', 134);
INSERT INTO `t_military_term_data` VALUES ('926b2bb1-2840-4b57-a087-2402c5030763', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹飞行试验安控', '防止因导弹在飞行试验中发生故障或偏离预定弹道而危及地面安全所采取的控制措施。由地面安控系统和弹上安控系统两部分组成。地面安控系统用于对导弹飞行状态进行监视、判断和发出炸毁指令；弹上安控系统用于接收、判别炸毁指令,并引爆炸毁导弹。', 73);
INSERT INTO `t_military_term_data` VALUES ('926d4ca2-ca5c-41a7-a97a-144f2f7015a2', '97a19170-bfac-42c5-9906-1acb187f0654', '战役轰炸', '为达成一定的战役目的而对敌战役目标进行的轰炸。', 93);
INSERT INTO `t_military_term_data` VALUES ('92828711-1a36-4dd2-8347-bcc909697572', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '密码电报', '采用密码方式传送的军用文书。', 115);
INSERT INTO `t_military_term_data` VALUES ('9284c368-d121-475c-9424-34ca7355842a', '06a75831-13a1-4660-870a-455bb445336a', '蜂窝式移动通信系统', '亦称蜂房式移动通信系统。将通信地域划分成若干个半径为2～10千米左右的蜂房式（六边形）小区而组成的移动通信系统。每个小区设一基地台,为该小区内的移动用户接转信息。用户跨越相邻小区边界时,可自动切换信道而不影响通信。', 170);
INSERT INTO `t_military_term_data` VALUES ('92879820-7d7a-44a6-acad-8e778dedeb36', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '下达命令', '以书面或口头形式向受令对象告之命令内容的活动、要求简明、准确、迅速、保密。', 128);
INSERT INTO `t_military_term_data` VALUES ('9288f9a5-ba08-4d1b-bccc-c762c10c318a', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤按方向部署', '将后勤力量区分为两部分,分别配置在两个方向上的后勤部署。通常为集团军以下后勤在作战正面较宽、受地形道路限制时采用。', 54);
INSERT INTO `t_military_term_data` VALUES ('92a1d122-6b4d-4c8f-9006-ef866e3e2e73', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '投降', '军队或其人员被迫停止抵抗,放下武器,屈服于对方的行为。', 388);
INSERT INTO `t_military_term_data` VALUES ('92b48662-0d35-46d3-967b-e8a720cf1646', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤装备', '军队为实施后勤保障所编配的专用车辆、装具、机械、器材和运输工具等的统称。分为通用后勤装备和专用后勤装备。是军队装备的重要组成部分。', 19);
INSERT INTO `t_military_term_data` VALUES ('92bfa36d-aa60-447d-afe2-a2d9b032eb8b', '97a19170-bfac-42c5-9906-1acb187f0654', '航路', '由国家航空管制部门统一划定的具有一定宽度和高度范围的空中飞行通道。宽度通常为20公里。航路经过的地面设有较完善的通信、导航设备,用以维持空中交通秩序,提高空间利用率,保证飞行安全。', 380);
INSERT INTO `t_military_term_data` VALUES ('92c48a70-73c7-424d-9190-ea3fcd987d7e', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核试验放射性泄漏', '地下核试验后,放射性物质通过岩石裂隙、断层等进入大气环境中的现象。', 187);
INSERT INTO `t_military_term_data` VALUES ('92cb3a32-2459-451e-b4a9-2c4177186cd1', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察台', '亦称搜索台、搜索无线电通信网台的基本侦察业务单位。', 77);
INSERT INTO `t_military_term_data` VALUES ('92cfd765-9ccc-4f6a-bcbd-13fa65f6e95e', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射表', '在标准气象条件下，某种射击武器及配用弹药的射角与射程等弹道诸元之间对应关系的数据表。表内载有弹道基本诸元、修正诸元、散布诸元等。用以决定射击诸元和射击指挥。', 62);
INSERT INTO `t_military_term_data` VALUES ('92db51bc-54d1-4edd-83ee-d9543a6b4686', '06a75831-13a1-4660-870a-455bb445336a', '通信计划', '亦称通信保障计划。为组织实施通信联络而制定的计划。主要包括：通信联络的组织,通信枢纽的布局和转移方案,通信部队和分队的任务区分和战斗编组,作战地域内既设通信设施的利用方案,通信器材供应和技术保障勤务的组织,通信保密和隐蔽指挥文书的使用,通信防护和通信对抗的措施,完成通信联络准备工作的时限等。', 31);
INSERT INTO `t_military_term_data` VALUES ('92e7ff6b-f317-4da2-9e36-052167cc164a', '97a19170-bfac-42c5-9906-1acb187f0654', '前沿机场', '亦称一线机场。靠近国境线或战线前沿地区的军用机场。通常进驻歼击、强击航空兵部队,也可作为其他航空兵部队的隐蔽出动基地或前进基地。', 414);
INSERT INTO `t_military_term_data` VALUES ('9311e0e0-5ebe-466f-8bde-bd0113a24790', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战目的', '作战所要达到的预期结果。', 116);
INSERT INTO `t_military_term_data` VALUES ('9313b26e-1b99-41c7-bf01-027c88f0854f', '06a75831-13a1-4660-870a-455bb445336a', '指挥机', '分队指挥员亲自携带并用于指挥的一种对讲机。主要用以建立连、排指挥员之间的通信联络,有时也用于火器分队或执行重要任务的小分队的通信联络。', 176);
INSERT INTO `t_military_term_data` VALUES ('9314dee2-2106-4a22-8007-061d3b505543', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '冲击桥', '亦称强击桥。保障坦克和其他装甲车辆冲击时克服壕、沟等障碍的军用桥梁。多用坦克架桥车架设。', 285);
INSERT INTO `t_military_term_data` VALUES ('9321565c-8341-43c4-9c02-dbd2c50c0059', '916997ee-6728-4c61-9b79-d96960b1dc86', '个人剂量检查仪', '简称剂量仪。测量人员吸收剂量的核辐射剂量的仪器。分为直读式剂量仪和非直读式剂量仪。用于核爆炸时对人员所受旱期核辐射和剩余核辐射累积剂量的监测。', 157);
INSERT INTO `t_military_term_data` VALUES ('93350ffb-0858-4e7a-96a0-b9d70094232c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火箭增程弹', '弹丸内外交困尾部装有火箭助推器以增加射程的炮弹。有榴弹炮火箭增程弹、迫击炮火箭增程弹和无坐力炮火箭增程弹等。增程率可达25％～100％。', 313);
INSERT INTO `t_military_term_data` VALUES ('934c4c64-ccb1-479e-abb8-6c2faa95ee7b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '进攻正面', '进攻的部队展开后朝向敌方的一面。分为战役进攻正面和战术进攻正面。其宽度通常由进攻作战任务、地形条件、兵力兵器数质量等因素决定。', 280);
INSERT INTO `t_military_term_data` VALUES ('935ef90b-9b36-453a-b1a8-94ada991ae8e', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击指挥', '高射炮兵指挥员组织和运用火力的指挥。主要包括：组织实施对空侦察,分析判断情况,选定射击目标,确定火力运用方法,下达射击任务,实施火力机动,组织射弹观察和修正射击偏差,组织战斗协同,监督部队战斗行动等。', 143);
INSERT INTO `t_military_term_data` VALUES ('9367a327-fd18-4402-8ebc-63466851ce79', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克维修制度', '为实施坦克维修工作而制定的一系列管理制度。包括坦克保养制度和坦克修理制度。主要内容有坦克维修级别、维修类型、各类维修间隔期、维修项目等方面的规定。由坦克维修管理部门制定。', 196);
INSERT INTO `t_military_term_data` VALUES ('936f2e25-7527-4673-945f-3b2b2a894528', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程器材', '工程作业使用的器具和材料的统称。主要包括制式工程器材、就便工程器材以及相关的维修设备和配件等。制式工程器材属于工程装备。就便工程器材指就地搜集的工程器材。', 35);
INSERT INTO `t_military_term_data` VALUES ('9372d705-d679-4baf-a3ca-75e58ea221f1', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '接替指挥', '指挥员或指挥所从另一指拧员或指挥所接过指挥任务并继续实施指挥。', 23);
INSERT INTO `t_military_term_data` VALUES ('93770d7e-9983-4beb-aa66-6575bb7f9fc1', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机洞库', '为防敌空袭而构筑在机场附近的,能停放多架飞机或直升机的坑道式或掘开式工事。', 436);
INSERT INTO `t_military_term_data` VALUES ('937b5482-ca93-4547-a69a-427c4d84743f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮牵引车', '牵引火炮的专用车辆。有轮式和履带式两类。除能牵引火炮外,还可载运炮手和随炮弹药。', 293);
INSERT INTO `t_military_term_data` VALUES ('93855443-33c8-46c8-b36a-dc2a8dcfca0b', '98df76fb-4b65-48ff-a56c-4db587327c79', '兽医勤务', '运用兽医理论、技术、装备等为军用动物健康和军队人员安全服务的专业勤务。主要负责组织军用动物伤病、人畜共患疾病、食用动物疾病的防治,以及动物性食品的兽医卫生检验与监督。', 231);
INSERT INTO `t_military_term_data` VALUES ('938bdc77-8e92-48c8-9fe8-a0be94d87bd5', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '退休', '①军队干部服现役满一定年限,退出现役休养。②军队在编职工工作满一定年限,按规定退出工作岗位休养。', 161);
INSERT INTO `t_military_term_data` VALUES ('93955f73-bf34-4113-9a60-5356f87cfc88', '916997ee-6728-4c61-9b79-d96960b1dc86', '燃烧武器', '以燃烧剂的燃烧效应起毁伤作用的武器。有各种燃烧弹药和各种喷火器等。按使用方式,分为爆炸型燃烧武器、抛撒型燃烧武器和喷射型燃烧武器。', 232);
INSERT INTO `t_military_term_data` VALUES ('93a92b8a-235a-41da-b000-6b575f3111db', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航海日志', '舰艇上记载航行过程和情况的主要文书。用以分析航行情况,总结航海经验,积累航海资料。是处理海事时具有法律效力的原始记录。', 275);
INSERT INTO `t_military_term_data` VALUES ('93aade46-14a3-4f3c-93de-8d132262090d', '878651de-adf5-4c72-9376-9c363b893ff8', '战略基地', '对国防或战争全局具有重要作用的军事基地。如战略导弹基地、战略空军基地、战略物资补给基地等。', 91);
INSERT INTO `t_military_term_data` VALUES ('93ceec80-f83e-4c11-9721-a4664a9da78a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '偏差法试射', '根据测定的炸点偏差量直接求出修正量并进行修正,以确定目标效力射开始诸元或实有试射点成果诸元的试射。是试射的基本方法。', 152);
INSERT INTO `t_military_term_data` VALUES ('93e3179a-8728-49f4-8a23-db2b8c0e6133', '98df76fb-4b65-48ff-a56c-4db587327c79', '军用车辆', '军队编配的各种汽车、牵引车和摩托车的统称。按编配用途,分为载重车、牵引车、特种车、指挥车和乘座车等。其中汽车按使用条件,又分为越野汽车和非越野汽车。', 292);
INSERT INTO `t_military_term_data` VALUES ('93fb2705-c27d-4462-9616-d6c485b6466f', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力报复', '在遭受敌方打击或某一地区被敌占领后,立即进行的报复性火力反击。', 104);
INSERT INTO `t_military_term_data` VALUES ('93fde4de-ca01-4d91-89ec-3ff48e6c44c9', '8a761efd-50a6-4ac8-9913-b7d745104f82', '倒射', '亦称反射。敌越过射手所在位置后,射手向敌背面进行的射击。', 110);
INSERT INTO `t_military_term_data` VALUES ('93feda86-219f-4d24-bbd3-0d9baef87313', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '地雷场移交', '将地雷场移交给受地雷场掩护的部队的行动。包括布雷分队将布设好的地雷场向防御部队移交和防御部队换班时的移交。移交时,除移交地雷场文件外,还应在现地指出地雷场的位置和介绍有关情况。', 192);
INSERT INTO `t_military_term_data` VALUES ('940af47e-5fe2-4bbe-884b-419d4b7cf1cc', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '志愿兵役制', '招收志愿人员参加军队的制度。如中国共产党领导的人民军队,在革命战争时期和中华人民共和国成立初期所实行的志愿兵役制。', 24);
INSERT INTO `t_military_term_data` VALUES ('9413af73-d5c4-4fb3-ae2e-1cd6caa8d066', '98df76fb-4b65-48ff-a56c-4db587327c79', '支前供应站', '地方政府为支援军队作战而开设的物资供应机构。主要供应粮袜、副食、燃料、日用品等。', 42);
INSERT INTO `t_military_term_data` VALUES ('941976ca-2400-41c2-9c5d-42261e457706', 'd7132c58-5df3-4b97-919f-58740148b9ca', '短距出击', '高炮分队迅速进入配置地城附近有利位置,歼灭敌机的战术手段。通常在执行固定掩护任务并已掌握敌机活动规律时采用。', 74);
INSERT INTO `t_military_term_data` VALUES ('94395521-090c-4f01-a02a-fdda1bedbb8d', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天气系统', '具有典型特征并伴随一定天气的大气运动形式。是气旋、反气旋、锋、高空槽、切变线等的统称。', 35);
INSERT INTO `t_military_term_data` VALUES ('944988e2-87a2-430d-b4aa-7fdb76749fcd', '8a761efd-50a6-4ac8-9913-b7d745104f82', '追随射击', '直瞄武器将瞄准线指向目标的前方，计算出提前量（选好修正分划），随目标运动平稳移动火身，在追随过程中实施的射击。是对直升机、伞兵、地面车辆等运动目标常用的射击方法。', 97);
INSERT INTO `t_military_term_data` VALUES ('9473db77-8525-48bd-8cc6-46c0b081418d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '热带山岳丛林地', '分布在热带地区植被茂密的山地。特征是：气候湿热,山高坡陡,沟深谷狭,河流纵横,林密草深,藤葛攀缠,路少人稀,毒虫较多等。军事上便于隐蔽、伪装,但不便于机动、联络,运输补给困难,易患疾病和迷失方向。', 117);
INSERT INTO `t_military_term_data` VALUES ('947e3f53-16d9-4ef5-908c-dc6f4b6757a9', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击精度', '射弹命中目标的精确程度。决定于射击准度和射弹密集度。', 72);
INSERT INTO `t_military_term_data` VALUES ('9484456f-2a57-4d8c-9d18-faa99e750dc3', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹加注推进剂', '将槽车或固定储罐内的液体推进剂注入液体导弹推进剂储箱的过程。是液体导弹发射准备中的一项重要工作。', 100);
INSERT INTO `t_military_term_data` VALUES ('94907088-4a07-4f2c-9865-cd9c711bb927', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '电子战', '运用电子对抗的手段进行的作战。', 147);
INSERT INTO `t_military_term_data` VALUES ('949e92c3-a9b1-4d98-b235-02471621f345', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹阵地维护', '为使导弹阵地保持完好状态而进行的技术管理工作。主要包括：工程设施的检测、维修和保养,人员、装备环境技术条件的监控,技术性安全防护,阵地隐蔽伪装等。', 203);
INSERT INTO `t_military_term_data` VALUES ('94aaeb80-fef5-4d9f-9927-496d573f340c', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '气象水文判断', '对遂行任务地区的气象、水文情况进行分析研究并得出结论的思维活动、主要判明气象、水文的特点及其对敌我双方武器装备使用和遂行任务的影响。', 72);
INSERT INTO `t_military_term_data` VALUES ('94b12475-1e49-416c-95da-32e839ea003c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '纪律教育', '以维护和执行军队纪律为主要内容的教育。', 98);
INSERT INTO `t_military_term_data` VALUES ('94b2e024-5b5a-4279-80dd-bbc562ade522', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹训练弹', '简称训练弹。供操作训练和教学用的导弹。', 18);
INSERT INTO `t_military_term_data` VALUES ('94b9d17c-f8f5-45b6-8b81-60a53e3c8bc3', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '简易法', '根据简易测地决定的测地诸元以及完整性较差、精确度较低的弹道、气象资料,确定并修入射击条件修正量以决定射击开始诸元的方法。简易法精度较差,一般只用以决定试射开始诸元。', 144);
INSERT INTO `t_military_term_data` VALUES ('94c298f6-9f45-4469-b4c2-c3bd889a3325', '878651de-adf5-4c72-9376-9c363b893ff8', '战争性质', '战争的政治属性。依据战争的结果是否推动社会进步而定。分为正义的和非正义的两大类。', 6);
INSERT INTO `t_military_term_data` VALUES ('94cd0a2d-1893-4560-a3d9-3b31ee257f0d', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '同位素分离', '提高同位素混合物中某一同位素丰度或将某一同位素从同位素混合物中分离出来的物理或化学过程。', 121);
INSERT INTO `t_military_term_data` VALUES ('94e839aa-c7ca-4865-8c26-fc7579fe459b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '测地卫星', '用于大地测量的人造地球卫星。可测定地面点位坐标、地球形体和地球引力场等参数。', 215);
INSERT INTO `t_military_term_data` VALUES ('94ec046a-20d3-4a50-8a30-3755ab32de35', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教程', '某一学科一定范围内知识体系的完整阐述。是实施军事训练的基本教材。如战略学教程、炮兵射击教程等。', 38);
INSERT INTO `t_military_term_data` VALUES ('94ecb3dc-e452-4e6e-bde4-0489fb5e7925', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '放射性落下灰', '核爆炸后沉降到地面和水中的放射性微粒。直径大多数小于几微米。粒度大的较易沉降,是造成近区地面和物体沾染的主要因素；粒度小的不易沉降,随气流传播很远,可造成大面积的环境污染。', 171);
INSERT INTO `t_military_term_data` VALUES ('94f6aedf-2f59-4194-8f6a-74aa8224aa1c', '8a761efd-50a6-4ac8-9913-b7d745104f82', '无壳枪弹', '发射后没有弹壳抛出口没有剩余物留在枪膛内的枪弹。通常由弹头、发射药柱和可燃底火等构成、无壳枪弹可节省金属材料,减小枪弹体积,减轻弹重、携行量可增大一倍多。', 206);
INSERT INTO `t_military_term_data` VALUES ('950fc0b9-f03b-4f76-8f56-dfec967e52cf', '916997ee-6728-4c61-9b79-d96960b1dc86', '扰乱性化学袭击', '以扰乱敌作战行动,疲惫其有生力量为主要目的的化学袭击。通常用少量速效性毒剂不定时地对敌实施。', 25);
INSERT INTO `t_military_term_data` VALUES ('95196626-dd50-4838-aacc-39f9216b63d9', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战斗保障', '兵团或部队、分队为顺利遂行战斗任务而采取的各项保证性措施与进行的相应活动的统称。主要包括：战术范围内的侦察、警戒、通信、电子防御、工程、伪装、气象、水文和对核、化学、生物、燃烧武器袭击的防护等作战保障,以及后勤、技术、政治工作等保障。海军、空军、第二炮兵还有其特有的战斗保障。', 45);
INSERT INTO `t_military_term_data` VALUES ('951b811d-7ec1-4788-aa5b-13842de004dc', '8a761efd-50a6-4ac8-9913-b7d745104f82', '密位', '军事上常用的测角单位。将圆周分作6000等分,每一等分弧长所对应的圆心角为1密位,写法是00－01。6000密位则写为60－00。', 82);
INSERT INTO `t_military_term_data` VALUES ('951b917e-1e5e-4878-9fdc-f976cf7f426a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击指挥系统', '炮兵用于射击指挥的数据处理和信息传输的自动化系统。分为炮兵群。营、连等各级射击指挥系统。通常由电子计算机及有关软件、信息传输终端和通信设备等组成。数据处理功能强,射击诸元计算精度高,信息传输快,能进行方案评定和辅助决策。', 295);
INSERT INTO `t_military_term_data` VALUES ('951d1a97-bfdd-45ed-a12a-01b45bcdbb99', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军登陆艇', '陆军编配的用以运送兵员和武器装备,能在岸滩直接登陆的艇。', 326);
INSERT INTO `t_military_term_data` VALUES ('9525ff3e-ee18-439d-857a-69dbf159616f', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察员', '担负侦察任务的人员。', 80);
INSERT INTO `t_military_term_data` VALUES ('95270651-350d-4ad7-abc4-8bebd91b308b', '98df76fb-4b65-48ff-a56c-4db587327c79', '军费', '国家用于军队建设和作战的经费。主要包括：人员生活费,公务事业费,教育训练费,科学研究费,装备购置与维修管理费,基本建设费,油料购置费,战备作战费等。', 79);
INSERT INTO `t_military_term_data` VALUES ('9533e7c5-7027-4e05-bf7f-09d4e717ea14', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '首长', '①军人在行政职务上有隶属关系时,行政职务高者。②泛指连级以上各级领导干部。③对职务较高的军队和地方领导干部的尊称。', 123);
INSERT INTO `t_military_term_data` VALUES ('9538c635-0815-4730-bb55-e176d1fa96da', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高射炮兵分队', '简称高炮分队。高射炮兵营、连、排、班的统称。', 7);
INSERT INTO `t_military_term_data` VALUES ('953c0414-c072-4c30-8d9f-a74de42b365c', '98df76fb-4b65-48ff-a56c-4db587327c79', '营区环境保护', '保护和改善营区环境,防止环境污染的专项营房工作。', 235);
INSERT INTO `t_military_term_data` VALUES ('95487d88-b83d-41a1-9b74-48c0d9a369d1', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵空炸射击', '装定空炸引信使射弹在空中爆炸的射击。通常用以毁伤直升机、歼灭或压制空降兵以及暴露的和无掩盖掩体内的有生力量和火器。', 190);
INSERT INTO `t_military_term_data` VALUES ('95529491-c1b6-4b34-8035-55af5f9bb8af', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '深水炸弹', '简称深弹。能在水中一定深度爆炸,用以攻击潜艇的水中武器。按携带方式,分为舰用深水炸弹和航空深水炸弹；按装药性质,分为核深水炸弹和常规深水炸弹。由水面舰艇或飞机、直升机发射或投射。', 225);
INSERT INTO `t_military_term_data` VALUES ('9552dc99-41c3-4fc2-b306-88c6599e7485', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹射击', '地空导弹部队或分队使用地空导弹武器系统对空中目标进行的射击。包括射击准备和射击实施。', 194);
INSERT INTO `t_military_term_data` VALUES ('9567851c-f86c-4a3c-b5ff-44f290869389', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰类', '按基本使命划分的舰艇类别。通常分为战斗舰艇、登陆作战舰艇和勤务舰船3类。', 122);
INSERT INTO `t_military_term_data` VALUES ('9576de7f-dddd-4457-8af7-48ea0c45273d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '炮控点', '炮兵控制点的简称。依据大地点和军用控制点加密的供炮兵使用的控制点。其密度平均为2～4平方公里1个点。是炮兵连测战斗队形的基础,其精度将直接影响射击效果。', 168);
INSERT INTO `t_military_term_data` VALUES ('9584023d-00c2-4835-8d7c-b9a9181c5729', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核钻地弹', '能钻入地下一定深度后爆炸的核炸弹或核导弹弹头。对地下结构的摧毁效果比同等威力的地面爆炸大20～50倍。主要利用核爆炸产生的地震冲击波和成坑效应破坏敌方加固的地下军事目标,也可用以攻击藏在极深冰层下的敌方目标。', 112);
INSERT INTO `t_military_term_data` VALUES ('958eb8ac-3a14-4c0f-bd2e-98e2035272c5', '97a19170-bfac-42c5-9906-1acb187f0654', '空降单位', '空降人员、物资数量的计算单位。以一名空降人或一件空投物品为一个空降单位。计算的标准重量是：每名武装士兵伞降时为120千克,机降时为100千克；每件物资空投时,小件为120千克,中件为500千克,大件为1000千克以上。', 160);
INSERT INTO `t_military_term_data` VALUES ('9596a831-0c73-4e76-a3bf-abb7f1324501', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '反坦克导弹分队专业训练', '反坦克导弹分队进行的以专业知识和作战技能为主要内容的训练。包括专业技术训练和专业战术训练。', 127);
INSERT INTO `t_military_term_data` VALUES ('95a3bdc0-88f5-4a98-bcc0-7c5d16d88364', 'f0140091-c11a-48c9-8836-8aa94439dac0', '化学突破口', '现称化学袭击缺口。使用化学武器在敌防御部署中打开的缺口。', 192);
INSERT INTO `t_military_term_data` VALUES ('95b743b9-9d47-4784-b2dd-d3ef318e1cae', '878651de-adf5-4c72-9376-9c363b893ff8', '战略机动', '军队为达成一定的战略目的而进行的兵力、兵器移动。通常由统帅部组织或根据统帅部意图实施,以形成有利的战略态势,夺取和保持战略主动权。', 101);
INSERT INTO `t_military_term_data` VALUES ('95b933eb-066a-4549-8907-6ed0854f8aea', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵环形配置', '将数个防空兵分队按照一定间隔在被掩护目标四周所作的略成环状的配置。通常在掩护部队实施环形防御和坚守要点时采用。', 22);
INSERT INTO `t_military_term_data` VALUES ('95bfc01e-8543-449b-9baa-4d7cd37e4f8a', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '排雷（弹）', '使地雷、水雷及未爆炸弹等爆炸物失效或将其移走、销毁的行动。', 196);
INSERT INTO `t_military_term_data` VALUES ('95c75317-2357-41be-a45a-6a8ce93d9305', '97a19170-bfac-42c5-9906-1acb187f0654', '雷达警戒线', '在一定的地段部署多部雷达时,各部雷达最大探测距离线相互衔接所构成的对空警戒范围的边缘线。', 396);
INSERT INTO `t_military_term_data` VALUES ('95edf2b4-9052-4d76-b22f-b9f5e280ae8f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '司令部工作', '军队司令部为辅助首长对军事建设、作战及其他行动的组织领导而进行的有关业务工作。', 159);
INSERT INTO `t_military_term_data` VALUES ('95f3543d-346c-4968-ab3c-b3bad0a188cb', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '巡洋舰', '具有多种作战能力,能在远洋活动的大型水面战斗舰艇。按排水量,分为轻型巡洋舰和重型巡洋舰；按动力,分为常规动力巡洋舰和核动力巡洋舰。主要用以掩护航空母舰编队或其他舰船编队保卫己方海上交通线或破坏敌方海上交通线,攻击敌方舰艇和岸上目标,支援登陆和抗登陆作战等。', 133);
INSERT INTO `t_military_term_data` VALUES ('95fd8b86-362a-454d-8656-5b5db51e867c', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '调整哨', '行军中执行调整勤务并进入预定位置的人员。其位置通常设在行军沿途的各调整点以及桥梁、渡口、隘路、交叉路口等处。', 68);
INSERT INTO `t_military_term_data` VALUES ('96179f7d-dfb5-4ba8-ae78-bd34964e1726', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '电障碍物', '带有高压电的铁丝网（简称电网）或铁丝构成的非爆炸性障碍物。主要用以迟滞和杀伤有生力量。抗登陆作战时,通电铁丝可敷设在水下,使一定水域带电。', 112);
INSERT INTO `t_military_term_data` VALUES ('961e4e41-b987-4feb-b55c-dc6bc1074198', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '歼灭战', '消灭敌全部或大部有生力量的作战。', 133);
INSERT INTO `t_military_term_data` VALUES ('962b35cb-5226-4e29-ba96-d6bdf82288c6', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤保障关系', '后勤机构与保障对象之间在后勤保障活动中所构成的工作关系。', 23);
INSERT INTO `t_military_term_data` VALUES ('96343531-d012-40a0-8371-d8087e510597', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '杀伤概率', '表示武器系统在给定射击条件下,射弹（战斗部）杀伤给定生动目标的可能性大小的量。通常用0～1之间的数值表示。杀伤概率的大小取决于武器性能、弹药威力、战斗或射击条件、目标的防护能力等因素。', 189);
INSERT INTO `t_military_term_data` VALUES ('96412457-24a4-468e-8751-b04352066553', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事集团', '两个以上国家或政治集团结成的军事联盟组织。如第二次世界大战后建立的北大西洋公约组织和华沙条约组织。有时也指某一国内的大的武装集团。如中国北洋政府时期的奉系、直系、皖系军阀等军事集团。', 84);
INSERT INTO `t_military_term_data` VALUES ('9642d964-b389-42c6-8c96-afa036575626', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境地区', '一个国家紧靠陆地边界的一定地区。面积的大小随不同国家和不同的地段而异。', 82);
INSERT INTO `t_military_term_data` VALUES ('9657bfb3-cc82-49a6-812e-79aca63ba489', 'f0140091-c11a-48c9-8836-8aa94439dac0', '瞰制', '从高处对低处的控制。', 73);
INSERT INTO `t_military_term_data` VALUES ('965a408f-a128-4bdb-a41b-4a6453ccbebf', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役纵深', '战役部署的纵向深度或战役任务要求达到的全纵向深度。', 30);
INSERT INTO `t_military_term_data` VALUES ('966900af-65a7-45e9-b46d-cb32f6b8e946', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子干扰吊舱', '装有电子干扰设备,外挂在飞机或直升机下进行电子干扰的专用舱。分为有源干扰吊舱、无源干扰吊舱和红外干扰吊舱等。', 124);
INSERT INTO `t_military_term_data` VALUES ('9685f4b4-01c9-40dd-954f-22d19c5e35fa', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '合练弹', '在导弹飞行试验前,专为测试发射单位进行测试操作和综合演练而特制的导弹样机。基本性能与待用于飞行试验的导弹相同。主要用以检查导弹与发射设施的协调性,培训试验人员的操作技能。', 19);
INSERT INTO `t_military_term_data` VALUES ('96887277-2194-49e3-b693-34b50f663eb3', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '事故', '军队在人员、装备、物资等方面遭到的非正常的损失或发生的变故。一般分为行政责任事故、自然灾害事故等。', 57);
INSERT INTO `t_military_term_data` VALUES ('9691abdf-be35-46c0-8ca0-436a7696f2f7', '98df76fb-4b65-48ff-a56c-4db587327c79', '被服', '军用被褥和服装的统称。主要包括被子、褥子、衣服、帽子、鞋子、袜子、手套等。', 152);
INSERT INTO `t_military_term_data` VALUES ('969950f8-acc2-4cdb-be1c-ff08ca9caccd', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军备', ' 国家或政治集团所拥有的常备军和武器装备的统称。', 86);
INSERT INTO `t_military_term_data` VALUES ('96a88dfc-f028-494a-981d-e7ed037957d9', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '条约线', '相邻两国依据签订的边界条约所划定的国界线。为正式的法定的国界线。国界标志依此线而设。', 86);
INSERT INTO `t_military_term_data` VALUES ('96ac48f2-006f-4de2-8e35-b2e4cbc601e3', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备技术革新', '对现有的武器装备进行的技术改进。用以改进和提高现有武器装备的战术技术性自自。', 114);
INSERT INTO `t_military_term_data` VALUES ('96ae98a7-1dea-44b0-9799-ddc0d5e9a860', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核试验地下水污染', '地下核试验后放射性物质进入地下水而造成污染的现象。', 188);
INSERT INTO `t_military_term_data` VALUES ('96b579f0-0520-4c3a-ad7a-8c8fe66acba9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮射弹散布率', '以中间偏差为单位、把散布范围分为8个区间,火炮射弹散布于各区间的概率的统称。在不同条件下射击,尽管散布范围和中间偏差值有所不同,但散布率不变。', 260);
INSERT INTO `t_military_term_data` VALUES ('96bbae40-e575-4157-a5ab-5c84d56fbc54', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '队列训练', '按队列条令规定的内容进行的队列制式动作的训练。共同科目训练内容之一。', 72);
INSERT INTO `t_military_term_data` VALUES ('96cd8006-6fc4-44a2-a385-62d5da9a02fc', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '观察工事', '保障观察人员隐蔽安全地实施观察的工事。', 45);
INSERT INTO `t_military_term_data` VALUES ('96d43ed5-524e-487e-a2ab-e5fd3ca42dfa', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '斜面', '亦称山坡。山体倾斜部分的表面。按纵断面的形状,分为等齐斜面、凸形斜面、凹形斜面、波状斜面。军事上将朝向敌人的斜面称正斜面,背向敌人的斜面称反斜面。反斜面利于隐蔽兵力和配置曲射火器。', 23);
INSERT INTO `t_military_term_data` VALUES ('96d88277-28f9-476f-8922-ccdf62d3826d', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克疏开地区', '坦克部队和分队由行军队形变换成疏开队形的地区。分为团、营、连疏开地区。通常选择在便于坦克机动和隐蔽的地区。', 19);
INSERT INTO `t_military_term_data` VALUES ('96d8dba5-fd43-4473-8241-3b683444a9d7', '98df76fb-4b65-48ff-a56c-4db587327c79', '军服', '军人穿着的制式服装。有统一规定的式样、颜色、用料和穿着方式。一般分为常服、礼服、作训服、工作服等类。', 153);
INSERT INTO `t_military_term_data` VALUES ('96ecfa3d-84c0-4c8b-b91f-39e86af2c4a1', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克运输车', '载运坦克及其他装甲车辆,实施远程机动的轮式车辆。由轮式牵引车和载重平板挂车或半挂车组成。有重型（载重量大于45吨）、中型（载重量25～45吨）和轻型（载重量小于25吨）3种。', 108);
INSERT INTO `t_military_term_data` VALUES ('96edad4d-a812-48a4-b279-da998c033429', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '联合战役', '在联合战役指挥机构的统一指挥下,由两个以上军种的战役军团共同实施的战役,或由两个以上军种战役所构成的系列战役。如陆军战役军团、空军战役军团共同实施的联合战役,或由第二炮兵战役、空军战役、海军战役等构成的联合战役。某些小型联合战役也可由两个以上军种的战术兵团共同实施。有时也指两个以上国家或政治集团的军队共同实施的战役。', 6);
INSERT INTO `t_military_term_data` VALUES ('9705171b-0bd4-4ae2-9f8d-30cde45c894f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事大地测量', '为满足国防建设和军队作战的需要,测定地球形状、大小、重力场和地面点几何位置的理论和技术。主要包括三角测量、三边测量、导线测量、水准测量、三角高程测量、大地天文测量、重力测量、卫星大地测量、惯性测量、甚长基线干涉测量和各种数据处理等。', 162);
INSERT INTO `t_military_term_data` VALUES ('970f19e5-c7f9-4abd-9349-1bc28b6d8ac3', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹弹道测量', '用无线电技术设备和光学仪器对发射后的导弹进行的跟踪和遥测。用以了解导弹飞行状态,推算并描绘导弹的飞行轨迹,为预报弹头落点提供数据。', 176);
INSERT INTO `t_military_term_data` VALUES ('971197e8-488b-42a6-aa85-42d9fb438a0a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地球重力场', '地球重力作用的空间。包含重力、重力位、重力线和等位面等要素。研究地球重力场的成果,可用于处理测量成果,推求地球的形状和大小,研究地球内部结构和资源分布,确定空间飞行器受地球重力场作用的轨道改正等。', 222);
INSERT INTO `t_military_term_data` VALUES ('97240c9a-c636-4ed7-9178-0df0f3744828', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮初速偏差量', '由于炮膛的烧油和磨损，造成药室长度增加而形成的火炮实际初速对于标准切速的偏差量。通常以偏差量占标准初速的百分数表示。', 242);
INSERT INTO `t_military_term_data` VALUES ('972bb001-9615-4875-9f62-0d2dd4214b31', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克电台', '坦克上的专用无线电收发设备。是乘车战斗的指挥员实施战斗指挥和对外联络的主要通信工具。按调制方式,分为调幅电台、调频电台和单边带电台。通常采用后两种电台。', 142);
INSERT INTO `t_military_term_data` VALUES ('9762f885-374c-4c24-9553-3c96a2fa13c6', 'd7132c58-5df3-4b97-919f-58740148b9ca', '敌机投弹线', '以被掩护目标为圆心,以敌机投弹距离为半径划定的圆周线或弧线。被掩护目标面积较小时以目标中心为圆心划定；目标面积较大时以目标边沿为园心划定。', 59);
INSERT INTO `t_military_term_data` VALUES ('9764329f-eaed-4f19-b272-f074ae25d3d0', '06a75831-13a1-4660-870a-455bb445336a', '无线电接力通信', '亦称无线电中继通信。利用超短波、微波的视距传输特性,采用地面中间站转接的方法达成的无线电多路通信。可传输电话、电报、数据和图像。通信容量较大、可与有线电通信结合使用。', 109);
INSERT INTO `t_military_term_data` VALUES ('977105f2-c6c5-48b4-879b-ad13efa1dade', '83e065b4-6737-4645-9ea5-8276d1de13ed', '重型坦克', '战斗全重为40～60吨、火炮口径为76～122毫米的坦克。主要用以支援和掩护中型坦克作战。', 89);
INSERT INTO `t_military_term_data` VALUES ('97773c5d-7fce-4764-93d5-37518480f002', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵团', '亦称飞行团。由若干个飞行大队以及机务大队编成的航空兵一级组织。为航空兵的战术部队。通常隶属于航空兵师。', 11);
INSERT INTO `t_military_term_data` VALUES ('97916223-75fa-4872-b842-5a80a67cff2f', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹弹头分解', '将核弹头的核装置、引爆控制系统、姿态控制系统、突防装置及壳体等拆卸开来的过程。', 94);
INSERT INTO `t_military_term_data` VALUES ('9793259d-5973-4964-8890-61c8d8632c0c', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '定点指挥', '指挥员及其指挥机关在相对固定的地点或设施中实施的指挥', 27);
INSERT INTO `t_military_term_data` VALUES ('97977334-c577-4dd5-a83b-3c8bfd0ebad0', '98df76fb-4b65-48ff-a56c-4db587327c79', '兵站', '①战时由战区后勤分部派出的、沿交通线设置的综合保障机构。是对部队实施后勤保障的基本单位。分为基地兵站和野战兵站。②平时在长距离军事交通线上设置的为过往部队提供食宿保障的机构。③设在边境口岸负责转运出入境军用物资的保障机构。', 15);
INSERT INTO `t_military_term_data` VALUES ('9798a408-23b4-457b-bdbe-d54dcb6c6566', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '微波武器', '利用高能微波束毁伤目标的武器。可使电子设备的元器件和电路失效或烧毁,也可使人员生理功能紊乱，丧失作战能力。是尚在研究试验中的武器。', 48);
INSERT INTO `t_military_term_data` VALUES ('97a19170-bfac-42c5-9906-1acb187f0654', '0', '空军', NULL, 25);
INSERT INTO `t_military_term_data` VALUES ('97a1bc19-2837-4c17-b22d-723c21c3daf7', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹预备阵地', '导弹部队准备和实施导弹突击的备用作战阵地。通常预先构筑有简易的工程设施。有机动作战能力的导弹部队一般设有预备阵地。', 42);
INSERT INTO `t_military_term_data` VALUES ('97a8d8e3-049d-440f-8400-9e13a6e6d72e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '渔区', '沿海国家为行使专属捕鱼权或养护渔业资源而建立的特别管辖海域。分为专属渔区和养护区。', 384);
INSERT INTO `t_military_term_data` VALUES ('97a9329d-32e7-4265-a40c-2ae0038e5fc0', '8a761efd-50a6-4ac8-9913-b7d745104f82', '枪弹', '亦称子弹、须用枪膛发射的弹药。由弹丸、弹壳、发射药底火等组成。按枪械种类,分为手枪弹、步（机）枪弹和大口径机枪弹；按弹头用途分为普通枪弹特种枪弹和辅助枪弹；按口径分为小口径枪弹（6毫米以下）、普通口径枪弹（6～12毫米）和大口径枪弹（12－20毫米）。', 197);
INSERT INTO `t_military_term_data` VALUES ('97aa9f5a-2554-468a-a68a-8c90e8d6bec4', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军旗', '象征军队或军队一 定级别以上建制单位的旗帜。中国人民解放军军旗的旗面为红地,左上方缀金黄色的五角星和“八一”两字。简称“八一军旗”。主要授予团级以上部队、院校。各级所授军旗旗幅大小不同。', 136);
INSERT INTO `t_military_term_data` VALUES ('97b07755-cf9a-4670-9a1f-66bcb2a7b818', 'f0140091-c11a-48c9-8836-8aa94439dac0', '运动防御战斗', '在一定地区内逐次转换阵地,结合灵活反击,节节抗击敌人进攻的防御战斗。', 201);
INSERT INTO `t_military_term_data` VALUES ('97b191bf-303c-4ec0-a772-f0da184bdd7b', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达跟踪干扰源', '雷达利用目标上的干扰机发射的干扰信号对目标进行角度或距离的跟踪。是雷达反干扰的一种措施。', 104);
INSERT INTO `t_military_term_data` VALUES ('97b3311c-8fdd-49f6-bb63-06ff1f2c606a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '时令河', '季节性有水的河流。旱季河床干涸,雨季或冰雪融化季节有水流。暴雨或冰雪迅速融化时,水位急剧上升,可成为通行的障碍。', 61);
INSERT INTO `t_military_term_data` VALUES ('97c23a5b-88fb-4d15-a61b-0e7062cdfa14', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '义务兵', '根据义务兵役制的规定被征集入伍,在军队中按规定期限服役或超期服役的士兵。', 147);
INSERT INTO `t_military_term_data` VALUES ('97ccd573-5a96-4856-ab54-901d3964eafc', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜水加压舱', '亦称潜水减压舱。为潜水员提供高压环境的特制舱室。主要用于：潜水作业时潜水员的加压、减压和生活居住,模拟潜水训练。以及失事潜艇艇员脱险出水后的加压治疗等。通常设置在打捞船、救生船上和潜水训练医疗中心。', 246);
INSERT INTO `t_military_term_data` VALUES ('97e097fd-1f28-4403-8c0a-93cbbe75ec4a', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '障碍设置队', '作战中以工兵分队为主编成的,担负机动设置障碍物和实施破坏作业的战斗编组。主要任务是：在敌坦克威胁最大方向上快速设置地雷障碍物和实施破坏作业,以迟滞敌行动,封闭敌核突破口,掩护己方暴露的翼侧和接合部等。', 22);
INSERT INTO `t_military_term_data` VALUES ('97e1abef-14b7-4d43-8280-c880609dc3f9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '预定战场', '在敌人可能入侵的方向上,预先选定的作战地区。通常选定在作战双方可能交战并有利于歼敌的区域。', 172);
INSERT INTO `t_military_term_data` VALUES ('97e598f5-af9a-4f5c-8b79-c70dfe9da3f0', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '巩固扩大登陆场', '登陆先头梯队突击上陆后向敌翼侧和纵深发展进攻并组织防御的作战行动。用以保障后续部队和装备物资上陆,为尔后陆上发展进攻创造条件。', 75);
INSERT INTO `t_military_term_data` VALUES ('97f71687-739e-488c-b789-dbc34776eeb7', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵急袭射击', '炮兵在短时间内用预定的较多弹药,对目标实施的突然、猛烈的射击。是炮兵完成压制、歼灭等射击任务的基本方法、通常以急促射进行,或按规定的持续时间以急促射、等速射、单发射、齐射等交替进行,在规定的时间内发射完规定的弹药。', 185);
INSERT INTO `t_military_term_data` VALUES ('980101f4-c613-4d21-8fa8-9de4bd4819ba', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '太空战', '亦称天战。敌对双方主要在外层空间进行的军事对抗活动。包括外层空间的相互攻防行动以及外层空间同空中或地面之间的相互攻防行动。', 146);
INSERT INTO `t_military_term_data` VALUES ('980846fc-6076-49ed-8647-0b93406618e7', '8a761efd-50a6-4ac8-9913-b7d745104f82', '穿爆燃枪弹', '弹头具有穿甲、爆炸燃烧二种作用的枪弹。供大口径机枪使用。', 203);
INSERT INTO `t_military_term_data` VALUES ('9809b424-4980-4b45-a3af-723052bf6440', '878651de-adf5-4c72-9376-9c363b893ff8', '战略后方', '国家的总后方和战略区的后方。是国家和军队进行战争的依托。', 86);
INSERT INTO `t_military_term_data` VALUES ('980cec29-a720-4617-a3c4-a0e2e4eb7f40', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '测方尖兵', '位于行军纵队侧方的尖兵。通常由侧卫派出,或由本队直接派出。前卫、后卫也可同时派出自己的侧方尖兵。', 17);
INSERT INTO `t_military_term_data` VALUES ('981a6c6a-ffb3-4060-b29d-963b33b278fc', '916997ee-6728-4c61-9b79-d96960b1dc86', '消毒', '对受染对象实施的清除毒剂或消除生物战剂的洗消。根据不同的受染对象,可采用喷洒消毒剂、热气流喷射、蒸煮、溶剂擦洗、吸附、除去染毒表层、掩埋、火烧以及日晒、风吹等方法进行消毒。', 62);
INSERT INTO `t_military_term_data` VALUES ('9820f917-dc84-434f-90ce-bef956ba8ca6', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战方针', '作战行动所要达到的总目标及其采取的基本方法。是一定作战思想的体现,作战行动应遵循的根本依据。', 112);
INSERT INTO `t_military_term_data` VALUES ('98222614-bf0d-4632-ac54-578aee4d87a7', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '地方军', '中国人民解放军曾用的对遂行地区性军事任务的陆军地方部队的称谓。相对于野战军而言。', 17);
INSERT INTO `t_military_term_data` VALUES ('983a3235-9353-4660-aa19-d160823ed8f0', '31f4a446-5b98-4873-9d53-310d97125b07', '撤出导弹发射阵地', '导弹发射分队撤收发射设备,离开发射阵地的行动。通常在完成导弹发射任务后或情况发生变化时撤出。', 109);
INSERT INTO `t_military_term_data` VALUES ('983b914c-da74-45d3-8472-56960fbd8780', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵纵深梯次配置', '防空兵在作战区域将兵力、兵器从前沿向纵深分成几个梯队所作的配置。', 19);
INSERT INTO `t_military_term_data` VALUES ('9845bc21-e776-4bb1-a68d-e8366dd1989a', '97a19170-bfac-42c5-9906-1acb187f0654', '僚机', '基本空中编队中跟随长机飞行的飞机或直升机。主要任务是负责观察空中情况,保护长机,执行长机的命令。', 191);
INSERT INTO `t_military_term_data` VALUES ('986b50ff-ab24-4f55-b958-b0598c3fffbb', '97a19170-bfac-42c5-9906-1acb187f0654', '轰炸机', '炸弹、鱼雷、空地导弹等为基本武器,具有轰炸能力的作战飞机。分为战略轰炸机和战术轰炸机。主要用以轰炸敌地面或水面、水下的目标。', 282);
INSERT INTO `t_military_term_data` VALUES ('98800f26-b4e1-41e0-87e5-ac163e662fdd', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克轻度损坏', '坦克个别主要机件损伤,不能完成规定功能的故障状态。通常可由营、连技术保障组或旅、因抢修所修复。', 204);
INSERT INTO `t_military_term_data` VALUES ('9886e769-6de1-4ec2-ba37-5b63caa378c4', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵测风雷达', '防空兵用以探测高空风的雷达。是防空兵气象探测系统的主要组成部分。能接收无线电探空仪发出的信号,测定高空气压、温度和湿度。', 125);
INSERT INTO `t_military_term_data` VALUES ('98a1b54f-88b7-43e0-a0e2-cef3e449c507', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '推进', '军队边克服敌人的抵抗边前进的行动。如部队在突破敌前沿阵地后,向其纵深推进。', 340);
INSERT INTO `t_military_term_data` VALUES ('98a1bcee-a187-4489-a11c-520186166f7c', '06a75831-13a1-4660-870a-455bb445336a', '警报报知网', '传递警报信号的专用通信网。通常运用无线电、有线电、光缆通信等手段建立。有条件的还可建立多种通信手段相结合的自动化警报网。警报报知网全时开放,守听单位可按规定全时守听、定时收听或根据需要收听。', 70);
INSERT INTO `t_military_term_data` VALUES ('98abb8e8-679f-4609-954d-f5d993ede020', 'd7132c58-5df3-4b97-919f-58740148b9ca', '远方空中情报', '由空军开设的空情报知总站或分站通报的,范围在数百公里内的空中情报。防空兵各级指挥所组织接收,并不断地将空中目标航迹标示在情报图板上,或用监视器显示出来。', 109);
INSERT INTO `t_military_term_data` VALUES ('98df76fb-4b65-48ff-a56c-4db587327c79', '0', '后方勤务', NULL, 14);
INSERT INTO `t_military_term_data` VALUES ('98e742ab-ee65-430b-b095-a6c1e39992d2', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '报废装备', '经申报批准作废品处理的武器装备。通常指严重损坏不能修复或无修复价值的武器装备以及影响使用安全的弹药。', 110);
INSERT INTO `t_military_term_data` VALUES ('98fc79b0-73a1-4b2e-a660-2d58bf24b92f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火追击', '炮兵对退却或突围逃跑之敌实施的跟踪火力突击。通常用以拦击敌先头部队,突击其主力、打乱其队形,封锁其通道,为步兵、坦克追歼敌人创造条件。', 70);
INSERT INTO `t_military_term_data` VALUES ('98fff171-d5a9-4a00-b5a4-6d5d17ac9577', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克抢救', '对淤陷、战伤、损坏和有故障的坦克实施自救、拖救、牵引和后送行动的统称。', 215);
INSERT INTO `t_military_term_data` VALUES ('991a3d51-ce26-4a61-9326-2aa8f71de423', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机起落坪', '用水泥等建筑材料建造的专供直升机起飞和降落的平坦场地。面积和厚度根据直升机机型确定。', 101);
INSERT INTO `t_military_term_data` VALUES ('991a547b-73c4-47e4-8bb1-4739033d067f', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '系统瘫痪', '对敌某一电子系统中的各种电子设备实行全面干扰并结合火力摧毁,以使其系统效能完全丧失的行动。', 88);
INSERT INTO `t_military_term_data` VALUES ('992ec951-8705-4ec0-ac52-a3828cfba89d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '伪装', '隐蔽自己和欺骗、迷惑敌人的措施,。按范围,分为战略伪装、战役伪装和战术伪装；按方法,分为天然伪装和人工伪装。', 225);
INSERT INTO `t_military_term_data` VALUES ('99308299-ace1-46ab-b8b8-28c945823c31', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场撤收', '撤收渡场内渡河器材、设备和撤除渡场勤务的行动。', 328);
INSERT INTO `t_military_term_data` VALUES ('99327699-ffa1-4786-8d9a-677fcdeaf577', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '图上作业', '按照想定在军用地图上研练组织指挥的作业。', 104);
INSERT INTO `t_military_term_data` VALUES ('993b0ed3-94a0-428f-beb9-82a73d34e22d', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机编队解散', '编队飞行的各直升机按照命令迅速飞离编队的行动。', 33);
INSERT INTO `t_military_term_data` VALUES ('99520965-b44f-4788-b65c-bcade75e039d', '06a75831-13a1-4660-870a-455bb445336a', '短波通信', '亦称高频通信。波长为 100～10米（频率为3～30兆赫）的无线电通信。可传输电报、电话、数据等。建立迅速,便于机动,可用较小的发信功率进行远距离通信。', 102);
INSERT INTO `t_military_term_data` VALUES ('9970ca9b-5d0e-49fb-b431-2e7859a06b55', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射方式', '根据导弹的类型和战术技术要求采取的发射方法和样式。按发射时的导弹姿态,分为垂直发射、倾斜发射和水平发射；按发射平台的位置,分为陆基发射、海基发射和空基发射；按发射的原动力,分为自力发射（热发射）、外力发射（冷发射）和投放发射；按导弹发射装置的机动性能,分为固定发射和机动发射等。', 110);
INSERT INTO `t_military_term_data` VALUES ('997330a9-56b8-41fc-bb55-e4c97584e844', 'f0140091-c11a-48c9-8836-8aa94439dac0', '机动防御战斗', '以迟滞作战与机动反击相结合的方法粉碎敌人进攻的防御战斗。', 202);
INSERT INTO `t_military_term_data` VALUES ('997419ca-5bb0-41b0-8ce9-70748eaf4aad', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事价值', '某事物在军事上所具有的重要性的程度。', 53);
INSERT INTO `t_military_term_data` VALUES ('997a288c-c579-47d7-a5e1-3573a254828b', 'd7132c58-5df3-4b97-919f-58740148b9ca', '临空指挥', '高射炮兵指挥员在敌机临空时通过直接观察实施的射击指挥。可直接掌握实时情况,及时、正确地区分和选择目标进行射击。', 145);
INSERT INTO `t_military_term_data` VALUES ('998480e3-f8fb-4074-9221-0d51f5d47539', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克炮射击死界', '坦克停在水平地面上,其火炮呈最大俯角时,炮身轴线延长线与地面的交点到车首的距离。', 51);
INSERT INTO `t_military_term_data` VALUES ('99919183-8b5f-44e5-89c7-78ac2c3f98f3', '8a761efd-50a6-4ac8-9913-b7d745104f82', '卡壳', '射击武器的弹壳退出弹膛后卡在机（炮）匣内,使次发射弹无法进入弹膛，造成射击中断的射击故障。', 136);
INSERT INTO `t_military_term_data` VALUES ('99ad4f88-a06c-4df8-bbcc-1cdca0e36c08', '97a19170-bfac-42c5-9906-1acb187f0654', '空降集团', '由担负空降作战任务的各种部队统一编成的兵力集团。通常由空降兵部队、运输航空兵部队和直升机部队编成。机降时还可编入步兵部队等。', 154);
INSERT INTO `t_military_term_data` VALUES ('99b37d90-e831-41a0-9511-dc52f9261622', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮弹弹丸', '亦称弹头。炮弹的战斗部。是炮弹直接起杀伤、破坏作用的部分。', 327);
INSERT INTO `t_military_term_data` VALUES ('99c72998-043b-4c5d-a95c-c6f0296c6338', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '官兵一致', '中国人民解放军在官兵关系方面实行的原则。主要内容包括：官兵之间、上下级之间政治上平等,军官关心和爱护士兵,士兵尊重和服从军官,团结互助,同甘共苦,实行有领导的民主,建立自觉的纪律,共同为军队建设和完成各项任务负责。', 12);
INSERT INTO `t_military_term_data` VALUES ('99cc191d-f0d2-44c8-ba14-5fa7c130e1f4', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '像片判读仪', '能对航空、航天像片进行目视观察和简易量测的光学仪器。主要用以判释军事目标和地形。', 248);
INSERT INTO `t_military_term_data` VALUES ('99cebb70-8fdf-462e-9a88-dc3f8885b2eb', '97a19170-bfac-42c5-9906-1acb187f0654', '着陆雷达', '在复杂气象或夜暗条件下引导飞机下滑着陆的雷达。通常设在机场跑道中部的一侧。', 363);
INSERT INTO `t_military_term_data` VALUES ('99d1e9bc-a3ad-4e4c-a735-6daebf777454', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '向敌行军', '朝向敌方的行军。须加强前方警戒并作好与敌遭遇的战斗准备。', 48);
INSERT INTO `t_military_term_data` VALUES ('99d2dccd-f2ef-499e-9869-1198bc943692', '06a75831-13a1-4660-870a-455bb445336a', '超长波电台', '亦称超低频电台。工作波长为10～1兆米（频率为30～300赫）的无线电发信台。电台设备庞大,通常配置数部至数十部兆瓦级大功率发信机,天线总长度为数百至数千千米。用于对深潜的潜艇发信。', 181);
INSERT INTO `t_military_term_data` VALUES ('99f9577e-ecdc-4bb1-ba90-da773ed4b53d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程作业方法', '完成工程任务的方法。包括人工作业法、机械作业法、爆破作业法和混合作业法等。', 30);
INSERT INTO `t_military_term_data` VALUES ('9a18ac94-c27b-45a0-8bc2-d9af44728f1d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '全球定位系统', '利用一组发布时间信息和轨道数据的人造卫星,对地球上任一时刻的任一地点进行连续定位的导航定位系统。具有很高的军用价值。', 228);
INSERT INTO `t_military_term_data` VALUES ('9a1e9554-ebd8-45bc-9e18-df08353fa286', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '防界线', '从山顶到山脚的斜面上由缓变陡的部位。在防界线上能俯瞰其下方的全部或部分斜面,便于观察和射击。', 126);
INSERT INTO `t_military_term_data` VALUES ('9a1ef566-21e8-4736-a4dd-eda36618f026', '97a19170-bfac-42c5-9906-1acb187f0654', '作战飞机', '装有机载武器和特种设备,专门用于对空中、地面、水面、水下目标进行攻击或担负直接作战保障任务的军用飞机。包括歼击机、歼击轰炸机、轰炸机、强击机、反潜巡逻机、侦察机、预警机、空中加油机、电子对抗飞机、炮兵校射机等。', 280);
INSERT INTO `t_military_term_data` VALUES ('9a2bf6f8-b726-4305-bf86-de85f73b8433', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '封冻', '水域出现整片固定冰盖的现象。在中、小河流上冰层增厚直至河底,称连底冻。封冻时冰厚在0.6米以上,可通行汽车。军事上可视情利用。', 72);
INSERT INTO `t_military_term_data` VALUES ('9a3f8ec5-43e6-4f84-92d1-98c83c9ee036', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '近地点注入', '地球同步卫星发射过程中,在转移轨道近地点附近依靠末级火箭点火,使卫星由停泊轨道进入转移轨道的轨道机动。转移轨道的近地点在赤道上空,其高度就是入轨点的高度。', 262);
INSERT INTO `t_military_term_data` VALUES ('9a417ec1-e4a1-4d02-96ee-b9af6b7e663b', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤分部', '中国人民解放军总后勤部或军区后勤部派出的划区保障机构。设有司令部、政治部和若干业务处,并根据保障任务编有若干医院、仓库以及运输、工程、修理等勤务部队或分队。分为一线分部、二线分部和总后勤部直属分部。', 13);
INSERT INTO `t_military_term_data` VALUES ('9a433ab2-a723-4a53-9606-bc5e53938f07', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒伤急救', '人员受毒剂伤害后在现场进行的紧急救治。主要包括；使用抗毒剂,配戴或更换防护器材,消毒,迅速撤离毒区等。', 139);
INSERT INTO `t_military_term_data` VALUES ('9a47d335-2f34-4c82-a8eb-756c8861d13a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵快速反应', '炮兵对突然出现或意外发生的情况作出迅速的反应。主要表现在快速遂行作战任务,对战场上出现的各种情况迅速作出处置，及时以准确的火力打击各种目标等方向。', 64);
INSERT INTO `t_military_term_data` VALUES ('9a52fef6-c88b-44e0-98ad-c217c82013ef', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察器材', '用于侦察的器具、设备和材料的统称。按工作原理,分为光学侦察器材、声学侦察器材、电子侦察器材；按使用空间,分为地面侦察器材、空中侦察器材和水上侦察器材。', 116);
INSERT INTO `t_military_term_data` VALUES ('9a5553a4-c408-4aff-9b6b-9a0e7700de18', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '陆军航空兵', '以军用直升机为基本装备,具有空中机动、空中突击和空中保障能力,主要遂行以航空火力支援地面作战和机降作战任务的陆军兵种。由直升机飞行部队和直升机飞行保障部队等组成。', 1);
INSERT INTO `t_military_term_data` VALUES ('9a65b518-aab7-4ded-bd65-fd81ac0faeb4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '迫击炮', '用座钣承受后坐力,主要行高射界射击的曲射火炮。一般体积较小,重量较轻,结构简单,适于随伴步兵行动主要用以歼灭遮蔽物后和位于反斜面上的目标。', 26);
INSERT INTO `t_military_term_data` VALUES ('9a752d69-4492-4a9f-931d-004d67a594e5', '98df76fb-4b65-48ff-a56c-4db587327c79', '野战医疗所', '军队在紧急情况下从医院临时抽组的小型野战医疗机构。是执行作战和抢险救灾医疗后送任务的卫勤机动力量。', 212);
INSERT INTO `t_military_term_data` VALUES ('9a784404-e89f-4bd7-9933-e479a9278583', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '编内职工', '军队中编制内无军籍的职员和工人的统称。', 122);
INSERT INTO `t_military_term_data` VALUES ('9a915048-9f34-4376-93a9-813a7f10d859', 'd7132c58-5df3-4b97-919f-58740148b9ca', '撤去', '将高炮和仪器由战斗状态转为行军状态的行动过程。', 189);
INSERT INTO `t_military_term_data` VALUES ('9aa843fc-9fb0-4d8c-883f-275c1743eff2', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '自导鱼雷', '亦称寻的鱼雷。利用自导装置自动搜索、跟踪并导向目标的鱼雷。分为声自导鱼雷和尾流自导鱼雷。', 202);
INSERT INTO `t_military_term_data` VALUES ('9ab1fc92-c793-4b96-8eae-24784a8e3ac1', '916997ee-6728-4c61-9b79-d96960b1dc86', '致死性毒剂', '基本毒害作用能使中毒人员死亡的毒剂。如沙林、梭曼、维埃克斯、氢氰酸等。', 206);
INSERT INTO `t_military_term_data` VALUES ('9ab224ac-6d7d-4b2f-a2db-cb6683e125bd', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '预备炮兵', '在建制上直接隶属于军区以上单位的炮兵。', 4);
INSERT INTO `t_military_term_data` VALUES ('9ac2a4be-21f2-4e91-90ac-93500849fa70', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇导航设备', '舰艇上定位、导航的仪器和设备的统称。分为自主式导航设备和非自主式导航设备两类。有普通导航设备,天文导航设备,电子导航设备（包括无线电导航设备、惯性导航设备、激光导航设备、水声导航设备）和综合导航设备等。', 226);
INSERT INTO `t_military_term_data` VALUES ('9ad184ac-64c5-4c18-9d2b-0827aef29770', '97a19170-bfac-42c5-9906-1acb187f0654', '空中掩护队', '机群中负责护卫空中突击队的空中编队。通常由一个或几个小编队组成,位于敌机可能来袭的一侧,担任警戒、牵制、消灭或驱逐对空中突击队构成直接威胁的敌机。', 50);
INSERT INTO `t_military_term_data` VALUES ('9ad9d8a3-a1f7-483c-a182-976ac8f3d721', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察兵', '担负侦察任务的专业兵。', 84);
INSERT INTO `t_military_term_data` VALUES ('9af48427-22d9-4b84-97ec-25ad92e975a2', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '袋形部署', '将兵力分别从三面配置成口袋状的作战部署。通常用于伏击作战', 98);
INSERT INTO `t_military_term_data` VALUES ('9af5d383-f4a7-4564-8c1d-cd9984885dd7', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '爆心投影点', '亦称地面零点或水面零点。爆心与地面或水面的垂直线和地面或水面的交点。', 141);
INSERT INTO `t_military_term_data` VALUES ('9b0b1c50-0a0d-441f-bac5-2acdf19412ce', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵行动计划', '炮兵为完成作战任务而制定的作战行动计划。内容包括作战各阶段的火力运用。协同动作、各种信号、战斗队形转移等。通常由炮兵群以上指挥机关根据上级炮兵的战斗命令与行动计划、合成军队的协同计划、本级的任务与首长决心等制定。', 94);
INSERT INTO `t_military_term_data` VALUES ('9b112f8b-aaca-4bf2-a081-e73cfd5eed21', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '随行干扰', '掩护攻击机群作战时,电子干扰飞机与作战飞机混合编队,并在编队中实施电子干扰的战术。', 70);
INSERT INTO `t_military_term_data` VALUES ('9b26862b-b45d-45d3-a1fb-10387f8ae384', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '野外保障组', '负责直升机野外场地的飞行战勤保障工作的小组。由指挥、通、导航、气象和后勤等方面的保障人员组成。', 94);
INSERT INTO `t_military_term_data` VALUES ('9b2e032c-f880-4e80-bc72-a5ce483b99a5', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射未成', '液体导弹发动机点火后、固体导弹发动机点火前,因技术、战术、气象条件等方面的原因而采取紧急关机、紧急断电或自毁措施,使其不能起飞或不能飞向目标的发射。', 139);
INSERT INTO `t_military_term_data` VALUES ('9b305577-fe1a-46ea-b894-1b68a26e5ab4', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方指挥', '军队指挥员及其指挥机构对后方工作进行的组织领导活动。包括对后勤保障、技术保障、后方防卫、交通运输、后方通信、后方工程建设等的指挥和对后方各项工作的协调等。', 43);
INSERT INTO `t_military_term_data` VALUES ('9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '0', '国防类', NULL, 3);
INSERT INTO `t_military_term_data` VALUES ('9b41f469-0b00-40f9-b580-762a4eadd63c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹推进系统', '亦称动力装置。为导弹飞行提供动力的整套装置。包括发动机及保证其正常工作的系统和部件。分为空气喷气推进系统和火箭推进系统。', 32);
INSERT INTO `t_military_term_data` VALUES ('9b4b76c9-55f8-4eff-a5b9-9eb80dd1cbda', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克防护系统', '坦克装甲壳体和其他防护装置、器材的统称。包括坦克车体和炮塔、三防装置、灭火装置、防后效装置和伪装器材等。用以保护坦克及其乘员和内部机件。', 130);
INSERT INTO `t_military_term_data` VALUES ('9b552c81-0e1e-4dd6-86ff-83af9580e993', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行航程', '亦称飞行距离。航空器从起飞至着陆在空中飞行的水平距离。分为最大飞行航程、实用飞行航程和战术飞行航程。', 301);
INSERT INTO `t_military_term_data` VALUES ('9b5577af-830a-44a5-8da7-fe42ce8b1079', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵计划火力', '炮兵预先制定火力运用方案的工作。主要包括：确定射击的目标、时机、方法,承担射击任务的部队,射击持续时间,弹药消耗量和信号等。通常根据合成军队营长的决心,上级炮兵行动计划,本级炮兵的任务、配置地域、射击效能,敌各类目标可能出现的区域以及地形等情况进行计划。', 96);
INSERT INTO `t_military_term_data` VALUES ('9b585404-ef0c-4e8d-a84d-74528d80546c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场转移', '将原渡场的器材和设备撤收,易地开设新渡场的行动。分为渡场正常转移和渡场紧急转移。', 327);
INSERT INTO `t_military_term_data` VALUES ('9b5a8502-898a-4b85-b654-96f1c0d6188a', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '风', '空气相对于地球表面的水平运动。用风向和风速（或风级）表示。气象台一般用固定安装在离地约10米高处的测风仪器测定地面风。高空风则用测风雷达或测风经纬仪跟踪气球的方法测定。风对射击精度和飞机、舰船活动以及航天器发射等有一定影响。', 15);
INSERT INTO `t_military_term_data` VALUES ('9b60c8f9-8a66-4c1b-8f69-dd9b206f957e', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器破甲力', '轻武器对装甲目标的毁伤能力。以弹心或金属射流对装甲板的最大穿风破甲率和后效作用衡量、穿深通常以装甲厚度（毫米）／法线角（度）表示；破甲率以穿透装甲的发数占有效发数的百分比表示。后效作用指穿透装甲后的射流、破片对装甲后生动目标或器材的毁坏作用。', 217);
INSERT INTO `t_military_term_data` VALUES ('9b6bd247-f7dd-4568-b1f2-74c8ac3f1c16', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '发现概率', '亦称探测概率、检测概率。表示某种探测手段（如肉眼、光学器械、雷达等）在一定条件下发现目标可能性大小的量。用0～1之间的数值表示。发现概率的人小决定于目标特性、探测手段的特性、目标和探测手段所处的环境与气象条件等因素。', 188);
INSERT INTO `t_military_term_data` VALUES ('9b7adc64-6dea-4575-bd28-b9703e234e5e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵火力要图', '标绘有炮兵射击任务的要图。通常标有：简要的敌我情况,射击任务、方位物（注有编号、距离）,各炮基本射击地境和补加射击地境,注明射击指挥和协同信号等。', 99);
INSERT INTO `t_military_term_data` VALUES ('9b7e57ff-f479-4d0f-b00c-3af86d81549f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '歼灭', '亦称消灭。毙伤俘敌全部或大部有生力量,解除其武装,剥夺其抵抗能力。', 378);
INSERT INTO `t_military_term_data` VALUES ('9b8a0d03-aaf7-4d01-bfe8-e399c6ccc159', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防暴', '国家依法以武装力量预防和制止暴乱的措施与行动。', 432);
INSERT INTO `t_military_term_data` VALUES ('9ba59c47-2992-4678-8c25-ce4e42a543a2', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克过垂直墙高', '坦克能越过水平地面上的坚实垂直墙的最大高度。一般为0.9～1.2米。', 166);
INSERT INTO `t_military_term_data` VALUES ('9bb9aee4-522e-470c-bafd-d4e0e1bc4a30', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '拥政爱民', '中国人民解放军开展的以拥护政府和热爱人民群众为主要内容的群众工作。', 122);
INSERT INTO `t_military_term_data` VALUES ('9bbb5b0c-0abb-4b50-9a36-00a7e008f71a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察分队', '营以下各级专业侦察单位的统称。', 69);
INSERT INTO `t_military_term_data` VALUES ('9bbd47d8-ce0e-4449-a6fa-0c102e526993', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '弹药技术检查', '对弹药及其元件的质量、技术状况进行的检查。主要采取查看、测试、化验、鉴别与评定等方法进行。', 118);
INSERT INTO `t_military_term_data` VALUES ('9bcb1d70-2c0c-4c03-af03-17b45ef3f881', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '军事训练', '简称训练。军事理论教育和作战技能教练的活动。包括部队训练、院校教育、预备役训练等。部队训练的内容,主要包括共同科目、技术、战术、战役法等；训练的形式和方法,主要包括理论教学、图上作业、实物操练、计算机模拟、实兵演习等。目的是提高军人的军事素质,提高作战能力,培养部队高度的纪律性和优良的战斗作风。', 0);
INSERT INTO `t_military_term_data` VALUES ('9bcf324c-59ac-4969-8eb6-42137576471b', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '指战员', '指挥员和战斗员的统称。通常泛指全体军人。', 110);
INSERT INTO `t_military_term_data` VALUES ('9bfca853-ed27-4006-85e4-0493dd386765', '98df76fb-4b65-48ff-a56c-4db587327c79', '物资储备', '为保障持续不间断的物资供应而进行的物资储存。分为日常储备和战备储备。', 108);
INSERT INTO `t_military_term_data` VALUES ('9bffca27-70a5-4c70-bc39-c2592b55e3e3', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防坦克三角锥', '用混凝土、钢筋混凝土或型钢等制成三角形锥体状的桩着类障碍物。其边长一般为12米。成数列交错配置，间隔1～15米,距离2．5～3米。', 122);
INSERT INTO `t_military_term_data` VALUES ('9c0167f0-546d-4cfa-9d30-a7d2f9f5d0c4', '98df76fb-4b65-48ff-a56c-4db587327c79', '军用加油站', '军队为用油装备加注油料的设施及其机构。分为固定加油站和野战加油站。通常开设在部队营区或交通线上。', 174);
INSERT INTO `t_military_term_data` VALUES ('9c0e42b8-30ec-49c4-a5a9-629f9bcbe02b', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹弹头总装', '将核弹头的核装置、引爆控制系统、姿态控制系统、突防装置及壳体等装配成一个弹头整体的过程。', 95);
INSERT INTO `t_military_term_data` VALUES ('9c14f649-daa4-44a5-9595-3621440f0b00', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '向心突击', '从数个方向向敌防御区域中心目标实施的突击。通常是在对被围之敌或城市防御之敌进攻时采用。', 99);
INSERT INTO `t_military_term_data` VALUES ('9c1d106d-1cdc-420c-b159-a50cbafd48cf', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事谈判', '国家、政治集团或军队之间就战争或其他军事问题进行的正式会谈。', 77);
INSERT INTO `t_military_term_data` VALUES ('9c1d3ccb-6876-4c63-8ea6-fa7dc3ab1562', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '火具', '亦称火工品。装有火药或炸药,用以点燃火药、引爆炸药或做机械功的一次性使用的元器件和装置的统称。包括火帽、底火、点火管、导火索、延期件、雷管、传爆管、导爆索、切割索、爆炸开关、爆炸螺栓、驱动器等。', 215);
INSERT INTO `t_military_term_data` VALUES ('9c1d6223-a3a4-4003-acc0-b368e09d2c15', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮有效射高', '高炮对空中目标能实施有效射击的最大高度。100毫米高炮有效射高为12000米；57毫米高炮用指挥仪诸元射击时有效射高为5000米,用瞄准具诸元射击时有效射高为4000术；37毫米高炮有效射高为3000米。', 150);
INSERT INTO `t_military_term_data` VALUES ('9c287032-31fa-4c1b-8a47-a2be2e7031ac', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行续航时间', '简称航时。飞机或直升机从起飞至着陆在空中飞行的时间。其长短取决于载油量。载重量、飞行高度、飞行速度等。采用空中加油可延长飞行续航时间。', 302);
INSERT INTO `t_military_term_data` VALUES ('9c3d9bbc-3b41-42cb-b6eb-5e8e70a2f23a', '878651de-adf5-4c72-9376-9c363b893ff8', '战略内线', '军队处于战略防御或被敌战略包围的态势。相对于战略外线而言。', 87);
INSERT INTO `t_military_term_data` VALUES ('9c3e5c54-986d-4086-b002-150c2e670f34', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '导演计划', '导演和调理员按本身担负的任务分别拟制的指导军事演习的工作计划。主要内容包括训练问题以及演习的时间、地点和导演方法等。', 136);
INSERT INTO `t_military_term_data` VALUES ('9c432c55-7231-45fd-9b9a-0493b9c5ad16', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '计算机外围设备', '亦称计算机外部设备。计算机硬件中的输入设备、输出设备和辅助存储器等的统称。通常泛指计算机中除中央处理机以外的设备,如键盘、打印机、磁盘机、磁带机等。', 57);
INSERT INTO `t_military_term_data` VALUES ('9c50227f-f89c-423c-8198-7ba9a8840b97', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '役龄青年', '根据兵役法的规定,处于服现役年龄段的青年。', 28);
INSERT INTO `t_military_term_data` VALUES ('9c5638c1-a207-40df-a9fa-b35648a38ef3', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇部门', '大、中型舰艇上设立的一级战斗和勤务组织。通常设航海、枪炮、水中武器、观察通信、机电、雷达声纳、导弹、航空、舰务、军需、卫生等部门。有指挥控制中心的舰艇,设作战、装备、机电、舰务等部门。', 13);
INSERT INTO `t_military_term_data` VALUES ('9c573e71-e0fb-4b76-8112-0e1dff2c10cf', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火伏击', '炮兵预先埋伏兵力等待时机,以突然猛烈的火力袭击运动之敌的战斗行动。', 80);
INSERT INTO `t_military_term_data` VALUES ('9c6324c7-b65e-49d9-aa06-5c4a5187ad91', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击硬目标', '具有较强抗力不易被核武器摧毁的目标。', 165);
INSERT INTO `t_military_term_data` VALUES ('9c68f07c-f8ed-4bb4-a562-d881f6f07e9d', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '干扰压制区', '对敌方实施有源压制性干扰时,使其电子设备不能正常工作的空间范围。通常在制定干扰计划时,须对干扰压制区进行估算或图上作业,以作为部署干扰设备和拟定干扰行动计划的依据。', 80);
INSERT INTO `t_military_term_data` VALUES ('9c772300-1bdc-4465-8aaa-8791d6e1a9a1', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军战术训练', '海军部队、分队进行的以海上战斗的原则和方法为主要内容的训练。分为合同战术训练、兵种战术训练、舰种战术训练和专业战术训练。', 314);
INSERT INTO `t_military_term_data` VALUES ('9c85de7f-31b7-4322-b6ac-b754051eaf39', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '跟踪和数据中继卫星', '转发地面站对低、中轨道航天器的跟踪测控信号和中继从航天器发回地面信息的通信卫星。可居高临下地测量、控制在近地空间内运行的大部分航天器。具有全轨道连续覆盖、全天候数据收集和高速率数据传输能力,可为各类航天器提供良好的测控和通信手段。', 213);
INSERT INTO `t_military_term_data` VALUES ('9c8676ce-7e33-40b0-b905-54b7567cd96e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练方针', '军事训练须达到的总目标及所要采取的基本方法。是一定时期内训练指导思想的体现和军事训练应遵循的依据。', 2);
INSERT INTO `t_military_term_data` VALUES ('9c8fc88f-0f67-4d1c-a02a-15fdcacbf43a', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克防护性能', '坦克具有的保护其自身和内部乘员的特性与功能。包括装甲防护、形体防护、伪装防护、防后效和三防等性能。', 175);
INSERT INTO `t_military_term_data` VALUES ('9c94da27-57d4-48d6-8852-c1835b856fef', '98df76fb-4b65-48ff-a56c-4db587327c79', '军事运输', '军队运用各种运输方式输送人员和物资的活动。包括铁路、公路、水路、航空、管线和人力、畜力的军事运输。按其规模和目的；分为战略运输、战役运输和战术运输。', 244);
INSERT INTO `t_military_term_data` VALUES ('9c999e66-5047-4cde-abb5-af619b33f372', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '洋', '海洋的中心和主体部分。地球的大洋分为太平洋、大西洋、印度洋、北冰洋。洋占海洋总面积的89％。一般水深在2～3千米以上,水文特征受大陆影响小,水的盐度和温度较稳定,水呈深蓝色,透明度大,有独立的潮波系统和洋流系统。', 6);
INSERT INTO `t_military_term_data` VALUES ('9ca1b674-172a-44d5-94ab-a000f397cf6a', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '警戒', '防敌袭击和侦察的警卫措施。按警戒兵力所在的空间位置,分为地面警戒、空中警戒和海上警戒；接任务性质,分为战斗警戒、行军（航行）警戒和宿营（停泊）警戒等。', 0);
INSERT INTO `t_military_term_data` VALUES ('9ca5670f-c506-4b00-b961-5e4baa37712f', 'f0140091-c11a-48c9-8836-8aa94439dac0', '反空降预备队', '担负反空降任务的预备队。通常以坦克兵或机械化步兵、摩托化步兵为主编成。', 51);
INSERT INTO `t_military_term_data` VALUES ('9ca97164-046e-4122-9864-875c7186cb5a', 'd7132c58-5df3-4b97-919f-58740148b9ca', '起占', '①高射炮弹弹丸底部脱离炮口瞬间,弹丸重心所在的位置。高炮射击通常以火炮位置或发射阵地中心为起点。②亦称原点。地空导弹离开发射装置瞬间,导弹重心所在的位置。地空导弹发射通常以导弹发射点或制导站所在点为起点。', 165);
INSERT INTO `t_military_term_data` VALUES ('9cbb9d60-7a36-431d-9580-bff2b6638ac5', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '裂变燃料', '能发生链式裂变反应并释放出巨大能量的核物质。如铀-235、钚-239和铀-233等。', 117);
INSERT INTO `t_military_term_data` VALUES ('9cd9d8d7-9837-4712-a2bc-a62b28da056f', '916997ee-6728-4c61-9b79-d96960b1dc86', '半数致死浓度', '在一定时间内能使50％无防护人员死亡的染毒浓度。用LC50表示。', 125);
INSERT INTO `t_military_term_data` VALUES ('9ce47c67-d471-4207-a097-acfca2aca19e', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '液体火箭发动机', '使用液体推进剂的化学火箭发动机。', 37);
INSERT INTO `t_military_term_data` VALUES ('9d0cfec3-92ba-45ac-aec4-09833ab53107', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮情报指挥系统', '高炮团、群实施对空侦察和作战的指挥自动化系统。由计算机、通信器材、对空观测器材和运载车辆等组成。包括团站、营站、连站和雷达站。', 105);
INSERT INTO `t_military_term_data` VALUES ('9d0e77f2-0a2d-4ec6-a6cd-fd7c4d8b91e0', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军航空兵目标引导组', '海军航空兵部队向协同作战的舰艇部队或地面部队派出的对空引导小组。随协同作战的舰艇或地面部队行动。任务是反映协同作战部队对航空兵支援的要求,向协同作战部队通报空中飞机情况,引导己方飞机、直升机准确突击目标。', 291);
INSERT INTO `t_military_term_data` VALUES ('9d139058-a460-4b14-8e03-ed50e2f8fdc4', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '分水岭', '分隔相邻两个流域的山岭或高地。分水岭最高点的连线称为分水线或分水界。降水形成的地表径流以分水线为界,分别流向两个相反的方向。如中国的秦岭是长江和黄河的分水岭,其北面的径流注入黄河水系,南面的径流注入长江水系。', 67);
INSERT INTO `t_military_term_data` VALUES ('9d1c35b5-1624-4e8b-8fa1-7fa6934d92a9', '97a19170-bfac-42c5-9906-1acb187f0654', '喷气式飞机', '以空气喷气发动机为动力装置利用喷射高速气流直接产生推力的飞机。', 269);
INSERT INTO `t_military_term_data` VALUES ('9d1f91e7-b271-4f6e-82ef-9f969f29be9c', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '换班命令', '下达部队换班任务的命令。内容一般包括交接班部队或分队的任务换班的顺序、开始和结束时间接班部队或分队的出发地域运动路线、下车地点和车辆隐蔽位置,交班部队或分队的集合地域、登车点和运动路线,换班时的警戒和发牛情况的处置方案,加强兵器的转隶和物资器材的交接方法指挥、通信联络、向导员及警备调整勤务的组织等', 104);
INSERT INTO `t_military_term_data` VALUES ('9d236703-0557-4523-9e34-9448da8dbd19', '916997ee-6728-4c61-9b79-d96960b1dc86', '沾染检查', '对人员、装备和粮秣饮水、蔬菜等放射性沾染程度的测量。包括检查沾染对象的表面沾染水平、沾染浓度或沾染比活度。用以及时消除沾染,避免或减轻放射性物质的伤害。', 44);
INSERT INTO `t_military_term_data` VALUES ('9d2a640f-0673-4a37-9cef-4dfb1c9db28c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇操纵', '操纵潜艇在水下和水面航行。停泊、改变运动状态以及实施战斗的技艺。包括水面操纵、下潜上浮操纵、水下操纵和应急操纵等。', 303);
INSERT INTO `t_military_term_data` VALUES ('9d2bf8bf-52ae-48f1-9ba4-d6939b7aed33', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战经过图', '标绘有作战过程和结局的图。通常标绘有不同作战时刻或阶段敌对双方军队的位置、行动及其结果等情况。主要供指挥员及其指挥机关掌握作战情况,研究与总结作战经验使用。', 151);
INSERT INTO `t_military_term_data` VALUES ('9d356575-c83c-40ba-a1f1-7ed86e6cae86', '916997ee-6728-4c61-9b79-d96960b1dc86', '氢氰酸', '学名氰化氢。全身中毒性毒剂的一种。可装填在炮弹、航空炸弹、火箭弹中使用,造成空气染毒。通过呼吸道侵入机体,引起全身中毒。', 219);
INSERT INTO `t_military_term_data` VALUES ('9d38e075-00f5-47f7-8425-5a5be592f2f6', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '精确制导武器', '采用精确制导技术,直接命中概率在50％以上的武器。如各类导弹以及制导炸弹、制导炮弹、制导鱼雷等。', 43);
INSERT INTO `t_military_term_data` VALUES ('9d38fba0-3af8-4f7b-a148-5310f23445ed', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '特小威力核武器', '威力低于1千吨梯恩梯当量的核武器。', 106);
INSERT INTO `t_military_term_data` VALUES ('9d3c2489-af84-481a-aa88-55406f51afa7', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '三角高程测量', '用经纬仪观测两点间的垂直角或天顶距,并按已知距离推算两点间高差的测量方法。作业简单,不受地形起伏限制,是测定三角点、导线点高程并替代低等级水准测量的基本方法。', 180);
INSERT INTO `t_military_term_data` VALUES ('9d3c4643-9a37-4d4f-a0f5-8897030c3063', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备维护保养', '对武器装备采取的各种保护性措施的统称。如对武器装备的擦拭、清洗、检查、调整、测试、涂油等。通常分为日常保养、定期保养和季节保养。', 104);
INSERT INTO `t_military_term_data` VALUES ('9d3c7795-f5c2-497a-84e0-93ebaecec396', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '掩体', '供观察、射击、操作技术装备和隐蔽用的露天工事。如单人掩体、机枪掩体、火炮掩体、坦克掩体、雷达掩体等。', 61);
INSERT INTO `t_military_term_data` VALUES ('9d40bd6c-9f89-413c-b804-db4451c02f64', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '政治民主', '中国人民解放军内部在政治上实行的民主。主要内容包括：官兵政治上一律平等,没有高低贵贱之别；军官尊重士兵的民主权利,自觉接受士兵监督；士兵正确行使民主权利,在集中领导下积极参加连队管理,可以对军官提出批评和意见,对工作提出合理建议。', 6);
INSERT INTO `t_military_term_data` VALUES ('9d418251-a41e-49eb-9869-996e12554314', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克检修', '坦克未到小修期限,由于故障或损坏而进行的修理。由负责小修的单位承担,或由负责小修的单位派出技术力量协助坦克分队完成。', 212);
INSERT INTO `t_military_term_data` VALUES ('9d502ce4-5149-46fd-9317-cb872a68855a', 'f0140091-c11a-48c9-8836-8aa94439dac0', '防御要点', '防御地区内起支柱作用的重要地点。分为前沿防御要点和纵深防御要点。', 236);
INSERT INTO `t_military_term_data` VALUES ('9d604599-8046-4115-a1f0-c6c07cabc0e4', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹头体结合设备', '将导弹弹头与弹体对准连接的设备。包括弹头结合车、专用起重机和吊装设备等。是导弹武器系统中的基本设备之一。', 66);
INSERT INTO `t_military_term_data` VALUES ('9d701142-3340-416b-800a-f1236fb013fb', '06a75831-13a1-4660-870a-455bb445336a', '信息保密', '将传递的信息内容加以密化的通信保密措施。主要方法是通信双方使用保密机。必要时,可用事先规定的数码、字母或词组的不同组合代替信息真实内容进行传递。', 146);
INSERT INTO `t_military_term_data` VALUES ('9d7454f2-08fc-4bcc-ae30-f534adf07372', 'f0140091-c11a-48c9-8836-8aa94439dac0', '冲击基准时间', '亦称“C”时。规定的各冲击分队先头冲至敌防御前沿（第一道堑壕）的时间。代字“C”。用以协调冲击时各军兵种的行动。', 184);
INSERT INTO `t_military_term_data` VALUES ('9d767e33-d5a6-44bb-bcfb-d759fce044ac', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '营产管理', '对营区内的土地、林木和营房、营具、场地、道路及其附属设备的管理、主要包括营产的使用、保管、维护、建档以及有关费用的收缴和闲置营产的处理等工作。', 23);
INSERT INTO `t_military_term_data` VALUES ('9d8a3fdd-6c59-4c13-ad61-401460de106b', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '文职干部', '军队编制内不授予军衔的干部。包括科学研究、工程技术、医疗卫生、教学、新闻、出版、文化艺术、体育等单位的部分专业技术干部,机关、院校、医疗等单位中从事行政事务、生活保障工作的部分干部。', 108);
INSERT INTO `t_military_term_data` VALUES ('9d8a6f1c-b426-48b8-a719-391cc804b5f9', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '士官', '①士兵军衔中最高的一等。中国人民解放军的士官军衔授予志愿兵,分为军上长和专业军士两类。②被授予军士长、专业军士军衔的军人。', 118);
INSERT INTO `t_military_term_data` VALUES ('9d8a903d-9664-4058-816b-8a110a65d337', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵技术管理', '装甲兵各项技术工作的计划、组织、实施和协调活动的统称。主要包括：装甲兵科研管理,装备管理,使用与维修管理,大修生产管理,监造管理,器材管理,战时技术保障和技术人员的教育与训练等。', 186);
INSERT INTO `t_military_term_data` VALUES ('9d8c53a6-e0a5-4b13-90fe-372ede0f8114', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹发射种类', '按地空导弹发射数量和发射时间间隔的不同,对地空导弹发射方法所作的分类。通常分为单发发射和连续发射。', 137);
INSERT INTO `t_military_term_data` VALUES ('9d8d6d0c-c821-4dee-a386-83c7ae7b582a', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防部署', '边防武装力量的任务区分、兵力编组和配置的统称。', 112);
INSERT INTO `t_military_term_data` VALUES ('9d9671f2-3393-41a0-ac20-47bf1aecdecd', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '伪装涂料', '涂敷在目标或背景表面以对付侦察和末段制导武器的涂料。分为光学伪装涂料、防雷达伪装涂料和防热红外伪装涂料等。', 355);
INSERT INTO `t_military_term_data` VALUES ('9da70915-6723-4eba-8431-e491f3487e3b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '布雷舰艇', '专门用以布设水雷的水面战斗舰艇。有远程布雷舰、基地布雷舰和布雷艇等。', 139);
INSERT INTO `t_military_term_data` VALUES ('9dabc8be-4e7f-49de-94e0-31bcd8346224', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '指令制导', '由弹外的制导装置发出控制指令进行的制导。属遥控制导。制导装置可安装在地面、舰船或飞行器上。', 47);
INSERT INTO `t_military_term_data` VALUES ('9db911cd-eeb3-4e5e-b256-87cff1be8db4', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '导弹护卫艇', '以舰舰导弹、舰炮为主要武器的小型水面战对舰艇。兼有导弹艇和护卫艇的性能。作战们针导弹艇大,攻击力较护卫艇强。主要用于近岸海区的攻击、巡逻、护航等。', 141);
INSERT INTO `t_military_term_data` VALUES ('9db944b4-d941-4394-8c80-0362c75fa0d0', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵集团配置', '将数个防空兵分队按照一定的间隔和距离在被掩护目标周围所作的配置。通常在掩护点状、面状和集团目标时采用。', 20);
INSERT INTO `t_military_term_data` VALUES ('9dc3e483-7771-493f-a48f-cd3227436301', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '专项训练计划', '组织实施单一项目训练的计划。通常包括演习计划、集训计划及其他专项训练活动计划等。', 29);
INSERT INTO `t_military_term_data` VALUES ('9dd0d4e7-4bfc-4052-acd3-b86ae7394136', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克乘员训练团', '培训坦克乘员的团级训练单位。用以培训坦克车长、一炮手、驾驶员等。', 68);
INSERT INTO `t_military_term_data` VALUES ('9dd7f1c2-2059-463a-ac23-34b7c9869252', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备值班部队', '担负防备敌人突然袭击任务和应付意外情况的机动作战部队。', 108);
INSERT INTO `t_military_term_data` VALUES ('9de0baba-c11a-4063-8f5e-5b678d0089e3', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '陆军航空兵作战指挥', '陆军航空兵指挥员及其指挥机关对所属部队或分队的作战行动实施的指挥。包括机降作战的指挥、空中支援地面部队作战的指挥等。', 57);
INSERT INTO `t_military_term_data` VALUES ('9dea2723-c167-4cba-a6c5-893eca5369f0', '97a19170-bfac-42c5-9906-1acb187f0654', '战斗飞行', '为遂行战斗和战斗保障任务而实施的飞行。通常包括：起飞,集合或会合,飞向目标或空域,进入目标或空域遂行任务,返航,降落。', 208);
INSERT INTO `t_military_term_data` VALUES ('9df20a36-0098-4230-9483-ed22b3e05854', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇航速', '舰艇航行时相对于水的运动速度。是舰艇战术技术性能要素之一。通常分为最大航速、全速、巡航航速、经济航速和最小航速等。潜艇还可分为水下经济航速、水下巡航航速、水下低噪声航速和通气管航速等。以节（海里/小时）为计量单位。舰艇在风和水流影响下,相对于陆地的运动速度,称实际航速。', 325);
INSERT INTO `t_military_term_data` VALUES ('9dfa783a-1021-4917-a2a3-3dfae6f0b523', '0', '综合类', NULL, 2);
INSERT INTO `t_military_term_data` VALUES ('9e0dcb6d-81ac-4861-bdea-e93362cded42', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '判定方位', '在现地辨明站立点的东、西、南、北方向,明确站立点与周围地形的关系位置。可利用指北针、北极星、太阳与时表以及某些地物的自然特征进行判定。', 139);
INSERT INTO `t_military_term_data` VALUES ('9e2d5776-5afc-462e-8f23-582070229e3c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '干部离休退休制度', '军队干部离职休养或退出现役休养的制度。主要包括干部离休退休的条件。待遇、安置和管理办法等规定。', 82);
INSERT INTO `t_military_term_data` VALUES ('9e59c392-fcac-4ac0-addb-f668538848c2', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '军事气候志', '以文字、图、表等形式表述某地区气候状况及其与军事活动关系的资料。是军队拟制作战、训练计划,进行战场准备、国防科研试验和工程建设等的重要参考依据。', 90);
INSERT INTO `t_military_term_data` VALUES ('9e5a57db-a3ae-46af-89bc-261d3f34a2f2', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '登陆场', '团以上登陆部队在敌岸攻占的具有一定宽度和纵深的地域。用以保障后续梯队上陆发展进攻。分为战术登陆场和战役登陆场。', 73);
INSERT INTO `t_military_term_data` VALUES ('9e5c5ec5-a869-4960-8c48-3abca6bb915c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '反辐射摧毁', '用敌方的电磁辐射信号导引反辐射武器摧毁敌电磁辐射源的行动。主要摧毁目标是敌雷达、无线电制导设备、干扰台,以及其他无线电发射设备。', 90);
INSERT INTO `t_military_term_data` VALUES ('9e60c315-7998-4b27-9f9d-012e11738fca', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵指挥车', '炮兵用以指挥射击的专用车辆。有炮兵团指挥车、炮兵营指挥车和炮兵连指挥车。车上装有炮兵射击指挥系统的主要设备、定向仪器及供电装置等。', 292);
INSERT INTO `t_military_term_data` VALUES ('9e6f8443-97dc-4361-8f40-527ec5805c4d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上拖靶', '简称海靶。由拖靶船拖曳供海上射击训练使用的靶。由靶体和靶标组成。有浪花靶、雷达靶、炮靶、声纳靶等。', 321);
INSERT INTO `t_military_term_data` VALUES ('9e727eb7-0333-42d6-b399-7801608b902b', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥机构', ' 军队各级、各类、各种形式指挥组织的统称。通常分为常设指挥机构和临时指挥机构、常设指挥机构主要指军队建制内的各级指挥员及其指挥机关；临时指挥机构本要指临时编组的指作所、指挥小组等。', 40);
INSERT INTO `t_military_term_data` VALUES ('9e9e8d0b-5d84-49d1-90b8-61b889f2fce5', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '晚点名', '连队在晚间进行的以清点人数为主要内容的例行性行政管理活动。主要内容包括：清查人员在队情况,进行生活讲评,宣布次日工作或传达命令、指示等。通常以连为单位（有时以排为单位）于就寝前或其他时间列队进行,时间不超过15分钟。', 37);
INSERT INTO `t_military_term_data` VALUES ('9eb318cf-e040-4dfd-82a6-e10866d919f1', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事地理学', '研究军事活动与地理环境的关系以及军事上运用地理条件的规律的学科。是军事科学的组成部分。包括普通军事地理学、部门或专题军事地理学和区域军事地理学等。', 34);
INSERT INTO `t_military_term_data` VALUES ('9eb425d5-5a6e-4aae-8b77-96dc81856e26', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击范围', '高炮发射的弹丸能够达到的空间。包括最大射击范围和有效射击范围。最大射击范围,指用不空炸的炮弹射击,弹丸所能达到的空间范围；有效射击范围,指发射的弹丸及其杀伤体具有毁伤空中目标效能的空间范围。', 146);
INSERT INTO `t_military_term_data` VALUES ('9ec7cf10-c0c5-41c4-934d-c9d853993d5c', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '应征公民', '根据兵役法的规定,经兵役登记并符合服现役条件的公民。', 29);
INSERT INTO `t_military_term_data` VALUES ('9edfa9bb-96b6-4823-99cc-a91b0e45f57a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导引头', '亦称自动导引装置或寻的头。安装在导弹等的头部,接收目标反射或辐射信息,产生导引信号的装置。按作用原理,分为主动式、半主动式和被动式导引头；按接受的能量种类,分为雷达、红外、激光、电视和声波导引头。常用于末制导。', 62);
INSERT INTO `t_military_term_data` VALUES ('9ee586de-75fe-4048-a2fe-d4f2bf406a72', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '立功', '军队对在作战、训练和其他任务中成绩显著、有较人或重大贡献的单位和个人所给予的记功奖励。立功等级向三等功、二等功、一等功。', 63);
INSERT INTO `t_military_term_data` VALUES ('9ee706de-2a64-4f8c-8eb4-6654cae20088', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机着陆距离', '飞机从下滑至一定高度（通常为25米或15米）开始,到降落于地面停止滑跑所经过的水平距离。着陆距离与飞机的着陆重量、制动能力、机场标高、气象条件、跑道道面状况和着落过程的速度等有关。', 305);
INSERT INTO `t_military_term_data` VALUES ('9eeeb0f2-125c-494a-a4cd-a11c855e611c', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹阵地环境监测', '对导弹阵地上的生活和工作场所的大气、水源、食物、装备、设施等的污染程度进行的监视和测量。包括对放射性物质、推进剂、医疗污水、坑道噪音污染等的监测。', 202);
INSERT INTO `t_military_term_data` VALUES ('9ef2d048-168c-4401-ab41-47dd3544791b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '综合声纳系统', '亦称多站声纳系统。将多部声纳和水声测量设备有机结合,部分部件共用,能对各种水声信息进行综合处理和集中控制的声纳系统。多装备于核动力潜艇和现代大、中型水面战斗舰艇。具有警戒、攻击、水声通信、侦察、识别和测量等多种功能。', 236);
INSERT INTO `t_military_term_data` VALUES ('9efb28d2-af01-42a2-8717-9e67f58edb2e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '通令', '对所属单位和人员公有功过、奖惩等事宜的军用文书。', 137);
INSERT INTO `t_military_term_data` VALUES ('9f06fd01-cc49-4514-a331-d2abd9584d25', '878651de-adf5-4c72-9376-9c363b893ff8', '战略形势', '①战争双方在一定时间内形成的总体上的强弱、攻守等情况的综合态势。②国家或政治集团之间矛盾关系在一定条件下形成的总的格局和态势。', 65);
INSERT INTO `t_military_term_data` VALUES ('9f070deb-2b6a-4f91-ad75-4a3ff2505dd0', '83e065b4-6737-4645-9ea5-8276d1de13ed', '履带车辆摩托小时', '履带车辆发动机工作时间的计算单位。发动机累积工作1小时,即为1个摩托小时。发动机实际拥有的摩托小时称为储备摩托小时。用于训练之外的摩托小时称勤务摩托小时。', 193);
INSERT INTO `t_military_term_data` VALUES ('9f16d2f9-38b2-4edc-ac18-73905436d443', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军乐', '军队用于礼仪、壮威等方面的音乐。', 114);
INSERT INTO `t_military_term_data` VALUES ('9f2ec974-7dd9-47c1-9cbe-27f94a9f3753', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '峰林', '可溶性岩石地表因水流的长期溶蚀而形成的散列形或丛聚形的石峰。山坡陡峭,体态挺拔,规模比石林大,相对高度一般为100～200米,远望如林。如中国广西桂林、阳朔的峰林。', 34);
INSERT INTO `t_military_term_data` VALUES ('9f328616-6cfb-4c21-9ac8-1a88c3616fa6', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克可靠性', '坦克在规定的条件下和时间内所具有的规定功能的程度。分为基本可靠性和任务可靠性。基本可靠性是坦克在规定条件下,无故障工作的持续时间（里程）或概率；任务可靠性是坦克在规定的任务剖面内实现规定功能的能力。坦克可靠性的概率度量称坦克可靠度。', 182);
INSERT INTO `t_military_term_data` VALUES ('9f39a36c-3be9-43e2-9b07-984bb6d101bc', '06a75831-13a1-4660-870a-455bb445336a', '载波电话终端机', '简称载波机。利用频率分割原理在一条通信线路上进行多路复用的有线电话通信设备。一般由音频终端、变频、载频供给和电源等设备组成。可使一条通信线路同时传输数路至万余路电话。主要用于有线电长途电话通信。', 190);
INSERT INTO `t_military_term_data` VALUES ('9f3aa4fc-9a9e-4868-bf01-752f0bde9934', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '卫戍', '①军队对重要地区或目标的保卫戍守。②特指中国人民解放军对首都北京的警备。', 423);
INSERT INTO `t_military_term_data` VALUES ('9f3d1ec6-4e66-4998-8d27-77e294caf264', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战情况图', '标绘有敌力与己方作战发展情况和行动状态的图。主要供指挥员了解作战发展情况、指挥作战使用。', 150);
INSERT INTO `t_military_term_data` VALUES ('9f3dfbb9-ba5e-4e7c-af4e-f022ee19862c', '31f4a446-5b98-4873-9d53-310d97125b07', '核防御', '对来袭核武器的防御。包括积极核防御和消极核防御。积极核防御是使用核或非核手段,在安全空域拦截、摧毁来袭的核武器及其运载工具,或使其失控、自毁,以免遭核袭击损伤；消极核防御是采取积极核防御以外的措施,如抗核加固,隐蔽、伪装、疏散,设置假目标等,以避免或减弱核袭击造成的损伤。', 28);
INSERT INTO `t_military_term_data` VALUES ('9f41bf97-62ed-4ec7-9973-484206513fa3', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '陆军航空兵飞行指挥', '陆军航空兵指挥员及其指挥机关对所属部队或分队的飞行活动实施的指挥。主要包括：按飞行计划表指挥飞行,向机组通报有关情况,检查督促各项飞行保障,协助机组处置飞行中发生的特殊情况等。', 56);
INSERT INTO `t_military_term_data` VALUES ('9f50df89-6a86-4455-ac67-48b1aeb1de8d', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹杀伤概率', '地空导弹武器系统发射导弹毁伤空中目标的可能性大小的量。通常用0～1之间数值表示。其大小主要取决于地空导弹武器系统的可靠性、制导系统的精确度, 导弹性能和目标特性,以及导弹和目标的遭遇情况等因素。', 144);
INSERT INTO `t_military_term_data` VALUES ('9f52927b-2f85-4ee8-b900-160a12d413bb', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮圆周射界', '火炮方向射界为360度的射界。', 253);
INSERT INTO `t_military_term_data` VALUES ('9f560fa5-34b0-4042-b31c-e16093e3d743', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '激光雷达', '用激光来探测目标的雷达。由于工作波长短、波束窄,其测量精度、分辨能力和抗干扰性能均超过普通雷达,但受气候影响大,作用距离近,搜索目标较困难。军事上通常用于对各种飞行目标轨迹的精密跟踪测量、火力控制和目标识别等。', 99);
INSERT INTO `t_military_term_data` VALUES ('9f5aa077-2855-421e-bf0d-64db09e44538', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上突击基准时间', '实施海上突击的基准兵力开始突击的时间。是确定其他参战兵力行动时间的依据。', 46);
INSERT INTO `t_military_term_data` VALUES ('9f6d9284-a741-4464-91f2-681efe664b78', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹转载对接设备', '用以转载和对接导弹弹体、弹头的地面设备。包括起重机械以及专用的转载、对接和吊装结合的设备等。', 57);
INSERT INTO `t_military_term_data` VALUES ('9f7d5f19-f947-4710-8418-b4d3a1d880bd', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '爆破弹', '以弹的冲击作用、弹体爆炸时产生的冲击波及破片破坏、毁伤目标的炮弹。主要用以破坏敌坚固的工事、障碍物及其他建筑物,毁伤敌隐蔽的有生力量和技术兵器等。', 306);
INSERT INTO `t_military_term_data` VALUES ('9f8a8f90-a4ac-4ab9-84e9-9e366a54d6a5', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行速度', '航空器在空中运动的速度。通常以千米／时或米／秒为计算单位。相对于空气的飞行速度称空速,相对于地面的飞行速度称地速。', 227);
INSERT INTO `t_military_term_data` VALUES ('9f9c3ddd-25f0-43b5-9912-d0595e29e293', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '外线作战', '军队处于进攻地位或对敌实施包围态势下的作战。', 183);
INSERT INTO `t_military_term_data` VALUES ('9f9f2c7a-f488-4ce2-b66b-a446eaea6cf5', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹战斗部', '导弹上装有爆炸物和引爆系统,直接用以摧毁和杀伤目标的装置。多数位于导弹的头部。某些导弹的战斗部亦称弹头。按装药不同。分为核战斗部、常规战斗部和特种战斗部。', 20);
INSERT INTO `t_military_term_data` VALUES ('9fa127bb-1d31-4c85-a90b-f2f1e8a7fad6', 'f0140091-c11a-48c9-8836-8aa94439dac0', '掩蔽', '遮蔽和隐藏目标,防敌火力毁伤的行动。通常以构筑工事或改造地形的方法实施。', 119);
INSERT INTO `t_military_term_data` VALUES ('9fa3da81-7cef-45a4-b737-074293803adb', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '野战工事', '临战时或战斗过程中构筑的,抗力较低、设备较简单的临时性工事。', 40);
INSERT INTO `t_military_term_data` VALUES ('9fa7bd43-d68b-46ef-a36d-2bae5ce5b296', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上侦察', '使用海军兵力在海上进行的侦察。必要时还可组织海员和渔民进行。', 52);
INSERT INTO `t_military_term_data` VALUES ('9fab3c16-3535-4230-b1af-736b312b4e83', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '遥控鱼雷', '预先布设,由舰艇、飞机或岸上遥控启动、控制并导向目标的鱼雷。分为有线遥控鱼雷和无线遥控鱼雷。', 206);
INSERT INTO `t_military_term_data` VALUES ('9fb970fe-e707-4546-aadb-4da9dbe51697', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克炮塔', '设在坦克车体顶部,用以安装坦克炮等武器和设备的可旋转的装甲壳体。', 132);
INSERT INTO `t_military_term_data` VALUES ('9fc178c3-24bc-4b69-8074-156ba880a8ce', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '兵', '①士兵军衔中最低的一等。兵的衔级一般分为 2～5级。中国人民解放军的兵的衔级分为上等兵和列兵两级。②被授予士兵军衔的战士。相对于干部而言。', 115);
INSERT INTO `t_military_term_data` VALUES ('9fddfc09-8395-477e-8972-8f21edd57a5f', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军士长', '①士官军衔中的一个类别。中国人民解放军的军士长军衔由高至低分为四级、三级、二级、一级。②被授予军士长军衔、担任基层行政或专业技术管理职务的军人。', 120);
INSERT INTO `t_military_term_data` VALUES ('9ff20c6f-4943-441d-b8b0-12520199ffe2', '98df76fb-4b65-48ff-a56c-4db587327c79', '运输能力', '运输企业或一定的线路、港口。车船设备在一定时期内所能担负的最大客货运输量或周转量。通常分别以铁路通过能力、铁路输送能力、港口通过能力、船舶运输能力等表示。', 276);
INSERT INTO `t_military_term_data` VALUES ('9ffd1505-49cc-4a23-bb0f-d15e3d75e915', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克炮自动装弹机', '为坦克炮装填炮弹的自动装置。一般为电力机械式。按装填方式,分为定角装填式和非定角装填式两种。', 117);
INSERT INTO `t_military_term_data` VALUES ('a00d4778-a41c-493e-8e64-15aa55d29a6b', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克器材保障所', '坦克部队战时负责器材供应的临时性技术保障机构。由技术部门和器材仓库有关人员组成。负责供应坦克抢救、抢修、保养所需的器材,收集并上缴废旧的坦克器材与缴获的技术装备、器材等。', 229);
INSERT INTO `t_military_term_data` VALUES ('a0180c29-a6aa-4c45-9573-a7e82d8a2bf8', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '尊干爱兵', '士兵尊重干部,干部爱护士兵。是中国人民解放军官兵关系的基本要求和优良传统。主要内容是：干部爱护和尊重士兵,关心士兵的政治进步和生活福利,听取士兵的意见；士兵尊重和爱护干部,自觉遵守纪律,服从命令听指挥。', 15);
INSERT INTO `t_military_term_data` VALUES ('a03cb60e-a044-4b80-9724-f369c1ac41fd', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '通用装备', '各军种和兵种均可使用的装备。相对于专用装备而言。如枪械、运输汽车等。', 81);
INSERT INTO `t_military_term_data` VALUES ('a04318d4-fe7f-4bfd-bc96-f9bdaafcff00', '06a75831-13a1-4660-870a-455bb445336a', '陆海协同通信', '为保障陆军与海军的协同作战而建立的通信联络。主要方法有：组织协同无线电网；通过海军向陆军派出的作战小组、舰炮火力校正组的电台建立无线电通信；陆军向海军建立野战有线电通信；使用简易信号通信器材等。', 11);
INSERT INTO `t_military_term_data` VALUES ('a0496ab9-4501-4851-a0e7-c68bc4dac2aa', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '爆破', '用炸药爆炸的能量破坏物体和实施工程作业的技术。按爆破对象,分为土石爆破和结构物爆破；按装药位置,分为内部装药爆破和外部装药爆破；按爆破技术,分为抛掷爆破、定向爆破、松散爆破、压缩爆破、光面爆破、预裂爆破和拆除、爆破等。', 202);
INSERT INTO `t_military_term_data` VALUES ('a05d8607-44b0-4515-a7b8-a3b96c7d89ba', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察方式', '获取情报所采用的形式。如航天侦察、航空侦察、电子侦察、光学侦察、声学侦察等。', 28);
INSERT INTO `t_military_term_data` VALUES ('a0619608-8365-4488-8683-2456c3f81b47', '97a19170-bfac-42c5-9906-1acb187f0654', '空降时间', '在一个空降地区一批次空降或多批次持续空降所用的时间。伞降时,指从第一名伞兵离开航空器开始至最后一名伞兵着陆所用的时间；机降时,指航空器编队从第一架航空器着陆开始至最后一架航空器着陆所用的时间。', 166);
INSERT INTO `t_military_term_data` VALUES ('a06a310f-0de1-4e37-839d-24a6bc9d9b29', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥程序', '构成指挥活动的请事项及其实施的顺序和步骤、如作战指挥的基本程序已了解任务、领会意图、查明和判断情况,定下决心,制定计划、下达命令组织协同和保障,协调、控制部队作战行动等。', 16);
INSERT INTO `t_military_term_data` VALUES ('a06b5385-f239-4de1-bdff-93630a56a9c3', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '工作图', '指挥员、参谋人员随时标绘并注记有关情况的工作用图。通常标绘在地图上,也可标绘在临时绘制的草图上。标注的内容及详略程度根据工作需要而定。', 152);
INSERT INTO `t_military_term_data` VALUES ('a06cc06a-9636-431b-85ff-f61bfbf045cd', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥自动化系统开设', '指挥自动化系统在选定的地点和预定的时间设立并展开工作。', 55);
INSERT INTO `t_military_term_data` VALUES ('a06d0e0e-3a47-42f7-a0b7-e05b48dc02c7', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机减少率', '一个单位在一定时限内,由于战斗损失、飞行事故、自然消耗等原因造成飞机减少的架数与实有飞机架数的比值。通常用百分比表示。', 57);
INSERT INTO `t_military_term_data` VALUES ('a06d1e23-7465-4511-b367-74f8bdb1e027', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵前进观察所', '在作战过程中跟随第一线步兵、坦克分队行动的炮兵观察所。用以侦察敌情、观察炸点、指挥射击,并与步兵、坦克分队保持密切联系等。', 92);
INSERT INTO `t_military_term_data` VALUES ('a07414d1-52b7-42e8-bf5e-43e3616bdb50', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事素质', '军队建制单位或个人在军事方面所具备的知识水平和实践能力。通常指军事理论、军事技术、战斗作风、组织指挥、管理教育等方面的水平和能力。', 54);
INSERT INTO `t_military_term_data` VALUES ('a07a524c-7f2e-4b9b-83be-9c9bcdb981ff', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '中比高空爆', '比高在120-250米/根号3下的千吨TNT当量的空中核爆炸。能杀伤地面上相当范围内有一般掩护或暴露的人畜和破坏中等抗力的地面目标。', 149);
INSERT INTO `t_military_term_data` VALUES ('a083374f-b0f3-448b-bcab-13de0cd8a3be', '878651de-adf5-4c72-9376-9c363b893ff8', '战略步骤', '为实现战略目标而采取的具有全局意义的阶段划分和行动程序。', 81);
INSERT INTO `t_military_term_data` VALUES ('a08549fd-868b-49fd-b33d-a75c77b3e3a2', '83e065b4-6737-4645-9ea5-8276d1de13ed', '喷火坦克', '装有喷火装置的坦克。用以在近距离内喷射火焰,杀伤敌有生力量,破坏军事装备和设施等。', 94);
INSERT INTO `t_military_term_data` VALUES ('a09159a1-1af4-4036-a681-edf519c8e3b8', '916997ee-6728-4c61-9b79-d96960b1dc86', '核监测', '对核武器爆炸及爆后核辐射进行的监测。包括核爆炸监测和核辐射监测。', 84);
INSERT INTO `t_military_term_data` VALUES ('a096446f-1944-40d7-930c-702526208c5e', '06a75831-13a1-4660-870a-455bb445336a', '通信兵专业训练', '为提高各类通信人员的专业水平和通信部队、分队的通信保障能力而进行的训练。主要内容包括；通信专业技能与勤务知识,指挥自动化和通信技术基础理论与应用,战役、战术通信理论与组织实施等。', 215);
INSERT INTO `t_military_term_data` VALUES ('a0b0cdb9-1e4b-4f85-a836-239ac6f9e818', '98df76fb-4b65-48ff-a56c-4db587327c79', '物资消耗', '因战斗使用、正常消费、遭敌破坏、自然损耗等造成的物资数量的减少。分为战斗消耗和非战斗消耗。', 123);
INSERT INTO `t_military_term_data` VALUES ('a0b2f7ab-2ff1-497e-bf65-b0c64db450bb', '916997ee-6728-4c61-9b79-d96960b1dc86', '半厚度', '亦称半值厚度、半值层。可将单向粒子流的辐射量减少到初始值一半时的减弱层厚度。常用以表示各种防护材料的防护性能。单位是米。', 95);
INSERT INTO `t_military_term_data` VALUES ('a0b7ebfc-4ebf-4155-a652-cda9aa518f33', '97a19170-bfac-42c5-9906-1acb187f0654', '跳伞训练', '飞行人员、空降兵以及其他有关人员为掌握跳伞技术而进行的训练。', 201);
INSERT INTO `t_military_term_data` VALUES ('a0c29cac-b05e-4fbb-a5c4-dd9d033988f5', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机（直升机）夜航', '飞机或直升机在夜间的飞行。夜航时,飞行员主要依靠机上仪表指示进行驾驶,机场亦要有相应的夜航设备。', 241);
INSERT INTO `t_military_term_data` VALUES ('a0cf9da4-ab4f-4670-b652-f844aeaafc0a', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '隐蔽指挥', '采用密语、密码等隐蔽手段实施指挥、是保证指挥安全稳定的重要措施。', 28);
INSERT INTO `t_military_term_data` VALUES ('a0d3559a-50ab-4aec-9259-3fdfd0ae1b41', '83e065b4-6737-4645-9ea5-8276d1de13ed', '履带式装甲车辆', '靠履带行驶的装甲车辆。是装甲兵部队的主要装备。与轮式装甲车辆相比,具有较高的越野机动性能,但噪声大、成本及使用维修费高。', 82);
INSERT INTO `t_military_term_data` VALUES ('a0d484db-1222-42ed-b7de-c3d0201b114f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '本初子午线', '亦称首子午线。地球上计算经度的起始经线。1884年国际经度会议决定,以通过英国伦敦格林尼治天文台子午仪中心的经线为本初子午线,作为全球经度起算经线。1968年,以国际协议原点（CIO）作为地权原点,把通过国际协议原点和平均天文台经度原点的子午线作为本初子午线。', 202);
INSERT INTO `t_military_term_data` VALUES ('a0d93d57-b933-4cc1-abbb-9eb5ce1de846', '878651de-adf5-4c72-9376-9c363b893ff8', '人民战争', '广大人民群众为反抗阶级压迫或抵御外敌入侵而组织和武装起来进行的战争。亦指为了人民,并动员、组织和依靠广大人民群众进行的战争。', 20);
INSERT INTO `t_military_term_data` VALUES ('a0dc7241-137e-42a6-8b7a-b06acf426be0', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '适应性训练', '适应特定环境和条件下的作战要求而进行的训练。通常选择与预定作战地区相似的地形、气象等环境与条件,有针对性地进行战术技术以及生活、体质等方面的训练和锻炼。', 49);
INSERT INTO `t_military_term_data` VALUES ('a0e17f61-28ea-4835-9d52-4b827cf4af73', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航标', '助航标志的简称。供舰船定位、导航或表示警告、测速等特殊用途的各种人工标志的统称。分为目视航标、音响航标、无线电航标、激光航标。目视航标包括灯塔、灯桩、灯船、立标、浮标、导标等；音响航标包括雾号、雾笛、雾钟、雾哨、雾炮、水下震荡器等；无线电航标包括无线电指向标、雷达指向标、雷达应答标、雷达反射器等。', 395);
INSERT INTO `t_military_term_data` VALUES ('a0e35191-b468-4b82-a192-70c07a3e1556', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境管理', '边防管理部门为维护边境地区的社会秩序和安全面依法进行的管辖和治理。包括边界管理、边界口岸管理和边境管理区管理等。', 118);
INSERT INTO `t_military_term_data` VALUES ('a0ea2323-817b-48aa-97e8-60ab5339c0bc', 'f0140091-c11a-48c9-8836-8aa94439dac0', '反坦克火力', '用以摧毁敌坦克、步兵战车等装甲目标的火力。通常包括火箭筒、反坦克火炮、反坦克导弹、坦克炮以及机载反坦克火箭或导弹等的火力。', 82);
INSERT INTO `t_military_term_data` VALUES ('a0f8ace1-4780-43b6-ba6c-b6a0c618324e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '弱点', '①交战双方各自的短处。②作战部署中,兵力、火力较弱或工事薄弱之处。', 307);
INSERT INTO `t_military_term_data` VALUES ('a103505c-ea97-4e04-a339-c8b595398258', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '封锁', '使用兵力、火力、障碍物等手段控制某一区域或地点,不让敌人通过或切断敌对外联系的作战行动。按空间,分为地面封锁、海上封锁和空中封锁；按规模,分为战略封锁、战役封锁和战术封锁。', 226);
INSERT INTO `t_military_term_data` VALUES ('a1085cc9-0fe8-419b-8b50-f0a09c4ad73b', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹射击指挥', '地空导弹部队战斗指挥员及其指挥机构,对所属部队运用地空导弹武器攻击空中目标实施的指挥。主要包括：指挥所属部队进行战斗准备等级转换；侦察和判断空中情况,严密掌握空中目标的动态；指示和校对空中目标；定下射击决心,区分和下达射击任务；监督所属部队的战斗活动；组织协同动作和战斗保障等。', 132);
INSERT INTO `t_military_term_data` VALUES ('a10b52f0-083b-4317-b804-265de00ed98e', '916997ee-6728-4c61-9b79-d96960b1dc86', '化验器材', '对染毒样品进行化学分析和鉴定的化学侦察器材。通常包括野战化验车、化验箱等。主要用以确定毒剂种类、染毒程度以及分析未知毒剂的化学结构等。还可用于对毒物、毒素、消毒剂、植物杀伤剂、发烟剂等的化验。', 167);
INSERT INTO `t_military_term_data` VALUES ('a11f565b-53c4-4cd1-ad90-71c5db15faa8', 'f0140091-c11a-48c9-8836-8aa94439dac0', '防步兵火力配系', '用以杀伤敌步兵的火力配系。由步枪、机枪和火炮等火力组成,并与障碍物相结合。', 81);
INSERT INTO `t_military_term_data` VALUES ('a125de54-6481-4467-88f2-d31cb5c554d7', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '野营训练', '亦称野营拉练。军队离开营区在野外条件下进行的训练。通常分为移动野营训练和驻止野营训练。一般在完成基础训练后实施。', 50);
INSERT INTO `t_military_term_data` VALUES ('a1270b3b-8654-4803-baf3-096d7e9e0b1d', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '连续波雷达', '发射连续无线电波信号的雷达。按发射信号形式，分为单频、多频、调频等多种连续波雷达。适合于探测活动目标。主要用作机载多普勒导航仪、雷达速度表、交通管制雷达、导弹和炮弹测速雷达,以及便携式战场侦察雷达等。', 90);
INSERT INTO `t_military_term_data` VALUES ('a12b6849-ad11-40e6-a5fd-a1ce09052054', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机后退飞行', '直升机向其机尾方向倒退的飞行。', 23);
INSERT INTO `t_military_term_data` VALUES ('a14322e3-7026-4029-9d53-920a6d44f221', '06a75831-13a1-4660-870a-455bb445336a', '瞬间通信', '亦称猝发通信。按预定的工作频率在极短时间内快速发送信息的无线电通信方式。能在1～2秒或更短时间内突然快速发送电报或数据,不易被敌截获和干扰。常用于潜艇对岸通信和保密通信等。', 111);
INSERT INTO `t_military_term_data` VALUES ('a145270c-93b7-422d-8fa4-b5c4374b092e', '878651de-adf5-4c72-9376-9c363b893ff8', '战略包围', '对敌战略集团、战略区或敌国实施的包围。通常是在战争力量对比处于优势、战略态势有利的情况下实施。', 119);
INSERT INTO `t_military_term_data` VALUES ('a1454d87-ea29-4280-8875-27bc30de5c88', 'f0140091-c11a-48c9-8836-8aa94439dac0', '疏开队形', '部队或分队在行进中通过扩大间隔和距离而形成的队形。通常在开进接敌时,或通过火力封锁区、障碍区、沾染区以及行军中防敌空袭和核、化学武器袭击时采用。', 54);
INSERT INTO `t_military_term_data` VALUES ('a1523b57-c373-4d79-83b1-286aeb23ce24', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '参谋人员', '从事参谋工作的各类军官的统杯包括指挥机关的业务部门领导、参谋以及担负参谋工作的专业技术军官等。', 43);
INSERT INTO `t_military_term_data` VALUES ('a1536dac-0de8-4bbf-b5c1-c192d634516b', '916997ee-6728-4c61-9b79-d96960b1dc86', '全身中毒性毒剂', '亦称血液中毒性毒剂。能破坏全身组织对氧的正常利用,造成组织细胞内窒息的毒剂。如氢氰酸、氯化氰等。施放后呈蒸气态,主要通过呼吸道吸入中毒。中毒者在几分钟内出现昏迷、痉挛和呼吸麻痹等症状,严重者会立即死亡。', 218);
INSERT INTO `t_military_term_data` VALUES ('a15d0b0c-16d1-48bf-b964-7f5c7d3189eb', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察情报机构', '负责侦察情报工作的建制单位和临时编组单位的统称。', 67);
INSERT INTO `t_military_term_data` VALUES ('a15d4688-4c4d-4bbe-99db-b276e81b5b7b', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机战术训练', '为掌握直升机的战斗方法而进行的训练。包括战术飞行训练、战术综合演练和战术演习等。', 54);
INSERT INTO `t_military_term_data` VALUES ('a1636732-52ec-45a4-8255-46d298faeb5e', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物战剂', '军事行动中用以杀伤人、畜和破坏农作物的致病微生物、毒素和其他生物活性物质的统称。按形态和病理,分为细菌类、病毒类、立克次体类、衣原体类、毒素类、真菌类战剂；按毒害效果,分为失能性战剂与致死性战剂,传染性战剂与非传染性战剂。', 230);
INSERT INTO `t_military_term_data` VALUES ('a1685294-9a23-42b8-9aee-1b90e938286c', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '战时体制', '战争时期,国家为适应战争需要而在政治、经济、军事、文化等领域确定的组织体系及相应制度。相对于平时体制而言。', 12);
INSERT INTO `t_military_term_data` VALUES ('a16a465f-20eb-4589-8b40-03370892e154', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '江河防御', '依托江河障碍进行的防御。防御重点是控制便于渡江河的地点。', 120);
INSERT INTO `t_military_term_data` VALUES ('a187d4aa-3dcd-4c4d-ae31-f79946135522', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '自卫', '保卫己方不受敌人武力侵犯的行动。', 399);
INSERT INTO `t_military_term_data` VALUES ('a18da17f-f965-46b0-8ed1-ff329f03e6a2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '警卫', '对人员、机构和设施等重要目标实施武装的警戒和保卫。', 425);
INSERT INTO `t_military_term_data` VALUES ('a1933d0c-dbb5-4db5-a892-5d60ae44ac5c', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥手段', '实施指挥所采用的工具和人法的统称、包括指挥作业工具、信息传递与处理工具、各种通信方法以及指挥自动化系统等。', 10);
INSERT INTO `t_military_term_data` VALUES ('a1978c32-7d89-4a3f-8cac-0104c1fb10c5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炸点', '火炮射弹的爆炸点。', 227);
INSERT INTO `t_military_term_data` VALUES ('a19e2496-8c35-44c7-a345-390f1d6031f7', '06a75831-13a1-4660-870a-455bb445336a', '指挥自动化工作站', '担负指挥自动化技术保障工作的通信机构。主要承担指挥自动化系统的值勤、维护和指挥自动化设备的安装、测试、维修等任务。', 5);
INSERT INTO `t_military_term_data` VALUES ('a1a06633-7960-43b0-8683-58e7a720758d', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵照相勤务', '炮兵照相分队实施地面照相侦察并对空中照相侦察资料进行处理的勤务。可及时提供比较直观、准确的敌情和地形资料。', 117);
INSERT INTO `t_military_term_data` VALUES ('a1a8e190-9df4-43c6-9a93-b83abe51181c', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '河床', ' 亦称河槽。河谷中平水期被水淹没的槽地。其高低、宽窄随水位涨落而变化。', 68);
INSERT INTO `t_military_term_data` VALUES ('a1a95536-ea3f-415f-9b51-4f1e64e5f4a3', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '电离层', '距地面60～500千米或1000千米高度之间的空气呈电离状态的大气层。由太阳的紫外线辐射和X射线辐射等对空气分子或原子的电离作用而形成。具有折射、反射无线电波的特性,对无线电通信具有重要的影响和作用。', 7);
INSERT INTO `t_military_term_data` VALUES ('a1ab1eda-a789-4e3e-a814-cc8de90547ff', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵最小射距离', '炮兵群或炮兵营内距敌最近的炮兵连阵地至射击区域近沿的距离。', 205);
INSERT INTO `t_military_term_data` VALUES ('a1b368ed-aeed-4d75-be80-d7ee86b9d150', '97a19170-bfac-42c5-9906-1acb187f0654', '空中投物器材', '用以空投物品的器具及其配套设备的统称。包括投物伞、投物容器、投物货台、捆绑带、系留带、着陆缓冲和着陆脱离装置等。', 342);
INSERT INTO `t_military_term_data` VALUES ('a1bb5b44-f3de-44ed-9a6b-bbfc328bcc18', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地图投影', '按一定数学法则将地球椭球面上的经纬线网变换为平面上相应的坐标网。是地图制图确定变形大小、特征和使用要求的数学基础。按投影变形性质,分为等角投影、等面积投影、任意（等距离）投影等。', 270);
INSERT INTO `t_military_term_data` VALUES ('a1cb021f-7881-4adf-a24e-1278b6c3682a', '916997ee-6728-4c61-9b79-d96960b1dc86', '道路消毒', '对染毒道路实施的消毒。通常是对部队必经的染毒道路实施消毒或在染毒地域中开辟通路,以保障部队通过染毒地域。', 63);
INSERT INTO `t_military_term_data` VALUES ('a1d2595c-74f4-4b53-acb7-aa95e568b2c9', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报资料', '对形成军事情报具有参考价值的情况和材料。按内容性质,分为基本情况资料和动向情报资料；按获取途径,分为公开情报资料和秘密情报资料；按载体形式。分为文献情报资料和非文献情报资料。', 137);
INSERT INTO `t_military_term_data` VALUES ('a1d82a74-7793-42dc-a24a-aaf472791c9d', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战计算', '为提供指挥作战所需数据而进行的数量分析运算。主要包括对作战的能力、时间、空间以及力量的投人、消耗、补给和各种专业数据等的计算。', 154);
INSERT INTO `t_military_term_data` VALUES ('a1f0db7b-eabd-4db2-b7ad-b2e012f87bdd', '916997ee-6728-4c61-9b79-d96960b1dc86', '不可耐刺激浓度', '受染空气中的刺激剂使 2／3无防护人员不能忍受其刺激而脱离接触的浓度。单位为毫克／升或毫克／立方米。', 141);
INSERT INTO `t_military_term_data` VALUES ('a2034cb0-4731-47a3-963c-cf53d6892e9c', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '列车梯队', '铁路输送时按列车运行序列编组的梯队。', 82);
INSERT INTO `t_military_term_data` VALUES ('a206fffd-eacb-4fcc-98dd-141df219bdb7', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '特种舟桥', '所架浮桥最大载重量可达100吨的舟桥器材。具有水上可以自行、稳定性能和抗风浪性能好等特点。主要用以在特大江河上实施定点保障。', 300);
INSERT INTO `t_military_term_data` VALUES ('a2104afe-a435-41b3-a4c7-00cede483e8d', '97a19170-bfac-42c5-9906-1acb187f0654', '空中同时攻击', '一架飞机或直升机同时对数个空中目标进行的攻击,或多架飞机或直升机同时对一个或数个空中目标进行的攻击。', 81);
INSERT INTO `t_military_term_data` VALUES ('a21a3af5-6dad-423f-89f6-8f58c5dac96c', 'f0140091-c11a-48c9-8836-8aa94439dac0', '游击战术', '进行游击战战斗的方法。基本战法是袭击。依据袭击的对象、目的和方式不同,一般分为伏击战、破击战、袭扰战等游击战术。中国人民在革命战争中进行的游击战,还创造了地雷战、地道战、麻雀战、围困战等多种战法。', 27);
INSERT INTO `t_military_term_data` VALUES ('a22d0f65-03a9-4a67-916c-2130d07736d6', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '变形遮障', '能改变目标外形及其阴影形状的人工遮障。分为檐形遮障、冠形遮障和仿形遮障。', 348);
INSERT INTO `t_military_term_data` VALUES ('a23614b8-54db-41c3-b966-7d04aa543c85', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '军官在职训练', '现任军官不脱离或短期脱离工作岗位进行的经常性训练。通常采取集训、自学、函授、参观见学等形式组织实施。', 58);
INSERT INTO `t_military_term_data` VALUES ('a23b1521-f688-4ae3-a3fb-32c3033ae014', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹射击可行性检查', '对导弹在给定的环境条件下飞抵目标的可能性进行的检查。当导弹的最大瞄准射程大于或等于实际瞄准射程时,才允许发射。', 186);
INSERT INTO `t_military_term_data` VALUES ('a2408160-12af-45e1-85fe-ead25a6ac704', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆勤务', '军用车辆的筹划、供应、使用、管理的专业勤务。基本任务是：不断提高军用车辆保障能力,组织运用车辆牵引和运载武器装备、输送人员及运输物资,以保障军队作战、建设和其他活动的需要。', 291);
INSERT INTO `t_military_term_data` VALUES ('a25aa33e-4f1d-40d4-a766-80ec0b1be626', '98df76fb-4b65-48ff-a56c-4db587327c79', '乘座车', '专门用以载运人员及其行装的汽车。包括轿车（卧车）、人客车和中小型旅行车等。', 297);
INSERT INTO `t_military_term_data` VALUES ('a269b12f-c086-43de-a77d-9437be848dcd', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆战斗准备', '坦克及其他装甲车辆乘员为遂行战斗任务而进行的准备。主要包括：车辆检查、排除故障,武器系统校正测试,补充油、弹、水、给养、备品和自救器材等。', 18);
INSERT INTO `t_military_term_data` VALUES ('a26ed36f-9c83-4c8d-829f-3292a689b0a4', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力袭击', '以火力给敌以突然而急速的打击。通常由炮兵、航空兵、舰艇部队和战役战术导弹部队等实施。', 105);
INSERT INTO `t_military_term_data` VALUES ('a26f409f-2c98-4427-818d-80c1d991e53d', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵遮蔽阵地', '位于遮蔽物后有良好的遮蔽度,敌从地面观察不能通视的炮阵地。', 60);
INSERT INTO `t_military_term_data` VALUES ('a27bebf0-a7b4-4269-8597-eba0ad127675', '8a761efd-50a6-4ac8-9913-b7d745104f82', '最大发射速度', '火炮在一定射击持续时间内，在火炮技术性能允许的条件下，炮手操作能力所能达到的最多发射弹数。用发／分表示。', 52);
INSERT INTO `t_military_term_data` VALUES ('a299ce5c-70cc-4000-a952-83143036ecde', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '封闭通路', '堵塞通路的行动。对预留的通路通常用雷栅、操纵地雷群、移动式障碍物等进行封闭。对敌开辟的通路,可用再布雷或设置移动式障碍物等方法封闭。', 200);
INSERT INTO `t_military_term_data` VALUES ('a299e2e9-9ab1-4813-a1f3-685284c3ae21', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '方位角', '从某点的指北方向线起按顺时针方向至目标方向线间的水平夹角。用度或密位表示。用以判定方位、指示目标。保持行进方向等。有真方位角、磁方位角和坐标方位角。', 143);
INSERT INTO `t_military_term_data` VALUES ('a29c20e7-0b8c-477b-a6a4-7b9a9c98fd68', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克射击地带', ' 防御战斗中给坦克连、排规定的带状射击区域。分为基本射击地带和补加射击地带。通常以坦克连、排防御阵地两侧为端点,利用防御前方地幅内的方位物明确。', 48);
INSERT INTO `t_military_term_data` VALUES ('a2a836ab-3d5d-4284-8f8a-c0db47da1c4b', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '预防事故', '军队预先采取措施,防止各种可能发生的事故。主要内容包括：加强人员的教育和管理,搞好技术基础训练,严格执行规章制度,注意总结经验教训等。', 59);
INSERT INTO `t_military_term_data` VALUES ('a2c99dfb-0e2b-4dac-8fbe-7a47d75764b5', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '通信干扰设备', '用以发射干扰电磁波，扰乱或破坏敌方无线电通信的通信对抗设备。按工作原理,分为瞄准式通信干扰设备和阻塞式通信干扰设备；按工作波段,分为长波、中波、短波、超短波和微波通信干扰设备。', 127);
INSERT INTO `t_military_term_data` VALUES ('a2cf7f9d-d9cc-4949-a043-43322a5b0b38', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指示', '指导下级作战或其他工作的军用文书、通常以文字下达,也可口头下达。', 129);
INSERT INTO `t_military_term_data` VALUES ('a2cfbd11-2a8d-49fc-a73a-f1e815f47ba3', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '重力', '地球表面任一质点受到的地球质量的引力和地球自转产生的惯性离心力的合力。地球表面各质点所受的引力大小不等。惯性离心力在赤道上最大,在两极为零。地球表面各点的重力值,由赤道向两极增大。重力值还随高度的增加而减小。', 219);
INSERT INTO `t_military_term_data` VALUES ('a2dc26b7-8844-408c-8a1c-d1b31b7232b3', '97a19170-bfac-42c5-9906-1acb187f0654', '同时突击', '航空兵部队以若干个空中编队或机群,在同一时间内分别对地面或水上若干个目标或某一目标系统进行的空中突击。用以破坏、瘫痪敌某一目标系统或封锁敌某一区域。', 103);
INSERT INTO `t_military_term_data` VALUES ('a2e60849-909d-4003-8128-1fc39f367097', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '弹药所', '战时或实弹训练中临时开设的负责弹药补给的机构。主要负责弹药的接收、分发、保管、回收、上交和消耗统计等工作。', 108);
INSERT INTO `t_military_term_data` VALUES ('a2eacbd3-1a35-4bd0-9be7-c2f734051c11', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '主官', '军队各级各类建制单位中担任正职的领导干部。如司令员、政治委员,连长、政治指导员,院长,所长等。', 103);
INSERT INTO `t_military_term_data` VALUES ('a2eb434a-47be-4a52-8202-9f88145ce2e8', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防空降障碍物', '用以阻止或迟滞空降兵着陆及着陆后的集结与机动的人工障碍物。如防空雷区、地雷场、桩砦、沟壕、铁丝网、拦障、土堆等。通常预先设置在反空降地域,或发现敌空降征候时临时设置。', 105);
INSERT INTO `t_military_term_data` VALUES ('a2fd5e33-0847-4cb3-a1bb-86f87aedd7ad', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '瓦解敌军', '中国人民解放军在对敌军斗争方面实行的原则。主要内容包括：配合军事打击,对敌军开展政治攻势,实行宽待俘虏政策,采取各种措施和手段,从政治上、组织上分化敌军,动摇敌人军心,促使敌军官兵反战、怠战、厌战、恐战,直至停止抵抗、投诚起义,以削弱和瓦解敌军战斗力。', 14);
INSERT INTO `t_military_term_data` VALUES ('a302c7f8-2208-4b9e-901d-055ee4a8d964', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹分队', '地空导弹营、连、排、班的统称。', 5);
INSERT INTO `t_military_term_data` VALUES ('a3070b01-ce7f-481d-a8e9-ac855f2a2339', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发动机探伤', '对固体导弹发动机进行的检查和探测。主要检查、探测发动机有无出现脱粘、裂纹、气孔、夹杂等。', 92);
INSERT INTO `t_military_term_data` VALUES ('a3129bee-9b1d-4ce6-b746-2cd28d94cb23', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '冲淡干扰', '在敌力导弹制导系统开机前施放多个假目标,以降低敌导弹制导系统锁定、跟踪真目标的概率的电子干扰战术。', 68);
INSERT INTO `t_military_term_data` VALUES ('a313eb72-018e-415c-929e-04d40f4735b2', 'd7132c58-5df3-4b97-919f-58740148b9ca', '目标防空', '亦称目标掩护、直接掩护。防空兵对合成军队和后方地域的重要目标实施的对空掩护。通常由集团军以下单位,使用建制的防空兵部队或分队实施。要求在被掩护目标的上空构成较绵密的防空火网。', 70);
INSERT INTO `t_military_term_data` VALUES ('a3222497-708b-492e-a55e-61770bfb2c8d', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战指挥', '军队指挥员及其指挥机关对作战行动的指挥按范围和层次分为战略指挥、战役指挥和战斗指挥。', 59);
INSERT INTO `t_military_term_data` VALUES ('a33b8390-7134-48f2-8a8b-fe69093d62f5', '916997ee-6728-4c61-9b79-d96960b1dc86', '喷洒车', '对武器装备、地面等实施消毒和消除沾染的专用车辆。可利用车上的设备调制洗消液和使用喷洒装置对洗消对象进行喷刷或喷洒。消除沾染时通常用水冲洗。', 190);
INSERT INTO `t_military_term_data` VALUES ('a3547739-bc12-41b4-b6a7-9c2a19313287', '06a75831-13a1-4660-870a-455bb445336a', '微波通信', '波长为 1米～0.1毫米（频率为0.3～3000吉赫）的无线电通信。包括微波接力通信、散射通信、卫星通信和毫米波通信等。通信频段宽、容量大、质量高、抗干扰能力强。通常用以建立战略、战役通信网和地域通信网的通信干线。', 105);
INSERT INTO `t_military_term_data` VALUES ('a36663ea-42af-4430-b44c-fd05130c8a35', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军种', '主要作战领域、任务和兵种,对军队的构成成分划分的基本种类。通常分为陆军、海军、空军。有的国家还划分有防空军、战略火箭军。军种又由若干兵种、专业兵组成。', 33);
INSERT INTO `t_military_term_data` VALUES ('a36abed4-860f-4008-97d0-d272bde6d213', '97a19170-bfac-42c5-9906-1acb187f0654', '后半球攻击', '飞机从空中目标的后方任意角度对其进行的攻击。', 88);
INSERT INTO `t_military_term_data` VALUES ('a374cd5b-e2fd-4984-a4ae-e8b8834bdc1c', '98df76fb-4b65-48ff-a56c-4db587327c79', '消耗量', '油料、武器、弹药和给养等物资的消耗数量。', 124);
INSERT INTO `t_military_term_data` VALUES ('a3841426-f8ec-4c06-9752-d350295b115e', '06a75831-13a1-4660-870a-455bb445336a', '电报站', '收、发电报和为其他电报站转报的通信站。主要设备有电报机和电报交换机。可收发音响电报和印字电报等。', 85);
INSERT INTO `t_military_term_data` VALUES ('a387ede5-3212-4187-b981-8d642af7c4a9', '8a761efd-50a6-4ac8-9913-b7d745104f82', '冷枪射击', '乘敌不备,暗中进行的单个枪械射击。', 104);
INSERT INTO `t_military_term_data` VALUES ('a39db0c6-f9c7-41ee-b449-fe0a2e98cede', '31f4a446-5b98-4873-9d53-310d97125b07', '反导系统', '拦截来袭弹道导弹的武器系统。包括拦截武器、预警雷达、目标识别雷达、目标跟踪雷达、目标拦截计算机、指挥中心等。', 32);
INSERT INTO `t_military_term_data` VALUES ('a39fbb5b-331f-4910-b258-d1c9f6e7e3a5', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境事件', '在边境地区发生的涉及相邻国家关系的重大事情。包括政治、外交、军事、经济、民族、宗教等方面的纠纷和由此而产生的武装冲突等。', 97);
INSERT INTO `t_military_term_data` VALUES ('a3a4b5fe-ae8b-4c94-bac6-287784b71b51', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸火球', '核爆炸时在爆点周围形成的高温、高压发光气团。火球以光和热的形式向外辐射能量,即光（热）辐射。', 165);
INSERT INTO `t_military_term_data` VALUES ('a3a860e4-dc3d-469c-abc1-39a2d7896f71', '97a19170-bfac-42c5-9906-1acb187f0654', '空军战役训练', '空军战役军团为掌握战役理论和战役行动的原则与方法而进行的训练。包括空军单独进行的战役训练和以空军为主体、其他军种参加的合同战役训练。', 197);
INSERT INTO `t_military_term_data` VALUES ('a3c2d85f-5308-4c10-a2c3-d253104fa38e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克潜渡场', '坦克潜渡江河的场地。应选择在入水角不大于20度,出水角不大于15度,河底坚实、平坦,水的流速小于 2米／秒的地段上。', 62);
INSERT INTO `t_military_term_data` VALUES ('a3c30031-ad57-4766-aa3b-7b1865ff5bdb', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '兵棋', '供沙盘或图上作业使用的军队标号图形和表示人员、兵器、地物等的模型式棋子。', 163);
INSERT INTO `t_military_term_data` VALUES ('a3c6991b-dac3-4c4e-b327-f7e1e56b635c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵预备队', '合成军队首长掌握的炮兵机动（后备）兵力。由机动性能较好、火力较强的炮兵部队或分队组成。兵力大小依据执行的战役、战术任务而定。主要用以对付突然发生的情况或增强主要方向的火力。', 46);
INSERT INTO `t_military_term_data` VALUES ('a3ccc7a3-4c62-45b3-94b6-5e422ed7442b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事地理', '①军事活动赖以存在并能给军事活动以影响的自然地理环境和人文地理环境的统称。包括地貌、水文、植被、气候、土壤以及资源、工农业生产、交通、人口、民族、城镇等要素。②同军事地理学。', 0);
INSERT INTO `t_military_term_data` VALUES ('a3cdf61a-0337-4356-8118-64897538d486', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '方面军', '战时由若干个集团军或军组成的军队一级组织。一般隶属于统帅部。设有领导机关,辖有一定数量的战斗部队和勤务保障部队。为诸军兵种合成的战略战役军团。', 14);
INSERT INTO `t_military_term_data` VALUES ('a3d69634-6b30-4958-baf5-f74e8159e18c', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火袋', '以各种火力从多方面构成的袋形火制区。', 244);
INSERT INTO `t_military_term_data` VALUES ('a3eebbff-161f-4614-9ecb-ab7e4d4ad06d', '878651de-adf5-4c72-9376-9c363b893ff8', '战略任务', '为达成战略目的而遂行的重大任务。分为总的、阶段性的和具体的战略任务。军队的战略任务通常由最高统帅机构确定和赋予。', 76);
INSERT INTO `t_military_term_data` VALUES ('a3f216d6-d0bc-43c6-bc64-a48510bc6b38', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上合同攻击', '海军两个以上兵种或战术群内两个以上舰种的兵力在统一计划和指挥下,协调一致地对敌实施的海上攻击。', 84);
INSERT INTO `t_military_term_data` VALUES ('a3f6210b-3937-4fc8-a651-b2483eef4f70', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '围攻', '攻歼被围之敌的作战行动。', 364);
INSERT INTO `t_military_term_data` VALUES ('a3f8d1ed-34c0-4350-bd9c-fea72c9390f1', '878651de-adf5-4c72-9376-9c363b893ff8', '战争进程', '战争进行的过程。通常指战争活动所经历的时空跨度。', 44);
INSERT INTO `t_military_term_data` VALUES ('a405e18c-26f1-4e25-bd0e-3be140ed9dee', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '侧方警戒', '位于行军纵队侧方,由侧卫或侧方尖兵实施的警戒。包括侧方移动警戒和侧方停留警戒。侧敌行军时、侧方警戒是行军警戒的主要部分。', 9);
INSERT INTO `t_military_term_data` VALUES ('a4161c0b-f1e7-4472-84ef-e917ba567fae', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰潜导弹', '从水面舰艇上发射,用以攻击潜艇的导弹。', 195);
INSERT INTO `t_military_term_data` VALUES ('a42d0d08-09d4-4ced-8c06-3bd4626cf989', '916997ee-6728-4c61-9b79-d96960b1dc86', '半数伤害剂量', '能使染毒人员50％丧失战斗力的毒剂量。用ID50或ICt50表示。', 134);
INSERT INTO `t_military_term_data` VALUES ('a43644ee-3b7f-4f01-98b5-19b423fa54c8', '916997ee-6728-4c61-9b79-d96960b1dc86', '受染标志', '标承受染区及其受染程度的标志。有标志牌、标志旗等。通常用规定的图形、文字、颜色等表示受染区特性,以避免人员误入受染区。', 148);
INSERT INTO `t_military_term_data` VALUES ('a43d34ee-6f6b-4b16-b25d-552b5f23e98b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程构筑', '为适应作战需要而进行的改造地形和修筑工程设施的行动。', 27);
INSERT INTO `t_military_term_data` VALUES ('a4459ce2-f4ff-4731-b9aa-cf7693e32a12', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '特种炮弹', '具有特殊结构或特殊装填物,能完成特种任务的炮弹。有曳光弹、燃烧弹、发烟弹、化学弹、照明弹、干扰弹、电视侦察弹和宣传弹等。', 326);
INSERT INTO `t_military_term_data` VALUES ('a446684f-834b-464a-83c4-f0d26a1da9d7', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇航行状态', '潜艇在水面和水下不同深度航行时所处的状态。分为水面航行状态、半潜航行状态、潜望深度航行状态、工作深度航行状态。', 293);
INSERT INTO `t_military_term_data` VALUES ('a447b1d3-3887-4563-90d5-c53f5adbe92c', '0', '炮兵', NULL, 13);
INSERT INTO `t_military_term_data` VALUES ('a44816e1-0d34-40b0-b1fb-5e34fce61ae1', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '光电经纬仪', '采用光电技术对运动目标跟踪测量的仪器。在电影经纬仪的基础上,增设有红外、电视、激光等探测装置,能对目标进行自动跟踪和精确测量,实时输出测量数据和目标图像。', 74);
INSERT INTO `t_military_term_data` VALUES ('a453f6c1-db7d-4148-9ad1-eb18d50a8cbd', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '潜伏侦察', '侦察分队或人员隐藏在敌人附近进行的侦察。主要查明敌人的设防和活动情况。伺机捕捉俘虏。', 37);
INSERT INTO `t_military_term_data` VALUES ('a454bf02-198b-41f7-9bb5-55f60ea4c5fa', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵气象保障', '第二炮兵为遂行作战和训练任务而在气象方面进行的保障。主要包括导弹发射区的气象保障和目标区的气象保障。', 187);
INSERT INTO `t_military_term_data` VALUES ('a45825f8-2678-49fa-a507-3692922386e4', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '集中', '将分散配置或分散行动的部队调集一起。', 327);
INSERT INTO `t_military_term_data` VALUES ('a45b5585-46f5-46fc-86a1-92dfd804539f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '宗教', '相信在现实世界之外存在着超自然、超人类的神秘境界和力量的社会意识形态。是一种历史现象,有其产生、发展和消亡的过程。宗教势力对政治、经济、军事和社会文化有重大影响。', 101);
INSERT INTO `t_military_term_data` VALUES ('a45e013c-76f5-4e57-9196-295084a75669', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克传动装置', '连接坦克发动机输出轴与坦克主动轮的所有部件的统称。是坦克推进系统的主要组成部分。分为机械传动装置、液体传动装置和电力传动装置。', 126);
INSERT INTO `t_military_term_data` VALUES ('a46e14dc-34c0-4693-9c9f-23e8d444d1cd', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '应急机动作战部队', '亦称快速反应部队。具有快速机动能力,能够紧急出动执行作战仟务的部队。主要用以应付局部战争和边境武装冲突以及其他军事突发事件。', 50);
INSERT INTO `t_military_term_data` VALUES ('a473124b-44cc-45c7-ae5e-659d1f05a225', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战协调', '指挥员及其指挥机关对所属部队和分队的作战行动在时间、空间与目标上进行的协调。主要包括纠正偏差,调整任务组织新的协同,调节行动速度等。', 106);
INSERT INTO `t_military_term_data` VALUES ('a47ad021-8f12-4250-bbb1-c100e0946ea7', 'f0140091-c11a-48c9-8836-8aa94439dac0', '纵深战斗', '战术纵深内的战斗行动。', 13);
INSERT INTO `t_military_term_data` VALUES ('a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '0', '工程兵', NULL, 10);
INSERT INTO `t_military_term_data` VALUES ('a49b69c8-9c80-4a0f-93cc-e78e130af6d9', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '前方警戒', '位于行军纵队前方,由前卫或前方尖兵实施的警戒。向敌行军时,前方警戒是行军警戒的主要部分。', 7);
INSERT INTO `t_military_term_data` VALUES ('a4a6e4a5-64ff-4c0e-b37b-191fa2536f25', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆技术保障', '为保持或恢复装甲车辆完好的技术状态而采取的各项保证性措施和进行的相应活动的统称。主要是组织对装甲车辆的正确使用、管理及其封存保管、检查保养、修理抢救和器材筹措补给等。', 187);
INSERT INTO `t_military_term_data` VALUES ('a4aa907b-433e-43a7-a018-af43aa20b6db', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '国际信号', '国际间海上通信所使用的信号简语。供不同国籍的舰船间及舰船与岸上信号台间使用。信号简语由《国际信号规则》统一规定,以字母或字母加数字组成信号码组,每一个信号码组代表一个完整的特定含义,可使用各种通信工具传递。', 360);
INSERT INTO `t_military_term_data` VALUES ('a4bb940e-85c4-4028-b8d6-5dbf24336a31', '83e065b4-6737-4645-9ea5-8276d1de13ed', '轻型坦克', '战斗全重一般为20吨以下的坦克。主要用于侦察、警戒和特定条件下作战。通常装备于机械化部队、摩托化部队的侦察分队以及空降兵和海军陆战队。', 87);
INSERT INTO `t_military_term_data` VALUES ('a4c14e03-fc46-4b90-9373-5f83f91650c0', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹一次转移火力', '在有多批或多个空中目标连续进袭,目标的批次间隔时间小于地空导弹射击周期的情况下,利用后续目标在地空导弹发射区内飞行的时间完成射击准备,并射击该批目标的转移火力的方法。', 203);
INSERT INTO `t_military_term_data` VALUES ('a4cb9d09-6128-4841-88db-03227b2bab0e', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '单脉冲雷达', '从单个目标回波脉冲信号中获取目标角度和距离信息的雷达。测量精度高、速度快,反角度欺骗干扰能力强。军事上广泛用于武器的火力控制、靶场试验中的精密跟踪测量以及气象探测等方面。', 89);
INSERT INTO `t_military_term_data` VALUES ('a4de530a-f70a-4193-a508-ceb9afe2c6c5', '916997ee-6728-4c61-9b79-d96960b1dc86', '工事防化设施', '亦称工事三防设施。使工事内人员免受毒剂、生物战剂、放射性落下灰伤害的防护设备和器材的统称。通常包括；工事气密、滤毒通风和人员进出保障设施,以及报警控制、防化监测和洗消设施等。', 180);
INSERT INTO `t_military_term_data` VALUES ('a4df36f8-6a74-476a-aa29-a3083bc1d548', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '兵种', '按主要武器装备和作战任务,对军种的构成成分划分的基本种类。如：陆军划分为步兵、装甲兵、炮兵、陆军航空兵、工程兵、通信兵、防化兵等兵种；海军划分为潜艇部队、水面舰艇部队、海军航空兵、海军岸防兵、海军陆战队等兵种；空军划分为航空兵、地空导弹兵、高射炮兵、空降兵、雷达兵等兵种。', 34);
INSERT INTO `t_military_term_data` VALUES ('a4e27154-2df2-492c-9f2c-99d5a3b96205', '97a19170-bfac-42c5-9906-1acb187f0654', '人机比', '航空兵部队在编的飞行员人数或空勤组数与在编的飞机或直升机架数的比例。战时的人机比一般高于平时的人机比。', 192);
INSERT INTO `t_military_term_data` VALUES ('a4e6862c-3ad8-4751-b31a-f1abd683c089', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '壤土', '土壤颗粒组成中砂粒、粉粒、粘粒含量适中的土壤。兼具砂土、粘土的优点,通气透水性能较好,是农业生产上较理想的土壤。军事上便于部队运动和工程构筑。', 85);
INSERT INTO `t_military_term_data` VALUES ('a4f0c6c1-4f45-4d57-80cb-f9140cd4be82', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防决算', '国防预算执行结果的总结报告。是国家决算的组成部分。', 35);
INSERT INTO `t_military_term_data` VALUES ('a4f5c3a6-2c53-4d47-84c1-2b10e42ea75c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '船时', '装配在舰船上的专用时钟（简称船钟,天文钟除外）所指示的时间。在港停泊采用当地标准时。远洋航行时一般采用时区时,过时区时要将船钟拨快或拨慢1小时。', 283);
INSERT INTO `t_military_term_data` VALUES ('a4ff97bf-67d7-4428-a766-0576bb00fb53', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '突然袭', '简称突袭。对敌实施的出其不意、急促猛烈的攻击。分为战略突袭、战役突袭、战术突袭。', 206);
INSERT INTO `t_military_term_data` VALUES ('a50582d1-f065-4672-a9d4-b9350384248c', '06a75831-13a1-4660-870a-455bb445336a', '战略通信', '为保障战略指挥而建立的通信联络。基本任务是保障战略警报信号和情报信息的传递,保障统帅部指导战争全局和直接指挥重大战役的通信联络,以及保障战略后方的通信联络等。', 23);
INSERT INTO `t_military_term_data` VALUES ('a51519d2-4391-4701-9603-e86da8aa5b48', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '通路勤务', '对通路进行警戒、维护、加宽、封闭以及调整通过次序等勤务工作的统称。通常由开辟通路的分队负责。', 201);
INSERT INTO `t_military_term_data` VALUES ('a5262c8c-8ed7-4958-9286-0852dbeebc37', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '进攻速度', '进攻的军队每昼夜或每小时推进的平均速度。通常用公里／日或公里／时表示。', 88);
INSERT INTO `t_military_term_data` VALUES ('a52effcd-1e65-486e-b097-c6d94c278928', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弯曲弹道', '用大于最大射程角的射角射击时所获得的弹道。弹道弯曲度大,落角一般大于20度,适合射击遮掩物后面或反斜面上的目标。', 36);
INSERT INTO `t_military_term_data` VALUES ('a52fdcc3-a8dd-40c9-a0ea-0de727a29a2c', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '危险天气通报', '气象台站按规定格式和要求及时编发的危险天气发生或解除的天气实况报告。内容包括危险天气发生或解除的时间、种类、强度、所在方向和去向等。', 68);
INSERT INTO `t_military_term_data` VALUES ('a5313e90-99a4-419b-bfa7-44c03df598fe', '878651de-adf5-4c72-9376-9c363b893ff8', '战略价值', '某事物在国防或战争全局中所具有的重要性的程度。如在主要战略方向上的要地或交通、通信枢纽等,在战争全局上具有重要的战略价值。', 73);
INSERT INTO `t_military_term_data` VALUES ('a53a6952-5405-4769-a675-552bddbb3200', '97a19170-bfac-42c5-9906-1acb187f0654', '应急起飞跑道', '简称应急跑道。机场中主跑道以外供疏散、隐蔽的飞机紧急情况下起飞的跑道。以拖机道与主跑道、飞机洞库、飞机疏散区相连,并与主跑道保持规定的安全距离。', 426);
INSERT INTO `t_military_term_data` VALUES ('a53bde25-4938-4b60-862d-6a8db7d7fa0d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '落差', '水位落差的简称。河道上某一段的两个地点,在同一时刻以同一基准面计算的水位高程差。河源与河口间的水位落差称为总落差。是衡量河流水力资源大小的主要因素之一。落差大,表明河流水力资源丰富。', 71);
INSERT INTO `t_military_term_data` VALUES ('a53cdb6f-c2ce-4e7a-8cee-5a73abcf256a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军炮', '装备在舰艇和岸防阵地上的海军专用火炮。包括舰炮和海岸炮。', 183);
INSERT INTO `t_military_term_data` VALUES ('a54614b5-629d-4321-952e-bb368bdc2a5c', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥重心', '指挥员在指挥部队作战或其他行动时,须全力关注和解决的对全局具有决定性影响的问题。', 8);
INSERT INTO `t_military_term_data` VALUES ('a54ae3ce-3cb6-4a13-8483-223236579bb7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '僵持', '作战中出现的敌对双方胜负难分、相持不下的态势。', 406);
INSERT INTO `t_military_term_data` VALUES ('a54d6c33-7960-470a-ad1d-65212ddb1954', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '夜视技术', '在夜间或低照度条件下,将不可见的景物图像经光电转换增强为可见图像的技术。包括主动红外夜视技术、激光夜视技术和热成像技术等。军事上主要应用于夜间侦察、瞄准、导航、驾驶车辆和武器的火控系统。', 26);
INSERT INTO `t_military_term_data` VALUES ('a54e1405-347c-4dd7-8c27-43ec106ab044', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '临界质量', '在一定条件下实现自持的链式裂变反应所需的核裂变材料的最小质量。任何易于发生裂变的物质,只有当其质量达到或超过临界质量时,才能发生自持裂变反应。', 115);
INSERT INTO `t_military_term_data` VALUES ('a54e9daf-d44f-43b2-9500-69aca564e911', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '高程基准', '地面点高程的起算面。一个国家采用一个平均海面作为统一的高程基准。中华人民共和国曾规定以青岛验潮站验潮资料算得的1956年黄海平均海面作为全国统一的高程起算面。1987年正式启用“1985年国家高程基准”,比1956年的高程基准面高0.029米。', 176);
INSERT INTO `t_military_term_data` VALUES ('a55666b4-7989-43d2-a8ba-19f81f63310c', '8a761efd-50a6-4ac8-9913-b7d745104f82', '防盾', '专门设计制造的用以保护人员或武器装备免遭杀伤击毁的遮挡物。手持的防盾通常由工程塑料等制成主要用以遮挡拳击和投掷物。安装在武器装备上的防盾通常由钢板等制成,主要用以抵挡枪弹或弹片。', 191);
INSERT INTO `t_military_term_data` VALUES ('a55a28c2-6784-432f-8c72-e498fe6018ff', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海岸炮', '简称岸炮。配置在港口要塞、海岸重要地段、岛屿和水道翼侧,以火力遂行海岸防御任务的海军炮。按配置方式,分为固定式岸炮和移动式岸炮；按防护结构,分为炮塔式岸炮和护板式岸炮。', 185);
INSERT INTO `t_military_term_data` VALUES ('a55a5b2c-5ab2-4994-a92a-daa6fc0d406e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练方法', '军事训练的组织与实施的方式方法。包括理论传授、技能教练以及各种战术、战役训练的方法。', 140);
INSERT INTO `t_military_term_data` VALUES ('a5763139-ed04-4e66-a2bf-ecc12dbea930', '8a761efd-50a6-4ac8-9913-b7d745104f82', '枪械', '简称枪。利用火药燃气等能量通过身管发射弹丸，口径通常小于20毫米的武器。分为手枪、步枪、冲锋枪、机枪等。主要用以射击生动目标和低空目标。利用电能、声能、激光等现代新技术的小型轻便的杀伤武器,称为新型枪械。', 148);
INSERT INTO `t_military_term_data` VALUES ('a588cf28-e5df-4a74-a9d1-3e0952faf356', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '以劳养武', '和平时期民兵以生产经营的收益补充人民武装工作必要的经费开支。', 129);
INSERT INTO `t_military_term_data` VALUES ('a5b61457-ca18-4e21-b0d5-bae09e94f54c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克公路平均运动速度', '坦克在战斗全重状态及规定的环境条件下,按规定比例的各类公路路面行驶的平均运动速度。坦克公路平均运动速度约为最大速度的60％～70％。', 158);
INSERT INTO `t_military_term_data` VALUES ('a5b6d95b-e818-4929-94a0-780616000d88', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克战损率', '战场损伤（包括技术损坏）的坦克数与参战坦克总数的比值。通常用百分比表示。是实施坦克技术保障的一个重要参数。', 199);
INSERT INTO `t_military_term_data` VALUES ('a5d660b4-dd4c-4605-9ba8-216927d0f911', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '非全训', '全年中以少量的时间进行军事训练。中国人民解放军中非全训的部队或分队,主要指执行生产、营建、施工、执勤或其他任务的部队或分队。其年度训练时间一般要求不得少于30天；在训练时间内,要求参训人数达到实力数的80％以上。', 10);
INSERT INTO `t_military_term_data` VALUES ('a5d868fa-5b63-42c5-8ca6-216a15bf27ea', '98df76fb-4b65-48ff-a56c-4db587327c79', '自救互救', '作战人员自我和相互之间进行的战伤救护活动。主要内容包括止血、包扎、固定、通气、搬运等。是加强火线抢救的重要措施。', 200);
INSERT INTO `t_military_term_data` VALUES ('a5db3278-0261-49a5-a2f6-5b1c6f1f6750', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役佯动', '为隐蔽战役企图和行动而采取的隐真示假的行动。是战役伪装的一种方式。', 49);
INSERT INTO `t_military_term_data` VALUES ('a5e69047-28a3-40f9-9197-3f9a0c46c088', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '运载火箭', '装载和运送航天器进入外层空间预定轨道的火箭。一般为2～4级的多级火箭。', 68);
INSERT INTO `t_military_term_data` VALUES ('a5ec199c-83fd-4201-a83a-a6351d3bd3b3', '97a19170-bfac-42c5-9906-1acb187f0654', '空降地区', '空降部队或空降人员伞降或机降着陆的地区。大规模空降时,空降地区包括若干个空降场。', 162);
INSERT INTO `t_military_term_data` VALUES ('a5f39ce8-2dca-49cd-aab1-93904f567373', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术开进', '兵团或部队、分队由集结地域向进攻出发阵地或防御阵地的机动。', 35);
INSERT INTO `t_military_term_data` VALUES ('a5f867b4-3807-4574-bd68-28ab8b3eb107', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击武器', '以身管发射弹丸的武器。如枪械、火炮等。也泛指一切利用机械的、化学的或其他能是将射弹射向目标的武器,如火箭、导弹、鱼雷等。', 2);
INSERT INTO `t_military_term_data` VALUES ('a5fa6c30-d81a-4d57-a1e2-9c9e3ac1e79e', '97a19170-bfac-42c5-9906-1acb187f0654', '着陆线', '机场上飞机着陆滑跑结束后发动机停车的地方。通常位于跑道一端。', 429);
INSERT INTO `t_military_term_data` VALUES ('a5ff1ac2-9e9a-4d89-a931-6267e52c1c08', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行指挥员', '亦称塔台指挥员。在塔台直接指挥航空器飞行的指挥员。通常由上级批准的担负领导职务的军官担任。', 188);
INSERT INTO `t_military_term_data` VALUES ('a5ff22f3-ef98-4b1e-9bb4-87069ed4b32f', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '收容队', '随行军的部队移动,负责收容行军途中掉队人员和伤病员的临时性组织。', 72);
INSERT INTO `t_military_term_data` VALUES ('a60288a2-f017-432b-8ef2-180aa9a00731', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '火力反准备', '对发起进攻直前之敌实施的火力打击。通常由炮兵、航空兵、导弹部队等实施。用以破坏敌之进攻计划和行动。', 260);
INSERT INTO `t_military_term_data` VALUES ('a6055305-1024-46df-9c94-2f7e224ac751', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹测试车', '装有检测地空导弹设备和供电系统的专用车辆。用于对地空导弹及有关系统的检查和测试。', 39);
INSERT INTO `t_military_term_data` VALUES ('a607de8a-d397-4c18-95bb-be6703a2e320', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '山麓', '亦称山脚。山脉或山岭的最下部分,与周围谷地或平地交界的地带。', 20);
INSERT INTO `t_military_term_data` VALUES ('a6118619-d7a3-40e0-b142-8e48fef4255c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰舰导弹', '从水面舰艇上发射,用以攻击水面舰艇的导弹。分为近程舰舰导弹和远程舰舰导弹。', 187);
INSERT INTO `t_military_term_data` VALUES ('a61d5ab1-0263-484b-b653-24dd6dcc5b29', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '机械化步兵', '亦称装甲步兵。能以建制内的装甲战斗车辆实施机动,乘车或下车进行战斗的步兵。', 37);
INSERT INTO `t_military_term_data` VALUES ('a62c85f0-fd49-4e41-b209-bd461dd6af5a', '98df76fb-4b65-48ff-a56c-4db587327c79', '供应标准', '军队关于经费、物资供给的统一规定。内容包括：经费供应的数额,物资供应的范围、数量、质量和物资使用时限等。分为平时标准与战时标准；基本标准与补助或附加标准等。', 106);
INSERT INTO `t_military_term_data` VALUES ('a62e9102-f907-45c5-8f32-0a4cf94d3cff', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '太阳系', '太阳和以太阳为中心,受其引力支配而环绕它运动的天体构成的系统。主要包括：太阳和9颗大行星及大行星的50颗天然卫星,2000多颗已测出轨道的小行星,1600多颗已发现的慧星和难以计数的流星体、星际物质以及为数众多的人造天体。', 185);
INSERT INTO `t_military_term_data` VALUES ('a63a6b83-c56b-425f-8db5-dc2f989ee6e7', '98df76fb-4b65-48ff-a56c-4db587327c79', '补给方式', '军队实施物资补给的方法和形式。如逐级补给、越级补给,定点补给、途中补给、伴随补给,海上补给、空投补给等。', 129);
INSERT INTO `t_military_term_data` VALUES ('a63d40e9-5ad5-4010-9b22-781fef1ea1be', '97a19170-bfac-42c5-9906-1acb187f0654', '机载雷达', '飞机或直升机上各种专用雷达的统称。包括机载的火控雷达、导航雷达、航行雷达、预警雷达以及空中侦察雷达和地形测绘雷达等。', 340);
INSERT INTO `t_military_term_data` VALUES ('a64066ef-2608-415e-8c43-73a43a91b1b8', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '协调世界时', '以原子时秒长为基准，在时刻上尽量接近于世界时的一种时间计量系统。原子时秒长与世界时秒长不相等。当原子时秒长累积的时刻与世界时时刻相差接近0.9秒时,协调世界时就增加1秒或减少1秒,称为跳秒（闰秒）。目前世界上各授时台播送的时号大部分是协调世界时时号。', 214);
INSERT INTO `t_military_term_data` VALUES ('a6422d62-f875-4a8a-b608-32cb4c579d18', '31f4a446-5b98-4873-9d53-310d97125b07', '核袭击', '使用核武器对敌进行的袭击。', 27);
INSERT INTO `t_military_term_data` VALUES ('a646dfce-40b7-47cc-83b5-3938a65c8950', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '三角点', '在三角测量中构成水平控制同的各三角形的顶点。通常用埋设于地面或地下一定深度的标石表示其点位,并建造测量观标以供观测照准和整置仪器用。', 167);
INSERT INTO `t_military_term_data` VALUES ('a64d1e2a-3658-4185-b12d-0dd967e6010f', '916997ee-6728-4c61-9b79-d96960b1dc86', '氧化罐', '亦称霍加拉特罐。防一氧化碳气体的专用滤毒罐。适用于一氧化碳浓度不很高的场合。使用时可直接连在防毒面具的面罩上,也可与滤毒罐相连接。', 173);
INSERT INTO `t_military_term_data` VALUES ('a6568598-5afe-4533-88df-dd2b43b544aa', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '战斗工程保障', '对战斗行动实施的工程保障。由战术指挥机关组织实施。主要任务是；实施工程侦察,构筑工事,设置和排除障碍物，实施破坏作业,构筑和维护道路、桥梁、渡场,实施工程伪装,侦察水源和建立、维护给水站,以工程手段消除敌核、化学、生物武器和燃烧武器袭击造成的后果等。', 12);
INSERT INTO `t_military_term_data` VALUES ('a666e990-75dc-450d-83d6-3fbbab020eb1', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '密级', '秘密等级的简称。对各种信息载体根据其内容的涉密程度划分的等级。一般分为绝密、机密、秘密3个等级,并用印章、注记等在载体上标明。', 71);
INSERT INTO `t_military_term_data` VALUES ('a674e3cd-a3e6-44b6-aa97-97a3f612a354', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '直属单位', '军队中各级各类领导机关直接管辖的建制单位。如集团军直属工兵团、师直属侦察连等。', 11);
INSERT INTO `t_military_term_data` VALUES ('a67cad17-adc8-4f0a-b5af-1b0b543afeac', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '吊放声纳', '用吊放电缆将探头悬垂入水中进行目标探测的声纳。主要装备于反潜直升机。', 239);
INSERT INTO `t_military_term_data` VALUES ('a68f000a-bb9f-4640-b168-e172728d5eca', '98df76fb-4b65-48ff-a56c-4db587327c79', '伴随保障', '组织后勤力量随同部队或分队实施的后勤保障。通常在部队担负长途开进以及穿插、迂回、追击等机动作战任务时采用。', 26);
INSERT INTO `t_military_term_data` VALUES ('a6cd28c9-ddde-4b49-bc77-bea50766cced', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '反突击方向', '防御战役中对突入之敌实施攻击的行动方向。通常根据敌人进攻态势、反突击地区地形特点和反突击目的而定。', 134);
INSERT INTO `t_military_term_data` VALUES ('a6d176a4-fde9-492d-980a-ef4d1b3948bc', '06a75831-13a1-4660-870a-455bb445336a', '计算机通信', '计算机之间或计算机与终端设备之间,以数据传输形式传输信息的通信。一般组成通信网实施。广泛用于指挥自动化、武器控制、情报资料检索、信息处理、办公自动化等。', 143);
INSERT INTO `t_military_term_data` VALUES ('a6e39555-c866-454b-936b-ae8a7447f7b9', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '尉官', '①军官军衔中最低的一等。通常分为上尉、中尉、少尉3级。有的国家还在上尉之上设大尉,少尉之下设准尉。②泛指被授予尉官军衔的军官。', 133);
INSERT INTO `t_military_term_data` VALUES ('a6fb6b29-1830-4f14-afe3-de7ab11762a5', 'd7132c58-5df3-4b97-919f-58740148b9ca', '标定', '使高炮射向与仪器、器材瞄准线取得一致的行动过程。基本方法有远点标定、反观标定和各自标定。', 192);
INSERT INTO `t_military_term_data` VALUES ('a70391ff-56b1-4016-bba7-bd0036e17601', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '作风建设', '中国人民解放军为培养部队优良作风而进行的建设。如教育官兵发扬实事求是、艰苦奋斗、英勇顽强、雷厉风行、令行禁止、团结互助、公道正派、廉洁奉公的优良作风等。', 25);
INSERT INTO `t_military_term_data` VALUES ('a707be10-ac0f-4f53-b3e2-57a4c4b69b6d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '防潜障碍', '用以阻止敌潜艇突入和潜射鱼雷穿过的水中障碍。包括防潜水雷障碍、防潜网和防鱼雷网。', 97);
INSERT INTO `t_military_term_data` VALUES ('a709065f-7995-4fed-98a9-54656d109e90', '06a75831-13a1-4660-870a-455bb445336a', '通信预备队', '作战部署中作为机动使用的通信兵力。由司令部所属或加强的通信专业分队组成。通常配置在便于机动的隐蔽地域,使用在具有决定意义的时机和方向。', 28);
INSERT INTO `t_military_term_data` VALUES ('a7126ee7-ae37-4ecf-9fde-6dc867f83f9b', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '内务秩序', '军队内部日常生活事务按照有关条令和规定保持的井然有序的状态。包括工作秩序和生活秩序等。', 30);
INSERT INTO `t_military_term_data` VALUES ('a719ef9e-ba3e-4c98-90c2-1342e701428e', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '作战实力', '亦称战斗实力。军队或军队某一组织能够投人作战的建制单位、人员、武器装备等的数量与质量。是构成军队作战能力的主要因素。', 85);
INSERT INTO `t_military_term_data` VALUES ('a71bbf28-3630-43d9-98c7-4fa8e9ee9649', '97a19170-bfac-42c5-9906-1acb187f0654', '制导航空炸弹', '亦称灵巧炸弹。有制导装置和空气动力操纵面的航空炸弹。包括激光、电视、红外和无线电等制导方式的航空炸弹。', 320);
INSERT INTO `t_military_term_data` VALUES ('a72059f7-5d00-4318-908a-6e8b351d6fcc', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰船分道通航制', '规定船舶分道单向航行的制度。通常用分隔带、分隔线、自然障碍物或特定的地理物标,将航道分隔成左右两个分道实施,以保障船舶航行安全。', 292);
INSERT INTO `t_military_term_data` VALUES ('a72089b3-3f1f-4f27-8dc4-29e136239fb0', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核试验安全措施', '进行核爆炸试验时,为确保试验地区人员和建筑物等不受核爆炸诸毁伤因素的危害而采取的防护措施。', 189);
INSERT INTO `t_military_term_data` VALUES ('a7365154-5cb1-419e-b114-53f9d60cd397', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边界谈判', '相邻国家为解决共同边界问题而进行的会谈。包括为边界的位置、走向以及历史遗留的边界纠纷等问题而进行的谈判。有双边和多边的谈判。', 119);
INSERT INTO `t_military_term_data` VALUES ('a7424298-dc96-46a9-93fd-1af0baceec27', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '协同作战', '在联合作战或合同作战中,参战的各军兵种部队按照协同计划,协调一致地进行作战。', 181);
INSERT INTO `t_military_term_data` VALUES ('a74abcb5-dc00-467b-b8da-9d965fd7783c', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击目标类型', '按照一定的标准对各种核打击目标所作的基本分类。按目标的价值,分为战略目标、战役目标和战术目标；按目标的性质,分为军事目标、工业目标、城市目标和交通目标；按目标的幅员,分为点目标和面目标；按目标的抗压强度,分为硬目标和软目标等。', 161);
INSERT INTO `t_military_term_data` VALUES ('a76a7eae-829c-4bbd-97a9-2444586686e9', 'f0140091-c11a-48c9-8836-8aa94439dac0', '防御阵地体系', '由防御阵地的各要素按作战要求构成的有机整体。主要包括射击、指挥、观察、隐蔽、机动等各种工事和障碍物等。分为堑壕式防御阵地体系、支撑点式防御阵地体系、堑场式与支撑点式相结合的防御阵地体系等。', 217);
INSERT INTO `t_military_term_data` VALUES ('a77b82b3-6d83-4446-b3a9-945764e8af86', '97a19170-bfac-42c5-9906-1acb187f0654', '军用飞机', '列入军队编制直接用于作战、训练和保障等任务的各种飞机的统称。包括作战飞机、军用运输机和军用教练机等。', 279);
INSERT INTO `t_military_term_data` VALUES ('a7815993-c112-4199-9e1c-50bad279b342', 'f0140091-c11a-48c9-8836-8aa94439dac0', '换乘', '①登陆兵由运输舰船转换到登陆工具上的行动。在运输舰船进入换乘海域时进行。②部队在陆上输送途中,转换输送工具的行动。', 146);
INSERT INTO `t_military_term_data` VALUES ('a786d1db-50ad-4b4f-82f6-42a5ec7072b7', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '助爆型原子弹', '亦称加强型原子弹。在核裂变装料中添加少量热核材料的原子弹。通过添加热核材料,可提高核裂变装料利用率,增加裂变威力；并可通过改变热核材料的装量,调节原子弹威力的大小,有利于核装置的小型化。', 87);
INSERT INTO `t_military_term_data` VALUES ('a7947c76-c447-426b-93d3-222513c122a2', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '巡回修理', '由机动修理分队或临时组成的流动修理小组,到部队驻地或阵地上对武器装备进行的修理。', 127);
INSERT INTO `t_military_term_data` VALUES ('a79c4808-7658-4168-b4eb-edb0ef242f31', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '卫星激光测距', '利用地面测站上的卫星激光测距仪测定地面测站至卫星的距离。用以测定卫星的精确轨道及地面测站的精确位置和地极移动等。', 225);
INSERT INTO `t_military_term_data` VALUES ('a79f247d-7746-49fc-80ea-1bb51090096e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克技术保障组', '坦克营战时组织的临时性技术保障机构。由坦克分队的技术干部和上级加强的技术力量组成。负责观察报告坦克损坏情况,及时进行技术条件允许的抢救、抢修,或给坦克乘员以技术支援和提供所需器材。', 231);
INSERT INTO `t_military_term_data` VALUES ('a79fd5cd-4abd-43f4-8cfd-82d432fbcb99', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '军事航海', '军用船只执行作战、训练等任务时的海上航行活动。主要包括：选择最佳航线,实时定位和导航,进行舰艇战术机动,完成各项航海保障工作等。', 251);
INSERT INTO `t_military_term_data` VALUES ('a7a54c94-cc71-42cf-8274-e4859661b058', '98df76fb-4b65-48ff-a56c-4db587327c79', '铁路便线', '技术标准较低、工程量较小的简易铁路线。通常修筑在发生严重障碍、短期内难以修通的铁路正线附近。主要作为绕过正线被毁路段的迂回线使用,或作为运送施工料具的临时线路使用。', 261);
INSERT INTO `t_military_term_data` VALUES ('a7ad4710-cb9b-430d-802d-5fdde5d2deb0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵预备阵地', '预先选定的备用的炮阵地。在基本阵地不能遂行射击任务时使用。炮兵预备阵地应构筑一定的工事。', 57);
INSERT INTO `t_military_term_data` VALUES ('a7b76621-9386-4d75-92e0-2f9ccd605f78', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '围点打援', '以部分兵力包围城市或要点,诱敌增援,集中主力歼灭援敌于运动中。目的不在于打被围之敌,而在于打援敌。', 234);
INSERT INTO `t_military_term_data` VALUES ('a7bdb0fe-653a-48e1-bf37-9f96ec0d04e1', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无源电子干扰', '简称无源干扰,亦称消极干扰。利用本身不发射电磁波的器材反射或吸收敌电子设备发射的电磁波而形成的电子干扰。按干扰原理,分为反射型无源干扰和吸收型无源干扰。', 44);
INSERT INTO `t_military_term_data` VALUES ('a7c07ccf-09fb-41d2-b648-b692e3148f43', '98df76fb-4b65-48ff-a56c-4db587327c79', '野战油库', '野战条件下临时开设的储备和补充油料的仓库。主要负责衔接后勤基地对作战部队的油料供应。', 176);
INSERT INTO `t_military_term_data` VALUES ('a7c9ac17-8a02-45f7-8820-4f8be1d7df6c', '98df76fb-4b65-48ff-a56c-4db587327c79', '野营装备', '供部队野外宿营用的制式设备和器材的统称。包括宿营装备、照明装备、取暖装备、储运水装备、淋浴设备、活动厕所、营具等。', 238);
INSERT INTO `t_military_term_data` VALUES ('a7de4c61-544c-477e-803a-6bf54f6f64d1', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗支援侦察', '在战斗准备和战斗过程中实时截获、识别敌方电子设备的电磁辐射信号,判明其属性和威胁程度的电子对抗侦察。主要用于威胁告警和为实施电子干扰、电子防御、规避机动及引导杀伤武器等作战行动提供情报。', 21);
INSERT INTO `t_military_term_data` VALUES ('a7e4ed98-5991-40af-91b1-3c26fecf79ca', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '天体', '宇宙间各种星体的统称。分为自然天体和人造天体。如：恒星、星云、行星、卫星、小行星、慧星、流星等,属自然天体；人造卫星、宇宙火箭、行星际飞船等,属人造天体。', 184);
INSERT INTO `t_military_term_data` VALUES ('a7e7ad47-bcc0-43e7-80aa-534607f23744', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '潮汐表', '专门编制的沿海主要军港和有关海区未来一定时期内（通常为1年）的潮汐预报资料。内容包括逐日高潮和低潮的潮时和潮高,以及附近海区的潮流情况等。', 143);
INSERT INTO `t_military_term_data` VALUES ('a7e8d671-1501-4da9-a149-8ff42d898af2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '早期疏散', '在出现战争迹象,形势逐渐紧张时进行的疏散。', 221);
INSERT INTO `t_military_term_data` VALUES ('a7eec324-8682-44b9-9f21-eaf3655b0c94', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子防御', '在电子对抗斗争中,为保护己方电子设备及其系统正常发挥效能而采取的措施与行动的统称。主要包括反电子侦察、反电子干扰和防反辐射武器摧毁等。由雷达、无线电通信等专业部队、分队和使用各种电子设备的战斗部队、分队按统一计划分别组织实施。', 91);
INSERT INTO `t_military_term_data` VALUES ('a7fa792f-836e-451f-afa9-6201220a484f', '83e065b4-6737-4645-9ea5-8276d1de13ed', '一类坦克', '符合规定的技术状况,储备足够的摩托小时,能及时执行任务,具有持续战斗力的坦克。', 190);
INSERT INTO `t_military_term_data` VALUES ('a7faba5f-78e3-4215-b4c0-620bc5b389b7', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮穿甲燃烧榴弹', '具有穿甲、燃烧和破片杀伤作用的高射炮弹。可侵入目标内爆炸并燃烧。主要用以射击空中和地面有装甲防护的目标。', 218);
INSERT INTO `t_military_term_data` VALUES ('a8059bb2-4e8f-486c-862a-f4ae004e6eb9', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军基地防御', '为保卫海军基地及其驻泊兵力的安全和行动自由而进行的防御。通常以海军基地兵力为主,诸军兵种部队联合组织实施。主要包括：对空防御,对潜防御,对水面舰艇防御,对水雷防御,对陆防御,电子防御以及对核、化学、生物武器袭击的防护等。', 32);
INSERT INTO `t_military_term_data` VALUES ('a81895b4-fd37-4ee1-abca-5f0343604ee0', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '联合指挥所', '亦称联合指挥部、由两个以上不同建制单位共同建立的对联合行动实施指挥的机构、包括由两支以上军队或同一军队的不同建制单位以及军队与地方共同建方的联合指挥所。', 51);
INSERT INTO `t_military_term_data` VALUES ('a8264ec8-9979-40a6-a980-87fe15422fca', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '登陆展开区', '简称展开区。登陆作战中登陆编队完成航渡后,由登陆编队展开线至登陆冲击出发线之间的海区。', 100);
INSERT INTO `t_military_term_data` VALUES ('a8320339-87d9-4967-96d8-7d28654bb586', '06a75831-13a1-4660-870a-455bb445336a', '通信指示', '上级司令部向下级司令部和通信部队、分队下达通信任务的指示。根据通信计划拟制。主要包括；本级各通信枢纽的开设地点、时限和预定转移地点,通信联络组织,任务区分,通信联络沟通时限,通信对抗措施,通信器材供应与技术保障,以及有关规定与要求等。', 33);
INSERT INTO `t_military_term_data` VALUES ('a8345cbe-cc50-4d85-a9cc-c4f215dccf9e', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '点圈战术', '以少量直升机从上面攻击，大部分直升机从翼侧和后方对敌装甲目标进行突击的方法。', 73);
INSERT INTO `t_military_term_data` VALUES ('a83c2fff-2a6f-47ca-a9f3-6a7156d8f7ca', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '大地控制点', '简称大地点。利用大地测量方法以一定的精度测得水平位置和高程的固定点。包括三角点、导线点和水准点。点上设置有测量标志,以示点位。', 165);
INSERT INTO `t_military_term_data` VALUES ('a84c7325-8f10-4846-87a7-3de21b7ace92', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻型冲锋枪', '全枪重在2千克以下的冲锋枪。比一般冲锋枪更加短小、轻便、灵巧,可以单手射击。', 159);
INSERT INTO `t_military_term_data` VALUES ('a8503615-9816-4772-9bf6-80192256613d', '916997ee-6728-4c61-9b79-d96960b1dc86', '核爆炸探测仪器', '测定核爆炸时间、爆炸点坐标、爆炸威力以及核弹类型等参数的专用仪器。按探测范围,分为远距离、中距离、近距离3类核爆炸探测仪器；按探测方法,分为自动测量和目视观测两类核爆炸探测仪器。所获参数用以估算核爆炸的毁伤效应。', 151);
INSERT INTO `t_military_term_data` VALUES ('a85336f7-5086-4751-a55f-7a4af1e0edf1', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '抗核加固', '简称核加固。为使武器系统及其设施、设备在核爆炸环境中仍能保持其预定功能而采取的防护加固措施。', 133);
INSERT INTO `t_military_term_data` VALUES ('a866066e-3b93-4774-890e-e9f5c4c139f3', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学弹药', '战斗部内主要装填毒剂或毒剂前体的弹药。包括化学炮弹、化学航空炸弹、化学火箭弹、导弹化学弹头和化学地雷等。按装填毒剂的毒害作用,分为神经性、糜烂性、全身中毒性、窒息性和失能性化学弹药。', 199);
INSERT INTO `t_military_term_data` VALUES ('a8742520-24cf-4825-aa8a-157b381a7d59', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军工程保障', '海军为顺利遂行作战任务在工程方面进行的保障。由海军各级司令部组织实施。主要包括：进行工程侦察、勘察和伪装,对海防工程设施进行抢建、抢修,设置和排除水中障碍等。', 366);
INSERT INTO `t_military_term_data` VALUES ('a8819ee3-f64e-4eb0-a159-76792425d8d1', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '战斗英雄', '军队对在作战中有重大功绩建树,堪称军人榜样的人员所授予的荣誉称号。亦指被授予这种荣誉称号的人员。', 59);
INSERT INTO `t_military_term_data` VALUES ('a889540b-9ff3-4880-8723-b645df9fd33b', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '自转着陆', '直升机因发动机全部停车,仅依靠旋翼自转产生的空气阻力进行的着陆。', 50);
INSERT INTO `t_military_term_data` VALUES ('a88a1c39-3048-44fb-a48e-f9b428362f96', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵跳弹射击', '选择低伸弹道、延期引信使射弹着地后跳飞到空中爆炸的射击、通常用以歼灭或压制暴露的、无掩盖掩体内的以及水面上的目标。', 189);
INSERT INTO `t_military_term_data` VALUES ('a89193cd-72e2-49dd-a6ba-422a722a4ba2', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '隔绝遮障', '用吸收或反射电磁波的材料构成的防雷达人工遮障。使用的材料有金属网、金属板、金属膜、防雷达伪装涂料等。', 349);
INSERT INTO `t_military_term_data` VALUES ('a8a9cb3c-4631-4137-b81a-425e23557df2', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '经始', '在现地标示建筑物和构筑物的中心线、平面形状、各部尺寸等的作业。', 86);
INSERT INTO `t_military_term_data` VALUES ('a8bae956-4fc2-45a9-86e0-26c34cc6b5ed', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤报告', '下级后勤机关向上级后勤机关或后勤机关向军政首长反映后勤工作情况的军用文书。', 69);
INSERT INTO `t_military_term_data` VALUES ('a8ce2093-0ce4-4bde-8b19-c4d8def742a2', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '经济民主', '中国人民解放军内部在经济上实行的民主。主要内容包括：官兵都有权管理和监督经济生活,通过民主选举产生的连队军人委员会协助连队首长管理伙食和农副业生产,监督经费开支,维护财经制度,防止贪污浪费、侵占士兵利益和违反政策等现象,使基层生活获得改善。', 7);
INSERT INTO `t_military_term_data` VALUES ('a8d1daf4-fd96-433d-9ec2-15b23276434a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '山脊', '若干山顶、鞍部连接的凸棱部分。一般作线状延伸,常构成河流的分水岭。山脊的棱线称山脊线。', 15);
INSERT INTO `t_military_term_data` VALUES ('a8de8a06-2fd9-471c-8421-9f139c815f19', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '直列装药', '外形长度大于最小横向尺寸5倍的爆破装药。主要用以在障碍物中开辟通路、制造障碍物和破坏作业。', 225);
INSERT INTO `t_military_term_data` VALUES ('a8e64393-fc4c-4035-b35c-cce4216ae6e9', '98df76fb-4b65-48ff-a56c-4db587327c79', '野战仓库', '能够在野战条件下快速展开。撤收的军用仓库、通常具有较强的机动能力和野外收发作业能力。', 135);
INSERT INTO `t_military_term_data` VALUES ('a90fe3d8-775b-4507-8bd4-1279081e1d6a', '878651de-adf5-4c72-9376-9c363b893ff8', '战争结局', '交战双方在战争结束时的胜负结果及其相应的军事、政治、经济局势。', 46);
INSERT INTO `t_military_term_data` VALUES ('a9200ab3-9f78-485e-8a36-78180ec2ec79', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥时效', '军队指挥系统在一定时间内发挥有效作用的程度。', 18);
INSERT INTO `t_military_term_data` VALUES ('a928dda8-344f-4eae-a483-5bf5abf2a5d0', '98df76fb-4b65-48ff-a56c-4db587327c79', '特种车', '装有专用设备,具有特种功能和用途的车辆。分为通用特种车和专用特种车。通用特种车适用于各军兵种,如消防车、救护车等。专用特种车适用于某一军兵种,如舟桥车、防化洗消车等。', 298);
INSERT INTO `t_military_term_data` VALUES ('a92a1a83-1df4-418d-aa08-7c7364e773fb', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '预备役', '亦称后备役。公民在军队外服兵役。包括军官预备役和士兵预备役。', 26);
INSERT INTO `t_military_term_data` VALUES ('a92e1482-afc8-4f1c-9c19-344cb38ca9c6', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵游动伏击', '防空兵分队预先隐蔽地配置在敌机可能飞越的地段或可能攻击的目标附近,对来袭敌机实施突然打击的对空掩护方法。通常配合固定掩护实施。', 83);
INSERT INTO `t_military_term_data` VALUES ('a9323519-4b8e-4a95-87a2-39f26420fe3d', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克最大行程', '坦克一次加足油料后,按规定条件所能行驶的最大距离。一般为300～650公里。根据最大行程,可确定坦克战时最大行动纵深和行军时的加油时机及次数。', 160);
INSERT INTO `t_military_term_data` VALUES ('a93a2f33-3ff0-40d6-8702-b21ef3899919', '916997ee-6728-4c61-9b79-d96960b1dc86', '滤毒通风装置', '安装于密闭的防毒工事、战斗车辆、帐篷、舰船和飞机中,用以供给人员清洁空气的集体防护器材。通常由过滤器、离心式风机、密闭阀门。通风管道等构成。', 181);
INSERT INTO `t_military_term_data` VALUES ('a95a1238-84ec-4035-9571-1a2ebec763e0', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '殉爆', '一个装药爆炸时，激发被介质（空气、水、上等）隔开的另一个装药爆炸的现象。两个装药之间能发生殉爆的最大距离称为殉爆距离。', 253);
INSERT INTO `t_military_term_data` VALUES ('a96a87a3-0dab-4164-8ca2-095f4a46f250', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '永备工事', '预先构筑的抗力较高、设备较完善、可长期使用的工事。分为掘开式永备工事和坑道式永备工事。', 39);
INSERT INTO `t_military_term_data` VALUES ('a96f5897-7d03-490c-b16e-4cb66a77e89e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战博弈', '为检验作战构想,借助一定的作战模型进行的对抗性模拟活动。包括对战争的对抗模拟和对战役、战斗的对抗模拟。', 170);
INSERT INTO `t_military_term_data` VALUES ('a9708b7c-3bfe-40a2-8a07-9f0b3cfa6b16', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '雷暴', '由发展旺盛的积雨云引起，伴有闪电和雷鸣的天气现象。积雨云体特大的超级单体雷暴或由多个雷暴单体组成的多单体雷暴称为强雷暴。强雷暴持续时间较长,通常伴有暴雨、大风、冰雹或龙卷等。雷暴严重危及飞机和舰艇航行,以及导弹、火箭、卫星发射的安全,干扰无线电通信和电子设备等,是对军事活动影响极大的危险天气。', 28);
INSERT INTO `t_military_term_data` VALUES ('a974c1ee-5fdd-41f0-a9cb-0dccbe8cafa8', '97a19170-bfac-42c5-9906-1acb187f0654', '跨昼夜飞行', '从昼间到夜间或从夜间到昼间的时间内实施的连续飞行。', 223);
INSERT INTO `t_military_term_data` VALUES ('a976a0bf-cef2-499d-a74d-58b296cb251f', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '云高', '云底距地面的高度。计量单位为米。', 22);
INSERT INTO `t_military_term_data` VALUES ('a97bfa44-fa18-4dca-9409-fa720d52fce4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '检查零线', '在火炮规正水平和调好零位的基础上,检查调整瞄准镜的视轴线,使其与炮身轴线平行的过程。用以排除瞄准镜视轴线与炮身轴线不平行造成的瞄准误差。', 274);
INSERT INTO `t_military_term_data` VALUES ('a981400a-cc60-4e22-b319-a043937cb1c2', '97a19170-bfac-42c5-9906-1acb187f0654', '空军作战小组', '空军派往陆军、海军军级以上单位的指挥机构,协助该单位首长对空军航空兵部队的支援行动实施指挥的小组。', 179);
INSERT INTO `t_military_term_data` VALUES ('a9a0c2aa-792c-4364-8a4b-62d469d2a865', '06a75831-13a1-4660-870a-455bb445336a', '通信事故', '通信值勤中发生的事故。分为人为通信事故和自然通信事故。人为通信事故指值勤人员失职、违反操作规程等造成严重的延误通信、损坏通信设备等；自然通信事故指天候条件、自然灾害等造成的延误通信等。', 58);
INSERT INTO `t_military_term_data` VALUES ('a9ad4e1c-dec5-4210-9a0c-23215c0518f4', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '核技术', '原子核科学技术的简称。利用原子核反应或衰变释放的能量和射线的技术。包括核燃料技术、核能技术、核动力技术、同位素技术、核辐射技术及核辐射防护技术等。军事上主要应用于研制核武器和核动力舰艇等。', 3);
INSERT INTO `t_military_term_data` VALUES ('a9b08c03-96e7-4d8a-895a-553e68043e86', '0', '电子对抗', NULL, 11);
INSERT INTO `t_military_term_data` VALUES ('a9e5aad0-6a7b-4bb1-8db5-4c2e459310a6', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '优秀士兵证章', '中国人民解放军在开展争当优秀士兵活动中发给被评为“优秀士兵”的战士的徽章。', 67);
INSERT INTO `t_military_term_data` VALUES ('a9ecb655-3df8-4893-bcd2-55e9dccdd80f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舷角', '舰首线与物标方位线之间的水平夹角。以舰首线为基准向左舷或右舷从0～180度计量。用以指示目标、舰艇机动绘算和舰载火控系统参数计算等。', 276);
INSERT INTO `t_military_term_data` VALUES ('aa097d4d-c090-4646-9135-c752c32f13c6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '单舰艇训练', '单艘舰艇进行的技术战术基础科目训练。的是使舰长和艇长学会在各种情况下操纵舰艇和组织指挥战斗,使全舰人员熟练掌握武器装备,熟悉舰艇各部门之间的协同动作,提高舰艇的整体战斗力。', 317);
INSERT INTO `t_military_term_data` VALUES ('aa0fff67-3c7f-47ae-8d4e-0a468a009f10', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆教练射击', '装甲车辆单车射击练习中,以发射枪弹代替发射炮弹的射击。坦克通常以并列机枪或内膛枪的射击代替坦克炮的射击。', 71);
INSERT INTO `t_military_term_data` VALUES ('aa1aff74-ca37-4b00-99b6-c3959c540ab9', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上航线', '①舰船由起航点至预定到达点的海上航行路线。通常标在海图上,如计划航线、推荐航线、气象航线等。②泛指沟通两地的海上交通线。通常以起迄点命名。', 255);
INSERT INTO `t_military_term_data` VALUES ('aa2b93cf-d47f-47b7-8824-afe76270ff6f', '97a19170-bfac-42c5-9906-1acb187f0654', '机载巡航导弹', '亦称空地巡航导弹。从飞行的飞机或直升机上发射,用以攻击地面或水面目标的巡航导弹。', 314);
INSERT INTO `t_military_term_data` VALUES ('aa369938-6339-47ce-883b-405a71f6fab5', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '输送', '使用运输工具把部队由一地运送到另一地的行动。按方式,分为铁路输送、公路输送、水路输送和空中输送；按规模,分为战略输送、战役输送和战术输送等。', 73);
INSERT INTO `t_military_term_data` VALUES ('aa4448da-ce90-46f1-a6b0-07d1f4ebcac8', '8a761efd-50a6-4ac8-9913-b7d745104f82', '手榴弹', '用手投掷使用的爆炸弹药。包括杀伤手榴弹、反坦克手榴弹、烟幕手榴弹、化学手榴弹等。一般使用距离不超过50米,弹重 0.15～12千克,杀伤半径小于15米。', 209);
INSERT INTO `t_military_term_data` VALUES ('aa5598f5-f8d9-4128-91b3-d50c15273c2d', '31f4a446-5b98-4873-9d53-310d97125b07', '弹头测试设备', '用以检查测试导弹弹头技术参数、性能的专用设备。', 61);
INSERT INTO `t_military_term_data` VALUES ('aa5b9083-85a3-43d3-ac5c-137ad57f7fcc', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军警戒', '保障军队行军安全的警戒。主要包括前方警戒、后方警戒和侧方警戒。有时还可派直升机在空中实施警戒。', 6);
INSERT INTO `t_military_term_data` VALUES ('aa5c7eea-cea8-4d50-8ce8-6a14c4964612', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克交战', '作战双方的坦克之间或以坦克为主的各种装甲战斗车辆之间的各种规模的交战。通常发生在反突击、反冲击和遭遇作战中。', 7);
INSERT INTO `t_military_term_data` VALUES ('aa5e4382-719b-4f7e-9020-b6528296318e', '97a19170-bfac-42c5-9906-1acb187f0654', '空中佯动', '飞机或直升机在空中制造假象以欺骗和迷惑敌人的战斗行动。主要用以隐蔽空中或地面战斗行动企图,牵制敌空中和地面兵力。', 106);
INSERT INTO `t_military_term_data` VALUES ('aa600a33-9697-4508-b059-9788240d75e8', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '实兵演习', '按照想定情况,部队或分队在现地实施的军事演习。', 117);
INSERT INTO `t_military_term_data` VALUES ('aa61bc6b-4c4e-4547-b67a-42364ae1e470', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达反侦察', '为防止敌方截获并利用己方雷达信号获取有关情报而采取的战术技术措施。', 93);
INSERT INTO `t_military_term_data` VALUES ('aa6246d9-4f6f-46bf-8dc7-62265b78ff47', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '集团军战役', '集团军进行的战役。可在上级编成内实施,也可单独实施。', 12);
INSERT INTO `t_military_term_data` VALUES ('aa652056-c4f0-4094-8d52-5c7fdebf6c00', '06a75831-13a1-4660-870a-455bb445336a', '综合业务数字网', '利用数字传输和数字交换技术提供多种业务的通信网。可为用户提供电话、电报、数据、图像及其他新的电信业务服务。自动化程度高,使用方便,通信时效高,网络资源利用率高,易于加密。', 71);
INSERT INTO `t_military_term_data` VALUES ('aa738cb3-55cf-4548-b6af-dcda31195b07', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵与航空兵协同', '防空兵与航空兵为共同完成防空作战任务而进行的协调与配合。包括高炮部队与航空兵（炮空）协同和地空导弹部队与航空兵（弹空）协同。一般按空域、高度、目标、时间、方向等进行协同。', 100);
INSERT INTO `t_military_term_data` VALUES ('aa7add01-fbd8-4db5-9e4b-8eb64acbea79', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮长点射', '小口径高炮每次射击时每管发射4～6发炮弹的发射方式。通常用于对空中高速目标射击。', 184);
INSERT INTO `t_military_term_data` VALUES ('aa7dc633-4434-46c6-9956-9a1bc59da314', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '争议地区', '国家间对领土主权及海洋权益有争执的地区。包括边境争议地区和非边境争议地区。', 88);
INSERT INTO `t_military_term_data` VALUES ('aa8cf96e-6c37-4cb4-81fc-189c51bccb3b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '水网稻田地', '江河、沟渠、湖泊、池塘。水稻田交织分布的地区。地势平坦开阔,但由于受水网分割,路少巳狭窄,作战协同较困难,车辆越野通行受限制,不易构筑坚固工事。', 125);
INSERT INTO `t_military_term_data` VALUES ('aa955159-d1aa-41a2-a3a8-ae9cc4695d82', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '第三梯队', '作战部署或战斗队形中配置在第梯队后面的梯队。主要用以增强突击力量或用以反突击,发展胜利,达成最后作战目标。', 317);
INSERT INTO `t_military_term_data` VALUES ('aa9d5f84-2a24-44ff-a575-8c2091cacfec', '97a19170-bfac-42c5-9906-1acb187f0654', '水陆两用飞机', '亦称两栖飞机。既能在陆飞机场起降,又能在水面上起降的飞机。主要用于水面上空巡逻、空中反潜和空中救援等。', 272);
INSERT INTO `t_military_term_data` VALUES ('aaa1dbbf-670f-4478-9571-cdc694e3eb5d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '非军事区', '根据一定协议划定的,禁止敌对双方建立、保留或使用军事设施以及驻扎军队、进行军事活动的特定区域。一般用作军事上的缓冲区,以阻隔双方武装力量的直接接触,防止敌对行为的发生。', 81);
INSERT INTO `t_military_term_data` VALUES ('aaa50ffa-e72a-46fa-a3bb-0cedc6f4f4d1', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇拖带', '舰艇拖曳其他舰船或非自航水上浮动物体的航行。拖带方式有尾拖,舷拖（旁拖）和顶推。主要用以拖带战伤受损舰船、失去动力或操纵能力的舰船,还可用于拖带小型舰艇以及靶标、驳船、浮筒等无动力浮体。', 344);
INSERT INTO `t_military_term_data` VALUES ('aaab7b67-f6ca-4de9-b203-b85f51e90f47', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮弹装药批号初速偏差量', '某批号炮弹装药的初速对标准初速的偏差量、一般可利用测速仪器测定或用实弹射击的方法确定。通常以偏差量占标准初速的百分数表示。', 243);
INSERT INTO `t_military_term_data` VALUES ('aaad2fdb-d711-4739-aa95-9fec99d1d2f1', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹地面设备', '放置在地面和专用车辆上的保障导弹发射和控制导弹飞行的各种设备的统称。包括测试发射设备、起重运输设备、瞄准设备、加注设备、弹头装配检验设备、指挥监控设备、辅助设备等。', 55);
INSERT INTO `t_military_term_data` VALUES ('aaadd7a9-0c91-4b20-9778-63856b273196', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '太空', '亦称外层空间。地球大气层以外的宇宙空间。其下界一般认为距地面100千米。', 199);
INSERT INTO `t_military_term_data` VALUES ('aaafa03c-a984-4db5-a63c-74187c68afbc', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹弹道最大高度', '导弹弹道最高点至其投影点所在大地水平面的距离。其大小与导弹飞行关机点的坐标及速度和俯仰角有关。', 143);
INSERT INTO `t_military_term_data` VALUES ('aacfaf63-eeab-4b59-8586-b98ec61a7876', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程机械场勤务', '为维护军用工程机械场的正常工作秩序和场区安全而进行的各项工作的统称。包括建立和执行机械场规则、保养日制度和消防制度,组织机械场的安全警卫等。', 379);
INSERT INTO `t_military_term_data` VALUES ('aae29233-14ca-484e-9782-b26205a08a91', 'd7132c58-5df3-4b97-919f-58740148b9ca', '炮瞄雷达', '称人控雷达、跟踪雷达。用以搜索、发现和自动跟踪空中目标,连续测定目标坐标,以保障高射炮射击的雷达。', 52);
INSERT INTO `t_military_term_data` VALUES ('aaf2f6f9-4b5b-49ec-b7d0-c4ca343da107', '97a19170-bfac-42c5-9906-1acb187f0654', '空军战略', '筹划和指导空军运用与建设的方略。从属于军事战略。', 30);
INSERT INTO `t_military_term_data` VALUES ('aaf4a659-1578-47f2-84ed-e731b9b974d1', '916997ee-6728-4c61-9b79-d96960b1dc86', '核观测', '为获取核爆炸的时间、地点、威力和方式等信息而组织的观测。分为野战核观测和要地核观测。为估算核爆炸瞬时杀伤破坏范围、放射性沾染情况提供依据。', 41);
INSERT INTO `t_military_term_data` VALUES ('aafe1c61-63fb-445d-89f5-10461042a782', 'd7132c58-5df3-4b97-919f-58740148b9ca', '空情报知通信', '传递空中情况的通信联络。包括远方空情报知通信、近方空情报知通信和对空观察哨报知通信。', 127);
INSERT INTO `t_military_term_data` VALUES ('ab010636-17fd-4d98-a8b7-8f9f2d1d7010', '97a19170-bfac-42c5-9906-1acb187f0654', '紧急起飞', '飞机在紧急情况下采取快速出动措施的起飞。主要措施是：紧急启动发动机,从停机位置直接滑出,开加力起飞等。', 206);
INSERT INTO `t_military_term_data` VALUES ('ab0137a3-da69-4aff-8dce-d175f3b8e187', '06a75831-13a1-4660-870a-455bb445336a', '多路通信', '在一条信道上利用多路复用通信设备同时传输多个独立信息的通信方式。多路复用的通信设备有频分制的载波通信设备和时分、码分制的多路通信设备。', 97);
INSERT INTO `t_military_term_data` VALUES ('ab05754c-2160-4db5-a227-38b804674dae', '97a19170-bfac-42c5-9906-1acb187f0654', '空阵地面作战地区', '空降部队着陆后进行地面作战的地区。', 164);
INSERT INTO `t_military_term_data` VALUES ('ab05d126-1a06-43d7-a883-919daee96b8d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军合同战术', '海军两个以上兵种进行合同战斗的方法。', 49);
INSERT INTO `t_military_term_data` VALUES ('ab09c1d4-1f13-4477-ba55-31de4289d63b', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '固定哨', '警戒位置相对固定的哨兵。', 29);
INSERT INTO `t_military_term_data` VALUES ('ab0ab5e6-a353-42a0-aaeb-bcfc9574cfcd', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军事题材艺术', '以反映武装斗争和军人生活为主要内容的各种艺术形式的统称。包括军事题材的戏剧、电影、电视剧、美术、音乐、舞蹈、曲艺等。', 112);
INSERT INTO `t_military_term_data` VALUES ('ab0d20c1-054a-4063-b1a3-1c189adc7926', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '警备区', '在重要城市设立的担负警卫、守备任务的军队一级组织。中国人民解放军的警备区一般（师级）隶属于省军区,少数（军级）隶属于军区。同时是所在市的中国共产党委员会的军事工作部门和政府的兵役工作机构,受省军区或军区和所在市党委、政府的双重领导。设有领导机关。辖有区、县人民武装部和一定数量的警备、守备部队。主要负责所在城市的警卫、守备任务和民兵、预备役、兵役、动员工作,维护军容风纪,施行军车交通安全检查,协助地方维持社会治安等。', 27);
INSERT INTO `t_military_term_data` VALUES ('ab12f925-d9a5-4db5-abaa-e6e9e7e336fd', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '留置侦察', '部队撤退或转移时留置在当地的分队和人员进行的侦察。主要查明窗置地区的敌军情况,并监视其动向。', 39);
INSERT INTO `t_military_term_data` VALUES ('ab1aa72d-4b94-4871-8765-00608f2b0f96', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮短停射击', '小口径高炮或高射机枪分队在行进中,作短促停顿（不放列）对空中目标进行的射击。', 178);
INSERT INTO `t_military_term_data` VALUES ('ab23ab74-96e3-4a70-aafe-5f504170c4b7', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高射炮兵射击', '简称高炮射击。高射炮兵使用高射炮进行的射击。包括射击准备和射击实施。分为对飞机射击、对直升机射击、对巡航导弹射击、对伞降目标射击。对地面和水面目标射击等。', 138);
INSERT INTO `t_military_term_data` VALUES ('ab31cd58-c5cd-4984-afed-b47134187205', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '发射程序', '发射运载火箭和航天器的工作流程。通常从运载火箭和航天器进入发射区开始列入发射程序。主要包括：发射设备准备,起竖与安装,垂直度校准和定向,温度调节,检查与测试,安装火工品,加注推进剂和充灌压缩气体,临射检查,瞄准和发射等。', 254);
INSERT INTO `t_military_term_data` VALUES ('ab3bfa90-2325-455d-bbb8-fb21d9f94d52', '97a19170-bfac-42c5-9906-1acb187f0654', '航路捷径', '由地空导弹或高射炮发射阵地的中心到空中目标航迹的投影线或投影线切线的垂直距离。是确定能否进行发射或射击的重要参数。', 138);
INSERT INTO `t_military_term_data` VALUES ('ab3edd47-775d-43eb-8ba3-accf31196bca', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '障碍区', '构筑和设置有大量障碍物的区域。', 97);
INSERT INTO `t_military_term_data` VALUES ('ab60c495-4042-462c-ad0a-bbeda7856a08', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '服役', '①公民依法服兵役。②马匹、武器装备等列人现役部队或预备役部队编制以供使用。', 144);
INSERT INTO `t_military_term_data` VALUES ('ab6885d4-4958-42a2-bd37-639ba341db48', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '地文航海', '利用陆上物标测定舰位和引导舰船航行的航海技术。主要内容包括：航海基础知识,航线设计,航迹推算,陆标定位以及航行方法等。', 253);
INSERT INTO `t_military_term_data` VALUES ('ab83c609-51df-4cbf-9899-82bfe93a3281', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '气压高程测量', '根据大气压力随地面高度而变化的原理,利用气压计测定地面点高程的测量方法。其精度远较水准测量和三角高程测量低,主要用于水准测量和三角高程测量难以到达的地区。', 181);
INSERT INTO `t_military_term_data` VALUES ('abac99ec-330b-4b19-8e85-8f889f39052e', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '装（卸）载指挥所', '临时设立的统一组织实施装（卸）载工作的指挥机构。通常由被输送单付、输送单位的负责人以及军运代表联合组成。', 91);
INSERT INTO `t_military_term_data` VALUES ('abeada70-b79d-49df-9278-196d2cb2a596', '98df76fb-4b65-48ff-a56c-4db587327c79', '供应计算单位', '军队内担负后勤保障任务的营和营级以下的后勤建制单位、如汽车营、管线队、修理所、勤务连、炊事班等。', 130);
INSERT INTO `t_military_term_data` VALUES ('abf9830c-7b8d-4d02-8dbd-6223bdb4be5e', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器机动性', '轻武器的火力机动性、携行机动性和装载机动性的统称。火力机动性指武器的射击操作、转移火力、变换射击方式的快慢程度；携行机动性指武器的提携、握持、肩背、扛载、搬运的灵便程度；装载机动性指武器适应马驮、车载、船载和空运的程度。', 222);
INSERT INTO `t_military_term_data` VALUES ('abff1efe-2ffc-4ab1-b6a9-3afd89c1e62e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '敌我态势图', '标绘有敌方与己方主要兵力兵器部署,行动企图等情况的图。包括战前敌我态势图和作战过程中某一时刻或阶段的敌我态势图主要供指挥员了解情况。定下决心、指挥作战使用。', 145);
INSERT INTO `t_military_term_data` VALUES ('ac10f307-7b71-448c-824f-d1f598c2c9d6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上遭遇战', '敌对双方海军兵力在海上相遇而发生的交战。分为预期的海上遭遇战和不预期的海上遭遇战。', 24);
INSERT INTO `t_military_term_data` VALUES ('ac15e9b4-54da-41b0-904f-e0fb1962498e', '06a75831-13a1-4660-870a-455bb445336a', '信道', '传输信息的通道。由传输媒介构成。传送单路信息的称单路信道,若干个单路信道可组成多路信道。', 91);
INSERT INTO `t_military_term_data` VALUES ('ac20209a-f026-4baf-8732-3a362856cdc8', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '人文地理环境', '简称人文环境。人类在自然地理环境的基础上,通过政治、经济、社会文化等活动形成的人文事物与人文现象的地域组合。通常分为政治地理环境、经济地理环境、社会文化地理环境等。', 98);
INSERT INTO `t_military_term_data` VALUES ('ac30f3bd-f73e-4cef-975d-9d7cd47b2165', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军队形', '军队按行军部署形成的纵长行进队形。可根据情况成一路先后行进或数路并进的队形。', 56);
INSERT INTO `t_military_term_data` VALUES ('ac3752ea-e19d-42f7-8162-985ca65d2e47', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '垂直遮障', '遮障面与地面垂直或倾斜的,设置在目标侧边或道路上空的人工遮障。分为栅栏垂直遮障和道路上空垂直遮障。', 346);
INSERT INTO `t_military_term_data` VALUES ('ac3affc2-ed6a-4214-b575-a7f354076411', '916997ee-6728-4c61-9b79-d96960b1dc86', '安全浓度', '亦称允许浓度。不引起染毒人员产生可观察到的毒害效应的最大染毒浓度。', 128);
INSERT INTO `t_military_term_data` VALUES ('ac3d696f-8354-4d70-8be9-7d0b43459457', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '海洋开发技术', '开发利用海洋资源所涉及的各种技术的统称。主要包括：海洋调查和海洋预报技术,海底石油、天然气和其他矿藏的开发技术,海水资源的提取技术,海洋能源的开发技术,海洋空间的利用技术,渔业技术,海洋运输技术等。', 16);
INSERT INTO `t_military_term_data` VALUES ('ac3f4c1c-212a-4f8b-9ca5-7f14a3d99e1b', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克伪装器材', '坦克伪装用的器具和专用材料的统称。是坦克防护系统的组成部分。包括坦克烟幕装置、伪装材料和伪装涂层等。主要用以隐蔽坦克或减弱坦克暴露征状。', 138);
INSERT INTO `t_military_term_data` VALUES ('ac401e93-c2da-4ce0-9353-5485a41a9381', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '遮断', '以空中或地面火力，对敌战略或战役、战术纵深一定区域实施覆盖与隔断性打击的作战行动。目的是阻滞和切断敌方前后联系及人员、物资的机动。', 357);
INSERT INTO `t_military_term_data` VALUES ('ac480357-c781-4239-ac8f-e54473db470e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '一专多能', '在精通本职专业的基础上掌握与本职有关的其他专业技能。目的是做到一兵多用。', 162);
INSERT INTO `t_military_term_data` VALUES ('ac4c334e-5b0c-465a-832a-8d0432e9383a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '发射场测试', '在航天器发射场对航天器各分系统、分系统之间的接口以及航天器整体的电气指标和性能进行的检查和测量。包括技术阵地测试和发射阵地测试。', 251);
INSERT INTO `t_military_term_data` VALUES ('ac58c091-488d-4bad-9207-dd26dcedc43a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '星下点轨迹', '人造地球卫星运动和地球自转使星下点在地球表面移动所形成的轨迹。某一时刻人造卫星和地心连线与地面的交点,称为该时刻的星下点（用地理经、纬度表示）。将星下点轨迹标在地图上,便是星下点轨迹留。通常用大屏幕实时显示,以提供人造卫星运行情况。', 235);
INSERT INTO `t_military_term_data` VALUES ('ac69b594-b702-4d9a-93f7-944698c20c5e', 'd7132c58-5df3-4b97-919f-58740148b9ca', '对空掩护走廊', '在部队开进通道上空形成的带状防空火网。通常在敌航空兵威胁较大的路段,以防空兵连或排、班为单位，按一定间隔沿道路侧方配置,形成衔接的防空火力地带。', 82);
INSERT INTO `t_military_term_data` VALUES ('ac782c4f-74e3-4900-82ac-e43ddfa989e4', '97a19170-bfac-42c5-9906-1acb187f0654', '空军目标引导组', '空军航空兵队协同陆军、海军部队作战时,向陆军地面部队或海军舰艇部队派出的对空引导小组。通常由空军轰炸、歼击轰炸、强击航空兵部队派出的人员组成,随地面部队或舰艇部队行动。负责反映陆军、海军部队对空军航空兵部队支援的要求,并引导己方飞机及时发现和突击地面、水面目标。', 180);
INSERT INTO `t_military_term_data` VALUES ('ac8169b1-fba7-4ec5-a0e5-a59f12a7fd83', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机升限', '飞机依靠本身动力所能达到的最大飞行高度。分为静升限和动升限。稳定上升所能达到的最大高度为静升限；利用动能以跃升的方法所能达到的最大飞行高度为动升限。', 298);
INSERT INTO `t_military_term_data` VALUES ('ac837ea9-32ff-451b-8d4e-e2a279ee2f78', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵气象车', '遂行炮兵气象保障任务的专用车辆。在能见度良好的条件下,能完成炮兵气象要素的探测。与测风雷达结合,可组成全天候的炮兵气象探测系统,有的还可作为移动式气象站使用。', 291);
INSERT INTO `t_military_term_data` VALUES ('ac87f5ed-da90-4a46-9a08-f36bc0c93e73', 'f0140091-c11a-48c9-8836-8aa94439dac0', '对空降着陆之敌的进攻战斗', '对空降着陆的正在集结之敌或刚展开进攻之敌或仓促转入防御之敌实施的进攻战斗。包括对机降着陆之敌的进攻战斗和对伞降着陆之敌的进攻战斗。', 129);
INSERT INTO `t_military_term_data` VALUES ('ac8d4576-5265-4281-b896-8500e3f6acb9', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队干部工作', '中国人民解放车领导和管理军官、文职干部的工作。是党和国家组织人事工作的组成部分,中国人民解放军政治工作的重要内容。', 78);
INSERT INTO `t_military_term_data` VALUES ('ac975771-3cf7-435c-a9ac-28d611c7936b', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤编组', '为执行后勤保障任务,对后勤各种力量进行；临时性的组合。是后勤部署的主要内容之一。', 58);
INSERT INTO `t_military_term_data` VALUES ('acb25ddf-6d1c-4518-b8a6-308034ae6aba', '878651de-adf5-4c72-9376-9c363b893ff8', '战争计划', '国家或政治集团对战争的准备与实施所作的预先安排。', 41);
INSERT INTO `t_military_term_data` VALUES ('acc2bab5-ff01-43d2-b350-2b52f4019606', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机持续打击能力', '使用多批武装直升机在一定时间内对敌目标进行轮番攻占的能力。本要取决于合理的进行兵力编组,使攻击、待命、补给的兵力相互衔接。', 16);
INSERT INTO `t_military_term_data` VALUES ('ace19f9b-f986-43fc-8e70-fcc15f88cb82', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地图储备', '根据战备和军事训练等需要在图库中储存备用地图。', 293);
INSERT INTO `t_military_term_data` VALUES ('ace4ef43-8e0c-4736-b0e3-5e31f4ec2aee', 'd7132c58-5df3-4b97-919f-58740148b9ca', '按固定高度射击', '高炮对水平飞行目标射击时,在指挥仪上装定固定的高度求取射击诸元而进行的射击。目标方位角、高低角由高炮测距机或炮瞄雷达测出,目标高度通过计算仪计算或由指挥员指定。', 174);
INSERT INTO `t_military_term_data` VALUES ('ace6e44e-2352-468e-acaf-90cb0782a5f1', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '编组', '按照一定的要求将部队、分队或人员进行临时性的组合。', 319);
INSERT INTO `t_military_term_data` VALUES ('acf7d69c-5bb2-4d86-a33d-f481cf3d39a1', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上航道', '舰船在海上安全航行的通道。具有一定的深度和宽度,障碍物少,一般设有航标等导航设备。通常分为主航道、副航道和进出港航道。', 254);
INSERT INTO `t_military_term_data` VALUES ('acf91e4c-954e-452d-b752-00e50ad1d70b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '蛇腹形钢带网', '用刺钢带和钢圈制成的圆筒形制式铁丝障碍物。每盘展开后长约10米,直径70～90厘米。通常成1～3列或品字形设置。主要用以防步兵,多列设置时也可迟滞履带式车辆的行动。', 126);
INSERT INTO `t_military_term_data` VALUES ('acfd134e-5674-46f5-b940-de651afb29c8', 'f0140091-c11a-48c9-8836-8aa94439dac0', '封闭', '以兵力、火力和障碍物等严密封锁突破口、间隙地或通道等的战斗行动。', 71);
INSERT INTO `t_military_term_data` VALUES ('ad08e3b6-5677-43d1-9f1e-58b37a901c74', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '常备军', '国家平时经常保持的现役正规军队。是武装力量的主体。其编成规模依据国家情况和战略需要确定。', 15);
INSERT INTO `t_military_term_data` VALUES ('ad105921-4c24-40d1-88f4-8ec9afa56c4f', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '潮流', '海水受月球和太阳等天体引潮力作用产生的水平方向的周期性流动现象。潮流的周期通常与潮汐相一致,分为半日潮流、全日潮流和混合潮流。其流动形式,一般在广阔海区表现为旋转潮流,在海峡、水道、狭窄港湾表现为往复潮流。', 136);
INSERT INTO `t_military_term_data` VALUES ('ad13f81d-fd02-45ce-ac24-78a723ff3e60', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '坐标方位角', '从某点的坐标纵线北向起,顺时针方向至目标方向线间的水平夹角。易于从地形图上量取。炮兵使用较多。', 218);
INSERT INTO `t_military_term_data` VALUES ('ad1a223f-69de-4a17-92c1-87082b32c34b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '人工伪装', '亦称技术伪装。用伪装器材、工程作业和其他技术手段实施的伪装。包括工程伪装和利用其他技术手段进行的伪装。', 333);
INSERT INTO `t_military_term_data` VALUES ('ad25526f-bc87-4a66-b723-30bec7037bb0', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '登陆方向', '登陆兵在敌海岸或岛屿实施突击上陆的方向。分为主要登陆方向、辅助登陆方向和佯动登陆方向。', 66);
INSERT INTO `t_military_term_data` VALUES ('ad4185c6-1596-4e9f-b787-31a6c8929aff', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '计算机网络', '利用通信设备和线路把多个独立的计算机互连起来，构成硬件、软件和数据等资源共享的网络系统。军事上有广泛用途。', 63);
INSERT INTO `t_military_term_data` VALUES ('ad4801a6-7a70-4bec-9769-d96acad0a425', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '世界时', '亦称格林尼治平时。由格林尼治平子夜起算的平太阳时。以地球自转为基础的时间计量系统。由测定恒星时推算得到。', 209);
INSERT INTO `t_military_term_data` VALUES ('ad4e203c-9759-46d1-b44e-1a67b556c02b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '保障机械', '用以配合野战工程机械和军用建筑机械作业以及进行工程装备维修的军用工程机械、包括移动式电站、工程起重机和修理工程车等。', 375);
INSERT INTO `t_military_term_data` VALUES ('ad54b19b-0404-4aca-905c-237f836cc7a0', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '干扰走廊', '在空中大量投放箔条等无源干扰物,干扰敌对空情报雷达形成的掩护攻击机群突防作战的通道。', 84);
INSERT INTO `t_military_term_data` VALUES ('ad59c6d7-a682-4f5b-8e40-4e40538d5f0d', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆换季', '为适应季节变化对装甲车辆采取的维护措施。通常在每年秋冬、春夏之交进行,以更换季节性燃料、润滑油脂和冷却液为主,并对车辆的技术状况进行全面普查和排除故障。必要时可对封存车辆启封和重新封存。', 223);
INSERT INTO `t_military_term_data` VALUES ('ad5b03ad-8091-4a95-aeef-e12a81f45ec7', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤配置', '作战时选定后勤机关、部队和分队展开工作的具体位置。也指后勤机关、部队和分队已经形成的配置状况。', 48);
INSERT INTO `t_military_term_data` VALUES ('ad67ccbf-13db-4d09-a8bd-a989decb6038', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军指挥', '海军指挥员及其指挥机关对所属部队的作战和其他行动实施的组织领导活动。', 115);
INSERT INTO `t_military_term_data` VALUES ('ad73cd0f-58b3-4c23-ae92-4c040d5f14d7', '878651de-adf5-4c72-9376-9c363b893ff8', '战争潜力', '通过动员和开发才可用于战争的潜在力量。一般指能够动员起来用于战争的人力、物力、财力。主要取决于国家的政治、经济、科技、文化以及人口、资源、自然条件等。', 39);
INSERT INTO `t_military_term_data` VALUES ('ad7cbd40-026a-422d-a583-40cbe2d38b25', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '结构物爆破', '为破坏建筑物的结构而实施的爆破。包括对组成结构物的构件（如梁、柱、板、桁等）或直接由材料构成的结构物（如墙壁、桥墩、路基、堤坝、工事等）进行的爆破。', 237);
INSERT INTO `t_military_term_data` VALUES ('ad80b35f-5520-40e7-936d-cee265e2e8e8', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战要报', '作战过程中或经过一个作战阶段后向上级反映简要情况的作战报告。', 135);
INSERT INTO `t_military_term_data` VALUES ('ad85c084-f07b-4a93-ba56-cc44d14b6791', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '火力计划', '组织和使用火力的计划、通常分为综合火力计划和单项火力计划。是作战计划的组成部分。', 91);
INSERT INTO `t_military_term_data` VALUES ('ad8c5625-d05b-4550-a58e-98671269ee1b', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '云', '悬浮在空中,不接触地面的水滴、冰晶或两者混合的可见聚合体。云的基本特征以云量、云状、云高等表示。根据云的外形特证和云底高度,通常将云分为3族、10属、29类。', 19);
INSERT INTO `t_military_term_data` VALUES ('ad903d9b-d0fc-4853-9875-eb0e323c15a3', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地形图分幅编号', '地形图图幅的划分和编号规定。通常按照国际统一规定的1:100万比例尺世界地图的分幅和编号原则,依次进行基本比例尺地形图的升幅和编号。', 277);
INSERT INTO `t_military_term_data` VALUES ('ad91085f-377e-4df5-800b-8cb684884428', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '蚕食', '小块、逐步地侵占对方的领土或控制区的行为。', 358);
INSERT INTO `t_military_term_data` VALUES ('ad93a992-088b-4ae6-acec-0f2e4cee4d09', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮密度', '作战正面平均每公里使用火炮的数量。用以表示炮兵力量的强弱程度和计算敌我炮兵兵力的对比。', 101);
INSERT INTO `t_military_term_data` VALUES ('ada0c062-7f7e-490e-9f6d-829e02e15e17', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '海战场', '敌对双方进行海战活动的空间。主要指一定的海域及其相关的空域,有的还包括濒海陆地、岛屿等。', 166);
INSERT INTO `t_military_term_data` VALUES ('ada10e20-7f51-4e50-893e-b694cc1436a6', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '海防', '国家为保卫主权、领土完整和安全,维护海洋权益,防备外敌入侵,在沿海地区和海疆进行的防卫和管理活动的统称。', 102);
INSERT INTO `t_military_term_data` VALUES ('ada37e9a-9b86-4c90-8c0c-345e4b7d4ecf', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '试教', '授课人员按授课程序和要求进行的试验性的教学活动。用以检查授课人员的准备情况和授课能力。', 147);
INSERT INTO `t_military_term_data` VALUES ('adb2445e-eb81-4b7e-a7d0-12dabc2e61bc', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行记录器', '亦称飞行数据记录器。自动记录飞行数据的机载设备。主要有事故记录器（亦称黑匣子）和维修记录器两类。事故记录器用以记录事故发生前一定时间内的飞行状态,以及飞机和飞行人员的有关信息。维修记录器用以记录机上设备的工作状况和有关数据。还有专门用于飞行试验的飞行记录器。', 337);
INSERT INTO `t_military_term_data` VALUES ('add09f08-01b8-42d8-99f8-1db81015b427', 'f0140091-c11a-48c9-8836-8aa94439dac0', '珊瑚岛礁战斗', '在珊瑚岛礁及其附近水域进行的战斗。受气象、水文影响大,机动受限,保障困难。', 10);
INSERT INTO `t_military_term_data` VALUES ('add1e396-b766-44ae-bae3-dda10f75ccf4', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上封锁', '由海军兵力单独或在其他军兵种协同下,控制特定海区或海上通道,隔绝敌方海岸、岛屿同外界联系的作战行动。按封锁范围,分为全面封锁和局部封锁；按作战手段,分为水雷封锁、兵力封锁以及水雷和兵力相结合的综合封锁。', 35);
INSERT INTO `t_military_term_data` VALUES ('add2743e-2767-4e05-b30f-6acfdc2121f1', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵射击指挥练习', '防空兵部队、分队指挥员为巩固和提高射击指挥技能而进行的训练。可在室内利用各种模拟器材进行,也可在室外带防空兵分队共同实施。', 134);
INSERT INTO `t_military_term_data` VALUES ('add58ba6-cec1-4f23-b17f-56f46f3afc72', '8a761efd-50a6-4ac8-9913-b7d745104f82', '多弹头枪弹', '一个弹壳装有2～3个弹丸的枪弹。可提高命中率和杀伤概率。射程较近,适合近战使用。', 205);
INSERT INTO `t_military_term_data` VALUES ('adddaaed-c554-4725-a8ab-3fc49e34c2ff', '8a761efd-50a6-4ac8-9913-b7d745104f82', '落速', '射弹在落点的速度。', 48);
INSERT INTO `t_military_term_data` VALUES ('ade1ed0f-f119-4aac-a965-13aa6c1656b2', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '到课率', '实际到课人数与应到课人数的比值。通常用百分比表示。', 45);
INSERT INTO `t_military_term_data` VALUES ('adefe3ce-230f-4d22-b3a9-bb38d568b30b', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机协同防御', '武装直升机协调配合地面部队对敌进行的防御。主要任务是突击进攻之敌装甲战斗车辆及直升机等。', 61);
INSERT INTO `t_military_term_data` VALUES ('adf24fed-1377-4113-aba2-238db67438e7', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化作业箱', '估算核、化学袭击的杀伤破坏情况的作业工具。箱内装有袖珍计算机、录音机等。主要以人机对话方式，计算核爆炸的威力、爆高、比高和爆心投影点,以及瞬时杀伤破坏效应和地面放射性沾染等参数；估算化学袭击的危害纵深、染毒地域毒剂云团的变化和毒剂滞留时间等。', 152);
INSERT INTO `t_military_term_data` VALUES ('adf6a5bc-73e9-4d58-bff9-a4fdaa6b3e83', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '军种战役', '由一个军种单独组织实施的合同战役。如陆军战役、海军战役、空军战役、第二炮兵战役等。', 8);
INSERT INTO `t_military_term_data` VALUES ('ae0f9909-35e8-42b0-b9a5-2ed76528eb92', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹突防', '导弹突破对方反导防御系统的拦截,进入预定的攻击目标区。', 145);
INSERT INTO `t_military_term_data` VALUES ('ae13f89c-104d-469b-847c-92ecd2e39703', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '特殊条件下作战', '在特殊地形和气候的区域内进行的作战。如在山地、荒漠草原地、水网稻田地、热带山岳丛林地、高寒地等区域的作战。', 186);
INSERT INTO `t_military_term_data` VALUES ('ae1ed28f-7b9a-4551-acb1-cd20f583907d', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '洪峰', '①洪水自起涨至峰顶到落尽的整个过程。②一次洪水过程中,达到最高水位或最大流量时的洪水。洪峰的大小以洪峰流量或洪峰水位表示。', 117);
INSERT INTO `t_military_term_data` VALUES ('ae3c84e4-f4bd-41e6-9e24-3e69268682a5', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '预演', '正式演习前按演习方案进行的演练。', 119);
INSERT INTO `t_military_term_data` VALUES ('ae56e547-0dce-41b1-9a4b-23bee8a3e6d9', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事地形学', '军事上研究和利用地形的一门学科。主要研究：各类地形对作战行动的影响,军用地图和遥感图像的判读和使用,战场简易测量和调制要图,制作地形模型,以及判定方位和指示目标等。', 115);
INSERT INTO `t_military_term_data` VALUES ('ae73be8f-984f-4e57-894d-f52d6116d424', '98df76fb-4b65-48ff-a56c-4db587327c79', '常服', '军人在平时和一般礼仪场合穿着的军服。中国人民解放军的常服分为夏常服和冬常服两类。', 154);
INSERT INTO `t_military_term_data` VALUES ('ae8201b3-f31c-48fd-be27-8629a0f87868', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '地地战役战术导弹武器系统', '地地战役战术导弹及其配套技术装备的统称。一般由导弹、导弹发射装置和瞄准设备及其他配套设备组成。是陆军的重要远战兵器。主要用以攻击敌方纵深内重要目标,如敌地地战役战术导弹发射阵地、机场、战役指挥机关和通信枢纽等。', 31);
INSERT INTO `t_military_term_data` VALUES ('ae8cc30c-eb93-4229-95e7-9910e1bb1730', '8a761efd-50a6-4ac8-9913-b7d745104f82', '炸壳', '射击武器击发后,弹丸飞出膛口,弹壳炸裂的射击故障。', 128);
INSERT INTO `t_military_term_data` VALUES ('ae947c10-18e0-4123-bda4-17fb4a4c7f2e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '预制构件', '按照建筑物或构筑物的结构规格预先制作的构件。如工事构件、桥梁构件等。', 36);
INSERT INTO `t_military_term_data` VALUES ('ae97672f-5ee7-4dea-96b3-411652618c9b', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '人工智能', '亦称机器智能。计算机系统所具有的能在一定程度上模拟人类大脑的思维、推理、抽象等功能的性能。', 67);
INSERT INTO `t_military_term_data` VALUES ('ae98906f-8cff-4be6-9db4-2bb59ee831ff', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '通信对抗侦察', '为获取通信对抗所需的情报而进行的电子对抗侦察。主要是通过搜索、截获、分析和识别敌方无线电信号,查明敌无线电通信设备的频率、频谱结构、调制方式、功率电平、工作体制、配置位置以及通信规律、通信网络的性质和组成等。', 19);
INSERT INTO `t_military_term_data` VALUES ('aea093db-b019-4f14-8f02-a20038b22f62', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '轨道周期', '航天器在轨道上绕地球运行一周所用的时间。周期的长短取决于运行轨道的半长轴。半长轴相同的轨道,周期也相同。', 233);
INSERT INTO `t_military_term_data` VALUES ('aeaab500-d426-4588-b310-f779d8364d2e', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '突破地段', '部队在进攻正面上从敌防御部署中打开缺口的地段。其宽度为突破口的宽度。', 91);
INSERT INTO `t_military_term_data` VALUES ('aeb3a821-758c-4637-98e3-82b20a9497de', '97a19170-bfac-42c5-9906-1acb187f0654', '靶机', '用作空中靶标的无人驾驶飞机。主要用于地空导弹、高炮或歼击机等的射击训练以及检验武器性能等。', 274);
INSERT INTO `t_military_term_data` VALUES ('aec167e1-4b84-45eb-9b76-173c6c5af653', '97a19170-bfac-42c5-9906-1acb187f0654', '空中截获', '机载雷达或空空导弹导引头接收到空中目标的信号后,转入自动跟踪目标信号的工作状态。雷达截获目标时,在显示器上出现目标模拟图象,并显示目标与飞机的相对位置和距离。空空导弹导引头截获目标时,机上有关设备发出音响等信号。', 77);
INSERT INTO `t_military_term_data` VALUES ('aec175e5-8897-432f-bf80-9331fba88ac9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '突然性', '作战行动所具有的出敌不意的性质。', 275);
INSERT INTO `t_military_term_data` VALUES ('aec30faf-2a76-407f-bb5a-efbce5d7a0d4', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵经训率', '民兵组织的成员在规定的应训年龄段内,参训并经考核合格的人数与总人数的比值。通常用百分比表示。', 138);
INSERT INTO `t_military_term_data` VALUES ('aecb2c87-98d1-4638-af1c-624147a55f43', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '军事管理区', '由军队保护和管理的营区、军事设施区域及其他因特殊需要而划定的区域的统称。', 68);
INSERT INTO `t_military_term_data` VALUES ('aed93a2a-a553-417e-936f-cb89e2ec8b1c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇动力装置', '舰艇上用以提供推进动力和为其他设备提供能源的机械、设备、管路系统的统称。包括主动力装置及辅助装置和辅助机械等。', 166);
INSERT INTO `t_military_term_data` VALUES ('aef00de3-4599-4274-a2f0-6f6fcef00833', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '红外线侦察', '使用红外线器材进行的侦察。分为主动式红外线侦察和被动式红外线侦察。主要器材有红外线观察仪、红外线照相机、热像仪、热定向仪、红外线富达、红外线电视和红外线扫描仪等。', 52);
INSERT INTO `t_military_term_data` VALUES ('aef3db25-2c53-4746-8f9f-ea1ff2637b2a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹姿态控制系统', '用以控制和稳定导弹的飞行姿态及改变或保持导弹航向的装置。', 59);
INSERT INTO `t_military_term_data` VALUES ('aeff35b0-62da-4b41-8744-7c14177ba9e5', '06a75831-13a1-4660-870a-455bb445336a', '航空兵与防空兵协同通信', '为保障航空兵与防空兵的快同作战而建立的通信联络。主要方法有；组织协同无线电网；通过航空兵派往合成军队的作战小组或目标引导小组的电台建立无线电通信；由合成军队统一分配有线电通信既设线路（电路）；由防空兵负责建立与合成军队之间的野战通信线路；使用简易信号通信器材等。', 17);
INSERT INTO `t_military_term_data` VALUES ('af024f55-f220-4711-b8bf-8dffec4b692a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇防险救生设备', '用以防止、限制舰艇因战斗或事故造成的损害,对舰艇和人员进行援救或自救的设备和器材的统称。主要包括：舰艇损害管制,救生与求救、潜水等器材和装具,以及舰艇的助浮、离浅、拖救设备等。', 243);
INSERT INTO `t_military_term_data` VALUES ('af07ad25-2f01-476c-a4c3-c0d966bc7e97', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上航行', '舰船依靠动力在海洋的水面或水下的行驶活动。按航行水域,分为狭水道（岛礁区）航行、沿岸航行、近海航行、大洋航行等；按航行条件,分为夜间航行、雾中航行、风暴中航行、冰区航行等。', 256);
INSERT INTO `t_military_term_data` VALUES ('af2cfab2-6232-40cf-be0b-af7395ffe477', '97a19170-bfac-42c5-9906-1acb187f0654', '试飞', '为检查、试验航空器的技术性能与工作特性或有关设备的性能而进行的飞行。对新交付使用的航空器或经过大修、定期检修、更换发动机及有关设备后的航空器,都要进行试飞。有时为检查机上或地面设备,也要进行试飞。', 243);
INSERT INTO `t_military_term_data` VALUES ('af416774-43f8-4e15-9064-9c4718a16fe2', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '充气工事', '用薄膜材料制成气囊式构件,在现地充入空气后组装成的掩蔽工事。重量轻,便于运输,结构简单,构筑快速,密闭防水性好,有的可埋入地下,但抗力有限。多用作后方野战医院、野战修理所和人员的掩蔽工事等。', 77);
INSERT INTO `t_military_term_data` VALUES ('af45b8e2-cd9d-4d45-8eb7-c910588631a4', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练油料', '专供军事训练使用的各种油料的统称。通常包括标准油料和专项油料。', 189);
INSERT INTO `t_military_term_data` VALUES ('af49924e-e9b3-4a07-81e4-8874e495c70d', 'f0140091-c11a-48c9-8836-8aa94439dac0', '尾击', '向运动之敌的后尾实施的攻击。主要用以配合主力从正面或翼侧歼敌。', 160);
INSERT INTO `t_military_term_data` VALUES ('af4d2579-54fb-4f2c-9f9a-de3310ef0f67', '878651de-adf5-4c72-9376-9c363b893ff8', '战略突击', '使用重兵集团或战略武器对敌战略目标实施的突击。', 116);
INSERT INTO `t_military_term_data` VALUES ('af5067bc-7865-4f76-b6e1-3afebab40f6a', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '遥感技术', '利用物体能辐射或反射电磁波的特性,通过光学和微波等仪器从远距离探测、识别目标与环境信息的技术。军事上广泛应用于侦察、预警、制导、测绘、气象等方面。', 17);
INSERT INTO `t_military_term_data` VALUES ('af5c1771-ee59-4d6e-86a7-f53f2ce0f8a3', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击毁伤（歼）概率', '炮兵在给定的射击条件下射击时,毁伤（歼）目标可能性大小的量。通常用0～1之间的数值表示。', 222);
INSERT INTO `t_military_term_data` VALUES ('af620872-6b08-4e89-b8b7-14ab5e0f615c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '迂回路', '为绕过难以克服的障碍物或隐蔽行动而构筑的辅助军用道路。', 258);
INSERT INTO `t_military_term_data` VALUES ('af62a6ff-6f92-41fd-87dd-47e65a61c8fd', 'f0140091-c11a-48c9-8836-8aa94439dac0', '反空降阵地', '用以打击空降之敌的阵地。通常选择在防御纵深内敌可能空降的地域。', 226);
INSERT INTO `t_military_term_data` VALUES ('af6ee3d4-0573-4118-870a-eab2760073d8', '98df76fb-4b65-48ff-a56c-4db587327c79', '战略运输', '为达成战略目的,在战略后和战区之间或各战区之间实施的军事运输。主要包括战略机动运输、战争动员运输、战略供应运输和战略疏散运输等。通常由统帅部或战区的交通运输指挥机构组织实施。', 245);
INSERT INTO `t_military_term_data` VALUES ('af6fba78-5732-4a63-9c5f-ee5856daf1b3', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上靶场', '设在海上供部队进行实弹训练或试验新武器用的靶场。主要包括：航空兵轰炸靶场,水面舰艇射击靶场,反舰导弹射击靶场,鱼雷、水雷攻击训练靶场和新武器试验靶场等。', 320);
INSERT INTO `t_military_term_data` VALUES ('af839cc5-60cf-465c-bf89-8eb8d615ddd9', '878651de-adf5-4c72-9376-9c363b893ff8', '战略重点', '对战略全局具有决定性影响的重大问题。如在军事上,主要或重要的作战方向、地区和目标等都可能成为战略重点。', 78);
INSERT INTO `t_military_term_data` VALUES ('af8b6523-979f-48ce-a530-7a308800a386', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '路标', '使用简便器材和方法标示部队行进方向、路线的记号。通常由组织行军的司令部统一规定,先头分队设置,后尾分队消除。', 71);
INSERT INTO `t_military_term_data` VALUES ('af909505-2118-4a73-8bcb-17e7efd0e020', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '重创', '给敌军以严重杀伤,使其虽仍保持建制但已基本丧失战斗力。', 377);
INSERT INTO `t_military_term_data` VALUES ('afa05241-a39f-4410-8bc0-5b8ed7bfcf03', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事科学', '亦称军事学。反映战争规律和战争指导规律,用以指导国防与军队建设、战争准备与实施的知识体系。包括军事思想、军事学术、军事技术、军事历史和军事地理等内容及其学科门类。', 6);
INSERT INTO `t_military_term_data` VALUES ('afa801b3-c8d7-4eea-9d2b-937612de659f', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '双拥模范城（县）', '拥政爱民、拥军优属模范城市和模范县的简称。中国人民解放军的部队与所驻县或县级以上城市的政府、人民群众,在开展拥军优属、拥政爱民活动中因成绩突出而被授予的荣誉称号。', 124);
INSERT INTO `t_military_term_data` VALUES ('afaa14d9-fd44-4415-a744-463dfa8c26d7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防卫', '对国家、地区或目标的防守和保卫。也指武装人员对自身安全的防卫。', 398);
INSERT INTO `t_military_term_data` VALUES ('afaf341e-e1a3-4ffd-ad29-182f9f1845a6', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象车', '装有气象仪器设备,遂行机动气象保障任务的专用车辆。包括地面气象观测车、高空气象探测车、气象火箭探测车、气象通信车、天气预报保障车、气象装备修理车、气象电源车等。', 104);
INSERT INTO `t_military_term_data` VALUES ('afb31449-ad79-402d-a339-c1053c1c9e72', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '三大民主', '中国人民解放军内部实行的政治民主、经济民主、军事民主。主要是经过集中领导下的民主,达到政治上高度团结、生活上获得改善、军事上提高技术和战术的目的。', 5);
INSERT INTO `t_military_term_data` VALUES ('afc32fad-d97d-47e0-abf3-db853fa67758', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲单位', '装甲战斗车辆数量的计算单位。l辆装甲战斗车辆即为1个装甲单位。', 13);
INSERT INTO `t_military_term_data` VALUES ('afcc3e10-ca77-446e-9561-535c1247bd6b', '06a75831-13a1-4660-870a-455bb445336a', '无线电管制', '对无线电发射设备和其他辐射电磁波设备的使用实施的军事管制。包括禁止、中止或限制某些无线电发信。通常在战时或某种非常情况下实施。', 37);
INSERT INTO `t_military_term_data` VALUES ('afcc5d4b-484a-47e9-bda4-8d0add5c3c6a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '自航水雷', '油布放入水后能自动潜航至预定地点的沉底水雷。主要用于攻势布雷,以封锁敌港口和海军基地。', 218);
INSERT INTO `t_military_term_data` VALUES ('afdee567-5e07-4764-a85f-58512efdff57', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '夹叉法试射', '逐次折半火炮射弹的远近炸点形成的夹叉,使射弹逼近目标或实有试射点,以确定目标效力射开始诸元或实有试射点成果诸元的试射。通常在不能使用偏差法试射时采用。', 151);
INSERT INTO `t_military_term_data` VALUES ('afe3a072-c9e6-4a5d-9b21-f55c44ba7f67', '98df76fb-4b65-48ff-a56c-4db587327c79', '军队房地产', '由军队管理使用的土地、房屋及其附属设备、林木等国家财产的统称。是军事设施的重要组成部分。', 240);
INSERT INTO `t_military_term_data` VALUES ('afe7f9fa-8a74-4c90-9e49-3be69f3cd725', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵后勤保障', '第二炮兵为满足部队建设、作战和生活等需要而在后勤方面采取的各项保证性措施与进行的相应活动的统称、主要包括：物资、经费保障,医疗卫生保障,运输保障和后勤技术装备保障等。', 205);
INSERT INTO `t_military_term_data` VALUES ('aff2c918-d356-4dca-8ae2-594497c91b70', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '分段作业', '将一个训练课题按内容和顺序划分成若于段落,逐个地进行作业。', 95);
INSERT INTO `t_military_term_data` VALUES ('aff84ec0-c139-4201-b92a-e4bde35231e4', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '部队业余演出队', '中国人民解放军的军级以下单位从事业余文艺创作和演出活动的群众性文娱组织。主要任务是：培养、发挥基层官兵的文艺爱好和特长,提高官兵的审美素质,活跃和丰富官兵的文化生活等。', 119);
INSERT INTO `t_military_term_data` VALUES ('b000a245-51ad-41ca-bd4f-8b673b2a3550', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵测量保障', '亦称第二炮兵测绘勤务保障。第二炮兵为获取作战和训练需要的测绘资料和测定场点位置等而进行的保障。主要包括：布设导弹发射阵地区域专用控制网,测定导弹发射点坐标、高程和所在地重力加速度,测定导弹弹道观察点和核爆探测点的位置,测定目标点和瞄准点,整理提供有关测绘资料等。战略巡航导弹部队测绘保障,还需提供预定航线下的详细地图等。', 179);
INSERT INTO `t_military_term_data` VALUES ('b0129662-bb58-4f93-9d36-155564884ee8', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '调查询问', '向有关人员了解作战所需情况的活动。主要对象是党政机关、群众团体、游击队、居民、来往敌占区的人员和投诚人员等。', 48);
INSERT INTO `t_military_term_data` VALUES ('b017fcce-2cd7-42d1-8af6-e97a51b5bfc2', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '三从训练', '从实战需要出发,从难、从严进行训练。是军事训练的基本原则之一。', 4);
INSERT INTO `t_military_term_data` VALUES ('b0215f21-a6c8-40dd-ad17-c9566be83de4', '8a761efd-50a6-4ac8-9913-b7d745104f82', '山地射击', '在高差200米以上的地形上进行的实弹射击。', 103);
INSERT INTO `t_military_term_data` VALUES ('b022d632-9da6-454a-bf76-63f633f07515', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '外军研究', '对外国军事情况进行的分析研究。主要研究外军的军事思想、军事战略、战役战术、军事训练、编制装备等情况。', 143);
INSERT INTO `t_military_term_data` VALUES ('b0232a8d-b649-4646-8df6-d786b818d5a3', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '补充', '军队的人员、装备、物资不足时,在其原有基础上予以补给、充实。', 393);
INSERT INTO `t_military_term_data` VALUES ('b030b263-b7cf-4249-a364-ec7c0ef07461', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军歌', '①以反映战争和军事生活题材为主要内容的歌曲。②代表一支军队或某一部队的歌曲。中国人民解放军的军歌是《中国人民解放军军歌》。1939年创作于延安,原名为《八路军进行曲》；解放战争时期更名为《人民解放军进行曲》；1965年改名为《中同人民解政军进行曲》；1988年7月25日改为现名,并被正式确定为中国人民解放军的军歌。', 113);
INSERT INTO `t_military_term_data` VALUES ('b03571b3-84f6-4875-ba4e-43dcc352352c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上巡逻', '海军兵力在一定海区内进行的巡查活动。按距离,分为远程巡逻和近程巡逻；按任务,分为防潜巡逻、防空巡逻、防水面舰艇巡逻和防水雷巡逻。由海军航空兵、水面舰艇和潜艇分别实施或协同实施。', 51);
INSERT INTO `t_military_term_data` VALUES ('b04b44c8-dc7e-4705-a017-1673b66c0a54', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上破袭战', '海军兵力运用多种手段对敌方重要目标实施袭击、破坏的进攻作战。是海上进攻战的重要样式。目的是歼灭、削弱、消耗敌人,配合正面战场作战。', 26);
INSERT INTO `t_military_term_data` VALUES ('b04ca095-df9d-42c2-8f16-a0cc40075984', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克密度', '作战正面上使用坦克的疏密程度。通常以作战正面上平均每公里使用坦克的数量表示,单位为辆／公里。用以衡量坦克集中使用的程度和计算敌对双方兵力的对比。', 14);
INSERT INTO `t_military_term_data` VALUES ('b05533b2-a82a-491a-8b2a-d49374372670', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机尾迹', '飞机飞行中发动机排出的废气与周围空气混合凝结而成的带状云。一般发生在气温低于-40度、又有适当湿度条件的空气层中。', 385);
INSERT INTO `t_military_term_data` VALUES ('b0576827-5793-4ce9-82ed-9fd125f238e9', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海流', '亦称洋流。由海面风力、海水中压强梯度力和地转偏向力等引起的海水沿一定方向与途径的大规模流动。按成因,分为风生流、梯度流和补偿流；按流经海域的水温差,分为寒流和暖流。海流对海洋的物理、化学、生物和地质特征,及其附近的天气、气候的形成和变化等有重要影响。', 125);
INSERT INTO `t_military_term_data` VALUES ('b05c688f-44d8-464f-a22c-a6b919fadfeb', '06a75831-13a1-4660-870a-455bb445336a', '军事通信网', '由军用通信线路连接若干通信台站、通信枢纽而构成的通信网络。按保障任务和范围,分为战略、战役、战术通信网；按通信业务,分为电话、电报、数据、图像和综合业务通信网等。通常按指挥系统和按地域两种形式组网。', 61);
INSERT INTO `t_military_term_data` VALUES ('b063c595-7dd7-4c4a-af82-311c159b3aae', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天测控站', '航天测控网中,对航天器及运载火箭的飞行直接进行跟踪测量和控制的工作站。分为固定测控站和机动测控站。通常由跟踪测量设备、遥测设备、遥控设备、计算机、通信设备、监控显示和时间统一设备等组成。在航天控制中心的组织下,担负测量航天器的运动参数、接收解调航天器的遥测信息、向航天器发送遥控指令,并与航天器通信等。', 269);
INSERT INTO `t_military_term_data` VALUES ('b06cfd5c-4f47-435d-b1ca-c59239a9e982', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '殿后舰', '舰编队航行时位于编队队形或队列最后面的舰。', 262);
INSERT INTO `t_military_term_data` VALUES ('b07856ec-5ab8-499e-a712-9a4aebe557f5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反潜导弹', '用以攻击潜艇的各种导弹的统称。包括舰潜导弹、潜潜导弹和空潜导弹。分为弹道式反潜导弹和巡航式反潜导弹。其战斗部通常为反潜自导鱼雷或核深水炸弹。', 193);
INSERT INTO `t_military_term_data` VALUES ('b08bf96d-2337-47ba-9821-fe4cc0fcf0bf', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事后勤学', '研究军事后勤活动的理论与实践及其规律的学科。主要研究内容包括：武装力量后勤建设,军事后勤保障的基本理论、指导原则和组织实施方法等。', 32);
INSERT INTO `t_military_term_data` VALUES ('b0bc5bd2-9cb7-48ea-93eb-2b6091f1ab0b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反空袭', '针对敌之空袭采取的抗击、反击和防护的行动。', 209);
INSERT INTO `t_military_term_data` VALUES ('b0d4ce8b-fdab-465e-8eaa-40cebf11f6fb', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达干扰', '削弱或破坏敌方雷达对目标的探测和跟踪能力的电子干扰。按干扰产生的方法,分为有源雷达干扰和无源雷达干扰；按干扰性质,分为压制性雷达干扰和欺骗性雷达干扰。', 53);
INSERT INTO `t_military_term_data` VALUES ('b0de6817-f96e-4788-8e69-ab016c62e234', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '电子工业', '研制和生产电子设备、电子元件、专用原材料的工业。主要产品有电子计算机、广播电视设备、通信导航设备、雷达设备、电子元器件、电子仪器仪表和其他电子专用设备等。', 43);
INSERT INTO `t_military_term_data` VALUES ('b0e49139-01a2-4f5c-bd3c-51bf02963b1d', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '阵地防御战役', '依托阵地进行的防御战役。分为坚固阵地防御战役和野战阵地防御战役。', 121);
INSERT INTO `t_military_term_data` VALUES ('b0e81e67-4058-45d1-868d-8f02c02a0d40', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '列装', '将新装备正式列人军队现行的装备体制或编制。', 88);
INSERT INTO `t_military_term_data` VALUES ('b0ff1bc7-fd8c-4ad5-a8f7-eb9d20e2edc5', '98df76fb-4b65-48ff-a56c-4db587327c79', '专用物资', '只适用于某一军兵种的特殊物资。如空军的航空弹药、航空技术器材、飞行服,海军的水雷、鱼雷、舰艇维修器材,防化兵的防化器材等。', 99);
INSERT INTO `t_military_term_data` VALUES ('b1198ed8-d7da-40fa-8881-b3327bb09012', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '水源污染', '人类活动中排放或投放的污染物进入水体,使水中有害物质的含量超过用水标准的现象。分为河流污染,湖泊、水库污染,海洋污染和地下水污染。', 361);
INSERT INTO `t_military_term_data` VALUES ('b123921e-21c7-4947-ae32-670ac76ffb72', '98df76fb-4b65-48ff-a56c-4db587327c79', '油料供应指标', '简称油料指标。按年度或按任务规定的油料供应定额。是平时实施油料供应和控制油料消耗的主要依据。', 180);
INSERT INTO `t_military_term_data` VALUES ('b13eb80c-f9d3-4d9a-ba91-3386297a34ae', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '军事系统工程', '运用系统科学的理沦和方法对军事领域的特定目标进行定量分析和定性分析,实施合理的规划、研究、设计和管理,以实现最优化的系统目标的工程技术。广泛应用于作战、训练、后勤保障和武器装备研制等。', 36);
INSERT INTO `t_military_term_data` VALUES ('b14c12da-7ec6-410b-8880-e20afe10a5dc', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '劳武结合', '民兵生产劳动与武装斗争相结合的简称。指民兵在战时,既坚持生产劳动,又参加作战活动；在平时,既参加经济建设活动,又坚持军事训练,参加战备执勤。', 128);
INSERT INTO `t_military_term_data` VALUES ('b14e0fc4-5b65-4c5a-8e77-a088e0d2cada', 'd7132c58-5df3-4b97-919f-58740148b9ca', '牵引高炮武器系统', '靠牵引车牵引行进的高射炮武器系统。通常包括高射炮、炮瞄雷达、高炮射击指挥仪（光学跟踪和测距装置、火控计算机）和电源机等。', 45);
INSERT INTO `t_military_term_data` VALUES ('b1581008-baea-4376-926d-501d893bcd1d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵对空掩护', '防空兵抗击敌空袭兵器,掩护己方目标对空安全的作战行动。通常根据敌情、防空武器性能、被掩护目标性质以及地形和道路等情况,确定不同的防空样式,采取不同的掩护方法。', 64);
INSERT INTO `t_military_term_data` VALUES ('b1615a6d-3973-4452-ae18-9d42a3ada0fe', 'f0140091-c11a-48c9-8836-8aa94439dac0', '散兵线', '分队散开形成的线式战斗队形。相邻的两个士兵间隔一般为6～8米。通常在敌火下运动或冲击时采用。', 70);
INSERT INTO `t_military_term_data` VALUES ('b161efad-ca03-4e23-ae79-374cc86ae322', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '技术训练', '对军人进行的以技术装备的理论知识、操作使用、管理维修技能等为主要内容的训练。', 76);
INSERT INTO `t_military_term_data` VALUES ('b1649194-3d08-4f86-ada1-b60cf7841cf4', '97a19170-bfac-42c5-9906-1acb187f0654', '机场加油设备', '亦称地面加油设备。在地面给飞机或直升机加注航空油料的成套机械、设施和器具的统称。分为活动式、固定式和半固定式机场加油设备。', 431);
INSERT INTO `t_military_term_data` VALUES ('b1760252-0c16-4c07-b931-784576289a96', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '反辐射无人机', '装有战斗部并能利用敌方电磁辐射源发射的信号进行自导引、摧毁波辐射源的无人驾驶飞机。可由飞机携带到空中发射或在地面发射。', 146);
INSERT INTO `t_military_term_data` VALUES ('b181a74a-0a74-4791-8a08-efc395de8dee', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战指导', '对作战基本问题所给予的原则性指示和引导。', 113);
INSERT INTO `t_military_term_data` VALUES ('b1882b50-2adc-4866-83a4-7fcb15214abd', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电引信干扰设备', '用以发射干扰电磁波,使敌方射弹上的无线电引信提前引爆或失效的电子干扰设备。', 128);
INSERT INTO `t_military_term_data` VALUES ('b1946b79-969d-471f-844f-3c6eaa04479e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '后发制人', '首先采取防御姿态,待敌发起进攻后抓住其暴露的弱点,再以攻击行动制服敌人。', 241);
INSERT INTO `t_military_term_data` VALUES ('b19f31a9-7b4b-4b8d-8486-b7be497aae49', '97a19170-bfac-42c5-9906-1acb187f0654', '通信飞机', '用以传递战斗文书和接送通信联络人员的军用飞机。通常为小型飞机。', 289);
INSERT INTO `t_military_term_data` VALUES ('b19fffc5-c5a1-43e8-a899-4f9b58394f29', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机作战区域', '直升机部队进行作战活动的区域。', 86);
INSERT INTO `t_military_term_data` VALUES ('b1b30078-daf5-46f5-a8c0-8b4359867fa9', '97a19170-bfac-42c5-9906-1acb187f0654', '战略空降', '由统帅部组织的为达成一定战略目的而在敌战略纵深和后方实施的空降。主要任务是夺取敌方政治、经济、军事中心或其他战略要地。', 150);
INSERT INTO `t_military_term_data` VALUES ('b1b71ecc-fb80-4bba-874b-4afd433db913', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军部署', '对行军的兵力、路线、任务及相关工作所作的布置和安排。', 55);
INSERT INTO `t_military_term_data` VALUES ('b1c84b64-d9a3-4689-8082-03d0882d38b3', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火网', '由正射、斜射、侧射等多方向火力交织的密集火力。', 242);
INSERT INTO `t_military_term_data` VALUES ('b1d5ac11-6367-4ad0-aae8-443ef3d13d90', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军事代表', '简称军代表。军队派驻地方某些单位办理与军队有关事务的人员。中国人民解放军中的军事代表主要有：派驻交通运输部门办理军事交通事务的人员,派驻工厂担负军工产品验收任务的人员等。', 111);
INSERT INTO `t_military_term_data` VALUES ('b1dbf3c9-979d-484f-bd44-2d042e13f4b7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '地境', '呈扇形的区域。如射击地境、观察地境等。', 301);
INSERT INTO `t_military_term_data` VALUES ('b1e04800-81a8-4113-ba85-28b8821d8ae2', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '搜索', '根据作战需要,对复杂和可疑的区域进行的搜查活动。分为地面搜索、海上搜索和空中搜索。', 43);
INSERT INTO `t_military_term_data` VALUES ('b1f81954-530b-4a06-ab49-ee2b00796c87', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '红外干扰机', '用以发射宽带编码的红外干扰脉冲,破坏红外寻的导弹跟踪的光电干扰设备。通常装在飞机尾部,用于自卫。可按预编程序自动工作,也可按驾驶仓控制台发出的指令工作。', 130);
INSERT INTO `t_military_term_data` VALUES ('b1f92fcf-ca1d-45db-8ae4-479fc9f81aee', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆抗风浪能力', '具有浮渡能力的装甲车辆抵御风浪、安全航行的力。一般以在保障安全航行条件下所能承受的最大风浪等级表示。', 172);
INSERT INTO `t_military_term_data` VALUES ('b1fa19aa-d520-41f5-8435-1fdd13bdabec', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军容风纪', '军队、军人的仪表、姿态、风貌的统称。是军队军政素质和战斗力的一种表现。', 44);
INSERT INTO `t_military_term_data` VALUES ('b1fd834d-4243-43c4-bf3a-25a122cfbc57', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '导弹技术', '研制导弹所涉及的各种技术的统称。主要包括导弹总体设计技术、推进技术、制导技术、战斗部技术、结构技术、试验技术和管理技术等。', 5);
INSERT INTO `t_military_term_data` VALUES ('b20299a1-3686-4999-a0c2-eff4eea817ca', '97a19170-bfac-42c5-9906-1acb187f0654', '机载电子设备', '安装在飞机或直升机上的各种电子设备的统称。主要包括：通信、导航、目标探测、电子对抗、敌我识别、座舱显示、信息综合与处理的电子设备,以及航空发动机和机载武器系统的控制与管理的电子设备等。', 336);
INSERT INTO `t_military_term_data` VALUES ('b2037f3d-1c16-4170-9d4a-574c02c515b6', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '冰雹', '单块直径在5毫米以上的固态降水现象。冰雹呈坚硬的球状、锥状或不规则形状,常降自发展特别旺盛、过冷雨滴和云滴含量十分丰富的积雨云中。', 27);
INSERT INTO `t_military_term_data` VALUES ('b20b3fd0-9172-4534-94dd-3fdc4a9a5239', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '专职人武干部训练', '对乡镇、大中型企业和事业单位专门从事民兵、兵役等工作的人民武装干部进行的训练。主要内容包括军事知识、作战技能和民兵工作等。', 67);
INSERT INTO `t_military_term_data` VALUES ('b21785ae-db9d-4c54-868b-1f1518ebeede', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '桅杆', '简称桅。舰艇甲板上竖置的立柱或衍架。用以装设雷达、通信、导航设备的天线及桅灯、信号灯、航行灯,是挂国旗、号旗、号型和其他信号等。', 162);
INSERT INTO `t_military_term_data` VALUES ('b223cba9-ca04-4f01-a269-ad779c6c39e4', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹飞行时间', '导弹自飞离发射装置至弹头命中目标的时间。', 144);
INSERT INTO `t_military_term_data` VALUES ('b229814d-9bbd-437a-9e84-c4f3ed0f248d', '06a75831-13a1-4660-870a-455bb445336a', '军邮', '军队管理的邮政工作。主要是传递军队内部和军内同军外互寄的函件、报刊、图书资料、包裹以及办理汇兑等。战时师以上部队根据需要设立军邮机构；平时通常不建立专门的军邮机构,其业务通过国家邮政部门实施。', 131);
INSERT INTO `t_military_term_data` VALUES ('b235206b-a0da-4e80-99a4-2daa11885602', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射弹散布', '亦称弹道散布。同一武器在相同条件下连续射击时，射弹的弹着点在一定垂直向或水平面上的分布现象。造成散布的主要原因是射弹的初速、射角、方向角以及射弹脱离火身口瞬时的旋速、摆动角速度、气象条件不一致等。在垂直面上的弹着群称垂直散布面,在水平面上的弹着群称水平散布面。', 73);
INSERT INTO `t_military_term_data` VALUES ('b239665a-0f90-4ef4-b489-0ca4050af187', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练考勤', '对所属单位训练的出勤率和效率等情况进行的检查。', 167);
INSERT INTO `t_military_term_data` VALUES ('b23b05ae-3fe6-4699-befe-d0359b70aa8e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '强点', '①交战双方各自的长处。②作战部署中,兵力、火力较强或工事强固之处。', 306);
INSERT INTO `t_military_term_data` VALUES ('b25cdba7-0a81-49e8-9c9f-0d42d34021e9', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹瞄准设备', '赋予导弹射向的各种仪器设备的统称。分为自动瞄准设备、半自动瞄准设备和手动瞄准设备。包括光学、光电、惯性仪表和激光专用仪器设备等。', 69);
INSERT INTO `t_military_term_data` VALUES ('b26c1427-5db9-42a5-8236-1f01fb09a4ec', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '模拟教学', '使用模拟器材和设备进行的教学。如用驾驶模拟器、飞行模拟器进行的驾驶与飞行教学等。', 158);
INSERT INTO `t_military_term_data` VALUES ('b26d4d1c-c04b-4792-b039-bcbc86e70a04', 'f0140091-c11a-48c9-8836-8aa94439dac0', '突击点', '亦称攻击点。进攻战斗中对敌实施攻击的地点。通常选择在敌防御薄弱,便于突击分队隐蔽接近和展开攻击之处。', 176);
INSERT INTO `t_military_term_data` VALUES ('b27bf280-a5e7-4672-8afa-f61a4656ca43', '97a19170-bfac-42c5-9906-1acb187f0654', '专机飞行', '飞机或直升机供高级领导人或重要外宾乘坐,并有专门飞行保障的飞行。', 218);
INSERT INTO `t_military_term_data` VALUES ('b281ef0e-fe0d-42cd-ac84-5e921a8e7093', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '战略工程保障', '对战略行动实施的工程保障。由战略指挥机关组织实施。主要任务是；实施战场工程准备和其他国防工程建设,生产、储备工程器材,组建并部署工程兵部队、预备役工程兵部队和民兵工程兵,以及其他关系战争全局的工程保障等。', 10);
INSERT INTO `t_military_term_data` VALUES ('b28324da-1f62-4e38-b442-6953cfaaa9d4', 'f0140091-c11a-48c9-8836-8aa94439dac0', '近战火力', '近战火器发射的火力。通常包括各种枪械、便携式导弹、直瞄火炮所发射的火力。', 91);
INSERT INTO `t_military_term_data` VALUES ('b284fccc-2557-4529-9508-e0b84771f31d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰载机弹射装置', '航空母舰上用以增大舰载飞机起飞速度以缩短滑跑距离的装置。分为压缩空气式、火药式、电动式、液压式和蒸汽式等弹射装置。', 169);
INSERT INTO `t_military_term_data` VALUES ('b285eef4-91a8-4cdf-a0ee-262c7e3e8add', '98df76fb-4b65-48ff-a56c-4db587327c79', '携行量', '按规定由人员携行、马匹驮运和武器装备配带的物资数量的统称。是移动储备的组成部分。', 116);
INSERT INTO `t_military_term_data` VALUES ('b28a8434-1cff-4270-9a73-a0927aa497b0', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核战斗部自毁', '核武器投射后,为了安全或其他原因,有意使核战斗部失去核爆炸能力并自行销毁。', 137);
INSERT INTO `t_military_term_data` VALUES ('b291e19e-9e5e-42b4-b677-65d18e910177', '98df76fb-4b65-48ff-a56c-4db587327c79', '伤病员后送', '将伤病员从下级救治机构送往上级救治机构的活动。包括前接和后转两种方式。是实施分级救治的基本条件之一。', 202);
INSERT INTO `t_military_term_data` VALUES ('b2a869e7-c6b3-428d-aa39-97f0b6d2765a', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工事射界', '工事能为火器射击提供的最大射界。包括水平射界和高低射界。', 82);
INSERT INTO `t_military_term_data` VALUES ('b2c19af0-18f7-4305-920b-685e83135331', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化兵专业训练', '防化兵进行的以专业理论知识和作战技能为主要内容的训练。分为专业技术训练和专业战术训练。目的是提高组织实施防化保障和遂行专业任务的能力。', 38);
INSERT INTO `t_military_term_data` VALUES ('b2c1a562-6644-4313-af19-c0d9dd5ffac1', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射点', '经过精密大地测量确定的用于导弹发射的点位置。通常用大地坐标表示。', 54);
INSERT INTO `t_military_term_data` VALUES ('b2c79714-01f8-4a67-8ce9-404be2cba38b', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '大队', '相当于团或营的军队一级组织。如中国人民解放军海军的舰艇大队（相当于团）、空军的飞行大队（相当于营）等。', 30);
INSERT INTO `t_military_term_data` VALUES ('b2d2ff07-4a94-41f6-a760-7cb5b38fe9e4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵气象雷达', '炮兵用以探测大气中一定范围内某些气象要素和天气系统的雷达。主要有测雨雷达和测风雷达。', 290);
INSERT INTO `t_military_term_data` VALUES ('b2d86b1a-701c-4829-8037-7dd467487024', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '被动', '军队在作战行动中受制于敌的状态。', 269);
INSERT INTO `t_military_term_data` VALUES ('b2da1189-6a0f-4d5d-962d-51a83173f80f', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '数据库系统', '在计算机上对数据集合进行统一存储和管理的系统。由数据库和数据库管理系统构成。数据库是按一定数据模型在计算机设备中组织、存储和使用的互相联系的数据集合；数据作管理系统是负责建立、维护和管理数据库的软件。军事上有广泛用途。', 61);
INSERT INTO `t_military_term_data` VALUES ('b2dbcc43-406a-4cad-aed2-beba3b89b98f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防空区域', '按照对空作战和对空防护的需要而划分的遂行防空任务的空间范围。', 215);
INSERT INTO `t_military_term_data` VALUES ('b2dd415a-e7b4-4779-9ed1-a5747b94b095', '8a761efd-50a6-4ac8-9913-b7d745104f82', '验枪', '为了安全,在操作枪械前后或必要时,检查弹膛、弹匣、弹箱内和教练弹中有无实弹的动作。', 230);
INSERT INTO `t_military_term_data` VALUES ('b2dec26c-016a-4eae-bf2c-37404db69caf', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '越海侦察', '侦察分队或人员秘密渡过海峡和水道,对敌占岛屿、海岸进行的侦察。', 27);
INSERT INTO `t_military_term_data` VALUES ('b2f547e7-9d77-4f85-9689-6a4f529e12c2', '06a75831-13a1-4660-870a-455bb445336a', '通信系统', '由通信人员及其所使用的通信装备、设施组成的,用以传递信息的系统。按保障任务和范围,分为战略通信系统、战役通信系统和战术通信系统；按系统的位置可否移动,分为野战通信系统和固定通信系统。', 167);
INSERT INTO `t_military_term_data` VALUES ('b2fa1604-449b-4db3-9066-7bf114a8ff0b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防空组织', '根据防空任务组成的防空组织系统及其工作机构。中华人民共和国的防空组织包括国土防空、野战防空和人民防空三大部分。', 213);
INSERT INTO `t_military_term_data` VALUES ('b3009399-aec6-4b3f-9909-0aadfaf34691', '916997ee-6728-4c61-9b79-d96960b1dc86', '发烟分队', '担负烟幕保障任务的防化兵分队。主要负责：施放大面积烟幕,遮蔽己方作战行动和重要目标，干扰敌方的观察、射击和光电武器系统。', 6);
INSERT INTO `t_military_term_data` VALUES ('b30865d0-60b3-415a-a96d-a2e139ea0d12', '98df76fb-4b65-48ff-a56c-4db587327c79', '前接', '由上级救治机构到下级救治机构接取伤病员的活动。是伤病员后送的主要方式。分为逐级前接和越级前接。', 203);
INSERT INTO `t_military_term_data` VALUES ('b313c4e2-93a4-462a-8549-588cb9d9edfe', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '武装巡罗', '部队或人员携带武器在所受领的任务区域内进行的游动巡查活动。主要包括边境武装巡逻和城市武装巡逻等。', 427);
INSERT INTO `t_military_term_data` VALUES ('b31477b0-767d-46f6-b805-5be0e3a62df7', '98df76fb-4b65-48ff-a56c-4db587327c79', '专科治疗', '专科医生使用专门的医疗设备对伤病员进行的确定性治疗。通常由专科医院、综合医院和得到专科医疗队或手术队加强的野战医院实施。', 197);
INSERT INTO `t_military_term_data` VALUES ('b33625cd-b4ff-4877-83ce-0841df1e4c0b', 'f0140091-c11a-48c9-8836-8aa94439dac0', '登陆战斗', '对据守海岸之敌的渡海进攻战斗。通常在战役编成内,由登陆部队、海军登陆编队和直接支援的航空兵组成的联合登陆兵团共同实施。', 136);
INSERT INTO `t_military_term_data` VALUES ('b33cee3f-24c1-4b8a-aa41-cfca7fcab246', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵工程保障', '第二炮兵为遂行作战、训练等任务而在工程方面进行的保障。主要包括；实施工程侦察,维护和抢修防护工程、发射阵地、道路、桥梁,构筑机动作战阵地、作战工事,实施伪装，排除障碍物,处置核袭击后果的工程作业等。', 190);
INSERT INTO `t_military_term_data` VALUES ('b3441087-f020-43be-9f5a-840c32045402', '97a19170-bfac-42c5-9906-1acb187f0654', '俯冲', '飞机向前下方以较大下降角进行直线加速的飞行。飞机俯冲时的飞行轨迹延长线与地面的夹角称俯冲角,通常为30度～90度。', 237);
INSERT INTO `t_military_term_data` VALUES ('b3461459-af95-43bc-877a-9c05761968d5', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空武器系统反应时间', '地空导弹、高射炮武器系统从发现目标到开始发射（射击）的时间。', 56);
INSERT INTO `t_military_term_data` VALUES ('b35a5ac4-efd6-4575-bf7c-992ce5de8bd6', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队信访工作', '中国人民解放军各级领导机关受理部队官兵和人民群众来信来访的工作。', 143);
INSERT INTO `t_military_term_data` VALUES ('b35f34ac-f732-4fca-83bc-d948f480474e', '31f4a446-5b98-4873-9d53-310d97125b07', '结合导弹弹头', '将导弹弹头按要求结合在弹体上的过程。分为水平结合和垂直结合。通常在导弹技术阵地实施,也可在导弹发射阵地实施。是导弹发射准备中的一项重要工作。', 85);
INSERT INTO `t_military_term_data` VALUES ('b364199a-0091-4cda-8a1f-6b8ff3bc7248', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '伴随桥', '保障第一梯队或先头部队克服江河障碍的军用桥梁、多用伴随部队机动的机械化桥、重型或中型衍架桥等器材架设。', 286);
INSERT INTO `t_military_term_data` VALUES ('b36736fe-91a7-4c67-9a09-9c53760af94d', '878651de-adf5-4c72-9376-9c363b893ff8', '战略目标', '①对战争全局有重大影响或对达成战略目的有重要意义的打击或防卫对象。如政治、经济和军事指挥中心、重兵集团、军事基地、重要的生产和工程设施等。②国家或政治集团确定的一定时期内,在战略上所要达到的目的、标准和水平。', 75);
INSERT INTO `t_military_term_data` VALUES ('b3688e91-2c2e-47a5-af4b-87ba9da0a274', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '人工遮障', '用制式或就便伪装器材设置的遮障。按对付侦察器材的种类,分为防光学遮障、防雷达遮障、防热红外遮障和多谱段遮障等；按架设形式和作用,分为掩盖遮障、垂直遮障、水平遮障、变形遮障和干扰遮障等。', 344);
INSERT INTO `t_military_term_data` VALUES ('b36ce27f-443d-4ad4-aa69-f44bf3299b83', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹师', '空军中由若干个地空导弹团编成的地空导弹兵一级组织。为地空导弹兵的基本战术兵团。通常隶属于军区空军。', 24);
INSERT INTO `t_military_term_data` VALUES ('b393193d-7dc0-4771-be5b-093d9e99f00e', '8a761efd-50a6-4ac8-9913-b7d745104f82', '冲锋枪', '可双手握持,抵肩使用,发射手枪弹的全自动枪。适合在丛林战、巷战中使用,能以密集火力射击200米内的生动目标。全枪重一般为3千克左右,单发战斗射速约40发／分,连发战斗射速100发/分。', 158);
INSERT INTO `t_military_term_data` VALUES ('b393abe7-aa46-4cf6-9c47-569babc4e0b9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战机', '适于用兵作战的时机。现代战争作战节奏加快,战机稍纵即逝、应善于把握、捕捉和创造战机。', 250);
INSERT INTO `t_military_term_data` VALUES ('b3956a36-aabb-41e1-80bc-6cfd1e474039', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹固定发射', '利用固定不动的发射装置和地面控制飞行系统进行的导弹发射。有场坪发射、井内发射和井口发射。', 113);
INSERT INTO `t_military_term_data` VALUES ('b398188a-1cb0-41f8-8f9b-36b003030d8b', '06a75831-13a1-4660-870a-455bb445336a', '卫星通信地球站', '设在地球表面（含大气层）以卫星为中继站的无线电通信站。分为固定站、移动站和可搬移站等。由发信、收信、天线、终端、用户接口和供电等设备组成。可传送电话、电报、数据和图像等。', 83);
INSERT INTO `t_military_term_data` VALUES ('b3982596-cbf8-410c-b892-323f51842e68', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天器', '在太空沿一定轨道运行并执行探索、开发、利用太空等任务的飞行器。分为无人航天器和载人航天器。无人航天器包括人造地球卫星、空间平台和空间探测器等；载人航天器包括载人飞船、空间站、航天飞机等。', 203);
INSERT INTO `t_military_term_data` VALUES ('b3a06535-7362-4938-b6e0-671dfd8da272', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '合水线', '山谷两侧坡面上水流的集聚线。反映在地形图上是山谷各条等高线凹入部分顶点的连线。合水线往往是水流的河床,对军队机动有一定影响。', 128);
INSERT INTO `t_military_term_data` VALUES ('b3a59d01-3952-4acc-9b4f-b6f3d29b5783', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队基层党委', '军队中党的基层委员会的简称。中国共产党在中国人民解放军营或相当于营级的单位设立的委员会。一般由该单位党员大会差额选举产生,是该单位统一领导和团结的核心。', 41);
INSERT INTO `t_military_term_data` VALUES ('b3a9499b-bf2d-4ed0-9bc0-1a4895bb21f0', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射井', '供陆基战略导弹垂直储存、发射准备和实施发射的地下工程设施。包括坚井及与其配套的技术设施、设备。分为井口发射式发射井和井内发射式发射井。', 53);
INSERT INTO `t_military_term_data` VALUES ('b3b285ec-3564-41c4-9501-6aa6589625dc', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察专业知识训练', '为使侦察人员掌握侦察专业知识而进行的训练。主要训练内容包括侦察常识、外军知识、调查询问、审讯俘虏和军事地形学等。', 88);
INSERT INTO `t_military_term_data` VALUES ('b3b45f48-eb14-4598-b53c-40fe84efd3c5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇降噪', '降低舰艇的噪声的技术措施。用以减小被敌方声纳发现和水声制导武器命中的概率,提高舰艇隐蔽性与航行安全,并保证舰艇自身水声设备的正常工作,增大声纳探测距离。', 343);
INSERT INTO `t_military_term_data` VALUES ('b3bb5358-333e-45e7-82f8-f2cb5c912703', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机空中避让', '直升机在空中给正在飞行的其他航空器让出航路的行动。', 37);
INSERT INTO `t_military_term_data` VALUES ('b3bbd0b7-c170-4546-a907-2a8ba12571ba', 'f0140091-c11a-48c9-8836-8aa94439dac0', '野战防御阵地', '只构筑野战工事的防御阵地。通常临时在有利地形上构筑,有射击、指挥、掩蔽工事,并有堑壕、交通壕相连接。工事及障碍物配系可在作战中逐步完善。', 215);
INSERT INTO `t_military_term_data` VALUES ('b3bbe98a-de8a-47fe-9958-90431fb9ae36', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '输送命令', '下达输送任务的命令。内容一般包括；敌情,输送任务和决心,输送工具的组成,装（卸）载地域,梯队的编组和运行（航行、飞行）序列,装载和起运时间,装（卸）载指挥所的开设、输送中指挥所的位置及报告、联络方法,输送的各种保障措施等。', 79);
INSERT INTO `t_military_term_data` VALUES ('b3c6cb05-8448-4621-b5af-51eda2365ff8', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '龙卷', '亦称龙卷风。自积雨云底部下垂的漏斗状云及其所伴随的猛烈旋风。漏斗云内气压很低,可产生100～200米／秒的强风,并具有极强的吸卷作用,可把所到之处的尘沙或海水,甚至树木、房屋和人畜等卷入空中,形成高大的尘柱或水柱。是破坏力极强的小尺度天气系统。', 49);
INSERT INTO `t_military_term_data` VALUES ('b3d132c1-8f5f-4c14-a81c-0d0c640cda02', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战形式', '作战行动的整体的或基本的表现形态。如运动战、阵地战、游击战曾是中国革命战争的三种基本作战形式。在每种基本作战形式中,还可结合运用他种作战形式。', 129);
INSERT INTO `t_military_term_data` VALUES ('b3d7ab7c-c71b-4781-a2a1-497e7689bf24', '916997ee-6728-4c61-9b79-d96960b1dc86', '消毒液', '消毒剂与溶剂按一定比例调制成的溶液。供对装备、道路、地面和人员等消毒时使用。如三合二水溶液、一氧胺酒精溶液等。', 187);
INSERT INTO `t_military_term_data` VALUES ('b40158fa-f12f-4806-bb9c-4e64731cfe24', '878651de-adf5-4c72-9376-9c363b893ff8', '战略手段', '用以达成战略目的的力量。方法和措施的统称。通常以军事手段为主,与政治、经济、外交等其他手段配合使用。', 63);
INSERT INTO `t_military_term_data` VALUES ('b40254ec-1f5a-43e7-8198-129fec55e571', 'f0140091-c11a-48c9-8836-8aa94439dac0', '伏击地区', '预先埋伏兵力,以对运动之敌实施突然攻击的地区。通常包括埋伏地区、展开地区和歼击地区。应选择在敌必经之路,便于己方隐蔽配置兵力、发扬火力、迅速前出、突然攻击、进行堵截,且不便于敌展开和机动的地区。', 67);
INSERT INTO `t_military_term_data` VALUES ('b407b761-d93c-4963-a080-01880452d998', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '局部动员', '国家采取紧急措施,在局部地区、某些部门或担负作战任务的部队中实施的国防动员。局部动员后,相应的地区、部门或部队由平时状态转入战时状态。', 49);
INSERT INTO `t_military_term_data` VALUES ('b40df3ea-63bb-43f0-94dd-11889926d172', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹阵地布局', '导弹部队根据作战任务、武器装备性能、地形和安全要求,对导弹阵地各要素的统筹配置。包括对指挥所、技术阵地、发射阵地、储存库、各种保障设施等配置所作的合理安排。', 48);
INSERT INTO `t_military_term_data` VALUES ('b4147e0a-214b-430b-9c12-dbc4a4fbbf61', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '诱发闪电', '飞行器接近或穿越带电云层时,在电场作用下因强烈起带和电晕放电引起的闪电。诱发闪电对飞机飞行和导弹发射的安全威胁较大。', 88);
INSERT INTO `t_military_term_data` VALUES ('b422a9ac-3c88-4c22-93d1-958b2f938023', '878651de-adf5-4c72-9376-9c363b893ff8', '战略资源', '对国防或战争具有战略意义的人力、物力、财力资源的统称。如人口、土地、矿藏、粮食、资金储备等。', 98);
INSERT INTO `t_military_term_data` VALUES ('b4248a89-d40d-45c4-87b3-34902c543cd1', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军人举止', '军人的言谈行止。要求谈吐文明、得体,行止端正、规范。', 46);
INSERT INTO `t_military_term_data` VALUES ('b427fa2a-bc08-4b70-a22f-541e6cb22b88', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上反封锁', '由海军兵力单独或在其他军兵种协同下,阻止和粉碎敌方海上封锁的作战行动。按作战手段,分为反水雷封锁、反兵力封锁和反综合封锁。', 36);
INSERT INTO `t_military_term_data` VALUES ('b432bfab-e3aa-4317-b49e-a4491f0669a7', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '总动员', '全国总动员的简称,亦称全面动员。国家采取紧急措施,在全国范围内实施的国防动员。总动员后,国家一切社会生活领域均由平时状态转入战时状态。', 48);
INSERT INTO `t_military_term_data` VALUES ('b437735f-ad78-469d-b6d6-8c8e3dee37a4', 'f0140091-c11a-48c9-8836-8aa94439dac0', '集结地域', '部队临时集中并进行战斗准备的地域。通常选择在便于部队疏散隐蔽配置,便于组织对敌核、化学、生物武器袭击的防护,有良好的机动道路和充足水源的地域。', 62);
INSERT INTO `t_military_term_data` VALUES ('b43c8736-c0bd-43ab-bfe2-9b883387d6b9', 'f0140091-c11a-48c9-8836-8aa94439dac0', '热带山岳丛林地战斗', '在热带或亚热带山岳丛林地区进行的战斗。便于部队隐蔽和防护,但观察、通信联络和判定方位及机动、保障困难,人员体能消耗大,易发生疫病和受毒虫伤害。', 6);
INSERT INTO `t_military_term_data` VALUES ('b43dc141-3903-4993-8d69-9f7de46cc71a', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '警卫对象', '需要武装警戒和保卫的重要人物、机构、设施等目标的统称。', 124);
INSERT INTO `t_military_term_data` VALUES ('b43e043c-eed3-4578-b720-96a1c26b6186', '97a19170-bfac-42c5-9906-1acb187f0654', '随机空中突击', '航空兵部队以小编队或单机在一定空域内的游猎活动中,伺机对临时出现的地面、水面目标进行的空中突击。用以监视和限制敌之行动,给敌出其不意的打击。', 104);
INSERT INTO `t_military_term_data` VALUES ('b45a5de1-3937-496f-b107-d912618ab314', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战术训练指导法', '用以统一、规范战术训练的组织与实施的指导性文件。主要内容包括：战术训练的基本原则与要求,组织战术训练的形式、程序和方法,实施战术训练的手段与保障等。', 20);
INSERT INTO `t_military_term_data` VALUES ('b469cf64-5c75-44a8-acab-747612bf8afb', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇海上训练', '舰艇在海洋上进行的训练。主要包括：锚泊训练、锚地集训,练习性航行,转移海区或基地训练,远航训练,舰艇最大自给力连续航行训练等。目的是使舰艇人员熟练操纵舰艇和使用武器装备,适应海上生活环境,提高海上作战能力。', 316);
INSERT INTO `t_military_term_data` VALUES ('b4817c0e-16d5-4a43-b263-b3e2c7de99ec', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰空导弹', '亦称舰艇防空导弹。从水面舰艇上发射,用以攻击空中目标的导弹。', 196);
INSERT INTO `t_military_term_data` VALUES ('b4836128-6b25-455f-be9f-0d6f2cc5d8aa', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '渡江河战役', '对依托江河障碍进行防御之敌实施的进攻战役。', 59);
INSERT INTO `t_military_term_data` VALUES ('b495322b-7171-418e-b59f-c87da51c2b8c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '压制性电子干扰', '简称压制性干扰。使敌方电子设备接收到的有用信号模糊不清或完全被掩盖的电子干扰。按干扰产生的方法,分为有源压制性干扰和无源压制性干扰。', 41);
INSERT INTO `t_military_term_data` VALUES ('b4b701df-0434-47f6-9580-62e2c4b5eecf', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '测向', '使用有关技术设备测定有源目标的方向和位置。分为无线电测向、光学测向、声响测向和热辐射测向等。', 64);
INSERT INTO `t_military_term_data` VALUES ('b4c9bf7d-dd4a-494b-aad3-3faaa7468f84', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克反应装甲', '亦称坦克爆件装甲。由两层薄金属板夹一层炸药组成的盒式装甲。通常用螺栓固定在坦克主装甲上、主要用以防射弹空心装药战斗部的破坏。当反应装甲被击中时，引起盒内炸药爆炸,使空心装药战斗部的聚能金属射流受到干扰,保护主装甲不被穿透。', 136);
INSERT INTO `t_military_term_data` VALUES ('b4ce1b95-3c64-460d-a423-9ed91d56d4a0', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '磁子午线', '通过地面某点及地球南、北磁极的平面与地球表面的交线。习惯上指某点磁针所指的方向线。地形图的磁子午线,是实地测量若干点的磁场方向和大小的平均值。', 159);
INSERT INTO `t_military_term_data` VALUES ('b4d69e6e-37e7-4bdf-8df9-4321421db7b3', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克拖救', '用牵引车辆和工具将淤陷、损坏等失去行动能力的坦克拖离危险地域或送至修理、装载位置的行动。', 217);
INSERT INTO `t_military_term_data` VALUES ('b4d72c8b-be58-437d-b573-73dc137482fe', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击准度', '亦称平均弹着点偏差。平均弹着点对预期命中点（瞄准点）之间的偏差程度。在垂直靶面上用高低与方向两个偏差表示,在水平靶面上用距离与方向两个偏差表示。', 70);
INSERT INTO `t_military_term_data` VALUES ('b4d95ad6-2513-4b86-aad1-54bd11fa5400', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '自由港', '亦称自由口岸。划在一国海关管制区范围以外的贸易港口。对外国船舶运载的进口商品免征关税或只限于对少数商品征税,并提供装卸、存储、加工和转口运输。其范围,有的仅限于港口或其所在城市的一部分,有的扩大至整个港口及所在城市。自由港大部分划在沿海港口,也有的划在内陆地区。', 105);
INSERT INTO `t_military_term_data` VALUES ('b4dc295e-e2bb-4d7e-ab87-a5274c291fd4', '97a19170-bfac-42c5-9906-1acb187f0654', '野战导航', '保障飞机或直升机在机场区域和常用航线、航路以外区域飞行的导航。通常利用战区各机场和航路上的导航设备及专设的野战导航点组织实施。', 360);
INSERT INTO `t_military_term_data` VALUES ('b4dd2b64-5b83-45ca-a790-c924a20996b6', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '空袭警报', '在敌即将实施空袭时发出的警报。以便及时采取防空措施,避免或减少遭受敌空袭所造成的损失。', 39);
INSERT INTO `t_military_term_data` VALUES ('b4ea601e-27e6-432f-a6a8-f777a4fca114', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '设营队', '预先派往宿营地域进行宿营准备的临时性组织。通常由单独组织实施行军的部队或分队派出、用以了解情况勘察和划分宿营地域,查明和分配水源,准备给养引导本单位进入宿营地域。', 98);
INSERT INTO `t_military_term_data` VALUES ('b4ec03ac-9922-45db-92fd-6838ea5be251', '8a761efd-50a6-4ac8-9913-b7d745104f82', '低伸弹道', '用小于最大射程角的射角射击时所获得的弹道。弹道弯曲度小，落角一般小于20度,适合射击暴露的目标。', 35);
INSERT INTO `t_military_term_data` VALUES ('b4f144b4-b89c-4284-8854-738326aa6665', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '技术侦察', '使用技术装备进行的侦察。如光学侦察、声学侦察和电子侦察等。', 14);
INSERT INTO `t_military_term_data` VALUES ('b4f2addc-fb50-457c-8de3-850c5d31b182', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防经济', '亦称军事经济。保障国家安全、满足军事需求的经济部门和经济活动及与此相适应的经济关系的统称。是国民经济的特殊部分。', 33);
INSERT INTO `t_military_term_data` VALUES ('b4fc44cc-a7a8-4f28-ae60-c26f47fd7f01', 'f0140091-c11a-48c9-8836-8aa94439dac0', '垂直登陆', '在渡海作战中,空运部队到敌岸或其浅近纵深空降着陆的作战行动。', 135);
INSERT INTO `t_military_term_data` VALUES ('b509eb3c-7eb6-43a2-a9e7-1e1eaccd4ed1', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '军事气象情报', '保障军事活动所需的气象方面的情报。主要包括气象观测报告、各种气象通报、天气分析和预报、天气警报、气候分析和预测,以及其他气象报告与资料等。', 71);
INSERT INTO `t_military_term_data` VALUES ('b50f6707-8567-47f2-8650-b4f1e1bbf4b9', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹兵机动作战', '地空导弹兵为寻求战机或避敌空袭,有组织地迅速移动兵力兵器而进行的作战。', 134);
INSERT INTO `t_military_term_data` VALUES ('b5139316-8d14-42b7-9b51-c18b7d977838', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '邓小平新时期军队建设思想', '邓小平在中国社会主义建设的新的历史时期,关于军队建设及有关军事问题的科学理论体系。是邓小平理论的重要组成部分。基本内容包括：当代战争与和平问题的新论断国防建设、军队建设指导思想的战略性转变,以及建设现代化国防和建设现代化、正规化革命军队等一系列重要的理论、方针和原则等。', 12);
INSERT INTO `t_military_term_data` VALUES ('b519a160-1f0a-49c5-bc4d-9d4b87df7c3b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵重叠射击', '数个炮兵连或营的火力重叠在同一目标幅员或阻全线（点）上的射击。各营、连统一对目标中心点决定诸元，按目标幅员或阻击线宽度分配火力。', 183);
INSERT INTO `t_military_term_data` VALUES ('b51f2f7b-357a-459b-9697-70f5a5e24172', '97a19170-bfac-42c5-9906-1acb187f0654', '转场飞行', '飞机或直升机由一个机场起飞到另一个机场降落的飞行。按行动性质,分为战斗转场飞行、训练转场飞行和任务转场飞行；按数量多少,分为单机转场飞行和编队转场飞行。', 216);
INSERT INTO `t_military_term_data` VALUES ('b521189f-b371-4a0c-a616-03ce69dc4c45', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地方时', '以观测地点的子午圈为基准的时间。地球上位于不同经度的观测者,其子午圈不同,同一瞬间的时刻也不同。同一时间计量系统中,两地地方时之差相应于两地经度之差（经度相差1度,地方时相差4分；经度相差l\',地方时相差4秒）。', 208);
INSERT INTO `t_military_term_data` VALUES ('b544393e-5372-4b33-aa63-7800ed7fd695', '916997ee-6728-4c61-9b79-d96960b1dc86', '生物威胁', '敌可能在战争中使用生物武器而构成的威胁。构成生物威胁的主要条件是：敌拥有生物武器的数量和质量,使用生物武器的能力、可能性和准备状况。', 21);
INSERT INTO `t_military_term_data` VALUES ('b544e4a7-c55f-4c45-b503-89713c2ca676', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战计划图', '标绘有作战计划内容的图。通常作为作战计划的附图。', 147);
INSERT INTO `t_military_term_data` VALUES ('b54ed7ad-6f7a-4fb9-be66-14be856a6ccd', '916997ee-6728-4c61-9b79-d96960b1dc86', '沾染浓度', '受染物的单位体积中的放射性活度。常用以表示空气、水等受放射性沾染的情况。单位是贝可／升。', 93);
INSERT INTO `t_military_term_data` VALUES ('b550aa9d-5df5-493e-8da6-c901cab4dd3f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '情况判断', '亦称判断情况。对与遂行作战任务有关的情况进行分析研究井得出结论的思维活动主要包括敌情判断、我情判断地形判断、社情判断和气象水文情况判断等、是指挥员定下决心的前提和基础。', 67);
INSERT INTO `t_military_term_data` VALUES ('b55e2b48-5d94-44ee-8c95-1cfa024822b4', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '小休息', '行军中间隔时间和休息时间均较短的休息。通常徒步行军每小时、摩托化行军每2小时进行一次,按原队形就地休息。', 63);
INSERT INTO `t_military_term_data` VALUES ('b56a40b4-6ac8-4535-b411-ea72ca755e83', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '值班火炮', '担负警戒任务或用以应付突发情况的火炮。值班火炮应人员定位,保持高度警惕,能随时执行射击任务。', 50);
INSERT INTO `t_military_term_data` VALUES ('b575f931-5862-413f-b650-8944632ef7c0', '97a19170-bfac-42c5-9906-1acb187f0654', '空中会合', '不同机种或从不同机场起飞的飞机或直升机为执行共同任务,按预定的方法准时到达指定空域进行编队组合。', 48);
INSERT INTO `t_military_term_data` VALUES ('b57f863f-e7a9-4db4-8c0d-921bd0e7bb52', '878651de-adf5-4c72-9376-9c363b893ff8', '进攻战略', '筹划和指导进攻性战争全局的方略。相对于防御战略而言。', 53);
INSERT INTO `t_military_term_data` VALUES ('b595e4a9-5197-4554-b81e-ca2c27e631ad', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '弹药', '在金属壳体内装有火药、炸药或其他装填物,能对目标起毁伤作用或完成其他任务的装置与物品的统称。包括枪弹、炮弹、手榴弹、枪榴弹、炸弹、火箭弹、水雷、鱼雷、地雷等。礼炮弹、照明弹、信号弹等也属于弹药范畴。', 100);
INSERT INTO `t_military_term_data` VALUES ('b5972109-684f-4551-8008-1081ddbe5065', '98df76fb-4b65-48ff-a56c-4db587327c79', '物资补给', '对部队的物资消耗进行的补充和供给。', 128);
INSERT INTO `t_military_term_data` VALUES ('b59ab798-889e-4bfc-9ec7-9dcfffb439e6', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '预提班长培训', '对准备担任班长职务的士兵进行的培养训练。一般由部队的教导队组织实施。培训内容主要有管理教育、教学法、队列、军事地形学、军兵种知识、专业技术、专业协同和战术基础等。', 55);
INSERT INTO `t_military_term_data` VALUES ('b59fd81f-a00d-404c-b4d0-8971f53c1a6b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '发射轨道', '载有航天器的运载火箭从地面起飞至达到所需的高度和速度,把航天器送入运行轨道之前的飞行轨迹。', 255);
INSERT INTO `t_military_term_data` VALUES ('b5a7ad52-fc9c-47a0-9b10-c36dd81b0183', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程保障指示', '合成军队司令部为组织实施工程保障,对建制和配属的部队下达的指示。主要包括：各部队或分队的工程保障任务,完成任务的要求和时限,工程兵运用,工程器材保障和工程装备技术保障等。', 15);
INSERT INTO `t_military_term_data` VALUES ('b5abd996-010e-4c81-b3d0-b846f08faadf', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '激光告警设备', '用以实时截获、测量、识别敌方激光辐射信号,并能立即发出警报信息的光电对抗设备。通常安装在固定的防卫设施以及坦克、步兵战车和单兵头盔上,用以及时指示激光的种类、方位和强度,以便采取激光防护或激光干扰措施。', 118);
INSERT INTO `t_military_term_data` VALUES ('b5e48614-efdf-4d0e-8bb7-daf304dc3fc0', '97a19170-bfac-42c5-9906-1acb187f0654', '空中护航', '歼击航空兵部队为保障其他航空兵部队在空中遂行任务时不受敌空中袭击而进行的护送飞行。分为全程空中护航和部分地段空中护航。', 113);
INSERT INTO `t_military_term_data` VALUES ('b5f2377a-0bbb-4992-9afe-fb8266190de8', '97a19170-bfac-42c5-9906-1acb187f0654', '强击航空兵', '以强击机为基本装备,主要遂行低空、超低空突击地面、水面目标任务的航空兵。通常用以攻击敌战术纵深和浅近战役纵深内的小型活动目标,并以航空火力直接支援陆军、海军部队作战。', 7);
INSERT INTO `t_military_term_data` VALUES ('b602d0a0-5c6a-4ce6-ab9e-82075954816c', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察专业技术训练', '为使侦察人员掌握侦察专业技能而进行的训练。主要训练内容包括：捕俘技术,攀登,武装泅渡,应用射击,排雷破障,爆破,车辆与船艇驾驶,照相,以及无人驾驶侦察飞机、雷达、观察器材的操作使用等。', 89);
INSERT INTO `t_military_term_data` VALUES ('b6052e46-6d3d-4071-ab4e-9e2541acbb27', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战区独立方向战役', '临时编组的方面军（集团军群）或方向兵力集团,在战区或临时组成的方向指挥所的统一指挥下,在一个战役方向单独实施的战役。', 5);
INSERT INTO `t_military_term_data` VALUES ('b60d1e39-163e-4f58-9af2-f7f2baf5bd4c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上阅兵', '阅兵首长在海上对舰艇部队进行的检阅。通常在国家、军队节日,大型军事演习,接待国家、政府、军队领导人,或其他重大活动时举行。以表示庆祝、致敬、展现成就等。', 406);
INSERT INTO `t_military_term_data` VALUES ('b616bfb6-70ce-49b6-b6ca-b8f6dfb53676', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '高差', '起算面相同的两点间高程之差。', 173);
INSERT INTO `t_military_term_data` VALUES ('b628b1db-ee40-4607-9710-cf00afa18e35', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上防险救生保障', '海军为预防海损事故、援救海上失事或战损的舰艇、飞机及其人员而进行的保障。由海军基地以上司令部组织实施。主要包括：制定海上救援方案,组织海上救援作业,组织舰艇防救器材维修供应,检查、指导舰艇防救工作,清除航道、港湾的沉船和危险物等。', 368);
INSERT INTO `t_military_term_data` VALUES ('b63c68f8-21ac-4190-95f6-b889cf15f60b', '878651de-adf5-4c72-9376-9c363b893ff8', '核战略', '亦称核战争战略。筹划和指导核力量的建设与运用的方略。', 50);
INSERT INTO `t_military_term_data` VALUES ('b644954d-af4f-49a4-8b7b-e17a4918d9d9', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤按方向成梯队部署', '将后勤力量区分为三部分,既成梯次又按方向配置的后勤部署。通常为集团军后勤在作战正面较宽、纵深较大,且受地形、道路限制时采用。', 55);
INSERT INTO `t_military_term_data` VALUES ('b6577780-5137-4bcb-99ac-31d1debbeecd', '06a75831-13a1-4660-870a-455bb445336a', '回令', '回答对方索要口令的对证暗语。', 159);
INSERT INTO `t_military_term_data` VALUES ('b66a02e1-0014-4b56-a774-00d30ddf68be', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '弹药标记', '标示弹药有关情况的记号。常用涂刷在弹药上的文字、数码、代号、色漆和印痕等表示。以表明弹药的种类、型号、构造特点、使用方法和制造批次、出厂年份、制造厂家等。', 102);
INSERT INTO `t_military_term_data` VALUES ('b66fb888-81e8-491d-9def-2b62ff27aa26', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '近战武器', '用以遂行近距离火力打击任务的武器。如步枪、机枪、火箭筒、小口径火炮、反坦克导弹、喷火器等。', 42);
INSERT INTO `t_military_term_data` VALUES ('b6742e9c-f92b-40c2-b748-5b122a07407f', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '定向能技术', '采用高能激光器、高功率微波发生器、高能粒子加速器和能束聚焦控制等手段,在很小的发散角内集中发射巨大能量的技术。军事上可应用于研制定向能武器。', 31);
INSERT INTO `t_military_term_data` VALUES ('b67817f0-7b6b-4d88-9b68-f2475aa3f1f5', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '共同科目训练', '军人均须进行的基础军事科目的训练。主要内容包括共同条令、军事体育、卫生与防护、军事基本知识等。', 71);
INSERT INTO `t_military_term_data` VALUES ('b68127ce-0376-4207-830b-1fd6d7e70dcf', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇', '亦称军舰。配有一定数量的人员、武器或专用装备,主要在海洋进行作战或勤务保障活动的海军船只。通常分为水面舰艇和潜艇。有时也泛指所有的军用船只。', 121);
INSERT INTO `t_military_term_data` VALUES ('b6846c4e-2111-4938-88d4-2fc8f1649667', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂持久度', '染毒区内毒剂对人、畜有毒害作用的持续时间。包括毒剂液滴持久度和毒剂再生云团持久度。一般夏季可持续数小时至数日,冬季可持续数周以上。', 138);
INSERT INTO `t_military_term_data` VALUES ('b692bbb1-44d5-4049-b227-fd53f6d15e04', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报归口', '对各种来源的情报资料进行集中掌握、整理和处理。由情报部门担任。目的是使各种情报资料得到及时综合分析,互相印证、补充,避免多头报告、通报。', 136);
INSERT INTO `t_military_term_data` VALUES ('b69b02f6-eae0-4215-8e82-5c1167887521', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵集结地域', '炮兵临时集中并进行战斗准备的地域。通常由上级指定。一般选择在便于疏散隐蔽、机动和有利于及时展开作战的地方。', 52);
INSERT INTO `t_military_term_data` VALUES ('b6a9d3b3-fda8-45a0-b9e2-a21dbf2e16b7', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '军事气象', '①影响军事活动的大气环境状况。②研究大气环境对战争和其他军事活动影响的规律,以及实施军事气象保障的理论与方法的学科。', 1);
INSERT INTO `t_military_term_data` VALUES ('b6ab0674-8752-450b-a5d1-e992b134b50c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克高射机枪', '安装在坦克顶部的高平两用机枪。主要用于对空射击,亦可对地面目标射击。通常由二炮手或车长操作。', 116);
INSERT INTO `t_military_term_data` VALUES ('b6af6729-fd07-41ad-b754-2cb544136e12', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '反电子侦察', '亦称信号保密。为防止敌方截获并利用己方电子设备发射的电磁信号而采取的措施。目的是使敌方难以获取有价值的情报,不易实施有效的干扰和摧毁。', 92);
INSERT INTO `t_military_term_data` VALUES ('b6c8ebf1-5879-48de-9dc5-2feb85ea937f', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克完好率', '具有规定状态的完好坦克数与在编坦克数的比值。通常用百分比表示。实力统计时,把一、二类坦克作为具有规定状态的完好坦克。', 195);
INSERT INTO `t_military_term_data` VALUES ('b6ccbfb5-a5e8-41a2-ba36-14fe1cb7de89', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹禁射区', '保证己方目标安全,上级按方位给地空导弹火力单位划定的不准发射导弹的区域。', 143);
INSERT INTO `t_military_term_data` VALUES ('b6cea83d-3f01-4481-80cf-917b4527a341', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '近地点', '航天器绕地球运行的椭圆轨道上距地心最近的一点。近地点与地球表面的距离称为近地点高度。为避免航天器过早陨落,轨道近地点高度通常超过180千米。', 231);
INSERT INTO `t_military_term_data` VALUES ('b6d68fb4-f327-4725-a152-adf4a444ba1e', '878651de-adf5-4c72-9376-9c363b893ff8', '战争观', '关于战争问题的根本看法。包括对战争根源、战争本质、战争目的以及战争与相关因素的内在联系等问题的基本观点。', 31);
INSERT INTO `t_military_term_data` VALUES ('b6d834fd-e0c6-4682-a485-91ece77ebcd2', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '导演', '①对军事演习进行的指导与调控活动。②指导与调控军事演习的指挥人员。', 128);
INSERT INTO `t_military_term_data` VALUES ('b6dad9f8-7de9-44ab-b652-c8d06455cc66', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '掩蔽工事', '保障人员、装备物资等隐蔽安全的工事。如掩蔽部、避弹所、掩蔽所和洞库等。', 46);
INSERT INTO `t_military_term_data` VALUES ('b6e07dca-56af-4c95-a2b1-871827757ad8', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '规定任务', '指挥员给所属部队或分队赋予任务、可一次明确,也可逐次明确可以面授也可以文书等形式下达。', 62);
INSERT INTO `t_military_term_data` VALUES ('b6e13536-661e-46ea-9841-0942a2fac9c8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上保交战', '海军兵力保护己方海上交通线的防御作战。是海上防御战的重要样式。', 28);
INSERT INTO `t_military_term_data` VALUES ('b6f17b1d-05a7-45ca-8290-29e2d2399377', '916997ee-6728-4c61-9b79-d96960b1dc86', '航空布洒器', '亦称飞机布洒器。由飞机等航空器携带,用以布洒毒剂的装置。主要用以布洒芥子气、维埃克斯和胶粘沙林等,也可用以布洒刺激剂、植物杀伤剂和生物战剂。', 202);
INSERT INTO `t_military_term_data` VALUES ('b710dd39-c77c-4759-a2fb-1a90a9bfd91d', '8a761efd-50a6-4ac8-9913-b7d745104f82', '常用表尺', '直接瞄准的武器上，对应常用射距的表尺分划。以供紧急战斗情况下来不及装定表尺时，直接瞄准目标下沿进行射击使用。如步、机枪上的常用表尺为300米射程的分划。', 42);
INSERT INTO `t_military_term_data` VALUES ('b7508461-cba4-4e30-b153-b463ef8fa8c8', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机超低空大速度攻击', '直升机在超低空以较大速度的飞行中对敌方目标进行的攻击。通常在敌方有较严密防空火力掩护时采用。', 82);
INSERT INTO `t_military_term_data` VALUES ('b753131e-6bf6-4639-ab99-55e0ea10f14f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '制导', '控制和导引火箭、导弹等,按照预定的弹道或根据目标与导弹等运动信息确定的飞行路线准确到达目标的过程。按制导方式,分为自主制导、遥控制导、寻的制导和复合制导；按传输方式,分为无线电制导和有线电制导；按飞行阶段,分为初制导、中制导和末制导。', 42);
INSERT INTO `t_military_term_data` VALUES ('b77e9775-7cef-4c6d-aa68-3ac0d4d395e5', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '城市进攻战役', '对依托城市市区及其外围地区进行防守之敌实施的进攻战役。', 57);
INSERT INTO `t_military_term_data` VALUES ('b784f692-1762-483f-9ebe-48608fd7e548', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学侦察器材', '发现毒剂并查明毒剂的种类和染毒情况的器材。包括化学观察、报警、侦毒、监测和化验器材等。', 161);
INSERT INTO `t_military_term_data` VALUES ('b7953ba0-860f-4b3e-b833-8a72f5911e23', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机地面效应', '直升机在超低空悬停或超低空低速飞行时,旋翼下气流受地面阻挡折回而使旋翼升力增大的现象。利用地面效应可以提高直升机的载重量。但如果地面效应不能均衡产生,会危及飞行安全。', 18);
INSERT INTO `t_military_term_data` VALUES ('b7b0f28b-74c3-4ab2-917b-0aece1336274', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役分割', '亦称战役割裂。战役中通过突击、穿插、迂回等作战行动,将敌战役部署割裂成若干部分的作战行动。', 114);
INSERT INTO `t_military_term_data` VALUES ('b7b2dcee-5e6b-4364-bdec-65d62c62cec0', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '起爆药', '能在外界小能量作用下发生爆炸,用以引爆其他炸药的炸药。分为单质起爆药和混合起爆药。', 208);
INSERT INTO `t_military_term_data` VALUES ('b7bf507a-56c7-48de-b8d6-07fcece7cdf4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '榴弹炮', '比加浓炮身管短、初速小、弹道较弯曲的火炮。通常身管长为口径的2O～3O倍,初速小于650米／秒射角可在45度以上。主要用以歼灭、压制有生力量和技术兵器,破坏工程设施等。适于对遮蔽物后目标和水平目标射击。', 23);
INSERT INTO `t_military_term_data` VALUES ('b7c93ec0-d976-4870-b00a-598857797e62', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '紧急集合', '军队在紧急情况下迅速进行的集合。通常根据上级指示或经上级批准,由本级最高首长发出紧急号令、命令或信号,按预定的或临时确定的紧急集合方案实施。', 52);
INSERT INTO `t_military_term_data` VALUES ('b7d3b7cb-4a4e-4b00-9638-f7e813af0b31', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教令', '有关作战、训练、武器使用的近似条令和带实验性的规定。如战斗行动组织与实施教令,战斗勤务和战斗保障教令,演习和实弹射击教令等。', 36);
INSERT INTO `t_military_term_data` VALUES ('b7d3c192-c1dd-418c-aeff-37b55865f3d2', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '部队侦察', '各军兵种侦察部队、分队和作战部队、分队进行的侦察。', 8);
INSERT INTO `t_military_term_data` VALUES ('b7e3be7a-b1a9-48d0-a48a-1777ecbb8c91', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇耐波性', '舰艇所具有的在保证安全航行和正常操作使用的前提下,承受最大波浪的性能。是舰艇战术技术性能要素之一。', 330);
INSERT INTO `t_military_term_data` VALUES ('b7e8ae3f-a652-4fe7-97bd-65ddff30f766', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '公路输送', '使用轮式车辆在公路上实施的输送。通常用以输送装备履带车辆及其他重型武器装备的部队。', 75);
INSERT INTO `t_military_term_data` VALUES ('b7e9a4f0-f55e-479f-b0b6-7ebbca90a82c', 'd7132c58-5df3-4b97-919f-58740148b9ca', '背筒', '将便携式地空导弹武器系统由战斗状态转为行军状态的行动过程。', 214);
INSERT INTO `t_military_term_data` VALUES ('b7f535e0-ba9b-46aa-a332-b182bc576fdc', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮指挥仪射击法', '利用高炮射击指挥仪或火控计算机求取射击诸元的射击方法。分为按测距机诸元射击、按炮瞄雷达诸元射击、按综合诸元射击和按固定高度射击。是高炮射击的基本方法。', 170);
INSERT INTO `t_military_term_data` VALUES ('b804c5da-62df-437d-9e15-2814ff985cf8', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '滑行引导', '地面人员对大型直升机或飞机的地面滑行过程进行的指引。主要是引导直升机或飞机滑行到指定位置,并防止其碰撞障碍物等。', 91);
INSERT INTO `t_military_term_data` VALUES ('b80a7b58-9399-4a41-a670-c0f7eaab00d2', '98df76fb-4b65-48ff-a56c-4db587327c79', '军队审计', '军队审计组织依法对军内所有单位的经费收支及有关经济活动独立进行的经济审查和监督。审计的主要内容包括预（决）算、经费收支、基本建设、生产经营、军队国有资产管理等。', 88);
INSERT INTO `t_military_term_data` VALUES ('b80b45a0-04ac-48f4-a140-57d4e0f2084b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '桥梁履带式荷载', '履带式车辆对桥梁的垂直压力。是计算桥跨抗弯强度和桥梁整体承载能力的主要数据。', 296);
INSERT INTO `t_military_term_data` VALUES ('b813177a-a43f-4a71-84e9-c212c14e7d52', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫生防护', '军队为免受或减轻核、化学。牛物武器对人员的伤害而进行的预防和救治的卫勤保障活动。', 210);
INSERT INTO `t_military_term_data` VALUES ('b81e9590-af1b-4392-a6d9-fd7ebee2f3b6', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '嘉奖', '中国人民解放军对表现比较突出,取得优良成绩的人员给子的一种奖励。', 71);
INSERT INTO `t_military_term_data` VALUES ('b821ca74-7902-4cd6-a39d-886656321190', '98df76fb-4b65-48ff-a56c-4db587327c79', '制液站', '军队制备、供应伤病员补充体液所需的大型输液等灭菌制剂的卫勤专业机构。', 218);
INSERT INTO `t_military_term_data` VALUES ('b822158a-8f88-47ec-8cdb-d2dc41ed4d00', '06a75831-13a1-4660-870a-455bb445336a', '指挥所通信枢纽', '为保障指挥员及指挥机关实施指挥而建立的通信枢纽。根据作战指挥需要,通常分别建立基本指挥所、预备指挥所、后方指挥所通信枢纽。必要时建立前进指挥所和技术保障指挥所通信枢纽。', 75);
INSERT INTO `t_military_term_data` VALUES ('b82c7dc0-2dda-40d3-b6f3-28d4d0a66f9e', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报价值', '情报对国家安全和军队作战行动所具有的重要性的程度。情报价值的大小,主要取决于情报的内容、情报来源的可靠性、对情报资料分析判断的准确性和情报传递的时效性等。', 141);
INSERT INTO `t_military_term_data` VALUES ('b830802e-f320-4953-b504-f6ee0254680d', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '作战勤务直升机', '装有机载专用设备,用以执行特定作战勤务的军用直升机的统称。包括侦察与观察直升机、电子对抗直升机、指挥与通信直升机、空中加油直升机等。', 9);
INSERT INTO `t_military_term_data` VALUES ('b8421eae-870d-418b-870f-610e69f90328', 'f0140091-c11a-48c9-8836-8aa94439dac0', '背水击', '趁渡江河湖海进攻之敌刚上陆、背水作战时予以打击的作战行动。', 207);
INSERT INTO `t_military_term_data` VALUES ('b84ac2ff-6f9f-4a64-8b96-4e6c8f472857', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '风寒指数', '低温条件下,人体对寒冷的感觉程度与风速、气温关系的指数。用给定的低温和风速下人体的冷感程度与无风条件下相当的气温值来表示。气温低于15摄氏度时,风速越大,人体感觉越冷。', 92);
INSERT INTO `t_military_term_data` VALUES ('b861a5d3-f758-4ed8-8bf2-1dd782d91434', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战场建设', '在预定战场以修建军事工程、设施为主要内容的战场准备。包括构筑国防工程、修筑交通运输线、改造地形、储备作战物资、编制战场资料等。', 169);
INSERT INTO `t_military_term_data` VALUES ('b86e2276-2c32-4168-80e1-deaf5c149966', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '扫雷火箭弹', '主要用于地雷场中开辟通路的火箭弹。装有串联集团装药、单个集团装药或燃料空气炸药。通常装载于火箭扫雷车上发射。射程为数百米至数千米。', 177);
INSERT INTO `t_military_term_data` VALUES ('b887e661-c7ed-4a7d-91ec-228678b852b8', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机战术训练场', '供直升机进行战斗技术训练和战术训练的场地。通常选设在有山头、山谷等特殊地形的地域。', 103);
INSERT INTO `t_military_term_data` VALUES ('b89783de-d916-4e88-aeea-d78c1644338d', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤转移', '后勤机关、部队或分队转换配置地域的行动。通常分为一次转移、分批转移、交替转移和接替转移等。', 61);
INSERT INTO `t_military_term_data` VALUES ('b8af842d-62d6-4958-a654-b08a1b439e11', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '平原', '地面平坦宽广,海拔一般在 200米以下,高差在50米以下的地区。地面起伏小,人烟稠密,物产丰富,交通发达。军事上展望良好,射界开阔,适于大兵团作战。', 29);
INSERT INTO `t_military_term_data` VALUES ('b8b8170a-442d-4ebe-9ea0-fdef988a76cd', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '测绘', '获取、处理、描述和应用地理信息的各种活动的统称。主要是测定、描述地球的形状、大小、重力场、地表形态及其各种变化,确定地面各种自然要素和天文要素的空间位置及属性,编制成各种地图、大地成果和建立有关信息系统等。', 145);
INSERT INTO `t_military_term_data` VALUES ('b8bb012a-eeae-43e6-b9b4-03fb205b8ae6', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察任务', '侦察部门和侦察部队、分队为获取作战所需情报而承担的工作。通常由上级赋予,有时由侦察部门根据作战任务和上级指示以及对情况掌握的程度确定。', 98);
INSERT INTO `t_military_term_data` VALUES ('b8bd1a28-9fdc-4abc-8190-e4b28538a13c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '地形匹配制导', '利用装在弹上的图形识别装置和遥感技术获得导引信息,将导弹自动引向目标的制导。即将导弹实测地图信息与预先储存在弹上的基准地图信息作比较,确定导弹所在位置与它偏离预定位置的误差,形成导引信号,控制导弹飞回预定的弹道。抗干扰能力强,制导精度高,但设备复杂。常用于巡航导弹的制导。', 52);
INSERT INTO `t_military_term_data` VALUES ('b8c4ee73-607f-4c8b-82f5-e59ea2037d84', 'f0140091-c11a-48c9-8836-8aa94439dac0', '巩固阵地', '对已攻占的敌阵地采取控制措施,防敌反击的行动。包括：调整部署,整修工事,进行伪装,组织防护，补充弹药、油料和给养,建立和完善防御配系等。', 197);
INSERT INTO `t_military_term_data` VALUES ('b8df4bca-bc1f-444b-917f-2b4a5d0041f0', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '想定作业', '依据设想的作战情况研练战役、战斗组织指挥的作业。按作业者所充当的职务,分为集团作业和编组作业；按作业形式,分为现地作业、沙盘作业和图上作业等。', 98);
INSERT INTO `t_military_term_data` VALUES ('b8e95586-21a3-4f69-a7a7-4369941698b7', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '平均海面', '亦称平均海水面。某地（通常为设在沿海的验潮站）一定时间内每小时海面高度的算术平均值。通常作为高程的基准。', 175);
INSERT INTO `t_military_term_data` VALUES ('b8ec9b08-4862-420e-bfe4-14093ac1c6b6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上观察', '以视觉或技术手段对海面。水下及海面上空目标进行的观察。', 55);
INSERT INTO `t_military_term_data` VALUES ('b8f6a02a-2aec-47ab-a201-31123f7080f4', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆器材保障', '为组织实施装甲车辆专用器材供应而进行的保障。主要包括器材的筹措、补给、储备、管理和旧品翻新等。', 226);
INSERT INTO `t_military_term_data` VALUES ('b8f780c9-1d43-4f3b-92c9-44dc9d72b8e6', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '印章管理', '军队有关部门和人员对单位公章和首长名章的管理。主要包括印章的制发、保管、使用、销毁等工作。', 22);
INSERT INTO `t_military_term_data` VALUES ('b8f79ace-ef4f-444e-b08c-0cfb765294b6', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机俯冲攻击', '直升机在俯冲的状态中以机载武器对敌方目标进行的攻击。', 80);
INSERT INTO `t_military_term_data` VALUES ('b8fbc4cc-99cd-4276-941e-1d45551925c6', '98df76fb-4b65-48ff-a56c-4db587327c79', '移动储备', '亦称携运行量。部队携行和运行的物资储备的统称。是战术储备的组成部分。', 115);
INSERT INTO `t_military_term_data` VALUES ('b90793ef-4f48-43e5-8219-d1756546c32d', '97a19170-bfac-42c5-9906-1acb187f0654', '连续突击', '航空兵部队组织多批的兵力,按一定的时间间隔对地面或水面单个目标或有限区域内数个目标进行逐批接连的空中突击。用以在较长时间内压制敌行动,阻止敌恢复已被破坏的目标设施。', 102);
INSERT INTO `t_military_term_data` VALUES ('b9082cec-aa8c-4b85-9eb6-23a29a848763', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '肩炮射击', '无坐力炮炮手以肩扛炮身实施的射击。通常在情况紧急,来不及或不能架炮的情况下采用。', 202);
INSERT INTO `t_military_term_data` VALUES ('b922fc00-81d4-4e2b-b928-e04a11567e49', 'f0140091-c11a-48c9-8836-8aa94439dac0', '坑道战斗', '夺取或扼守坑道的战斗行动。包括夺取坑道口、肃清坑道内的敌人或坚守坑道、依托坑道出击和配合上级实施反击。', 15);
INSERT INTO `t_military_term_data` VALUES ('b9255b5f-7f10-4d94-8d05-6478b54d485f', '06a75831-13a1-4660-870a-455bb445336a', '电话机', '电话通信中实现话音信号与电信号相互转换的用户设备。有磁石式、共电式和自动式3种。一般由送话器、受话器和振铃器等组成。野战用的电话机,体积小、重量轻、携带方便,具有防潮湿、耐寒暑等性能。', 198);
INSERT INTO `t_military_term_data` VALUES ('b92733bd-490a-446a-9c35-bf4a14d01956', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射控制室（间）', '控制导弹测试和发射的地面或地下的工作间。主要装有测试发射控制设备和监控设备等。', 72);
INSERT INTO `t_military_term_data` VALUES ('b94f099f-6bdf-489f-9c41-b18adfc622cc', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '太空战场', '敌对双方进行天战活动的空间。主要指外层空间,也包括相关的空域、地域或海域。', 167);
INSERT INTO `t_military_term_data` VALUES ('b95a6577-45bf-4fcc-af23-90d27d34d8cf', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫生勤务', '简称卫勤。军队运用医学理论、技术、装备等为其成员健康服务的专业勤务。', 181);
INSERT INTO `t_military_term_data` VALUES ('b963ac4d-2190-409c-8103-6af76dc80be1', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报站', '由情报机关派出的,组织侦察和接收情报的基层机构。通常设置在边防、海防地区,战时亦可根据需要设置在预定作战地区。主要任务是调查搜集当面情况,开展群众性侦察工作。', 73);
INSERT INTO `t_military_term_data` VALUES ('b968b60b-0e70-4396-b295-f86011e355c8', '97a19170-bfac-42c5-9906-1acb187f0654', '特技飞行', '飞行员使用特殊的驾驶技能,操纵飞机或直升机所作的高难度的飞行。分为简单特技飞行、复杂特技飞行和高级特技飞行。', 215);
INSERT INTO `t_military_term_data` VALUES ('b973256e-4193-45be-82d4-bd4a88b36061', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核武器威力', '核武器爆炸时所释放的总能量、这些能量分配到各种杀伤破坏因素的份额,随核武器种类的不同和爆炸高度的差异而不同。', 88);
INSERT INTO `t_military_term_data` VALUES ('b976f9d6-c9d1-4bca-a463-0e9409d82e5c', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '全天候', '包括昼、夜间各种天气、气候条件在内的大气环境状况。通常用以形容能适应最低气象条件的某些性能先进的武器装备或技术高超的人员。如全天候飞行员,是指能在所规定的昼间简单、昼间复杂、夜间简单、夜间复杂等4种气象条件下飞行的飞行员。', 84);
INSERT INTO `t_military_term_data` VALUES ('b986bcf3-1683-42b9-907d-35b546e6c538', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防力量', ' 国家在国防领域内所拥有的各种力量的统称。包括国防实力和国防潜力。武装力量是国防力量的主体。', 7);
INSERT INTO `t_military_term_data` VALUES ('b993c8cc-df33-4a51-84d1-55c1018a0358', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '军事演习', '简称演习。在想定情况诱导下进行的作战指挥和行动的演练。是部队在完成理论学习和基础训练之后实施的近似实战的综合性训练,军事训练的高级阶段。按规模,分为战术演习、战役演习；按对象,分为首长机关演习和实兵演习；按形式,分为室内演习和野外演习、单方演习和对抗演习、实弹演习和非实弹演习、分段演习和综合演习；按目的,分为示范性演习、试验（研究）性演习和检验（考核）性演习。', 111);
INSERT INTO `t_military_term_data` VALUES ('b99ffaa9-7be6-46cd-bb6c-f6fa9e45c286', '06a75831-13a1-4660-870a-455bb445336a', '通信防护', '为预防通信联络遭受敌方干扰和破坏而采取的措施。主要包括：无线电通信反侦察、反干扰,有线电通信防窃听,防敌核、化学、生物等武器对通信人员和设施的杀伤与破坏,构筑防护工事,实施伪装及警戒等。', 55);
INSERT INTO `t_military_term_data` VALUES ('b9a15165-015c-4e54-904b-3593521d6379', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '太阳同步轨道', '轨道平面绕地球自转轴旋转的方向与地球公转方向大致相同、旋转角速度等于地球公转平均角速度（0.9856度／天或360度／年）的人造地球卫星轨道。在这种轨道上运行的卫星,以相同方向经过同一纬度的当地时间是相同的。气象卫星、地球资源卫星常采用这种轨道。', 238);
INSERT INTO `t_military_term_data` VALUES ('b9b0136e-1099-4005-a6b0-de3ecfc413d5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '码头补给', '对停靠码头的舰艇实施的物资补给。是舰艇物资保障的基本方式。补给的物资包括油料、淡水、食品、军械、弹药、医药用品和维修器材等。', 349);
INSERT INTO `t_military_term_data` VALUES ('b9cbf333-2a1b-4081-bfd1-6cdf69755c0e', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军械库', '存放军械物资的场所及其管理机构。按所存物资,分为单一军械库和综合军械库；按供给关系、分为基地军械库和部队军械库。主要负责军械物资的接收、保管和发放,以及与此有关的技术管理和安全工作。', 106);
INSERT INTO `t_military_term_data` VALUES ('b9cebe97-a3bb-46e7-851c-f3ad9e0fcff0', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '宿营', '部队离开常驻营房遂行各种任务中的临时住宿。分为合营和露营。根据情况,也可采取两者相结合的方式进行宿营。', 92);
INSERT INTO `t_military_term_data` VALUES ('b9d15b50-7ba7-4b41-9875-9df086514ee0', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '登陆突击', '亦称突击上陆。登陆兵在舰炮和航空兵火力支援下,夺占登陆场的作战行动。', 71);
INSERT INTO `t_military_term_data` VALUES ('b9d9a55b-6bbd-41f0-966f-1883cb836b68', '8a761efd-50a6-4ac8-9913-b7d745104f82', '高低射界', '射击武器由于结构限制，火身轴线在铅里面上能俯仰的角度范围。', 86);
INSERT INTO `t_military_term_data` VALUES ('b9dd1ea7-897a-4761-9faa-49d94e1a91cc', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达信号模拟器', '能模仿一种或多种雷达信号的电子对抗训练设备。可对雷达的各种信号参数进行模拟。主要用以训练电子对抗装备的操作人员。', 143);
INSERT INTO `t_military_term_data` VALUES ('b9e3f8da-883c-4ce7-a8bd-4b3594627408', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上袭击战', '海军兵力以突袭方式对敌实施的进攻作战。是海上进攻战的重要样式。袭击的主要目标为敌舰艇编队、登陆输送队、护航运输队、海军基地等。', 25);
INSERT INTO `t_military_term_data` VALUES ('b9f49074-52a0-45b8-b190-bfef6fccaf03', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹火力转移', '地空导弹火力单位不变换发射阵地而将火力由一个射击目标转向另一个射击目标的行动。有逐批转移火力、一次转移火力和越批转移火力。在同一防区内配置有两个或两个以上的火力单位，且都能满足射击条件要求时,也可交替转移火力。', 202);
INSERT INTO `t_military_term_data` VALUES ('b9faadb8-e8b4-462f-a747-94d0b18b70fb', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮标准', '火炮弹药消耗量的计算单位。炮种不同,一个炮标准所规定的消耗弹数也不尽相同。线膛炮、迫击炮的一个炮标准通常为其一个弹药基数的1／10,火箭炮一个炮标准通常为其一个弹药基数的1／5。', 239);
INSERT INTO `t_military_term_data` VALUES ('ba021167-2e0c-4de5-9448-74b5263d0be6', '916997ee-6728-4c61-9b79-d96960b1dc86', '发烟装备', '使用发烟剂生成烟幕的装备。包括发烟弹药、发烟车、发烟器、发烟罐等。在战斗中用以构成遮蔽、迷盲、干扰和信号烟幕。', 239);
INSERT INTO `t_military_term_data` VALUES ('ba0390c8-a7d7-4674-9d1b-27da1f9e99c4', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '水库', '建有坝闸堤堰等水工建筑物拦蓄河川水流而形成的人工湖。蓄水容积大于10万立方米的人工湖称水库,蓄水容积小于10万立方米的人工湖称池塘。水库具有调节河川径流、防洪、供水、灌溉、发电、渔业、航运、改善环境等作用。战时可能被破坏,造成水障。', 75);
INSERT INTO `t_military_term_data` VALUES ('ba043812-a44c-4d1f-970a-fa39ff7e47a0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮战', '敌对双方炮兵相互射击的作战行动。用以歼灭或压制敌方炮兵,夺取或保持对敌炮兵火力的优势。', 82);
INSERT INTO `t_military_term_data` VALUES ('ba1065c7-8ebc-4a42-98b9-b894c0ddf82e', 'd7132c58-5df3-4b97-919f-58740148b9ca', '空中目标提前位置', '高炮发射的弹丸与空中运动目标预定相遇的位置。由防空武器系统的射击诸元计算装置自动计算测定。', 164);
INSERT INTO `t_military_term_data` VALUES ('ba1f356b-9304-4b6a-aade-649876f2470f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '驻防', '军队在一定的区域较长期地驻扎防守。', 422);
INSERT INTO `t_military_term_data` VALUES ('ba1f8ba3-c1f4-4b72-bf25-63d95b51f13c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '机械布雷车', '利用机械装置实施布雷的专用车辆。按行驶方式,分为拖式布雷车和自行布雷车；按布雷方式,分为放置（包括埋设）式布雷车和抛撒式布雷车；按布雷作业自动化程度，分为自动布雷车和半自动布雷车。', 164);
INSERT INTO `t_military_term_data` VALUES ('ba24186e-83fb-4864-b4fd-0b7e415b52f7', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工事定位', '根据工事配置、地形和战术技术要求,在现地用基准桩确定工事具体位置和方向的作业。', 80);
INSERT INTO `t_military_term_data` VALUES ('ba2748c5-36ba-49bc-8a85-b8c487ef62df', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '红外告警', '实时截获和识别来袭目标的红外辐射能并对具有威胁的目标立即报警的过程。广泛用了对来袭的导弹、炮弹、飞机等武器和入侵人员的警戒。', 29);
INSERT INTO `t_military_term_data` VALUES ('ba3a967c-ebb1-4669-b482-78e0d91e178c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '集束式多弹头', '亦称霸弹式多弹头。导弹的母弹头和子弹头都没有制导装置的导弹多弹头。当母弹头飞至预定点时,一次释放全部子弹头,同时攻击面目标。在相同当量的条件下,可提高对面目标的毁伤效果。', 25);
INSERT INTO `t_military_term_data` VALUES ('ba3bad4d-3f33-4886-9c49-34cf8459c099', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '实力统计', '对一定时限内军队或军队某一组织实有的建制单位、人员、武器装备等的数量和质量的统计。包括军事实力统计、政治实力统计、武器装备实力统计、后勤实力统计等。', 86);
INSERT INTO `t_military_term_data` VALUES ('ba4099ac-628c-4af4-970a-35e79d7cbe67', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事学术史', '关于军事学术的产生及其发展的历史。是军事历史学的重要研究内容。', 38);
INSERT INTO `t_military_term_data` VALUES ('ba449724-b876-4a66-bd4b-efa4e0ca49f0', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '箔条', '由金属箔、金属丝或镀覆金属的介质制成,按电磁波波长切割成一定形状,能强烈反射电磁波的无源干扰器材。主要有干扰丝、干扰片、干扰带（绳）等。其长度通常为被干扰雷达波长的一半。使用时,由装在飞机、舰艇和地面上的投放装置或火箭、火炮投射到空中。主要用以干扰雷达。', 135);
INSERT INTO `t_military_term_data` VALUES ('ba45b9b9-6d34-4f26-b571-e5ca6d5061d8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '岸对潜通信', '岸上指挥所对海上潜艇的通信。主要使用甚长波、超长波通信手段对潜艇进行定时、单向发信,并全时接收潜艇的快速短波发信；也可通过卫星进行双向通信。', 359);
INSERT INTO `t_military_term_data` VALUES ('ba470f33-d8f9-4851-b015-1bfd4f35003b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇备战备航', '舰艇临出航前的准备活动。要求舰员在规定时限内,按部署完成对舰艇及其装备的检查准备工作,使之处于备用状态。紧急备战备航须发出战斗警报,并按紧急使用规定,在最短时间内完成对武器装备和技术器材的准备。', 286);
INSERT INTO `t_military_term_data` VALUES ('ba5765c1-f3e6-4011-9bf5-235ed331a15e', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮有效射击半径', '亦称有效火力半径。高炮有效射击范围在某高度上的水平断面的半径。随目标高度的增大而减小。在计算高炮连的火力范围时,通常100毫米高炮连的有效火力半径取9000米,57毫米高炮连取4000米,37毫米高炮连取2500米,25毫米高炮连取2000米。', 147);
INSERT INTO `t_military_term_data` VALUES ('ba657291-edb1-4503-bff1-37f63ffddeec', '98df76fb-4b65-48ff-a56c-4db587327c79', '物资供应', '亦称物资供给。军队后勤机构为部队提供各类物资的活动。包括物资的筹措、储备、补给和管理等。', 89);
INSERT INTO `t_military_term_data` VALUES ('ba660449-3bbb-4ab0-bb28-d5d4fb3463c4', '916997ee-6728-4c61-9b79-d96960b1dc86', '侦毒器', '用抽气装置抽气使侦毒管显色为侦毒特征的侦毒器材。用以发现空气、地面、装备等的染毒情况,查明毒剂种类,并概略测定空气的染毒浓度。', 164);
INSERT INTO `t_military_term_data` VALUES ('ba6b6f99-5f5f-4157-99a6-076831aebf5b', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军事科研机关', '研究军事理论科学或军事技术科学的机构。', 9);
INSERT INTO `t_military_term_data` VALUES ('ba76b4f4-97e9-4d2d-8ff3-a9df30996373', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察船', '装备有侦察技术设备,用以进行水上技术侦察的专用船舶。通常装有侦察声纳、侦察雷达、光学侦察器材、水文测量仪器和无线电技术侦察设备,有的还设有情况处理和分析系统。', 120);
INSERT INTO `t_military_term_data` VALUES ('ba854ece-ef4e-4de6-a7c9-be7e95a5d125', '8a761efd-50a6-4ac8-9913-b7d745104f82', '微声手枪', '射击时只有微弱的声响、火焰和烟雾的手枪。在枪管前段安有消声、消焰和消烟装置。与一般手枪相比,其体积和重量较大,有效的程较近。', 157);
INSERT INTO `t_military_term_data` VALUES ('ba89ea49-466e-4bc7-ba69-4e42d05cc3ff', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '编队着陆', '两架以上编队飞行的直升机或飞机按编队队形同时降落于地面的着陆。', 45);
INSERT INTO `t_military_term_data` VALUES ('ba8e7720-4047-440b-91a4-78338bff78f1', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '多光谱照相机', '对同一景物拍摄多幅不同光谱影像的照相机。在近紫外、可见光至近红外光谱范围，可分为4－9个波段。多光谱图像经过处理后,比通常的黑白或彩色图像能提供良多的信息，还可识别伪装的目标。军事上用于航空和航天侦察等。', 77);
INSERT INTO `t_military_term_data` VALUES ('ba9f15fa-5612-4b84-b53b-7e1c8cc2c08a', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '线性规划', '研究在线性等式或不等式的约束条件下,使线性目标函数达到最大值或最小值的数学规划。通常在解决兵力、兵器的分配和物资的调配、运输等问题时,用以寻找使用效率较高和代价较小的方案。', 183);
INSERT INTO `t_military_term_data` VALUES ('baa83110-384d-4a41-a82d-c0f444e23523', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '卫戍部队', '专门担负首都或其他重要地区的保卫和戍守任务的部队。', 52);
INSERT INTO `t_military_term_data` VALUES ('babaaba2-23cd-472d-a5cc-6ce82f77c39e', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机机降集结场', '空降作战准备中,遂行机降任务的运输直升机和搭乘直升机的部队或分队临时集中并进行机降准备的场地。', 97);
INSERT INTO `t_military_term_data` VALUES ('babd53c9-909f-4607-b849-2c08cd0d1931', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军工程作业船', '亦称工程船。陆军编配的专门从事水上、水下工程作业的船。主要包括起重船、挖泥船、水线船、潜水工作船、修理工程船和测量船等。', 331);
INSERT INTO `t_military_term_data` VALUES ('bac4b2c3-d356-421e-81be-cedd97391c48', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '国际日期变更线', '简称日界线。在经度180度子午线或其附近划定的一条日期界线。1884年国际经度会议决定,将经度180度的子午线作为日期变更线。向东航行过这一线时须减去一天,向西航行过这一线时须增加一天。由于国家政区关系,日界线并不严格在180度子午线上,成折线在海洋上通过。', 215);
INSERT INTO `t_military_term_data` VALUES ('bacb71c1-4a5d-4241-832e-0c1263b6242e', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境冲突', '相邻国家在边境地区发生的对抗性暴力行动。属于严重的边境事件。', 98);
INSERT INTO `t_military_term_data` VALUES ('bace9600-32df-4ce6-9c19-bc90dffdf4fb', '878651de-adf5-4c72-9376-9c363b893ff8', '战略指挥', '军事统帅及军队统帅机构对战略行动实施的组织领导活动。是作战指挥的最高层次。', 74);
INSERT INTO `t_military_term_data` VALUES ('baf7064c-be96-4735-84aa-5a3689e01f2b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '反坦克侧甲地雷', '简称反侧甲雷。主要用以炸穿坦克侧甲,破坏内部设备并杀伤乘员的防坦克地雷。配用触发或近炸引信。通常设于道路两侧,作用距离可达百米。', 142);
INSERT INTO `t_military_term_data` VALUES ('bafe7272-0a2f-47b9-9a2a-0e33370e113a', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂', '亦称军用毒剂。军事行动中以毒害作用杀伤人、畜的化学物质。通常装填于各种弹药和布洒器内,以液滴、蒸气、气溶胶等状态使空气、地面、水源和物体染毒,引起人、畜中毒。按毒害作用,分为神经性毒剂、糜烂性毒剂、全身中毒性毒剂、窒息性毒剂和失能性毒剂；接杀伤作用持续时间,分为暂时性毒剂和持久性毒剂；接杀伤作用的效果,分为致死性毒剂和非致死性毒剂。', 203);
INSERT INTO `t_military_term_data` VALUES ('baff2c32-8944-4bdb-9f56-e538a616fbe8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '重点守备', '在重要的方向或地域有重点地进行防守和戒备。', 414);
INSERT INTO `t_military_term_data` VALUES ('bb1179a3-b5e3-4546-b4c9-bf6b38ad72aa', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '干扰报告', '雷达、无线电通信等部队向上级反映电子设备受干扰情况的报告。内容包括：干扰的种类、样式、强度、效果、起止时间,受干扰的频率范围,受影响的电子设备的类型和位置,采取的反干扰措施和反干扰效果等。', 102);
INSERT INTO `t_military_term_data` VALUES ('bb128a36-c540-4958-9c49-41d21445bbba', '97a19170-bfac-42c5-9906-1acb187f0654', '升空疏散', '航空兵部队为避免飞机或直升机被敌空袭兵器摧毁在地面上而实施起飞离场的分散转移行动。', 118);
INSERT INTO `t_military_term_data` VALUES ('bb142ff0-93ff-4bc3-b6ab-91f6785d2c18', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战场传感器', '探测地面目标运动所产生的声响、震动或引起地球磁场、红外线辐射场等物理量变化的技术侦察器材。常用的有音响传感器、震动传感器、磁传感器、压力传感器、电磁传感器和红外线传感器等。', 123);
INSERT INTO `t_military_term_data` VALUES ('bb16f54d-cab9-4879-b169-2d6f64e4733d', '98df76fb-4b65-48ff-a56c-4db587327c79', '野炊', '在野外用制式炊具或就便器材制作热食和熟食的炊事活动。', 146);
INSERT INTO `t_military_term_data` VALUES ('bb1928c8-bdeb-4d5c-beee-197cf61ec91e', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达对抗装备', '用于对敌方雷达进行侦察、干扰的电子对抗装备。包括雷达对抗侦察设备和雷达干扰设备（器材）。', 111);
INSERT INTO `t_military_term_data` VALUES ('bb464100-0d5e-4983-8b0e-a47643c27464', '916997ee-6728-4c61-9b79-d96960b1dc86', '消毒杀虫车', '在生物战剂污染区进行大规模消毒与杀虫作业的专用车辆。平时也可用于卫生防疫工作。', 196);
INSERT INTO `t_military_term_data` VALUES ('bb4a6cbc-8c39-48ef-98a1-40416fe170eb', '97a19170-bfac-42c5-9906-1acb187f0654', '空军合同训练', '空军诸兵种部队或分队为提高合同作战能力而进行的训练。包括空军合同战役训练和空军合同战术训练。', 199);
INSERT INTO `t_military_term_data` VALUES ('bb4a960e-716f-43be-b296-f4e4def9c0d4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵部署', '遂行作战任务而对炮兵兵力进行的区分、编组和配置。通常根据炮兵的任务、数量、武器性能、敌情和地形等决定。', 39);
INSERT INTO `t_military_term_data` VALUES ('bb503deb-b9ba-4a23-b0a4-33fde3ac0558', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '压制兵器', '主要用于对地面、水面的面状目标实施压制射击的各种兵器的统称。包括各种压制火炮、火箭炮和地地战役战术导弹等。', 14);
INSERT INTO `t_military_term_data` VALUES ('bb57e691-4eab-459a-9177-a8e064ce411e', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '武装警察部队', '简称武警部队。主要担负国内安全保卫任务的武装组织。中国人民武装警察部队是中华人民共和国武装力量的组成部分,其使命是维护国家主权和尊严,维护社会治安,保护国家重要目标和人民生命财产安全等。由内卫、边防、消防部队,以及交通、水电、黄金、森林等警察部队组成。', 123);
INSERT INTO `t_military_term_data` VALUES ('bb79fda2-9994-41f5-a9f0-c3d0a1067235', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '连队军人委员会', '中国人民解放军为保障军人充分行使民主权利,在连队或相当于连级的基层单位设立的群众性组织。由连军人大会选举产生。在党支部的领导和连长、政治指导员的指导下进行工作。', 10);
INSERT INTO `t_military_term_data` VALUES ('bb7fc527-0a14-41e3-b0a3-6f9e218c7657', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇战位', '舰艇战斗部位的简称。舰艇上设立的最低的一级战斗组织。通常由一至数人组成。两人以上的战位设战位长。受中心战位或舰艇部门、舰艇指挥所指挥。', 14);
INSERT INTO `t_military_term_data` VALUES ('bb7ff3a7-3970-482d-8a5b-e77bca9ef6c0', '916997ee-6728-4c61-9b79-d96960b1dc86', '辐射仪', '测量核爆炸剩余核辐射Y照射量率（吸收剂量率）和放射性活度的辐射剂量探测仪器。分为便携式、车载式、舰载式和机载式等辐射仪。', 155);
INSERT INTO `t_military_term_data` VALUES ('bb889a39-b336-41e8-978b-327720f76cbf', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '石林', '岩柱林立、形体高大陡峭的一种喀斯特地貌。相对高度一般在20米左右。如中国云南省的路南石林。', 33);
INSERT INTO `t_military_term_data` VALUES ('bb97ad5a-21bd-4291-b432-0c23900c5783', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备完好率', '武器装备能随时遂行作战任务的完好数与实有数的比值。通常用百分比表示。主要用以衡量武器装备的技术状况和管理水平,以及武器装备对作战、训练、执勤的可能保障程度。', 111);
INSERT INTO `t_military_term_data` VALUES ('bb984449-b00f-4363-8f8a-2ea8221689cc', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军队总定额', '国家规定的军队总人数的限额。根据国防需要和政治、经济、人口、地理环境等因素确定。', 59);
INSERT INTO `t_military_term_data` VALUES ('bb9abe8b-cfad-4378-9061-862111080ae7', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '回收舱', '航天器返回时从返回舱分离出来在地面或水面回收的舱段或容器。回收舱内可以乘坐航天员、装载拍摄的胶片、生物试样以及其他样品等。', 282);
INSERT INTO `t_military_term_data` VALUES ('bb9fd13a-41b4-4b86-b549-095178b2ce0d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '空中目标航路', '空中目标飞行的路线。', 161);
INSERT INTO `t_military_term_data` VALUES ('bba1f98b-0e50-44a8-9b10-eab5b259b9c2', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '发射勤务保障', '航天器发射场为保证发射试验的顺利实施而提供的技术勤务保障。包括通信保障、气象保障、计量保障、大地测量保障等。', 249);
INSERT INTO `t_military_term_data` VALUES ('bba8f197-f5b0-4054-a0db-beceb35f740b', '878651de-adf5-4c72-9376-9c363b893ff8', '战略佯动', '为隐蔽战略企图和行动而采取的隐真示假的军事行动。是战略伪装的一种方式。', 103);
INSERT INTO `t_military_term_data` VALUES ('bbb37402-b3c2-429a-b8f0-d3e34d4a3cd5', '06a75831-13a1-4660-870a-455bb445336a', '通信网络技术管理中心', '简称网管中心。担负通信网络技术管理工作的通信机构。主要任务是：负责对各级通信网络的技术管理和监测,对网内的通信台、站进行技术指导,组织巡修通信机线设备等。', 4);
INSERT INTO `t_military_term_data` VALUES ('bbb3c398-3cae-4657-866d-207f8628bca0', '916997ee-6728-4c61-9b79-d96960b1dc86', '发烟器', '亦称烟幕施放器。利用机械发烟装置施放烟幕的发烟装备。按形成烟幕的方式,分为喷洒式发烟器和受热蒸发式发烟器。', 241);
INSERT INTO `t_military_term_data` VALUES ('bbc2c3a8-b572-417a-b792-4d462fad0604', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军路线', '行军的起止地点与所经过地点的连线。通常由上级指挥员指定,有时也可由本级指挥员根据敌情、地形、道路、任务、行军方式等情况确定。', 53);
INSERT INTO `t_military_term_data` VALUES ('bbc76ae0-c701-4700-bd99-9252fc31433e', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '退兵', '军队在规定的时限内,把不符合服现役条件的新兵退回原征兵机关的工作。', 150);
INSERT INTO `t_military_term_data` VALUES ('bbcc3393-1ef1-4add-af47-cbd75a940657', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术后方', '兵团或部队配置后方机构的地域。是战斗中物资补给、医疗救护、技术修理等的依托。', 38);
INSERT INTO `t_military_term_data` VALUES ('bbf1f502-c598-4529-b58a-55d193fe5216', '878651de-adf5-4c72-9376-9c363b893ff8', '民族解放战争', '被压迫民族为争取民族独立和解放而进行的正义战争。', 29);
INSERT INTO `t_military_term_data` VALUES ('bbf7c31d-220a-4915-a01b-a389b36ead87', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '阔叶林', '阔叶树为主的森林。分为常绿阔叶林和落叶阔叶林。一般叶面较宽,树冠较大。', 91);
INSERT INTO `t_military_term_data` VALUES ('bc004f7e-fb33-41d5-a979-88185283e59b', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教养一致', '日常作风养成与教育、训练的内容和要求相一致。是军事训练的基本原则之一。', 5);
INSERT INTO `t_military_term_data` VALUES ('bc09478c-d5a9-432e-b31a-ac18538f0ba4', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '基本指挥所', '亦简称基指、实施指挥的主要指挥所通常正职首长、参谋长、司令部主要人员和政治、后勤机关的有关人员以及加强的军兵种部队的有关人员组成。配备有较强的通信或指挥自动化工具以及工程、防化、警卫等保障力量。', 47);
INSERT INTO `t_military_term_data` VALUES ('bc1b459c-5617-41d3-aa26-87f949908fc4', '97a19170-bfac-42c5-9906-1acb187f0654', '听召唤出动', '航空兵部队在支援陆军、海军部队作战中,按照协同计划做好战斗准备,听从合成军队指挥所的出动命令而组织的战斗出动。', 128);
INSERT INTO `t_military_term_data` VALUES ('bc2c838a-ed4f-49bb-9caa-0bff7a3e56a2', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '疏散配置', '在一定战役、战术地幅内对兵力兵器所作的间隔较大、密度较小的配置。', 103);
INSERT INTO `t_military_term_data` VALUES ('bc3265c4-a945-4ea7-8037-d16fbd675330', '31f4a446-5b98-4873-9d53-310d97125b07', '核爆炸电磁脉冲探测', '对核爆炸产生的电磁脉冲进行的探测。主要用以确定核爆炸的时间、位置和当量等。', 175);
INSERT INTO `t_military_term_data` VALUES ('bc359dd0-a88e-4cdc-a21e-4474e6457a0e', '31f4a446-5b98-4873-9d53-310d97125b07', '核爆炸探测', '对核爆炸产生的次声波、地震波、电磁脉冲以及各种射线进行的探测。主要用以判定核爆炸的时间、位置、当量、爆高和核效应等。', 172);
INSERT INTO `t_military_term_data` VALUES ('bc371491-e7be-48b1-b417-58eca8fc49e7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战场起义', '①在中国人民革命战争中,敌方军队或其人员在战场上携带武器叛离其所从属的集团,投向并参加中国人民武装力量的行为。②泛指战争中非正义一方的军队或其人员,在战场上携带武器叛离其所从属的集团,投向正义一方并反戈的行为。', 390);
INSERT INTO `t_military_term_data` VALUES ('bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '0', '陆军航空兵', NULL, 4);
INSERT INTO `t_military_term_data` VALUES ('bc3fe5c1-22e3-45a6-958e-60052ff5ba71', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '单舰（艇）攻击', '单艘舰艇单独对敌实施的海上攻击、是潜艇攻击的基本方法。', 85);
INSERT INTO `t_military_term_data` VALUES ('bc44d696-611e-4712-a8ea-8571c044817c', 'f0140091-c11a-48c9-8836-8aa94439dac0', '步兵战术', '步兵进行战斗的方法。分为机械化步兵战术、摩托化步兵战术和徒步步兵战术。是陆军战术的组成部分。主要内容包括步兵战斗的基本原则以及兵力部署、战斗指挥、协同动作、战斗行动的方法和各种保障措施等。', 26);
INSERT INTO `t_military_term_data` VALUES ('bc4913ed-7949-4d99-9342-0402771ed719', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '退伍', '中国人民解放军的义务兵退出现役。', 158);
INSERT INTO `t_military_term_data` VALUES ('bc49a0de-6b1c-4aa7-a9a3-e2dad728c72b', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高射炮兵部队', '简称高炮部队。高射炮兵旅、团的统称。独立高炮营一般亦被称作高炮部队。', 6);
INSERT INTO `t_military_term_data` VALUES ('bc568824-98dd-4fbf-ad9a-a7e4e5d0de21', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '分区防守', '担负防御作战任务的部队按划分的防御地区进行的防守。多在城市防御作战中采用。', 128);
INSERT INTO `t_military_term_data` VALUES ('bc57c6ee-23ed-4909-a0b2-4630bb4b2525', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击死界', '高炮对空中目标射击时,在射击范围内因追随不上目标而求不出射击诸元或射击不到的空间。分为圆锥死界范围和瞄准死界范围。随射击高度的增加而增大。', 152);
INSERT INTO `t_military_term_data` VALUES ('bc5c695d-32d8-4494-b041-d49b4debc1e2', '97a19170-bfac-42c5-9906-1acb187f0654', '隐身飞机', '亦称隐形飞机。广泛采用减弱自身的辐射和反射信息的技术,不易被探测系统发现的飞机。具有较强的隐蔽性、生存力和较高的作战效能。', 278);
INSERT INTO `t_military_term_data` VALUES ('bc6929e0-7e67-44a4-8283-886d4ed35ec2', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机', '有动力装置,主要靠机翼产生气动升力升空的航空器。通常由机身、机翼、尾翼、起落装置和动力装置等组成。按用途,分为军用飞机和民用飞机；按动力,分为喷气式飞机、螺旋桨式飞机；按起落场所,分为陆上飞机、水上飞机。水陆两用飞机、舰载飞机等。', 263);
INSERT INTO `t_military_term_data` VALUES ('bc6f0d6c-707c-4f19-9f4b-c4af1bcf3c51', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '观察勤务', '组织实施观察的日常工作。主要包括：观察所和观察哨的组成、任务、配置,工事构筑,通信联络,观察器材的维修保养,观察所得情况的登记、报告,换班和转移等。', 111);
INSERT INTO `t_military_term_data` VALUES ('bc7c7cd6-6cbe-471e-85a5-2ce48976c1b3', 'd7132c58-5df3-4b97-919f-58740148b9ca', '机动防空', '亦称机动掩护。防空兵以适时变换发射阵地和快速转移等方法对预定地域或地段实施的对空掩护。通常与目标防空结合使用。', 71);
INSERT INTO `t_military_term_data` VALUES ('bc7e0393-de36-4006-a4e5-feea6174e1b2', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反潜封锁区', '综合使用阵地防潜器材和机动反潜兵力构成一定的纵深和宽度的防潜配系,以阻止敌潜艇通过的海区。通常设置在敌潜艇进入作战海区的必经海峡或航道。', 98);
INSERT INTO `t_military_term_data` VALUES ('bc88d3c9-ac81-46df-9f40-e2afa75dc1a9', '916997ee-6728-4c61-9b79-d96960b1dc86', '遮蔽烟幕', '施放在敌对双方之间或己方配置地域内,以遮蔽己方为主要目的的烟幕。主要用以遮蔽己方的作战行动、配置地域、交通枢纽、机场、基地、渡口、桥梁等重要目标。', 73);
INSERT INTO `t_military_term_data` VALUES ('bc89ff3c-7351-4325-9a6f-dd53bb4f9969', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '配属炮兵', '临时配属给某一部队指挥员使用的炮兵。', 9);
INSERT INTO `t_military_term_data` VALUES ('bc8b2489-e22f-478a-a5e4-f50364fd748a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防御作战', '军队遂行抗击敌人进攻任务的作战。包括战略、战役和战术范围的防御作战。', 188);
INSERT INTO `t_military_term_data` VALUES ('bc8ba682-828a-4fe4-89c0-ad492a4b339a', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵通信训练', '装甲兵各级指挥员及装甲车辆乘员为熟练掌握装甲车辆通信设备的使用方法,学会通信联络的组织与实施而进行的训练。', 73);
INSERT INTO `t_military_term_data` VALUES ('bc9d9f4a-4858-4890-8f91-247e38627955', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上掩护队', '登陆作战中负责海上掩护的舰艇编队。由水面战斗舰艇、潜艇和航空兵组成。分为战役掩护队和直接掩护队、战役掩护队通常展开在登陆编队受威胁的方向上,抗击敌人袭击,夺取和保持海战区的制海权与制宝权；直接掩护队伴随登陆输送队航行,进行直接掩护。', 71);
INSERT INTO `t_military_term_data` VALUES ('bcb482f1-128c-4f89-87a9-378ebf9c9b42', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '密码破译', '亦称密码分析。对截获侦察对象的加密通信信息进行解析还原,从中获取情报的工作。', 146);
INSERT INTO `t_military_term_data` VALUES ('bcca01bc-e4d6-4500-a84b-16f59a469e88', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤要图', '标绘有后勤工作情况的图。通常标绘在地图上,也可标绘在略图上。标注的内容及详略程度根据工作需要而定。', 70);
INSERT INTO `t_military_term_data` VALUES ('bccdd417-794b-4c37-b27f-9d1e21d8bb61', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '航空摄影', '亦称航空照相。利用飞机等航空器上安装的航摄机,获取地面或空中目标的图像信息的技术。按摄影机光轴的状态,分为垂直摄影、倾斜摄影、全景摄影；按使用的摄影材料,分为黑白摄影、彩色摄影和多谱段摄影。可用于军事侦察、地形测绘、资源勘测等。', 238);
INSERT INTO `t_military_term_data` VALUES ('bcd1a1cd-f4fd-4e20-8bfc-18ba600d2546', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '军港', '专供军用船只使用的港口。通常建有码头、港池、进出港航道、锚地等设施。用于舰船的停泊、补给、避风等。有的还可为舰艇提供作战、后勤和技术等保障,并建有防御体系。', 389);
INSERT INTO `t_military_term_data` VALUES ('bcda6eb9-9bd1-4fba-84e2-8fca4e94e144', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火转移', '炮兵将火力由一个射击目标转向另一个射击目标的作战行动。', 76);
INSERT INTO `t_military_term_data` VALUES ('bce519e9-6d55-4764-b01a-72c44c568dda', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '地雷战器材', '用以构成地雷障碍物的工程器材。包括各种地雷和布雷器材及其有关配套器材等。', 129);
INSERT INTO `t_military_term_data` VALUES ('bcefc2ed-15f3-46ec-8eea-7119161760f4', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '失密', '秘密载体失落、失控、失窃的统称。', 76);
INSERT INTO `t_military_term_data` VALUES ('bd01ea22-4686-46f1-ae22-ee4d6e36dd19', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆最大航速', '具备浮渡能力的装甲车辆在静水中按规定条件航行时的最大速度。装甲车辆的最大航速：用履带或轮胎划水时为4～7公里／时,用螺旋桨推进时为 7～12公里／时,用喷水推进装置时为 8～13公里／时。', 170);
INSERT INTO `t_military_term_data` VALUES ('bd0f0626-0d92-4252-9def-741782b31f4d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '雪线', '多年积雪区的下部界线。其上为常年积雪区,其下有季节性积雪区。高度取决于气温和降雪量的大小,以及山体的坡向和坡度。', 79);
INSERT INTO `t_military_term_data` VALUES ('bd20c6bb-ee67-4a61-b22c-a82ee3d1b47b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反潜鱼雷', '用以攻击潜艇和其他水下目标的鱼雷。分为舰潜鱼雷、潜潜鱼雷和空潜鱼雷。', 208);
INSERT INTO `t_military_term_data` VALUES ('bd2b20d1-8ab6-4e2b-8cd2-1d76ed816190', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '突破地带', '进攻的军队对敌防御地幅的突破所形成的带状地域。由突破地段与突破纵深构成。', 90);
INSERT INTO `t_military_term_data` VALUES ('bd42d6a8-796b-452e-9fe2-982796ac4c90', '916997ee-6728-4c61-9b79-d96960b1dc86', '核辐射监测', '探测核爆炸早期核辐射和剩余核辐射,评估人员体内外辐照剂量、急性辐射危害的核监测。包括对环境的监测和对人员的监测。', 86);
INSERT INTO `t_military_term_data` VALUES ('bd554790-29d8-4986-8849-589ad80ea230', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '开辟登陆通道', '登陆作战中为保障登陆兵突击上陆,排除敌抗登陆障碍物,以打通登陆航（通）道的作战行动。', 70);
INSERT INTO `t_military_term_data` VALUES ('bd592fe1-cba9-4b50-8ac5-5d74b40c215c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗系统', '为完成特定的电子对抗任务,由若干不同功能的电子对抗设备和通信设备组成的系统。分为雷达对抗系统、通信对抗系统、光电对抗系统、水声对抗系统等。', 109);
INSERT INTO `t_military_term_data` VALUES ('bd65e61c-378c-45e6-aa3f-1883ae66cf21', '97a19170-bfac-42c5-9906-1acb187f0654', '空中垂直攻击', '飞机在垂直或大角度的上升、下降飞行中对空中目标进行的攻击。突然性强,但瞄准射击难度较空中水平攻击大。', 85);
INSERT INTO `t_military_term_data` VALUES ('bd7144c0-3d8a-4911-9f57-bebd457dd683', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '战区', '亦称战略区。为执行战略作战任务而划分的区域和设立的军队一级组织。中国人民解放军的军区具有战区性质。', 12);
INSERT INTO `t_military_term_data` VALUES ('bd7aa02b-8da8-42af-be11-02a6518225e0', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '热层', '中间层顶至距地面250千米（太阳宁静期）或500千米（大阳活动期）高度之间的大气层。由于直接吸收太阳辐射,气温随高度的增加而升高、白天最高可达1700度左右,夜间最低也在200度左右。', 5);
INSERT INTO `t_military_term_data` VALUES ('bd7c3ab3-9f89-41c6-b92a-be80979793b9', 'f0140091-c11a-48c9-8836-8aa94439dac0', '交替掩护', '在行军、作战中,部队、分队或人员之间轮番进行的相互掩护。', 116);
INSERT INTO `t_military_term_data` VALUES ('bd8911b1-4a7b-4b3c-8031-d7bf90b1765d', '97a19170-bfac-42c5-9906-1acb187f0654', '转信飞机', '在空中担负无线电中转通信任务的军用飞机。主要用于对低空、远距离或在地形复杂区域活动的飞机进行中继联络,以便增大地对空、空对空的通信距离。', 290);
INSERT INTO `t_military_term_data` VALUES ('bd8969f5-3862-4bd0-9360-f62209f7caa5', '97a19170-bfac-42c5-9906-1acb187f0654', '空中连续截击', '多批歼击机在有效截击地带,对同批空中目标分段连续进行的空中截击。', 73);
INSERT INTO `t_military_term_data` VALUES ('bd8e2fb9-0075-416a-a501-627b6cc4d06d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '触发水雷', '装有触发引信,在舰船直接碰触不起爆的水雷。多为锚雷和漂雷。分为电液触发水雷、惯性触发水雷、接电触发水雷和触线水雷。', 214);
INSERT INTO `t_military_term_data` VALUES ('bd8f6a83-81bb-4647-a884-640724bf605c', '878651de-adf5-4c72-9376-9c363b893ff8', '战略预警', '对敌战略袭击的预先警报。主要是利用现代先进的探测和通信技术手段,建立灵敏完善的战略预警系统,及时查明敌战略袭击的动向,并迅速准确地传送有关情报和号令。', 97);
INSERT INTO `t_military_term_data` VALUES ('bd9e2f4d-56d2-44b8-9f7f-1764a35edc03', '97a19170-bfac-42c5-9906-1acb187f0654', '布板信号', '铺设布板向空中飞机或直升机显示目标和指示方向的视觉信号。通常选用便于空中观察识别的红、白、黑等颜色的布板,按预先的规定铺设成各种图形,以表示不同的含义。', 365);
INSERT INTO `t_military_term_data` VALUES ('bda2db02-3f16-4c2e-a19d-220da5ad17b1', '8a761efd-50a6-4ac8-9913-b7d745104f82', '散布射', '连射武器在一定范围内边转动边进行的射击。是机枪对集群生动目标的射击方法。包括正向散布射和纵深散布射。', 89);
INSERT INTO `t_military_term_data` VALUES ('bdb2ce51-57ee-4da2-bcc5-690518b73cd8', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '合成风', '某地一定时段内同一高度不同时次的风,或一定厚度气层内同一时次不同高度的风,经矢量合成后求得的平均风矢量。常用于核爆炸放射性粒子沉降、平降修正、航空兵轰炸、炮兵射击修正等的计算。', 85);
INSERT INTO `t_military_term_data` VALUES ('bdb37d02-82f1-48fc-a2a8-8921d5d13582', '97a19170-bfac-42c5-9906-1acb187f0654', '简单气象飞行', '飞行员在可以目视到地标或发光点的气象条件下的飞行。分为昼间简单气象飞行和夜间简单气象飞行。包括晴空的飞行,云量7成（含）以下的飞行,以及云量7成以上的云下飞行。', 224);
INSERT INTO `t_military_term_data` VALUES ('bdb9e959-c87d-4483-b3ec-0b142e14127d', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '军事五项', '国际军事体育理事会确定的军事体育竞赛项目。陆、海、空军均有五项、陆军五项为射击、通过障碍、游泳、投弹、越野；海军五项为通过障碍、救生、航海技术、实用游泳、两栖越野；空军五项为射击、击剑、游泳、篮球、脱离（通过障碍和识图越野）。', 74);
INSERT INTO `t_military_term_data` VALUES ('bdc612ef-6c0d-45e7-b4a7-3f25ce2bee55', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '扫雷', '搜索和清除地雷障碍物、水雷障碍物及其他爆炸物的行动。按清扫范围,分为道路扫雷、江河扫雷、居民地扫雷、全面扫雷和在雷场中开辟通路等。', 197);
INSERT INTO `t_military_term_data` VALUES ('bdcf66c0-af40-4d45-aca5-b351134a7627', 'f0140091-c11a-48c9-8836-8aa94439dac0', '第三阵地', '师防御地区内第二梯队团或师预备队占领的阵地。', 221);
INSERT INTO `t_military_term_data` VALUES ('bdd8ff16-7f2f-4c03-aba8-f68df178ac5e', '97a19170-bfac-42c5-9906-1acb187f0654', '机场网', '在一定地域内根据作战需要修建多个机场所形成的布局。通常由若干个永备机场、野战机场、预备机场以及公路跑道等组成。', 411);
INSERT INTO `t_military_term_data` VALUES ('be01bfed-be13-4731-93a9-dd77648744e2', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '示范分队', '在训练和教学中担任示范表演任务的分队。', 185);
INSERT INTO `t_military_term_data` VALUES ('be0858dd-5a40-46c2-9450-c6163f1877aa', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '化学地雷', '亦称毒剂地雷。以毒剂杀伤人员和构成染毒地段的特种地雷。', 154);
INSERT INTO `t_military_term_data` VALUES ('be0b7a03-f1b0-47dd-a0cf-889a8b552625', '97a19170-bfac-42c5-9906-1acb187f0654', '带伞空投', '装备、物资系有降落伞的空投。空投物着陆时碰撞力小,损坏率低,但散布面大,包装比较复杂。', 173);
INSERT INTO `t_military_term_data` VALUES ('be1ae984-e105-4c25-8638-16a8928fc88f', '878651de-adf5-4c72-9376-9c363b893ff8', '侵略战争', '以侵占他国领土、掠夺他国财富、奴役他国人民为目的而进行的非正义战争。', 26);
INSERT INTO `t_military_term_data` VALUES ('be23eaf6-040e-4a95-88af-9e96c5c879a5', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '排', '由若干个班编成的军队一级组织。通常隶属于连。为战术小分队。', 21);
INSERT INTO `t_military_term_data` VALUES ('be2a661c-b683-42a9-880b-5d788e8a889e', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报交换', '有关国家、军队之间相互提供情报资料的活动。对所得的情报资料须认真鉴别。', 139);
INSERT INTO `t_military_term_data` VALUES ('be413433-9ddd-482d-8752-dfd7955da000', 'f0140091-c11a-48c9-8836-8aa94439dac0', '团防区', '团负责防守的区域。通常包括；第一梯队营防御地域和纵深营防御地域,炮兵阵地、防空兵阵地、诸预备队配置地域、反冲击展开地区、反坦克预备队展开地区、障碍设置队展开地区，伏击阵地、反空降阵地、反坦克阵地、战斗警戒阵地,各种指挥所,后勤配置地域等。', 210);
INSERT INTO `t_military_term_data` VALUES ('be531252-6e70-437d-80b9-72dd4b28f751', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备计划', '有关战争准备的各项工作的计划。主要包括作战预案、动员计划、部队扩编计划、疏散计划、国防工程建设计划、物资储备计划等。', 101);
INSERT INTO `t_military_term_data` VALUES ('be5e1a25-6510-4a9d-866e-9551bf44696a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '无名高地', '在地形图上没有注记山名或高程的高地。指示其位置时,可用邻近的地名或有高程注记的高地来说明其关系位置,如石村北侧无名高地,96.5高地南侧无名高地。', 131);
INSERT INTO `t_military_term_data` VALUES ('be671f21-f278-49e4-ab20-568922133b69', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '全日潮', '在每半个月中有连续7天以上的天数在一个太阴日内出现一次高潮和一次低潮,少数几天潮差较小,且呈现出半日潮现象的潮汐。', 139);
INSERT INTO `t_military_term_data` VALUES ('be6bf0ac-fd2f-4e42-af54-5f3803967cc8', '878651de-adf5-4c72-9376-9c363b893ff8', '战略进攻', '在战争全局上对敌实施的进攻。是战略行动的基本类型之一。分为全线实施的全面进攻和对一定方向或地区实施的重点进攻。通常由战略突击、战略包围、战略决战和战略追击等组成。是大量歼灭敌人,夺取胜利的主要手段,对实现战争目的起着决定性作用。', 107);
INSERT INTO `t_military_term_data` VALUES ('be6e5178-bacb-4bee-b776-661706324a76', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '掌握关节', '指挥员及其指挥机关抓住对全局有决定意义的关键环节。', 32);
INSERT INTO `t_military_term_data` VALUES ('be750fb1-dfaf-46bc-91eb-dfd7e304ca8a', '916997ee-6728-4c61-9b79-d96960b1dc86', '染毒密度', '染毒物单位面积上所含毒剂的重量。单位是克／平方米。', 129);
INSERT INTO `t_military_term_data` VALUES ('be809553-4429-4de3-8912-4f97202a3236', '98df76fb-4b65-48ff-a56c-4db587327c79', '车场', '集中停放、管理和维护车辆的场所。分为水入车场、临时车场和野战车场等。通常设有车库或停车场,值班室。洗车台或洗车场,保养间,器材间和消防设施等。野战车场还构筑有必要的掩体。', 309);
INSERT INTO `t_military_term_data` VALUES ('be89930c-aa6a-4776-bf10-db801b825852', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事斗争', '国家、阶级、民族、政治集团之间为达到一定的政治、经济目的,以军事手段为主进行的相互威慑或对抗活动。', 1);
INSERT INTO `t_military_term_data` VALUES ('be9023ce-807e-411e-be06-68846211224d', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '按仪表着陆', '飞行员按机上仪表的指示操纵直升机或飞机进行的着陆。', 47);
INSERT INTO `t_military_term_data` VALUES ('beaba1b1-44e4-41ff-8d42-46aeabbe1b8c', 'd7132c58-5df3-4b97-919f-58740148b9ca', '搜捕空中目标', '防空兵部队或分队利用雷达、光学器材等对空中目标实施的搜索和捕捉。', 215);
INSERT INTO `t_military_term_data` VALUES ('beb13f74-c054-4200-adbd-47ad0c79f578', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军纵队', '军队行军时的基本编队。由前卫、本队、后卫等各个部分组成。战备行军时,各行军纵队应具有独立的战斗能力。', 57);
INSERT INTO `t_military_term_data` VALUES ('beb21e05-3de3-46df-b63c-aac1b6c05555', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机操纵性', '飞机在飞行中所具有的在飞行员的操纵下改变运动姿态的特性。分为纵向（俯仰）操纵性、横侧（滚转）操纵性和方向操纵性。', 306);
INSERT INTO `t_military_term_data` VALUES ('beb49e05-9040-4a21-99be-907eaa99e90a', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '单站定位', '从单个侦测点确定电磁辐射源的位置。通常用于对高频无线电台和雷达定位。', 36);
INSERT INTO `t_military_term_data` VALUES ('beb5dd88-6b66-4b0f-a1db-7c9e63108ad6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '江心洲', '江河中的滩地。通常由分布在河心的河床底部浅滩不断增大淤高,出露于中水位以上而成。', 66);
INSERT INTO `t_military_term_data` VALUES ('beb98b2c-b5eb-45fd-8fcd-fafa68a51a3b', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '突击集团', '进攻战役中担负突击任务的兵力集团。分为主要突击集团和辅助突击集团。还可按作战领域分为地面突击集团、海上突击集团和空中突击集团等。', 77);
INSERT INTO `t_military_term_data` VALUES ('bebb5ee3-7dcc-4af9-b89c-95d20454fbce', '8a761efd-50a6-4ac8-9913-b7d745104f82', '膛外弹道', '简称外弹道。射弹在空中运动的轨迹。', 16);
INSERT INTO `t_military_term_data` VALUES ('bebc9596-2912-4d11-b045-4770bc261f5b', '98df76fb-4b65-48ff-a56c-4db587327c79', '军队财务', '军队在经费的取得、筹措、分配。使用、管理、监督等方面的事务。', 71);
INSERT INTO `t_military_term_data` VALUES ('bec96576-8aa8-4aab-ab31-22331f69d1bc', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇编队转向', '舰艇编队在航行中为改变航向而进行的运动。转向方法有鱼贯转法、齐转法、保持阵位转法、旋转法、两半角转法、同心圆转法等。', 268);
INSERT INTO `t_military_term_data` VALUES ('becc3be2-3631-43c6-985b-e2085bf843ed', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役编成', '将遂行战役任务的兵力组成有机的整体。其编成的兵力通常包括建制的和配属的。', 39);
INSERT INTO `t_military_term_data` VALUES ('bede3299-c299-4873-8111-59d1e1e08d95', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练指导思想', '指导军事训练实践的理论与原则。通常指在一定时间内军事训练应遵循的根本依据和达到的总要求等。', 1);
INSERT INTO `t_military_term_data` VALUES ('bedeea40-c051-4045-9b02-81f5e05d7d3a', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '基因工程', '亦称遗传工程。通过人工转移和重新组合生物遗传物质中的基因,改变生物的性状和功能的技术。可培育动物、植物和微生物的新品种,增加产量、改善品质,控制和治疗遗传病等。军事上可应用于研制新的生物战剂,使生物武器进入基因武器的新阶段。', 14);
INSERT INTO `t_military_term_data` VALUES ('bee11e72-f825-4085-b027-ddb95e47e068', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '部署', '①部队按照任务和行动性质形成的兵力区分和配置、如作战部署、行军部署、宿营部署等。②对部队任务的区分和对其行动序列及配置的确定。如部署行军、部署作战等。', 309);
INSERT INTO `t_military_term_data` VALUES ('beecafcd-17ed-4816-9569-8c1d8ca7c3d3', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海防工程', '为防御外敌从海上入侵,在沿海地区构筑的各种军事工程和设施的统称。是国防工程的组成部分。主要包括：舰艇基地工程,海军机场工程,岸防工程,水下防御工程,岛屿防御工程,以及岸上指挥、通信、侦察工程和导航工程等。', 386);
INSERT INTO `t_military_term_data` VALUES ('beed60e5-51f7-4987-b939-51d32f9a4ad2', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '思想政治建设', '中国人民解放军为提高部队政治质量,保持人民军队性质和官兵思想道德上的纯洁性而进行的建设。主要内容包括：进行马列主义、毛泽东思想和邓小平理论教育,人民军队性质、宗旨和优良传统教育,爱国奉献教育,革命人生观教育、尊干爱兵教育,艰苦奋斗教育,以及做好经常性思想政治工作等。', 23);
INSERT INTO `t_military_term_data` VALUES ('bef29e31-14b9-492c-aaf5-6e0819be05e0', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '暴乱', '使用暴力手段聚众破坏公共财产和社会秩序,造成生命财产损失和社会混乱的严重违法行为。', 431);
INSERT INTO `t_military_term_data` VALUES ('befdcbd5-2409-41d2-b6f9-6a04bb0a3988', '8a761efd-50a6-4ac8-9913-b7d745104f82', '底火击穿', '射击武器在射击时,射弹底火击窝中心被击穿或边缘被冲破的射击故障。', 141);
INSERT INTO `t_military_term_data` VALUES ('bf057f21-3a4d-4a9d-92da-bf51455db432', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航行补给船', '专门用于对航行中的舰艇实施补给的勤务舰船。分为综合航行补给船和专业航行补给船。通常伴随舰艇编队行动,以增大编队的作战半径和持续作战能力。', 156);
INSERT INTO `t_military_term_data` VALUES ('bf295c07-0838-4a5e-87b9-bd67928b2958', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克越壕宽', '坦克在战斗全重状态下,以低速行驶能跨越的水平地面上壕沟的最大宽度。一般为2.7～3.15米。', 165);
INSERT INTO `t_military_term_data` VALUES ('bf29a2a9-01e0-49ad-b2dc-d66f1eda156e', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '评衔', '评定军衔的简称。依据军官军衔条例和士兵服役条例,以及军官和士兵的职务、德才、实绩、贡献和经历等条件,对其军衔等级进行评定的活动。', 85);
INSERT INTO `t_military_term_data` VALUES ('bf398b4d-87cc-4818-a0e2-dc77981b32c8', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '专业军士', '①士官军衔中的一个类别。中国人民解放军的专业军士军衔由高至低分为四级、三级、二级、一级。②服现役满一定年限、被授予专业军士军衔、担任专业技术职务的军人。', 119);
INSERT INTO `t_military_term_data` VALUES ('bf3bafa6-4a18-4aec-820a-6c369c5b4a77', 'f0140091-c11a-48c9-8836-8aa94439dac0', '反冲击', '防御战斗中对突入阵地之敌实施的冲击。以消灭或击退突入之敌,稳定防御。', 251);
INSERT INTO `t_military_term_data` VALUES ('bf3cb63f-f699-450d-b04e-471abd7e7213', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '急流', '大气急流的简称。大气中出现的宽度窄、风力强的气流带。高空急流出现在对流层顶附近和平流层中,低空急流出现在对流层下部。急流区有很强的风速切变和湍流扰动,对飞行活动影响很大。', 38);
INSERT INTO `t_military_term_data` VALUES ('bf3ff3a0-dba5-446d-be30-1ea93f796240', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行航向', '航空器飞行时,其纵轴水平投影线的前端所指的方向。通常以航空器至基准北的经线与沿顺时针方向到航空器的纵轴水平投影线之间的夹角表示。按起算的基准北不同,分为真航向、磁航向和罗航向。', 373);
INSERT INTO `t_military_term_data` VALUES ('bf5b2cac-5001-40a3-807b-616e9fafde57', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战行动计划', '组织实施部队或分队作战行动的计划通常包括总体计划、分支计划和协同动作计划等。', 88);
INSERT INTO `t_military_term_data` VALUES ('bf7902bf-d723-4eaa-ae43-4ec5ad61388e', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '防御体系', '由防御诸要素构成的有机整体。包括兵力部署、阵地编成、火力配系、障碍物配系和有关保障体系等。', 126);
INSERT INTO `t_military_term_data` VALUES ('bf80f8c8-2195-4e26-bda4-adde189d2ab0', '97a19170-bfac-42c5-9906-1acb187f0654', '空军战场准备', '空军在可能作战的地区进行的以战场建设为主要内容的各项准备。主要包括：修建机场网、指挥引导网、雷达情报网、技侦情报网、通信网、气象预报网、后勤供应网、兵器修理网等工程设施,以及各种阵地和防护工程等。', 408);
INSERT INTO `t_military_term_data` VALUES ('bf8163db-aac5-4120-8bb5-58aeca654c77', '97a19170-bfac-42c5-9906-1acb187f0654', '战斗飞行时间', '飞机或直升机遂行战斗任务时从起飞至着陆全过程所用的时间。通常以1架次为单位进行计算。', 58);
INSERT INTO `t_military_term_data` VALUES ('bf83783b-d6a3-4f7f-8019-abae180bfba3', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '霾', '大量极细微的尘粒、烟粒、盐粒等均匀地浮游在空中,致使水平能见度小于10千米的天气现象。出现时天空呈乳白色,空气比较于燥,垂直能见度较差。', 33);
INSERT INTO `t_military_term_data` VALUES ('bfb1b6dc-75e7-4b90-83da-5bcbc8052e65', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '玻璃钢工事', '用玻璃纤维增强塑料或其他纤维增强塑料制成的工事。如玻璃钢圆筒形机枪工事、玻璃钢椭圆形掩蔽部、玻璃钢蜂窝夹层拱形掩蔽部等。特点是重量轻、构件少、防水、抗力强、保温性能好,适于寒区使用。', 73);
INSERT INTO `t_military_term_data` VALUES ('bfc639e3-b57b-4c56-8cab-4db4b940e214', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战斗条令', '规范师以下部队作战行动的各种条令的统称。包括合成军队战斗条令和军种、兵种及专业兵的战斗条令。是部队战斗行动和战术训练的依据。', 1);
INSERT INTO `t_military_term_data` VALUES ('bfd30cae-4232-433a-96f7-efb631455d62', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教学设施', '教学用的房舍、场地、设备及其相应的管理机构的统称。通常包括教室、实验室、专修室、图书馆、附设教学医院、电化教学中心、计算机辅助教学系统、模拟训练系统和训练场地等。', 181);
INSERT INTO `t_military_term_data` VALUES ('bfdae751-d7c4-49af-8d18-fe7037fe0210', '8a761efd-50a6-4ac8-9913-b7d745104f82', '盲目射击', '没有具体目标的射击。', 105);
INSERT INTO `t_military_term_data` VALUES ('bfde1a71-5eb9-45d3-88df-0944b05fbf5e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '炸坑器', '用以在土、石、混凝土等目标上快速炸出漏斗坑的爆破器材。由穿孔装药、炸坑装药和引信组成。分为整体式炸坑器和分装式炸坑器。主要用以构筑掩体、路坑障碍以及实施破坏作业等。', 228);
INSERT INTO `t_military_term_data` VALUES ('bfe30d88-773c-4413-9df3-d4a56ea9d4c8', '97a19170-bfac-42c5-9906-1acb187f0654', '空中支援', '亦称航空兵支援。空军航空兵部队为配合陆军、海军部队作战而实施的各种支援行动的统称。主要包括：航空火力突击,空中掩护,航空侦察,航空布雷,空中电子对抗支援以及空中运输、空中救援等。', 120);
INSERT INTO `t_military_term_data` VALUES ('bfe6f221-b25b-4109-bff1-cf730691a7c7', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '地形侦察', '对有关作战行动的地形情况迸行的侦察。主要查明作战地区的地貌、地物以及障碍物等情况及其对军队行动的影响。', 22);
INSERT INTO `t_military_term_data` VALUES ('bfe84742-3749-4d9a-809f-eab4638b00ec', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹道降弧', '由弹道最高点到落点的一段弧。', 34);
INSERT INTO `t_military_term_data` VALUES ('bfeaa918-60c7-4b06-846f-a17c43a82552', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇战斗准备', '舰艇受领作战任务后进行的准备工作。主要内容包括：战斗动员,调整、充实舰（艇）员,检查、维修、校正武器装备,补充油、水、雷、弹、给养和备品、配件,备齐作战文书和有关资料,制定航行计划和作战行动方案,组织临战训练等。', 285);
INSERT INTO `t_military_term_data` VALUES ('bff9ed6c-a517-428f-b7ce-cda1a90acdd2', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '解除警报', '紧急或危险情况已经消除后发出的警报。以使有关单位和人员恢复正常的生活与工作状态。', 40);
INSERT INTO `t_military_term_data` VALUES ('c00ba646-e215-4139-a7c3-254ae1814ee4', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲救护车', '备有制式担架、医疗设备、药品和器材的装甲保障车辆。用于野战条件下救护和运送负伤人员。可载医护人员l～2人,负伤人员4～8人。', 107);
INSERT INTO `t_military_term_data` VALUES ('c0187ecd-5a80-4237-8873-5dc1f8830983', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '冰上渡河', '部队从冰层上通过江河的行动。', 308);
INSERT INTO `t_military_term_data` VALUES ('c01ab46b-cb8c-47c3-b0b2-df66ffacc8f2', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵机动', '炮兵有组织地转移兵力、火力的作战行动。分为转移阵地的兵力机动和不转移阵地、只转移火力的火力机动。以适应战场情况的变化,不失时机地打击敌人。', 78);
INSERT INTO `t_military_term_data` VALUES ('c0323377-baae-4902-8135-4985ff98dd09', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇潜望镜', '潜艇在水下一定深度用以观察水面和空中目标的光学器材。分为攻击（指挥）、搜索（对空）、星光导航和多用途潜艇潜望镜。', 250);
INSERT INTO `t_military_term_data` VALUES ('c0332490-7c50-47ab-bb26-598a5e437ac3', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象侦察飞机', '用于天气侦察和特殊气象探测的飞机。机上装有大气测量、采样和数据处理的仪器、设备,气象雷达和微波辐射仪,磁带记录仪和微型计算机等。主要用以探测空中气温、气压、湿度、风等气象要素,大气成分,大气湍流,大气电场,大气化学参数,云和降水的宏观、微观参数,以及强对流天气等。', 99);
INSERT INTO `t_military_term_data` VALUES ('c03343c4-6fdf-4851-966d-a915316ae408', '98df76fb-4b65-48ff-a56c-4db587327c79', '整装油料', '亦称桶装油料。用油桶等小型容器盛装储运的油料。', 178);
INSERT INTO `t_military_term_data` VALUES ('c052ecbd-4374-44c6-8a3e-9640445da87e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上战略突袭', '在统帅部统一指挥下,海军单独或在其他军种协同下从海上对敌战略目标实施的突然袭击。通常由具有战略袭击手段的潜艇、水面舰艇、航空兵等部队实施。', 20);
INSERT INTO `t_military_term_data` VALUES ('c05f1752-9087-4d34-934b-56b85b85b85c', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹单发杀伤概率', '一发地空导弹杀伤一个空中目标的可能性大小的量。通常用0～1的数值表示。', 200);
INSERT INTO `t_military_term_data` VALUES ('c060fc19-faef-456a-bed6-0c15fc3bf8f9', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '轮番攻击', '各部队轮流对同一敌人实施的攻击。通常在对难以攻克的目标攻击时采用。也是武装直升机攻击地面目标的一种方式。', 108);
INSERT INTO `t_military_term_data` VALUES ('c07029d4-60b0-4a7f-9126-ce3a696df43f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地形测量', '对地球表面局部地区的地物、地貌进行测定,并按比例尺缩小,用符号和注记绘制成地形图的技术。方法有摄影测量和平板仪测量等。', 155);
INSERT INTO `t_military_term_data` VALUES ('c092b51b-d4ce-46aa-8ad4-7d716c9bb139', '97a19170-bfac-42c5-9906-1acb187f0654', '空军通信保障', '空军为顺利遂行作战、训练等任务而在通信联络方面进行的保障。', 349);
INSERT INTO `t_military_term_data` VALUES ('c0984f13-4512-4918-ad19-dcf45e472392', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '后方桥', '在战役、战术地幅的后方地域架设的军用桥梁。主要用以替换用舟桥器材和其他制式器材架设的浮桥、固定桥,保障后续部队通过江河障碍。', 287);
INSERT INTO `t_military_term_data` VALUES ('c09a82c0-7566-447f-990e-480b8cc7590b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '防潜', '为防止敌潜艇袭击而采取的措施和行动的统称。包括海军基地防潜、海峡或狭水道防潜和舰船编队防潜。主要措施有组织防潜观察和防潜警戒、设置防潜障碍、部署反潜兵力等。', 96);
INSERT INTO `t_military_term_data` VALUES ('c0a17339-18e6-41e9-8224-85b7e788e25d', '8a761efd-50a6-4ac8-9913-b7d745104f82', '终点效能', '射弹对目标产生作用的有效程度。取决于射弹的结构特性、材料特性、弹道特性以及目标本身的特性。对生动目标表现为杀伤作用；对装甲目标表现为穿甲、破甲作用；对混凝土、砖石、土木工事、物资器材等目标表现为侵彻、爆破作用。', 117);
INSERT INTO `t_military_term_data` VALUES ('c0a399f8-d0ca-4ca9-a274-9436c60326b3', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '心理战', '运用心理学的原理,通过宣传等方式从精神上瓦解敌方军民的斗志,或消除敌方宣传所造成影响的对抗活动。', 153);
INSERT INTO `t_military_term_data` VALUES ('c0a6dcb2-7a62-4804-abf1-4f666746ca9a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上突击基准兵力', '实施海上突击的兵力中作为协同动作基准的兵力。通常为担负主要突击任务的兵力。', 47);
INSERT INTO `t_military_term_data` VALUES ('c0c324c0-d779-4b5b-aef2-4ec764aff9f5', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克单位压力', '坦克战斗全重与两条履带着地面积总和之比。一般约为（6～10）X10(四次方)帕。是衡量坦克通过各种性质地面能力的重要指标。', 161);
INSERT INTO `t_military_term_data` VALUES ('c0c5d8ce-5705-4fd0-a86a-e13c333224a3', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克车内通话器', '坦克车内的有线电通信设备。由通话盒、工作帽、胸前开关和电缆等组成。主要用于坦克乘员间相互通话,也可供个别乘员控制电台对外联络。', 143);
INSERT INTO `t_military_term_data` VALUES ('c0d31501-1734-47a3-90e9-bc74f27f61a0', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '副热带高压', '中心位于南、北半球副热带地区的大型暖性高压系统。夏半年（4～9月）,中国东部地区的主要雨带与西太平洋副热带高压脊线位置的变化相对应。在其北侧的西风带中,气旋和锋活动频繁,多阴雨和暴雨天气；在其南侧常有东风波和热带气旋活动,降水量大；脊线控制地区,天气酷热、少雨。', 45);
INSERT INTO `t_military_term_data` VALUES ('c0db65d0-eb9a-418c-8ffc-40fb10888c2e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军制学', '研究军事制度及其发展规律的学科。是军事学术的组成部分。主要研究内容包括：军事领导体制,武装力量体制,军队体制编制。军队行政管理制度,武器装备管理制度,后备力量建设制度,兵役制度,战争动员制度等。', 27);
INSERT INTO `t_military_term_data` VALUES ('c0e6745d-cbb9-439c-ba1c-2b2bad0426c9', '06a75831-13a1-4660-870a-455bb445336a', '陆空协同通信', '为保障陆军地面部队与航空兵的协同作战而建立的通信联络。主要方法有：组织协同无线电网；通过航空兵向陆军地面部队派出的作战小组、目标引导小组的电台建立无线电通信；由陆军地面部队向航空兵建立野战有线电通信；使用简易信号通信器材等。', 12);
INSERT INTO `t_military_term_data` VALUES ('c0e8f064-bd5b-4336-9247-98decb6b07f5', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战斗部署', '根据战斗企图对战斗编成内的兵力兵器所作的任务区分、编组和配置。不同类型和样式的战斗,有不同的战斗部署。', 49);
INSERT INTO `t_military_term_data` VALUES ('c1075b28-29d1-4b8d-b8a9-8b2cddc09761', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '观察器材', '用于观察的光学器具、设备的统称。如望远镜、潜望镜、炮队镜、夜视仪、侦察经纬仪等。', 117);
INSERT INTO `t_military_term_data` VALUES ('c124bc0c-17aa-4c7b-ad32-576e2796c1fb', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '军用机器人', '军事上专用的具有类似人体某些器官功能,并能代替人完成某些军事任务的机电一体化自动装置。如排除地雷机器人,海底机器人,核反应堆的检修机器人,航天飞机上的发收卫星的机器人等。', 68);
INSERT INTO `t_military_term_data` VALUES ('c137ca10-a66d-481e-bd1d-6cf923ffdd72', '8a761efd-50a6-4ac8-9913-b7d745104f82', '无壳弹枪', '发射无壳枪弹的枪。由于没有弹壳,携弹数可增加一倍多,火力持续性强。', 174);
INSERT INTO `t_military_term_data` VALUES ('c1403c4c-d065-4cda-9d91-184aee14d005', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '值班舰艇', '担负值班任务,保持规定的戒备状态,随时可执行作战或其他紧急任务的舰艇。分为战备值班舰艇和日常战斗勤务值班舰艇。值班舰艇白天挂值班旗,夜间挂值班灯。', 288);
INSERT INTO `t_military_term_data` VALUES ('c144d526-2ce0-453c-a750-c121984e2adb', '97a19170-bfac-42c5-9906-1acb187f0654', '直接航空火力支援', '航空兵部队在己方或敌方的地面部队发起进攻后对敌目标实施的空中火力突击。通常与地面部队行动或其他突击火力结合进行。', 125);
INSERT INTO `t_military_term_data` VALUES ('c14ad2c8-9936-42cc-926c-b6777bdbefbf', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '外层', '亦称散逸层。距地面 500千米以上的大气层。空气十分稀薄,大气粒子很少互相碰撞,有些速度较大的中性粒子能克服地球引力勉入星际空间。', 6);
INSERT INTO `t_military_term_data` VALUES ('c16084f2-98b1-4794-8d25-799fa9aa0de2', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军官', '军队中被授予少尉以上军衔的军人。中国人民解放军的军官分为军事军官、政治军官、后勤军官和专业技术军官等。', 102);
INSERT INTO `t_military_term_data` VALUES ('c16674b1-7245-493d-bd16-565120dbf172', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军人代表会议', '中国人民解放军为开展民主生活,保障军队正确行使民主权利和参与部队管理的一项民主制度。由旅、团或相当于旅、团级的单位每年召开一次。在同级部队党委的领导和政治机关的指导下,由会议主席团主持召开。', 9);
INSERT INTO `t_military_term_data` VALUES ('c16cf065-25f6-4c3f-ad97-99eac406a813', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '反弹道导弹导弹', '简称反导导弹。专门用以截击并摧毁来袭的弹道导弹的导弹。分为高空反导导弹和低空反导导弹。高空反导导弹用以拦截在大气层外飞行的弹道导弹；低空反导导弹用以拦截重返大气层后飞行的弹道导弹。', 14);
INSERT INTO `t_military_term_data` VALUES ('c176afcd-a419-46d4-b4da-3536c032a2e4', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹测试', '对导弹各部分的主要技术性能、协调工作情况和可靠性进行的检查和鉴定。', 86);
INSERT INTO `t_military_term_data` VALUES ('c1772c4c-cdb7-4a0b-b70b-4da10d29c7f0', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克越野平均运动速度', '坦克在战斗全重及规定的环境条件下,按规定比例的各类越野地面行驶的平均运动速度。', 159);
INSERT INTO `t_military_term_data` VALUES ('c1819b5a-be21-4d09-95dd-ae50f14ec51f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '运输管道', '用以输送石油、天然气、固体料浆等的管道。一般埋于地下,不易遭破坏和损坏,运输受气候、地形等自然条件影响小,且易保密。', 113);
INSERT INTO `t_military_term_data` VALUES ('c18eae38-f445-4f57-bbe8-2f2b79db1d21', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '士兵', '亦称战士。军队中被授予士官、军士和兵军衔的军人。相时于干部而言。有的国家仅指被授予军士和兵军衔的军人。', 114);
INSERT INTO `t_military_term_data` VALUES ('c19a299c-0a00-44be-98b5-780e0cdeb819', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战保障指示', '对有关部门、部队或分队所作的关于组织与实施作战保障的指示。通常包括侦察通信警戒电子防御、防化、工施伪装、测绘气象水文以及交通、航海、声纳、防险救生、领航等保障指示。', 132);
INSERT INTO `t_military_term_data` VALUES ('c1a77643-8b83-4ced-8353-82a620c4d30f', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵战术', '第二炮兵进行战斗的方法。主要内容包括战斗基本原则、兵力部署、战斗指挥、协同动作、战斗行动的方法和各种保障措施等。', 30);
INSERT INTO `t_military_term_data` VALUES ('c1b80433-36f6-4f16-b719-3f84716cbc43', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '增强X射线弹', '以增强x射线破坏效应为主要杀伤破坏因素的特殊性能核武器。其高空爆炸时产生的强大X射线流,可穿透来袭武器的壳体,对其内部电子器件、电路等产生辐照效应,使之丧失应有的功能。', 95);
INSERT INTO `t_military_term_data` VALUES ('c1c49832-4dc4-4009-81da-d1f84c3f91b4', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '音响伪装', '通过消除、降低、压制或模拟目标音响暴露征候而实施的伪装。', 338);
INSERT INTO `t_military_term_data` VALUES ('c1c6d554-b63d-44c5-b5a1-b1fa8c79bd06', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击目标', '射击的对象。按目标所处空间位置，分为空中目标、地面目标和水面（下）目标；按目标编成,分为单个目标和集群目标；按目标形状,分为点目标,线目标和面目标；按目标有无工事防护,分为暴露目标和掩蔽目标；按目标有无装甲,分为装甲目标和非装甲目标；按目标有无生命,分为生动目标、非生动目标；按目标是否运动,分为固定目标、运动目标和隐显目标等。', 114);
INSERT INTO `t_military_term_data` VALUES ('c1c7277e-de62-41e9-b76d-7176c2183b34', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '交战', '战争中敌对双方直接交火的作战行动。如两国交战、两军交战、两支部队交战等。', 200);
INSERT INTO `t_military_term_data` VALUES ('c1ccbdcf-505e-4400-9d76-bb233d55d4c8', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '乔木', '主干明显而直立、分枝繁盛的木本植物。如松、杉、杨、榆等。', 95);
INSERT INTO `t_military_term_data` VALUES ('c1cd664d-3a3a-4185-bc32-104528879965', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵气象站', '防空兵部队编制内担负气象保障任务的专业气象站。编有气象专业人员和报务人员,以及测风雷达、气象车等。', 122);
INSERT INTO `t_military_term_data` VALUES ('c1d2dade-72dc-40ed-94a2-beab1a11b8ab', '916997ee-6728-4c61-9b79-d96960b1dc86', '烟幕', '人工造成的能起屏蔽作用的烟雾。按用途,分为遮蔽烟幕、迷盲烟幕、干扰烟幕和信号烟幕；按施放方式,分为固定烟幕和移动烟幕。可采用发烟弹药、发烟车、发烟器。发烟罐等发烟装备生成烟幕。', 72);
INSERT INTO `t_military_term_data` VALUES ('c1d651b2-9370-4d0b-a1b0-47427d7ca395', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '官兵比例', '军队总人数或军队建制单位总人数中,军官与士兵的人数分别所占的比例或军官人数与士兵人数之间的比例。', 96);
INSERT INTO `t_military_term_data` VALUES ('c1d9df26-16d3-42de-9f11-eecaf81bb601', '98df76fb-4b65-48ff-a56c-4db587327c79', '运行量', '按规定由师、旅、团仓库运行的物资数量。是移动储备的组成部分。', 117);
INSERT INTO `t_military_term_data` VALUES ('c1eca6fb-f213-4125-9cfd-377f46cd7021', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹武器系统', '地空导弹及其配套技术装备的统称。由地空导弹、目标搜索与指示系统、地面制导设备、发射系统、供电设备和保障设备等组成。按射高,分为高空、中空、低空地空导弹武器系统；按射程,分为远程、中程、近程、超近程地空导弹武器系统。', 30);
INSERT INTO `t_military_term_data` VALUES ('c20a8344-548d-40be-aa02-4c726d3f38e9', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '火箭', '火箭发动机辅进的飞行器。由箭体、推进系统和有效载荷等部分组成、按使用的能源,分为化学火箭（其中还可分为液体火箭、固体火箭等）、电火箭、核火箭等；按级数,分为单级火箭和多级火箭；按有无控制系统,分为有控火箭和无控火箭。有控火箭,可用以发射航天器,在军事上用作攻击型武器。', 65);
INSERT INTO `t_military_term_data` VALUES ('c2106503-9ee2-47f2-ae7d-25ab59c2dcf5', '97a19170-bfac-42c5-9906-1acb187f0654', '陆（海）空协同作战方式', '空军协同陆军、海军作战时,对空军航空兵部队的组织指挥方式。通常分为支援作战方式和配属作战方式。支援作战方式是根据协同作战计划,由空军指挥所属航空兵部队支援陆军、海军部队作战。配属作战方式是把一定数量的航空兵部队临时调归合成军队,由合成军队统一指挥,配合陆军、海军部队作战。', 126);
INSERT INTO `t_military_term_data` VALUES ('c21a1a90-2af0-4f1b-8364-6ce433620fe1', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '赤道', '环绕地球表面与地球南北两极距离相等的圆周线。地球赤道面通过地心,垂直于地轴,将地球分为南北两个半球,是划分纬度的基准。赤道的纬度为零。', 199);
INSERT INTO `t_military_term_data` VALUES ('c22aa842-b696-4574-bc2e-f155c307fe4e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克并列机枪', '与坦克炮并列安装的机枪。用以歼灭和压制近距离内的有生力量,有的还兼具测距功能。射击时与坦克炮共用一个火控系统。通常由一炮手操作。', 114);
INSERT INTO `t_military_term_data` VALUES ('c2352d87-e565-4b8c-b4ba-5d9ec521f8f3', 'd7132c58-5df3-4b97-919f-58740148b9ca', '弹炮合一防空武器系统', '由地空导弹、小口径高炮、共用火控系统联为一体的防空武器系统。以自行式居多、主要用以毁伤低空目标,遂行跟进掩护和伴随掩护任务。', 33);
INSERT INTO `t_military_term_data` VALUES ('c235f200-c851-458a-aa22-b2ed4c28e91b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '坑道封闭', '对平时不使用的坑道工事采取封闭工事口部的管理措施。用以隐蔽伪装坑道,节省维护人员和经费。基本办法是加装防潮门、防盗门或覆土掩埋。', 84);
INSERT INTO `t_military_term_data` VALUES ('c23dc9b3-50c4-4ee9-9487-63f8816ca20f', '916997ee-6728-4c61-9b79-d96960b1dc86', '芥子气', '学名二氯二乙硫酸。糜烂性毒剂的一种。可装填在炮弹、航空炸弹、地雷、航空布洒器中使用。主要通过皮肤接触或呼吸道吸入,经2～12小时的潜伏期后相继出现红肿、水泡和溃疡等中毒症状。', 216);
INSERT INTO `t_military_term_data` VALUES ('c261cc08-4691-4354-9ab7-08f27604f93b', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹阵地', '导弹部队准备和实施导弹突击的作战场地。通常分为基本阵地和预备阵地。兼有作战和防护两种功能。是导弹部队作战的依托。', 39);
INSERT INTO `t_military_term_data` VALUES ('c264f245-0f97-4e64-91c9-8a95455fcaf7', '878651de-adf5-4c72-9376-9c363b893ff8', '国际战争', '国家或国家集团之间进行的战争。相对于国内战争而言。', 16);
INSERT INTO `t_military_term_data` VALUES ('c2695e00-3859-4b2c-81ba-5b1b9cda7c97', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇导航', '引导舰艇按一定航线行驶的方法和技术的统称。分为自主式导航和非自主式导航。', 272);
INSERT INTO `t_military_term_data` VALUES ('c269f5be-ae73-424d-bcd4-1b1f99feda1f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '中子弹', '亦称增强辐射弹。以高能中子辐射为主要杀伤因素,冲击波和光辐射效应相对减弱的特殊性能核武器。具有很强的辐射穿透力,能有效地杀伤坦克和地面建筑物中的人员；同时可大幅度减少非直接攻击目标的连带毁伤。', 94);
INSERT INTO `t_military_term_data` VALUES ('c26d419c-7a7b-402e-999b-5aab488f5c96', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '军用吊桥', '在缆索下面悬挂桥跨结构而架成的军用桥梁。缆索两端锚固于河、谷两岸并支撑在塔架上。按承载能力,分为载重吊桥、驮载吊桥和徒步吊桥。', 279);
INSERT INTO `t_military_term_data` VALUES ('c26d6ddb-5095-4dce-abc8-8b35430226a7', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '政治军官', '军队中从事政治工作的军官中国人民解放军中的政治军官包括从事组织、干部、宣传、保卫、文化、群众、联络等工作的军官。', 105);
INSERT INTO `t_military_term_data` VALUES ('c274efad-64c1-4eea-af64-442b6d7cd452', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵半遮蔽阵地', '位于遮蔽物后但无良好的遮蔽度,在一般气象条件下,敌从地面能观察到火炮发射的火光和烟尘的炮阵地。', 61);
INSERT INTO `t_military_term_data` VALUES ('c27df89d-de79-45c8-a0cb-5f6428bd866a', '98df76fb-4b65-48ff-a56c-4db587327c79', '火线运输', '在战术地幅内受敌火力直接威胁下实施的运输。一般采取小群、分散、多路的形式进行。', 248);
INSERT INTO `t_military_term_data` VALUES ('c28b1f48-dccb-4be9-a165-8823532c3c03', '97a19170-bfac-42c5-9906-1acb187f0654', '空中退出战斗', '空战的结束阶段。自飞机完成退出攻击起至飞机退出作战空域止。主要进行返航活动。', 80);
INSERT INTO `t_military_term_data` VALUES ('c28bbd83-a0f7-4d2b-a932-cebe02c00f72', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '赋予基准射向', '简称赋予射向。使炮身轴线和观察器材视轴线指向基准射向的操作过程。', 213);
INSERT INTO `t_military_term_data` VALUES ('c28cd261-7137-48ef-9f3e-38425e83af5f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '函', '军队内部以及军队与地方有关单件之间商办事宜的军用文书。', 142);
INSERT INTO `t_military_term_data` VALUES ('c294808a-ff06-4f25-8fb8-920c9d02d9ba', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '社情判断', '对遂行任务地区的社会情况进行分析研究并得出结论的思维活动、主要判明民族宗教、风俗以及社会治安等政治状况地方病及疫情人民群众支前的能力,有关资源和物资储备等情况,以及对敌我双方遂行任务的影响', 71);
INSERT INTO `t_military_term_data` VALUES ('c2a9f72e-c35d-49a7-aa93-d4898210ea5a', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力点', '亦称发射点。机枪、火箭筒、榴弹发射器、便携式导弹、直接瞄准火炮、坦克等配置和射击的地点。按坚固程度,分为永备火力点和野战火力点；按暴露程度,分为明火力点和暗火力点等。', 240);
INSERT INTO `t_military_term_data` VALUES ('c2ab9c39-5bcf-4a06-ac02-4973bda481e2', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射时间', '发射导弹的操作人员按下点火按钮的时刻。是导弹发射命令的一项重要内容、必须严格执行。', 137);
INSERT INTO `t_military_term_data` VALUES ('c2ceeacc-114a-4890-80bb-1966761bce9e', '06a75831-13a1-4660-870a-455bb445336a', '传真站', '担负传真通信任务的通信站。主要设备为传真机、可传送军用文书、报文、照片、图表等原稿的真迹。', 87);
INSERT INTO `t_military_term_data` VALUES ('c2d5d1d9-3a58-4508-9ca0-dd029ab91cf6', 'd7132c58-5df3-4b97-919f-58740148b9ca', '抗击空袭兵器袭击', '简称抗击空袭。防空兵部队或分队以火力或其他措施破坏敌空袭兵器所实施的袭击。包括毁伤和拦截敌方飞机、直升机、巡航导弹和其他飞行器等。', 62);
INSERT INTO `t_military_term_data` VALUES ('c2db909a-1e47-4974-9df1-34f082f172cc', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '尾桨失效', '直升机飞行时发生的尾桨失去功效而无法控制飞行的状况。尾桨失效的直升机,极易发生飞行事故。', 52);
INSERT INTO `t_military_term_data` VALUES ('c2de6f0a-3db3-4817-940f-431acfa4f6a5', '98df76fb-4b65-48ff-a56c-4db587327c79', '迂回运输', '绕道进行的运输。通常在某段运输线路被毁坏、遭封锁和沾染、染毒时,或为隐蔽真实意图时采用。', 254);
INSERT INTO `t_military_term_data` VALUES ('c2eea8b0-3e52-4b53-b3bb-3a88954dd6bc', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤部队', '军队内担负后勤保障任务的团和相当于团级以上的后勤建制单位。如汽车团、团级的仓库等。', 11);
INSERT INTO `t_military_term_data` VALUES ('c2fb205f-af8b-4222-8c7e-af7ca076dc3b', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克遮蔽阵地射击', '坦克在遮蔽阵地上进行的间接瞄准射击。由专设的观察所为其提供射击诸元。', 58);
INSERT INTO `t_military_term_data` VALUES ('c303a59b-dbb2-44e7-959e-473767060a64', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '燃料空气炸药', '由固体或液体燃料与空气混合而成的炸药。使用的燃料通常有环氧乙烷、环氧丙烷。可用于炸弹、火箭弹、导弹战斗部的装药及核爆炸模拟等。', 214);
INSERT INTO `t_military_term_data` VALUES ('c3068950-eb73-4bae-ace9-c99562412818', '878651de-adf5-4c72-9376-9c363b893ff8', '战略地位', '某事物在国防建设、军队建设和战争全局中,处于关系全局、起到重大作用和长远影响的位置。如教育训练、战场建设、国防科研和装备发展等在国防和军队建设中具有重要的战略地位。', 72);
INSERT INTO `t_military_term_data` VALUES ('c32285bf-6832-46bb-bd4e-f5f1e7701c70', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导轨式发射装置', '装有滑行导轨的导弹发射装置。发射时导弹沿发射臂上的滑行导轨滑动,保证导弹离轨时具有一定的初始高低角、方位和初始速度。如地空导弹、舰舰导弹、岸舰导弹等发射装置。', 63);
INSERT INTO `t_military_term_data` VALUES ('c32e9fa7-9282-4d13-849f-a38c4572e2fc', 'f0140091-c11a-48c9-8836-8aa94439dac0', '阵地', '为进行战斗,兵力兵器所占领（准备占领）并构有工事的位置。是部队作战的依托。如既设阵地、临时构筑的阵地,进攻出发阵地、防御阵地,导弹发射阵地等。', 212);
INSERT INTO `t_military_term_data` VALUES ('c332c468-9188-4b47-9160-9f8dda1c5108', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮阵地通话器', '在高炮连阵地内传递射击指挥信息的通信设备。分为有线电阵地通话器、无线电阵地通话器和有线电无线电综合阵地通话器。', 130);
INSERT INTO `t_military_term_data` VALUES ('c341e6ef-e272-4abc-91af-10fcd5dcff89', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡河地区', '部队实施渡河的地区。包括江河的一段及其两岸的附近区域。', 309);
INSERT INTO `t_military_term_data` VALUES ('c34c0df1-40fd-4116-9b96-115f98e2419c', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '初战', '战争中的首次战役或战役中的首次战斗。初战对战争、战役全局及后续作战影响甚大,应慎重初战。', 199);
INSERT INTO `t_military_term_data` VALUES ('c34f28c8-5c8b-43d2-8a03-9dfd5c6bd17e', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '专属经济区', '主权国家在邻接其领海的外部海域设立的经济管辖区。其外部界线至领海基线不应超过200海里。是国家自然资源区的组成部分,国家对之行使有关国际海洋法规定的经济主权权利和管辖权。', 77);
INSERT INTO `t_military_term_data` VALUES ('c34f7be0-7149-44a8-b75b-f3ee9b52c8c5', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥关节', '指挥活动中的关键环节、作战指挥的关键环节主要包括分析判断情况,定下决心,计划组织行动保持时部队不间断的指挥多。', 9);
INSERT INTO `t_military_term_data` VALUES ('c35adc54-10fb-4269-9cc9-2d58769aaa6f', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防工业', '亦称军事工业。研制和生产武器装备、军用器材、军队生活用品以及国防所需特殊原材料的工业门类。包括兵器工业、航空工业、舰船工业、电子工业、核工业、航天工业、军需工业等。', 38);
INSERT INTO `t_military_term_data` VALUES ('c35f0d98-9b6d-4dc8-ba7b-c7e63581e0ea', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '战备秩序', '军队的战备活动按照有关条令和规定保持的井然有序的状态。', 34);
INSERT INTO `t_military_term_data` VALUES ('c36be3fd-9dd7-4142-a859-183214e60613', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '集结', '部队由运动状态转变为临时停留状态的缩短队形过程,或将分散在不同地点的兵力调集到指定区域的行动。', 343);
INSERT INTO `t_military_term_data` VALUES ('c37d2e60-c49b-4991-a257-55bc53accf91', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '水位', '海洋、江河、湖泊、水库或地下水水面相对于某一基准面的高度。江河、湖泊水位随季节、雨量等而变化,海洋和通海河口的水位受潮汐影响而产生周期性升降运动。', 112);
INSERT INTO `t_military_term_data` VALUES ('c38cb192-1bc4-42e0-bee8-ee0e9ccc2b31', '98df76fb-4b65-48ff-a56c-4db587327c79', '军费决算', '加对军队经费预算执行结果的总结报告。主要包括军队经费总决算、单位经费决算、分项经费决算和专项经费决算等。', 75);
INSERT INTO `t_military_term_data` VALUES ('c3972e96-bc6d-4d19-b42d-d3b0429400d7', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤建设', '为提高后勤保障能力而进行的有关建设。主要包括物资、装备、设施、组织、法制、理论等方面的建设。', 5);
INSERT INTO `t_military_term_data` VALUES ('c3ad5127-b298-4c3a-9bd9-017e4708203d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮火力单位', '配有目标探测跟踪装置和射击诸元计算装置,能独立进行对空射击的高炮分队。通常以一个高炮连为1个火力单位。与目标探测跟踪装置、射击诸元计算装置结为一体的单门自行高炮,亦为1个火力单位。', 158);
INSERT INTO `t_military_term_data` VALUES ('c3ada802-c7d5-4491-aa0d-a98eac6ab675', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '稳定性', '作战系统或武器系统所具有的在复杂情况下仍能正常发挥作用的性质。', 276);
INSERT INTO `t_military_term_data` VALUES ('c3b5ddce-da79-4b72-98a3-a004e25b2169', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '防空武器', '主要用以歼灭空中目标的武器装备。包括高射机枪、高射炮、防空导弹、歼击机等。', 216);
INSERT INTO `t_military_term_data` VALUES ('c3bfa278-6a60-48a8-bde6-ce091151c089', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '军用设备气候极值', '供军用设备设计所使用的气候要素的极端值。是军用设备设计标准之一。分为工作极值和承受极值。工作极值是在一定的风险率下保证军用设备正常工作的气候要素极值；承受极值是按一定风险率保证军用设备能够承受（不发生不可逆损坏）的气候要素极值。', 89);
INSERT INTO `t_military_term_data` VALUES ('c3c1e63c-f7dc-4943-b959-ad2ce971f3dd', '97a19170-bfac-42c5-9906-1acb187f0654', '对空警戒雷达', '用以监视一定的空域,早期发现空中目标并测定其位置的雷达。一般具有较大的探测范围,但测量精度和分辨力不高。', 347);
INSERT INTO `t_military_term_data` VALUES ('c3e79bbc-0015-41c4-86cb-44d7e50a2b1c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '政治工作三大原则', '中国人民解放军在政治工作中实行的官兵一致、军民一致、瓦解敌军三项基本原则。是军队处理官兵关系、军民关系和对敌斗争的准则。', 11);
INSERT INTO `t_military_term_data` VALUES ('c3fd86ef-0f0a-4f4b-9045-6b59fdb326c6', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克车场', '保管、保养和修理坦克及其他装甲车辆的场所与机构。分为永久车场和临时（野战）车场。场内有车库、保养间、修理间、保管间、器材仓库、管理站、加油站、洗车台、消防设施和跑道等。', 222);
INSERT INTO `t_military_term_data` VALUES ('c3fff87c-2245-4e7c-b8d5-1afa43e3e304', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '捕俘技术训练', '为使侦察兵掌握制敌技能而进行的训练。主要训练内容包括由后捕俘、防枪捕俘、防刀捕俘、摔打捕俘、捆绑俘虏、押带俘虏等。', 93);
INSERT INTO `t_military_term_data` VALUES ('c4002f46-f945-47f1-a736-d84327e251a5', '916997ee-6728-4c61-9b79-d96960b1dc86', '核爆炸估算', '简称核估算。对核爆炸毁伤效应的概略计算。包括瞬时毁伤估算和放射性沾染估算。用以评估核袭击对军队造成的损伤和影响,为组织部队行动和消除核袭击后果提供依据。', 42);
INSERT INTO `t_military_term_data` VALUES ('c41b11ad-93c7-41dc-8d78-3175a09628f7', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '岛屿', '比大陆面积小并完全被水包围的陆地。通常把面积较大的称岛,较小的称屿。是控制一定面积水域的立足地,军事上通常易守难攻。', 52);
INSERT INTO `t_military_term_data` VALUES ('c42158ea-69c3-414d-9180-0cfb4dafcbf7', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克火力威力', '坦克武器摧毁和压制目标的能力。主要取决于坦克炮口径、弹丸威力、首发命中率和战斗射速,以及辅助武器的类型和数量等。', 154);
INSERT INTO `t_military_term_data` VALUES ('c4223136-c4f0-4cf5-ba88-acf0f0355fa5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '观炮通信', '炮兵力保障射击指挥而在观察所与炮阵地之间建立的通信联络。通常由炮兵营组织,以有线电话、无线电台和无线电接力等通信手段保障。炮兵连单独遂行任务时，也必须建立观炮通信。', 123);
INSERT INTO `t_military_term_data` VALUES ('c42c15da-1b13-4027-b29b-5377a73640fe', '98df76fb-4b65-48ff-a56c-4db587327c79', '吨公里', '物资周转量的计算单位。运输工具将1吨重的物资运送1公里称1吨公里。', 278);
INSERT INTO `t_military_term_data` VALUES ('c42d42ee-8c00-4cd0-9d6d-5bc19bec6da4', '97a19170-bfac-42c5-9906-1acb187f0654', '空降', '空降兵或其他部队由航空器输送,从空中降落到地面的行动。包括伞降和机降。按规模和任务,分为战略空降、战役空降、战术空降和特种空降等。', 146);
INSERT INTO `t_military_term_data` VALUES ('c431a031-c6e4-4b22-a795-daf8c58cf607', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '入轨', '航天器由发射轨道开始进入运行轨道。当航天器的实际运行轨道偏差在设计要求范围内时,称为精确入轨。', 257);
INSERT INTO `t_military_term_data` VALUES ('c43d1377-fb10-4cba-a373-73fd8f40ee6c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克间隙射击', '坦克使其射弹通过己方战斗队形间隙进行的直接瞄准射击。实施间隙射击时应确保己方部队的安全。', 53);
INSERT INTO `t_military_term_data` VALUES ('c445ae88-a8e6-480c-a46e-423cb63ec7ce', '8a761efd-50a6-4ac8-9913-b7d745104f82', '半自动步枪', '能实现首发后的自动再次装填,但只能单发射击的步枪。战斗射速介于非自动装填步枪和自动装填步枪之间。', 162);
INSERT INTO `t_military_term_data` VALUES ('c44db3db-2c97-4157-93b9-af7bc35c5dc1', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '车辙道', '在路基上铺设两条车辙式路面层而构成的军用道路。通常在构筑急造军路时采用。', 263);
INSERT INTO `t_military_term_data` VALUES ('c4568cd4-99ca-445b-8b61-564426af6670', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上突击', '海军集中兵力、火力对敌海上目标实施急促而猛烈打击的战斗行动。接任务,分为主要突击、辅助突击和预先突击；按方法,分为集中突击和连续突击。', 43);
INSERT INTO `t_military_term_data` VALUES ('c475c2cb-a37c-419b-8dbf-e17582a15cdf', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '连贯作业', '将一个训练课题的内容按顺序贯穿起来,连续地进行作业。通常在分段作业的基础上进行。', 96);
INSERT INTO `t_military_term_data` VALUES ('c47bb3f2-cb25-433a-8f16-8ea37ca2fa52', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '天水线', '亦称水天线。在海上的舰船、飞机所见到的天空与海面相交的边界线。地球表面能见到天水线的距离,取决于观察者所处的海拔高度。', 337);
INSERT INTO `t_military_term_data` VALUES ('c484baea-f2aa-4e42-885b-42c1430c3871', '8a761efd-50a6-4ac8-9913-b7d745104f82', '发火率', '发火的弹药数与发射或投掷的弹药总数的比值。通常用百分比表示。包括底火发火率和引信或其他发火件的发火率。', 122);
INSERT INTO `t_military_term_data` VALUES ('c4898177-46b5-4b9c-9382-99e67efa0251', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '外部装药爆破', '装药配置在目标外部或附近实施的爆破。包括装药直接贴放在目标表面的接触爆破和装药设置在距目标一定距离处进行的非接触爆破。', 236);
INSERT INTO `t_military_term_data` VALUES ('c4a0fafd-b376-4092-a8c4-a5cd5fd21af9', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹着点散布轴线', '在散布面上通过散布中心画的两条相互垂直的直线。散布轴线在垂直散布面上，分为垂直（高低）散布轴线和水平（方向）散布轴线；在水平散布面上,分为纵（距离）散布轴线和横（方向）散布轴线。', 75);
INSERT INTO `t_military_term_data` VALUES ('c4a14cc1-93bd-4896-9ac3-c76414c71c7a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '技术试验卫星', '用于新技术试验或为应用卫星进行先期试验的人造地球卫星。其试验内容广泛,如对新的仪器设备、电火箭以及生物对空间环境的适应性、无线电新频段传输、空间截击等进行试验。', 217);
INSERT INTO `t_military_term_data` VALUES ('c4b1fc8b-b0af-46fd-b00e-0c6b5cfbab11', '31f4a446-5b98-4873-9d53-310d97125b07', '固体发动机探伤设', '用以检测固体火箭发动机裂纹、脱粘等缺陷的设备。包括检测零部件和检测整机的探伤设备。检测零部件的探伤设备主要有X（Y）射线机、超声波探伤仪、涡流探伤仪、磁粉探伤机、红外无损检测仪、激光全息无损检测设备等；检测整机的探伤设备主要有高能实时显像系统、高能射线计算机断层成像（CT）系统等。', 65);
INSERT INTO `t_military_term_data` VALUES ('c4be6435-27e2-442b-bfa2-ff432ab17033', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '荣誉称号', '军队对执行作战、训练和其他任务中功绩卓著、有特殊贡献的单位和个人授予的光荣名称。中国人民解放军中授予的荣誉称号是各种奖励中的最高奖励。由中央军委授予荣誉称号的个人,颁发一级英雄模范奖章；由军区、军兵种级单位授予荣誉称号的个人,颁发二级英雄模范奖章。', 58);
INSERT INTO `t_military_term_data` VALUES ('c4c2ef92-7e1f-4be0-a7e1-50eadf3455e3', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上进攻战', '海军或以海军为主体的兵力在海上向敌实施进攻的作战。是海战的基本类型之一。目的是歼灭或摧毁敌海上兵力集团,夺取制海权等。', 22);
INSERT INTO `t_military_term_data` VALUES ('c4d8cec5-ff12-43fa-a68f-bf9297046ea7', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '无线电技术侦察', '使用无线电技术器材搜集和截收无线电信号的侦察。包括无线电侦听、无线电侦收、无线电测向等。', 55);
INSERT INTO `t_military_term_data` VALUES ('c4e51667-3235-46cd-9fbd-2dec54b8786e', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '泥石流', '沟谷或坡地上松散的土石层被暴雨或冰、雪融水所饱和,形成含有大量泥、沙、石等固体物质的固液两相流体,在重力作用下沿沟谷或斜坡流动的特殊洪流。爆发突然,历时短暂,具有强大的破坏力,能堵塞江河,毁坏路基、桥涵、房屋等。', 82);
INSERT INTO `t_military_term_data` VALUES ('c4e708aa-0e25-4bda-a7f4-c3dd07864bd9', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵线形配置', '亦称一线配置。将数个防空兵分队按照一定间隔在被掩护目标侧方所作的略成一线的配置。通常在掩护狭长目标和线状目标时采用。', 21);
INSERT INTO `t_military_term_data` VALUES ('c50e71a1-87f2-4f01-a84d-113c8b061f60', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击效果', '炮兵时射击任务完成的程度。通常用毁伤概率、毁伤目标数的数学期望等表示。', 220);
INSERT INTO `t_military_term_data` VALUES ('c5169ab1-d125-4ad7-a51f-31510a1003b6', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行高度层', '飞行管制部门以标准水平面为基准,按一定的垂直间隔在空中划分的飞行层次。目的是使航空器之间具有规定的垂直间隔,防止航空器相撞。', 377);
INSERT INTO `t_military_term_data` VALUES ('c52cd782-902d-41d8-ba84-0af02451d55d', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '军需工业', '生产军队给养、被服和装具等军用物资的工业。有些国家称整个军事工业为军需工业。', 45);
INSERT INTO `t_military_term_data` VALUES ('c5343237-0ae9-408b-9674-339ad317bfa8', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海洋调查', '对一定海区的海洋要素分布状况及其变化规律等进行的调查研究。主要包括：海洋水文要素观测,海洋气象要素观测,海水化学要素测定,海洋地质调查,海洋生物调查,以及其他专门调查等。', 123);
INSERT INTO `t_military_term_data` VALUES ('c541997b-142c-4aeb-bd45-3b5e10a75c20', '916997ee-6728-4c61-9b79-d96960b1dc86', '燃气射流洗消车', '利用高温高速燃气射流对大型武器装备实施快速洗消的专用车辆。通常由主车和副车组成。主车上装有燃气射流发生装置,副车上设有输送燃料油或储存发烟剂的装置。主要用于对坦克、自行火炮等装甲车辆等进行洗消,亦可用以装填发烟剂施放大面积遮蔽烟幕。', 192);
INSERT INTO `t_military_term_data` VALUES ('c54b8532-1e84-4da6-91a0-1c1e72b78ede', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核辐射远期效应', '人体受大剂量核辐射照射后造成的慢性伤害作用。可持续数月、数年直至终身。主要症状有造血障碍、白内障、白血病、恶性肿瘤等。', 179);
INSERT INTO `t_military_term_data` VALUES ('c550def8-8249-4dcf-9e1a-33a0ff564feb', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克观察性能', '坦克所具有的可供乘员对外观察的特性与功能。主要取决于坦克观察仪器的性能、数量和在车上的安装位置。', 180);
INSERT INTO `t_military_term_data` VALUES ('c56171b4-7613-4c77-a5a5-b6107ced9937', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军人道德', '符合军人职业要求的行为准则和规范。中国人民解放军的军人道德以爱国主义、集体主义、革命英雄主义和全心全意为人民服务的无私奉献精神为本质特征。', 102);
INSERT INTO `t_military_term_data` VALUES ('c574eeef-8cfc-468f-b576-a12985b67a78', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天运输系统', '能把航天器、航天员或物资等有效载荷从地面运送到太空预定轨道或能将有效载荷带回地面的运输系统。包括运载器和运输器。运载器是能把人造地球卫星、载入飞船、空间站和空间探测器等航天器,从地球上送入太空预定轨道而不返回地面的飞行器,通常为一次性使用的运载火箭。运输器是为在轨道上的航天器运送人员、物资以及进行维修、更换、补给等,并能返回地面的飞行器,通常由推进级和轨道器组成。', 244);
INSERT INTO `t_military_term_data` VALUES ('c57eccf4-532e-4052-97a7-994f660befba', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役企图', '对战役行动的基本设想和打算。是战役决心的重要内容。主要包括战役目的（目标）、使用力量及所要采取的基本方法、步骤等。', 23);
INSERT INTO `t_military_term_data` VALUES ('c58d1104-94e4-4f60-b99f-36a5cbf45fa2', '98df76fb-4b65-48ff-a56c-4db587327c79', '阵地卫生', '为消除或减少阵地环境的不利因素对作战人员身体健康的影响而采取的医学预防措施。包括排水防潮、防寒保暖、通风换气、饮食保障及粪污、尸体的处理等。', 209);
INSERT INTO `t_military_term_data` VALUES ('c58dbd94-e54a-4595-9a04-878d720db88b', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练团', '培训专业新兵和新飞行员的团级建制训练机构。', 14);
INSERT INTO `t_military_term_data` VALUES ('c597a76b-1b5b-4b88-9a1f-ee6cc91cd024', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥观察所', ' ①分队指挥员指挥作战、观察战场的场所与机构、如连指挥观察所②部队指挥所为观察战场情况、保障指挥而建立的分支机构、一般由侦察或作战参谋等人员组成,并携带必要的观察、通信器材', 52);
INSERT INTO `t_military_term_data` VALUES ('c59c4006-f6f6-403f-85eb-577f442bef8d', '97a19170-bfac-42c5-9906-1acb187f0654', '航空杀伤炸弹', '主要以弹体爆炸时产生的大量弹片杀伤人员、破坏目标的航空炸弹。通常用以杀伤地面或水面暴露的有生力量,破坏各种暴露的无装甲或轻装甲的技术兵器。如汽车、火炮、飞机、导弹、雷达等。', 322);
INSERT INTO `t_military_term_data` VALUES ('c5a946dd-6952-4a34-94e6-1884089a06b4', '97a19170-bfac-42c5-9906-1acb187f0654', '空军', '以航空兵为主体,主要遂行空中作战任务的军种。通常由航空兵、地空导弹兵、高射炮兵、空降兵、雷达兵、通信兵等兵种和各种专业勤务部队组成。可单独作战,或与其他军种协同作战。', 0);
INSERT INTO `t_military_term_data` VALUES ('c5b2ba27-4278-4b48-bb78-1800166207c2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事协定', '国家或政治集团之间就军事问题签定的契约性书面协议。是军事条约的形式之一。', 79);
INSERT INTO `t_military_term_data` VALUES ('c5b4af87-2fce-474e-98e6-575644f495e1', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机空战', '武装直升机对空中之敌进行的战斗。其方式有空中截击和空中格斗。通常包括空中搜索、接敌、攻击和退出战斗等阶段。', 66);
INSERT INTO `t_military_term_data` VALUES ('c5be0133-8a39-46b6-af38-6341005cb4f5', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事要地', '具有军事性质或军事价值的重要地点或地区。如军事首脑机关驻地、重要的军事基地（机场、港口、战略导弹发射场）以及重要的高地、关隘、岛屿、海峡、交通枢纽等。', 114);
INSERT INTO `t_military_term_data` VALUES ('c5cba1d9-9a6e-4b6f-bc6a-752390a35df2', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '电视侦收', '使用电视接收设备接收侦察对象播放的电视内容,从中提炼情报的方法。', 60);
INSERT INTO `t_military_term_data` VALUES ('c5e259f4-7745-4049-9b77-a1148df39c93', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防坦克地雷', '主用以炸毁坦克等装甲车辆的地雷。包括反坦克履带地雷,反坦克车底地雷,反坦克履带车底两用地雷,反坦克侧甲地雷和反坦克顶甲地雷等。', 131);
INSERT INTO `t_military_term_data` VALUES ('c5e8cbbb-e093-487a-9aae-fb2561dbf4c2', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '预先警报', '根据可能发生的紧急或危险情况的征候,预先发出的警报。以使有关单位和人员及时作好相应准备。', 36);
INSERT INTO `t_military_term_data` VALUES ('c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '0', '军事气象 . 水文', NULL, 30);
INSERT INTO `t_military_term_data` VALUES ('c6000fc6-6253-41db-bfc2-8ca62fba6b78', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '地域', '作战中对横宽、纵深都作明确标示的陆上一定区域。通常用三个以上的点表述。如XX、XX、XX地域,即指XX、XX、XX之间的地域。', 297);
INSERT INTO `t_military_term_data` VALUES ('c6190c10-dfeb-4c6b-ba7f-973cd8371239', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '武装斗争', '国家、阶级、民族、政治集团之间为达到一定的目的,组织和使用武装力量,采取暴力手段进行的对抗活动。是军事斗争的主要形式。', 0);
INSERT INTO `t_military_term_data` VALUES ('c626753e-c06d-4bbc-ab15-5472ec6f11d7', '0', '战役.战役法', NULL, 6);
INSERT INTO `t_military_term_data` VALUES ('c6297adf-2b15-4cb4-80bb-8636e913066d', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役战术核突击', '战役、战斗中使用核武器对敌实施的突击。通常采取发射核导弹、核炮弹、核鱼雷和投掷核炸弹等方法实施。', 104);
INSERT INTO `t_military_term_data` VALUES ('c630b0ff-c23b-4407-b5a3-075c506f183f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮目高低角', '炮目线与炮口水平面的夹角。', 258);
INSERT INTO `t_military_term_data` VALUES ('c645bebf-d13d-4ec7-8364-0c0fa6a9c4e3', '8a761efd-50a6-4ac8-9913-b7d745104f82', '枪榴弹', '用枪和枪弹发射的爆炸弹药有杀伤、破甲杀伤破甲、燃怀烟蒂等弹种。主要用以杀伤生动目标和对忖薄壁装甲目标、一般弹径 35～75毫米,弹重0.15～1.0千克,反装甲射程50～100米,杀伤射程 50～400米。', 210);
INSERT INTO `t_military_term_data` VALUES ('c64eb802-c553-43d8-a7e1-45285e07ee52', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '人造地球卫星运行轨道', '人造地球卫星运行时质心运动的轨迹。由人造卫星入轨点位置、入轨速度和入轨方向决定。人造卫星的入轨点位置和入轨速度不同,运行轨道也不同。', 228);
INSERT INTO `t_military_term_data` VALUES ('c654296a-875b-475d-80b0-43b4b6d7f8bc', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰种', '同一舰类中按基本任务划分的舰艇种别。如战斗舰艇有航空母舰、战列舰、巡洋舰、驱逐舰、护卫舰。扫雷舰、潜艇等；登陆作战舰艇中有两栖指挥舰、两栖攻击舰。船坞登陆舰、坦克登陆舰、登陆艇等；勤务舰船中有军事运输船、航行补给船、防险救生船、工程船、医院船等。', 123);
INSERT INTO `t_military_term_data` VALUES ('c66c9d1b-3c44-497d-80da-3bcdc61320ed', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '汇报制度', '军队中关于下级向上级、个人向组织汇报思想与工作情况的制度。', 13);
INSERT INTO `t_military_term_data` VALUES ('c67a0d5c-8297-4933-993c-8a181a73f20d', 'f0140091-c11a-48c9-8836-8aa94439dac0', '扩大突破口', '向突破口的翼侧和纵深迅速发展进攻的战斗行动。', 194);
INSERT INTO `t_military_term_data` VALUES ('c67aa97c-c9aa-4de2-a9f0-322a6357942d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水面舰艇操纵', '保持和改变水面舰艇运动状态,以保证安全航行和实施机动的技艺。包括系泊操纵、避碰操纵、风暴中操纵、复杂水域操纵、海上作业操纵、应急操纵等。', 302);
INSERT INTO `t_military_term_data` VALUES ('c68e882f-6f13-4e41-a781-ff04426155f7', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '滑坡', '土体、岩块或堆积物在重力的作用下沿一个或多个破裂滑动面作整体下滑的过程和现象。多发生在坡度小于50度的缓斜坡上,具有很大的破坏性。', 83);
INSERT INTO `t_military_term_data` VALUES ('c68f93ce-ae38-4ae9-8d87-34504130621d', 'f0140091-c11a-48c9-8836-8aa94439dac0', '壕内战斗', '堑壕、交通壕内短兵相接的战斗行动。', 14);
INSERT INTO `t_military_term_data` VALUES ('c6947018-0b58-4876-b6da-65f4eb51303e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵妨害射击', '炮兵封锁敌交通要道或扰乱、迟滞敌行动、削弱其战斗力的射击。', 177);
INSERT INTO `t_military_term_data` VALUES ('c69fa0b1-b06b-4553-bdd8-1189c1b83dab', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '战斗员', '①军队士兵的泛称。相对于指挥员而言。②国际法用语。指参加武装部队的成员,包括士兵和军官。', 113);
INSERT INTO `t_military_term_data` VALUES ('c6b27a61-4d01-42d7-ac4b-38089f0f4fe6', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术方位', '战术目标所在的方向和位置。判定和指示战术方位,通常以某一方位物为基准,按目标与方位物的位置关系来表述。', 40);
INSERT INTO `t_military_term_data` VALUES ('c6b462eb-c106-4da3-8782-74938f7168cb', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '反坦克车底地雷', '简称反车底雷。主要用以击穿坦克底甲,破坏坦克内部设备和杀伤乘员的防坦克地雷。配用近炸引信或触发式触发引信,利用坦克物理场或碰撞触杆使地雷起爆。', 140);
INSERT INTO `t_military_term_data` VALUES ('c6b4e76e-4fe8-412a-8c89-4e08d18f8749', 'd7132c58-5df3-4b97-919f-58740148b9ca', '野战防空武器系统', '用于野战条件下防空作战的地面防空武器系统的统称。主要包括高射机枪、高射炮武器系统、地空导弹武器系统、弹炮合一防空武器系统等。越野能力强,反应速度快,可全天候作战。', 28);
INSERT INTO `t_military_term_data` VALUES ('c6c44410-83d8-42b8-ac65-dbd19e9011f8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '增援', '以兵力援助所属部队或友邻,使其增强作战力量的行动。', 323);
INSERT INTO `t_military_term_data` VALUES ('c6d7f81e-0463-4361-88ad-85ff7ed41355', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲抢救车', '装有专用救援设备的装甲保障车辆。主要用于野战条件下对淤陷、战伤和发生故障的装甲车辆实施拖救和牵引后送。用坦克底盘改装的装甲抢救车,亦称坦克抢救车。', 103);
INSERT INTO `t_military_term_data` VALUES ('c6e415d5-b156-41ff-ae9a-c876ff9ae860', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇幕', '海战中使用多艘潜艇按一定间隔排列而形成的具有一定宽度的幕状战斗队形。通常垂直展开于敌舰船必经航路上。分固定潜艇幕和移动潜艇幕。', 91);
INSERT INTO `t_military_term_data` VALUES ('c6e44ada-37f9-45bb-bf38-7e8a9e8b52a7', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '感应引信', '亦称非触发引信和近炸引信。利用引信上的敏感装置,感应目标信息引爆弹丸的引信。主要包括无线电近炸引信、光近炸引信、声引信、磁引信、电容感应引信、静电引信和水压引信等。配用于炮弹、火箭弹、导弹、航空炸弹、地雷、水雷和鱼雷等弹药。', 337);
INSERT INTO `t_military_term_data` VALUES ('c6ec8cf7-1f88-4da4-a206-afa8103d847f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰级', '同一舰种中按排水量和主要武器装备划分的舰艇级别。有的国家多以首制舰的舰名表示某一舰种的级别。如“尼米兹”级航空母舰,“莱格”级反潜驱逐舰等。', 124);
INSERT INTO `t_military_term_data` VALUES ('c6f19226-ba55-4d7f-971e-bd8cf7795ae2', '98df76fb-4b65-48ff-a56c-4db587327c79', '加油方式', '为军队用油装备加注油料的方法和形式、车辆主要有定点加油、机动加油、分散加油等方式；飞机主要有油车加油、管道加油、空中加油等方式；舰艇主要有码头加油、岸滩无码头加油和海上加油等方式。', 175);
INSERT INTO `t_military_term_data` VALUES ('c6f3ccfd-6de2-48ea-b360-5c76881e710b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '远地点注入', '地球同步卫星发射过程中,在转移轨道远地点附近依靠卫星远地点发动机点火,使卫星由转移轨道进入准同步轨道的轨道机动。转移轨道的远地点在赤道上空,高度约为35786千米。', 263);
INSERT INTO `t_military_term_data` VALUES ('c6f669f1-3d4d-4170-ad34-942fed4757ef', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '给水勤务', '对给水系统运行的管理以及配水、防护与警戒等勤务工作的统称。', 365);
INSERT INTO `t_military_term_data` VALUES ('c6f6e26e-3466-45a7-bb9f-5ac91fb38d7f', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '干部制度', '军队在干部工作方面的政策、法规的统称、中国人民解放军的干部制度,主要包括干部的选拔、培养、考核、任免、晋升、福利、转业、复员、离休、退休以及奖惩等规定。', 79);
INSERT INTO `t_military_term_data` VALUES ('c6f7411f-62d3-452a-8cf8-bc46a213aaf3', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '决心', '指挥员对作战目的和行动的基本决定、内容通常包括作战企图主要作战方向、兵力部署、各部队或分队的任务等。', 75);
INSERT INTO `t_military_term_data` VALUES ('c6fcce6c-b1ba-4661-a7d1-42e2913fe9f3', 'f0140091-c11a-48c9-8836-8aa94439dac0', '夹击', '从相对的两个方向同时向敌实施的攻击。', 162);
INSERT INTO `t_military_term_data` VALUES ('c7035114-758d-4798-ba87-6a0703bab052', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '围困', '对敌实施的围而不攻、断绝外援,将其困饿瓦解的作战行动。', 365);
INSERT INTO `t_military_term_data` VALUES ('c70e6ed7-e712-4f85-93b9-f77b94cabd3b', '878651de-adf5-4c72-9376-9c363b893ff8', '战略封锁', '综合使用军事、政治、经济等手段,对敌国、敌方战略区或重兵集团实施的封锁。', 109);
INSERT INTO `t_military_term_data` VALUES ('c7156d5d-80d9-4d9a-bc35-0caff10a711c', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子干扰强度', '电子设备受到有源压制性电子干扰时影响工作的程度。一般分为3级：一级为弱干扰,基本不影响工作；二级为中等干扰,工作困难；三级为强干扰,无法工作。', 83);
INSERT INTO `t_military_term_data` VALUES ('c72ac836-a483-41c2-8c54-2f84d33abf97', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫生减员', '减员中被送到团救护所以上救治机构的伤员和病员、包括战斗减员中的战伤减员和非战斗减员中的疾病减员、非战斗外伤减员等。', 185);
INSERT INTO `t_military_term_data` VALUES ('c72b396f-18b2-40b3-8908-03ee12c7f7bc', '06a75831-13a1-4660-870a-455bb445336a', '步炮协同通信', '为保障步兵与炮兵的协同作战而建立的通信联络。主要方法有；组织协同无线电网；通过炮兵向步兵派出的作战小组（代表）或炮兵前进观察所的电台建立无线电通信；通过上级指挥网转信；由炮兵向步兵建立野战有线电通信；使用简易信号通信器材等。', 14);
INSERT INTO `t_military_term_data` VALUES ('c72d4c0f-b566-4d51-83b2-fdd9b6918a25', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹制导方式', '将地空导弹导向被攻击目标的方式。有自寻的制导（主动式、半主动式、被动式）、遥控制导（波束制导、指令制导、电视制导）和复合制导（遥控加自寻的制导）等。', 197);
INSERT INTO `t_military_term_data` VALUES ('c72f7f9c-cb87-4c4f-8e1c-1d8c22a3a91b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '单人掩体', '亦称散兵坑。供单兵射击、隐蔽用的露天工事。有卧射的、跪射的和立射的单人掩体。', 62);
INSERT INTO `t_military_term_data` VALUES ('c72fe410-097c-4f3e-8bed-495454521c37', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵基本指挥所', '炮兵实施作战指挥的主要指挥所。通常由炮兵正职首长、参谋长、司令部主要人员和必要的侦察、计算、通信等分队组成。一般配置在合成军队指挥所附近,便于指挥、协同、隐蔽、伪装和机动的位置。', 88);
INSERT INTO `t_military_term_data` VALUES ('c733f283-7492-4ff2-81fa-0c23a83be831', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克技术保障指挥所', '坦克部队战时组织实施技术保障指挥的临时性机构。由主管技术工作的首长和机关有关人员组成。', 227);
INSERT INTO `t_military_term_data` VALUES ('c7410584-7d9a-4f13-bd98-a4a3fcea7e00', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵整组', '对民兵组织进行的调整和整顿。是保证民兵组织健全、民兵工作落实的一项重要措施。通常包括对民兵进行宣传教育、调整编组、调配干部、清点装备等内容。', 126);
INSERT INTO `t_military_term_data` VALUES ('c75475a7-09a0-4f30-a360-b8ab0a03e48f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '立足未稳之敌', '刚由运动状态转为驻止状态已作战准备尚不完善的敌军。通常指临时驻止、仓促转入防御、空降着陆不久和登陆上岸尚不巩固等情况下的敌军。', 239);
INSERT INTO `t_military_term_data` VALUES ('c78f7f45-881e-4871-a74b-ae0ef14790c1', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '天然伪装', '利用地形和能见度不良的天候（夜暗、雾、雨、雪）等自然条件实施的伪装。', 332);
INSERT INTO `t_military_term_data` VALUES ('c79ffcbd-2bd6-4128-ba6c-fc62cb5ca718', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克搭载步兵', '坦克以车体搭载步兵共同实施机动的方法、通常每辆坦克搭载1个步兵班。搭载时应注意敌情威胁情况,密切保持车内外联络和协同。', 25);
INSERT INTO `t_military_term_data` VALUES ('c7adf1c5-2996-460f-89cb-4714200166c8', 'f0140091-c11a-48c9-8836-8aa94439dac0', '江河战斗', '在河流、湖泊等水域进行的战斗。易守难攻,兵力展开和机动受限,指挥、协同、保障较为困难。', 11);
INSERT INTO `t_military_term_data` VALUES ('c7b1f592-8ccc-4bca-b354-e7c179676e0c', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '湖泊', '陆地表面洼地积水形成的面积较宽广的水域。按成因,分为天然湖泊和人工湖泊（水库）；按泄水情况,分为排水湖和非排水湖；按湖水含盐度,分为淡水湖（湖水含盐量小于 l％。）、微咸湖（湖水含盐量在 l％。～24.7％。之间）和咸水湖（湖水含盐量大于 24.7％。）。淡水湖是重要的水源。战时,湖泊可成为一种天然水障。', 74);
INSERT INTO `t_military_term_data` VALUES ('c7b88b24-2ac6-499f-b58a-69e007ab5f1c', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克火控系统', '用以搜索、发现目标和控制坦克武器进行跟踪、瞄准与发射的整套自动化或半自动化装置。主要包括人控计算机、传感器、测距仪、坦克炮稳定器、观察瞄准仪器和操纵机构等。', 119);
INSERT INTO `t_military_term_data` VALUES ('c7b9e756-b049-4384-97c1-9eec759f6aba', '98df76fb-4b65-48ff-a56c-4db587327c79', '运输周转量', '一定时期内运量与运输距离的乘积。其计量单位为吨公里或人公里、是考核、计算运输生产的主要指标。', 277);
INSERT INTO `t_military_term_data` VALUES ('c7d5f458-9019-438d-adba-0f2e488e3e1a', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器耐用性', '轻武器经受长期训练、使用或跌落后仍保持原设计性能的程度。通常要求能经受长期重复操作,跌落后零件不损坏、不发生永久变形仍能继续使用。', 220);
INSERT INTO `t_military_term_data` VALUES ('c7f7ffdb-1579-442b-adee-a2ef8dff03c6', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵群', '由数个炮兵营或连及指挥机构临时组成的战斗编组。按建制,分为集团军炮兵群、师炮兵群、团炮兵群和临时轻便炮兵群；按火炮性能和任务,分为支援炮兵群、机动炮兵群等。', 44);
INSERT INTO `t_military_term_data` VALUES ('c7f97a5f-1cdd-4319-a1fc-72a090aded60', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队团委', '军队中共青团委员会的简称。中国共产中义青年团在中国人民解放军旅、团级单位或初级、中级院校设立的委员会。由同级共青团员代表大会或共青团员大会差额选举产生,并经本级党委批准。在本单位党的委员会、政治机关的领导厂和同级首长的指导卜,领导所属单位的共青团工作和青年工作。', 49);
INSERT INTO `t_military_term_data` VALUES ('c7fc151c-4e96-4cf6-8de5-1967df3ecb56', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '因人施教', '针对受训者的不同情况采取不同的教学方法。', 153);
INSERT INTO `t_military_term_data` VALUES ('c80a145d-ad2a-41e5-8f8b-3cee738c6b27', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '军事网络图', '亦称军事统筹图。用箭头、编号和往记等表示某一军事行动计划及实施程序的示意图。由事件（用圆圈、编号表示）、工作（用箭头表示和文字注记）和线路（表示最初事件至最终事件的各项工作的流程）三个要素构成。运用网络图对军事活动进行计划安排,可简明直观地反映计划的逻辑关系和主要矛盾,以寻求最佳的行动方案。', 153);
INSERT INTO `t_military_term_data` VALUES ('c8159225-1f44-4766-ae4a-a85b182e8a20', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战役训练', '战役军团为掌握战役理论和战役行动的原则与方法而进行的训练。目的是提高战役指挥员及其领导机关的战役指挥能力和战役军团遂行战役任务的能力。按战役基本类型,分为进攻战役训练和防御战役训练；按军兵种,分为陆军战役训练、海军战役训练、空军战役训练和战略导弹部队战役训练；按作战规模,分为集团军战役训练、方面军战役训练和战区战役训练；按战役力量构成及其相互关系,分为合同战役训练和联合战役训练等。主要采取战役集训和战役演习的方式进行。', 91);
INSERT INTO `t_military_term_data` VALUES ('c815d58d-8335-4955-b5d5-6188ce8c2f3c', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击软目标', '暴露在地面上抗力较低,易被核武器摧毁的目标。', 164);
INSERT INTO `t_military_term_data` VALUES ('c8206789-4ed1-49eb-a2b3-cde2f4c0b53f', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '应用地雷', '利用就便器材或其他弹药等自行制作的地雷。', 155);
INSERT INTO `t_military_term_data` VALUES ('c8258546-3747-4050-8b19-5ed24977bcba', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '分导式多弹头', '导弹的母弹头装有发动机和制导装置的导弹多弹头。当母弹头与弹体分离后,母弹头可按预先给定的程序作机动飞行,改变飞行弹道,逐次地或同时释放子弹头,使其沿不同的弹道攻击不同的目标或同一个目标。分导式多弹头能提高突防能力和摧毁目标的能力。', 26);
INSERT INTO `t_military_term_data` VALUES ('c827b916-781d-4908-868b-48ecb9493230', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '反坦克履带车底两用地雷', '简称反履带车底雷或两用雷。具有反履带和反车底两种功能的防坦克地雷。', 141);
INSERT INTO `t_military_term_data` VALUES ('c8324d62-95df-4ffe-aefd-3febf2a1c64a', '916997ee-6728-4c61-9b79-d96960b1dc86', '洗消分队', '担负消毒和消除沾染任务的防化分队。主要负责：对受染的人员、装备进行洗消,对染毒、污染的道路、地域实施消毒,对沾染的坑道工事口部和坚硬路面实施消除。', 4);
INSERT INTO `t_military_term_data` VALUES ('c83a0222-2c61-427e-a6fc-5c713859b864', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队党的纪律检查委员会', '中国共产党在中国人民解放军团或相当于团级以上的部队和单位设立的维护和执行党的纪律的检查机关。在同级党的委员会和上级纪律检查委员会的双重领导下进行工作。', 19);
INSERT INTO `t_military_term_data` VALUES ('c83b3d15-1eaa-4a60-9e46-ffc31f7473db', '878651de-adf5-4c72-9376-9c363b893ff8', '代理人战争', '交战一方或双方在霸权主义国家的利用和操纵下进行的战争。', 21);
INSERT INTO `t_military_term_data` VALUES ('c84d01b4-6a98-43ee-8bcb-6745ebcdf4e5', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克驾驶', '坦克乘员对坦克行驶的操纵。包括基础驾驶、坡上驾驶、通过障碍物驾驶、通过水障碍驾驶、特种驾驶和夜间驾驶等。', 75);
INSERT INTO `t_military_term_data` VALUES ('c85380cb-9a5a-439b-abfe-e5cfd71008e8', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '停泊轨道', '亦称驻留轨道。航天器为转移到另一条轨道而暂时停留的椭圆形或圆形轨道。分为地球停泊轨道、月球停泊轨道和行星停泊轨道。', 241);
INSERT INTO `t_military_term_data` VALUES ('c8546102-c156-4d91-8b3d-8df213b168ae', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '陡崖', '亦称断崖。坡度在70度以上难以攀登的陡峭崖壁。', 135);
INSERT INTO `t_military_term_data` VALUES ('c859e5e2-825e-488e-ab04-90c6640fd904', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军官军衔', '区分和表明军官身份等级的称号和标志。通常分为将官、校官、尉官3等。有的国家还在将官之上设元帅。', 130);
INSERT INTO `t_military_term_data` VALUES ('c86681f4-b82c-4dd2-8d5b-d231d9a35bfb', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '退役', '①军队人员退出现役或预备役。②马匹、武器装备等退出服役状态。', 153);
INSERT INTO `t_military_term_data` VALUES ('c880bf0c-183c-4450-8b32-ae896fdb1025', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '掘开式工事', '采取掘开地面的施工方法构筑的工事。分为掘开式永备工事和掘开式野战工事。', 48);
INSERT INTO `t_military_term_data` VALUES ('c887c88c-38dc-48e2-be3d-fc2c1c1d58c8', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸探测卫星', '用以监视和探测大气层内和外层空间核爆炸的侦察卫星。平时主要用以监视核试验的情况,战时用以收集核爆炸参数（坐标、时间、威力、高度等）,以估计核袭击的效果。', 211);
INSERT INTO `t_military_term_data` VALUES ('c897f7db-aea3-40ef-ac66-3bae9e3738f9', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '护卫舰', '以导弹、舰炮和反潜武器为主要装备的轻型或中型水面战斗舰艇。包括对海型、防空型、反潜型和多用途型等护卫舰。主要用于舰船编队反潜、防空以及护航、巡逻、警戒、侦察,支援登陆和抗登陆作战等。', 135);
INSERT INTO `t_military_term_data` VALUES ('c8ae73d0-a795-4ce9-b5b1-8af4847aa966', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹弹翼', '安装于导弹弹体上的翼面。其功能是产生空气升力,对导弹飞行起稳定作用。', 31);
INSERT INTO `t_military_term_data` VALUES ('c8af2a94-e257-49cd-91a4-c20d824b33c0', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮指挥机', '炮营以上指挥所射击指挥用的集中控制有线电和无线电通信的设备、可实施通播、专向和分组通信以及越级指挥。', 129);
INSERT INTO `t_military_term_data` VALUES ('c8ba24d7-37e4-4b58-af4d-4fdab88983a1', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '河谷', '河流所流经的线状延伸的凹地。包括谷坡和谷底两部分。山区河谷多窄深,谷底被河床占据,谷坡较陡。平原地区河谷较宽浅,除河床外,还有宽阔的河漫滩和阶地,谷坡较缓。', 63);
INSERT INTO `t_military_term_data` VALUES ('c8d6544b-886e-43cd-8edc-47b4d47c9d71', '98df76fb-4b65-48ff-a56c-4db587327c79', '分站', '兵站派出的主要负责物资供应的分支机构。', 16);
INSERT INTO `t_military_term_data` VALUES ('c8d68fc4-983f-4645-891b-4f6b8e14b93f', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '冲击波动压', '核爆炸冲击波内,空气高速运动形成的强大冲击压力。可使人体抛出、碰撞而致伤亡,工事建筑物倒塌,造成武器毁坏。', 159);
INSERT INTO `t_military_term_data` VALUES ('c8db42c3-1d92-4a6e-80b6-312d3e19d292', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '反卫星武器', '用以攻击、破坏、干扰敌方卫星等航天器的空间武器。分为陆基反卫星武器、海基反卫星武器、空基反卫星武器、天基反卫星武器。主要利用核能或动能、定向能等杀伤手段毁伤目标。', 225);
INSERT INTO `t_military_term_data` VALUES ('c8dbad0d-719c-4531-a0b6-c1971be45e47', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '两栖船坞运输舰', '亦称船坞式登陆运输舰。舰上设有船坞,用以运载登陆兵、登陆艇、战斗车辆、武器装备和物资,实施由舰到岸登陆的登陆作战舰艇。', 147);
INSERT INTO `t_military_term_data` VALUES ('c8e8b97d-8dbc-483f-9d9a-d9587263732e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '箭霰炮弹', '弹体内装有大量小钢箭的炮弹。炮弹飞抵目标区时,在时间引信作用下弹体炸裂,小钢箭喷射而出,杀伤有生力量。', 317);
INSERT INTO `t_military_term_data` VALUES ('c8e956bc-1831-4d28-9b5c-a8c6d48fc76e', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '地面传感器侦察', '使用地面传感器探测运动目标的侦察。包括使用音响、磁、电磁、震动、压力、红外辐射等传感器进行的侦察。', 63);
INSERT INTO `t_military_term_data` VALUES ('c8f26235-9343-4d8a-9ec0-925cad64f518', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤编成', '按照一定的要求把后勤力量组成有机的整体。是战役、战斗编成的组成部分。', 57);
INSERT INTO `t_military_term_data` VALUES ('c8ffa6d9-dba6-4bb9-83de-933e247f1e19', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '党课', '授课的形式对共产党员进行的党内教育。', 46);
INSERT INTO `t_military_term_data` VALUES ('c911706f-858f-4a92-ad50-67e7a23d92de', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '校阅', '首长或领导机关对部队、院校进行的检查和视察活动。分为定期校阅和临时校间。主要形式有点验、视察、考核、比武、演习和阅兵等。', 65);
INSERT INTO `t_military_term_data` VALUES ('c9149783-e16f-4fef-8cf0-0ea503259ca6', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥要素', '构成军队指挥的必要因素。主要包括指挥主体指挥对象、指挥手段等。', 4);
INSERT INTO `t_military_term_data` VALUES ('c9212362-1948-4a7a-92f3-8afea447d169', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '牵制', '以兵力、火力吸引和拖住敌人的作战行动。主要用以配合或掩护主要战场、主要方向或主力部队的作战。分为战略牵制、战役牵制和战术牵制。', 348);
INSERT INTO `t_military_term_data` VALUES ('c9329f11-c608-4e88-ae3f-3fcaae95a978', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵', '地空导弹、高射炮、高射机枪为基本装备,主要遂行地面防空作战任务的有关兵种和部队的统称。包括地空导弹兵、高射炮兵和雷达、电子对抗部队等。可在合成军队编成内或单独遂行防空作战任务。', 0);
INSERT INTO `t_military_term_data` VALUES ('c93efcce-d24a-43b5-9415-bf5265f2c36b', 'f0140091-c11a-48c9-8836-8aa94439dac0', '前沿支撑点', '营防御地域内第一线连、排坚守的支撑点。', 238);
INSERT INTO `t_military_term_data` VALUES ('c9402666-d922-408c-b683-2051541c8922', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '子午面', '通过地面上一点包含地球南北两极的平面。包含沿垂线方向并与地球自转轴平行的平面,称天文子午面；包含参考椭球面的法线及其短轴的平面,称大地子午面。', 200);
INSERT INTO `t_military_term_data` VALUES ('c9483e86-af2d-48f4-8511-55b74623819d', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役理论', '关于战役问题的系统化理性认识和知识体系。它产生于战役实践,又给战役实践以指导,并受战役实践的检验。', 16);
INSERT INTO `t_military_term_data` VALUES ('c94aaa6f-17f0-42f8-9034-65e6f8107a7a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '突破', '在敌防线或防御阵地中打开缺口的作战行动。分为战略突破、战役突破和战术突破。', 361);
INSERT INTO `t_military_term_data` VALUES ('c9612304-8931-48b8-9d05-8c6d35ceca52', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '无坐力炮', '利用发射时后喷物质的反作用力使炮身不后坐的火炮。体积小、重量轻,结构简单,操作方便,但射程近,且发射时后喷火焰大,易暴露。主要用以摧毁近距离装甲目标和火力点。', 27);
INSERT INTO `t_military_term_data` VALUES ('c96f3a35-442a-4c6c-a543-5d0e3923008d', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '浮尘', '大量尘沙等细粒悬浮在空中,致使水平能见度小于10千米的天气现象。出现时天空呈上黄色。常在风沙天气之后或随气流从远处移来,严重时水平能见度可降至1千米以下。', 32);
INSERT INTO `t_military_term_data` VALUES ('c974cb25-d141-4e8e-8faa-3ef7a272df8a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '大地坐标', ' 大地测量中以参考椭球面为基准面的坐标。地面一点的位置,通常用大地经度、大地纬度和大地高表示。', 232);
INSERT INTO `t_military_term_data` VALUES ('c97ba65d-5d04-452f-a79e-01b60b4837d4', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸深度', '简称爆深。核武器在地面或水面以下爆炸时,从爆心到地面或水面的垂直距离。', 145);
INSERT INTO `t_military_term_data` VALUES ('c98e92c4-d7f5-4cff-a828-eb5959d1e610', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹兵战斗部署', '根据防空作战任务和战斗决心对地空导弹兵所作的任务区分、编组和配置。基本形式有环形部署、扇形部署、宽正面部署和集团部署。', 133);
INSERT INTO `t_military_term_data` VALUES ('c99aa017-2c10-477d-acad-8d3715db1a31', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行装具', '飞行人员飞行时必须携带的制式装备和用具的统称。包括飞行图囊、飞行包、领航通信包。飞行风镜、飞行头盔等。', 403);
INSERT INTO `t_military_term_data` VALUES ('c9a15ea1-8554-44fc-862c-5fd23664f763', '878651de-adf5-4c72-9376-9c363b893ff8', '战略预测', '对战争或其他全局性的重大问题所作的宏观预计和推测。', 67);
INSERT INTO `t_military_term_data` VALUES ('c9c5a393-1d06-4800-9799-48fef5d5ff34', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '报务分析', '亦称台情分析。对侦察对象的无线电台通信联络情况进行综合研究,从中获取情报的工作。是无线电技术侦察获取情报的重要环节。', 145);
INSERT INTO `t_military_term_data` VALUES ('c9c5ba75-7225-44a6-8dbf-44b3202826cd', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '导爆索', '以猛炸药为芯药,用以传递爆轰波的索类火工品。按外壳材料,分为棉线导爆索、塑料导爆索、橡胶导爆索和金属导爆索。', 219);
INSERT INTO `t_military_term_data` VALUES ('c9c6ba9a-6027-472a-b1a0-33ee71a49136', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '接力输送', '在同一输送过程中,采用两种以上输送工具或两个以上单位以接力方式进行的输送。', 78);
INSERT INTO `t_military_term_data` VALUES ('c9c8ece1-a068-4382-b814-d40b21a960a2', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇满灯', '舰艇停泊时在夜间沿满旗位置和舰舷、上层建筑轮廓悬挂彩灯的隆重礼仪。用途与舰艇满旗相同。', 401);
INSERT INTO `t_military_term_data` VALUES ('c9cb1d7b-78d4-4cab-9ace-606920c64521', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵待机阵地', '炮兵等待遂行射击任务时占领的阵地。通常选择在便于隐蔽,进出方便,距各炮阵地位置适中的地点。', 59);
INSERT INTO `t_military_term_data` VALUES ('c9e0c326-8395-419e-b4ba-f73b94e7c53c', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹基本阵地', '以导弹部队准备和实施导弹突击的主要作战阵地。通常预先构筑有坚固的工程设施,包括指挥所、技术阵地、发射阵地、储存库及各种保障设施等。', 41);
INSERT INTO `t_military_term_data` VALUES ('c9e78a7f-d6d9-4d2e-bc4a-1dabd6720a5d', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '党支部', '党的基层组织。中国共产党在中国人民解放军连队或相当于连级的单位以及机关部门和教学、科研、技术、医疗等机构中的基层单位设立的支部。连队党支部,是连队统一领导和团结的核心；教学、科研、医疗、技术等基层单位党支部,是该单位政治领导和团结的核心；机关部门党支部,则主要起监督保证作用。', 43);
INSERT INTO `t_military_term_data` VALUES ('c9ea0859-a5a5-4d5f-8284-6de0099045f6', '97a19170-bfac-42c5-9906-1acb187f0654', '歼击机', '以航炮、航空火箭、空空导弹等为基本武器,具有空战能力的作战飞机。分为昼间歼击机和全天候歼击机。主要用以攻击敌空中目标,必要时也可用以攻击敌地面、水面目标。', 281);
INSERT INTO `t_military_term_data` VALUES ('c9ec9ef3-28ea-40ad-beb1-8619737e9c56', '06a75831-13a1-4660-870a-455bb445336a', '无线电通信纠察', '为发现和纠正无线电台通信中违犯通信纪律现象而采取的措施。分为专台纠察和相互纠察。', 39);
INSERT INTO `t_military_term_data` VALUES ('c9eee452-732e-4d5f-9cc2-9991609d4fce', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '针叶林', '以松、杉类针叶树为主的森林。分为常绿针叶林和落叶针叶林。树叶呈针状、条状和鳞片状,树干多通直,树冠多为圆锥形。', 92);
INSERT INTO `t_military_term_data` VALUES ('ca2c10e9-7918-4356-9b1b-ec25a8d65ca4', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天器机动飞行', '航天器有目的地改变运行轨道的飞行。军事航天常用的机动飞行有：改变运行轨道的高度,与另一个航天器接近、交会,离开原来的运行轨道等。', 278);
INSERT INTO `t_military_term_data` VALUES ('ca34e0da-70f4-4dfc-a921-be47f952165c', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '领水', '主权国家内水和领海的水域。是国家领土的组成部分。', 72);
INSERT INTO `t_military_term_data` VALUES ('ca4e531f-c21f-4b8a-9ee8-fd85491293c1', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '隐蔽爆破', '隐蔽接近目标突然实施的爆破。通常利用夜暗、不良天候和地形等自然条件,或采取伪装、佯动等措施进行。', 249);
INSERT INTO `t_military_term_data` VALUES ('ca655afa-c564-47ba-9bfd-c4a8531b28c0', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上空域', '海洋上的空中区域。通常指海军航空兵为实施海上训练与作战而划定的海洋上的空域范围。', 382);
INSERT INTO `t_military_term_data` VALUES ('ca7088cf-4595-48b8-9b20-4cbbd1590dcd', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '突击力', '攻击行动所具有的急剧、猛烈的打击能力。', 271);
INSERT INTO `t_military_term_data` VALUES ('ca7e3c37-987e-4840-99ad-94917b1e9772', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '野战给水工程', '野战条件下用于军队给水的工程设施。主要包括；开辟水源和取水的构筑物,汲水、水处理和储水的设施,输配水设施及其附属工程等。', 358);
INSERT INTO `t_military_term_data` VALUES ('ca826041-ea36-47da-b0bb-1c98fbacc93d', '878651de-adf5-4c72-9376-9c363b893ff8', '战略决策', '对战争或其他全局性的重大问题所决定的策略或办法。', 68);
INSERT INTO `t_military_term_data` VALUES ('ca905068-76d7-4652-9fc3-4b3e39828a5c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核试验场', '建有各种工程技术和保障设施可进行核试验的固定场区。', 191);
INSERT INTO `t_military_term_data` VALUES ('ca933a34-a25a-4969-960b-64c14f7685bd', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克屏蔽装甲', '装在坦克主装甲外,并与主装甲有一定间距的附加装甲。其作用是提前引爆射弹空心装药的战斗部,以降低作用在主装甲上的穿透能力。安装在行动装置外部的屏蔽装甲亦称裙板。', 135);
INSERT INTO `t_military_term_data` VALUES ('ca9ae04d-2f36-4104-9359-c33ef3a0cca0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '试射后修正量', '对目标或试射点试射后所求得的射击条件修正量。用以修正射击开始诸元和效力射诸元之间的偏差。', 160);
INSERT INTO `t_military_term_data` VALUES ('ca9f8f15-3df9-464d-8db4-66f5f3c652a9', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教材', '进行教育和训练所使用的各种教学材料的统称。通常包括教程、教范、讲义、讲授提纲、教学参考书以及图片等教学辅助材料。是进行训练和教学的基本条件和重要工具。', 37);
INSERT INTO `t_military_term_data` VALUES ('caa5f7ca-d312-4abf-9d33-e526c680a6a5', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹火力机动', '导弹在不变换发射阵地时,用改变射向和射程的方法进行的由一个目标向另一个目标的火力转移。', 142);
INSERT INTO `t_military_term_data` VALUES ('cab48018-e949-45e1-89fd-febb559be24b', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '欺骗性电子干扰', '简称欺骗性干扰,亦称电子欺骗。使敌方电子设备接收虚假信息,以至产生错误判断和错误行动的电子干扰。按干扰产生的方法,分为有源欺骗性干扰和无源欺骗性干扰。', 42);
INSERT INTO `t_military_term_data` VALUES ('cabef919-4333-451d-b57f-8688489e34c8', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '预备役训练', '对预备役部队和人员进行的训练。主要内容有军事知识和作战技能。通常包括：预备役部队训练,民兵训练,高级中学、高等院校学生的军事训练。', 66);
INSERT INTO `t_military_term_data` VALUES ('cabf0182-b67e-470e-ade5-784137ebb8b7', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击目标侦察', '为获取核打击目标的有关情报而进行的侦察。通常采用侦察卫星、飞船、预警飞机等现代侦察手段实施。', 167);
INSERT INTO `t_military_term_data` VALUES ('cacf38bc-abdc-4cf9-917e-0645d27a9f76', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海况', '风力作用下的海面外貌特征。根据视野内的海面状况、波浪的波峰形状和破碎程度以及浪花飞沫出现的多少等,可将海况划分为10级。有时亦泛指海水的成分、温度、盐度、密度,以及海流、波浪等情况。', 127);
INSERT INTO `t_military_term_data` VALUES ('caf0130d-3d26-4984-8bfe-22b7d906b60c', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥关系转换', '部队所从属的直接指挥员及其指挥机关的改变。如某师原属某集团军指挥,因作战需要转属另一个集团军指几', 14);
INSERT INTO `t_military_term_data` VALUES ('caf95547-8000-4f51-83c1-53b1bbe4646d', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防支出', '亦称国防开支。国家财政中用于国防的经费支出。包括国防建设费用支出和战争费用支出。', 37);
INSERT INTO `t_military_term_data` VALUES ('cb38bc02-5555-41a8-ad4a-4488717031e8', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '道路维护', '对军用道路的管理、养护和抢修等的统称。', 266);
INSERT INTO `t_military_term_data` VALUES ('cb39d403-b8a6-49fc-83fc-95ff4237001e', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方勘察', '对后方地域的敌情、社情、地形、交通、水源、气象、疫情以及人力、物力资源等情况进行的实地察看和调查。', 46);
INSERT INTO `t_military_term_data` VALUES ('cb3d09b8-c146-4aef-9a46-daf46f31aa7b', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '反电子干扰训练', '简称反干扰训练。雷达、无线电通信等专业部队、分队和人员为提高在电子干扰条件下工作的技能而进行的训练。主要内容包括理论学习、模拟训练、操作训练、近似实战条件下的战术合练等。', 15);
INSERT INTO `t_military_term_data` VALUES ('cb44f651-b317-4a07-a3e1-72ca64384107', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水文侦察', '为军事目的而在预定海域内对海洋水文情况进行的侦察。', 54);
INSERT INTO `t_military_term_data` VALUES ('cb4ac086-bd8a-441e-994a-431d73eff21d', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '编制职务', '军队编制规定的工作职位。如团长、政治委员、连长、政治指导员、参谋、干事、助理员等。', 98);
INSERT INTO `t_military_term_data` VALUES ('cb5d3a3c-ac1f-42a0-860f-b708b817346c', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹储存维修技术', '为使导弹安全可靠和保持、恢复良好状态而采用的各种技术的统称。包括导弹储存技术和导弹维修技术。导弹储存技术有储存设施技术、安全存放技术、储存环境技术、储存监控技术及安全设施技术等；导弹维修技术有保养技术、检测技术、故障诊断技术和修复技术等。', 200);
INSERT INTO `t_military_term_data` VALUES ('cb638581-f52b-4996-b9d5-041f5f5c8163', 'f0140091-c11a-48c9-8836-8aa94439dac0', '独立战斗', '在没有上级支援和友邻配合的情况下单独进行的战斗。', 18);
INSERT INTO `t_military_term_data` VALUES ('cb63bb6c-06f4-4bac-b4c0-d1cee556d274', '916997ee-6728-4c61-9b79-d96960b1dc86', '停留剂量', '人员在沾染区内停留时受到的照射量或吸收剂量。单位是库仑／千克或戈瑞。', 103);
INSERT INTO `t_military_term_data` VALUES ('cb68e2e6-b710-44bb-ad31-1d64105246d6', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '哨兵', '执行警戒任务的士兵。如步哨、游动哨、潜伏哨等。', 25);
INSERT INTO `t_military_term_data` VALUES ('cb6bdead-25f4-477f-88a3-38cb6830ac7e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '布雷密度', '亦称地雷场技术密度。地雷场中布设地雷的疏密程度。用人工和机械布设的地雷场的密度,是指地雷场每米正面布设地雷的平均数；用火箭、飞机、火炮等撒布的地雷场的密度,是指地雷场每平方米内撒布地雷的平均数。', 190);
INSERT INTO `t_military_term_data` VALUES ('cb739682-a357-4446-bd95-5e846d2cd1e6', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察正面', '侦察任务所及区域的正面。通常略大于本级部队作战任务的正面。', 104);
INSERT INTO `t_military_term_data` VALUES ('cb7a4b38-30dc-47f2-937c-278a46be27a5', '06a75831-13a1-4660-870a-455bb445336a', '战术通信训练', '为提高组织实施战术通信的能力而进行的训练。主要包括：通信联络基本原则,通信分队的组织指挥，通信枢纽的开设、撤收和转移，通信手段的运用,指挥自动化系统的建立与管理,通信技术保障,通信对抗与通信防护等。', 217);
INSERT INTO `t_military_term_data` VALUES ('cb82db58-2b6e-462c-9845-f3024e10fa0d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '残敌', '由未被彻底歼灭而剩下的敌人。', 373);
INSERT INTO `t_military_term_data` VALUES ('cb877f65-d758-4228-9d7a-ec0ae9108438', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵侦察', '防空兵为获取作战所需的敌情、地形和气象等资料而进行的侦察。分为对空中目标侦察、对地面和水面目标侦察、对地形和道路侦察等。', 107);
INSERT INTO `t_military_term_data` VALUES ('cb8f3d18-3016-45cd-9be4-6ba8b2468a68', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '近迫作业', '在敌直瞄火力威胁下,用携带的土工工具挖掘掩体的作业。通常先挖成卧射掩体,根据需要逐步加深为跪射、立射掩体,尔后连接成堑壕。有条件时也可使用单人掩体爆破器构筑掩体。', 88);
INSERT INTO `t_military_term_data` VALUES ('cb9346f0-dc58-4252-8ff8-9ae4415c1c85', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军出发点', '行军纵队实施行军的起点。通常选择在宿营或集结地域前方进出方便、地形隐蔽、便于识别的地点。行军纵队的各部分应按规定的顺序和时间,依次通过此点,尔后形成行军序列。', 64);
INSERT INTO `t_military_term_data` VALUES ('cbd00c5e-5e6d-4cde-af03-28ed24aaff21', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练管理', '为正规、统一施训,确保质量,对军事训练工作进行的管理。主要是按照训练法规、制度,对部队的训练活动实施筹划、组织、指导、监督和检查。', 8);
INSERT INTO `t_military_term_data` VALUES ('cbe7a291-714f-4b9e-9d08-1d891796ddfd', '97a19170-bfac-42c5-9906-1acb187f0654', '军用机场', '供军用飞机或直升机起飞、着陆、停放和组织飞行保障活动的固定场所。包括飞行场地和各种保障设施。按保障条件和用途,分为永备机场和野战机场；按所在位置,分为前沿机场和纵深机场；按跑道基本长度,分为特级、一级、二级、三级军用机场。特级军用机场可供远程轰炸机、远程运输机等使用；一级军用机场可供中程轰炸机、中程运输机等使用；二级军用机场可供歼击机、强击机、歼击轰炸机和中近程运输机等使用；三级军用机场可供初级教练机和近程运输机等使用。', 409);
INSERT INTO `t_military_term_data` VALUES ('cbedc498-a130-49f0-a7cf-11c7f6fd1bce', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机水平机动攻击', '直升机在空中水平面上的机动飞行中对敌方目标进行的攻击。主要是为避开敌防空火力的杀伤,选择恰当的攻击时机和角度。', 83);
INSERT INTO `t_military_term_data` VALUES ('cbff1a09-4152-4a55-80c8-5fa27fd72cea', '97a19170-bfac-42c5-9906-1acb187f0654', '受阅飞行', '飞机或直升机接受检阅的飞行。通常在重大节日或重要军事演习时举行。', 211);
INSERT INTO `t_military_term_data` VALUES ('cc00650e-51c9-496d-a75b-c2e40596aa53', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '远海', '近海以外的海区。', 378);
INSERT INTO `t_military_term_data` VALUES ('cc0b35c6-09e6-4d38-884d-583eef2462cc', '06a75831-13a1-4660-870a-455bb445336a', '视距通信', '亦称直射波通信。电波从发射天线直接辐射到接收天线的超短波或微波通信。包括视距内的无线电台（站）之间、通信卫星与地球站之间、飞行器之间的直射波通信。所需发射功率较小,通信较稳定。', 120);
INSERT INTO `t_military_term_data` VALUES ('cc14de42-c787-4e79-b7e3-670c7a209f26', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练科目', '按一定的知识和技能范围,对军事训练的内容所划分的类别、如对部队军事训练的内容划分为共同科目、技术科目、战术科目等。', 24);
INSERT INTO `t_military_term_data` VALUES ('cc1a3f1f-aa2a-4282-9477-1c2c167aa192', 'd7132c58-5df3-4b97-919f-58740148b9ca', '遭遇点', '地空导弹接近目标,战斗部起爆瞬间空中目标所在的位置。', 166);
INSERT INTO `t_military_term_data` VALUES ('cc438447-e01b-45d3-a649-ffc059e3d465', '31f4a446-5b98-4873-9d53-310d97125b07', '核袭击安全距离', '使用核武器时为确保己方前沿部队或所要保护的目标免遭杀伤破坏的最小距离。通常为距预定爆心投影点的安全距离与可能的最大偏差距离之和。其大小主要取决于命中精度、核爆炸威力、爆炸方式、气象条件和部队配置地域的地形特点。', 38);
INSERT INTO `t_military_term_data` VALUES ('cc53f7b8-52d4-4159-9e08-e56869208350', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '近岸波', '亦称拍岸浪。外海的风浪或涌浪传播至海岸或岛屿附近,因受地形作用改变其波动性质的海浪。由于波浪由深水向浅水传播,其波长变短,波高增高,最后发生卷倒、破碎现象,同时海水向前流动,水面高度发生变化。近岸波对军港设施和舰船靠泊、作业等影响较大。', 131);
INSERT INTO `t_military_term_data` VALUES ('cc5b946a-058c-4bb5-a9fc-640a1c8d38e0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵测地车', '亦称连测车。主要用以送行连测炮兵战斗队形任务的专用车辆。车上装有陀螺车向仪、路程传送器、计算机、绘图仪、瞄准装置和电源设备等。通常用以连测炮兵战斗队形,还可用以引导部队在夜间或地形点稀少的条件下行进,并能自动标绘行进路线。', 285);
INSERT INTO `t_military_term_data` VALUES ('cc63e147-a124-48a5-9a71-fa54a055932a', '98df76fb-4b65-48ff-a56c-4db587327c79', '被装', '军队被服和装具的统称。是军需物资的组成部分。', 148);
INSERT INTO `t_military_term_data` VALUES ('cc944eac-a972-41bd-be21-4e223b505e94', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵驾驶训练', '坦克及其他装甲车辆乘员为熟练掌握驾驶技能而进行的训练。', 74);
INSERT INTO `t_military_term_data` VALUES ('cc9e4204-980f-4dee-acde-a05f20cb5766', 'f0140091-c11a-48c9-8836-8aa94439dac0', '冲击准备', '到达冲击出发阵地或展开地区后至发起冲击前的短暂时间内所进行的最后攻击准备。包括单兵、单车冲击准备和分队冲击准备。', 182);
INSERT INTO `t_military_term_data` VALUES ('ccaa6b11-1d26-449b-88fd-1976386e521b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '指挥舰艇', '舰艇编队中指挥员所在的舰或艇。指挥舰亦称旗舰。通常装备有相应的指挥设备,能指挥、控制所属舰艇和飞机、直升机的作战行动。', 259);
INSERT INTO `t_military_term_data` VALUES ('ccc112ed-3a00-4811-ad96-bd1c9d9d6807', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '防御战役', '抗击敌人进攻的战役。是战役基本类型之一。根据防御作战的性质、规模、空间及地理环境等,分为不同样式的防御战役。如阵地防御战役、运动防御战役,战区防御战役、集团军防御战役,防空战役、抗登陆战役、城市防御战役等。', 117);
INSERT INTO `t_military_term_data` VALUES ('cccac96f-d838-4eb7-bdd5-54f8361e524e', '97a19170-bfac-42c5-9906-1acb187f0654', '短距起落飞机', '能在很短距离内滑跑起飞和着陆的飞机。', 270);
INSERT INTO `t_military_term_data` VALUES ('ccd76979-7552-4c61-aa57-1888b651e19d', '8a761efd-50a6-4ac8-9913-b7d745104f82', '斜射', '射向与目标正面成锐角的射击。射向与目标正面之间的角度愈小,斜射愈接近侧射。', 109);
INSERT INTO `t_military_term_data` VALUES ('ccdb0493-e88e-4d2b-8b84-8bc4c75cbeef', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射程序', '按照规定的时限和要求组织实施发射导弹的各项工作顺序。包括占领发射阵地、发射准备、临射前检查、发射等。', 107);
INSERT INTO `t_military_term_data` VALUES ('ccfd4c94-6b2c-42f8-a169-208fd98dbcbc', '97a19170-bfac-42c5-9906-1acb187f0654', '空中游猎', '亦称空中游击。航空兵部队以小编队或单机在空中分散游动,以寻歼敌空中或地面目标的战斗活动。', 114);
INSERT INTO `t_military_term_data` VALUES ('cd091cb1-d2ea-4013-96d5-17dcc937052e', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射环境条件', '保障导弹正常发射所必须具备的自然环境方面的条件。通常包括；规定范围的大气温度、湿度,风速、雨、雪、雷暴,海拔高度,经纬度,重力场和大地磁场等。', 120);
INSERT INTO `t_military_term_data` VALUES ('cd17435d-5ca4-4517-9284-a25ea768d36c', '98df76fb-4b65-48ff-a56c-4db587327c79', '军队财务法规', '有关军队财务的各种法律规范文件的统称。主要包括财务工作的条例、规定、规则、办法和经费标准等。是军队内部组织财务活动的准则和调整经济关系的依据。', 73);
INSERT INTO `t_military_term_data` VALUES ('cd1e0f5a-4ec2-44f9-92a7-3521ff1cefdb', 'f0140091-c11a-48c9-8836-8aa94439dac0', '掩护支队', '担负掩护任务的战斗编组。通常由师以上部队派出,兵力为1个加强营至1个加强团。', 53);
INSERT INTO `t_military_term_data` VALUES ('cd233d7e-2b66-4508-b84a-8ed1fd9df9f3', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '正规化训练', '按统一规范要求进行的训练、要求训练的内容、手段以及组织实施的方法等应符合统一的规定。', 3);
INSERT INTO `t_military_term_data` VALUES ('cd24f816-8101-4257-8cc8-f0879df7d636', '916997ee-6728-4c61-9b79-d96960b1dc86', '中毒途径', '毒剂进入机体造成伤害的途径。包括吸入中毒、食入中毒和渗透（从皮肤、伤口、眼睛进入）中毒。', 117);
INSERT INTO `t_military_term_data` VALUES ('cd2b2f94-a64d-4247-83ee-4806c0cf099f', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天候', '天气、气候及某些天文现象的泛称。通常指某一地区某一时段的阴晴、冷暖、干湿、雨雪等天气、气候特征,以及日出日没、昼夜长短等天文现象。', 83);
INSERT INTO `t_military_term_data` VALUES ('cd368fb8-7eda-406d-8949-7ad1e99b2edf', '98df76fb-4b65-48ff-a56c-4db587327c79', '交替保障', '两支后勤力量交替转移、轮流展开所实施的后勤保障。通常在部队担负长距离快速机动作战任务时采用。', 28);
INSERT INTO `t_military_term_data` VALUES ('cd39f812-76e8-4e4b-ac41-da53169dbd4d', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵模拟训练器材', '能模仿炮兵武器装备的作用、战术技术性能或战场某些景况的训练器材。如模拟炮、炮兵射击指挥模拟器、激光代炮射击练习器等。', 302);
INSERT INTO `t_military_term_data` VALUES ('cd4af99a-d352-46f3-b973-94c896e99675', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克掩体', '坦克射击和隐蔽用的露天工事。由供射击和掩蔽的平底坑、斜坡进出口、乘员避弹所或掩壕组成。', 41);
INSERT INTO `t_military_term_data` VALUES ('cd5a4c25-0122-4648-a7f9-4c56cd620e0c', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行日', '航空兵部队按照训练计划组织实施飞行训练的工作日。根据一天中飞行场次的时间安排,分为昼间场。夜间场和跨昼夜场等。', 249);
INSERT INTO `t_military_term_data` VALUES ('cd5f0534-123e-460e-abc8-9dfe29a286a3', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '第一梯队', '作战部署或战斗队形中配置在最前面的梯队。进攻时,用以突破敌之防御；防御时,用以扼守第一线防御阵地。', 315);
INSERT INTO `t_military_term_data` VALUES ('cd62e0d0-d602-48eb-b32a-9a3287da3b15', 'f0140091-c11a-48c9-8836-8aa94439dac0', '倒射火力', '亦称反射火力。射击方向指向目标背面的火力。', 87);
INSERT INTO `t_military_term_data` VALUES ('cd6f3105-ebd6-4dc8-bbf7-c7cf770570a7', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '代管', '根据上级的命令、指示和规定,对建制外的单位、人员或非分管的工作实行的领导和管理。', 67);
INSERT INTO `t_military_term_data` VALUES ('cd74ad0e-5f57-4bbb-9934-90daf6f09b82', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '误越国境', '因国界标志不明及其他原因而无意地出入国境的行为。', 95);
INSERT INTO `t_military_term_data` VALUES ('cd7d7bc4-e4a2-4f2a-b60f-e671605ed569', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战模拟', '按照已知的或假定的情况和数据对作战过程进行的模仿。主要包括实兵演习、沙盘作业或图上作业、兵棋博奕、计算机作战模拟等。通常用以研究、检验作战计划,评价武器装备效能,研究新的作战理论等。', 165);
INSERT INTO `t_military_term_data` VALUES ('cd83525e-7f45-47a0-a43b-04a63ca41b50', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军基地', '担负一定海区的作战任务,并为辖区内驻泊的海军兵力和过往舰船提供全面保障的海军军一级组织。隶属于舰队。下辖水警区、舰艇支队、海军岸防兵部队以及勤务保障部队等。建有港口、码头、观察通信、航海保证、港岸训练、装备维修、军需供应、卫生医疗、文化娱乐和其他生活保障设施等。有时也指设施较完善的军港。', 7);
INSERT INTO `t_military_term_data` VALUES ('cd8a8cdc-fba7-4b78-9952-ab9db9b07803', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '核工业', '亦称原子能工业。从事核燃料研究、生产、加工,核能开发、利用,核武器研制、生产的工业。主要产品有核原料、核燃料、核动力装置、核武器、核电力和放射性同位素等。', 40);
INSERT INTO `t_military_term_data` VALUES ('cd8b3c8a-5de1-4061-b97c-f0df47381c81', '97a19170-bfac-42c5-9906-1acb187f0654', '空降地面作战阶段', '空降作战中部队从空降着陆起至完成地面作战任务止的阶段。主要包括：空降集合,抢占空降场,抗击反空降之敌,向预定目标开进,实施进攻或防御等。', 158);
INSERT INTO `t_military_term_data` VALUES ('cd90d475-6cc0-4117-a478-1c6950a440d1', '916997ee-6728-4c61-9b79-d96960b1dc86', '核辐射剂量探测仪器', '简称核辐射探测仪器。发现和测量核爆炸早期与剩余核辐射的专用仪器。主要包括Y射线指示仪、Y射线报警器、Y剂量率仪（照射量率仪）、放射性沾染测量仪、辐射仪和剂量仪等。', 153);
INSERT INTO `t_military_term_data` VALUES ('cd918c9b-d731-4a77-a205-9531f440f6ef', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上攻势布雷', '海军兵力在敌方海域布设水雷的战斗行动。', 106);
INSERT INTO `t_military_term_data` VALUES ('cdaae0a8-acab-43fe-8cbc-8887d26a08f1', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射击指挥仪', '简称指挥仪。用于为高射炮测定空中目标坐标、计算射击诸元和控制火炮射击的仪器。分为机械模拟式射击指挥仪、机电电子模拟式射击指挥仪和数字式射击指挥仪等。', 50);
INSERT INTO `t_military_term_data` VALUES ('cdbf9379-c2a5-43e5-90f7-b12fc644b3d1', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机机降乘载场', '机降部队或分队搭乘运输直升机和装载作战物资的场地。', 98);
INSERT INTO `t_military_term_data` VALUES ('cdbfaa41-2211-4f7e-8dae-2857f35747bd', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击目标发现概率', '表示核打击目标被发现的可能性大小的量。通常用0～1之间的数值表示。主要取决于目标的活动性能、伪装技术和保密措施的有效性，以及实施核打击一方的侦察技术、识别能力和谍报工作等。', 168);
INSERT INTO `t_military_term_data` VALUES ('cdd4c347-fac9-4374-99b2-2db2922479d9', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事历史学', '研究以往战争及其他军事活动的发生、发展过程及其规律的学科。是军事科学的组成部分。主要研究内容包括战争史、军队史、军事思想史、军事学术史、军事技术史等。', 33);
INSERT INTO `t_military_term_data` VALUES ('cdd6f040-c719-4af5-ad82-799827d1bc56', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵山地射击', '炮兵在地貌起伏较大、炮目高差在200米以上的地区实施的射击。山地地形复杂。射击死界较多，气象多变,射击精度易受影响,射击准备与射击实施比较复杂。', 194);
INSERT INTO `t_military_term_data` VALUES ('cde11443-5ec2-463a-8839-46f393c1b8bc', '97a19170-bfac-42c5-9906-1acb187f0654', '空中禁区', '为安全和保密等需要而划定的禁止或控制航空器飞行的空域。分为永久性空中禁区和临时性空中禁区。通常将政治经济中心、工业基地、军事要地和港口等重要的地区或海域的上空划为禁区。', 378);
INSERT INTO `t_military_term_data` VALUES ('cde2784e-45c0-46f9-b16b-4750c2fbfd9c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵区分', '对建制和加强的炮兵兵力及其任务进行的分配。主要根据炮兵的任务、数量、敌情和地形等情况决定。通常对主要作战方向上第一梯队的部队给予较多数量炮兵的加强。', 40);
INSERT INTO `t_military_term_data` VALUES ('cde2a94c-df6a-48a1-9f64-f692b026145d', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学障碍物', '以毒剂构成的障碍物。通常用布洒持久性毒剂或引爆化学地雷等方法构成。持续时间可达数小时至数周。用以迟滞敌行动,杀伤其有生力量。', 27);
INSERT INTO `t_military_term_data` VALUES ('cdf79c90-6ece-4950-9d6a-3e9283bc8e51', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行批次', '指挥机构或雷达情报部门对空中航空器按批编排的次序。用于飞行顺序编排时,依批次表述,如第一批,第二批；用于雷达空情报知时,依批号表述,如0305批,0306批。', 54);
INSERT INTO `t_military_term_data` VALUES ('cdf9e462-ac74-4a6f-8c19-3b0cdadb4b77', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '合练', '不同军兵种的部队、分队或不同岗位的人员合在一起进行的训练。', 170);
INSERT INTO `t_military_term_data` VALUES ('ce11a518-911e-45e5-8d51-0aa30f53f019', '97a19170-bfac-42c5-9906-1acb187f0654', '航空训练炸弹', '供轰炸训练用的航空炸弹。弹壳通常用钢筋水泥或薄钢板制成,内装中心药筒,装填灰砂或烟火剂。着地爆炸时,发出闪光或浓烟以标示弹着点。夜间使用的航空训练弹还装有曳光剂以标示弹道。', 334);
INSERT INTO `t_military_term_data` VALUES ('ce1f3d5b-9d58-47ea-b9b9-ebd6d76d8ffa', 'f0140091-c11a-48c9-8836-8aa94439dac0', '潜伏', '人员或分队在己方阵地前沿前、敌人的纵深或其他特定地点隐蔽起来的行动。通常用以执行警戒、侦察或某种特定任务。', 72);
INSERT INTO `t_military_term_data` VALUES ('ce20a67f-0cff-4451-bd26-148320506913', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '空中输送', '使用空中运输工具实施的输送。是部队实施快速机动的方式。', 76);
INSERT INTO `t_military_term_data` VALUES ('ce31dd4f-b03b-4535-b1fb-a10337cb04cc', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力队', '强击支队或强击群中遂行火力支援任务的战斗编组。强击支队的火力队通常编有坦克、反坦克火炮、压制火炮、防空兵器等。', 172);
INSERT INTO `t_military_term_data` VALUES ('ce35ac56-2819-41bf-b94c-60ac2572a40b', 'd7132c58-5df3-4b97-919f-58740148b9ca', '预备防空兵', '在建制上直接隶属于军区以上单位的防空兵。装备有较大射程和射高、适于野战的防空武器系统。', 2);
INSERT INTO `t_military_term_data` VALUES ('ce4344da-9849-4b32-926e-a9c3c165cd23', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '弹道风', '地面至最大弹道高或炸高范围内的各高度上的实际风矢量的加权平均值。通常根据弹道高范围内各高度上的实测风或平均风计算出弹道风,再从射表上查出该弹道风的射击修正量,对火炮射击进行修正。', 86);
INSERT INTO `t_military_term_data` VALUES ('ce4cece6-d6d7-47b4-bfb5-71e800cf4a7f', '06a75831-13a1-4660-870a-455bb445336a', '流星余迹通信', '利用流星穿过大气层时形成的短暂电离痕迹对无线电波的反射和散射作用而达成的无线电通信。主要用于远距离、小容量专向或网路的数据通信。通信实时性差,不适于通话。', 110);
INSERT INTO `t_military_term_data` VALUES ('ce4ea940-76a2-4efe-bd40-64253cde04c9', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '越境', '非法出入国境的行为。', 94);
INSERT INTO `t_military_term_data` VALUES ('ce4f4cef-c102-405b-aefb-c7f3a0cbdc0a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '扫雷具', '用机械器具扫除水雷或以模拟舰艇物理场诱爆水雷的扫雷武器。按工作原理,分为接触扫雷具和非接触扫雷具；按携带方式,分为拖曳式扫雷具和艇具合一式扫雷具。通常装备在扫雷舰艇或扫雷直升机上。', 223);
INSERT INTO `t_military_term_data` VALUES ('ce54a4ce-0f16-48cf-b236-34db39e7abba', '98df76fb-4b65-48ff-a56c-4db587327c79', '战术后勤', '保障兵团、部队、分队的建设和作战的后勤。主要包括师、旅、团后勤以及营、连后勤。', 10);
INSERT INTO `t_military_term_data` VALUES ('ce678f76-55aa-4906-b626-32219c22bf86', 'f0140091-c11a-48c9-8836-8aa94439dac0', '集结上船', '登陆兵进入待机地域后,按装载计划装载武器装备和其他物资,并在各自的上船点按顺序上船的行动。要求隐蔽、安全、有序、快速。', 142);
INSERT INTO `t_military_term_data` VALUES ('ce824244-0b5f-4e0e-afc6-0fb398afbdba', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教学勤务', '保障教学的各种勤务。如情况显示勤务、靶场勤务、演习场勤务等。', 184);
INSERT INTO `t_military_term_data` VALUES ('ce835c3d-55f6-4bc4-901e-e16be2c49c1d', 'f0140091-c11a-48c9-8836-8aa94439dac0', '第一阵地', '师防御地区内由第一梯队团的第一梯队步兵营或坦克营防御地域组成的阵地。通常是防御的主要阵地。', 219);
INSERT INTO `t_military_term_data` VALUES ('ce8389f9-6704-4c1d-9da2-a6fc25b19810', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '微光夜视仪', '能在微弱光照条件下将图像亮度增强几万倍的观察仪器。由光学系统、像增强器和高压电源等部分组成。在星光条件下，对人员、车辆的观察距离为数百米至两千米左右。', 80);
INSERT INTO `t_military_term_data` VALUES ('ce859f85-0cd8-421b-af16-dbe6031df380', '8a761efd-50a6-4ac8-9913-b7d745104f82', '战斗射击', '训练中在不同地形和气象条件下进行的带有战术背景的实弹射击。分为进攻战斗射击和防御战斗射击。', 102);
INSERT INTO `t_military_term_data` VALUES ('ce9b0b6c-532b-4cae-81b4-4a97228155fe', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '计算机病毒', '人为编写的依附在计算机源程序中的具有伤害性并能自我繁衍的计算机程序。它通过软盘、终端设备及其他方式侵入计算机系统或网络可使其工作紊乱,甚至瘫痪。具有传染性、潜伏性、隐蔽性、复制性和破坏性等特点。防止和利用计算机病毒,在军事上具有十分重要的意义。', 65);
INSERT INTO `t_military_term_data` VALUES ('ce9e1a62-7485-4963-aba0-01939bbbfabd', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '鱼雷靶', '亦称靶雷。模拟潜艇的水下靶。主要用于鱼雷试验和反潜训练,也可作为声自导鱼雷的诱饵或训练声纳兵的活动声源。', 322);
INSERT INTO `t_military_term_data` VALUES ('cea09abe-b3da-40d2-a249-7cb096f7a857', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '计算机技术', '研究计算机的系统结构、硬件、软件及其应用的技术。是实现作战指挥系统、武器装备系统和后勤支援系统的自动化、信息化与智能化的关键技术。', 35);
INSERT INTO `t_military_term_data` VALUES ('ceaabf5c-970d-4515-b264-46bd29cfa48c', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '封锁区域', '实施封锁的空间范围。', 227);
INSERT INTO `t_military_term_data` VALUES ('ceb206fe-27b4-4150-a190-6f4dc0ac332a', '916997ee-6728-4c61-9b79-d96960b1dc86', '失能剂量', '能使染毒人员90％以上丧失正常活动能力的毒剂量。用ID90-100或ICt90-100表示。', 135);
INSERT INTO `t_military_term_data` VALUES ('ceb43a1a-27e6-49b4-b0f4-7468fb309a90', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化侦察组', '执行化学、辐射侦察任务的小组。由防化侦察分队派出。主要负责：查明地面沾染的范围和程度,查明染毒的种类、范围和概略浓度,毒剂云团的滞留和扩散情况,实施化学观察、沾染检查及气象观测等。', 11);
INSERT INTO `t_military_term_data` VALUES ('cecd876c-ea72-495e-bf71-65bd2da74aeb', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军防化保障', '海军为减少或避免部队在核、化学、生物武器袭击中造成的损伤而进行的保障。由海军各级司令部组织实施。', 365);
INSERT INTO `t_military_term_data` VALUES ('ced66241-1ade-4a78-ad4f-58b872ab5482', 'f0140091-c11a-48c9-8836-8aa94439dac0', '师防区', '师负责防守的区域。通常包括：第一梯队团防区、纵深团防区和后方防区,炮兵阵地、防空兵阵地、诸预备队配置地域、反冲击展开地区、反坦克预备队展开地区、障碍设置队展开地区,伏击阵地、反空降阵地、侧方阵地,各种指挥所,掩护地带等。', 209);
INSERT INTO `t_military_term_data` VALUES ('cee44bdb-ea56-4541-9c53-c6c0aad22827', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '换班报告', '换班情况的报告、包括交班报告和接班报告。', 106);
INSERT INTO `t_military_term_data` VALUES ('ceeaf3ef-4d9e-40db-82f2-dcbd44e38547', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹', '依靠自身动力推进,能控制其飞行弹道（轨迹）,将弹头或战斗部导向并毁伤目标的武器。通常由弹头或战斗部、控制系统、推进系统和弹体等部分构成。按飞行轨迹,分为弹道式导弹和飞航式导弹；按作战任务,分为战略导弹和战役战术导弹；按射程,分为洲际导弹、远程导弹、中程导弹和近程导弹；按发射点和目标位置,分为地地导弹、地空导弹、空地导弹、舰舰导弹、舰空导弹、借地导弹和空空导弹；按攻击的目标,分为反坦克导弹、反舰导弹、反潜导弹、反卫星导弹。反辐射导弹和反导弹导弹等。还可按发动机推进剂的种类,分为固体导弹、液体导弹和固液导弹；按发动机装置的级数,分为单级导弹和多级导弹等。', 0);
INSERT INTO `t_military_term_data` VALUES ('cf025b7c-e4a1-4bc2-b046-417c596a44cf', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '轨道要素', '亦称轨道参数。描述与确定绕地球运行的航天器椭圆轨道的基本参数。包括轨道半长轴、轨道偏心率、轨道倾角、升交点赤经、近地点幅角、过近地点时刻等6个基本参数。主要用以计算航天器在任何时刻的位置与速度。', 229);
INSERT INTO `t_military_term_data` VALUES ('cf1be966-52df-47b0-9354-1d035722cb29', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵逐次转移', '防空兵分队以逐段依次实施的方法进行的转移。为便于组织实施,通常将转移的全程划分为几个地段。', 87);
INSERT INTO `t_military_term_data` VALUES ('cf1dacb0-d750-47d3-8579-aa04f021c02a', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通重点目标', '对运输有重人影响的交通设施。通常指重要的交通枢纽、桥梁、隧道、车站、港口、渡口、机场、闸坝和通信枢纽等。', 288);
INSERT INTO `t_military_term_data` VALUES ('cf20dbc6-bfdf-43ae-a78b-a36b60b93c01', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '有线电制导', '简称有线制导。利用弹外的控制装置,通过导线传送控制指令进行的制导。常用于反坦克导弹。', 53);
INSERT INTO `t_military_term_data` VALUES ('cf21bb0b-b50a-4dda-a658-ba59bbb9b4fb', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥保障', '军队为实施正确、稳定和不间断的指挥而采取的各项保证性措施与进行的相应活动的统称、主要包括情报、通信、电子防御测绘、气象、警戒防卫、指挥所管理等方面的保障。', 12);
INSERT INTO `t_military_term_data` VALUES ('cf34ca4e-5acd-462d-ac26-706a4d2a983b', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象管制', '对气象情报进行的军事管制。是战时实施情报封锁的组成部分。主要包括：对气象情报的传递进行加密,中断对有关国家或地区的气象通信,停止公开发布天气预报等。', 69);
INSERT INTO `t_military_term_data` VALUES ('cf48f1f2-986c-4357-af24-3ee553585cae', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '合场飞行训练', '不同建制单位或不同型号的直升机在同一机场使用同一跑道同时进行的飞行训练。', 55);
INSERT INTO `t_military_term_data` VALUES ('cf56f545-88d2-481c-8599-61898c4df751', '06a75831-13a1-4660-870a-455bb445336a', '无线电台通信', '利用长波、短波和超短波无线电台进行的通信。可传输电话和电报,单边带电台还可进行数据和传真通信。组织运用的基本方法有网路通信与专向通信。', 106);
INSERT INTO `t_military_term_data` VALUES ('cf5b01e0-54f9-4c97-b409-d9b866930c8b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '随伴炮兵', '在步兵分队战斗编成内跟随步兵行动,以火力直接支援其战斗的炮兵。通常由团营属炮兵和配属的轻便炮兵担任。', 11);
INSERT INTO `t_military_term_data` VALUES ('cf6bf82d-0ba5-4511-88c6-d69b06ff84c3', '916997ee-6728-4c61-9b79-d96960b1dc86', '洗消剂', '用以消毒和消除沾染的化学制剂。包括消毒剂、消除剂和溶剂。', 185);
INSERT INTO `t_military_term_data` VALUES ('cf6d6141-d3e5-4c90-af97-6397907c4fad', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇不沉性', '舰艇所具有的在船体破损、部分舱室进水后仍能稳定漂浮于水面的性能。是舰艇战术技术性能要素之一。潜艇还具有水下不沉性。', 336);
INSERT INTO `t_military_term_data` VALUES ('cf6d8021-4800-4ef8-845f-5ac17aab7e36', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇水幕系统', '舰艇上能产生细微水流笼罩全舰艇上甲板和上层建筑的喷水装置。主要用以减轻核武器爆炸时的光辐射和放射性沾染对人员、舰艇的杀伤与破坏作用、并洗消舰艇所受的污染。', 167);
INSERT INTO `t_military_term_data` VALUES ('cf77c0e1-9746-438e-b442-92d692c729b1', '8a761efd-50a6-4ac8-9913-b7d745104f82', '火身口水平面', '通过火身口中心点的水平面。', 19);
INSERT INTO `t_military_term_data` VALUES ('cf8777a5-2316-4d6e-9775-b79c7094c7b4', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '就便桥', '用就便器材和预制构件架设的军用桥梁。可就地取材,以弥补制式器材之不足。', 273);
INSERT INTO `t_military_term_data` VALUES ('cf88d85e-40f6-4eec-939a-b59ff098fc7e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克特修', '坦克未到大、中修期限,由于技术损坏或战伤而进行的修理。通常由团以上修理分队或大修厂承担。', 213);
INSERT INTO `t_military_term_data` VALUES ('cf92a226-bfca-4a24-9861-55025ebfd1ff', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '免役', '公民依照法律免服兵役。有严重生理缺陷或严重残疾不适合服兵役的人,免服兵役。', 30);
INSERT INTO `t_military_term_data` VALUES ('cf9d2136-0f1a-4e09-836c-0f0a254e1a9f', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '敌情研究', '对敌方情况进行的分析研究。包括对其基本情况和动向情况的研究。', 144);
INSERT INTO `t_military_term_data` VALUES ('cf9e96d1-68f2-45dc-899c-41b1155b97ce', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '通信对抗装备', '用于通信对抗侦察和无线电通信干扰的电子对抗装备。包括通信对抗侦察设备和通信干扰设备。', 112);
INSERT INTO `t_military_term_data` VALUES ('cfab64b1-bcdc-46bc-861c-1a43f71646f5', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '兵要地志', '记述和评价某一地区军事地理及其对国防建设和军事活动影响的一种地方志。包括按行政区或战区编写的区域兵要地志和按军队专业需要编写的专题兵要地志。', 2);
INSERT INTO `t_military_term_data` VALUES ('cfac873f-1634-4fe3-ac41-efc8cab51681', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '潜望镜', '采用反射镜、棱镜、透镜等折转光路,可以从隐蔽位置观察目标的光学仪器。上端镜筒水平轴线与下端目镜中心间的距离称为潜望高。步兵、炮兵、坦克潜望镜的潜望高为几十厘米至几米,潜艇潜望镜的潜望高达十几米。', 75);
INSERT INTO `t_military_term_data` VALUES ('cfc70209-3f11-4e78-aba5-fc9aa31a8609', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '平叛', '国家依法以武装力量平定叛乱的措施与行动。', 435);
INSERT INTO `t_military_term_data` VALUES ('cfc7cc3e-580d-467a-8915-ae90c2c175ad', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '单发着陆', '装备多台发动机的直升机或飞机,在仅用一台发动机工作的情况下进行的着陆。', 49);
INSERT INTO `t_military_term_data` VALUES ('cfe14278-d0e1-42a4-9f2e-746bab763b5b', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '运动战战役', '战役军团在不固定的战线上对敌实施的进攻战役。具有歼击目标、作战地区不固定,作战样式变换快,部队机动频繁,组织指挥复杂等特点。', 55);
INSERT INTO `t_military_term_data` VALUES ('cfeabca9-aedf-4d2c-83e3-1bbe355f615c', '98df76fb-4b65-48ff-a56c-4db587327c79', '特种液', '用于减震、防冻、传递能量等特殊用途的液体。主要有液压油、刹车油、减震器油、驻退液、防冻液、防结冰液等。', 168);
INSERT INTO `t_military_term_data` VALUES ('cff703cf-9350-45cf-8faa-0350edbab5e2', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '连续攻击', '对敌实施的不间断的攻击。以不给敌人喘息之机,迅速歼灭之。', 107);
INSERT INTO `t_military_term_data` VALUES ('cff99029-5178-45a0-8b14-6f67886073a5', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '布雷', '布设地雷、水雷和空飘雷的行动。按布雷时机,分为预先布雷和机动布雷；按布雷手段,分为人工布雷、单兵布雷器布雷、机械布雷、火箭布雷、火炮布雷、飞机布雷和舰船布雷等。', 178);
INSERT INTO `t_military_term_data` VALUES ('cffd5ffb-c4a5-497a-8521-ffa35a5dc647', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术突破', '在敌主要防御阵地中打开缺口的战斗行动。分为一点突破和多点突破。', 46);
INSERT INTO `t_military_term_data` VALUES ('d00517f5-7e59-4f14-98bc-ff12ebe5d039', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '展开', '军队按照一定的作战计划,完成作战部署或由行军、机动（开进）队形变为战斗队形的行动。分为战略展开、战役展开和战术展开。', 337);
INSERT INTO `t_military_term_data` VALUES ('d016517b-02cc-4e27-aae6-62671bc81717', '97a19170-bfac-42c5-9906-1acb187f0654', '空投场标志', '为标示空投场的位置而设置的信号标志。通常使用信标机。此外,昼间还可使用布板、旗帜、烟幕等；夜间还可使用灯光、火堆、信号弹等。按统一规定或经过协商确定的样式设置。', 172);
INSERT INTO `t_military_term_data` VALUES ('d01c400c-40df-4deb-b5ab-0b6cf6efafcd', '97a19170-bfac-42c5-9906-1acb187f0654', '领航保障', '航空兵部队为顺利遂行飞行任务而在领航方面进行的保障。主要内容包括：向首长提供定下决心所需的领航资料和建议,参与拟制航空兵部队与其他军兵种部队的协同作战计划,组织实施各种飞行的领航工作、航图供应、航空测量等。', 367);
INSERT INTO `t_military_term_data` VALUES ('d02b6911-01e9-4261-b7e5-ebe472190170', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮射弹观察', '高炮部队或分队为观察与判定射击结果而组织的观察。主要内容包括：目标是否被击落、击伤,弹迹或炸点是否正常,弹迹或炸点的偏差量。', 185);
INSERT INTO `t_military_term_data` VALUES ('d0338155-55a4-4961-a430-237ab9b51a49', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '集团军（军）', '由若干个师、旅编成的军队一级组织。一般隶属于军区或方面军。设有领导机关,编有由步兵、装甲兵、炮兵、防空兵、工程兵、通信兵、防化兵、电子对抗兵、陆军航空兵等兵种或专业兵组成的战斗部队和勤务保障部队。为基本战役军团。', 15);
INSERT INTO `t_military_term_data` VALUES ('d0377638-8473-4b5d-aaa7-3c7271d31d6d', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '太阴日', '月球相继两次经过上中天或下中天所经历的时间间隔。一个太阴日等于24小时50分。', 137);
INSERT INTO `t_military_term_data` VALUES ('d0389be0-cb99-4e0a-988e-0d150fcb4ff3', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '发射窗口', '亦称发射时机。满足预定飞行条件和任务要求,允许发射航天器的时间范围。分为年计窗口、月计窗口、日计窗口三种发射窗口。发射航天器通常要同时计算三种或两种发射窗口,但最终决定于日计窗口。', 253);
INSERT INTO `t_military_term_data` VALUES ('d03c93b7-73d1-4112-b0e6-51af10ad89a6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '通用两栖攻击舰', '亦称综合登陆运输舰。能运载直升机、登陆艇、两栖车辆,用于按建制单位实施的由舰到岸登陆的登陆作战舰艇。可输送登陆兵及其武器装备和物资。', 148);
INSERT INTO `t_military_term_data` VALUES ('d03caf2d-22fa-4331-a986-e926208eafa0', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化专业分队洗消', '由防化兵洗消分队对受染对象实施的洗消。通常用于对受染严重的单位和指挥机关等重点保障单位的洗消。', 60);
INSERT INTO `t_military_term_data` VALUES ('d03e989a-d6ae-4f37-b502-c62548786923', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克寿命周期', '某型坦克从论证开始,经研制、生产、使用、维修,到退役为止的时限。通常以年计算。', 185);
INSERT INTO `t_military_term_data` VALUES ('d043f604-9555-4b63-aefc-8a8a9178e432', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '干扰扇面', '雷达受到有源压制性干扰时，其平面位置显示器显示的受干扰的角度范围。其中因干扰强而不能发现和跟踪目标的角度范围,称有效干扰扇面。', 82);
INSERT INTO `t_military_term_data` VALUES ('d046a14c-f7da-4892-951a-545de2c6f199', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '夜行军', '夜暗条件下实施的行军、利于隐蔽和保持行动的突然性。', 47);
INSERT INTO `t_military_term_data` VALUES ('d049e273-c6b6-48ef-be15-b6f087316f3d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '液体炸药', '常温下呈液态的炸药。常用的是由液态氧化剂（如浓硝酸、二氧化氮等）和液体可燃物（如硝基苯等）制成的混合液体炸药。爆炸性能较好,但稳定性较差。主要用以装填炸弹和爆破等。', 213);
INSERT INTO `t_military_term_data` VALUES ('d05adc81-23f1-4857-a452-9fbf5ce8a3db', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航区测控站', '航天器发射中对运载火箭跟踪、测量运动参数、接收遥测信息和发送安全控制指令的工作站。沿运载火箭的飞行航区配置。主要由光学测量站、雷达测量站、遥测接收站、综合测量站等组成。有的航区测控站电能测量航天器的运行轨道。', 248);
INSERT INTO `t_military_term_data` VALUES ('d05f7445-c621-475a-88f0-e4062cb98ea6', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事危机', '国家或政治集团之间的关系处于可能发生战争或军事冲突的危险状态。', 64);
INSERT INTO `t_military_term_data` VALUES ('d068df99-457a-4632-b3c6-9b7ab9cf5108', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '首长司令部演习', '团以上指挥员及其司令机关进行的军事演习。通常使用通信工具在现地或室内实施。', 123);
INSERT INTO `t_military_term_data` VALUES ('d069c006-2805-486d-afca-c7c96090f1ab', '8a761efd-50a6-4ac8-9913-b7d745104f82', '卡链', '使用弹链供弹的武器在射击过程中，弹链被卡在受弹器内不能输弹的射击故障。', 129);
INSERT INTO `t_military_term_data` VALUES ('d069e0a3-8e27-4298-b3f0-45417e6b097e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克乘员', '坦克内编配的操作人员。一般包括车长、一炮手、驾驶员、二炮手。车长负责指挥全车战斗（指挥车的车长由各级指挥员兼任）,并操作指挥仪器和电台；一炮手亦称炮长,负责操作坦克炮和并列机枪；驾驶员负责驾驶坦克,并操作航向机枪；二炮手亦称装填手,负责装填弹药,并操作高射机枪等。', 2);
INSERT INTO `t_military_term_data` VALUES ('d06ab28d-fd14-4164-a1cf-45218a32d543', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '水面核爆炸', '爆心在水面或接近水面的空中,火球接触水面的核爆炸。能在一定范围的水域造成严重的放射性沾染和强大的水下冲击波,引起巨大的浪涌。主要用以破坏水面舰艇、海军基地、港口、码头等目标。', 153);
INSERT INTO `t_military_term_data` VALUES ('d06ec387-0986-4b6a-996b-a882ca15077f', '98df76fb-4b65-48ff-a56c-4db587327c79', '指挥车', '专门用于指挥人员乘坐和进行指挥作业的车辆。通常装有野战通信设备和指挥器材,一般由越野车辆改装而成。', 296);
INSERT INTO `t_military_term_data` VALUES ('d06f2979-159b-44e8-a2a1-37cfeea3d703', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '火箭发动机', '完全依靠自身携带的能源和工质,不使用外界介质（空气）进行工作的喷气发动机。包括化学、核、电、光子火箭发动机。既可在大气层又可在外层空间工作。是火箭、导弹和航天运载器的主要发动机类型。', 34);
INSERT INTO `t_military_term_data` VALUES ('d07ffb69-d64e-40b2-8852-cc09e74599a4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵直接瞄准射击', '用火炮直接向目标瞄准所实施的射击。包括对固定目标射击和对运动目标射击。组织准备简单,指挥方便,命中率高,但距敌较近,阵地暴露。', 166);
INSERT INTO `t_military_term_data` VALUES ('d08e4e7e-23c0-4f61-a6fe-2212f271ac56', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵指挥机', '炮兵指挥射击时用以集中控制有线电通信和无线电通信的设备。通常设在炮兵群、营指挥所内,用以实施通播、专向通话、分组通话和越级指挥。', 298);
INSERT INTO `t_military_term_data` VALUES ('d08f2b3a-2272-4f8e-8226-cea0862719ce', '8a761efd-50a6-4ac8-9913-b7d745104f82', '枪族', '枪弹、供弹具和主要活动部件通用的若干种不同的枪的统称。如1981年式班用枪族由1981年式7.62毫米步枪、1981年1式7.52毫米折叠托步枪和1981年式7.62毫米轻机枪组成。部队装备枪族,便于训练、使用和维修,也便于生产、供应和补充。', 155);
INSERT INTO `t_military_term_data` VALUES ('d0d7fbc3-eaa7-42e8-9f02-ebfa29fb5398', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队防突袭', '战略导弹部队为防范和抗击敌人突然袭击而采取的措施和行动。主要包括：加强战备教育和战备值班,完善防突袭计划,搞好阵地工程建设,健全侦察、情报、预警系统,隐真示假,适时机动等。', 25);
INSERT INTO `t_military_term_data` VALUES ('d0ddacea-6022-4004-bdb0-2c27c66c3508', '98df76fb-4b65-48ff-a56c-4db587327c79', '公路通行能力', '公路在单位时间内通行车辆的能力。通常以1条车道或道路集断面在每小时或每昼夜内所能通过的最大车辆数量表示。', 274);
INSERT INTO `t_military_term_data` VALUES ('d0f22685-65c4-4372-9eff-52a25c9ce4a9', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤部署', '对后勤力量的任务区分、编组和配置。通常根据作战任务、作战部署、上级指示、地形条件、交通道路和敌人对后方的威胁程度等情况确定。', 51);
INSERT INTO `t_military_term_data` VALUES ('d0f52f89-ea1c-4e34-b83c-af1a37c5778e', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹机动设伏战法', '地空导弹部队隐蔽机动至敌机可能活动的空域或进出航线的下方预设埋伏,出其不意地打击敌机的战斗方法。是地空导弹部队积极寻求战机,主动歼敌的重要战法。', 136);
INSERT INTO `t_military_term_data` VALUES ('d1231575-d7a2-49b1-b28d-9301fd65097f', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克战斗队形', '坦克连、排进行战斗时展开的队形。有一线式、前三角、后三角、左梯形和右梯形等队形。战斗中需依据敌情、地形、任务和战斗编成,灵活地运用和变换。', 22);
INSERT INTO `t_military_term_data` VALUES ('d12854a2-43a7-459d-a943-b8fc6b079372', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '探空火箭', '用以探测地球引力场范围内的大气层物理现象和在近地空间进行科学试验的火箭。', 67);
INSERT INTO `t_military_term_data` VALUES ('d12af022-2dbc-4d90-8781-d4d779b2c245', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克牵引', '利用坦克抢救车将行动装置尚能工作的损坏坦克拖走的行动。有刚性牵引和柔性牵引两种。', 218);
INSERT INTO `t_military_term_data` VALUES ('d12f0c02-3e4c-4061-ad96-f8dd043d673d', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '车载指挥所', '开设在机动车辆上的指挥所。', 50);
INSERT INTO `t_military_term_data` VALUES ('d13840dc-864f-4666-ba75-33a0fc2b7f05', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '决战', '敌对双方使用主力进行的决定最后胜负的作战。决战的基本原则是：实行有利的决战,避免不利的决战。', 202);
INSERT INTO `t_military_term_data` VALUES ('d13c902f-a8da-468c-9acf-83c213f49f91', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电通信反侦察', '为防止敌方截获并利用己方无线电通信信号获取有关情报而采取的战术技术措施。', 94);
INSERT INTO `t_military_term_data` VALUES ('d141cd6f-1a36-4cdb-8f3c-c173c72096c9', '8a761efd-50a6-4ac8-9913-b7d745104f82', '标准射击条件', '为检验射击武器技术性能和确定射击诸元而规定的射击条件。包括标准气象条件、标准弹道条件、标准地球和地形条件。', 64);
INSERT INTO `t_military_term_data` VALUES ('d148d2c8-f2a4-4640-bd93-51adca93712b', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役军团', '具有单独实施战役能力的军队集团。按军兵种,分为陆军战役军团、海军战役军团、空军战役军团和第二炮兵战役军团；按规模,分为大型战役军团、中型战役军团和小型战役军团。大型战役军团,包括战区、方面军群等；中型战役军团,包括方面军（集团军群）、海军舰队、战区空军等；小型战役军团,包括陆军集团军、海军战役编队（区舰队、分舰队）、空军军、空降军等。', 41);
INSERT INTO `t_military_term_data` VALUES ('d1517b32-bfad-4a91-98b3-16d15868e3eb', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役合围', '战役军团对敌实施四面包围的作战行动。', 111);
INSERT INTO `t_military_term_data` VALUES ('d156fe10-d870-4f3c-bb73-7cd5a6b7295c', '8a761efd-50a6-4ac8-9913-b7d745104f82', '反坦克武器', '主要用以攻击坦克和其他装甲目标的武器。如火箭筒、无尘力炮、反坦克炮、反坦克导弹、反坦克地雷反坦克炸弹等。', 184);
INSERT INTO `t_military_term_data` VALUES ('d158605c-d605-4053-8c7d-209bb4832f75', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克保障性', '坦克的设计特性和计划的保障物资能满足坦克平时战备及战时使用要求的程度。分为使用保障性和维修保障性。', 183);
INSERT INTO `t_military_term_data` VALUES ('d1685cac-a0dd-4f77-9d96-c7945dc99bfb', '98df76fb-4b65-48ff-a56c-4db587327c79', '直供', '后勤机构对本级部队建制内的单位或人员实施的经费、物资供应。是军队实施经费、物资供应的基本方式。', 92);
INSERT INTO `t_military_term_data` VALUES ('d17188f5-1278-401d-b112-708373a1f1aa', '8a761efd-50a6-4ac8-9913-b7d745104f82', '瞄准基线', '①机械瞄准具表尺板上的分划归零时,照门上沿中央到准星尖中央的联线。②光学瞄准镜分划归零时,镜内中心的光轴。瞄准基线应与火身轴线平行。', 8);
INSERT INTO `t_military_term_data` VALUES ('d1787817-c9cb-487d-b46d-9a6b1fea2af3', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '两栖车辆渡河', '部队借助水陆两栖车辆实施的渡河。可在隐蔽地域搭乘,突然前出渡河、两岸地形适宜时,可在宽正面实施。', 306);
INSERT INTO `t_military_term_data` VALUES ('d18da563-00f8-4a3e-9e44-26f881549512', '98df76fb-4b65-48ff-a56c-4db587327c79', '事业费', '军队各事业部门用以完成本事业任务的经费。如情报事业费、气象事业费、测绘事业费、民兵工作费、政治工作费、出版费、卫生事业费等。', 82);
INSERT INTO `t_military_term_data` VALUES ('d18eb643-fcc5-4e6b-99fc-ec5f2d21a4eb', '97a19170-bfac-42c5-9906-1acb187f0654', '机场跑道', '机场中供飞机或直升机起飞。着陆滑行,具有一定长度、宽度和承载能力的铺筑路段。按构筑材料,分为混凝土、沥青、金属、碎石、土质跑道等。', 423);
INSERT INTO `t_military_term_data` VALUES ('d1aac7d6-a047-4e44-b8ef-c98101a6223d', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克短停射击', '坦克在运动中完成射击准备、利用短暂停顿进行的射击。', 55);
INSERT INTO `t_military_term_data` VALUES ('d1ab7e74-5177-49ef-b61e-a78fc67d30d7', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核反应堆', '简称反应堆。能以可控方式产生自持核反应的装置。按照核反应方式,分为核聚变反应堆和核裂变反应堆。', 119);
INSERT INTO `t_military_term_data` VALUES ('d1afc058-c74e-44e7-8861-d37016bf44f6', '8a761efd-50a6-4ac8-9913-b7d745104f82', '穿甲燃烧枪弹', '弹丸内装有穿甲钢心和燃烧剂的枪弹。主要用以射击薄壁装甲目标和飞机、直升机等。', 201);
INSERT INTO `t_military_term_data` VALUES ('d1d7918b-8702-4d6c-acdf-a9ee6226e234', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '拖曳声纳', '将声纳基阵拖曳在运载体尾后水中进行目标探测的声纳。包括拖体声纳和拖曳线列阵声纳。主要装备于反潜水面舰艇、攻击潜艇和反潜直升机。', 238);
INSERT INTO `t_military_term_data` VALUES ('d1d8a481-d25f-44c9-bc44-bcece733c813', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场', '为保障部队渡河而开设的场地。分为桥梁渡场、漕渡场、徒沙场、冰上渡场、泅渡场、坦克潜渡场和预备渡场。由渡口、渡场指挥所、渡河器材集结场、待渡地区、渡河检查站、渡场救护打捞站、接近路等组成。', 311);
INSERT INTO `t_military_term_data` VALUES ('d1df4de3-c4de-46d2-9265-d0401689f436', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核试验零时', '在核试验中发出起爆指令的时刻。', 180);
INSERT INTO `t_military_term_data` VALUES ('d1e0705e-4a37-4274-bf16-1c45bfd533a2', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '战时政治工作', '中国人民解放军在作战中进行的思想工作和组织工作。主要内容包括：保证作战方针、命令、指示的贯彻落实,进行作战动员和战场宣传鼓动,开展杀敌立功运动和战评工作,适时调整和健全组织,维护战场纪律和群众纪律,开展瓦解敌军工作,做好参战民兵民工政治工作、战区群众工作和烈士善后工作等。', 33);
INSERT INTO `t_military_term_data` VALUES ('d1e49ab1-4328-4a59-8452-aea702a4a370', '83e065b4-6737-4645-9ea5-8276d1de13ed', '毁损坦克', '因战伤或事故丧失规定功能而无法修复的坦克。通常按报废坦克处理。', 203);
INSERT INTO `t_military_term_data` VALUES ('d1ecce66-53e1-418d-a355-31797ec0bbae', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上破雷', '使用破雷舰排除水雷的战斗行动。能排除多种引信的水雷,但排雷宽度小,不能排除定时水雷。', 112);
INSERT INTO `t_military_term_data` VALUES ('d1f6b289-1329-44d6-8cef-a451480ce49c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '海洋监视卫星', '用于探测、监视海面状况和舰船、潜艇活动,侦收舰载雷达信号和窃听舰船无线电通信的侦察卫星。能在全天候条件下鉴别舰船的编队、航向、航速,并能探测水下核潜艇的尾流辐射等。还可为舰船的安全航行提供海面状况和海洋特性的重要数据。', 209);
INSERT INTO `t_military_term_data` VALUES ('d1f9fee9-3020-4acc-8a73-97d32cba476a', '83e065b4-6737-4645-9ea5-8276d1de13ed', '指挥坦克', '坦克部队各级指挥员用以乘车指挥战斗的坦克。连以上指挥坦克通常装备两部电台。', 26);
INSERT INTO `t_military_term_data` VALUES ('d1fcd2b3-dad6-40fd-94f3-725c259a558b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '测量标志', '标定测量控制点在地面上位置的标石、观标以及其他标记物的统称。是使用测量成果的依据。', 150);
INSERT INTO `t_military_term_data` VALUES ('d1fdd9ec-84a8-4922-a641-e123bd03e5c6', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫生包', '配备给部队医护人员随身携带的制式卫生装备。包内装有急救包、止血带、注射器、体温计和消炎、止痛药品等。主要用于平时巡诊和战时急救。', 224);
INSERT INTO `t_military_term_data` VALUES ('d2092a43-f351-4368-b9ed-71718813e244', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹道', '射弹的质心从发射开始点到终点的运动轨迹。按发射方式,分为枪炮弹道和火箭弹道；按枪炮弹丸的运动过程,分为起始弹道、膛内弹道、中间弹道、膛外弹道、终点弹道。', 14);
INSERT INTO `t_military_term_data` VALUES ('d21a5e39-5c9c-4986-8d4c-c10ae0eb3e12', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵观察所侦察', '炮兵在观察所内使用观测器材进行的侦察。主要有光测侦察、雷达侦察、照相侦察。任务是观察战场,查明敌情、地形,测定目标坐标,必要时指挥和校正火炮射击。', 104);
INSERT INTO `t_military_term_data` VALUES ('d21c4dfe-5c86-4635-9ddc-d210566b8c1d', '97a19170-bfac-42c5-9906-1acb187f0654', '雷达情报报知通信', '雷达和通信部门组织的向上级和有关方面传递雷达情报的通信。包括雷达情报上报通信和通报通信。根据雷达的布局和报知关系组织实施。', 354);
INSERT INTO `t_military_term_data` VALUES ('d224b3da-8981-4e6d-befa-41ba68ab1b52', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '仓促防御', '没有经过充分的防御作战准备,临时转入或应急进行的防御。通常防御的组织准备时间短促,防御体系和设施不够完善。', 119);
INSERT INTO `t_military_term_data` VALUES ('d22c57da-e9bd-4102-bad2-18388b0666b3', '97a19170-bfac-42c5-9906-1acb187f0654', '空中积冰', '飞机或直升机在飞行中机体某些突出部位聚积冰层的现象。按积冰程度,分为弱、中、强3级。中级以上的空中积冰会使飞机或直升机的空气动力性能、安定性和操纵性变坏。严重时可能造成飞行事故。', 383);
INSERT INTO `t_military_term_data` VALUES ('d247328f-f05b-4ed3-8e6b-f3c1b6c32677', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '中队', '相当于营或连的军队一级组织。如中国人民解放军海军的舰艇中队（相当于营）、空军的飞行中队（相当于连）等。', 31);
INSERT INTO `t_military_term_data` VALUES ('d252d724-6f40-431e-a4d9-e43a4c68a1d8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战平台', '现代各种武器系统中,具有运载功能并可作为火器依托的载体部分。如坦克、步兵战车、舰艇、飞机等武器系统中除火器之外的部分。', 122);
INSERT INTO `t_military_term_data` VALUES ('d2542b34-237e-46e5-b894-a3d770bd12f2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '坚守', '军队对某一地方或阵地的坚决固守。', 409);
INSERT INTO `t_military_term_data` VALUES ('d257957e-2e17-4358-8ee3-620a06d86294', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队党总支', '军队机关业务部门中党的总支部委员会的简称。中国共产党在中国人民解放军各级机关的业务部门设立的基层组织。在同级党的机关委员会或党的机关直属委员会领导下,领导所属单位的党支部。', 42);
INSERT INTO `t_military_term_data` VALUES ('d25c043e-0f62-4264-801c-bb4b53188bde', '8a761efd-50a6-4ac8-9913-b7d745104f82', '催泪弹', '装填催泪溶胶或蒸汽,能够刺激人、畜的眼睛、上呼吸道及暴露的皮肤的弹药。主要用于防暴。', 193);
INSERT INTO `t_military_term_data` VALUES ('d26bae5e-0d04-48db-83ca-7fd86464f475', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '空袭', '使用航空器、导弹等兵器从空中对地面(下)、水面(下)目标进行的袭击。分为战略空袭、战役空袭和战术空袭。', 208);
INSERT INTO `t_military_term_data` VALUES ('d27d518d-ee03-4467-8d6a-b94de96b97a8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '液体发射药炮', '以液体发射药为能源的火炮。具有射弹初速大、发射速度快、不需装填和抽抛药筒等特点。', 28);
INSERT INTO `t_military_term_data` VALUES ('d27f7208-9154-45e9-809d-a94551de5f03', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵观察配系', '将炮兵观察所有计划地配置而形成的观察体系。通常按纵深梯次、正侧结合、高低相辅、疏散隐蔽的原则进行配置,以实施严密观察。', 106);
INSERT INTO `t_military_term_data` VALUES ('d28bf59a-af80-40ef-b511-b1dd2bd1c958', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '小潮', '当月球、太阳和地球的相对位置大致成直角,月球与太阳的引潮力接近正交时产生的潮差最小的潮汐。小潮一般出现在农历上弦（初七、八）和下弦（廿二、廿三）后约1～2天。', 142);
INSERT INTO `t_military_term_data` VALUES ('d291f79b-7815-4738-a4e2-9e02a09a5625', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '地区', '①陆上较大范围的地方。如东北地区、华南地区、北京地区等。②陆上两点之间的狭长区域。如XX、 XX地区,即指由XX至XX之间的地区。', 296);
INSERT INTO `t_military_term_data` VALUES ('d29fcce5-1332-4c49-a0ad-88649b2d523b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '道路网', '在团以上各级作战地幅内,以原有道路和军用道路构成的网状道路系统。', 257);
INSERT INTO `t_military_term_data` VALUES ('d2ac4314-a7a7-4076-ba14-aa614fe4dc88', 'f0140091-c11a-48c9-8836-8aa94439dac0', '对临时驻止之敌的进攻战斗', '对运动中短暂停留、临时驻扎之敌实施的进攻战斗。', 127);
INSERT INTO `t_military_term_data` VALUES ('d2b4634e-8e24-4357-b314-5a488320a22e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战任务区分', '简称任务区分、根据作战决心,对所属各部队和分队担负的作战任务进行的划分包括明确作战区域和作战目标以及完成任务的要求、时限等。', 84);
INSERT INTO `t_military_term_data` VALUES ('d2c3b40c-ba94-43c3-a71a-6c958b45c5b6', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '输送计划', '组织实施输送的计划。通常依据输送命令的内容及有关规定拟制。', 80);
INSERT INTO `t_military_term_data` VALUES ('d2d4d961-de0c-47ae-976c-bcda8960cbbc', '06a75831-13a1-4660-870a-455bb445336a', '无线电网路', '简称网路。三部以上无线电台之间使用相同的联络规定建立通信联络的方法。具有占用频率少,节省人员、器材,便于通播、转信和各台间的相互联络等特点,但通信时效较低,易暴露指挥关系。', 50);
INSERT INTO `t_military_term_data` VALUES ('d2d8b29d-d497-466b-b9a1-0ef1699b6cc3', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '图库', '储备、管理和供应各种地图、成果表等军事测绘资料的机构及库房。', 292);
INSERT INTO `t_military_term_data` VALUES ('d2e86590-5bbf-48d1-8afc-11ee6bd5f0c2', '06a75831-13a1-4660-870a-455bb445336a', '通信工程', '为保障军事通信而进行的重大通信设施的建设与工程构筑的统称。包括固定通信台、站和通信线路的勘察、设计、施工以及通信设备的安装、调试、开通等。', 212);
INSERT INTO `t_military_term_data` VALUES ('d300bb09-a235-4b11-a945-3b5b969c6515', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆使用管理', '为保证车辆正确合理使用而实施的管理。是车辆管理的组成部分。主要包括：归口派遣,按编配用途、技术性能、运用计划、车公里限额、动用车数、行驶区域规定使用车辆等。', 300);
INSERT INTO `t_military_term_data` VALUES ('d3069644-a578-4c9a-bc68-4517d1b48f02', '878651de-adf5-4c72-9376-9c363b893ff8', '战略主动权', '在战争全局上所具有的自主行动能力。掌握和保持战略主动权,是夺取战争胜利的关键。', 71);
INSERT INTO `t_military_term_data` VALUES ('d30bd369-32f3-4df4-bbb6-011b8412ad57', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '山地', '地面起伏显著,群山连绵交错,海拔一般在500米以上,比高大于200米的地区。山地地形复杂,人烟稀少,交通不便。军事上便于隐蔽固守,但机动、展开及指挥、协同、通信联络和运输补给等有一定困难。', 11);
INSERT INTO `t_military_term_data` VALUES ('d314bc32-6d9b-41ee-a1b0-afc7fd99e5ea', '97a19170-bfac-42c5-9906-1acb187f0654', '单机跟进', '遂行同一任务的若干架飞机或直升机,沿同一航线以一定的间隔和同一速度逐架跟随的飞行。', 217);
INSERT INTO `t_military_term_data` VALUES ('d31d4a86-0f8f-439b-8d79-cb9196eaaa7e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '相机', '察看适于军事行动的机会。', 252);
INSERT INTO `t_military_term_data` VALUES ('d3238a4d-8fc1-49e5-9406-d95762e8b40e', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '陆军航空兵战术', '陆军航空兵部队进行战斗的方法。主要包括陆军航空兵战斗基本原则、兵力部署、战斗指挥、战斗行动的方法、战斗协同以及各种保障措施等。', 2);
INSERT INTO `t_military_term_data` VALUES ('d32bec07-bd6c-4c16-90a2-f2ce1276a21f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥中心', '亦称指挥控制中心。军队各级指挥系统中的核心部分、有时也指一个指挥机构中起核心作用的部门,或多个指挥机构中起核心作用的机构。', 45);
INSERT INTO `t_military_term_data` VALUES ('d32f18b3-8988-4fd5-b7da-9580c6589c5f', '916997ee-6728-4c61-9b79-d96960b1dc86', '核观测哨', '为观测核爆炸情况而开设的哨所。分为野战核观测哨和要地核观测哨。通常由核观测分队开设。主要负责：观察核爆炸景象,测定核爆炸的时间、地点、威力和爆炸方式,为核估算提供依据。', 8);
INSERT INTO `t_military_term_data` VALUES ('d333cdf2-dae4-49f0-be2a-d58a3c8a1306', '878651de-adf5-4c72-9376-9c363b893ff8', '战略反攻', '战略防御中,对进攻之敌实施的战略性攻势行动。一般属于战略防御的最后阶段,是由战略防御转入战略进攻的过渡形式,带有战略进攻前夜的性质。', 123);
INSERT INTO `t_military_term_data` VALUES ('d33adf97-b469-460f-9c03-423811fc855d', '97a19170-bfac-42c5-9906-1acb187f0654', '航空照明炸弹', '以爆炸时产生的强烈亮光照明目标的航空炸弹。主要用于为航空兵部队夜间轰炸、侦察或为地面部队、海上舰艇夜间活动提供照明。', 325);
INSERT INTO `t_military_term_data` VALUES ('d356c994-0415-4855-8f21-50c0663dcda8', 'f0140091-c11a-48c9-8836-8aa94439dac0', '登陆输送方式', '输送登陆兵抵达敌方海岸的方式。分为由岸到岸、由舰到岸,或由岸到岸与由舰到岸相结合等登陆输送方式。', 143);
INSERT INTO `t_military_term_data` VALUES ('d358b62d-c827-471a-95c0-4e64277e2b1f', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '舰船工业', '亦称船舶工业。研制、建造和维修舰船、浮动工具及其配套设备的工业。主要产品有军用舰艇、民用船舶、舰载武器、舰船设备等。', 44);
INSERT INTO `t_military_term_data` VALUES ('d3642e69-417a-4358-93bf-9d09670b4b28', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '多点突击', '对被攻击之敌的多处同时实施的突击。通常是在兵力占较大优势时采用,但应有重点突击方向。', 102);
INSERT INTO `t_military_term_data` VALUES ('d381b621-01ca-47c5-9a64-c17b4b9b004e', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机外场降落', '飞机在驻地机场以外的机场降落。飞机进行全程作战或起飞后由于某种原因不能返回驻地机场降落时,均在外场降落。', 253);
INSERT INTO `t_military_term_data` VALUES ('d38b6fa4-c297-4086-a498-3d4954a00477', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮薄壁榴弹', '弹壁较薄、装药量大。侵入目标内爆炸的高射榴弹。主要用以射击飞机、直升机、装甲输送车和轻型舰艇。', 220);
INSERT INTO `t_military_term_data` VALUES ('d38cb399-e65f-437e-bd87-98332fa1ba80', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '反飞机导弹', '用以攻击、毁伤飞行中的飞机的导弹。主要用以打飞机,也可用以攻击飞航式导弹。包括地空导弹、舰空导弹、空空导弹。', 12);
INSERT INTO `t_military_term_data` VALUES ('d391055f-79e9-44c9-a4e9-17428efb9017', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '军事气象保障', '为军队送行作战、训练和其他任务而在气象方面采取的各项保证性措施和进行的相应活动的统称。是作战保障的组成部分。分为合成军队气象保障,海军水文气象保障,空军气象保障,战略导弹部队气象保障,军事航天气象保障,国防科研试验气象保障,炮兵气象保障和核、化学、生物武器防护气象保障等。基本任务是提供战区和有关地区的军事气象情报以及利用气象条件的建议和防范不利天气危害的措施等。', 94);
INSERT INTO `t_military_term_data` VALUES ('d3927828-ab18-4af7-9523-427f5e4e3857', '06a75831-13a1-4660-870a-455bb445336a', '救生电台', '亦称呼救电台。在舰艇、飞机遇险时用于报警、呼救的小型无线电台。频率固定,操作简便,能人工或自动发出遇险信号。通信距离为数公里至数十公里。', 177);
INSERT INTO `t_military_term_data` VALUES ('d396fcbe-8d1c-4be4-849e-23d8294590cc', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹训练场', '供导弹部队进行技术操作和合成训练的场地。通常包括导弹技术准备训练场和导弹发射准备训练场。', 78);
INSERT INTO `t_military_term_data` VALUES ('d39f515c-8451-419b-8ce8-63e126773000', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '洲际导弹', '射程为8000公里以上的导弹。', 5);
INSERT INTO `t_military_term_data` VALUES ('d3a43bc5-d940-4fc0-8452-4cbe8945ef2c', 'd7132c58-5df3-4b97-919f-58740148b9ca', '对空掩护目标', '由防空兵保障其对空安全的地面目标。主要包括：指挥所,兵力集团、炮兵群,导弹发射阵地,机场、桥梁、渡口、隘路、车站,物资集散地域和弹药库等。', 65);
INSERT INTO `t_military_term_data` VALUES ('d3a47827-2233-4f80-a729-80514fa9f69b', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '军运船舶梯队', '部队水路输送时按单船或船队编成的、梯次开进的基本运输单位。通常设梯队长、梯队政委、船舱长和值班员等。梯队编成力求保持建制完整,符合战术技术要求。', 84);
INSERT INTO `t_military_term_data` VALUES ('d3c3c2ca-872f-4cdf-b77f-ac8cc28618c2', '06a75831-13a1-4660-870a-455bb445336a', '军事通信', '为军事目的而运用通信工具或其他方法进行的信息传递活动。按通信手段,分为无线电通信、有线电通信、光通信、运动通信和简易信号通信；按通信保障范围,分为战略通信、战役通信、战术通信；按通信业务,分为电话通信、电报通信、数据通信、图像通信等。', 7);
INSERT INTO `t_military_term_data` VALUES ('d3c73aab-cddc-4ea3-ac13-c452a0e239ce', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军事交通图', '着重标出与军事行动有关的陆地、水上和空中的交通网的地图。', 264);
INSERT INTO `t_military_term_data` VALUES ('d3c74299-dc8f-4a22-b341-97d88f78f8e8', '98df76fb-4b65-48ff-a56c-4db587327c79', '周转量', '物资周转量的简称。军队为保证日常物资供应不间断而建立的机动库存量。是核定日常供应储备或周转储备量的计算依据。通常由业务主管部门根据不同物资的消耗规律和补充间隔时间等因素作出具体规定。', 119);
INSERT INTO `t_military_term_data` VALUES ('d3d424d5-bd4f-485e-afe0-33a43ed635ee', 'f0140091-c11a-48c9-8836-8aa94439dac0', '抢占', '抢在敌人之前占领有利地形或重要目标的行动。', 166);
INSERT INTO `t_military_term_data` VALUES ('d3df9f1b-3d05-452c-86b1-4ed32d4f5e16', '97a19170-bfac-42c5-9906-1acb187f0654', '最大飞行速度', '飞机或直升机在发动机处于最大功率或最大推力的工作状态时所能达到或允许达到的飞行速度。分为平飞最大速度和最大允许速度。平飞所能达到的最大飞行速度为平飞最大速度。为保证飞机结构强度不致破坏,安定性、操纵性不致丧失,而规定不得超过的最大飞行速度为最大允许速度。', 296);
INSERT INTO `t_military_term_data` VALUES ('d3e1764d-58d3-4363-8a0a-f10cb9205906', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '航天摄影', '利用航天器成像系统获取地球或其他星球表面的图像信息的技术。可用于军事侦察、地形测绘、气象研究、资源调查等。', 239);
INSERT INTO `t_military_term_data` VALUES ('d3ec7010-db0c-4ef2-b551-5131a4271bf0', '97a19170-bfac-42c5-9906-1acb187f0654', '航空反坦克炸弹', '以弹头内锥孔装药爆炸时产生的高速高温金属射流穿透装甲的航空炸弹。主要用以摧毁坦克、步兵战车、自行火炮等装甲目标。可装入航空子母弹箱或机上的多次使用弹箱内投放。', 324);
INSERT INTO `t_military_term_data` VALUES ('d3f2b746-1a10-4000-81f1-d88074f0a02d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '门桥渡河', '部队的技术兵器、车辆和人员等搭乘门桥实施的渡河。适用于先遣分队和第一梯队的重兵器采用。', 305);
INSERT INTO `t_military_term_data` VALUES ('d40d9d79-9bdf-4b48-8c3f-26c9f83bf8d7', 'f0140091-c11a-48c9-8836-8aa94439dac0', '登陆地段', '登陆地域内团一级登陆部队登陆和发展岸上进攻的地段。在登陆地段内,通常含有数个登陆点。', 138);
INSERT INTO `t_military_term_data` VALUES ('d41975fb-8877-48fe-9248-f561c4b77865', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航海雷达', '亦称导航雷达。用于舰艇定位、导航,以保证航行安全的舰艇雷达。与自动雷达标绘仪结合,能进行航行数据计算和显示、航行安全报警和避让、航道和锚位的监视等。', 230);
INSERT INTO `t_military_term_data` VALUES ('d41ea304-afb5-4de5-9402-312658835dec', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵固定掩护', '防空兵在被掩护目标附近配置成相对稳定的战斗队形实施的对空掩护。通常在掩护固定的或相对稳定的目标时采用。', 77);
INSERT INTO `t_military_term_data` VALUES ('d426c49c-dd66-4ca0-97c0-f97deda9ac5f', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '情报处理', '情报的收集、整理、报告、通报和储存、检索等工作的统称。', 148);
INSERT INTO `t_military_term_data` VALUES ('d42ed7c0-b1d9-4c14-894a-4a261010d6c8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮最低表尺', '使火炮所有的射弹都能通过遮蔽顶,与最低平均弹道相应的表尺。', 238);
INSERT INTO `t_military_term_data` VALUES ('d457a87c-e811-46de-8991-d233bf72bde7', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '集成电路', '利用微电子技术把有源元件（如晶体管）和无源元件（如电阻、电容）制作在半导体材料的基片上,并按功能需要使其互连成的整体电路。按单块芯片上所包含的元件或门电路的数量,分为小、中、大和超大规模集成电路。军事上广泛用于各种电子装备。', 87);
INSERT INTO `t_military_term_data` VALUES ('d45feaa8-d8af-46e6-8546-224c604b4cc9', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '宿营部署', '宿营时对兵力所作的部署。通常在行军命令中确定。', 96);
INSERT INTO `t_military_term_data` VALUES ('d468eb9b-bb35-453d-8430-3278331061da', '916997ee-6728-4c61-9b79-d96960b1dc86', '辐射侦察器材', '用以发现、测量沾染区辐射分布情况的核辐射剂量探测器材。包括射线指示仪、辐射仪等。', 154);
INSERT INTO `t_military_term_data` VALUES ('d469351a-ad14-43a0-b5fd-a21d5737582e', '06a75831-13a1-4660-870a-455bb445336a', '通信工程部队', '担负国防通信工程建设任务的通信部队。主要负责固定通信台、站和通信线路的勘察、施工,以及通信装备的安装与调试等。', 3);
INSERT INTO `t_military_term_data` VALUES ('d4908fe8-b1f5-454e-9965-01ad4da3ea96', '06a75831-13a1-4660-870a-455bb445336a', '磁石式电话机', '通话和呼叫信号电源自备的电话机。对传输线路要求低,通话距离较远,但需用手摇发电机发送呼叫信号。适用于野战条件下和无交流电地区的电话通信。', 200);
INSERT INTO `t_military_term_data` VALUES ('d49b1313-cf43-43fb-9031-bcfbee1d233a', '98df76fb-4b65-48ff-a56c-4db587327c79', '救护所', '部队在执行作战或其他任务中,由卫勤分队展开的医疗后送机构。通常按各级救治范围和任务分工,负责伤病员的救治、后送及其他卫勤保障工作。', 211);
INSERT INTO `t_military_term_data` VALUES ('d4c08ba5-12e5-4fca-827f-a564b34322b3', '8a761efd-50a6-4ac8-9913-b7d745104f82', '单兵武器', '单人携带和使用的武器。如手枪、步枪、冲锋枪、手榴弹等。', 151);
INSERT INTO `t_military_term_data` VALUES ('d4dffc7f-41d8-4747-9da0-75986cea41e9', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵', '中国人民解放军地地战略导弹部队的代称。是以地地战略导弹为基本装备,实现积极防御战略方针的重要核反击力量。由地地近程、中程、远程、洲际等导弹部队及各种保障部队、院校和科研试验单位等组成。可单独作战,或与其他军种协同作战。', 0);
INSERT INTO `t_military_term_data` VALUES ('d4e17416-1ed7-48da-9ac2-d76b19ef7fd9', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '自给力', '舰艇一次装足燃料、淡水、食品（潜艇还包括氧气再生药板等）,中途不补给能在海上连续活动的最长时间。是舰艇战术技术性能要素之一。通常以昼夜为计量单位。', 328);
INSERT INTO `t_military_term_data` VALUES ('d4ea1900-cc66-4041-80de-926c3f40a6ed', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗', '为削弱、破坏敌方电子设备（系统）的使用效能,保护己方电子设备（系统）正常发挥效能而采取的各种措施和行动的统称。基本内容包括电子对抗侦察、电子干扰和电子防御等。按电子设备的类型,分为雷达对抗、无线电通信对抗、光电对抗、水声对抗等。是现代战争中重要的作战手段和保障手段。', 0);
INSERT INTO `t_military_term_data` VALUES ('d4f49bde-dc13-4405-907e-e863fb91460d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '直航鱼雷', '无自导装置,只能按预先设定的航深和航向航行的鱼雷。', 205);
INSERT INTO `t_military_term_data` VALUES ('d5011b0d-391f-4a34-9d13-6209a8b691b7', '98df76fb-4b65-48ff-a56c-4db587327c79', '油料基数里程', '一个基数的油料按基本耗油标准计算,能供车辆行驶的里程。分为单车油料基数里程和部队平均油料基数里程。是计算需油量,实施油料供应的依据之一。', 171);
INSERT INTO `t_military_term_data` VALUES ('d50b99d0-ad73-4897-88ee-e1b2e8b12007', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵侦察网', '防空兵运用各种侦察组织和手段组成的对空侦察配系。包括雷达侦察网、对空观察哨侦察网和阵地、指挥所观察网。', 113);
INSERT INTO `t_military_term_data` VALUES ('d50c542e-3777-4a9a-b6e2-6652bd7387d6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇适航性', '舰艇所具有的在一定海况条件下能安全航行和正常使用武器装备的性能。是舰艇战术技术性能要素之一。通常以海况的等级表示。', 333);
INSERT INTO `t_military_term_data` VALUES ('d515a325-a4a9-434e-b762-8d6b19aecc7c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海里', '航海通用的计量海上距离的长度单位。为地球子午线上纬度1分的弧长。通常以1852米作为1海里。', 277);
INSERT INTO `t_military_term_data` VALUES ('d51e1919-d4df-4c2f-a49a-d2422f125649', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军信号台', '海军中担负港口通信联络和观察了望任务的专业勤务分队。隶属于海军基地或水警区。主要负责岸上指挥所与舰艇之间的视觉通信联络,观察港口附近水域的情况,发布舰船通告和大风警报等。', 15);
INSERT INTO `t_military_term_data` VALUES ('d524065a-d788-4047-9086-d555a3d7526f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '惯性测量系统', '利用惯性敏感元件测定运载体的位置和地球重力场参数的组合仪器。由陀螺仪、加速度计、惯性平台、电子计算机、控制显示器、数据存储记录器、电源等部件组成。可安放在汽车或直升机上进行测量。用以加密军用控制网、快速定位、炮兵联测等。', 182);
INSERT INTO `t_military_term_data` VALUES ('d52e23f5-d0ae-487a-ab74-b60af6220786', '06a75831-13a1-4660-870a-455bb445336a', '属台', '无线电网路和专向中的下级台。属台要服从主台；属台间要互相配合,密切协作。', 52);
INSERT INTO `t_military_term_data` VALUES ('d53082de-d4d6-439d-9e5e-0bf3cc3f280d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '进攻作战', '军队遂行主动进击敌人任务的作战。包括战略、战役和战术范围的进攻作战。', 187);
INSERT INTO `t_military_term_data` VALUES ('d53709c4-0798-4ce2-8d22-ef419f257547', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防步兵地雷', '用以杀伤徒步人员的地雷。分为爆破型防步兵地雷和破片型防步兵地雷。', 132);
INSERT INTO `t_military_term_data` VALUES ('d539af58-9318-4fe5-9919-f8117fdb550e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '门桥', '用两个以上桥脚舟和其他构件结构成的浮游结构物。分为漕渡门桥、桥节门桥、锚定门桥和打桩门桥等。可用舟桥器材、制式门桥器材和民舟等就便器材架设。', 304);
INSERT INTO `t_military_term_data` VALUES ('d53b358e-0678-4ae6-9499-31e68e11820c', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮高角', '为使火炮射弹射击到预定的水平距离,炮身轴线从炮口水平面需要仰起的角度。', 256);
INSERT INTO `t_military_term_data` VALUES ('d54c7ffb-0e2e-4d6d-a9e5-8a0a69f28929', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹阵地抗核加固', '对导弹阵地设施、设备采取的防止或减轻核爆炸产生的各种破坏效应的加固措施。是核防护的重要手段之一。', 194);
INSERT INTO `t_military_term_data` VALUES ('d556dc14-d29d-4c39-b3e8-fc99abf011e5', '97a19170-bfac-42c5-9906-1acb187f0654', '空军兵种战术', '空军单一兵种进行战斗的方法。分为空军航空兵战术、地空导弹兵战术、高射炮兵战术、空降兵战术等。', 37);
INSERT INTO `t_military_term_data` VALUES ('d557adcd-1bbf-4ec6-ae22-670166ae38f9', '97a19170-bfac-42c5-9906-1acb187f0654', '下令雷达开机线', '预先确定的下达雷达开机命令时空中目标应处的位置线。由目标的飞行速度、命令传递、雷达开机和搜索目标所需要的时间,以及雷达的最大探测距离等因素确定。', 397);
INSERT INTO `t_military_term_data` VALUES ('d5599152-4e09-4604-8985-375330d1ddc4', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击目标生存概率', '表示目标遭核武器袭击后仍保持其基本功能或最低作战需要的可能性大小的量。通常用0～1之间的数值表示。主要取决于目标的发现概率、防护能力,目标性能的可靠性,以及核武器的命中精度和威力等。', 169);
INSERT INTO `t_military_term_data` VALUES ('d5690e9f-8f7f-48e8-a22d-a190251749f1', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '北极星', '小熊星庄中的a星。中国星名是勾陈一、北辰。目前距北天极约l度,肉眼观察在正北方,其高度角约等于观测者所在地的地理纬度。中国位于北半球,绝大部分地区终年可利用北极星判定方位。', 190);
INSERT INTO `t_military_term_data` VALUES ('d56cc55a-5479-4be5-905d-b7bd7a4456cb', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反水雷武器', '用以探测、消灭水雷或使水雷失效的水中武器。包括扫雷武器和猎雷武器等。由反水雷舰艇、扫雷直升机等携载使用。', 222);
INSERT INTO `t_military_term_data` VALUES ('d56e67cc-49eb-4ee3-8054-01331b2d2300', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练体制', '军事训练工作的组织体系及相应制度。包括军事训练的机构设置及其职能划分、相互关系等方面的规定。', 6);
INSERT INTO `t_military_term_data` VALUES ('d56f67ce-8102-4b09-8dfa-c8d28ec08d76', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '助曲线', '亦称辅助等高线。在地形图上按 1／4等高距描绘的等高线。用短虚线表示,用以显示间曲线还不能显示的局部地貌。', 284);
INSERT INTO `t_military_term_data` VALUES ('d58bc746-f809-401a-953c-3aa59cd98cda', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹弹体技术准备', '对导弹弹体进行的各项技术准备工作的统称。包括单元测试、分系统测试和综合测试等。', 132);
INSERT INTO `t_military_term_data` VALUES ('d592526f-2d4b-48bc-94a9-5abb98b8ab5e', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '沼泽', '地表常年过度湿润或有薄层积水,土层潜育化或泥炭化,生长沼生和湿生植物的地段。按有无泥炭积累,分为泥炭沼泽和潜育沼泽；按发育阶段,分为低位沼泽、中位沼泽和高位沼泽。沼泽地不便构筑工事和宿营,通行困难,是军队机动的严重障碍。', 77);
INSERT INTO `t_military_term_data` VALUES ('d59ff0d6-f92b-45fb-b353-cfddf2afb22d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '戒严', '国家因战争或其他特殊情况,使用武装力量在全国或局部地区采取的一种非常的警戒措施。包括：加强警戒巡逻,管制人员、车辆、船只、飞机等的通行,限制公众集会,实行宵禁等。', 428);
INSERT INTO `t_military_term_data` VALUES ('d5a50e4e-67b8-4529-a744-e4772baedd7e', '98df76fb-4b65-48ff-a56c-4db587327c79', '野战手术队', '战时由医院临时抽组担负手术治疗支援任务的机动卫勤分队。分为综合手术队和专科手术队。战时主要用以加强救护所和野战医院的手术力量。', 213);
INSERT INTO `t_military_term_data` VALUES ('d5af8fbd-6889-4957-9626-c325e94010fd', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '兵器工业', '以研制和生产陆军常规武器装备为主的工业。主要产品有各种枪械、弹药、火炮、坦克、军事特种车辆、战术导弹、防化器材、观测器材等。', 39);
INSERT INTO `t_military_term_data` VALUES ('d5b2ca68-e2fc-45cc-ac38-75a7342f93ee', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击提前时间', '炮兵对运动目标射击时,从标定目标起至首群（发）射弹落达（击中）目标区（目标）的时间。是分队作业、传递口令、阵地操作和射弹飞行等听需时间的总和。', 206);
INSERT INTO `t_military_term_data` VALUES ('d5b40fc4-1514-46c0-a809-22be82c75bcb', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '精确制导技术', '高性能光电探测器为基础,采用目标识别、成像跟踪、相关跟踪等新方法,控制和导引武器准确地命中目标的技术。包括红外制导、激光制导、电视制导、微波制导和毫米波制导等技术。', 30);
INSERT INTO `t_military_term_data` VALUES ('d5d60d25-9ae4-4401-8ef3-baff13e0d76d', 'f0140091-c11a-48c9-8836-8aa94439dac0', '偷袭', '以秘密方式出其不意地对敌进行的袭击。通常利用不良天气、夜暗及复杂地形等条件实施。', 154);
INSERT INTO `t_military_term_data` VALUES ('d5d65d6f-389b-4f0b-b079-1dc7b69d9cbf', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天气警报', '以紧急通告的形式发布的天气预报。内容包括：将要发生的危险天气、灾害性天气等重要天气的性质、强度,出现和持续时间,影响地区等。通常向作战指挥部门和有关单位发布。', 74);
INSERT INTO `t_military_term_data` VALUES ('d5e1e160-f492-422c-be6e-4d24514ba2cc', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '猎雷舰', '用以探测、识别并摧毁水雷的水面战斗舰艇。多为玻璃钢船体。有良好的防磁、低噪声和抗冲击性能主要用以对付沉底水雷。', 142);
INSERT INTO `t_military_term_data` VALUES ('d5e7c908-b44c-4f11-8843-669cd0d2a7e9', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '水文站网', '按一定的规划原则布设的水文测站的总体。包括雨量站网、蒸发站网、流量站网、水位站网、泥沙站网、水质站网和地下水井网等。', 119);
INSERT INTO `t_military_term_data` VALUES ('d5ead01d-bc16-47ec-90c3-914688cdb640', '878651de-adf5-4c72-9376-9c363b893ff8', '战略理论', '关于战略问题的系统化理性认识和知识体系。', 57);
INSERT INTO `t_military_term_data` VALUES ('d5f41e7b-2a33-461e-8efd-2210a0797e19', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通线遮断', '战时对决定弃守地域内的交通线进行破坏或设置障碍物的作战行动通常采用撤除。爆破、机械破坏、焚烧、布雷、设障等方法。', 289);
INSERT INTO `t_military_term_data` VALUES ('d6006a3b-c079-402b-bc6e-98f7c42c8798', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹飞行试验测量', '对飞行试验的导弹进行跟踪测量以获取外弹道和遥测信息的工作过程。', 72);
INSERT INTO `t_military_term_data` VALUES ('d60b0c06-9d1b-40ae-b1f2-2b815e3c7f19', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮开火距离', '高炮对运动目标开始射击时火炮到目标的斜距离。通常分为最大开火距离和压缩开火距离。', 179);
INSERT INTO `t_military_term_data` VALUES ('d613d7ac-e773-4db4-ad1a-b7abfc263726', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察指示', '指挥员或指挥机关对所属部队和分队下达的关于组织实施侦察的指示。内容包括：当面敌军的态势、企图,侦察任务和侦察地域的区分,侦察机构的兵力编成和派出时间、地点,报告情况的时间、方法,上级、友邻的有关侦察活动和与之协同的方法等。', 97);
INSERT INTO `t_military_term_data` VALUES ('d61aece4-233d-41c4-aebc-b234c7c3a5fd', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '复员', '①中国人民解放军的志愿兵和干部退出现役,回参军地区或在服役所在地安置。国家不包分配工作。②战争结束后,国家由战时状态转入平时状态。', 154);
INSERT INTO `t_military_term_data` VALUES ('d61ec8e3-0306-4ac4-aac3-7399a8ebe5cf', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '抛撒布雷', '使用抛撒布雷工具实施的布雷。多用于机动布设地雷和陆军水雷。', 179);
INSERT INTO `t_military_term_data` VALUES ('d61fb6e6-d2c7-46ac-a360-033a192dfd98', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机侧飞', '亦称直升机横向飞。直升机机头方向不变,向横侧运动的飞行。', 24);
INSERT INTO `t_military_term_data` VALUES ('d626c8f9-67e3-40bc-9648-77a3349b2906', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '预备役部队', '国家平时保持的,以预备役人员为基础、现役军人为骨干,按规定的体制编制组成的部队。经动员可快速转为现役部队。', 45);
INSERT INTO `t_military_term_data` VALUES ('d630e3d5-5c59-4312-bee8-b7767ce4fdbb', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵火力计划', '炮兵为完成射击任务而制定的火力运用计划。由炮兵指挥员根据合同作战计划和本级的兵力、作战任务区分、敌情、地形条件等拟制。主要包括：射击的目标、时机、方法、弹药消耗量,担负射击任务的部队和分队,信号规定等。', 95);
INSERT INTO `t_military_term_data` VALUES ('d636533e-3451-471f-b0fc-3eb8742ddd53', 'f0140091-c11a-48c9-8836-8aa94439dac0', '破袭', '亦称破击。以破坏敌重要目标为目的的袭击。包括破坏和瘫痪敌方的交通运输、C3I系统、高技术兵器、工程和后方设施等。', 153);
INSERT INTO `t_military_term_data` VALUES ('d636d184-3a6a-43ec-a30d-dde8ca51e3b9', '31f4a446-5b98-4873-9d53-310d97125b07', '战略导弹反应时间', '战略导弹部队从受领发射命令至导弹飞离发射装置的时间。时间的长短取决于导弹部队的戒备程度与军事技术素质,导弹技术状态与发射可靠性,武器系统的自动化程度与发射方式等因素。', 19);
INSERT INTO `t_military_term_data` VALUES ('d63a5183-7b7a-4c7e-90f5-e17b24d82c67', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上葬礼', '舰员在舰艇上举行海葬或向海中撒骨灰及表示哀悼的仪式。通常以舰艇下半旗、播放哀乐、舰员列队等方式进行。', 408);
INSERT INTO `t_military_term_data` VALUES ('d6449a9b-e5f7-42fa-8c7c-3c7a99d6c93b', '97a19170-bfac-42c5-9906-1acb187f0654', '电子对抗飞机', '亦称电子战飞机。用于对敌方雷达、无线电通信设备和电子制导系统等实施电子侦察、干扰和攻击的各种专用作战飞机的统称。包括电子侦察飞机、电子干扰飞机和反雷达飞机等。', 292);
INSERT INTO `t_military_term_data` VALUES ('d64f6a1b-6c8a-486f-915c-8546f7c22c0f', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '地雷群', '简称雷群。用数枚至数十枚地雷设置而成的地雷障碍物。由一至数个雷组（每组3～5枚地雷）组成。通常用以掩护个别目标,封锁道路、桥梁,封闭通路等。', 185);
INSERT INTO `t_military_term_data` VALUES ('d66a8272-3e05-49aa-a436-5d7c084aef61', 'd7132c58-5df3-4b97-919f-58740148b9ca', '野战防空情报指挥系统', '防空兵遂行野战防空任务时,实施对空侦察和作战的指挥自动化系统。分为高炮情报指挥系统和弹炮情报指挥系统。用以收集、传输、处理、显示空中情况,进行战术、技术数据计算,辅助指挥决策。', 104);
INSERT INTO `t_military_term_data` VALUES ('d6759269-ba19-44d8-86ca-4ef54f7b12f7', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '人民武装', '来自人民、属于人民和保护人民利益的武装力量。包括人民军队和民兵等武装组织。有时也专指民兵等群众性武装组织。', 18);
INSERT INTO `t_military_term_data` VALUES ('d67ac303-6ca5-40f6-bda7-0c7f6ec70211', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '农副业生产管理', '军队对自身经营的农业和副业生产的管理。主要包括对生产的经营活动及收益的分配使用等方面的管理工作。', 26);
INSERT INTO `t_military_term_data` VALUES ('d67b14e0-451c-43f1-b964-b638ca957059', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '红外探测器', '接收红外辐射能并将其转换为电能或其他便于测量的物理量的器件。有热探测器和光电探测器两类。军事上主要采用光电探测器。用于夜视仪器和制导、侦察等设备。', 82);
INSERT INTO `t_military_term_data` VALUES ('d691e172-8945-4158-9b4e-960f467a29e6', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂前体', '装填于二元化学弹药弹体内,可生成毒剂的无毒或低毒化学物质。', 201);
INSERT INTO `t_military_term_data` VALUES ('d6b2d85d-eb31-4fc8-93eb-82daf9893a09', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行训练', '飞行人员为掌握飞行理论知识和业务技能而进行的训练。包括驾驶技术训练、战斗技术训练和战术飞行训练等。', 200);
INSERT INTO `t_military_term_data` VALUES ('d6b30c7b-0fb9-4a8a-8a84-359182d03d59', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '均势', '战争双方的力量或所处地位呈现均衡的态势。', 267);
INSERT INTO `t_military_term_data` VALUES ('d6bc5db4-ee91-49e0-9fe2-59243693f6a0', 'f0140091-c11a-48c9-8836-8aa94439dac0', '正射火力', '射击方向与目标正面垂直的火力。', 84);
INSERT INTO `t_military_term_data` VALUES ('d6c269db-4483-4509-8003-c16cef33c2b2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '联合作战', '两个以 上的军种或两个以上国家、政治集团的军队,按照总的企图和统一计划,在联合指挥机构的统一指挥下共同进行的作战。通常为战役以上规模。', 179);
INSERT INTO `t_military_term_data` VALUES ('d6c754c7-4ca1-4aae-a484-fe3d29427aed', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上待机', '舰艇驶抵指定海区,等待有利的作战时机。目的是缩短接敌时间,不失时机地投入战斗。待机方式有锚泊、漂泊、设伏、游戈和预先展开等。', 39);
INSERT INTO `t_military_term_data` VALUES ('d6c8be61-cbe6-4a1e-9ae7-062eb7d4731a', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防巡逻', '边防武装力量在国界线己方一侧进行的边界巡查活动。包括定期的和不定期的边防巡逻。', 114);
INSERT INTO `t_military_term_data` VALUES ('d6ca4e3d-78e7-4ff3-96cd-071930e1dbea', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '鱼雷', '由舰艇、岸台发射或飞机、直升机投射,能自航、自导或复合制导以毁伤水面和水下目标的水中武器。按动力,分为热动力鱼雷、电动力鱼雷和火箭助飞鱼雷；按攻击对象,分为反舰鱼雷、反潜鱼雷和多用途鱼雷；按制导方式,分为自控鱼雷、自导鱼雷和复合制导鱼雷等。', 199);
INSERT INTO `t_military_term_data` VALUES ('d6cf09fa-3a33-49a2-9cab-ad27945fcc21', '878651de-adf5-4c72-9376-9c363b893ff8', '战略相持', '敌对双方的总体力量对比处于相对平衡,战争全局呈现相持不下的状态。是交战双方力量消长、优劣形势转换的阶段。', 120);
INSERT INTO `t_military_term_data` VALUES ('d6dbc3be-1c96-453b-8864-c737a642bbb4', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '山背', '山顶到山脚的凸起部分。', 16);
INSERT INTO `t_military_term_data` VALUES ('d6e03a47-cad2-4b93-bae3-7d9453392b02', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲保障车辆', '装有专用设备和装置,用以遂行保障任务的装甲车辆。包括工程保障车辆、技术保障车辆和后勤保障车辆。如坦克架桥车、装甲抢救车、装甲救护车、装甲补给车等。多数有装甲防护,有的无装甲防护。', 85);
INSERT INTO `t_military_term_data` VALUES ('d6f17cdd-084d-4bf7-88bd-cc3fcb5e3b0b', '916997ee-6728-4c61-9b79-d96960b1dc86', '个人防护', '单个人员为避免或减轻敌核、化学、生物武器袭击的伤害而进行的防护。如使用个人防护器材,利用地形,采取防护动作,遵守在受染区行动的安全规定,及时洗消等。', 55);
INSERT INTO `t_military_term_data` VALUES ('d7033c94-65b4-446e-8db5-bef164ec2a5f', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵预备队', '由防空兵部队或分队编成的预备队。是集团军以上指挥员掌握的防空兵机动兵力。通常配置在战役纵深便于隐蔽和机动的位置。', 15);
INSERT INTO `t_military_term_data` VALUES ('d7132c58-5df3-4b97-919f-58740148b9ca', '0', '防空兵', NULL, 22);
INSERT INTO `t_military_term_data` VALUES ('d719cc81-2b7d-40e2-b551-b8314fbff66a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵对不能观察目标射击', '炮兵对观察不到或不能进行射击修正的目标实施的射击。', 170);
INSERT INTO `t_military_term_data` VALUES ('d71f141b-e5eb-4ec7-8877-d8dc1fbc9215', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '对策分析', '应用对策论对具有竞争性或对抗性的活动进行研究并寻求优化对策方案的方法。是军事运筹分析的重要方法。', 182);
INSERT INTO `t_military_term_data` VALUES ('d723b587-dfd7-461e-91b6-6a130ac6ce3d', '97a19170-bfac-42c5-9906-1acb187f0654', '航空标志炸弹', '爆炸时以有色强光、浓烟等视觉信号标示目标的航空炸弹。分为陆地航空标志弹和海上航空标志弹。陆地航空标志弹以有色强光或浓烟标示目标；海上航空标志弹以染色剂使水面变色标示目标。主要为飞机夜间轰炸时标示轰炸目标,或为飞机在无地标地区（如沙漠、海洋）飞行以及夜航时标示航线检查点。', 328);
INSERT INTO `t_military_term_data` VALUES ('d728c574-daa9-4d9d-9758-6fbd75ed1bbc', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '留营住宿制度', '军队中关于连队、舰（船）艇军官和飞行员在所在单位住宿的制度。主要内容包括军官留宿本单位的规定,配偶来队探亲期间回家住宿的规定,配偶居住在营区附近者按比例轮流回家住宿与归队时限的规定等。', 18);
INSERT INTO `t_military_term_data` VALUES ('d72bc0d5-35fa-49d1-9ffb-7e31952589e1', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '建军原则', '军队建设所依据的法则或标准。根据建军思想和建军方针确定。', 96);
INSERT INTO `t_military_term_data` VALUES ('d7309b63-9ee7-4121-8f4d-28d096bbd33d', '97a19170-bfac-42c5-9906-1acb187f0654', '空军地空导弹兵', '空军中以地空导弹武器系统为基本装备,遂行地面防空作战任务的兵种。主要用于要地防空和争夺制空权的斗争等。', 22);
INSERT INTO `t_military_term_data` VALUES ('d7324cea-30a0-4911-b617-9e4ad8c3d53c', '06a75831-13a1-4660-870a-455bb445336a', '野战线路通信', '利用野战线路作为传输媒介的有线电通信。分为野战电缆通信和野战被覆线通信。可传输电话、电报和低速数据。线路敷（架）设简便,但通信容量小、距离近。', 124);
INSERT INTO `t_military_term_data` VALUES ('d7461e6d-b0fa-4b08-8f0e-a184f8017e9c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '革命烈士', '在中国人民革命战争、保卫祖国或建设社会主义事业中牺牲或殉职的人员。凡定为革命烈士,需经一定机关批准,并给其家属颁发《革命烈士证明书》。', 73);
INSERT INTO `t_military_term_data` VALUES ('d74a1050-810e-4e68-a449-569a57d78358', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程保障决心', '亦称工程决心。合成军队指挥员对工程保障目的和行动所作的基本决定。内容视作战样式而定。', 14);
INSERT INTO `t_military_term_data` VALUES ('d7662d58-d340-4e9a-8149-d3f67ad5e4e7', '98df76fb-4b65-48ff-a56c-4db587327c79', '卫生防疫队', '负责组织、指导与实施部队卫生、防疫和卫牛检验工作的卫勤机构。设有卫生监督监测,疫病监控,卫生宣传,检验消毒等部门。中国人民解放军在总部、军区、军种后勤部门均编有卫生防疫队。', 208);
INSERT INTO `t_military_term_data` VALUES ('d7693d2c-1370-4cc3-9e86-269795ed8545', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '战略核武器', '弹道式导弹的简称。飞行轨迹绝大部分为自由抛物体轨迹的导弹。由火箭发动机推送到一定高度和取得一定速度及弹道倾角后,发动机关闭,弹头沿着预定弹道飞向目标。为提高命中精度,有的弹道导弹在弹头再入大气层后的最后飞行段,也能实施制导。', 100);
INSERT INTO `t_military_term_data` VALUES ('d76a8ce0-aa40-4be6-b3ba-81127fa71bd2', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '设伏火炮', '为执行炮火伏击任务而隐蔽配置的火炮。通常由较轻便和便于机动的火炮担任。主要用以突击运动之敌。', 49);
INSERT INTO `t_military_term_data` VALUES ('d7721094-dd33-4618-9e8f-c5720f86514b', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '连', '由若干个排编成的军队一级组织。通常隶属于营。为基本战术分队。', 20);
INSERT INTO `t_military_term_data` VALUES ('d78e2fa2-fb99-45a0-8e5a-2ff425901d2a', '97a19170-bfac-42c5-9906-1acb187f0654', '空中通信', '空中航空器之间的通信。分为无线电空中通信和视觉信号空中通信。主要用以保障空中指挥员实施指挥和航空器之间的协同。', 352);
INSERT INTO `t_military_term_data` VALUES ('d79be1ad-d6e7-49db-b422-617d92142db7', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队宣传工作', '中国人民解放军在官兵中开展的以理论传播、思想政治教育、经常性思想工作以及科学文化教育为主要内容的工作。是中国人民解放军政治工作的重要内容。', 92);
INSERT INTO `t_military_term_data` VALUES ('d7aad389-ec2e-4034-b756-94a83fed7743', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '演习文书', '组织实施军事演习的各种文电、图表和资料等军用文书的统称。通常包括演习想定、演习计划、导演计划,以及演习的命令、指示、通报、报告等。', 134);
INSERT INTO `t_military_term_data` VALUES ('d7aedfe4-abc1-49fb-8e06-093408373666', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '高程测量', '确定地面点高程的测量。主要方法有水准测量、三角高程测量和气压高程测量等。', 172);
INSERT INTO `t_military_term_data` VALUES ('d7b68414-5f0c-4a9b-9a5e-d40ee42c9727', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵侦察组侦察', '炮兵派遣少量人员编成临时侦察小组,携带轻便侦察器材遂行专门任务的侦察。包括道路侦察组侦察、敌后侦察组侦察和阵地侦察组侦察等。', 105);
INSERT INTO `t_military_term_data` VALUES ('d7c7b42e-1d6f-417d-86a8-8ebc1dc69ff9', '97a19170-bfac-42c5-9906-1acb187f0654', '航空气球', '无推进装置,主要靠空气浮力升空的航空器。分为热航空气球、氢航空气球和氦航空气球。由气囊、载吊装置和飞行操纵设备等组成。可用于侦察、通信、科研和航空体育等。', 260);
INSERT INTO `t_military_term_data` VALUES ('d7ccd0cf-0b39-4766-ad83-eddb802211e8', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克中修', ' 坦克中修间隔期使用终了时进行的修理。由师以上修理分队承担。', 210);
INSERT INTO `t_military_term_data` VALUES ('d7d7caa3-8463-4e05-b3fd-2de03dfee0bc', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '野外场地信号标志', '为便于直升机在空中发现和识别野外场地而在地面设置的视觉信号。通常有“T”字布、风向标、信号旗、旗门或灯门、发射的信号弹、点燃的发烟罐、灯光等。', 104);
INSERT INTO `t_military_term_data` VALUES ('d7e0d0e2-6a9d-4109-8f52-a2303489e64b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '守备炮兵', '担负军事要地防守任务的炮兵。分为海防守备炮兵、边防守备炮兵、要塞守备炮兵、城市守备炮兵等。主要装备大口径、远射程火炮。通常构筑有永备工事,阵地比较固定。', 7);
INSERT INTO `t_military_term_data` VALUES ('d7f75871-3ce0-4275-8930-985397e6c10e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克车体', '由装甲材料制造,构成坦克底盘的刚性壳体。是坦克防护系统的重要组成部分。主战坦克车体的重要部位普遍采用复合装甲。', 131);
INSERT INTO `t_military_term_data` VALUES ('d80544ad-cb04-4146-bc83-b5ec300167ee', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地图编绘', '亦称地图编制。根据地图制图资料制作地图编绘原图和出版区图的工作。包括建立数学基础、编绘地图内容、制作出版原图等工艺过程。', 287);
INSERT INTO `t_military_term_data` VALUES ('d80a0f52-298f-40f2-9051-ab99f4f10e41', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术迂回', '兵团或部队、分队从敌部署翼侧绕向其侧后的作战行动。', 32);
INSERT INTO `t_military_term_data` VALUES ('d817705e-efae-46fa-a979-5dcee7ff6e1c', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆事故', '军用车辆在运行中因意外原因造成的人员伤亡、车辆损坏或其他损失。分为责任事故和非责任事故。', 316);
INSERT INTO `t_military_term_data` VALUES ('d81c24a8-31bc-4c6b-8251-bf395c2af8b1', '98df76fb-4b65-48ff-a56c-4db587327c79', '军事医学', '以军事活动中防治伤病、保障军队成员身心健康为研究对象的学科。是医学的一个综合性分支学科。', 183);
INSERT INTO `t_military_term_data` VALUES ('d82ff262-a6a5-45fe-bbae-d8654a89cac5', '98df76fb-4b65-48ff-a56c-4db587327c79', '载重车', '亦称载货车、运输车、卡车。用以载运物资和人员的车辆。按装载量,分为轻型、中型和重型载重车。', 294);
INSERT INTO `t_military_term_data` VALUES ('d83a4bfe-b65b-4ee3-8879-7bcd4932f016', 'd7132c58-5df3-4b97-919f-58740148b9ca', '室内指挥', '高射炮兵指挥员在室内或掩蔽部内，依据远、近方情报图板等显示的空中情况实施的射击指挥。', 144);
INSERT INTO `t_military_term_data` VALUES ('d83de1a6-2f09-4326-8d69-f8a906068198', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海岸声纳', '亦称岸用声纳。基阵布设在近岸海底或深海山脉上,用于近海水域的对潜警戒和监视,引导反潜兵力实施对潜搜索和攻占的大型警戒声纳。', 240);
INSERT INTO `t_military_term_data` VALUES ('d84e8a6d-4a1d-495d-b2d3-6033406bf418', 'd7132c58-5df3-4b97-919f-58740148b9ca', '按雷达诸元射击', '由炮瞄雷达测定空中目标方位角、高低角和距离,计算仪计算射击诸元而进行的射击。不受气象条件影响,测距精度高,但测角精度稍差,且易受电子干扰。', 172);
INSERT INTO `t_military_term_data` VALUES ('d8557222-3275-487c-b161-509ad64144e6', '916997ee-6728-4c61-9b79-d96960b1dc86', '伤害剂量', '能使染毒人员90％以上丧失战斗力的毒剂量。用ID90-100或ICt90-100表示。', 133);
INSERT INTO `t_military_term_data` VALUES ('d85f7c8b-b9a9-4177-be8d-6d280e2c12eb', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹安全管道', '亦称安全飞行走廊。导弹在有动力飞行时允许其弹道偏离设计值的范围。分为位置的、速度的和落点的导弹安全管道。具体视安全控制中所选用的弹道参数而定。', 74);
INSERT INTO `t_military_term_data` VALUES ('d87349da-bec3-488c-9ab5-fb979b219417', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵', '以军用飞机和直升机为基本装备,主要遂行空中作战任务和空中保障任务的兵种。是空军的主要兵种。通常包括歼击航空兵、歼击轰炸航空兵、轰炸航空兵、强击航空兵、侦察航空兵、运输航空兵和其他专业航空兵部队。', 3);
INSERT INTO `t_military_term_data` VALUES ('d877de90-42ac-4fd1-aac4-90b779fbae3c', '8a761efd-50a6-4ac8-9913-b7d745104f82', '发射角', '亦称掷角。发射线与火身口水平面的夹角。', 25);
INSERT INTO `t_military_term_data` VALUES ('d8800836-bc4a-4c47-84a2-4da27cb16544', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '火力反击', '对发起进攻之敌实施的火力突击。', 261);
INSERT INTO `t_military_term_data` VALUES ('d8976120-2f20-4b2f-b7e0-22e36014c419', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹道升弧', '由弹道起打到弹道最高点的一段弧。', 33);
INSERT INTO `t_military_term_data` VALUES ('d89b489f-f11a-437b-9010-d71698fb30ab', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵利用侦察校射飞机射击', '炮兵利用侦察校射飞机侦察目标位置、判定炸点偏差量实施的射击。利用飞机校射,观察及时、准确,但易受气象影响和敌空中、地面火力的威胁。通常在对地面观察所观察不到的敌纵深内重要目标射击时采用。', 199);
INSERT INTO `t_military_term_data` VALUES ('d8aa0f6e-7e81-42a9-acc5-c8654ab64da1', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克容量', '作战地区所能容纳的展开成作战部署的坦克数量。', 15);
INSERT INTO `t_military_term_data` VALUES ('d8ab4e80-face-4e3b-8604-aedf7c11dd96', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '宇宙速度', '从地球表面发射后的航天器环绕地球、脱离地球引力或飞出太阳系所需的最小速度。能环绕地球在最低的圆形轨道上运行的速度称为第一宇宙速度,约为7.9千米／秒；脱离地球引力的最小速度称为第二宇宙速度,约为11．2千米／秒；飞出太阳系的最小速度称为第三宇宙速度,约为 16．7千米／秒。', 227);
INSERT INTO `t_military_term_data` VALUES ('d8bb9f86-331b-475a-b087-522c0680f538', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '陡石山', '岩石大部或全部裸露,坡度大于70度的山背、山脊及独立石山等的统称。', 133);
INSERT INTO `t_military_term_data` VALUES ('d8be1b53-5469-4e1b-b5e1-481235eca6d6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '雪崩', '积雪沿沟槽或山坡向下滑动引起雪体崩塌的现象。多分布于降雪丰富和稳定积雪期较长的高山区。通常突然爆发,崩塌量大,对人员和建筑物安全有严重危害。', 80);
INSERT INTO `t_military_term_data` VALUES ('d8d106a6-65e4-4f46-8853-3434115d2f6d', '31f4a446-5b98-4873-9d53-310d97125b07', '牵连损伤', '核爆炸对社会财富和居民的生命、财产等造成的非直接杀伤破坏。如由核爆炸引起的火灾。水灾、房屋倒塌等造成的杀伤破坏。', 153);
INSERT INTO `t_military_term_data` VALUES ('d8defc80-c24b-4e6c-a7ee-0fac02492a16', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军巡逻艇', '亦称边防巡逻艇、陆军编配的专门用以在国境界河执行巡查、警戒、救援等任务的艇。有的装备有固定武器。', 330);
INSERT INTO `t_military_term_data` VALUES ('d8e0ecac-8fed-4e3a-8126-8c4bc9c2ab62', '8a761efd-50a6-4ac8-9913-b7d745104f82', '电击枪', '亦称电晕枪。发射电能或高能粒子束的手持发射器。发射时产生的瞬时高电压可使生动目标立即昏厥或失去活动能力。射程较近，有的只有几米。有的电击枪还兼有照明电筒、警棍等功能。', 176);
INSERT INTO `t_military_term_data` VALUES ('d8e2fb76-34d8-4959-aacc-24cd5bbd4bd0', '98df76fb-4b65-48ff-a56c-4db587327c79', '营产', '专供军队使用并由军队自行管理的营区的土地、林木、营房及其附属设施、设备等的统称。', 236);
INSERT INTO `t_military_term_data` VALUES ('d8ea2639-482b-4818-b0dc-8eef3c030a74', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '海军侦察', '海军为获取所需情报而进行的侦察。通常由海军各级指挥员及其司令部组织。包括海军各级直属侦察部队和分队,以及潜艇部队、水面舰艇部队、海军航空兵、海军岸防兵、海军陆战队等的侦察。', 5);
INSERT INTO `t_military_term_data` VALUES ('d905b3e6-63b6-4d52-be62-6d0aa9a032ca', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '专用装备', '专供某一军种或兵种使用的装备。相对于通用装备而言。如军种专用的陆军装备、海军装备、空军装备；兵种专用的通信装备、工程装备等。', 82);
INSERT INTO `t_military_term_data` VALUES ('d9067e1a-f2f5-43b8-9c7e-bde593a2cc6a', '8a761efd-50a6-4ac8-9913-b7d745104f82', '弹道最高点', '弹道上到火身口水平面的垂直距离最大的一点。', 27);
INSERT INTO `t_military_term_data` VALUES ('d91142be-26ed-4b15-81c6-2014436e5daa', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵交替指挥', '两个炮兵指挥员或炮兵指挥所对炮兵部队或分队交替实施的指挥。通常在战斗队形转移时，为保证指挥的不间断而采用。', 86);
INSERT INTO `t_military_term_data` VALUES ('d9155b65-55b0-4776-a8a9-70e28ea299a0', 'f0140091-c11a-48c9-8836-8aa94439dac0', '半渡击', '趁渡江河湖海进攻之敌进到近岸水域时,或趁其部分已经上岸、部分尚在航渡时予以打击的作战行动。', 206);
INSERT INTO `t_military_term_data` VALUES ('d91b39b7-2d20-4201-8280-338e506ad7cf', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰载攻击机', '以航空母舰为基地,主要用以攻大水面和岸上目标兼有一定空战能力的舰载机。分为轻型舰载攻击机和重型舰载攻击机。通常装备有航炮、炸弹、空舰或空地导弹、空空导弹、鱼雷、火箭等,也可携带核武器。', 175);
INSERT INTO `t_military_term_data` VALUES ('d923207d-0e36-42f6-a0a3-b14523757135', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '陷阱', '有掩盖和伪装的坑式土工障碍物。通常构筑在敌必经之地,能使其车辆和人员陷入。分为防坦克馅阱和防步兵陷阱,防坦克陷阱一般口宽6.5米,长不小于8米,深2.5一3米。防步兵陷阱又称小陷阱,多成梅花形配置或数列交错配置,一般口径0.3～0.4米,深0.5米,底部一般设有竹签桩或防步兵地雷。', 119);
INSERT INTO `t_military_term_data` VALUES ('d92bf54f-ea76-4d4f-94c9-4c6d1812da71', '97a19170-bfac-42c5-9906-1acb187f0654', '空中救援', '使用直升机、运输机对跳伞或迫降的飞行人员以及陆上、海上其他遇险人员进行的营救和援助活动。', 129);
INSERT INTO `t_military_term_data` VALUES ('d935fdf3-a607-4e2d-9ab8-655c31e930a4', '06a75831-13a1-4660-870a-455bb445336a', '频率', '电磁波每秒钟振荡的次数。用符号f表示,基本计量单位为赫。在组织和实施无线电通信时,须严格按规定分配和使用频率。', 89);
INSERT INTO `t_military_term_data` VALUES ('d93819d2-af64-4ef7-993c-b3d82f15ef9d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '磁方位角', '从某点的磁子午线北向起,顺时针方向至目标方向线间的水平夹角。广泛用于航空、航海、部队行进和炮兵射击等方面。', 160);
INSERT INTO `t_military_term_data` VALUES ('d941d9b3-eaa4-49a3-9d7d-5aceee19067f', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海水跃层', '海洋中海水温度、盐度或密度在垂直方向上出现急剧变化的水层。包括温度跃层、盐度跃层和密度跃层。海水跃层对潜艇活动、水声探测、水下通信等影响很大,但巧妙地利用跃层,有利于潜艇实施隐蔽攻击。', 124);
INSERT INTO `t_military_term_data` VALUES ('d9427b7d-88a7-47a5-9617-4d1fe4a5c157', 'f0140091-c11a-48c9-8836-8aa94439dac0', '岛屿战斗', '在群岛或列岛、孤岛等地区进行的战斗。包括岛屿进攻战斗和岛屿防御战斗。', 9);
INSERT INTO `t_military_term_data` VALUES ('d945438d-ea1f-4028-b10e-1c8047a170a4', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '军用文书', '军队使用的具有现范体式的各种文电、图表的统称。按种类,分为作战义书和其他军用文书；按性质,分为命令、通令、指示通知、通报、报告、请示、计划、批复、函等。通常采用文字记述、地图或海图注记、表格、网络图等形式。', 110);
INSERT INTO `t_military_term_data` VALUES ('d9465562-f656-4703-93aa-d4a9ddac278d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上遇险求救信号', '简称遇险信号或海难信号。海上舰船、飞机遇险时用于求救的信号。分为国际遇险信号和军内遇险信号。国际遇险信号包括视觉信号。音响信号和无线电信号。舰艇、军用飞机遇险时一般使用军内遇险信号,在特殊情况下方可使用国际遇险信号。', 362);
INSERT INTO `t_military_term_data` VALUES ('d948c17a-8be1-4ce1-9eb1-44370cdd8b7a', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '猛炸药', '亦称破坏药。用以装填弹药和进行爆破作业的炸药。爆炸威力大,对冲击、摩擦和热的感度较迟钝,便于使用和保管。', 209);
INSERT INTO `t_military_term_data` VALUES ('d94afbec-4811-4759-9bb5-8aac35d75f49', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射弹密集度', '射弹着点在垂直散布面上或水平散布面上相对于散布中心的密集程度。常用射弹公算编差、射弹散布密集界、半数弹着圆半径等方法衡量。', 71);
INSERT INTO `t_military_term_data` VALUES ('d94faeda-2e57-4db9-b6c2-afc0b91a5064', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '粘土', '土壤颗粒组成中粘粒含量较高的土壤。干燥季节硬结,遇风时或车辆通行时尘土飞扬；雨天吸水快,易形成泥泞,影响部队运动。但粘土结构紧密,利于构筑工事。', 84);
INSERT INTO `t_military_term_data` VALUES ('d953399d-6351-4ec2-bf15-2be5ee764908', '97a19170-bfac-42c5-9906-1acb187f0654', '空降作战', '空降兵或其他部队通过空中机动降落到预定地区实施的作战。空降作战过程一般包括空降作战准备、空降、地面作战等阶段。', 149);
INSERT INTO `t_military_term_data` VALUES ('d9600113-e1d2-4219-813e-b291269f876e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '值班坦克', '担负观察、警戒、联络任务或用以应付突发情况的坦克。要求乘员定位,坚持观察和电台收听,能随时执行作战任务。', 27);
INSERT INTO `t_military_term_data` VALUES ('d974b73b-4ff6-4b6d-b989-bf36c4176ee6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军陆战队', '以两栖作战武器为基本装备,主要遂行登陆作战任务的海军兵种。可单独或配合其他军兵种实施登陆作战,参加海军基地、港口、岛屿的防御作战及特种机动作战等。', 5);
INSERT INTO `t_military_term_data` VALUES ('d979e1bc-8224-47e2-be5c-f17cafc782b2', '31f4a446-5b98-4873-9d53-310d97125b07', '密集核突击', '用大量核弹头在一定时间内对多个目标或目标群实施的突击。', 24);
INSERT INTO `t_military_term_data` VALUES ('d995533a-0f04-4972-8832-62ec659d5070', '98df76fb-4b65-48ff-a56c-4db587327c79', '仓库勤务', '管理军用仓库的专业勤务。主要内容包括：仓储物资的收发、储存、保养、维修,仓库的警戒。消防和库区管理等。', 133);
INSERT INTO `t_military_term_data` VALUES ('d9972808-7c97-4efb-997a-fd3c48d02eb8', 'd7132c58-5df3-4b97-919f-58740148b9ca', '预设埋伏', '高炮分队预先隐蔽地机动到敌机活动的地域展开,待机歼敌的战术手段。可以突然的火力,出其不意地歼灭敌机。', 73);
INSERT INTO `t_military_term_data` VALUES ('d998a4e3-9a86-4ec3-a725-3ccaeb5bd8a6', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '平时体制', '和平时期,国家为适应经济建设和社会发展需要而在政治、经济、军事、文化等领域确定的组织体系及相应制度。相对于战时体制而言。', 11);
INSERT INTO `t_military_term_data` VALUES ('d99d5672-407f-4ca0-8b99-93177b5e20cd', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '流量', '水流量的简称。单位时间内通过的某一江河渠道等水体横断面的水量。通常以立方米／秒表示。', 114);
INSERT INTO `t_military_term_data` VALUES ('d99e06f0-0e28-4982-8261-49feba49f8ff', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上救助', '亦称海难救助。对海上失事的舰船、飞机、直升机及人员、物资进行的救援。', 340);
INSERT INTO `t_military_term_data` VALUES ('d99f41ad-aa9f-4b0d-8bb6-9aa374be0d4f', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机加改装', '航空工程机务人员对直升机的装备和设备进行的技术改动。包括增加、减少或改换机上的设备部件等。目的是改善直升机的性能或消除设计与工艺上的缺点。', 92);
INSERT INTO `t_military_term_data` VALUES ('d9a0e8eb-4cca-4b6c-820b-f543d62072f9', '97a19170-bfac-42c5-9906-1acb187f0654', '起落航线', '在机场附近上空,以规定的飞行高度、速度和预定的飞行转弯点组成的航线。通常包括5个边和4个转弯。以起飞方向为准,起飞后向左转弯叫左航线,向右转弯叫右航线。起落航线主要用于帮助飞行员目测着陆或调整进场飞机的着陆次序。', 236);
INSERT INTO `t_military_term_data` VALUES ('d9a34316-032c-4af1-ac6b-08a19ffda790', '31f4a446-5b98-4873-9d53-310d97125b07', '枝打击面目标', '一枚核弹头直接命中只能使其局部毁坏的目标。其最小长度的一半大于核弹威力的半径。', 163);
INSERT INTO `t_military_term_data` VALUES ('d9a68fc1-a52f-4a90-8264-b443c6eec948', '878651de-adf5-4c72-9376-9c363b893ff8', '国内战争', '简称内战。国家内部的阶级、民族或政治集团之间进行的战争。', 17);
INSERT INTO `t_military_term_data` VALUES ('d9b095d2-c8ac-4c3f-953a-3a916aaacb35', '97a19170-bfac-42c5-9906-1acb187f0654', '夜间飞行', '从天黑到天亮前的时间内实施的飞行。光线较差,主要依靠夜航设备进行。', 220);
INSERT INTO `t_military_term_data` VALUES ('d9c2a8d6-d04a-4833-84a8-f6ac8406279a', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '经常性思想工作', '在军队各项工作和日常活动中,针对军人现实思想问题及时进行的教育和疏导工作。', 103);
INSERT INTO `t_military_term_data` VALUES ('d9c4132f-650c-4fb1-9189-07ecb4283374', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '反坦克导弹攻击区', '反坦克导弹实施攻击时能按给定概率毁伤目标的区域。', 265);
INSERT INTO `t_military_term_data` VALUES ('d9d5858e-fbfc-4f7c-9828-27bdd5fe26cd', '878651de-adf5-4c72-9376-9c363b893ff8', '战争准备', '为实施战争而进行的各种准备的统称。按内容,分为组织准备、物质准备和精神准备；按时间,分为平时准备、临战准备和战争过程中的准备。', 42);
INSERT INTO `t_military_term_data` VALUES ('d9dd004a-8e7a-4ba8-a222-79391c7c7c12', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇主尺度', '表示舰艇船体外形大小的基本直线量度。包括船长、船员、型深和吃水等。以流为计量准位。是舰艇战术技术性能要素之一。', 159);
INSERT INTO `t_military_term_data` VALUES ('d9dd0eb8-7b6b-42dd-a39f-85638c500aab', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '摩托化炮兵', '装备有火箭炮、自行火炮的炮兵和火炮与人员由机械车辆牵引、载运的炮兵的统称。', 5);
INSERT INTO `t_military_term_data` VALUES ('d9e039bd-8918-48c7-8e71-0822008f5921', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防动员', '亦称战争动员。国家为准备战争和实施战争而在相应的范围内由平时状态转入战时状态所采取的统一调动人力、物力、财力的紧急措施。分为全国总动员和局部动员。', 47);
INSERT INTO `t_military_term_data` VALUES ('d9eec866-d397-43cf-99d6-a779730849a6', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战略性战役', '对战争全局具有决定性意义或重大影响的战役。战略性战役的筹划、决策和指挥通常由战区或统帅部与战区共同进行。', 4);
INSERT INTO `t_military_term_data` VALUES ('d9f9d16c-bd1e-4225-8ff5-32fc73b784c9', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '编制序列', '亦称编制系统。编制规定的军队的组织结构和建制关系。内容包括军队组织系统中各建制单位的名称、数量、相互关系以及员额、装备等。通常以编制序列表表示。', 65);
INSERT INTO `t_military_term_data` VALUES ('da04ea94-0548-45c1-a719-03b5d7777411', '98df76fb-4b65-48ff-a56c-4db587327c79', '早期治疗', '战时师救护所或相当的救治机构在明确诊断的基础上对伤病员实施的早期救护治疗。主要包括：进行开放性气胸缝合,较大血管修补、吻合,开颅减压、剖腹探查等紧急手术和清创手术、彻底纠正休克等。', 196);
INSERT INTO `t_military_term_data` VALUES ('da1125e7-48b8-4430-b47e-2e9d4025d952', '8a761efd-50a6-4ac8-9913-b7d745104f82', '曳光枪弹', '弹头尾部装有曳光剂飞行时能发光显示弹迹的枪弹。主要用以指示目标和校正射击。有的曳光弹在出枪口后的一段距离内（如200米）不曳光或只曳出弱光然后再曳出强光,以免暴露射击位置。', 199);
INSERT INTO `t_military_term_data` VALUES ('da11d3af-b094-4da8-928b-400948168d18', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '火力侦察', '以火力袭击进行的侦察。用以逼迫、诱使敌人还击或运动,从而查明其兵力部署和火力配系。', 42);
INSERT INTO `t_military_term_data` VALUES ('da1665f2-b38a-4c73-baef-f7842d77fb72', '06a75831-13a1-4660-870a-455bb445336a', '长波通信', '波长为10～1千米（频率为30～300千赫）的无线电通信。主要用于岸上对水下潜艇的通信,也可用于对远海活动的水面舰船通信和地下通信。', 100);
INSERT INTO `t_military_term_data` VALUES ('da21146e-25b0-47f0-8b4b-e5ed59b9ad48', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '按级任教', '在部队训练中上级首长担任所属的下一级军官或部队、分队的教员。', 152);
INSERT INTO `t_military_term_data` VALUES ('da21ab61-d583-4407-af0c-6f20a1b41b3d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '宣战', '一国或政治集团以通知或通告的形式,对他国或政治集团正式宣布双方关系处于战争状态。1907年的海牙公约规定,国家之间除非有预先和正式的警告或通知,不得开战。但现代战争为达成突然性,发动战争的一方大都不宣而战。', 66);
INSERT INTO `t_military_term_data` VALUES ('da2e6ae6-5dd7-4411-b1f2-64515d1bb837', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器可靠性', '轻武器在寿命期内保持原设计性能的程度。包括对故障率、存储性、耐用性等方面的要求。', 223);
INSERT INTO `t_military_term_data` VALUES ('da334640-8fdf-49aa-a209-c4f9adce48e5', '916997ee-6728-4c61-9b79-d96960b1dc86', '放射性活度', '简称活度。一种表示放射性强弱的物理量。单位是贝可,1贝可=1衰变数／秒。', 90);
INSERT INTO `t_military_term_data` VALUES ('da49a52c-2b4b-4944-9cf5-d6963cf99678', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察报告', '向上级反映组织实施侦察情况的报告。分为简报、专题报告和综合报告。主要内容包括：派出的侦察力量及其任务,使用的侦察手段,任务完成的情况和经验教训等。', 109);
INSERT INTO `t_military_term_data` VALUES ('da5a039f-61be-4ce0-93fc-d841c51be4d9', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上引导攻击', '海军攻击兵力在指挥所或引导兵力的引导下对敌实施的攻击、通常由指挥所或引导兵力连续向攻击兵力通报目标的位置和运动要素、必要时可使用飞机或直升机直接引导攻击兵力实施攻击。', 82);
INSERT INTO `t_military_term_data` VALUES ('da68814b-c066-4677-b989-f6046ceb0e33', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战保障计划', '组织实施军队作战的各项保障的计划通常包括侦察、通信、警戒电子防御、防化、工程、伪装、测绘、气象水文以及交通、航海、声纳、防险救生、领航等保障计划。', 92);
INSERT INTO `t_military_term_data` VALUES ('da6ba996-2b20-4fec-b4e6-f8e4f3896b1f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事方针', '国家、政党在一定时期内,依据一定的军事思想和军事路线所规定的军事工作须达到的总目标和应遵循的指针。包括国防建设与军队建设方针、作战方针等。', 14);
INSERT INTO `t_military_term_data` VALUES ('da71bac3-cc32-440b-a797-01bb4ba3cdb8', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹遥测设备', '检测飞行中导弹的参数并以无线电波传送到接收站进行处理的设备。包括敏感发射设备和接收处理设备。主要用以实时监视导弹的飞行状态及各系统的工作状况,并为快速预报弹着点,评估导弹和分析故障提供依据。', 70);
INSERT INTO `t_military_term_data` VALUES ('da7fad85-d2ca-417e-96ba-0778ad05b372', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆载员', '装甲车辆单车的额定搭载人员。步兵战车载员一般为8～9人,装甲输送车载员一般为8～13人。有的主战坦克亦编有载员。', 4);
INSERT INTO `t_military_term_data` VALUES ('da7fae12-256e-4a9b-b18f-996ef4f96749', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教学计划', '军队院校培养人才,实施教学的总体设计的法规性文件。是院校制定教学大纲的主要依据。', 23);
INSERT INTO `t_military_term_data` VALUES ('da911e71-5fc6-440f-b8a5-edae9a436fd4', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '植被', '覆盖地球表面的某一区域的所有植物或植物群落的统称。是自然地理环境的组成要素。', 87);
INSERT INTO `t_military_term_data` VALUES ('da918cf0-2425-4cf7-8e70-8d1ff0b1cb34', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通线斗争', '交战双方为达成作战目的,对交通线进行的破坏与反破坏、封锁与反封锁、占领下反占领的军事行动。', 285);
INSERT INTO `t_military_term_data` VALUES ('da967da4-9c85-477a-b12d-110a9de04f9a', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '双休日', '国家规定的公务员和城镇职工每周星期六、星期日连续两天的公休日。军队参照执行。', 39);
INSERT INTO `t_military_term_data` VALUES ('da998ba5-ac09-4969-aaab-bb69e6b46208', '916997ee-6728-4c61-9b79-d96960b1dc86', '洗消装备', '消毒和消除沾染的三防装备。包括喷洒车、燃气射流洗消车、淋浴车和轻便洗消器、高压洗消器等。用于对染有毒剂、放射性落下灰、生物战剂的人员、装备、地面、工事等进行消毒和消除沾染。', 184);
INSERT INTO `t_military_term_data` VALUES ('da9bcb4c-e8a3-4002-96bb-d477a835e383', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '对壕作业', '进攻战斗中面对敌坚固工事,从壕的一端隐蔽挖掘交通壕以接近敌人的作业。用以隐蔽接敌,突然发起冲击。', 89);
INSERT INTO `t_military_term_data` VALUES ('daa01a6b-9d08-4bee-8c99-b20ff942e014', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '请示', '请求上级对提出的问题给予指示的军用文书、请示也可口头提出。', 140);
INSERT INTO `t_military_term_data` VALUES ('daa691ac-0b34-4752-b4be-94501792db48', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '奖励', '军队对执行作战、训练和其他任务中的先进单位和个人的表彰与鼓励。中国人民解放军纪律条令规定的奖励项目有嘉奖、三等功、二等功、一等功、荣誉称号。', 57);
INSERT INTO `t_military_term_data` VALUES ('daa9decf-b21f-41cf-b2bc-377cbe53b867', '06a75831-13a1-4660-870a-455bb445336a', '长途电话自动交换网', '由大容量的长途通信线路，连接分设在各地的长途自动电话交换设备构成的电话通信网。用以完成网内用户长途电话的自动接转工作。', 67);
INSERT INTO `t_military_term_data` VALUES ('daadf27b-40e8-4808-9f72-0f16dd59f820', '8a761efd-50a6-4ac8-9913-b7d745104f82', '脱壳穿燃曳枪弹', '采用脱壳结构并具有穿甲、燃烧和曳光作用的枪弹。主要供大口径机枪使用。', 204);
INSERT INTO `t_military_term_data` VALUES ('dab66633-e35d-44ca-a773-066a462dd720', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '转移战场', '战争中,军队由某一战场转到另一战场的行动。有时也指作战重心由某一战场转到另一战场。', 174);
INSERT INTO `t_military_term_data` VALUES ('dab78464-1b2b-44eb-b8b7-e602cc9f435d', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '基准炮', '作为炮兵连内各炮射出操作基准的火炮。通常是中央炮,也可以是两翼炮。', 208);
INSERT INTO `t_military_term_data` VALUES ('dabdfbf6-3f1d-4186-8989-d9fc7c0f9c54', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '正面突击', '向敌人作战部署或行军队形的正面实施的突击。通常在不便于实施翼侧突击时采用。有时为了配合主攻部队的翼侧突击也采用。', 97);
INSERT INTO `t_military_term_data` VALUES ('dac2dc08-b052-44bf-94af-367bff4dee33', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役决战', '敌对双方使用主力进行决定战役胜负的作战。', 53);
INSERT INTO `t_military_term_data` VALUES ('dac85a4d-87e6-4975-9cd9-b2532213d345', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '回收区', '航天器回收舱在地球表面降落的预定区域。', 283);
INSERT INTO `t_military_term_data` VALUES ('dad0b652-a2eb-4e31-828e-33c9535f0e98', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '换装', '用新式的或新型号的装备更换部队原有的装备。', 89);
INSERT INTO `t_military_term_data` VALUES ('dadda558-1d5d-4906-a01e-853f9a37e597', '8a761efd-50a6-4ac8-9913-b7d745104f82', '迎风篇', '靠尾翼稳定的火箭弹在主动段内,由于横风影响而使全弹质心逐渐脱离射面向逆风方向的偏移。火箭弹的飞行速度越低,编移量越大。', 59);
INSERT INTO `t_military_term_data` VALUES ('daedf320-6f28-4719-b0b6-6670aa55ea9c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '跳雷', '雷体能跳离地面一定高度爆炸的防步兵地雷。包括破片型防步兵跳雷和化学跳雷等。一般跳炸高度为0.3～5米,杀伤半径为10～60米。', 148);
INSERT INTO `t_military_term_data` VALUES ('daefbff2-5d34-422a-8b73-3105f00272b0', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克事故', '在坦克使用或维修过程中,由于人为因素造成的坦克（或其机件）损坏、人员伤亡、财产损失等事故。分为一等事故、二等事故和三等事故。', 201);
INSERT INTO `t_military_term_data` VALUES ('daf58a02-d279-44b2-b4e8-76f215f774d1', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤保障能力', '军事后勤保障军队建设和作战的能力。是军队战斗力的重要组成部分。构成和影响后勤保障能力的主要因素包括：后勤人员素质,后勤装备、设施、物资等的数质量状况,以及能够引人后勤保障活动的经济资源和自然资源等。', 24);
INSERT INTO `t_military_term_data` VALUES ('db064ab3-8f6a-4d96-89e5-c36b6c65fbc9', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '干部当兵代职', '中国人民解放军实行的通过部队实践以锻炼和培养干部的制度。规定军队的领导干部、机关干部要到所属部队或基层单位当兵或代理行政职务,以体验士兵生活、熟悉了解基层情况,并使自身得到锻炼和提高。', 83);
INSERT INTO `t_military_term_data` VALUES ('db14abeb-24c0-4389-9c45-ddb276f2607e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '对抗演习', '演习双方互为假设敌,相互进行攻防的军事演习。可采取实兵、兵棋、图上作业、计算机模拟等方式进行。', 116);
INSERT INTO `t_military_term_data` VALUES ('db16e89a-ad70-4eff-8731-d6fae408d222', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克使用寿命', '在规定条件下单辆坦克或其机件能够正常使用的最大期限。通常指从投入使用开始,到出现不可修复的故障或不能接受的故障率为止。一般用小时或公里数表示。', 184);
INSERT INTO `t_military_term_data` VALUES ('db22b3c8-f9ba-4b78-855c-9638cc45a881', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '营哨', '担负宿营警戒任务并进入预定位置的建制营。通常由宿营的集团军（军）、师派出。', 20);
INSERT INTO `t_military_term_data` VALUES ('db2bf7eb-4753-4d67-bb53-6935fe99ae1f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '人一机系统', '由具有特定功能的计算机、相应的操作人员以及被控制的武器装备等构成的有机整体。', 177);
INSERT INTO `t_military_term_data` VALUES ('db3ee479-83a3-4da2-982d-cbee1d1a62cd', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '声纳侦察', '亦称水声侦察。使用被动式声纳进行的声学侦察。主要任务是：截收敌方各种主动式水声设备及原发性声场的声信号,并测定其技术参数及方位、距离,以掌握敌舰动态,或为进行水声干扰和舰艇使用武器提供可靠依据。', 53);
INSERT INTO `t_military_term_data` VALUES ('db423e93-e5fe-4e61-9e9a-90fa7ea8f789', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场指挥所', '亦称渡场指挥观察所。为保障部队顺利渡过江河而建立的临时性指挥机构。通常设在渡口附近便于指挥、观察的地点,并构筑有观察工事和掩蔽工事。由渡场长及有关人员组成。', 313);
INSERT INTO `t_military_term_data` VALUES ('db44dfbc-8fd1-4660-adaa-c3b0d5d734fd', '878651de-adf5-4c72-9376-9c363b893ff8', '战略目的', '战略行动所要达到的预期结果。是战略企图的集中体现和制定战略计划的基本依据。', 60);
INSERT INTO `t_military_term_data` VALUES ('db484288-a726-4f5e-b592-e4ef2c696e56', '31f4a446-5b98-4873-9d53-310d97125b07', '第二炮兵指挥自动化系统', '保障第二炮兵各级指挥机构对所属部队作战行动和导弹武器的安全使用实施指挥与控制的指挥自动化系统。是军队指挥自动化系统的组成部分。包括作战指挥、侦察情报、通信传输、武器控制等分系统。', 127);
INSERT INTO `t_military_term_data` VALUES ('db4d495d-a1ae-48e5-8206-6e4d1237221f', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '宽待俘虏', '中国人民解放军实行的从宽对待被俘敌军官兵的政策。主要内容包括：对俘虏不杀害,不打骂,不虐待,不侮辱,不没收其私人财物,尊重其人格、宗教信仰和民族风俗,治疗其伤病,给予人道主义待遇,在适当时机予以释放和遣返等。', 128);
INSERT INTO `t_military_term_data` VALUES ('db508675-bd37-4dad-914b-d25e9fcc3b23', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '值班制度', '军队中关于人员或单位按规定时间轮流担任工作或轮流处于待命状态的制度。通常有首长值班制度,机关值班制度,部队或分队值班、值日制度,基层战斗单位和专业性单位的值班、值日、值更制度等。主要包括值班的设立、职责以及换班的时间、程序和方法等方面的规定。用以加强战备,保持工作和指挥的不问断,维持军队内务秩序和保障安全。', 19);
INSERT INTO `t_military_term_data` VALUES ('db7bc543-1a7d-4233-b481-ff1c15e0d671', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '纵深打击', '对敌作战部署纵深的目标实施的突击。是现代作战的一种重要方法。主要手段包括：航空兵袭击,导弹和远程火炮袭击,空降兵突击,特种部队对敌纵深的破袭等。', 109);
INSERT INTO `t_military_term_data` VALUES ('db901fe0-39c7-4152-bf36-8d8677beaf89', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '起爆器', '亦称点火机。为起爆爆破装药提供点火能的爆破器材。分为直流发电机式起爆器、电容式起爆器和遥控起爆器。', 233);
INSERT INTO `t_military_term_data` VALUES ('db939f20-6896-4ab3-b65b-794b7f03f7a0', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射击', '射手或操作人员利用发射装置,经过瞄准将射弹射向目标的行动。', 1);
INSERT INTO `t_military_term_data` VALUES ('dbadd755-0ea3-49e3-bf0b-797b1b963fc3', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '火力对比', '敌对双方火力密度的比较。通常指双方在一定时间和地域内的火力对比,也指双方相当的建制单位之间的火力对比。', 158);
INSERT INTO `t_military_term_data` VALUES ('dbbad971-2c30-454c-93ba-e2fe7a3d3ec1', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机动升限', '直升机在发动机以最大功率工作的状况下向前爬升能达到的最大高度。分为理论动升限、实用动升限、巡航动升限和战斗动升限等。', 20);
INSERT INTO `t_military_term_data` VALUES ('dbc355b4-7b5b-41bb-9fc6-a27bd6382f9d', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '大比高空爆', '比高在250米/根号3下千吨TNT当量以上的空中核爆炸。能杀伤地面上较大范围的暴露人畜和破坏不坚固的地面目标。', 148);
INSERT INTO `t_military_term_data` VALUES ('dbc5f9d3-35a0-4ebb-a717-476f9169910e', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '评定职称', '按照国家和军队统一现定的条件,根据军队专业技术人员的学术、技术和业务水平,对其专业技术职务等级进行评审和认定的活动。职称等级分为高级、中级、初级3等。', 89);
INSERT INTO `t_military_term_data` VALUES ('dbcb989b-69e9-4912-8ba1-9b4741ad754a', '97a19170-bfac-42c5-9906-1acb187f0654', '机场关闭', '机场停止对空引导和保障等活动,不接受飞机、直升机的起降。', 417);
INSERT INTO `t_military_term_data` VALUES ('dbcdcefc-2a77-4c97-b184-7b1dc4e5fc82', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '素图', '以一种或几种浅淡色调印制的地图。通常用作军事标图、规划设计和标绘专业内容的底图。', 268);
INSERT INTO `t_military_term_data` VALUES ('dbd43eea-c11e-4c80-b7c4-3ca36d90d4fc', 'f0140091-c11a-48c9-8836-8aa94439dac0', '交替前进', '单兵或分队之间互相掩护,轮番前进的运动方法。', 115);
INSERT INTO `t_military_term_data` VALUES ('dbdfafa6-608b-4daf-9fdd-d9fde269f2ec', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队作战方式', '导弹部队遂行作战任务的方式。按武器装备的性能,分为固定作战和机动作战；按阵地的设置情况,分为基本阵地作战和预备阵地作战。', 14);
INSERT INTO `t_military_term_data` VALUES ('dbe0244a-0a8d-4555-9d2b-8c0440f23998', '98df76fb-4b65-48ff-a56c-4db587327c79', '按指挥系统保障', '后勤机构按作战指挥关系组织实施的保障。负责对建制内的和配属的部队或分队以及随军支前的民工、民兵的后勤保障。', 35);
INSERT INTO `t_military_term_data` VALUES ('dbe0ff4b-a32e-4b4e-a22a-663779c56dba', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '人防组织机构', '国家为领导人民防空而建立的各级组织机构的统称。中华人民共和国的人防组织机构主要是国家人民防空办公室及在大军区、省（自治区、直辖市）和一些重点城市设立的相应组织。', 63);
INSERT INTO `t_military_term_data` VALUES ('dbf0698b-aeed-4850-bf34-8fd604eaf726', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '干通比', '干扰通信距离比的简称。在干扰压制有效的条件下,干扰机至被干扰的通信接收机之间的距离与被干扰的通信收、发信机之间距离的比值。是通信干扰机的一项战术指标。', 85);
INSERT INTO `t_military_term_data` VALUES ('dbf3e68a-dd24-4ddf-aed1-515f05b0b20e', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核炮弹', '装有核战斗部的炮弹。分为原子炮弹和中子炮弹。原子炮弹的威力一般为几百至几千吨梯恩梯当量；中子炮弹的威力一般为1千～2千吨梯恩梯当量。具有体积小、重量轻、射程短、灵活机动等特点。', 108);
INSERT INTO `t_military_term_data` VALUES ('dc229b35-6e08-4fe2-b568-efe5134e2f21', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '坐标', '确定平面上或空间中一点位置的有次序的一组数。在地形图上绘制有地理坐标网和平面直角坐标网,可用以迅速准确地确定点的地理坐标和平面直角坐标。', 230);
INSERT INTO `t_military_term_data` VALUES ('dc23683b-e60b-4bd6-b955-3b7100f80f25', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '方向比法试射', '用观察所测得的炸点方向偏差量和高低偏差量,分别乘以方向比,求取射击修正量并进行修正以确定目标效力射开始诸元的试射。通常在小间隔射击的情况下,对位于倾斜度大于40度的正斜面上的目标用低伸弹道射击时采用。', 153);
INSERT INTO `t_military_term_data` VALUES ('dc38a043-fba0-4ac4-a9fd-f5e4e97657a8', '06a75831-13a1-4660-870a-455bb445336a', '后方通信', '为保障军队后方指挥和供应,按后勤部署和供应关系建立的通信联络。包括上下级后方指挥所之间,后方指挥所同所属部队和分队之间,上级派出的供应单位以及地方支前机构之间,供应机构同被供应单位之间建立的通信联络。', 18);
INSERT INTO `t_military_term_data` VALUES ('dc38e679-1c84-4336-aae9-cdde2ff0b0c6', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '配水', '按供水计划将水分配给军队用户的给水作业。', 367);
INSERT INTO `t_military_term_data` VALUES ('dc391bcc-6117-4953-8898-8022a886e7eb', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵照相成果处理车', '用于对炮兵照相侦察的胶片进行洗印、判读和测量的专用车辆。可提供地面全景像片、目标成果图、目标放大像片等，还可提供目标判读报告及目标坐标。', 288);
INSERT INTO `t_military_term_data` VALUES ('dc3a5ce6-7092-4eb2-b4f6-85d1b25cb4b0', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子干扰飞机', '装有电子对抗设备,专门执行电子干扰任务的飞机。主要用以干扰敌方防空系统的各种雷达和无线电通信,掩护航空兵作战。', 123);
INSERT INTO `t_military_term_data` VALUES ('dc3f1996-c32b-455f-aa5c-81c61a94bd27', 'f0140091-c11a-48c9-8836-8aa94439dac0', '山地战斗', '在山地进行的战斗。便于利用地形隐蔽和防护,但指挥、观察、协同、通信联络不便,机动受限,保障困难。', 3);
INSERT INTO `t_military_term_data` VALUES ('dc3fda53-cd4c-461f-9428-b16340e8a09c', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '动态规划', '研究具有动态性质决策过程的最优对策的数学方法。是进行军事运筹分析时解决多阶段决策问题（如作战中的兵力或火力分配、国防资源分配、制导武器控制参数选择等）的有效方法。', 185);
INSERT INTO `t_military_term_data` VALUES ('dc3ffa0c-b744-459e-889c-3459a13cd04b', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂配伍使用', '几种毒剂或毒剂与添加剂按一定比例调配使用的方法。用以改变毒剂的分散性和渗透性,改善毒剂的使用性能,从而增加侦检、防护、消毒、救护的复杂性。', 29);
INSERT INTO `t_military_term_data` VALUES ('dc47477e-aa83-4aa5-9f8f-f0e4f071ac27', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵战斗效率指标', '防空兵完成战斗任务有效程度的数量标准。通常以毁歼概率或击毁敌机架数的数学期望、抗击率和安全率表示。', 60);
INSERT INTO `t_military_term_data` VALUES ('dc4951de-bc60-4bc6-a9a2-917f10a4acc2', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '实时侦察', '以同步或近似同步的时态,将侦察目标的实况显示在终端设备上的侦察。由遥感、数据传输设备和电子计算机构成的自动化侦察系统实施。', 65);
INSERT INTO `t_military_term_data` VALUES ('dc6bbc6b-b7c9-4e9e-9347-ada686c91319', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹假阵地', '导弹部队为欺骗敌人而专门设置的假作战阵地。用以提高真作战阵地的生存能力。其外观和光电反射特性逼真,构筑简易。', 43);
INSERT INTO `t_military_term_data` VALUES ('dc903fa1-3ca1-4e3a-b1e9-086c70d64c16', '06a75831-13a1-4660-870a-455bb445336a', '散射通信', '利用对流层、电离层对无线电波的散射作用而达成的微波、超短波无线电通信。可传送电话、电报、数据和图像。通信容量较大、距离远,但设备较庞大。主要用于干线通信。', 112);
INSERT INTO `t_military_term_data` VALUES ('dc92b422-dd22-4c95-8df9-ddec177e9069', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '城市防御战役', '依托城市市区及其外围地区进行的防御战役。', 122);
INSERT INTO `t_military_term_data` VALUES ('dc9af3df-a394-4a13-8735-00d7e5e39b19', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '观察哨', '为弥补观察所的不足或根据需要而派出的,观察当面情况的哨位。通常由1～3人组成。', 76);
INSERT INTO `t_military_term_data` VALUES ('dca56837-fe22-4aa3-af27-c4969038a598', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '转移干扰', '在投放无源假目标后,又发射有源欺骗干扰，诱使敌方导弹制导系统转而跟踪假目标的电子干扰战术。', 67);
INSERT INTO `t_military_term_data` VALUES ('dcac2c2e-d8cb-45c9-be0b-6a439f96acbd', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役部署', '亦称战役布势。对战役编成内的兵力所作的任务区分、编组和配置。通常根据敌情、地形、任务和战役类型、样式等,建立梯队式部署或集团式部署。', 40);
INSERT INTO `t_military_term_data` VALUES ('dcc6e997-989d-41b3-a0fa-625da36c7f45', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '地雷', '布设在地面或地面下,用以构成障碍物的专用爆炸性武器。主要由雷体和引信组成,在目标作用下起爆或操纵起爆,以杀伤敌有生力量和毁坏其技术装备。按用途,分为防坦克地雷、防步兵地雷和特种地雷；按配用的引信,分为触发地雷。非触发地雷和操纵地雷；按制作方式,分为制式地雷和应用地雷。', 130);
INSERT INTO `t_military_term_data` VALUES ('dccbffed-646f-4d8c-a265-873f950bdc36', 'f0140091-c11a-48c9-8836-8aa94439dac0', '军种战术', '单一军种进行战斗的方法。包括陆军战术、海军战术、空军战术等。', 23);
INSERT INTO `t_military_term_data` VALUES ('dcd14102-7513-4c3f-9947-b717b2efcd52', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '指挥工事', '亦称指挥所掩蔽工事。保障指挥员及其机关人员隐蔽安全地工作和休息的工事。', 44);
INSERT INTO `t_military_term_data` VALUES ('dcd4783b-6b45-4867-81ec-e9431f928a00', '06a75831-13a1-4660-870a-455bb445336a', '移动通信', '通信双方或一方处于运动中的通信。分为陆地移动通信、海上移动通信、空中移动通信。机动灵活,能适应部队频繁机动的需要。', 114);
INSERT INTO `t_military_term_data` VALUES ('dce2a52d-076b-484e-b8cf-e2983898e186', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地图', '将地球表面的自然、社会要素和现象的空间分布,按一定的投影方法、比例关系和制图综合原则,用规定的符号、颜色和注记绘制的图。按内容,分为普通地图和专用地图；按比例尺,分为大、中、小比例尺地图；按表现形式,分为线划地图、影像地图、数字地图；按色彩,分为单色地图、多色地图。可在地图上分析地形,量算距离、方位、高度、坡度、面积等。', 250);
INSERT INTO `t_military_term_data` VALUES ('dce2dc13-ec76-4055-8b28-7ac6bf448ac2', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战斗编成', '将遂行战斗任务的兵力兵器组成有机的整体。其编成的兵力兵器通常包括建制的和配属的。', 47);
INSERT INTO `t_military_term_data` VALUES ('dcfcd927-42ba-4b34-bf4d-2d8aabbf51ef', '06a75831-13a1-4660-870a-455bb445336a', '数字保密电话自动交换网', '用户间可实现自动接续的数字保密电话通信网。通常采用数字程控交换、数字加密和数字传输技术。接通率高,抗干扰性能好,能自动加密、解密。', 69);
INSERT INTO `t_military_term_data` VALUES ('dd009741-63bc-408a-963f-ccc86e59c93e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '利用秒表试射', '用秒表测出目标声音与射弹爆音传播时间之差,并据此求取炸点距离修正量进行射击修正的试射。通常在夜暗、雨雾等观察条件差时采用。', 155);
INSERT INTO `t_military_term_data` VALUES ('dd00d4c2-121f-41a4-bac7-a183a92e8dd9', '878651de-adf5-4c72-9376-9c363b893ff8', '战略反封锁', '综合使用军事、政治、经济等手段,打破敌方战略封锁的行动。', 110);
INSERT INTO `t_military_term_data` VALUES ('dd1188a5-b7aa-4edb-82fe-07a15b212eca', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '激光防护镜', '用以保护人员眼睛免受激光辐射伤害的专用眼镜。有反射型、吸收型、反射吸收型、爆炸型、光化学反应型、光电型和微晶玻璃型防护镜等。', 141);
INSERT INTO `t_military_term_data` VALUES ('dd1decbc-cb56-41e0-88b5-c29790d78ac6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜艇艇员救生设备', '潜艇在水下失事时供艇员离艇脱险的装置和器材的统称。主要包括出艇脱险装置（耐压救生舱、救生闸套、脱险舱口等）和出水脱险器材（脱险浮标、水下脱险装具、快速漂浮脱险器、救生球等）。', 245);
INSERT INTO `t_military_term_data` VALUES ('dd217172-17c2-4d27-a748-8d769c366f36', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射装置', '用以支撑导弹并赋予其射向、进行发射准备和实施发射的专用装置。按导弹的起飞姿态,分为垂直发射装置、倾斜发射装置和水平发射装置；按导弹的作战要求,分为固定发射装置和移动发射装置；按导弹的发射方式,分为热发射装置和冷发射装置。是导弹武器系统中的基本设备和火力计算单位。', 58);
INSERT INTO `t_military_term_data` VALUES ('dd263e8b-1613-4cbe-aa91-c2b1faeb9251', '878651de-adf5-4c72-9376-9c363b893ff8', '战略预备队', '由统帅部直接掌握的担负战略机动作战任务的合成军队。通常配置在战略纵深内。主要用以支援或接替战略第一梯队作战,应付意外情况,稳定或转换战略态势,夺取或保持战略主动权等。', 94);
INSERT INTO `t_military_term_data` VALUES ('dd32cebe-4d12-4391-84fa-92004b1ca357', '06a75831-13a1-4660-870a-455bb445336a', '通信装备修理', '为使已损坏或有故障的通信装备恢复到正常工作状态而采取的技术措施。分为小修、中修和大修。', 214);
INSERT INTO `t_military_term_data` VALUES ('dd669289-ad04-4e88-b049-d0d8b5011139', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '实弹演习', '按照想定情况,以实兵演练战斗动作并发射实弹的军事演习。多用于战术范围的单方演习。', 118);
INSERT INTO `t_military_term_data` VALUES ('dd68415a-6e0b-46cc-bee3-8ba6371e79d1', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机尾追攻击', '直升机在空中追赶敌航空器,并从其后方进行的攻击。', 84);
INSERT INTO `t_military_term_data` VALUES ('dd6ed5f6-ecbe-4890-9bab-0a78d54c96a4', '8a761efd-50a6-4ac8-9913-b7d745104f82', '瞄准线', '①用机械瞄准具,视线通过照门上沿中央和准星尖中央瞄向目标的直线。②用光学瞄准镜瞄向目标的镜内光轴。', 9);
INSERT INTO `t_military_term_data` VALUES ('dd91d305-cb54-41ff-af35-41454f4703fd', '97a19170-bfac-42c5-9906-1acb187f0654', '空中水平攻击', '飞机或直升机在水平飞行中对空中目标进行的攻击。', 84);
INSERT INTO `t_military_term_data` VALUES ('dda1b492-78ec-4d3c-948e-cf46aa8b4acb', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练保障', '为使军事训练顺利实施而采取的各项保证性措施与进行的相应活动的统称。通常包括：经费保障,教材保障,器材保障,物资保障,场地保障,电化教学保障和勤务、技术保障等。', 179);
INSERT INTO `t_military_term_data` VALUES ('dda1cf50-cd9a-434f-857f-40c85055cf1b', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '低压槽', '天气图上水平气流呈明显的气旋式切变、等压线伸向气压较高一侧的槽形区域。低压槽内各条等压线曲率最大处的连线称为槽线。槽线附近气流辐合上升,易产生低云、降水等。', 42);
INSERT INTO `t_military_term_data` VALUES ('ddaa803c-1dcc-4a0b-b302-b3b2e8981ecd', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '定编', '正式确定军队中某一建制单位的编制。', 68);
INSERT INTO `t_military_term_data` VALUES ('ddba3251-21a6-4f52-9b29-698b121d07d4', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '反侦察', '为防范、制止和破坏敌方的侦察而采取的措施和进行的相应活动的统称。包括反武装侦察、反谍报侦察、反技术侦察等。主要手段有：使用技术伪装,组织战役战术欺骗,进行电子干扰,摧毁敌方侦察设施,组织警戒、保密、防间谍等。', 124);
INSERT INTO `t_military_term_data` VALUES ('ddbe9f15-4c2f-4b9f-a38e-4e5652898dd1', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '河流', '沿地表线形低凹部分集中的经常性或周期性水流。较大的称河或江,较小的称溪。发源地称河源。入海、湖处或与另一河流的交汇处称河口。', 59);
INSERT INTO `t_military_term_data` VALUES ('ddce3f46-0dc4-4c8e-812c-43a736dd903f', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇隐蔽性', '舰艇所具有的抗探测搜索的性能。是舰艇战术技术性能要素之一。主要表现为降低舰艇自身各种物理场的辐射强度,如磁场、电场、声场、水压场、热场、核辐射场等。', 335);
INSERT INTO `t_military_term_data` VALUES ('ddd6bb49-fe1b-42d2-8634-1416eb4e2e3f', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '后卫', '位于行军纵队后部,担负后方警戒和护卫任务的部队或分队。', 11);
INSERT INTO `t_military_term_data` VALUES ('dde24d74-79f6-4c86-809d-2ea9d306530f', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机地形跟踪飞行', '直升机贴地飞行时,飞行高度随飞经地形的高度变化而变化,保持一定相对高度的飞行。', 31);
INSERT INTO `t_military_term_data` VALUES ('ddfcb816-1aff-443a-a46c-2fcc8588c194', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '接应', '以兵力或火力应援其他部队或人员的作战行动。如派出兵力接应突围的部队,已入城的部队接应后续人城的部队等。', 331);
INSERT INTO `t_military_term_data` VALUES ('de15cf29-27d0-4d21-a27f-57f7d219758d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事学术', '研究战争指导、作战方法和武装力量建设的理论及其应用的各学科的统称。是军事科学的重要组成部分。包括战略学、战役学、战术学、军队指挥学、军制学、军事训练学、军事运筹学等学科。其中,战略学、战役学、战术学是军事学术的主导部分。', 7);
INSERT INTO `t_military_term_data` VALUES ('de1d6ca4-667a-4ba0-b8ac-dad0229eb064', 'f0140091-c11a-48c9-8836-8aa94439dac0', '搜剿', '搜索和剿灭溃散隐藏之敌的行动。', 198);
INSERT INTO `t_military_term_data` VALUES ('de20636c-0136-460d-9b6b-91a3c73d0b40', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '条例', '国家或军队制定的关于某项工作的法规性文件。如《中国人民解放军现役军官服役条例》、《中国人民解放军武器装备管理工作条例》等。', 20);
INSERT INTO `t_military_term_data` VALUES ('de24716a-611f-4f9e-924a-11bebe5997d1', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '工作秩序', '军队的各项工作按照有关条令和规定保持的井然有序的状态。', 32);
INSERT INTO `t_military_term_data` VALUES ('de2c8461-89de-4428-b570-a574551186f1', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '渗透侦察', '侦察分队利用敌人部署的间隙成暴露翼侧秘密渗入敌区进行的侦察。', 38);
INSERT INTO `t_military_term_data` VALUES ('de3625f1-45db-4a82-a564-c3b7c137ec3c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '机动式弹头', '弹道末端机动式弹头的简称。在飞行弹道末端按预定程序改变飞行弹道的导弹弹头。通常由壳体、末制导系统、推进系统、核装置和引爆控制系统等组成。突防能力强,命中精度高。机动式弹头也可以是多弹头。', 28);
INSERT INTO `t_military_term_data` VALUES ('de37d517-d3e6-44bc-a037-406dae9289c1', '916997ee-6728-4c61-9b79-d96960b1dc86', '致死浓度', '在一定时间内能使90 ％ 以上无防护人员死亡的染毒浓度。用LC90-100表示。', 124);
INSERT INTO `t_military_term_data` VALUES ('de3e4e0d-6c8d-4773-822b-c7b8ea0c9e56', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '地面核爆炸', '简称地爆。爆心在地面或接近地面的空中,火球接触地面的核爆炸。分为有坑地面核爆炸（含触地核爆炸）和无坑地面核爆炸。地面核爆炸的光辐射和冲击波比较集中,能造成强烈的地运动,对坚固的地下和地面目标杀伤破坏作用较大。地爆的放射性沾染严重,持续时间长,能有效地阻滞敌方的行动。', 151);
INSERT INTO `t_military_term_data` VALUES ('de3f4ef0-d382-4572-adcf-e58350c42f51', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '集火射向', '炮兵连内各门火炮的射向统一指向目标某一部位所构成的射击方向。通常用于对点目标或幅员较小的目标射击。', 210);
INSERT INTO `t_military_term_data` VALUES ('de3f7d11-b867-443a-8d6a-d4096ccf0515', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '燃烧地雷', '装填燃烧剂用以烧毁目标或造成火障碍物的特种地雷。', 153);
INSERT INTO `t_military_term_data` VALUES ('de498436-f69b-4ef5-b313-e9f5239aaeb6', '878651de-adf5-4c72-9376-9c363b893ff8', '战略措施', '根据战略方针,为完成战略任务而采取的重大举措和办法。', 80);
INSERT INTO `t_military_term_data` VALUES ('de53d80e-4335-4276-9aab-1d879493ed3e', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术要点', '对战斗具有重要价值的地点。通常指对发展进攻或确保防御稳定性具有重要作用的高地、山垭口、隘路、建筑物等。', 39);
INSERT INTO `t_military_term_data` VALUES ('de57f381-7617-4851-bca3-2eaac0d335c4', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '风险分析', '亦称风险度分析。分析和预测军事决策的成功或失败的程度的方法、一般通过对随机因素的统计分析或判断,确定决策成功或失败的概率。是军事运筹分析的重要方法。', 181);
INSERT INTO `t_military_term_data` VALUES ('de86b8f7-e7db-4f7c-bec0-90819b22371d', '06a75831-13a1-4660-870a-455bb445336a', '静态图像通信', '传输静止图像与凝固图像的通信。包括传真通信和凝固图像通信。传真通信,是用传真机传输文字、照片和图表等静止图像；凝固图像通信,是用电视设备收看定时转换的图像。战时用于传送前沿阵地的景象,平时用于观察训练和作战演习等实况。', 142);
INSERT INTO `t_military_term_data` VALUES ('de8db850-47ed-4538-a66a-3ece81b1c444', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反突防', '对敌方突防的导弹或飞机实施拦截的行动。通常利用对空防御系统,及时发现、跟踪、识别并截击敌之导弹或飞机。', 211);
INSERT INTO `t_military_term_data` VALUES ('dea34a8e-fdd0-4ad2-be08-7d9959001a53', 'f0140091-c11a-48c9-8836-8aa94439dac0', '营防御地域', '营负责防守的地域、通常由各连防御阵地、营直接指挥的火器射击阵地和指挥观察所组成。', 211);
INSERT INTO `t_military_term_data` VALUES ('deb71b66-3a88-4292-a593-4e2bcfaa01bb', 'd7132c58-5df3-4b97-919f-58740148b9ca', '自动发射', '地空导弹按照发射程序自动控制实施的发射。', 207);
INSERT INTO `t_military_term_data` VALUES ('debb305a-3df8-4da9-959a-50278f48f5ae', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上突击顺序', '实施海上突击时,各突击群（舰艇）实施突击的先后次序。通常由机动性能好、武器射程远和突防能力强的突击群（舰艇）实施首次突击。', 45);
INSERT INTO `t_military_term_data` VALUES ('dec166a4-c765-430a-819c-247c26184341', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '微电子技术', '研制、生产和应用微电子器件实现电子系统功能的技术。对军事技术装备的小型化和自动化具有重要作用。', 23);
INSERT INTO `t_military_term_data` VALUES ('dec1a537-02d4-4e21-9fad-255dee9f5cc7', '97a19170-bfac-42c5-9906-1acb187f0654', '航空通信', '空中航空器之间,空中航空器与地面通信台站或与舰船通信台站之间的通信的统称。包括空中通信和地空通信。一般以无线电通信为主,视觉信号通信为辅。', 350);
INSERT INTO `t_military_term_data` VALUES ('ded03a30-cffc-468b-b673-ebabbd64762a', '06a75831-13a1-4660-870a-455bb445336a', '通信联络规定', '各通信对象实施通信联络时应共同遵守的规定。包括无线电台通信联络规定,无线电接力通信联络规定,隐蔽指挥规定以及其他各种通信台、站的通信联络规定。', 44);
INSERT INTO `t_military_term_data` VALUES ('ded462c3-9981-444e-b4fd-dd95462f25f5', '98df76fb-4b65-48ff-a56c-4db587327c79', '基地兵站网', '在战或战役方向上,以铁路、公路干线连结起来的若干兵站所构成的前后贯通、左右相连的后勤保障网。', 52);
INSERT INTO `t_military_term_data` VALUES ('dedbb2f1-6dfd-4be3-b7a6-2013954557f6', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '装备送修', '将无力修复或不便修复的损坏的武器装备、送到上级或地方有关单位进行修理。', 119);
INSERT INTO `t_military_term_data` VALUES ('dee05583-6cea-4f97-b77b-810ece67e5ed', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战场侦察', '为查明战场情况而进行的侦察。分为地面战场侦察、海上战场侦察和空中战场侦察。', 20);
INSERT INTO `t_military_term_data` VALUES ('def3213e-38cc-4804-be04-9f994797a720', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '火箭技术', '研制火箭所涉及的各种技术的统称。主要包括火箭总体设计技术、推进技术、控制技术、头部或战斗部技术、试验技术等。广泛应用于研制导弹和运载火箭。', 4);
INSERT INTO `t_military_term_data` VALUES ('df096f04-4cd9-4d45-adf6-889ed8e5a75b', '878651de-adf5-4c72-9376-9c363b893ff8', '高技术战争', '大量运用具有信息技术、新材料技术、新能源技术、生物技术、航天技术、海洋技术等当代高、新技术水平的常规武器装备,并采取相应作战方法进行的战争。', 15);
INSERT INTO `t_military_term_data` VALUES ('df0f2875-3c1d-4c29-b8a3-51ec368435d8', '98df76fb-4b65-48ff-a56c-4db587327c79', '车辆运用凭证', '军用车辆运用的凭据和证明。包括军车号牌、行车执照和行驶卡片。', 315);
INSERT INTO `t_military_term_data` VALUES ('df0fb418-b5ef-4819-a49b-4e2b603371dd', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '登陆基地', '登陆兵在已夺占的登陆场建立的临时基地。设有码头、仓库和助航标志,并修筑道路,组织调整勤务等。用以保障后续部队和装备物资上陆。', 74);
INSERT INTO `t_military_term_data` VALUES ('df424613-ede4-4c27-b641-e5534e2f3c02', '98df76fb-4b65-48ff-a56c-4db587327c79', '野战兵站', '具有一定机动能力,能随时展开或撤收的兵站。', 17);
INSERT INTO `t_military_term_data` VALUES ('df43dbd3-5853-4db7-8a75-516b2a6d41ca', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '军事气候区划', '以气候类型为基础,按一定的军事气象条件对某一地区的气候进行的逐级区域划分。通常以图、表和文字相结合的形式表述。根据用途,分为综合军事气候区划、军兵种气候区划或专业军事气候区划等。是制定作战、训练、后勤等保障计划,进行武器装备研制、使用、维护和其他国防建设的依据之一。', 91);
INSERT INTO `t_military_term_data` VALUES ('df458f7e-2b5b-4341-a742-e7a636e0a5b3', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行马赫数', '简称飞行 M数。航空器的飞行速度与其飞行高度上音速的比值。超音速飞行时,飞行马赫数大于l；亚音速飞行时,飞行马赫数小于1。', 228);
INSERT INTO `t_military_term_data` VALUES ('df4c47bf-7f6a-4c9c-bd33-b24ea65aa493', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '缴获', '作战中,收缴、获得敌方武器装备、物资、文件等的统称。', 383);
INSERT INTO `t_military_term_data` VALUES ('df5d938c-065c-4f67-90cb-2534497580ff', 'f0140091-c11a-48c9-8836-8aa94439dac0', '指示目标', '指出目标的名称、方向和位置。主要方法有在现地和地图上指示,或利用战场侦察、监视系统指示。', 68);
INSERT INTO `t_military_term_data` VALUES ('df606180-d7cd-4da4-9603-eb2fb165a4d5', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '激光技术', '研究激光的产生传输、探测及其应用的技术。主要包括各种激光器的研制技术。激光光学系统和精密机械的制造技术，信息的处理和显示技术等。军事上广泛应用于测距、通信、制导、模拟训练以及激光武器等方向。', 25);
INSERT INTO `t_military_term_data` VALUES ('df650fa7-95e2-4f64-82f0-4bd3d103a56b', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '卫星多普勒定位', '利用测量卫星发射的无线电信号的多普勒频移实施定位的方法。主要用于舰船、飞机导航和地面点位置的测定。', 226);
INSERT INTO `t_military_term_data` VALUES ('df6b5cb5-5ed2-4e17-b42a-05dfe474fc68', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵夜间射击', '炮兵在夜间实施的射击。射击时一般要使用夜视器材观察,条件允许时还可发射照明弹照明，或使用雷达、声测分队进行保障。', 193);
INSERT INTO `t_military_term_data` VALUES ('df77e6e8-25ab-4223-bb81-5c23c402861c', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '海防侦察', '海防部队、民兵在沿海地区和领海海域组织实施的侦察。', 26);
INSERT INTO `t_military_term_data` VALUES ('df8b226d-e238-4473-b82f-7596210f35ee', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海洋调查船', '装有专门设备用于海洋科学考察的勤务舰船。分为综合海洋调查船和专业海洋调查船。', 152);
INSERT INTO `t_military_term_data` VALUES ('df8e4dd0-ec9a-47d2-9641-076e74eb0353', '98df76fb-4b65-48ff-a56c-4db587327c79', '军用方舱', '能对人员、装备、物资提供良好工作环境和防护条件的箱式后勤装备、由舱体、内部设施和附加装置构成,适于各种运输工具运载,可用作人员掩蔽部和指挥所、救护所、修理所等机构的工作间。分为基本型方舱、简易型方舱和特种方舱等。', 21);
INSERT INTO `t_military_term_data` VALUES ('df991415-7615-4a28-bf26-173a86bdd9fc', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练考核', '对训练质量进行的考查和核定。', 173);
INSERT INTO `t_military_term_data` VALUES ('df9ce773-8df6-46ca-9118-9803160f2f9c', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥跨度', '亦称指挥幅度。指挥员及其指挥机关直接指挥的建制单位的数量通常根据任务、指挥能力、指挥手段和兵力等情况确定。', 7);
INSERT INTO `t_military_term_data` VALUES ('dfa1ff21-8174-419b-b49d-9ad73deb957c', 'f0140091-c11a-48c9-8836-8aa94439dac0', '海岸防御战斗', '在濒海地区抗击敌人登陆的防御战斗。', 204);
INSERT INTO `t_military_term_data` VALUES ('dfab08d1-685a-4931-8308-b66f66a5f054', '06a75831-13a1-4660-870a-455bb445336a', '无线电静默', '在规定的时间和区域内禁止无线电发信。通常在战斗准备、变更部署、秘密接敌、设伏和撤离战场等情况时实施。', 42);
INSERT INTO `t_military_term_data` VALUES ('dfc5a14e-5fba-45ee-ade3-7cdc17b191b3', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '重力异常', '实际重力值与正常重力值之差。反映了地球形状和质量分布与正常椭球的差别。是研究地球形状、卫星轨道摄动和修正远程导弹弹道的重要数据。', 223);
INSERT INTO `t_military_term_data` VALUES ('dfc67bb0-2b08-4a21-8c18-4995d94f97e3', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '群众性练兵', '部队、分队中开展的群策群力、能者为帅、互教互学的军事训练活动。是中国人民解放军的传统练兵方法之一。', 159);
INSERT INTO `t_military_term_data` VALUES ('dfd85956-0b60-4646-9b5c-067e5382c83c', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '钳形突击', '从敌人两翼发起进攻并向同一目标实施夹击的突击。通常在敌防御正面阵地突出、两翼暴露或两翼地形便于实施突击时采用。', 101);
INSERT INTO `t_military_term_data` VALUES ('dfdee5b1-46b6-4c29-a48a-3a0b4f31d8e3', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵', '①不脱离生产的群众武装组织。中华人民共和国的民兵是国家武装力量的组成部分。②民兵组织的成员。', 20);
INSERT INTO `t_military_term_data` VALUES ('dfe1bb48-d2c4-48db-985d-ab8d1bed46d2', 'd7132c58-5df3-4b97-919f-58740148b9ca', '便携式地空导弹武器系统', '由单兵或小组携带使用的地空导弹武器系统。以肩扛方式发射或用小型发射架发射。由导弹、发射筒、发射机构、地面电池和敌我识别器等组成。是攻击低空和超低空目标的重要地面防空武器。', 31);
INSERT INTO `t_military_term_data` VALUES ('dfe87405-af47-45a0-866e-35edfae1cbb1', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射可靠性', '亦称导弹发射可靠率。在规定的发射条件和时间内成功发射导弹的可靠程度。主要取决于导弹及其地面设备等的可靠性和可维修性,还与操作人员的心理状态、技术水平等有关。', 121);
INSERT INTO `t_military_term_data` VALUES ('dfef2324-29c9-49ed-b677-10b45b5ec147', '97a19170-bfac-42c5-9906-1acb187f0654', '地标', '具有明显特征,易于从空中识别的地物和地貌。分为点状地标、面状地标和线状地标。如城镇、桥梁、山岳、机场、河流、铁路等。主要用于飞行中判定航空器位置,测定领航数据和辨认目标。', 369);
INSERT INTO `t_military_term_data` VALUES ('e018e90e-7de6-43d0-917f-c63d17636ef5', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮发射种类', '按照发射的程序和时间间隔对高炮发射炮弹方式的分类。中口径高炮分为单发射、齐射和急促射；小口径高炮分为单发射、短点射和长点射。', 180);
INSERT INTO `t_military_term_data` VALUES ('e0259f5c-55b2-46c9-8863-56a935bcde1e', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '统帅部', '战时国家武装力量的最高领导和指挥机关。有的国家称作大本营。负责筹划和指导战争全局,实施战略指挥。', 3);
INSERT INTO `t_military_term_data` VALUES ('e04d240f-cca7-4f14-a94a-1aa286c5ad6e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '坑道维护', '为保障坑道及其设备的性能完好而采取的定期检查和维修措施。一般分为外部维护和内部维护。', 85);
INSERT INTO `t_military_term_data` VALUES ('e066f90e-f48e-49df-94fc-32a0f4594132', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '云状', '云的外形特征。包括云的尺度、形状、结构、灰度、透光程度和所在高度等。', 21);
INSERT INTO `t_military_term_data` VALUES ('e06d5959-c89e-4cd7-a8bc-b2540661d00d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇港岸训练', '舰艇人员利用港岸教练设备和战斗装备进行的训练。通常包括理论学习、操练、操演、图上作业、模拟海上训练等。目的是为海上训练打牢基础或巩固海上训练效果。', 315);
INSERT INTO `t_military_term_data` VALUES ('e07274fe-94bf-4f5d-9f2b-a977468a54bc', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '松发地雷', '卸除预加在发火机构上的荷载即发火的触发地雷。配用松发引信。松发地雷多作为诡雷使用,当人员移动压在其上的物体或剪断其拉线时即爆炸。', 138);
INSERT INTO `t_military_term_data` VALUES ('e0905d49-db69-422a-b13c-1b08a5154cac', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇支队', '集团军建制内担负对空预警任务的雷达专业分队。由指挥分队和数个雷达分队组成。主要是为集团军指挥所及其所属的防空部队提供空情保障。', 8);
INSERT INTO `t_military_term_data` VALUES ('e093fa54-f4a6-45b2-a98f-44ccfa3c484f', '878651de-adf5-4c72-9376-9c363b893ff8', '战略方针', '一定时期内规定的战争准备与战争实施须达到的总目标和应遵循的指针。是军事战略的核心与集中体现。分为统管全局与全过程军事行动的总方针和指导不同阶段与范围军事行动的具体方针。', 58);
INSERT INTO `t_military_term_data` VALUES ('e09a0b45-e79f-4a93-999e-2affe8e363eb', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '敌我态势', '敌对双方部署和行动所形成的状态和形势。按范围,分为战略敌我态势、战役敌我态势、战斗敌我态势；按时间,分为战前敌我态势、战中敌我态势（其中又分为某日和某时的敌我态势）、战后敌我态势。', 264);
INSERT INTO `t_military_term_data` VALUES ('e09a8ef2-0fa3-4846-b143-3a69e1d8fe7b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰名', '国家或海军授予舰艇的名称。用以确立舰艇在海军中的序列位置,以便指挥和管理。通常用人名、地名、星辰名、水族名、鸟兽名、植物名以及荣誉称号等命名。', 126);
INSERT INTO `t_military_term_data` VALUES ('e0a41c5e-0e3b-4745-9e71-ede3ccec0ba8', '98df76fb-4b65-48ff-a56c-4db587327c79', '单车油料基数里程', '单台车辆一个基数的油料按基本耗油标准计算,能供车辆行驶的里程。', 172);
INSERT INTO `t_military_term_data` VALUES ('e0a6098a-4c00-4b7f-8003-dfa4ddd00f5f', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火延伸', '炮兵按计划逐次向敌纵深转移火力的作战行动。主要用以支援步兵、坦克冲击。', 67);
INSERT INTO `t_military_term_data` VALUES ('e0b74e33-8ee4-47e1-820f-52a9a87ea6c5', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹测试', '对地空导弹武器系统的性能和精度进行的测量。分为单元测试和综合测试。', 102);
INSERT INTO `t_military_term_data` VALUES ('e0df67d3-fa9d-447d-93be-58c68dc9ed3f', '8a761efd-50a6-4ac8-9913-b7d745104f82', '直射', '在枪械、火炮整个表尺距离内,瞄准线上的弹道高不超过目标高时直接瞄准目标的射击。', 65);
INSERT INTO `t_military_term_data` VALUES ('e0e406c6-673e-40ef-a8f1-f7598c3710b3', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '陆军航空兵直升机大队', '由若干个直升机中队编成的陆军航空兵一级组织。', 1);
INSERT INTO `t_military_term_data` VALUES ('e0e5498c-d11c-4538-8b72-12c639d452d0', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海洋水文气象浮标', '设置在海上的海洋水文气象要素自动遥测装置。由岸站和浮标两部分组成。按定位方式,分为锚泊浮标和漂流浮标。主要测量；气温、气压、空气湿度、风向、风速、降水,表层海水的温度、盐度、海水透明度,以及波高、波周期、表层流等。能在任何海区和恶劣环境下长期连续工作。', 105);
INSERT INTO `t_military_term_data` VALUES ('e0edaad7-ce5a-4390-96b0-d1d39de4af63', '97a19170-bfac-42c5-9906-1acb187f0654', '防空混成师', '空军中由若干个地空导弹团和高射炮团混合编成的地面防空兵一级组织。为要地防空作战的基本战术兵团。通常隶属于军区空军。', 25);
INSERT INTO `t_military_term_data` VALUES ('e0f5c9d6-a052-4354-ba2f-9f8edf2db840', '916997ee-6728-4c61-9b79-d96960b1dc86', '发烟地域', '由若干发烟点构成的有一定宽度和纵深的施放烟幕的区域。', 80);
INSERT INTO `t_military_term_data` VALUES ('e0ffb3e1-b094-4ebd-b605-c4d4146df03b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '空飘雷', '悬飘于空中的防空雷。由气球将配有近炸引信的雷体悬吊于空中。分为系留空飘雷和非系留空飘雷。系留空飘雷由系留索控制高度。非系留空飘雷靠气球充气量控制高度。', 158);
INSERT INTO `t_military_term_data` VALUES ('e11623cd-1e58-4ccc-a4cd-45826abacf09', '98df76fb-4b65-48ff-a56c-4db587327c79', '枢纽前方作业站', '在铁路枢纽外围选定的,战时开设的能够分担枢纽站部分作业任务的车站。', 273);
INSERT INTO `t_military_term_data` VALUES ('e11d2c24-d129-4d3b-8445-f6b4d324c40e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '示教', '为统一教学思想、内容和方法而进行的示范性的教学活动。', 148);
INSERT INTO `t_military_term_data` VALUES ('e123e09d-93fd-4337-8851-ab42ce2fc21e', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '卫星侦察地面站', '设置在地球表面,用以接收、记录、传输、储存和处理卫星侦察所得信息,并对卫星的侦察系统实施控制的机构及其设施。', 72);
INSERT INTO `t_military_term_data` VALUES ('e126b4b9-b7f5-4a73-ae19-c45cc47ef7c9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '撤收', '炮兵将器材由战斗状态转换为行军状态的过程。', 272);
INSERT INTO `t_military_term_data` VALUES ('e12d240c-5ab0-4e7a-906f-ae936c726ad0', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '预防犯罪', '预先进行思想政治教育和采取各种措施,防止和杜绝各种可能发生的犯罪行为。', 141);
INSERT INTO `t_military_term_data` VALUES ('e13d1b25-6a1c-4c51-b221-ce6631a699ef', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察预备队', '各级司令部掌握的机动侦察力量、主要用以执行临时侦察任务或加强、接替已派出的侦察部队或分队。', 71);
INSERT INTO `t_military_term_data` VALUES ('e1792924-d7b3-49e3-ac6b-fe7e80b6d223', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军士', '①士兵军衔中高于兵、低于士官的一等。军士的衔级一般分为3～6级。中国人民解放军的军士的衔级分为上士、中土和下士3级。②被授予军士军衔的军人。', 117);
INSERT INTO `t_military_term_data` VALUES ('e1829115-0620-4b85-ba12-bf844d733c6c', '06a75831-13a1-4660-870a-455bb445336a', '有线电载波通信', '利用频率分割原理在一条有线电线路上进行多路复用的通信。可传输多路电话、电报、数据和图像等。传输质量较好,通信容量较大,传输距离远,是军用长途通信的重要方式。', 122);
INSERT INTO `t_military_term_data` VALUES ('e18e243e-f8dd-4ee3-aafa-3be638d3ed66', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察专业战术训练', '为使侦察部队和分队掌握侦察战术而进行的训练。主要训练内容包括：侦察兵战术,侦察组战术,伏击捕俘、袭击捕俘、行军侦察、先遣侦察、敌后侦察等班排连战术。', 90);
INSERT INTO `t_military_term_data` VALUES ('e196db72-9679-4f54-839c-fa890c5b4ded', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡河出发线', '部队疏开待渡并能适时前出渡河的位置线。通常设在待渡地区前缘靠近渡口、便于疏散隐蔽的适当位置。适用于漕渡场。', 316);
INSERT INTO `t_military_term_data` VALUES ('e1a62f7b-981c-4a77-a876-693fc3a74cd2', '97a19170-bfac-42c5-9906-1acb187f0654', '空降兵军', '由若干个空降兵师编成的空降兵一级组织。设有领导机关,编有伞兵、坦克、炮兵等战斗部队和通信兵等勤务保障部队。主要遂行空降作战任务。', 27);
INSERT INTO `t_military_term_data` VALUES ('e1b1f524-3e8d-4579-a580-9f012cca94db', '06a75831-13a1-4660-870a-455bb445336a', '超短波电台', '亦称甚高频电台。工作波长为10～l米（频率为30～300兆赫）的无线电台。通常指工作在此波段内的对讲机、调频电台、调幅电台、单边带电台和跳频电台等。主要用于通话,有的还可传输电报、数据和图像等。是战时无线电通信的主要装备。', 179);
INSERT INTO `t_military_term_data` VALUES ('e1c5b220-9b84-4af0-a23e-3c80d12ef0a9', '98df76fb-4b65-48ff-a56c-4db587327c79', '主油', '亦称燃料油。军队用于各种动力机械燃烧供能的油料的统称。如汽油、柴油、喷气燃料等。', 166);
INSERT INTO `t_military_term_data` VALUES ('e1e7c155-9252-4952-91a3-4daa01076d89', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '瞄准具', '使射击武器或投掷武器瞄准目标的装置。按所配用的武器类型,分为枪械、火炮、导弹、炸弹、鱼雷瞄准具等；按结构和作用原理,分为机械、光学、红外、微光、激光和光电综合瞄准具等。瞄准具与火控雷达、计算机配合，组成武器火控系统。', 70);
INSERT INTO `t_military_term_data` VALUES ('e1f0280c-ce81-4cff-8891-eccc62e4d361', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹冷发射', '亦称外力发射或弹射。靠弹射系统的动力使导弹弹离发射装置,到达预定高度后导弹发动机再行点火的发射。冷发射可节省弹内推进剂,减轻导弹重量,但设备复杂。', 119);
INSERT INTO `t_military_term_data` VALUES ('e20f78c7-3a9d-4304-bd1e-c6ee9554a08e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥环境', '影响指挥活动的各种情况和条件的统称。主要包括：指挥对象、作战对象、作战时间和空间遂行任务地区的社会情况和自然条件等', 38);
INSERT INTO `t_military_term_data` VALUES ('e2123ed7-f44d-4001-87ec-efcdadcfe895', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '露天工事', '不加掩盖的工事。', 54);
INSERT INTO `t_military_term_data` VALUES ('e2137037-804b-429f-be1f-9a2e72fb6ad1', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工事', '为保障军队作战行动而构筑的防护性建筑物。按构筑时机和预定使用时间,分为永备工事和野战工事；按构筑方式,分为掘开式工事、暗挖式工事和堆积式工事；按支撑结构的施工方法,分为整体式工事和装配式工事；按作战用途,分为射击工事、观察工事、指挥工事、掩蔽工事、交通工事和堑壕。', 38);
INSERT INTO `t_military_term_data` VALUES ('e2145541-d84d-46a3-93d8-9bfdd11fbb90', '06a75831-13a1-4660-870a-455bb445336a', '通信值勤', '通信台、站组织通信人员昼夜值班和执勤。', 56);
INSERT INTO `t_military_term_data` VALUES ('e21fd8b2-3dd7-48be-b5de-89b9fcf4cad6', '97a19170-bfac-42c5-9906-1acb187f0654', '航空侦察情报报知通信', '从飞行的航空器上向地面指挥机构传递航空侦察情报的通信。通常在地空指挥无线电网内实施。也可根据航空侦察的范围、任务和性质,组织专门的航空侦察无线电网。', 353);
INSERT INTO `t_military_term_data` VALUES ('e2259338-e027-446f-b85d-4f37e2d83ec9', 'd7132c58-5df3-4b97-919f-58740148b9ca', '阵地、指挥所观察网', '由防空兵阵地、指挥所的对空观察员组成的对空观察网。通常采取定人、定位、定任务的方法,进行圆周、多层、有重点的对空观察。', 121);
INSERT INTO `t_military_term_data` VALUES ('e22655a7-1355-4aa1-bd2f-ffe54da53651', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇警戒雷达', '亦称舰艇搜索雷达。用以搜索、监视、测定空中和海面目标的舰艇雷达。分为舰艇对空警戒雷达和舰艇对海警戒雷达。', 228);
INSERT INTO `t_military_term_data` VALUES ('e2316030-df3f-4abd-aa1e-3787bac3853a', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机空中正常投放', '直升机按计划或正常程序,将载运或吊挂的装备、物资等从空中投到地面的行动。', 26);
INSERT INTO `t_military_term_data` VALUES ('e23415f2-a071-45ef-b69d-f229846c2f3b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '全纵深作战', '敌对双方在从前沿到后方的整个作战区域内同时展开的作战。', 194);
INSERT INTO `t_military_term_data` VALUES ('e23dc962-e99f-477b-bc36-8c51e766a82d', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机乘载', '人员搭乘直升机的行动。', 12);
INSERT INTO `t_military_term_data` VALUES ('e24b3dd7-1d1d-480c-9965-bfef3272e915', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '光面爆破', '按设计轮廓线爆落预留岩层，使围岩或边坡表面保持平整的爆破。常用以开挖坑道、地道、隧道、巷道,也可用以开挖石质路堑等。', 242);
INSERT INTO `t_military_term_data` VALUES ('e255c08d-3f19-44ab-80f1-be37248a7720', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '抗登陆战役', '依托濒海地区或岛屿抗击敌人渡海登陆的防御战役。大规模的抗登陆战役,通常是由诸军兵种共同进行的联合战役。', 124);
INSERT INTO `t_military_term_data` VALUES ('e26cc5cd-8bb1-4619-afb2-05d11f3a5a2e', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '漏训', '应训人员没有参训或必训课目没有训练。', 175);
INSERT INTO `t_military_term_data` VALUES ('e2700505-dce6-4e71-87aa-9e5ff7fdb8d6', '06a75831-13a1-4660-870a-455bb445336a', '报知通信', '为保障传递警报信号和空情、海情、气象、水文等情报信息而建立的通信联络。通常使用无线电、有线电和光通信等手段,以单方发信的方法实施。有关单位按规定全时守听、定时守听或根据需要守听。各级通信系统对警报信号应优先传递。', 19);
INSERT INTO `t_military_term_data` VALUES ('e276fa24-3e37-44f6-8635-54f184aa7ab6', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '靠近弹', '弹着点靠近目标的射弹。是既不能确切判定为命中弹,又不能准确测出距离和方向偏差的射弹。', 230);
INSERT INTO `t_military_term_data` VALUES ('e27dccff-a328-412c-9821-e09ed9aba3e9', '83e065b4-6737-4645-9ea5-8276d1de13ed', '二类坦克', '符合规定的技术状况,储备一定摩托小时,能执行一般任务,持续作战能力稍差的坦克。', 191);
INSERT INTO `t_military_term_data` VALUES ('e2868ccb-e1d2-4023-9dba-94e4944ccb05', '06a75831-13a1-4660-870a-455bb445336a', '跳频电台', '工作频率由伪随机码控制跳变的无线电台。工作频率可在较宽的范围内快速跳变,跳变的速率通常每秒数次至数百次,跳变的频率数可达数千个,以对抗敌方的侦察干扰。主要用于战术通信。', 185);
INSERT INTO `t_military_term_data` VALUES ('e2947368-4972-4ab9-b2e4-891f5e885813', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役决心', '指挥员对战役目的和行动所作的基本决定。是实施战役的基础和制定战役计划、下达战役命令、组织战役协同的依据。内容包括：战役企图,主要作战方向和地区,战役部署,行动方法,重要保障措施,战役发起时间或完成战役准备的时限,指挥所开设等。', 24);
INSERT INTO `t_military_term_data` VALUES ('e2b41fb9-6210-44b7-a775-764bd86d30d9', '97a19170-bfac-42c5-9906-1acb187f0654', '俯冲轰炸', '飞机向前下方在较大下降角的直线加速飞行中对目标进行的轰炸。其飞行轨迹的延长线与地面的夹角通常为30～90度。是强击机、歼击机、歼击轰炸机的主要轰炸方法。适用于轰炸点状目标和活动目标。', 96);
INSERT INTO `t_military_term_data` VALUES ('e2ca2a4d-771e-4b90-a0cc-bcec26608ad4', 'f0140091-c11a-48c9-8836-8aa94439dac0', '合成预备队', '以机械化步兵或摩托化步兵、坦克兵为主的陆军诸兵种部队或分队编成的预备队。', 50);
INSERT INTO `t_military_term_data` VALUES ('e2d7a448-bcc8-4ec3-a1fe-e6a9b94c9e17', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '党对军队的绝对领导', '中国共产党对中国人民解放军实施的全面的独立的集中统一的领导。是中国人民解放军建军的根本原则。', 3);
INSERT INTO `t_military_term_data` VALUES ('e2daab0e-3d5a-4b76-bd6a-3c463d2aedba', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行大队', '由若干个飞行中队编成的航空兵一级组织。为航空的高级战术分队。通常隶属于航空兵团。', 12);
INSERT INTO `t_military_term_data` VALUES ('e2dbe1d9-47b3-4358-a4c9-84088101c553', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队干部任免', '对军队干部职务的任命和免除的统称。', 84);
INSERT INTO `t_military_term_data` VALUES ('e2e1e670-21cf-44ed-b079-cdc705205100', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克装甲', '用以防御各种反坦克武器的攻击,保护坦克内乘员、武器和机件的刚性防护层。其防护力取决于装甲材料的性能、厚度、形状、结构和制造方法。分为均质装甲和非均质装甲两类。非均质装甲亦称特种装甲,主要有复合装甲、屏蔽装甲和反应装甲等。', 133);
INSERT INTO `t_military_term_data` VALUES ('e2f1addf-46af-46ca-b71b-cac1b71c9750', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '冲沟', '地面上由水流冲蚀而形成的线状深沟。在土质疏松并有一定坡度的地方,冲沟长可达数百米,宽、深可达数十米,沟壁一般较陡峻,妨碍陆上交通,但利于隐蔽。小的冲沟亦称雨裂。', 58);
INSERT INTO `t_military_term_data` VALUES ('e2feceb0-641c-47c2-a1f5-2b2b2ae873cd', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事设施', '专门用于军事目的的工程建筑和设备及其相应的组织机构的统称。主要有：军事指挥工程,作战和防护工程,军用机场、港口、码头,营房,训练场,试验场等。', 56);
INSERT INTO `t_military_term_data` VALUES ('e301136a-2778-4897-9c08-756d261ca257', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵对能观察目标射击', '炮兵对能从地面或空中目视或利用仪器、器材观察并能进行射击修正的目标实施的射击。', 169);
INSERT INTO `t_military_term_data` VALUES ('e3029ad0-63dc-412e-a4e8-15ad90e4d47d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '先发制人', '先敌发起进攻以求将其制服。', 240);
INSERT INTO `t_military_term_data` VALUES ('e3131b55-f362-4295-9250-c67e4201ce51', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军兵种比例', '各军种、兵种人数在军队总人数中所占的比例或各军种之间、各兵种之间人数的比例。', 95);
INSERT INTO `t_military_term_data` VALUES ('e314a810-c6af-415f-ac0d-aad668c1dcc3', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮光电火控系统', '主要使用光电装置探测跟踪空中目标的高射炮火控系统。由光学瞄准镜,激光测距机,红外或电视跟踪装置，火控计算机和高炮随动装置等组成。', 49);
INSERT INTO `t_military_term_data` VALUES ('e318033b-8899-46ed-bb08-4a65eee5a161', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '战斗工事', '供部队射击、观察和机动的各种工事的统称。', 41);
INSERT INTO `t_military_term_data` VALUES ('e3286bb9-7870-4c41-9595-c4ed066585be', '8a761efd-50a6-4ac8-9913-b7d745104f82', '待机射击', '直瞄武器将瞄准线指向目标运动前方的一点，待目标运动到所需提前量时进行的射击。是只有简易瞄准装置的直瞄武器对运动目标的常用射击方法。', 96);
INSERT INTO `t_military_term_data` VALUES ('e3340f54-0f30-4bbe-a83f-1bd6edf886be', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '规避战术', '直升机在机动飞行中躲避敌空中和地面、水面火力打击的方法。', 74);
INSERT INTO `t_military_term_data` VALUES ('e337bfd2-66aa-4c12-ac86-fab939a77f8c', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '简编', '建制单位、人员或武器装备的数量少于正常编制的一种编制。', 72);
INSERT INTO `t_military_term_data` VALUES ('e33981f8-2818-403a-8d06-9fd101c03e70', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核爆炸热激波效应', '核爆炸产生的X射线被靶目标（如导弹彩表层材料吸收,形成局部高温、高压区所产生的冲击波对靶材的破坏作用。可破坏来袭导弹。', 168);
INSERT INTO `t_military_term_data` VALUES ('e3530a21-1db5-4953-bc1c-18af01a2a6e8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火封锁', '炮兵为限制敌人的行动或切断敌人之间的联系,对某一地区或目标实施定时或不定时射击的作战行动。', 74);
INSERT INTO `t_military_term_data` VALUES ('e3538393-77f9-405c-ba7c-013740fb4a4c', '0', '政治工作', NULL, 18);
INSERT INTO `t_military_term_data` VALUES ('e35e4a0f-b01c-422f-b84b-676d035797b2', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '翼侧突击', '向敌人作战部署或行军队形的翼侧实施的突击。分为一翼突击和两翼突击。', 98);
INSERT INTO `t_military_term_data` VALUES ('e3620c86-ed24-49e2-bba0-5ce46eeaf841', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术', '进行战斗的方法。包括战斗基本原则以及兵力部署、战斗指挥、协同动作、战斗行动的方法和各种保障措施等内容。', 21);
INSERT INTO `t_military_term_data` VALUES ('e36a809f-5a2e-4ce9-af7f-7de48ea23afb', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '桥梁分解', '将军用桥梁分解、构件撤离桥轴线的行动。依据情况可采取全部分解或局部分解。', 292);
INSERT INTO `t_military_term_data` VALUES ('e380becd-059e-42c8-aad9-8294d1e0aeaa', '31f4a446-5b98-4873-9d53-310d97125b07', '单个核突击', '用一枚核弹头对单个目标或目标群实施的突击。', 22);
INSERT INTO `t_military_term_data` VALUES ('e383eedc-8d8e-4e2d-a226-6b1d263ea35a', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '穿甲弹', '以弹丸的强度和动能穿透目标的装甲或摧毁坚固工程设施的炮弹。有同口径穿甲弹和次口径穿甲弹等。', 308);
INSERT INTO `t_military_term_data` VALUES ('e3896253-c4b8-4959-81da-830cb1b8e801', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击手段', '炮兵为完成射击任务而采取的各种措施的统称。主要包括：使用的炮种、弹种、引信、装药、弹道种类,确定火力分配、弹药消耗量、射击持续时间及发射法等。', 164);
INSERT INTO `t_military_term_data` VALUES ('e3965d00-1452-4e3a-bb8b-76d02bab30c5', '0', '组织指挥', NULL, 12);
INSERT INTO `t_military_term_data` VALUES ('e39b8573-f224-4b2a-bebe-18df607d55dc', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '阅兵', '首长对部队、院校进行检阅的仪式。包括阅兵式和分列式。通常在重大节日、迎送国宾或军队出征、凯旋、校阅、授旗、授奖、演习、院校学员毕业典礼时举行。', 66);
INSERT INTO `t_military_term_data` VALUES ('e39e9a3c-12df-4ebc-8f94-0b9f8fd77999', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机最大载重量', '在一定条件下直升机所能允许装载的人员、武器装备、物资的最大总重量。', 11);
INSERT INTO `t_military_term_data` VALUES ('e3a771db-09db-4982-8954-b41f8b052d3e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '主动权', '军队在作战中对敌所具有的自主行动能力。掌握主动权是克敌制胜的关键。', 270);
INSERT INTO `t_military_term_data` VALUES ('e3b0e187-c600-4af4-8e19-e73d230bff77', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '统计实力', '一定时限内军队或军队的某一组织实际拥有的建制单位、人员、武器装备等的数量与质量。', 84);
INSERT INTO `t_military_term_data` VALUES ('e3bb3cb1-d357-4593-a16a-631742ce88c6', 'f0140091-c11a-48c9-8836-8aa94439dac0', '阵地编成', '防御战斗中将各种阵地组成有机的整体。根据敌情、地形和防守部队的兵力编成及其任务的不同,防御阵地的编成也不同。如师的防御阵地,通常由警戒阵地、第一阵地、第二阵地、第三阵地、斜切阵地、反坦克阵地、反空降阵地、炮兵阵地、防空兵阵地、诸预备队配置地域和指挥所以及后方配置地域等编成。', 218);
INSERT INTO `t_military_term_data` VALUES ('e3d23246-3b82-4ec7-9d7f-51f08d79608d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '出奇制胜', '用非常规的和出敌不意的战法制服敌人,夺取胜利。', 244);
INSERT INTO `t_military_term_data` VALUES ('e3d728d2-39bb-4196-bf6b-627d55872e34', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '军用工程机械场', '简称机械场。停放、维护和保养军用工程机械的场所。分为永久性机械场和临时性机械场。野战条件下设置的临时性机械场称为野战机械场。', 378);
INSERT INTO `t_military_term_data` VALUES ('e3fc974d-25a1-4bdf-9870-881b3048822f', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗兵专业训练', '电子对抗兵进行的以电子对抗专业理论知识和作战技能为主要内容的专业训练。包括电子对抗专业技术训练和电子对抗战术训练。', 11);
INSERT INTO `t_military_term_data` VALUES ('e40d8c6f-fad0-4a11-8627-6eeae5fb811f', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场调整哨', '指引和调整人员、车辆及技术兵器按规定前往和离开渡口的岗哨。通常设在渡口两岸和渡河检查站通往渡口的道路交叉点。', 318);
INSERT INTO `t_military_term_data` VALUES ('e4111da4-a972-4c6c-892b-75e3874d5841', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '地下化建设', '供战时转入地下生活、生产和战斗使用而进行的地下工程建设。如修建坑道、地道、地下指挥所、地下工厂、地下医院、地下仓库等。', 67);
INSERT INTO `t_military_term_data` VALUES ('e4173844-8fed-4217-9f9b-9482e0fcb226', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战役训练指导法', '用以统一、规范战役训练的组织与实施的指导性文件。主要内容包括：战役训练的基本原则与要求,组织战役训练的形式、程序和方法,实施战役训练的手段与保障等。', 19);
INSERT INTO `t_military_term_data` VALUES ('e41b44b0-30a5-416c-8d04-b5791a09701d', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '对外正面', '围歼敌军时,担负阻援任务的部队面向援敌方向的一面。', 52);
INSERT INTO `t_military_term_data` VALUES ('e4205b01-e182-4771-80e9-c479df82fc80', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '硐室爆破', '亦称大爆破。把大量装药置于岩体内专门开挖的药室或巷道内进行的爆破。一般用于大规模土石方工程作业。', 241);
INSERT INTO `t_military_term_data` VALUES ('e42bea01-9ab6-4e31-ba6e-98e0582967a8', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '交会法', '根据已知点的位置测定未知点位置的方法。分为前方交会法、后方交会法和侧方交会法等。', 156);
INSERT INTO `t_military_term_data` VALUES ('e431d33a-5615-4202-9896-362629367a8d', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗装备', '专门用于电子对抗侦察和电子干扰的电子装备（系统）和制式器材的统称。按用途,分为电子对抗侦察装备和电子干扰装备；按工作平台,分为地面式、机载式、舰载式、弹载式和星（卫星）载式等电子对抗装备。', 108);
INSERT INTO `t_military_term_data` VALUES ('e44119c8-7e5a-4131-91e0-8a5a66285ef0', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '海洋', '地球表面包围大陆的连续水域。面积约占地球表面总面积的71％。通常包括由海水水体及其溶解或悬浮于其中的物质及生活于其中的生物、邻近海面的大气、海岸和海底地貌等。', 5);
INSERT INTO `t_military_term_data` VALUES ('e4412af5-af30-480b-882c-79e827fd418f', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '伴随修理', '修理分队及人员跟随部队或分队,对其损坏的武器装备随时随地进行的修理。', 125);
INSERT INTO `t_military_term_data` VALUES ('e448064f-5dde-4f64-8725-d0eab88827d2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '敌变我变', '随着敌情变化,及时调整己方部署、战法和行动。', 246);
INSERT INTO `t_military_term_data` VALUES ('e44c4a5a-5b46-4487-ac72-f6b0060fc132', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '国际机场', '亦称国际航空港。以国际航线为主要运营宗旨的大型民用机场。可起降大中型喷气式客机,供国际中远程航线使用。', 112);
INSERT INTO `t_military_term_data` VALUES ('e44c5944-4b3e-41aa-a75a-94fe285f6466', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '机断行事', '因情况突变不宜执行原定计划目来不及请不或联络中断不能请示时,指挥员根据上级总的意图和当时实际情况所作的灵活果断的处置。', 37);
INSERT INTO `t_military_term_data` VALUES ('e4516260-361c-4e8e-8629-92bcd842f580', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防光学伪装', '为降低敌光学侦察仪器的发现概率和制导武器的命中概率而实施的伪装。主要包括；利用地形配置目标,设置遮障和假目标,施放烟幕,实施迷彩和管制灯火等。', 340);
INSERT INTO `t_military_term_data` VALUES ('e454f8c8-2a1f-4267-95c2-81c01cbcac60', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '紧追权', '沿海国的军舰、军用飞机或其他有清楚标志可以识别的为政府服务并经授权的船舶或飞机,对在其内水、群岛水域、领海、毗连区内违反该国法律、规章的他国船舶,从上述水域开始,连续不断地追逐至领海、毗连区以外海域的权利。紧追权在被追逐的船舶进入其本国领海或第三国领海时即行终止。在专属经济区和大陆架上,对违反沿海国适用专属经济区和大陆架的法律和规章的行为的船舶,沿海国也可比照使用此项权利。', 376);
INSERT INTO `t_military_term_data` VALUES ('e458de23-365f-4779-a041-fafca9604000', '916997ee-6728-4c61-9b79-d96960b1dc86', '核爆炸监测', '探测核爆炸信息,预测和评估核袭击毁伤效应的核监测。包括核爆炸探测和核估算。', 85);
INSERT INTO `t_military_term_data` VALUES ('e470f19f-130f-4970-b47d-74fb9a3ecd5b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '侦察卫星', '装有光电遥感器、雷达或无线电接收机等侦察设备,用以获取军事信息的人造地球卫星。包括电子侦察卫星、照相侦察卫星、海洋监视卫星、预警卫星和核爆炸探测卫星等。', 206);
INSERT INTO `t_military_term_data` VALUES ('e4719648-7f78-42c7-bdfb-49364c9eff3b', '878651de-adf5-4c72-9376-9c363b893ff8', '战略突袭', '对敌实施的出其不意的战略性攻击。多用于战争发起时,也用于战争过程中。', 114);
INSERT INTO `t_military_term_data` VALUES ('e4933c6f-61b9-443c-8b37-3e6cf4f39f3e', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '雪暴', '亦称暴风雪。大量的雪被强风吹卷致使水平能见度降至1千米以下的天气现象。出现雪暴时常伴有强降雪和剧烈降温。', 29);
INSERT INTO `t_military_term_data` VALUES ('e4991d42-7e7e-432b-abf5-508f73e6582b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹常规战斗部', '装有高能炸药的导弹战斗部。主要有杀伤战斗部、爆破战斗部、聚能战斗部、穿甲战斗部等。', 22);
INSERT INTO `t_military_term_data` VALUES ('e4a226e6-68e8-42de-b8ad-92e1d71e53ef', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达反干扰', '为降低或消除敌方雷达干扰对己方雷达使用效能的影响而采取的战术技术措施。主要有；战术上合理部署雷达,提高雷达网的反干扰能力；技术上展宽雷达工作频段、快速跳频、增大发射功率,降低天线副瓣,加装反干扰电路和提高操作人员技术水平等。', 100);
INSERT INTO `t_military_term_data` VALUES ('e4ab4a06-27a6-4ec2-bca3-42c5f83df5a5', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '敌情通报', '向所属部队和友邻告知有关敌情的通报。通报的对象和范围,视情报的内容、性质、重要程度、机密程度和使用对象的任务与需要而定。', 150);
INSERT INTO `t_military_term_data` VALUES ('e4c8662b-08e4-464e-8e6f-e3e54533f08e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '游动坦克', '担负游动射击任务的坦克。应预先规定游动地区、路线、发射阵地、射击任务、时机和弹药消耗量。', 38);
INSERT INTO `t_military_term_data` VALUES ('e4dccb74-792c-4a1a-9bb2-df7d1a22df29', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '超越作战', '部队超越当面敌人或己方战斗队形的作战行动。如利用敌人的间隙或暴露翼侧进入敌后的作战行动；追击作战时,超越或绕过敌掩护部队,在退却之敌前面截断其退路的作战行动；第二梯队超越第一梯队的作战行动等。', 185);
INSERT INTO `t_military_term_data` VALUES ('e4de4c48-17ba-4e94-811a-d2017922c709', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '预先布雷', '战前根据障碍物设置计划实施的布雷。要求隐蔽、严密伪装,并按规定设置标志。', 180);
INSERT INTO `t_military_term_data` VALUES ('e4f24ab7-0f46-477b-baad-643b17584eaf', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击毁伤幅员', '亦称有效杀伤幅员。炮兵射击时单发炮弹的毁伤范围。炮兵进行射击理论计算时使用。', 221);
INSERT INTO `t_military_term_data` VALUES ('e4f5507a-0b59-462e-90d7-c8de70ad119d', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '列编', '军队将其编制以外的单位、人员或武器装备列人编制序列。', 70);
INSERT INTO `t_military_term_data` VALUES ('e5002270-8504-41d7-8f65-36c985fda797', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海岸声纳站', '亦称水声站。海军设在海岸担负对水下目标探测、警戒任务的专业勤务分队。通常隶属于观通营。装备有声纳和水声识别器等技术器材。', 18);
INSERT INTO `t_military_term_data` VALUES ('e504ce1f-894b-4594-a38e-c73283af42e1', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反潜水雷', '布设在水中不同深度上用以毁伤潜艇的水雷。', 221);
INSERT INTO `t_military_term_data` VALUES ('e510c5b4-5c4c-43dd-9788-8b1c49ab7c28', 'f0140091-c11a-48c9-8836-8aa94439dac0', '登陆', '登陆部队搭乘海上输送工具,通过航渡在敌岸上陆的作战行动。', 134);
INSERT INTO `t_military_term_data` VALUES ('e514daa7-5b96-4f79-9070-8d1bb07cf841', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '子午线', '子午面与地球表面的交线。天文子午面与地球表面的交线称为该地的经线,是准确的南北方向线和量度方位角的起始线。', 201);
INSERT INTO `t_military_term_data` VALUES ('e520a33f-3660-42f5-ad7f-b792268d7472', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '兵员', '①军队中的兵、军士和士官的统称。②泛指军队的干部和士兵。', 112);
INSERT INTO `t_military_term_data` VALUES ('e53a77d6-af68-4d20-9c92-7a868e85bc05', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战详报', '一个作战阶段或整个作战结束后向上级反映详细情况的作战报告内容通常包括敌我态势,敌方企图,乙方任务,决心部署和作战经过,战果伤亡、损耗以及经验教训等,并附以必要的图表。', 136);
INSERT INTO `t_military_term_data` VALUES ('e542a848-8dad-4240-b2ed-b3e80897181a', '31f4a446-5b98-4873-9d53-310d97125b07', '核爆炸次声波探测', '对核爆炸产生的次声波进行的探测。主要用以确定核爆炸的时间、位置和当量等。', 173);
INSERT INTO `t_military_term_data` VALUES ('e54557ab-dc6e-4d80-909c-dfc18c305bf2', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '露营', '部队在房舍外的宿营。通常在无房舍或不便舍营时采用。可根据情况采取架设帐篷、搭棚或挖洞、挖窖等方式进行。', 94);
INSERT INTO `t_military_term_data` VALUES ('e54f1293-42f9-4c1f-a522-cc9f33aec59e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '底部排气榴弹', '弹丸尾部装有排气装置和喷气焰火剂的炮弹。与火箭增程弹相比,飞行阻力小,射击精度高,装填炸药多,杀伤破坏威力大。', 320);
INSERT INTO `t_military_term_data` VALUES ('e5566ede-b2b3-4b3d-a894-09e5da6bcc24', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '配属', '指挥员将其掌握的兵力兵器的一部分,临时调归所属某单位指挥与使用。', 324);
INSERT INTO `t_military_term_data` VALUES ('e5592488-9b19-4bec-bda1-12aa7249afd8', '916997ee-6728-4c61-9b79-d96960b1dc86', '消除核袭击后果', '遭敌核袭击后为减轻损失而采取的防护措施。主要包括：查明受损受染的范围程度和放射性烟云移动情况,组织灭火,抢救伤员,抢修受损装备和重要设施,对受染人员、装备进行洗消,对受染粮秣、饮水进行检验和卫生处理等。', 46);
INSERT INTO `t_military_term_data` VALUES ('e55b946e-07ae-4ca1-b6bd-2eea37481fd5', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防预算', '亦称军事预算。国家经法定程序批准的用于国防的年度经费开支计划。是国家预算的重要项目之一。', 34);
INSERT INTO `t_military_term_data` VALUES ('e59aedde-3179-4987-9afd-16b5f819e7a0', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射姿态', '导弹发射时其纵轴线相对于发射点所处大地水平面的状态。通常分为垂直、倾斜和水平三种发射姿态。导弹发射姿态的选择,取决于导弹的类型、战术技术性能和作战需要。弹道导弹一般采用垂直发射姿态。', 111);
INSERT INTO `t_military_term_data` VALUES ('e59bf0ae-2b41-4971-b1c5-17367b9a84f2', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战预测', '对作战行动的发展趋势及其前景进行的预计和推测。通常包括对作战进程、战场态势的演变敌可能使用的兵力兵器及其战法作战结果等问题进行的预测。', 74);
INSERT INTO `t_military_term_data` VALUES ('e5a85554-9ddd-4056-ad9f-955dcb140368', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗演习', '以电子对抗侦察、电子干扰与反电子侦察、反电子干扰为主要内容的军事演习。', 13);
INSERT INTO `t_military_term_data` VALUES ('e5d93050-654f-4076-af18-8669aa8e10ea', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '远地点', '航天器绕地球运行的椭圆轨道上距地心最远的一点。远地点与地球表面的距离称为远地点高度。', 232);
INSERT INTO `t_military_term_data` VALUES ('e5da6797-566f-416d-bb34-d76f7d0b5eec', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '护渔', '海军兵力为保护本国海上渔业生产安全和海洋水产资源不受侵犯而实施的巡逻警戒活动。护渔兵力主要使用轻型水面舰艇,必要时由海军航空兵给予支援。', 42);
INSERT INTO `t_military_term_data` VALUES ('e5dae97a-2aa5-4227-81e8-d3697cbfe3bb', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '对海警戒', '军队在地面或空中组织和实施的对海区情况的警戒。主要任务是搜索、发现和监视指定海区的水面与水下的目标及其活动情况,防范来自水面与水下之敌的突然袭击和侦察活动。', 3);
INSERT INTO `t_military_term_data` VALUES ('e5e27335-130f-477e-a201-c94344a91417', '878651de-adf5-4c72-9376-9c363b893ff8', '战略展开', '军队按战略计划完成战略部署的行动。主要包括：战略疏散,组织军队向战区机动和集结,占领预定的进攻或防御阵地,后方勤务及各种保障机构的开设等。', 100);
INSERT INTO `t_military_term_data` VALUES ('e5e5a05b-a26a-469b-874c-9d8c3af66478', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通线', '可实施运输的路线、“管线和航线的统称。分为陆地交通线、水域交通线和空中交通线。包括：铁路、公路、管道,内河航道、海上航线,空中航线。', 282);
INSERT INTO `t_military_term_data` VALUES ('e5e892ee-6793-4c75-8bb5-5f14fa20d218', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察兵专业基础训练', '为使侦察兵掌握侦察专业基础知识和基本技能而进行的训练。主要训练内容包括：侦察常识、外军知识、军兵种侦察知识、兵器常识,基础射击,游泳泅渡；军事地形学以及侦察兵和侦察组战术等。', 87);
INSERT INTO `t_military_term_data` VALUES ('e60d458f-26e7-4759-bbdc-13fcf7b23137', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役法', '进行战役的方法。主要包括战役基本原则以及战役部署、战役指挥、战役协同、战役行动的方法和战役保障等内容。', 13);
INSERT INTO `t_military_term_data` VALUES ('e636646c-84fd-48a8-b6dc-b4c23ebf89f9', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '基本比例尺地形图', '根据国家颁布的测量规范、图式和比例尺测绘或编制的地形图。中华人民共和国的基本比例尺地形图包括1:1万、1:2.5万、1:5万1:1O万、1:25万、1:5O万和1:100万比例尺地形图。', 258);
INSERT INTO `t_military_term_data` VALUES ('e63d85dc-c0e0-458e-9edb-8e2380733aca', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军备控制', '国家或国际上对军备发展状况的监控和限制活动。', 88);
INSERT INTO `t_military_term_data` VALUES ('e6455aeb-0910-4eac-a7d6-944a4ce6956e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军战役训练', '海军战役军团为掌握战役理论和战役行动的原则与方法而进行的训练。包括海军单独进行的战役训练和以海军为主体、其他军种参加的合同战役训练。', 312);
INSERT INTO `t_military_term_data` VALUES ('e64db8d9-0167-4e8a-8d47-f6e8ddcf9083', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '协同动作计划', '协调各军兵种、部队和分队作战行动的计划。是作战行动计划的组成部分。', 90);
INSERT INTO `t_military_term_data` VALUES ('e6583536-4aeb-4386-a6f8-950bba6b1262', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防立法', '亦称军事立法。国家立法机关及其授权的国家机关通过法定程序,制定、修改或废止国防法律规范的活动。是国家立法的重要组成部分。', 56);
INSERT INTO `t_military_term_data` VALUES ('e65abf68-ac43-4999-930e-78a27c200623', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军兵种战术', '海军单一兵种进行战斗的方法。有潜艇战术、水面舰艇战术、海军航空兵战术、海军岸防兵战术和海军陆战队战术等。', 50);
INSERT INTO `t_military_term_data` VALUES ('e6651dd9-158f-45e8-ac93-0ad251e3317c', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '坡度尺', '在地形图上量取地面坡度的图解尺度。使用时可根据图上两点间距离与等高线条数,在相应坡度尺底线与相应曲线间的纵线上比量,读出地面的坡度。', 157);
INSERT INTO `t_military_term_data` VALUES ('e67eaf22-06df-4874-bcbd-65c3107e4e4f', '878651de-adf5-4c72-9376-9c363b893ff8', '积极防御战略', '以战略上的后发制人和战役战斗上的先机制敌的思想筹划和指导战争全局的方略。通常表现为战略上的内线的持久的防御战与战役战斗上的外线的速决的进攻战相结合,并适时将战略防御转为战略反攻和进攻,夺取战争的最后胜利。', 55);
INSERT INTO `t_military_term_data` VALUES ('e6811fab-e69b-4a77-b987-4b95d1492667', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击准备', '炮兵为实施射击而进行的准备。主要包括；研究敌我情况和地形,决定基准射向,建立指挥机构,组织侦察、通信、测地、气象保障及弹道、技术准备,计划火力,决定射击诸元,拟制指挥文书等。', 133);
INSERT INTO `t_military_term_data` VALUES ('e68a70f7-7476-4d31-92ef-6d7294a398c8', '98df76fb-4b65-48ff-a56c-4db587327c79', '国家计划分配物资', '国家物资主管部门按计划分配的物资。主要包括国家指令性计划分配物资、国家合同订购物资和国家组织产需衔接物资。', 100);
INSERT INTO `t_military_term_data` VALUES ('e69a5597-e32b-48e4-a20c-d8b0c5fb1b2f', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤训练', '部队进行的以后勤知识和技能为内容的训练。通常按后勤组织指挥、专业勤务和专业技术等类分别组织实施,并在一定基础上组织综合演练。', 37);
INSERT INTO `t_military_term_data` VALUES ('e69b8201-25b3-4131-8ead-5e45e6ae8bec', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '避强击弱', '避开敌之主力或强点,打击敌之弱部或弱点。', 243);
INSERT INTO `t_military_term_data` VALUES ('e69f5161-8f5a-4851-89f4-b6d975c1b573', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '冻土', '温度在 O摄氏度以下,因冻结而含冰的岩土。分为多年冻土、隔年冻土和季节冻土等。冻土给土工作业造成困难。冻土热融时造成地表泥泞松软,使人员、车辆难以或无法通行。', 81);
INSERT INTO `t_military_term_data` VALUES ('e6b060b0-344f-4c0a-9f0b-8aa654b540e9', 'f0140091-c11a-48c9-8836-8aa94439dac0', '伏击战斗', '设伏的方式攻歼运动之敌的战斗。', 132);
INSERT INTO `t_military_term_data` VALUES ('e6b8dafd-abbe-49d2-88a6-f254900ba2cc', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '海湾', '海洋伸入陆地并具有独特水文性质的部分水域。通常以湾口附近两个对应海角的连线或以选定的等深线为海湾最外部的界线。某些海湾口部小,湾内水面宽广,风浪小,成为舰船的良好驻泊地。', 49);
INSERT INTO `t_military_term_data` VALUES ('e6cfd0f3-9ac3-4ae9-b7c3-5b90c140c607', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤成梯队部署', '将后勤力量区分为两部分,前后成阶梯式配置的后勤部署。通常为集团军以下后勤在作战纵深较大时采用。', 53);
INSERT INTO `t_military_term_data` VALUES ('e6d4965e-56ff-4494-bd1f-b8cf726fea1e', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '对空观察哨', '借助观察器材或用目力监视空中敌情的哨兵。通常由对空观察分队派出。', 32);
INSERT INTO `t_military_term_data` VALUES ('e6d9f1b1-8ffa-4c8a-a90e-c87e0f2fe928', '97a19170-bfac-42c5-9906-1acb187f0654', '防空战役', '空军战役军团单独或在其他防空力量协同下实施的抗击敌空袭的战役。分为要地防空战役、战区防空战役和多战区防空战役。', 33);
INSERT INTO `t_military_term_data` VALUES ('e6e1cde0-daad-4ea7-a6ce-e2fd7d1d5591', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '电视制导', '利用电视技术提供目标信息,形成制导指令进行的制导。分为可见光电视制导、红外电视制导、激光电视制导。', 51);
INSERT INTO `t_military_term_data` VALUES ('e6e682e8-f4b2-47f4-91c3-3cf2b7cf00ce', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '拦阻射击阻击点', '炮兵预先选定的用于拦击运动目标的射击点。通常根据射击任务和地形条件,在运动目标可能经过的能观察地区选定。若干个阻击点可组成阻击线。', 232);
INSERT INTO `t_military_term_data` VALUES ('e6e856c4-dfe2-4150-adda-8be40d842c78', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '卫戍区', '担负首都或其他重要地区的保卫、戍守任务的军队一级组织。中国人民解放军设北京卫戍区,隶属于北京军区,同时是中国共产党北京市委员会的军事工作部门和北京市政府的兵役工作机构,受北京军区和中共北京市委、北京市政府的双重领导。设有领导机关。辖有若干个区、县人民武装部和一定数量的卫戍部队。主要担负北京地区的军事警卫和守备任务,负责民兵、预备役、兵役和动员工作,维护军容风纪,施行军车交通安全检查,协助地方维护社会治安等。', 26);
INSERT INTO `t_military_term_data` VALUES ('e714a951-704b-4c1f-bdc2-63a35b7f5722', 'd7132c58-5df3-4b97-919f-58740148b9ca', '野战防空样式', '亦称掩护方式。防空兵野战中遂行对空掩护任务的方式。包括区域防空、目标防空和机动防空。各种样式可结合使用。', 66);
INSERT INTO `t_military_term_data` VALUES ('e729c8a5-f8c0-4ec6-a2e8-d00ce2473028', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '降水量', '一定时段内的液态或固态（经融化后）降水,未经蒸发、渗透、流失,在水平面上积聚的深度。计量单位为毫米。单位时间内的降水量称为降水强度,通常以毫米／时表示。', 26);
INSERT INTO `t_military_term_data` VALUES ('e729d6a0-3cb0-4f85-9a24-7c5c5307597f', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地图比例尺', '地图上某两点间直线长度与相应实地水平距离之比。通常以数字比例尺或直线比例尺标注在地图图廓外。是判定地表实地水平长度在地图上的缩小比例和根据图上量测长度计算实地水平距离的依据。如1:5万比例尺地形图,图上两点间长度为1厘米,相应实地水平距离为5万厘米,即500米。', 276);
INSERT INTO `t_military_term_data` VALUES ('e72cdc87-47ad-4fca-9e32-e91a029a7718', '98df76fb-4b65-48ff-a56c-4db587327c79', '后方防卫', '在后方地域内进行的防卫。主要包括：对后方机关及其他重要目标的警卫,组织后方对敌空袭和核、化学、生物武器的防护,组织军民联防,进行防间反特斗争等。', 63);
INSERT INTO `t_military_term_data` VALUES ('e7381ecc-8b6a-4819-99fb-6d7f54522ebb', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮射弹落角', '火炮射弹落点的弹道切线与炮口水平面所夹的锐角。', 252);
INSERT INTO `t_military_term_data` VALUES ('e74831f0-8c35-4fd8-8c7f-a207e4ede28e', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗信号环境', '在电子对抗系统工作时所处的战场空间内,由各种电磁辐射信号形成的特定的电磁环境、描述电子对抗信号环境的主要参数有辐射源数量、信号密度、信号频率范围、信号形式及其参数范围等。是研制电子对抗装备、开展电子对抗训练、组织电子对抗行动的基本依据。', 23);
INSERT INTO `t_military_term_data` VALUES ('e7680e4a-5315-45d2-a61b-caed24cfcde6', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹弹体', '用以安装连接导弹战斗部、仪器设备和动力装置的导弹壳体。其功能是使导弹有良好的气动力外形,并便于导弹储存、运输、维护和使用。', 30);
INSERT INTO `t_military_term_data` VALUES ('e7701462-d887-4f59-a7cc-0981ec5f0827', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克抢修', '在战斗过程中为使战伤、技术损坏的坦克尽快恢复战斗力而进行的现地修理。通常采取换件修理法,有时采取拆拼或应急修理法。', 216);
INSERT INTO `t_military_term_data` VALUES ('e771d87b-573f-42c5-a322-f07a8357327c', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵后勤保障', '防空兵为满足部队建设、作战和生活等需要而在后勤方面采取的各项保证性措施与进行的相应活动的统称。主要包括：武器、仪器、器材、弹药、车辆、油料、给养等物资的供应,交通运输的组织与实施,伤病人员的救治、后送,卫生防疫和防护等。', 96);
INSERT INTO `t_military_term_data` VALUES ('e77263d3-6259-47d9-a0b9-63cdcc317e7d', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战术训练', '对单个士兵进行的以战斗动作、战斗方法为主要内容的训练。', 83);
INSERT INTO `t_military_term_data` VALUES ('e77fdf5a-69f7-42a6-a843-761cb1aa6dca', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事干涉', '亦称武装干涉。以军事手段强行介人别国事务的行为。', 62);
INSERT INTO `t_military_term_data` VALUES ('e7821929-8205-4edc-addf-ccd20379e0b6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰载歼击机', '亦称舰载战斗机。以航空母舰为基地,主要用于海洋上空战斗并兼有对水面和岸上目标攻击能力的舰载飞机。分为常现起落舰载歼击机和平直、短距起落舰载歼击机。通常装备有航炮、空空导弹等。', 176);
INSERT INTO `t_military_term_data` VALUES ('e7a01cd1-877b-4d9f-8baa-719c833e893d', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达对抗', '为削弱、破坏敌方雷达使用效能,保护己方雷达正常发挥效能而采取的各种措施和行动的统称。基本内容包括雷达对抗侦察、雷达干扰和雷达电子防御等。', 1);
INSERT INTO `t_military_term_data` VALUES ('e7ab61bd-4dab-48b7-b45c-ac01611ecff1', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队影视工作', '中国人民解放军中进行的电影、电视剧的创作生产和发行放映、技术管理、宣传评论等项工作的统称。', 115);
INSERT INTO `t_military_term_data` VALUES ('e7ac9212-467b-4d1c-bd5c-03c7d15a0e44', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇中队', '由若干艘同型舰艇或若干个舰艇分队编成的海军营一级组织。通常隶属于舰艇大队。按其所辖舰种称谓,如登陆艇中队等。', 10);
INSERT INTO `t_military_term_data` VALUES ('e7b2503f-b276-4c1f-90ea-7e4e9e566773', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战场派遣', '部队在作战地区将有条件的人员秘密派往敌区或敌军内部进行侦察的方式。', 35);
INSERT INTO `t_military_term_data` VALUES ('e7b38867-edc3-4aee-8b92-5ac8c37a1454', 'f0140091-c11a-48c9-8836-8aa94439dac0', '出发线', '为调整、控制部队某一行动而指定的起始线。分为行军出发线和冲击出发线等。', 69);
INSERT INTO `t_military_term_data` VALUES ('e7c619f5-787d-46f3-95ad-f486f7f0883d', '878651de-adf5-4c72-9376-9c363b893ff8', '战争规律', '战争运动过程中诸因素之间的本质联系及其发展的客观必然趋势。分为一般战争规律和特殊战争规律。正确认识战争规律是对战争实施正确指导的前提。', 32);
INSERT INTO `t_military_term_data` VALUES ('e7c7292f-98a9-4dba-a35f-350ee0103975', 'f0140091-c11a-48c9-8836-8aa94439dac0', '伏击阵地', '用以伏击敌人的阵地。通常在伏击地区内预先构筑或占领,也可在战斗中相机构筑或占领。', 227);
INSERT INTO `t_military_term_data` VALUES ('e7cbdb69-5f4d-466e-9461-b87fce2a14f6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '法定时', '国家法律规定使用的时间。由于政治、经济等原因,一些国家用法律规定该国或地区使用的区时提前1小时或几小时。中华人民共和国规定以北京时间作为标准时,也属法定时。', 212);
INSERT INTO `t_military_term_data` VALUES ('e7cd24a6-ce97-4ab4-978c-347835e712a2', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '简易测绘', '用简便器材和简易方法测绘略图和要图的作业。通常在侦察敌情、地形、调查行军路线时使用。', 151);
INSERT INTO `t_military_term_data` VALUES ('e7d2778a-62cc-4008-9fe7-02b826e0fbf7', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器杀伤力', '弹丸或弹丸的破片对生动目标致死致伤的能力。通常以78焦动能的弹丸击中人的要害部位为致命标准,也有的以150焦／平方厘米的比动能为致命标准。其大小主要取决于弹丸的动能、弹丸的几何形状、穿入时的飞行姿态等因素。', 216);
INSERT INTO `t_military_term_data` VALUES ('e7d77a52-9b8a-4014-a478-f5348b3423f2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '连续作战', '军队在一定时间内不经休整接连遂行若干次战役、战斗任务的作战。', 197);
INSERT INTO `t_military_term_data` VALUES ('e7d8e105-8ca0-4fcb-b855-c0fa6c13fcb0', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '后勤军官', '军队中从事后勤工作的军官。包括从事后勤组织指挥、财务、军需、卫生、营房、运输、油料等工作的军官。', 106);
INSERT INTO `t_military_term_data` VALUES ('e7dd5a5a-04cd-4e21-a356-8a7d2e224019', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '汉字信息处理', '利用计算机对汉字信息进行输入、输出和加工处理的技术。军事上广泛应用于作战、训练以及机关文字工作和情报资料管理等。', 60);
INSERT INTO `t_military_term_data` VALUES ('e7e0b791-7a35-4984-9c08-81b86ad9bdce', '31f4a446-5b98-4873-9d53-310d97125b07', '对接导弹', '将多级导弹的弹体按要求逐级对准连接的过程。分为水平状态对接和垂直状态对接。是多级导弹技术准备中的一项重要工作。', 84);
INSERT INTO `t_military_term_data` VALUES ('e7e33d5d-cf74-42c7-aa44-87eaad788981', '916997ee-6728-4c61-9b79-d96960b1dc86', '安全剂量', '亦称允许剂量。对无防护人员不会引起可见中毒症状的最大允许毒剂量。', 137);
INSERT INTO `t_military_term_data` VALUES ('e7e3bf63-5d70-47e9-8f3a-f3d8eab86a0a', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '龙伯透镜反射器', '在龙伯透镜的局部表面上镀上金属反射层而构成的反射装置。可在大的入角范围内,将入的电磁波能量聚集反射回去。在电子对抗中,主要用以产生假目标以欺骗雷达。', 137);
INSERT INTO `t_military_term_data` VALUES ('e7e5968c-cea7-4e67-bc2c-a04fdce024c7', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '过境通行权', '在公海或专属经济区的一部分和公海或专属经济区的另一部分之间的用于国际航行的海峡,各国船舶和飞机享有的,为继续不停和迅速过境的目的而行使航行与飞越的权利。行使过境通行权不能对海峡沿岸国进行任何武力威胁或使用武力,应遵守有关的国际规章、制度和惯例。海峡沿岸国有权制定有关过境通行的法律和规章。', 372);
INSERT INTO `t_military_term_data` VALUES ('e7eeaba6-1f67-4e3c-81d2-85c635d1f711', 'f0140091-c11a-48c9-8836-8aa94439dac0', '侧射火力', '射击方向指向目标翼侧的火力。', 85);
INSERT INTO `t_military_term_data` VALUES ('e7ef36d6-3822-4956-898b-0a285561e28d', '8a761efd-50a6-4ac8-9913-b7d745104f82', '战斗射速', '亦称实际射速。轻武器、火炮以其典型操作程序及射击方式在每分钟内能发射的平均弹数。其值取决于理论射速、瞄准速度、容弹具容量、容弹具更换时间、转移射向速度以及射击方式等。', 51);
INSERT INTO `t_military_term_data` VALUES ('e7fadbc5-16c8-4948-ab6f-42e38162052a', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '紧急警报', '出现紧急或危险情况时发出的警报。以使有关单位和人员立即采取相应的行动和措施。', 37);
INSERT INTO `t_military_term_data` VALUES ('e80004d8-a209-4dde-b403-e2cc0807d559', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '水平遮障', '架空设置于目标上方，遮障而与地面平行的人工遮障。', 345);
INSERT INTO `t_military_term_data` VALUES ('e81c0c4e-f5e7-4049-bb90-bc794273fa00', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学监测', '为查明目标的染毒时间、染毒程度及其变化而实施的监测。包括染毒区再生云监测和毒害剂量监测。', 114);
INSERT INTO `t_military_term_data` VALUES ('e81e06fc-fddc-4516-949f-2df05ff02016', '31f4a446-5b98-4873-9d53-310d97125b07', '占领导弹发射阵地', '导弹发射分队进入发射阵地并展开成战斗队形的行动。可由待机地域进入发射阵地,也可在机动中直接占领发射阵地。主要工作是按规定的时间、道路和顺序进入发射阵地,并按规定的位置和要求展开地面设备,为发射导弹做好准备。', 108);
INSERT INTO `t_military_term_data` VALUES ('e8239efd-f8a7-4f31-88c0-b80462a88161', '8a761efd-50a6-4ac8-9913-b7d745104f82', '终点', '射弹落点与弹着点的统称。', 31);
INSERT INTO `t_military_term_data` VALUES ('e8246839-106d-490a-96e3-9cee298ab270', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术穿插', '兵团或部队、分队从敌部署的间隙或在敌防御部署的薄弱部位打开缺口,插入敌方战术纵深的作战行动。', 33);
INSERT INTO `t_military_term_data` VALUES ('e82d89fe-af5d-48a0-a7e2-73765990f7bc', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '驻止之敌', '处于停留或驻扎状态的敌军。包括临时驻止之敌和长期驻止之敌。', 237);
INSERT INTO `t_military_term_data` VALUES ('e859324b-5004-449b-8930-5f56060de50b', 'd7132c58-5df3-4b97-919f-58740148b9ca', '近方空中情报', '由防空兵部队统一组织的雷达侦察网通报的,范围在200公里内的空中情报。', 110);
INSERT INTO `t_military_term_data` VALUES ('e85ad490-d4f7-41f8-9ffd-1c2555deb4ba', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '驱逐', '将敌从其占据的地方驱赶出去的军事行动。', 368);
INSERT INTO `t_military_term_data` VALUES ('e86044f9-c6b0-4c6b-823f-189f2f5800cf', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '落点预示', '根据火箭的瞬时弹道参数,推算出在该瞬间终止动力飞行后火箭的坠落地点并加以显示。是判断火箭实时飞行状态的主要依据之一。预示落点可在显示屏幕上以数字或图像形式显示出来,或用打印机、电传机以数字形式输出。', 286);
INSERT INTO `t_military_term_data` VALUES ('e86a7a61-416d-4f8c-a5cd-c749ff647fdd', '98df76fb-4b65-48ff-a56c-4db587327c79', '车公里', '每辆车行驶 1公里。是车辆行驶里程的计量单位。', 321);
INSERT INTO `t_military_term_data` VALUES ('e87df556-2766-4678-af77-8890b01bf00a', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '季风气候', '季风盛行地区的气候。东亚季风气候区四季分明,夏季湿热,冬季干冷，冬夏温差大,春、秋为过渡季节。南亚季风气候区雨季和旱季十分显著,两季的降水量对比大,而气温差异不大。', 61);
INSERT INTO `t_military_term_data` VALUES ('e87ece5b-b9c6-4fba-a1bb-13ef70ba12f5', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '军用运输直升机', '专门用以运载武器装备、人员和物资的军用直升机。', 8);
INSERT INTO `t_military_term_data` VALUES ('e880797a-091a-43f9-8e3b-866f0809aaef', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核炸弹', '亦称核航弹。装有核战斗部的炸弹。由战略轰炸机携带的核炸弹,威力一般为几十万至几百万吨梯恩梯当量；由战术轰炸机或歼轰机、强击机携带的核炸弹,威力一般为几千至几十万吨梯恩梯当量。', 107);
INSERT INTO `t_military_term_data` VALUES ('e8823cc0-b1b6-4372-bd64-721c1809dede', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '超导技术', '研究物质在超导状态下的性能及其应用的技术。某些物质（如金属、陶瓷和有机材料）在一定的温度条件下电阻会完全消失,这种现象称为超导电性,简称超导。利用超导技术可制成超导储能装置、超导电机和电磁推进装置,还可制成功耗低、灵敏度高、反应速度快的超导电子器件，在军事上有厂泛的应用前景。', 33);
INSERT INTO `t_military_term_data` VALUES ('e88c4711-f692-45c0-89ef-b2431cbc229f', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '军事仿生技术', '从军事角度研究、模仿生物的结构和功能原理,创制或改进武器装备的技术。主要包括信息仿生技术、控制仿生技术、力学仿生技术、化学仿生技术等。在军事上有广阔的发展前景。', 15);
INSERT INTO `t_military_term_data` VALUES ('e8912033-ad36-4ec4-ac10-dc3e4b70c910', '97a19170-bfac-42c5-9906-1acb187f0654', '滑翔机', '无动力装置或仅有供起飞用的小型辅助动力装置,主要靠机翼产生气动升力升空的航空器。通常借助民机、汽车、绞盘车等牵引或依靠自身的辅助动力装置起飞。主要用于体育运动和飞行训练,也可用于空降和空中运输。', 262);
INSERT INTO `t_military_term_data` VALUES ('e89ede17-f885-4a30-b0f1-300624b2a26b', '916997ee-6728-4c61-9b79-d96960b1dc86', '化学估算', '对化学袭击杀伤效应的概略计算。包括化学袭击区杀伤效应估算和化学袭击下风区危害估算。', 49);
INSERT INTO `t_military_term_data` VALUES ('e8a15333-0ee4-46c9-b92d-306c6269b6a1', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '军用物资', '专供武装力量使用和消费的各种物资的统称。主要包括装备器材、军需物资、医疗物资、油料物资、营房物资等。', 46);
INSERT INTO `t_military_term_data` VALUES ('e8a24520-5fb8-4050-bffe-136dd5a54b2d', '06a75831-13a1-4660-870a-455bb445336a', '升空平台通信', '以飞机、飞艇、系留气球为载体,将通信设备升至空中进行的无线电通信。可实施空中转信、通播,也可在通信飞机上开设小型空中通信枢纽。通信覆盖面积大,通信距离远,适于在部队高度机动、地形复杂等情况下使用。', 115);
INSERT INTO `t_military_term_data` VALUES ('e8a573b9-e294-4f26-baa7-63d8dc0fd505', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲兵战术', '亦称坦克兵战术。装甲兵进行战斗的方法。主要包括装甲兵战斗基本原则、战斗部署、战斗指挥、协同动作、战斗行动的方法和各种保障措施等。', 6);
INSERT INTO `t_military_term_data` VALUES ('e8a6a332-fb50-476a-8a28-5477b87713ad', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役持续时间', '战役从开始到结束的时间。其长短主要取决于敌对双方战役力量对比、战役规模、战役指导和战役保障等因素。', 37);
INSERT INTO `t_military_term_data` VALUES ('e8aab57b-f2ef-4290-8271-2d14df0e64e4', '878651de-adf5-4c72-9376-9c363b893ff8', '正规战争', '正规军队进行的以运动战和阵地战为主要作战形式的战争。相对于游击战争而言。具有高度集中的指挥、严密的组织计划、密切的协同动作、统一的后方供应等特征。', 18);
INSERT INTO `t_military_term_data` VALUES ('e8ae1115-b5a5-4467-bf22-75966c090421', '878651de-adf5-4c72-9376-9c363b893ff8', '战略阶段', '根据战争的形势、任务或特点,对战争的进程所划分的段落。有战前对战争的战略阶段进行预见性的划分,用以指导战争；也有战后根据战争的实际进程对其战略阶段所作的划分,用以研究战争。', 82);
INSERT INTO `t_military_term_data` VALUES ('e8b2a40d-9030-4228-b79d-1bbdfeda7d8f', '8a761efd-50a6-4ac8-9913-b7d745104f82', '射面', '包含射线的铅垂面。', 23);
INSERT INTO `t_military_term_data` VALUES ('e8bfbbc5-9eec-4a2c-a173-ed5b1c02ea9c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇惯性', '舰艇所具有的在推进器停车或紧急倒车时继续向前运动的性能。是舰艇战术技术性能要素之一。通常以停船冲程或停船时间表示。', 332);
INSERT INTO `t_military_term_data` VALUES ('e8bfcd19-8887-484f-ace1-2d6a1af40394', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战思想', '关于作战问题的理性认识。通常表现为作战的指导理论与基本原则。', 111);
INSERT INTO `t_military_term_data` VALUES ('e8ca9298-6861-4523-a2f0-5a5fafa7bd4e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舱室', '舰艇上各种包蔽空间的统称。在主船体内,  由纵、横舱壁和其他构件分割成的空间一般称舱；在上层建筑内,由围壁和其他构件分割成的空间一般称室。', 163);
INSERT INTO `t_military_term_data` VALUES ('e8d10e84-cee6-46bb-a04a-c482926eef8f', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '敌进我进', '当敌进攻时,避开敌之主力和正面,向敌侧后进击。', 245);
INSERT INTO `t_military_term_data` VALUES ('e8d518e1-61be-4aab-9f6c-29e712c75917', '31f4a446-5b98-4873-9d53-310d97125b07', '核打击目标系统', '按一定规则排序的核打击目标的体系。主要包括：由同一种类的各单个目标组成的单项目标系统（如石油目标系统、钢铁目标系统等）,由同一性质各单项目标系统组成的更大的目标系统（如经济目标系统、军事目标系统、交通目标系统等）。', 158);
INSERT INTO `t_military_term_data` VALUES ('e8dd97af-1e70-4a61-8575-7993fde2ce19', 'f0140091-c11a-48c9-8836-8aa94439dac0', '集合', '分散的人员或部队、分队按指定的地点和要求的队形进行的聚集行动。', 108);
INSERT INTO `t_military_term_data` VALUES ('e8e1b34d-e3e7-48c6-a51e-23dfb42dad91', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵测地器材', '炮兵用以连测战斗队形和测定炮兵控制点坐标的器材。包括方向盘、经纬仪、电磁波测距仪、测地计算器、炮兵测地车、自动定位系统等。', 284);
INSERT INTO `t_military_term_data` VALUES ('e8e51033-cef2-48b0-8b9e-0d703ae3d82b', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '频率捷变雷达', '发射脉冲的载频能在一定频带范围内快速跳变的脉冲雷达。有随机、程序控制和自适应等几种频率捷变方式。反侦察和反干扰能力强,探测距离较远,测角精度和对目标的分辨能力较强,能抑制海浪杂波干扰。其工作原理为多数军用雷达所采用,用以提高电子对抗能力。', 93);
INSERT INTO `t_military_term_data` VALUES ('e8e7dcd5-2e34-4ad4-becc-4ffa61d4e9c6', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '背敌行军', '背向敌方的行军。须加强后方警戒并注意防敌昆追。', 50);
INSERT INTO `t_military_term_data` VALUES ('e8eec0aa-c9c6-4d15-a3ac-a0707e98e36b', '916997ee-6728-4c61-9b79-d96960b1dc86', '放射病', '机体受到过量的核辐射射线照射造成的病症。分为急性放射病和慢性放射病。急性放射病通常分为轻度、中度、重度、极重度4级。患轻度放射病后,数天内可能出现疲乏、头昏、恶心,两月内可自行恢复；患中度以上放射病会失去战斗力,甚至死亡。', 110);
INSERT INTO `t_military_term_data` VALUES ('e8fd1043-aa2d-4951-913b-4e61af8d94ee', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '特种警备部队', '简称特警部队。遂行特殊警卫、守备任务的部队。', 54);
INSERT INTO `t_military_term_data` VALUES ('e9177548-1b7d-457e-9492-03d3a9189bee', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '编队', '①舰船、飞机或车辆的兵力编组。②舰船、飞机或车辆在机动中编组队形的行动。', 313);
INSERT INTO `t_military_term_data` VALUES ('e91b25c9-4db2-4d7a-8ffb-ec09dc7782d4', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克行动装置', '坦克履带推进装置和悬挂装置的统称。用以支撑车体,实现坦克运动,并保障坦克平稳行驶和通过难行地面与障碍物等。', 128);
INSERT INTO `t_military_term_data` VALUES ('e94b572a-2fa0-410d-8ac6-be6ad78bba24', '06a75831-13a1-4660-870a-455bb445336a', '调频电台', '采用载波频率随调制信号变化的调制方式,发送、接收调频信号的无线电台。大多工作在超短波和微波波段。可传输电话、移频电报等。与调幅电台相比,抗干扰性能较好,广泛用于战术分队通信、也是装甲兵、炮兵的主要通信设备。', 184);
INSERT INTO `t_military_term_data` VALUES ('e960e1b4-b238-4923-84b3-f4aed5c745b4', '0', '行政管理 . 装备管理', NULL, 20);
INSERT INTO `t_military_term_data` VALUES ('e962416c-6744-467c-a2ee-52254b8cf2ea', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行事故万时率', '一个单位在一定期限内所有飞机的总计飞行时间中,平均每飞行1万小时所发生的严重飞行事故的次数。是衡量飞行安全状况的重要指标。', 252);
INSERT INTO `t_military_term_data` VALUES ('e9699f40-44cd-497e-8721-571024107865', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '地面警戒', '军队在地面组织和实施的警戒。包括对地警戒、对空警戒和对海警戒。任务是及时发现、防范和制止敌之突然袭击和侦察。', 1);
INSERT INTO `t_military_term_data` VALUES ('e97ba91b-3ac7-4936-a2ae-dc272ec76cb5', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边境禁区', '国家根据特殊管理需要,在边境地带的某些地段划定的严格禁止打猎、鸣枪、爆破、放牧、旅游等活动的区域。', 89);
INSERT INTO `t_military_term_data` VALUES ('e986df56-46ce-48be-9799-1a05391d392c', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '排哨', '担负宿营警戒任务并进入预定位置的建制排。通常由宿营的团、营或连哨派出。', 22);
INSERT INTO `t_military_term_data` VALUES ('e98cdef1-a44c-47d7-8993-db5cedb9652b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上警戒', '海军兵力为防止敌方的海上袭击和侦察而实施的警戒。按距离,分为远程警戒、近程警戒和直接警戒；按性质,分为战斗警戒、航行警戒和停泊警戒；按任务,分为海上对空警戒、对潜警戒、对水面舰艇警戒和综合警戒。', 57);
INSERT INTO `t_military_term_data` VALUES ('e99fe0d8-e427-4e33-a309-b3f6e07579e3', '0', '海军', NULL, 7);
INSERT INTO `t_military_term_data` VALUES ('e9aa62ff-9ef9-4bbc-9e6a-0bba71bfdd4b', 'f0140091-c11a-48c9-8836-8aa94439dac0', '渡江河进攻战斗', '对凭借江河实施防御之敌的进攻战斗。', 133);
INSERT INTO `t_military_term_data` VALUES ('e9aad331-19eb-46de-99a6-6a74b15d3473', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核潜艇', '用核动力推进的潜艇。按装载的武器,分为弹道导弹核潜艇、飞航导弹核潜艇和鱼雷核潜艇等。', 131);
INSERT INTO `t_military_term_data` VALUES ('e9ab8e15-bf37-476d-b312-cf9e9d5a0ee2', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰载机拦阻装置', '航空母舰上用以吸收着舰飞机的前冲能量,以缩短其滑跑距离的装置。通常由拦阻索、拦阻网和缓冲器、控制系统等构成。', 168);
INSERT INTO `t_military_term_data` VALUES ('e9ae2df0-be0d-4dca-8ed0-9716763c097a', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆最大航程', '具有浮渡能力的装甲车辆一次加足油料后,按规定条件在水上航行时的最大行程。一般为100～150公里。是确定车辆在水上作战时的活动半径、油料基数和加油时机的主要依据。', 173);
INSERT INTO `t_military_term_data` VALUES ('e9b7ba7a-8bff-4707-9266-192dfb352824', '8a761efd-50a6-4ac8-9913-b7d745104f82', '防暴专用装备', '专门用以执行防暴任务和维持社会治安的武器和器材的统称。一般不具有致命功能。如防暴枪、橡皮弹、催泪弹、警棍、防盾、装甲防暴车等。', 187);
INSERT INTO `t_military_term_data` VALUES ('e9bdbc51-0fc9-4950-bd16-4da454cf560c', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机空中突击', '武装直升机以机载武器从空中向地面、水面或水下目标进行急速而猛烈的攻击。分为集中突击、分散突击、连续突击和设伏突击等。', 59);
INSERT INTO `t_military_term_data` VALUES ('e9ddc7e4-8466-422b-a1cb-722ce1fc018d', '06a75831-13a1-4660-870a-455bb445336a', '对讲机', '亦称步谈机、手持机。能在行进中通话的小型无线电话机。主要用于营以下分队的近距离通信联络。体积小,重量轻,操作简单,携带方便。', 175);
INSERT INTO `t_military_term_data` VALUES ('e9df6b2c-261d-46b0-931e-f2101d5a44ec', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '遥控系统', '能对相隔一定距离的被控对象进行控制,并使其产生相应的控制效果的系统。由控制信号产生机构、传输设备、执行机构组成。广泛用于作战、侦察、训练、武器试验、发射人造卫星等方面。', 277);
INSERT INTO `t_military_term_data` VALUES ('e9e21eca-73df-4912-8ce0-378f2db73f7f', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防交通', '用于国防目的的交通、邮电的线路、设施及其管理机构的统称。', 59);
INSERT INTO `t_military_term_data` VALUES ('e9f359d3-cc85-4d6b-b1da-91e8f243eba1', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆出入水角', '具有浮渡能力的装甲车辆在规定的岸坡条件下,出水登陆和安全下水所能克服的最大坡道角。通常情况下,出水角为25度～30度,入水角为20度～25度。', 171);
INSERT INTO `t_military_term_data` VALUES ('e9fe77f9-348a-4641-a13e-e9df2f3d1b27', '878651de-adf5-4c72-9376-9c363b893ff8', '战略突破', '对敌战略防线打开缺口的作战行动。用以破坏敌战略防御体系,并为尔后向敌战略纵深发展进攻创造条件。', 117);
INSERT INTO `t_military_term_data` VALUES ('ea13df6a-4a05-4035-a8a0-ec2e5977adf0', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击开始诸元', '炮兵对目标或试射点开始射击时使用的表尺、方向、高低等数值的统称。空炸射击时还包括引信分划。某些导弹射击时还包括发动机关机分划和飞行时间等。', 141);
INSERT INTO `t_military_term_data` VALUES ('ea15121f-b7a3-46f5-af74-f5764b6f7133', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术纵深', '战斗部署的纵向深度或战斗任务要求达到的全纵向深度。', 37);
INSERT INTO `t_military_term_data` VALUES ('ea1c65bd-7a4a-472a-bd2c-1af17eb25595', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '隶属', '编制或命令规定的下级对上级的从属关系。如一个营建制内下辖3个连,这3个连即隶属于这个营。', 80);
INSERT INTO `t_military_term_data` VALUES ('ea3dc5f7-e3e2-4962-99c7-fbf0f174641b', '8a761efd-50a6-4ac8-9913-b7d745104f82', '炮目距离', '火炮的发射位置到目标的直线距离。有时也指其他射击武器射击位置到目标的直线距离。', 13);
INSERT INTO `t_military_term_data` VALUES ('ea411b61-1cc4-479a-8d5b-fcff32403efc', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战场准备', '根据作战需要对预定战场所进行的准备。主要包括对预定战场的勘察、规划、建设和管理。用以创造有利的战场环境,保障未来作战任务的顺利进行。', 162);
INSERT INTO `t_military_term_data` VALUES ('ea48ce29-c220-4c9d-a5a9-b8d3b6a2f94d', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '反突击', '亦称战役反击。防御作战中,战役军团以其第二梯队或预备队为主对突入之敌实施的攻击。以歼灭突入之敌,恢复原防御态势。', 133);
INSERT INTO `t_military_term_data` VALUES ('ea75500b-3b6b-425d-8ab3-b04b3ed3d34c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜水疾病', '潜水人员受水下环境因素作用而引起的病症、损伤和功能紊乱等的统称。主要包括减压病、缺氧症、氧中毒、二氧化碳中毒、氮麻醉、肺气压伤、高压神经综合症、水下生物咬伤等。', 354);
INSERT INTO `t_military_term_data` VALUES ('ea76cc19-8bb3-44fb-9605-bad3f1a5c9d1', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '复训', '对已训人员或课目再次进行的训练。目的是巩固和提高训练水平。', 178);
INSERT INTO `t_military_term_data` VALUES ('ea795e07-e5c4-42b6-95e2-81931b6cfe1d', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '优秀士兵', '中国人民解放军在全军开展的争当优秀士兵活动中成绩优异的战士。条件是政治思想强、军事技术精、作风纪律严、完成任务好。', 55);
INSERT INTO `t_military_term_data` VALUES ('ea7abc97-25c1-41ca-be70-4b876a52c8be', '916997ee-6728-4c61-9b79-d96960b1dc86', '窒息性毒剂', '亦称伤肺性毒剂。以损害肺组织,破坏呼吸功能为主要毒害特征的毒剂。如光气等。施放后造成空气染毒,通过呼吸道侵入机体。中毒者一般经几小时的潜伏期后出现肺水肿症状：呼吸困难、胸部压痛、血压下降等,严重时出现昏迷以至死亡。', 221);
INSERT INTO `t_military_term_data` VALUES ('ea8a7b31-54a7-4ffa-9ff3-2bdbeef38bfd', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '陆军航空兵机降指挥', '陆军航空兵指挥员及其指挥机关对所属部队或分队的机降行动所实施的指挥。主要包括按计划指挥直升机机降和脱离机降场,协助机组处置特殊情况等。', 58);
INSERT INTO `t_military_term_data` VALUES ('eabaa9b0-41a5-41d9-a325-4f7b3f77af2a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '追击', '追歼退却或溃逃之敌的作战行动。按规模,分为战略追击、战役追击和战术追击；按手段,分为兵力追击和火力追击；按方式,分为跟踪追击、平行追击和垂直追击。', 369);
INSERT INTO `t_military_term_data` VALUES ('eacd99a7-e67f-41a9-ab49-ae589fcc4a5a', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '战役情报', '组织实施战役行动所需的情报。主要包括：作战区域内敌军的战役企图、战役编成、兵力部署、武器装备、通信联络、后勤保障,指挥官特点,以及地形、气象、水文、社会情况等。', 127);
INSERT INTO `t_military_term_data` VALUES ('ead4c8da-767b-4606-8a6b-0c172084c719', '878651de-adf5-4c72-9376-9c363b893ff8', '战略防御', '在战争全局上对敌实施的防御。是战略行动的基本类型之一。分为全线实施的全面防御和在某个方向或地区实施的重点防御。通常由战略反侦察、战略反突袭、战略相持、战略反攻等组成。', 108);
INSERT INTO `t_military_term_data` VALUES ('ead52d85-253e-4d55-a381-c14e1c4b465d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '穿插', '利用敌人部署间隙或薄弱部位插入其纵深或后方的作战行动。', 346);
INSERT INTO `t_military_term_data` VALUES ('eae58a47-dc0c-418a-b785-e2e4ee48d740', '8a761efd-50a6-4ac8-9913-b7d745104f82', '轻武器寿命', '轻武器在规定的试验条件和射击规范下保持设计性能的射弹发数。武器的种类不同寿命长短也不同。', 218);
INSERT INTO `t_military_term_data` VALUES ('eaf2c53f-9ae8-460f-96d2-5eb4f9ac4bd3', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '加强指挥', '上级指挥员或其指派的人员到所属部队协助指挥通常在下属部队执行主要任务或独有遂行任务时采用。上级指挥员应充分发挥下级指挥员的积极性,防止包办代替', 22);
INSERT INTO `t_military_term_data` VALUES ('eaf42a4a-d8d5-434b-8a3e-f060e288dbad', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '暗挖式工事', '利用自然地层作防护层、采取暗挖的施工方法在山体内和地下构筑的工事。如坑道工事、地道和短洞等。', 49);
INSERT INTO `t_military_term_data` VALUES ('eb053fe0-d18c-42b1-bf0a-10a2c331a0d6', '31f4a446-5b98-4873-9d53-310d97125b07', '禁射区', '为保证己方人员、物体的安全而在导弹射界内划定的禁止导弹发射的一定区域。', 123);
INSERT INTO `t_military_term_data` VALUES ('eb0566bf-44ab-4fc4-be37-d73021bba3d8', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天气', '一定地区某一时刻或短时段内大气的综合状态。通常用气温、气压、湿度、风向、风速,以及发生在大气中的云、雾、降水、雷电等现象来描述。有时也用阴、晴、冷、热、干、湿等来表示。', 34);
INSERT INTO `t_military_term_data` VALUES ('eb178933-1c59-4447-b5e8-b7b798d86482', '06a75831-13a1-4660-870a-455bb445336a', '技术保障通信', '为实施技术保障的组织指挥,按技术保障关系建立的通信联络。包括上下级技术保障机关之间,技术保障机关与技术保障部队和分队之间建立的通信联络。', 20);
INSERT INTO `t_military_term_data` VALUES ('eb2d14c4-82d5-4136-8512-c50f59475ac6', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役特点', '战役作战矛盾的特殊性。是战役本质和规律的反映。包括战役的一般特点和各种战役的具体特点。', 14);
INSERT INTO `t_military_term_data` VALUES ('eb3f1f00-5890-4c85-b9a0-022ae11f5690', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '街垒', '在街道或建筑物间的空地上,以就便材料堆砌或夯筑而成的有射击设备的拦障类障碍物。在城市（居民地）防御时,用以阻滞坦克、步兵的行动。', 124);
INSERT INTO `t_military_term_data` VALUES ('eb43595f-3a09-4fc9-b356-ecc5c1db28b9', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '桥梁加强', '提高原有桥梁承载能力的工程作业。方法有增加辅助构件、加强薄弱环节和改变结构体系等。', 290);
INSERT INTO `t_military_term_data` VALUES ('eb512043-2e39-458b-8825-0e2a0cd15e57', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '扫雷器材', '用以扫除地雷等爆炸性障碍物的工程器材。主要有扫雷器、扫雷车和供人工扫雷用的简易工具。如扫雷锚、扫雷耙、保险销、标示旗、标示绳等。', 173);
INSERT INTO `t_military_term_data` VALUES ('eb62814b-1daf-4e62-a473-bc5a0d92f2a7', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '台（飓）风', '中心附近平均最大风力达12级及其以上的强热带气旋。发生在北太平洋西部和中国南海的称为台风,发生在北太平洋东部和大西样的称为飓风。台风（飓风）多出现在夏、秋季节,所经之处产生狂风、暴雨和巨浪,登陆后强度迅速减弱,带来大范围降雨。', 41);
INSERT INTO `t_military_term_data` VALUES ('eb83761f-e7ef-4612-93d2-78b7258b7b70', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '水文要素', '表示和反映水文状况的物理量与现象。分为陆地水文要素和海洋水文要素。陆地水文要素包括降水、蒸发和径流,以及水位、流量、含沙量、水温、冰凌和水质等；海洋水文要素包括海水的温度、盐度、密度、水色、透明度和海发光、海冰、海流、海浪、海洋潮汐等。', 110);
INSERT INTO `t_military_term_data` VALUES ('eb85cea4-a1e5-4b36-a460-88d7ead88ea9', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '末端制导炮弹', '利用炮弹自身的制导装置,在外弹道末段导引弹丸飞向目标的炮弹。按制导方式,分为激光末段制导炮弹、红外末段制导炮弹和无线电末段制导炮弹等；按所配用的炮种,分为榴弹炮末段制导炮弹、迫击炮末段制导炮弹等。通常用以射击远距离的重要目标。', 316);
INSERT INTO `t_military_term_data` VALUES ('eb9214d0-f3fe-46eb-8e13-ebfc54b46f69', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇满旗', '舰艇停泊时在昼间悬挂国旗、军旗,并从舰首通过桅杆横桁至舰尾挂满通信旗的隆重礼仪。通常在重大节日,阅兵,授旗、命名、授予荣誉称号等典礼,以及迎送国家、政府、军队领导人和重要外宾或其他隆重庆祝活动时举行。', 400);
INSERT INTO `t_military_term_data` VALUES ('eb968df3-a4ac-441f-8b93-1df783727c7d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事因素', '①构成军事的各种成分。②影响非军事领域活动的军事原因和条件。', 51);
INSERT INTO `t_military_term_data` VALUES ('eba4b67d-f506-43eb-bc09-e99adf0c0378', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击训练', '炮兵部队和分队为掌握火炮射击本领而进行的训练。内容包括射击理论、射击技能等。', 126);
INSERT INTO `t_military_term_data` VALUES ('ebbe4f6c-41dd-45d7-bd02-ab6eef38878b', 'd7132c58-5df3-4b97-919f-58740148b9ca', '战役防空', '战役军团在战役中组织的对空防御和抗击敌空袭的作战行动。主要包括：建立战役防空指挥体系,制定战役防空计划,组织战役防空侦察和情报传递,对战役防空力量进行区分、编组,组织转移和转隶,组织战役防空作战协同以及各种保障等。', 67);
INSERT INTO `t_military_term_data` VALUES ('ebc30e76-5adb-47d0-8231-bd9d05626822', 'd7132c58-5df3-4b97-919f-58740148b9ca', '对空观察哨报知通信', '传递对空观察哨所获情报的通信联络。通常由高炮旅、团组织远方、近方对空观察哨的无线电台报告空情,各级指挥所组织收听。有条件时观察哨还应与指挥所建立有线电通信。', 128);
INSERT INTO `t_military_term_data` VALUES ('ebe2094b-8975-4622-b5b4-4adb6d6c10d2', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术包围', '兵团或部队、分队对敌实施的包围。目的是为全歼敌人创造有利条件。', 31);
INSERT INTO `t_military_term_data` VALUES ('ebf2514e-cb74-4135-a391-2d6759d378e0', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '时分电子干扰', '以一部瞄准式电子干扰机,在预定时段内按时间分割原理,依次快速对多个不同频率的电子设备轮流实施的电子干扰。', 64);
INSERT INTO `t_military_term_data` VALUES ('ebfeedf0-3cda-45a3-8fc5-5e4ee74b676b', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术思想', '关于战斗问题的理性认识。通常表现为进行战斗的指导理论和基本原则。', 28);
INSERT INTO `t_military_term_data` VALUES ('ec0aca00-05ac-4bf5-9107-d88f8359e507', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队基本阵地作战', '导弹部队在基本阵地上实施导弹突击的作战。分为基本阵地发射场坪作战和发射井作战。', 36);
INSERT INTO `t_military_term_data` VALUES ('ec0d41b9-6f5c-44e9-89ee-5e250f373356', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '热动力鱼雷', '利用推进剂燃烧产生的热能转换成机械能作为推进动力的色雷。按推进剂,分为单组元推进剂鱼雷、双组元推进剂鱼雷、多组元推进剂鱼雷、混合推进剂鱼雷和固体推进剂鱼雷；按发动机,分为往复式发动机鱼雷、凸轮式发动机鱼雷、摆盘或斜盘式发动机鱼雷、火箭发动机鱼雷和喷水发动机鱼雷。', 200);
INSERT INTO `t_military_term_data` VALUES ('ec21d574-845c-4895-aac1-32c499ffd167', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '测距仪', '亦称测距机。测定目标与观测点之间距离的仪器。按测距原理,分为几何法和时基法两类。运用几何法测距的一般指普通光学测距仪；运用时基法测距的主要有激光测距仪、微波测距仪、声波测距仪等。军事上广泛用于射击、轰炸、侦察、测绘、导航等。', 71);
INSERT INTO `t_military_term_data` VALUES ('ec27d7d7-8e5c-4e14-bde0-c8a36538a720', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '装（卸）载地域', '部队输送或物资运输时进行装（卸）载的地域。包括待运或集合地域、装（卸）载点和相互连接的道路。由被输送单位的指挥员与军事交通部门负责人共同选定。', 90);
INSERT INTO `t_military_term_data` VALUES ('ec3d2686-9ff0-44ea-b6c6-dae2407e25a8', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '雷管', '能在外界小能量激发下输出爆轰能,起爆炸药的管状火工品。分为火雷管、电雷管、激光雷管等。', 216);
INSERT INTO `t_military_term_data` VALUES ('ec3e942c-8936-4372-854b-0be8ca60f721', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '火力密度', '在单位时间内发射或投送到单位面积、空间或单位正面宽度上弹药的数量。通常指步兵武器火力密度和各种炮兵、导弹的火力密度。一般以平均每分钟发射到100米正面宽度上的子弹数,或平均每分钟发射到1公顷地域内的炮弹数分别表示。', 156);
INSERT INTO `t_military_term_data` VALUES ('ec3fdd3b-5f27-4d46-b435-c1904051cd52', '916997ee-6728-4c61-9b79-d96960b1dc86', '发烟罐', '装有发烟剂的罐状发烟装备。分为遮蔽发烟罐和信号发烟罐。', 242);
INSERT INTO `t_military_term_data` VALUES ('ec57b82c-9f6e-478c-b186-0e7c1ae55f23', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '检验性演习', '亦称考核性演习。以检查考核方式进行的军事演习。', 114);
INSERT INTO `t_military_term_data` VALUES ('ec5a7738-916c-45a3-b228-b210837f2183', '06a75831-13a1-4660-870a-455bb445336a', '水下通信', '通信双方或一方处于水下的通信。包括水下电缆通信、无线电通信、激光通信和水声通信等。主要用于岸台对潜艇,潜艇之间,潜艇与水面舰艇之间,潜水员之间,潜水员与水面舰艇之间的通信等。', 118);
INSERT INTO `t_military_term_data` VALUES ('ec5da6ed-4e9a-4ff6-adbb-54e528e236c2', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '遮蔽角', '炮口至遮蔽顶的连线与炮口水平面的高低夹角。可用以确定火炮射击的最低表尺。', 236);
INSERT INTO `t_military_term_data` VALUES ('ec6249c9-1281-4ac2-b28b-a9d06ae4ef45', '878651de-adf5-4c72-9376-9c363b893ff8', '战争规模', '战争双方参战的力量和作战行动涉及的空间范围。', 7);
INSERT INTO `t_military_term_data` VALUES ('ec6be7a2-ebe4-46fc-b449-a5a7c8983544', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '干扰时机', '对敌实施电子干扰的有利时间。取决于作战任务、干扰对象和干扰样式等因素。施放干扰过早,可能会暴露己方意图；施放干扰过晚,则失去作用。', 78);
INSERT INTO `t_military_term_data` VALUES ('ec784666-81c7-4b7b-9ecb-6086ad3c6dfc', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '教学大纲', '军队院校指导一门学科教学的法规性文件。是制定科（课）目实施计划、编写教学材料的基本依据。', 30);
INSERT INTO `t_military_term_data` VALUES ('ec7b65ee-bbdb-472d-bbba-1d7566fe5a67', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练指导法', '用以统一、规范部队军事训练的组织与实施的指导性文件。是部队组织实施军事训练的基本依据。如《中国人民解放军陆军军事训练指导法》。', 17);
INSERT INTO `t_military_term_data` VALUES ('ec82bfd6-2a9a-4a0c-aec4-17f94149c221', '97a19170-bfac-42c5-9906-1acb187f0654', '空降编成', '将参加空降作战的空降部队和航空兵部队的兵力组成有机的整体。主要根据作战任务、兵力部署、航空兵输送能力和输送程序等因素确定。', 155);
INSERT INTO `t_military_term_data` VALUES ('ec8d04b4-2ab2-4845-bfa7-c47335202ad3', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军人宣誓', '军人通过一定的仪式表达对其肩负的神圣职责和光荣使命的承诺与保证。中华人民共和国公民应征入伍后,都要进行军人宣誓。', 108);
INSERT INTO `t_military_term_data` VALUES ('ec9443d8-91ec-4c5b-bdfc-6398be147af8', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰载机起降', '舰载机在舰船上进行的起飞和降落。包括固定翼舰载机起降、垂直／短距起落舰载机起降和舰载直升机起降。', 308);
INSERT INTO `t_military_term_data` VALUES ('eca5bac4-1431-4b5a-96b0-355a5a162f54', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '空抛雷', '设置在地面上的防空雷。在目标进入雷场或雷群上空时,由人工操纵或自动点火,使防空雷破片或将雷弹抛射至空中,以毁伤敌机和杀伤敌空降兵。', 159);
INSERT INTO `t_military_term_data` VALUES ('eca67864-a670-47af-9e2c-d852447d50b9', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '方位物', '为判定方位和指示目标而选定的地面上明显、独立的固定物体。如山顶、突出树、塔形建筑物、桥梁、岔路口、河汊口、林间空地等,均可作为方位物。', 138);
INSERT INTO `t_military_term_data` VALUES ('eca6f183-2535-4eb3-bc78-9e2ba8a5000c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军属', '现役军人的家属。包括军人的父母、配偶、子女以及依靠军人生活的18周岁以下的弟妹或自幼抚养军人长大,现尚依靠军人生活的其他亲属。', 91);
INSERT INTO `t_military_term_data` VALUES ('ecba4188-8d92-444f-b35c-f4c4ff5f82ee', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '特大威力核武器', '威力超过 100万吨梯恩梯当量的核武器。', 102);
INSERT INTO `t_military_term_data` VALUES ('ecc7a988-a044-4719-b802-2adb11cc25e5', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防热红外伪装', '为降低敌热红外侦察仪器的发现概率和热红外制导武器的命中概率而实施的伪装。主要包括：将目标配置在地形遮蔽区内,设置热红外假目标和热红外遮障,涂刷热红外涂料或隔热涂层以及施放热红外烟幕等。', 341);
INSERT INTO `t_military_term_data` VALUES ('ecc89c42-7d3b-40d6-88b4-62c2c65a11ed', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军轰炸机', '用以轰炸海上及岸上目标的海军飞机。通常装备有航炮、空舰或空地导弹、炸弹、水雷、鱼雷、深水炸弹等,也可携带核武器。', 172);
INSERT INTO `t_military_term_data` VALUES ('ece661b7-7418-43b5-b437-c4fdb08deb98', '31f4a446-5b98-4873-9d53-310d97125b07', '地面分辨率', '通过一定高度上的空中探测器所获得的遥感图像,对地面目标能够辨析的程度。通常以能够分析辨别出的最小地物的长度与宽度表示。计量单位为米或厘米。', 192);
INSERT INTO `t_military_term_data` VALUES ('ece70b45-1532-4460-a258-6374b3e4edb4', '97a19170-bfac-42c5-9906-1acb187f0654', '空军气象保障', '空军为顺利遂行作战、训练等任务而在气象方面进行的保障。主要是提供天气预报、天气实况和其他有关气象资料。', 381);
INSERT INTO `t_military_term_data` VALUES ('eceb06c9-4f37-44bf-9c99-1c76df36ae47', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '毗连区', '沿海国在毗连其领海以外一定范围内,为行使必要管制权而划定的区域。其外部界限从领海基线量起不得超过24海里。沿海国在毗连区内可对本国和外国公民及船只行使海关、缉私、卫生和移民等事项的管制权。', 76);
INSERT INTO `t_military_term_data` VALUES ('ecfafd1e-7b64-45aa-ba36-f429f62a954f', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队生存能力', '导弹部队遭敌袭击后仍能遂行作战任务的能力。主要取决于阵地的防护能力和隐蔽伪装的程度,装备的抗打击能力,以及部队的机动能力等因素。', 17);
INSERT INTO `t_military_term_data` VALUES ('ed218d08-d25a-41b3-b452-28ea17c5397c', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机战损率', '一个单位在一定时限内,战斗损失的飞机架数与战斗出动的飞机架次数的比值。通常用百分比表示。如战斗出动飞机100架次,战斗损失9架,则战损率为9％。', 56);
INSERT INTO `t_military_term_data` VALUES ('ed22add2-3f66-49ad-841a-212253bd1d73', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '涌浪', '亦称涌。风浪离开风区或风停止、转向后,因惯性作用继续向前传播的波浪。其外形较规则,波面平滑,波长较长,波速较快。在气象、水文保障中,将海上涌浪划分为无涌、小涌、中涌、大涌和巨涌等5级。', 130);
INSERT INTO `t_military_term_data` VALUES ('ed2b3d12-37f8-4c2f-bea7-9056a327a73a', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防哨所', '驻守边境前沿的边防小分队或民兵执勤和生活的处所。', 91);
INSERT INTO `t_military_term_data` VALUES ('ed2fb115-4ed2-4f20-8e0b-694139a372b0', '06a75831-13a1-4660-870a-455bb445336a', '自动化指令执行系统', '在指挥自动化系统中执行指令并反馈执行情况的分系统。可作为执行命令的部队指挥自动化系统；也可作为自动执行指令的装置,如导弹的制导装置、火炮的火控装置等。', 166);
INSERT INTO `t_military_term_data` VALUES ('ed372d0e-eea1-460f-bcf2-2cef907b72cd', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军人姿态', '军人的姿势形态。要求行、立、坐、卧符合条令规范。', 47);
INSERT INTO `t_military_term_data` VALUES ('ed404131-d375-44c1-bc6a-a6a0153dcb5f', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机完好率', '一定时间内一个单位能够遂行任务的飞机架数与实有飞机架数或在队飞机架数的比值。通常用百分比表示。分为实有飞机完好率和在队飞机完好率。', 452);
INSERT INTO `t_military_term_data` VALUES ('ed420705-6431-4505-97b8-d56ee449eabd', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练改革', '对军事训练中过时的不合理的部分进行的改进和革新。通常包括训练的体制、内容、方法、管理和保障等方面的改革。', 7);
INSERT INTO `t_military_term_data` VALUES ('ed5f9cae-e0d9-4c90-a2d8-c43d6dee3ea8', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役包围', '战役军团对敌实施的包围。目的是为全歼敌人创造有利条件。', 110);
INSERT INTO `t_military_term_data` VALUES ('ed6d6793-55fb-41fd-a140-c79f8d8f2e18', '97a19170-bfac-42c5-9906-1acb187f0654', '雷达网', '雷达情报网的简称。在一定区域内配置多部雷达,并使各雷达的探测范围在规定高度上能够互相衔接的布局。', 393);
INSERT INTO `t_military_term_data` VALUES ('ed7310a5-12ed-4f70-9509-8a87b2ed2ca1', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '崖壁', '面向敌方的陡壁式防坦克土工障碍物。通常在15度～45度的向敌斜坡上切坡构成。高度不小干2米,底宽3.5～4米,并稍向内倾斜,以使坦克不易碰榻。', 116);
INSERT INTO `t_military_term_data` VALUES ('ed839b22-6e98-4ffc-b4b8-09cd9ae8d7cb', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '现役部队', '国家经常保持的、由现役军人按现定的体制编制组成的部队。', 44);
INSERT INTO `t_military_term_data` VALUES ('ed87f5df-ded9-47bc-bd2e-006fe6fb317d', '8a761efd-50a6-4ac8-9913-b7d745104f82', '侧射', '射向与目标侧面概略垂直的射击。', 108);
INSERT INTO `t_military_term_data` VALUES ('ed97f915-781a-4bcc-b6a2-de0e4fa57f86', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '干部退出现役制度', '军队干部免除服现役的制度。主要包括了部退出现役的条件、批准权限、安置办法及待遇等规定。', 81);
INSERT INTO `t_military_term_data` VALUES ('eda659cd-0f6e-459d-8e17-0bbd4203b4d4', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防实力', ' 国家现有的防卫力量。主要包括：武装力量、国防科技、国防工业、国防设施等的规模和水平,以及与国防有关的政治、经济、科技、文化等方面的综合力量。', 8);
INSERT INTO `t_military_term_data` VALUES ('edc69457-7a10-44f1-a2c6-f9e339336550', '97a19170-bfac-42c5-9906-1acb187f0654', '航空油料', '航空器使用的航空主油和航空附油的统称。航空主油有航空煤油和航空汽油；航空附油有航空润滑油、润滑脂和航空特种液等。', 402);
INSERT INTO `t_military_term_data` VALUES ('edd00def-d906-49e0-849d-481f08f61437', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '海滩', '海边比较平缓的滩地。通常位于平均高潮面与平均低潮面之间。分为砾石（卵石）滩、粗砂滩、细沙滩和泥滩。', 47);
INSERT INTO `t_military_term_data` VALUES ('edd74de7-2099-4e04-bc11-5b7c7c9e44b2', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '对潜指挥', '海军岸上指挥所对潜艇部队作战行动实施的指挥。包括对战略导弹潜艇指挥和对攻击潜艇指挥。', 116);
INSERT INTO `t_military_term_data` VALUES ('edda71c6-10ed-47da-b722-46c60dde4885', 'f0140091-c11a-48c9-8836-8aa94439dac0', '狙击', '单枪或单炮隐蔽、突然、准确地射杀敌单个或小群目标的战斗行动。', 248);
INSERT INTO `t_military_term_data` VALUES ('edf301a4-ecfc-4ad6-ba6d-a2ea2822ce3b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天系统', '亦称航天工程系统、由航天器、航天运输系统、航天器发射场和回收着陆场、航天测控网、应用系统等组成的完成特定航天任务的工程系统。分为民用航天系统和军用航天系统。军用航天系统主要有卫星侦察系统、军用卫星通信系统、军用卫星导航系统、军用卫星气象观测系统、军用卫星测地系统以及各种空间武器系统等。', 198);
INSERT INTO `t_military_term_data` VALUES ('edfaae3c-b606-4946-8f88-0c8f01794e27', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮火突击', '炮兵对敌实施的突然、猛烈的火力突击。', 75);
INSERT INTO `t_military_term_data` VALUES ('edfff4cb-490e-4c68-8c64-0b308f62cf74', '98df76fb-4b65-48ff-a56c-4db587327c79', '战役运输', '为达成战役目的,在战役后方和战术后方之间或各战术后方之间实施的军事运输。主要包括战役机动运输、战役供应运输和伤病员后送运输等。由战区或战役军团的交通运输指挥机构组织实施。', 246);
INSERT INTO `t_military_term_data` VALUES ('ee075618-6c4c-4913-83b3-904488091c68', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵战斗队形转移', '防空兵部队或分队的战斗队形从已配置的地域转向另一配置地域的行动。基本方法有跟随转移、交替转移和逐次转移。', 84);
INSERT INTO `t_military_term_data` VALUES ('ee1e64fb-38b9-45da-8a49-a54bb8a30a8c', '97a19170-bfac-42c5-9906-1acb187f0654', '野战机场', '只有简易的飞行保障设施,供航空兵部队战时临时驻用的军用机场。通常铺设有装配式金属板或其他简易道面的跑道,配备有活动式的飞行保障设施。', 413);
INSERT INTO `t_military_term_data` VALUES ('ee43fac5-3cb4-4f75-bc32-166d3307ea32', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '会师', '两支以上军队或两个以上部队在战场上会合。', 329);
INSERT INTO `t_military_term_data` VALUES ('ee5d6be3-135e-4462-b6c4-961a97c5ec9e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '乘敌之隙', '利用敌之错误或疏漏采取作战行动。', 229);
INSERT INTO `t_military_term_data` VALUES ('ee73effc-963a-4e59-916e-ac36b25e8d05', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂侦检', '发现和查明毒剂并测定其含量的技术。通常采用物理、化学、生物化学、生物等侦检法。用于战时化学防护,也可用于化学事故应急救援和化学裁军核查等。', 115);
INSERT INTO `t_military_term_data` VALUES ('ee7445c8-fbca-47ff-8bd1-af09149a1adb', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克武器', '装在坦克上的杀伤兵器的统称。包括坦克炮及装弹机构、坦克机枪和坦克弹药等。有的坦克还装有导弹。用以毁伤敌坦克及其他装甲车辆,压制、消灭反坦克武器，摧毁野战工事,杀伤有生力量,打击低空目标等。', 111);
INSERT INTO `t_military_term_data` VALUES ('ee792bbe-c804-4368-982d-cf3d6c0ad491', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '渡场长', '统一负责渡场全面工作的指挥员。由合成军队首长指定。通常由负责开设渡场的工程兵部队或分队指挥员担任。', 322);
INSERT INTO `t_military_term_data` VALUES ('ee7c8f31-b122-4ea7-abb0-f78f1395e94e', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '按级指挥', '隶属关系逐级实施的指挥', 24);
INSERT INTO `t_military_term_data` VALUES ('ee81d0aa-5ef4-45c1-a47f-867f0b0b0b59', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '返回舱', '从航天器上分离出来的,重返地球稠密大气层并能承受再入环境的舱段。包括回收舱、制动火箭等。', 281);
INSERT INTO `t_military_term_data` VALUES ('ee87ab60-70ba-48f6-b76a-63f3804f682d', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事思想', '关于战争和军队问题的理性认识。通常表现为国防与军队建设、战争准备与实施的指导理论和基本原则。是军事科学的重要组成部分,属于社会意识形态,受世界观与方法论的制约,具有鲜明的政治性。', 8);
INSERT INTO `t_military_term_data` VALUES ('ee8a8aab-69fc-4133-9c2d-ef2d0c1c4747', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电波吸收材料', '能将入的电磁波能量转换成其他形式的能量而极少反射回去的材料。有吸收型、干涉型、诸振型和放射性同位素型等。主要用以覆盖飞机、导弹等武器表面,以减少其有效反射面积。也可用以制作伪装网、伪装服等。', 139);
INSERT INTO `t_military_term_data` VALUES ('ee925238-06ff-4b04-90d3-6807dedfbd56', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '登陆作战', '军队对据守岛屿、海岸之敌实施渡海上陆的进攻作战。用以突破敌人海岸或岛屿的防御,夺占登陆场,为尔后作战创造有利条件。', 192);
INSERT INTO `t_military_term_data` VALUES ('ee97832d-578e-4870-a844-1e8d014fb7b6', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '交接制度', '军队中关于单位或人员之间对掌管的工作、物品进行移交和接收的制度。主要包括交接的时机、内容、程序、监督等方面的规定。', 15);
INSERT INTO `t_military_term_data` VALUES ('eea30002-8dfc-4ccb-a62a-d7bcae5d3d49', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机（直升机）作战半径', '飞机或直升机在载有一定油量和武器、弹药遂行战斗任务时,在同一机场作一次往返飞行所能到达最远作战点的距离。是飞机战术技术性能的主要指标之一。作战半径的大小与飞机的技术性能和飞行高度、速度、气象条件、编队大小、战斗任务以及实施方法等因素有关。', 60);
INSERT INTO `t_military_term_data` VALUES ('eeb6f849-00d4-4107-9985-083a82c72c39', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '营房管理制度', '军队中关于营房使用与管理的制度。主要包括营房及其设备的使用、收费、检查。维修以及安全管理等方面的规定。', 17);
INSERT INTO `t_military_term_data` VALUES ('eeba22fe-9c3a-4dc7-ad12-2841665d6ae1', '06a75831-13a1-4660-870a-455bb445336a', '宽频带电台', '工作频段覆盖短波及部分中波、超短波波段的无线电台。频段覆盖一般为 16～80兆赫。可进行多种工作种类的通信。主要用于师、团级部队无线电通信和步、炮、坦协同通信。', 186);
INSERT INTO `t_military_term_data` VALUES ('eed872c1-279e-44ca-a6d5-997d4c7cf8bd', 'f0140091-c11a-48c9-8836-8aa94439dac0', '纵深支撑点', '营防御地域内第二线连、排坚守的支撑点。', 239);
INSERT INTO `t_military_term_data` VALUES ('eee0690f-9186-4d17-a26b-084a79c36e49', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '荒漠', '植被贫乏,地面大部或全部裸露的干旱和半干旱地区。气候干燥,降水稀少已多为暴雨,蒸发量大,地表水奇缺,地面气温变化剧烈,昼夜温差大,风力作用活跃,太阳辐射强,日照时间长。按地表组成物质,分为岩漠、沙漠、泥漠和盐漠等。军事上利于观察、空中突击,但不利于隐蔽、伪装和给水。', 35);
INSERT INTO `t_military_term_data` VALUES ('eee17178-a900-42f8-83ed-434d7d153f13', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '计算机硬件', '简称硬件。计算机系统中实体设备的统称。一般由输入设备、运算器、控制器、存储器和输出设备等构成。具有信息变换、传送、解算和处理等功能。', 55);
INSERT INTO `t_military_term_data` VALUES ('eee44fcd-9661-4d32-9ce0-9ff9db9a329a', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克复合装甲', '由两层以上不同性能的防护材料组成的非均质坦克装甲。分为金属与金属复合装甲、金属与非金属复合装甲和间隔装甲3种。具有较强的综合防护性能。', 134);
INSERT INTO `t_military_term_data` VALUES ('eee646ca-3317-4176-88e1-971d774ff27b', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '野外场地', '场以外可供直升机起飞、降落的天然和人工简易场地的统称。包括具有一定面积、表面平坦的平地、院落、河滩、房顶、山头、谷地、设备平台等。', 95);
INSERT INTO `t_military_term_data` VALUES ('eee984d0-9ac8-43c7-ab16-c68b260a116b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事技术史', '关于军事技术的产生及其发展的历史。是军事历史学的重要研究内容。', 39);
INSERT INTO `t_military_term_data` VALUES ('ef058f56-8e30-4cb8-bcfa-17cc9bc00a30', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上防御布雷', '海军兵力在己方海域布设水雷的战斗行动。', 107);
INSERT INTO `t_military_term_data` VALUES ('ef067e6b-3d5b-40ff-b4a9-c549130ef345', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海浪', '海水的波动现象。包括风浪、涌浪和近岸波。广义上也包括海啸、风暴潮和海洋内波等。', 128);
INSERT INTO `t_military_term_data` VALUES ('ef12ce21-d670-427e-9284-58fa628300e0', '98df76fb-4b65-48ff-a56c-4db587327c79', '基地兵站', '设在战役后方基地的固定兵站。编有指挥机关,统一管理后方基地的仓库、医院、运输、修理等单位。负责支援野战兵站实施后勤保障。', 18);
INSERT INTO `t_military_term_data` VALUES ('ef2aaee1-1ead-45bf-80ee-4a6179ee06ba', '878651de-adf5-4c72-9376-9c363b893ff8', '战略物资', '对国防或战争具有全局性重要作用的物资。如石油、钢铁、粮食等。', 99);
INSERT INTO `t_military_term_data` VALUES ('ef2bfa71-143c-4a01-b2ca-71a787755160', '8a761efd-50a6-4ac8-9913-b7d745104f82', '自动榴弹发射器', '亦称连发榴弹发射器。能自动地连续进行装弹、闭膛、击发的榴弹发射器。口径30～40毫米，重量20～50千克，射速90－400发／分，射程可达2000米。发射弹种有杀伤弹、破甲弹、燃烧弹、烟幕弹等。', 183);
INSERT INTO `t_military_term_data` VALUES ('ef2ec3ff-1050-4c73-a4a1-35dceea99e7d', '98df76fb-4b65-48ff-a56c-4db587327c79', '野战医院', '适于野战条件下展开工作的机动性较强的医院。主要负责对伤病员进行早期治疗和部分专科治疗。', 214);
INSERT INTO `t_military_term_data` VALUES ('ef3dddda-5317-493f-8d51-1aac8775ce97', '97a19170-bfac-42c5-9906-1acb187f0654', '空军军', '由若干个师、旅等编成的空军一级组织。隶属于军区空军。设有领导机关,下辖若干个航空兵师、地空导弹旅、高射炮团、雷达团等战斗部队和专业勤务部队。通常作为空军基本战役军团,担负军区内某一方向或地区的防空作战、空中进攻作战和支援陆军、海军作战等任务。', 2);
INSERT INTO `t_military_term_data` VALUES ('ef433e27-9fc6-4f1d-8c7c-e8c70d980208', '97a19170-bfac-42c5-9906-1acb187f0654', '航空管制', '亦称飞行管制。有关部门根据国家颁布的飞行规则,对空中飞行的航空器实施的监督控制和强制性管理的统称。主要目的是维持飞行秩序,防止航空器互撞和航空器与地面障碍物相撞。', 374);
INSERT INTO `t_military_term_data` VALUES ('ef436977-1917-4f04-b2e5-689b75115ebe', '97a19170-bfac-42c5-9906-1acb187f0654', '昼间飞行', '从日出到日没的时间内实施的飞行。光线较好,利于飞行。', 219);
INSERT INTO `t_military_term_data` VALUES ('ef44c3ff-8a84-41c9-8101-0069efe0034a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '早期核辐射效应', '亦称贯穿辐射效应。核爆炸瞬间释放的具有很强贯穿能力的中子和X射线对生物体、电子器件和其他物体的毁伤作用与效果。作用时间短暂（仅十几秒）。对生物体的损伤程度取决于剂量当量,对电子器件的损伤则取决于中子能谱与积分通量和Y射线的吸收剂量与吸收剂量率。', 169);
INSERT INTO `t_military_term_data` VALUES ('ef48879b-4923-4ade-9427-39df14b61d1d', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵敌后侦察组', '炮兵派出的、潜入敌纵深观察敌情,校正和指挥射击的侦察组。通常在受地形影响,其他炮兵观察所难以完成任务时,根据作战需要和可能,经合成军队首长批准而派出。', 93);
INSERT INTO `t_military_term_data` VALUES ('ef4c1fe9-e32b-41c6-b969-d620cb64143f', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '非战斗损耗', '由于事故或其他非战斗原因造成的武器、弹药、车辆、油料、器材及其他物资的损失。损坏和消耗的统称。', 92);
INSERT INTO `t_military_term_data` VALUES ('ef4d7e66-d5c2-4d01-84c4-04671fa1c1df', '97a19170-bfac-42c5-9906-1acb187f0654', '空投', '用航空器将输送的装备和物资从空中投送到指定地点的行动。分为带伞空投和不带伞空投。', 170);
INSERT INTO `t_military_term_data` VALUES ('ef520505-f124-48ce-8722-5a2fc8696cf6', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '战斗力指数', '反映战斗力强弱的相对数。分为单件武器战斗力指数（亦称武器指数）和兵力战斗力指数（亦称综合战斗力指数）。单件武器战斗力指数是在武器火力指数基础上考虑机动能力、生存能力等因素而得的指数。兵力战斗力指数,须考虑作战环境、作战对象、作战样式、指战员素质、战略战术等因素影响,通常以火力指数为基础,采用线性加权求和或运用其他方法求得。', 187);
INSERT INTO `t_military_term_data` VALUES ('ef569796-af33-467a-ab1a-101ade656505', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战术演习', '根据想定的战术情况进行的军事演习。目的是提高指挥员、机关的组织指挥能力和部队、分队的战斗能力。', 121);
INSERT INTO `t_military_term_data` VALUES ('ef571551-34d6-42fe-8756-0b7ea2eb7ce1', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '精密法', '根据精密测地决定的测地诸元以及完整的弹道资料和适时的气象通报,计算并修入射击条件修正量以决定射击开始诸元的方法。精密法精度较好,通常用以决定目标射击开始诸元。是决定射击开始诸元的基本方法。', 145);
INSERT INTO `t_military_term_data` VALUES ('ef5ce984-0de5-4594-9d38-58937383b5e9', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '城市', '具有一定规模的人口和工商业,并以非农业人口为主的居民聚居地。通常是国家或一定地区范围内的政治、经济、文化中心、一般认为,100万人以上的为特大城市,50万人以上的为大城市,20～50万人的为中等城市,20万人以下的为小城市。城市作战与野战条件下作战有不同的特点。', 102);
INSERT INTO `t_military_term_data` VALUES ('ef61ce57-426b-4395-8a39-9e37f24c33c5', '97a19170-bfac-42c5-9906-1acb187f0654', '水平轰炸', '飞机在水平飞行中对目标进行的轰炸。适用于昼夜各种气象条件和各种高度。是轰炸机主要的轰炸方法。强击机和歼击机、歼击轰炸机在低空、超低空对面状目标或垂直面较大的立体目标进行轰炸时也可采用。', 95);
INSERT INTO `t_military_term_data` VALUES ('ef67adf7-cf1d-4fd9-9f63-246b6775044e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '军用道路', '为保障军事行动而构筑和维修的道路。包括新修的和加修、改造而成的标准军用道路及急造军路等。', 255);
INSERT INTO `t_military_term_data` VALUES ('ef6a6f21-5236-4219-90fe-8c3796b142bf', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役指导', '对战役的筹划与实施给予原则性的指示和引导。', 21);
INSERT INTO `t_military_term_data` VALUES ('ef6bbce5-47c9-466f-b63c-7884ed13392f', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '影像判读', '对所获取的影像资料进行观察、测量、分析并判定其本质的工作、包括对照片、胶片和屏幕影像的判读。分为可见光影像判读、红外线影像判读、多光谱影像判读、微波影像判读等。', 147);
INSERT INTO `t_military_term_data` VALUES ('ef8c6203-9274-4798-baee-8efc264b42bc', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '反潜直升机', '用以搜索和攻大潜艇的海军直升机、分为岸基反潜直升机和舰载反潜直升机。通常装备会水声器材和航空反潜鱼雷、深水炸弹、空舰导弹等。', 178);
INSERT INTO `t_military_term_data` VALUES ('ef8ef645-bb86-4962-8c38-3e8714dbd1e5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水面舰艇部队', '以水面舰艇为基本装备,在水面遂行作战任务的海军兵种。包括水面战斗舰艇部队、登陆作战舰艇部队和勤务舰船部队。可攻击敌方海上和沿岸及其一定纵深内的目标,参加争夺制海权的斗争,进行海上封锁、反封锁作战,参加登陆、抗登陆作战,保护或破坏海上交通线等。', 2);
INSERT INTO `t_military_term_data` VALUES ('ef91412f-f5d0-4921-887b-691b6ad25184', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '临战状态', '①国家或其局部地区从宣布战争动员起到战争爆发的一段时间内采取的措施和所呈现的状态。②武装力量从受领作战任务到作战开始前采取的措施和所呈现的状态。', 154);
INSERT INTO `t_military_term_data` VALUES ('efaad7c6-b9ff-4de7-99c0-9e8ad1ff1b83', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化定点监测', '对指定地点实施的化学、辐射侦察。主要监测指挥所等重点目标的放射性烟云降开始和结束的时间,毒剂初生云团到达和通过的时间及受染情况,以及监测指定地点的受染程度随时间变化的情况。', 54);
INSERT INTO `t_military_term_data` VALUES ('efba6ef3-fe39-4f07-b5f0-e2ac145c94a7', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上布雷', '海军兵力在指定海区布设水雷的战斗行动。分为海上攻势布雷、海上防御布雷和海上机动布雷。', 105);
INSERT INTO `t_military_term_data` VALUES ('efbabdb1-b12e-4912-93b3-430efa9710fa', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵组织', '参照军队的编制形式建立起来的民兵建制单位。如民兵排、民兵连、民兵营等。民兵组织落实是民兵建设的基础。', 125);
INSERT INTO `t_military_term_data` VALUES ('efd09c25-17fb-4ea2-a502-5cdceb6f442c', '98df76fb-4b65-48ff-a56c-4db587327c79', '军运设施', '国家交通运输部门和地方政府为保障军事运输需要而修建和提供的专用设施的统称。主要包括：军用线路、站台,码头、防雨棚,军人候车（船）室,军用饮食供应站、供水站,人接待转运站,军运备品仓库,军事代表办公房舍等。', 269);
INSERT INTO `t_military_term_data` VALUES ('efd659c5-fa51-4e59-8a6b-b947c802f1a7', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队专业训练', '导弹部队各专业分队及人员进行的以专业理论和专门技能为主要内容的训练。', 74);
INSERT INTO `t_military_term_data` VALUES ('efdd55f2-c7b8-4958-8ac7-3dccdd4c3aa7', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆', '具有装甲防护能力的车辆。按用途,分为装甲战斗车辆和装甲保障车辆；按行动装置结构,分为履带武装甲车辆和轮式装甲车辆。', 81);
INSERT INTO `t_military_term_data` VALUES ('eff996e5-c29c-4505-bbab-bf788232bf70', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行导航设备', '用于飞行导航的各种技术设备的统称。按工作方式,分为自备式导航设备和他各式导航设备；按工作原理,分为无线电导航设备、惯性导航设备、天文导航设备和目视导航设备。', 361);
INSERT INTO `t_military_term_data` VALUES ('f00190ec-7d0e-416b-8e11-ddbfbf1038ca', '98df76fb-4b65-48ff-a56c-4db587327c79', '后勤体制', '军队后勤工作体系及相应制度。主要包括：后勤组织体制,后勤指挥体制,后勤保障体制,后勤教育训练体制,后勤科研体制等。', 6);
INSERT INTO `t_military_term_data` VALUES ('f0140091-c11a-48c9-8836-8aa94439dac0', '0', '战斗 .战术', NULL, 26);
INSERT INTO `t_military_term_data` VALUES ('f0178e9b-3537-4782-915f-309f23f774ab', '97a19170-bfac-42c5-9906-1acb187f0654', '航空兵战斗队形', '航空兵的若干架飞机或直升机在空中按一定规律排列所形成的队形。按形态,分为楔队、梯队、纵队、横队、蛇行队等队形；按疏密程度,分为密集队形、疏开队形和疏散队形。以便于战斗协同。', 45);
INSERT INTO `t_military_term_data` VALUES ('f025b7df-024b-4244-95ec-ce8ca7350577', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '摩托化部队', '陆军中能以建制内的轮式载重车辆实施机动的部队。是以摩托化步兵为主体的诸兵种合成部队。', 46);
INSERT INTO `t_military_term_data` VALUES ('f0286aa4-4a19-4db4-9876-90e4efd99ca4', '916997ee-6728-4c61-9b79-d96960b1dc86', '缓效性毒剂', '能使中毒人员经一至数小时后才出现毒害效应的毒剂。如芥子气、光气等。', 209);
INSERT INTO `t_military_term_data` VALUES ('f02bd81f-c478-44ff-b871-493bfb6aca1b', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '探雷针', '简称探针。以触及雷体的方式发现地雷的针状探雷器材。通常与单兵探雷器配合使用。作业时将探雷针逐次插入土、雪等覆盖物中,凭手感发现地雷。', 171);
INSERT INTO `t_military_term_data` VALUES ('f0338874-ddd8-4dfd-91b9-e7e9780ddc0c', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '进攻', '主动进击敌人的作战行动。是作战基本类型之一。包括战略、战役和战术范围的进攻。', 344);
INSERT INTO `t_military_term_data` VALUES ('f037b947-b7c3-4f29-8776-9832277b1aff', '97a19170-bfac-42c5-9906-1acb187f0654', '地空通信', '地面指挥机构与空中的航空器之间的通信。分为无线电地空通信和视觉信号地空通信。主要用以保障地面指挥人员对空中实施指挥引导和航空兵部队与地面部队的协同。', 351);
INSERT INTO `t_military_term_data` VALUES ('f0488bfe-c97f-420c-92d4-e04616c6fc19', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '拒爆', '点火后装药中的雷管未爆或雷管已爆但炸药未爆炸的现象。', 252);
INSERT INTO `t_military_term_data` VALUES ('f04a5abc-186f-4bd6-b690-7ecc9b8ac2b5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '自行火炮', '同车辆底盘构成一体,靠自身动力机动并能按指令发射的火炮。有轮式和履带式两种。机动性能好,行军与战斗转换速度快,多数有装甲防护,便于和坦克。步兵战车协同作战。', 19);
INSERT INTO `t_military_term_data` VALUES ('f05c6335-7bf5-4980-a3eb-65db01f6acbc', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '思想政治教育', '为提高军人政治觉悟和思想认识水平,培养革命精神,激励战斗意志而进行的教育。', 93);
INSERT INTO `t_military_term_data` VALUES ('f076e4a1-eb35-4d73-826b-0eead9505df7', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '马克思主义军事理论', '以马克思、恩格斯、列宁、毛泽东等为代表的无产阶级革命家关于军事问题的科学理论体系。是马克思主义的重要组成部分。基本内容包括辩证唯物主义的战争观和方法论,无产阶级在战争、和平与革命问题上的理论和策略,无产阶级建军和作战的指导原则等。', 10);
INSERT INTO `t_military_term_data` VALUES ('f077a724-3683-4c5a-82e0-194ee95de27a', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '遥控技术', '由控制机构通过传输信道,对远处被控对象发送指令实施控制的技术。军事上广泛应用于对飞机、靶标、导弹、炸弹和航天器等的遥控。', 19);
INSERT INTO `t_military_term_data` VALUES ('f07bd67c-8da5-4ea7-99bd-2752e999a850', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象要素', '表示和反映大气状态的物理量与天气现象。主要包括：气温、气压、湿度、风、能见度,日照、辐射、蒸发、凝结、冻结,以及云、降水、雷暴、风沙、龙卷等。观测所得的气象要素记录,是制作天气预报和气候预测,进行气候分析和科学研究,以及遂行气象保障的基础资料。', 11);
INSERT INTO `t_military_term_data` VALUES ('f0a52090-d2f5-417e-9af1-8fe7ff20f8b3', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '砂土', '土壤颗粒组成中砂粒含量较高的土壤。结构较疏松,粘结力小,通气透水性良好,雨天干燥快,不泥泞。但干燥季节,土质松软,影响人员和车辆通行；军队在破土地运动时速度降低,人员体力消耗增大,且不易构筑工事。', 86);
INSERT INTO `t_military_term_data` VALUES ('f0af68df-c0a1-48c1-b5cf-b5455badaa76', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹部队预备阵地作战', '导弹部队机动到预有准备的阵地上实施导弹突击的作战。是提高导弹部队反击能力和生存能力的重要措施。', 37);
INSERT INTO `t_military_term_data` VALUES ('f0b441b8-7795-4bff-8915-cf372f7c5957', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵执勤', '民兵在平时和战时执行勤务的活动。主要任务包括：担负边防、海防、防空观察哨,对铁路。桥梁、隧道、仓库等重要目标的警戒,以及协助维护社会治安等。', 139);
INSERT INTO `t_military_term_data` VALUES ('f0b53bad-89b7-4ff7-bf09-95a56da65b05', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克通过性', '坦克所具有的克服各种天然和人工障碍的能力。通常表现为克服坡道、壕沟、垂直墙、雪地、沼泽地、水稻田和水障碍等的能力。主要由坦克的外廓尺寸。重心位置、单位功率、单位压力、车底距地高以及坦克与地面作用的附着系数和阻力系数等因素决定。', 162);
INSERT INTO `t_military_term_data` VALUES ('f0b8f416-a9f9-432a-b8ca-b6a86dead7ab', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '微波统一系统', '共用一个载波信道、一套天线完成对航天器的测控和通信的微波跟踪测量系统。具有测轨、遥测、遥控、通信（数传）和传输电视图像等功能。', 275);
INSERT INTO `t_military_term_data` VALUES ('f0c0b8de-cab4-4de7-8817-ebe18e0a861c', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防空雷', '布设在空中或地面用以构成障碍物以对付低空和超低空飞行目标的爆炸性武器。分为空飘雷和空抛雷。', 157);
INSERT INTO `t_military_term_data` VALUES ('f0cc4193-ae2d-47a7-961d-bf34bd2c9a03', '06a75831-13a1-4660-870a-455bb445336a', '通信保密', '为保障军事通信安全、防止泄密而采取的各种防护措施。包括信息保密、传递保密、通信设施保密、文件资料保密和通信人员管理等。', 144);
INSERT INTO `t_military_term_data` VALUES ('f0ccfaa0-71bc-4fe9-a992-4aae4818dded', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂扩散界', '毒剂云团自然扩散形成的对人、畜有伤害作用区域的边界。', 121);
INSERT INTO `t_military_term_data` VALUES ('f0d58d5e-5232-42f5-b8ca-faee9d133af3', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '防间保密', '中国人民解放军预防敌方间谍的破坏和窃取、刺探情报,保守党和国家军事机密的工作。', 142);
INSERT INTO `t_military_term_data` VALUES ('f0dfa118-7f9a-4ff6-8a5f-b59e9645b5ff', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '天亮', '太阳中心点升至当地地平线下7度的时刻（约在日出前半小时）。天亮时刻随日期和地理位置的不同而异,根据某地的地理坐标（经、纬度）和日期（月、日）,可按公式计算该地当日的天亮时刻,也可在专门编制的“天亮、天黑时刻表”中查算。', 146);
INSERT INTO `t_military_term_data` VALUES ('f0e65ac4-e305-4ae4-b981-7a10e53795d1', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '攻城打援', '在攻城的同时歼敌援军。', 232);
INSERT INTO `t_military_term_data` VALUES ('f0f30689-f82e-429e-b0f9-8a6816b300d0', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '卫星侦察', '使用有侦察设备的人造地球卫星进行的侦察。如卫星成像侦察、卫星电子侦察、卫星导弹预警、卫星海洋监视等。', 32);
INSERT INTO `t_military_term_data` VALUES ('f0f34031-0044-4127-9576-5423b1dcf997', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '休整', '部队利用作战或执行其他任务的间隙进行的休息、整顿和训练。', 412);
INSERT INTO `t_military_term_data` VALUES ('f10b0efa-fe27-426b-b880-d669f8622fb4', '8a761efd-50a6-4ac8-9913-b7d745104f82', '压制射击', '给敌生动目标或武器装备以部分毁伤,迫使其暂时丧失战斗力、机动受到限制或指挥遭到破坏的射击。通常要求对暴露的集群生动目标的杀伤数量达到50％以上。', 99);
INSERT INTO `t_military_term_data` VALUES ('f11db2a9-84b0-4448-b701-f9775aa89e58', '8a761efd-50a6-4ac8-9913-b7d745104f82', '最大弹道高', '弹道最高点到火身口水平面的垂直距离。', 28);
INSERT INTO `t_military_term_data` VALUES ('f1339919-585f-4b44-b896-f7c35caf569e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '教练坦克', '专供部队或院校训练用的坦克。为保持部队的战备水平,用作教练坦克的数量应按规定的比例。通常将剩余摩托小时最少的坦克作为教练坦克。', 189);
INSERT INTO `t_military_term_data` VALUES ('f13537ba-6ef3-4eda-9c26-73cd4807b6c0', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '团支部', '团的基层组织。中国共产主义青年团在中国人民解放军连队或相当于连级的单位设立的支部。由共青团员大会选举产生,经本级党支部同意,报上级团组织批准。在上级团组织、本级党支部的领导下和本级首长的指导下进行工作。', 51);
INSERT INTO `t_military_term_data` VALUES ('f1398e0d-c430-4d55-9780-7be8934ee271', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '营', '由若干个连编成的军队一级组织。通常隶属于团或旅。为高级战术分队。', 19);
INSERT INTO `t_military_term_data` VALUES ('f13d1a0c-fbab-4c4d-883c-472221d41a2b', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '反干扰战术', '反电子干扰战术的简称。在敌方实施电子干扰时,为完成己方电子设备所担负的作战任务而采取的战术措施和行动。主要有：将不同频率、各种体制的雷达进行组网,以发挥整体抗干扰能力；综合运用各种探测和通信手段；设置隐蔽电子设备台站（网）和复式电子设备；用火力摧毁干扰源等。', 99);
INSERT INTO `t_military_term_data` VALUES ('f1505b65-78ed-4668-ba58-c99353fede1f', 'd7132c58-5df3-4b97-919f-58740148b9ca', '跟踪空中目标', '防空兵部队或分队对空中目标实施的追随瞄准与观察。有手控跟踪、半自动跟踪、自动跟踪和混合跟踪等。', 216);
INSERT INTO `t_military_term_data` VALUES ('f15cb455-10eb-4100-860a-0059f682e316', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役进程', '战役进行的过程。通常指战役活动所经历的时空跨度。', 34);
INSERT INTO `t_military_term_data` VALUES ('f15d913c-e3fb-4408-a22b-2a2aadaabe2a', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '干部四化', '干部队伍建设实现革命化、年轻化、知识化、专业化。是中国共产党在社会主义现代化建设新时期干部队伍建设的总方针,也是中国人民解放军新时期干部队伍建设的总方针和总目标。革命化,指干部应具有正确的政治立场和政治态度,良好的道德品质和思想作风；年轻化,指干部年富力强,身体健康,能够适应紧张繁重的工作任务,领导班子年龄结构合理,形成梯次配备；知识化,指干部应具为与履行本职工作相适应的文化素质和知识水平；专业化,指干部应具有本行业的专门知识和技能,精通本职业务。', 80);
INSERT INTO `t_military_term_data` VALUES ('f15f8217-7ef8-4016-9f62-a5bd7fbde7c4', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜地导弹', '由潜艇水下发射,用以攻击陆上固定目标的战略导弹。分为弹道潜地导弹和巡航潜地导弹。其隐蔽性、机动性好,生存能力强,便于实施突然袭击。主要用以袭击敌政治和经济中心、交通枢纽、重要军事设施等战略目标。', 192);
INSERT INTO `t_military_term_data` VALUES ('f161987e-cbce-421b-9b86-7b20bb222671', '98df76fb-4b65-48ff-a56c-4db587327c79', '军工企业', '以军品生产为主、实行独立核算并具有法人资格的了业生产单位。', 162);
INSERT INTO `t_military_term_data` VALUES ('f164e84f-5299-4627-b63e-a1d17270d1e5', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '纬差', '地面两点的纬度值之差。', 207);
INSERT INTO `t_military_term_data` VALUES ('f172f084-fb84-446b-aef6-fa39db9a67ee', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '指挥原则', '军队指挥活动所依据的法则或标准。', 2);
INSERT INTO `t_military_term_data` VALUES ('f179c82c-82a4-4a7c-9092-86a9749bbab9', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '桥轴线', '桥梁车行道（通行道）的纵向中心线。架设桥梁时首先标定桥轴线,作为架设作业的基准线。', 293);
INSERT INTO `t_military_term_data` VALUES ('f180a730-1ce8-4089-bdad-a6fe2ad52a4a', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '固定装备', '配置于一定位置不能伴随部队运动的装备。相对于野战装备而言、如在海防、边防和要地上设置的固定的重型火炮、雷达,战略导弹部队的固定发射装置等。', 84);
INSERT INTO `t_military_term_data` VALUES ('f1a06754-f8fd-442c-b804-e011b855a344', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '接合部保障', '为确保接合部的安全而明确的保障责任及其措施。通常应明确作战分界线上各点及其连线的保障责任,并要求以兵力、火力、障碍等措施对接合部的安全实施保障。', 286);
INSERT INTO `t_military_term_data` VALUES ('f1a68212-6c05-4d98-bf60-1ba03b18d656', '0', '军事训练', NULL, 17);
INSERT INTO `t_military_term_data` VALUES ('f1a881d9-018d-47d2-bf56-f11faf972426', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '核武器引爆控制系统', '简称引控系统。能在预定高度或预定时刻准确、可靠地引爆核装置,并能按预定程序发出各种预定的控制信号,保障核武器在操作、运载、投放过程中具有高度安全性的控制系统。通常由电源、保险机构、程序控制装置、引信、引爆装置等组成。', 126);
INSERT INTO `t_military_term_data` VALUES ('f1b6308d-eeaa-420a-920a-e84645330647', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队司法行政工作', '中国人民解放军为辅助和保障国家在军队内部行使司法权所进行的专门管理工作。主要包括对律师、公证和基层法律服务工作等的管理。', 134);
INSERT INTO `t_military_term_data` VALUES ('f1bce446-6ffc-44fc-be8b-814fb7a36b8b', '06a75831-13a1-4660-870a-455bb445336a', '人民防空通信', '简称人防通信。为保障城市人民防空而建立的通信联络。包括人防情报、警报通信和人防指挥通信。主要任务是：及时传递空袭。情报,发放警报信号,保障人防指挥机关在防空指挥中的通信联络。电信、广播。电视等部门应优先传递防空警报信号和指挥号令。', 21);
INSERT INTO `t_military_term_data` VALUES ('f1c2b819-2c56-426e-94e2-b213e98e3d69', '98df76fb-4b65-48ff-a56c-4db587327c79', '物资供应站', '负责工业品生产资料供应和管理的后勤机构。主要任务是：办理所在区域内部队所需计划分配物资和自由购销物资的供应业务；平时了解所在地区主要物资资源状况,做好动员准备；战时协助地方支前机构组织支前物资供应。', 105);
INSERT INTO `t_military_term_data` VALUES ('f1d9c4e8-b26b-4f4a-9b47-f014a1623887', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '枪代炮射击训练', '把枪支固定在火炮身管上或身管内,以发射枪弹代替发射炮弹的炮兵射击训练。通常在炮兵指挥员进行射击练习和分队进行直接瞄准射击训练时采用。', 129);
INSERT INTO `t_military_term_data` VALUES ('f1e4528f-20e7-4202-b2c0-c6058a09cf2d', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '水深', '水面到水底的垂直距离。海图上的水深注记是指深度基准面至海底的垂直距离,地形图上江河湖泊的水深注记是指最低水位或设计水位到江河湖底的垂直距离。', 70);
INSERT INTO `t_military_term_data` VALUES ('f1f67e72-7977-469b-beed-17c3961b948d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '逐批转移火力', '防空兵火力单位对两批或两架以上连续进袭的敌机逐批或逐架进行射击。通常在敌机批与批或架与架的间隔时间大于该火力单位射击周转时间时采用。', 90);
INSERT INTO `t_military_term_data` VALUES ('f1f706f9-2ef8-4d00-91c8-3a849b7a6c9b', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '水船', '专门用以载运和补给淡水、蒸馏水的勤务舰船。', 150);
INSERT INTO `t_military_term_data` VALUES ('f1f80cdd-8673-4ebc-9e0c-4961ae403ef6', '97a19170-bfac-42c5-9906-1acb187f0654', '雷达探测范围', '雷达能够发现目标的空间范围。其大小取决于雷达性能、阵地地形、气象条件以及目标的高度、大小和反射特性等因素。一般用雷达最大探测距离的曲线图表示。是使用和部署雷达的重要依据。', 394);
INSERT INTO `t_military_term_data` VALUES ('f203207c-88a5-4e5d-8d50-c877f3269398', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '边防', '国家为保卫主权、领土完整和安全,防御外敌入侵,在边境地区进行的防卫和管理活动的统称。', 101);
INSERT INTO `t_military_term_data` VALUES ('f203debc-59b7-47a0-a692-6414366cefdf', '8a761efd-50a6-4ac8-9913-b7d745104f82', '机枪', '以枪架（座）或两脚架为固定依托的连发枪。主要用于较远距离上歼灭或压制生动目标,口径大的机枪可对付薄壁装甲目标及低空目标。按技术性能分，为轻机枪、而机枪通用机枪以及高射机枪等。可携行或安装在装甲车辆、飞机舰艇等载体上。', 166);
INSERT INTO `t_military_term_data` VALUES ('f206c887-57dc-4f1f-a931-3147ca764987', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '乘机战斗', '步兵或空降兵乘载直升机,以随身携带的武器从空中射击地面或水面目标的战斗。通常以直升机的机舱窗口和舱门作为射击孔。', 75);
INSERT INTO `t_military_term_data` VALUES ('f2085f26-0d84-466e-bd0d-c8a92aa1e74a', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '进攻直前', '发起进攻前的短暂时间。', 94);
INSERT INTO `t_military_term_data` VALUES ('f209f918-ff65-4008-92a6-823116ad4313', '878651de-adf5-4c72-9376-9c363b893ff8', '战争原因', '引发战争的条件。是战争根源在一定历史条件下的具体表现。如领土争端、民族矛盾、宗教纠纷等。', 4);
INSERT INTO `t_military_term_data` VALUES ('f20dae67-73cf-43ea-871c-1e806d2d26f5', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '末制导', '亦称末段制导。在接近目标的飞行段（弹道末段）进行的制导。一般采用寻的制导或图像识别制导。', 58);
INSERT INTO `t_military_term_data` VALUES ('f21c9282-38b2-4bbc-a401-2531bd58f9d6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地理位置', '地球表面某一地区或地点与周围的自然现象和人文现象的空间关系。分为数理地理位置、自然地理位置,经济地理位置和军事地理位置。', 3);
INSERT INTO `t_military_term_data` VALUES ('f229978b-11a1-4cfa-ba18-f676ca6383cb', 'f0140091-c11a-48c9-8836-8aa94439dac0', '待机地域', '部队为组织和准备进攻战斗而占领的待机出动地域。通常选择在具有良好的隐蔽条件和便于进出与机动的地域。', 63);
INSERT INTO `t_military_term_data` VALUES ('f22d6118-c3b1-4fd1-9cff-9e348a030f1b', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '以战斗力为标准', '以提高作战能力作为衡量部队建设水平的根本标准。', 125);
INSERT INTO `t_military_term_data` VALUES ('f238471a-4d97-4de3-9bb9-d0194d7904d0', '06a75831-13a1-4660-870a-455bb445336a', '光中继器', '将传输过程中变形的光脉冲信号恢复原状的通信设备。设置在光缆通信线路上,用以放大光信号,延长通信距离。', 196);
INSERT INTO `t_military_term_data` VALUES ('f242ed22-a40e-4272-82ae-c02813a17fc3', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克中等损坏', '坦克一、两个主要部件损坏或较多的非主要机件损坏,不能完成规定功能的故障状态。通常可由师坦克抢修所修复。', 205);
INSERT INTO `t_military_term_data` VALUES ('f24354ed-4246-40b9-8bcd-fc320202029b', '8a761efd-50a6-4ac8-9913-b7d745104f82', '警棍', '用于自卫和指挥的专用制式手持棍棒。通常由木材或橡胶制成。有的警棍兼有电击器、喷雾器或发射器功能可发射催泪弹、染色弹等。', 190);
INSERT INTO `t_military_term_data` VALUES ('f244d6f5-1d2b-4e0e-a138-4c7554682141', 'f0140091-c11a-48c9-8836-8aa94439dac0', '防空火力', '亦称对空火力。主要用以打击敌空中目标的火力。通常包括地空导弹、舰空导弹、高射炮、高射机枪等的火力。', 83);
INSERT INTO `t_military_term_data` VALUES ('f24c2bc6-e74d-4fd7-a625-175be2b80c36', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察手段', '获取情报所采用的具体方法与措施。如观察、捕俘、无线电侦听、无线电侦收、无线电测向、照相侦察、雷达侦察、战斗侦察等。', 29);
INSERT INTO `t_military_term_data` VALUES ('f24dcd73-3c54-40ae-8f8c-ac64061de128', 'f0140091-c11a-48c9-8836-8aa94439dac0', '滩头阵地', '设置在岸滩的防御阵地。用以抗击敌人登陆。', 230);
INSERT INTO `t_military_term_data` VALUES ('f253a18c-65b2-4265-bd70-a7a036710d0d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '野战给水站开设', '战时部队在有水源的地点构筑和设立给水站的过程。通常包括：构筑接近路和取水构筑物,准备水处理作业场地、停车场和洗涤场,构筑防护工事、设置给水器材,实施伪装和管理给水站等。', 359);
INSERT INTO `t_military_term_data` VALUES ('f25f4895-d2f0-4c30-a16c-9871420aa4e5', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '冲击波超压', '核爆炸冲击波内超过正常大气压的压力。常用的超压值,系指冲击波阵面（压缩区的前界面）上的最大超压。可引起人畜的心、肺和听觉器官的损伤。', 158);
INSERT INTO `t_military_term_data` VALUES ('f26097d6-8a82-49d1-b4d0-3b55ecbf384f', '916997ee-6728-4c61-9b79-d96960b1dc86', '淋浴车', '供遭受放射性沾染和消毒后的人员进行全部洗消的专用车辆。可利用车上的设备将冷水加热至适当温度后,送入淋浴间或淋浴帐篷供人员洗消使用。', 191);
INSERT INTO `t_military_term_data` VALUES ('f2628580-903e-4d6a-92e5-a7b08bcbb8bd', 'f0140091-c11a-48c9-8836-8aa94439dac0', '匍匐前进', '单兵身体贴近地面,以手臂和腿的合力推动身体前进的动作。分为低姿、高姿、侧身三种姿势。通常在受敌火力威胁,遮蔽物较低时采用。', 112);
INSERT INTO `t_military_term_data` VALUES ('f26c499d-9554-462a-9371-4098b83a5f38', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '红外告警设备', '用以实时探测、识别敌方来袭目标的红外辐射信号,并能立即发出警报信息的光电对抗设备。通常安装在飞机、舰船、坦克等兵器上,并与电子干扰系统和武器控制系统交联,以便及时对来袭目标采取有效的对抗措施。', 117);
INSERT INTO `t_military_term_data` VALUES ('f2776985-d309-4b5f-871d-c7d87ad05a12', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上指挥所', '开设在舰艇上的指挥所。主要担负对海上兵力的直接指挥。通常开设在专门的指挥舰上,也可开设在航海机动性能好、装有指挥自动化系统、舱室宽敞、防护能力较强的舰艇上。', 118);
INSERT INTO `t_military_term_data` VALUES ('f29ba3ee-36d3-4e0b-89a4-7b99a23d3bef', '916997ee-6728-4c61-9b79-d96960b1dc86', '移动烟幕', '发烟正面不断移动的烟幕。施放烟幕时,发烟地域随发烟器材移动或发烟炮火转移而变化。', 78);
INSERT INTO `t_military_term_data` VALUES ('f29d3f35-9a95-4e14-b0e1-51a47d60a2bd', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机水上漂浮性能', '为保证乘员安全离机,直升机在非正常降落于水面时所具有的在水面漂浮一定时间的特性与功能。', 17);
INSERT INTO `t_military_term_data` VALUES ('f29e4ed2-3746-4bab-a3b0-725d328523f7', '97a19170-bfac-42c5-9906-1acb187f0654', '空勤特种服装', '空勤人员在飞行时着用的具有特殊性能的制式工作服装。包括飞行服、高空代偿服、抗荷服、通风服、液冷服以及与其配套使用的飞行头盔。飞行帽、飞行靴、飞行风镜等。', 404);
INSERT INTO `t_military_term_data` VALUES ('f2b94c9a-343e-4bfc-b4c4-a67ff8dc60e8', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '自卫反击作战', '亦称自卫还击作战。为保卫国家主权、领土完整和安全,回击侵犯之敌的作战。', 191);
INSERT INTO `t_military_term_data` VALUES ('f2baff2c-d20d-4610-a72d-9ac319ff54a4', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机进场着陆系统', '为飞机进场着陆提供方位偏差、下滑角偏差和距离信息的全套无线电导航设备的统称。由机上导航设备和机场导航设备组成。分为双信标着陆系统、仪表着陆系统、雷达引导着陆系统、微波着陆系统等。', 339);
INSERT INTO `t_military_term_data` VALUES ('f2bf6316-b41f-48c2-b25b-56d10c814530', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '号令', '指挥军队行动的命令和指示的统称。', 122);
INSERT INTO `t_military_term_data` VALUES ('f2cb3e04-5390-4cf4-bf5b-9f9f0a2541d7', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战例研究', '对战争、战役、战斗的实例进行分析研究。', 107);
INSERT INTO `t_military_term_data` VALUES ('f2d030ac-56b2-4cae-b7bd-e1b56b07b070', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '保密守则', '领导机关制定和颁布的要求全体人员必须共同遵守的保守秘密的行为准则。', 74);
INSERT INTO `t_military_term_data` VALUES ('f2d36145-98fc-4f81-846e-90a59d8fa2c6', '06a75831-13a1-4660-870a-455bb445336a', '中波通信', '波长为 1000～100米（频率为300～3000千赫）的无线电通信。其频段高端常用于近距离战术通信,频段低端可用于地下通信和海上通信。', 101);
INSERT INTO `t_military_term_data` VALUES ('f2d53279-ab92-42d7-81ad-838f5ac208f7', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空雷达情报处理', '对各雷达情报站传来的所有空中目标点迹和航迹进行综合处理。包括目标性质验证,统一编批,判断来袭目标的威胁程度,确定报知范围等。', 115);
INSERT INTO `t_military_term_data` VALUES ('f2d866a2-05ee-4ce2-8744-d90863cece81', '31f4a446-5b98-4873-9d53-310d97125b07', '战略核力量运用', '为达到特定的战略目的而对战略核力量的筹划和使用。包括战略核威慑运用和战略核反（突）击运用。是核战略的重要内容。', 9);
INSERT INTO `t_military_term_data` VALUES ('f2dfcccb-dbb6-4d6a-84f2-b7850d9e946d', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '上浮水雷', '布设在水底,当舰船通过时在舰船物理场作用下,其火箭发动机自动点火,使雷体上浮攻击目标的非触发水雷。', 215);
INSERT INTO `t_military_term_data` VALUES ('f2e60adc-946f-4327-bafd-f3e4a01cfb24', '98df76fb-4b65-48ff-a56c-4db587327c79', '消耗预计', '根据消耗标准和经验数据,结合作战任务情况对物资消耗量所作的预先估算。是制定物资供应计划,确定物资储备标准,规定物资消耗限额的依据。', 125);
INSERT INTO `t_military_term_data` VALUES ('f2ebb177-7cc0-4782-8172-118a10e233db', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '地球静止卫星轨道', '简称地球静止轨道。轨道周期与地球自转周期（23时56分4秒）相等。倾角为0度,圆形的人造地球卫星轨道。通信卫星、广播卫星和气象卫星等一般都采用静止卫星轨道。', 237);
INSERT INTO `t_military_term_data` VALUES ('f2f20688-f9cd-40bb-aeaa-b99c460bd249', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军队宗旨', '军队的建立、建设与一切行动的最高准则和根本目的。中国人民解放军的唯一宗旨是紧紧地和人民站在一起,全心全意地为人民服务。', 2);
INSERT INTO `t_military_term_data` VALUES ('f2f3bf0e-fef7-480f-abe9-4db0b169d248', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '计曲线', '亦称加粗等高线。从高程起算面起,在地形图上每隔4条首曲线加粗的一条等高线。便于在图上查算某点高程。', 282);
INSERT INTO `t_military_term_data` VALUES ('f303613d-eb88-4034-9c62-37bf58ef5471', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '军事航天', '人类借助航天器在地球大气层以外的空间进行的军事性质的活动。主要包括：航天遥感侦察、航天电子侦察,导弹预警,海洋监视,核爆炸探测,军用卫星通信。军用卫星气象观测,军用卫星导肮,军用卫星测地与测绘,航天防御与攻击以及航天勤务保障等。', 196);
INSERT INTO `t_military_term_data` VALUES ('f31c8905-ce37-450a-914a-932005da5ddb', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '初步决心', '亦称预先决心、指挥员对作战目的及行动作出的初步决定。以便指挥机关及时研究作战计划提出建议', 76);
INSERT INTO `t_military_term_data` VALUES ('f3238139-751c-4d26-a7e1-6bc0fa2f0bb5', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军种符号', '表明军人所属军种的标志。中国人民解放军陆、海、空军的军种符号均以“八一军徽”为体,分别衬以金黄色的宝剑形光芒线、铁锚和飞鹰两翅。规定佩戴在军衣领上。', 140);
INSERT INTO `t_military_term_data` VALUES ('f32ccd79-a7a7-48a6-8c91-85dc89bce484', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '雷达干扰模拟器', '能模仿一种或多种样式的雷达干扰信号的电子对抗训练设备。主要用于雷达操作人员的反干扰训练。', 142);
INSERT INTO `t_military_term_data` VALUES ('f3364f28-2237-41f1-a39d-852c98f0f1f1', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹命中精度', '导弹平均弹着点（散布中心）对瞄准点（目标中心）的偏差。通常用公算偏差或圆公算偏差表示。', 148);
INSERT INTO `t_military_term_data` VALUES ('f34e64ab-3f2c-4139-883b-86b1e0972ebb', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上扫雷', '使用扫雷具扫除水雷的战斗行动。按战术目的,分为导航扫雷、检查扫雷和清除水雷障碍；按扫雷兵力,分为水面舰艇扫雷和直升机扫雷；按使用的扫雷具,分为接触扫雷和非接触扫雷。', 111);
INSERT INTO `t_military_term_data` VALUES ('f35fa866-4269-4458-874b-1afbdcfb6788', 'f0140091-c11a-48c9-8836-8aa94439dac0', '排除障碍', '作战中排除敌方人工或天然障碍物的行动。包括在敌防御前沿前障碍场中开辟通路和在机动时排除各种障碍物。', 188);
INSERT INTO `t_military_term_data` VALUES ('f365458c-3421-4ab6-9453-4b09dc417585', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '海冰', '海洋上出现的各种冰的统称。包括由海水冰结而成的咸水冰和来自陆地的淡水冰。按其运动状态,分为固定冰和流冰。漂浮在海上高出海面5米以上的巨大冰体称为冰山。', 126);
INSERT INTO `t_military_term_data` VALUES ('f367aea9-5fb7-4b8e-b1de-56bfc89eba4f', '916997ee-6728-4c61-9b79-d96960b1dc86', '发烟弹药', '装有发烟剂的弹药。包括发烟炮弹、发烟航空炸弹、发烟火箭弹、发烟手榴弹和发烟枪榴弹等。', 243);
INSERT INTO `t_military_term_data` VALUES ('f367f569-2f6d-4b76-8e0b-ae151b806c37', '06a75831-13a1-4660-870a-455bb445336a', '通信兵战术', '通信兵在战斗中遂行任务的方法。主要包括通信联络基本原则、通信兵指挥、通信手段的组织运用、通信对抗以及通信系统的防护、管理和技术保障措施等。', 27);
INSERT INTO `t_military_term_data` VALUES ('f3804809-c6f1-4837-8e63-9103db9284e3', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '示范作业', '对受训或见学人员演示规范的动作和科学的训练方法的教学活动。通常运用于新的、难度大的课目或重点课目训练,一般由上级指挥员或机关组织实施。', 150);
INSERT INTO `t_military_term_data` VALUES ('f380e4e8-6439-45be-8595-feab52ac5d0c', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '开辟战场', '战争中,在尚未发生交战的地区主动对敌实施攻击而形成新的战场的行动。如第二次世界大战中盟军在诺曼底登陆,开辟了欧洲第二战场。', 173);
INSERT INTO `t_military_term_data` VALUES ('f39872c0-4044-46fb-b7fd-2a2692a44ad2', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役集团', '亦称战役集群。战役编成内,为担负某一战役作战任务而临时编组的兵力集团。如突击集团、阻援（打援）集团、守备集团等。', 42);
INSERT INTO `t_military_term_data` VALUES ('f3af6992-f87d-4c63-b8ab-61bb434e601c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军人违反职责罪', '中国人民解放军和中国人民武装警察部队的官兵与文职人员违反军人职责,危害国家军事利益,依照中华人民共和国惩治军人违反职责犯罪条例应受刑罚处罚的行为。', 135);
INSERT INTO `t_military_term_data` VALUES ('f3bd0b01-0a47-4e2f-913c-6aec0f118043', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '地面共振', '直升机在地面滑行、滑跑或试车过程中由于共振作用而发生的振幅越来越大的现象。如不及时采取措施制止,将会造成直升机的损坏。', 51);
INSERT INTO `t_military_term_data` VALUES ('f3c5ddec-4fa9-4aad-bc31-6d3d9fa9261a', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克撞击', '以坦克车体向敌坦克和其他目标实施冲撞的战斗行动。一般在不能用其他手段毁伤目标的紧急情况下采用。', 31);
INSERT INTO `t_military_term_data` VALUES ('f3c88681-66a4-4b7c-b3b6-8ba451ad19fd', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '收炮', '将火炮由战斗状态转换为行军状态的过程。', 270);
INSERT INTO `t_military_term_data` VALUES ('f3cf5df9-ac49-4f91-8b64-6c8f49cc1f98', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '领陆', '主权国家国界以内的陆地（包括岛屿）地域。是国家领土的基本组成部分。', 70);
INSERT INTO `t_military_term_data` VALUES ('f3d3ddaa-3130-4bb0-b28a-9f507f9695be', '97a19170-bfac-42c5-9906-1acb187f0654', '航空火力准备', '航空兵部队在己方地面部队进攻前或冲击前对敌目标实施的航空火力突击。通常与炮兵等火力准备结合进行,也可单独进行。', 123);
INSERT INTO `t_military_term_data` VALUES ('f3da2977-adc5-40be-85cb-d3435c2bf10f', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克战术技术性能', '由设计、制造等因素决定的坦克所具备的固有特性和功能。主要包括：火力性能、机动性能、防护性能,可靠性、维修性、环境适应性和经济性等。', 150);
INSERT INTO `t_military_term_data` VALUES ('f3dca2da-d755-4fe3-901e-92b5b0b83e6f', '878651de-adf5-4c72-9376-9c363b893ff8', '战争实力', '可直接用于战争的现实力量。是战争赖以进行并对其进程和结局具有重大影响的物质基础。主要包括军队、后备力量以及武器装备、战争物资等。', 38);
INSERT INTO `t_military_term_data` VALUES ('f3dde3af-6bf5-4aeb-a668-38aaec28415f', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '专业侦察', '军队中专门担负侦察任务的单位和人员进行的侦察。', 9);
INSERT INTO `t_military_term_data` VALUES ('f3e74fb0-42a5-4304-8e4f-e33f4259155a', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克武器系统', '坦克武器及其火控系统的统称、用以发现、跟踪、瞄准和摧毁目标。', 110);
INSERT INTO `t_military_term_data` VALUES ('f3fc1eb5-d7b3-4a6d-976e-064bc3372f7e', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克弹药', '供坦克武器发射用的各种弹药的统称。主要包括坦克炮弹和坦克机枪弹。坦克炮弹有穿甲弹、破甲弹、杀伤爆破弹和碎甲弹等。有的坦克还配有炮射导弹。', 118);
INSERT INTO `t_military_term_data` VALUES ('f4017aee-d5d1-487b-9fb7-d1a523081def', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '防线', '①军队防守的绵亘的横向线状地区。有的由筑垒配系构成。②战役军团占领的横向线状防御地区。根据规模及其任务,通常集团军防守1道防线,每道防线由2～3道防御地带构成。', 125);
INSERT INTO `t_military_term_data` VALUES ('f404672b-5d89-493d-8ef5-7cf86f5f6b0f', '916997ee-6728-4c61-9b79-d96960b1dc86', '三防装备', '专门用于对核、化学、生物武器袭击实施防护的装备。按用途,分为观测、侦察、防护、洗消和预防急救器材等装备；按使用对象,分为合成军队使用的群防装备和防化部（分）队使用的专业装备。', 150);
INSERT INTO `t_military_term_data` VALUES ('f40e1a7b-9b9d-4475-8418-42f54e0a1589', '916997ee-6728-4c61-9b79-d96960b1dc86', '射线指示仪', '发现和概略测量γ和 a辐射的核辐射剂量探测仪器。用以发现放射性烟云到达和沾染的边界,概略测量沾染地域内的γ照射量率（或吸收剂量率）,监测物体表面放射性沾染是否超过限值。供合成军队使用。', 158);
INSERT INTO `t_military_term_data` VALUES ('f40e6987-a824-4920-82b8-8a25934c4ee3', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮弹道高', '火炮弹道上的某一点到炮口水平面的垂直距离。', 249);
INSERT INTO `t_military_term_data` VALUES ('f40fbe60-404e-4183-b8b6-c1b22957cbad', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '环形部署', ' 能抗击多方向进攻的环状防御作战部署。', 96);
INSERT INTO `t_military_term_data` VALUES ('f421ff65-2920-4ca7-92fe-100220a767d0', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象观测', '亦称大气探测。对大气的物理、化学特性和大气现象进行的观察和测量。通常分为地面气象观测和高空气象观测。观测项目主要包括：气温、气压、湿度、风向、风速,云、能见度、辐射、日照、以及降水、雷暴、沙暴、积雪等。气象观测是获取大气信息的基本手段,是制作气象预报、实施气象保障和科学研究的基础。', 63);
INSERT INTO `t_military_term_data` VALUES ('f42fe290-102c-4a51-869e-3c66da589368', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '拉火管', '用以点燃导火索的管状火具。通常由管壳（纸壳、塑料壳或金属壳）、火帽、金属拉火丝和拉火柄（拉环）组成。有的还有保险销。', 217);
INSERT INTO `t_military_term_data` VALUES ('f435d9fd-f869-44f4-ad15-be4c39dd4086', '8a761efd-50a6-4ac8-9913-b7d745104f82', '装甲防暴车', '有薄壁装甲防护,配有防暴武器弹药和有关仪器设备的专用车辆。', 188);
INSERT INTO `t_military_term_data` VALUES ('f44bb016-59af-4c0f-aaa8-66bf1bc81866', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '水文测验', '水文要素的观测、水文资料的收集与整理等技术工作的统称。主要包括：水文站网布设,水文测验方法研究和技术标准制定,水文测验仪器设备研制,水文测站上的观测,巡回测验和水文调查,以及水文资料整理与汇编等。', 120);
INSERT INTO `t_military_term_data` VALUES ('f44c6a1c-cec6-478e-ac17-72a8eea6a86f', 'f0140091-c11a-48c9-8836-8aa94439dac0', '值班火器', '担负值班任务、处于准备发射状态的火器。用以对付突然发生的情况。', 106);
INSERT INTO `t_military_term_data` VALUES ('f44c9a3d-87ba-4798-b879-067f32e6534a', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上禁区', '沿海国在主权管辖的海区内划定的禁止或限制某些活动的水域。包括禁航区、禁锚区和禁渔区等。分为永久禁区和临时禁区。根据武器试验和军事演习的需要,也可在公海上划定临时禁区。海上禁区通常由国家政府机关或军事当局批准并发表公告。', 290);
INSERT INTO `t_military_term_data` VALUES ('f4653fd0-8a9b-4be4-b655-cf3558230cc7', 'd7132c58-5df3-4b97-919f-58740148b9ca', '高炮集火射击', '高炮部队或分队在有效火力范围内集中两个以上火力单位的火力,同时对一个目标进行的射击。是高射炮兵火力运用的基本方法。', 168);
INSERT INTO `t_military_term_data` VALUES ('f47a97a0-b380-41c7-8e9e-9ae1e303804b', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵侦察地境', '炮兵观察所负责侦察的扇形区域。通常包括基本侦察地境和补加侦察地境。相邻的侦察地境应有一定的重叠。', 108);
INSERT INTO `t_military_term_data` VALUES ('f4802b75-3133-4fc2-8ca2-6b6d7025b6d0', '97a19170-bfac-42c5-9906-1acb187f0654', '歼击轰炸机', '以航炮、航空火箭、空空导弹和炸弹、空地导弹等为基本武器,兼有空战和轰炸能力的作战飞机。主要用于对敌战役战术纵深内的地面和水面目标实施轰炸和突击。', 283);
INSERT INTO `t_military_term_data` VALUES ('f4874b36-51f5-4899-bf72-a368240c1f76', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '便携式净水器', '可由单兵携带供小分队野战使用的净水器材。', 370);
INSERT INTO `t_military_term_data` VALUES ('f494763d-7a1d-4fde-878d-187caca09f1a', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机滑跑起飞', '直升机经地面滑跑而进行的起飞。多在直升机超载时采用。对起飞场地条件要求较高。', 38);
INSERT INTO `t_military_term_data` VALUES ('f4c86cd7-3801-49a6-b6ed-e0525b6ea6b1', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '纪念章', '为纪念有历史意义的事件和人物而制发的徽章。', 68);
INSERT INTO `t_military_term_data` VALUES ('f4cdabf8-27db-43e6-a113-b7018c415b09', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军', '军队徒步或乘坐建制内和配属的车辆沿指定路线进行的有组织的移动。按行军方式。分为徒步行军、摩托化行军和履带行军；按行军时速和每日行程,分为常行军和强行军。', 41);
INSERT INTO `t_military_term_data` VALUES ('f4d2ce83-6c03-4873-8834-ae6622e667ba', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '企图立案', '按照训练课题设想的敌对双方作战企图的总体方案。是编写基本想定的依据。', 108);
INSERT INTO `t_military_term_data` VALUES ('f4def91b-2961-487c-85f1-d3e0b346aa86', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '弹测法', '利用对试射点的试射成果,连测观察所和炮阵地的关系位置调制实弹连测射击图以决定射击开始诸元的方法。弹测法精度较好,通常用以决定目标射击开始诸元。', 147);
INSERT INTO `t_military_term_data` VALUES ('f4e8c1a5-a2b0-4d64-a336-9e4f19cefec8', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '子母炮弹', '母弹弹体内装有若干子弹的炮弹。炮弹飞至目标区上空,在时间引信作用下弹体爆裂,将子弹抛出。通常配用于大中口径火炮,多用以攻击面状目标。', 318);
INSERT INTO `t_military_term_data` VALUES ('f4ee338c-6be0-4b65-ad1c-3237b96cc868', '31f4a446-5b98-4873-9d53-310d97125b07', '目标抗压强度', '目标能够承受超压的能力。是表示目标结构强度的重要物理数据和目标工程防护能力的重要指标。国际标准单位为帕（牛／平方米）。', 196);
INSERT INTO `t_military_term_data` VALUES ('f4ee91ba-744b-4c82-9934-d0d9a157a00e', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹搜索指挥车', '装有对空中目标搜索、识别、跟踪及信息传输等设备,并能进行地空导弹射击指挥的专用车辆。主要用以完成导弹发射前的目标指示、火力分配、发射决策等任务。', 35);
INSERT INTO `t_military_term_data` VALUES ('f508c06a-0135-462b-963f-6c2c3e82f71e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上航渡', '①舰艇或舰艇编队从一地（海区）到另一地（海区）的航行。按舰艇数量,分为单舰（艇）航渡和编队航渡；按方式,分为集中航渡和分别航渡,直达航渡和分段航渡。②登陆作战的一个阶段。', 99);
INSERT INTO `t_military_term_data` VALUES ('f5195ff1-9023-40b9-9f7e-a2f2a0a4c0eb', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '高速公路', '供汽车高速（时速达120公里）行驶的一种现代化公路。有4个以上行车道,双向分隔行驶,出入口受控制,立体交叉,线路顺畅,纵坡较缓,路面质量高,沿线设有完备的安全与服务设施等。必要时部分路段可用作飞机起降的跑道。', 111);
INSERT INTO `t_military_term_data` VALUES ('f51bb686-c050-4eed-aeff-87fa4e132385', '06a75831-13a1-4660-870a-455bb445336a', '数据终端设备', '数据通信中用以发送和接收数据信号的用户设备。主要包括；键盘印字机、凿孔机、阅读机、磁带（盘）机和显示器等输入输出设备,计算机,智能仪表,以及其他专用设备。', 204);
INSERT INTO `t_military_term_data` VALUES ('f51e82dd-aa42-4512-a01c-8aaa40fbfaf6', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '两翼', '军队作战部署的左右两边。以面向敌方为准,左边为左翼,右边为右翼。', 283);
INSERT INTO `t_military_term_data` VALUES ('f52dc1fc-08d7-4d13-ac1c-a94aec69bdb7', '916997ee-6728-4c61-9b79-d96960b1dc86', '群众性洗消', '由受染部队或人民群众自行组织实施的洗消。可利用装备的洗消器材,也可用就便器材、设施进行洗消。必要时防化兵洗消分队可给予协助和指导。', 61);
INSERT INTO `t_military_term_data` VALUES ('f52f799d-3481-4f52-853e-70d84b5248a7', '97a19170-bfac-42c5-9906-1acb187f0654', '空空导弹', '从空中发射,用以攻击空中目标的导弹。分为格斗空空导弹和拦射空空导弹。是歼击机的主要空战武器,也可作为强击机、歼击轰炸机的自卫武器。', 315);
INSERT INTO `t_military_term_data` VALUES ('f53082bb-5c55-40ad-a95a-aca11e34597b', '98df76fb-4b65-48ff-a56c-4db587327c79', '陆军侦察艇', '陆军编配的专门用以在沿海执行侦察任务的艇。艇上装有多频段无线电接收机和侦察雷达等。', 329);
INSERT INTO `t_military_term_data` VALUES ('f533f5c5-b73e-486a-9dce-41f4f9d28dd0', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战控制', '指挥员及其指挥机关对所属的部队和分队作战行动的掌握与制约。', 105);
INSERT INTO `t_military_term_data` VALUES ('f549c4b3-a494-4065-83b6-ddd922db2fb5', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '濒海翼侧', '陆上部队的作战部署、行军队形、战斗队形或阵地靠海的一侧。濒海翼侧受敌海上威胁时,通常由海军兵力担任掩护和支援。', 381);
INSERT INTO `t_military_term_data` VALUES ('f54a473f-01b7-4121-8c53-6ff62190a752', '06a75831-13a1-4660-870a-455bb445336a', '程控电话交换机', '存储程序控制电话交换机的简称。利用电子计算机预先编制的程序控制通话接续的自动电话交换机。自动化程度高,接续速度快,效率高,功能多,使用方便、灵活。', 206);
INSERT INTO `t_military_term_data` VALUES ('f54f741f-9495-4374-b446-0d9c06395872', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克展开地区', '坦克分队展开成战斗队形发起冲击的地区。通常选择在敌方近程反坦克火器有效射程之外,便于坦克隐蔽、展开、观察和发起冲击的地形上。', 20);
INSERT INTO `t_military_term_data` VALUES ('f57a8edc-18f9-49fe-a6a0-01d1810f926c', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天员训练', '对预备航天员在体格、航天技能等方面进行的一系列训练。目的是提高受训人员对航天环境的适应能力,熟练掌握航天技术和操作技能,胜任航天任务。包括一般性训练、航天环境因素适应性训练、模拟飞行训练等。预备航天员在完成训练内容,经审议合格后,方可成为航天员参加航天飞行。', 292);
INSERT INTO `t_military_term_data` VALUES ('f58f4548-08c7-4df3-b7a6-8e4d8205c2e9', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '合同战役', '以一个军种或兵种为主并在其统一指挥下,由其他军兵种直接配合进行的战役。包括军种之间和同一军种内诸兵种之间进行的合同战役。', 7);
INSERT INTO `t_military_term_data` VALUES ('f59b937f-8330-4581-a313-1413198a14fa', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '气象部（分）队', '突然发生、过程短暂、规模较小的武装冲突事件。可能是蓄谋的,也可能是偶然发生的。多指外来的武装袭击或边境武装冲突,有时也指国内敌对的武装集团之间突然发生的军事冲突。', 96);
INSERT INTO `t_military_term_data` VALUES ('f5a09a93-20ea-40cf-bc6a-df15ea70671d', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '触发地雷', '靠目标直接触动而发火的地雷。配用触发引信。如碰发地雷、压发地雷、绊发地雷、松发地雷等。', 134);
INSERT INTO `t_military_term_data` VALUES ('f5a217bd-267a-46f2-b7e8-94e8bfac9bf9', '06a75831-13a1-4660-870a-455bb445336a', '主台', '无线电网路和专向中的上级台。实施网路通信时,主台负有指挥、协调全网工作的责任。', 51);
INSERT INTO `t_military_term_data` VALUES ('f5b654bb-a06b-4940-9aa4-4a154324ff51', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地极', '地轴与地球表面相交的两点。在北半球的端点称北极,在南半球的端点称南极,为地面上的正北方和正南方。', 198);
INSERT INTO `t_military_term_data` VALUES ('f5b8bca6-acb3-4a31-ae6b-441cf95fad75', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '军舰访问', '军舰对他国进行的友好交往活动。分为正式访问和非正式访问。', 385);
INSERT INTO `t_military_term_data` VALUES ('f5ba5d62-2e2f-444c-80e2-fa0718e7fb77', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '腹地', '①远离边境的内陆地区。通常指国家的战略纵深。②交通线及其车站、港口客货集散所及的地区。', 106);
INSERT INTO `t_military_term_data` VALUES ('f5c55885-7618-45e4-b89d-9b43a1bc2d90', '916997ee-6728-4c61-9b79-d96960b1dc86', '刺激剂', '亦称防暴剂。主要用以刺激眼、鼻、喉及皮肤等感觉神经末梢的化学物质。包括催泪剂、喷嚏剂、复合型刺激剂等。如苯氯乙酮、亚当氏气、西埃斯、西阿尔等。使用时呈气溶胶或粉末状态,使人迅速出现流泪、喷嚏、咳嗽、头痛及皮肤灼痛等症状。', 223);
INSERT INTO `t_military_term_data` VALUES ('f5ccd345-a240-44a9-adc0-eef0aba7667e', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮最大弹道高', '火炮弹道最高点到炮口水平面的垂直距离。每条弹道都有相应的最大弹道高。', 255);
INSERT INTO `t_military_term_data` VALUES ('f5efcf97-9af4-4d50-b5f0-420e339ceff6', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上护航运输队', '由运输舰船和护航舰艇组成的担负海上运输任务的临时舰艇编队。按规模,分为大型护航运输队、中型护航运输队和小型护航运输队；按航速,分为快速护航运输队和慢速护航运输队；按航行海区,分为远洋护航运输队和近海护航运输队。', 66);
INSERT INTO `t_military_term_data` VALUES ('f5f3a6d2-d7c9-48c5-828e-00f3b53778fe', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '电子技术', '研制与使用电子器件、设备和电子系统所涉及的技术的统称。主要包括有线电和无线电技术、微电子技术、光电子技术、计算机技术等。对推动军队作战指挥、武器装备和后勤保障的现代化有重要影响。', 8);
INSERT INTO `t_military_term_data` VALUES ('f6037f09-9e27-4dd3-a052-065b87ce70e4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '无壳弹', '以发射药模压成可燃弹壳的炮弹。发射时可燃弹壳和发射药全部燃尽。', 321);
INSERT INTO `t_military_term_data` VALUES ('f60d69b8-367e-40c0-9cd1-55cb9d85d82f', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '防护密闭门', '带有密闭设施的防护门。具有防护门的功能,还能阻止放射性物质、毒剂、生物战剂等侵入工事内部。', 92);
INSERT INTO `t_military_term_data` VALUES ('f6131eec-5f6b-48cb-ade5-c41303f1ee10', 'f0140091-c11a-48c9-8836-8aa94439dac0', '梯形队形', '向侧后展开成阶梯式的战斗队形。分为左梯形队形和右梯形队形。通常在翼侧受敌威胁时采用。', 59);
INSERT INTO `t_military_term_data` VALUES ('f62fccc0-3bfc-4413-841e-38abb6c1eb5b', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '入轨点', '航天器进入运行轨道时的初始位置。也是运载火箭最后一级推力的终止点。', 258);
INSERT INTO `t_military_term_data` VALUES ('f63907b7-6ccc-49bc-96ea-ef09684b54bd', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '火力指数', '反映武器杀伤力和破坏力强弱的相对数。通常以某一单件武器在特定条件下发射弹药对目标所产生的毁伤效果作为基准,再将其他武器按照同样条件与之对比,其相对数即为该武器的火力指数。', 186);
INSERT INTO `t_military_term_data` VALUES ('f640abcf-3f86-446c-a639-43807c908f03', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '数字地图', '以数字形式储存于磁带、磁盘、光盘等介质上的地图。需要时可经电子计算机处理,由输出设备制作成纸质地图,或显示在屏幕上。主要用于作战指挥和地形匹配等。', 255);
INSERT INTO `t_military_term_data` VALUES ('f64a8331-6d23-4823-b497-2b9bc0ef2dd2', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '组织火力', '计划、运用与协调各种火力的活动、包括作战前对火力配系的计划组织和作战中根据需要对火力的临时组织。', 81);
INSERT INTO `t_military_term_data` VALUES ('f651ac94-845b-4639-85d0-897f264dce4e', '06a75831-13a1-4660-870a-455bb445336a', '坦炮协同通信', '为保障坦克与炮兵的协同作战而建立的通信联络。主要方法有：组织协同无线电网；通过炮兵派往坦克兵的作战小组（代表）的电台或炮兵前进观察所的电台,也可通过炮兵、坦克兵派往步兵的作战小组（代表）的电台建立无线电通信；由炮兵向坦克兵建立野战有线电通信；使用简易信号通信器材等。', 16);
INSERT INTO `t_military_term_data` VALUES ('f65c84cc-7cfc-499a-9f98-afd377014835', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练指标', '军事训练应达到的计划规定的目标。通常以具体的数字表示。包括训练的人员、时间、内容、质量等方面的指标。', 43);
INSERT INTO `t_military_term_data` VALUES ('f665e3d4-ac44-463d-aacc-b59da53579e5', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '帽徽', '佩戴于军帽上的象征军军江队或军种的标志。', 138);
INSERT INTO `t_military_term_data` VALUES ('f66c327c-605d-4189-a65b-30a5a8cedf14', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '突击', '集中兵力、火力对敌实施急速、猛烈的打击。按手段；分为兵力突击和火力突击；按火力性质,分为常规突击和核突击等。', 360);
INSERT INTO `t_military_term_data` VALUES ('f6815421-5b04-4958-a5e2-7a565cc31503', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察部队', '①团级的专业侦察单位、②各级专业侦察单位的统称。', 68);
INSERT INTO `t_military_term_data` VALUES ('f68ecf9e-40c9-4c6f-a348-54cf356b4c0b', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军事民主', '中国人民解放军内部在军事上实行的民主。主要内容包括：在军事训练中实行官兵互教互学的练兵方法,开展评教评学活动；在执行作战任务和其他任务时,发动官兵出主意、想办法,讨论如何执行命令、克服困难、圆满完成任务。', 8);
INSERT INTO `t_military_term_data` VALUES ('f691267b-64ea-47b0-9b3c-15d965365b47', '916997ee-6728-4c61-9b79-d96960b1dc86', '气密检查', '对防护器材或防护工事密闭性能进行的检查。通常采用专用仪器设备检查,也可使用简易方法检查。', 142);
INSERT INTO `t_military_term_data` VALUES ('f6c94186-4b4f-457f-a73b-f5536c2cb47f', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '计算机作战模拟', '将一定的作战模型编成计算机程序并通过以计算机为主体的现代技术设备进行的作战模拟。', 166);
INSERT INTO `t_military_term_data` VALUES ('f6d9dfb6-3fc3-4116-a573-3bfe1f4e09d5', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵配置', '将炮兵兵力、兵器布置在适当的位置。通常根据合成指挥员的决心、作战方案,炮兵的任务与武器装备的性能,敌情和地形等确定。要求能发扬火力,便于指挥、协同、机动和隐蔽。', 42);
INSERT INTO `t_military_term_data` VALUES ('f6debabe-23ee-4bba-892d-bcb7c0a25959', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '转发式电子干扰', '简称转发式干扰。干扰机直接将接收到的敌电磁辐射信号放大,并经含有虚假信息的信号调制后再发射出去的回答式电子干扰。用以欺骗敌人。', 51);
INSERT INTO `t_military_term_data` VALUES ('f6ed2aa0-17ed-416f-b5a9-c9de5a3d5127', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '热带雨林气候', '赤道附近热带雨林地区的气候。主要特征是常年高温、潮湿、多雨。', 60);
INSERT INTO `t_military_term_data` VALUES ('f6f32eb6-9ea0-4e3c-97d8-ea26d1c0418a', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '水准点', '用水准测量方法测定的高程控制点。水准标志嵌于混凝土或基石制成的标石上。主要作为各种测图和工程建设的高程依据。', 179);
INSERT INTO `t_military_term_data` VALUES ('f6f96fd8-c6bd-4208-8891-bab13564a269', '97a19170-bfac-42c5-9906-1acb187f0654', '不带伞空投', '装备、物资不系降落伞的空投。空投物散布面小,包装简便,但着陆时碰撞力大,损坏率高。通常用以空投粮食、被装等不易摔坏的物资。', 174);
INSERT INTO `t_military_term_data` VALUES ('f701703c-c8d4-40c8-9cf4-621af682619b', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克疏散地域', '坦克部队分散转移并分开配置的地域。通常选择在驻地附近利于坦克隐蔽和机动的地形上。', 16);
INSERT INTO `t_military_term_data` VALUES ('f710928a-f980-42c2-b2ee-a420c2283b5e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事基地', '驻扎一定数量的军事人员,储备相当数量的武器装备和军事物资,建有相应的组织机构和设施,能够进行特定的军事活动的地区。是军队作战和训练的重要依托。按用途,分为作战基地、训练基地、补给基地、武器试验基地等；按军种,分为陆军基地、海军基地、空军基地、战略导弹部队基地等。', 55);
INSERT INTO `t_military_term_data` VALUES ('f7239218-5d0f-4f52-b432-d96f003918e8', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '武器系统', '由相互配合的武器和技术装备组成并具有一定作战功能的有机整体。一般包括武器本身及其发射或投掷的各种运载工具、观瞄装置和指挥、控制、通信等技术装备。有单件武器构成的单一武器系统和多种武器构成的组合武器系统。', 39);
INSERT INTO `t_military_term_data` VALUES ('f726c27c-2db8-49b1-90a6-9b0f1de43d4d', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克射击等级', '对坦克指挥员和坦克乘员掌握的射击理论和技能程度划分的等级。分为特级射手、一级射手和二级射手3个等级。', 78);
INSERT INTO `t_military_term_data` VALUES ('f727c4bc-47e2-4cb9-875e-a140eb772475', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '突围', '部队从敌人包围中突破出来的作战行动。', 419);
INSERT INTO `t_military_term_data` VALUES ('f736fcb6-dd26-4bb8-a469-1fdecefb3c04', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰型', '同一舰种或舰级中按外形、构造和战术技术性能划分的舰艇型号。常用首制舰的代号表示同种或同级舰艇的舰型。如中国人民解放军海军的“052”型导弹驱逐舰、“053H2”型导弹护卫舰、“037－II”型导弹护卫艇等。', 125);
INSERT INTO `t_military_term_data` VALUES ('f737b9bc-3b3a-434e-88e3-56f989540759', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役机动', '为达成一定的战役目的而组织实施的兵力兵器移动。基本样式包括战役包围、战役迂回、战役穿插、战役退却等。', 48);
INSERT INTO `t_military_term_data` VALUES ('f73b2ac5-2b7e-40e2-bc44-aaf71ac53a3c', '06a75831-13a1-4660-870a-455bb445336a', '无线电寻呼系统', '一种单向传送简单信息的无线电呼叫系统。由寻呼控制中心、基站和寻呼接收器（俗称BP机）组成。用以寻呼持有BP机的用户。', 172);
INSERT INTO `t_military_term_data` VALUES ('f743c8fa-4fd0-4f7b-a2ff-3c1071240671', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '保障部队', '遂行作战保障、后勤保障、技术保障等任务的部队的统称。', 49);
INSERT INTO `t_military_term_data` VALUES ('f7444cb7-9e4a-4ce3-8dcf-ac6b544435a1', '97a19170-bfac-42c5-9906-1acb187f0654', '低空飞行', '航空器在真实高度为 100～1000米（含）的飞行。', 231);
INSERT INTO `t_military_term_data` VALUES ('f744c6f8-69e5-45ec-927a-74d4825c1718', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察组', '专门派出执行侦察任务的小组。通常担负搜索、窃听、潜听、敌后侦察、照相侦察、调查询问、资料搜集等任务。', 79);
INSERT INTO `t_military_term_data` VALUES ('f746ace7-06a8-4fce-9c9f-adf2d3900dff', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '专业兵', '①编配专门技术装备、担负专项保障任务、不称兵种的专业部队和分队的统称。如侦察兵、测绘兵、气象兵、汽车兵等。②泛指担任专业勤务的士兵。', 39);
INSERT INTO `t_military_term_data` VALUES ('f7483a37-552a-4708-887f-758614281e55', '97a19170-bfac-42c5-9906-1acb187f0654', '航空侦察', '使用航空器对地面、水面或水下以及空中的情况进行的侦察。包括飞机侦察和气球侦察等。', 115);
INSERT INTO `t_military_term_data` VALUES ('f74b6cd3-974f-4012-949e-7cb3381e1031', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '装备技术部（处）', '军队中主管武器装备的技术勤务工作的领导机关。一般在团级以上部队或单位设立。在本部队或单位首长领导下,负责武器装备的技术勤务保障和技术管理工作。', 7);
INSERT INTO `t_military_term_data` VALUES ('f7557bdc-8caf-4baa-8691-78c67eb7f176', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '国防工程', '用于国防目的,主要在平时构筑的各种水备工程的统称。包括永备阵地工程、大型指挥工程、通信枢纽工程、军港和军用机场工程、导弹基地工程、洞库工程、人防工程等。', 57);
INSERT INTO `t_military_term_data` VALUES ('f7575b0b-3479-4ede-8c38-a4b04b02354f', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '光学侦察', '使用光学技术器材进行的侦察。包括照相侦察、红外线侦察、微光侦察、激光侦察和电视侦察等。', 49);
INSERT INTO `t_military_term_data` VALUES ('f76189b5-41f6-47d8-80a6-2ad9e36ffb8f', '916997ee-6728-4c61-9b79-d96960b1dc86', '表面沾染水平', '亦称表面沾染程度。受染物或人体表面单位面积上的放射性活度。常用以表示人员、装备等表面的沾染情况。单位是贝可／平方厘米。', 92);
INSERT INTO `t_military_term_data` VALUES ('f7735b90-f5b1-4de3-a44f-eab33f4af978', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '高地', '地面隆起部位的统称。如山、丘陵等。在军事上常以地形图上的高程注记为其名称,如某高地的高程注记为28.9米,即称为 286.9高地。', 130);
INSERT INTO `t_military_term_data` VALUES ('f77ed312-4b15-4d2a-8bae-bde4bb035247', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事行动', '武装力量为实现某种政治、经济或军事意图而采取的举动。', 58);
INSERT INTO `t_military_term_data` VALUES ('f77f2c4c-94b8-47b9-baca-cecdb24a009a', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '大部歼灭', '敌军 60％～80％被歼灭,但尚有一定的作战能力。', 381);
INSERT INTO `t_military_term_data` VALUES ('f78db9d5-a6d1-425a-8c76-d446788c5b25', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '登陆战役', '对据守岛岸、海岸之敌实施的渡海进攻战役。通常由陆军。海军、空军、第二炮兵的战役军团联合进行。', 65);
INSERT INTO `t_military_term_data` VALUES ('f78f373a-1811-421f-b845-df0de7fd701e', 'f0140091-c11a-48c9-8836-8aa94439dac0', '支撑点', '依托有利地形构成的环形防御阵地。是连、排防御阵地的基本形式,也是构成营防御地域的基础。', 237);
INSERT INTO `t_military_term_data` VALUES ('f792583b-6953-4109-b293-c8b1d7e257ea', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '能见度', '反映大气透明程度的物理量。通常以人的正常视力能将一定大小的黑色目标物从天空背景中识别出来的最大距离来表示。以米或千米为计量单位。一般分为水平能见度、垂直能见度和斜视能见度等。影响能见度的天气现象主要有沙尘暴、雾、雨、雪、烟、覆、浮尘、吹沙和吹雪等。', 23);
INSERT INTO `t_military_term_data` VALUES ('f79b76a7-6fb5-4ba0-8943-47c35c482666', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '梯恩梯', '英文TNT的音译。用甲苯经硝酸和硫酸的混酸硝化而成的单质猛炸药。为淡黄色晶体状物,味苦有毒,吸湿性小,难溶于水，化学稳定性高。主要用以装填弹药和爆破。', 210);
INSERT INTO `t_military_term_data` VALUES ('f7a50e07-3263-4459-9350-e1b7fb182d7b', '916997ee-6728-4c61-9b79-d96960b1dc86', '核事故应急救援', '核反应堆失控、放射性物质外泄造成的意外事故实施的紧急救援。主要包括；对核事故危害地区实施辐射监测,排除事故危害,抢救伤员,组织群众撤离,消除沾染后果等。', 81);
INSERT INTO `t_military_term_data` VALUES ('f7b704b9-1ebf-4449-a002-b87b1dadab79', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇损害管制', '舰艇为保持或恢复自身生命力而采取的预防、限制、消除损害的措施和行动的统称。主要包括：防沉与抗沉,防火、防爆与灭火,保持或恢复武器、设备的作战功能等。', 244);
INSERT INTO `t_military_term_data` VALUES ('f7c4bd7d-64d3-4b31-8bc2-bc85f35ce258', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '单个教练', '以单个人员为对象进行教学和练习。通常在队列、射击、军事体育、单兵战斗动作及专业技术训练中采用。', 154);
INSERT INTO `t_military_term_data` VALUES ('f7c6c888-5e42-4358-8895-8910f8bd6cad', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇稳性', '舰艇所具有的受外力作用偏离平衡位置而倾斜后能自行恢复原平衡位置的性能。是舰艇战术技术性能要素之一。按偏离方向,分为横稳性和纵稳性；按倾角大小,分为初稳性和大倾角稳性。', 331);
INSERT INTO `t_military_term_data` VALUES ('f7c7ad54-16f5-4a3a-bff0-66946ca78928', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇远航训练', '单艘舰艇或舰艇编队远离港岸进行的较长时间航行的海上训练。目的是：熟练各种情况下的航行方法,提高舰艇的远航能力；检验舰艇航行的精确性、武器装备长时间工作的状况；培养舰员的战斗作风和海上生活习惯；锻炼领导机关的组织指挥和后勤支援保障的能力。', 319);
INSERT INTO `t_military_term_data` VALUES ('f7d47894-c29f-4414-865d-31943ec53a11', '8a761efd-50a6-4ac8-9913-b7d745104f82', '偏流', '亦称定偏。靠旋转稳定的弹丸因空气阻力、重力和旋转运动的综合作用,其质心逐渐脱离射向的横向偏移。右旋膛线发射面上的弹丸通常向右边偏移。偏移量因弹种不同而异,且随射程增加而增大,但不成比例。射击时须修正定偏对射弹的影响。', 58);
INSERT INTO `t_military_term_data` VALUES ('f7ec3f40-74b3-4db2-865d-1376f1d6f118', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '行军速度', '军队行军时在单位时间内行进的里程。通常按公里／时计算。根据行军任务、方式和道路等决定。', 61);
INSERT INTO `t_military_term_data` VALUES ('f7ecee15-f86d-4008-b767-23d8ff1c9d43', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练日志', '记载每日训练情况的文书。一般记载当日的训练内容、时间、地点、天候,应到、实到、缺课人数,对训练的评估等。', 168);
INSERT INTO `t_military_term_data` VALUES ('f808d3f6-5cd2-4a0d-8e58-73f8cb6a0bfe', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '制动火箭发动机', '简称制动火箭。安装于运载火箭或航天器上,能产生与飞行方向相反推力的火箭发动机。是一种小型辅助发动机,可用以减缓飞行器的前进速度或使其向相反方向运动。', 39);
INSERT INTO `t_military_term_data` VALUES ('f80cff5f-59f2-4375-aaf5-f238c9ea3090', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '通过时限', '行军时规定部队通过某地的时间。包括其先头到达和后尾通过的时间。', 70);
INSERT INTO `t_military_term_data` VALUES ('f80de339-13ff-4cde-88ee-2033589efc48', '8a761efd-50a6-4ac8-9913-b7d745104f82', '命中角', '弹着点处的弹道切线与目标表面或地表面之间小于90度的夹角。当目标表面或地表面呈水平时,命中角等于落角。', 39);
INSERT INTO `t_military_term_data` VALUES ('f80f76df-80b0-4834-9f75-00ea05cf00f6', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹火力单位', '亦称火力单元。能够独立实施对空中目标射击的地空导弹分队。根据兵器性能和设备情况,可以地空导弹营或连组成1个火力单位,也可以地空导弹排、班或发射组组成三个火力单位。', 159);
INSERT INTO `t_military_term_data` VALUES ('f81c03a4-f5ec-4d0f-8daf-325a63f79704', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '基浪', '水面或浅水下核爆炸产生的水柱下落时,在水柱外沿底部形成由细微水珠组成的,并以波浪形式迅速向四周扩展的环状云雾。地面或浅地下核爆炸后,在爆炸尘柱底部周围形成的环状尘雾,亦称基浪。基浪具有强烈的放射性。', 161);
INSERT INTO `t_military_term_data` VALUES ('f820b415-87f5-4def-a41a-051bbd02fbb5', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '前线', '战时第一线部队遂行作战任务的地区。也泛指两军进行交战的地区。', 294);
INSERT INTO `t_military_term_data` VALUES ('f8233759-29ed-4f10-8002-604929e4e158', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '导弹试验航区', '导弹飞行试验时从发射点到弹着点的飞行弹道所经过的区域。航区内,沿弹道投影线两侧设置有各种测量、控制、通信机构与设备,对导弹进行跟踪、测量、监控。远程导弹试验航区延伸到海上时,还需配备测量船队和飞机。', 79);
INSERT INTO `t_military_term_data` VALUES ('f824633c-f6e8-4f16-a876-2dc9a74a9596', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇吃水', '舰艇船体水线面至底龙骨线的垂直距离。分为标准吃水、正常吃水、满载吃水和最大吃水。通常以米为计量单位。', 324);
INSERT INTO `t_military_term_data` VALUES ('f82e28fb-1915-49e2-b9b6-0b718392c7c2', '98df76fb-4b65-48ff-a56c-4db587327c79', '战役后勤', '保障战区、战役军团的建设和作战的后勤。主要包括：战区或军区后勤,集团军后勤,海军基地后勤,临时编成的方面军（集团军群）后勤或其他执行战役任务的作战集团后勤等。', 9);
INSERT INTO `t_military_term_data` VALUES ('f836522d-3848-4191-9234-cb2d4014efa4', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '干扰效果', '电子干扰对敌电子设备效能破坏的程度。在设计干扰机和选择最佳干扰样式时,一般通过模拟试验和近似计算评价干扰效果。实际作战中的干扰效果,受话多复杂因素的影响,须综合分析对比,进行评估。', 79);
INSERT INTO `t_military_term_data` VALUES ('f8377165-8965-4b88-ba5f-f4b3076fa98c', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '战斗勤务训练', '为能保障战斗顺利实施而进行的各种勤务科目的训练。通常包括侦察、伪装、警戒、行军、输送、宿营、换班等训练。', 90);
INSERT INTO `t_military_term_data` VALUES ('f837717f-5637-4a71-a7c1-7ec2aecb30f1', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无线电测向', '利用无线电测向设备确定正在工作的无线电发射台（辐射源）的方位。通常以配置在适当地点的两个以上的测向站,交会测定无线电发射台的位置。', 34);
INSERT INTO `t_military_term_data` VALUES ('f8439366-6561-4785-b867-25da98e270de', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '指挥员侦察', '指挥员为直接获取作战所需情报而进行的侦察。通常在作战准备阶段和作战实施阶段的关键时刻由指挥员率领有关人员实施。', 11);
INSERT INTO `t_military_term_data` VALUES ('f84d1668-2515-4b1d-87ba-f04b27ff48c4', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '社情侦察', '对作战行动区域内的社会情况进行的侦察。主要查明政治、经济、文化、人口、宗教、疫情、民族特点和风俗习惯等情况。', 24);
INSERT INTO `t_military_term_data` VALUES ('f8512c55-5b0a-474f-9d3c-8d533551f690', '97a19170-bfac-42c5-9906-1acb187f0654', '空军战斗', '空军部队、分队在较短时间和较小空间内进行的有组织的作战行动。按基本类型,分为空中进攻战斗和防空战斗；按样式,分为空对空战斗、空对地战斗和地对空战斗。', 34);
INSERT INTO `t_military_term_data` VALUES ('f8532b70-76e7-4622-8dce-420437d67125', '97a19170-bfac-42c5-9906-1acb187f0654', '地空导弹责任射界', '上级按方位给地空导弹火力单位划定的负责消灭空中目标的区域界线。主要依据地空导弹火力单位的数量、兵器性能、兵力部署和空中目标的可能袭击方向等因素确定。', 142);
INSERT INTO `t_military_term_data` VALUES ('f85d7cc4-b962-4208-8121-3799273801b2', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '单兵净水器材', '供单个人员制取饮用水的净水器、消毒剂和脱盐剂的统称。', 371);
INSERT INTO `t_military_term_data` VALUES ('f861d72a-cb3d-4f1b-af56-b6d2087c7aad', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹储存期', '导弹在正常使用和规定的储存环境条件下,生产单位向使用单位保证的能够满足战术技术性能要求的存放期限。是导弹的重要质量指标。', 198);
INSERT INTO `t_military_term_data` VALUES ('f865adc3-8f03-49f8-b63f-e8b5f5dd4da4', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '连（营）散布', '炮兵连（营）行集火射向实施一距离射击（用相应目标中心点的射距离实施的射击）时,连（营）内各炮的射弹散布中心所构成的散布。', 263);
INSERT INTO `t_military_term_data` VALUES ('f86949d9-ac7f-42b9-b70c-7f4e2c2196ff', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹发射控制设备', '用以传递发射指令和控制导弹发射的地面设备。分为固定式导弹发射控制设备和移动式导弹发射控制设备。包括发射控制、诸元装定、信息传输和监控等设备。', 71);
INSERT INTO `t_military_term_data` VALUES ('f86b604b-de0c-4056-bf9e-70eeddf609e3', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵通信', '为保障防空兵作战指挥和传输武器控制信息的通信联络。主要包括指挥通信、警报通信、空情报知通信、武器控制通信、协同通信、技术保障通信和后勤通信等。', 126);
INSERT INTO `t_military_term_data` VALUES ('f8722abf-24c6-4f0e-a4ac-6f0881b46a60', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '待命', '等待执行任务的命令。', 253);
INSERT INTO `t_military_term_data` VALUES ('f87a66c0-bc2d-4252-9764-59bbdad0f325', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克使用建议', '合同作战中坦克兵指挥员向上级或合成军队指挥员提出使用坦克兵力的建议。主要包括：使用坦克的方向,兵力区分和使用方法,展开地区的位置,开辟通路的数量,有关保障等。', 12);
INSERT INTO `t_military_term_data` VALUES ('f88bba0d-8da7-4ae6-92fe-649bc61d9706', 'f0140091-c11a-48c9-8836-8aa94439dac0', '火力阻击', '阻止或迟滞敌人运动。', 96);
INSERT INTO `t_military_term_data` VALUES ('f8a91b38-f2cb-4737-86d3-8d47e674b204', 'd7132c58-5df3-4b97-919f-58740148b9ca', '防空兵伴随掩护', '防空兵分队编在被掩护部队的战斗队形或临战（疏开）队形中,主要以行进间射击的方法实施的对空掩护。', 80);
INSERT INTO `t_military_term_data` VALUES ('f8aab842-1148-4817-ad0a-cbafb281bada', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '组哨', '担负宿营警戒任务并进入预定位置的战斗小组。通常由宿营的连、排派出。', 24);
INSERT INTO `t_military_term_data` VALUES ('f8af24ba-4960-43e9-88e5-62a79eea6e48', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '破袭战', '亦称破击战。游击队或正规部队以破坏或袭击敌后方和纵深内重要目标为主的作战。破袭的主要目标有交通运输线。输油管线、通信设施、工程设施、重要技术兵器、作战和补给基地等,以给敌行动、联络、补给等造成困难,消耗或消灭敌人。', 143);
INSERT INTO `t_military_term_data` VALUES ('f8c9a876-c791-4a23-8bd1-93982c192f74', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '坑道爆破', '在地下挖掘通道至敌坚固目标下方或附近而实施的爆破。', 250);
INSERT INTO `t_military_term_data` VALUES ('f8dc15aa-b68f-46e3-8bd2-e8a4bfdb5164', '97a19170-bfac-42c5-9906-1acb187f0654', '空中掩护', '歼击航空兵部队为保障己方地面、水面和空中兵力不受或少受敌空中袭击而进行的掩护。通常包括空中截击、空中阻击、空中巡逻和空中护航等作战行动。', 109);
INSERT INTO `t_military_term_data` VALUES ('f8e733ce-9dfb-407a-94fe-a199af4156ca', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '通知', '对所属单位和人员传达有关事项的军用文书。', 138);
INSERT INTO `t_military_term_data` VALUES ('f8ee8238-1989-4883-ac19-40916e563a12', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵交会观察所', '主要用以进行交会作业的炮兵观察所。交会作业通常由两个以上的交会观察所配合进行。', 91);
INSERT INTO `t_military_term_data` VALUES ('f8f276ff-3585-44ea-90ef-72a0ca8b51fe', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '战损率', '在一次作战行动结束后或一定作战时间内,武器装备损失数与参战的武器装备总数的比值。通常用百分比表示。', 112);
INSERT INTO `t_military_term_data` VALUES ('f8ff4f47-e89f-4f3b-b271-3c1642977187', '06a75831-13a1-4660-870a-455bb445336a', '短波电台', '亦称高频电台。工作波长为100～10米（频率为3～30兆赫）的无线电台。能传输等幅报、印字报、传真报、电话、数据等。开设方便,能以较小的发射功率,进行远距离通信。', 178);
INSERT INTO `t_military_term_data` VALUES ('f92662b8-affd-4a9c-b604-0fd44ea602cc', '06a75831-13a1-4660-870a-455bb445336a', '通播', '在既设通信网或专设的通播网内同时向若干个通信对象发信的单方通信工作方式。可实施电报、电话和图像通播。通播时各通信对象须使用相同的通信联络规定。', 46);
INSERT INTO `t_military_term_data` VALUES ('f92749d4-de4c-4914-838a-25f9ac1f6b56', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '游击战', '分散游动的非正规的作战形式。通常以袭击为主要手段,以消耗敌人为主要目的。较之正规战有更大的主动性、灵活性、进攻性、速决性和流动性。', 142);
INSERT INTO `t_military_term_data` VALUES ('f9287c11-7425-490c-a26a-353d275dbb80', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '无源干扰器材', '本身不发射电磁波而依靠反射、散射或吸收电磁波的作用干扰敌电子设备的器材。主要有箔条、角反射器、龙伯透镜反射器、假目标、电波吸收材料、烟幕发生器和消光材料等。', 133);
INSERT INTO `t_military_term_data` VALUES ('f92db385-e87b-4140-b121-eb4e20988330', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '地下核试验', '爆心在地下一定深度的核爆炸试验。通常分为浅层地下核试验和深层地下核试验。浅层地下核试验在地面形成弹坑,有大量放射性物质逸出；深层地下核试验即封闭式地下核试验。', 183);
INSERT INTO `t_military_term_data` VALUES ('f934ddc8-c39c-4525-8162-23b7a78a6eec', 'f0140091-c11a-48c9-8836-8aa94439dac0', '扫清外围', '歼灭城市或要塞外围守敌的战斗行动。', 190);
INSERT INTO `t_military_term_data` VALUES ('f93916b1-2743-479c-a974-ba960674d7ba', '98df76fb-4b65-48ff-a56c-4db587327c79', '被装供应气候区', '军队主要按气候因素划分的被装供应区域。是制定被装供应标准和组织供应的主要依据。中国人民解放军将全国划分为热区、亚热区。温区、寒区、高寒区等5个被装供应气候区。', 150);
INSERT INTO `t_military_term_data` VALUES ('f93ac19e-8031-424b-889e-6cd2dd6ade9e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '前行舰', '舰艇编队成单纵队航行时,前后相邻的两艘舰中前面的一艘舰。通常以整个编队队列的前行舰为舰艇编队的基准舰。', 263);
INSERT INTO `t_military_term_data` VALUES ('f93ef028-64d2-423e-9185-86121cd23505', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '校官', '①军官军衔中低于将官高于尉官的一等。通常分为上校、中校、少校3级。有的国家还在上校之上设大校。②泛指被授予校官军衔的军官。', 132);
INSERT INTO `t_military_term_data` VALUES ('f9441c8a-8fc2-4e32-ad60-8b0a2e2abd94', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '综合训练计划', '一定时间内组织实施多种项目训练的计划。包括年度训练计划、阶段训练计划、月训练计划、周训练计划等。', 28);
INSERT INTO `t_military_term_data` VALUES ('f9613800-a99e-4b5d-b86e-6e2f08691c87', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '保密制度', '为保守秘密而制定的制度。主要包括：保密组织机构及其职责的规定,保密教育制度,文件、资料和档案等秘密载体的管理制度,保密守则,保密检查与奖惩制度等。', 75);
INSERT INTO `t_military_term_data` VALUES ('f96276c7-b9fd-4543-a85c-633540364578', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '政治觉悟', '中国人民解放军军人对无产阶级及其政党中国共产党的根本利益与历史使命、建设有中国特色社会主义以及建军宗旨、原则和任务的自觉意识。', 106);
INSERT INTO `t_military_term_data` VALUES ('f967e723-9b92-46d1-960e-53b1cc80f7fd', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化侦察车', '防化侦察分队遂行辐射、化学侦察任务的专用车辆。主要用以发现放射性沾染和测量地面Y射线照射量率,发现、监测染毒空气,查明毒剂种类。染毒范围,标示受染道路与地域的范围,及时传递和报告侦察情况。是部队实施大面积辐射、化学侦察的主要装备。', 170);
INSERT INTO `t_military_term_data` VALUES ('f96a58d2-5a78-434d-bb3d-4581f444b554', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '平时编制', '军队在和平时期的编制。一般要求机构精干,人员、装备较少。是战时扩编的基础。', 61);
INSERT INTO `t_military_term_data` VALUES ('f98466cd-9b32-468c-806c-7bc2c94fff45', '06a75831-13a1-4660-870a-455bb445336a', '公用数据自动交换网', '由多种通信手段建立的通信线路,接若干自动数据交换设备构成的公用数据通信网。迂回路由多,信道利用率高,接转信息快。', 68);
INSERT INTO `t_military_term_data` VALUES ('f98d1e69-d330-4c1f-bb62-6bdb1daa8b00', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上截击', '亦称海上拦击、海军舰艇或飞机对在海上运动的敌方舰艇实施的拦截与攻击。', 83);
INSERT INTO `t_military_term_data` VALUES ('f9a24958-57ec-44f4-915d-8cec97187d41', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '作战构想', '对作战行动的概略设想主要包括对作战目标、方向、战法、步骤等的大致设想。', 73);
INSERT INTO `t_military_term_data` VALUES ('f9b40503-4629-4247-b8c3-651b3a04bc08', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察纵深', '侦察任务所及区域的纵深。通常略大于本级部队作战任务的纵深。', 105);
INSERT INTO `t_military_term_data` VALUES ('f9bf48a6-35ab-43bf-a90e-e65ac48ab7ed', '98df76fb-4b65-48ff-a56c-4db587327c79', '交通线防护', '为保障交通线的安全或减轻其被破坏程度而采取的警戒、掩护、伪装和加固等措施的统称。', 286);
INSERT INTO `t_military_term_data` VALUES ('f9c37a6c-1ed5-4756-b339-89b091097ed5', '878651de-adf5-4c72-9376-9c363b893ff8', '战略反空袭', '对敌战略空袭从全局上实施的抗击和反击。', 112);
INSERT INTO `t_military_term_data` VALUES ('f9ce94c7-239f-4b97-9d85-90e51d3f29c7', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '攻击直升机', '专门设计制造的以航炮、航空火箭、空对地导弹为基本武器,主要用于对地面或水面、水下目标进行空中突击的武装直升机。可执行反坦克、反潜、航空火力支援等多种作战任务。', 6);
INSERT INTO `t_military_term_data` VALUES ('f9d4a157-0a01-4da1-a042-8bedb560a271', '8a761efd-50a6-4ac8-9913-b7d745104f82', '自燃', '射击武器在射击过程中，射弹的发射药在膛内自行燃烧,使射弹未经击发即被发射的射击故障。', 133);
INSERT INTO `t_military_term_data` VALUES ('f9da317d-9f74-4377-92b2-831a4b64b588', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '布雷火箭弹', '亦称布雷火箭。用以撒布地雷的火箭弹。由战斗部（装有可撒布地雷）、火箭发动机和稳定器组成。用火箭布雷车、火箭炮或火箭发射架发射。', 166);
INSERT INTO `t_military_term_data` VALUES ('f9e6dbeb-b1ba-49e6-b83b-96990056c425', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '预警技术', '采用红外探测雷达探测和计算机处理等技术手段远距离发现来袭的弹道导弹、飞机等目标并迅速提供报警信息的技术。', 29);
INSERT INTO `t_military_term_data` VALUES ('f9ee42f7-6cca-4ccf-b186-957ab7333e52', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '边界地图', '标示相邻国家对边界地区实地划界情况或现实控制情况的专题地图。', 265);
INSERT INTO `t_military_term_data` VALUES ('f9f0294a-3c33-416b-966c-d011fadd6de2', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '给水器材', '用于野战给水工程和给水勤务的机械、车辆、器具和材料的统称。主要包括：水源侦察器材,钻井器材,水处理器材和输运水、储水、配水器材等。', 368);
INSERT INTO `t_military_term_data` VALUES ('fa00ef4b-67d3-412c-b017-146faa9dc451', '98df76fb-4b65-48ff-a56c-4db587327c79', '军事后勤', '军队后勤为主体,为国家军事建设和战争服务的后勤。包括武装力量的后勤和政府、人民群众直接为军事服务的后勤。', 1);
INSERT INTO `t_military_term_data` VALUES ('fa11fe8d-ff7e-43a6-9d72-77928f8400ef', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '人口', '生活在一定社会一定地区和一定时间内的人的总体。人口状况包括数量、质量、密度、分布、种族、民族及年龄、性别和职业构成等。是国力的重要组成部分,制定国家政策和军事战略的重要依据。', 99);
INSERT INTO `t_military_term_data` VALUES ('fa1ff9fc-719a-42cf-a37b-659429261796', '06a75831-13a1-4660-870a-455bb445336a', '通信总站', '由若干固定通信台、站和线路维护分队编成的通信部队。编配于总部、军区和军兵种。主要任务是保障战略、战役指挥机关实施指挥的通信联络。', 2);
INSERT INTO `t_military_term_data` VALUES ('fa202d72-4355-43a4-a418-fb760af4d96f', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '作息制度', '军队中关于一日工作、生活时间划分的制度。通常以作息时间表的形式作出统一的规定。', 10);
INSERT INTO `t_military_term_data` VALUES ('fa53d398-e488-4609-8f71-83204f588c64', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '三防训练', '以对核、化学、生物武器袭击的防护知识和技能为主要内容的训练。', 79);
INSERT INTO `t_military_term_data` VALUES ('fa6cfa9d-1b9d-456a-957a-de3e69e75edc', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '墨卡托投影', '亦称正轴等角圆柱投影。由荷兰地图学家墨卡托首创的一种投影方法。是海图中使用最多的一种投影。', 272);
INSERT INTO `t_military_term_data` VALUES ('fa74f1d6-3a01-4c44-bd87-5278b4eb11a9', 'd7132c58-5df3-4b97-919f-58740148b9ca', '小高炮航路仪', '为小口径高射炮提供瞄准具装定诸元的仪器。用以搜索、跟踪空中目标、测定目标方位角、高低角、距离等现在坐标,计算目标速度、航路方位角；升降角、距离等火炮瞄准具装定诸元。', 54);
INSERT INTO `t_military_term_data` VALUES ('fa7e0511-31d9-4b26-af40-e0200c52c303', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '俘虏', '①亦称战俘。战争中被抓获和投降的敌方从事战争的人员。②作战中擒获敌人的行动。', 391);
INSERT INTO `t_military_term_data` VALUES ('fa8263b0-3f4f-4b68-98d4-4a73b93b2592', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '空气喷气发动机', '本身只携带燃烧剂（燃料）,利用空气中的氧气作为氧化剂的喷气发动机。分为涡轮喷气发动机和冲压喷气发动机。多用于大气层中飞行的飞行器。', 33);
INSERT INTO `t_military_term_data` VALUES ('fa8738b3-0a9c-43cf-a4d7-b7701e2e095d', 'f0140091-c11a-48c9-8836-8aa94439dac0', '暗火力点', '位置隐秘,严密伪装,在近距离内突然射击的火力点。', 241);
INSERT INTO `t_military_term_data` VALUES ('fa8fd118-e887-4fe1-9d46-0bdc03211e21', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹瞄准', '赋子导弹射向的过程。其瞄准精度直接影响导弹的命中精度。', 102);
INSERT INTO `t_military_term_data` VALUES ('fa9e8499-dd65-4e8e-a1af-7e621ff6a560', '916997ee-6728-4c61-9b79-d96960b1dc86', '毒剂气溶胶', '毒剂的固体或液体微粒分散在空气中形成的气溶胶。毒剂微粒的直径通常为0.01～100微米。', 122);
INSERT INTO `t_military_term_data` VALUES ('faa269c5-0ab8-4aee-847d-0dbfc98bb804', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '空投水雷', '亦称航空水雷。由飞机或直升机布放的水雷。雷体尾部装有稳定器和降落伞,用以保障水雷在空中下降轨迹的稳定和减小入水的撞击力。通常装有自爆装置。', 220);
INSERT INTO `t_military_term_data` VALUES ('faa69555-51a1-4a5c-8dd0-8f1a21f7a11c', '98df76fb-4b65-48ff-a56c-4db587327c79', '军人工资', '国家以货币形式定期给予军人的报酬。分为军官工资、文职干部工资和士官工资等。中国人民解放军实行结构工资制；军官工资由基础、职务、军衔、军龄工资构成；文职干部工资由基础、职务、级别、军龄工资构成；士官工资由基础、军衔、军龄工资构成。', 86);
INSERT INTO `t_military_term_data` VALUES ('faa699d1-9ffd-46df-ad25-3dff9f407ba3', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '热像仪', '能将景物的热图象转变为可见图象的仪器。由红外光学系统、红外探测器、显示器等部分组成。', 79);
INSERT INTO `t_military_term_data` VALUES ('faa9ed28-c646-4c03-ae0f-55233e982f35', '97a19170-bfac-42c5-9906-1acb187f0654', '空军航空工程', '空军对航空装备的技术使用和维修实行全寿命管理的各项工作的统称。主要内容是对空军的航空装备从设计、制造到使用、退役的全过程,实施有效的监督、控制和管理。', 440);
INSERT INTO `t_military_term_data` VALUES ('faaa3aca-b389-470e-88d6-02b34aadce50', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军事挑衅', '亦称武装挑衅。使用武装力量借端生事,企图挑起武装冲突或战争的行为。', 63);
INSERT INTO `t_military_term_data` VALUES ('faaace79-a862-44aa-9e5f-5c64084f53b1', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天测控系统', '能对飞行中的航天器及运载火箭进行跟踪测量、监视和控制的系统。主要包括：光学跟踪测量系统,无线电跟踪测量系统,遥测系统,实时数据处理系统,指挥监控系统,遥控系统,通信系统,时间统一系统,事后数据处理系统等。', 274);
INSERT INTO `t_military_term_data` VALUES ('faac300a-122e-416e-87df-ed0a1af4e0cb', '97a19170-bfac-42c5-9906-1acb187f0654', '飞行续航能力', '飞机或直升机一次加满油后能够持续飞行的最大续航时间和最大航程的统称。', 303);
INSERT INTO `t_military_term_data` VALUES ('fabb207d-a6b5-4e43-b443-4a8b5b0e199a', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '辐射源特征参数', '表示电磁辐射源固有特性的一组可测量的数值或图形。通常分为频域、时域、空域参数。如雷达的载波频率、脉冲宽度、脉冲重复频率、天线波束宽度、天线扫描周期等。', 27);
INSERT INTO `t_military_term_data` VALUES ('fabbc595-0a3a-4eba-9c53-d9231f63735d', '06a75831-13a1-4660-870a-455bb445336a', '固定通信枢纽', '将通信设备安装在地面建筑物或坑道、掩蔽部等地下永备工事内的通信枢纽。通信设施较完备,防护能力较强。', 73);
INSERT INTO `t_military_term_data` VALUES ('fac2281a-3ac6-41f4-b1bb-89a690b878f3', '8a761efd-50a6-4ac8-9913-b7d745104f82', '靶', '用作射击训练的目标物。如头靶、胸靶、机枪靶、坦克靶、飞机拖靶等。', 115);
INSERT INTO `t_military_term_data` VALUES ('fac298b8-24b2-4252-82b1-e20c9b9b3a1d', 'd7132c58-5df3-4b97-919f-58740148b9ca', '空中目标航向', '空中目标飞行的方向。', 162);
INSERT INTO `t_military_term_data` VALUES ('fac5a9a8-3cfa-4057-96b5-bfa7963b9ab0', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克观察界', '坦克分队或坦克内乘员为观察敌情、地形、友邻和上级信号而划分的观察区域。应形成环形和对空观察网。单辆坦克观察界,通常按乘员位置区分。', 29);
INSERT INTO `t_military_term_data` VALUES ('fac8807f-0b92-4f2e-b542-d2c5c30be9ee', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '司令部建设', '为提高司令部履行职责的能力而进行的各项建设。包括政治、组织、业务、作风和指挥手段等方面的建设。', 160);
INSERT INTO `t_military_term_data` VALUES ('fad6bd0b-d02e-473d-848e-96558513d96c', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '军港港区', '军港界内的区域。包括互相毗连的水域和陆域。', 390);
INSERT INTO `t_military_term_data` VALUES ('fadc824e-27f9-43bb-bc18-84f02f110711', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天器返回技术', '使航天器脱离原来的运行轨道进入地球大气层,并在地面安全着陆的技术。包括轨道衰减法返回技术和直接再入法返回技术。', 279);
INSERT INTO `t_military_term_data` VALUES ('faf185ee-be6e-44cc-ac76-fe42cecd38d0', '97a19170-bfac-42c5-9906-1acb187f0654', '格斗空空导弹', '亦称近距格斗导弹。能在空战中对目视距离内的高速、大机动飞行的空中目标进行攻击的空空导弹。最小发射距离为300～500米,多采用红外制导。', 316);
INSERT INTO `t_military_term_data` VALUES ('faf92f99-d009-4e6c-b2d1-4cb1f724b5b0', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '工程设施', '工程建筑及有关设备的统称。', 32);
INSERT INTO `t_military_term_data` VALUES ('fb01506b-5f6c-4c2e-832b-ba936ec1da12', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '全方位作战', '在一定的战场范围内,同时或相继展开于正面和翼侧,前方和后方、陆地、海洋、空中和太空等各个方位的作战。', 184);
INSERT INTO `t_military_term_data` VALUES ('fb1bd63b-2b6e-4a43-8ab9-e72f6d1bfbe6', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '影像地图', '将航空像片或航天像片纠正成正射投影像片图,并加绘等高线和必要的地形符号、注记而制成的地图。显示的地形真实、立体感强、信息丰富。军事上可用以分析地形和判定目标点位等。', 254);
INSERT INTO `t_military_term_data` VALUES ('fb257889-1235-46a9-a9cc-66ffd6077305', 'f0140091-c11a-48c9-8836-8aa94439dac0', '冲击目标', '冲击分队所要消灭的敌人和攻占的阵地。通常在现地明确,可用地名或编号表示。', 187);
INSERT INTO `t_military_term_data` VALUES ('fb30704c-5ab1-4283-9357-05fb14c6d408', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '封闭式地下核试验', '在地下深层,爆炸后产生的放射性物质被封闭在地下的核爆炸试验。包括平洞核试验、竖井核试验等。', 184);
INSERT INTO `t_military_term_data` VALUES ('fb34a527-feb9-4fc0-b2bf-d21c38da9cfe', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '退职', '不够退休条件的军队在编职工因病或其他原因退出工作岗位。', 162);
INSERT INTO `t_military_term_data` VALUES ('fb34fff2-c827-40e8-8788-6abd5f8338f0', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '飞航式导弹', '亦称有翼导弹。依靠喷气发动机的推力和翼面产生的升力在大气层内飞行,并利用翼面控制其飞行轨迹的导弹。包括多数反飞机导弹、反舰导弹、反坦克导弹和巡航导弹等。', 10);
INSERT INTO `t_military_term_data` VALUES ('fb50a36b-860b-48ce-8898-a24910ee8efb', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹储存环境条件', '正常储存导弹弹体、弹头、弹上仪器、推进剂和地面设备等应具备的周围环境方面的条件。通常包括规定范围的温度、湿度、气压以及防虫、防鼠、防锈、防腐、防火措施等。', 199);
INSERT INTO `t_military_term_data` VALUES ('fb57fbae-f057-4cad-8a82-49386b4ac4b9', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '炸药', '在适当的外界能量作用下能发生化学爆炸的物质。按用途,分为起爆药和猛炸药；按组成,分为单质炸药和混合炸药。', 207);
INSERT INTO `t_military_term_data` VALUES ('fb6f9b2e-25aa-4476-8947-f1cc3c78aad3', '06a75831-13a1-4660-870a-455bb445336a', '通信现地勘察', '对通信枢纽（台、站）预定开设地域和通信线路预定架设路由等有关情况进行现地观察与研究的活动。主要包括：选定通信枢纽各要素和通信预备队的配置地点,确定内外线布设的路由、方法以及通信防护的措施等。', 29);
INSERT INTO `t_military_term_data` VALUES ('fb770f67-ee0a-4c90-a4ae-5458303ad40b', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机', '由航空发动机带动旋翼旋转而产生升力和拉力的航空器。主要由机体、旋翼系统、发动机、起落架、操纵系统等组成。具有垂直起落、空中悬停、定点回转、前飞、侧飞、后退飞等性能，可在野外场地起降。', 3);
INSERT INTO `t_military_term_data` VALUES ('fb78739a-f809-47af-b42d-f2b9219f3ac0', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '交会定位', '利用两个以上侦测点对同一个电磁辐射源进行无线电测向而直接确定电磁辐射源的位置。可从设在地面不同位置的侦察站测定,也可用单个运动平台从不同位置测定。', 37);
INSERT INTO `t_military_term_data` VALUES ('fb7de0a3-56b6-41b0-950b-ded3d5d98477', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '反空降地域', '歼灭空降之敌的地域。通常选在防御的战役、战术纵深敌可能空降的地域及其附近预先设置。一般构有反空降阵地,并以兵力和火力加以控制。', 132);
INSERT INTO `t_military_term_data` VALUES ('fb951d38-f825-4a8f-9687-50606ec7b383', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '并肩突击', '两支以上部队从相邻的地段向同一方向上的敌人同时实施的突击。通常在敌防御正面较宽,没有暴露翼侧时,或为了在敌防御阵地打开较大缺口时采用。', 103);
INSERT INTO `t_military_term_data` VALUES ('fb968a7f-ae14-408c-979c-6ab67e1b7423', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海军', '以舰艇部队为主体,主要在海洋遂行作战任务的军种。通常由潜艇部队、水面舰艇部队、海军航空兵、海军岸防兵、海军陆战队等兵种和各种专业勤务部队组成。可单独作战,或与其他军种协同作战。', 0);
INSERT INTO `t_military_term_data` VALUES ('fb9db6aa-f997-417d-877d-d1ce0cebfff1', '8a761efd-50a6-4ac8-9913-b7d745104f82', '匕首枪', '兼有发射枪弹功能的匕首。通常在匕首的握把内安装枪管和击发机构,容弹4发左右，发射手枪弹或小口径运动枪弹。较手枪射程近、精度差。', 175);
INSERT INTO `t_military_term_data` VALUES ('fbc4aadd-9b9b-4c02-a2f8-eb96a2c72227', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '军队纪律', '规定的军队所属人员必须遵守的行为准则。中国人民解放军纪律的基本内容包括：执行中国共产党的路线、方针、政策；遵守国家的宪法、法律、法规；执行军队的条令、条例和规章制度；执行上级的命令和指示；执行三大纪律、八项注意。', 97);
INSERT INTO `t_military_term_data` VALUES ('fbc4b4cd-4a05-4f98-a382-e16006984c74', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '移动指挥', '指挥员及其指挥机关在运动中实施的指挥。现代条件下一般借助飞机直升机、车辆、舰船等工具与设备实施。', 26);
INSERT INTO `t_military_term_data` VALUES ('fbc95284-3472-4504-bd67-91397f3abf93', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '激光告警', '实时截获和识别敌方发射的激光信号并立即报警的过程。主要用于对激光制导武器、激光雷达和激光武器的警戒。', 30);
INSERT INTO `t_military_term_data` VALUES ('fbca4949-5d88-47a4-a5ca-81292317156e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '航海保障', '海军为使舰艇能在海上安全航行和机动而进行的保障。主要包括：进行海战区测量,编绘航海图书,提供航海设备,建立导航系统或战时航标,发布航海通告,制定战时航行规程,组织军事领航等。', 367);
INSERT INTO `t_military_term_data` VALUES ('fbcb0941-5ba9-4af2-8dc5-e838cecc9484', '9b340a5a-070c-4aec-95c6-91fac7a4b2b6', '民兵专业技术分队', '民兵组织中能够担负作战需要的某种专业技术方面任务的分队。如民兵的通信、防化、工程、军械、运输等专业技术分队。', 132);
INSERT INTO `t_military_term_data` VALUES ('fbdbda5f-936b-4a76-9565-8d670e1ec7dd', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '航天器发射场', '用以发射航天器的特定场区。通常由技术测试区、发射区、发射指挥控制中心、航区测控站、发射勤务保障设施和管理服务部门等组成。某些航天器发射场,还包括助推火箭或运载火箭第一级工作结束后的坠落区和航天器回收着陆场。', 245);
INSERT INTO `t_military_term_data` VALUES ('fbea8c47-f7bd-42cd-bad6-8da83715b540', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '自动化技术', '研究实现自动化过程的技术。可使受控对象在无人直接参与下,自动地按程序完成预定操作,在一定程度上代替人的体力劳动和脑力劳动。军事上广泛应用于火控、制导、侦察、通信、指挥等方面。', 10);
INSERT INTO `t_military_term_data` VALUES ('fbf802a0-51af-4dd1-ac6e-02a33d89452a', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '巡航导弹', '依靠喷气发动机的推力和弹翼的气动升力,主要以巡航速度（燃料消耗量最小的飞行速度）在大气层内飞行的飞航式导弹。可从车辆、飞机或舰艇上发射。采用超低空飞行,具有较强的突防能力。', 11);
INSERT INTO `t_military_term_data` VALUES ('fbf8e711-4649-4a3d-b122-83a02230e9c9', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '想定', '按照训练课题对作战双方的企图、态势以及作战发展情况的设想和假定。分基本想定和补充想定。是组织、诱导军事演习和作业的基本文书。', 97);
INSERT INTO `t_military_term_data` VALUES ('fbfaae98-1620-48db-ab5d-905992869895', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '前方尖兵', '位于行军纵队前方的尖兵。通常由前卫派出。本队或侧卫也可同时派出自己的前方尖兵。', 15);
INSERT INTO `t_military_term_data` VALUES ('fc0c75b5-6b6d-44be-baac-0209c58d99f5', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '化学战', '使用化学武器杀伤人畜、毁坏植物的作战。', 149);
INSERT INTO `t_military_term_data` VALUES ('fc0d86f8-6666-4e33-9aa8-0465e2349cf0', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹弹头垂直检查', '导弹在垂直状态下,使用垂直检查仪对弹头的引爆控制系统发送工作指令并进行测试检查的工作。也可在水平状态或台面联试状态下模拟进行。', 97);
INSERT INTO `t_military_term_data` VALUES ('fc259e78-daef-4d88-8280-e82a4dd282c9', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '初制导', '亦称初始段制导或发射段制导。在火箭、导弹等发射后的初始飞行段（弹道导弹从起飞到主动段结中）进行的制导。通常采用自主制导。', 56);
INSERT INTO `t_military_term_data` VALUES ('fc29bda1-231f-45ff-b181-b9a269201729', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克火力性能', '坦克以火力毁伤目标的特性和功能。包括火力威力和火力机动性。', 153);
INSERT INTO `t_military_term_data` VALUES ('fc2c12a4-a5b3-4634-87cf-2e2e5d26f654', 'f0140091-c11a-48c9-8836-8aa94439dac0', '进攻战斗', '主动攻击敌人的战斗。是战斗的基本类型之一。按敌人的行动性质和状态,分为对预有准备防御之敌、立足未稳之敌、运动之敌等的进攻战斗。还可按地形、气候等条件,分为登陆战斗、渡江河进攻战斗,以及山地、荒漠草原地、水网稻田地、热带山岳丛林地、高寒地等进攻战斗。', 120);
INSERT INTO `t_military_term_data` VALUES ('fc2fac16-8cf2-4f6c-82f3-897c310b04b3', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '潜舰导弹', '从潜艇上发射,用以攻击水面舰船的导弹。其体积小,射程远,命中率高,飞行高度低,突防能力强。可从水下借助潜艇鱼雷发射管发射,也可用垂直发射简发射。', 189);
INSERT INTO `t_military_term_data` VALUES ('fc3211a9-6ad4-48fb-bd70-613b1b21dd03', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '喀斯特地貌', '亦称岩溶地貌。水对可溶性岩石产生溶蚀等作用所形成的地貌。在地表有石芽、石林、峰林、岩溶丘陵、溶沟、落水洞、盲谷、干谷、岩溶洼地等形态,在地下有溶洞、地下河、地下湖等形态。', 31);
INSERT INTO `t_military_term_data` VALUES ('fc39f9b1-8301-46c3-aeec-6ea72e6c2a90', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '链式裂变反应', '亦称链式反应。一个重原子核在中子轰击下分裂为两个以上中等质量的原子核,同时释放的中子再触发下一次核分裂,并如此连续不断进行的核反应。', 113);
INSERT INTO `t_military_term_data` VALUES ('fc492883-d639-4eb3-82f1-6be8aab600b6', '916997ee-6728-4c61-9b79-d96960b1dc86', '迷盲烟幕', '施放在敌方阵地内,以妨碍其观察、联络和射击为主要目的的烟幕。', 74);
INSERT INTO `t_military_term_data` VALUES ('fc50de76-d974-4532-b7c0-ea85ec0ee756', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '参谋六会训练', '参谋人员进行的会写、会画、会传、会读、会记、会算训练。是参谋人员掌握基本业务技能的必要训练。', 63);
INSERT INTO `t_military_term_data` VALUES ('fc627c0b-e337-4b47-b356-e6e60671f9df', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '海图', '根据航海和开发海洋需要,以海洋为主要对象而测绘或编制的地图。分为普通海图和专用海图两类。普通海图详细表示海岸性质、岛屿、海底地貌、底质、海洋水文等海区的地理要素和沿岸显著目标、助航设备、航行障碍物、地磁偏差等航海要素。专用海图根据专门的用途突出表示某些海洋要素。', 261);
INSERT INTO `t_military_term_data` VALUES ('fc74ee34-b101-422e-847d-0d2754a71283', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '军人礼节', '军人表示尊重和敬意的形式、包括敬礼、起立、立正、报告等。', 49);
INSERT INTO `t_military_term_data` VALUES ('fc7cc0de-a66a-4972-9a01-9044f7187f5c', '97a19170-bfac-42c5-9906-1acb187f0654', '后掠翼飞机', '机翼前、后缘均向机身后方倾  斜的飞机。机翼前缘与机身纵轴的垂线之间的夹角称后掠角,通 常在25度以上。', 276);
INSERT INTO `t_military_term_data` VALUES ('fc805124-e2c0-4b64-afc0-70c6235f4c6f', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军人', '军队中有军籍的人员。通常包括服现役的军’白和士兵、中国人民解放军中的军人还包括服现役的文职于部、车队院校的学员等。', 97);
INSERT INTO `t_military_term_data` VALUES ('fc848553-83ca-4598-9e8a-7ce3456e6d96', 'f0140091-c11a-48c9-8836-8aa94439dac0', '爆破队', '强击支队或强击群中遂行排除障碍和其他爆破作业任务的战斗编组。通常由工兵或经过专门训练的步兵编成。', 173);
INSERT INTO `t_military_term_data` VALUES ('fc8b368e-c152-49c1-823f-5ece541e4ceb', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹发射制导车', '装有跟踪目标、控制地空导弹发射井将导弹导向目标的设备的专用车辆。主要用以完成地空导弹的发射与制导。', 36);
INSERT INTO `t_military_term_data` VALUES ('fc8d0c8d-e938-4599-80d5-b6ee679008ed', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '军事题材文学', '亦称军事文学或军旅文学。以反映武装斗争和军人生活为主要内容的各种文学作品的统称。包括军事题材的小说、诗歌、散文、报告文学等。', 111);
INSERT INTO `t_military_term_data` VALUES ('fc932925-8e02-4775-a525-e8492114c0a6', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '非爆炸性障碍物', '以形体或能量阻滞敌人行动或杀伤敌人的人工障碍物。如筑城障碍物、火障碍物、电障碍物、破坏物、沾染区等。', 101);
INSERT INTO `t_military_term_data` VALUES ('fca28d57-4804-4c1d-ac6b-d3413f2ff53c', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役阶段', '对战役进程所划分的段落。通常分为战役准备阶段、战役实施阶段和战役结束阶段。战役实施阶段中,还可根据实际情况进一步划分为若干阶段。', 35);
INSERT INTO `t_military_term_data` VALUES ('fcbabeed-105f-486c-9c75-57470bdd1e8e', '06a75831-13a1-4660-870a-455bb445336a', '自动化决策监控系统', '在指挥自动化系统中用以辅助指挥人员作出决策并监控系统运行的分系统。由监视器、键盘、打印机、电话机等组成。可为指挥人员决策显示所需信息,还可用以改变指挥自动化系统的工作状态,监视命令执行情况。', 165);
INSERT INTO `t_military_term_data` VALUES ('fd206e3f-f571-4666-9974-e48f40e7d600', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '随机导演', '围绕既定的训练问题,针对演习的发展变化,临时设置情况对军事演习进行的导演。', 133);
INSERT INTO `t_military_term_data` VALUES ('fd26860f-c512-472d-99d3-07f9a66420fe', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '政治素质', '军人在政治觉悟、思想作风和组织纪律等方面所具有的素养。是政治方向、政治立场、政治观点、政治纪律、政治鉴别力和政治敏锐性的具体体现。提高军人政治素质,是军队政治工作的重要内容。', 30);
INSERT INTO `t_military_term_data` VALUES ('fd439fc2-4ee2-42ac-80e3-5545dea7f177', '06a75831-13a1-4660-870a-455bb445336a', '模拟通信', '用模拟信号传输信息的通信。可传输电报、电话、数据和图像等。', 96);
INSERT INTO `t_military_term_data` VALUES ('fd5128b8-c016-47c6-9248-9ecd97138629', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇防热带风暴', '为防范热带风暴（包括强热带风暴、台风）对舰艇的损害而采取的安全措施。主要包括：及时发布热带风暴及台风警报,适时进入防风部署；港内舰艇进入指定泊位,防止搁浅、碰撞；海上舰艇避免进入或尽快驶离大风范围,位于较深海区的潜艇则潜入水下防风。', 287);
INSERT INTO `t_military_term_data` VALUES ('fd526d95-9d18-4d78-bbe0-c74937f87219', '8a761efd-50a6-4ac8-9913-b7d745104f82', '保险距离', '亦称安全距离。①爆炸性弹孔飞出火身口后允许其爆炸的最近距离。弹药在此距离内不允许发火，以保证使用者和装备的绝对安全。是弹药的设计、生产、使用的安全指标之一。③己方人员与炸点之间所允许的最近距离。', 123);
INSERT INTO `t_military_term_data` VALUES ('fd5ddf34-0972-476d-8440-c7424f770dac', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹停射', '地空导弹操作手在实施导弹发射过程中终止射击。通常适用于：操作手接到指挥员停止射击的口令时,或出现技术、操作故障以及发生其他情况时。', 212);
INSERT INTO `t_military_term_data` VALUES ('fd608e8e-da02-45a5-95f3-4769fd8888fd', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '三坐标雷达', '能同时测定目标的方位、距离和高度三个空间坐标的雷达。具有探测目标速度快,掌握目标容量大、精度高等优点,并有边搜索、边跟踪的能力。军事上主要用于对空警戒、引导及导弹制导与空中交通管制等。', 96);
INSERT INTO `t_military_term_data` VALUES ('fd71589c-a9e3-43a3-8fe9-4891cec741f3', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '照相侦察', '使用照相器材摄取目标影像的侦察。分为可见光照相侦察、红外线成像侦察和多光谱照相侦察。', 50);
INSERT INTO `t_military_term_data` VALUES ('fd717731-35fc-4483-b4d1-b9796869911c', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '战场纪律', '中国人民解放军军人在作战中必须严格遵守的纪律。主要内容包括：履行军人职责,服从命令听指挥；保守秘密；一切缴获要归公；爱护战地人民利益；严格执行俘虏政策；果断处置临阵脱逃、投敌叛变者等。', 29);
INSERT INTO `t_military_term_data` VALUES ('fd76548f-1edd-4d51-bf47-c76fd1e7e7d2', '97a19170-bfac-42c5-9906-1acb187f0654', '动高度截击', '歼击机跃升到其静升限以上、动升限以下的高度进行的空中截击。', 70);
INSERT INTO `t_military_term_data` VALUES ('fd7f244e-51a2-4045-b969-7f6bc7bc9fbf', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '超低空制空权', '交战一方在一定时间内对某一地区超低空空间的控制权。是陆军航空兵遂行作战任务的重要条件。', 62);
INSERT INTO `t_military_term_data` VALUES ('fd83ba28-0d17-4067-984f-a570be7424c6', '98df76fb-4b65-48ff-a56c-4db587327c79', '战时营房保障', '战时组织部队住宿所实施的保障。主要包括：组织野营物资供应,调查军队集结地域内的房屋、水电资源,调整、分配房舍,指导部队搭设临时住用设施,管理集结地域内的各种野营设施和装备等。', 237);
INSERT INTO `t_military_term_data` VALUES ('fd897279-5583-4cc5-8b1a-62221aa6a1b4', 'f0140091-c11a-48c9-8836-8aa94439dac0', '战术协同', '诸军兵种的兵团、部队、分队为遂行共同的战斗任务而进行的协调配合。通常以执行主要作战任务的军兵种的兵团或部队、分队为主,按照任务、时间、空间组织。', 44);
INSERT INTO `t_military_term_data` VALUES ('fd90a703-4f48-4c8e-8666-0cc3a86bb549', 'f1a68212-6c05-4d98-bf60-1ba03b18d656', '训练场', '供军事训练用的各种训练场地的统称。通常分为技术训练场、战术训练场、共同科目训练场等。', 182);
INSERT INTO `t_military_term_data` VALUES ('fd9e2efe-f8fc-48c6-bab5-dab4bccf0976', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '战术指示', '对下级所作的关于战斗方法的指示、如反坦克战术指所、反空降战术指示等。', 130);
INSERT INTO `t_military_term_data` VALUES ('fda33a94-4b51-46e2-87bf-aa0066e22bad', 'c626753e-c06d-4bbc-ab15-5472ec6f11d7', '战役地幅', '战役部署及行动所涉及的空间范围。其大小通常取决于战役军团的任务及其编成、预定行动地区的地形特点、敌人可能的行动等情况。', 26);
INSERT INTO `t_military_term_data` VALUES ('fda8a412-884b-43ca-bd63-e0c8d374da6f', 'd7132c58-5df3-4b97-919f-58740148b9ca', '地空导弹发射', '使地空导弹靠自身推力或外部动力飞离发射装置的行动过程。', 206);
INSERT INTO `t_military_term_data` VALUES ('fdb47f13-d5ec-4b36-91b0-63682d20aaed', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '航海图', '供舰船航行的海图。多采用墨卡托投影,图上着重表示海岸、干出滩、海底地貌、底质,航行障碍物、助航设备、航道、锚地,禁区,海区水文、方位图和地磁资料等。', 262);
INSERT INTO `t_military_term_data` VALUES ('fdb4971f-4c75-4eb1-a2f5-60ff81744abb', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '海洋资源', '存在于海洋中的动力、化学、生物、矿产等自然资源的统称。', 97);
INSERT INTO `t_military_term_data` VALUES ('fdc0a435-f58b-4d93-924d-fa9b81ee623e', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '地势', '地表高低起伏所形成的总体形态。一般指一定范围内的地貌,包括山地、高原、盆地、丘陵、平原等分布状况及其所形成的交错的地理特征。如中国的地势西高东低。', 10);
INSERT INTO `t_military_term_data` VALUES ('fdcc9e70-dee0-49c0-bca4-92092ea352bd', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '侦察艇', '装备有侦察器材和武器,用以进行海上侦察的艇。', 119);
INSERT INTO `t_military_term_data` VALUES ('fdf967f1-3da5-40e8-8181-1e6b6eecc7d6', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '模范', '军队对执行除作战外的其他任务中功绩卓著、有特殊贡献、堪称楷模的单位和个人所授予的荣誉称号。亦指被授予这种荣誉称号的人员。', 60);
INSERT INTO `t_military_term_data` VALUES ('fe212ddf-b9cb-4e8f-ab80-40c8fa57df52', '16e50003-8833-4d6f-9968-165e9a4ad3d5', '声像情报', '以胶片、磁带、磁盘、光盘等为载体的,通过声音、图像表达的情报。', 129);
INSERT INTO `t_military_term_data` VALUES ('fe28ef12-4f98-421f-b41f-73e220ef9e92', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '持久战', '持续时间较长的作战。相对于速决战而言。在战略上,通常是较弱或处于防御的一方采取的作战方针。中国共产党在抗日战争中,采取了战略上的持久战与战役战斗的速决战相结合的方针,以逐步消耗、削弱敌人,从总体上改变敌我力量对比,变劣势为优势,变被动为主动,最后夺取战争的胜利。', 131);
INSERT INTO `t_military_term_data` VALUES ('fe2ceb79-a3ec-45f8-ae7f-13e84d7f2043', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '军用控制点', '简称军控点。在预定作战地区,以大地点为基础加密布设、施测的供炮兵使用的控制点。', 166);
INSERT INTO `t_military_term_data` VALUES ('fe33ad71-7550-4b61-a163-1a3c0ee3c6ba', '916997ee-6728-4c61-9b79-d96960b1dc86', '防化保障计划', '为组织实施对核、化学、生物武器防护而拟制的计划。主要包括：对敌可能实施核、化学、生物武器袭击情况的判断,部队核观测和化学观察的报知配系,防化部队和分队的任务及行动,部队的防护措施、要求及行动,三防装备的保障等。', 16);
INSERT INTO `t_military_term_data` VALUES ('fe39cc56-22b0-4ad5-8900-6f0d4fafe198', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '火炮射表', '为炮兵决定射击诸元、指挥射击提供所需数据的一种表册。主要内容有弹道基本诸元、修正诸元、散布诸元、基础技术诸元、标准射击条件和有关附表等。各种火炮都有相应的射表。', 240);
INSERT INTO `t_military_term_data` VALUES ('fe4cb3ad-aa72-4493-9d8f-4080757f643d', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '喜报', '向获得三等功以上奖励的个人和被评为“优秀士兵”的战士的家庭报喜的书面材料。', 70);
INSERT INTO `t_military_term_data` VALUES ('fe69576b-2b69-4dad-bc58-643a6ad48443', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '登陆舰艇', '运送登陆兵及其武器装备在敌方岸滩直接登陆的登陆作战舰艇。包括坦克登陆舰、步兵登陆舰以及各种登陆艇等。', 146);
INSERT INTO `t_military_term_data` VALUES ('fe6a412e-9a6d-43fa-bf1f-cde642787cd0', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '通用直升机', '亦称多用途直升机。可用以遂行侦察、运输、救护等多种任务的直升机。', 4);
INSERT INTO `t_military_term_data` VALUES ('fe820f55-8f47-4ba7-9ecf-9442258bbcba', 'd7132c58-5df3-4b97-919f-58740148b9ca', '区域防空', '①亦称区域掩护。防空兵对合成军队作战地域和后方地域实施的面状对空掩护。由战区、集团军组织地空导弹部队实施。要求构成宽正面、大纵深、多道防空火网,保障整个被掩护区域的对空安全。②按战区或统一划分的地域范围组织的防空。', 69);
INSERT INTO `t_military_term_data` VALUES ('fe8a706f-e3c6-4a31-adaf-765aaadcbf37', '98df76fb-4b65-48ff-a56c-4db587327c79', '油料换季', '对坦克、步兵战车、装甲输送车、自行火炮以及其他有关车辆和机械装备的用油,按季节进行的更换。通常在人冬时,以冬用油料更换夏用油料；在翌年春季,再以夏用油料更换冬用油料。', 169);
INSERT INTO `t_military_term_data` VALUES ('fe9da41c-2c70-4435-8a86-8d61b7dff365', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '应答式电子干扰', '简称应答式干扰。干扰机实时测定敌电磁辐射信号的频率,并将干扰频率调整到该频率,然后经虚假信息调制再发射出去的回答式电子干扰。用以欺骗敌人。', 52);
INSERT INTO `t_military_term_data` VALUES ('fe9e1412-fd19-4506-8cd7-fe0bee530578', 'e3965d00-1452-4e3a-bb8b-76d02bab30c5', '地形判断', '对遂行任务地区的地形情况进行分析研究并得出结论的思维活动。主要判明地形特点及其对敌我双方遂行任务的影响。', 70);
INSERT INTO `t_military_term_data` VALUES ('fea19e0e-f885-4ce2-901f-c2f0859d1e65', '276e4679-d468-4ecf-a6e0-f4e09eb13db2', '中制导', '亦称中段制导。自火箭、导弹等进入正常轨道到弹道本段前（从初制导结束到末制导开始前）进行的制导。弹道导弹为在被动段的自由飞行区间进行的制导。通常采用自主制导或遥控制导。', 57);
INSERT INTO `t_military_term_data` VALUES ('fea31d9f-bf8b-4950-b695-c1e235d8dd19', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '干部代理人', '为保证作战指挥的连续性,战时各级指挥员的接替人员。一般在战前预先确定,亦可在战中临时指定或由下属自行代理。', 37);
INSERT INTO `t_military_term_data` VALUES ('fea5e83b-e474-491c-8e79-daccaab61c57', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰艇典礼', '舰艇在授旗、命名、授予荣誉称号和退役时举行的隆重仪式。', 407);
INSERT INTO `t_military_term_data` VALUES ('feb85762-85e9-4a15-8973-a5ed517a6ada', '916997ee-6728-4c61-9b79-d96960b1dc86', '核伤情等级', '依核爆炸对机体造成的损伤程度划分的等级。按照人员受损伤后对战斗力的影响和伤员治愈的可能性,分为轻度、中度、重度和极重度损伤4级。人员受轻度损伤,对作战行动有一定影响,但可全部治愈；人员受中度以上损伤,一般会失去战斗力。', 112);
INSERT INTO `t_military_term_data` VALUES ('fec49986-16d7-4914-8c6e-8d7d98882d6e', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '地堡', '供直瞄火器射击和掩蔽用的低矮工事。一般为砖石或钢筋混凝土结构。主要用以掩护桥梁、交通要道和封锁开阔地等。', 59);
INSERT INTO `t_military_term_data` VALUES ('fedec918-db14-4718-9341-1c8a5f60d2d0', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '反合围', '对抗和打破敌人合围的作战行动。', 416);
INSERT INTO `t_military_term_data` VALUES ('fee9ce2f-c09a-4ac5-b5e3-d89f9d72ae55', 'a9b08c03-96e7-4d8a-895a-553e68043e86', '电子对抗兵', '①应用电子对抗装备遂行电子对抗侦察和电子干扰任务的部队和分队的统称。包括雷达对抗部队、分队和通信对抗部队、分队。通常用于协同作战,也可单独遂行作战任务。②从事电子对抗专业的士兵。', 5);
INSERT INTO `t_military_term_data` VALUES ('feedc7e0-9d86-4750-8ebb-fea808e03c07', '31f4a446-5b98-4873-9d53-310d97125b07', '导弹机动发射', '利用移动发射装置在运动中或运动到某点快速定位后进行的导弹发射。包括地面、地下、水面、水下和空中机动发射等。地面机动发射,是将发射装置配置在车辆上实施预有准备的越野机动发射和铁路机动发射；地下机动发射,是将发射装置配置在隧道、坑道内或掩体基地实施的隐蔽机动发射；水面和水下机动发射,是将发射装置配置在舰船、潜艇上实施的发射；空中机动发射,是将发射装置配置在飞机上实施的发射。', 114);
INSERT INTO `t_military_term_data` VALUES ('feeebf4b-bb8f-4086-a578-ece348b2f368', '98df76fb-4b65-48ff-a56c-4db587327c79', '消耗限额', '根据后勤保障能力状况、上级为下级规定的一次战役、战斗或一定时间内允许消耗物资的最大限量。通常由后勤部门协同司令部门提出建议,报合成军队首长批准后,以命令的形式下达。', 126);
INSERT INTO `t_military_term_data` VALUES ('fef5e562-4542-4d03-bb46-e9ab3eb57985', '6866d5d5-80c3-41b3-9d96-9e5ba253e0b1', '定向能武器', '采用定向能技术，以很小的发散角发射高能量射束毁伤目标的武器。如激光武器、粒子束武器和微波武器等。', 45);
INSERT INTO `t_military_term_data` VALUES ('fef650d0-3c6e-4c4e-bc4b-9d210d1e12a4', '97a19170-bfac-42c5-9906-1acb187f0654', '飞机颤振', '飞机在一定的飞行速度下产生的自激振荡。主要是由于气动力与惯性力、弹性力的耦合作用,将气流能量转换为使飞机结构产生等幅振荡的能量所致。颤振达到一定强度时可使飞机解体。飞行员正确操纵可避免颤振。', 244);
INSERT INTO `t_military_term_data` VALUES ('fefb47cb-529e-45a2-a643-285cdfed6775', 'bc3c2dcb-5413-464e-b16c-baf4c506e5a7', '直升机反坦克', '武装直升机从空中以反坦克导弹、火箭、炸弹等对敌坦克进行的攻击行动。', 64);
INSERT INTO `t_military_term_data` VALUES ('ff057134-53e7-44a6-af2b-9b46162608e9', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '水质检查', '对水的物理性质、化学成分和细菌含量等进行的检测。包括对天然水、用水、废水的质量检查,并依据检测结果对水质作出定性和定量的评价。', 362);
INSERT INTO `t_military_term_data` VALUES ('ff26197e-cdbd-4477-8850-32d5aee595a9', 'f0140091-c11a-48c9-8836-8aa94439dac0', '突破口', '在敌防御部署中打开的缺口。其宽度和深度应能保证后续梯队进入战斗及发展进攻。', 191);
INSERT INTO `t_military_term_data` VALUES ('ff26593d-f923-479e-8217-734ee77ff6d7', '8a761efd-50a6-4ac8-9913-b7d745104f82', '手榴弹失手保险', '碰炸型手榴弹在保险解脱,失手落地时仍能保证该弹不爆炸的装置。', 229);
INSERT INTO `t_military_term_data` VALUES ('ff33a596-2930-4754-8785-f449667e48d0', '85fe7ebb-ffe1-4a25-8bd0-bcca17a792b3', '涵洞', '修筑于路基和堤坝下的泄水通道。有管形、箱形和拱形等,可以是单孔或多孔。常建于铁路或公路与沟溪的交叉处。', 110);
INSERT INTO `t_military_term_data` VALUES ('ff3b7788-0eca-4343-a06b-aaceb5dd5df7', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '收容所', '军队在执行警备勤务中,临时收留严重违纪的过往军人和严重违章的过往军车的机构。', 63);
INSERT INTO `t_military_term_data` VALUES ('ff425c1a-bf73-45bf-9924-08a17f472eab', '83e065b4-6737-4645-9ea5-8276d1de13ed', '装甲车辆浮渡设备', '为保障装甲车辆浮渡而随车配备的制式专用辅助设备。由折叠式浮渡围帐或悬挂式漂浮器材、排水设备和救生设备等组成。', 149);
INSERT INTO `t_military_term_data` VALUES ('ff441d74-af3d-4b42-b900-ddf8ed8e66a8', 'c5ffc2a6-5861-4897-ab52-5bfbd03dc75f', '凌晨', '从零时起到天亮前的一段时间。', 144);
INSERT INTO `t_military_term_data` VALUES ('ff64c665-0725-45a4-b4a8-412e26f97bb2', '97a19170-bfac-42c5-9906-1acb187f0654', '空中全向攻击', '飞机从空中目标周围的任意方向对其进行的攻击。只有装备全向攻击的空空导弹和相应火控系统的飞机才能实施全向攻击。', 86);
INSERT INTO `t_military_term_data` VALUES ('ff65fca1-1e99-4589-a1b9-f89918b57d6e', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '舰队', '①主要担负某一海洋战区作战任务的海军一级组织。设有领导机关,下辖一定数量的潜艇部队、水面舰艇部队、海军航空兵部队、海军岸防兵部队、海军陆战队以及海军基地等。②根据作战、训练或其他任务需要,由多艘舰艇组成的临时编队。', 6);
INSERT INTO `t_military_term_data` VALUES ('ff73ae26-13f4-490c-a76b-cc11d7cd9b2d', '98df76fb-4b65-48ff-a56c-4db587327c79', '铁路便桥', '技术标准较低、工程量较小的临时性铁路桥梁。由临时性桥墩、桥台、短跨轻便梁和简易桥面构成。战时当铁路正桥遭受破坏短期难以修复时,作为应急性桥梁使用,有时也作为预备桥梁。', 260);
INSERT INTO `t_military_term_data` VALUES ('ff7af8ba-114d-46c5-b8da-0a6f7aae2b20', '06a75831-13a1-4660-870a-455bb445336a', '发信机', '亦称通信发射机。将通信信息转换成射频信号，通过天线发射出去的无线电技术设备。按调制方式，分为调幅发信机、调频发信机和单边带发信机等。由振荡器、调制器和功率放大器等部件组成。可发送电话、电报、数据、图像等。', 187);
INSERT INTO `t_military_term_data` VALUES ('ff7cc829-b709-489a-bcba-c9caeb035307', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '战备检查', '对部队战备状况的检查。检查内容主要包括战备教育、战备训练、武器装备、行动方案、战场设施、物资储备等。', 106);
INSERT INTO `t_military_term_data` VALUES ('ff83ea32-f5e3-4be9-ac56-8109719e8af4', 'e960e1b4-b238-4923-84b3-f4aed5c745b4', '换件修理', '对武器装备进行更换其零部件的修理、相对于原件修理而言。', 123);
INSERT INTO `t_military_term_data` VALUES ('ff8d399e-cdd7-4d03-be4b-d3602a55784a', '97a19170-bfac-42c5-9906-1acb187f0654', '航空燃烧炸弹', '主要以弹体爆炸后燃烧剂产生的高温火焰杀伤人员、破坏目标的航空炸弹。分为集中性航空燃烧弹和散布性航空燃烧弹。集中性航空燃烧弹装有固体燃烧剂,爆炸后形成集中火源,可破坏不易燃的目标；散布性航空燃烧弹装有粘性燃烧剂,爆炸后燃烧剂抛散在一个较大面积内,可破坏易燃的大面积目标。', 326);
INSERT INTO `t_military_term_data` VALUES ('ff8eeea1-fae3-4cad-8419-f1c1e563bd7e', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '配置', '作战时根据任务、敌情和地形,将兵力、兵器布置在适当的位置。', 311);
INSERT INTO `t_military_term_data` VALUES ('ff96d02e-0c69-4ec3-a3cf-b4f454bb1a2f', 'e3538393-77f9-405c-ba7c-013740fb4a4c', '革命伤残军人', '中国人民解放军和中国人民武装警察部队中因战、因公、因病致残,经规定的审批机关批准,并取得《革命伤残军人证》的人员。', 75);
INSERT INTO `t_military_term_data` VALUES ('ff98df46-43f9-43a6-a104-1735d4d1e0e1', 'f0140091-c11a-48c9-8836-8aa94439dac0', '遮蔽', '遮住目标,防止敌人发现的行动。主要方法有利用地形、设置遮障、进行迷彩伪装、施放烟幕、使用角反射器等。', 118);
INSERT INTO `t_military_term_data` VALUES ('ffa18ad0-1e35-46db-adc8-b8c173545bcc', 'a447b1d3-3887-4563-90d5-c53f5adbe92c', '炮兵射击弹道准备', '炮兵射击前准备弹药和确定射击弹道条件偏差量的工作。主要包括：区分、分配弹药,确定火炮及装药的批号初速偏差量（火箭弹批号速度偏差量）、装药温度和其他弹道特性的偏差量等。', 134);
INSERT INTO `t_military_term_data` VALUES ('ffb38e9d-7dcc-41de-856b-ebd815fe9eb4', '8f5e1e02-0dad-4fb2-a99c-a5846a6538bd', '徒步行军', '以步行方式实施的行军。通常在没有输送工具或不便于乘车行军时采用。', 42);
INSERT INTO `t_military_term_data` VALUES ('ffb50d12-3413-4d57-bdd7-776a71ce0cb4', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '海上编队内部通信', '为保障海上编队内部的指挥、协同和情况报知而建立的通信。包括超短波无线电通信和视觉通信。', 358);
INSERT INTO `t_military_term_data` VALUES ('ffc2f8b3-b1b7-4a62-9ddb-26bc4a9f7f92', 'a4863f1e-20b3-4ef0-8aef-3d7c3edf743a', '雷场勤务', '地雷场的警戒、检查、维护以及对地雷场中预留通路的表示与封闭等工作的统称。通常由设置地雷场的分队负责。', 194);
INSERT INTO `t_military_term_data` VALUES ('ffc78ec9-1ef4-41d9-b614-5b3a8876a3eb', 'f0140091-c11a-48c9-8836-8aa94439dac0', '核突破口', '现称核突击缺口。使用核火力在敌防御部署中打开的缺口。', 193);
INSERT INTO `t_military_term_data` VALUES ('ffc8a84d-9982-45b4-8926-92f202976f1e', '8855a63f-abce-4eb8-b14a-2d3005f88b95', '军队编制', '军队各级各类建制单位的机构设置和人员、装备编配的具体规定。分为平时编制和战时编制。由最高军事领导机关或其授权机关制定。以编制表形式颁发。是军队编成的法规和军队建制单位设置、控制定额、配备干部、补充兵员、配发武器装备的准则与依据。', 58);
INSERT INTO `t_military_term_data` VALUES ('ffc9cbc6-2c80-40d3-9948-e93a8b7834be', 'e99fe0d8-e427-4e33-a309-b3f6e07579e3', '线导鱼雷', '有线制导鱼雷的简称。由舰艇或航空器通过导线传输指令制导的鱼雷。通常装有末段声自导装置。鱼雷发射后用线导方式遥控,当进入末自导作用范围时,即自动搜索攻击目标。', 203);
INSERT INTO `t_military_term_data` VALUES ('ffd8fbdd-6f6e-4b96-8db9-791846ff5d65', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '重点设防', '在重要的方向或地域有重点地设置防御体系。', 413);
INSERT INTO `t_military_term_data` VALUES ('fff29cfa-7601-4050-8324-ab15d628d573', '83e065b4-6737-4645-9ea5-8276d1de13ed', '坦克区分火力', '坦克连、排将各排或车的火力分别射向不同目标。', 45);
INSERT INTO `t_military_term_data` VALUES ('fff34911-8fd0-4ad4-bc0e-ba4ddb4811b2', '9dfa783a-1021-4917-a2a3-3dfae6f0b523', '作战样式', '按敌情、地形、气候等不同情况对作战类型的具体划分。如按敌情,进攻作战可具体划分为对预有准备防御之敌、立足未稳之敌、运动之敌的作战；防御作战可具体划分为阵地防御、运动防御、机动防御、仓促防御作战。按地形、气候等条件,对进攻、防御作战还可具体划分为山地、荒漠草原地、水网稻田地、热带山岳丛林地、高寒地等作战。', 130);
