INSERT INTO `t_theory_knowledge_swf` VALUES ('0462758f-1708-4a66-829b-efab2a21a259', '44117277-36fc-47aa-a33b-24fe37e5db0d', '/006/cover/base.jpg', '握姿要领', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; &nbsp;右大臂下垂；小臂抬起，与手腕、中指成一线并与桌面平面构成15度左右的夹角，并且与电子键的键盘略成平行；四个手指弯曲成弧形，指尖在一条水平线上（小指较短或中指较长者都可略成弧形），按手指的分工轻扶在基准键上，手背不要绷的过紧或松软无力；握键要轻松自如，保持自然。</span></p>', '2', '1677566885771', 1, NULL, NULL, 0);
