INSERT INTO `t_theory_knowledge_swf` VALUES ('369d2a13-4c71-4324-bedb-1d3a5fcffbc9', '44117277-36fc-47aa-a33b-24fe37e5db0d', '/006/cover/base.jpg', '用力要领', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; &nbsp; &nbsp;拍发用力主要是小臂、手腕、手指三者的合力。小臂力起主导作用，经过手腕传到手指，通过手指的支撑作用将键击下。</span></p>', '2', '1677566932459', 2, NULL, NULL, 0);
