INSERT INTO `t_theory_knowledge_swf` VALUES ('3d65fc8a-3ab1-43e8-8537-ea0320b3ecf4', '0792a8f2-f79a-4db2-8b36-22045dd10a88', '/006/cover/base.jpg', '电离层传播的基本原理', '<p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_13.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_14.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_15.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_16.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_17.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_18.png\"/></p><p><br/></p>', '2', '1659326244782', 3, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('3e600e69-ee3c-4e9d-a52b-f47301ca9856', '5f2351fe-4a53-453c-8d03-3653b0702c5b', '/006/cover/base.jpg', '基础知识', '<p>IO片；就；O记</p>', '2', '1678173481378', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('3fd828ea-ceef-480a-a813-ef609834e2e1', 'a3a597f7-931b-4eec-99d1-43a65c3f184d', '/006/cover/base.jpg', '手键拍发要领', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; 腕部活动均匀有力，腕部上下垂直活动，活动幅度一致，力量大小一致，下打、回复要干脆、敏捷。为达到以上要求，手背应相对绷紧，手腕要放平，拍发是腕部要按照三条水平线运动。<br/>&nbsp; 初学时腕部活动的三条水平线是：<br/>&nbsp; 水平线--按照正确的握键姿势，静止时腕下平面与键钮底盘构成的一条线；<br/>&nbsp; 上水平线--手腕抬起时，手腕下平面与键钮顶端所构成的一条线；<br/>&nbsp; 下水平线--手腕打下时，手腕下平面与电键底座所构成的一条线。<br/>&nbsp; 水平线上下的活动范围将随电键的高低和速度的快慢而变化。但从水平线到上水平线和水平线的距离始终是相等的。</span></p><p><img alt=\"\" src/></p><p><br/></p>', '2', '1677569028813', 2, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('4ae9b96e-a06c-4863-8424-cca4d9ed2bfc', '0792a8f2-f79a-4db2-8b36-22045dd10a88', '/006/cover/base.jpg', '无线电干扰', '<p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_19.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_20.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_21.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_22.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_23.png\"/></p><p><br/></p>', '2', '1659326267694', 4, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('54f7157a-7008-4da4-a086-65ccebee09ec', '0792a8f2-f79a-4db2-8b36-22045dd10a88', '/006/cover/base.jpg', '无线电波的传输方式', '<p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_07.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_08.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_09.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_10.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_11.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_12.png\"/></p><p><br/></p>', '2', '1659326201615', 2, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('562b4b98-8834-4728-bc34-45ff50b92526', '63386180-be2c-4629-b6ed-ed4891a261a1', '/006/cover/base.jpg', '野战分队', '<p><span style=\"font-size:24px;font-family:宋体\">手键拍发<br/>&nbsp;&nbsp;&nbsp; \n持续拍发200组。拍发报文准确无误，清楚正规，间隔均匀，速度平稳，快慢自如，有持久力，得100分。错号每个扣0.5分，超过6个（不含）每个扣1分；每低于分速一码扣5分；点粗、点虚、点松、点不均、划长、划短、间隔不均5处以内没处扣1分，5处（不含）以上每项扣10分；单字脱节、连码，5处以内没处扣2分，5处（不含）以上每项扣10分；错发1组、漏发、多发、拍发不清未更正每处扣20分；单字严重脱节、痼癖性连码、大小间隔不分，各扣15分。义务兵：分速74/65码；一级士官：分速80/70码；二级以上士官：分速90/80码。<br/><br/>考核：在本科目或阶段训练结束时进行；实际操作；达到80分（含）以上为合格，否则为不合格。<br/></span></p>', '2', '1677568753932', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('5bb307fb-6d0b-4f19-9ddb-9ec3c8cc26c7', 'b9e71136-96ad-425f-aacf-bf6ea15429fc', '/006/cover/base.jpg', '上传版本最终测试', '<p>aaaa</p>', '2', '1660182151884', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('62e0ffa0-c556-4694-836b-507c38bb6e27', '9fcf399e-8999-4da6-9b62-4c6670f41428', '/006/cover/base.jpg', '情况处理', '<p><span style=\"font-family:宋体\"><span style=\"font-size:24px\">1、错字的处理<br/>&nbsp;&nbsp;&nbsp; \n在进行报文拍发时，报文中任何一处发错都要用改错符号（斜线）将该组报文更正。其具体方法是：<br/>&nbsp;&nbsp;&nbsp; 第一码发错，拍发三个斜杠一个间隔。<br/>&nbsp;&nbsp;&nbsp; \n第二码发错，拍发二个斜杠一个间隔。<br/>&nbsp;&nbsp;&nbsp; 第三码发错，拍发一个斜线一个间隔。<br/>&nbsp;&nbsp;&nbsp; 第四码发错，拍发一个斜线不拍发间隔。<br/>&nbsp;&nbsp;&nbsp; \n第四码发错已发间隔，拍发四个斜线一个间隔。<br/>2、报文中有漏改的错字，在行尾或页尾更正。<br/>&nbsp;&nbsp;&nbsp; \n本页更正，只标明更正的组位数和该组正确的报文。<br/>&nbsp;&nbsp;&nbsp; \n行尾更正，在该行拍发完毕时，拍发出所需更正的组位数和该组的正确报文，并分别以一个间隔相区分。<br/>&nbsp;&nbsp;&nbsp; \n页尾更正，在该页标明页数后，拍发“回车”键一次，拍发出所需更正的组位数和该组的报文，并以一个间隔相区分，然后再拍发“回车”键一次。<br/>&nbsp;&nbsp;&nbsp; \n隔页更正，除标明所需更正的组位数和该组正确的报文外，还要标明页数和页的符号。<br/>&nbsp;&nbsp;&nbsp; \n改错时，若下一组第一码发错，且上一组又漏发了间隔，可拍发四个斜线一个间隔，将该组和上一组一起更正。<br/>3、三、五码的处理<br/>&nbsp;&nbsp;&nbsp; \n报文中出现三、五码，可按错字的处理方法进行处理，如果本组第四码掉了，且已发了间隔，将第四码补发，再发一个间隔。<br/>4、多、少组的处理<br/>&nbsp;&nbsp;&nbsp; \n报文中出现多、少组，应在页尾（或行尾）用更正的方法处理。<br/>&nbsp;&nbsp;&nbsp; 多组：拍发出“取消”单词（QTA）和需取消的组位数，中间以一个间隔相区分。<br/>&nbsp;&nbsp;&nbsp; \n少组：拍发出“增加”单词（ADD）和组位数及该组报文，中间分别以一个间隔区分。<br/>5、多、少行的处理<br/>&nbsp;&nbsp;&nbsp; \n报文中出现多、少行，可在页尾更正：拍发“取消”（QTA）或“增加”（ADD）单词以及XX组至XX组（以三横线相区分）。<br/>6、串行的处理<br/>&nbsp;&nbsp;&nbsp; \n报文中出现串行，可在页尾按实际拍发的组数进行更正。<br/>&nbsp;&nbsp;&nbsp; 串多，按多行的处理方法处理。<br/>&nbsp;&nbsp;&nbsp; \n串少，按少行的处理方法处理。<br/>7、标页错误的处理<br/>&nbsp;&nbsp;&nbsp; (1)漏页标符号：拍发四个斜线一个间隔，将第一百组更正重新标页。<br/>&nbsp;&nbsp;&nbsp; \n(2)漏标页（已自动换行）：拍发出第一百组的组位数和报文以及页标符号和页数。<br/>&nbsp;&nbsp;&nbsp; \n(3)标错页：拍发一个斜线，按正确的页数重新标页。如果已回车换行，可按漏标页的处理方法处理。<br/>&nbsp;&nbsp;&nbsp; \n(4)如果超过一页后对标页错误进行处理，可按实际拍发报文的页数进行更正。</span></span></p>', '2', '1677565452618', 2, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('69004dca-60d3-43a6-9480-bbc1349472a0', 'b0d287bc-138f-4a68-a7e5-50000b2640b5', '/006/cover/base.jpg', '机上发报（话）', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; &nbsp; &nbsp;1、信号、电报拍发次序<br/>&nbsp;&nbsp;&nbsp;&nbsp;a.&nbsp;警报信号<br/>&nbsp;&nbsp;&nbsp;&nbsp;b.&nbsp;无线电信号<br/>&nbsp;&nbsp;&nbsp;&nbsp;c.&nbsp;特加急<br/>&nbsp;&nbsp;&nbsp;&nbsp;d.&nbsp;加急报<br/>&nbsp;&nbsp;&nbsp;&nbsp;e.&nbsp;急报<br/>&nbsp;&nbsp;&nbsp; \n另外，如果遇到全程预告电报和限时电报时，可以优先处理。<br/>&nbsp;&nbsp;&nbsp; 2、手键（电子键）报拍发方法<br/>&nbsp;&nbsp;&nbsp; （一）发报程序<br/>&nbsp;&nbsp;&nbsp; “电报”单词&nbsp;&nbsp; \n&nbsp;&nbsp;1次<br/>&nbsp;&nbsp;&nbsp; 号数单词与号数&nbsp;&nbsp; 1次<br/>&nbsp;&nbsp;&nbsp; 组数单词及组数&nbsp;&nbsp; 1次<br/>&nbsp;&nbsp;&nbsp; 电报等级（代码）&nbsp;1次<br/>&nbsp;&nbsp;&nbsp; \n月日&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;1次<br/>&nbsp;&nbsp;&nbsp; 时分&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 1次<br/>&nbsp;&nbsp;&nbsp; 附注单词及内容（没有则不发）<br/>&nbsp;&nbsp;&nbsp; \n开始符号&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;1次<br/>&nbsp;&nbsp;&nbsp; 报文&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;1次<br/>&nbsp;&nbsp;&nbsp; 完结符号&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;1次<br/></span><span style=\"font-size:24px;font-family:宋体\">&nbsp;&nbsp;&nbsp; 3、拍发电报的要求<br/>&nbsp;&nbsp;&nbsp; \n发报应当根据先急后缓、先主要方向后次要方向的原则办理，如果有数份同等级的电报时，应当按电报时间的先后拍发（时间相同的电报按号数先后拍发），或者按照上级的指示和机要部分的通知拍发。转报与直达的电报等级相同时，应当优先办理转报。<br/>&nbsp;&nbsp;&nbsp; \n双方有多份同等级电报时，一般应当交叉作报。当双方工作比较顺利时，除特急报外，不同等级的电报也可以交叉拍发。交叉作报时，每次发报和重复应当按先本台后对方的方法进行。<br/>&nbsp;&nbsp;&nbsp; \n在一般情况下，要征得同意才能拍发电报。本台电报比对方急时，也可以主动拍发。在有特急电报或者信号，而又长时间联络无效时，可以进行转发或者盲发，但事后应当继续设法沟通联络和索取收据。<br/>&nbsp;&nbsp;&nbsp; \n发报中某一码发错或者未发清楚，应当拍发错误符号，从本组第一个码重发。如果发现前一组发错或者发的不清楚时，应当发“FM”，而后从前一组重发。<br/>&nbsp;&nbsp;&nbsp; \n试发一段后，应当拍发句号和组位数；继续拍发时，应当发出始发组位数和“开始符号”。每发完100组，应当拍发句号；接发下页时，拍发页号与分段符号。最后拍发完结符号。<br/>&nbsp;&nbsp;&nbsp; \n报头及组位数中的“0”拍发一划。如果遇有电报号数为字码混合时，数码均发长码。通信勤务暗语、识别暗令和信号中的数码均发长码。<br/>&nbsp;&nbsp;&nbsp; \n电码代号、通信勤务暗语中的代码及改换的具体频率均应为加密拍发，约会联络时间和改换频率（信道）的序号均明发。 <br/>&nbsp;&nbsp;&nbsp; 4、通报电报<br/>&nbsp;&nbsp;&nbsp; \n通报电报发给全网所有或部分属台时，应当与全部或者部分属台沟通后再发报。有把握时也可以长呼叫后即发报，并在发报中穿插呼叫未沟通的属台，并告其抄报。报量较大时，应当在发报过程中，了解对方台抄收电报情况。<br/>&nbsp;&nbsp;&nbsp; \n通报电报发给全部属台，应当在报头发往栏内拍发“CQ”；只发给部分属台，则应当在报头附注栏内拍发有关属台电报代码。<br/>&nbsp;&nbsp;&nbsp; \n专设通播台，通常是定时发信，呼叫三至五分钟后即拍发通播电报。必要时，可以发两遍。索取收据时，在另外的专向网络或者有限点报站重复和索取收据。<br/>&nbsp;&nbsp;&nbsp; \n5、信号<br/>&nbsp;&nbsp;&nbsp; 警报信号<br/>&nbsp;&nbsp;&nbsp; \n未沟通的电台有警报信号呼叫时，应当在每遍呼叫后即发出“警报信号”单词和信号内容。已经沟通联络的电台，有警报信号时，应当立即发出“警报信号”单词和信号内容。<br/>&nbsp;&nbsp;&nbsp; \n警报台拍发警报信号后，应当通过其他途径索取收据。在专向、网络工作的电台拍发警报信号时，抄收无误后，应当立即给对方收据。<br/>&nbsp;&nbsp;&nbsp; 无线电信号<br/>&nbsp;&nbsp;&nbsp; \n拍发无线电信号时，应当在每遍呼叫后，拍发无线电信号呼号，表示有无线电信号。<br/>&nbsp;&nbsp;&nbsp; \n无线电信号一般应当在沟通后拍发。必要时也可以在呼叫后即发，或者在听不到对方回答时，进行盲发，但事后必须设法沟通联络索取收据。<br/>&nbsp;&nbsp;&nbsp; \n无线电信号应当编号数，送到电台的时间填写在信号纸的“时间”栏内，号数和时间应当与信号内容一并发出。</span></p>', '2', '1736318892745', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('6eacd4d6-8424-438c-aaf1-189a0cef17c3', 'b6dc209d-88cf-4c3b-b231-40df787dbf23', '/006/cover/base.jpg', '表报填写方法', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; &nbsp; &nbsp;电台通报通常所设立的登记有：电台日记、收报登记、发报登记、转报登记、无线电通信值勤日（月）报表等表报。根据工作需要也可建立上级通知登记、事故差错登记、器材请领消耗登记等。<br/>&nbsp;&nbsp;&nbsp; \n填写各种表报，必须准确、清楚，重要的内容，应当随时填写，一般的内容应当利用电台工作空隙时间填写。在工作很忙或者不能记载的情况下，可以在事后补记，一般情况下，不能因填写表报而耽搁工作。</span></p>', '2', '1677564381795', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('6f15de4a-b0ad-41b9-a501-4d0eee5a7b68', '44117277-36fc-47aa-a33b-24fe37e5db0d', '/006/cover/base.jpg', '动作要领', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; &nbsp;准备：右手的食指、中指、无名指及小指弯曲成弧形（四个手指的指尖应保持在一条直线上，中指较长或小指较短者也可成弧形），大指姆自然外张，按握键要求将手上抬起基准键的上方约2-3厘米处，保持手型、准备击键。<br/>&nbsp; &nbsp;击键：在击键意识的支配下，小臂上下运动所产生的力量，经过手腕传递到击键手指上，带动右手整个向下运动。手即将传递到击键手指上，带动右手整体向下运动。手即将接触目标键之前的瞬间，击键指有意思地伸出约0.5-1厘米（其他手指要保持手型，不要里勾外翘）击键。击键力量的大小以能击下目标键为宜。<br/>&nbsp; &nbsp;恢复：目标键击下后，右手借助击键指下达时产生的反作用力，恢复（先弹后抬）到原来的高度（在手恢复的过程中击键手指要自然放松收回）并移至下一个目标键的上方，准备击键（单字练习时，手要恢复基准键的上方）。</span></p><p><br/></p>', '2', '1677566968523', 3, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('6ff6f7b2-b362-441e-98ea-23df0244a32e', '4161a96c-7858-4471-b03d-cacc0aed468d', '/006/cover/base.jpg', '固定台站', '<p><span style=\"font-size:24px;font-family:宋体\">电子键数码拍发<br/></span><span style=\"font-size:24px;font-family:宋体\">&nbsp;&nbsp;&nbsp; \n持续拍发数码报文200组，平均分速120码。拍发报文准确无误得100分；低于规定分速，每码扣2分；改错4个以上每个扣0.5分；超过4个（不含）每个扣1分；多发、少发没处扣10分，错码没处扣35分。</span></p><p><span style=\"font-size:24px;font-family:宋体\">考核：在本课目或阶段训练结束时进行；<br/>实际操作：达到80分（含）以上为合格，否则为不合格。</span></p><p><br/></p>', '2', '1677566647391', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('7283a0a7-4ea0-4314-a2aa-b409e00157db', '5864a20f-012d-4c94-a924-ced9f3f8015b', '/006/cover/base.jpg', '执掌测试1', '<p style=\"line-height: 1.75em;\">&nbsp; &nbsp; &nbsp; &nbsp; 发报是无线电通信人员必须掌握的收、发、通三大技术之一，它是学习的重点，也是难点。无线电通信人员发报技术的好坏，通常称为手法的好坏，它同一个人的口才一样, 口才好，说话清楚流利，听得就明白，如果口才不好，咬字不清，结结巴巴，就会使对方听起来感到困难。同样，如果手法好，对方收报就会省时省力。如果手法不好，对方收报就会感到困难，容易产生错误，影响速度和准确性，甚至会耽误军事行动，造成战斗失利。因此，无线电通信人员必须掌握熟练地发报技术。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是发报的工具，只有了解它，才能熟练地使用它，如图3-1所示为电键构造。</p><p style=\"text-align: center; line-height: 1.75em;\"><img src=\"http://10.10.0.99:8003/ueditor/image/20220124/1643014090102tkjsge.png\" title=\"1643014090102tkjsge.png\" alt=\"s1.png\"/></p><p style=\"text-align: center; line-height: 1.75em;\">图3-1电键构造图</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我们使用的电键，通常叫手键，手键由如下部分组成：</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键钮一手握的地方，由胶木做成，键簧，钢丝绕成，富有弹性，压在键梁下面；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;接触点一弹簧与键钮之间（上下两个）突出部分；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键梁一架在电键中间的一根金属长条；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;螺丝一左右螺丝，用于固定键梁，调整键梁位置，使上下接点对准，以免左右移动。高低螺丝，用于调整两个接触点的高低。松紧螺丝，用于调整弹簧的松紧，适应发报的用力； 导线一两根连到两个接触点的导线；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;插头一外层是胶木，里层是两个互相绝缘的金属芯，分别连接导线，用于接通电键和机器；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键盘一上层是胶木，下层是铁盘，用于固定零件。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是无线电报务员手中的武器，必须很好地认识它，正确地使用它，才能较好地发挥发报技术。弹簧的软硬影响着用力，弹簧硬一些，有利于锻炼腕力和指力，尤其是发报的基础阶段，有利于充分地体会腕力，但是弹簧太硬，容易使人疲劳，反而会影响用力，同时不利于高速拍发。弹簧软一些，有利于腕力和指力的配合，尤其是高速拍发，有利于充分发挥指力的作用。但是，弹簧太软，容易使腕力遭到破坏，而单纯地运用指力，会造 成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;触点高低对用力也是有影响的。电键的接触点高一些，能够锻炼手指的支撑力和手腕的下打力，有利于充分体会用力。但是过高，容易出现浑身用力，拍发吃力，点划脱节等问题。电键的接触点低一些，拍发起来省力，对提速、高速拍发有利。但是过低，容易出现用力靠手指挤抠等问题，造成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;综上所述，初学阶段，电键要调的硬一些，高一些。随着用力的不断掌握和发报技术的不断提高，电键的软硬、高低可根据需要进行必要的调整。但要切记，不能调的太软过低。一般说来，初学阶段，电键软硬、高低应由教员掌握。</p><p><br style=\"white-space: normal;\"/></p><p><br/></p>', '2', '1656399324379', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('75ce6901-b316-46b4-aeb2-973c82eef4b9', 'a2a0195b-3f9d-4ae6-a5cc-94e8697e1235', '/006/cover/base.jpg', '执掌课件2', '<p style=\"line-height: 1.75em;\">&nbsp; &nbsp; &nbsp; &nbsp; 发报是无线电通信人员必须掌握的收、发、通三大技术之一，它是学习的重点，也是难点。无线电通信人员发报技术的好坏，通常称为手法的好坏，它同一个人的口才一样, 口才好，说话清楚流利，听得就明白，如果口才不好，咬字不清，结结巴巴，就会使对方听起来感到困难。同样，如果手法好，对方收报就会省时省力。如果手法不好，对方收报就会感到困难，容易产生错误，影响速度和准确性，甚至会耽误军事行动，造成战斗失利。因此，无线电通信人员必须掌握熟练地发报技术。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是发报的工具，只有了解它，才能熟练地使用它，如图3-1所示为电键构造。</p><p style=\"text-align: center; line-height: 1.75em;\"><img src=\"http://10.10.0.99:8003/ueditor/image/20220124/1643014090102tkjsge.png\" title=\"1643014090102tkjsge.png\" alt=\"s1.png\"/></p><p style=\"text-align: center; line-height: 1.75em;\">图3-1电键构造图</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我们使用的电键，通常叫手键，手键由如下部分组成：</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键钮一手握的地方，由胶木做成，键簧，钢丝绕成，富有弹性，压在键梁下面；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;接触点一弹簧与键钮之间（上下两个）突出部分；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键梁一架在电键中间的一根金属长条；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;螺丝一左右螺丝，用于固定键梁，调整键梁位置，使上下接点对准，以免左右移动。高低螺丝，用于调整两个接触点的高低。松紧螺丝，用于调整弹簧的松紧，适应发报的用力； 导线一两根连到两个接触点的导线；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;插头一外层是胶木，里层是两个互相绝缘的金属芯，分别连接导线，用于接通电键和机器；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键盘一上层是胶木，下层是铁盘，用于固定零件。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是无线电报务员手中的武器，必须很好地认识它，正确地使用它，才能较好地发挥发报技术。弹簧的软硬影响着用力，弹簧硬一些，有利于锻炼腕力和指力，尤其是发报的基础阶段，有利于充分地体会腕力，但是弹簧太硬，容易使人疲劳，反而会影响用力，同时不利于高速拍发。弹簧软一些，有利于腕力和指力的配合，尤其是高速拍发，有利于充分发挥指力的作用。但是，弹簧太软，容易使腕力遭到破坏，而单纯地运用指力，会造 成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;触点高低对用力也是有影响的。电键的接触点高一些，能够锻炼手指的支撑力和手腕的下打力，有利于充分体会用力。但是过高，容易出现浑身用力，拍发吃力，点划脱节等问题。电键的接触点低一些，拍发起来省力，对提速、高速拍发有利。但是过低，容易出现用力靠手指挤抠等问题，造成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;综上所述，初学阶段，电键要调的硬一些，高一些。随着用力的不断掌握和发报技术的不断提高，电键的软硬、高低可根据需要进行必要的调整。但要切记，不能调的太软过低。一般说来，初学阶段，电键软硬、高低应由教员掌握。</p><p><br style=\"white-space: normal;\"/></p><p><br/></p>', '2', '1648604011771', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('771b0de4-da3c-4692-9b62-6a7b98e5ebc4', 'b0d287bc-138f-4a68-a7e5-50000b2640b5', '/006/cover/base.jpg', '结束联络', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; &nbsp; 1、手键（电子键）结束联络<br/>&nbsp;&nbsp;&nbsp; \n双方都收到“结束联络”的符号（SK），此次联络才能确认结束。<br/>&nbsp;&nbsp;&nbsp; 2、无线电话务结束联络<br/>&nbsp;&nbsp;&nbsp; \n双方沟通联络无事或者工作完毕后既可以结束联络，双方在发“无事”后，互相听到“再会”，此次联络才能确认结束。<br/>&nbsp;&nbsp;&nbsp; \n3、手键（电子键）结束联络<br/>&nbsp;&nbsp;&nbsp; 双方都收到“结束联络”的符号（SK），此次联络才能确认结束。<br/></span></p><p><br/></p>', '2', '1736318892763', 3, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('7a855a75-df7d-4627-b030-989c67fcbdf8', 'b9e71136-96ad-425f-aacf-bf6ea15429fc', '/006/cover/base.jpg', '上传版本最终测试2', '<p>默认课件内容asdasd</p>', '2', '1660182180695', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('7c1f3376-a781-43aa-b16b-0aed5c9fff93', 'b588d741-40b0-44d2-b079-aab0eca96106', '/006/cover/base.jpg', '姿势要领', '<p><span style=\"font-size:24px;font-family:宋体\">1、坐姿要领<br/>&nbsp;&nbsp;&nbsp; \n两脚自然着地与肩同宽，两小腿自立与大腿约成90度；上体自然端正，微向前倾，距桌沿约15厘米；两小臂放于桌面，左手扶抄报纸，右手握笔；两眼目视抄报纸。</span></p><p><span style=\"font-size:24px;font-family:宋体\"><img alt=\"\"/></span></p><p><span style=\"font-size:24px;font-family:宋体\">2、握姿要领<br/>&nbsp;&nbsp; \n右手拇指（指肚）、中指第一关节与食指相邻的一侧和食指指尖内侧合捏处呈一正三角形，外侧略成平面，距笔尖约3厘米左右；无名指和小指自然曲回掌心，笔身考住食指第三关节后部，倾斜与桌面夹度约45度，虎口向左上方，手掌右侧轻贴纸面。</span></p><p><span style=\"font-size:24px;font-family:宋体\"><img alt=\"\"/></span></p><p><span style=\"font-size:24px;font-family:宋体\">3、铅笔削法<br/>&nbsp;&nbsp;&nbsp; \n左手握笔，右手持刀，距铅笔顶端2.5公分处开始削，左手拇指向前推刀，右手掌握削的厚度，边削边转动铅笔，将铅笔的木质削成圆锥形，使笔芯露出0.5公分，最后将铅笔芯削好。</span></p><p><span style=\"font-size:24px;font-family:宋体\"><img alt=\"\"/></span></p><p><span style=\"font-size:24px;font-family:宋体\">4、书写要求<br/>&nbsp;&nbsp;&nbsp; \n笔路正确、字迹清晰、流畅圆润、排列整齐、大小适中、不连不草、美观端正、清楚正规。字体在书写时一般向右倾斜20度左右。<br/>&nbsp;&nbsp;&nbsp; \n书写数码时，码子高度约占电报纸格子的四分之三，每个格子应靠近格子的底线，并向格子左边靠拢，一组数码的宽度约占格子的五分之四。</span></p><p><img alt=\"\"/></p><p><br/></p>', '2', '1677568601292', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('7c9881a3-afe6-4e67-b138-88769195d51e', 'b0d287bc-138f-4a68-a7e5-50000b2640b5', '/006/cover/base.jpg', '沟通联络', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; &nbsp; 1、手键（电子键）联络方法<br/>&nbsp;&nbsp;&nbsp; （1）呼叫程序<br/>&nbsp;&nbsp;&nbsp; 呼号区分符号&nbsp;&nbsp;&nbsp; \n&nbsp;1-3次<br/>&nbsp;&nbsp;&nbsp; 对方电台被呼&nbsp;&nbsp;&nbsp; &nbsp;1-3次<br/>&nbsp;&nbsp;&nbsp; 呼号区分符号&nbsp;&nbsp;&nbsp;&nbsp; 1次<br/>&nbsp;&nbsp;&nbsp; 本台自用&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \n&nbsp;1-3次<br/>&nbsp;&nbsp;&nbsp; “请回答”单词&nbsp;&nbsp; 1次<br/>&nbsp;&nbsp;&nbsp; 有报时，在“请回答”单词前拍发“电报”单词和电报等级代码一次。<br/>&nbsp;&nbsp;&nbsp; \n（2）回答程序<br/>&nbsp;&nbsp;&nbsp; “听到了”单词&nbsp;&nbsp; 1次<br/>&nbsp;&nbsp;&nbsp; 对方电台被呼&nbsp;&nbsp;&nbsp; &nbsp;1-3次<br/>&nbsp;&nbsp;&nbsp; 呼号区分符号&nbsp;&nbsp;&nbsp;&nbsp; 1次<br/>&nbsp;&nbsp;&nbsp; \n本台自用&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1-3次<br/>&nbsp;&nbsp;&nbsp; “听到了”单词&nbsp;&nbsp; 1-2次<br/>&nbsp;&nbsp;&nbsp; 拍发守听对方信号强度<br/>&nbsp;&nbsp;&nbsp; \n问对方守听本台信号强度如何？<br/>&nbsp;&nbsp;&nbsp; “请回答”单词&nbsp;1次<br/>&nbsp;&nbsp;&nbsp; 本台无报，对方台有报时，在“请回答”单词前拍发“发下来”单词一次。<br/>&nbsp;&nbsp;&nbsp; \n本台有报，对方台无报时，在“请回答”单词前拍发“电报”单词和电报等级代码各一次。<br/>&nbsp;&nbsp;&nbsp; 对方有报时的回答：<br/>&nbsp;&nbsp;&nbsp; \n有两种情况，双方有同等级电报，另一种情况是双方有不同等级的电报。其回答的方法是：<br/>&nbsp;&nbsp;&nbsp; \n对方有报，但本台有较急的电报，回答时应当请对方电报稍等，并拍发自己电报等级代码，或者酌情试发一段。<br/>&nbsp;&nbsp;&nbsp; 对方有同等级电报时应交叉作报。<br/>&nbsp;&nbsp;&nbsp; \n每次呼叫或者回答一般应当在三遍以内，如遇有特殊情况时，可以酌情增加（减少）呼叫和回答的遍数。<br/>&nbsp;&nbsp;&nbsp; \n两遍以上的呼叫，在每遍呼叫结束时，应当加发呼叫区分符号（V）一次。情况好时，回答应当从简，一般拍发被呼和自用各一次，有时也可以只拍发本台各用一次。<br/>&nbsp;&nbsp;&nbsp; \n呼号中的数码均应拍发长码。<br/>&nbsp;&nbsp;&nbsp; 初次联络、长时间不联络或者遇到联络对象有异常时双方应当互相询问识别暗令。<br/>&nbsp;&nbsp;&nbsp; \n问令的拍发方法：识别暗令“IEC”单词一次，开始符号一次。暗令两组（问令），完结符号一次。<br/>&nbsp;&nbsp;&nbsp; \n答令的拍发方法：开始符号一次，暗令两组（与问令相对应的答令两组），完结符号一次。<br/>&nbsp;&nbsp;&nbsp; 2、暗令使用方法：<br/>&nbsp;&nbsp;&nbsp; \n暗令使用可以采用相邻对照法和十字交叉法。问答横排或者竖排相邻的两组，回答对应的答令两组。也可以分别问答十字交叉线分割的对角的两组，顺序为自上而下，由左至右。<br/></span></p>', '2', '1736318892696', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('84902aeb-6498-4a8d-b416-e043806e0d0e', '9fcf399e-8999-4da6-9b62-4c6670f41428', '/006/cover/base.jpg', '拍发要领', '<p>默认课件内容</p>', '2', '1677564919034', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('8501949d-904e-4a64-969b-6a6e72efdf5e', 'b6dc209d-88cf-4c3b-b231-40df787dbf23', '/006/cover/base.jpg', '发报登记填写', '<p><span style=\"font-size:24px;font-family:宋体\">1、填写内容<br/>&nbsp;&nbsp;&nbsp; \n电报、信号发往何台的电报代号、号数、组数、等级、原来时间。填写电报代号时应细致、准确。报头时间，是指机要部门拟制电报的时间。<br/>2、收到时间<br/>&nbsp;&nbsp;&nbsp; \n是机要人员或电报收发室人员将电报送达电台的时间。签名，是机要部门或电报收发室送来电报的人员。<br/>3、发出时间<br/>&nbsp;&nbsp;&nbsp; \n指电报发给发往对象后对方给收报的时间。发报人，指电台拍发此份电报、信号的报务员。如是两人以上分别拍发电报，可以拍发数量多者为主填写（或共同签名）。<br/>4、附注<br/>&nbsp;&nbsp;&nbsp; \n转报、通播电报、重收电报、业务公电和其他需说明的事项填写在“附注”栏内。<br/>&nbsp;&nbsp;&nbsp; \n退回发报底或被机要、收发室人员取走发报底时，应在“附注”栏内签名，记时。<br/></span></p><p><br/></p>', '2', '1677564450001', 2, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('87f7e18f-f1ab-4976-b7d2-60e8ef2e222e', 'a8653f8a-ceb4-4f1c-8e7b-631f94746ee9', '/006/cover/base.jpg', '野战分队', '<p><span style=\"font-size:24px;font-family:宋体\">数码拍发：<br/>&nbsp;&nbsp;&nbsp; \n持续拍发10分钟，其中手抄报底200组，报底不得重复，准确无误，报文整洁得100分；每低于分速1组扣4分；改错（补加1行，取消行，更正1组均算改错1处），报文正规（含改错不正规），两组中出现三、五码，多、少间隔，两页之间多、少行距，每处扣1分；多码、少码、压码、多行、错打、漏打页标，每处扣10分；错发1组、串行、少行、压行，每处扣10分、义务兵：分速50/40组；一级士官：分速60/50组；二级以上士官：分速65/55组。</span></p><p><span style=\"font-size:24px;font-family:宋体\">字码拍发：<br/>&nbsp;&nbsp;&nbsp; \n持续拍发5分钟，准确无误，报文整洁，得100每低于分速一码扣2分。其他同电传数码拍发。义务兵：分速90/80码；一级士官：分速100/90码；三级士官：分速110/100码；</span></p><p><span style=\"font-size:24px;font-family:宋体\">考核：在课目训练结束时进行；<br/>实际操作：达到80分（含）以上为合格，否则为不合格。</span></p><p><br/></p>', '2', '1677564803930', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('895906b3-1e37-4753-ad01-3bc1ab36bf64', '44117277-36fc-47aa-a33b-24fe37e5db0d', '/006/cover/base.jpg', '坐姿要领', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; &nbsp;两脚平放自然着地与肩同宽，两小脚直立与大腿约成90度；上体端正，大臂下垂（不操作时，两手放于膝盖上）；腹部离桌沿约15-20厘米；头稍向前倾，两眼目视拍发报底。电子键放置正对右臂，后部距离桌沿约5厘米；报底放置胸前桌面，底边距桌沿约5厘米。</span></p>', '2', '1677566787985', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('8b2fdb06-40e3-4cf9-9d71-1b85c05664b4', '6515c61a-55bb-4807-b207-52fd60aa93e7', '/006/cover/base.jpg', '手键发报介绍', '<p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;发报是无线电通信人员必须掌握的收、发、通三大技术之一，它是学习的重点，也是难点。无线电通信人员发报技术的好坏，通常称为手法的好坏，它同一个人的口才一样, 口才好，说话清楚流利，听得就明白，如果口才不好，咬字不清，结结巴巴，就会使对方听起来感到困难。同样，如果手法好，对方收报就会省时省力。如果手法不好，对方收报就会感到困难，容易产生错误，影响速度和准确性，甚至会耽误军事行动，造成战斗失利。因此，无线电通信人员必须掌握熟练地发报技术。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是发报的工具，只有了解它，才能熟练地使用它，如图3-1所示为电键构造。</p><p style=\"text-align: center; line-height: 1.75em;\"><img src=\"http://10.10.0.99:8003/ueditor/image/20220124/1643014090102tkjsge.png\" title=\"1643014090102tkjsge.png\" alt=\"s1.png\"/></p><p style=\"text-align: center; line-height: 1.75em;\">图3-1电键构造图</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我们使用的电键，通常叫手键，手键由如下部分组成：</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键钮一手握的地方，由胶木做成，键簧，钢丝绕成，富有弹性，压在键梁下面；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;接触点一弹簧与键钮之间（上下两个）突出部分；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键梁一架在电键中间的一根金属长条；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;螺丝一左右螺丝，用于固定键梁，调整键梁位置，使上下接点对准，以免左右移动。高低螺丝，用于调整两个接触点的高低。松紧螺丝，用于调整弹簧的松紧，适应发报的用力；&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 导线一两根连到两个接触点的导线；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;插头一外层是胶木，里层是两个互相绝缘的金属芯，分别连接导线，用于接通电键和机器；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键盘一上层是胶木，下层是铁盘，用于固定零件。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是无线电报务员手中的武器，必须很好地认识它，正确地使用它，才能较好地发挥发报技术。弹簧的软硬影响着用力，弹簧硬一些，有利于锻炼腕力和指力，尤其是发报的基础阶段，有利于充分地体会腕力，但是弹簧太硬，容易使人疲劳，反而会影响用力，同时不利于高速拍发。弹簧软一些，有利于腕力和指力的配合，尤其是高速拍发，有利于充分发挥指力的作用。但是，弹簧太软，容易使腕力遭到破坏，而单纯地运用指力，会造 成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;触点高低对用力也是有影响的。电键的接触点高一些，能够锻炼手指的支撑力和手腕的下打力，有利于充分体会用力。但是过高，容易出现浑身用力，拍发吃力，点划脱节等问题。电键的接触点低一些，拍发起来省力，对提速、高速拍发有利。但是过低，容易出现用力靠手指挤抠等问题，造成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;综上所述，初学阶段，电键要调的硬一些，高一些。随着用力的不断掌握和发报技术的不断提高，电键的软硬、高低可根据需要进行必要的调整。但要切记，不能调的太软过低。一般说来，初学阶段，电键软硬、高低应由教员掌握。</p><p><br/></p>', '2', '1643013835847', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('9afbbe4d-f0ef-4d94-b0b2-b2df748ccbd7', '6515c61a-55bb-4807-b207-52fd60aa93e7', '/006/cover/base.jpg', '第一节 发报姿势与用力', '<p style=\"line-height: 1.75em;\">（一）发报姿势</p><p style=\"line-height: 1.75em;\">&nbsp; &nbsp; &nbsp; &nbsp;手法好不好，取决于用力是否正确。而正确的坐握姿势对掌握正确的发报用力有着直接影响，初学时，要固定姿势，不能任意改变。坐的姿势要上体自然端正，距离桌沿约十 五公分。两脚自然着地，与肩同宽。电键的位置正对右臂，键钮底盘后部大致与桌沿取齐。 右手握键，左手放于桌面或指向报底行首，如图3-2所示。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;握健姿势目前有几种，但只要能掌握正确的用力，不管釆用娜种握键姿势都可以发却 报。初学时，必须按照教员指定的姿势进行练习，不得自己乱改姿势。一种是跪姿，右手 拇指自然微曲，第一关节扶于键钮左侧腰部；中指第一关节跪于键钮底盘右側，第二关节成垂于键钮顶峰前端；无名指、小指自然曲回掌心，腕部下平面与键盘略成水平，拇指和中指轻捏键钮，小臂、食指与键梁三点成一直线，大臂自然下垂略离上体，右肘大致成直角。握键要松紧适当，握的太紧影响发报动作的灵活性，过松了，用力分散，姿势容易变形，如图3-3所示。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;另<span style=\"color: rgb(123, 144, 175);\">一</span>种是立姿，立姿的握键姿势同跪姿握键姿势唯<span style=\"color: rgb(123, 144, 175);\">一</span>不同的是：中指的第一关节是立在键钮定盘右侧的。所以立姿的握键要领就不再重复了，如图3-4所示。</p><p style=\"line-height: 1.75em;\"><br/></p><p style=\"line-height: 1.75em;\">（二）发报用力</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;发报质量的优劣、速度的快慢，关键在于发报的用力是否正确。正确的发报用力，是腕、指、小臂的紧密配合，发报训练的整个过程主要体会和掌握用力的过程。学习发报基本以三个阶段。一是基础阶段，即拍发要领阶段；二是低速拍发阶段，即七十码以内；三是高速拍发阶段。作为初学者，必须在掌握了基本用力打好基础以后，才能逐渐地由低速拍发阶段向高速拍发阶段发展，如果不按照这个规律去进行学习，将欲速而不达。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;发报有腕力、指力和臂力，腕力即腕部上下垂直运动所产生的力量。它的要求是：腕部上下垂直运动，活动幅度一致，力量大小一样。要使腕部活动均匀、有力，必须手腕放平，手背绷紧，不前推后拉，动作灵活有力。拍发任何符号时，腕部都要体现出三条水平线。如图3-5所示。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;中水平线一按照正确的握键姿势，在静止时，手腕下平面所构成的一条线；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;上水平线一手腕抬起时，手背与手腕上平面所构成的一条线；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;下水平线一手腕下打时，手腕下平面所构成的一条线。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;掌握三条水平线是十分重要的，如果掌握得不好，手腕活动就会没有规律，直接影响到用力和拍发质量。掌握三条水平线的原则是：以中水平为基准，腕部上抬、下打都要幅度一致，低速拍发时，腕部活动幅度要大一些。上抬时手腕下部与键钮腰部略成水平，下打时手腕下部与键底盘略成水平，随着速度的提高，手腕上抬、下打的位置可以缩小一些, 但是一定要等幅。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;指力是手指的支撑力和弹力。手指作用是把腕部均匀有力的活动所产生的力借手指支撑力和弹力传送到键钮上，支撑力越强，弹力就越明显，其传导作用就越好。如果手指支撑力不强，腕部虽然活动均匀、有力，也会因手指的阻力，不能使力量全部传到键钮上去。且易形成姿势变形，点划不实，点划脱节等现象。手指的弹力是支撑力的发展，它有力加快腕部活动速度的作用。因此，在体会用力时必须加强手指的支撑力和弹跳力。具体方法是：手背绷紧，无名指、小指向手心握拢。指关节不能蠕动、下塌和变形。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;臂力是小臂肌肉的伸缩力，没有良好的小臂肌肉伸缩力，腕力就得不到充分的发挥。在体会小臂肌肉伸缩力时，要防止小臂压，大臂用力等现象。总之，发报的整个用力是以腕力带动指力，腕力、指力和小臂肌肉的伸缩力密切配合，协同用力，互相依赖，不能把这三种力截然分开。当小臂肌肉伸缩产生的力量和腕部均匀有力的活动所产生的力量通过手指传导到键钮的时候，三指力量分布是：中指的力量稍大，食指次之，大姆指只起辅助 作用。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;发报的用力要领可归为四个字，即抬、打、撑、弹。抬就是每拍发一码之前，先将手腕从静止状态（中水平线）抬至上水平线，动作要自然灵敏。打就是腕部从上平线垂直下打至下水平线，动作要短促，干脆有力。撑是中指、食指要有挺力，当腕部下打时中指、食指要用力支撑。弹是腕部下打后，借指力和弹簧的反弹作用，使手腕弹回上水平线。</p><p><br/></p>', '2', '1643014202996', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('9c4cf414-5339-4194-93eb-e3286e550a38', 'b6dc209d-88cf-4c3b-b231-40df787dbf23', '/006/cover/base.jpg', '电台日记填写', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; &nbsp; 电台日记和收、发报登记填写用铅笔，其它表报资料用蓝、黑色钢笔。<br/>&nbsp;&nbsp;&nbsp; \n电台日记应当填写下列内容：<br/>&nbsp;&nbsp;&nbsp; 日、月：填写联络时的日期。<br/>&nbsp;&nbsp;&nbsp; 联络对象：填写对方电台的电报代号。<br/>&nbsp;&nbsp;&nbsp; \n本台联络方式：填写本台本次联络的工作方式。如果用有线方式工作，填写“有线”；用单边带话开通自动通信终端方式工作，则视情填写“主呼”或者“被呼”；用上边带I路电传复接手键方式工作，填写“上边带”（USB）；用等幅报（手键或电子键）方式工作，填写“等幅报”（CW）。<br/>&nbsp;&nbsp;&nbsp; \n时间：填写开始联络、双方沟通和结束联络的时间。<br/>&nbsp;&nbsp;&nbsp; “时限”：按照不同网专和联络方式确定，填写“X分钟”（X M）。<br/>&nbsp;&nbsp;&nbsp; \n呼叫无效时间：填写自动通信网内本台本次联络的呼叫无效时间。<br/>&nbsp;&nbsp;&nbsp; 通信时间：填写本台本次联络的通信时间。<br/>&nbsp;&nbsp;&nbsp; \n工作情况记录栏的填写：填写收、发、转报的号数、组数、等级、收报时间等。记录简便，收用“R”、发用“S”、号用“#”表示，在号数和组数之间划一横线。无线电信号应当在“R”或者“S”之后，“#”之前填写无线电信号符号；警报信号应当在“R”或者“S”后面填写“警报信号”、信号内容和发出或者收到时间（时间用括号括起来）。填写工作中所处理的主要事物，如收、发电报，重发、重收、转报、转告、通信检查，改频的时间、频率，守听或者呼叫无效、联络的时间及原因，增加或取消电报，机线电设备故障的起止时间和采取的措施，以及工作中发生的通信事故和差错等。<br/>&nbsp;&nbsp;&nbsp; \n小结：本班工作的联络次数、时限内沟通次数、无效次数及主呼次数、被呼次数、呼叫无效时间、通信时间、通信时效和本班总的工作报量和总的通信时间等。<br/>&nbsp;&nbsp;&nbsp; \n交接班：待收、待发的电报及其它待办事项，上级有关指示重要的联络情况，临时约会的时间和频率，联络文件和机线设备状况，交、接班人员签名等。<br/>&nbsp;&nbsp;&nbsp; \n填写电台日记可以用通报用语，通报用语不能表达时，可以用文字记载，交接班内容应当用文字记载。<br/></span></p>', '2', '1677564614866', 3, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('a322214b-4fe3-4e38-9d56-64bd00ab4aa6', '9fcf399e-8999-4da6-9b62-4c6670f41428', '/006/cover/base.jpg', '拍发姿势', '<p dir=\"ltr\"><span style=\"font-size:24px;font-family:宋体\">1、坐姿<br/>&nbsp;&nbsp;&nbsp; \n两脚平行着地与肩同宽，小腿与地面垂直；上体端正，保持自然，大臂自然下垂，与上体之间距离约为10厘米，与小臂的角度略小于90度；腹部离键盘边沿约10厘米；头稍向前倾，两眼注视报底。</span></p><p><img alt=\"\"/><img alt=\"\"/></p><p><span style=\"font-size:24px;font-family:宋体\">2、握键<br/>&nbsp;&nbsp;&nbsp; \n大臂自然下垂，小臂抬起与大臂略成直角，肘部离上体约10厘米，小臂、手腕略成水平。八个手指自然弯曲成弧形，按手指分工轻扶在基准键上，指肚前段触键；手指不要绷得太紧或松软无力，手指第三关节要高于第二关节，中指与手腕、小臂基本成一条直线；右手拇指自然外张，悬于间隔键或字母下位键上方（左手拇指自然放置）。</span></p><p><span style=\"font-size:24px;font-family:宋体\"><img alt=\"\"/></span></p><p><br/></p>', '2', '1677564889391', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('a41ef032-9203-4de4-86b3-23269ffe0ce9', 'a3a597f7-931b-4eec-99d1-43a65c3f184d', '/006/cover/base.jpg', '发报姿势', '<p><span style=\"font-size:24px;font-family:宋体\">发报姿势：<br/>&nbsp;&nbsp;&nbsp; \n坐姿要领：上体自然端正，距离桌沿15厘米；两脚平放，自然着地，与肩同宽；电键的位置正对右臂，电键底盘后部大致与桌沿取齐；右手握键，左手放于桌面或指向报底；头稍向前倾；两眼注视报底。</span></p><p><br/></p>', '2', '1677568876653', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('a6074e32-45fd-4b59-916a-2312df088505', '6e78e49f-cbf0-4d65-aec4-49c052e4c826', '/006/cover/base.jpg', '航空兵测试', '<p style=\"line-height: 1.75em;\">&nbsp; &nbsp; &nbsp; &nbsp; 发报是无线电通信人员必须掌握的收、发、通三大技术之一，它是学习的重点，也是难点。无线电通信人员发报技术的好坏，通常称为手法的好坏，它同一个人的口才一样, 口才好，说话清楚流利，听得就明白，如果口才不好，咬字不清，结结巴巴，就会使对方听起来感到困难。同样，如果手法好，对方收报就会省时省力。如果手法不好，对方收报就会感到困难，容易产生错误，影响速度和准确性，甚至会耽误军事行动，造成战斗失利。因此，无线电通信人员必须掌握熟练地发报技术。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是发报的工具，只有了解它，才能熟练地使用它，如图3-1所示为电键构造。</p><p style=\"text-align: center; line-height: 1.75em;\"><img src=\"http://10.10.0.99:8003/ueditor/image/20220124/1643014090102tkjsge.png\" title=\"1643014090102tkjsge.png\" alt=\"s1.png\"/></p><p style=\"text-align: center; line-height: 1.75em;\">图3-1电键构造图</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我们使用的电键，通常叫手键，手键由如下部分组成：</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键钮一手握的地方，由胶木做成，键簧，钢丝绕成，富有弹性，压在键梁下面；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;接触点一弹簧与键钮之间（上下两个）突出部分；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键梁一架在电键中间的一根金属长条；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;螺丝一左右螺丝，用于固定键梁，调整键梁位置，使上下接点对准，以免左右移动。高低螺丝，用于调整两个接触点的高低。松紧螺丝，用于调整弹簧的松紧，适应发报的用力； 导线一两根连到两个接触点的导线；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;插头一外层是胶木，里层是两个互相绝缘的金属芯，分别连接导线，用于接通电键和机器；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键盘一上层是胶木，下层是铁盘，用于固定零件。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是无线电报务员手中的武器，必须很好地认识它，正确地使用它，才能较好地发挥发报技术。弹簧的软硬影响着用力，弹簧硬一些，有利于锻炼腕力和指力，尤其是发报的基础阶段，有利于充分地体会腕力，但是弹簧太硬，容易使人疲劳，反而会影响用力，同时不利于高速拍发。弹簧软一些，有利于腕力和指力的配合，尤其是高速拍发，有利于充分发挥指力的作用。但是，弹簧太软，容易使腕力遭到破坏，而单纯地运用指力，会造 成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;触点高低对用力也是有影响的。电键的接触点高一些，能够锻炼手指的支撑力和手腕的下打力，有利于充分体会用力。但是过高，容易出现浑身用力，拍发吃力，点划脱节等问题。电键的接触点低一些，拍发起来省力，对提速、高速拍发有利。但是过低，容易出现用力靠手指挤抠等问题，造成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;综上所述，初学阶段，电键要调的硬一些，高一些。随着用力的不断掌握和发报技术的不断提高，电键的软硬、高低可根据需要进行必要的调整。但要切记，不能调的太软过低。一般说来，初学阶段，电键软硬、高低应由教员掌握。</p><p><br style=\"white-space: normal;\"/></p><p><br/></p>', '2', '1657520490494', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('a8bfec2d-839a-4811-a32b-47da51be5134', '0792a8f2-f79a-4db2-8b36-22045dd10a88', '/006/cover/base.jpg', '基本概念', '<p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_02.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_03.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_04.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_05.png\"/></p><p style=\"white-space: normal; text-align: center;\"><img src=\"http://10.10.0.99:8000/api/file/getFile/ueditor/image/20220215/(%E6%97%A0%E6%B0%B4%E5%8D%B0)%E6%AC%A7%E5%8F%82-%E7%9F%AD%E6%B3%A2%E9%80%9A%E4%BF%A1_06.png\"/></p><p><br/></p>', '2', '1659326129542', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('b47e2341-6045-4109-a58d-e4e151e3e397', 'b0f30127-cfaf-42c6-9d62-1489380d43b5', '/006/cover/base.jpg', '野战分队', '<p><span style=\"font-size:24px;font-family:宋体\">数码抄报<br/>&nbsp;&nbsp;&nbsp; \n持续抄收300组，报文准确无误得100分。报头、报文每掉1组扣6分，错1组等于掉3组；错字、字体无法辨认，有标记算掉，无标记算错（含串组），无效标记每个扣0.5分，超过6个（不含）每个扣1分。义务兵：分速110/100码；一级士官：分速120/110码；二级以上士官：分速130/120码。<br/></span><span style=\"font-size:24px;font-family:宋体\"><br/></span><span style=\"font-size:24px;font-family:宋体\">抗干扰抄报<br/>&nbsp;&nbsp;&nbsp; \n持续抄收数码报文300组，全对，得100分。每掉一组扣2分，错1组等于掉3组；错字、字体无法辨认，有标记算掉，无标记算错（含串组），无效标记每个扣0.2分，超过10个（不含）每个扣0.5分。义务兵：分速85/75码，加入1个等量的报干扰信号；一级士官：分速90/80码，加入两个中干扰报（话）信号；二级以上士官：分速100/90码，加入1个中干扰和1个等量的报（话或音乐）干扰信号。<br/><br/>考核：在本课目训练结束时进行；实际操作达到80分（含）以上为合格，否则为不合格。</span></p>', '2', '1677567789700', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('b7ed6149-1bba-443f-8ac5-d664cf9870c0', 'a8653f8a-ceb4-4f1c-8e7b-631f94746ee9', '/006/cover/base.jpg', '固定台站', '<p><span style=\"font-size:24px;font-family:宋体\">电传数码拍发：<br/>&nbsp;&nbsp;&nbsp; \n持续拍发10分钟，平均分速75组，准确无误得100分；低于规定分速，每组扣4分；改错一处扣2分；多码、少码、压码、多组、少组、错漏打页标、变异型码每处扣10分；多行、少行、串行每处扣20分；发错一组扣35分。&nbsp; \n</span></p><p><span style=\"font-size:24px;font-family:宋体\">电传字码拍发：<br/>&nbsp;&nbsp;&nbsp; \n持续拍发5分钟，平均分速30组，准确无误，报文整洁得100分；改错一个扣3分；多组、少组、压码、错漏打页标、变异型码每处扣10分；串行扣20分；发错一组扣35分，少页扣60分，每低于规定分速一码扣4分。</span></p><p><span style=\"font-size:24px;font-family:宋体\">考核：在本课目或阶段训练结束时进行；<br/>实际操作：达到80分（含）以上为合格，否则为不合格。</span></p><p><br/></p>', '2', '1677564721358', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('b9139ddd-5bce-437a-955c-69f6b92d9e02', 'b0d287bc-138f-4a68-a7e5-50000b2640b5', '/006/cover/base.jpg', '手键（电子键）报抄收', '<p><span style=\"font-size:24px;font-family:宋体\">&nbsp; &nbsp; &nbsp;如果实抄报文组数与报文组数不符，静重复报头组数无误时，应当查对组数。查对组数一般应当由收方主动查对，如果收方查对不便，可以主动请求发方查对</span></p>', '2', '1736318892760', 2, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('c60030a8-9010-4905-857a-bfdf4589a3d2', '6515c61a-55bb-4807-b207-52fd60aa93e7', '/006/cover/base.jpg', '第三节 发报要求和练习', '<p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;发报练习的整个过程是一个实践、认识、再实践、再认识，不断体会用力要领，掌握规律的过程。发报要准确无误，看得准、发得准、一丝不苟。清楚正规，节奏分明、音调正规、点划按比例、不拍或少拍错误符号。快慢自如，拍发熟练、平稳，在已经掌握的速度内能快能慢。间隔均匀，字与字，组与组的间隔合乎要求，不连码，均匀流利。有持久力，在保证质量、速度变化不大的情况下能坚持长时间的方法。速度平稳，拍发速度始终大体一致，不忽快忽慢，更不能抢快。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;初学时的练习应在教员具体指导下进行，一般应以领发为主，逐步增长自发的时间，切不可随便乱发。电键接点的高度约1.5mm左右同伍分硬币厚度，弹簧稍硬些。每次练习前，特别是激烈运动后，均应先做此预备活动（如拍发五点五划），使手腕灵活后再开始拍发报文。常练习五点五划可体会多点多划的用力要领，对提高发报速度与质量都有帮助。练习发报时，精力要集中，手指行、眼看码。由看一码发一码逐渐锻炼到一次能看一组甚至更多些，做到流水式看报底，这样有助于提高拍发的准确性和拍发得更加流利，可以减少错误符号，不要养成发发停停或东张西望的不良习惯。每次练习时，应本着低平高平这个一般规律进行：</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;低：每次练习时，开始用低速拍发，主是活动手腕，使手腕恢复练习时 的最佳状态。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;平：是指自己逐渐提高到已经掌握了的速度，而这个速度拍发的时间要长些；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;高：当手法比较顺利时，可以在清楚的基础上适当提高拍发速度，一般以不超过五码为宜，最多不超过十码，但拍发时间不宜太长。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;最后回到有把握的速度继续拍发，以达到巩固的目的。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;注意锻炼持久的拍发能力。持久力主要靠勤学苦练来养成，并要有坚强的毅力和高 度的责任感。练习时要保持自然的坐姿和握键姿势，并逐渐增长拍发时间，当手腕稍感疲劳时，不要立即停止，应适当降低速度，利用大小间隔、换页等间隔，使指腕得到松驰， 继续坚持练习。看、听、想、练相结合：</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;看：看发报好的同志用力动作与用力方法；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;听：听教员拍发的正确节奏和拍发的正规音调；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;想：把看到的好的用力动作，听到的正规音调，自己进行细心琢磨和体会，边模仿、边练习；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;练：固定一种好的姿势，勤学苦练，练习中 要做到胸中有数，有针对性，如根据本人情况，编一些特殊报底进行练习，以助于克服拍 发中的毛病。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;训练中可有计划地进行一些空键拍发，在拍发时，应适当降低速度，注意听 空键声音，严格要求，一丝不苟。出现了毛病，要实事求是地分析产生原因，找出具体克 服方法，按拍发要领加以纠正。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;发报中“错误符号”和“从前一组”的应用：</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;当发现正在拍发的这一组发错或发不清楚时，应立即拍发出错误符号（・•一••）然后从该组的第一码重新拍发。当发现已拍发过的前一组错发或发不清楚时，应立即拍发出从前一组符号（fm）,然后从前一组的第一码重新往后拍发。</p><p><br/></p>', '2', '1643015314274', 3, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('c66d6964-6a62-4152-840f-83f35b2343c0', '5864a20f-012d-4c94-a924-ced9f3f8015b', '/006/cover/base.jpg', '执掌测试2', '<p style=\"line-height: 1.75em;\">&nbsp; &nbsp; &nbsp; &nbsp; 发报是无线电通信人员必须掌握的收、发、通三大技术之一，它是学习的重点，也是难点。无线电通信人员发报技术的好坏，通常称为手法的好坏，它同一个人的口才一样, 口才好，说话清楚流利，听得就明白，如果口才不好，咬字不清，结结巴巴，就会使对方听起来感到困难。同样，如果手法好，对方收报就会省时省力。如果手法不好，对方收报就会感到困难，容易产生错误，影响速度和准确性，甚至会耽误军事行动，造成战斗失利。因此，无线电通信人员必须掌握熟练地发报技术。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是发报的工具，只有了解它，才能熟练地使用它，如图3-1所示为电键构造。</p><p style=\"text-align: center; line-height: 1.75em;\"><img src=\"http://10.10.0.99:8003/ueditor/image/20220124/1643014090102tkjsge.png\" title=\"1643014090102tkjsge.png\" alt=\"s1.png\"/></p><p style=\"text-align: center; line-height: 1.75em;\">图3-1电键构造图</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我们使用的电键，通常叫手键，手键由如下部分组成：</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键钮一手握的地方，由胶木做成，键簧，钢丝绕成，富有弹性，压在键梁下面；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;接触点一弹簧与键钮之间（上下两个）突出部分；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键梁一架在电键中间的一根金属长条；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;螺丝一左右螺丝，用于固定键梁，调整键梁位置，使上下接点对准，以免左右移动。高低螺丝，用于调整两个接触点的高低。松紧螺丝，用于调整弹簧的松紧，适应发报的用力； 导线一两根连到两个接触点的导线；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;插头一外层是胶木，里层是两个互相绝缘的金属芯，分别连接导线，用于接通电键和机器；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键盘一上层是胶木，下层是铁盘，用于固定零件。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是无线电报务员手中的武器，必须很好地认识它，正确地使用它，才能较好地发挥发报技术。弹簧的软硬影响着用力，弹簧硬一些，有利于锻炼腕力和指力，尤其是发报的基础阶段，有利于充分地体会腕力，但是弹簧太硬，容易使人疲劳，反而会影响用力，同时不利于高速拍发。弹簧软一些，有利于腕力和指力的配合，尤其是高速拍发，有利于充分发挥指力的作用。但是，弹簧太软，容易使腕力遭到破坏，而单纯地运用指力，会造 成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;触点高低对用力也是有影响的。电键的接触点高一些，能够锻炼手指的支撑力和手腕的下打力，有利于充分体会用力。但是过高，容易出现浑身用力，拍发吃力，点划脱节等问题。电键的接触点低一些，拍发起来省力，对提速、高速拍发有利。但是过低，容易出现用力靠手指挤抠等问题，造成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;综上所述，初学阶段，电键要调的硬一些，高一些。随着用力的不断掌握和发报技术的不断提高，电键的软硬、高低可根据需要进行必要的调整。但要切记，不能调的太软过低。一般说来，初学阶段，电键软硬、高低应由教员掌握。</p><p><br style=\"white-space: normal;\"/></p><p><br/></p>', '2', '1656399564344', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('ca87c2cc-71ce-4f7e-b675-a10d3a4680b6', '4161a96c-7858-4471-b03d-cacc0aed468d', '/006/cover/base.jpg', '野战分队', '<p><span style=\"font-size:24px;font-family:宋体\">电子键数码拍发<br/>&nbsp;&nbsp;&nbsp; \n持续拍发200组，全对，得100分，每低于规定分速一码扣2分；改错5个（含）以内每个扣0.5分，5个以上每个扣1分；多、少间隔，每处扣10分；错发、漏发、多发、串组各扣10分。义务兵：分速160/140码；以及士官：180/160码；二级以上士官：分速200/180码。 \n</span></p><p><span style=\"font-size:24px;font-family:宋体\">电子键字码和混合码拍发：<br/>&nbsp;&nbsp;&nbsp; \n持续100组，全对，得100分。每低于分速一码扣2分，其它同电子键数码拍发。义务兵：分速80/70码；以及士官：90/80码；二级以上士官：分速100/90码。 \n</span></p><p><span style=\"font-size:24px;font-family:宋体\">考核：在本课目训练结束时进行；实际操作：达到80分（含）以上为合格，否则为不合格。&nbsp; &nbsp;</span></p><p><br/></p>', '2', '1677566680251', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('e1b63820-a6d8-4302-9017-0c879cbc8d66', 'b588d741-40b0-44d2-b079-aab0eca96106', '/006/cover/base.jpg', '收报要求', '<p><span style=\"font-size:24px;font-family:宋体\">无干扰收报<br/>1、集中精力、平心静气。<br/>&nbsp;&nbsp;&nbsp; \n抄报前应做好一切准备工作，排除一切干扰，专心致志的进行抄报，保持心平气和，认真听辨，抓住信号特点，抄好每一字，每一码。<br/>2、边听边写，压码稳抄。<br/>&nbsp;&nbsp;&nbsp; \n压码：同一时间内抄报的报文滞后于拍发的报文。<br/>&nbsp;&nbsp;&nbsp; 压码作用：<br/>&nbsp;&nbsp;&nbsp; \n延长脑辩时间，保证抄收质量。只有压码才能做到平心静气，使精力持久的集中于抄报中。<br/>&nbsp;&nbsp;&nbsp; 压码的方法：<br/>&nbsp;&nbsp;&nbsp; 要做到六个不停：<br/>&nbsp;&nbsp;&nbsp; \n耳不停的听，脑不停的辨。手不停的写，笔不停的转。眼不停的看，臂不停的移。</span></p><p><span style=\"font-size:24px;font-family:宋体\"><br/>抗干扰收报<br/>&nbsp;&nbsp;&nbsp; \n抗干扰收报是在干扰条件下抄收报文的一种能力。通常情况下，分为机上对抗收报，机下対抗抄报两种基本形式。它难度较大，一般要求抄报者达到抄报分速100-110码且质量较为稳定的程度后进行。其基本抄报要领可归纳为：全神贯注，分清特点，压码稳抄，判断抄收。</span></p><p><br/></p>', '2', '1677568647436', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('e5ed359a-e86c-4378-97a4-79744af32114', 'a3a597f7-931b-4eec-99d1-43a65c3f184d', '/006/cover/base.jpg', '手键握姿', '<p><span style=\"font-size:24px;font-family:宋体\">握键跪姿要领：<br/>&nbsp;&nbsp;&nbsp; \n手键握键姿势跪姿，拇指自然微曲，扶于键钮底盘左侧腰部；中指半弯曲，第一节跪于键钮底座右侧；食指半弯曲，第一节直立于键钮顶端前部；无名指和小指自然握回掌心。以拇指和中指的合力轻轻捏住键钮，小臂、食指同键梁成一直线，腕部下平面与键钮底盘基本持平，右肘大致弯成直角，大臂略离上体。</span></p><p><span style=\"font-size:24px;font-family:宋体\"><img alt=\"\"/></span></p><p><span style=\"font-size:24px;font-family:宋体\">握键立姿要领：<br/>&nbsp;&nbsp;&nbsp; \n手键握键姿势立姿，拇指自然微曲，扶于键钮底盘左侧腰部；中指半弯曲，第一节直立于键钮底座右侧；食指半弯曲，第一节直立于键钮顶端前部；无名指和小指自然握回掌心。以拇指和中指的合力轻轻捏住键钮，小臂、食指同键梁成一直线，腕部下平面与键钮底盘基本持平，右肘大致弯成直角，大臂略离上体。</span></p><p><span style=\"font-size:24px;font-family:宋体\"><img alt=\"\"/></span></p><p><br/></p>', '2', '1677568897692', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('e648cb3b-cdc2-45fb-8a13-a043971ab15a', 'b6dc209d-88cf-4c3b-b231-40df787dbf23', '/006/cover/base.jpg', '收报登记填写', '<p><span style=\"font-size:24px;font-family:宋体\">1、填写内容<br/>&nbsp;&nbsp;&nbsp; \n电报、信号报头的内容。<br/>&nbsp;&nbsp;&nbsp; \n电报、信号来自何台的电报代号、号数、组数、等级（填写等级时应按照联络文件代密译出汉字等级）。<br/>2、收到时间<br/>&nbsp;&nbsp;&nbsp; \n填写对方台给收据的时间。“收到时间”和“送译时间”栏中的日期均应填写完整。如七月一日写为“1/7”任何一项内容都不能用省略号填写。<br/>3、送到（译）时间<br/>&nbsp;&nbsp;&nbsp; \n是指该份电报、信号送交机要部门或电报收发室的时间以及签收人姓名。<br/>4、附注<br/>&nbsp;&nbsp;&nbsp; \n转报、通播电报、重收电报、业务公电和其他需说明的事项填写在“附注”栏内。</span></p><p><br/></p>', '2', '1677564425385', 1, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('ed652da7-6b4b-4dd8-9228-5861095679fd', '6515c61a-55bb-4807-b207-52fd60aa93e7', '/006/cover/base.jpg', '第二节 拍发要领', '<p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;（一）点的拍发</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;点的拍发分为单点拍发和多点拍发，单点拍发是腕部由静止状态（中水平线）自然灵敏的拾至上水平线，手指姿势不变，然后立即垂直有力地下打至下水平线，在电键两个接 触点接触一瞬间，借腕、指和弹簧的反作用力，将手腕瞬间弹回上水平线，然后回落到静止状态。多点拍发的用力要领与单点相同，它是数个单点动作连接在一起的结果。不同的是，第一个动作完成后腕部不回落至静止状态，而是继续从上水平线下打完成下一个点的动作。以此类推，直到多点动作完成为止才恢复至静止状态。发点时，动作要自然、灵敏、协调，用力要垂直均匀有力、点要拍发得扎实、干脆，防止前推后拉，或用大小臂压点。</p><p style=\"line-height: 1.75em;\"><br/></p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;（二） 划的拍发</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;划的拍发分为单划拍发和多划拍发，单划拍发是腕部由静止状态抬至上水平线，手腕姿势不变，然后立即垂直有力地将手腕打至下水平线，在电键两个接触点接触时，手指支撑住，使接触点不分开，手腕逐渐抬至上水平线，上抬的过程是完成一个划长度的过程，然后指松腕落恢复至静止状态。多划的用力要领与单划相同，它是数个单划紧凑连接的结果。不同的是，当第一个划动作完成之后，手腕不恢复至静止状态，手指仍然支撑住, 然后手腕以上水平线迅速下打至下水平线，在下打的一瞬间，手指支撑力稍松，使电键的接触点瞬间离开，尔后迅即支撑，使接触点再次接通（稍松一定要在下打之后，否则就会脱节），手腕逐渐上抬至上水平线，反复上述动作即拍出多划，多划动作完成后，手腕恢复至静止状态。在拍发单划和多划时，动作要自然有力，连贯。腕部下打不能太低，手指的支撑力一定要强，要防止指关节松软蠕动，造成握姿变形，影响用力。要防止出现全身用力和用小臂压的现象。重点练习多划拍发中划与划连接的动作。</p><p style=\"line-height: 1.75em;\"><br/></p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;（三） 点划与划点连接</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;点划连接的动作要领是单点、单划拍发动作的结合。点的动作完成之后，手腕不恢复至静止状态，而是由上水平线下打完成一个划的动作，然后恢复至静止状态。如果多点、多划的连接，只要把多点的拍发动作和多划的拍发动作，结合上述的拍发要领即可完成。划点连接的动作要领是单划、单点拍发动作的结合。当-个划的动作完成之后，手腕不恢复至静止状态，而是从上水平线下打至下水平线，在下打的一瞬间，手指支撑力放松，使接点离开，转换点的用力动作完成点的拍发。然后恢复到静止状态。如果是多划、多点的连接，多划的拍发和多点的拍发动作结合上述要领即可完成。</p><p><br/></p>', '2', '1643015075773', 2, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('f59dcc09-ee87-4159-8c84-3f009f76b8ed', 'a2a0195b-3f9d-4ae6-a5cc-94e8697e1235', '/006/cover/base.jpg', '执掌课件1', '<p style=\"line-height: 1.75em;\">&nbsp; &nbsp; &nbsp; &nbsp; 发报是无线电通信人员必须掌握的收、发、通三大技术之一，它是学习的重点，也是难点。无线电通信人员发报技术的好坏，通常称为手法的好坏，它同一个人的口才一样, 口才好，说话清楚流利，听得就明白，如果口才不好，咬字不清，结结巴巴，就会使对方听起来感到困难。同样，如果手法好，对方收报就会省时省力。如果手法不好，对方收报就会感到困难，容易产生错误，影响速度和准确性，甚至会耽误军事行动，造成战斗失利。因此，无线电通信人员必须掌握熟练地发报技术。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是发报的工具，只有了解它，才能熟练地使用它，如图3-1所示为电键构造。</p><p style=\"text-align: center; line-height: 1.75em;\"><img src=\"http://10.10.0.99:8003/ueditor/image/20220124/1643014090102tkjsge.png\" title=\"1643014090102tkjsge.png\" alt=\"s1.png\"/></p><p style=\"text-align: center; line-height: 1.75em;\">图3-1电键构造图</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我们使用的电键，通常叫手键，手键由如下部分组成：</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键钮一手握的地方，由胶木做成，键簧，钢丝绕成，富有弹性，压在键梁下面；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;接触点一弹簧与键钮之间（上下两个）突出部分；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键梁一架在电键中间的一根金属长条；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;螺丝一左右螺丝，用于固定键梁，调整键梁位置，使上下接点对准，以免左右移动。高低螺丝，用于调整两个接触点的高低。松紧螺丝，用于调整弹簧的松紧，适应发报的用力； 导线一两根连到两个接触点的导线；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;插头一外层是胶木，里层是两个互相绝缘的金属芯，分别连接导线，用于接通电键和机器；</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;键盘一上层是胶木，下层是铁盘，用于固定零件。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;电键是无线电报务员手中的武器，必须很好地认识它，正确地使用它，才能较好地发挥发报技术。弹簧的软硬影响着用力，弹簧硬一些，有利于锻炼腕力和指力，尤其是发报的基础阶段，有利于充分地体会腕力，但是弹簧太硬，容易使人疲劳，反而会影响用力，同时不利于高速拍发。弹簧软一些，有利于腕力和指力的配合，尤其是高速拍发，有利于充分发挥指力的作用。但是，弹簧太软，容易使腕力遭到破坏，而单纯地运用指力，会造 成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;触点高低对用力也是有影响的。电键的接触点高一些，能够锻炼手指的支撑力和手腕的下打力，有利于充分体会用力。但是过高，容易出现浑身用力，拍发吃力，点划脱节等问题。电键的接触点低一些，拍发起来省力，对提速、高速拍发有利。但是过低，容易出现用力靠手指挤抠等问题，造成坏手。</p><p style=\"line-height: 1.75em;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;综上所述，初学阶段，电键要调的硬一些，高一些。随着用力的不断掌握和发报技术的不断提高，电键的软硬、高低可根据需要进行必要的调整。但要切记，不能调的太软过低。一般说来，初学阶段，电键软硬、高低应由教员掌握。</p><p><br style=\"white-space: normal;\"/></p><p><br/></p>', '2', '1648603635501', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('f62536e2-efd1-4125-a36e-2d3be85076fe', '63386180-be2c-4629-b6ed-ed4891a261a1', '/006/cover/base.jpg', '固定台站', '<p><span style=\"font-size:24px;font-family:宋体\">手键拍发<br/></span><span style=\"font-size:24px;font-family:宋体\">&nbsp;&nbsp;&nbsp; \n持续拍发数码报文200组，平均分速50码。报文准确无误得100分；低于规定分速一码扣2分；改错2个以内每个扣0.5分；超过2个（不含）每个扣1分；错发、漏发、多发、拍发不清未更正每项扣35分。<br/><br/>考核：在本科目或阶段训练结束时进行；实际操作；达到80分（含）以上为合格，否则为不合格。<br/></span></p><p><br/></p>', '2', '1677568748676', 0, NULL, NULL, 0);
INSERT INTO `t_theory_knowledge_swf` VALUES ('fa80cd8c-7888-4327-92b1-cea74c3f7d5f', 'b0f30127-cfaf-42c6-9d62-1489380d43b5', '/006/cover/base.jpg', '固定台站', '<p><span style=\"font-size:24px;font-family:宋体\">数码抄报<br/>&nbsp;&nbsp;&nbsp; \n持续抄收300组，平均分速90码，报文准确无误得100分；无效标记2个以内每个扣0.5分，每超2个（不含），少行尾标记扣1分；掉一组扣10分，错一组等于掉四组，错字、字体无法辨认、有标记算掉，无标记（含串组）算错。<br/></span><span style=\"font-size:24px;font-family:宋体\"><br/>字码抄报<br/>&nbsp;&nbsp;&nbsp; \n持续抄收2分钟，平均分速60码，报文准确无误得100分；无效标记2个以内每个扣0.5分，超过2个（不含），少行尾标记每个扣1分，每掉一码扣8分，错一码等于掉4码，错字、字体无法辨认，有标记算掉，无标记（含串组）算错。<br/><br/>考核：在本课目或阶段训练结束时进行；实际操作；达到80分（含）以上为合格，否则为不合格。<br/></span></p><p><br/></p>', '2', '1677567755938', 0, NULL, NULL, 0);
