INSERT INTO `t_theory_knowledge_test_content` VALUES ('ba447e87-6920-42e1-bed9-d47659446a1b', 'a8653f8a-ceb4-4f1c-8e7b-631f94746ee9', 'b7ed6149-1bba-443f-8ac5-d664cf9870c0', '01e4b299-ec56-4d37-9a71-fa6c490d8e1a', 4, '持续拍发5分钟，平均分速30组，，报文整洁得100分；改错一个扣3分；多组、少组、压码、错漏打页标、变异型码每处扣10分；串行扣20分；发错一组扣35分，少页扣60分，每低于规定分速一码扣4分$_$', '[]', '[\"准确无误\"]', '准确无误', NULL, '2', '1677565159418');
INSERT INTO `t_theory_knowledge_test_content` VALUES ('bba1c467-2f1b-4383-8b6e-7d522b191951', 'b588d741-40b0-44d2-b079-aab0eca96106', '7c1f3376-a781-43aa-b16b-0aed5c9fff93', '88a2e3ec-1fa5-4e1a-acdb-66812db76b4e', 3, '  两脚自然着地与肩同宽，两小腿自立与大腿约成90度；上体自然端正，微向前倾，距桌沿约15厘米；两小臂放于桌面，左手扶抄报纸，右手握笔；两眼目视抄报纸。', '[{\"name\":\"对\",\"id\":\"1\"},{\"name\":\"错\",\"id\":\"2\"}]', '\"1\"', '', NULL, '2', '1677568998033');
