INSERT INTO `t_theory_question` VALUES ('0af01e41-d87e-4a30-92e8-04fc9bb7e328', 3, '报务员必须严格遵守：严禁私自编用密码、代号、联络规定，拍发明码、汉语拼音电报或在机上进行私人交谈。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"1\"', '', '2', '1660208035678', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
