INSERT INTO `t_theory_question` VALUES ('0b2cb883-d7ea-424d-86d4-73e0463184e6', 1, 'H/TJS-402型短波收信机喇叭开关；该开关用于喇叭通断转换在双工方式中，应将喇叭开关位于“关”位置，此时采用耳机（），这对防止语音反馈是特别有用的。', '[{\"value\":\"0\",\"label\":\"抄收\"},{\"value\":\"1\",\"label\":\"监听\"},{\"value\":\"2\",\"label\":\"旁抄\"},{\"value\":\"3\",\"label\":\"收听\"}]', '\"1\"', '', '2', '1660031419044', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
