INSERT INTO `t_theory_question` VALUES ('0b5a0b63-d73a-4ba0-b475-696277f61fe1', 3, '利用短波综合终端进行无线电数据报工作时，按要求设置好系统的通信参数和接收状态。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"1\"', '', '2', '1660031421429', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
