INSERT INTO `t_theory_question` VALUES ('0b71d5c2-014d-4d93-b02d-a2be2ecce327', 3, '无线电话务发无线电信号，信号内容发错时，应当讲“取消”，尔后从本组第一码重发。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"2\"', '', '2', '1660029608556', '9a2da855-2cab-4fb7-995d-fc87a9d9aa32');
