INSERT INTO `t_theory_question` VALUES ('0b7b3e54-a16b-47c9-89d8-e0d9a78746a4', 3, '手键专向通报程序，在要求重复时，发“重复”的单词和要求重复的组位数。重复多页电报时，应当拍发页数。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"1\"', '', '2', '1644997105584', '476e9942-ae39-4da9-9f8a-9ce41489edfe');
INSERT INTO `t_theory_question` VALUES ('0b86b053-3d97-46c7-b492-e500dfb497d4', 1, '手键专向通报程序，呼叫区分符号（）次，手键沟通时回答“听到了”单词1次。', '[{\"value\":\"0\",\"label\":\"3、0\"},{\"value\":\"1\",\"label\":\"1-3\"},{\"value\":\"2\",\"label\":\"1-2\"},{\"value\":\"3\",\"label\":\"1、0\"}]', '\"2\"', '', '2', '1660031418884', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
