INSERT INTO `t_theory_question` VALUES ('0bc36e2c-1af3-45ee-bbd5-e594e1eea417', 1, '水下通信一般通过以下四种手段组织实施：（）、水声通信、无线电甚长波和超长波通信、激光通信', '[{\"value\":\"0\",\"label\":\"水下电缆\"},{\"value\":\"1\",\"label\":\"水下通信\"},{\"value\":\"2\",\"label\":\"无线通信\"},{\"value\":\"3\",\"label\":\"信号通信\"}]', '\"0\"', '', '2', '1660269355304', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
