INSERT INTO `t_theory_question` VALUES ('0c4b0d6d-0617-47af-88dd-cbb80a53ef10', 1, 'H/TJS-402型短波收信机利用频率旋钮置定频率；旋转频率旋钮可改变频率。顺时针转动，频率升高；反时针转动，频率降低。步进值则由步进一拍频转换开关决定，分别为（）、10Hz和1Hz。', '[{\"value\":\"0\",\"label\":\"50Hz\"},{\"value\":\"1\",\"label\":\"200Hz\"},{\"value\":\"2\",\"label\":\"20Hz\"},{\"value\":\"3\",\"label\":\"100Hz\"}]', '\"3\"', '', '2', '1660029606294', '9a2da855-2cab-4fb7-995d-fc87a9d9aa32');
