INSERT INTO `t_theory_question` VALUES ('0cb25827-31d6-46a8-8995-9da535debc0d', 3, '无线电通信纠察员交接班要做到交接清楚，手续完备，责任分明；交班前要清扫工作间卫生，整理工具、仪表和资料，检测设备，做好交班准备。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"1\"', '', '2', '1660031422158', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
