INSERT INTO `t_theory_question` VALUES ('0cd8b2b0-785e-4f27-b9ed-a8d7d7e678da', 2, 'H／TJZ-802板卡设置包括：801卡设为电传，（），413卡插入设为有，ECU卡插入设为有，频管卡，801（2）卡插入设为有，板卡的设置，用户可根据需要对其进行设置。\r', '[{\"value\":\"0\",\"label\":\"413卡插入设为无\"},{\"value\":\"1\",\"label\":\"401卡插入设为有\"},{\"value\":\"2\",\"label\":\"低速卡插入设为有\"},{\"value\":\"3\",\"label\":\"ECU卡插入设为无\"}]', '[\"1\",\"2\"]', '', '2', '1660008228425', NULL);
