INSERT INTO `t_theory_question` VALUES ('0d629e80-36ca-44da-a092-47b2ea1b2bd4', 3, '舰炮主要特点是：通用性好，可执行多种任务；反应快，射击控制自动化；初速大、发射率高并能持续发射；但射程近，命中率受射距影响小；破坏威力小等。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"2\"', '', '2', '1660269356716', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
