INSERT INTO `t_theory_question` VALUES ('12dac918-dd48-4ed2-baea-daf8475bcbe3', 3, 'H/TJS-402型短波收信机亮度调节旋钮；可用来调节显示器数码管和发光二极管的亮度，使其与周围环境照明条件相适应。左旋时亮度减弱，右旋时亮度增强。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"1\"', '', '2', '1660208036270', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
