INSERT INTO `t_theory_question` VALUES ('130208b3-fd44-4315-964d-8c74dbf5239c', 2, 'H/TJS-402型短波收信机抗电强度；电源插座与机壳间施加1500V、50Hz正弦交流电压，稳定1分钟后不应出现（）和（）。', '[{\"value\":\"0\",\"label\":\"飞直\"},{\"value\":\"1\",\"label\":\"飞弧\"},{\"value\":\"2\",\"label\":\"击穿\"},{\"value\":\"3\",\"label\":\"击弧\"}]', '[\"1\",\"2\"]', '', '2', '1660031420705', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
