INSERT INTO `t_theory_question` VALUES ('68b2fdcd-c057-4097-942f-09a1dbb038f8', 3, '多发、错发单位或者机要部门通知取消电报时，应当发取消公电。拍发取消公电时，领班员台长签名。如果取消的电报已经转出，应当逐站发出取消公电。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"2\"', '', '2', '1660031421457', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
