INSERT INTO `t_theory_question` VALUES ('68bfb94d-e0b3-4af0-a1a5-491100d656bf', 2, '无线电通信纠察台（室）在实施（）和执行重要无线电台通信纠察任务工作期间，应当增加通信保密纠察力量，防止失、泄密问题发生。\r', '[{\"value\":\"0\",\"label\":\"重要会议\"},{\"value\":\"1\",\"label\":\"等级战备\"},{\"value\":\"2\",\"label\":\"地方政府宴会\"},{\"value\":\"3\",\"label\":\"节日战备\"}]', '[\"1\",\"3\"]', '', '2', '1660008228252', NULL);
