INSERT INTO `t_theory_question` VALUES ('68e5d763-fa37-459a-be1d-fc7e10b76f57', 1, '（）是机要部门让电台向电报拟制单位发出的公电。凡收到重译公电，均按原电报路径的返回过程依次逐站（台）发出。', '[{\"value\":\"0\",\"label\":\"更正\"},{\"value\":\"1\",\"label\":\"重发\"},{\"value\":\"2\",\"label\":\"取消\"},{\"value\":\"3\",\"label\":\"重译\"}]', '\"3\"', '', '2', '1660208033294', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
INSERT INTO `t_theory_question` VALUES ('68e663da-83fc-47d8-b760-97bf39573694', 3, 'H/TJS-402型短波收信机利用频率旋钮置定频率；旋转频率旋钮可改变频率。顺时针转动，频率升高。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"1\"', '', '2', '1660208034688', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
