INSERT INTO `t_theory_question` VALUES ('69588531-3f21-4f87-8bba-75988742c92c', 2, '短波通信中可以采用以下措施克服工业干扰。', '[{\"value\":\"0\",\"label\":\"工业干扰主要沿电力线传播，因此电台在开设时应远离电力线\"},{\"value\":\"1\",\"label\":\"工业干扰主要集中在频率较低的波段，因此在通信中应尽量选用较低的工作频率\"},{\"value\":\"2\",\"label\":\"从工业干扰的性质看，都属于脉冲干扰，电台中可采用专门电路（积分器)消除\"},{\"value\":\"3\",\"label\":\"在电台的设计上提高电磁兼容性，防止干扰\"}]', '[\"0\",\"2\",\"3\"]', '', '2', '1660031420676', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
