INSERT INTO `t_theory_question` VALUES ('69d93e9f-017d-427b-9ee7-b2371ee01387', 3, '所谓移频电报信号就是用高频信号的不同频率表示电报键控的不同状态，来传输报文信息。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"1\"', '', '2', '1660029607441', '9a2da855-2cab-4fb7-995d-fc87a9d9aa32');
