INSERT INTO `t_theory_question` VALUES ('87bc2e7c-dbc2-4a5a-a5e9-540107a06712', 2, '填写电台日记的工作情况时，交接班内容包括待收、待发的电报及其它待办事项，上级有关指示，重要的联络情况，临时约会的（），交接班时间及交、接班人员签名等。', '[{\"value\":\"0\",\"label\":\"时间\"},{\"value\":\"1\",\"label\":\"频率\"},{\"value\":\"2\",\"label\":\"联络文件\"},{\"value\":\"3\",\"label\":\"机线设备状况\"}]', '[\"0\",\"1\",\"2\",\"3\"]', '', '2', '1660208033889', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
