INSERT INTO `t_theory_question` VALUES ('880254d3-4e68-4959-ba4c-077bcd326f32', 1, 'H/TJS-402型短波收信机调谐锁定；当从键盘注入“00”时，收信机处于频率调谐无效状态，此时旋转频率调谐旋钮不起作用，只能通过键盘送入工作频率、工作种类等数据；中有再次键入“（）”时，频率调谐旋钮才能解锁。', '[{\"value\":\"0\",\"label\":\"01\"},{\"value\":\"1\",\"label\":\"02\"},{\"value\":\"2\",\"label\":\"03\"},{\"value\":\"3\",\"label\":\"00\"}]', '\"3\"', '', '2', '1660269353628', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
