INSERT INTO `t_theory_question` VALUES ('88180036-71b0-4047-94a7-448acc483a08', 3, '自动通信网通报程序与工作方法：发报工作中应注意纠正：未按规定拍发报头、附注、报文间隔与换行。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"1\"', '', '2', '1660208036301', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
