INSERT INTO `t_theory_question` VALUES ('9294a783-1004-490e-9ec5-fe3c6b092c14', 2, '调频信号其特点具有什么（）。\r', '[{\"value\":\"0\",\"label\":\"同样的输出功率，调频发信机的作用距离是调幅机的三倍\"},{\"value\":\"1\",\"label\":\"调频信号不同于调幅信号，它的振幅是不变的，而频率随低频信号变化而变化，因此获得调频信号的方法就不同于获得调幅信号的方法\"},{\"value\":\"2\",\"label\":\"抗干扰性弱\"},{\"value\":\"3\",\"label\":\"占用频带宽。调频波的有效频带比调幅波宽几倍，频带越宽，波段内能容纳的电台数目就越少，故调频制只在超短波范围内得到广泛应用\"}]', '[\"1\",\"3\"]', '', '2', '1660008228688', NULL);
INSERT INTO `t_theory_question` VALUES ('929e3a59-6079-41c9-9d44-fe8f6f1f66e0', 1, 'H/TJS-402型短波收信机利用频率旋钮置定频率；旋转频率旋钮可改变频率。顺时针转动，频率升高；反时针转动，频率降低。步进值则由步进一拍频转换开关决定，分别为（）、10Hz和1Hz。', '[{\"value\":\"0\",\"label\":\"50Hz\"},{\"value\":\"1\",\"label\":\"200Hz\"},{\"value\":\"2\",\"label\":\"20Hz\"},{\"value\":\"3\",\"label\":\"100Hz\"}]', '\"3\"', '', '2', '1660208033543', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
