INSERT INTO `t_theory_question` VALUES ('9c41e0fe-f332-49fb-bfa0-f8c885161e2b', 2, '无线电通信纠察台（室）在实施（）和执行重要无线电台通信纠察任务工作期间，应当增加通信保密纠察力量，防止失、泄密问题发生。', '[{\"value\":\"0\",\"label\":\"重要会议\"},{\"value\":\"1\",\"label\":\"等级战备\"},{\"value\":\"2\",\"label\":\"地方政府宴会\"},{\"value\":\"3\",\"label\":\"节日战备\"}]', '[\"1\",\"3\"]', '', '2', '1660029606493', '9a2da855-2cab-4fb7-995d-fc87a9d9aa32');
