INSERT INTO `t_theory_question` VALUES ('9c85b9e3-db74-4ebd-8c70-5b751cfa5d87', 1, '拍发警报信号时，“警报信号”单词和信号内容各一次，中间间隔三个，拍发（），每遍均应当回动换行。', '[{\"value\":\"0\",\"label\":\"一至三遍\"},{\"value\":\"1\",\"label\":\"一遍\"},{\"value\":\"2\",\"label\":\"二遍\"},{\"value\":\"3\",\"label\":\"一至二遍\"}]', '\"0\"', '', '2', '1660208032190', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
