INSERT INTO `t_theory_question` VALUES ('9c8f17b1-4cdc-4878-804b-3f59ac340454', 1, '利用终端工作传真报，当对方呼叫有报时，应当立即进行接收。发现字迹不清等问题时，应当请求对方调整发送状态后（）。', '[{\"value\":\"0\",\"label\":\"重复\"},{\"value\":\"1\",\"label\":\"重收\"},{\"value\":\"2\",\"label\":\"重发\"},{\"value\":\"3\",\"label\":\"发下\"}]', '\"2\"', '', '2', '1660208033158', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
