INSERT INTO `t_theory_question` VALUES ('9d066529-d06c-432b-8c58-66507b4f5882', 3, 'H/TJS-402型短波收信机利用频率旋钮置定频率；旋转频率旋钮可改变频率。顺时针转动，频率升高。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"1\"', '', '2', '1660269356529', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
