INSERT INTO `t_theory_question` VALUES ('9d3201f4-814f-4469-90c8-afb85e153272', 2, '插叫通常是利用被插叫台（）的机会，校准其收信频率直接插叫。也可以校准被插叫台的发信频率插叫其对方，要求转告或者转报。', '[{\"value\":\"0\",\"label\":\"守听\"},{\"value\":\"1\",\"label\":\"扫描\"},{\"value\":\"2\",\"label\":\"发报\"},{\"value\":\"3\",\"label\":\"收报\"}]', '[\"0\",\"1\",\"3\"]', '', '2', '1644997103616', '476e9942-ae39-4da9-9f8a-9ce41489edfe');
INSERT INTO `t_theory_question` VALUES ('9d352e4e-420f-4cbb-8e21-b55afc599451', 4, '在短波通信中，多径时延主要与工作频率、$_$、时间等因素有关。', '[]', '[\"通信距离\"]', '', '2', '1660269357878', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
