INSERT INTO `t_theory_question` VALUES ('9d86b494-13a0-4bb7-a798-0832caba994a', 3, '无线电台通信纠察在纠察过程中对工作中不给予配合，故意刁难对方等；在无线电路上明拍呼电报代号、电报等级和固定代密；未按规定拍发实习电报、无线电信号或者随意取消实习电报、无线电信号的情况进行纠察登记。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"1\"', '', '2', '1660031421931', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
