INSERT INTO `t_theory_question` VALUES ('cc8a7680-455c-4545-8787-ab2cb97e2dbd', 2, '调频信号其特点具有什么（）。', '[{\"value\":\"0\",\"label\":\"同样的输出功率，调频发信机的作用距离是调幅机的三倍\"},{\"value\":\"1\",\"label\":\"调频信号不同于调幅信号，它的振幅是不变的，而频率随低频信号变化而变化，因此获得调频信号的方法就不同于获得调幅信号的方法\"},{\"value\":\"2\",\"label\":\"抗干扰性弱\"},{\"value\":\"3\",\"label\":\"占用频带宽。调频波的有效频带比调幅波宽几倍，频带越宽，波段内能容纳的电台数目就越少，故调频制只在超短波范围内得到广泛应用\"}]', '[\"1\",\"3\"]', '', '2', '1660208033815', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
