INSERT INTO `t_theory_question` VALUES ('e04eba2f-f8c1-4f46-a739-33919313078c', 3, '潜艇专用通信装备主要有短波猝发通信发信装备和水下甚长波和超长波收信设备及特殊的水中拖曳天线。短波猝发发信设备可以在天线浮出水面以短于10秒钟的速度猝发报文。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"2\"', '', '2', '1644997105477', '476e9942-ae39-4da9-9f8a-9ce41489edfe');
