INSERT INTO `t_theory_question` VALUES ('ea19c06e-0d23-4848-9d22-f34a6b5820b3', 2, 'H/TJS-402参数编程方法；收信机可以对其工作种类、（）、天线衰减、预选器通断等参数、参量进行编程，方法是利用键盘注入相应的程序号。\r', '[{\"value\":\"0\",\"label\":\"窄带\"},{\"value\":\"1\",\"label\":\"带宽\"},{\"value\":\"2\",\"label\":\"射频增益控制方式\"},{\"value\":\"3\",\"label\":\"射频减益控制方式\"}]', '[\"1\",\"2\"]', '', '2', '1660008228573', NULL);
