INSERT INTO `t_theory_question` VALUES ('f3004655-4782-416e-add2-b84b7161351a', 1, '自动通信网通报程序与工作方法：沟通联络工作中，双方沟通后用电传询问识别暗令其方法是拍发识别暗令“IEC”单词一次，暗令两组，每项间隔三个，击铃三响。回答时拍发识别暗令“IEC”单词一次，暗令（），每项间隔三个，击铃一响。', '[{\"value\":\"0\",\"label\":\"一组\"},{\"value\":\"1\",\"label\":\"两组\"},{\"value\":\"2\",\"label\":\"三组\"},{\"value\":\"3\",\"label\":\"五组\"}]', '\"1\"', '', '2', '1660208033257', 'a4bdaff4-81be-4a9a-b0e9-ac8ea42dc515');
