INSERT INTO `t_theory_question` VALUES ('f32853e7-730a-4837-ae9f-8583b5234db3', 3, '手键专向通报程序，情况复杂时，可以酌情重复两遍或者发短码重复。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"2\"', '', '2', '1660029608579', '9a2da855-2cab-4fb7-995d-fc87a9d9aa32');
