INSERT INTO `t_theory_question` VALUES ('f4e07400-3dab-4007-93b8-a9bbc4043c60', 1, 'H/TJS-402型短波收信机遥控开关；当开关位于“（）”位置时，收信机处于被遥控状态，此时键盘、频率调谐旋钮不起作用。当开关位于“关”位置时，则收信机处于本地状态，收信机由键盘或调谐旋钮送入工作频率等数据。', '[{\"value\":\"0\",\"label\":\"关闭\"},{\"value\":\"1\",\"label\":\"遥控\"},{\"value\":\"2\",\"label\":\"开启\"},{\"value\":\"3\",\"label\":\"开\"}]', '\"1\"', '', '2', '1660269354972', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
