INSERT INTO `t_theory_question` VALUES ('ff8fffe8-b23a-44a9-a27f-8ffac611e09d', 1, '在有（）电报或者信号，而又长时间联络无效时，可以进行转发或者盲发，但应当继续设法沟通联络索取收据。', '[{\"value\":\"0\",\"label\":\"加急\"},{\"value\":\"1\",\"label\":\"气象\"},{\"value\":\"2\",\"label\":\"特急\"},{\"value\":\"3\",\"label\":\"航海\"}]', '\"2\"', '', '2', '1644997102158', '476e9942-ae39-4da9-9f8a-9ce41489edfe');
INSERT INTO `t_theory_question` VALUES ('ffa3e2fa-a122-404a-8af1-ddb9e0d10272', 3, '话音通信是指利用通信信道传递语音的通信，具有实时间接沟通信息等特点。', '[{\"id\":\"1\",\"name\":\"对\"},{\"id\":\"2\",\"name\":\"错\"}]', '\"2\"', '', '2', '1660269357109', '1da60fbc-11bb-4ef5-a122-5b704c842df7');
