-- Table structure for simulation_router_room
-- ----------------------------
DROP TABLE IF EXISTS `simulation_router_room`;
CREATE TABLE `simulation_router_room`  (
  `id` int(0) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '房间名称',
  `is_cable` int(0) NULL DEFAULT NULL COMMENT '是否是固定报 0 随机报 1 固定报',
  `create_user_Id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `stats` int(0) NULL DEFAULT NULL COMMENT '0 未开始 1进行中 2结束',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `room_type` int(0) NULL DEFAULT NULL COMMENT '0=线路通报 1=快报\\干扰报 2=通报教学',
  `total_time` int(0) NULL DEFAULT NULL,
  `play_status` int(0) NULL DEFAULT NULL COMMENT '0 暂停 1继续',
  `setting` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `start_time` datetime(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1181 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '仿真训练 线路通报 房间类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for simulation_router_room_content
-- ----------------------------
DROP TABLE IF EXISTS `simulation_router_room_content`;
CREATE TABLE `simulation_router_room_content`  (
  `id` int(0) NOT NULL AUTO_INCREMENT,
  `room_id` int(0) NULL DEFAULT NULL COMMENT '房间id',
  `content` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '报文内容',
  `main_signal` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '主信号（包括线路、播报速度）',
  `interference_signal` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '干扰信号',
  `bd_type` int(0) NULL DEFAULT NULL COMMENT '报底类型 1=平均保底 2=乱码报底',
  `bw_type` int(0) NULL DEFAULT NULL COMMENT '报文类型 1=数字短码 2=数字长码 3=字码 4=混合报',
  `bw_count` int(0) NULL DEFAULT NULL COMMENT '报文组数',
  `is_random` int(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1174 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '仿真训练 线路通报 房间报底类' ROW_FORMAT = Dynamic;

