DROP TABLE IF EXISTS `t_entering_exercise`;
CREATE TABLE `t_entering_exercise`  (
  `id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '训练名称',
  `type` int(0) NULL DEFAULT NULL COMMENT '类型 0 异音同字 1同音异字 2连音词组 3军语词组 4文章练习 5口诀练习 6字根练习 7拆字练习 8词组练习 9 五笔连音词组',
  `create_user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人Id',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '结束时间',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `accuracy` double(11, 2) NULL DEFAULT NULL COMMENT '正确率',
  `speed` int(0) NULL DEFAULT NULL COMMENT '速度',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `duration` int(0) NULL DEFAULT NULL COMMENT '训练时长',
  `status` int(0) NULL DEFAULT NULL COMMENT '状态：0 未开始 1进行中 2结束 3暂停',
  `error_num` int(0) NULL DEFAULT NULL COMMENT '错误个数',
  `correct_num` int(0) NULL DEFAULT NULL COMMENT '正确个数',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '输入练习表' ROW_FORMAT = Dynamic;

