-- ----------------------------
-- Table structure for t_telegram_train
-- ----------------------------
DROP TABLE IF EXISTS `t_telegram_train`;
CREATE TABLE `t_telegram_train`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '训练标题',
  `start_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开始时间',
  `pause_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '暂停时间',
  `end_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结束时间',
  `sustain_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '持续时长，秒',
  `type` int(0) NULL DEFAULT NULL COMMENT '0.字码报，1.数码报，2.混合报, 11.点报，12.划报，13.点划报，14.点划连接报 21基础训练',
  `status` int(0) NULL DEFAULT NULL COMMENT '0未开始，1，进行中，2未完成已暂停，3已完成',
  `total_knock_number` int(0) NULL DEFAULT NULL COMMENT '总敲击次数',
  `total_number` int(0) NULL DEFAULT NULL COMMENT '报文总数',
  `error_number` int(0) NULL DEFAULT NULL COMMENT '错误数',
  `accuracy` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '正确率',
  `speed` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '速率',
  `rate_dot_min_ms` int(0) NULL DEFAULT NULL COMMENT '点的最小持续时间',
  `rate_dot_max_ms` int(0) NULL DEFAULT NULL COMMENT '点的最大持续时间',
  `rate_line_min_ms` int(0) NULL DEFAULT NULL COMMENT '线的最小持续时间',
  `rate_line_max_ms` int(0) NULL DEFAULT NULL COMMENT '线的最大持续时间',
  `rate_interval_min_ms` int(0) NULL DEFAULT NULL COMMENT '码的最小间隔时间',
  `rate_interval_max_ms` int(0) NULL DEFAULT NULL COMMENT '码的最大间隔时间',
  `big_interval_min_ms` int(0) NULL DEFAULT NULL COMMENT '组的最小间隔时间',
  `big_interval_max_ms` int(0) NULL DEFAULT NULL COMMENT '组的最大间隔时间',
  `create_user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `create_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `now_floor_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前报底ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

