-- ----------------------------
-- Table structure for t_ticker_tape_train
-- ----------------------------
DROP TABLE IF EXISTS `t_ticker_tape_train`;
CREATE TABLE `t_ticker_tape_train`  (
  `id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `rate` int(0) NULL DEFAULT NULL COMMENT '速率',
  `type` int(0) NULL DEFAULT NULL COMMENT '\'0\': \'字码报\',\'1\': \'数码报\',\'2\': \'混合报\', 21 基础练习 22科室训练',
  `code_message_body` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '报文内容',
  `code_short` int(0) NULL DEFAULT NULL COMMENT '0：短码 1:长码',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '创建时间',
  `start_time` datetime(6) NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime(6) NULL DEFAULT NULL COMMENT '结束时间',
  `valid_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有效时长',
  `status` int(0) NULL DEFAULT NULL COMMENT '0:未开始 1:进行中 2：暂停 3：结束',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '名称',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `mark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '听到的报文位置',
  `accuracy` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `big_interval_max_ms` int(0) NULL DEFAULT NULL,
  `big_interval_min_ms` int(0) NULL DEFAULT NULL,
  `create_user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `error_number` int(0) NULL DEFAULT NULL,
  `now_floor_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `pause_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `rate_dot_max_ms` int(0) NULL DEFAULT NULL,
  `rate_dot_min_ms` int(0) NULL DEFAULT NULL,
  `rate_interval_max_ms` int(0) NULL DEFAULT NULL,
  `rate_interval_min_ms` int(0) NULL DEFAULT NULL,
  `rate_line_max_ms` int(0) NULL DEFAULT NULL,
  `rate_line_min_ms` int(0) NULL DEFAULT NULL,
  `speed` int(0) NULL DEFAULT NULL,
  `sustain_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `total_knock_number` int(0) NULL DEFAULT NULL,
  `total_number` int(0) NULL DEFAULT NULL,
  `schedule` int(0) NULL DEFAULT 0 COMMENT '进度',
  `is_low_rate` int(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '收报管理-训练表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for t_ticker_tape_train_setting
-- ----------------------------
DROP TABLE IF EXISTS `t_ticker_tape_train_setting`;
CREATE TABLE `t_ticker_tape_train_setting`  (
  `id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '类型',
  `rate` int(0) NULL DEFAULT NULL COMMENT '速率',
  `text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文案',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '创建时间',
  `key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `dot` int(0) NULL DEFAULT NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_ticker_tape_train_setting
-- ----------------------------

-- ----------------------------
-- Table structure for t_ticker_tape_train_stage_setting
-- ----------------------------
DROP TABLE IF EXISTS `t_ticker_tape_train_stage_setting`;
CREATE TABLE `t_ticker_tape_train_stage_setting`  (
  `id` int(0) NOT NULL AUTO_INCREMENT,
  `stage_array` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_ticker_tape_train_stage_setting
-- ----------------------------

-- ----------------------------
-- Table structure for t_ticker_tape_train_statistical
-- ----------------------------
DROP TABLE IF EXISTS `t_ticker_tape_train_statistical`;
CREATE TABLE `t_ticker_tape_train_statistical`  (
  `id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `type` int(0) NULL DEFAULT NULL COMMENT '0 基础练习 1科室练习 2单词练习',
  `total_count` int(0) NULL DEFAULT NULL COMMENT '训练次数',
  `total_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总时长',
  `avg_speed` decimal(10, 2) NULL DEFAULT NULL COMMENT '平均速率',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '电传拍发统计表' ROW_FORMAT = Dynamic;

